_narrator_task = None  # type: asyncio.Task | None


def _narrator_cadence_for_phase(phase: int) -> float:
    # P1+P2 stream rich real data — tighter cadence catches sub-step changes.
    # P0/3/4/5 transition in chunky deterministic steps — 20s is plenty.
    return 6.0 if phase in (1, 2) else 20.0


# Chat-thread chrome that leaks via DOM scrape into events. Strip from
# narrator inputs ONLY (scrape outputs untouched — chip/step count still
# read those raw). Patterns mirror the FE filter at
# PhaseDropdown.tsx:2034-2041 plus 'brief.md' and the partial form
# without trailing colon. Compiled once at module load.
_NARR_NOISE_PREFIX_RE = re.compile(
    # Optional leading verb-prefix (e.g. "Building: ", "Searching: ") allows
    # the JS-prepended composites at research.py:7102 to be cleaned —
    # "Building: Claude responded: I'll start by..." → "I'll start by..."
    r"^\s*(?:\w+:\s*)?(?:you|chatgpt|gemini|claude|notebooklm|gpt)\s+(?:said|responded)\b\s*[:.]?\s*",
    re.IGNORECASE,
)
_NARR_NOISE_LINE_RE = re.compile(
    r"^\s*(?:"
    r"(?:you|chatgpt|gemini|claude|notebooklm|gpt)\s+(?:said|responded)\b"
    r"|brief\.md"
    r"|skip to content"
    r"|new chat"
    r")\s*[:.]?\s*$",
    re.IGNORECASE,
)


def _scrub_for_narrator(s: str) -> str:
    """Strip chat-thread chrome from a single narrator-input string.
    Returns "" when the input is entirely chrome (caller should drop the
    field). Used only for narrator inputs — does NOT touch scrape outputs
    that drive chip/step counts."""
    if not isinstance(s, str) or not s:
        return ""
    s = s.strip()
    if not s:
        return ""
    if _NARR_NOISE_LINE_RE.match(s):
        return ""
    # Strip leading "X said:" / "X responded:" prefix (handles both
    # bare-prefix lines and verbose "Building: Claude responded: ..."
    # composites — sub() runs once at start; the JS prepends "Building: "
    # so the noise prefix still appears at start in the worst case).
    s = _NARR_NOISE_PREFIX_RE.sub("", s, count=1).strip()
    return s


# Trailing-stopword set for narrator output sanity-check. A narration
# ending with one of these as its last word is mid-sentence (e.g.
# "Reading two sources from") — emit-time fragments worth rejecting so
# the FE doesn't render a half-thought as the live agent line.
# Refusal-style substrings — when present, the model is replying as a
# chat assistant ("I don't have enough info, could you provide…") instead
# of narrating. These leaked into the FE pre-2026-05-07 (screenshots
# Narration 1/2). The SKIP escape hatch in the prompt is the primary
# defense; this list catches near-misses where the model paraphrases
# the refusal without using SKIP.
_NARR_REFUSAL_SUBSTRINGS = (
    "i don't have", "i do not have", "i cannot", "i can't",
    "i am unable", "i'm unable", "i need", "i'd need",
    "could you provide", "could you share", "please provide",
    "lacks sufficient", "structured fields", "event payload",
    "to construct a specific", "to write a precise", "to write a tight",
    "without more", "more recent event", "more concrete", "more specific",
    "the events show only", "the event log shows", "the entry shows only",
    "the log indicates", "based on the data",
)

# WH-word leading tokens. A narration that starts with one of these is
# question-shaped ("Could you provide…", "Is there…"), not declarative.
_NARR_WH_LEADING = frozenset({
    "who", "what", "why", "how", "where", "when",
    "could", "can", "would", "will", "do", "does", "did",
    "is", "are", "should", "may", "might",
})

# Hosts that should not be cited as "sources" — they ARE the agent UI
# itself or its CDN. Filtered before passing hostnames into the narrator
# prompt (otherwise narration says "scraping chatgpt.com" which is dumb).
_HOST_DENYLIST = frozenset({
    "chatgpt.com", "openai.com", "chat.openai.com", "oaiusercontent.com",
    "claude.ai", "anthropic.com",
    "gemini.google.com", "bard.google.com",
    "notebooklm.google.com", "notebook.google.com",
})


def _narration_last_sentence(s: str, limit: int | None = None) -> str:
    """The longest prefix of `s` that ENDS a sentence, or "" if it has none.

    ⭐⭐ 2026-08-17 — the owner's phase card showed five narration lines cut
    mid-phrase ("ChatGPT is launching its deep", "Data thinness check: We"). Two
    mechanisms produced them and this helper answers both:

      * the narrator model returning a fragment, which the quality gate below
        could not see because its length rule ANDed two conditions;
      * a `[:140]` slice applied to the vision narration BEFORE that gate, so the
        gate was inspecting damage the pipeline had just done rather than the
        model's own output. A character count cannot know where a word ends.

    A terminal mark is a '.' or '!' followed by end-of-string or whitespace — so
    a hostname the narrator is told to cite ("docs.nvidia.com") is not mistaken
    for the end of a sentence. '?' is not terminal here: the gate rejects
    questions outright, and accepting one would smuggle it back in.

    `limit` caps the returned length in characters, and it is the RIGHT way to
    shorten narration: the answer is always a whole sentence or nothing, never a
    word cut in half.
    """
    s = (s or "").strip()
    if not s:
        return ""
    best = -1
    for i, ch in enumerate(s):
        if ch not in ".!":
            continue
        if i + 1 < len(s) and not s[i + 1].isspace():
            continue
        if limit is not None and i + 1 > limit:
            break
        best = i
    return s[:best + 1].strip() if best >= 0 else ""


def _is_acceptable_narration(s: str) -> bool:
    """Reject narration outputs that don't read as a single declarative
    sentence. Signals:
    (1) under 5 words OR under 22 chars (catches 'Twenty', 'Engaged in')
    (2) NO COMPLETE SENTENCE IN IT — the 2026-08-17 report. A narration is
        one declarative sentence and a sentence ends; a line that never
        does was cut, wherever it was cut.
    (3) total length > 160 chars (prompt budget is 110/140 — overflow
        signals the model is composing prose, not one sentence)
    (4) `?` in the last 30 chars — declarative narrations don't end in
        a question
    (5) leading WH-word (Could/Can/Would/Is/Are/...) — question shape
    (6) refusal substrings ('I don't have', 'could you provide', ...) —
        the model is replying as a chat assistant, not narrating
    (7) leading-tokenization artifact ('"d unambiguous...')

    On reject the caller should fall through to Tier-3 realistic
    fallback (or Tier-4 deterministic template) rather than just
    skipping the tick — a sustained refusal mode would otherwise leave
    the FE narration frozen on stale text for minutes."""
    if not s:
        return False
    words = s.split()
    # ⭐⭐ 2026-08-17 — WAS `and`, AND THAT IS THE HOLE THE OWNER PHOTOGRAPHED.
    # Two guards joined by `and` mean neither can veto on its own, so a fragment
    # that is short in WORDS but long enough in CHARACTERS sailed through:
    # "ChatGPT is selecting its" is 4 words and 24 characters, and it was shown.
    # Same defect shape as the two redundant guards this file removed in the
    # 2026-08-06 wave — a condition that cannot change an answer alone.
    if len(words) < 5 or len(s) < 22:
        return False
    # ⭐ A narration is ONE DECLARATIVE SENTENCE — that is what the prompt asks
    # for, and a sentence ends. Without this, the only defence against a cut line
    # is guessing from its last word, and the last word of "ChatGPT is launching
    # its deep" is an ordinary adjective that no list could hold.
    if not _narration_last_sentence(s):
        return False
    if len(s) > 160:
        return False
    if "?" in s[-30:]:
        return False
    first = words[0].lower().rstrip(",.:;!?") if words else ""
    if first in _NARR_WH_LEADING:
        return False
    s_lower = s.lower()
    for needle in _NARR_REFUSAL_SUBSTRINGS:
        if needle in s_lower:
            return False
    # ⛔ 2026-08-17 — THE TRAILING-STOPWORD RULE IS GONE, and this is where it
    # was. It guessed a mid-sentence cut from the last word against a list of
    # seventeen prepositions, and the owner's screenshot is what a list of an
    # open class lets through: "ChatGPT is launching its deep" ends on an
    # ordinary adjective, and no list can hold those. Widening it to a closed
    # word class was tried and then removed too — with the complete-sentence rule
    # above, it can only ever fire on a line that rule has already refused, and a
    # condition that cannot change an answer is one this file has repeatedly
    # found being read as load-bearing and tested by nobody. Worse, it was
    # actively WRONG on a properly ended sentence: the deterministic phase
    # template reads "…verifying every agent is logged in." and 'in' was on the
    # list, so the floor the whole fallback chain rests on failed its own gate.
    # One guard, and a test that fails if it goes.
    # Leading-tokenization artifact — Haiku occasionally returns a
    # response that begins with a fragment like "d unambiguous..." or
    # "'s research..." when the system prompt contains quoted strings.
    head = s.lstrip()[:2]
    if head in ('"d', "'d", '"s', "'s", '"t', "'t", '"r', "'r"):
        return False
    return True


def _is_skip_token(text: str) -> bool:
    """Detect the SKIP escape-hatch token Haiku/Flash emits when data is
    too thin to narrate honestly. Normalizes wrappers the model may add
    (`SKIP.`, `"SKIP"`, `Output: SKIP`)."""
    if not text:
        return False
    t = text.strip().strip('"').strip("'").strip("`").strip().lower()
    if t in {"skip", "skip.", "skip!", "skip,"}:
        return True
    if t.startswith(("output: skip", "output:skip", "skip\n", "skip ")):
        return True
    return False


def _phase_short_label(phase: int) -> str:
    """Compact human label per phase, for the deterministic phase-narration
    template that ships when Tier-2 (LLM) refuses or fails the gate. Static
    text — the FE shows elapsed time below the dropdown separately, so no
    counter suffix is needed here. Dedupe at emit site means this lands
    once per phase if Tier-2 stays in refusal mode."""
    return {
        0: "the warmup phase, verifying every agent is logged in",
        1: "brief generation, drafting a structured research brief",
        2: "parallel deep research across ChatGPT, Gemini, and Claude",
        3: "NotebookLM upload and audio overview generation",
    }.get(phase, "running through the active phase")


_NARRATION_STOPWORDS = frozenset({
    "is", "in", "of", "the", "a", "an", "and", "or", "with", "without",
    "after", "before", "over", "under", "across", "into", "onto", "from",
    "to", "as", "at", "for", "by", "on", "off", "no", "not", "yet", "so",
    "now", "still", "while", "during", "having", "been", "be", "being",
    "this", "that", "these", "those", "it", "its", "then", "than",
})


# Words that appear in almost any research topic and therefore anchor nothing.
# A topic whose only content words are these is not guardable — see
# `topic_anchors`, which abstains rather than guessing.
_TOPIC_GENERIC_WORDS = frozenset({
    "research", "report", "reports", "analysis", "analyses", "overview",
    "evidence", "guide", "comparison", "compare", "comparing", "review",
    "reviews", "study", "studies", "summary", "detail", "details", "about",
    "using", "used", "usage", "various", "different", "best", "practice",
    "practices", "based", "also", "how", "what", "which", "when", "where",
    "why", "them", "they", "their", "there", "here", "more", "most", "some",
    "any", "all", "both", "each", "other", "others", "such", "very", "much",
    "many", "same", "well", "just", "only", "even", "make", "makes", "made",
    "used", "useful", "case", "cases", "example", "examples", "topic",
    "information", "data", "current", "recent", "latest", "general",
    "security", "technology", "technologies", "system", "systems", "tool",
    "tools", "model", "models", "market", "markets", "industry", "state",
    "future", "impact", "impacts", "risk", "risks", "trend", "trends",
    "into", "with", "from", "that", "this", "these", "those", "have", "has",
    "been", "were", "will", "would", "could", "should", "than", "then",
    "over", "under", "between", "across", "within", "against", "while",
    # Connectors. A topic joining two subjects ("A plus B", "A versus B") must
    # not turn the joining word into an anchor: the guard fires only when ZERO
    # anchors are present, so a word that appears in arbitrary prose silently
    # makes it unfireable. 2026-08-05 — caught by a test fixture using "plus".
    "plus", "versus", "along", "together", "alongside", "either", "neither",
    "whether", "rather", "instead", "besides", "regarding", "concerning",
})

# A guard needs at least this many distinctive words in the topic before it may
# judge anything, and the document must be at least this long. Both thresholds
# exist to make the guard ABSTAIN rather than misfire: a short partial and a
# vocabulary-free topic are the two shapes it cannot reason about.
_TOPIC_GUARD_MIN_ANCHORS = 3
_TOPIC_GUARD_MIN_CHARS = 20_000


def topic_anchors(topic: str) -> "list[str]":
    """The distinctive words of a research topic — the ones a report about it
    could not plausibly avoid.

    2026-08-05. Built from the same tokenizer the narrator dedupe uses
    (`[a-zA-Z]{4,}` minus the stopwords), then filtered down to words that are
    not generic research vocabulary. For the incident's topic — "NemoClaw vs
    NemoHermes vs Nemotron and also about OpenShell and how all of these can be
    used for security" — that leaves exactly nemoclaw, nemohermes, nemotron,
    openshell. The 121KB document that shipped contained ZERO of them and 46
    instances of "golden retriever".

    Returns [] when the topic has no distinctive vocabulary at all. A caller
    seeing fewer than `_TOPIC_GUARD_MIN_ANCHORS` must ABSTAIN: "best practices
    for team retrospectives" is a perfectly good topic and is simply not
    guardable this way. Refusing to judge is the correct answer — a guard that
    fails a healthy run is worse than the hole it closes.
    """
    seen = []
    for m in re.finditer(r"[a-zA-Z]{4,}", topic or ""):
        w = m.group(0).lower()
        if w in _NARRATION_STOPWORDS or w in _TOPIC_GENERIC_WORDS:
            continue
        if w not in seen:
            seen.append(w)
    return seen


def text_is_off_topic(text: str, topic: str) -> bool:
    """Does `text` fail to mention ANY distinctive word from `topic`?

    True only when we are confident: enough anchors to judge by, enough text to
    be a real document, and not one single anchor present anywhere in it.
    Matching is case-insensitive SUBSTRING, so "Nemotron-4" and "NemoClaw's"
    both count — a report that discusses the subject cannot score zero.

    Everything uncertain returns False. That asymmetry is the point: this gate
    can lose a run's leg when it fires, so it must fire only on the shape that
    has no innocent explanation.
    """
    anchors = topic_anchors(topic)
    if len(anchors) < _TOPIC_GUARD_MIN_ANCHORS:
        return False
    if len(text or "") < _TOPIC_GUARD_MIN_CHARS:
        return False
    low = text.lower()
    return not any(a in low for a in anchors)


def reject_off_topic_text(text: str, queue_dir, label: str, agent_key: str,
                          *, op: str) -> str:
    """`text` if it is about the run's topic, `""` if it demonstrably is not.

    ⭐⭐ 2026-08-05 — THE GUARD MOVED TO THE SINK, and this function is why. The
    check used to live at ONE call site, inside `extract_and_record_agent`, which
    is the path a HEALTHY agent takes. The 2026-08-05 e2e shipped 121KB about
    golden retrievers anyway, because two other paths reach the same files and
    neither went through it:

      1. The user-Skip branch calls `extract_fns[name](...)` directly and drops the
         raw string into `results[name]["text"]`. Log evidence: "Skipped by user —
         extracting partial output" at 12:00:54, "Extracted via T1 CUA download
         (Export to Markdown): 120368 chars" at 12:01:04, and NO "Saved … chars to
         documents/chatgpt.md" line anywhere — because the healthy writer never
         ran.
      2. The Phase-2 finalize re-save loop writes EVERY `results[name]["text"]` to
         `documents/<agent>.md` and Firestore, and the consolidated builder merges
         them. On disk afterwards: chatgpt.md=121081b, consolidated.md=257040b,
         both handed to NotebookLM as "3 files ready".

    Only the title guard objected, at 12:01:08, after the upload had been queued.
    A guard on the producer is a guard on the producers you remembered; a guard on
    the sink covers the ones you did not. Every path that fills a `text` destined
    for disk calls this.

    Same asymmetry as `text_is_off_topic`, which does the deciding: everything
    uncertain passes. `queue_dir` of None, an unreadable topic, fewer than
    `_TOPIC_GUARD_MIN_ANCHORS` distinctive words, or a document under
    `_TOPIC_GUARD_MIN_CHARS` all mean ABSTAIN — this can lose a leg when it fires,
    so it fires only on the shape with no innocent explanation.
    """
    if not text or not queue_dir:
        return text
    topic = _run_topic_for_guard(queue_dir)
    # ⚠ `not topic` is a FREE BELT, not a covered condition, and it is recorded as such
    # because a survivor list is only useful when every entry is a real hole. Mutation
    # testing flagged its removal as surviving, and it is subsumed rather than untested:
    # `topic_anchors("")` is `[]`, `len([]) < _TOPIC_GUARD_MIN_ANCHORS`, so
    # `text_is_off_topic(text, "")` already returns False and the guard already abstains.
    # Kept for the reader — "no topic means abstain" is the intent and it should be
    # visible at the decision, not inferred two functions away.
    if not topic or not text_is_off_topic(text, topic):
        return text
    anchors = topic_anchors(topic)
    log(f"[{label}] OFF-TOPIC text REJECTED at {op}: {len(text)} chars mention "
        f"none of the topic's distinctive terms ({', '.join(anchors[:6])}) — "
        f"this is not this run's research. Not saving it.", "ERROR")
    try:
        emit_event("wrong_artifact_rejected", phase=2, agent=agent_key,
                   op=op, length=len(text), tier="topic_guard")
    except Exception:
        pass
    return ""


def apply_off_topic_sweep(results: dict, queue_dir) -> "list[str]":
    """Blank every `results[name]["text"]` that is demonstrably not this run's
    research. Mutates `results` in place; returns the rejected names.

    A function rather than a loop inlined at the call site, because the call site
    is deep in `run_phase2` and this decision is the one that stands between a
    wrong-topic harvest and the run's deliverable files. It has to be executable
    on its own to be worth anything.

    Four things happen to a rejected entry, and all four are load-bearing:

      * `text` is cleared, which is what keeps it out of `documents/<agent>.md`,
        the Firestore documents subcollection, `consolidated.md` and `save_meta`.
        Every one of those reads this field.
      * `verified` is cleared, so the agent cannot be bucketed as `linked` and
        offered to the user as "Read <agent> report" pointing at a file we refused
        to write.
      * a terminal `done` becomes `failed`. Leaving it `done` would turn the tile
        green with nothing behind it AND make the phase_complete invariant check
        report a breach about a document that was deliberately not written.
      * `off_topic_rejected` is set. ⚠ This list used to claim clearing `text`
        also covered the P2→P3 NotebookLM handoff. It does NOT — that builder reads
        the conversation `url` on a line of its own, so the 11:08 run published the
        rejected foreign thread as the run's ChatGPT source with its text already
        blanked. The url itself is left alone on purpose: it is documented for
        resume reconnect.
    """
    # ⭐ SAY WHEN THE GUARD IS INERT. Adversarial review pointed out that on a run
    # whose meta.json/checkpoint.json is missing, `_run_topic_for_guard` falls back to
    # the run DIRECTORY'S name — and a short or generic topic yields fewer than
    # `_TOPIC_GUARD_MIN_ANCHORS` distinctive words, so the guard abstains on everything.
    # That direction is deliberate (fail open beats failing a healthy run), but an
    # operator reading the log must be able to tell "nothing was off-topic" from
    # "nothing could be judged". One line per sweep, not per agent.
    _t = _run_topic_for_guard(queue_dir)
    _a = topic_anchors(_t)
    if len(_a) < _TOPIC_GUARD_MIN_ANCHORS:
        log(f"[Phase 2] off-topic sweep is INERT this run: topic {_t[:60]!r} yields "
            f"{len(_a)} distinctive word(s) ({', '.join(_a) or 'none'}), below the "
            f"{_TOPIC_GUARD_MIN_ANCHORS} needed to judge anything", "WARN")

    rejected = []
    for name, r in (results or {}).items():
        if not isinstance(r, dict):
            continue
        text = r.get("text") or ""
        if not text:
            continue
        if reject_off_topic_text(text, queue_dir, name,
                                 name.lower().replace(" ", ""),
                                 op="phase2_finalize_topic_guard"):
            continue
        r["text"] = ""
        r["verified"] = False
        # ⭐ 2026-08-05 (review, f10) — a FOURTH thing, and the docstring above was
        # wrong to say clearing `text` covered the P2→P3 handoff. It does not: the
        # handoff reads the conversation `url` on its own line and adds it to the
        # NotebookLM link set whether or not any text survived. The 11:08 run logged
        # `Links saved: {'ChatGPT': '…/c/6a72ce1e…'}` — the rejected foreign thread,
        # published as the run's ChatGPT source, after the sweep had already blanked
        # its text. So mark the entry instead of clearing the url: the url is
        # documented for RESUME RECONNECT (see the results contract) and clearing it
        # would break reattaching to a live conversation.
        r["off_topic_rejected"] = True
        if (r.get("status") or "").lower() in ("done", "complete", "completed",
                                              "done_partial"):
            r["status"] = "failed"
        rejected.append(name)
    return rejected


def _too_similar_to_recent(new_text: str, prev_text: str, threshold: float = 0.65) -> bool:
    """Reject a fresh narration if it's a paraphrase of the previous one.
    The exact-string dedupe at the emit site catches "ChatGPT is X" twice
    in a row but misses "ChatGPT accumulated 198 chars over 5 minutes" vs
    "ChatGPT has 198 tokens drafted after 5 minutes" — same idea, different
    wording. Word-set Jaccard over content words (>=4 chars, no stopwords)
    catches the user-reported "all five narrations say the same thing"
    pattern during ChatGPT's extended-thinking window.
    """
    if not new_text or not prev_text:
        return False
    import re as _re
    def _content(s: str) -> set[str]:
        return {
            w for w in (m.group(0).lower() for m in _re.finditer(r"[a-zA-Z]{4,}", s))
            if w not in _NARRATION_STOPWORDS
        }
    new_words = _content(new_text)
    prev_words = _content(prev_text)
    if len(new_words) < 4 or len(prev_words) < 4:
        return False
    union = new_words | prev_words
    if not union:
        return False
    return len(new_words & prev_words) / len(union) >= threshold


def _extract_top_hosts(events: list, limit: int = 2) -> list:
    """Pull deduped non-UI hostnames from agent_progress.source_urls and
    link_extracted events in the recent ring-buffer window. Used to feed
    the narrator prompt's `hosts=` field so narration can cite the actual
    sources the agents are reading instead of generic 'reading sources'.
    """
    try:
        from urllib.parse import urlparse as _urlparse
    except Exception:
        return []
    seen = []
    seen_set = set()
    for e in events:
        d = e.get("data", {}) or {}
        urls = []
        v = d.get("source_urls") or d.get("sourceUrls")
        if isinstance(v, list):
            urls.extend(v)
        if e.get("type") == "link_extracted":
            single = d.get("url")
            if single:
                urls.append(single)
        for u in urls:
            if not isinstance(u, str):
                continue
            try:
                host = (_urlparse(u).hostname or "").lower()
                if host.startswith("www."):
                    host = host[4:]
            except Exception:
                continue
            if not host or host in _HOST_DENYLIST or host in seen_set:
                continue
            seen.append(host)
            seen_set.add(host)
            if len(seen) >= limit:
                return seen
    return seen


# Tier-4 deterministic template variants — the absolute last-ditch
# fallback when both Tier-2 (Haiku/Flash on real events) AND Tier-3
# (LLM with hardcoded timeline) refuse or fail. Three phrasings per
# (akey, phase) so consecutive emits don't collide on the dedupe
# equality guard at line ~7131/~7207 (silent-emit trap).
AGENT_TIER4_VARIANTS = {
    ("chatgpt", 1): [
        "ChatGPT is reasoning through the brief with its latest thinking model.",
        "ChatGPT is shaping the brief outline with structured sections.",
        "ChatGPT is consolidating the brief output and validating sources.",
    ],
    ("chatgpt", 2): [
        "ChatGPT is sweeping the web for fresh sources on the topic.",
        "ChatGPT is reading retrieved articles and pulling citations.",
        "ChatGPT is synthesizing findings into the report sections.",
    ],
    ("claude", 2): [
        "Claude is loading the brief and planning the research scope.",
        "Claude is searching and reading sources into the artifact.",
        "Claude is structuring the artifact with citations and sections.",
    ],
    ("gemini", 2): [
        "Gemini is launching Deep Research from the Tools menu.",
        "Gemini is browsing fresh sources into the activity panel.",
        "Gemini is weaving findings into a structured report.",
    ],
}

_tier4_counter = {}  # type: dict[str, int]


def _tier4_template(akey: str, ph: int) -> str:
    """Round-robin pick from AGENT_TIER4_VARIANTS so consecutive Tier-4
    emits produce different strings (defeats the equality dedupe at the
    emit sites). Counter keyed by (akey, ph) so a future entry like
    ("chatgpt", 0) doesn't cross-contaminate ("chatgpt", 2)'s rotation."""
    variants = AGENT_TIER4_VARIANTS.get((akey, ph))
    if not variants:
        return f"{akey.upper()} is processing the request."
    key = (akey, ph)
    counter = _tier4_counter.get(key, 0)
    _tier4_counter[key] = counter + 1
    return variants[counter % len(variants)]


def _compact_event_for_narration(e: dict) -> str:
    """Flatten an event into one line for the narrator prompt. Skips
    high-cardinality fields and caps each value at 120 chars so a 20-event
    window stays well under the narrator input budget. Also strips
    chat-thread chrome ("You said:", "Claude responded:", "brief.md") so
    the narrator doesn't paraphrase noise back as narration."""
    t = e.get("type", "")
    ph = e.get("phase", "")
    ag = e.get("agent", "")
    d = e.get("data", {}) or {}
    parts = [f"{t} ph={ph}"]
    if ag:
        parts.append(f"agent={ag}")
    for k in ("status", "progress", "error", "message", "reason",
              "sources", "sections", "steps", "partialTextLen", "partialTextPreview",
              "elapsedSec", "searches", "sectionsDone", "sectionsTotal",
              "currentFocus", "websitesCount", "panelOpen", "artifactCount"):
        v = d.get(k)
        if v in (None, "", [], {}):
            continue
        if isinstance(v, (list, dict)):
            # Scrub each list element of chat-thread chrome before serializing.
            if k in ("sections", "steps") and isinstance(v, list):
                v = [c for c in (_scrub_for_narrator(x) for x in v
                                  if isinstance(x, str)) if c]
                if not v:
                    continue
                if k == "steps":
                    # The scraped activity-panel step titles = the literal
                    # "what's happening now". Feed the narrator the freshest
                    # few as a readable line so it grounds its sentence in the
                    # real activity instead of inventing from a hardcoded
                    # timeline (the user-reported "generic narration").
                    parts.append(f"steps={' · '.join(v[-3:])[:220]}")
                    continue
            s = json.dumps(v)[:120]
        elif k == "partialTextPreview":
            # Last 80 chars of the streaming preview — the most-recent
            # token cluster is what the narrator should reference, not
            # the stale opening of a long synthesis.
            s = _scrub_for_narrator(str(v)[-80:])
            if not s:
                continue
        else:
            s = str(v)[:120]
            if k in ("progress", "currentFocus", "message", "reason"):
                s = _scrub_for_narrator(s)
                if not s:
                    continue
        parts.append(f"{k}={s}")
    # Surface link_extracted events with a hostname + truncated label so
    # the narrator can name the actual source ("Skimming sec.gov on
    # Tesla 10-K") instead of just "Reading sources". Hostname keeps
    # the input compact; the full URL would blow the 120-char cap.
    if t == "link_extracted":
        url = d.get("url") or ""
        label = d.get("label") or d.get("title") or ""
        if url:
            try:
                from urllib.parse import urlparse as _urlparse
                host = (_urlparse(url).hostname or "").lower()
                if host.startswith("www."):
                    host = host[4:]
            except Exception:
                host = ""
            if host and host not in _HOST_DENYLIST:
                parts.append(f"host={host}")
        if label:
            parts.append(f"label={str(label)[:40]}")
    # Surface agent_progress.source_urls as `hosts=foo.com,bar.com` (top
    # 2, deduped, agent UI hosts filtered). This is the primary signal
    # for live browsing during P2 — link_extracted does NOT fire from
    # agent browsing (it's only emitted from share-link extraction in
    # P5), so without this the prompt's "weave hostnames" instruction
    # would be no-op for the in-progress P2 narration.
    if t == "agent_progress":
        urls = d.get("source_urls") or d.get("sourceUrls")
        if isinstance(urls, list) and urls:
            try:
                from urllib.parse import urlparse as _urlparse
            except Exception:
                _urlparse = None
            if _urlparse is not None:
                _hosts = []
                _hosts_seen = set()
                for u in urls:
                    if not isinstance(u, str):
                        continue
                    try:
                        h = (_urlparse(u).hostname or "").lower()
                        if h.startswith("www."):
                            h = h[4:]
                    except Exception:
                        continue
                    if not h or h in _HOST_DENYLIST or h in _hosts_seen:
                        continue
                    _hosts.append(h)
                    _hosts_seen.add(h)
                    if len(_hosts) >= 2:
                        break
                if _hosts:
                    parts.append(f"hosts={','.join(_hosts)}")
    return " | ".join(parts)


def _gemini_error_detail(resp, sent_config: "dict | None" = None) -> str:
    """The reason Google gave for refusing a call, as one line.

    `sent_config` is the generationConfig we posted. It is used only when Google
    returns INVALID_ARGUMENT with no fieldViolations — see below.

    The body is the ONLY place the cause lives. `API key not valid` and
    `Invalid JSON payload received. Unknown name "thinkingConfig"` are both HTTP
    400 on this endpoint, so a message built from the status alone cannot tell an
    expired key from a payload the API version stopped accepting — which is why
    1125 identical warnings in the live corpus never once said what was wrong.
    (⚠ A MISSING MODEL is 404/NOT_FOUND, not 400 — an earlier version of this
    docstring listed `models/<name> is not found` among the 400s and sent a
    reader hunting a phantom rename. The sibling fixture in
    test_narrator_gemini_diagnosis.py had the status right all along.)

    ⚠ AND SOMETIMES THE BODY SAYS NOTHING EITHER. The 2026-08-05 narrator failure
    returned `INVALID_ARGUMENT` with the boilerplate "Request contains an invalid
    argument." and NO `details`, so there were no fieldViolations to surface and
    no amount of better reporting here could have named the offending key. When
    Google declines to say which field it disliked, the only remaining lever is
    printing the field names WE sent — hence the config-key tail below, which
    would have put `thinkingConfig` in that prod log directly.

    Falls back to the raw body, then to a plain statement that there wasn't one,
    so this never returns an empty string that reads as "no error".
    """
    try:
        err = ((resp.json() or {}).get("error") or {})
    except Exception:
        err = {}
    message = str(err.get("message") or "").strip()
    reason = ""
    fields = []
    for detail in (err.get("details") or []):
        if not isinstance(detail, dict):
            continue
        if detail.get("reason") and not reason:
            reason = str(detail["reason"])
        # ⭐ The field is the whole answer for INVALID_ARGUMENT. Google's
        # top-level message for it is the useless "Request contains an invalid
        # argument."; the offending field name lives one level down in a
        # BadRequest detail, and reading only `reason` left the live corpus
        # saying nothing more than the status code did.
        for viol in (detail.get("fieldViolations") or []):
            if not isinstance(viol, dict):
                continue
            name = str(viol.get("field") or "").strip()
            desc = str(viol.get("description") or "").strip()
            if name or desc:
                fields.append(f"{name}: {desc}" if name and desc else (name or desc))
    if message:
        status = str(err.get("status") or "").strip()
        tag = "/".join(p for p in (status, reason) if p)
        head = f"{tag}: {message[:160]}" if tag else message[:160]
        if fields:
            return f"{head} [{'; '.join(fields)[:200]}]"
        # No fieldViolations. Name what WE sent — the only lever left when
        # Google refuses to say which key it disliked. Keys only, never values:
        # this line goes to the log and the payload carries user prompt text.
        if status == "INVALID_ARGUMENT" and sent_config:
            try:
                keys = ",".join(sorted(str(k) for k in sent_config))
            except TypeError:
                keys = ""
            if keys:
                return f"{head} [we sent generationConfig: {keys}]"
        return head
    body = " ".join(str(getattr(resp, "text", "") or "").split())
    return body[:160] or "(no error body)"


# ── The narrator's HTTP budget, split between its two vendors ────────────────
#
# ⚠ 2026-08-05 — this replaces a bare `timeout=5` on the Gemini POST and a bare
# `timeout=5.0` on the Anthropic fallback client. That 5 was sized for a request
# that DISABLED thinking, and `_gemini_gen_config` no longer sends the disable
# field because the endpoint rejects it — so the primary now reasons before it
# answers and its latency TAIL no longer fits. The 2026-08-05 e2e recorded 30
# ReadTimeouts at exactly `read timeout=5` across one run.
#
# ⭐ Those 30 lines are also the proof that the primary DOES answer now. The
# downgrade line is logged once per `err_holder` and re-armed only by
# `last_vendor == "gemini"` — i.e. only by a Gemini SUCCESS — so 30 lines from
# one loop invocation means ~29 successful Gemini calls between them. The HTTP
# 400s this replaces were every call, with none.
#
# ⛔ SPLIT, not simply raised. Raising both sides to 10s would make a fully
# failing tick a 20-second tick, and narration that lands 20s late has already
# been overtaken by the next one (the P1/P2 cadence is 6s). One budget covers
# BOTH attempts: the primary gets it minus the fallback's floor, and the fallback
# gets whatever is actually left — the full budget when the primary failed
# instantly (bad key, refused connection), the bare floor when it burned its
# whole share.
NARRATOR_HTTP_BUDGET_S = 14.0
NARRATOR_FALLBACK_FLOOR_S = 4.0
# After this many CONSECUTIVE transport failures, stop calling the primary for the
# rest of this narrator loop and go straight to the fallback. Two, not one: a
# single blip should not cost the whole phase its preferred vendor.
NARRATOR_PRIMARY_TRIP_AFTER = 2


def _narrator_primary_should_skip(err_holder) -> "bool":
    """Has the primary already been written off for this narrator loop?

    Extracted so a test can CALL it: the decision otherwise lives inline in a
    700-line request function nothing in the suite executes, which is how an
    inverted gate ships green.
    """
    return bool(err_holder) and bool(err_holder.get("gemini_tripped"))


def _narrator_note_primary_failure(err_holder, *, elapsed_s: float,
                                   exc_name: str) -> "tuple[bool, str]":
    """Record one primary TRANSPORT failure. Returns (tripped_now, detail).

    ⭐ 2026-08-06 — why this exists. On the 6 August run every narration attempt
    to the primary read-timed-out, and nothing remembered that, so each tick paid
    the full primary share of the shared budget again before handing over. The
    narrator cadence in phases 1 and 2 is SIX seconds, so this was not the four
    failures the log appears to show — the downgrade line is logged once per loop,
    which suppressed the true count. Four visible lines, and on the order of a
    hundred timeouts underneath them.

    Counting only transport failures is deliberate. A refusal or a 200-with-no-text
    returns promptly and costs nothing to retry; a read timeout costs the whole
    primary allowance. It is the WAITING this stops paying for, not the failing.

    The trip is per `err_holder`, which the narrator loop creates once per phase —
    so a phase that fails throughout stops retrying, and the next phase gets a
    clean attempt. That is a free half-open probe at every phase boundary, without
    a timer.
    """
    if err_holder is None:
        return False, ""
    n = int(err_holder.get("gemini_consecutive_fail") or 0) + 1
    err_holder["gemini_consecutive_fail"] = n
    detail = f"{exc_name} after {elapsed_s:.1f}s, consecutive={n}"
    if n >= NARRATOR_PRIMARY_TRIP_AFTER and not err_holder.get("gemini_tripped"):
        err_holder["gemini_tripped"] = True
        return True, detail
    return False, detail


def _narrator_note_primary_success(err_holder) -> None:
    """A primary answer clears the consecutive count.

    It does NOT un-trip: once written off, the primary stays off for the rest of
    this loop. Re-arming inside a loop would reintroduce the retry cost this
    exists to remove, and the phase boundary already provides the retry.
    """
    if err_holder is not None:
        err_holder["gemini_consecutive_fail"] = 0


def _narrator_http_budget_s() -> float:
    """The tick's total HTTP budget, read from the environment AT CALL TIME.

    ⚠ This used to be `float(os.environ.get("DG_NARRATOR_HTTP_BUDGET", "14.0"))`
    at module level, which made the override unreachable in the way it is
    actually supplied: `_load_env_file(args.env_file)` runs inside `main()`, so
    `.dg-supervisor.env` is applied long after this module's constants bind.
    Measured — env set before import: 99.0; set after import: still 14.0. An
    operator raising the budget on a slow link would have seen no effect at all.

    A bad value is ignored rather than fatal: narration is a nicety and a typo in
    an env file must not stop a run. `NARRATOR_HTTP_BUDGET_S` stays the default
    (and stays monkeypatchable) for exactly that fall-through.
    """
    raw = os.environ.get("DG_NARRATOR_HTTP_BUDGET")
    if raw:
        try:
            return float(raw)
        except (TypeError, ValueError):
            log(f"[narrator] DG_NARRATOR_HTTP_BUDGET={raw!r} is not a number — "
                f"using {NARRATOR_HTTP_BUDGET_S}s", "WARN")
    return NARRATOR_HTTP_BUDGET_S


def _narrator_http_timeouts(spent_s: float = 0.0) -> "tuple[float, float]":
    """(primary_timeout, fallback_timeout) for one narrator tick.

    `spent_s` is the wall-clock the primary attempt already consumed. Both
    returns are floored at `NARRATOR_FALLBACK_FLOOR_S` so a misconfigured or
    exhausted budget can never hand a vendor a zero/negative timeout — requests
    treats those as "fail immediately", which would silence narration entirely
    rather than degrade it. Pure function; the ceiling arithmetic is the whole
    contract, so it is tested directly.
    """
    budget = max(_narrator_http_budget_s(), 2.0 * NARRATOR_FALLBACK_FLOOR_S)
    primary = max(NARRATOR_FALLBACK_FLOOR_S, budget - NARRATOR_FALLBACK_FLOOR_S)
    fallback = max(NARRATOR_FALLBACK_FLOOR_S, budget - max(0.0, spent_s))
    return primary, fallback


def _gemini_gen_config(*, temperature: float, max_tokens: int, **extra) -> dict:
    """The ONE generationConfig every Gemini text call sends.

    ⭐ 2026-08-05 — WHY THIS EXISTS. Four builders each hand-rolled this dict and
    all four carried `"thinkingConfig": {"thinkingBudget": 0}`. On the live
    endpoint that field is what the narrator's HTTP 400 INVALID_ARGUMENT was
    about, and the proof is a differential inside a single process: the
    vision-URL extractor sends the SAME model id (both constants default to the
    same literal), to the SAME v1beta path, with the same `role`/`parts`, the
    same systemInstruction shape, an int maxOutputTokens and a float
    temperature — and no thinkingConfig — and gets 200 in the same run where the
    narrator gets 400 on every attempt.

    Google declines to name the field: the response carries the useless
    top-level "Request contains an invalid argument." and NO fieldViolations, so
    no amount of better error reporting on our side could have named it. The only
    lever was the differential.

    ⚠ The budget is now OPT-IN. Omission is the only variant with a live 200
    behind it, so that is the default; `DG_GEMINI_THINKING_BUDGET` re-enables it
    for whoever wants to test a future model that accepts it. Thinking being ON
    is why the narrator's own token ceiling had to rise — the original comment
    ("thinking eats the token budget leaving 2-3-word stubs") was describing a
    real effect, and the answer is a bigger ceiling, not a rejected request.

    ⓘ 2026-08-13 — the body moved to `models.gemini_gen_config` so narrate.py's
    fifth hand-rolled copy could share it. A compiled sibling cannot import from
    this module (it is a launcher shim in the wheel), so `models` is the only
    home both can reach. This stays as the name research.py's callers and tests
    already use.
    """
    return _models_gemini_gen_config(
        temperature=temperature, max_tokens=max_tokens, **extra)


def _gemini_empty_reason(payload: dict) -> str:
    """Why a 200 came back with no text: the finish reason, or a block reason.

    A refusal and an empty success are different faults with different fixes —
    a blocked prompt is ours to change, a token budget spent on thinking is a
    config value — and the old single message described neither.

    ⓘ The body moved to `models.gemini_empty_reason` so narrate.py's panel call
    could name the same reasons; it was the last Gemini leg still reporting an
    empty 200 as a parse fault. A compiled sibling cannot import from this
    module, so `models` is the shared home. This name stays for its callers.
    """
    return _models_gemini_empty_reason(payload)


def _call_text_narrator(
    system: str,
    user_msg: str,
    *,
    gemini_key: str,
    use_gemini: bool = True,
    err_holder: dict | None = None,
    # 2026-08-05: 200 → 800. The old ceiling was sized for a request that
    # disabled thinking, and that disable field is what the endpoint was
    # rejecting (see `_gemini_gen_config`). With thinking on, 200 output tokens
    # returns a 200-with-no-text — `finishReason=MAX_TOKENS`, which
    # `_gemini_empty_reason` already names — so removing the field without
    # raising this would trade a 400 for a silent empty. Narration is hard-capped
    # downstream at 140 chars regardless, so the larger ceiling costs nothing.
    max_tokens: int = 800,
) -> tuple[str | None, int]:
    """Call the shared text-narrator brain. Gemini 3.5 Flash first; Haiku 4.5
    fallback on ANY Gemini failure (4xx non-429, 5xx, timeout, parse error,
    empty output). Sync — callers wrap it in asyncio.to_thread. Returns
    (text, status_code). 429 is surfaced (not fallback) so the outer loop can
    back off — Haiku fallback is reserved for non-rate-limit blips, not for
    absorbing a quota storm on the primary.

    Note: non-429 4xx errors fall through to Haiku (not surfaced) so a
    Gemini-project-scoped quota window doesn't blank output for hours. The
    Gemini→Haiku downgrade is logged once per `err_holder` (a caller-owned
    mutable dict keyed on "gemini_downgrade_logged") so the operator sees when
    text is running on Haiku, without log spam. Pass err_holder=None to
    suppress the downgrade log entirely (best-effort callers with no loop to
    dedupe over, e.g. the async alert-copy upgrade).

    `err_holder["last_vendor"]` is set to "gemini" or "haiku" on every success,
    and it is what the caller must consult before clearing the downgrade flag.
    Clearing it on any successful tick re-arms the log every tick, because the
    tick is succeeding on HAIKU — the state the log exists to report. The
    downgrade line also carries what the API SAID (see `_gemini_error_detail`):
    a message built from the status code alone cannot separate an invalid key
    from a renamed model, and both are HTTP 400 here.

    Hoisted to module scope (was the `_call_narrator` closure inside
    `_narrator_loop`) so both the narrator loop and the async alert-copy
    upgrade reuse the exact same fallback chain. `gemini_key`/`use_gemini` are
    passed in (the narrator loop resolves the key at loop entry; alert-copy
    resolves its own) rather than closed over — this fn makes NO assumption
    about a caller's preconditions."""
    try:
        import requests
    except Exception:
        return None, 0
    # Defensive: Anthropic rejects an empty user turn with a 400
    # ("messages.0: user messages must have non-empty content"); Gemini
    # tolerates it. Every current caller passes a non-empty user_msg, so this
    # guard is INERT today — it exists so a future caller can never again
    # silently collapse the Haiku cross-vendor hedge (and with it the whole
    # fallback chain) down to a canned template.
    if not (user_msg and user_msg.strip()):
        user_msg = "Narrate the current pipeline moment in one present-tense sentence."

    def _note_downgrade(msg: str) -> None:
        # Log the Gemini→Haiku downgrade once per caller-owned err_holder so
        # the operator sees narration is on Haiku without per-tick spam. This
        # replaces the old `nonlocal _gemini_err_logged` closure flag.
        if err_holder is not None and not err_holder.get("gemini_downgrade_logged"):
            log(msg, "WARN")
            err_holder["gemini_downgrade_logged"] = True

    def _won(vendor: str) -> None:
        # Which vendor actually produced the text. The narrator loop clears the
        # downgrade flag when a tick succeeds, and a tick succeeds on HAIKU —
        # so without this the "log once" above resets every tick and the single
        # line becomes one per tick. Measured on the live corpus: 1125 copies of
        # the same warning across two logs, and no successful Gemini call in any
        # of them.
        if err_holder is not None:
            err_holder["last_vendor"] = vendor

    # One budget for both vendors — see `_narrator_http_timeouts`. Measured from
    # here (not from the POST) so a slow DNS/TLS handshake on the primary is
    # debited to the primary, which is what the split is protecting against.
    _http_started = time.monotonic()
    _primary_timeout, _ = _narrator_http_timeouts()

    # Skip the primary entirely once it has been written off for this loop — see
    # `_narrator_note_primary_failure`. Without this the fallback still answered
    # every tick, so narration never broke; it just paid the primary's whole
    # timeout first, every six seconds, for the length of the phase.
    if use_gemini and gemini_key and not _narrator_primary_should_skip(err_holder):
        url_primary = (
            "https://generativelanguage.googleapis.com/v1beta/models/"
            f"{GEMINI_TEXT}:generateContent?key={gemini_key}"
        )
        # Gemini Flash primary. The generationConfig comes from the shared
        # builder — see `_gemini_gen_config` for why the thinking-disable field
        # is gone and why the ceiling below had to rise with it.
        payload = {
            "contents": [{"role": "user", "parts": [{"text": user_msg}]}],
            "systemInstruction": {"parts": [{"text": system}]},
            "generationConfig": _gemini_gen_config(
                temperature=0.2, max_tokens=max_tokens),
        }
        try:
            resp = requests.post(url_primary, json=payload,
                                 timeout=_primary_timeout)
            sc = resp.status_code
            if sc == 429:
                return "", 429  # let outer loop back off
            if sc != 200:
                # ⭐ SAY WHAT GOOGLE SAID. The old line was
                # "Gemini Flash sc=400 (empty or non-200)", which repeats the
                # status and adds nothing — and the cause was sitting in `resp`
                # the whole time. "API key not valid", "models/… is not found"
                # and "Unknown name in generationConfig" are ALL HTTP 400 here,
                # so the status alone cannot tell an expired key from a renamed
                # model. Measured against the live endpoint: a bad key returns
                # 400 INVALID_ARGUMENT / API_KEY_INVALID.
                #
                # ⚠ Decided BEFORE parsing, deliberately. A refusal that arrives
                # as an HTML error page (a 502 from a proxy) is still a refusal;
                # reporting it as "we could not read the body" would describe the
                # parser instead of the fault.
                _note_downgrade(
                    f"[narrator] Gemini {GEMINI_TEXT} refused the call — "
                    f"HTTP {sc} {_gemini_error_detail(resp, payload.get('generationConfig'))} — narration is "
                    f"running on {NARRATOR_HAIKU} until this is fixed")
            else:
                try:
                    j = resp.json()
                    # ⚠ Tolerant of an EMPTY candidates list, not just a missing
                    # text field. A safety block returns `candidates: []` with the
                    # reason in promptFeedback — chaining `[0]` on it raises, and
                    # the run would be told "we could not read the body" about the
                    # one case `_gemini_empty_reason` exists to explain.
                    cand = (j.get("candidates") or [{}])[0] or {}
                    parts = (cand.get("content") or {}).get("parts") or [{}]
                    text = ((parts[0] or {}).get("text") or "").strip()
                    if text:
                        # Clears the consecutive count so an isolated blip cannot
                        # accumulate across a whole phase and trip the breaker on
                        # two failures that were minutes and many successes apart.
                        _narrator_note_primary_success(err_holder)
                        _won("gemini")
                        return text, 200
                    # A 200 with no text is a different fault from a refusal:
                    # the request was accepted and the model returned nothing
                    # (a safety block, or the token budget spent on thinking).
                    # Collapsing the two into one message is how 1125 warnings
                    # said nothing anyone could act on.
                    _note_downgrade(
                        f"[narrator] Gemini {GEMINI_TEXT} returned 200 with no "
                        f"text ({_gemini_empty_reason(j)}) — narration is "
                        f"running on {NARRATOR_HAIKU} until this is fixed")
                except Exception as _parse_e:
                    _note_downgrade(f"[narrator] Gemini {GEMINI_TEXT} sent a 200 "
                                    f"body we could not read "
                                    f"({type(_parse_e).__name__}) — falling back "
                                    f"to {NARRATOR_HAIKU}")
        except Exception as _gemini_e:
            # A TRANSPORT failure — the class that costs the full primary
            # allowance. `ReadTimeout` vs `ConnectTimeout` already separates "the
            # request was accepted and never answered" from "the connection never
            # opened", so the exception name plus the elapsed time is the whole
            # diagnosis; no extra probe is needed.
            _tripped, _detail = _narrator_note_primary_failure(
                err_holder,
                elapsed_s=time.monotonic() - _http_started,
                exc_name=type(_gemini_e).__name__)
            _note_downgrade(f"[narrator] Gemini {GEMINI_TEXT} error "
                            f"({type(_gemini_e).__name__}: "
                            f"{str(_gemini_e)[:120]}) — falling back to "
                            f"{NARRATOR_HAIKU}")
            if _tripped:
                # Deliberately NOT routed through `_note_downgrade`: that logs once
                # per loop and has already spent its one line on the downgrade
                # above, which is precisely how the true failure count stayed
                # hidden. This line fires exactly once per loop on its own terms.
                log(f"[narrator] {GEMINI_TEXT} written off for this phase after "
                    f"{NARRATOR_PRIMARY_TRIP_AFTER} consecutive transport "
                    f"failures ({_detail}) — narration continues on "
                    f"{NARRATOR_HAIKU} with no further primary attempts, so the "
                    f"per-tick wait is no longer spent", "WARN")
        # fall through to Haiku fallback

    # Haiku 4.5 fallback — cross-vendor hedge for Google regional outages.
    # Anthropic SDK is already a BE dep (vision.py uses Sonnet for ACT) so no
    # extra footprint.
    try:
        import anthropic as _anth
        _key = resolve_api_key()
        if not _key:
            return None, 0
        # Whatever the primary left of the shared budget — never below the floor.
        _, _fallback_timeout = _narrator_http_timeouts(
            time.monotonic() - _http_started)
        _cli = _anth.Anthropic(api_key=_key, timeout=_fallback_timeout)
        try:
            resp = _cli.messages.create(
                model=NARRATOR_HAIKU,
                max_tokens=max_tokens,
                system=system,
                messages=[{"role": "user", "content": user_msg}],
            )
            txt = "".join(
                getattr(b, "text", "") for b in resp.content
                if getattr(b, "type", "") == "text"
            )
            _won("haiku")
            return (txt or "").strip(), 200
        except _anth.RateLimitError:
            return "", 429
        except Exception:
            return None, 0
    except Exception:
        return None, 0


async def _narrator_loop(phase: int):
    """Poll the ring buffer every `cadence` seconds. Synthesize one human
    sentence (phase-wide) plus, for Phase 2, one sentence per active agent.
    Emits `phase_narration` always and `agent_narration` for Phase 2.
    Back off on 429 / network blip."""
    # Resolve at loop entry, not module-load — so the user's Account-page
    # apiKeys.gemini wins. Module-load resolution would always lose: the
    # backend may pair / re-fetch keys before any pipeline starts, and the
    # narrator only spins up inside run_pipeline anyway.
    gemini_key = resolve_gemini_api_key()
    if not gemini_key:
        return
    if phase is None or phase < 0:
        return
    cadence = _narrator_cadence_for_phase(phase)
    last_narration = ""
    last_agent_lines: dict[str, str] = {}
    last_known_status_for_agent: dict[str, str] = {}
    phase_started_ts = time.time()
    backoff_ticks_left = 0
    # 2026-05-28: per-agent narrator brain swapped to Gemini 3.5 Flash
    # primary with Haiku 4.5 as cross-vendor fallback. Drivers:
    #  - Cost: 3.5 Flash is ~comparable-or-cheaper at narrator volume
    #    AND the rest of the BE text-task stack (summary, title
    #    fallback, URL extractor) already runs on it — consolidating
    #    the narrator removes the lone Anthropic-text-call outlier.
    #  - Latency: Gemini single-region inference is empirically faster
    #    than the cross-vendor Anthropic hop on this hot path.
    #  - Quality: the prior parrot-input issue that pushed us off
    #    Gemini Pro 2.5 in 04-30 doesn't manifest on 3.5 Flash at
    #    temp 0.2 with the "do not echo input spans" system rule.
    #  - Vendor hedge: Haiku 4.5 stays in place as the fallback so a
    #    Google regional blip doesn't blank narration entirely.
    # Prior order (Haiku primary, Gemini fallback) was the inverse
    # of every other text-task on the BE; this swap aligns the path.
    # Backwards-compat: honor legacy DG_NARRATOR_USE_HAIKU env (renamed to
    # DG_NARRATOR_USE_GEMINI on 2026-05-28 when the primary swapped). The
    # semantic flipped — old "1" meant "use Haiku primary", new "1" means
    # "use Gemini primary" — so we invert when reading the legacy var.
    # Operators with the old name pinned in .dg-supervisor.env get one
    # release of grace before the alias is removed.
    _legacy_use_haiku = os.environ.get("DG_NARRATOR_USE_HAIKU")
    if _legacy_use_haiku is not None:
        _legacy_truthy = _legacy_use_haiku.lower() not in ("0", "false", "no")
        _USE_GEMINI = not _legacy_truthy
    else:
        _USE_GEMINI = os.environ.get("DG_NARRATOR_USE_GEMINI", "1").lower() not in ("0", "false", "no")
    _gemini_model = GEMINI_TEXT
    _haiku_model = NARRATOR_HAIKU
    _err_logged = False  # one-shot — avoid log spam if narrator stays broken
    # One-shot Gemini→Haiku downgrade log, shared across all three call sites
    # (phase / per-agent / Tier-3 fallback) within this loop invocation and
    # threaded into the module-level `_call_text_narrator` as its err_holder.
    # Reset on recovery (anti-latch) below. Replaces the old
    # `nonlocal _gemini_err_logged` closure flag now that the narrator brain
    # is hoisted to module scope (shared with the async alert-copy upgrade).
    # One holder per narrator loop, i.e. per PHASE — which is also the lifetime of
    # the primary-vendor circuit breaker below, so each phase gets one clean
    # attempt at the primary regardless of how the previous phase went.
    # `gemini_tripped` is deliberately NOT cleared by the re-arm further down:
    # that re-arm is gated on Gemini having answered, and a tripped primary is
    # never called, so the two cannot fight.
    _narrator_err_holder = {"gemini_downgrade_logged": False, "last_vendor": "",
                            "gemini_consecutive_fail": 0, "gemini_tripped": False}

    async def _realistic_fallback(akey: str, ph: int, elapsed_sec: float,
                                   last_status: str = "", *,
                                   recent_hosts=None) -> str:
        """Tier 3 fallback narration — when real data (DOM + vision) is sparse
        OR Tier-2 (LLM on real events) refused / failed the quality gate,
        ask Haiku/Flash to produce ONE realistic sentence based on phase
        + elapsed time + the typical timeline. The output cites the actual
        timeline stage (planning vs searching vs synthesizing) so it feels
        real rather than generic.

        Tier-3 OWN output is also gated through `_is_acceptable_narration`
        and `_is_skip_token` — if the model refuses again, return empty
        and the caller falls through to Tier-4 deterministic template."""
        timeline = AGENT_PHASE_FLOWS.get((akey, ph))
        if not timeline:
            return ""
        elapsed_min = elapsed_sec / 60.0
        timeline_text = "\n".join(f"- {t}" for t in timeline)
        hosts_block = ""
        hosts_hint = ""
        if recent_hosts:
            hosts_block = (
                f"Recently visited hosts: {', '.join(recent_hosts[:2])}\n\n"
            )
            hosts_hint = (
                f" If natural, mention one host — 'skimming {recent_hosts[0]}' "
                "beats 'reading sources'."
            )
        fb_system = (
            f"You narrate what the {akey.upper()} agent is likely doing right now. "
            f"Elapsed: {elapsed_min:.1f} minutes. "
            f"Last known status: {last_status or 'unknown'}.\n\n"
            f"TYPICAL TIMELINE for {akey.upper()}:\n"
            f"{timeline_text}\n\n"
            f"{hosts_block}"
            "Output ONE realistic sentence in present tense (<= 110 chars) "
            f"describing what's happening at minute {elapsed_min:.1f} of the "
            "timeline above. Reference the specific stage by what the agent "
            f"is doing (e.g. 'ChatGPT is mapping cluster overlaps across the "
            f"first 80 sources').{hosts_hint}\n\n"
            "FORBIDDEN — your output is broadcast verbatim to the user. NEVER:\n"
            "  - Questions or '?'.\n"
            "  - Refusals ('I don't have', 'I cannot', 'lacks sufficient', "
            "'Without more', 'I need').\n"
            "  - First-person ('I '). You are not in the conversation.\n"
            "  - Meta-references ('the events', 'the log', 'event payload',\n"
            "    'structured fields').\n"
            "  - 'Super Research Phase' / 'in Phase N' / 'Phase 2'.\n"
            "  - Multi-sentence answers (one period only).\n"
            "  - 'currently' as a leading word, 'Status:' prefix.\n"
            "  - Generic 'still working' / 'is still processing'.\n\n"
            "Stage references like 'in the synthesis stage' or 'in extended "
            "thinking' are FINE — only the literal 'Phase N' pipeline-meta is "
            "banned. Start with the agent name. No markdown, no em-dashes. "
            "If you cannot produce a clean sentence, output the literal token "
            "SKIP and nothing else; a deterministic template will replace it."
        )
        # Pass a concise, NON-EMPTY user nudge (not "") so the Haiku
        # cross-vendor hedge works too: Anthropic 400s on empty user
        # content ("messages.0: user messages must have non-empty
        # content") while Gemini tolerates it. An empty user_msg here
        # silently collapsed Tier-3 → Haiku to a canned Tier-4 template
        # whenever Gemini was down (frequent on flaky networks — see the
        # recurring SSLError/ReadTimeout in backend.log), which is the
        # "stale/shallow" narration users still saw during sparse-data
        # windows (P1 extended-thinking, P2 planning gaps). The rich
        # timeline/elapsed/host context already lives in fb_system; this
        # is just a non-empty user turn so BOTH brains accept the call.
        fb_user = (
            f"Narrate what the {akey.upper()} agent is doing right now, "
            f"at minute {elapsed_min:.1f} of its run. One present-tense sentence."
        )
        fb_text, fb_status = await asyncio.to_thread(
            _call_text_narrator, fb_system, fb_user,
            gemini_key=gemini_key, use_gemini=_USE_GEMINI,
            err_holder=_narrator_err_holder, max_tokens=200,
        )
        if fb_status >= 400 or not fb_text:
            return ""
        fb_text = fb_text.strip().strip('"').strip("`").strip()
        if _is_skip_token(fb_text):
            return ""
        if not _is_acceptable_narration(fb_text):
            return ""
        return fb_text[:140]

    try:
        while True:
            await asyncio.sleep(cadence if backoff_ticks_left == 0 else 15.0)
            if backoff_ticks_left > 0:
                backoff_ticks_left -= 1
            try:
                if _controls.is_stop() or _controls.is_pause():
                    continue
            except Exception:
                pass
            # Phase-scope filter — the ring buffer is process-global, so a
            # Phase 2 `agent_progress` from 28s ago can leak into Phase 3's
            # narrator and produce "Still working on Phase 2: generating
            # the agent reports..." emitted under phase=3 (observed in the
            # FE Phase 3 dropdown 2026-04-28). Filter to the current phase
            # only, plus any events without a phase tag (system events).
            recent_raw = _recent_events_window(30.0)
            recent = [e for e in recent_raw
                      if e.get("phase") in (phase, None)]
            phase_ctx = PHASE_FLOW_CONTEXT.get(phase, "")
            data_rich = phase in (1, 2)
            style_note = (
                "CITE the real scrape content when you can — reference specific "
                "source counts, section titles, or partialTextLen numbers you see "
                "in the events. Do not invent specifics."
                if data_rich else
                "Reason from the hardcoded phase flow + elapsed time + last status "
                "transition. Do not invent specific numbers."
            )
            system = (
                "You narrate ONE human sentence summarizing what the Super Research "
                "pipeline is doing RIGHT NOW for a user watching the phase dropdown. "
                f"Phase {phase}: {phase_ctx} {style_note}\n\n"
                "HARD CONSTRAINTS — your output is broadcast verbatim to a human "
                "user with zero post-processing. Every word ships.\n\n"
                "OUTPUT SHAPE: Exactly ONE COMPLETE sentence ending in a period. "
                "<= 110 chars. Never stop mid-clause — if it will not fit, "
                "say less. Subject = the "
                "pipeline OR a specific agent (ChatGPT/Gemini/Claude). Verb = "
                "present-progressive (is reading, is mapping, is drafting). "
                "Object = a concrete thing from the events. Period. End.\n\n"
                "NEVER (these ship to the user as-is):\n"
                "  - Questions. No 'Could you', 'Can you', 'Would you', '?'.\n"
                "  - First-person ('I '). You are not in the conversation.\n"
                "  - Refusals or capability disclaimers ('I don't have', "
                "'lacks sufficient', 'I cannot narrate', 'Without more', "
                "'I need').\n"
                "  - Meta about the input ('the events show', 'the log "
                "indicates', 'structured fields', 'event payload', 'recent "
                "entries', 'based on the data').\n"
                "  - Multi-sentence answers (no second period followed by space).\n"
                "  - Lists, bullets, em-dashes for enumeration, prefixes like "
                "'Currently' or 'Status:'.\n"
                "  - Generic stalls: 'still working', 'still processing', "
                "'in progress'.\n\n"
                "WHEN DATA IS THIN: Output the literal token  SKIP  on its own "
                "and nothing else. A deterministic fallback will produce a "
                "sentence from the typical phase flow. Your refusal would be "
                "worse than silence.\n\n"
                "WHEN DATA IS RICH: Cite specifics — counts, section names, "
                "hostnames from `host=` or `hosts=` lines, focus areas from "
                "`currentFocus`. Weave hostnames naturally: 'pulling Tesla "
                "10-K filings from sec.gov' beats 'reading sources'. Cap at "
                "1-2 hostnames per sentence."
            )
            event_lines = "\n".join(
                f"- {_compact_event_for_narration(e)}" for e in recent[-20:]
            )
            user_msg = f"Recent events (newest last):\n{event_lines or '[none]'}"

            text, status_code = await asyncio.to_thread(
                _call_text_narrator, system, user_msg,
                gemini_key=gemini_key, use_gemini=_USE_GEMINI,
                err_holder=_narrator_err_holder,
            )
            if status_code == 429:
                backoff_ticks_left = 3
                continue
            if not text or status_code >= 400:
                # One-shot diagnostic — without this, a deprecated model or bad
                # API key produces a completely silent failure (the gemini-2.0
                # → 2.5 deprecation went unnoticed because every tick just
                # `continue`d). Log the first failure per phase so the operator
                # can act; subsequent failures stay quiet to avoid log spam.
                if not _err_logged:
                    log(f"[narrator] narrator call failed status={status_code} "
                        f"(use_gemini={_USE_GEMINI}, primary={_gemini_model}, "
                        f"fallback={_haiku_model}) "
                        f"— phase narration silent until resolved. Check "
                        f"GEMINI_API_KEY or ANTHROPIC_API_KEY.", "WARN")
                    _err_logged = True
                continue
            # Reset both err flags once we recover so a later regression re-logs.
            _err_logged = False
            # ⛔ The downgrade flag resets only when GEMINI came back — not when
            # the tick merely succeeded. A tick succeeds on Haiku, which is the
            # very state the downgrade line reports, so clearing it here
            # unconditionally turned "log once per phase" into "log every tick":
            # 1125 copies of one warning across the live corpus, with no
            # successful Gemini call anywhere in it. The anti-latch intent is
            # preserved — a transient Gemini blip still re-arms the log the
            # moment Gemini answers again.
            if _narrator_err_holder.get("last_vendor") == "gemini":
                _narrator_err_holder["gemini_downgrade_logged"] = False
            text = text.strip().strip('"').strip("`").strip()
            # SKIP escape hatch — model used the designated fallback signal
            # because data was too thin to narrate honestly. Replace with
            # a deterministic phase template so the FE never goes silent.
            if _is_skip_token(text):
                text = f"Super Research is in {_phase_short_label(phase)}."
            # Quality gate — drop fragments / single-words / refusal text /
            # stopword-tail mid-sentence cuts before they hit the wire. On
            # reject, fall through to the same deterministic template (a
            # sustained Tier-2 refusal mode would otherwise leave the FE
            # narration frozen on stale text for minutes). Dedupe at emit
            # site means this template lands once per phase if Tier-2 stays
            # in refusal — subsequent ticks return clean output and resume.
            # Trim to the last WHOLE sentence first: a model that adds a
            # dangling clause after a good sentence should lose the clause, not
            # the narration. Only a line with no complete sentence at all falls
            # through to the deterministic template.
            text = _narration_last_sentence(text) or text
            if text and not _is_acceptable_narration(text):
                text = f"Super Research is in {_phase_short_label(phase)}."
            if text and text != last_narration:
                last_narration = text
                try:
                    emit_event("phase_narration", phase=phase, text=text)
                except Exception:
                    pass

            # ── Per-agent narration (P1 + P2) ──
            # Filter the recent window per agent and emit one `agent_narration`
            # per active agent so the per-agent card carries live context.
            # Phase 1 has only ChatGPT (Pro + Extended Thinking); Phase 2 has
            # all three. When an agent has no events in the window AND we're
            # past the 60s warmup, fall back to Tier 3 realistic narration
            # (Gemini + typical timeline) so the card never goes blank during
            # long Extended-Thinking or planning windows where DOM and vision
            # both produce nothing for minutes at a stretch.
            if phase == 1:
                agent_keys = ("chatgpt",)
            elif phase == 2:
                agent_keys = ("chatgpt", "gemini", "claude")
            else:
                agent_keys = ()
            if agent_keys:
                elapsed_in_phase = time.time() - phase_started_ts
                for akey in agent_keys:
                    a_events = [e for e in recent
                                if (e.get("agent") or "").lower() == akey
                                or ((e.get("data", {}) or {}).get("agent") or "").lower() == akey]
                    if not a_events:
                        # Never-started agent: P2 opens ChatGPT → Claude →
                        # Gemini sequentially (~30s apart). If this agent hasn't
                        # produced a single event yet, it isn't underway — stay
                        # SILENT rather than fabricating "Claude is…" before the
                        # backend has even opened Claude (which would contradict
                        # the FE's "Waiting to start" queued card). Once it has
                        # emitted at least one event, the quiet-window Tier-3
                        # fallback below resumes as before.
                        if akey not in last_known_status_for_agent:
                            continue
                        # Tier 3 fallback — only after 60s warmup so we don't
                        # produce bogus narration during the brief window where
                        # DOM scrape is settling and vision hasn't run yet.
                        # (Rejection-triggered fallback below skips this gate.)
                        if elapsed_in_phase < 60:
                            continue
                        last_status = last_known_status_for_agent.get(akey, "")
                        # Per-agent has no events; pull hosts from phase-wide
                        # window so the fallback can still cite a real source
                        # if any agent visited one in the recent ring buffer.
                        recent_hosts_phase = _extract_top_hosts(recent)
                        fb_text = await _realistic_fallback(
                            akey, phase, elapsed_in_phase, last_status,
                            recent_hosts=recent_hosts_phase,
                        )
                        # Tier-4 deterministic template if Tier-3 LLM call
                        # also refused/failed — round-robin rotation per
                        # agent so consecutive Tier-4 emits don't collide
                        # with the dedupe equality guard below.
                        if not fb_text:
                            fb_text = _tier4_template(akey, phase)
                        if fb_text and fb_text != last_agent_lines.get(akey):
                            last_agent_lines[akey] = fb_text
                            try:
                                emit_event("agent_narration", phase=phase,
                                           agent=akey, text=fb_text,
                                           fallback=True)
                            except Exception:
                                pass
                        continue
                    # Track latest status so a future fallback (after events
                    # stop arriving) can reference it for richer context.
                    for _e in reversed(a_events):
                        _d = _e.get("data", {}) or {}
                        if _d.get("status"):
                            last_known_status_for_agent[akey] = str(_d["status"])
                            break
                    a_lines = "\n".join(
                        f"- {_compact_event_for_narration(e)}" for e in a_events[-12:]
                    )
                    a_system = (
                        f"You narrate ONE human sentence about what the {akey.upper()} "
                        f"agent is doing RIGHT NOW.\n\n"
                        "HARD CONSTRAINTS — your output is broadcast verbatim to a "
                        "human user with zero post-processing. Every word ships.\n\n"
                        f"OUTPUT SHAPE: Exactly ONE COMPLETE sentence ending in a period. "
                        f"<= 140 chars. Never stop mid-clause — if it will "
                        f"not fit, say less. Subject "
                        f"= {akey.upper()}. Verb = present-progressive (is reading, "
                        "is mapping, is drafting). Object = a concrete thing from "
                        "the events. Period. End.\n\n"
                        "NEVER (these ship to the user as-is):\n"
                        "  - Questions. No 'Could you', 'Can you', 'Would you', '?'.\n"
                        "  - First-person ('I '). You are not in the conversation.\n"
                        "  - Refusals or capability disclaimers ('I don't have', "
                        "'lacks sufficient', 'I cannot narrate', 'Without more', "
                        "'I need').\n"
                        "  - Meta about the input ('the events show', 'the log "
                        "indicates', 'structured fields', 'event payload', 'recent "
                        "entries', 'based on the data').\n"
                        "  - Multi-sentence answers (no second period followed by space).\n"
                        "  - Lists, bullets, em-dashes, prefixes ('Currently', 'Status:').\n"
                        "  - Generic stalls: 'still working', 'still processing'.\n"
                        "  - Pipeline meta: 'Super Research Phase N', 'in Phase 2', "
                        "'Phase 1 of the pipeline'. Stage names like 'in the "
                        "synthesis stage' / 'in extended thinking' / 'is now in "
                        "<stage>' are FINE — only literal 'Phase N' is banned.\n"
                        "  - Echoing input verbatim. If input contains 'research "
                        "voice mode false positives', do NOT write 'researching "
                        "voice mode false positives'. Paraphrase or output SKIP.\n"
                        "  - UI chrome: 'You said:', '<name> responded:', 'brief.md'.\n\n"
                        "WHEN DATA IS THIN: Output the literal token  SKIP  on its "
                        "own and nothing else. A deterministic fallback will "
                        "produce a sentence from the typical timeline. Your "
                        "refusal would be worse than silence.\n\n"
                        "WHEN DATA IS RICH: Weave structured fields (searches, "
                        "sectionsDone/Total, currentFocus, partialTextLen) as "
                        "paraphrased facts, not quoted strings. When events "
                        "contain `steps=<titles>` that is the platform's OWN "
                        "description of its current activity — GROUND your "
                        "sentence in the freshest step (the truth of what's "
                        "happening now), paraphrased not quoted. When events "
                        "contain `host=<domain>` or `hosts=foo.com,bar.com`, "
                        "weave 1-2 hostnames naturally — 'ChatGPT is skimming "
                        "sec.gov filings on Tesla 10-K' beats 'ChatGPT is "
                        "reading three sources'.\n\n"
                        "GOOD examples (paraphrase activity, don't quote input):\n"
                        "  - 'Gemini is mapping discrepancy patterns across the "
                        "latest test runs while pulling fresh sources.'\n"
                        "  - 'Claude has woven 380 sources into a 7-section "
                        "outline so far.'\n"
                        "  - 'ChatGPT is narrowing in on the false-positive root "
                        "cause via the docs cluster on sec.gov.'\n\n"
                        f"SCOPE: ONLY {akey.upper()}'s progress. Don't compare agents."
                    )
                    # Pass the previous narration so the model writes
                    # something MEANINGFULLY DIFFERENT instead of
                    # paraphrasing the same idea each tick — fixes the
                    # user-reported "all five narrations say 198 chars
                    # of partial output" pattern during ChatGPT's
                    # extended-thinking window where state changes
                    # little between ticks. The model emits SKIP if
                    # there's nothing new to say; the emit-site
                    # similarity gate below is a belt-and-suspenders
                    # backstop if it ignores the instruction.
                    prev_narration = last_agent_lines.get(akey, "")
                    prev_narration_clause = (
                        f"\n\nPREVIOUS NARRATION (do NOT repeat or paraphrase this — "
                        f"if the agent's state hasn't materially changed, output SKIP):\n"
                        f"\"{prev_narration}\""
                    ) if prev_narration else ""
                    a_user = (
                        f"Recent events for {akey.upper()} (newest last):\n"
                        f"{a_lines or '[none]'}"
                        f"{prev_narration_clause}"
                    )
                    a_text, a_status = await asyncio.to_thread(
                        _call_text_narrator, a_system, a_user,
                        gemini_key=gemini_key, use_gemini=_USE_GEMINI,
                        err_holder=_narrator_err_holder, max_tokens=200,
                    )
                    if a_status == 429:
                        backoff_ticks_left = 3
                        break
                    a_text = (a_text or "").strip().strip('"').strip("`").strip()
                    # SKIP escape hatch — model used the designated fallback
                    # signal. Treat as rejected so the fallback chain runs.
                    if _is_skip_token(a_text):
                        a_text = ""
                    # Quality gate — drop refusal text / fragments / overlength.
                    else:
                        a_text = _narration_last_sentence(a_text) or a_text
                        if a_text and not _is_acceptable_narration(a_text):
                            a_text = ""
                    # Empty result (Tier-2 refused, failed gate, or upstream
                    # error) → fall through to Tier-3 realistic fallback. Bypass
                    # the 60s warmup gate that applies to the no-events branch
                    # — an active refusal is worse than t<60. Tier-3 takes the
                    # recent_hosts hint so the fallback can cite real sources
                    # when the agent has visited any.
                    if not a_text:
                        last_status = last_known_status_for_agent.get(akey, "")
                        recent_hosts_for_agent = _extract_top_hosts(a_events)
                        a_text = await _realistic_fallback(
                            akey, phase, elapsed_in_phase, last_status,
                            recent_hosts=recent_hosts_for_agent,
                        )
                        # Tier-4 deterministic template — Tier-3 calls the same
                        # Haiku/Flash chain that just refused; if THAT also
                        # failed/refused, use a pure-string template that
                        # cannot be rejected. Round-robin rotation defeats
                        # the equality dedupe at the emit site below.
                        if not a_text:
                            a_text = _tier4_template(akey, phase)
                    # Two-stage dedupe at emit: exact-equality (prior
                    # behavior) + Jaccard similarity to the last emitted
                    # narration (catches paraphrases that share the same
                    # data points — "198 chars partial output" vs "198
                    # tokens drafted"). Tier-4 templates are short and
                    # phrased differently across rotations, so they pass
                    # the similarity gate naturally.
                    if a_text and a_text != last_agent_lines.get(akey) and not _too_similar_to_recent(a_text, last_agent_lines.get(akey, "")):
                        last_agent_lines[akey] = a_text
                        try:
                            emit_event("agent_narration", phase=phase,
                                       agent=akey, text=a_text)
                        except Exception:
                            pass
    except asyncio.CancelledError:
        return
    except Exception as _e:
        try:
            log(f"[narrator] loop crashed ({_e}) — narration stopped for phase {phase}", "WARN")
        except Exception:
            pass
        return


def start_narrator(phase: int):
    """Cancel any existing narrator task and start a fresh one scoped to
    this phase. Wired automatically from emit_event on `phase_start`.
    Safe to call when there's no running event loop (silently no-ops)."""
    global _narrator_task
    try:
        if _narrator_task and not _narrator_task.done():
            _narrator_task.cancel()
    except Exception:
        pass
    try:
        import narrate as _vn
        _vn.reset_phase_budget()
    except Exception:
        pass
    try:
        _narrator_task = asyncio.create_task(_narrator_loop(phase))
    except RuntimeError:
        # No running event loop (pre-startup / CLI paths). Skip.
        _narrator_task = None


def stop_narrator():
    """Cancel the narrator task. Wired automatically from emit_event on
    `phase_complete` / `phase_skipped`. Also called explicitly by
    orchestrator teardown / exception paths."""
    global _narrator_task
    try:
        if _narrator_task and not _narrator_task.done():
            _narrator_task.cancel()
    except Exception:
        pass
    _narrator_task = None


# ── Login URL negatives (shared between Phase 0 preflight + setup) ─────
# Known login-wall host fragments. When the browser lands on one of
# these after a navigation, the profile is not authenticated on that
# platform. Cheap short-circuit before spending CUA.

_LOGIN_HOST_NEGATIVES = (
    "auth.openai.com", "accounts.google.com/signin",
    # Google's sign-in surfaces (#899). These are the ONLY signed-out tell
    # for Gemini/NotebookLM (the DOM probes below are ChatGPT-specific), so
    # they must cover where the flow actually RESTS, not just the entry hop:
    # /servicelogin is a legacy 302 redirector; the flow lands and sits on
    # /v3/signin/* (identifier + challenge/password pages — a mid-sign-in
    # user is still "walled"). Every consumer lowercases before matching.
    "accounts.google.com/servicelogin",
    "accounts.google.com/v3/signin",
    "accounts.google.com/interactivelogin",
    "accounts.google.com/accountchooser",
    "login.live.com", "claude.ai/login", "claude.ai/signup",
)

# NOTE (2026-04-24): `await_phase_login_probe` used to live here as a
# per-phase cookie-only gate called at the start of Phases 1-5. It
# turned every transient cookie blip into a mid-run `login_required`
# banner even when Phase 0 had just verified successfully. The layer
# is deleted — Phase 0 is now the single source of truth for login
# state. If a session really drifts mid-run, the phase's own driving
# code (ChatGPT navigation, NotebookLM upload, etc.) will surface a
# concrete failure through fail_phase with a specific reason, which
# the existing PhaseAlertPanel handles without the generic
# "Login required" noise.


# ⭐⭐ 2026-08-06 — ONE CEILING FOR THE SOURCE LIST, AND IT WAS SIZED BELOW THE PANEL.
#
# The 2026-08-06 run's ChatGPT activity panel held 142 distinct non-platform URLs
# in a single sample (157 anchors, 154 rows, captured to
# `p2_panel_dump_2.html`). Every walker truncated its OWN sample to 50 BEFORE the
# cross-sample union ever saw it, and the panel had gone from 3 anchors to 157 in
# one 45-second sample — so 92 sources were discarded at the door and no later
# tick could recover them. The card read "50 sources" all run.
#
# ⛔ AND THE OBVIOUS FIX WAS THE WRONG ONE. "Keep the newest 50" was proposed and
# is measurably WORSE on this very panel: the head is the topic's primary
# evidence (github.com/NVIDIA/NemoClaw, docs.nvidia.com/nemoclaw/…,
# github.com/NVIDIA/OpenShell/releases) and the tail is where the search drifted
# (goodreads "august releases", a games round-up, a book-blog). Document order in
# this panel is roughly relevance order. So the direction stays head-first and the
# CEILING moves instead — which is the thing that was actually binding.
#
# 200 keeps a real bound (a pathological panel still cannot blow up a Firestore
# doc: 200 URLs is ~20 KB against a 1 MB limit) while sitting comfortably above
# every panel size this project has measured.
#
# ⚠ The JavaScript walkers cannot import this. They carry the literal, and
# `tests/test_source_cap_0806.py` asserts every one of them equals this value —
# that test is the only thing keeping the two sides in step, so do not delete it
# in favour of a comment.
_SOURCE_LIST_CAP = 200


async def scrape_progress_chatgpt(page):
    """Scrape ChatGPT's current research progress (Playwright JS — zero CUA cost).
    Returns rich data for web app: status, thinking steps, sources, sections, text length.

    Deep Research note: as of 2026, ChatGPT Deep Research renders inside a cross-origin
    iframe (connector_openai_deep_research.web-sandbox.oaiusercontent.com). Main-page
    selectors miss DR content, so we iterate `page.frames` and scrape the DR frame
    separately, then merge. Main-page signals (title, model, stop button) still come
    from the host page."""
    try:
        # ---- Main-page scrape (host page: title, model, stop button, chat-level DR indicators)
        result = await page.evaluate("""() => {
            const r = {
                status: 'unknown', phase: '', progress: '', thinking: '',
                sources: 0, source_urls: [], sections: [], steps: [],
                partial_text_len: 0, plan: '', model: '', title: '',
                dr_active: false, dr_done_text: false, has_stop_btn: false,
                panel_open: false, searches: 0
            };
            // Model info
            const modelEl = document.querySelector('[data-testid="model-selector"], .model-label');
            if (modelEl) r.model = modelEl.innerText.substring(0, 50);
            // Conversation title
            const titleEl = document.querySelector('h1, [data-testid="conversation-title"]');
            if (titleEl) r.title = titleEl.innerText.substring(0, 100);
            // Stop-button detection (aria-label + text fallback)
            r.has_stop_btn = !!document.querySelector(
                'button[aria-label="Stop generating"], button[aria-label*="Stop"], ' +
                'button[data-testid="stop-button"], button[data-testid*="stop"]'
            );
            if (!r.has_stop_btn) {
                const btns = document.querySelectorAll('button');
                for (const b of btns) {
                    const t = (b.textContent || '').trim().toLowerCase();
                    if (t === 'stop' || t === 'stop generating' || t === 'stop research') { r.has_stop_btn = true; break; }
                }
            }
            // Body-level DR indicators (host page shows banner/status strings even when content is in iframe)
            const bodyLower = document.body.innerText.toLowerCase();
            const drKws = ['researching', 'sources found', 'sources and counting',
                          'searching the web', 'reading sources', 'analyzing',
                          'deep research', 'looking into', 'investigating'];
            r.dr_active = drKws.some(kw => bodyLower.includes(kw));

            // 2026-04-26 v3: extract the COLLAPSED activity strip BEFORE the
            // side panel opens. Strip wording: "Looking into Hermes memory
            // system... 196 searches". Without this, FE per-platform card
            // shows empty narration for the first 3 min (gate is 180s).
            // Verb regex constrained to start-of-string + count badge so
            // stale chat text (user prompts, prior responses) won't match.
            try {
                const VERB = /^(thinking|reasoning|searching|looking|browsing|investigating|analyzing|reading|exploring|checking|visiting|researching|confirming|summari[zs]ing|synthesi[zs]ing|drafting|finali[zs]ing)\\b/i;
                const COUNT = /\\b\\d+\\s+(?:searches?|sources?|results?)\\b/i;
                let stripText = '';
                let stripTop = -1;
                const cands = document.querySelectorAll('div, button, [role="button"], li');
                for (const el of cands) {
                    const t = (el.innerText || '').trim();
                    if (!t || t.length < 6 || t.length > 220) continue;
                    if (!(VERB.test(t) && COUNT.test(t))) continue;
                    const rect = el.getBoundingClientRect();
                    if (rect.width === 0 || rect.height === 0) continue;
                    if (rect.top > stripTop) { stripText = t.slice(0, 200); stripTop = rect.top; }
                }
                if (stripText) {
                    r.progress = stripText;
                    r.steps.push(stripText);
                    // Searches count — pull the integer from the strip badge
                    // (e.g., "Summarizing X · 133 searches"). Tracked
                    // separately from r.sources (URL-derived) because a
                    // single search yields many sources and the user cares
                    // about both: how many web queries were issued vs how
                    // many citations made it into the report.
                    const sm = stripText.match(/(\\d+)\\s+searches?/i);
                    if (sm) r.searches = parseInt(sm[1], 10) || 0;
                }
            } catch(e) {}
            // Completion indicators
            const doneKws = ['research completed', 'research complete',
                             'finished research', 'deep research completed'];
            r.dr_done_text = doneKws.some(kw => bodyLower.includes(kw));
            // Thinking/research progress (host page, rare in iframe DR but kept for chat mode)
            const thinking = document.querySelector('.thinking-text, [data-thinking], .research-progress, .step-text');
            if (thinking) r.thinking = thinking.innerText.substring(0, 500);
            // Sources/citations (host page — kept for non-DR chat)
            const srcSet = new Set();
            document.querySelectorAll(
                '.citation, .source-link, [data-citation], ' +
                '[data-message-author-role="assistant"] a[href*="http"], ' +
                '[data-testid="canvas"] a[href*="http"], .canvas-container a[href*="http"]'
            ).forEach(s => {
                const href = s.href || '';
                if (href.startsWith('http') && !href.includes('chatgpt.com') && !href.includes('openai.com') && !href.includes('chat.openai') && !href.includes('oaiusercontent') && href.length < 500)
                    srcSet.add(href);
            });
            r.source_urls = Array.from(srcSet).slice(0, 200);
            r.sources = r.source_urls.length;
            // Response sections (host page headings)
            const headings = document.querySelectorAll('[data-message-author-role="assistant"] h1, [data-message-author-role="assistant"] h2, [data-message-author-role="assistant"] h3');
            r.sections = Array.from(headings).map(h => h.innerText.substring(0, 80));
            // Partial response length (host page)
            const msgs = document.querySelectorAll('[data-message-author-role="assistant"]');
            if (msgs.length > 0) r.partial_text_len = msgs[msgs.length-1].innerText.length;
            // Canvas/artifact content
            const canvas = document.querySelector('[data-testid="canvas"], .canvas-container, .canvas-content');
            if (canvas && canvas.innerText.length > r.partial_text_len) r.partial_text_len = canvas.innerText.length;
            return r;
        }""")

        # ---- Host-page side-panel scrape (P1 Pro+ET, also catches P2 host-side panel)
        # P1 mode renders the activity panel inline on the host page (no DR
        # sandbox iframe). After _open_chatgpt_activity_panel clicks the strip,
        # the side panel mounts as <aside>/[role=complementary]/panel-class div
        # on the right ~30-40% of viewport. The iframe block below only matches
        # P2 DR; this block fills the P1 gap with a Gemini-style wide-net sweep
        # of the panel root: VERB-prefixed step rows, generic a[href] sources
        # with chatgpt.com redirector unwrap + chrome filter, h1/h2/h3 sections.
        # Returns panel_found:false when no host-side panel exists (e.g. P2 DR
        # where panel is iframe-rooted) → no-op merge, iframe block runs next.
        try:
            hp = await page.evaluate("""() => {
                const out = { steps: [], source_urls: [], sections: [], progress: '', panel_found: false };
                const sels = [
                    'aside', '[role="complementary"]', '[role="region"]',
                    '[aria-label*="source" i]', '[aria-label*="research" i]',
                    '[aria-label*="activity" i]',
                    '[class*="panel" i][class*="side" i]',
                    '[class*="research" i][class*="panel" i]',
                    '[class*="activity" i][class*="panel" i]'
                ];
                let root = null;
                for (const sel of sels) {
                    for (const el of document.querySelectorAll(sel)) {
                        const rc = el.getBoundingClientRect();
                        if (rc.width < 280 || rc.height < 200) continue;
                        if (rc.right < window.innerWidth * 0.55) continue;
                        const inner = (el.innerText || '').trim();
                        if (inner.length < 50) continue;
                        root = el; break;
                    }
                    if (root) break;
                }
                if (!root) return out;
                out.panel_found = true;
                // 2026-04-26 v5: structure-only gate. Old VERB+check+spin
                // gate dropped Extended Thinking reasoning paragraphs and
                // Deep Research source-title rows because they often have
                // no spin/check icon AND no verb prefix. New gate accepts
                // any leaf-row (no nested listitems) with substantial text.
                const VERB = /^(checking|searching|looking|browsing|investigating|analyzing|reading|exploring|visiting|researching|thinking|reasoning|gathering|reviewing|consulting|comparing|evaluating|considering|drafting|writing|finalizing|finalising|summari[zs]ing|confirming|synthesi[zs]ing)\\b/i;
                const rowEls = Array.from(root.querySelectorAll('li, [role="listitem"], div, p, button, [role="button"]'));
                const seenKey = new Set();
                const rows = [];
                for (const el of rowEls) {
                    const t = (el.innerText || '').trim();
                    if (!t || t.length < 12 || t.length > 240) continue;
                    if (el.querySelector('li, [role="listitem"]')) continue;
                    if (t === t.toUpperCase() && t.length < 30) continue;
                    const wordChars = t.replace(/[^A-Za-z]/g, '').length;
                    if (wordChars < 8) continue;
                    if ((t.match(/\\n/g) || []).length > 3) continue;
                    const hasCheck = !!el.querySelector('svg[class*="check"], svg[data-icon*="check"], [aria-label*="completed" i]');
                    const hasSpin  = !!el.querySelector('svg[class*="spin"], svg[class*="loader"], [class*="animate-spin"], [aria-busy="true"]');
                    const verbHit  = VERB.test(t);
                    const key = t.slice(0, 80);
                    if (seenKey.has(key)) continue;
                    seenKey.add(key);
                    rows.push({ t: t.slice(0, 220), hasSpin, hasCheck, verbHit });
                }
                out.steps = rows.map(r => r.t).slice(-15);
                const live = rows.find(r => r.hasSpin)
                           || rows.find(r => r.verbHit && !r.hasCheck)
                           || (rows.length ? rows[rows.length - 1] : null);
                if (live) out.progress = live.t.slice(0, 160);
                else if (out.steps.length) out.progress = out.steps[out.steps.length - 1];
                const srcSet = new Set();
                root.querySelectorAll('a[href^="http"]').forEach(a => {
                    let h = a.href || '';
                    if (!h || h.length >= 500) return;
                    try {
                        if (h.includes('chatgpt.com/') && h.includes('url=')) {
                            const u = new URL(h);
                            const real = u.searchParams.get('url');
                            if (real && real.startsWith('http')) h = decodeURIComponent(real);
                        }
                    } catch(e) {}
                    if (h.includes('chatgpt.com') || h.includes('openai.com') ||
                        h.includes('oaiusercontent') || h.includes('chat.openai')) return;
                    srcSet.add(h);
                });
                out.source_urls = Array.from(srcSet).slice(0, 200);
                out.sections = Array.from(root.querySelectorAll('h1, h2, h3'))
                    .map(h => (h.innerText || '').trim().slice(0, 80))
                    .filter(s => s.length > 1);
                return out;
            }""")
            if hp and hp.get("panel_found"):
                result["panel_open"] = True
                if hp.get("source_urls"):
                    seen_h = set(result.get("source_urls") or [])
                    unioned_h = list(result.get("source_urls") or [])
                    for u in hp["source_urls"]:
                        if u not in seen_h:
                            seen_h.add(u); unioned_h.append(u)
                    if len(unioned_h) > result.get("sources", 0):
                        result["source_urls"] = unioned_h[:_SOURCE_LIST_CAP]
                        result["sources"] = len(result["source_urls"])
                if hp.get("steps") and len(hp["steps"]) > len(result.get("steps") or []):
                    result["steps"] = hp["steps"]
                if hp.get("progress"):
                    result["progress"] = hp["progress"]
                if hp.get("sections") and len(hp["sections"]) > len(result.get("sections") or []):
                    result["sections"] = hp["sections"]
        except Exception as _hpe:
            log(f"ChatGPT host-panel scrape skipped: {_hpe}", "DEBUG")

        # ---- #913: inline turn sweep (2026-07 UI) ----
        # The live status line ("Pro thinking" → "Searching the web…")
        # renders inside the last assistant turn, and hostname chips +
        # "N searches/citations" counts appear there too. Sweep it EVERY
        # cycle: this data is scrapeable regardless of whether the Activity
        # side panel is open yet, so P1 narration stays rich from the first
        # poll tick instead of showing "0 sources, 0 chars" until a
        # panel-open succeeds.
        try:
            il = await page.evaluate(_CHATGPT_INLINE_ACTIVITY_JS)
            if il:
                if il.get("status_line") and not result.get("progress"):
                    result["progress"] = il["status_line"]
                if il.get("steps") and len(il["steps"]) > len(result.get("steps") or []):
                    result["steps"] = il["steps"]
                if il.get("source_urls"):
                    seen_il = set(result.get("source_urls") or [])
                    unioned_il = list(result.get("source_urls") or [])
                    for u in il["source_urls"]:
                        if u not in seen_il:
                            seen_il.add(u)
                            unioned_il.append(u)
                    if len(unioned_il) > result.get("sources", 0):
                        result["source_urls"] = unioned_il[:_SOURCE_LIST_CAP]
                        result["sources"] = len(result["source_urls"])
                # ⭐⭐ 2026-08-19 — THE CHIP ROW BELONGS TO THE FINAL RESULT TOO, and
                # leaving it out of this path was the worst thing the review of this
                # wave found. The live walk merges the chips into `progress`, so the
                # FE's activity popup would show eight domains all through the phase
                # and then the EXTRACTED result — the payload the report and the
                # source list are built from — would drop every one of them. Two
                # views of one run disagreeing is exactly the class of bug this wave
                # was opened for.
                #
                # ⛔ GAP-FILL ONLY, both halves. A finished response has rendered its
                # real citation links, and a page URL is strictly better than the
                # domain it lives on: `_merge_host_chips` skips a host already
                # represented, and `_drop_covered_host_placeholders` removes a
                # placeholder that a real page has since covered. So a chip survives
                # here only when nothing better exists — which is the case that made
                # the owner ask for the chips in the first place.
                #
                # ⛔ AND NO PRUNE CALL HERE, deliberately. `_merge_host_chips`
                # refuses a host that is already represented, and nothing else in
                # `result` is chip-derived — this dict is built fresh from the host
                # scrape on every call, so there is no earlier poll for a
                # placeholder to have arrived on. A prune here could not fire, and
                # a guard that cannot fire is the exact defect this whole wave was
                # opened to remove. The live walk DOES need it, because that list
                # accumulates across polls; see `_drop_covered_host_placeholders`.
                if il.get("source_hosts"):
                    _pre_n = len(result.get("source_urls") or [])
                    _merge_host_chips(result, il.get("source_hosts") or [])
                    result["source_urls"] = (result.get("source_urls") or [])[:_SOURCE_LIST_CAP]
                    result["sources"] = len(result["source_urls"])
                    if len(result["source_urls"]) != _pre_n:
                        log(f"[ChatGPT] inline chip row contributed "
                            f"{len(result['source_urls']) - _pre_n} source(s) the "
                            f"panel and the prose did not carry "
                            f"({il.get('chips', 0)} chips seen)", "DEBUG")
                if int(il.get("searches", 0) or 0) > int(result.get("searches", 0) or 0):
                    result["searches"] = int(il.get("searches", 0) or 0)
                if int(il.get("partial_text_len", 0) or 0) > int(result.get("partial_text_len", 0) or 0):
                    result["partial_text_len"] = int(il.get("partial_text_len", 0) or 0)
                if il.get("expanded"):
                    result["panel_open"] = True
                if (il.get("sections")
                        and len(il["sections"]) > len(result.get("sections") or [])):
                    result["sections"] = il["sections"]
        except Exception as _ile:
            log(f"ChatGPT inline activity sweep skipped: {_ile}", "DEBUG")

        # ---- Iframe scrape (Deep Research content lives here as of 2026)
        # 2026-08-06: candidates come from `_chatgpt_surface_frame_targets`. This
        # scrape feeds narration AND `last_growth_len`/`last_growth_sources`,
        # which arm the never-grew veto — so a frame list that misses the real
        # surface can make a working run look like it never produced anything.
        try:
            # ⛔ NARROW ON PURPOSE. This walker does not only read — it
            # CLICKS (the plan-item live row, the Cited-sources expander), and a
            # synthetic click into a surface we have never clicked is how the
            # 2026-08-06 second run acquired a panel failure that took two
            # analyses to argue about. Readers get the wide list; clickers do not.
            for frame in _chatgpt_surface_frame_targets(
                    page, include_blank=False)[1:]:
                try:
                    dr = await frame.evaluate("""() => {
                        const d = {
                            steps: [], source_urls: [], sections: [],
                            partial_text_len: 0, progress: '', thinking: '',
                            is_active: false, is_done: false
                        };
                        // 1. Steps: DR shows an activity/timeline panel
                        const stepEls = document.querySelectorAll(
                            '[class*="step"], [class*="activity"], [class*="timeline"] li, ' +
                            '[data-step], [class*="research-step"], ' +
                            'li[class*="activity"], [role="listitem"]'
                        );
                        d.steps = Array.from(stepEls).map(e => (e.innerText || '').trim().substring(0, 180))
                                                     .filter(s => s.length > 3).slice(-12);
                        // 2. Sources: DR shows a source list — collect http links inside iframe
                        const srcSet = new Set();
                        document.querySelectorAll('a[href^="http"]').forEach(a => {
                            const h = a.href || '';
                            if (h.length < 500 &&
                                !h.includes('chatgpt.com') && !h.includes('openai.com') &&
                                !h.includes('oaiusercontent')) srcSet.add(h);
                        });
                        d.source_urls = Array.from(srcSet).slice(0, 200);
                        // 3. Headings in the DR report
                        const hs = document.querySelectorAll('h1, h2, h3');
                        d.sections = Array.from(hs).map(h => (h.innerText || '').trim().substring(0, 80))
                                                   .filter(s => s.length > 1);
                        // 4. Partial text — use body text as proxy
                        d.partial_text_len = (document.body?.innerText || '').length;
                        // 5. Activity detection inside iframe
                        const bodyLower = (document.body?.innerText || '').toLowerCase();
                        const activeKws = ['researching', 'searching', 'reading', 'analyzing',
                                           'sources found', 'sources and counting', 'browsing'];
                        d.is_active = activeKws.some(kw => bodyLower.includes(kw));
                        // 6. Completion indicators inside iframe
                        const doneKws = ['research completed', 'finished research',
                                         'deep research completed'];
                        d.is_done = doneKws.some(kw => bodyLower.includes(kw));
                        // 7. Latest step as progress
                        if (d.steps.length > 0) d.progress = d.steps[d.steps.length - 1];
                        return d;
                    }""")
                    if dr:
                        # Additive merge: iframe data is rich for DR content,
                        # but host-panel sweep above already collected steps/
                        # sources from the host page side. Last-write-wins
                        # would clobber 12 host-panel rows with 8 iframe rows.
                        if dr.get("partial_text_len", 0) > result.get("partial_text_len", 0):
                            result["partial_text_len"] = dr["partial_text_len"]
                        # Sources: union (preserve order, capped at `_SOURCE_LIST_CAP`)
                        iframe_srcs = dr.get("source_urls") or []
                        if iframe_srcs:
                            seen_i = set(result.get("source_urls") or [])
                            unioned_i = list(result.get("source_urls") or [])
                            for u in iframe_srcs:
                                if u not in seen_i:
                                    seen_i.add(u); unioned_i.append(u)
                            if len(unioned_i) > len(result.get("source_urls") or []):
                                result["source_urls"] = unioned_i[:_SOURCE_LIST_CAP]
                                result["sources"] = len(result["source_urls"])
                        # Steps: union by [:80] dedupe key (keep last 15)
                        if dr.get("steps"):
                            existing_steps = result.get("steps") or []
                            seen_s = set(s[:80] for s in existing_steps)
                            merged_steps = list(existing_steps)
                            for s in dr["steps"]:
                                k = s[:80]
                                if k not in seen_s:
                                    seen_s.add(k); merged_steps.append(s)
                            result["steps"] = merged_steps[-15:]
                            if dr.get("progress"):
                                # 2026-04-29: keep host-panel progress when
                                # present — the host strip's "Focusing on X"
                                # / "224 searches" line is canonical for FE
                                # narration. Only fall through to iframe
                                # progress when host produced nothing.
                                cur = result.get("progress") or ""
                                if not cur:
                                    result["progress"] = dr["progress"]
                        # Sections: union (exact-string dedup since headings)
                        if dr.get("sections"):
                            existing_sec = result.get("sections") or []
                            seen_sec = set(existing_sec)
                            merged_sec = list(existing_sec)
                            for s in dr["sections"]:
                                if s not in seen_sec:
                                    seen_sec.add(s); merged_sec.append(s)
                            if len(merged_sec) > len(existing_sec):
                                result["sections"] = merged_sec
                        # Status override from iframe signals
                        if dr.get("is_active"):
                            result["dr_active"] = True
                        if dr.get("is_done"):
                            result["dr_done_text"] = True
                except Exception as _ie:
                    log(f"ChatGPT DR iframe evaluate skipped: {_ie}", "DEBUG")
                # ── Actively expand the "Cited sources" panel ──
                # ChatGPT DR collapses the sources list by default — the
                # `<a href>` nodes inside it are NOT rendered until the
                # user clicks the panel. The default scrape above misses
                # those links and undercounts sources (often 0–3 instead
                # of 10–20). On by default — opt out via
                # DG_SOURCE_PANEL_EXPAND=0/false/no. Wrapped in try/except
                # so any failure silently keeps the partial result we
                # already collected.
                if os.environ.get("DG_SOURCE_PANEL_EXPAND", "1").lower() not in ("0", "false", "no"):
                    try:
                        click_res = await frame.evaluate("""() => {
                            const candidates = document.querySelectorAll('button, [role="button"]');
                            for (const b of candidates) {
                                const t = (b.textContent || '').trim().toLowerCase();
                                const al = (b.getAttribute('aria-label') || '').toLowerCase();
                                const isSourcesLabel =
                                    t === 'sources' || t === 'cited sources' ||
                                    /^\\d+\\s+sources?$/.test(t) ||
                                    al.includes('cited source') || al === 'sources';
                                if (!isSourcesLabel) continue;
                                const expanded = b.getAttribute('aria-expanded');
                                if (expanded === 'true') {
                                    return { clicked: false, alreadyExpanded: true, label: t || al };
                                }
                                b.click();
                                return { clicked: true, label: t || al };
                            }
                            return { clicked: false, found: false };
                        }""")
                        if click_res and click_res.get("clicked"):
                            # Lazy render needs a beat. 1.0s is generous —
                            # the list either appears immediately or the
                            # panel was already populated.
                            await asyncio.sleep(1.0)
                            try:
                                dr2 = await frame.evaluate("""() => {
                                    const srcSet = new Set();
                                    document.querySelectorAll('a[href^="http"]').forEach(a => {
                                        const h = a.href || '';
                                        if (h.length < 500 &&
                                            !h.includes('chatgpt.com') && !h.includes('openai.com') &&
                                            !h.includes('oaiusercontent')) srcSet.add(h);
                                    });
                                    return { source_urls: Array.from(srcSet).slice(0, 200) };
                                }""")
                                if dr2 and dr2.get("source_urls"):
                                    # Union (preserve order) instead of replace —
                                    # the panel may render different URLs than the
                                    # pre-click DOM scrape (different ordering or
                                    # subset). Strict `>` would skip cases where
                                    # post-click count ties pre-click but the URLs
                                    # are objectively different.
                                    seen_u = set(result.get("source_urls") or [])
                                    unioned = list(result.get("source_urls") or [])
                                    for u in dr2["source_urls"]:
                                        if u not in seen_u:
                                            seen_u.add(u)
                                            unioned.append(u)
                                    if len(unioned) > result.get("sources", 0):
                                        result["source_urls"] = unioned[:_SOURCE_LIST_CAP]
                                        result["sources"] = len(result["source_urls"])
                            except Exception as _re2:
                                log(f"ChatGPT sources-panel re-scrape skipped: {_re2}", "DEBUG")
                    except Exception as _se:
                        log(f"ChatGPT sources-panel expand skipped: {_se}", "DEBUG")
                # ── 2026-04-26 (v2): plan-checklist DOM walker + live-row click ──
                # ChatGPT DR's plan checklist uses Tailwind <div>s (not role=checkbox /
                # data-testid=task / bare <li>) so the v1 selectors missed iteration 1.
                # v2: walk the checklist via verb-prefix + svg[class*=check|spin] heuristic,
                # populate result.steps[] (full plan list, last 15) and result.progress
                # (active-row label) directly. Click the live row IF NOT already
                # aria-expanded, then re-scrape URLs scoped to the expanded subtree
                # (no global host-page sweep). Opt out via DG_PLAN_ITEM_EXPAND=0.
                if os.environ.get("DG_PLAN_ITEM_EXPAND", "1").lower() not in ("0", "false", "no"):
                    try:
                        walk = await frame.evaluate("""() => {
                            const out = { steps: [], live_label: '', clicked: false, already_expanded: false };
                            const VERB = /^(thinking|reasoning|searching|looking|browsing|investigating|analyzing|reading|exploring|checking|visiting|researching|confirming|summari[zs]ing|synthesi[zs]ing|drafting|finali[zs]ing)\\b/i;
                            const all = Array.from(document.querySelectorAll('div, li, [role="listitem"], button, [role="button"]'));
                            const rows = [];
                            for (const el of all) {
                                const t = (el.innerText || '').trim();
                                if (!t || t.length < 4 || t.length > 220) continue;
                                const hasCheck = !!el.querySelector('svg[class*="check"], svg[data-icon*="check"]');
                                const hasSpin  = !!el.querySelector('svg[class*="spin"], svg[class*="loader"], [class*="animate-spin"]');
                                const verbHit  = VERB.test(t);
                                if (!verbHit && !hasCheck && !hasSpin) continue;
                                const key = t.slice(0, 60);
                                if (rows.find(r => r.key === key)) continue;
                                rows.push({ el, t, hasCheck, hasSpin, verbHit, key });
                            }
                            out.steps = rows.map(r => r.t.slice(0, 200)).slice(-15);
                            const live = rows.find(r => r.hasSpin) ||
                                         rows.find(r => r.verbHit && !r.hasCheck);
                            if (live) {
                                out.live_label = live.t.slice(0, 160);
                                const expanded = live.el.getAttribute('aria-expanded');
                                if (expanded === 'true') {
                                    out.already_expanded = true;
                                } else {
                                    live.el.click();
                                    out.clicked = true;
                                }
                            }
                            return out;
                        }""")
                        if walk:
                            # Additive: union plan-item steps with whatever
                            # the iframe walker + host-panel sweep already
                            # collected. live_label is the active row, so
                            # it typically wins for `progress` but only if
                            # richer than what's there.
                            if walk.get("steps"):
                                existing_steps = result.get("steps") or []
                                seen_s = set(s[:80] for s in existing_steps)
                                merged_steps = list(existing_steps)
                                for s in walk["steps"]:
                                    k = s[:80]
                                    if k not in seen_s:
                                        seen_s.add(k); merged_steps.append(s)
                                result["steps"] = merged_steps[-15:]
                            if walk.get("live_label"):
                                cur = result.get("progress") or ""
                                if not cur or len(walk["live_label"]) > len(cur) * 0.5:
                                    result["progress"] = walk["live_label"]
                            if walk.get("clicked"):
                                log(f'[ChatGPT] plan-item live-row clicked: "{walk.get("live_label","")}"')
                                await asyncio.sleep(1.0)
                            if walk.get("clicked") or walk.get("already_expanded"):
                                try:
                                    dr3 = await frame.evaluate("""() => {
                                        const expanded = document.querySelector('[aria-expanded="true"]');
                                        const root = expanded || document;
                                        const srcSet = new Set();
                                        root.querySelectorAll('a[href^="http"]').forEach(a => {
                                            const h = a.href || '';
                                            if (h.length < 500 &&
                                                !h.includes('chatgpt.com') && !h.includes('openai.com') &&
                                                !h.includes('oaiusercontent')) srcSet.add(h);
                                        });
                                        return { source_urls: Array.from(srcSet).slice(0, 200) };
                                    }""")
                                    if dr3 and dr3.get("source_urls"):
                                        seen3 = set(result.get("source_urls") or [])
                                        unioned3 = list(result.get("source_urls") or [])
                                        for u in dr3["source_urls"]:
                                            if u not in seen3:
                                                seen3.add(u)
                                                unioned3.append(u)
                                        if len(unioned3) > len(result.get("source_urls") or []):
                                            result["source_urls"] = unioned3[:_SOURCE_LIST_CAP]
                                            result["sources"] = len(result["source_urls"])
                                except Exception as _re3:
                                    log(f"ChatGPT plan-item re-scrape skipped: {_re3}", "DEBUG")
                    except Exception as _pe:
                        log(f"ChatGPT plan-item walker skipped: {_pe}", "DEBUG")
                # ⛔ NO `break`. It used to end this body, inside the URL
                # substring `if`, stopping at the FIRST matching frame — which on
                # 2026-08-06 was the connector shell, an empty document, while
                # the surface sat in the `about:blank` frame behind it. Every
                # merge in this body is a max-or-union (see the "last-write-wins
                # would clobber" note above), so visiting all candidates cannot
                # lose what an earlier one found.
        except Exception as _fe:
            log(f"ChatGPT frames iteration skipped: {_fe}", "DEBUG")

        # ---- Synthesize steps if iframe didn't provide any
        if not result.get("steps"):
            synth = []
            if result.get("thinking"):
                synth.append("Thinking: " + result["thinking"][:100])
            hosts = set()
            for u in result.get("source_urls", []):
                try:
                    from urllib.parse import urlparse
                    h = urlparse(u).hostname or ""
                    if h.startswith("www."):
                        h = h[4:]
                    if h:
                        hosts.add(h)
                except Exception:
                    pass
            for h in list(hosts)[:5]:
                synth.append(f"Researching {h}")
            if result.get("sections"):
                synth.append(f"Writing: {result['sections'][-1]}")
            if result.get("partial_text_len", 0) > 3000:
                synth.append(f"Generating brief: {round(result['partial_text_len']/1000)}k chars")
            result["steps"] = synth

        if result.get("steps") and not result.get("progress"):
            result["progress"] = result["steps"][-1]

        # Plan line (sections as outline)
        if len(result.get("sections", [])) >= 2 and not result.get("plan"):
            result["plan"] = "Research outline: " + " \u2192 ".join(result["sections"][:5])

        # ---- Final status resolution
        has_stop = result.pop("has_stop_btn", False)
        dr_active = result.pop("dr_active", False)
        dr_done_text = result.pop("dr_done_text", False)
        partial = result.get("partial_text_len", 0)
        if has_stop or dr_active:
            result["status"] = "generating"
            result["phase"] = "deep_research" if dr_active else "researching"
            if not result.get("progress"):
                result["progress"] = "Deep Research in progress"
        elif dr_done_text and partial > 100:
            result["status"] = "complete"
            result["phase"] = "done"
        elif partial > 100:
            # Partial content but no active/done signal — call it complete (historical behavior)
            result["status"] = "complete"
            result["phase"] = "done"
        else:
            result["status"] = "idle"
            result["phase"] = "waiting"

        return result
    except Exception as e:
        log(f"ChatGPT scrape failed (selectors may need update): {e}", "WARN")
        return {"status": "scrape_error", "progress": "Selector mismatch — ChatGPT UI may have changed", "sources": 0, "partial_text_len": 0}


# ── #913 (2026-07-07): ChatGPT 2026-07 UI redesign — shape-agnostic activity ──
# The activity/thinking affordance is the SHIMMERING STATUS LINE rendered
# directly below the last sent (user) message. GROUND TRUTH (user screenshot,
# 2026-07-07): clicking it opens a right-side panel headed "Activity · <N>s"
# (× close, "Answer now" link) in P1 Pro/ET; P2 Deep Research slides out the
# "Deep research execution plan" panel (CUA confirmed live 2026-07-06 21:59).
# Four live runs (2026-07-06) had DOM + CUA clicks judged "failed" because
# the verifier's gates rejected the OPEN Activity panel — it is NARROW
# (~21% of viewport ≈ 267px at 1280, gate demanded ≥280) and nearly EMPTY
# early (skeleton rows ≈ 33 chars, gate demanded ≥50) — so the poll
# re-clicked the line every ~30s, TOGGLING the panel closed. Additionally
# the DR card now renders in an iframe whose URL no longer matches the old
# "deep_research|oaiusercontent" filter (walked_hits=0 across ALL P2 cycles
# while CUA could see the strip) — frame loops must enumerate every frame.
# The inline-turn sweep below is (a) the per-cycle narration source (status
# line + counts are scrapeable in the turn regardless of panel state) and
# (b) a defensive secondary "open" shape for future UI variants.
# ⭐⭐ ONE DEFINITION OF "SHIMMERING", spliced into the three walkers that ask.
# A shimmer is an animated gradient MASKED TO THE GLYPHS, and both halves are
# required: the animation alone also describes the "Pro" badge (every panel-miss
# snapshot of the 19 August run recorded it anim/animKid true, clip FALSE), while
# the gradient alone survives on a FINISHED step that kept its class, which is the
# 2026-08-18 defect that put `background-clip` inside `shimmers()` in the first
# place.
#
# ⛔⛔ IT IS ONE CONSTANT BECAUSE DUPLICATES HIDE MUTANTS. There were two copies,
# and a mutation survivor proved the hazard exactly: stripping the check out of the
# PICKER still passed, because the SNAPSHOT's copy kept the asserted string alive
# in the file. `test_p1_panel_precedence_0818` was written to close that by
# counting the copies and checking each — a guard that has to be re-counted every
# time a fourth walker needs the predicate, and this wave was the third. One
# definition makes the count 1 and the hiding place gone.
#
# ⚠ The three call sites sat at three indentation depths. JS does not care, and
# nothing may depend on it — the picker and the snapshot were verified
# whitespace-identical to their previous copies after this was extracted.
_CHATGPT_SHIMMER_JS_HELPERS = """
    const shimmers = (n) => {
        try {
            const cs = getComputedStyle(n);
            return !!cs.animationName && cs.animationName !== 'none'
                && cs.animationPlayState !== 'paused';
        } catch (e) { return false; }
    };
    const clipped = (n) => {
        try {
            const cs = getComputedStyle(n);
            return cs.webkitBackgroundClip === 'text'
                || cs.backgroundClip === 'text';
        } catch (e) { return false; }
    };
"""


_CHATGPT_INLINE_ACTIVITY_JS = """() => {
    // Scope: the LAST assistant turn. The status row + drawer render inside
    // the <article> turn wrapper but OUTSIDE [data-message-author-role], so
    // prefer the article; fall back to the role node's parent.
    const main = document.querySelector('main') || document.body;
    const arts = main.querySelectorAll('article');
    let turn = arts.length ? arts[arts.length - 1] : null;
    let scope = turn ? 'article' : '';
    if (!turn) {
        const asst = main.querySelectorAll('[data-message-author-role="assistant"]');
        turn = asst.length ? (asst[asst.length - 1].parentElement
                              || asst[asst.length - 1]) : null;
        if (turn) scope = 'role-parent';
    }
    // ⛔⛔ 2026-08-20 — AND THE CONTAINER THE CHIPS ARE ACTUALLY IN. Neither arm
    // above accepts `[data-testid^="conversation-turn"]`, so on a page whose turn
    // is a SECTION with that testid and no assistant-role element this walker
    // returned NULL and the caller read zero chips — while eight hostnames sat on
    // screen. Measured in the 08-20 e2e, one second apart, from two probes on the
    // same page:
    //     21:46:35  miss #2 … chips 0->0
    //     21:46:35  snapshot rows: docs.nvidia.com, hermes-agent.org,
    //               developer.nvidia.com, github.com, www.nvidia.com,
    //               build.nvidia.com, www.lasso.security, "16 more"
    // Every one of those rows reported `inTurn: true` — which is THIS selector.
    // So the opener and the reader disagreed about what a turn is, and only the
    // reader's answer could stop the chips reaching the app.
    //
    // ⭐ LAST, not first. `article` has the success record and is left to answer
    // ahead of this; the new arm only picks up pages the old two abandoned.
    // ⭐ And it skips a turn holding the USER's own message: this testid is on
    // user turns too, so on a page where the assistant's turn has not rendered
    // yet the last match would be the brief we pasted.
    if (!turn) {
        try {
            const secs = main.querySelectorAll('[data-testid^="conversation-turn"]');
            for (let i = secs.length - 1; i >= 0; i--) {
                if (secs[i].querySelector('[data-message-author-role="user"]')) continue;
                turn = secs[i];
                scope = 'turn-testid';
                break;
            }
        } catch (e) {}
    }
    if (!turn) return null;
    // ⛔⛔ 2026-08-19 — THE ARTICLE SCOPE IS NOT ALWAYS THERE, AND THE WALK DIED
    // SILENTLY WHEN IT WASN'T. The 19 August P1 phase ran 13.7 minutes and logged
    // ZERO `panel tracking (P1)` lines — the raw-activity popup the owner reported
    // as empty. The panel-miss snapshots of that phase say why the article scope
    // is not trustworthy: the very status line this walker exists to read was
    // recorded with `inTurn: false` at 02:56:08 and 02:58:15 (its own
    // `closest('[data-testid^="conversation-turn"], [data-message-author-role=
    // "assistant"]')` came back null), and `inTurn: true` only from 03:00:06.
    // So for the first minutes of a response the live line is NOT inside the
    // last article, `arts[last]` is the USER's turn, and everything below is
    // scanned in the wrong subtree.
    //
    // The geometry the snapshot and the opener walker BOTH already use is the
    // reliable scope: whatever sits below the bottom of the last user message.
    // Recorded here as a bound rather than a container, and applied ADDITIVELY —
    // the article scope stays primary, so P2 (whose side panel and strip parse
    // correctly today) is untouched; the geometric pass only runs when the
    // article scope found nothing, which is exactly the case that was dying.
    let lub = -1;
    try {
        main.querySelectorAll('[data-message-author-role="user"]').forEach(u => {
            const r = u.getBoundingClientRect();
            if (r.bottom > lub) lub = r.bottom;
        });
    } catch (e) {}
    const out = { steps: [], source_urls: [], sections: [], searches: 0,
                  partial_text_len: 0, progress: '', status_line: '',
                  expanded: false,
                  // The inline chip row: hostnames only, plus how many. See the
                  // chip block below for why this is a SEPARATE fact from
                  // `expanded` rather than folded into it.
                  source_hosts: [], chips: 0, chip_row: false,
                  // ⭐ Instrumented because "the walk produced nothing" was
                  // indistinguishable from "there was nothing to produce" for a
                  // whole phase. Cheap: counters already computed by the scan.
                  dbg: { scope: scope, lub: Math.round(lub), turnTag: '',
                         cands: 0, chipsProse: 0, statusFrom: '' } };
    out.dbg.turnTag = (turn.tagName || '') + '|'
                      + String(turn.className || '').split(/\\s+/)[0].slice(0, 24);
    const turnText = (turn.innerText || '').trim();
    out.partial_text_len = turnText.length;
    // Inline-expansion state — SECONDARY shape (ground truth 2026-07-07:
    // P1's click opens the "Activity" SIDE panel; this only covers modes
    // that expand in-turn). Deliberately strict: a mounted thoughts/
    // activity region with real height AND readable text. No bare
    // aria-expanded=true shortcut — a stray expanded chip inside the turn
    // would report "open", block the click, and starve the real panel
    // forever. The ≥40-char text floor exists for P2: the DR card is an
    // iframe embed (its text is invisible to the host), so an "activity"-
    // classed host container around it must NOT count as expanded.
    //
    // ⛔⛔ 2026-08-19 — THIS DID NOT FIRE ONCE, AND IT IS WHY WE SPENT FOUR
    // MINUTES CLOSING THE DRAWER WE HAD OPENED. P1's 2026-08 UI has no side
    // panel at all: the live line expands an inline row of hostname chips whose
    // container is `class="flex"` and whose text is a domain of a few
    // characters. Every gate here refuses that — ≥60px tall, ≥120px wide,
    // ≥40 chars, and a class/testid naming "thought" or "activity" — so
    // `inline_expanded` was false against an already-open drawer, and the
    // callers read that as "closed":
    //   02:59:01 CUA opens the chip row · 02:59:32 "activity drawer collapsed
    //   — will re-open" · then eight clicks to 03:03:22, each a TOGGLE.
    // CUA watched us do it: "The click caused the website chips/badges below
    // the 'Searched 20 websites' line to collapse/hide" (03:06:40) and "the
    // second click just re-expanded the website chips dropdown again"
    // (03:07:05). That is #913's toggle storm exactly, defeated by a verifier
    // that cannot see the shape it is verifying.
    //
    // ⛔ IT IS NOT REPAIRED BY LOOSENING THESE GATES, and that matters: this
    // predicate is shared with P2, whose panel DOES parse today (03:12:42,
    // shape=side, 5 URLs), and whose iframe-embedded DR card is the reason for
    // the 40-char floor. Loosening it here would let P2 latch "already open"
    // on any small in-turn node and never click its strip — the 2026-08-06
    // failure that cost a whole phase. So the chip row is recorded BELOW as its
    // own fact, and only the P1 call sites treat it as open. `expanded` keeps
    // its strict meaning for a genuine in-turn thoughts region.
    for (const el of turn.querySelectorAll(
            '[class*="thought" i], [class*="activity" i], [data-testid*="thought" i]')) {
        const r = el.getBoundingClientRect();
        if (r.height < 60 || r.width < 120) continue;
        if (((el.innerText || '').trim()).length < 40) continue;
        out.expanded = true; break;
    }
    // Live status line — anchored on structure/wording, closest below the
    // last user message. Same anchor family as the opener walker.
    // ⭐ 2026-08-19: `websites?` and `sites?` added. The 19 August P1 line read
    // "Searched 20 websites" — measured, both in the opener's own label at
    // 02:55:35 and in the owner's screenshot at 03:03 — and this alternation had
    // neither word, while the aggregate-count regex forty lines below has had
    // both since it shipped. So the walker's own two counters disagreed about
    // what a count looks like, and the status line came back EMPTY for the whole
    // search phase. `progress` then fell through to the last activity row, which
    // by then was a bare hostname chip: the narration line the owner saw was
    // "www.penligent.ai" where the page said "Searched 20 websites".
    const COUNT = /\\b\\d+\\s+(?:websites?|sites?|searches?|sources?|results?|citations?)\\b/i;
    const STATUS_LINE = /^(?:[\\w.+-]{1,12}\\s+)?(?:thinking|reasoning|researching)\\b/i;
    const VERB = /^(?:checking|searching|looking|browsing|investigating|analyzing|reading|exploring|visiting|researching|thinking|reasoning|gathering|reviewing|consulting|comparing|evaluating|considering|drafting|writing|finalizing|finalising|summari[zs]ing|confirming|synthesi[zs]ing|thought)\\b/i;
    // ⛔ 2026-08-19 — KEPT, AND DEMOTED FROM AN INVARIANT TO ONE TERM AMONG
    // SEVERAL. The 2026-05-03 note in the opener walker calls the trailing
    // ellipsis a structural anchor that "always" holds while a run streams.
    // It holds for P2 — that run's DR strip opened off the label "Researching..."
    // at 03:12:42 — and it is simply false for P1's 2026-08 UI, where not one
    // label of a 13-minute phase ended in dots ("Mapped security coverage",
    // "Compared security layers", "Searching the web", "Searched 20 websites").
    // Deleting it would take P2's working anchor with it; relying on it alone is
    // what left P1 with no status line. Hence the SHIMMER term below.
    const ELLIPSIS = /(?:\\.{3}|\\u2026)\\s*$/;
    const HOSTCHIP = /^[a-z0-9][a-z0-9.-]{2,60}\\.[a-z]{2,10}$/i;
    // ⭐⭐ THE WORDING-FREE ANCHOR, and it must be the SAME SPLIT the opener and
    // the panel-miss snapshot use, or the three would disagree about the same
    // row. An animated gradient masked to the glyphs is what "shimmering" IS,
    // and the owner's instruction for this fix was exactly that: no hardcoded
    // labels, just open the shimmering line. Both terms are required —
    // `animKid` alone also matched the "Pro" badge in every snapshot of the
    // 19 August run (anim:false, animKid:true, clip:FALSE), and the status line
    // was clip:true in all four.
""" + _CHATGPT_SHIMMER_JS_HELPERS + """
    const shimmerLine = (el) => {
        let anim = shimmers(el), clip = clipped(el);
        if (anim && clip) return true;
        try {
            for (const kid of el.querySelectorAll('*')) {
                if (!anim && shimmers(kid)) anim = true;
                if (!clip && clipped(kid)) clip = true;
                if (anim && clip) return true;
            }
        } catch (e) {}
        return false;
    };
    let statusTop = Infinity;
    const seenStep = new Set();
    // The chip row, keyed by hostname so a re-render cannot double-count it.
    const chipTop = new Map();
    const proseChips = new Set();
    let lastVerbStep = '';
    // ⛔ The article scope is primary; the geometric pass below the last user
    // message runs ONLY when it yielded nothing. See the scope note at the top:
    // additive, so P2's working parse is untouched.
    let nodes;
    try { nodes = turn.querySelectorAll('*'); } catch (e) { nodes = []; }
    if (nodes.length > 8000) nodes = [];
    const scanNodes = (list, inGeo) => {
      for (const el of list) {
        if (el.children.length > 3) continue;
        const t = (el.innerText || '').trim();
        if (!t || t.length < 4 || t.length > 300) continue;
        if ((t.match(/\\n/g) || []).length > 3) continue;
        const r = el.getBoundingClientRect();
        if (r.width === 0 || r.height === 0) continue;
        // The geometric pass bounds itself the way the snapshot does: at or
        // below the last user message, and not so far below that the composer
        // and the footer disclaimer come along.
        if (inGeo && lub > 0 && (r.top < lub - 8 || r.top > lub + 900)) continue;
        out.dbg.cands += 1;
        // ⚠ ONE `if` LADDER RATHER THAN AN `||` CHAIN, for two reasons that both
        // bit the first draft. (a) `shimmerLine` walks the subtree calling
        // getComputedStyle on every descendant, and in an `||` chain it ran for
        // nearly every candidate — hundreds of style resolutions per poll — when
        // the answer can only matter for a row ABOVE the best one so far, so the
        // `r.top < statusTop` guard belongs BEFORE the call, not after it. (b) the
        // diagnostic has to name the term that actually fired: derived afterwards
        // it labelled a line matching both ELLIPSIS and COUNT as 'count' while
        // ELLIPSIS was what accepted it, and a >160-char COUNT line as 'count'
        // when the shimmer had carried it. A diagnostic that misattributes is
        // worse than none, because it is the thing the next reader trusts.
        let from = '';
        if (STATUS_LINE.test(t) && t.length <= 60) from = 'word';
        else if (ELLIPSIS.test(t) && t.length >= 8 && t.length <= 240) from = 'ellipsis';
        else if (COUNT.test(t) && t.length <= 160) from = 'count';
        else if (t.length <= 240 && r.top < statusTop && shimmerLine(el)) from = 'shimmer';
        if (from && r.top < statusTop) {
            statusTop = r.top;
            out.status_line = t.slice(0, 200);
            out.dbg.statusFrom = from;
        }
        // Activity rows: verb-prefixed leaves + hostname chips. Exclude the
        // response prose (.markdown) unless verb-gated — the drawer rows
        // render OUTSIDE the markdown body.
        const inProse = !!(el.closest && el.closest('.markdown'));
        const isChip = HOSTCHIP.test(t);
        // ⭐⭐ THE CHIP ROW — measured, not guessed. The panel-miss snapshot of
        // 03:00:06 recorded the whole thing: eight DIVs, `class="flex"`,
        // `inTurn: true`, `anim: false`, text a bare hostname, laid out on two
        // rows at y=278 and y=307 under a status line at y=242, plus a "13 more"
        // affordance that is not a hostname and so is not counted. Structure
        // only — no label, no class, no testid — because the shimmer label is
        // topic-specific and this row is the one thing about the expanded state
        // that is not.
        if (isChip && !inProse) {
            const host = t.toLowerCase();
            if (!chipTop.has(host)) chipTop.set(host, Math.round(r.top));
        }
        if ((VERB.test(t) && t.length >= 8) || (isChip && !inProse)) {
            if (inProse && !VERB.test(t)) continue;
            const k = t.slice(0, 80);
            if (!seenStep.has(k)) {
                seenStep.add(k);
                out.steps.push(t.slice(0, 220));
                // Tracked separately so `progress` can prefer a real activity
                // sentence over a hostname when no status line was found.
                if (VERB.test(t)) lastVerbStep = t.slice(0, 220);
            }
        } else if (isChip && inProse) {
            // ⚠ A SET, not a counter. Both the article pass and the geometric
            // pass can see the same citation, and an anchor and its own text
            // node are two elements naming one host — a raw ++ reported 6 for
            // three citations, which is the kind of diagnostic that sends the
            // next reader hunting a duplication that does not exist. Distinct
            // hostnames refused for being prose is also the more useful number.
            proseChips.add(t.toLowerCase());
        }
      }
    };
    scanNodes(nodes, false);
    if (!out.status_line && !chipTop.size && !out.steps.length && lub > 0) {
        let geo;
        try { geo = main.querySelectorAll('*'); } catch (e) { geo = []; }
        if (geo.length && geo.length <= 8000) {
            out.dbg.scope = scope + '+geo';
            scanNodes(geo, true);
        }
    }
    out.dbg.chipsProse = proseChips.size;
    // ⚠ The LIST is capped; the COUNT is not. Reporting the post-cap length would
    // make a 70-chip row read as 60, and this number is the one the log carries
    // and the one the callers latch on.
    out.source_hosts = [...chipTop.keys()].slice(0, 60);
    out.chips = chipTop.size;
    // ⛔ TWO, not one. A single hostname appears in ordinary prose and in a
    // collapsed one-source citation; a ROW is the shape that only the expanded
    // drawer has, and two is the smallest thing that can be a row.
    out.chip_row = out.chips >= 2;
    out.steps = out.steps.slice(-15);
    // Source links inside the turn — unwrap the chatgpt.com redirector.
    const seenUrl = new Set();
    turn.querySelectorAll('a[href^="http"]').forEach(a => {
        let h = a.href || '';
        if (!h || h.length >= 500) return;
        try {
            if (h.includes('chatgpt.com/') && h.includes('url=')) {
                const u = new URL(h);
                const real = u.searchParams.get('url');
                if (real && real.startsWith('http')) h = decodeURIComponent(real);
            }
        } catch (e) {}
        if (h.includes('chatgpt.com') || h.includes('openai.com') ||
            h.includes('oaiusercontent') || h.includes('chat.openai')) return;
        if (seenUrl.has(h)) return;
        seenUrl.add(h);
        out.source_urls.push(h);
    });
    out.source_urls = out.source_urls.slice(0, 200);
    // Aggregate counts — max wins so transient lower reads don't shrink.
    try {
        const re = /(\\d+)\\s+(?:websites?|sources?|searches?|sites?|results?|citations?)\\b/gi;
        let mm; let best = 0;
        while ((mm = re.exec(turnText)) !== null) {
            const n = parseInt(mm[1], 10) || 0;
            if (n > best) best = n;
        }
        out.searches = best;
    } catch (e) {}
    turn.querySelectorAll('h1, h2, h3').forEach(h => {
        const t = (h.innerText || '').trim();
        if (t && t.length > 1 && t.length < 120) out.sections.push(t);
    });
    out.sections = out.sections.slice(0, 20);
    // ⛔ 2026-08-19 — A HOSTNAME IS NOT A PROGRESS SENTENCE. This read the LAST
    // step, and once the chip row rendered the last step was a domain, so the
    // narration line became "www.penligent.ai". Prefer the status line, then the
    // newest verb row, and only then whatever the newest row is — every term is
    // a measurement, the order is which one a reader would rather be shown.
    const lastStep = out.steps.length ? out.steps[out.steps.length - 1] : '';
    out.progress = out.status_line || lastVerbStep || lastStep;
    return out;
}"""

# Right-hand side panel presence (bool) — evaluated on the host page AND in
# every frame (the DR iframe's URL no longer matches any fixed substring).
#
# #913 ground truth (user screenshot 2026-07-07, P1 live): clicking the
# "Pro thinking" shimmer opens a right-side panel headed "Activity · <N>s"
# with an × close button and an "Answer now" link. Two gates in the old
# heuristic rejected that OPEN panel and caused the re-click toggle storm:
#   - width ≥ 280: the Activity panel is ~21% of the viewport ≈ 267px at
#     our 1280px automation viewport;
#   - text ≥ 50 chars: early on it shows only skeleton/placeholder rows —
#     "Activity · 8s / Pro thinking / Answer now" ≈ 33 chars.
# Signature A below matches the measured panel directly; the legacy
# selector sweep keeps a relaxed width gate + the text gate (it has no
# header anchor, so the text floor still guards against random asides).
_CHATGPT_SIDE_PANEL_JS = """() => {
    // ⭐⭐ 2026-08-06 (run 2) — THE PANEL THAT WAS NEVER OPENED. This probe is the
    // anti-toggle PRE-CHECK: when it says "open", the poller latches
    // `chatgpt_activity_panel_open` and never calls the opener again for the
    // whole phase. On the 21:00 run it said open on its very first P2 sample and
    // the sources panel was consequently never clicked:
    //   [21:17:30] activity already open (shape=side) at elapsed=204s — no click needed
    //   [21:17:31] panel tracking (shape=side): 0 URLs, 0 steps, 1 sections, searches=0
    //   ...and 0/0/0 on every sample to the end of the phase. ChatGPT finished
    //   with sources=0.
    // The node the reader landed on one second later was
    //   DIV|flex w-full flex-col gap-1 empty:hidden items-end rtl:items-start
    // — a right-aligned USER TURN wrapper. `items-end` is why it sits in the
    // right half and passes the geometry, and nothing here asked whether a
    // conversation turn can be an activity panel.
    //
    // ⚠ WHICH element and WHICH context actually satisfied it on that run is NOT
    // established, and cannot be: this returned a bare boolean and logged
    // nothing, while the opener's success line has printed clickedTag + frameUrl
    // since #913. That asymmetry is half the defect. It now returns IDENTITY, so
    // the next occurrence is one grep instead of an argument.
    const isTurn = (n) => {
        // A conversation turn is never the activity panel. Cheap, absolute, and
        // it is the arm that would have refused the observed node.
        try {
            return !!(n.closest('[data-message-author-role], [data-testid^="conversation-turn"], article')
                      || n.querySelector('[data-message-author-role]'));
        } catch (e) { return false; }
    };
    const ident = (n, why) => ({
        why: why,
        tag: (n.tagName || '') + (n.getAttribute('role') ? '[' + n.getAttribute('role') + ']' : ''),
        cls: (n.getAttribute('class') || '').slice(0, 80),
        // How many external links the candidate holds. The real panel is a list
        // of sources; a chrome element is not. Reported, not gated — a freshly
        // opened panel is legitimately empty, and gating here would restart the
        // toggle storm #913 exists to prevent.
        anchors: n.querySelectorAll('a[href^="http"]').length,
        rows: n.querySelectorAll('li').length,
        len: ((n.innerText || '').trim()).length,
    });
    // Signature A — header-anchored right-side panel: "Activity · Ns"
    // (P1 Pro/ET, user screenshot 2026-07-07) or "Deep research execution
    // plan" (P2 DR, CUA transcript 2026-07-06 21:59). Header text anchors
    // the match, so no text-length floor: a skeleton-only panel is still
    // OPEN (a freshly-opened DR panel is sparse too, and bouncing it
    // through the legacy 50-char gate would restart the toggle storm).
    try {
        for (const el of document.querySelectorAll('*')) {
            const t = (el.innerText || '').trim();
            if (!t || !/^(?:activity|deep research)\\b/i.test(t)) continue;
            if (t.length > 40) continue;              // header leaf, not a container
            const hr = el.getBoundingClientRect();
            if (hr.width === 0 || hr.height === 0) continue;
            if (hr.left < window.innerWidth * 0.5) continue;  // right half only
            // Climb to a panel-sized ancestor.
            let node = el;
            for (let i = 0; i < 8 && node; i++) {
                const r = node.getBoundingClientRect();
                if (r.width >= 200 && r.width <= window.innerWidth * 0.6
                        && r.height >= 150
                        && r.right > window.innerWidth * 0.55) {
                    if (!node.querySelector('#prompt-textarea, form textarea, [data-testid*="composer" i]')
                            && !isTurn(node)) {
                        return ident(node, 'sigA:' + t.slice(0, 30));
                    }
                }
                node = node.parentElement;
            }
        }
    } catch (e) {}
    // Signature B — legacy selector sweep (P2 DR execution-plan panel etc.).
    const sels = [
        'aside', '[role="complementary"]', '[role="region"]',
        '[aria-label*="source" i]', '[aria-label*="activity" i]',
        '[aria-label*="research" i]',
        '[class*="panel" i][class*="side" i]',
        '[class*="research" i][class*="panel" i]'
    ];
    for (const sel of sels) {
        try {
            for (const el of document.querySelectorAll(sel)) {
                const r = el.getBoundingClientRect();
                if (r.width < 240 || r.height < 200) continue;
                if (r.right < window.innerWidth * 0.55) continue;
                const inner = (el.innerText || '').trim();
                if (inner.length < 50) continue;
                if (el.querySelector('#prompt-textarea, form textarea, [data-testid*="composer" i]')) continue;
                if (isTurn(el)) continue;
                return ident(el, 'sigB:' + sel);
            }
        } catch (e) {}
    }
    return null;
}"""


async def _chatgpt_activity_state(page):
    """#913: shape-agnostic ChatGPT activity state — what is open RIGHT NOW.

    Returns {side_panel, inline_expanded, thread_len}. `side_panel` covers
    BOTH real shapes seen live: P1's narrow "Activity · Ns" panel and P2
    DR's execution-plan panel (checked on the host page AND in every frame —
    the DR iframe's URL is no longer matchable). `inline_expanded` is a
    defensive secondary for in-turn expansions. Callers use this BEFORE
    clicking (never click when a shape is already open — the status line is
    a TOGGLE, and blind re-clicks close it) and AFTER clicking (either
    shape counts as verified open)."""
    out = {"side_panel": False, "inline_expanded": False, "thread_len": 0,
           # 2026-08-06: WHAT satisfied it, and WHERE. The pre-check used to
           # return a bare boolean and log nothing, so a false positive that
           # cost a whole phase could not be diagnosed from any log — while the
           # opener it suppresses has printed clickedTag + frameUrl since #913.
           "side_panel_id": None, "side_panel_ctx": "",
           # 2026-08-19: the P1 inline chip row, reported as a FACT and never
           # folded into `inline_expanded`. `_chatgpt_p1_activity_open` is the
           # only thing that treats it as open; P2's call sites read it in the
           # log and act on nothing. See `_CHATGPT_INLINE_ACTIVITY_JS`.
           "inline_chip_row": False, "inline_chips": 0}
    try:
        _hit = await page.evaluate(_CHATGPT_SIDE_PANEL_JS)
        if _hit:
            out["side_panel"] = True
            out["side_panel_id"] = _hit if isinstance(_hit, dict) else {}
            out["side_panel_ctx"] = "host"
    except Exception:
        pass
    try:
        il = await page.evaluate(_CHATGPT_INLINE_ACTIVITY_JS)
        if isinstance(il, dict):
            out["inline_expanded"] = bool(il.get("expanded"))
            out["thread_len"] = int(il.get("partial_text_len", 0) or 0)
            out["inline_chips"] = int(il.get("chips", 0) or 0)
            out["inline_chip_row"] = bool(il.get("chip_row"))
    except Exception:
        pass
    if not out["side_panel"]:
        try:
            for frame in [f for f in page.frames if f != page.main_frame][:20]:
                try:
                    _fh = await frame.evaluate(_CHATGPT_SIDE_PANEL_JS)
                    if _fh:
                        out["side_panel"] = True
                        out["side_panel_id"] = _fh if isinstance(_fh, dict) else {}
                        # ⚠ Frame geometry is FRAME-relative, so "right half of
                        # the viewport" and "at most 60% of it" mean almost
                        # nothing inside a small frame. Recording the context is
                        # what makes that visible when it next misfires.
                        try:
                            out["side_panel_ctx"] = (frame.url or "about:blank")[:60]
                        except Exception:
                            out["side_panel_ctx"] = "frame"
                        break
                except Exception:
                    continue
        except Exception:
            pass
    return out


# The Python twin of `_CHATGPT_INLINE_ACTIVITY_JS`'s HOSTCHIP: anchored at both
# ends so a sentence containing a domain can never pass for one.
_HOST_CHIP_RE = re.compile(r"^[a-z0-9][a-z0-9.-]{2,60}\.[a-z]{2,10}$", re.I)


def _chatgpt_p1_activity_open(st):
    """Is P1's activity open? — the P1-ONLY reading of `_chatgpt_activity_state`.

    ⛔⛔ 2026-08-19: WHY THIS IS A SEPARATE PREDICATE AND NOT A LOOSER SHARED ONE.
    P1's 2026-08 UI has no side panel; the live line expands an inline row of
    hostname chips. `inline_expanded` cannot see that row (its gates want a
    60px-tall region of ≥40 chars named "thought"/"activity"; the chips are
    `class="flex"` and a domain long), so on the 19 August run the callers read
    an OPEN drawer as closed and clicked the toggle eight times, closing it — CUA
    watched us do it at 03:06:40 and 03:07:05. The 15-minute cost was CUA
    escalations and dead narration.

    The repair is scoped rather than shared because the same predicate guards P2,
    whose side panel parses correctly today (03:12:42, shape=side, 5 URLs) and
    whose iframe-embedded DR card is the whole reason for `inline_expanded`'s
    text floor. A looser shared rule would let P2 latch "already open" on any
    small in-turn node and never click its strip — the 2026-08-06 regression that
    cost a phase its entire narration. So P2 keeps the strict pair, P1 adds the
    chip row, and the chip count travels in the log either way.
    """
    st = st or {}
    return bool(st.get("side_panel") or st.get("inline_expanded")
                or st.get("inline_chip_row"))


def _chatgpt_open_shape(st):
    """Which shape satisfied the check — for the log line, never for a decision.

    The order matters and is not cosmetic: a run where the side panel is open AND
    a chip row is present is a side-panel run, because that is the shape the
    walker will actually read from.
    """
    st = st or {}
    if st.get("side_panel"):
        return "side"
    if st.get("inline_expanded"):
        return "inline"
    if st.get("inline_chip_row"):
        return "chips"
    return "none"


def _merge_host_chips(res, hosts):
    """Fold P1's hostname chips into a scrape result's source list, in place.

    ⭐ THE OWNER'S ASK, and the reason it needs a function rather than a `+=`:
    a chip is NOT a URL. The measured row is eight DIVs whose entire text is a
    domain — `www.nvidia.com`, `github.com`, … — inside something clickable but
    carrying no href, so a page address for the chip does not exist to be read.
    Synthesising `https://<host>/` is honest about that: it names the site, which
    is what the row names, and it is a link a reader can follow.

    ⛔ AND IT IS DEDUPED BY HOST, NOT BY URL: a host already represented by ANY
    url is not given a second, bare entry. That is only half of the problem,
    because the lists ACCUMULATE across polls — a chip seen at minute two and the
    real page read at minute nine arrive in that order — so the other half,
    dropping the placeholder once a real page for its host lands, is
    `_drop_covered_host_placeholders`, applied by the caller after its merge.
    Both halves are needed or one source is counted twice, against a number the
    owner compares with ChatGPT's own "Searched 20 websites".
    """
    if not isinstance(res, dict) or not hosts:
        return res
    urls = list(res.get("source_urls") or [])
    items = list(res.get("source_items") or [])

    def _host_of(u):
        m = re.match(r"^https?://([^/?#]+)", str(u or ""), re.I)
        return m.group(1).lower().rstrip(".") if m else ""

    # A host is "already real" when some url for it names a path or a query —
    # a bare `https://host/` is only the placeholder this function itself makes.
    def _is_bare(u):
        return bool(re.match(r"^https?://[^/?#]+/?$", str(u or ""), re.I))

    have = {}
    for u in urls:
        h = _host_of(u)
        if not h:
            continue
        have[h] = have.get(h, False) or not _is_bare(u)
    added = []
    added_hosts = set()
    for host in hosts:
        h = str(host or "").strip().lower().rstrip(".")
        # ⛔ VALIDATED HERE TOO, not only in the JS. The row's last cell is an
        # "N more" affordance and the walker's shape test could widen; "13 more"
        # reaching this unchecked builds `https://13 more/`, which is a URL a
        # reader can click and nothing can serve. Same pattern as HOSTCHIP.
        if not h or not _HOST_CHIP_RE.match(h) or h in have:
            continue
        have[h] = False
        url = "https://" + h + "/"
        urls.append(url)
        items.append({"url": url, "title": h})
        added.append(url)
        added_hosts.add(h)
    if added:
        res["source_urls"] = urls
        res["source_items"] = items
        res["chip_hosts_added"] = len(added)
    # ⛔⛔ PROVENANCE, and it is not bookkeeping — it is the difference between a
    # correct prune and a silent deletion of real data. `https://github.com/` is
    # shaped exactly like the placeholder this function synthesises AND exactly
    # like a genuine citation of a project's home page, and nothing about the
    # string can tell them apart. Without this set the prune below would delete a
    # homepage ChatGPT actually cited the moment any deeper page on that host
    # arrived. Recorded as HOSTS on the result rather than a flag on each item,
    # because the caller's own source_items merge rebuilds every entry as exactly
    # {url, title} — a marker on the item would not survive one poll.
    if added_hosts:
        res["chip_hosts"] = sorted(set(res.get("chip_hosts") or []) | added_hosts)
    return res


def _drop_covered_host_placeholders(urls, items, chip_hosts):
    """Drop chip-derived `https://host/` entries that a real page now covers.

    The other half of `_merge_host_chips`. Order of arrival is the whole reason
    this exists: the chip row names a site minutes before the panel or the
    extraction names a page on it, and the caller's accumulator keeps both. One
    source would then be listed twice and counted twice, against a number the
    owner compares with ChatGPT's own "Searched N websites".

    ⛔⛔ `chip_hosts` IS NOT OPTIONAL AND NOT BOOKKEEPING. `https://github.com/` is
    shaped exactly like the placeholder `_merge_host_chips` synthesises AND exactly
    like a genuine citation of a project's home page — no property of the string
    separates them. A shape-only version of this function deleted the second kind:
    cite `https://nvidia.com/` and `https://nvidia.com/blog/x` in one response and
    the homepage citation vanished. So only a host this run actually took FROM A
    CHIP can lose its bare entry, and every other bare URL is somebody's real
    source and is left alone.

    ⛔ A HOST WITH ONLY A PLACEHOLDER KEEPS IT. Dropping every bare domain would
    delete the chips outright on a P1 run, where a bare domain is the only address
    that exists — which is the data the owner asked to see. Returns new lists;
    input order is preserved, because it is arrival order and the newest row is
    what `progress` reads.
    """
    urls = list(urls or [])
    items = list(items or [])
    chips = {str(h or "").strip().lower().rstrip(".") for h in (chip_hosts or [])}
    chips.discard("")
    if not chips:
        return urls, items

    def _host_of(u):
        m = re.match(r"^https?://([^/?#]+)", str(u or ""), re.I)
        return m.group(1).lower().rstrip(".") if m else ""

    def _is_bare(u):
        return bool(re.match(r"^https?://[^/?#]+/?$", str(u or ""), re.I))

    real = {_host_of(u) for u in urls if not _is_bare(u)}
    real.discard("")
    keep = [u for u in urls
            if not (_is_bare(u) and _host_of(u) in chips and _host_of(u) in real)]
    if len(keep) == len(urls):
        return urls, items
    kept = set(keep)
    return keep, [it for it in items
                  if not isinstance(it, dict) or it.get("url") in kept]


async def _close_chatgpt_side_panel(page):
    """#913: close an open ChatGPT right-side panel (Activity / DR plan).

    Used by 2A warm-tab reuse: P1 and P2 share the SAME ChatGPT tab, and if
    P1's Activity panel survives the client-side "New chat", P2's cycle-1
    anti-toggle pre-check would see side_panel=True, flag the panel open
    WITHOUT ever clicking the DR strip, and spend the whole phase scraping
    a stale P1 panel. Finds the panel root (same header/legacy signatures
    as `_chatgpt_activity_state`), clicks its close (×) button; Escape is
    the fallback. Returns True when a close action was dispatched."""
    JS = """() => {
        const roots = [];
        try {
            for (const el of document.querySelectorAll('*')) {
                const t = (el.innerText || '').trim();
                if (!t || !/^(?:activity|deep research)\\b/i.test(t) || t.length > 40) continue;
                const hr = el.getBoundingClientRect();
                if (hr.width === 0 || hr.height === 0) continue;
                if (hr.left < window.innerWidth * 0.5) continue;
                let node = el;
                for (let i = 0; i < 8 && node; i++) {
                    const r = node.getBoundingClientRect();
                    if (r.width >= 200 && r.width <= window.innerWidth * 0.6
                            && r.height >= 150 && r.right > window.innerWidth * 0.55) {
                        roots.push(node); break;
                    }
                    node = node.parentElement;
                }
            }
        } catch (e) {}
        for (const sel of ['aside', '[role="complementary"]',
                           '[aria-label*="activity" i]', '[aria-label*="research" i]']) {
            try {
                for (const el of document.querySelectorAll(sel)) {
                    const r = el.getBoundingClientRect();
                    if (r.width >= 200 && r.height >= 150
                            && r.right > window.innerWidth * 0.55) roots.push(el);
                }
            } catch (e) {}
        }
        for (const root of roots) {
            const btns = root.querySelectorAll(
                'button[aria-label*="close" i], [role="button"][aria-label*="close" i], button');
            for (const b of btns) {
                const bt = (b.innerText || b.getAttribute('aria-label') || '').trim().toLowerCase();
                if (bt === 'x' || bt === '\\u00d7' || bt === '\\u2715' || bt.includes('close')) {
                    try { b.click(); return true; } catch (e) {}
                }
            }
        }
        return false;
    }"""
    try:
        if await page.evaluate(JS):
            return True
    except Exception:
        pass
    try:
        await page.keyboard.press("Escape")
        return True
    except Exception:
        return False


"""How many CUA attempts an activity/artifact panel gets, and when.

⛔⛔ 2026-08-17 — THE ONE-SHOT CAP COST A WHOLE PHASE OF NARRATION.

Two consecutive live P1 runs, eleven hours apart, met the SAME ChatGPT UI: a
past-tense step summary below the last user message ("Built the research brief",
then "Clarified the research scope") with no ellipsis, no count and no matching
verb. The DOM rung missed it in BOTH runs — it has never once matched this state.
So the whole feature rests on the single CUA click, and the two runs diverged only
in whether that one click landed:

  * run A — CUA opened it, and the panel streamed 3 URLs / 17 searches for the
    rest of the phase.
  * run B — CUA reported "the click may not have registered", and that was that:
    21 more DOM misses over ELEVEN MINUTES with no second attempt, an empty
    activity drilldown in the app, and no sources.

One flaky visual click is an ordinary event. Spending a phase's entire narration
on it, while ten minutes of polling sit there doing nothing, is the defect. The
thresholds below are spaced so a long phase gets three well-separated chances
rather than a burst: with a 30s poll that is roughly the 1-minute, 3-minute and
7-minute marks.
"""
_PANEL_CUA_RETRY_AT_MISSES = (2, 6, 14)
# ⛔ DERIVED, never an independent literal. It began as `= 3` beside a 3-entry
# table, which made the ceiling check and the table-bounds check numerically
# identical — two guards that were each other's only protection, so mutation
# testing could not kill either: delete one and the other silently covers for it.
# This repo's rule is to remove the redundancy rather than test an unreachable
# path, and deriving it also means the two can never drift apart.
_PANEL_CUA_MAX_ATTEMPTS = len(_PANEL_CUA_RETRY_AT_MISSES)


def panel_cua_should_escalate(*, dom_misses, attempts, panel_open, blocked=False):
    """Should the panel opener escalate to CUA right now?

    `blocked` is the caller's own "there is legitimately nothing to click"
    signal — P2's completed-chip anchor, Claude's zero-artifact count. It is kept
    separate from the counters so that a phase which SHOULD stay quiet cannot be
    made noisy by the retry change.

    ⭐ The attempt number selects its own threshold, so the retries are spaced by
    DOM misses (i.e. by real elapsed polling) rather than firing back-to-back the
    moment the previous one fails — which on a visual click is just the same
    failure again a second later.
    """
    if panel_open:
        return False
    if blocked:
        return False
    # One bound, not two. It is both the attempt ceiling and the table bounds —
    # see the constant above for why having them separately was untestable.
    if attempts >= len(_PANEL_CUA_RETRY_AT_MISSES):
        return False
    return dom_misses >= _PANEL_CUA_RETRY_AT_MISSES[attempts]


#: How long a never-opened panel must have been never-opened before the vision
#: rescue is allowed to spend a call on it. Env-overridable like its neighbours.
try:
    _VISION_URL_CLOSED_PANEL_MIN_S = int(
        os.environ.get("DG_VISION_URL_CLOSED_PANEL_MIN_S", "300"))
except ValueError:
    _VISION_URL_CLOSED_PANEL_MIN_S = 300


def vision_url_rescue_should_run(*, agent, panel_open, elapsed_sec,
                                 dom_source_count, open_attempts_burned=0,
                                 dom_misses=0, ever_opened=False) -> tuple:
    """Should the screenshot source-rescue run right now? Returns (bool, reason).

    ⛔⛔ THE DEFECT THIS FIXES IS THE SIGNATURE ONE IN THIS FILE: the rescue was
    gated on `artifact_panel_open`, i.e. on the very condition it exists to
    rescue. Measured on this machine's own logs — `didn't stick` fired 28 times
    against 23 `artifact panel opened`, and Claude's rescue succeeded 3 times
    ever against ChatGPT's 9. The panel fails to open MORE often than it opens,
    and every one of those runs was refused the only fallback it had left.

    The three original arms are kept verbatim. The fourth is the never-opened
    case, and it is deliberately narrow because it costs a model call:

      * the panel has NEVER opened this phase — not merely closed right now. A
        panel that opened earlier had its chance and took the first arm.
      * the opener is out of road: its click budget is spent, or DOM misses have
        passed the last CUA-escalation threshold. ⛔ Without this the rescue burns
        its single shot on an early blank frame and then sets `vision_urls_done`,
        so a panel that opens later never gets rescued at all — strictly worse
        than doing nothing.
      * past `_VISION_URL_CLOSED_PANEL_MIN_S`, so an early run is not screenshot
        before Claude has rendered anything.
      * DOM sources are still ZERO. A run that already has sources does not need
        rescuing, and this is what bounds the cost to the failing runs only.

    Because the caller sets `vision_urls_done` on both the success and failure
    paths, this adds AT MOST ONE extra call per run.

    ⚠ CLAUDE ONLY, and that is a decision rather than an oversight. The first
    version of this arm covered ChatGPT too, and to do that it read three `p`
    keys — `chatgpt_panel_reopens`, `chatgpt_activity_dom_misses`,
    `_chatgpt_panel_ever_open` — that DO NOT EXIST. All three would have read
    absent, so the arm would have concluded "opener still trying" forever: a
    guard that cannot fire, added while fixing a guard that could not fire.
    ChatGPT's real state lives under different names, its rescue already
    succeeds three times as often, and nothing has been measured about its
    never-opened case. Widening this to an unmeasured path is not a bug fix.

    Pure and module-level: the caller is a closure inside
    `poll_all_agents_round_robin`, which nothing in the suite executes, so a
    predicate written inline there could only ever be source-scanned — and
    mutation has already proved a source-scanned gate can ship inverted.
    """
    if agent in ("ChatGPT", "Claude") and panel_open:
        return True, "panel-open"
    if agent == "Gemini" and int(elapsed_sec or 0) > 120:
        return True, "gemini-elapsed"
    if agent != "Claude":
        return False, "no-arm"
    if ever_opened:
        return False, "panel-opened-earlier"
    if int(dom_source_count or 0) > 0:
        return False, "dom-has-sources"
    if int(elapsed_sec or 0) < _VISION_URL_CLOSED_PANEL_MIN_S:
        return False, "too-early"
    _out_of_road = (int(open_attempts_burned or 0) >= 3
                    or int(dom_misses or 0) >= _PANEL_CUA_RETRY_AT_MISSES[-1])
    if not _out_of_road:
        return False, "opener-still-trying"
    return True, (f"panel-never-opened, reopens={int(open_attempts_burned or 0)}/3, "
                  f"dom_misses={int(dom_misses or 0)}, dom_sources=0")


async def _log_chatgpt_thread_snapshot(page, tag=""):
    """#913 (instrument-with-logs directive): one compact structural line of
    the thread region below the last user message + the frame inventory, so
    a persistent panel-open miss can be root-caused from backend.log alone —
    no live DOM session needed (probing the worker profile out-of-band risks
    the bot score)."""
    JS = """() => {
        let lub = -1;
        document.querySelectorAll('[data-message-author-role="user"]').forEach(u => {
            const r = u.getBoundingClientRect();
            if (r.bottom > lub) lub = r.bottom;
        });
        // ⛔ 2026-08-17 — THIS LINE USED TO ANSWER NOTHING. Every one of the 18
        // rows it could afford came back as the SAME text: a strip line is a
        // stack of nested wrappers, all reporting identical innerText, so the
        // whole budget was spent describing one line eighteen times. Two live
        // misses were captured that way and neither could say what ELSE sits
        // next to the strip — which is exactly what a wording-free matcher has
        // to be built from, and the reason no such matcher exists yet. Dedupe by
        // text and the budget describes the NEIGHBOURHOOD instead.
        const rows = [];
        const seen = new Map();          // text -> row already recorded
        let dupes = 0;
        for (const el of document.querySelectorAll('main *')) {
            if (rows.length >= 20) break;
            if (el.children.length > 2) continue;
            const t = (el.innerText || '').trim();
            if (!t || t.length < 3 || t.length > 120) continue;
            const r = el.getBoundingClientRect();
            if (r.width === 0 || r.height === 0) continue;
            if (lub > 0 && (r.top < lub - 8 || r.top > lub + 700)) continue;
            const key = t.slice(0, 60);
            // A shimmer lives on an inner span (animated gradient +
            // background-clip:text), and rows with >2 children never get here —
            // so asking only about THIS element reported anim:false on a line
            // the vision tier described as shimmering. Ask the subtree too, and
            // report the two answers separately: if `animKid` turns out to be
            // the reliable one, "the shimmering line below the last user
            // message" becomes the structural anchor that wording never was.
            // ⛔ Same split as the decider — and it has to BE the same split, or
            // the snapshot would keep reporting a shimmer the picker no longer
            // sees and the two would disagree about the same row.
""" + _CHATGPT_SHIMMER_JS_HELPERS + """
            let anim = shimmers(el);
            let clip = clipped(el);
            let animKid = false;
            try {
                for (const kid of el.querySelectorAll('*')) {
                    if (shimmers(kid)) { animKid = true; break; }
                }
            } catch (e) {}
            if (!clip) {
                try {
                    for (const kid of el.querySelectorAll('*')) {
                        if (clipped(kid)) { clip = true; break; }
                    }
                } catch (e) {}
            }
            if (seen.has(key)) {
                // Keep the OUTERMOST occurrence (document order), but do not
                // lose a shimmer that only the inner copy could see.
                const prev = seen.get(key);
                prev.anim = prev.anim || anim;
                prev.animKid = prev.animKid || animKid;
                prev.clip = prev.clip || clip;
                dupes += 1;
                continue;
            }
            const btn = el.closest ? !!el.closest('button, [role="button"], [tabindex]') : false;
            // ⛔ The snapshot recorded anim, animKid, testid, aria, class and y —
            // but NOT containment or interactivity, which are two of the four
            // terms the picker actually turns on. The artifact whose only job is
            // explaining a miss could not explain one: given a row it had chosen,
            // the log could not say whether `inter`, `inTurn`, `named` or a dead
            // gradient had carried it. Record what the decision is made of.
            let inter = false, node = el;
            for (let i = 0; i < 6 && node; i++) {
                const role = node.getAttribute && node.getAttribute('role');
                const ti2 = node.getAttribute && node.getAttribute('tabindex');
                if (node.tagName === 'BUTTON' || role === 'button'
                        || (ti2 !== null && ti2 !== undefined && parseInt(ti2, 10) >= 0)) {
                    inter = true; break;
                }
                node = node.parentElement;
            }
            let inTurn = false, named = false;
            try {
                inTurn = !!el.closest('[data-testid^="conversation-turn"], '
                                      + '[data-message-author-role="assistant"]');
            } catch (e) {}
            try {
                named = !!el.closest('[data-testid^="cot-v"][data-testid*="pinned-row"]');
            } catch (e) {}
            const row = { t: key, tag: el.tagName,
                          ti: (el.getAttribute && el.getAttribute('data-testid')) || '',
                          ax: (el.getAttribute && el.getAttribute('aria-expanded')) || '',
                          // First class token only. The full attribute is a wall
                          // of hashed utility classes; the leading token is the
                          // part that has ever been a usable hook.
                          cl: ((el.className && el.className.split)
                               ? el.className.split(/\\s+/)[0] : '').slice(0, 32),
                          y: Math.round(r.top), btn, anim, animKid,
                          clip, inter, inTurn, named };
            seen.set(key, row);
            rows.push(row);
        }
        return { lub: Math.round(lub), rows, dupes };
    }"""
    try:
        snap = await page.evaluate(JS)
    except Exception as _se:
        log(f"[ChatGPT] thread snapshot failed ({tag}): {_se}", "DEBUG")
        return
    try:
        frames = [(f.url or "")[:80] for f in page.frames][:10]
    except Exception:
        frames = []
    try:
        line = json.dumps({"snap": snap, "frames": frames}, ensure_ascii=True)
    except Exception:
        line = str(snap)[:1800]
    # 1800 chars truncated mid-row and threw away the tail, which after the
    # dedupe above is where the strip's neighbours now live.
    log(f"[ChatGPT] panel-miss snapshot ({tag}): {line[:3500]}", "DEBUG")


async def _open_chatgpt_activity_panel(page, skip_structural=False):
    """Click the activity affordance for the latest ChatGPT response.

    #913: what the click opens is MODE-DEPENDENT — P1 Pro/ET opens the
    narrow "Activity · Ns" right-side panel (skeleton rows early); P2 Deep
    Research slides out the execution-plan panel. This function only finds
    + clicks; callers verify with `_chatgpt_activity_state` (any shape
    counts) and must NEVER call this while a shape is already open — the
    line is a toggle. PASS 0 anchors structurally on the shimmering status
    line directly below the last sent (user) message; the wording anchors
    (PASS 1/2) remain for the DR count-badge strip (e.g. 'Looking into
    Hermes... 196 searches'), which lives inside the DR card's iframe.

    Robust selector (2026-04-26 v2): walks ALL elements (not just buttons —
    ChatGPT renders the strip as a styled <div> with imperatively-bound click
    handlers, so the v1 narrow `button, [role="button"]` selector matched 0
    candidates and silently no-op'd across 3 user runs). Recurses into Shadow
    DOM. Dispatches the full pointer/mouse event chain (pointerdown → mousedown
    → pointerup → mouseup → click) instead of bare `.click()` so React's
    synthetic listeners fire. Tries the leaf element then 5 ancestors.

    Returns dict with `found`, `candidates` (count of text-matched nodes),
    `clicked`, `alreadyExpanded`, `label`, `clickedTag`. Caller uses
    `_chatgpt_activity_state(page)` 2s post-click to confirm a shape
    actually mounted (mitigates silent click failures).

    `skip_structural=True` (#913): callers pass this after 2 failed
    attempts — if PASS 0 keeps picking a host-page element whose click
    never verifies, it would otherwise starve the legacy passes AND the
    frame walk (host found:true short-circuits both) forever."""
    JS = """(skipStructural) => {
        // searches | sources | results | citations — covers all observed
        // badge wordings ("citations" added 2026-07-06 #905: the completed
        // strip reads "Research completed in 8m · 17 citations · 96 searches").
        const COUNT = /\\b\\d+\\s+(?:searches?|sources?|results?|citations?)\\b/i;
        // 2026-07-06 (#905, live-run walked_hits=0 ×3): two NEW strip states
        // the old anchors missed entirely —
        //  - COMPLETED: after the run finishes the strip drops the ellipsis
        //    and reads "Research completed in 8m · …". Clicking it still
        //    opens the sources side panel (needed for source chips + the
        //    end-of-phase URL extraction), so it must stay clickable.
        //  - STATUS_LINE: the 2026-07 UI streams a tier-prefixed shimmer
        //    line ("Pro thinking") with NO ellipsis, NO count, and the verb
        //    not line-initial — invisible to VERB_ONLY's ^ anchor. Length-
        //    capped at 60 chars in findHitsIn so prose can't match.
        const COMPLETED = /\\bresearch\\s+completed\\b|\\bcompleted\\s+in\\s+\\d+\\s*(?:s|m|min|h)\\b/i;
        const STATUS_LINE = /^(?:[\\w.+-]{1,12}\\s+)?(?:thinking|reasoning|researching)\\b/i;
        // Verb-only fallback for P1 Pro+ET strips that haven't materialized a
        // count yet. Includes "thinking"/"reasoning" because Pro+ET shows
        // those before swapping to site-fetch verbs ("Reading <site>",
        // "Visiting <url>") mid-stream. Reverted 2026-05-03 to the pre-c06a60e
        // P1-only list — the P2 synthesis-stage verbs (confirming, summarizing,
        // synthesizing, drafting, finalizing) added across commits c06a60e..
        // 9f4117c chased a moving target and never opened the P2 source panel
        // reliably anyway. The ELLIPSIS anchor handles most P2 wording; P1 verb
        // wording is stable so this list stays.
        const VERB_ONLY = /^(thinking|reasoning|searching|looking|browsing|investigating|analyzing|reading|exploring|checking|visiting|researching)\\b/i;
        // 2026-05-03 STRUCTURAL ANCHOR: the live in-tile glow line ends with an
        // ellipsis ("..." or U+2026 normalized) while the run is streaming.
        // Verb wording mutates per stream (5 prior commits keep expanding the
        // verb regex with no end in sight). Match BOTH ASCII three-dot and
        // Unicode \\u2026.
        //
        // ⛔⛔ 2026-08-19 — "ALWAYS" IS WHAT THIS COMMENT USED TO SAY, AND IT IS
        // FALSE. Measured over one 13.7-minute P1 phase: not one label ended in
        // dots — "Mapped security coverage", "Compared security layers",
        // "Searching the web", "Searched 20 websites" (the last two confirmed
        // against the owner's screenshots). The same run's P2 strip DID open off
        // "Researching..." at 03:12:42, so this is not a dead anchor to delete —
        // deleting it would take P2's working leg with it. It is an anchor whose
        // stated universality was never true, and the cost of believing it was
        // paid by the downstream verifier, not here: `ELLIPSIS` was one of only
        // three ways `_CHATGPT_INLINE_ACTIVITY_JS` could recognise a status line,
        // so P1's status line came back EMPTY all phase. That walker now has a
        // shimmer term; this one already had STATUS_LINE and the structural
        // shimmer pass, which is why the OPENER found the line every single time
        // (anchor=structural at 02:56:08, anchor=global at 03:00:06). Finding it
        // was never the problem. Verifying it was.
        const ELLIPSIS = /(?:\\.{3}|\\u2026)\\s*$/;

        // A root with more than NODE_CAP descendants is abandoned unscanned —
        // a deliberate cost ceiling on a long ChatGPT thread. Both walks did
        // this SILENTLY, returning the same {found:false, candidates:0} as a
        // page that was scanned and simply had no strip in it. So the caller's
        // miss line asserted "strip not yet rendered or wording changed" on a
        // page where neither had been established, and a thread that had grown
        // past the ceiling looked identical to a wording change forever.
        // DIAG carries what was actually seen back to the caller.
        const NODE_CAP = 8000;
        // ⛔⛔ 2026-08-20 — AND THE CENSUS OF THE STRUCTURAL PASS, because
        // twenty-one identical miss lines over eleven minutes could not
        // distinguish "no candidate existed" from "a candidate existed and every
        // gate rejected it". The live 08-19 P1 phase produced exactly that: the
        // vision tier described the shimmering row on screen three separate
        // times while this walk reported `nothing matched` every thirty seconds.
        // `walked` and `prose` were the only two numbers the miss line carried,
        // and neither of them is ever touched by PASS 0.
        const DIAG = { roots: 0, walked: 0, cappedRoots: 0, maxNodes: 0,
                       structuralCapped: false, prose: 0,
                       // PASS 0's own accounting: did it run, how many rows
                       // reached its band, and what threw the rest out.
                       structRan: false, structAnchor: '', structSkip: '',
                       structInBand: 0,
                       structOffBand: 0, structShape: 0, structProse: 0,
                       structNoSignal: 0, structQualified: 0, structVia: '' };

        // ⛔⛔ 2026-08-18 — TWO OF THE THREE ARMS WERE NOT ANIMATION AT ALL.
        // `background-clip: text` is a static PAINT property: it says the fill is
        // clipped to the glyphs, which is equally true of a gradient that has
        // stopped. ChatGPT's completed thinking steps keep the gradient class and
        // just stop moving, so the detector answered "shimmering" for a row the
        // vision tier described, the same minute, as "shown in gray, not
        // shimmering". `animationName !== 'none'` had the same hole from the other
        // side: a finished or paused animation still has a name.
        //
        // A live line and a dead line were therefore indistinguishable to the one
        // check whose entire job was telling them apart — which is why an anchor
        // built to survive rewording still had to be rescued by wording.
        //
        // Split, not dropped. `shimmers` is now strictly "an animation is
        // RUNNING on this node"; the static gradient clip becomes `clipped`, is
        // reported, and can only ever decide when nothing strict qualifies — so
        // today's reach is preserved exactly while the log finally names which of
        // the two carried any given press.
""" + _CHATGPT_SHIMMER_JS_HELPERS + """

        // Specificity score for hit ranking. Layered to keep the 32c2957
        // "parent strip > badge child" guarantee while putting the live
        // ellipsis-bearing leaf above everything (it's the actual click
        // target with the React handler attached, not a presentational
        // wrapper). Tiers: 5 ellipsis+verb > 4.5 ellipsis+count >
        // 4 completed-strip > 3.5 bare ellipsis > 3.2 status-line >
        // 3 verb+count > 2 verb-only > 1 count-only > 0 (none —
        // unreachable; findHitsIn filters).
        const hitScore = (h) => {
            if (h.hasEllipsis && h.hasVerb)  return 5;
            if (h.hasEllipsis && h.hasCount) return 4.5;
            if (h.hasCompleted)              return 4;
            if (h.hasEllipsis)               return 3.5;
            if (h.hasStatusLine)             return 3.2;
            if (h.hasVerb && h.hasCount)     return 3;
            if (h.hasVerb)                   return 2;
            if (h.hasCount)                  return 1;
            return 0;
        };

        function findHitsIn(root) {
            // Local accumulator — kept narrow so caller can priority-rank
            // dialog hits ahead of host-page hits.
            const out = [];
            if (!root) return out;
            let nodes;
            try { nodes = root.querySelectorAll('*'); } catch (e) { return out; }
            DIAG.roots++;
            if (nodes.length > DIAG.maxNodes) DIAG.maxNodes = nodes.length;
            if (nodes.length > NODE_CAP) { DIAG.cappedRoots++; return out; }
            DIAG.walked += nodes.length;
            for (const el of nodes) {
                const t = (el.innerText || el.textContent || '').trim();
                if (!t || t.length < 4 || t.length > 300) continue;
                const matchesCount    = COUNT.test(t);
                const matchesVerb     = VERB_ONLY.test(t);
                // Ellipsis match limited to 12–240 char leaves — the live
                // narration sentences land in this window. Mid-sentence
                // "..." in streamed prose paragraphs typically run >240
                // chars (filtered out) or <12 chars (placeholder spans).
                const matchesEllipsis = ELLIPSIS.test(t) && t.length >= 12 && t.length <= 240;
                // #905: completed strip ("Research completed in 8m · …") —
                // leaf cap 120 chars so a prose recap can't match.
                const matchesCompleted = COMPLETED.test(t) && t.length <= 120;
                // #905: shimmer status line ("Pro thinking") — short leaves only.
                const matchesStatus   = STATUS_LINE.test(t) && t.length <= 60;
                if (!matchesCount && !matchesVerb && !matchesEllipsis
                        && !matchesCompleted && !matchesStatus) continue;
                // ⭐⭐ 2026-08-06 — THE STRIP IS NEVER IN THE REPORT. Twelve
                // presses in one phase (and five in the morning run) landed on
                // a MARKDOWN TABLE CELL of ChatGPT's own output:
                //   documents/chatgpt.md:574
                //     | Complex reasoning | 2-3 | 4 | 5 vendor-intended | ... |
                //   (05:35 run) | ... | Small reasoning safety classifier | ... |
                // Both clear STATUS_LINE's optional 1-12-char prefix and both
                // sit under its 60-char cap, so the weakest tier ranked them
                // 3.2 — above verb+count — and once the live strip was gone
                // they were the top-ranked hit on the whole document.
                //
                // Placed in findHitsIn, not in one pass: the structural pass
                // already excludes composer/header/nav subtrees and PASS 1 and
                // PASS 2 do not, which is the same one-of-several-paths shape
                // that keeps producing these. This arm applies to every pass.
                let inProse = false;
                try {
                    // A table cell, a code block, or a link is never the strip.
                    // The link arm is the sidebar-conversation lesson from the
                    // drift wave: pressing an <a> navigates.
                    if (el.closest('table, td, th, code, pre, a[href]')) inProse = true;
                    // ⛔⛔ 2026-08-18 — THE COMPOSER AND THE PAGE CHROME WERE ONLY
                    // EVER EXCLUDED BY PASS 0. While PASS 0 answered first that
                    // was invisible; the moment it was demoted to a last resort,
                    // the global walk became the first pass to see the whole
                    // document, and a shimmering "Searching for updates..."
                    // banner outside every conversation turn was pressed instead
                    // of the strip. Caught by an existing PASS 0 test whose
                    // fixture the reorder handed to a different pass.
                    //
                    // Safe for the dialog pass too: the activity strip has never
                    // rendered inside a form, a header, a toolbar or a nav.
                    if (!inProse && el.closest(
                            'form, [data-testid*="composer" i], #prompt-textarea, '
                            + 'header, [role="toolbar"], nav')) inProse = true;
                    // The rendered response body. Only the two WEAKEST tiers are
                    // refused here — a completed strip or a live ellipsis line
                    // carries evidence prose cannot fake, so if one ever renders
                    // inside the markdown container it still counts.
                    if (!inProse && !matchesEllipsis && !matchesCount && !matchesCompleted
                            && el.closest('.markdown, [class*="markdown"], [class*="prose"]')) {
                        inProse = true;
                    }
                } catch (e) { inProse = false; }
                if (inProse) { DIAG.prose = (DIAG.prose || 0) + 1; continue; }
                const r = el.getBoundingClientRect();
                if (r.width === 0 || r.height === 0) continue;
                out.push({ el, top: r.top, len: t.length,
                           hasCount: matchesCount, hasVerb: matchesVerb,
                           hasEllipsis: matchesEllipsis,
                           hasCompleted: matchesCompleted,
                           hasStatusLine: matchesStatus });
            }
            return out;
        }

        function clickAndReturn(target, candidatesCount, scope) {
            const label = (target.innerText || target.textContent || '').trim().slice(0, 160);
            // aria-expanded check up the chain — skip re-click if already open
            let probe = target;
            for (let i = 0; i < 6 && probe; i++) {
                if (probe.getAttribute && probe.getAttribute('aria-expanded') === 'true') {
                    const er = target.getBoundingClientRect();
                    return { found: true, alreadyExpanded: true, label,
                             candidates: candidatesCount, scope,
                             bbox: { cx: er.left + er.width / 2, cy: er.top + er.height / 2,
                                     vw: window.innerWidth, vh: window.innerHeight } };
                }
                probe = probe.parentElement;
            }
            // parent-chain dispatch loop — try leaf, then up to 5 ancestors
            const tries = [];
            let node = target;
            for (let i = 0; i < 6 && node; i++) { tries.push(node); node = node.parentElement; }
            let clickedTag = '';
            let clickedBox = null;
            let lastErr = '';
            for (const n of tries) {
                try {
                    const r = n.getBoundingClientRect();
                    const x = r.left + r.width / 2, y = r.top + r.height / 2;
                    const opts = { bubbles: true, cancelable: true, view: window,
                                   clientX: x, clientY: y, button: 0 };
                    // Full event chain — covers React onPointerDown/onMouseDown/onClick
                    n.dispatchEvent(new MouseEvent('pointerdown', opts));
                    n.dispatchEvent(new MouseEvent('mousedown',  opts));
                    n.dispatchEvent(new MouseEvent('pointerup',  opts));
                    n.dispatchEvent(new MouseEvent('mouseup',    opts));
                    n.dispatchEvent(new MouseEvent('click',      opts));
                    clickedBox = { cx: x, cy: y, vw: window.innerWidth, vh: window.innerHeight };
                    clickedTag = (n.tagName || '') +
                                 (n.getAttribute && n.getAttribute('role')
                                     ? `[${n.getAttribute('role')}]` : '');
                    break;
                } catch (e) { lastErr = String(e); continue; }
            }
            return { found: true, clicked: !!clickedTag, label,
                     candidates: candidatesCount, clickedTag, scope, error: lastErr,
                     bbox: clickedBox };
        }

        // #913 PASS 0 — STRUCTURAL anchor (user directive 2026-07-07): the
        // shimmering status line sits DIRECTLY BELOW the last sent (user)
        // message as the first short row of the assistant turn. Its wording
        // mutates with the platform's progress ("Pro thinking" →
        // "Searching the web" → "Research completed in 9m · …"), so rank by
        // position + interactivity + shimmer animation instead of text.
        // Never clicks bare prose: a candidate must have button/tabindex
        // ancestry OR an animated/gradient-clipped style. Composer, header
        // and toolbar subtrees are excluded. The wording anchors below stay
        // as PASS 1/2 fallbacks (they also serve the DR count-badge strip,
        // which sits at the BOTTOM of the DR card inside its iframe).
        let lub = -1;
        try {
            document.querySelectorAll('[data-message-author-role="user"]').forEach(u => {
                const r = u.getBoundingClientRect();
                if (r.bottom > lub) lub = r.bottom;
            });
        } catch (e) {}
        // ⛔⛔ THE STRUCTURAL CANDIDATE IS HELD, NOT ACTED ON. Measured 2026-08-18
        // against the owner's own corpus: the panel opened via DOM 13 times and
        // EVERY ONE was `anchor=global clickedTag=P` on a live in-progress label
        // ("Planning a research-based report..."). It has never once opened from
        // a structural pick.
        //
        // ⭐⭐ AND THE REASON IS A FIX OF MINE. Before 2026-08-17 the PASS 0 gate
        // was a score threshold that could never be met, so this pass always fell
        // through to the global walk — the one that worked. Making the gate a
        // predicate did exactly what it was meant to do, and thereby stole the
        // decision from the only path with a success record: it now picks a
        // COMPLETED thinking step (a DIV, past tense: "Structured security
        // analysis") whose click does nothing, burns both CUA escalations, and
        // the run narrates nothing for the rest of the phase.
        //
        // A guard that could not fire was load-bearing, because the fallback it
        // suppressed was the thing that worked. So the structural pick is kept as
        // a LAST resort — after the dialog pass and after the global walk — and
        // the pass that has 13 successes gets to answer first.
        let deferredStructural = null;
        let deferredStructuralCount = 0;
        // ⛔ WHICH reason, recorded. The census used to say "no turn and no
        // on-screen user message" whenever this pass did not run — naming two
        // causes on evidence for neither, which is the exact sin the miss-reason
        // function above documents fixing. In the 08-20 e2e it printed that while
        // every snapshot in the same run read `lub: 202`, so the stated cause was
        // impossible and the real one (the caller asking to skip) went unsaid.
        DIAG.structSkip = skipStructural ? 'caller asked to skip'
                        : (lub > 0 ? '' : 'no user message on screen');
        if (!skipStructural && lub > 0) {
            DIAG.structRan = true;
            DIAG.structAnchor = 'lub';
            const structural = [];
            const mainEl = document.querySelector('main') || document.body;
            let mnodes;
            try { mnodes = mainEl.querySelectorAll('*'); } catch (e) { mnodes = []; }
            if (mnodes.length > DIAG.maxNodes) DIAG.maxNodes = mnodes.length;
            if (mnodes.length > NODE_CAP) {
                DIAG.cappedRoots++; DIAG.structuralCapped = true; mnodes = [];
            } else { DIAG.roots++; DIAG.walked += mnodes.length; }
            for (const el of mnodes) {
                if (el.children.length > 2) { DIAG.structShape++; continue; }
                const t = (el.innerText || el.textContent || '').trim();
                if (!t || t.length < 3 || t.length > 200) { DIAG.structShape++; continue; }
                const r = el.getBoundingClientRect();
                if (r.width === 0 || r.height === 0) { DIAG.structShape++; continue; }
                const offTop = r.top - lub;
                if (offTop < -8 || offTop > 600) { DIAG.structOffBand++; continue; }
                DIAG.structInBand++;
                if (el.closest && el.closest(
                        'form, [data-testid*="composer" i], #prompt-textarea, ' +
                        'header, [role="toolbar"], nav')) { DIAG.structProse++; continue; }
                // ⛔ 2026-08-20 — THE PROSE EXCLUSION BELONGS HERE TOO. Until now
                // it lived only in `findHitsIn`, and the note there already says
                // why that is the wrong place: "the same one-of-several-paths
                // shape that keeps producing these". Removing the viewport band
                // above widens what this pass can see, so the arm that stops it
                // pressing a table cell in the agent's own report has to arrive
                // in the same change — a shimmering skeleton inside a rendered
                // table is exactly the thing a turn-relative band cannot exclude
                // on geometry alone.
                if (el.closest && el.closest(
                        'table, td, th, code, pre, a[href], '
                        + '.markdown, [class*="markdown"], [class*="prose"]')) {
                    DIAG.structProse++; continue;
                }
                let inter = false, node = el;
                for (let i = 0; i < 6 && node; i++) {
                    const role = node.getAttribute && node.getAttribute('role');
                    // tabindex >= 0 only — tabindex="-1" rides on scroll
                    // containers and would bless half the page.
                    const ti = node.getAttribute && node.getAttribute('tabindex');
                    if (node.tagName === 'BUTTON' || role === 'button' ||
                        (ti !== null && ti !== undefined && parseInt(ti, 10) >= 0)) {
                        inter = true; break;
                    }
                    node = node.parentElement;
                }
                // ⭐⭐ 2026-08-17 — THE SHIMMER LIVES ON AN INNER SPAN. Measured:
                // the same strip line reported `anim:false` on itself and
                // `animKid:true` on its subtree, and the vision tier had been
                // describing it as shimmering all along. Checking only this
                // element and its PARENT is how a wording-free anchor ended up
                // depending on wording anyway. Bounded — rows with more than two
                // children never reach here, so the subtree is a handful of nodes.
                // ⛔⛔ 2026-08-20 — THE SELF-ONLY READINGS, KEPT SEPARATE. The
                // broadened `anim`/`clip` below ask "this element, its parent, or
                // any of twelve children", which is what lets them find a shimmer
                // that lives on an inner span. It is also what makes each of them
                // useless as evidence on its own: the composer's model chip
                // reports an animated DESCENDANT too, and that is precisely why
                // the qualifier refuses a lone shimmer. The self-only pair does
                // not have that problem, and nothing was asking for it.
                const animSelf = shimmers(el);
                const clipSelf = clipped(el);
                let anim = shimmers(el)
                    || (el.parentElement ? shimmers(el.parentElement) : false);
                if (!anim) {
                    try {
                        let seen = 0;
                        for (const kid of el.querySelectorAll('*')) {
                            if (++seen > 12) break;
                            if (shimmers(kid)) { anim = true; break; }
                        }
                    } catch (e) {}
                }
                // The static gradient clip, asked separately and over the same
                // three places. It used to be folded into `anim`, which is how a
                // finished step read as a live one.
                let clip = clipped(el)
                    || (el.parentElement ? clipped(el.parentElement) : false);
                if (!clip) {
                    try {
                        let seen = 0;
                        for (const kid of el.querySelectorAll('*')) {
                            if (++seen > 12) break;
                            if (clipped(kid)) { clip = true; break; }
                        }
                    } catch (e) {}
                }
                // ⭐⭐ CHATGPT NAMES THIS ROW. Captured live from a panel miss:
                // `data-testid="cot-v5-pinned-row"` with the text on
                // `cot-v5-pinned-row-content`. An exact name beats every heuristic
                // below it, and the version digit is left free so a v6 still
                // matches — the row is the same row.
                let named = false;
                try {
                    named = !!el.closest('[data-testid^="cot-v"][data-testid*="pinned-row"]');
                } catch (e) {}
                // `clip` is admitted here purely so nothing that reached this
                // list before still reaches it — the arm used to live inside
                // `anim`. What changed is that it can no longer DECIDE alone.
                if (!inter && !anim && !clip && !named) { DIAG.structNoSignal++; continue; }
                // Is the candidate inside the assistant's own turn? The captured
                // chain puts the strip under `SECTION[data-testid=
                // "conversation-turn-2"]`. This is what keeps a lone shimmer from
                // qualifying: the composer's model chip ("Pro") also reported an
                // animated descendant in the same capture, 400px lower and outside
                // every turn.
                let inTurn = false;
                try {
                    inTurn = !!el.closest('[data-testid^="conversation-turn"], '
                                          + '[data-message-author-role="assistant"]');
                } catch (e) {}
                const wordy = COUNT.test(t) || VERB_ONLY.test(t)
                    || STATUS_LINE.test(t) || ELLIPSIS.test(t) || COMPLETED.test(t);
                // A dead gradient is worth 1 against a running animation's 3:
                // present, ranked, never mistaken for the live line.
                // ⭐ `named` IS NOT IN THIS SUM, deliberately. It is a TIER in
                // the sort below, so four points here could not change any
                // ordering — between two named rows it cancels, and against an
                // unnamed one the tier has already decided. A term that cannot
                // affect an outcome is the decorative-guard shape this file keeps
                // removing, and mutation proved it: zeroing it changed nothing.
                const score = (inter ? 3 : 0) + (anim ? 3 : 0)
                    + (wordy ? 2 : 0) + (clip ? 1 : 0) - offTop / 1000;
                structural.push({ el, score, len: t.length,
                                  named, inter, anim, clip, wordy, inTurn,
                                  animSelf, clipSelf });
            }
            // ⭐⭐ 2026-08-17 — THE GATE IS A PREDICATE, NOT A SUM. It used to be
            // `score >= 3`, and 3 is exactly the weight of ONE signal while the
            // distance penalty `-(top - lub)/1000` is ALWAYS subtracted. So a
            // candidate carrying one signal could never clear the bar: the
            // captured strips scored 2.960 and 2.896 and were both refused, and
            // the only PASS 0 that ever fired in the corpus did so because its
            // text happened to read "Searching the web" (+2 wordy). A structural
            // anchor built to survive rewording was therefore decided by wording,
            // silently, for as long as it has existed.
            //
            // ⛔ Not simply lowering the number: a bar below a single signal would
            // bless any clickable row near the message. The evidence has to be
            // named instead — and then the sum is free to do what it is good at,
            // which is RANKING the qualifiers.
            // ⛔⛔ 2026-08-20 — THE MEASURED GAP. A live P1 phase logged
            // twenty-three misses and spent all three vision escalations while
            // the row was on screen and shimmering, and the panel-miss snapshot
            // said why in full, twice, five minutes apart:
            //
            //   the live line   anim(self)=TRUE  clip(self)=TRUE  animKid=true
            //                   inter=false  inTurn=false  named=false
            //   the disclaimer  anim=false clip=false animKid=false
            //   the model chip  anim=false clip=false animKid=TRUE
            //
            // Every arm below was false for the row. `lub` was 202 the whole
            // phase, so the band never came into it, and ChatGPT had stopped
            // putting `cot-v*-pinned-row` and any turn container on that node —
            // so `named` and `inTurn`, the two exact signals, were both gone.
            //
            // ⭐⭐ AND THE PAIR THAT WAS TRUE HAD NO ARM. The 08-18 split was
            // right: a running animation ANYWHERE in the subtree matches the
            // composer's model chip, and a static gradient matches a finished
            // step, so neither half may decide alone. What it never did was
            // recombine them ON THE SAME ELEMENT. A node whose own animation is
            // running AND whose own text is clipped to a gradient is not a weak
            // signal — it is the definition of a live shimmering text row, and in
            // this capture it is the only node on the page that is both. The
            // model chip fails it on `animSelf`; the finished step fails it on
            // `animSelf`; a dead gradient fails it on `animSelf`.
            const qualifies = (h) => h.named           // ChatGPT's own name for it
                || (h.animSelf && h.clipSelf)          // a live shimmering text row
                || (h.anim && h.inTurn)                // the shimmer, contained
                || (h.inter && h.anim)                 // the original two-signal rule
                || (h.inter && h.wordy);               // clickable AND a known state
            // ⭐ The weak tier exists only so this pass reaches exactly what it
            // reached before the split. It is consulted when NOTHING carries a
            // running animation, and whatever it picks is tagged `+clip` so the
            // next miss line says out loud that a static gradient decided it.
            const qualifiesWeak = (h) => (h.clip && h.inTurn) || (h.inter && h.clip);
            let ranked = structural.filter(qualifies);
            let weakTier = false;
            if (!ranked.length) {
                ranked = structural.filter(qualifiesWeak);
                weakTier = ranked.length > 0;
            }
            DIAG.structQualified = ranked.length;
            // Which arm carried the pick, so a wrong press names its own reason.
            if (ranked.length) {
                const h = ranked[0];
                DIAG.structVia = [h.named ? 'named' : '',
                                  (h.animSelf && h.clipSelf) ? 'shimmer-self' : '',
                                  (h.anim && h.inTurn) ? 'anim+turn' : '',
                                  h.inter ? 'inter' : ''].filter(Boolean).join('+');
            }
            if (ranked.length) {
                // Sorted, then [0] — it used to rank the whole list and inspect
                // only the top one, so a qualifying row sitting behind an
                // unqualified higher scorer was never reached.
                // ⛔⛔ 2026-08-20 — AN EXACT NAME IS A TIER, NOT FOUR POINTS.
                // `named` is worth 4 and so is `anim`(3)+`clip`(1), so once the
                // pair got a qualifying arm the two tied — and the tie was broken
                // by the distance penalty, i.e. by eighteen thousandths of a
                // point of pixel offset. Found by mutation: a shimmering stranger
                // outranked the row ChatGPT itself names. The comment on `named`
                // has always said it "beats every heuristic below it"; this makes
                // the sort agree with it, instead of hoping the arithmetic does.
                ranked.sort((a, b) => (Number(!!b.named) - Number(!!a.named))
                                      || (b.score - a.score) || (a.len - b.len));
                // Held for the fallback at the bottom. NOT clicked here — see the
                // note where `deferredStructural` is declared.
                deferredStructural = ranked[0];
                deferredStructural.weak = weakTier;
                deferredStructuralCount = structural.length;
            }
        }

        // 2026-04-28: PASS 1 — dialog-scoped search FIRST. The DR plan
        // dialog (role="dialog" / aria-modal / report-plan class) renders
        // the activity-strip pill ("Summarizing X · 133 searches") pinned
        // at its bottom — clicking THAT is what mounts the sources sub-
        // panel. The host page ALSO renders a presentational footer with
        // the same wording, and clicking that does nothing. Without
        // searching dialog-scoped first, the global walker found the
        // host-page footer, scored it, clicked it, and silently no-op'd
        // — leaving narration stuck at "0 sources, 0 chars".
        const dialogs = document.querySelectorAll(
            '[role="dialog"], [aria-modal="true"], ' +
            '[class*="report-plan" i], [class*="research-plan" i]'
        );
        let dialogHits = [];
        for (const d of dialogs) {
            const r = d.getBoundingClientRect();
            if (r.width < 200 || r.height < 100) continue;
            const found = findHitsIn(d);
            for (const h of found) dialogHits.push(h);
        }
        if (dialogHits.length > 0) {
            dialogHits.sort((a, b) => (hitScore(b) - hitScore(a)) || (b.top - a.top) || (a.len - b.len));
            return clickAndReturn(dialogHits[0].el, dialogHits.length, 'dialog');
        }

        // PASS 2 — global walk (existing logic). Recurses into Shadow DOM.
        const seen = new WeakSet();
        const hits = [];
        function walk(root) {
            if (!root || seen.has(root)) return;
            seen.add(root);
            const found = findHitsIn(root);
            for (const h of found) hits.push(h);
            // Recurse into shadow roots.
            try {
                for (const el of root.querySelectorAll('*')) {
                    if (el.shadowRoot) walk(el.shadowRoot);
                }
            } catch (e) {}
        }
        walk(document);
        if (!hits.length && deferredStructural) {
            // Everything with a success record has now declined. The structural
            // pick is better than pressing nothing, and its `why` says which
            // evidence carried it so a miss can be read afterwards.
            const picked = clickAndReturn(deferredStructural.el,
                                          deferredStructuralCount, 'structural');
            picked.anchor = 'structural';
            picked.why = (deferredStructural.named ? 'named' : '')
                + (deferredStructural.anim ? '+anim' : '')
                + (deferredStructural.inter ? '+inter' : '')
                + (deferredStructural.wordy ? '+wordy' : '')
                + (deferredStructural.clip ? '+clip' : '')
                + (deferredStructural.inTurn ? '+turn' : '')
                + (deferredStructural.weak ? '+staticonly' : '')
                + '+lastresort';
            return picked;
        }
        if (!hits.length) return {
            found: false, candidates: 0,
            // "nothing matched" and "nothing was looked at" are different
            // failures needing different fixes, and they were reported
            // identically. `partial` is its own answer: some roots were
            // scanned and some abandoned, so a wording change and an oversized
            // thread are BOTH still live explanations.
            reason: (DIAG.cappedRoots && !DIAG.walked) ? 'node_cap'
                  : DIAG.cappedRoots ? 'node_cap_partial'
                  : DIAG.roots ? 'no_match' : 'no_roots',
            walked: DIAG.walked, maxNodes: DIAG.maxNodes,
            cappedRoots: DIAG.cappedRoots, roots: DIAG.roots,
            structuralCapped: DIAG.structuralCapped, nodeCap: NODE_CAP,
            // 2026-08-06: how many candidates were refused for being report
            // prose. A run that presses nothing and a run that refused fifty
            // table cells are different situations and used to log identically.
            prose: DIAG.prose || 0,
            // 2026-08-20: PASS 0's own census. Without these the miss line's two
            // numbers both came from the WORDING walk, so eleven minutes of
            // "nothing matched" could not say whether the structural pass had
            // even run — and on 08-19 it had not.
            structRan: DIAG.structRan, structAnchor: DIAG.structAnchor,
            structSkip: DIAG.structSkip,
            structInBand: DIAG.structInBand, structOffBand: DIAG.structOffBand,
            structShape: DIAG.structShape, structProse: DIAG.structProse,
            structNoSignal: DIAG.structNoSignal,
            structQualified: DIAG.structQualified,
            structVia: DIAG.structVia };
        // Parent strip (verb+count) wins over badge child (count-only) via
        // hitScore; ties broken by lowest-on-page, then shortest text.
        hits.sort((a, b) => (hitScore(b) - hitScore(a)) || (b.top - a.top) || (a.len - b.len));
        return clickAndReturn(hits[0].el, hits.length, 'global');
    }"""
    # The miss diagnostic, kept across every context we try. Without this the
    # function threw away everything the JS reported and returned a constant,
    # so the caller could only guess why — and guessed wrong on an oversized
    # thread, which is the one cause a longer run makes MORE likely.
    _miss = {"found": False, "candidates": 0, "reason": "no_result", "contexts": 0}

    def _keep(cand, ctx_label):
        """Prefer the most actionable miss across host + frames.

        A node-cap miss outranks a no-match miss: it names a concrete cause,
        whereas 'nothing matched here' is the default answer from the twenty
        frames that were never going to hold the strip anyway.
        """
        nonlocal _miss
        seen = _miss.get("contexts", 0) + 1
        if not isinstance(cand, dict):
            _miss["contexts"] = seen
            return
        rank = {"node_cap": 3, "node_cap_partial": 2, "no_match": 1}
        first = _miss.get("reason") == "no_result"
        better = rank.get(cand.get("reason"), 0) > rank.get(_miss.get("reason"), 0)
        if first or better:
            _miss = {**cand, "found": False, "context": ctx_label}
        _miss["contexts"] = seen

    try:
        res = await page.evaluate(JS, bool(skip_structural))
        if res and res.get("found"):
            return res
        _keep(res, "host")
    except Exception as _he:
        _miss["error"] = f"{type(_he).__name__}: {_he}"
    # #913: enumerate ALL frames — the DR card's iframe URL no longer matches
    # any fixed substring (live 2026-07-06: walked_hits=0 every P2 cycle while
    # CUA could SEE the strip; the old "deep_research|oaiusercontent" filter
    # simply never visited the frame that renders it).
    try:
        for frame in [f for f in page.frames if f != page.main_frame][:20]:
            try:
                res = await frame.evaluate(JS, bool(skip_structural))
            except Exception:
                continue
            if res and res.get("found"):
                try:
                    res["frameUrl"] = (frame.url or "")[:120]
                except Exception:
                    pass
                return res
            _keep(res, "frame")
    except Exception:
        pass
    return _miss


# How many verified-failed presses the ChatGPT P2 activity panel gets before the
# poller stops trying. Phase 1 has had a ceiling of 3 since #913
# (`_panel_reopens`) and Claude P2 has the same (`claude_panel_reopens`, visible
# in the 2026-08-06 log as "click budget 1/3"). ChatGPT P2 was the only re-opener
# in the file with no ceiling at all, and it pressed the same wrong element
# twelve times across nineteen minutes.
_CHATGPT_PANEL_CLICK_BUDGET = 3

# How many consecutive EMPTY reads of a panel we never clicked open before the
# reader is believed over the pre-check. Two, not one: a real panel is sparse for
# its first sample or two, and #913 removed the old text floor precisely because
# bouncing a sparse-but-real panel restarted the toggle storm.
_CHATGPT_PANEL_BARE_LIMIT = 2


def _chatgpt_panel_stand_down_reason(p: dict, label: str) -> str:
    """Why the ChatGPT P2 poller should stop re-opening the activity panel.

    Returns a human sentence, or "" to keep trying. A pure function of the poll
    state so the polarity is testable without a browser — the previous
    stand-down lived inline and was keyed on the anchor LABEL reading "research
    complete", a condition that by construction cannot fire when the anchor is
    the wrong node.

    Mutates `p` only to record the label it compared against, which is what makes
    "the same wrong element twice" observable at all.
    """
    prev = p.get("chatgpt_last_panel_label")
    p["chatgpt_last_panel_label"] = label
    # ⚠ Counts PRESSES THAT VERIFIED NOTHING, not `chatgpt_panel_dom_misses`,
    # which also counts cycles where the walker found no candidate at all. Those
    # are benign — early in a run the strip has simply not rendered yet, and
    # budgeting them would stop the poller before the panel ever exists. What
    # needs a ceiling is pressing something and watching nothing happen.
    presses = int(p.get("chatgpt_panel_click_misses", 0) or 0)
    if presses >= _CHATGPT_PANEL_CLICK_BUDGET:
        return (f"{presses} presses verified nothing open "
                f"(budget {_CHATGPT_PANEL_CLICK_BUDGET})")
    if label and prev == label:
        # Pressing the same element again cannot produce a different result,
        # and the panel-open state is re-checked every cycle anyway — so this
        # costs nothing to obey and saves the rest of the phase.
        return f"the same element answered twice in a row: {label[:60]!r}"
    return ""


def _panel_miss_reason(res) -> str:
    """One human line saying what the opener actually saw.

    Replaces the caller's old assertion that the strip was "not yet rendered or
    wording changed" — a sentence that named two causes on evidence for
    neither, and was simply false whenever the walk had been abandoned.
    """
    res = res or {}
    reason = res.get("reason") or "no_result"
    cap = res.get("nodeCap")
    biggest = res.get("maxNodes")
    where = res.get("context", "?")
    if reason == "node_cap":
        return (f"the page was too large to scan — every root exceeded the "
                f"{cap}-node ceiling (largest {biggest}), so NOTHING was "
                f"examined; the strip may well be there")
    if reason == "node_cap_partial":
        return (f"partially scanned — {res.get('cappedRoots')} root(s) exceeded "
                f"the {cap}-node ceiling (largest {biggest}) and were skipped, "
                f"{res.get('walked')} nodes examined elsewhere with no match"
                + (" (including the structural pass)"
                   if res.get("structuralCapped") else ""))
    if reason == "no_match":
        _pr = int(res.get("prose") or 0)
        return (f"scanned {res.get('walked')} nodes across {res.get('roots')} "
                f"root(s) in {res.get('contexts')} context(s) and nothing "
                f"matched — strip not yet rendered or wording changed"
                # 2026-08-06: "nothing matched" and "everything that matched was
                # the agent's own report" are different pages and used to read
                # the same. Twelve presses landed on a markdown table cell.
                + (f" ({_pr} candidate(s) refused for being report prose)"
                   if _pr else "")
                + _chatgpt_structural_census(res))
    if reason == "no_roots":
        return "found no roots to scan at all — the thread DOM may not have mounted"
    if res.get("error"):
        return f"the DOM walk raised in the {where} context: {res['error']}"
    return "no result came back from the DOM walk"


def _chatgpt_structural_census(res) -> str:
    """What the STRUCTURAL pass saw, appended to a miss line.

    ⛔⛔ WHY THIS EXISTS. The 2026-08-19 P1 phase logged twenty-one identical
    misses over eleven minutes — `scanned 862 nodes … nothing matched` — while the
    vision tier described the shimmering row plainly visible on screen and spent
    all three of its escalations pressing it. Both numbers in that sentence
    (`walked`, `prose`) come from the WORDING walk; PASS 0 never touches either.
    So the line could not distinguish the three states that matter:

      * the pass never ran (its anchor was gone — the actual 08-19 cause),
      * it ran and no row reached its band,
      * it ran, rows reached the band, and every one failed the signal test.

    Twenty-one lines, three possibilities, no way to tell. A miss line that
    cannot name its own gate is how a viewport-relative anchor survived from
    2026-07-07 to 2026-08-20.

    Deliberately short: a per-tick DEBUG line is exactly where wave 2's log-flood
    lesson applies, so this adds one clause, not a table."""
    res = res or {}
    if not res.get("structRan"):
        why = res.get("structSkip") or "reason not recorded"
        return f" · structural pass DID NOT RUN ({why})"
    bits = [f"anchor={res.get('structAnchor') or '?'}",
            f"in-band={int(res.get('structInBand') or 0)}"]
    for key, name in (("structOffBand", "off-band"), ("structProse", "prose"),
                      ("structNoSignal", "no-signal"), ("structShape", "shape")):
        n = int(res.get(key) or 0)
        if n:
            bits.append(f"{name}={n}")
    return " · structural: " + ", ".join(bits)


async def _verify_chatgpt_panel_open(page):
    """#913: shape-agnostic — True when EITHER the P2 DR right-hand side
    panel OR the P1 Pro/ET inline thoughts drawer is open.

    History: the pre-#913 version demanded ≥280px width and ≥50 chars of
    text (side-panel JS now lives in `_CHATGPT_SIDE_PANEL_JS`, evaluated
    across ALL frames by `_chatgpt_activity_state`). The 2026-07 P1
    "Activity" panel is ~267px at our 1280px viewport and shows only
    skeleton rows early, so the verifier judged every successful click
    "failed" and the poll re-clicked the status line each cycle — toggling
    the panel closed (live 2026-07-06, 4 runs; user screenshot 2026-07-07
    is the ground truth). #906's rule still holds: this verifier must never
    be STRICTER than the scraper it guards —
    `scrape_chatgpt_activity_panel_tracking` reads both shapes."""
    st = await _chatgpt_activity_state(page)
    return bool(st.get("side_panel") or st.get("inline_expanded"))


async def scrape_progress_gemini(page):
    """Scrape Gemini's current research progress — rich data for web app.
    Selectors use multiple fallbacks — degrades gracefully on UI changes."""
    try:
        return await page.evaluate("""() => {
            const r = {
                status: 'unknown', phase: '', progress: '', thinking: '',
                sources: 0, source_urls: [], sections: [], steps: [],
                partial_text_len: 0, plan: '', title: '', model: '',
                panel_open: false, observed_sources: 0, searches: 0
            };
            // Conversation title (Gemini sets it once the chat has a topic)
            const gtitle = document.querySelector('[data-conversation-title], .conversation-title, bard-sidenav-mini-content [aria-current="true"]');
            if (gtitle) r.title = gtitle.innerText.substring(0, 100);
            else if (document.title) r.title = document.title.replace(/ - Gemini$/, '').substring(0, 100);
            // Research steps (Gemini shows a progress panel during Deep Research)
            const steps = document.querySelectorAll('.research-step, .step-content, [data-research-step], .activity-item');
            r.steps = Array.from(steps).map(s => s.innerText.substring(0, 150));
            if (r.steps.length > 0) r.progress = r.steps[r.steps.length - 1];

            // 2026-04-28 v6: structure-only panel walker — when Gemini's
            // Deep Research activity panel opens, the canonical class
            // selectors (.research-step, .activity-item) may not match the
            // current build. This walker mirrors Claude's panel walker:
            // any aside/role=complementary/role=region container > 220px
            // wide with substantial text content gets walked for leaf
            // rows with VERB-prefix or check/spin icons. Always runs as
            // an additive merge so brittle class-based scrape above keeps
            // working when it does.
            try {
                const VERBG = /^(checking|searching|looking|browsing|investigating|analyzing|reading|exploring|visiting|researching|thinking|reasoning|gathering|reviewing|consulting|comparing|evaluating|considering|drafting|writing|finalizing|finalising|summari[zs]ing)\\b/i;
                const panelRoots = document.querySelectorAll(
                    'aside, [role="complementary"], [role="region"], ' +
                    '[aria-label*="research" i], [aria-label*="sources" i], ' +
                    '[aria-label*="activity" i], [class*="research-panel" i], ' +
                    '[class*="side-panel" i], [class*="drawer" i]'
                );
                const seenRow = new Set();
                const rows = [];
                let live = '';
                let panelMatched = null;
                for (const root of panelRoots) {
                    const pr = root.getBoundingClientRect();
                    if (pr.width < 220 || pr.height < 150) continue;
                    if (pr.right < window.innerWidth * 0.45) continue;
                    panelMatched = root;
                    const rowEls = Array.from(root.querySelectorAll('li, [role="listitem"], div, p, button, [role="button"]'));
                    for (const el of rowEls) {
                        const t = (el.innerText || '').trim();
                        if (!t || t.length < 12 || t.length > 240) continue;
                        if (el.querySelector('li, [role="listitem"]')) continue;
                        if (t === t.toUpperCase() && t.length < 30) continue;
                        const wordChars = t.replace(/[^A-Za-z]/g, '').length;
                        if (wordChars < 8) continue;
                        if ((t.match(/\\n/g) || []).length > 3) continue;
                        const hasCheck = !!el.querySelector('svg[class*="check"], svg[data-icon*="check"], [aria-label*="completed" i]');
                        const hasSpin  = !!el.querySelector('svg[class*="spin"], svg[class*="loader"], [class*="animate-spin"], [aria-busy="true"]');
                        const verbHit  = VERBG.test(t);
                        const key = t.slice(0, 80);
                        if (seenRow.has(key)) continue;
                        seenRow.add(key);
                        rows.push({ t: t.slice(0, 220), hasSpin, hasCheck, verbHit });
                        if (hasSpin && !live) live = t.slice(0, 160);
                    }
                }
                if (rows.length > 0) {
                    // NOTE: this generic panel-walker tier does NOT set
                    // panel_open (Gemini's research is INLINE in the chat
                    // for the structural walker; treating those rows as
                    // a "side panel open" would mis-trigger panel-aware
                    // vision crops). The Show-thinking branch lower in
                    // the function sets r.thinking_visible (NOT panel_open)
                    // for the same reason — Gemini's thinking expander is
                    // inline below the response, full-width, not a side
                    // panel. The vision crop targets the right viewport
                    // edge; firing it on inline thinking would scrape the
                    // wrong region.
                    const panelSteps = rows.map(x => x.t).slice(-15);
                    r.steps = r.steps.concat(panelSteps).slice(-15);
                    if (live) r.progress = live;
                    else {
                        const verbLive = rows.find(x => x.verbHit && !x.hasCheck);
                        if (verbLive) r.progress = verbLive.t.slice(0, 160);
                        else if (rows.length) r.progress = rows[rows.length - 1].t.slice(0, 160);
                    }
                }
                // Also pull source URLs from the matched panel — Gemini's
                // panel includes sourced citations as a[href] entries.
                if (panelMatched) {
                    const panelSrcSet = new Set();
                    panelMatched.querySelectorAll('a[href^="http"]').forEach(a => {
                        const h = a.href || '';
                        if (h.length < 500 &&
                            !h.includes('google.com/gemini') &&
                            !h.includes('accounts.google') &&
                            !h.includes('gemini.google')) panelSrcSet.add(h);
                    });
                    if (panelSrcSet.size > 0) {
                        // We'll union with the global srcSet below.
                        r._panel_sources = Array.from(panelSrcSet);
                    }
                    // Searches count — Gemini DR's activity panel typically
                    // surfaces an aggregate "Searched N websites" / "N sites"
                    // line. Pick the largest number across the four common
                    // wordings so a transient lower count doesn't shrink the
                    // chip mid-run. Tracked separately from r.sources
                    // (URL-derived) for the unified FE chip.
                    try {
                        const panelText = (panelMatched.innerText || '');
                        const re = /(\\d+)\\s+(?:websites?|sources?|searches?|sites?)\\b/gi;
                        let mm; let best = 0;
                        while ((mm = re.exec(panelText)) !== null) {
                            const n = parseInt(mm[1], 10) || 0;
                            if (n > best) best = n;
                        }
                        if (best > 0) r.searches = best;
                    } catch(e) {}
                }
            } catch(e) {}
            // Research plan (shown before "Start research")
            const plan = document.querySelector('.research-plan, .plan-content');
            if (plan) r.plan = plan.innerText.substring(0, 1000);
            // Sources — Gemini Deep Research shows sources in research panel + response
            const srcSet = new Set();
            document.querySelectorAll(
                '.source-card, .citation, [data-source], .web-result, ' +
                '.research-source, [class*="source"], [class*="citation"], ' +
                // ⭐ 2026-08-20 — `gemini.google` EXCLUDED HERE TOO. The panel
                // walker below has always dropped Gemini's own URLs; this global
                // arm did not, so the conversation's own link counted as a
                // source. Two paths, one rule — the GUARD THE HOST lesson.
                'a[href*="http"]:not([href*="google.com/gemini"])'
                + ':not([href*="accounts.google"]):not([href*="gemini.google"])'
            ).forEach(s => {
                // ⛔⛔ 2026-08-20 — THE BROADEST ARM OF THE SELECTOR ABOVE WAS
                // DEAD. `a[href*="http"]…` matches ANCHORS, and this line then
                // asked each anchor for a CHILD anchor — `querySelector` searches
                // descendants only, so an <a> always answered null and every
                // match was dropped. Only the container arms (.source-card,
                // .citation, [class*="source"]…) could ever contribute a URL.
                // Found by reading, after the 08-19 run reported sources=0 on an
                // 82,817-character Gemini report; measured Gemini-only (this
                // idiom appears once in the file).
                // ⭐ The element itself when it IS the anchor, its descendant
                // otherwise. Can only ADD sources, never remove one.
                const a = (s.tagName === 'A') ? s
                        : (s.querySelector ? s.querySelector('a') : s);
                const href = a?.href || '';
                // ⛔⛔ 2026-08-20 — THE EXCLUSION IS ON THE RESOLVED URL, not on
                // the selector. The `:not(...)` list guards only the ANCHOR arm;
                // a container arm (.source-card, .citation, [class*="source"])
                // resolves to its inner <a> and had no equivalent guard, so a
                // `.source-card` wrapping accounts.google smuggled it in as a
                // citation. Measured through the shim the moment the anchor arm
                // started working. One rule, applied where the URL is — the same
                // GUARD THE HOST lesson that cost 56% of the sources once.
                // ⚠ THE BACKSLASHES ARE DOUBLED, and they must be: this JS
                // lives in a NON-RAW Python string, so what is written here is
                // not what reaches the browser. A single backslash before a dot
                // is an invalid Python escape — it survives today with a
                // DeprecationWarning and breaks outright on a later Python.
                // Same trap the Gemini stop regex hit on 08-19, where a lone
                // backslash-b became a literal BACKSPACE character and the
                // word-boundary match silently matched nothing at all.
                const SELF = /accounts\\.google|google\\.com\\/gemini|gemini\\.google/i;
                if (href.startsWith('http') && href.length < 500
                        && !SELF.test(href)) srcSet.add(href);
                // No innerText fallback: titles like "Read on Bloomberg" can't
                // be clicked and would inflate r.sources beyond what the FE
                // filtered URL list shows.
            });
            // Union with the panel-walker's URL haul (above) so URLs found
            // only inside the right-side research panel still flow through.
            let _panelSrcCount = 0;
            if (r._panel_sources) {
                const _before = srcSet.size;
                for (const u of r._panel_sources) srcSet.add(u);
                _panelSrcCount = srcSet.size - _before;
                delete r._panel_sources;
            }
            // ⛔ PROVENANCE, because the count alone cannot be diagnosed. The
            // 08-19 run reported Gemini sources as zero and there was no way to
            // tell an empty page from a blind selector from a panel that never
            // opened — the number is logged nowhere. `src_page` is the
            // document-wide scan, `src_panel` the research-panel walker.
            r.src_panel = _panelSrcCount;
            r.src_page = srcSet.size - _panelSrcCount;
            r.source_urls = Array.from(srcSet).slice(0, 200);
            r.sources = r.source_urls.length;
            // Response sections
            const headings = document.querySelectorAll(
                'message-content h1, message-content h2, message-content h3, ' +
                '.model-response-text h1, .model-response-text h2, .model-response-text h3, ' +
                '[class*="response"] h1, [class*="response"] h2'
            );
            r.sections = Array.from(headings).map(h => h.innerText.substring(0, 80)).filter(s => s.length > 1);
            // Per-section status — Gemini renders ✓ / spinner / pending icons
            // next to section headings in the Show-thinking panel. Capture
            // counts so FE narration can say "drafted 4/8 sections".
            try {
                let doneCount = 0;
                Array.from(headings).forEach(h => {
                    const parent = h.parentElement;
                    if (!parent) return;
                    const checkLike = parent.querySelector(
                        'svg[class*="check"], [aria-label*="complete" i], ' +
                        '[aria-label*="done" i], [class*="completed"]'
                    );
                    if (checkLike) doneCount++;
                });
                r.sections_done = doneCount;
                r.sections_total = r.sections.length;
            } catch(e) { r.sections_done = 0; r.sections_total = r.sections.length; }
            // Show-thinking expander detection — capture state in
            // r.thinking_visible (not panel_open) since Gemini's thinking
            // is INLINE below the response, not a right-side panel. The
            // narrate vision crop targets the right edge of the
            // viewport, which would be the wrong region here. Setting
            // panel_open=true would mis-trigger that crop. Use this flag
            // for FE narration context without invoking vision.
            try {
                const showThinkingBtn = Array.from(document.querySelectorAll('button'))
                    .find(b => /show thinking|hide thinking/i.test(b.textContent || ''));
                if (showThinkingBtn && /hide thinking/i.test(showThinkingBtn.textContent || '')) {
                    r.thinking_visible = true;
                }
            } catch(e) {}
            // Composite progress line — cite section progress + website
            // count when both are present. Mirrors Claude's artifact tracker
            // narration ("Tracking N sources from artifact") with Gemini's
            // data shape. Boosts narration quality on iter-#3+ when the
            // raw `r.progress` (live row) is short or missing.
            if (r.searches > 0 && r.sections.length > 0) {
                const liveSection = r.sections[r.sections.length - 1];
                const composite = `Researching ${r.searches} websites — currently on "${liveSection}"`;
                if (composite.length > (r.progress || '').length) r.progress = composite;
            } else if (r.searches > 0 && !r.progress) {
                r.progress = `Researching ${r.searches} websites`;
            }
            // Partial text
            const responses = document.querySelectorAll('message-content, .model-response-text');
            if (responses.length > 0) r.partial_text_len = responses[responses.length-1].innerText.length;
            // Status — robust stop button detection (multiple strategies)
            let isActive = false;
            // 1. aria-label selectors (multiple patterns)
            const stopSels = 'button[aria-label="Stop"], button[aria-label*="stop"], button[aria-label="Cancel"], button[title*="Stop"]';
            if (document.querySelector(stopSels)) isActive = true;
            // 2. Text-based: any button with "Stop" text
            if (!isActive) {
                const btns = document.querySelectorAll('button');
                for (const b of btns) {
                    const txt = (b.textContent || '').trim().toLowerCase();
                    if (txt === 'stop' || txt === 'stop generating' || txt === 'cancel') { isActive = true; break; }
                }
            }
            // 3. Streaming attribute (Gemini marks actively streaming content)
            if (!isActive && document.querySelector('[data-is-streaming="true"], .loading-indicator, .streaming')) isActive = true;
            // 4. Animation detection (spinning/pulsing elements indicate active work)
            // Use getAnimations() + playState === 'running' instead of CSS
            // animationName !== 'none'. CSS animationName remains set on
            // elements whose animations finished or never started, causing
            // persistent UI chrome (avatars, fade-ins) to read as active long
            // after generation completed.
            //
            // ⚠ 2026-08-19 — THIS TIER AND TIER 1 CARRY THE SAME TWO MISSES
            // detect_completion_gemini was just fixed for, and they are LEFT
            // ALONE ON PURPOSE. Tier 1's selector list is case-sensitive, so
            // `aria-label="Stop response"` matches nothing; this tier selects on
            // CLASS names while Gemini's live skeletons carry `pulse` in the
            // ANIMATION NAME. Both misses are real. What is NOT measured is
            // Gemini's DOM while it DRAFTS THE PLAN — and `isActive` feeds
            // `status`, which the 2D plan-wait reads as its streaming clock
            // (research.py ~51055): a status of 'generating' resets the clock and
            // can flip `_streaming_handoff`, which SKIPS the CUA recovery ladder
            // for a genuinely dead plan. So making this tier see more, off a
            // capture taken while research was already running, would change
            // the dead-plan recovery path on evidence that says nothing about
            // it. The completion detector had two captures; this needs its own.
            // ⇒ WANTED before touching this: a capture during PLAN DRAFTING
            // (running animation names + visibility, and whether a stop-ish
            // button exists), plus one of a FAILED plan.
            if (!isActive) {
                const animated = document.querySelectorAll('[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"]');
                for (const el of animated) {
                    if (el.offsetParent === null) continue;
                    if (typeof el.getAnimations !== 'function') continue;
                    const anims = el.getAnimations();
                    if (anims.some(a => a.playState === 'running')) { isActive = true; break; }
                }
            }
            // 5. Research progress panel still showing active steps
            if (!isActive && r.steps.length > 0) {
                const lastStep = r.steps[r.steps.length - 1].toLowerCase();
                if (lastStep.includes('searching') || lastStep.includes('reading') || lastStep.includes('analyzing') || lastStep.includes('browsing')) isActive = true;
            }
            // Planning-gate: if an ENABLED, VISIBLE "Start research" button is
            // showing, Gemini has produced a plan but research hasn't started —
            // do NOT mark complete even if r.partial_text_len > 0 (that text is
            // the plan, not output).
            // #953 (2026-07-13 root fix): require offsetParent (visible) AND
            // not-disabled — mirroring detect_completion_gemini's #948 Start
            // scan. Gemini AUTO-STARTS research and leaves the old plan bubble's
            // Start button in the DOM but DISABLED; the old text-only match kept
            // this gate forcing status='generating'/phase='planning' for the
            // WHOLE auto-started run — which (a) fed the 2D streaming clock so it
            // dwelt to the 900s cap, and (b) permanently gated off the L1 stuck
            // arbiter (status_is_active keys on phase=='planning'). A truly-dead
            // plan whose disabled skeleton Start lingers likewise read
            // 'streaming' forever. Only a real, clickable Start gates now.
            let hasStartBtn = false;
            const allBtns = document.querySelectorAll('button, [role="button"]');
            for (const b of allBtns) {
                if (b.offsetParent === null) continue;                       // hidden leftover
                if (b.disabled || b.getAttribute('aria-disabled') === 'true') continue;  // disabled skeleton / post-auto-start
                const txt = (b.textContent || '').trim().toLowerCase();
                const aria = ((b.getAttribute && b.getAttribute('aria-label')) || '').trim().toLowerCase();
                if (txt.includes('start research') || aria.includes('start research')) { hasStartBtn = true; break; }
            }
            if (hasStartBtn) {
                r.status = 'generating';
                r.phase = 'planning';
                if (!r.progress) r.progress = 'Research plan ready — awaiting Start';
            } else {
                r.status = isActive ? 'generating' : (r.partial_text_len > 0 ? 'complete' : 'idle');
                r.phase = isActive ? 'researching' : (r.steps.length > 0 ? 'researching' : (r.plan ? 'planning' : (r.partial_text_len > 0 ? 'done' : 'waiting')));
            }
            return r;
        }""")
    except Exception as e:
        log(f"Gemini scrape failed (selectors may need update): {e}", "WARN")
        return {"status": "scrape_error", "progress": "Selector mismatch — Gemini UI may have changed", "sources": 0, "partial_text_len": 0}


async def scrape_progress_claude(page):
    """Scrape Claude's current research progress — rich data for web app.

    Claude Research (2026) shows:
      - "Stop research" button (not "Stop Response") while active
      - "N sources and counting" text while gathering sources
      - "Research completed in Xm" card header when done
      - Research renders inside a card/artifact panel, not main chat stream
    We detect these text markers as primary activity signals."""
    try:
        return await page.evaluate("""() => {
            const r = {
                status: 'unknown', phase: '', progress: '', thinking: '',
                sources: 0, source_urls: [], sections: [], steps: [],
                tool_uses: [], partial_text_len: 0, plan: '', model: '', title: '',
                panel_open: false, searches: 0
            };
            // Conversation title
            const ctitle = document.querySelector('[data-conversation-title], .conversation-title, header h1, h1.truncate, [data-testid="conversation-title"]');
            if (ctitle) r.title = ctitle.innerText.substring(0, 100);
            else if (document.title) r.title = document.title.replace(/ - Claude$/, '').replace(/^Claude$/, '').substring(0, 100);
            // Model info
            const modelEl = document.querySelector('.model-selector, [data-testid="model-name"]');
            if (modelEl) r.model = modelEl.innerText.substring(0, 50);
            // Thinking content
            const thinking = document.querySelector('[data-is-thinking="true"], .thinking-content, .thinking-block');
            if (thinking) r.thinking = thinking.innerText.substring(0, 500);

            // ---- Text-based markers (Claude Research surfaces activity as text, not attributes)
            const bodyText = document.body?.innerText || '';
            const bodyLower = bodyText.toLowerCase();
            // "N sources and counting" → research actively gathering
            const srcCountM = bodyText.match(/(\\d[\\d,]*)\\s+sources?\\s+and\\s+counting/i);
            const liveSrcCount = srcCountM ? parseInt(srcCountM[1].replace(/,/g, ''), 10) : 0;
            // "Research completed in Xm" → research done
            // 2026-04-26: matches BOTH "research completed in 5m" (legacy)
            // AND "Research complete · 553 sources · 24m 41s" (modern 2026).
            // 2026-05-04: also Claude's 2026-05+ "Boom! Research report is
            // ready" callout — long DR runs ship this instead of the prefix.
            // ⭐ 2026-08-22 — the source count is now CAPTURED, not just matched.
            // This regex has matched "Research complete · 553 sources · 24m 41s"
            // since 2026-04-26 and thrown the 553 away every time, because the
            // digits sat in a non-capturing group and the match was only ever
            // read as a boolean. That number is the most authoritative source
            // figure Claude ever prints — it is the FINAL count, where the
            // ticker below is mid-run and disappears on completion — and 13 of
            // 22 finished runs in this machine's own logs recorded ZERO sources
            // while it was on the page.
            //
            // ⛔ The eight OTHER sites matching this shape were deliberately left
            // as booleans. They are completion GATES, the anchored-vs-loose split
            // between them is load-bearing (a stray edit there re-opens either a
            // 24-minute blind window or a mid-run false COMPLETE), and the number
            // is already available here — the one site that returns data. A
            // capture whose only consumer is `if (m)` buys nothing and risks the
            // gate.
            const doneM = bodyText.match(/research\\s+complete(?:d)?(?:\\s+in)?(?:[\\s·•—\\-]+(\\d[\\d,]*)\\s+sources?)?(?:[\\s·•—\\-]+\\d+(?:[hms]|\\s*(?:hour|min|sec)))?/i);
            const printedSrc = (doneM && doneM[1])
                ? parseInt(doneM[1].replace(/,/g, ''), 10) : 0;
            const boomM = bodyText.match(/\\bBoom!\\s+(?:Your\\s+)?[Rr]esearch\\s+report\\s+is\\s+ready\\b/);
            const researchDone = !!(doneM || boomM);

            // ---- Tool uses (Research tool, web_search, browse, etc.)
            const tools = document.querySelectorAll(
                '.tool-use-content, [data-tool-name], .tool-result, ' +
                '[class*="tool-use"], [class*="tool_use"], [data-testid*="tool"], ' +
                '.font-claude-message [class*="border"][class*="rounded"]'
            );
            r.tool_uses = Array.from(tools).map(t => {
                const name = t.getAttribute('data-tool-name') || '';
                const txt = (t.innerText || '').substring(0, 200);
                return name ? `${name}: ${txt}` : txt;
            }).filter(t => t.length > 3);

            // ---- Sources — citations, tool-result links, artifact links
            const srcSet = new Set();
            document.querySelectorAll('.font-claude-message a[href*="http"], .contents a[href*="http"]').forEach(a => {
                const href = a.href || '';
                if (href.startsWith('http') && !href.includes('claude.ai') && !href.includes('anthropic.com'))
                    srcSet.add(href);
            });
            document.querySelectorAll('[class*="tool"] a[href], .tool-result a[href]').forEach(a => {
                if (a.href?.startsWith('http') && !a.href.includes('claude.')) srcSet.add(a.href);
            });
            document.querySelectorAll('aside a[href*="http"], [class*="artifact"] a[href*="http"]').forEach(a => {
                if (a.href?.startsWith('http') && !a.href.includes('claude.')) srcSet.add(a.href);
            });
            // Broad research-card link sweep: any http link inside an element whose class/text
            // mentions "research" (research report lives inside card wrappers with dynamic classes)
            document.querySelectorAll('[class*="research"] a[href*="http"], [data-testid*="research"] a[href*="http"]').forEach(a => {
                if (a.href?.startsWith('http') && !a.href.includes('claude.')) srcSet.add(a.href);
            });
            r.source_urls = Array.from(srcSet).slice(0, 200);
            r.sources = r.source_urls.length;
            // Text-derived count from "N sources and counting" — kept SEPARATE
            // from r.sources because there are no URLs to attribute. Without
            // this split, the chip "5 src" disagreed with the empty URL list.
            // The watchdog can still consume r.observed_sources for liveness.
            r.observed_sources = liveSrcCount;
            // The FINAL printed count, kept beside the ticker rather than folded
            // into it. Two separate facts: the ticker proves the run is ALIVE
            // (28115 reads it for exactly that), the printed total proves how
            // many sources it ended with. Merging them would let a completed
            // count masquerade as liveness and pin a finished run at
            // "generating" forever.
            r.printed_sources = printedSrc;
            // Mirror onto the unified `searches` field so the FE has one
            // consistent name across all three agents. Claude's UI conflates
            // searches and sources ("N sources and counting") but the FE
            // chip still reads from r.searches for visual consistency.
            r.searches = liveSrcCount;

            // ---- Sections — headings restricted to artifact / aside /
            // research-panel scope. The .font-claude-message + .contents
            // selectors used to be here (2026-04-30 removed) but they
            // grabbed conversation-thread chrome ("# You said:", "# Claude
            // responded:") which got prepended with "Building: " at line
            // 7102 and contaminated r.steps[] / r.progress, then leaked
            // into narrator inputs as parroted "Claude responded: I'll
            // start by..." narration. Belt-and-suspenders chrome filter
            // on the .filter() line defends against any future selector
            // that re-introduces chat-thread headings.
            const headings = document.querySelectorAll(
                'aside h1, aside h2, aside h3, ' +
                '[class*="artifact"] h1, [class*="artifact"] h2, ' +
                '[class*="research"] h1, [class*="research"] h2, [class*="research"] h3'
            );
            r.sections = Array.from(headings)
                .map(h => (h.innerText || '').substring(0, 80))
                .filter(s => s.length > 1 &&
                             !/^(?:you|claude|chatgpt|gemini|notebooklm|gpt)\\s+(?:said|responded)\\b/i.test(s));

            // ---- Partial text — conversation + artifact + research card
            let textLen = 0;
            const msgs = document.querySelectorAll('.font-claude-message, .contents .prose');
            if (msgs.length > 0) textLen = msgs[msgs.length-1].innerText.length;
            const artifact = document.querySelector('aside .prose, aside [class*="content"], [class*="artifact-panel"] .prose');
            if (artifact) textLen = Math.max(textLen, artifact.innerText.length);
            // Research card container text (major content host when "Research" tool is used)
            const researchCard = document.querySelector('[class*="research-card"], [data-testid*="research"], [class*="research-report"]');
            if (researchCard) textLen = Math.max(textLen, (researchCard.innerText || '').length);
            r.partial_text_len = textLen;

            // ---- 2026-04-26 v3: extract artifact-1 CARD preview text BEFORE
            // the side panel opens. The card sits in the assistant message in
            // the conversation column with class containing "artifact" — title
            // + first ~5 visible checklist rows are visible here. Currently the
            // existing scrape only reads <a href> links from these wrappers;
            // we now also extract the card body text so steps[] / progress
            // populate from the first poll, not just after iter-#3 panel-open.
            try {
                const artifactCards = document.querySelectorAll(
                    '.font-claude-message [class*="artifact"]'
                );
                const cardLines = [];
                let cardTitle = '';
                for (const c of artifactCards) {
                    const t = (c.innerText || '').trim();
                    if (!t || t.length < 10) continue;
                    const lines = t.split('\\n').map(s => s.trim())
                                   .filter(s => s.length > 3 && s.length < 200);
                    if (!cardTitle && lines.length) cardTitle = lines[0];
                    for (const ln of lines.slice(1, 8)) cardLines.push(ln);
                }
                if (cardTitle && !r.title) r.title = cardTitle.slice(0, 100);
                cardLines.slice(0, 6).forEach(ln => r.steps.push(ln));
                if (cardLines.length > 0 && !r.progress) {
                    r.progress = cardLines[cardLines.length - 1];
                }
            } catch(e) {}

            // ---- 2026-04-26 v5: live panel walker — after the artifact panel
            // opens (aside / artifact-panel / research-panel mount), the panel
            // root contains the full live checklist. Structure-only gate
            // (no VERB/icon requirement) matches the ChatGPT P1 walker so
            // Reading-source rows and Searched-the-web rows both register.
            try {
                const VERB2 = /^(checking|searching|looking|browsing|investigating|analyzing|reading|exploring|visiting|researching|thinking|reasoning|gathering|reviewing|consulting|comparing|evaluating|considering|drafting|writing|finalizing|finalising|summari[zs]ing)\\b/i;
                const panelRoots = document.querySelectorAll('aside, [role="complementary"], [role="dialog"], [data-state="open"], [class*="artifact-panel"], [class*="research-panel"], [class*="side-panel" i], [class*="sidebar" i], [class*="drawer" i], [aria-label*="research" i], [aria-label*="sources" i], [aria-label*="activity" i]');
                const panelSeen = new Set();
                const panelRows = [];
                let panelLive = '';
                for (const root of panelRoots) {
                    const pr = root.getBoundingClientRect();
                    if (pr.width < 220 || pr.height < 150) continue;
                    const rowEls = Array.from(root.querySelectorAll('li, [role="listitem"], div, p, button, [role="button"]'));
                    for (const el of rowEls) {
                        const t = (el.innerText || '').trim();
                        if (!t || t.length < 12 || t.length > 240) continue;
                        if (el.querySelector('li, [role="listitem"]')) continue;
                        if (t === t.toUpperCase() && t.length < 30) continue;
                        const wordChars = t.replace(/[^A-Za-z]/g, '').length;
                        if (wordChars < 8) continue;
                        if ((t.match(/\\n/g) || []).length > 3) continue;
                        const hasCheck = !!el.querySelector('svg[class*="check"], svg[data-icon*="check"], [aria-label*="completed" i]');
                        const hasSpin  = !!el.querySelector('svg[class*="spin"], svg[class*="loader"], [class*="animate-spin"], [aria-busy="true"]');
                        const verbHit  = VERB2.test(t);
                        const key = t.slice(0, 80);
                        if (panelSeen.has(key)) continue;
                        panelSeen.add(key);
                        panelRows.push({ t: t.slice(0, 220), hasSpin, hasCheck, verbHit });
                        if (hasSpin && !panelLive) panelLive = t.slice(0, 160);
                    }
                }
                if (panelRows.length > 0) {
                    r.panel_open = true;
                    const panelSteps = panelRows.map(x => x.t).slice(-15);
                    r.steps = panelSteps.concat(r.steps);
                    if (panelLive) r.progress = panelLive;
                    else {
                        const verbLive = panelRows.find(x => x.verbHit && !x.hasCheck);
                        r.progress = verbLive ? verbLive.t.slice(0, 160)
                                              : panelRows[panelRows.length - 1].t.slice(0, 160);
                    }
                }
            } catch(e) {}

            // ---- Steps: synthesize from tool_uses + live markers + sources
            if (r.thinking) r.steps.push('Thinking: ' + r.thinking.substring(0, 100));
            r.tool_uses.slice(-5).forEach(t => {
                const brief = t.substring(0, 120);
                r.steps.push(brief.toLowerCase().includes('earch') ? 'Searching: ' + brief : brief);
            });
            if (liveSrcCount > 0) r.steps.push(`Gathering sources (${liveSrcCount} and counting)`);
            const cHosts = new Set();
            r.source_urls.forEach(u => { try { cHosts.add(new URL(u).hostname.replace('www.', '')); } catch(e) {} });
            Array.from(cHosts).slice(0, 5).forEach(h => r.steps.push('Browsing ' + h));
            if (r.sections.length > 0) r.steps.push('Building: ' + r.sections[r.sections.length - 1]);
            if (r.partial_text_len > 3000) r.steps.push('Artifact: ' + Math.round(r.partial_text_len / 1000) + 'k chars');
            if (researchDone) r.steps.push('Research completed');

            if (r.tool_uses.length > 0) r.progress = r.tool_uses[r.tool_uses.length - 1].substring(0, 200);
            else if (r.steps.length > 0) r.progress = r.steps[r.steps.length - 1];
            else if (liveSrcCount > 0) r.progress = `${liveSrcCount} sources and counting`;

            // Plan
            if (r.sections.length >= 2) r.plan = 'Research structure: ' + r.sections.slice(0, 5).join(' \\u2192 ');

            // ---- Status resolution (multi-strategy)
            // 1. "Stop research" / "Stop" button — primary active signal
            let hasStop = false;
            const btns = document.querySelectorAll('button');
            for (const b of btns) {
                const txt = (b.textContent || '').trim().toLowerCase();
                const al  = (b.getAttribute('aria-label') || '').toLowerCase();
                if (txt === 'stop' || txt === 'stop generating' || txt === 'stop research' ||
                    txt === 'stop researching' ||
                    al.includes('stop response') || al.includes('stop research') ||
                    al.includes('stop generating')) { hasStop = true; break; }
            }
            // 2. Streaming DOM markers
            if (!hasStop && document.querySelector('[data-is-streaming="true"], .streaming, [class*="animate-pulse"]')) hasStop = true;
            // 3. "sources and counting" → still gathering (active)
            if (!hasStop && liveSrcCount > 0) hasStop = true;
            // 4. Body keyword sweep for active research verbs
            if (!hasStop) {
                const activeKws = ['searching the web', 'analyzing sources', 'reading sources',
                                   'browsing', 'conducting research', 'gathering information'];
                if (activeKws.some(kw => bodyLower.includes(kw))) hasStop = true;
            }

            // Resolve status — completion text trumps stale "active" signals
            if (researchDone && !hasStop) {
                r.status = 'complete'; r.phase = 'done';
            } else if (hasStop) {
                r.status = 'generating';
                r.phase = r.thinking ? 'thinking' : (r.tool_uses.length > 0 || liveSrcCount > 0 ? 'researching' : 'generating');
            } else if (r.partial_text_len > 0 || r.sources > 0) {
                r.status = 'complete'; r.phase = 'done';
            } else {
                r.status = 'idle'; r.phase = 'waiting';
            }
            return r;
        }""")
    except Exception as e:
        log(f"Claude scrape failed (selectors may need update): {e}", "WARN")
        return {"status": "scrape_error", "progress": "Selector mismatch — Claude UI may have changed", "sources": 0, "partial_text_len": 0}


SCRAPE_FNS = {
    "ChatGPT": scrape_progress_chatgpt,
    "Gemini": scrape_progress_gemini,
    "Claude": scrape_progress_claude,
    "Phase1": scrape_progress_chatgpt,  # Phase 1 runs on ChatGPT
}


# ── Per-Agent Completion Detectors (Playwright-only) ──────────────────────────
# Atomic single-shot detectors for the round-robin loop. Each returns
# (done: bool, reason: str). Reason is a short string for logging/telemetry.
# The caller tracks "2 consecutive polls" semantics where required — detectors
# just report the current signal snapshot from a single poll.
#
# Rules (locked 2026-04 with Phase 2 orchestration overhaul):
#   ChatGPT: no Stop (host + iframe) AND ("Research completed" text OR partial>5000)
#   Claude : no Stop/"sources and counting" AND
#            (artifacts>=2 OR done-text OR (partial>8000 AND summary/conclusion heading))
#   Gemini : no Start-research AND no Stop AND
#            (Share/Export visible OR (partial>5000 AND no active keywords))

def _chatgpt_surface_frame_targets(page, *, include_blank=True):
    """`include_blank=False` restores the pre-2026-08-06 reach (the DR sandbox
    URL substrings only).

    ⭐⭐ WIDENING SHARED REACH IS A CHANGE TO EVERY CALLER, and on 2026-08-06 I
    made it a default. Five consumers changed behaviour at once, and one of them
    — `scrape_progress_chatgpt` — CLICKS inside the frames it walks. So a fix
    aimed at the completion detector started dispatching synthetic clicks into a
    surface nothing had ever clicked before, on every poll tick, and the next run
    produced a panel failure nobody could attribute with confidence.
    ⛔ The lesson is not "the wider list was wrong" — it demonstrably fixed the
    33-minute blind run. It is that reach must be chosen BY THE CALLER, so a
    reader can see more without a clicker also reaching further.
    """
    """Every browsing context ChatGPT's Deep Research surface can occupy.

    ⭐⭐ 2026-08-06 — THE FILTER THAT NEVER VISITED THE FRAME. `#913` already
    learned this once, for the activity-panel opener: "the DR card's iframe URL no
    longer matches any fixed substring (live 2026-07-06: walked_hits=0 every P2
    cycle while CUA could SEE the strip; the old `deep_research|oaiusercontent`
    filter simply never visited the frame that renders it)". That fix was made in
    ONE consumer. Five others kept the substring list, and on 2026-08-06 the
    completion detector was one of them:

        frames: [ chatgpt.com/c/<id>,
                  chatgpt.com/backend-api/sentinel/frame.html,
                  connector-openai-deep-research.web-sandbox.oaiusercontent.com,
                  about:blank ]

    The old filter matched the CONNECTOR SHELL (it contains "oaiusercontent"),
    evaluated it, found nothing, and `break`ed — so `about:blank`, where the
    surface actually lived, was never visited. Same tick, same page: the panel
    tracker (which walks every frame) read 26 source URLs while the detector read
    `sources: 0`. 33 minutes of `no_done_marker` on a finished report.

    So this accepts the DR sandbox substrings AND the shapes a URL filter cannot
    describe — `about:`, `blob:`, and empty — exactly as
    `_claude_artifact_frame_targets` already does for Claude's srcdoc artifacts.
    Bounded to 20 frames, the same bound the panel walkers use.
    """
    targets = [page]
    try:
        for frame in page.frames:
            if len(targets) > 20:
                break
            try:
                if frame is page.main_frame:
                    continue
                src = (frame.url or "").lower()
            except Exception:
                continue
            _sandbox = ("deep_research" in src
                        or "oaiusercontent" in src
                        or "web-sandbox.oaiusercontent" in src)
            _blank = (src.startswith("about:") or src.startswith("blob:")
                      or src == "")
            if _sandbox or (include_blank and _blank):
                targets.append(frame)
    except Exception:
        pass
    return targets


# ⭐ ONE payload, run in EVERY context — see `_chatgpt_surface_frame_targets`.
# It used to be two: a rich probe inlined in the host branch and a thin one in
# the iframe branch that computed only `thoughtFor` and `researchDone`. The two
# markers added 2026-07-13 *specifically for the finished-canvas layout* —
# `completedChip` and `docPanelAffordances` — existed on the host path only, so
# even a widened frame filter could not have seen the markers that layout renders.
# A guard on one of two paths to the same sink; the recurring shape in this file.
#
# Module-level rather than inlined so a test can execute it against a captured
# DOM. While it lived inside the function body it had never once been run by a
# test, which is how a probe that reads an empty document survived two E2E runs.


# ⭐ 2026-08-12 — ONE SOURCE FOR THE THINKING-TIME BADGE, TWO ENGINES.
#
# ChatGPT's finished-response header ("Thought for 1m 14s", and since 2026-08 also
# "Worked for 9m") is read in FIVE places: `_classify_completion_verdict` in
# Python, and four page-side checks in JS. On 2026-08-11 the Python side was
# widened from the single literal "thought for" to the verb family — and the four
# JS copies were not. So the vision classifier could recognise "Worked for 16m 26s"
# while `verify_chatgpt_generating`, looking at the SAME page, could not; that
# split is what made the 2026-08-12 P1 run poll for 44 minutes past a finished
# brief. Two spellings of one page label is the bug, so there is now one spelling.
#
# The source below is shared verbatim: `re.compile()` reads it as a Python pattern
# and `new RegExp()`-equivalent literals read it as JS. Every construct in it
# (`\b`, `(?:…)`, `\s`, `\d`, `+`, `*`) means the same thing in both engines, and
# it contains no `/`, so it needs no re-escaping to sit inside a JS literal.
#
# ⛔ THE TIME UNIT IS LOAD-BEARING, and it is what makes widening the verb family
# safe. "thought for 3" is vanishingly rare in prose, but a research brief writes
# "worked for 3 years" and "researched for 5 months" as ordinary sentences — so
# the moment the verb family widened, a unitless match would have turned the
# report's own text into a completion marker. That is a false-COMPLETE, which
# every note in this file records as the strictly worse failure.
#
# Full history and the cost-asymmetry argument: `_THINKING_TIME_HEADER`.
_THINKING_TIME_HEADER_SRC = (
    r"\b(?:thought|worked|reasoned|researched)\s+for\s+\d+\s*"
    r"(?:hours|hour|hrs|hr|h|minutes|minute|mins|min|m|seconds|second|secs|sec|s)\b")

# The same pattern as a JS regex literal, for the page-side checks that run inside
# `page.evaluate`. Derived rather than retyped: a second hand-written copy is the
# defect this constant exists to end.
_THINKING_TIME_HEADER_JS = f"/{_THINKING_TIME_HEADER_SRC}/i"

_CHATGPT_DONE_PROBE_JS = """() => {
    let hasStop = !!document.querySelector(
        'button[aria-label="Stop generating"], button[aria-label*="Stop"], ' +
        'button[data-testid="stop-button"], button[data-testid*="stop"]'
    );
    if (!hasStop) {
        for (const b of document.querySelectorAll('button')) {
            const t = (b.textContent || '').trim().toLowerCase();
            const al = (b.getAttribute('aria-label') || '').toLowerCase();
            if (t === 'stop' || t === 'stop generating' || t === 'stop research' ||
                al.includes('stop')) { hasStop = true; break; }
        }
    }
    const bl = (document.body?.innerText || '');
    // The thinking-time badge — renders only AFTER the thinking phase
    // completes. With Stop button gone + this badge present, we're as
    // confident as we can be that DR is fully settled.
    // 2026-08-12: was the single literal /thought for\\s+\\d/i, which stopped
    // matching when ChatGPT relabelled it "Worked for 9m". Now the shared
    // pattern — see _THINKING_TIME_HEADER_SRC for why there is only one.
    const thoughtFor = __DONE_BADGE_RE__.test(bl);
    // 2026-04-26 backup: same modern marker Claude uses. Covers the case
    // where ChatGPT renames the badge or runs a non-thinking-mode DR
    // variant where "Thought for X" never appears. Either signal counts.
    // ⚠ This is the LOOSE marker — it is why Python only lets it count in the
    // main frame. See `detect_completion_chatgpt`.
    const researchDone = /research\\s+complete(?:d)?(?:[\\s·•—\\-]+\\d[\\d,]*\\s+sources?)?/i.test(bl);
    // 2026-07-13: the completed chip lives in a node innerText
    // EXCLUDES (collapsed drawer header / virtualized) — textContent
    // includes hidden nodes, and the anchored tails make it done-only
    // ("Researching · Xm" is the mid-run form; "completed in Xm" /
    // "complete · N citations" render only when DR has finished).
    const btc = (document.body?.textContent || '');
    const completedChip =
        /research\\s+complete(?:d)?\\s+in\\s+\\d+\\s*[hms]/i.test(btc) ||
        /research\\s+complete(?:d)?\\s*[·•]\\s*\\d[\\d,]*\\s+(?:citations?|sources?)/i.test(btc);
    // 2026-07-13 (rev 2, user-directed): the finished DR document/
    // canvas panel's HEADER STRIP carries a DOWNLOAD button — that
    // swap (Researching panel → Document panel with a download
    // affordance) IS the done signal; no need to open or scroll the
    // document. The DOWNLOAD BUTTON ALONE is sufficient.
    //
    // rev 1 (same day) required download AND an expand/enlarge button,
    // but ChatGPT's real canvas header is download + SHARE (not
    // download + expand — live screenshot 2026-07-13), so the AND
    // missed every finished canvas: the detector logged "doc-panel
    // affordances all missing" at the SAME tick the CUA screenshot read
    // "download (↓) and share/expand buttons — no stop button", and the
    // poller burned 17+ min scroll-checking a document that was done.
    // Also dropped the r.left >= 22%vw right-docked floor: when DR
    // finishes on the canvas layout the document is NEAR-FULL-WIDTH
    // (only the thin icon rail to its left), so a left-position floor
    // excluded the very layout this signal is for. Right-edge anchor +
    // min width + tall + header-only + the (pre-checked) no-stop gate
    // keep it specific to the finished document surface.
    const vw = window.innerWidth || document.documentElement.clientWidth;
    const vh = window.innerHeight || document.documentElement.clientHeight;
    let docPanelAffordances = false;
    let panelLen = 0;
    for (const el of document.querySelectorAll('div, aside, section')) {
        const r = el.getBoundingClientRect();
        if (r.width < 380) continue;            // a real panel, not a toolbar/widget
        if (r.right < vw - 40) continue;        // anchored to the right edge (canvas / doc panel)
        if (r.height < vh * 0.5) continue;      // tall — a document surface
        let hasDl = false;
        for (const b of el.querySelectorAll('button, [role="button"]')) {
            const br = b.getBoundingClientRect();
            if (br.top > r.top + 96) continue;      // header strip only
            const t = ((b.getAttribute('aria-label') || '') + ' ' +
                       (b.getAttribute('title') || '') + ' ' +
                       (b.getAttribute('data-testid') || '')).toLowerCase();
            if (/download/.test(t)) { hasDl = true; break; }
        }
        if (hasDl) {
            docPanelAffordances = true;
            // ⭐ 2026-08-06: MEASURE THE SURFACE WE JUST FOUND. `assistantLen`
            // below reads the conversation turn, and on the canvas layout there
            // is no assistant turn in this document at all — which is how
            // `text_len` reported 0 on a page carrying a finished report. The
            // caller's 2-cycle flatness gate needs a number that moves.
            panelLen = Math.max(panelLen, (el.innerText || '').length);
            break;
        }
    }
    const msgs = document.querySelectorAll('[data-message-author-role="assistant"]');
    const assistantLen = msgs.length ? msgs[msgs.length - 1].innerText.length : 0;
    // Sources count: external citation links anywhere in THIS document.
    const sources = document.querySelectorAll('a[href^="http"][target="_blank"]').length;
    // Steps: research card list items (the rotating step list)
    const steps = document.querySelectorAll(
        '[class*="research"] li, [class*="step"], [class*="task"]'
    ).length;
    return { hasStop, thoughtFor, researchDone, completedChip, docPanelAffordances,
             assistantLen, panelLen, bodyLen: bl.length, sources, steps, vw, vh };
}""".replace("__DONE_BADGE_RE__", _THINKING_TIME_HEADER_JS)

# A non-main context must be a real surface before its download-button scan may
# call the run finished. The geometry inside a frame is FRAME-relative, so
# `r.right >= vw - 40` and `r.height >= vh * 0.5` are trivially true inside a
# 200x100 telemetry blank — and a false done publishes a report. The main frame
# is exempt: it is the surface by definition, and gating it would change the
# behaviour of the marker that has been shipping since 2026-07-13.
_CHATGPT_FRAME_SURFACE_MIN_VW = 600
_CHATGPT_FRAME_SURFACE_MIN_VH = 400


async def detect_completion_chatgpt(page):
    """ChatGPT Deep Research completion detector. Playwright-only.
    Returns (done, reason, snap) where snap = {text_len, sources, steps}.

    2026-04-25 strictness rewrite: detector returns done=True ONLY when:
      • Stop button is gone (every context)
      • a done marker is present
    The previous `partial_len > 5000` fallback was a known false-positive
    path (fired mid-stream during long research). Removed entirely. The
    caller is responsible for the 2-cycle flatness gate (text/sources/steps
    all flat across 2 polling cycles) before extracting — we only report
    the snapshot here, never decide on flatness.

    2026-07-13 (two E2E runs, detector blind past completion — 10 min on
    the chip layout, 30+ min on the canvas layout until the user stopped):
    added `completedChip` (matched on textContent, which includes the
    collapsed/virtualized node innerText excludes) and `docPanelAffordances`
    (the Researching panel being REPLACED by a Document panel with a download
    button in its header IS the done signal). Both live in
    `_CHATGPT_DONE_PROBE_JS`, with their full rationale.

    2026-08-06 — RUN THE SAME PROBE IN EVERY CONTEXT, AND COMBINE. See
    `_chatgpt_surface_frame_targets` for the 33-minute blind run that forced
    this. Three rules govern the combination:

      • `hasStop` is a VETO and counts from anywhere — a stop button in any
        context means the run is live.
      • Every done marker counts from anywhere EXCEPT `researchDone`, the loose
        `/research complete/i` innerText form, which stays main-frame-only. The
        canvas frame holds the report *prose*, and a report about research may
        well contain that phrase; the anchored `completedChip` forms carry a
        duration or a citation count and cannot.
      • `docPanelAffordances` from a non-main context additionally requires that
        context to be a real surface (see `_CHATGPT_FRAME_SURFACE_MIN_VW`).

    The reason string names the context that supplied the marker, so the next
    drift is one grep rather than a code read.
    """
    try:
        targets = _chatgpt_surface_frame_targets(page)
        readings = []
        for target in targets:
            is_host = target is page
            try:
                data = await target.evaluate(_CHATGPT_DONE_PROBE_JS)
            except Exception:
                continue
            if not isinstance(data, dict):
                continue
            try:
                ctx = "host" if is_host else ((target.url or "about:blank")[:60])
            except Exception:
                ctx = "host" if is_host else "frame"
            readings.append((ctx, is_host, data))
        if not readings:
            return (False, "detect_error: no evaluable context", {})

        def _num(d, key):
            try:
                return int(d.get(key) or 0)
            except Exception:
                return 0

        def _surface(is_host, d):
            """May this context's doc-panel scan speak for the whole run?"""
            return is_host or (_num(d, "vw") >= _CHATGPT_FRAME_SURFACE_MIN_VW
                               and _num(d, "vh") >= _CHATGPT_FRAME_SURFACE_MIN_VH)

        has_stop = any(bool(d.get("hasStop")) for _c, _h, d in readings)

        # (marker name, does this reading carry it) — first hit names the reason.
        marker_from = ""
        which_marker = ""
        for name, pred in (
            ("thought_for", lambda h, d: bool(d.get("thoughtFor"))),
            ("completed_chip", lambda h, d: bool(d.get("completedChip"))),
            ("doc_panel_affordances",
             lambda h, d: bool(d.get("docPanelAffordances")) and _surface(h, d)),
            ("research_complete", lambda h, d: h and bool(d.get("researchDone"))),
        ):
            for ctx, is_host, d in readings:
                if pred(is_host, d):
                    which_marker, marker_from = name, ctx
                    break
            if which_marker:
                break
        has_done_marker = bool(which_marker)

        # `text_len` is what the caller's flatness gate watches. A non-main
        # context IS the surface, so its whole body counts there; in the main
        # frame the body would drag in the sidebar's conversation list, so only
        # the assistant turn and the document panel do.
        partial_len = 0
        sources = 0
        steps = 0
        for _ctx, is_host, d in readings:
            lens = [_num(d, "assistantLen"), _num(d, "panelLen")]
            if not is_host:
                lens.append(_num(d, "bodyLen"))
            partial_len = max([partial_len] + lens)
            sources = max(sources, _num(d, "sources"))
            steps = max(steps, _num(d, "steps"))
        snap = {"text_len": partial_len, "sources": sources, "steps": steps}

        ctxs = ",".join(c for c, _h, _d in readings)
        if has_stop:
            return (False, f"stop_btn_present (text={partial_len}, src={sources}, st={steps})", snap)
        if not has_done_marker:
            return (False, "no_done_marker (Thought-for badge, Research-complete text, "
                           f"completed chip AND doc-panel affordances all missing; ctx={ctxs})", snap)
        return (True, f"no_stop + done_marker={which_marker} ctx={marker_from}", snap)
    except Exception as e:
        return (False, f"detect_error: {e}", {})


async def detect_completion_claude(page):
    """Claude Research completion detector. Playwright-only.
    Returns (done, reason, snap) where snap = {text_len, sources, steps}.

    2026-04-25 strictness rewrite: detector returns done=True ONLY when:
      • Stop button gone + no live "sources and counting" indicator
      • "research completed" text present OR research-card status='complete'
    Removed: artifacts>=2 fallback (Claude legitimately produces 2 artifacts
    pre-final), text_len>8000+heading fallback (mid-stream summary headings
    can match). Caller handles 2-cycle flatness.

    2026-07-11 (FIFA run, detector blind 15:01→15:26 — 24 min):
      • liveActive DEMOTED below the done-markers. The poll loop keeps the
        research-TRACKING artifact panel open (keep_open=True), and its
        "N sources and counting" ticker text persists in body.innerText
        after completion — with liveActive as the first unconditional gate
        the detector returned live_sources_counting every tick while the
        SAME body text carried "Research complete · N sources" (proven: the
        CUA-branch marker probe matched at 15:26). A present done-marker
        now overrides the stale ticker; liveActive only vetoes on its own.
      • Snapshot re-rooted on the #914 geometry panel scan. The 2026-07
        claude.ai panel carries no artifact class names and the only
        <aside> is the LEFT NAV, so every legacy class/aside selector read
        0/0/0 (snap all zeros) while the geo walker read 16 URLs/15 steps
        from the same document in the same tick — and the all-zeros snap
        made the #921 empty-snapshot guard structurally refuse done. Same
        never-back-ported pattern as the animation guard note below.
      • NEW artifact-header affordance marker (user-suggested): a finished
        Document artifact's panel header shows Copy (+ download chevron)
        AND Publish/Share. Both present inside the geo panel counts as a
        done-marker — but ONLY when the live ticker is absent, so a
        mid-research tracking panel can never confirm through it."""
    try:
        data = await page.evaluate("""() => {
            let hasStop = false;
            for (const b of document.querySelectorAll('button')) {
                const txt = (b.textContent || '').trim().toLowerCase();
                const al  = (b.getAttribute('aria-label') || '').toLowerCase();
                if (txt === 'stop' || txt === 'stop generating' || txt === 'stop research' ||
                    txt === 'stop researching' ||
                    al.includes('stop response') || al.includes('stop research') ||
                    al.includes('stop generating')) { hasStop = true; break; }
            }
            if (!hasStop && document.querySelector('[data-is-streaming="true"]')) hasStop = true;
            // 2026-07-10: count an ANIMATION as "still streaming" ONLY when the
            // element is VISIBLE (offsetParent) AND its animation is actually
            // RUNNING. The prior bare `[class*="animate-pulse"], .streaming`
            // selector false-positived on persisted-but-completed shimmer / hidden
            // skeleton chrome that Claude leaves in the DOM after a research
            // completes — pinning hasStop=true forever, so detect returned
            // "stop_btn_present" on a genuinely-done report and completion fell to
            // the slow 5-min CUA fallback (stuck-despite-complete, live E2E
            // 2026-07-10). This is the exact guard verify_claude_generating
            // adopted 2026-05-14 (research.py:19872) but never back-ported here.
            if (!hasStop) {
                for (const el of document.querySelectorAll(
                    '[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"], .streaming'
                )) {
                    if (el.offsetParent === null) continue;                 // not visible
                    if (typeof el.getAnimations !== 'function') continue;
                    if (el.getAnimations().some(a => a.playState === 'running')) { hasStop = true; break; }
                }
            }

            const bodyText = document.body?.innerText || '';
            // 2026-04-26: matches BOTH "research completed in 5m" (legacy)
            // AND "Research complete · 553 sources · 24m 41s" (modern 2026
            // layout). 2026-05-04: also "Boom! Research report is ready".
            // 2026-07-11 (review r2): split into ANCHORED (requires the
            // "· N sources" tail or the Boom! callout — cannot match prose)
            // vs LOOSE. Only the anchored form may override a live ticker
            // below; the loose form gained a \\b so "the research completes"
            // (Claude's own launch prose) no longer matches.
            const anchoredDone = /research\\s+complete(?:d)?\\s*[\\s·•—\\-]+\\d[\\d,]*\\s+sources?/i.test(bodyText)
                              || /\\bBoom!\\s+(?:Your\\s+)?[Rr]esearch\\s+report\\s+is\\s+ready\\b/.test(bodyText);
            const researchDone = anchoredDone
                              || /research\\s+complete(?:d)?\\b/i.test(bodyText);
            const liveActive = /\\d[\\d,]*\\s+sources?\\s+and\\s+counting/i.test(bodyText);
            // Claude's research card flips status when streaming ends.
            // 2026-04-26: also accept TEXT-CONTENT match — Claude's modern
            // layout doesn't use [data-research-status]; the artifact card
            // shows "Research complete · N sources · Xm Ys" as visible text.
            let researchCardDone = !!document.querySelector(
                '[data-research-status="complete"], [data-research-state="done"]'
            );
            if (!researchCardDone) {
                researchCardDone = !!Array.from(
                    document.querySelectorAll('[class*="card"], [class*="artifact"], button, div[role="button"]')
                ).find(el => /research\\s+complete(?:d)?\\s*[\\s·•—\\-]/i.test(el.textContent || ''));
            }
            // 2026-05-04: Claude's 2026-05+ artifact card drops the "complete"
            // prefix and shows just "<Title> · N sources · Xh Ym". Body-text
            // matching that pattern is too greedy (mid-stream pages can render
            // separate elapsed-timer + source-count elements that look the
            // same when flattened to innerText). Scope to artifact/aside
            // containers — those only render this title post-completion.
            if (!researchCardDone) {
                researchCardDone = !!Array.from(document.querySelectorAll(
                    '.font-claude-message [class*="artifact"], aside [class*="artifact"], aside [class*="card"]'
                )).find(el => /[\\s·•—\\-]+\\d[\\d,]*\\s+sources?\\s*[\\s·•—\\-]+\\d+\\s*[hms]/i.test(el.innerText || ''));
            }

            let textLen = 0;
            const msgs = document.querySelectorAll('.font-claude-message, .contents .prose');
            if (msgs.length > 0) textLen = msgs[msgs.length-1].innerText.length;
            const artifact = document.querySelector(
                'aside .prose, aside [class*="content"], [class*="artifact-panel"] .prose'
            );
            if (artifact) textLen = Math.max(textLen, artifact.innerText.length);
            const researchCard = document.querySelector(
                '[class*="research-card"], [data-testid*="research"], [class*="research-report"]'
            );
            if (researchCard) textLen = Math.max(textLen, (researchCard.innerText || '').length);

            let sources = document.querySelectorAll(
                '.font-claude-message a[href^="http"], aside a[href^="http"]'
            ).length;
            let steps = document.querySelectorAll(
                '[class*="research"] li, [class*="step"]'
            ).length;

            // 2026-07-11 #914 back-port: geometry panel root — same gates as
            // _bestGeoPanel / _claude_artifact_panel_state (right-docked,
            // 380px..0.75vw, left ≥ 0.22vw, flush right, ≥ 0.5vh, no chat
            // markers). The legacy class/aside selectors above read 0/0/0 on
            // the 2026-07 layout; the geo root feeds real numbers into the
            // snap so the #921 empty-snapshot guard judges actual content.
            // (review r2) legacyEmpty is captured BEFORE the geo merge and
            // geoIsTracker flags a tracking-shaped panel, so the Python side
            // can refuse a done verdict whose ONLY content evidence is the
            // kept-open tracking panel with no anchored marker — otherwise
            // the geo numbers structurally disarm the #921 guard.
            const legacyEmpty = (textLen === 0 && sources === 0 && steps === 0);
            const vw = window.innerWidth || document.documentElement.clientWidth;
            const vh = window.innerHeight || document.documentElement.clientHeight;
            const CHAT_MARKERS = '[data-message-author-role="user"], ' +
                '[data-testid="user-message"], .font-claude-message';
            let geoPanel = null, geoLen = -1, geoArea = Infinity;
            for (const el of document.querySelectorAll('div, aside, section')) {
                const r = el.getBoundingClientRect();
                if (r.width < 380 || r.width > vw * 0.75) continue;
                if (r.left < vw * 0.22) continue;
                if (r.right < vw - 40) continue;
                if (r.height < vh * 0.5) continue;
                if (el.querySelector(CHAT_MARKERS)) continue;
                const t = (el.innerText || '');
                if (t.length < 40) continue;
                const area = r.width * r.height;
                if (t.length > geoLen || (t.length === geoLen && area < geoArea)) {
                    geoPanel = el; geoLen = t.length; geoArea = area;
                }
            }
            let artifactAffordances = false;
            let geoIsTracker = false;
            if (geoPanel) {
                textLen = Math.max(textLen, geoLen);
                sources = Math.max(sources,
                    geoPanel.querySelectorAll('a[href^="http"]').length);
                steps = Math.max(steps,
                    geoPanel.querySelectorAll('li, [role="listitem"]').length);
                geoIsTracker = /\\d[\\d,]*\\s+sources?\\s+and\\s+counting/i.test(
                    geoPanel.innerText || '');
                // Completed-header affordances: Copy (+ download chevron) AND
                // Publish/Share live in the finished Document artifact HEADER
                // (the same trio the T1 download and publish extractors use).
                // (review r2) scoped to the panel's top strip + aria-label
                // (or short text) — a code-block Copy button deep in report
                // content or a citation chip titled "…market share…" must
                // not satisfy it. Requiring BOTH keeps a lone Copy out.
                const pr = geoPanel.getBoundingClientRect();
                let hasCopy = false, hasPublish = false;
                for (const b of geoPanel.querySelectorAll('button, [role="button"]')) {
                    const br = b.getBoundingClientRect();
                    if (br.top > pr.top + 96) continue;      // header strip only
                    const al = (b.getAttribute('aria-label') || '').toLowerCase();
                    const bt = (b.textContent || '').trim().toLowerCase();
                    const t = al || (bt.length < 30 ? bt : '');
                    if (!t) continue;
                    if (/\\bcopy\\b/.test(t)) hasCopy = true;
                    if (/\\b(publish|share)\\b/.test(t)) hasPublish = true;
                    if (hasCopy && hasPublish) break;
                }
                artifactAffordances = hasCopy && hasPublish;
            }
            return { hasStop, researchDone, anchoredDone, researchCardDone,
                     liveActive, artifactAffordances, geoIsTracker, legacyEmpty,
                     textLen, sources, steps };
        }""")

        text_len = int(data.get("textLen") or 0)
        sources = int(data.get("sources") or 0)
        steps = int(data.get("steps") or 0)
        snap = {"text_len": text_len, "sources": sources, "steps": steps}

        live_active = bool(data.get("liveActive"))
        if data.get("hasStop"):
            return (False, f"stop_btn_present (text={text_len})", snap)
        # 2026-07-11 marker-over-ticker ordering: a definitive done-marker
        # overrides a lingering "N sources and counting" ticker (the kept-open
        # tracking panel freezes that text post-completion — FIFA incident).
        # (review r2) ONLY the ANCHORED markers may override: the card-state
        # marker, "Boom!…", or "research complete · N sources" — forms that
        # cannot occur mid-run as prose. The loose text marker and the header
        # affordances stay subordinate to a live ticker (a reviewer executed
        # the earlier draft's JS against a simulated mid-research DOM and got
        # a false done through prose + the loose regex).
        anchored = bool(data.get("anchoredDone") or data.get("researchCardDone"))
        if live_active and not anchored:
            return (False, "live_sources_counting", snap)
        markers = anchored or bool(data.get("researchDone"))
        affordances = bool(data.get("artifactAffordances")) and not live_active
        if not (markers or affordances):
            return (False, "no_done_marker (no research_complete text/card/affordances)", snap)
        # #921 incident-2: a done-marker on a COMPLETELY EMPTY snapshot
        # (0 chars, 0 sources, 0 steps) is the platform-bug false-done — the
        # research-complete card/marker rendered but the actual report artifact
        # never did (2026-07-08 NemoClaw: Claude sat 36 min on a "Research plan
        # created" placeholder carrying a stale complete marker; the old code
        # confirmed done here → fired a 0-char extraction → churned). Refuse to
        # confirm done on an empty artifact: the poll keeps going and #921's
        # stuck arbiter raises a [Retry][Skip] card if it never fills in.
        if text_len == 0 and sources == 0 and steps == 0:
            return (False, "done_marker_but_empty_snapshot (text=0, sources=0, steps=0)", snap)
        # (review r2) tracker-fed snapshot guard: when the ONLY content
        # evidence is the tracking-shaped geo panel (legacy selectors all
        # zero) and the marker isn't anchored, the geo numbers must not
        # stand in for report content — that combination is #921's stale-
        # marker case with the guard disarmed. Anchored markers pass (the
        # FIFA body text carried "Research complete · 553 sources" while
        # the open panel was the tracker — that must keep confirming).
        if (data.get("legacyEmpty") and data.get("geoIsTracker")
                and not anchored):
            return (False, "tracker_fed_snapshot_weak_marker", snap)
        which = "research_complete_marker" if markers else "artifact_header_affordances"
        stale = " (stale live-ticker overridden)" if live_active else ""
        return (True, f"no_stop + {which}{stale}", snap)
    except Exception as e:
        return (False, f"detect_error: {e}", {})


#: The queued→ongoing transaction has been refused on every run in the corpus
#: and the fallback read has resolved it every time. ONCE per process, keyed on
#: the root cause's class, so a NEW failure class still speaks. See the call site.
_FLIP_403_QUIET = logquiet.Suppressor(logquiet.ONCE)


async def detect_completion_gemini(page, running_confirmed: bool = False):
    """Gemini Deep Research completion detector. Playwright-only.
    Returns (done, reason, snap) where snap = {text_len, sources, steps}.

    2026-04-25 strictness rewrite: done=True ONLY when:
      • Stop button gone + Start-research button gone (post-planning)
      • a definitive done-marker is visible
    Removed: text_len>5000+!active_kw fallback (transient no-active-keyword
    windows mid-stream caused false positives). Caller handles 2-cycle flat.

    #897b (2026-07-04, user-confirmed live new UI): Gemini's collapsed
    composer removed the persistent bottom input box — a small launcher
    button becomes the input only when clicked — so "stop button lives in
    the composer" is no longer a reliable running-signal, and the done-state
    now renders in the LIVE DOM (no reload needed). Done-markers, keyed on
    visible TEXT/labels (never class selectors):
      • report button ROW "Contents" · "Share & Export" · "Create" (trio)
      • chat line "I've completed your research. Feel free to ask me
        follow-up questions or request changes."
      • "Share & Export" alone (the pre-2026-07 marker, kept as-is)
    Running-signal: stop-button scan broadened to [role=button]/aria on the
    report card, plus the guarded running-CSS-animation tier (offsetParent
    + getAnimations().playState — see scrape_progress_gemini 2026-05-14
    note on persisted-but-finished animations).

    2026-07-13 (two E2E runs, detector blind for the WHOLE research —
    "start_research_btn_visible (pre-research)" every tick while its own
    snapshot held the finished 111k-char report): the OLD plan bubble keeps
    its "Start research" button in the conversation DOM after the click, so
    the pre-research gate never released and the #897b trio marker below it
    was unreachable — the same stale-gate-outranks-done-marker disease as
    Claude's liveActive (fixed 2026-07-11). Now: the done-only markers
    (trio / completion chat line) outrank the stale Start button — those
    render exclusively on a FINISHED report, so their presence proves the
    Start button is leftover scrollback. Explicit stop buttons still veto
    everything; the weak running signals (streaming markers / animation
    tier) yield to the strong markers but still veto the weaker
    Share&Export-alone path. The Start scan also requires the button to be
    VISIBLE (offsetParent) — a display:none leftover must not gate.

    2026-08-19 (the 08-19 e2e: nineteen minutes of `start_research_btn_visible
    (pre-research)` ten seconds after the log said "Clicked 'Start research' ✓
    (confirmed it took)" and "Gemini is researching ✓"). The DECISION was right
    every tick — no done-marker, no stop, no weak signal, so the ladder fell to
    its last resort. The REASON was a lie, and the lie is what made a healthy
    run look pre-research. Root cause was TWO independent misses, both in the
    JS below and both fixed there with the captures that proved them:
      • the stop scan was case-sensitive, so `aria-label="Stop response"` matched
        nothing — and the button is INVISIBLE while running, so it had to be
        split into a visible veto and a hidden weak signal rather than simply
        made case-insensitive;
      • the running-animation tier matched CLASS names while Gemini carries
        `pulse` in the ANIMATION NAME.
    `running_confirmed` closes the label itself, belt-and-braces: the caller
    already knows whether a running-verify ever confirmed this agent, so the
    last resort can stop asserting "pre-research" about a run that demonstrably
    started. ⛔ It is deliberately NOT "we clicked Start" — that was TRUE in the
    2026-08-17 ninety-minute failure too, where `pre-research` was the CORRECT
    label; a confirmed RUNNING verify is the only fact that separates the two."""
    try:
        data = await page.evaluate("""() => {
            // ⛔⛔ 2026-08-19 — THE STOP SIGNAL IS TWO SIGNALS, and reading it
            // as one is what left this detector deaf for nineteen minutes. Two
            // live captures of the same Gemini Deep Research conversation
            // settled it (owner-run, 728×748 viewport):
            //   DURING research — exactly ONE stop-ish control in the whole
            //     document: <button aria-label="Stop response">, icon-only,
            //     offsetParent null, 0×0. Capital S. CSS attribute matching is
            //     case-SENSITIVE without the `i` flag, and of the selectors
            //     this block used to carry only the last one had it — and that
            //     one also demanded [role="button"], which a native <button>
            //     does not have. So the scan matched NOTHING while CUA's own
            //     screenshot described that button twice.
            //   AFTER completion — nothing matches, because the button is GONE.
            // ⭐⭐ BOTH OBVIOUS ONE-LINE FIXES WERE WRONG, IN OPPOSITE
            // DIRECTIONS, and only the measurement could tell them apart.
            // Adding `i` alone promotes a HIDDEN button to a veto that outranks
            // every done-marker. Gating on visibility alone rejects the only
            // running signal Gemini offers, because that button is invisible
            // WHILE RUNNING. Hence the split:
            //   hasStopVisible — case-insensitive AND visible ⇒ the hard veto
            //     at the top of the ladder, semantics unchanged for every state
            //     that already worked.
            //   hasStopHidden  — present but 0×0 ⇒ a WEAK RUNNING signal, ranked
            //     BELOW the done markers, so it can never outrank
            //     report_button_trio. HANG-PROOF BY CONSTRUCTION: if some
            //     future state leaves a hidden stop behind forever, the worst
            //     it can cost is the weakest done rung (Share & Export alone),
            //     never the run.
            // ⭐ `offsetParent === null` also reports a position:fixed element
            // as hidden. That error lands on the SAFE side here — a misread
            // visible stop becomes a weak signal, never a veto — so the
            // convention the Start scan below already uses is kept.
            // ⭐ A WORD-BOUNDARY match, not a bare substring: "Stop response" and "Stop
            // generating" match, a future "Stopwatch" does not. The veto is the
            // one rung that can hold a FINISHED run hostage, so it is the one
            // that should be narrow.
            let hasStopVisible = false;
            let hasStopHidden = false;
            const STOP_RE = /\\bstop\\b/i;
            for (const b of document.querySelectorAll('button, [role="button"]')) {
                const al = b.getAttribute('aria-label') || '';
                const ti = b.getAttribute('title') || '';
                const txt = (b.textContent || '').trim().toLowerCase();
                const isStop = STOP_RE.test(al) || STOP_RE.test(ti)
                    || al.trim().toLowerCase() === 'cancel'
                    || ti.trim().toLowerCase() === 'cancel'
                    || txt === 'stop' || txt === 'stop generating' || txt === 'cancel';
                if (!isStop) continue;
                const rect = b.getBoundingClientRect();
                if (b.offsetParent !== null && rect.width > 0 && rect.height > 0) {
                    hasStopVisible = true; break;
                }
                hasStopHidden = true;
            }
            // Weak running signals — real streaming usually shows these, but
            // they persist/false-positive on finished chrome, so they must
            // not outrank the done-only markers (2026-07-13 split).
            let hasRunningWeak = false;
            let runningWeakVia = '';
            if (document.querySelector(
                '[data-is-streaming="true"], .loading-indicator, .streaming'
            )) { hasRunningWeak = true; runningWeakVia = 'streaming-marker'; }
            // #897b: running-animation tier promoted into the completion
            // detector — with the composer collapsed there may be NO stop
            // button while the DR spinner still runs.
            //
            // ⛔⛔ 2026-08-19 — AND IT HAD BEEN LOOKING IN THE WRONG PLACE. It
            // selected on CLASS names ([class*="pulse"] …). Gemini's live
            // research skeletons are class="_index_0 item-line ng-star-inserted"
            // and carry the word `pulse` in the ANIMATION NAME
            // (_ngcontent-ng-c379413341_pulse). Four of them, visible, 634×14,
            // repeating — the exact signal #897b promoted this tier to catch,
            // and it saw none of them. A SECOND, INDEPENDENT miss: had this
            // tier worked, the false `pre-research` below could never have been
            // reached, stop button or no stop button.
            //
            // ⚠ AND "any running animation" IS NOT THE FIX. Gemini animates
            // its background FOREVER: nl-blob/nl-bg-blob (morphBG/scaleBG/
            // sweepBG) and gradient-strip (gradientScroll) are running, visible
            // and enormous on a COMPLETED page. Unscoped, this flag would be
            // permanently true and would veto the Share&Export done path for
            // the rest of time. The old class selector was ACCIDENTALLY safe
            // only because none of those class names contain
            // animate/spin/pulse/loading — not a property to keep relying on.
            //
            // ⇒ Match the animation NAME and keep the visibility gate. Both
            // captures were replayed row by row:
            //   after completion — ZERO visible matches (mdc-circular-progress-
            //     left-spin/right-spin DO contain "spin" but are 0×0; morphBG,
            //     morphFG, gradientScroll, image-fade-on, apd-ring-fade-in and
            //     both …-rotate names match nothing at all)
            //   during research — exactly ONE (…_pulse, 634×14)
            // The visibility gate is measured-sufficient, so nothing further is
            // narrowed by guesswork. The matched name is REPORTED in the reason
            // string instead: a future ambient animation that happens to be
            // named "…pulse…" AND renders visibly would cost the weakest done
            // rung and nothing else, and the log would name the culprit.
            if (!hasRunningWeak) {
                const RUN_RE = /pulse|spin|loading|shimmer/i;
                let anims = [];
                try {
                    anims = (typeof document.getAnimations === 'function')
                        ? document.getAnimations() : [];
                } catch (e) { anims = []; }
                for (const a of anims) {
                    if (a.playState !== 'running') continue;
                    const nm = String(a.animationName || '');
                    if (!RUN_RE.test(nm)) continue;
                    const el = a.effect && a.effect.target;
                    if (!el || typeof el.getBoundingClientRect !== 'function') continue;
                    // ⭐ THE RECT IS THE VISIBILITY GATE HERE, not offsetParent.
                    // A browser returns an all-zero rect for anything in a
                    // display:none subtree, so the two tests agree on every
                    // state this tier can see — except position:fixed, which has
                    // NO offsetParent and is perfectly visible. In a tier whose
                    // whole job is noticing that something still moves, a guard
                    // whose only distinct effect is a FALSE NEGATIVE is the wrong
                    // guard. (The stop scan above keeps both, for the opposite
                    // reason: there a misread lands on the safe side.)
                    // Measured: mdc-circular-progress-left-spin/right-spin DO
                    // match the name regex on a completed page and are 0×0.
                    const r = el.getBoundingClientRect();
                    if (r.width <= 0 || r.height <= 0) continue;
                    hasRunningWeak = true;
                    // ⭐ THE RESPONSE-REGION SCOPE IS REPORTED, NOT ENFORCED, and
                    // that is a deliberate choice rather than a half-done one.
                    // Scoping the SEARCH to model-response nodes was the obvious
                    // belt-and-braces — but the ancestry of Gemini's `item-line`
                    // skeletons is NOT in either capture, so a positive scope
                    // could just as easily be a guard that cannot fire, which is
                    // this file's most frequently repeated defect. The
                    // visibility gate is measured-sufficient on its own (zero
                    // visible matches after completion, exactly one during), so
                    // the scope rides along as EVIDENCE: the reason string says
                    // whether the winning animation was inside a response node,
                    // and that is precisely the measurement someone needs to
                    // turn it into a gate without guessing.
                    let inResponse = false;
                    try {
                        inResponse = !!(el.closest && el.closest(
                            'message-content, .model-response-text, model-response'));
                    } catch (e) { inResponse = false; }
                    runningWeakVia = 'anim:' + nm.slice(-32)
                        + (inResponse ? ' in-response' : ' page-wide');
                    break;
                }
            }

            let hasStartBtn = false;
            for (const b of document.querySelectorAll('button')) {
                if (b.offsetParent === null) continue;   // hidden leftover must not gate
                const txt = (b.textContent || '').trim().toLowerCase();
                if (txt === 'start research' || txt.includes('start research')) {
                    hasStartBtn = true; break;
                }
            }

            let hasShareExport = false;
            let hasContentsBtn = false;
            let hasCreateBtn = false;
            const shareKws = ['share & export', 'share and export'];
            for (const b of document.querySelectorAll('button, [role="button"]')) {
                const txt = (b.textContent || '').trim().toLowerCase().replace(/\\s+/g, ' ');
                const al  = (b.getAttribute('aria-label') || '').toLowerCase();
                if (shareKws.some(k => txt === k || txt.includes(k) || al.includes(k))) {
                    hasShareExport = true;
                }
                if (txt === 'share' || txt === 'export' ||
                    al === 'share' || al === 'export') {
                    hasShareExport = true;
                }
                // #897b trio members — EXACT text so composer tools like
                // "Create image" can't satisfy the "Create" leg.
                if (txt === 'contents' || al === 'contents') hasContentsBtn = true;
                if (txt === 'create'   || al === 'create')   hasCreateBtn = true;
            }
            // The completed report's button row, left→right:
            // "Contents" · "Share & Export" · "Create" (user-confirmed live).
            const reportButtonTrio = hasContentsBtn && hasShareExport && hasCreateBtn;

            // Gemini's own completion chat line, rendered above the report
            // tile: "I've completed your research. Feel free to ask me
            // follow-up questions or request changes."
            // Review catch (#752-755 lesson — never body-scan a phrase the
            // run itself can type): the pasted brief / mid-run user chat
            // sits in user-query bubbles inside body.innerText, so scope the
            // scan to MODEL-response nodes (user-query ancestry excluded)
            // and anchor on Gemini's exact line, apostrophe-normalized.
            let completedChatText = false;
            const responses = document.querySelectorAll('message-content, .model-response-text');
            for (const r of responses) {
                if (r.closest('user-query, [class*="user-query"], .query-text')) continue;
                const rt = (r.innerText || '').toLowerCase().replace(/[\\u2018\\u2019]/g, "'");
                if (rt.includes("i've completed your research") ||
                    rt.includes('completed your research. feel free')) {
                    completedChatText = true; break;
                }
            }

            let textLen = 0;
            if (responses.length > 0) textLen = responses[responses.length-1].innerText.length;

            const sources = document.querySelectorAll(
                'message-content a[href^="http"]'
            ).length;
            const steps = document.querySelectorAll(
                '[class*="research-step"], [class*="thought"]'
            ).length;
            return { hasStopVisible, hasStopHidden, hasRunningWeak, runningWeakVia,
                     hasStartBtn, hasShareExport,
                     reportButtonTrio, completedChatText, textLen, sources, steps };
        }""")

        text_len = int(data.get("textLen") or 0)
        sources = int(data.get("sources") or 0)
        steps = int(data.get("steps") or 0)
        snap = {"text_len": text_len, "sources": sources, "steps": steps}

        # 2026-07-13 decision order (stale-gate fix — see docstring), with the
        # 2026-08-19 stop split folded in:
        #   VISIBLE Stop → veto everything
        #   trio / completion chat line → DONE (done-only UI; a lingering
        #     plan-bubble Start button, a finished-chrome animation or a HIDDEN
        #     leftover stop must not hold these hostage — both 07-13 E2E runs
        #     lost 10-14 min here)
        #   weak running signals — the animation tier, then a HIDDEN stop →
        #     veto the weaker paths below
        #   visible Start button → pre-research gate (or, when a running-verify
        #     already confirmed this agent, an honest stale-Start label)
        #   Share & Export alone → done (pre-2026-07 marker, weakest)
        #
        # ⛔ THE HIDDEN STOP BELONGS HERE AND NOWHERE HIGHER. Ranked above the
        # done markers it would be the 90-minute timeout the 08-19 measurement
        # caught before it shipped; ranked here the worst it can ever cost is
        # the weakest done rung.
        if data.get("hasStopVisible"):
            return (False, f"stop_btn_present (text={text_len})", snap)
        stale_bits = []
        if data.get("hasStartBtn"):
            stale_bits.append("stale start-btn overridden")
        if data.get("hasRunningWeak"):
            stale_bits.append("weak running-signal overridden")
        if data.get("hasStopHidden"):
            stale_bits.append("hidden stop-btn overridden")
        stale = f" ({'; '.join(stale_bits)})" if stale_bits else ""
        if data.get("reportButtonTrio"):
            return (True, f"no_stop + report_button_trio (Contents/Share & Export/Create){stale}", snap)
        if data.get("completedChatText"):
            return (True, f"no_stop + completed_chat_text{stale}", snap)
        if data.get("hasRunningWeak"):
            return (False, f"running_weak_signal ({data.get('runningWeakVia') or 'unnamed'}"
                           f", text={text_len})", snap)
        if data.get("hasStopHidden"):
            return (False, f"running_hidden_stop_btn (text={text_len})", snap)
        if data.get("hasStartBtn"):
            # ⭐ The verbatim string below stays EXACTLY as it was: on 2026-08-17
            # it named this state correctly once a minute for ninety minutes,
            # and that run is the reason `running_confirmed` gates it instead of
            # replacing it.
            if running_confirmed:
                return (False, f"stale_start_btn_no_done_marker (running already "
                               f"confirmed; text={text_len})", snap)
            return (False, "start_research_btn_visible (pre-research)", snap)
        if data.get("hasShareExport"):
            return (True, "no_stop + share_export_visible", snap)
        return (False, "no_done_marker (trio/completion-text/Share & Export all missing)", snap)
    except Exception as e:
        return (False, f"detect_error: {e}", {})


DETECT_FNS = {
    "ChatGPT": detect_completion_chatgpt,
    "Gemini":  detect_completion_gemini,
    "Claude":  detect_completion_claude,
}


# ── Claude Artifact DOM Helpers ──────────────────────────────────────────────

async def _claude_modern_marker(page, strict=False) -> bool:
    """Cheap DOM probe for the modern Claude completion marker (2026-05-04
    parity set): anchored "research complete · N sources" (legacy + modern
    layouts, body-text safe), "Boom! Research report is ready" (2026-05+
    callout), and the modern card title "<Title> · N sources · Xh Ym"
    (scoped to artifact/aside containers — body-text would false-positive
    mid-stream on separate elapsed-timer + source-count elements).

    strict=True skips that card-title fallback — its safety rests on a
    layout-scoping assumption the 2026-05-04 docstring itself calls
    mid-stream-ambiguous, so callers using the marker to REPLACE a second
    CUA confirmation (done_count==1 corroboration) only accept the two
    anchored forms; the post-2-confirm artifact gate keeps the full set
    where the marker is merely a layout bypass.

    2026-07-11: hoisted out of the CUA-says-done branch into a shared helper
    so the poll loop can also consult it at done_count==1 — the FIFA run
    carried this marker in the DOM for ~24 min while completion waited on a
    second CUA vision pass (one contradicting misread reset the counter and
    cost ~14 min). Returns False on any evaluate error."""
    try:
        return bool(await page.evaluate(
            """(strict) => {
                const body = document.body?.innerText || '';
                if (/research\\s+complete(?:d)?\\s*[\\s·•—\\-]+\\d[\\d,]*\\s+sources?/i.test(body)) return true;
                if (/\\bBoom!\\s+(?:Your\\s+)?[Rr]esearch\\s+report\\s+is\\s+ready\\b/.test(body)) return true;
                if (strict) return false;
                const cards = document.querySelectorAll(
                    '.font-claude-message [class*="artifact"], aside [class*="artifact"], aside [class*="card"]'
                );
                for (const el of cards) {
                    if (/[\\s·•—\\-]+\\d[\\d,]*\\s+sources?\\s*[\\s·•—\\-]+\\d+\\s*[hms]/i.test(el.innerText || '')) return true;
                }
                return false;
            }""", bool(strict)
        ))
    except Exception:
        return False


async def _count_claude_artifacts(page):
    """Count artifact preview cards in Claude conversation. Returns int.
    2026-04-26: extended selectors for the modern Research card layout —
    aria-label="Open the artifact", a[href*="/artifacts/"] direct links,
    role=button rounded card divs, plus a TEXT-content fallback that
    finds buttons whose text contains "Research complete" or starts with
    a research-card-style prefix (e.g. "OpenClaw and OpenShell research").
    2026-05-04: scope to assistant-message containers + strip user-message
    and attachment chips. Claude renders user-attached .md files (e.g.
    brief.md) as artifact-style preview cards inside the user-message
    bubble — same DOM shape as assistant artifacts — so the broad
    selectors would inflate the count by 1 and make _click_claude_artifact
    land on the brief instead of the assistant's report.
    """
    try:
        return await page.evaluate("""() => {
            const selectors = [
                'button[data-testid*="artifact"]',
                '[data-testid*="artifact-preview"]',
                '.artifact-card', '.artifact-preview',
                'button[data-artifact-id]',
                '[class*="artifact"][role="button"]',
                'button[aria-label*="Open the artifact"]',
                'button[aria-label*="research"]',
                'a[href*="/artifacts/"]',
                // 2026-05-13: dropped `div[role="button"][class*="rounded"][class*="border"]`
                // from both _count_claude_artifacts and _click_claude_artifact —
                // matched chat-row context-menu triggers in Run 1 (image:
                // Star/Rename/Add to project/Delete popup) and grabbed the
                // wrong target. The remaining selectors cover every artifact-
                // card variant we have logs for; this fallback was a
                // 2026-04-26 belt-and-suspenders that turned into a misclick
                // magnet. Must drop from BOTH locations so count + click agree.
            ];
            // 2026-05-12: self-strip helper. Flow B attached .md/.pdf/.docx
            // files render in Claude as preview cards with the same artifact-
            // card DOM shape (rounded div role=button) — the ancestor-based
            // attachment exclusion missed these when Claude didn't tag any
            // parent with attachment/file/upload markers. Match on the
            // element's own text + aria to catch them.
            const _fileExtRe = /\\.(?:md|pdf|docx?|txt|csv|json|html?|rtf|odt|markdown)\\b/i;
            const _looksLikeFile = (el) => {
                const t = (el.textContent || '').trim().toLowerCase();
                const a = (el.getAttribute('aria-label') || '').toLowerCase();
                if (_fileExtRe.test(t) || _fileExtRe.test(a)) return true;
                if (/^(open|view)\\s+(?:file|attachment|document)\\b/i.test(a)) return true;
                return false;
            };
            const isUserOrAttachment = (el) => !!el.closest(
                '[data-testid="user-message"], [data-message-author-role="user"], ' +
                '[data-testid*="attachment"], [data-testid*="file"], [class*="attachment" i], ' +
                '[class*="upload" i], [data-testid*="upload"], ' +
                '[class*="file-preview" i], [class*="file-card" i], ' +
                '[aria-label*="attachment" i], [aria-label*="file " i]'
            ) || _looksLikeFile(el);
            const isInAssistant = (el) => !!el.closest('.font-claude-message');
            // #736: build the SAME candidate array _click_claude_artifact
            // indexes into, so count == click's clickable-card count and the
            // caller's target index (count-1) is always valid. Previously count
            // used Math.max-across-selectors + UNCONDITIONALLY folded in the
            // Boom!/Research-complete callout button + skipped click's
            // visibility/dialog filter — so at count==5 it over-reported by 1,
            // target_idx=4 fell out of click's filtered range, and a needless
            // CUA fallback fired on every 5-artifact run.
            let cards = [];
            // Pass 1: prefer matches inside assistant message scope.
            for (const sel of selectors) {
                const found = Array.from(document.querySelectorAll(sel))
                    .filter(el => isInAssistant(el) && !isUserOrAttachment(el));
                if (found.length > 0) { cards = found; break; }
            }
            // Pass 2: broad scan if assistant scope returned nothing.
            if (!cards.length) {
                for (const sel of selectors) {
                    const found = Array.from(document.querySelectorAll(sel))
                        .filter(el => !isUserOrAttachment(el));
                    if (found.length > 0) { cards = found; break; }
                }
            }
            // Text-content fallback ONLY when nothing else matched (mirrors
            // click) — the Boom!/Research-complete callout must NOT inflate the
            // count when real artifact cards already exist.
            if (!cards.length) {
                const textHits = Array.from(document.querySelectorAll(
                    '.font-claude-message button, .font-claude-message [role="button"]'
                )).filter(el => !isUserOrAttachment(el))
                  .filter(el => /research\\s+complete(?:d)?\\s*[\\s·•—\\-]/i.test(el.textContent || '')
                             || /\\bBoom!\\s+(?:Your\\s+)?[Rr]esearch\\s+report\\s+is\\s+ready\\b/.test(el.textContent || ''));
                if (textHits.length > 0) cards = textHits;
            }
            // Legacy fallback: document-like inline cards in assistant messages
            // (same selector set as click — note: NOT the [data-is-streaming]
            // variant, which click omits).
            if (!cards.length) {
                cards = Array.from(document.querySelectorAll(
                    '.font-claude-message button[class*="block"], ' +
                    '.font-claude-message [class*="artifact"]'
                )).filter(el => !isUserOrAttachment(el));
            }
            // Same visibility + dialog-modal filter _click_claude_artifact
            // applies, so the counted set == the clickable set.
            cards = cards.filter(c => {
                const r = c.getBoundingClientRect();
                if (r.width < 20 || r.height < 20) return false;
                if (c.closest('[role="dialog"], [aria-modal="true"]')) return false;
                // 2026-07-06: NEVER match the left nav/sidebar (Recents rows,
                // their "More options" kebabs) or any menu trigger — the
                // broad pass-2 scan could land there when no artifact card
                // has rendered yet, opening the Star/Rename/Delete menu
                // instead of the sources panel (user-observed).
                if (c.closest('nav, aside, [role="menu"], [aria-haspopup="menu"], [class*="sidebar" i]')) return false;
                return true;
            });
            return cards.length;
        }""")
    except Exception as e:
        log(f"Artifact count failed: {e}", "WARN")
        return 0


async def _click_claude_artifact(page, index=0):
    """Click the Nth artifact card (0-indexed). Returns a {cx,cy,vw,vh} dict (the
    clicked card's viewport-relative click center, for Track-B coord ground-truth)
    on success, else False — truthy on success, so callers that only test
    truthiness are unaffected.
    2026-04-26: same modernized selectors as _count_claude_artifacts.
    2026-05-04: same assistant-scope + user/attachment strip as
    _count_claude_artifacts so the brief.md attachment chip in the
    user-message bubble can't be the click target."""
    try:
        return await page.evaluate("""(idx) => {
            const selectors = [
                'button[data-testid*="artifact"]',
                '[data-testid*="artifact-preview"]',
                '.artifact-card', '.artifact-preview',
                'button[data-artifact-id]',
                '[class*="artifact"][role="button"]',
                'button[aria-label*="Open the artifact"]',
                'button[aria-label*="research"]',
                'a[href*="/artifacts/"]',
                // 2026-05-13: dropped `div[role="button"][class*="rounded"][class*="border"]`
                // from both _count_claude_artifacts and _click_claude_artifact —
                // matched chat-row context-menu triggers in Run 1 (image:
                // Star/Rename/Add to project/Delete popup) and grabbed the
                // wrong target. The remaining selectors cover every artifact-
                // card variant we have logs for; this fallback was a
                // 2026-04-26 belt-and-suspenders that turned into a misclick
                // magnet. Must drop from BOTH locations so count + click agree.
            ];
            // 2026-05-12: self-strip helper for Flow B attached files.
            // See _count_claude_artifacts for full rationale. f-string
            // braces doubled (`{`/`}`) per the surrounding pattern.
            const _fileExtRe = /\\.(?:md|pdf|docx?|txt|csv|json|html?|rtf|odt|markdown)\\b/i;
            const _looksLikeFile = (el) => {
                const t = (el.textContent || '').trim().toLowerCase();
                const a = (el.getAttribute('aria-label') || '').toLowerCase();
                if (_fileExtRe.test(t) || _fileExtRe.test(a)) return true;
                if (/^(open|view)\\s+(?:file|attachment|document)\\b/i.test(a)) return true;
                return false;
            };
            const isUserOrAttachment = (el) => !!el.closest(
                '[data-testid="user-message"], [data-message-author-role="user"], ' +
                '[data-testid*="attachment"], [data-testid*="file"], [class*="attachment" i], ' +
                '[class*="upload" i], [data-testid*="upload"], ' +
                '[class*="file-preview" i], [class*="file-card" i], ' +
                '[aria-label*="attachment" i], [aria-label*="file " i]'
            ) || _looksLikeFile(el);
            const isInAssistant = (el) => !!el.closest('.font-claude-message');
            let cards = [];
            // Pass 1: prefer matches inside assistant message scope.
            for (const sel of selectors) {
                const found = Array.from(document.querySelectorAll(sel))
                    .filter(el => isInAssistant(el) && !isUserOrAttachment(el));
                if (found.length > 0) { cards = found; break; }
            }
            // Pass 2: fallback to broad scan if assistant scope returned
            // nothing — still strips user-message + attachment matches.
            if (!cards.length) {
                for (const sel of selectors) {
                    const found = Array.from(document.querySelectorAll(sel))
                        .filter(el => !isUserOrAttachment(el));
                    if (found.length > 0) { cards = found; break; }
                }
            }
            if (!cards.length) {
                // Text-content fallback: legacy "Research complete · …" or
                // 2026-05+ Boom! marker. Scoped + user/attachment-stripped.
                const textHits = Array.from(document.querySelectorAll(
                    '.font-claude-message button, .font-claude-message [role="button"]'
                )).filter(el => !isUserOrAttachment(el))
                  .filter(el => /research\\s+complete(?:d)?\\s*[\\s·•—\\-]/i.test(el.textContent || '')
                             || /\\bBoom!\\s+(?:Your\\s+)?[Rr]esearch\\s+report\\s+is\\s+ready\\b/.test(el.textContent || ''));
                if (textHits.length > 0) cards = textHits;
            }
            if (!cards.length) {
                const fallback = Array.from(document.querySelectorAll(
                    '.font-claude-message button[class*="block"], ' +
                    '.font-claude-message [class*="artifact"]'
                )).filter(el => !isUserOrAttachment(el));
                cards = fallback;
            }
            // 2026-04-26: visibility + dialog-modal filter — a publish/share
            // dialog left over from a prior turn can match the same selectors;
            // skip zero-bbox elements and anything inside [role="dialog"].
            cards = cards.filter(c => {
                const r = c.getBoundingClientRect();
                if (r.width < 20 || r.height < 20) return false;
                if (c.closest('[role="dialog"], [aria-modal="true"]')) return false;
                // 2026-07-06: NEVER match the left nav/sidebar (Recents rows,
                // their "More options" kebabs) or any menu trigger — the
                // broad pass-2 scan could land there when no artifact card
                // has rendered yet, opening the Star/Rename/Delete menu
                // instead of the sources panel (user-observed).
                if (c.closest('nav, aside, [role="menu"], [aria-haspopup="menu"], [class*="sidebar" i]')) return false;
                return true;
            });
            const targetIdx = idx < 0 ? cards.length + idx : idx;
            if (cards.length > 0 && targetIdx >= 0 && targetIdx < cards.length) {
                const target = cards[targetIdx];
                const tr = target.getBoundingClientRect();
                // #914: full pointer/mouse event chain instead of bare
                // .click() — same lesson as ChatGPT's activity strip
                // (2026-04-26 v2): claude.ai binds card-open handlers via
                // React synthetic listeners that can swallow a bare
                // synthetic .click(); E2E logs showed the click "succeed"
                // while the CUA arriving ~30s later found the panel still
                // closed and had to click the card itself.
                const cx = tr.left + tr.width / 2;
                const cy = tr.top + tr.height / 2;
                const opts = { bubbles: true, cancelable: true, composed: true,
                               clientX: cx, clientY: cy, button: 0 };
                try {
                    target.dispatchEvent(new PointerEvent('pointerdown', opts));
                    target.dispatchEvent(new MouseEvent('mousedown', opts));
                    target.dispatchEvent(new PointerEvent('pointerup', opts));
                    target.dispatchEvent(new MouseEvent('mouseup', opts));
                    target.dispatchEvent(new MouseEvent('click', opts));
                } catch (e) {
                    target.click();
                }
                return { cx: cx, cy: cy,
                         vw: window.innerWidth, vh: window.innerHeight };
            }
            return false;
        }""", index)
    except Exception as e:
        log(f"Artifact click failed: {e}", "WARN")
        return False


def _claude_artifact_frame_targets(page):
    """Return frame targets worth scraping for Claude artifact content.

    Always starts with the main page. Appends any iframe whose URL is
    claude.ai / claude.site / about:blank (srcdoc-mounted sandboxes), plus
    any frame whose URL is empty/unknown — Claude has historically used
    blank-src iframes for some Document artifact variants and may again.

    Mirrors `_chatgpt_dr_frame_targets` (DGOPS-7366) but for Claude
    artifacts. Pre-fix, Run B 2026-05-12 had Claude Tier 2/3 both return
    empty while CUA later copied 127k chars — strong signal that the
    content was iframe-mounted and parent-document queries couldn't see
    it. This helper restores Tier 2/3 reach into the artifact iframe."""
    targets = [page]
    try:
        for frame in page.frames:
            try:
                src = (frame.url or "").lower()
            except Exception:
                continue
            if frame is page.main_frame:
                continue
            # Claude artifact iframe variants we've seen + the about:blank
            # srcdoc case (sandboxed inline HTML). The empty-URL case is a
            # belt-and-suspenders catch for any future scheme.
            if ("claude.ai" in src
                    or "claude.site" in src
                    or "anthropic" in src
                    or src.startswith("about:")
                    or src.startswith("blob:")
                    or src == ""):
                targets.append(frame)
    except Exception:
        pass
    return targets


_CLAUDE_PANEL_SELECTORS_JS = """[
    '[data-testid="artifact-content"]',
    '.artifact-content',
    '.artifact-panel .contents',
    // 2026-05-13: dropped `aside .prose`, `aside .markdown`,
    // `aside [contenteditable="true"]`, `aside .tiptap`,
    // `aside article`, `aside main` — bare-`aside` prefixes matched the
    // LEFT navigation <aside> on claude.ai (Run 1 returned 5906 chars of
    // "New chat / Search / Chats / Projects / Recents" nav text). The
    // artifact panel uses [class*="artifact-panel"] / similar markers, NOT
    // <aside>. Right-pane positioning is enforced at the panel-candidate
    // gate below; here we just list the artifact-class-anchored selectors.
    '[class*="artifact-panel"] .prose',
    '[class*="artifact-panel"] .markdown',
    '[class*="artifact-panel"] [contenteditable="true"]',
    '[class*="artifact-panel"] .tiptap',
    '[class*="artifact-panel"] article',
    '[class*="artifact-panel"] main',
    '[class*="artifact-panel"] [class*="content"]',
    '[class*="artifact"] .ProseMirror',
    '[class*="artifact"] [class*="rendered"]',
    '.markdown-body',
    '.prose-message',
    // iframe-side (when target is a Claude artifact frame): the
    // artifact body mounts directly on common containers.
    'main',
    'article',
    'body > div > article',
    'body main',
    '#root main',
    '#root article',
]"""


async def _read_claude_artifact_panel(page):
    """Read content from the currently open artifact panel (right side).

    Returns clean markdown when possible (innerHTML → markdownify) so the
    saved Claude report keeps its headings, lists, bold/italic, code blocks,
    and links. Falls back to innerText only when HTML extraction fails — the
    fallback flattens markdown structure to plain text, so a sentinel log is
    emitted to make the degradation visible (the FE would otherwise render
    a wall-of-text and we'd never know which extraction path produced it).

    2026-05-13 (DGOPS-7367 advisor): iframe-aware + retry-on-empty. Pre-fix,
    this function read only `document` and gave up on first miss. Run B
    2026-05-12 had Claude content reachable to CUA's pixel-level Ctrl+A but
    invisible to `document.querySelector` — almost certainly iframe-mounted.
    Now walks `_claude_artifact_frame_targets` for innerHTML across page +
    iframes, and retries once after 1.5s on the first empty pass to cover
    slow mounts. Falls through to innerText only after both passes miss.
    """
    targets = _claude_artifact_frame_targets(page)
    panel_selectors_arg = _CLAUDE_PANEL_SELECTORS_JS

    # 2026-05-13: shared right-pane position-gated panel finder. Run 1
    # had this function return 5906 chars of LEFT-nav text because the
    # old fallback `aside, [class*="side-panel"], [class*="right-panel"]`
    # matched claude.ai's navigation <aside>. The replacement requires
    # (a) wider than 400px, (b) right edge past viewport-center, (c)
    # innerText doesn't look like nav chrome (no "New chat / Recents /
    # Topic Generator" markers in the first 500 chars).
    _PANEL_GATE_JS = r"""
        const NAV_MARKERS = /\b(new chat|recents?|projects|search|topic generator|starred|home|chats?\b)\b/i;
        const _vw = window.innerWidth || document.documentElement.clientWidth;
        const _vh = window.innerHeight || document.documentElement.clientHeight;
        const _candidates = Array.from(document.querySelectorAll(
            '[class*="artifact-panel"], ' +
            '[data-testid*="artifact-panel"], ' +
            '[role="complementary"][class*="artifact" i], ' +
            '[class*="right-panel"][class*="artifact" i], ' +
            '[class*="side-panel"][class*="artifact" i], ' +
            'div[class*="artifact"][class*="open" i]'
        ));
        function _isLikelyPanel(el) {
            const r = el.getBoundingClientRect();
            if (r.width < 400) return false;
            if (r.right < _vw * 0.5) return false;
            const head = (el.innerText || '').slice(0, 500);
            if (NAV_MARKERS.test(head)) {
                let _matches = 0;
                const re = new RegExp(NAV_MARKERS.source, 'gi');
                while (re.exec(head) !== null) _matches++;
                if (_matches >= 2) return false;
            }
            return true;
        }
        // #914 geometry fallback — the 2026-07 claude.ai panel stopped
        // matching every artifact-classed selector above (E2E logs: DOM
        // read returned '' every cycle while the CUA could plainly SEE and
        // read the open panel → the CUA fallback fired on every poll).
        // Mirror ChatGPT #913 Signature-A: trust position/size over class
        // names. A right-DOCKED panel is flush right (right ≥ vw−40),
        // starts past the chat column (left ≥ 0.22·vw), is panel-sized
        // (380px..78% vw wide, ≥50% vh tall). The centered chat column and
        // its message bubbles fail the flush-right gate; the left nav
        // fails the left gate. Among survivors pick most-text, tie-break
        // smaller area so we root at the panel, not an ancestor wrapper.
        function _bestGeoPanel(minText) {
            // #914b: skip candidates containing chat-thread markers — with
            // the sidebar expanded the nav-right main wrapper passes the
            // pure-geometry gates (992px ≤ old 0.78vw cap at 1280), and
            // reading the chat column as "artifact content" is worse than
            // reading nothing. Width cap 0.75vw excludes it structurally.
            const CHAT_MARKERS = '[data-message-author-role="user"], ' +
                '[data-testid="user-message"], .font-claude-message';
            let best = null, bestLen = -1, bestArea = Infinity;
            for (const el of document.querySelectorAll('div, aside, section')) {
                const r = el.getBoundingClientRect();
                if (r.width < 380 || r.width > _vw * 0.75) continue;
                if (r.left < _vw * 0.22) continue;
                if (r.right < _vw - 40) continue;
                if (r.height < _vh * 0.5) continue;
                if (el.querySelector(CHAT_MARKERS)) continue;
                const txt = (el.innerText || '');
                if (txt.length < minText) continue;
                const head = txt.slice(0, 500);
                if (NAV_MARKERS.test(head)) {
                    let _m = 0;
                    const re = new RegExp(NAV_MARKERS.source, 'gi');
                    while (re.exec(head) !== null) _m++;
                    if (_m >= 2) continue;
                }
                const area = r.width * r.height;
                if (txt.length > bestLen || (txt.length === bestLen && area < bestArea)) {
                    best = el; bestLen = txt.length; bestArea = area;
                }
            }
            return best;
        }
    """

    async def _try_html(target):
        try:
            return await target.evaluate(f"""() => {{
                {_PANEL_GATE_JS}
                const panelSelectors = {panel_selectors_arg};
                for (const sel of panelSelectors) {{
                    let el;
                    try {{ el = document.querySelector(sel); }} catch (e) {{ continue; }}
                    if (el && el.innerText.length > 50) return el.innerHTML;
                }}
                // Right-pane-positioned fallback — only matches if a real
                // artifact panel is on the right half of the viewport AND
                // doesn't read like nav-chrome. Bare-`aside` fallback was
                // removed 2026-05-13.
                for (const el of _candidates) {{
                    if (_isLikelyPanel(el) && el.innerText.length > 200) return el.innerHTML;
                }}
                // #914: class-free geometry fallback (see _bestGeoPanel).
                const _geo = _bestGeoPanel(200);
                if (_geo) return _geo.innerHTML;
                return '';
            }}""")
        except Exception:
            return ""

    async def _try_text(target):
        try:
            return await target.evaluate(f"""() => {{
                {_PANEL_GATE_JS}
                const panelSelectors = {panel_selectors_arg};
                for (const sel of panelSelectors) {{
                    let el;
                    try {{ el = document.querySelector(sel); }} catch (e) {{ continue; }}
                    if (el && el.innerText.length > 50) return el.innerText;
                }}
                for (const el of _candidates) {{
                    if (_isLikelyPanel(el) && el.innerText.length > 200) return el.innerText;
                }}
                // #914: class-free geometry fallback (see _bestGeoPanel).
                const _geo = _bestGeoPanel(200);
                if (_geo) return _geo.innerText;
                return '';
            }}""")
        except Exception:
            return ""

    try:
        # Pass 1 — HTML across all targets.
        for target in targets:
            html_blob = await _try_html(target)
            if html_blob and len(html_blob) > 200:
                md = html_to_markdown(html_blob)
                if md and len(md) > 100:
                    return md
        # Pass 2 — wait 1.5s then HTML retry. Covers slow artifact mounts
        # where the wait_for_selector at the extractor entry timed out
        # against a narrower selector than what we query here.
        await asyncio.sleep(1.5)
        for target in targets:
            html_blob = await _try_html(target)
            if html_blob and len(html_blob) > 200:
                md = html_to_markdown(html_blob)
                if md and len(md) > 100:
                    return md
        # Pass 3 — innerText fallback (preserves prior behavior). Markdown
        # structure is lost here — log a sentinel so the operator knows
        # the saved doc is plain text rather than properly formatted MD.
        for target in targets:
            text = await _try_text(target)
            if text:
                log("[Claude] Artifact panel innerText fallback fired — markdown "
                    "structure lost. Saved doc will render as plain text.", "WARN")
                return text
        return ""
    except Exception as e:
        log(f"Artifact panel read failed: {e}", "WARN")
        return ""


def _looks_like_nav_sidebar(text: str) -> bool:
    """Reject heuristic for extraction returning navigation-sidebar text
    (e.g. claude.ai's left nav: New chat / Search / Chats / Projects /
    Recents / Topic Generator…). Run 1 (2026-05-12 chat_1778684431400_1)
    had `_read_claude_artifact_panel` fall back to a bare-`<aside>`
    selector that matched the left nav and returned 5906 chars of
    `New chat\\nSearch\\nChats\\nProjects\\nRecents\\nTopic Generator…`
    text — passed all downstream guards because it had no checklist /
    sources / wrong-artifact markers. This guard catches that shape.

    Heuristics (must trip ALL to be considered nav):
      - >=3 distinct nav markers in the first 500 chars
      - <3 prose paragraphs (lines >100 chars)
      - Total length < 8000 chars
    """
    if not text:
        return False
    head = text[:500]
    nav_markers_re = re.compile(
        r'\b(new\s+chat|recents?|projects|search|topic\s+generator|starred|chats?\b)\b',
        re.IGNORECASE,
    )
    nav_hits = set(m.group(0).lower() for m in nav_markers_re.finditer(head))
    if len(nav_hits) < 3:
        return False
    # Count prose paragraphs in full body (lines or blocks of >100 chars).
    long_lines = sum(1 for ln in text.split('\n') if len(ln.strip()) > 100)
    if long_lines >= 3:
        return False
    if len(text) >= 8000:
        return False
    return True


def _is_sources_not_document(text, *, platform="generic"):
    """Strict invariant guard for Phase 2 finalize extraction:
    extract_*_response must return the DOCUMENT (final report markdown),
    NEVER the SOURCES tracking checklist or right-side source-panel URL list.
    Errs toward LETTING DOCUMENTS THROUGH — a wrongly rejected report would
    force a retry on a correct extract.

    Heuristics (a doc passes if prose check holds; a source artifact must
    trip checklist OR url-list signals AND lack prose):
      STRONG-DOC    : >=4000 chars AND >=2 headings AND any paragraph
                      >=200 chars  → False (always accept long prose docs)
      DOC POSITIVE  : >=3 markdown headings AND >=5 paragraphs >100 chars
      MODERN MARKER : "Research complete · N sources" in text AND >=2
                      headings → False (Claude's 1-artifact layout)
      CHECKLIST NEG : >=4 [x]/[ ] OR >=4 "Reading source N" lines AND
                      heading count <2 AND length < 5000 AND
                      checkbox/total-lines ratio > 15% → True
      URL-LIST NEG  : >=8 numbered-URL/bare-hostname lines AND headings <2
                      AND length 800-3000

    A1 (2026-05-01): added STRONG-DOC override + MODERN MARKER sentinel +
    checklist-ratio gate. Final research reports may include a methodology
    section with a few checkboxes; the old length-only rejection rule
    (len<5000 + checkbox>=4 + headings<2) could mis-fire on dense reports
    that happened to land below 5000 chars during a partial render. The
    new ratio gate blocks rejection unless checkboxes dominate the body.
    """
    if not text or len(text) < 200:
        return False
    # CHAT-TRANSCRIPT NEG (2026-05-02): chat-transcript meta-summary
    # artifacts (e.g. "Claude Deep Research" tile with body containing
    # "You said: …" / "Claude responded: …") would otherwise pass the
    # STRONG-DOC override below — they have prose + headings but are
    # fundamentally a recorded conversation, not the report. Reject when
    # ≥2 chat-chrome lines are present anywhere.
    chat_chrome_lines = sum(
        1 for _l in text.splitlines()
        if re.match(r'^\s*(?:you|chatgpt|gemini|claude|notebooklm|gpt)\s+(?:said|responded)\b',
                    _l, re.I)
    )
    if chat_chrome_lines >= 2:
        return True
    headings = len(re.findall(r'(?m)^#{1,3}\s+\S', text))
    paragraphs = [p for p in text.split('\n\n') if len(p) > 100]
    # STRONG-DOC: clearly long-form prose with at least minimal structure.
    if len(text) >= 4000 and headings >= 2 and any(len(p) >= 200 for p in paragraphs):
        return False
    if headings >= 3 and len(paragraphs) >= 5:
        return False
    # MODERN MARKER: Claude's 1-artifact "Research complete · N sources"
    # layout — if the marker is present alongside any meaningful structure,
    # the artifact is definitely the final report (the tracking checklist
    # never carries this exact marker phrase).
    if re.search(r'research\s+complete(?:d)?\s*[·•—\-\s]+\d[\d,]*\s+sources?', text, re.I) \
            and headings >= 2:
        return False
    checkbox_lines = len(re.findall(r'(?m)^\s*[-*]?\s*\[[ xX]\]\s+\S', text))
    reading_lines = len(re.findall(
        r'(?im)^\s*(?:reading|checking|analyzing|searching)\s+(?:source\s+)?\d+', text))
    total_nonempty = max(1, len([ln for ln in text.splitlines() if ln.strip()]))
    checklist_ratio = checkbox_lines / total_nonempty
    if (checkbox_lines >= 4 or reading_lines >= 4) and headings < 2 and len(text) < 5000 \
            and (checkbox_lines < 4 or checklist_ratio > 0.15 or reading_lines >= 4):
        return True
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    url_only = sum(
        1 for ln in lines
        if re.match(r'^\d+[\.\)]?\s*(?:https?://|[a-z0-9.-]+\.[a-z]{2,}/)', ln, re.I))
    if url_only >= 8 and headings < 2 and 800 <= len(text) <= 3000:
        return True
    return False


def _strip_gemini_panel_noise(md: str) -> str:
    """Trim Gemini's research-panel chrome + post-report noise from the
    raw HTML→MD (T2) or select-all (T3) extraction.

    Gemini's `<immersive-panel>` legitimately contains, after the formal
    report body, a "Sources used in the report" section followed by
    hundreds of citation chips interleaved with Gemini's own thinking-
    trace narration ("Researching websites…", planning-header runs
    without `##` markers). All of that lives inside the same DOM scope
    our selectors match — tighter selectors can't exclude it, strip
    after the html2text pass instead.

    Strips:
      1. Leading toolbar chrome (`Contents` / `Share & Export` / `Create`)
         that Gemini's app shell renders inside the panel root.
      2. Everything at and after `Sources used in the report` — the
         marker is Gemini's UI label, never an author-written heading;
         additionally require a URL-shaped token within ~200 chars
         after the marker to guard against a hypothetical user-prompt
         phrasing collision.
      3. Collapses runs of 3+ blank lines left by the strips.

    Idempotent — safe to call twice."""
    if not md:
        return md
    # Toolbar chrome. Gemini renders this as a single line
    # "ContentsShare & Export" (no separator between the section
    # heading text and the menu label after html_to_markdown collapses
    # the nested elements) followed by "Create" on its own line. Both
    # sit near the top of the panel but AFTER the Gemini Deep Research
    # header + prompt-echo, so MULTILINE not start-anchored.
    md = re.sub(
        r'(?m)^\s*ContentsShare & Export\s*$\n+\s*Create\s*$\n+',
        '',
        md,
    )
    # Strip from "Sources used in the report" to EOF iff a URL appears
    # in the next ~200 chars (confirms Gemini citation panel, not a
    # collision with author phrasing).
    m = re.search(r'^\s*Sources used in the report\s*$', md, re.MULTILINE)
    if m:
        lookahead = md[m.end(): m.end() + 200]
        if re.search(r'https?://', lookahead):
            md = md[:m.start()].rstrip()
    # Collapse 3+ blank lines (the strips can leave awkward gaps).
    md = re.sub(r'\n{3,}', '\n\n', md)
    return md


async def _close_claude_artifact_panel(page):
    """Close the artifact panel by pressing Escape or clicking close."""
    try:
        # Try Escape first (most reliable)
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.3)
        # Verify panel closed by checking if aside/panel shrank
        still_open = await page.evaluate("""() => {
            const panel = document.querySelector('aside, [class*="artifact-panel"], [class*="side-panel"]');
            return panel && panel.offsetWidth > 100;
        }""")
        if still_open:
            # Try clicking close button
            await page.evaluate("""() => {
                const close = document.querySelector(
                    'aside button[aria-label="Close"], ' +
                    '[class*="artifact-panel"] button[aria-label="Close"], ' +
                    'aside button:has(svg[class*="close"]), ' +
                    'button[data-testid="close-artifact"]'
                );
                if (close) close.click();
            }""")
    except Exception:
        pass


async def _claude_artifact_panel_state(page):
    """#914 truthful panel probe — is Claude's right-side artifact/tracking
    panel ACTUALLY open? Geometry-first (mirror of ChatGPT #913's
    `_chatgpt_activity_state`): the 2026-07 claude.ai panel no longer
    reliably carries "artifact-panel"-style class names, so class-anchored
    checks can read "closed" while the panel is plainly open (and vice
    versa). The old call-site flag inferred "open" from "scrape returned
    data" — but that data could come from the CUA fallback which used to
    CLOSE the panel, so the flag lied and the open→read→close churn the
    user saw was invisible to the code.

    Gates (1280×800 automation viewport): a right-DOCKED panel is flush to
    the right edge (right ≥ vw−40) and tall (≥50% vh — matches the read
    path's gate; #906 rule: the verifier must never be stricter than the
    scraper) — a centered chat column (left ≈ 0.2·vw, right ≈ 0.8·vw) and
    message bubbles fail the flush-right gate, dialogs fail it too, and
    the left nav fails the left gate. Text floor is 40 chars (skeleton-
    tolerant) OR an embedded iframe ≥300px wide (artifact content can be
    iframe-mounted; host innerText reads '' then — same lesson as
    ChatGPT's DR-card iframe embed).

    #914b (review find, self-verified): with the SIDEBAR EXPANDED
    (~288px) the nav-right main-content wrapper passes every pure-
    geometry gate at 1280px (left=288 ≥ 0.22vw, flush right, width
    992 ≤ 0.78vw) — a false "open" that would freeze the click forever
    while the walker harvested chat-column junk. Two guards: width cap
    tightened to 0.75·vw (960px < the 992px wrapper; the real panel is
    ~half the viewport), and any candidate CONTAINING chat-thread
    markers (user-message bubbles / .font-claude-message) is skipped —
    the artifact panel never contains the conversation.

    Returns {"open": bool, "width": int, "text_len": int, "menu_open": bool}
    (all-falsy dict on evaluate failure — callers treat that as closed).
    Also reports `menu_open` (visible [role=menu]/radix popper) so callers
    can detect a card-click that landed on a menu trigger instead.
    """
    JS = """() => {
        const out = { open: false, width: 0, text_len: 0, menu_open: false };
        const vw = window.innerWidth || document.documentElement.clientWidth;
        const vh = window.innerHeight || document.documentElement.clientHeight;
        try {
            for (const m of document.querySelectorAll(
                    '[role="menu"], [data-radix-popper-content-wrapper], ' +
                    '[data-radix-menu-content]')) {
                const r = m.getBoundingClientRect();
                if (r.width > 40 && r.height > 40) { out.menu_open = true; break; }
            }
        } catch (e) {}
        const NAV_MARKERS = /\\b(new chat|recents?|projects|search|topic generator|starred|home|chats?\\b)\\b/i;
        const CHAT_MARKERS = '[data-message-author-role="user"], ' +
            '[data-testid="user-message"], .font-claude-message';
        let bestLen = -1, bestArea = Infinity;
        for (const el of document.querySelectorAll('div, aside, section')) {
            const r = el.getBoundingClientRect();
            if (r.width < 380 || r.width > vw * 0.75) continue;
            if (r.left < vw * 0.22) continue;
            if (r.right < vw - 40) continue;
            if (r.height < vh * 0.5) continue;
            if (el.querySelector(CHAT_MARKERS)) continue;
            const txt = (el.innerText || '').trim();
            let hasFrame = false;
            try {
                const fr = el.querySelector('iframe');
                hasFrame = !!(fr && fr.getBoundingClientRect().width >= 300);
            } catch (e) {}
            if (txt.length < 40 && !hasFrame) continue;
            const head = txt.slice(0, 500);
            if (NAV_MARKERS.test(head)) {
                let m = 0;
                const re = new RegExp(NAV_MARKERS.source, 'gi');
                while (re.exec(head) !== null) m++;
                if (m >= 2) continue;
            }
            const area = r.width * r.height;
            if (txt.length > bestLen || (txt.length === bestLen && area < bestArea)) {
                bestLen = txt.length; bestArea = area;
                out.open = true;
                out.width = Math.round(r.width);
                out.text_len = txt.length;
            }
        }
        return out;
    }"""
    try:
        res = await page.evaluate(JS)
        return res if isinstance(res, dict) else {}
    except Exception:
        return {}


async def _log_claude_artifact_snapshot(page, tag=""):
    """#914 (instrument-with-logs directive): one compact structural line of
    the artifact-card candidates + right-half container inventory + frame
    URLs, so a persistent Claude panel miss can be root-caused from
    backend.log alone — no live DOM session needed (probing the worker
    profile out-of-band risks the bot score). Mirror of ChatGPT #913's
    `_log_chatgpt_thread_snapshot`."""
    JS = """() => {
        const sels = [
            'button[data-testid*="artifact"]',
            '[data-testid*="artifact-preview"]',
            '[class*="artifact"][role="button"]',
            'button[aria-label*="Open the artifact"]',
            'button[aria-label*="research"]',
            'a[href*="/artifacts/"]'
        ];
        const counts = {};
        const cards = [];
        for (const s of sels) {
            let hits = [];
            try { hits = Array.from(document.querySelectorAll(s)); } catch (e) {}
            counts[s] = hits.length;
            for (const el of hits) {
                if (cards.length >= 4) break;
                const r = el.getBoundingClientRect();
                cards.push({ s: s.slice(0, 28),
                             t: (el.textContent || '').trim().slice(0, 50),
                             a: (el.getAttribute('aria-label') || '').slice(0, 36),
                             w: Math.round(r.width), h: Math.round(r.height),
                             y: Math.round(r.top) });
            }
        }
        const vw = window.innerWidth || 0;
        const vh = window.innerHeight || 0;
        const panels = [];
        for (const el of document.querySelectorAll('div, aside, section')) {
            if (panels.length >= 6) break;
            const r = el.getBoundingClientRect();
            if (r.width < 300 || r.height < vh * 0.4) continue;
            if (r.left < vw * 0.15) continue;
            if (el.children.length > 12) continue;
            panels.push({ tag: el.tagName,
                          c: (el.className && ('' + el.className).slice(0, 40)) || '',
                          w: Math.round(r.width), l: Math.round(r.left),
                          r: Math.round(r.right), h: Math.round(r.height),
                          tl: (el.innerText || '').length });
        }
        return { counts, cards, panels };
    }"""
    try:
        snap = await page.evaluate(JS)
    except Exception as _se:
        log(f"[Claude] artifact snapshot failed ({tag}): {_se}", "DEBUG")
        return
    try:
        frames = [(f.url or "")[:80] for f in page.frames][:8]
    except Exception:
        frames = []
    try:
        line = json.dumps({"snap": snap, "frames": frames}, ensure_ascii=True)
    except Exception:
        line = str(snap)[:1800]
    log(f"[Claude] artifact-miss snapshot ({tag}): {line[:1800]}", "DEBUG")


# ── Claude's "Gathered N sources" disclosure ─────────────────────────────────
# ⭐⭐ WHY THIS EXISTS, measured from this machine's own logs on 2026-08-22 rather
# than reasoned about. Across `~/.super-research/logs/e2e*.log` + `backend.log`,
# 22 Claude runs reached `CONFIRMED DONE`:
#   * 13 of them recorded ZERO sources — six on reports over 25,000 characters.
#   * 74 of 78 `Artifact tracking:` reads returned exactly ONE url.
#   * `walker_root=class` matched 0 times out of 147; the geometry fallback
#     carries every read, so the class-anchored primary selector is dead.
#   * `didn't stick` fired 28 times against 23 `artifact panel opened`.
# The panel we DO open is the progress CHECKLIST, its rows are not anchors, and
# the walker's sweep is `a[href^="http"]` — so it finds one stray anchor and
# nothing else. The panel that actually enumerates the sources has never been
# pressed. That is what these functions are for.
#
# ⭐ EVERY SELECTOR HERE IS KEYED TO A FACT MEASURED IN THE OWNER'S OWN BROWSER,
# not to a guess:
#   * the control is a <button> carrying `aria-expanded` whose visible label is
#     "Gathered N sources" — role + text is the only stable handle it offers
#   * it is `disabled` when N is 0, so a press that does nothing is a LEGITIMATE
#     outcome and must not log like a failure
#   * the count lives inside that label; there is no separate total element
#   * there is NO data-testid and no data-* hook anywhere in that subtree, so a
#     class-string selector would rot on the next Tailwind build
#
# ⛔ ROW SHAPE IS NOT A PRECONDITION, and that is the whole design. The sampled
# conversation had 0 sources, so whether a row is an `<a href>` or a click-handler
# button — and whether the list virtualises — CANNOT be answered from it: the
# markup does not exist. So this collects anchors AND buttons, scrolls-and-
# accumulates (correct either way), and REPORTS what it found on every run. The
# unknown is an observation the code emits, never an assumption a selector encodes.
#
# ⛔⛔ SCOPE. `_count_claude_artifacts` and `_click_claude_artifact` are
# deliberately UNTOUCHED. They feed extraction, publish, the poll loop and two
# count gates, and an earlier version of this feature was REVERTED for reaching
# into them. The guard that recorded that decision asked for the replacement to be
# "deliberate and isolated, never a passenger on an unrelated fix" — this is that
# isolated change. See tests/test_claude_health_and_sources_panel.py.
#
# ⚠ "Gathered N sources" also appears as a CHECKLIST ROW in the tracking panel
# (ten CUA readings in the corpus describe it that way). A row is an li/div, so
# requiring `button, [role="button"]` already excludes it — but the tag name is
# logged anyway, because "we matched a row" and "we matched the control" are
# different facts and the log is the only place that can tell them apart.

#: The attribute value `_sr_real_click` aims at. Its own constant so the JS that
#: stamps it and the Python that presses it cannot drift apart.
_CLAUDE_SOURCES_CLICK_VALUE = "claude-sources-toggle"

# THE FINDER, and it is one definition on purpose. `_count_claude_artifacts` and
# `_click_claude_artifact` drifted apart in exactly this way (#736: the count
# over-reported by one, the click's target index fell out of range) and the note
# there says the selector must change in both places at once. A shared string is
# the version of that rule an edit cannot forget — and the mutation harness for
# this wave found the second copy the first time it ran, before it could drift.
#
# ⛔ SYNCHRONOUS ON PURPOSE, and this is load-bearing rather than stylistic:
# `tests/_domshim.py` has no `setTimeout` and `run_js` JSON-stringifies the
# return value, so an async page-JS body is not executable by the harness — it
# could only ever be source-scanned, and this repo has shipped an inverted gate
# that way before. Every wait, press and scroll lives in Python, which is also
# the house "search in JS, press in Playwright" rule. The constraint and the
# convention agree.
_CLAUDE_SOURCES_FIND_JS = r"""
    // ⛔ ONE digit, and commas. The capture script written to MEASURE this
    // control demanded `\d{2,4}` and therefore reported "(none found)" while
    // `Gathered 0 sources` sat in the DOM — a measurement tool carrying the same
    // class of bug as the code it was measuring. A count regex that cannot see
    // zero cannot tell "no sources" from "no control", which is the one
    // distinction this whole path exists to make.
    const GATHERED = /gathered\s+([\d,]+)\s+sources?/i;
    // Fallback shape: a disclosure control whose label merely COUNTS sources
    // ("12 sources"). Survives a reword of the verb — the likeliest part to rot —
    // and still refuses anything that is not a disclosure control. Without the
    // aria-expanded requirement this would also match the running ticker and the
    // finished report card, neither of which opens a source list.
    const BARE = /\b([\d,]+)\s+sources?\b/i;
    const num = (s) => parseInt(String(s).replace(/,/g, ''), 10);
    const labels = (el) => [
        (el.textContent || '').replace(/\s+/g, ' ').trim(),
        (el.getAttribute('aria-label') || '').replace(/\s+/g, ' ').trim(),
    ];
    const find = () => {
        const btns = Array.from(document.querySelectorAll('button, [role="button"]'));
        for (const b of btns) {
            for (const s of labels(b)) {
                const m = s.match(GATHERED);
                if (m) return { el: b, count: num(m[1]), shape: 'gathered' };
            }
        }
        for (const b of btns) {
            if (!b.hasAttribute('aria-expanded')) continue;
            for (const s of labels(b)) {
                const m = s.match(BARE);
                if (m) return { el: b, count: num(m[1]), shape: 'bare-count' };
            }
        }
        return null;
    };
    // The disclosed region: the control's own aria-controls when it offers one,
    // else the nearest ancestor holding a list the control is not itself inside.
    //
    // ⛔ querySelectorALL, and a test caught this. `querySelector` returns the
    // first match in DOCUMENT ORDER, and on the real page the first list under a
    // shared ancestor is the progress CHECKLIST the toggle is a row of. With a
    // single-match read the guard rejected that one list and abandoned the whole
    // ancestor, walking straight past the source list sitting beside it. This is
    // the exact selector-semantics class `_domshim` exists to catch.
    const regionFor = (tog) => {
        const cid = tog.getAttribute('aria-controls');
        if (cid) {
            const byId = document.getElementById(cid);
            if (byId) return { el: byId, how: 'aria-controls' };
        }
        let n = tog.parentElement, hops = 0;
        while (n && hops++ < 8) {
            for (const l of n.querySelectorAll('ol, ul, [role="list"]')) {
                if (!l.contains(tog)) return { el: l, how: 'ancestor-list' };
            }
            n = n.parentElement;
        }
        const par = tog.parentElement;
        return par ? { el: par, how: 'parent' } : { el: null, how: 'none' };
    };
    // The scroll box: the region itself, or the first scrollable node in it.
    const scrollBoxIn = (region) => {
        for (const e of [region].concat(Array.from(region.querySelectorAll('*')))) {
            if (+(e.scrollHeight || 0) > +(e.clientHeight || 0) + 4) return e;
        }
        return null;
    };
"""

_CLAUDE_SOURCES_PROBE_JS = r"""(mark) => {""" + _CLAUDE_SOURCES_FIND_JS + r"""
    const out = {found: false, count: 0, shape: '', tag: '', disabled: false,
                 expanded: false, marked: false, region: 'none', rows: 0,
                 links: 0, buttons: 0, scroll_h: 0, client_h: 0,
                 scrollable: false, urls: [], hosts: [], row_sample: []};
    const hit = find();
    if (!hit) return out;
    out.found = true;
    out.count = hit.count;
    out.shape = hit.shape;
    out.tag = hit.el.tagName || '';
    // HTML semantics, and they differ between the two: the `disabled`
    // ATTRIBUTE's PRESENCE disables (so `disabled="false"` is still disabled),
    // while `aria-disabled` is a string that must equal "true".
    out.disabled = !!hit.el.disabled
        || hit.el.getAttribute('aria-disabled') === 'true';
    out.expanded = hit.el.getAttribute('aria-expanded') === 'true';
    // Stamp for a REAL press. A synthetic el.click() dispatches a click event
    // and nothing else; claude.ai's disclosures are React components whose
    // trigger listens on pointerdown, and this codebase has already paid for
    // that lesson once (see _SR_CLICK_MARK).
    if (mark && !out.disabled && !out.expanded) {
        try { hit.el.setAttribute(mark, "__VALUE__"); out.marked = true; } catch (e) {}
    }

    const found = regionFor(hit.el);
    const region = found.el;
    out.region = found.how;
    if (!region) return out;

    // ⛔ The CONTROL IS NOT A ROW. When the region falls back to the toggle's own
    // parent there is no list to scope to, so the toggle itself sits among the
    // candidates — and counting it would report `rows=1` for a panel that
    // disclosed nothing, which reads as "we found a source" rather than "we
    // found nothing". Its own label is also a source count, so it would have
    // contributed a bogus host too.
    const rowsOf = (r) => {
        let rs = Array.from(r.querySelectorAll('li, [role="listitem"]'));
        if (!rs.length) rs = Array.from(r.children || []);
        return rs.filter(e => e !== hit.el && !e.contains(hit.el)
                              && ((e.innerText || '').trim().length > 2));
    };
    // Read the scroll box DEFENSIVELY. A collapsed region reports 0/0 and a
    // 5-row list reports scrollHeight == clientHeight — the measured state — so
    // "not scrollable" is a legitimate answer here, never a failure.
    out.scroll_h = +(region.scrollHeight || 0);
    out.client_h = +(region.clientHeight || 0);
    out.scrollable = !!scrollBoxIn(region);

    const seenUrl = [], seenHost = [];
    // Hosts come from ROW TEXT, and they stay hosts. A row with no anchor gives
    // us a domain, not a link, and synthesising "https://" + domain would put a
    // FABRICATED url into source_urls — which feeds the findings cards and the
    // user-visible source list. A host count is a true fact; an invented url is
    // not, and this file has already discarded 56% of a run's real sources by
    // matching a whole url where it meant to match a host.
    const HOST_RE = /\b([a-z0-9][a-z0-9-]*(?:\.[a-z0-9-]+)*\.[a-z]{2,})\b/i;
    for (const a of region.querySelectorAll('a[href]')) {
        const h = a.href || a.getAttribute('href') || '';
        if (!/^https?:/i.test(h)) continue;
        if (h.length >= 500) continue;
        if (h.indexOf('claude.ai') !== -1 || h.indexOf('anthropic.com') !== -1) continue;
        if (seenUrl.indexOf(h) === -1) seenUrl.push(h);
    }
    for (const r of rowsOf(region)) {
        const t = (r.innerText || '').replace(/\s+/g, ' ').trim();
        if (!t) continue;
        out.rows += 1;
        if (out.row_sample.length < 5) out.row_sample.push(t.slice(0, 90));
        const m = t.match(HOST_RE);
        if (m) {
            const host = m[1].toLowerCase().replace(/^www\./, '').replace(/\.$/, '');
            if (seenHost.indexOf(host) === -1) seenHost.push(host);
        }
    }
    out.links = seenUrl.length;
    out.buttons = region.querySelectorAll('button, [role="button"]').length;
    out.urls = seenUrl.slice(0, 200);
    out.hosts = seenHost.slice(0, 200);
    return out;
}""".replace("__VALUE__", _CLAUDE_SOURCES_CLICK_VALUE)


#: The outcomes `read_claude_sources_panel` can report. A tuple rather than a set
#: of scattered string literals because the whole point of the function is that
#: these are DISTINCT — "the control says zero" and "the press did nothing" have
#: opposite next moves, and the code this replaces could say neither.
_CLAUDE_SOURCES_OUTCOMES = ("absent", "disabled", "already_open", "opened",
                            "press_failed", "read_failed")


async def _claude_sources_toggle_state(page):
    """Read-only probe of Claude's "Gathered N sources" disclosure.

    Presses nothing, so it is safe on every poll. Returns the probe dict, and an
    ALL-FALSY dict on any evaluate failure — so a caller reads a failure as "no
    control", never as a zero count. Those are different facts: ``found=False``
    means we could not see the control, ``found=True, count=0`` means Claude
    says there are no sources. Nothing downstream may conflate them.

    ⚠ Deliberately does NOT press. The scraper must stay read-only for two
    independent reasons: the control is a TOGGLE, so a press on an already-open
    panel CLOSES it (the P1 lesson — a "miss" can mean we closed what was open);
    and `scrape_progress_claude` routes its source count into
    `if (!hasStop && liveSrcCount > 0) hasStop = true`, so anything that grows a
    count on the scrape path can pin a finished run at "generating" forever.
    """
    try:
        res = await page.evaluate(_CLAUDE_SOURCES_PROBE_JS, "")
        return res if isinstance(res, dict) else {}
    except Exception:
        return {}


async def read_claude_sources_panel(page, max_scrolls: int = 12,
                                    settle_s: float = 0.25):
    """Open Claude's sources disclosure and read its rows. One press, one read.

    Always returns a dict carrying ``outcome`` (one of
    ``_CLAUDE_SOURCES_OUTCOMES``) plus whatever was observed. It decides nothing
    and logs nothing — `claude_sources_log_line` turns the result into a line,
    so the severity decision sits in a pure function a test can call.

    The outcomes, and why each is its own state rather than a bool:
      ``absent``       no such control on the page. Expected early in a run.
      ``disabled``     the control is there and says N == 0. NOT a failure —
                       Claude is telling us there is nothing to read.
      ``already_open`` found expanded; rows read without pressing anything.
      ``opened``       pressed, the control's OWN aria-expanded went true.
      ``press_failed`` enabled, pressed, never expanded. THIS is the failure,
                       and it is the one the old code could not tell from
                       either of the two above.
      ``read_failed``  the evaluate itself threw.

    ⭐ "It opened" is read from the control's own `aria-expanded`, never from
    "rows came back". #914 paid for that distinction on this exact panel: a flag
    inferred from "the scrape returned data" lied open for a panel the CUA had
    closed, and the re-click was skipped forever.

    ``rows_before``/``rows_after`` bracket the scroll-and-accumulate loop, so a
    virtualising list shows up as after > before and a static one as equal. That
    answers the row-shape and virtualisation questions from a real run instead
    of from an empty panel, which cannot answer them at all.
    """
    try:
        first = await page.evaluate(_CLAUDE_SOURCES_PROBE_JS,
                                    _SR_CLICK_MARK)
    except Exception as e:
        return {"outcome": "read_failed", "error": str(e)[:160]}
    if not isinstance(first, dict) or not first.get("found"):
        return {"outcome": "absent"}
    if first.get("disabled"):
        return dict(first, outcome="disabled")

    press = ""
    if not first.get("expanded"):
        if not first.get("marked"):
            # The JS found the control but could not stamp it, so Playwright has
            # nothing to aim at. Reporting this as a press failure is the honest
            # answer — we did not press.
            return dict(first, outcome="press_failed", press="unmarked")
        press = await _sr_real_click(page, _CLAUDE_SOURCES_CLICK_VALUE,
                                     tag="[Claude]")
        # Poll for the control to report ITSELF open. A fixed sleep guesses; this
        # waits exactly as long as it needs to and no longer.
        opened = False
        for _ in range(10):
            await asyncio.sleep(0.2)
            again = await _claude_sources_toggle_state(page)
            if again.get("expanded"):
                opened = True
                break
        if not opened:
            return dict(first, outcome="press_failed", press=press or "none")

    # Re-probe: a React re-render replaces the node, so the region and inventory
    # must be read AFTER the disclosure settled, not from the pre-press snapshot.
    cur = await _claude_sources_toggle_state(page)
    if not cur.get("found"):
        return dict(first, outcome="read_failed", press=press or "none",
                    error="control vanished after opening")
    res = dict(cur)
    res["outcome"] = "already_open" if first.get("expanded") else "opened"
    res["press"] = press or "none"
    res["rows_before"] = int(cur.get("rows", 0) or 0)

    # Scroll-and-accumulate. Correct whether or not the list virtualises, which
    # is the point: at 5 rows the measured region reports scrollHeight ==
    # clientHeight, so nothing about virtualisation can be inferred from a short
    # list and the loop must simply be harmless when there is nothing to scroll.
    urls = list(res.get("urls") or [])
    hosts = list(res.get("hosts") or [])
    samples = list(res.get("row_sample") or [])
    scrolls = 0
    if cur.get("scrollable"):
        flat = 0
        for i in range(max(0, int(max_scrolls))):
            if flat >= 2:
                break
            try:
                await page.evaluate(_CLAUDE_SOURCES_SCROLL_JS)
            except Exception:
                break
            scrolls = i + 1
            await asyncio.sleep(settle_s)
            nxt = await _claude_sources_toggle_state(page)
            grew = False
            for u in (nxt.get("urls") or []):
                if u not in urls:
                    urls.append(u)
                    grew = True
            for h in (nxt.get("hosts") or []):
                if h not in hosts:
                    hosts.append(h)
                    grew = True
            for s in (nxt.get("row_sample") or []):
                if s not in samples and len(samples) < 12:
                    samples.append(s)
            if int(nxt.get("rows", 0) or 0) > int(res.get("rows", 0) or 0):
                res["rows"] = int(nxt.get("rows", 0) or 0)
                grew = True
            # Stop on two consecutive rounds that add nothing, rather than on a
            # fixed count: a fixed count under-reads a long list and burns
            # rounds on a short one.
            flat = 0 if grew else flat + 1
    res["urls"] = urls[:_SOURCE_LIST_CAP]
    res["hosts"] = hosts[:_SOURCE_LIST_CAP]
    res["row_sample"] = samples
    res["links"] = len(res["urls"])
    res["rows_after"] = int(res.get("rows", 0) or 0)
    res["scrolls"] = scrolls
    return res


# Scroll the disclosed region by roughly one page. Separate from the probe so the
# probe stays a pure READ — a function that both measures and mutates cannot be
# used to check its own effect. It splices in the SAME finder, so the control and
# region this scrolls are by construction the ones the probe measured; two copies
# that merely happen to agree is the #736 defect.
_CLAUDE_SOURCES_SCROLL_JS = r"""() => {""" + _CLAUDE_SOURCES_FIND_JS + r"""
    const hit = find();
    if (!hit) return {scrolled: false, reason: 'no-toggle'};
    const region = regionFor(hit.el).el;
    if (!region) return {scrolled: false, reason: 'no-region'};
    const box = scrollBoxIn(region);
    if (!box) return {scrolled: false, reason: 'not-scrollable'};
    const step = Math.max(120, +(box.clientHeight || 0) * 0.8);
    box.scrollTop = Math.min(+(box.scrollTop || 0) + step, +(box.scrollHeight || 0));
    return {scrolled: true, top: +(box.scrollTop || 0)};
}"""


def claude_sources_log_line(res: dict) -> tuple:
    """Turn one ``read_claude_sources_panel`` result into ``(message, level)``.

    Pure and module-level on purpose: the poll leg that calls it is a closure
    inside ``poll_all_agents_round_robin``, which nothing in the suite executes —
    a severity decision written inline there could only ever be source-scanned,
    and mutation has already proved that a source-scanned gate can ship inverted.

    The severities ARE the item. ``disabled`` is INFO because Claude reporting
    zero sources is an answer, not a fault, and `note_line` tallies WARN into the
    per-run meta a support bundle is triaged on — a benign WARN makes an ordinary
    run look faulty. Only a press that did not land, a read that threw, and an
    opened-but-empty panel are owner-visible enough to warrant WARN.
    """
    r = res or {}
    o = r.get("outcome") or "absent"
    n = int(r.get("count", 0) or 0)
    if o == "absent":
        return ("[Claude] sources toggle not on the page", "DEBUG")
    if o == "disabled":
        return (f"[Claude] sources toggle reports {n} sources and is disabled — "
                "nothing to read (Claude's answer, not a failure)", "INFO")
    if o == "press_failed":
        return (f"[Claude] sources toggle says {n} sources but never expanded "
                f"(press={r.get('press') or 'none'}) — the source list was "
                "not read", "WARN")
    if o == "read_failed":
        return (f"[Claude] sources toggle read failed: "
                f"{r.get('error') or 'evaluate error'}", "WARN")
    # opened / already_open — ONE line carrying every runtime observation the
    # 0-source capture could not give us: whether rows are anchors or buttons,
    # whether the list virtualises, and how the region was resolved.
    detail = (f"[Claude] sources panel {o}: label={n} "
              f"rows {r.get('rows_before', 0)}->{r.get('rows_after', 0)} "
              f"links={r.get('links', 0)} buttons={r.get('buttons', 0)} "
              f"hosts={len(r.get('hosts') or [])} "
              f"region={r.get('region')} tag={r.get('tag')} "
              f"shape={r.get('shape')} scrolls={r.get('scrolls', 0)} "
              f"scrollable={bool(r.get('scrollable'))} "
              f"box={r.get('scroll_h', 0)}/{r.get('client_h', 0)} "
              f"press={r.get('press') or 'none'}")
    if not (r.get("urls") or r.get("hosts") or r.get("rows_after")):
        return (detail + " — opened but EMPTY", "WARN")
    return (detail, "INFO")


def claude_source_count(live: int = 0, printed: int = 0,
                        toggle_label: int = 0, vision: int = 0) -> int:
    """One source number from the union of every place Claude states it.

    Claude prints its own source count in three separate surfaces, each blind in
    a different way, and until now every one of them was matched with `.test()`
    and the number thrown away:

      ``live``          "N sources and counting" — the mid-run ticker. Gone the
                        moment the run finishes.
      ``printed``       "Research complete · N sources · 24m" — the final figure.
                        Absent while the run is still going.
      ``toggle_label``  "Gathered N sources" on the disclosure. Legitimately 0.

    ``vision`` is the fourth input and not one of Claude's own: the Gemini panel
    estimate already landing in `observed_sources`. It is folded in here so the
    union cannot LOSE a number that field was already carrying.

    The union is the maximum, because these are views of ONE quantity and each
    can only UNDER-report — a surface that has not rendered reads 0, and none of
    them can invent sources. Max is therefore the only combination that cannot
    drop a number Claude actually gave us.

    ⚠ This is `observed_sources`, NOT `sources`. `sources == len(source_urls)`
    is load-bearing: the FE chip disagreed with an empty url list the last time
    the two were merged. The frontend already takes the max of both fields, so
    widening this one is enough to fix the displayed number without touching
    that invariant — and without a frontend release.

    ⚠ Per-call, deliberately NOT monotonic. A high-water mark cannot fall, so one
    bad high read (a vision over-count, or a label belonging to a different turn
    in the same document) would be permanent for the whole run.
    """
    def _n(v):
        try:
            i = int(v or 0)
        except (TypeError, ValueError):
            return 0
        return i if i > 0 else 0
    return max(_n(live), _n(printed), _n(toggle_label), _n(vision))


def merge_claude_sources(snap: dict, urls=None, hosts=None,
                         label_count: int = 0) -> dict:
    """Fold a sources-panel read into the progress snapshot, in place.

    ⚠ THE SNAPSHOT, not `progress`. `extract_and_record_agent` reads
    `_runtime.agent_progress_snapshots[...]` — for the findings extraction and
    for the completion emit's sourceUrls/sources — and that snapshot is written
    once per poll cycle BEFORE the finished-run read happens. Merging into
    `progress` alone would be dead by the time anything looked.

    Dedupe keeps the FIRST-seen url, so a panel row already present from an
    earlier cycle keeps its original form rather than being replaced by a
    late duplicate. `sources` stays exactly `len(source_urls)`; the label count
    goes to `observed_sources` through `claude_source_count`.
    """
    out = snap if isinstance(snap, dict) else {}
    existing = list(out.get("source_urls") or [])
    seen = set(existing)
    for u in (urls or []):
        if u and u not in seen:
            seen.add(u)
            existing.append(u)
    out["source_urls"] = existing[:_SOURCE_LIST_CAP]
    out["sources"] = len(out["source_urls"])
    out["observed_sources"] = claude_source_count(
        live=int(out.get("observed_sources", 0) or 0),
        toggle_label=int(label_count or 0),
    )
    # Hosts are recorded as a COUNT, never expanded into urls. A row with no
    # anchor gives a domain, not a link; synthesising one would put a fabricated
    # url in front of the user.
    #
    # ⛔⛔ RENAMED 2026-08-24, AND THE OLD NAME WAS A TYPE COLLISION. This wrote
    # an INT to `source_hosts` — the same key the ChatGPT inline-chip path
    # carries a LIST of hostnames under, which `_merge_host_chips` iterates. The
    # two never met, so nothing broke; routing a Claude snapshot through that
    # helper would have iterated an integer. Two paths, one key, opposite types
    # and opposite decisions about the same question (ChatGPT DOES synthesise
    # `https://<host>/`, with its own reasoning). Named for what it holds.
    #
    # ⭐ AND IT NOW HAS A READER. Found by cross-verification as a value written
    # every run and consumed by nothing: the completion emit and meta.json
    # forwarded neither, and the next poll cycle overwrote the snapshot. A count
    # nobody reads cannot tell anyone that the panel held eight domains and no
    # links — which is the one thing it exists to say.
    if hosts:
        out["source_host_count"] = len({h for h in hosts if h})
    return out


def claude_sources_run_verdict(*, url_count, observed_count, panel_ever_opened,
                               toggle_outcome) -> tuple:
    """The one line that says whether a FINISHED Claude run gave us its sources.

    Returns ``(message, level)``. This is the item's "one WARN for a never-opened
    panel", moved to where it is actually owner-relevant — and the move is the
    point, not a dodge.

    A never-opened panel by itself is NOT owner-actionable: nothing in settings
    or a retry addresses it, the report still extracts through an independent
    path, and `note_line` folds every WARN into the per-run meta a support bundle
    is triaged on — so a benign per-phase WARN makes an ordinary run look faulty.
    What IS worth an owner's attention is the OUTCOME: a finished run whose
    sources we do not have.

    So the severity turns on the one distinction that has been invisible all
    along — whether a zero is Claude's answer or our blindness:

      * urls > 0                      → INFO. We have them.
      * urls == 0, Claude said N > 0  → WARN. The number exists and the sources
                                        do not; that gap is ours.
      * urls == 0, the toggle said 0  → INFO. Claude genuinely had none. The
                                        disclosure is authoritative here, and
                                        this is the only reason it is worth
                                        pressing at all.
      * urls == 0, no number anywhere → WARN. We cannot tell an empty run from a
                                        blind one, which is exactly the state 13
                                        of 22 corpus runs ended in.
    """
    u = int(url_count or 0)
    n = int(observed_count or 0)
    tail = (f"(panel_ever_opened={bool(panel_ever_opened)}, "
            f"toggle={toggle_outcome or 'not-read'})")
    if u > 0:
        return (f"[Claude] finished with {u} source urls "
                f"(Claude's own count: {n or 'unknown'}) {tail}", "INFO")
    if n > 0:
        return (f"[Claude] finished with ZERO source urls while Claude reported "
                f"{n} sources — the count is ours, the sources are not {tail}",
                "WARN")
    if toggle_outcome == "disabled":
        return ("[Claude] finished with no sources, and its own disclosure says "
                f"0 — an empty result, not a failed read {tail}", "INFO")
    return ("[Claude] finished with ZERO sources from every tier and no count "
            "from Claude either — an empty run and a blind read are "
            f"indistinguishable here {tail}", "WARN")


async def claude_finished_sources_read(page, p, snapshots, *,
                                       agent_key: str = "claude"):
    """Press Claude's sources disclosure ONCE, at the point the run is done.

    Returns the panel result (or None when it was skipped), so a caller can log
    a run-level outcome. The latch lives on ``p``, which is rebuilt per phase, so
    "once" means once per RUN and not once per process — `--serve` runs many runs
    in one process and a module global would silence every run after the first.

    ⛔⛔ CALLED FROM BOTH EXTRACT SITES, and that is the whole reason this is a
    function. ``extract_and_record_agent`` has TWO call sites for the same agent:
    the Playwright-confirmed-done path and the CUA-confirmed-done path. Claude
    reaching completion through the CUA never passes the first one — and the
    corpus run this fix exists for ("5 URLs, 15 steps") went through exactly that
    path, because only the CUA, which scrolls first, ever caught it. A read wired
    to one site only would have been a guard that cannot fire on the runs it was
    written for.

    ⚠ Must run BEFORE ``extract_claude_response``, which closes the artifact
    panel as its first act.
    """
    if p is None or p.get("_claude_sources_read_done"):
        return None
    p["_claude_sources_read_done"] = True
    try:
        res = await read_claude_sources_panel(page)
    except Exception as e:
        log(f"[Claude] sources panel read raised: {e}", "WARN")
        return None
    msg, lvl = claude_sources_log_line(res)
    log(msg, lvl)
    snap = None
    try:
        snap = (snapshots or {}).get(agent_key)
        if isinstance(snap, dict):
            before = len(snap.get("source_urls") or [])
            merge_claude_sources(snap, res.get("urls"), res.get("hosts"),
                                 int(res.get("count", 0) or 0))
            after = len(snap.get("source_urls") or [])
            if after != before:
                log(f"[Claude] sources panel added {after - before} urls to the "
                    f"snapshot ({before} -> {after})", "INFO")
    except Exception as e:
        log(f"[Claude] sources merge into snapshot skipped: {e}", "DEBUG")
    # The run-level verdict, AFTER the merge so it judges the final numbers. This
    # is the only place that can say whether a zero is Claude's answer or ours.
    try:
        _s = snap if isinstance(snap, dict) else {}
        _vmsg, _vlvl = claude_sources_run_verdict(
            url_count=len(_s.get("source_urls") or []),
            observed_count=int(_s.get("observed_sources", 0) or 0),
            panel_ever_opened=bool((p or {}).get("_claude_panel_ever_open")),
            toggle_outcome=res.get("outcome"),
        )
        log(_vmsg, _vlvl)
    except Exception as e:
        log(f"[Claude] sources run verdict skipped: {e}", "DEBUG")
    return res


async def scrape_claude_artifact_tracking(page, browser=None, cua_client=None,
                                          verbose=False, keep_open=False,
                                          already_open=False):
    """Scrape Claude's FIRST artifact for tracking/progress data during active research.
    DOM-first with CUA fallback. Returns enriched progress dict or None.
    keep_open=True: don't close the panel after read (re-used across polls).
    already_open=True: skip the click step (panel already open from prior poll)."""
    artifact_count = await _count_claude_artifacts(page)
    if artifact_count == 0:
        # ⛔ THIS RETURN WAS COMPLETELY SILENT, and it is the earliest gate in the
        # whole Claude tracking path — a wrong zero (selectors matched nothing on
        # a page that does have a card) is byte-identical to a genuine zero, and
        # both skipped the panel read, the CUA fallback and every log line with
        # it. Measured: 28 of 147 tracking reads came back with no panel at all.
        # The caller's DOM-miss counter is the only trace, and it is DEBUG.
        # Saying so costs nothing and makes the difference diagnosable.
        log("[Claude] artifact tracking skipped — the card count read 0 "
            "(no card rendered yet, or the card selectors matched nothing)",
            "DEBUG")
        return None

    content = ""
    walker = {"steps": [], "sections": [], "source_urls": []}

    # Layer 1: DOM probe — open panel (if not already), read panel + DOM walker
    _click_box = None  # Track-B: the clicked card's viewport center — ONLY when WE clicked this call
    try:
        if not already_open:
            clicked = await _click_claude_artifact(page, index=0)
            if clicked:
                if isinstance(clicked, dict):
                    _click_box = clicked
                await asyncio.sleep(1.5)  # Wait for panel to render
                # #914 post-click guard: probe what the click ACTUALLY did.
                # E2E runs showed the CUA repeatedly finding an open CONTEXT
                # MENU on arrival ("Good, the context menu is closed…") —
                # i.e. our card click had landed on a menu trigger. Detect
                # + Escape it instead of leaving it for the CUA, and log
                # the observed state either way (instrument-with-logs).
                _st_click = await _claude_artifact_panel_state(page)
                if _st_click.get("menu_open"):
                    log("[Claude] artifact click opened a context menu — "
                        f"Escape dispatched (panel_open={_st_click.get('open')})",
                        "WARN")
                    await _log_claude_artifact_snapshot(page, "click-opened-menu")
                    try:
                        await page.keyboard.press("Escape")
                        await asyncio.sleep(0.3)
                    except Exception:
                        pass
                elif not _st_click.get("open"):
                    log("[Claude] artifact click did not mount the side panel "
                        f"(text_len={_st_click.get('text_len')})", "DEBUG")
                else:
                    log("[Claude] artifact panel open after click "
                        f"(width={_st_click.get('width')}, "
                        f"text_len={_st_click.get('text_len')})", "DEBUG")
            else:
                log("[Claude] artifact card click found no target "
                    "(count saw cards, click's filtered set was empty)", "DEBUG")
        content = await _read_claude_artifact_panel(page)
        # Structured DOM walker — cheaper + more accurate than regex on plain text.
        # Reads the live artifact's checklist headings + section list + URL anchors
        # so steps[]/sections[]/source_urls[] reflect Claude's running outline.
        try:
            walker = await page.evaluate("""() => {
                const out = { steps: [], sections: [], source_urls: [], root: '' };
                // #914: the old root fell back to bare `aside` (claude.ai's
                // LEFT NAV is an <aside> — 2026-05-13 lesson in
                // _CLAUDE_PANEL_SELECTORS_JS) and then to `document`, so with
                // the panel unmatched the steps/sections sweep harvested nav
                // rows / chat chrome — the suspiciously constant "15 steps,
                // 15 sections" in every E2E tracking line. Root at the real
                // panel only: artifact-classed match OR the #914 geometry
                // panel (right-docked, flush right, panel-sized). No root →
                // no steps/sections (junk is worse than empty narration);
                // source_urls fall back to a nav-excluded document sweep
                // (external anchors in the thread are legitimate sources).
                const vw = window.innerWidth || document.documentElement.clientWidth;
                const vh = window.innerHeight || document.documentElement.clientHeight;
                let root = document.querySelector(
                    '[data-testid="artifact-content"], [class*="artifact-panel"]');
                if (root) {
                    const rr = root.getBoundingClientRect();
                    if (rr.width < 200 || rr.height < 150) root = null;
                    else out.root = 'class';
                }
                if (!root) {
                    // #914b: same chat-marker + 0.75vw guards as the probe/
                    // reader — the expanded-sidebar main wrapper must never
                    // become the walker root (chat-column junk steps).
                    const CHAT_MARKERS = '[data-message-author-role="user"], ' +
                        '[data-testid="user-message"], .font-claude-message';
                    let bestLen = -1, bestArea = Infinity;
                    for (const el of document.querySelectorAll('div, aside, section')) {
                        const r = el.getBoundingClientRect();
                        if (r.width < 380 || r.width > vw * 0.75) continue;
                        if (r.left < vw * 0.22) continue;
                        if (r.right < vw - 40) continue;
                        if (r.height < vh * 0.5) continue;
                        if (el.querySelector(CHAT_MARKERS)) continue;
                        const txt = (el.innerText || '');
                        if (txt.length < 40) continue;
                        const area = r.width * r.height;
                        if (txt.length > bestLen ||
                                (txt.length === bestLen && area < bestArea)) {
                            root = el; bestLen = txt.length; bestArea = area;
                        }
                    }
                    if (root) out.root = 'geo';
                }
                if (root) {
                    root.querySelectorAll(
                        'li, [role="listitem"], [class*="step"], [class*="checklist"] > div, ' +
                        '[class*="task"] > div, [class*="activity"]'
                    ).forEach(e => {
                        const t = (e.innerText || '').trim();
                        if (t && t.length > 4 && t.length < 240) out.steps.push(t.slice(0, 220));
                    });
                    root.querySelectorAll('h1, h2, h3').forEach(h => {
                        const t = (h.innerText || '').trim();
                        if (t && t.length > 1 && t.length < 120) out.sections.push(t);
                    });
                }
                const seen = new Set();
                (root || document).querySelectorAll('a[href^="http"]').forEach(a => {
                    const h = a.href || '';
                    if (!root && a.closest('nav, aside, [class*="sidebar" i]')) return;
                    if (h && h.length < 500 && !h.includes('claude.ai') &&
                        !h.includes('anthropic.com') && !seen.has(h)) {
                        seen.add(h); out.source_urls.push(h);
                    }
                });
                out.steps = out.steps.slice(-15);
                out.sections = out.sections.slice(0, 20);
                out.source_urls = out.source_urls.slice(0, 200);
                return out;
            }""")
        except Exception as _we:
            log(f"[Claude] artifact DOM walker skipped: {_we}", "DEBUG")
        if not keep_open:
            await _close_claude_artifact_panel(page)
    except Exception as e:
        log(f"[Claude] Artifact DOM tracking failed: {e}", "WARN")

    # Layer 2: CUA fallback if DOM yielded nothing
    _layer = "dom"
    if not content and not walker.get("source_urls") and browser and cua_client:
        try:
            async def _scrape_cua():
                # #914: the task text used to end "Then close the artifact
                # panel." — directly contradicting the system prompt's step
                # 5 ("DO NOT close the artifact panel"). The CUA obeyed the
                # task text, so every fallback read CLOSED the panel while
                # the call site flagged it open → the open→read→close churn
                # the user watched all E2E (2026-07-08). The panel must
                # STAY OPEN across polls, exactly like ChatGPT #913.
                return await agent_loop(cua_client, browser,
                    PROMPT_SCRAPE_CLAUDE_ARTIFACT_TRACKING,
                    "Open the first artifact in the conversation (skip this if "
                    "the right-side panel is already open) and read its content. "
                    "Report URLs, steps, sections, and sources found. LEAVE the "
                    "artifact panel OPEN when you finish — do NOT close it; the "
                    "polling loop re-reads the open panel each cycle.",
                    model=CUA_MODEL, max_iterations=6, verbose=verbose)

            # #839 act tier: the report itself is the value here — a Vision
            # success puts the read-out (URLs/steps/sections) in the returned
            # text, which the same regexes below parse. Vision's report is
            # shorter than CUA narration (single tool call) but the >=5-char /
            # walker-URL gate below is unchanged either way.
            result = await _shadow_observed_cua(
                page, hotspot_id="scrape-artifact", phase=2, platform="claude",
                current_step="scrape_artifact_1_tracking",
                context_hint="DOM walker yielded nothing — open the FIRST artifact "
                             "(research/sources tracking) unless the panel is "
                             "already open, read URLs/steps/sections, and LEAVE "
                             "the panel OPEN for the next poll",
                expected_outcome="a text report of the tracking artifact's URLs, steps and sections",
                cua_coro_factory=_scrape_cua,
                mission_prompt=PROMPT_SCRAPE_CLAUDE_ARTIFACT_TRACKING)
            content = (result or {}).get("text", "")
            if content:
                _layer = "cua"
        except Exception as e:
            log(f"[Claude] Artifact CUA tracking failed: {e}", "WARN")

    # Lowered gate: 5 chars (was 30) — accept partials. Walker URLs alone count.
    if (not content or len(content) < 5) and not walker.get("source_urls"):
        return None

    # Prefer DOM-walker output; fall back to regex on plain text only when walker empty.
    urls = walker["source_urls"] or list(dict.fromkeys(re.findall(r'https?://[^\s)>\]"]+', content or "")))[:_SOURCE_LIST_CAP]
    steps = walker["steps"] or re.findall(r'(?:^|\n)\s*(?:\d+[\.\)]\s*|[-•]\s+)(.{10,200})', content or "")
    sections = walker["sections"] or re.findall(r'(?:^|\n)#{1,3}\s+(.{3,80})', content or "")
    if not sections:
        sections = re.findall(r'(?:^|\n)([A-Z][A-Z\s&]{5,60})(?:\n|$)', content or "")

    domains = set()
    for u in urls:
        try:
            from urllib.parse import urlparse
            domains.add(urlparse(u).netloc)
        except Exception:
            pass

    return {
        "status": "generating",
        "phase": "researching",
        "progress": (steps[-1] if steps else f"Tracking {len(urls)} sources from artifact"),
        "sources": max(len(domains), len(urls)),
        "source_urls": urls[:_SOURCE_LIST_CAP],
        "sections": sections[:15],
        "steps": steps[:15],
        "tool_uses": [f"Analyzing: {s[:80]}" for s in sections[:5]],
        "partial_text_len": len(content or ""),
        "click_box": _click_box,  # Track-B coord ground-truth (None unless WE clicked this call)
        "artifact_tracking": True,
        "artifact_count": artifact_count,
        # #914 forensics: which layer produced the data (dom|cua) + which
        # walker root matched (class|geo|'') — lets backend.log alone answer
        # "is the DOM path healthy or is the CUA carrying every read?"
        "layer": _layer,
        "walker_root": (walker.get("root") or "") if isinstance(walker, dict) else "",
    }


_p1_src_dbg_dumped = False  # one-shot guard for the #P1-src-dbg panel DOM capture
# 2026-08-19: last shape reported by the inline-walk diagnostic. A SIGNATURE, not
# a counter — a walk that keeps failing the same way says so once, and a walk that
# starts failing a NEW way says so immediately. Yesterday's 412-line DEBUG flood
# is what this is guarding against.
_p1_inline_dbg_sig = ""
# #P2-panel-dbg (DGOPS-9614): bounded to two dumps per process, and the previous
# sample's signature so "identical to last time" is decidable at all.
_p2_panel_dbg_dumps = 0
_p2_panel_last_fp = None
# The textlen of the last panel we dumped — see the growth trigger at the call
# site. 0 means "nothing dumped yet", so the first sizeable panel always lands.
_p2_panel_dbg_last_len = 0
# One dump is enough to document "the sample stopped changing"; the remaining
# budget is reserved for growth. Without this the early panel's repeated samples
# spend every slot before the rich state ever appears (measured, twice).
_p2_panel_dbg_frozen_done = False


def _p2_panel_dbg_record(res: dict) -> None:
    """Log the panel fingerprint every sample, and dump its DOM on a bounded budget.

    A module-level function rather than a block inlined in the walker, because the
    BUDGET POLICY is the thing that has now been wrong twice and a source-shape test
    cannot catch it. Replaying a real sequence of panel sizes can — see
    tests/test_p2_panel_rows_9614.py.

    The fingerprint sequence is the evidence that settled DGOPS-9614: it MOVED while
    the counts froze, which ruled out "we are re-reading a detached node" and left "our
    extraction misses the rows".
    """
    global _p2_panel_dbg_dumps, _p2_panel_last_fp, _p2_panel_dbg_last_len
    global _p2_panel_dbg_frozen_done
    try:
        _fp = res.get("dbg_fp") or {}
        _counts = (len(res.get("source_urls") or []), len(res.get("steps") or []),
                   len(res.get("sections") or []), int(res.get("searches", 0) or 0))
        _sig = (_counts, _fp.get("kids"), _fp.get("textlen"),
                _fp.get("anchors"), _fp.get("rows"))
        # `headings` is what makes `sections=0` readable: zero headings present
        # and zero surviving the length filter are different facts with opposite
        # fixes, and the bare count could not tell them apart — which is how a
        # correct zero was carried as a parse gap. `more` is the per-row collapsed
        # remainder, kept beside the counts rather than folded into them.
        log(f"[P2-panel-dbg] urls/steps/sections/searches={_counts} "
            f"headings={res.get('dbg_headings')} "
            f"more={res.get('dbg_more_remainder')} "
            f"node={_fp.get('tag', '?')} kids={_fp.get('kids')} "
            f"textlen={_fp.get('textlen')} anchors={_fp.get('anchors')} "
            f"rows={_fp.get('rows')}", "INFO")
        # ⭐ 2026-08-05 — the budget is spread over the RUN, not spent on the first
        # two identical samples. Both dumps from the 11:08 e2e landed on the EARLY
        # panel (13957 and 13956 chars, 10:53 and 10:54) because that state repeats
        # first; the rich 26410-char state repeated too, at 11:01, and by then the
        # cap of 2 was gone. So the one artifact the ticket needed was never
        # captured, and it took a second run to settle.
        #
        # ⛔ THE IDENTICAL-SAMPLE TRIGGER FIRES ONCE — and that one word is the fix.
        # Adversarial review replayed the real log against a first attempt at this
        # (raise the cap to 4, add a growth trigger) and it still failed: backend.log
        # 665308-665927 holds FIVE consecutive 1254-char samples (10:52:20, 10:53:21,
        # 10:54:22, 10:55:23, 10:56:25), so all four slots went to the early panel by
        # 10:56 and the 26410-char state from 11:00:51 onward got nothing again. A
        # bigger budget spent by the same rule is the same bug with more disk.
        #
        # So: ONE dump proves the "frozen sample" claim, and the remaining slots are
        # GROWTH-ONLY against a high-water mark. Lesson, stated properly this time —
        # bound a diagnostic dump by a budget spread across the run, and make each
        # trigger able to fire only as often as the thing it documents can change.
        _tl = int(_fp.get("textlen") or 0)
        _grew = _tl >= max(2000, int(_p2_panel_dbg_last_len * 1.8))
        _frozen = (_sig == _p2_panel_last_fp and _p2_panel_last_fp is not None
                   and not _p2_panel_dbg_frozen_done)
        if (_frozen or _grew) \
                and _p2_panel_dbg_dumps < 4 and res.get("dbg_html"):
            if _frozen:
                _p2_panel_dbg_frozen_done = True
            _d = os.path.expanduser("~/.super-research/logs")
            os.makedirs(_d, exist_ok=True)
            _p2_panel_dbg_dumps += 1
            _p2_panel_dbg_last_len = _tl
            _pth = os.path.join(_d, f"p2_panel_dump_{_p2_panel_dbg_dumps}.html")
            with open(_pth, "w", encoding="utf-8") as _f:
                _f.write(res.get("dbg_html") or "")
            # ⚠ Say when the capture was CUT. A truncated dump parses fine and
            # every count read off it is a floor that reads like an exact figure —
            # which is precisely how "38 distinct sources" got reported off a
            # document missing its tail.
            _wrote = len(res.get("dbg_html") or "")
            _full = int(res.get("dbg_html_full_len") or _wrote)
            _cut = (" ⚠ TRUNCATED — counts from this file are FLOORS"
                    if _full > _wrote else "")
            log(f"[P2-panel-dbg] dumped panel DOM "
                f"({_wrote} of {_full} chars, textlen={_tl}, "
                f"reason={'grew' if _grew else 'identical-sample'}) to {_pth}"
                f"{_cut}", "INFO")
        _p2_panel_last_fp = _sig
    except Exception as _pdbe:
        log(f"[P2-panel-dbg] capture skipped: {_pdbe}", "DEBUG")


async def scrape_chatgpt_activity_panel_tracking(page):
    """Walk ChatGPT Deep Research's *open* activity side panel for live
    progress data — steps checklist, section headings, source URLs,
    aggregate search count.

    Mirrors `scrape_claude_artifact_tracking` (Claude's gold-standard
    rich-narration path). The panel must already be open — caller is
    responsible for invoking `_open_chatgpt_activity_panel` first and
    keeping it open across polls (`chatgpt_activity_panel_open` flag).

    DOM-only: no CUA fallback. Reading from an already-mounted panel is a
    cheap structural walk; if DOM yields nothing the caller can fall
    through to vision narration (which already runs alongside this in the
    round-robin loop). Returns None when the panel isn't mounted /
    mounted-but-empty so the caller can skip merging.

    Returns dict with keys:
        steps, sections, source_urls, searches, partial_text_len, progress
    """
    JS = """() => {
        const out = {
            steps: [], sections: [], source_urls: [], source_items: [],
            searches: 0, partial_text_len: 0, progress: ""
        };
        // Panel root — ChatGPT renders the side panel as <aside> /
        // [role="complementary"] / [aria-label~=source] in the DR
        // sandbox iframe OR host page (post-2025 redesign). Match either.
        // Width gate prevents matching narrow chrome (sidebar nav, etc.).
        // #913 ground truth (user screenshot): P1's "Activity · Ns" panel
        // is ~21% of the viewport (≈267px at 1280) — width gate is 200,
        // not 280, and an Activity-headed container is accepted directly
        // even when no legacy selector matches it.
        const PANEL_SELS = [
            'aside', '[role="complementary"]', '[role="region"]',
            '[aria-label*="source" i]', '[aria-label*="activity" i]',
            '[aria-label*="research" i]',
            '[class*="panel" i][class*="side" i]'
        ].join(', ');
        const panels = Array.from(document.querySelectorAll(PANEL_SELS))
            .filter(el => {
                const r = el.getBoundingClientRect();
                return r.width >= 200 && r.height >= 200 &&
                       r.right > window.innerWidth * 0.45;
            });
        // Activity-headed panel (Signature A) — climb from the header leaf
        // to a panel-sized ancestor. Kept OUTSIDE the sorted candidate list:
        // the header anchor beats any height-ranked legacy match.
        let activityRoot = null;
        try {
            for (const el of document.querySelectorAll('*')) {
                const t = (el.innerText || '').trim();
                if (!t || !/^(?:activity|deep research)\\b/i.test(t) || t.length > 40) continue;
                const hr = el.getBoundingClientRect();
                if (hr.width === 0 || hr.height === 0) continue;
                if (hr.left < window.innerWidth * 0.5) continue;
                let node = el;
                for (let i = 0; i < 8 && node; i++) {
                    const r = node.getBoundingClientRect();
                    if (r.width >= 200 && r.width <= window.innerWidth * 0.6
                            && r.height >= 150
                            && r.right > window.innerWidth * 0.55) {
                        activityRoot = node;
                        break;
                    }
                    node = node.parentElement;
                }
                if (activityRoot) break;
            }
        } catch (e) {}
        if (panels.length === 0 && !activityRoot) return out;
        // Prefer the rightmost-and-tallest — ChatGPT mounts a single
        // dominant side panel; smaller candidates are usually unrelated
        // chrome that happens to match the selector.
        panels.sort((a, b) => {
            const ra = a.getBoundingClientRect();
            const rb = b.getBoundingClientRect();
            return (rb.height * (rb.right > window.innerWidth * 0.5 ? 1.5 : 1))
                 - (ra.height * (ra.right > window.innerWidth * 0.5 ? 1.5 : 1));
        });
        const panel = activityRoot || panels[0];
        const panelText = (panel.innerText || '').trim();
        out.partial_text_len = panelText.length;

        // Step rows — walk listitems and styled <div>s. Same shape as
        // Claude's walker. Skip rows with nested children (we want leaf
        // text only, not the parent that contains many siblings).
        // 2026-04-30: dropped [class*="row" i] — too loose; matched
        // sidebar nav / model-switcher rows and bled UI chrome into
        // out.steps[]. Min length raised 4→12 to drop "OK"/"Done"
        // single-word noise. Activity-verb gate mirrors Claude's panel
        // walker at research.py:7052 — without it the walker grabs any
        // 4-240-char text inside a panel-shaped div.
        const STEP_SELS = [
            'li', '[role="listitem"]',
            '[class*="step" i]', '[class*="checklist" i] > div',
            '[class*="task" i] > div', '[class*="activity" i]'
        ].join(', ');
        // #913: was a lone \\b in a NON-raw Python string — Python parsed it
        // into a literal backspace char, so this gate NEVER matched and the
        // side-panel walker returned zero step rows since it shipped.
        // 2026-07-08 (#922): the old fixed verb allowlist rejected real step
        // titles like "Creating a brief on Golden Retrievers…" (starts with
        // "Creating", which wasn't listed) — the user's screenshot showed the
        // activity panel had rich content we were dropping. ChatGPT's activity
        // titles are consistently GERUND-led ("Creating…", "Reading…",
        // "Searching…", "Building…", "Analyzing…"), so a leading-gerund gate is
        // both broader (admits the titles we were losing) AND still rejects
        // non-verb UI chrome ("Settings", "New chat", "Deep Research Flash
        // Sources Files") — and it subsumes the whole old list (all gerunds).
        const VERB_GATE = /^[a-z]+ing\\b/i;
        // The source-count chip reads "Searching 1 website" — a gerund, so it would
        // pass the gate, and its number changes every poll, so each value would
        // become a separate "step" and churn the list. It is already reported as
        // `searches`.
        const COUNT_CHIP = /^[a-z]+ing\\s+\\d+\\s+(?:websites?|sources?|searches?|sites?|results?)\\b/i;
        const seenStep = new Set();
        const takeStep = (t) => {
            if (!t || t.length < 12 || t.length > 240) return;
            if (!VERB_GATE.test(t)) return;
            if (COUNT_CHIP.test(t)) return;
            const k = t.slice(0, 80);
            if (seenStep.has(k)) return;
            seenStep.add(k);
            out.steps.push(t.slice(0, 220));
            // ⚠ A TRAILING bound, not a `break` at N. Stopping the scan at a step
            // count keeps the FIRST N and `slice(-15)` below then hands back rows
            // 45-59 forever — so on a long run the progress line would freeze on
            // step 59 while the panel kept going. Dropping from the front keeps
            // memory bounded AND keeps the latest, which is what progress means.
            if (out.steps.length > 80) out.steps.shift();
        };
        panel.querySelectorAll(STEP_SELS).forEach(e => {
            if (e.querySelector('li, [role="listitem"]')) return;
            takeStep((e.innerText || '').trim());
        });
        // ⭐⭐ 2026-08-05 (DGOPS-9614) — A STRUCTURAL PASS, because there is no hook
        // to select on. MEASURED against the live panel, not guessed: the captured
        // flyout (`~/.super-research/logs/p2_panel_dump_1.html`, 13957 chars,
        // `section[data-testid="screen-threadFlyOut"]`) contains ZERO `<li>`, ZERO
        // `role="listitem"`, ZERO `h1/h2/h3`, and not one class containing "step",
        // "activity", "task" or "checklist". Every selector in STEP_SELS matched
        // nothing, so the walker had reported 0 steps since it shipped — while the
        // panel's own innerText carried four of them:
        //
        //   Clarifying research scope / Designing the research brief /
        //   Clarifying research direction / Building the research brief
        //
        // That is the ticket: not a detached node, not a frozen panel — a selector
        // set that cannot match. (The fingerprint moving while the counts froze is
        // what ruled the detached-node theory out.)
        //
        // The live row is `<div class="text-token-text-primary text-[14px]">Clarifying
        // research scope</div>`, whose only durable property is SHAPE: its text is
        // its OWN (a direct text child) and it holds no element that carries text
        // too. The step BODY beneath it is the same shape and is excluded by the
        // gerund gate, which is the discriminator that already existed. So this adds
        // a candidate source, not a second policy — the gate, the length bounds and
        // the dedupe are the same ones above.
        //
        // ⚠ LEAVES ONLY — `childElementCount === 0`. That is both the precise test
        // ("its text is the whole of its text") and the cheap one: reading innerText
        // on every div to compare it against its own text would rebuild the panel's
        // string once per node, which on the observed 26410-char panel is quadratic
        // work inside a loop that polls every 30-60 seconds.
        try {
            // The scan is bounded by NODES examined, not by steps kept — 6000 is well
            // past the observed 26410-char panel (~4,613 elements) and stops a
            // pathological DOM from stalling a poll.
            //
            // ⚠ 2026-08-05 (review, f13e) — THE BOUND KEEPS THE NEWEST ROWS, and it
            // used to keep the oldest. `let _scanned = 0; if (++_scanned > 6000) break;`
            // truncated in DOCUMENT order, and this panel APPENDS — which is the
            // premise of the trailing bound in `takeStep`, of `slice(-15)` and of
            // `progress = steps[last]` alike. Proved by building a >6000-node panel
            // with the newest step last: `steps` came back as ['Clarifying research
            // scope'] and `progress` froze on the OLDEST title while the panel kept
            // going. That is DGOPS-9614's own symptom, one panel size larger.
            //
            // A window over the tail, not a reverse walk: walking backwards would hand
            // `takeStep` newest-first, and then `slice(-15)` would keep the fifteen
            // OLDEST and `progress` would be the oldest of all. Same node budget,
            // document order preserved, oldest dropped instead of newest.
            const _leaves = panel.querySelectorAll('div, p, span');
            for (let i = Math.max(0, _leaves.length - 6000); i < _leaves.length; i++) {
                const e = _leaves[i];
                if (e.childElementCount !== 0) continue;
                takeStep((e.textContent || '').replace(/\\s+/g, ' ').trim());
            }
        } catch (e) {}
        out.steps = out.steps.slice(-15);
        if (out.steps.length > 0) out.progress = out.steps[out.steps.length - 1];

        // Section headings — ChatGPT uses h1/h2/h3 inside the panel for
        // top-level outline (Deep Research's running report skeleton).
        //
        // ⚠ 2026-08-06 — `sections` came back 0 on all seventeen samples of the
        // 6 August run, across two different panel shapes, and DGOPS-9614 read
        // that as a parse gap. Replaying the captured panel through this very
        // code settles it: the panel contains NO heading element at any level
        // (h1-h6 all zero) — it is a list of activity rows, 37 <li>, not a report
        // outline. Zero is the correct answer for this shape.
        //
        // So the count alone is not reportable: 0 headings present and 0 surviving
        // the length filter are different facts with opposite fixes. `dbg_headings`
        // carries the raw count so the log distinguishes them and nobody re-raises
        // this as a parse bug.
        const _headings = panel.querySelectorAll('h1, h2, h3');
        out.dbg_headings = _headings.length;
        _headings.forEach(h => {
            const t = (h.innerText || '').trim();
            if (t && t.length > 1 && t.length < 120) out.sections.push(t);
        });
        // ⭐ 2026-08-06 — THE PANEL DOES HAVE GROUPS; THEY ARE JUST NOT HEADINGS.
        // The finding was "sections=0 on every sample", and the note above is
        // right that zero headings is the correct count for this markup. But the
        // panel is not ungrouped: the captured DOM carries exactly two group
        // labels, and they are what a reader would call its sections —
        //   <div class="text-token-text-secondary mb-3 text-[1.05rem] font-medium">
        //     …<span class="min-w-0 truncate">Pro thinking</span>
        //   <div class="… font-medium">…<span>Sources</span> · <span>168</span>
        // So the panel reported no structure at all while carrying two labels
        // that describe it. `font-medium` is worth trusting here because it is
        // rare in this subtree — the 154 source rows use font-semibold and
        // font-normal, never font-medium.
        //
        // Additive: the heading scan above is untouched, `dbg_headings` still
        // reports the raw heading count, and the bounds and dedupe below are the
        // same ones. A future build that renders real headings gains both.
        try {
            panel.querySelectorAll('[class*="font-medium"]').forEach(g => {
                const t = (g.innerText || '').replace(/\\s+/g, ' ').trim();
                if (!t || t.length < 2 || t.length > 60) return;
                if (/https?:\\/\\//.test(t)) return;   // a source row, not a label
                if (out.sections.indexOf(t) === -1) out.sections.push(t);
            });
        } catch (e) {}
        out.sections = out.sections.slice(0, 20);

        // URL list — every external <a>. Exclude the platform's OWN pages
        // (sign-in, settings, the share endpoint) since those aren't research
        // sources. Cap at 50 to bound payload size.
        //
        // ⭐⭐ 2026-08-06 — TEST THE HOST, NEVER THE WHOLE URL. This read
        // `h.includes('chatgpt.com') || h.includes('openai.com')`, and ChatGPT
        // appends `?utm_source=chatgpt.com` to EVERY outbound source link. So the
        // filter written to skip the platform's own pages was instead discarding
        // every genuine source that carried the platform's own tracking tag.
        // Measured against the captured panel of the 6 August run: 22 of 40
        // anchors dropped, 16 sources reported where 36 distinct ones existed —
        // 20 real sources lost, and that capture was truncated, so 36 is a floor.
        // This is exactly the shortfall against the platform's end-of-run summary
        // that DGOPS-9614 recorded and could not explain.
        const hostOf = (u) => {
            const m = /^https?:\\/\\/([^/?#]+)/i.exec(String(u || ''));
            return m ? m[1].toLowerCase().replace(/:\\d+$/, '') : '';
        };
        // Subdomain-aware and anchored at both ends, so `docs.nvidia.com` is kept
        // while `chatgpt.com` and `cdn.openai.com` are not. A bare `endsWith`
        // would also swallow a hypothetical `notchatgpt.com`.
        const INTERNAL_HOST = /(^|\\.)(chatgpt\\.com|openai\\.com)$/i;
        // Tracking parameters are not part of a source's identity: one page cited
        // twice, once tagged and once not, is ONE source. Stripping them here is
        // what keeps the recovered links from re-inflating the count (36 distinct,
        // not the 38 raw hrefs). Only the utm_* family is removed — everything
        // else in a query string can be load-bearing for the page.
        const cleanUrl = (u) => {
            const s = String(u || '');
            const q = s.indexOf('?');
            if (q < 0) return s;
            const hashAt = s.indexOf('#', q);
            const base = s.slice(0, q);
            const hash = hashAt >= 0 ? s.slice(hashAt) : '';
            const query = s.slice(q + 1, hashAt >= 0 ? hashAt : undefined);
            const keep = query.split('&').filter(p => p && !/^utm_/i.test(p));
            return base + (keep.length ? '?' + keep.join('&') : '') + hash;
        };
        const seenUrl = new Set();
        panel.querySelectorAll('a[href^="http"]').forEach(a => {
            const raw = a.href || '';
            if (!raw || raw.length > 500) return;
            if (INTERNAL_HOST.test(hostOf(raw))) return;
            const h = cleanUrl(raw);
            if (!h || seenUrl.has(h)) return;
            seenUrl.add(h);
            out.source_urls.push(h);
            // Capture the visible anchor text as the source TITLE (the real
            // article/page name shown in the panel) so the raw-activity popup
            // can show it instead of just a hostname. Bounded + falls back to
            // empty when the anchor is icon-only.
            let _title = (a.innerText || a.getAttribute('aria-label') || a.title || '').trim();
            if (_title.length > 200) _title = _title.slice(0, 200);
            out.source_items.push({ url: h, title: _title });
        });
        out.source_urls = out.source_urls.slice(0, 200);
        out.source_items = out.source_items.slice(0, 200);

        // Aggregate search count — ChatGPT renders strings like
        // "193 searches" / "33 sources" in the panel header or near the
        // step list. Pick the largest match so a transient lower count
        // doesn't shrink the chip mid-run. Same heuristic as Gemini's
        // panel walker.
        try {
            const re = /(\\d+)\\s+(?:websites?|sources?|searches?|sites?|results?)\\b/gi;
            let mm; let best = 0;
            while ((mm = re.exec(panelText)) !== null) {
                const n = parseInt(mm[1], 10) || 0;
                if (n > best) best = n;
            }
            // ⭐⭐ 2026-08-06 — THE REMAINDER IS PER-ROW, SO IT CANNOT BE ADDED TO A
            // PANEL-WIDE TOTAL. This used to compute `hidden + shown`, on the reading
            // that "N more" was the panel's own remainder. Two captures of the SAME
            // panel, eight minutes apart, disprove that: both read "15 more" while
            // the panel's anchor count went from 5 to 40. A panel-wide remainder
            // would have fallen as the list filled; a per-row affordance would not.
            //
            // The sum only ever looked plausible because the source read was broken
            // (a whole-URL substring test discarded every link carrying the
            // platform's `utm_source` tag). With that fixed, `shown` is 36 rather
            // than 16 for the same panel, and the old formula returns 51 — an
            // over-count of a number the user compares against the platform's own.
            //
            // So: the count is the LARGER of what the panel says in words and what we
            // actually read. Both are measurements. The remainder is kept as a
            // diagnostic instead of folded in, because attributing it to its own row
            // would mean guessing at the row container — and the case the sum was
            // added for ("seventeen sources read as one") is now carried by the URL
            // fix itself, which is a measurement rather than an inference.
            const more = /(\\d+)\\s+more\\b/i.exec(panelText);
            const hidden = more ? (parseInt(more[1], 10) || 0) : 0;
            out.dbg_more_remainder = hidden;
            // The remainder belongs to ITS ROW, so it is added to that row's own
            // link count — never to the panel's. Measured: the chip's container
            // holds exactly 3 links in both captures of the same panel, while the
            // panel total went 3 to 40. Hence three candidate totals, and the
            // largest honest one wins:
            //   * what the panel says in words ("Searched 193 websites"),
            //   * how many distinct links the whole panel actually holds,
            //   * the collapsed row's own visible links plus its remainder.
            // Early in a phase only the third is meaningful (3 shown + 15 hidden
            // = 18, where the panel holds only those 3). Later the second
            // overtakes it (36 held). Adding the remainder to the PANEL total
            // instead returns 51 — asserting 15 addresses that are not in the
            // document and cannot be listed, so a user opening the source list
            // would see 36 under a count of 51.
            let rowTotal = 0;
            if (hidden > 0) {
                try {
                    const chipNode = [...panel.querySelectorAll('div, span, button')]
                        .filter(e => e.childElementCount === 0
                                     && /^\\d+\\s+more\\b/i.test(
                                         (e.textContent || '').trim()))[0];
                    let n = chipNode;
                    for (let i = 0; i < 8 && n && n !== panel; i++) {
                        const rowLinks = n.querySelectorAll('a[href^="http"]').length;
                        if (rowLinks > 0) { rowTotal = rowLinks + hidden; break; }
                        n = n.parentElement;
                    }
                    // No sibling links found next to the chip — the remainder is
                    // still real, so count it alone rather than discarding it.
                    if (rowTotal === 0) rowTotal = hidden;
                } catch (e) { rowTotal = hidden; }
            }
            if (out.source_urls.length > best) best = out.source_urls.length;
            if (rowTotal > best) best = rowTotal;
            out.searches = best;
        } catch (e) {}

        // #P1-src-dbg (2026-07-23): the Pro+Extended-Thinking panel opens and
        // its step rows parse, but source_urls comes back EMPTY throughout the
        // run — this panel renders its sources some other way than the old
        // Deep Research external-<a href> list (verified from backend.log:
        // "panel tracking (P1): 0 URLs, 2 steps"). Capture how THIS panel
        // structures its sources so the extraction can be fixed from the real
        // DOM, never guessed. Bounded; only computed when we truly have a panel
        // (real text) but zero source urls — costs nothing on the happy path.
        // #P2-panel-dbg (DGOPS-9614, 2026-08-05): a per-sample FINGERPRINT of the
        // panel node, always computed because it is cheap and it is the thing that
        // settles the open question. The second-phase tracker reports the same
        // counts sample after sample while the platform's own end-of-run summary
        // says it did far more. Two possible causes, opposite fixes: the panel is
        // changing and our extraction misses the new rows, or we are re-reading a
        // detached node that stopped updating. If this fingerprint MOVES while the
        // counts do not, it is the first; if it is identical, it is the second.
        try {
            out.dbg_fp = {
                tag: (panel.tagName || '') + '|' + String(panel.className || '').slice(0, 70),
                kids: panel.childElementCount,
                textlen: (panel.innerText || '').length,
                anchors: panel.querySelectorAll('a[href]').length,
                rows: panel.querySelectorAll('li, [role="listitem"]').length,
            };
        } catch (e) {}

        try {
            // ⚠ Gate widened from "zero sources" to "we have a real panel". The old
            // gate could not fire for DGOPS-9614, whose whole symptom is a NON-zero
            // count that never moves — so the one run that could answer it produced
            // nothing. The caller decides what to keep; this only makes it available.
            if (out.partial_text_len > 150) {
                out.dbg_panel_tag = (panel.tagName || '') + '|' +
                    String(panel.className || '').slice(0, 160);
                out.dbg_anchors = [];
                panel.querySelectorAll('a, [role="link"], button, cite, [data-url], [data-href]').forEach(a => {
                    if (out.dbg_anchors.length >= 80) return;
                    const href = a.getAttribute('href') || a.getAttribute('data-href') ||
                                 a.getAttribute('data-url') || '';
                    const txt = (a.innerText || a.getAttribute('aria-label') || a.title || '').trim().slice(0, 90);
                    if (!href && !txt) return;
                    out.dbg_anchors.push(a.tagName + ' [' + String(a.className || '').slice(0, 60) +
                                         '] href=' + String(href).slice(0, 220) + ' :: ' + txt);
                });
                // ⚠ 2026-08-06 — the cap USED to be 60000 with no record of whether
                // it bit, and the one grown sample of the 6 August run hit it
                // exactly: the file ended mid-tag with unbalanced containers, so
                // every count read off it was a floor that read like an exact
                // figure. Silent truncation of a diagnostic is worse than a
                // smaller diagnostic. The full length is always reported, so a
                // capture that was cut can never be mistaken for a whole one.
                const _outer = String(panel.outerHTML || '');
                out.dbg_html_full_len = _outer.length;
                out.dbg_html = _outer.slice(0, 400000);
            }
        } catch (e) {}

        return out;
    }"""
    try:
        res = await page.evaluate(JS)
    except Exception as _e:
        log(f"[ChatGPT] activity panel walker failed: {_e}", "DEBUG")
        res = None
    if res:
        res["panel_shape"] = "side"
    # #913: the DR sandbox iframe URL no longer matches any fixed substring
    # (live 2026-07-06: the strip + panel were visible to CUA while every
    # URL-filtered frame walk returned nothing) — enumerate ALL frames.
    if not res or (not res.get("steps") and not res.get("source_urls")):
        try:
            for frame in [f for f in page.frames if f != page.main_frame][:20]:
                try:
                    f_res = await frame.evaluate(JS)
                except Exception:
                    continue
                if f_res and (f_res.get("steps") or f_res.get("source_urls")):
                    res = f_res
                    res["panel_shape"] = "side"
                    break
        except Exception:
            pass
    # #913: inline-turn fallback — when no side panel yielded data (panel
    # closed, or open but still skeleton-only), scrape the last assistant
    # turn itself: status line, verb rows, hostname chips, counts. Keeps
    # the FE raw-activity dropdown + cycling readings rich in P1 too.
    if not res or (not res.get("steps") and not res.get("source_urls")
                   and not int(res.get("searches", 0) or 0)):
        try:
            il = await page.evaluate(_CHATGPT_INLINE_ACTIVITY_JS)
        except Exception as _ie:
            log(f"[ChatGPT] inline activity walker failed: {_ie}", "DEBUG")
            il = None
        # 2026-08-19: `chips` joins the has-anything test. A P1 drawer that is
        # open on its very first sample carries a chip row and NOTHING ELSE — no
        # verb row has streamed yet — and the old test would have thrown that
        # sample away, which is the one sample that proves the drawer is open.
        if il and (il.get("steps") or il.get("source_urls")
                   or il.get("progress") or int(il.get("searches", 0) or 0)
                   or int(il.get("chips", 0) or 0)):
            res = {
                "steps": il.get("steps") or [],
                "sections": il.get("sections") or [],
                "source_urls": il.get("source_urls") or [],
                "source_items": [],
                "searches": int(il.get("searches", 0) or 0),
                "partial_text_len": int(il.get("partial_text_len", 0) or 0),
                "progress": il.get("progress") or "",
                "panel_shape": "inline",
                "chips": int(il.get("chips", 0) or 0),
                "chip_row": bool(il.get("chip_row")),
                "inline_dbg": il.get("dbg") or {},
            }
            # Titles for the anchors the inline walker DID find, so a real page
            # url is never demoted to a bare domain by arriving without one.
            for _u in res["source_urls"]:
                res["source_items"].append({"url": _u, "title": ""})
            _merge_host_chips(res, il.get("source_hosts") or [])
        elif il:
            # ⭐ The walk produced nothing — say what it looked at. Sparse ON
            # PURPOSE: the same instinct un-sparsely applied is what put 412
            # identical DEBUG lines into yesterday's bundle, so this fires only
            # when the shape of the answer CHANGES, not once per poll.
            global _p1_inline_dbg_sig
            _d = il.get("dbg") or {}
            _sig = (f"{_d.get('scope', '?')}|{_d.get('turnTag', '?')}|"
                    f"{_d.get('cands', 0)}|{_d.get('chipsProse', 0)}")
            if _sig != _p1_inline_dbg_sig:
                _p1_inline_dbg_sig = _sig
                log(f"[ChatGPT] inline walk found nothing — scope="
                    f"{_d.get('scope', '?')} turn={_d.get('turnTag', '?')} "
                    f"lub={_d.get('lub', -1)} cands={_d.get('cands', 0)} "
                    f"chips_in_prose={_d.get('chipsProse', 0)}", "DEBUG")
    if not res:
        return None
    has_data = (
        bool(res.get("steps"))
        or bool(res.get("source_urls"))
        or bool(res.get("sections"))
        or int(res.get("searches", 0) or 0) > 0
        or bool((res.get("progress") or "").strip())
    )
    if not has_data:
        return None
    # #P1-src-dbg: one-shot ground-truth capture. When the panel opened and
    # parsed step rows but produced ZERO source urls (the reported P1 raw-
    # activity-empty symptom), dump the panel's real DOM + an anchor/button/
    # cite inventory so the source extraction can be corrected from what the
    # Pro+Extended-Thinking panel actually renders — not a blind selector
    # guess. Fires at most once per process; writes next to backend.log so it
    # survives whichever way the run was launched.
    global _p1_src_dbg_dumped
    if (not _p1_src_dbg_dumped and res.get("dbg_html")
            and not res.get("source_urls") and res.get("steps")):
        try:
            _dbg_dir = os.path.expanduser("~/.super-research/logs")
            os.makedirs(_dbg_dir, exist_ok=True)
            _dbg_path = os.path.join(_dbg_dir, "p1_activity_panel_dump.html")
            with open(_dbg_path, "w", encoding="utf-8") as _f:
                _f.write(res.get("dbg_html") or "")
            log(f"[P1-src-dbg] panel open + {len(res.get('steps', []))} steps but 0 source "
                f"urls — dumped panel DOM ({len(res.get('dbg_html') or '')} chars) to {_dbg_path} "
                f"(panel={res.get('dbg_panel_tag', '?')}); "
                f"{len(res.get('dbg_anchors') or [])} anchor/button/cite candidates:", "INFO")
            for _a in (res.get("dbg_anchors") or [])[:80]:
                log(f"[P1-src-dbg]   {_a}", "INFO")
            _p1_src_dbg_dumped = True
        except Exception as _dbe:
            log(f"[P1-src-dbg] capture failed: {_dbe}", "DEBUG")
    # #P2-panel-dbg (DGOPS-9614) — see `_p2_panel_dbg_record`.
    _p2_panel_dbg_record(res)
    # Strip debug-only keys so they never bleed into the merged progress/emit.
    # Diagnostic-only keys, dropped after `_p2_panel_dbg_record` has consumed
    # them so nothing downstream carries a 400 KB string or an unused counter.
    # Keep this list exhaustive: a new `dbg_*` that is not listed here rides all
    # the way into the merged progress payload.
    for _dk in ("dbg_html", "dbg_html_full_len", "dbg_anchors", "dbg_panel_tag",
                "dbg_fp", "dbg_headings", "dbg_more_remainder"):
        res.pop(_dk, None)
    return res


# ── Browser ────────────────────────────────────────────────────────────────────

class Browser:
    """Playwright persistent Chrome context — proven from original research.py."""

    # Hosts where popups are allowed to live. Anything else opened during a
    # run (linkedin/x/reddit/facebook from Gemini's share dialog social
    # icons, ads, third-party redirects we don't drive) gets auto-closed
    # by _guard_popup. Subdomain match: host == ALLOWED or host endswith
    # "." + ALLOWED. `google.com` covers the OAuth/sign-in chain.
    _POPUP_ALLOWED_HOSTS = frozenset({
        "chatgpt.com", "openai.com", "auth.openai.com",
        "claude.ai", "claude.site", "anthropic.com",
        "gemini.google.com", "g.co",
        "docs.google.com", "drive.google.com",
        "accounts.google.com", "myaccount.google.com",
        "mail.google.com",
        "notebooklm.google.com", "notebook.google.com",
        "studio.youtube.com", "youtube.com",
        "google.com",
    })

    def __init__(self, profile_dir, headless=False):
        self.profile_dir = str(profile_dir)
        self.headless = headless
        self.playwright = None
        self.context = None
        self.page = None
        self._upload_queue = []
        # Tabs opened by us via new_tab() get registered here. Anything
        # NOT here AND not on _POPUP_ALLOWED_HOSTS is auto-closed.
        self._known_pages: set = set()

    async def start(self):
        # Kill only orphaned Playwright Chrome from OUR profile directory.
        # NEVER kill all chrome.exe — that nukes the user's personal browser.
        # Q8 (2026-04-30): match by profile path AND only kill chromes whose
        # create_time predates this --serve process. A chrome younger than us
        # was spawned by this same --serve (sibling pipeline restart, parallel
        # phase relaunch, etc.) and killing it surfaces as "Page.bring_to_front:
        # Target page, context or browser has been closed" on the sibling run.
        # Pre-fix the killer was indiscriminate — every Browser.start() in the
        # process lifetime would chew live sibling chromes.
        try:
            import psutil
            our_profile = str(Path(self.profile_dir).resolve()).lower().replace("\\", "/")
            try:
                serve_start_ts = psutil.Process(os.getpid()).create_time()
            except Exception:
                serve_start_ts = 0.0
            _orphans = []
            for proc in psutil.process_iter(["pid", "name", "cmdline"]):
                try:
                    if proc.info["name"] and "chrome" in proc.info["name"].lower():
                        cmdline = " ".join(proc.info["cmdline"] or []).lower().replace("\\", "/")
                        if _profile_matches_cmdline(our_profile, cmdline):
                            try:
                                chrome_start_ts = proc.create_time()
                            except (psutil.NoSuchProcess, psutil.AccessDenied):
                                chrome_start_ts = 0.0
                            if serve_start_ts > 0 and chrome_start_ts >= serve_start_ts:
                                _sweep_log(f"Sparing sibling Chrome PID {proc.info['pid']} (younger than --serve, our profile)")
                                continue
                            # #898b: close GRACEFULLY first — a hard kill can
                            # drop a seconds-old sign-in (e.g. the user just
                            # ran --login) before Chrome flushes it to disk.
                            # Windows needs taskkill /T WITHOUT /F for a real
                            # WM_CLOSE (psutil terminate() is hard there).
                            _sweep_log(f"Closing orphaned Chrome PID {proc.info['pid']} (our profile) — graceful, hard-kill fallback")
                            try:
                                if sys.platform == "win32":
                                    subprocess.run(
                                        ["taskkill", "/PID", str(proc.info["pid"]), "/T"],
                                        capture_output=True, timeout=10,
                                        creationflags=_PS_NO_WINDOW)
                                else:
                                    proc.terminate()
                            except Exception:
                                pass
                            _orphans.append(proc)
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
            if _orphans:
                # Bounded flush grace, then hard-kill whatever survived so the
                # profile lock is still guaranteed free for our launch.
                _gone, _alive = await asyncio.to_thread(psutil.wait_procs, _orphans, 5)
                for _p in _alive:
                    try:
                        _sweep_log(f"Killing orphaned Chrome PID {_p.pid} (didn't exit within the graceful window)")
                        _p.kill()
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        pass
            await asyncio.sleep(1)
        except ImportError:
            pass
        except Exception:
            pass

        # Remove stale Chrome lock files from unclean shutdown — these prevent
        # Playwright from reusing the persistent profile directory.
        profile_path = Path(self.profile_dir)
        for lock_name in ("SingletonLock", "SingletonSocket", "SingletonCookie"):
            lock_file = profile_path / lock_name
            if lock_file.exists():
                try:
                    lock_file.unlink()
                    log(f"Removed stale Chrome lock: {lock_name}")
                except Exception:
                    pass

        # Clean version-specific cache dirs that cause downgrade errors when
        # switching between system Chrome and Playwright's bundled Chromium.
        # These are regeneratable caches — login sessions live in Default/.
        import shutil
        for cache_dir in ("ShaderCache", "GrShaderCache", "GraphiteDawnCache",
                          "component_crx_cache", "extensions_crx_cache",
                          "BrowserMetrics", "Crashpad"):
            p = profile_path / cache_dir
            if p.is_dir():
                try:
                    shutil.rmtree(p, ignore_errors=True)
                except Exception:
                    pass
        # Also remove the downgrade sentinel that triggers cleanup attempts
        for sentinel in profile_path.glob("*.CHROME_DELETE"):
            try:
                shutil.rmtree(sentinel, ignore_errors=True)
            except Exception:
                pass

        # STEALTH-2026-04-19: Escalated from playwright + UA/UACH spoof to
        # patchright + real Chrome binary. Prior stack (playwright's bundled
        # Chromium, manual UA/UACH overrides, --disable-blink-features, init
        # scripts) still got blocked by ChatGPT and Claude login — bot-score
        # too high even with all the shims. patchright is a drop-in async
        # replacement that patches the deeper CDP / runtime.enable / chrome
        # object / headless-mode detection vectors internally, and pairs
        # with channel="chrome" to run the user's installed Chrome binary
        # instead of the bundled Chromium.
        #
        # channel="chrome" was previously avoided because we feared the
        # Windows singleton broker would delegate to the user's personal
        # Chrome and exit. That only happens when sharing a user-data-dir;
        # we now use a DEDICATED profile at ~/.super-research/browser-profile
        # so Chrome launches a separate process independent of the user's
        # daily browsing instance.
        #
        # Per patchright docs, we MUST NOT set user_agent, extra_http_headers,
        # or automation-disabling args — patchright handles those internally,
        # and adding them back produces inconsistencies that detection
        # scripts flag. Keep the init_script below as a belt-and-suspenders
        # layer; it's additive and patchright tolerates it.
        from patchright.async_api import async_playwright
        self.playwright = await async_playwright().start()
        # macOS COOKIE-DECRYPTION FIX (2026-07-09). patchright/Playwright inject
        # `--use-mock-keychain` into the channel="chrome" launch by default. On
        # macOS, Chrome's cookie-encryption key ("Chrome Safe Storage") lives in
        # the login Keychain; --use-mock-keychain swaps in a MOCK key, so THIS
        # automated Chrome cannot decrypt the cookies the plain-Chrome sign-in
        # (_seed_login_plain_chrome, launched via `open` → real Keychain) wrote —
        # Chrome silently DROPS the undecryptable rows and rewrites the jar empty.
        # Net effect on macOS: verify + every research run reopen the SAME profile
        # dir the user signed into, but read it as SIGNED-OUT, and the saved
        # session is wiped on the first reopen. That is the reported "the profile
        # the Mac opens for runs/verify is a different (empty) profile" bug — and
        # it is macOS-specific because Windows cookies use DPAPI, which
        # --use-mock-keychain does not touch (so Windows decrypts fine). Dropping
        # the mock-keychain arg makes automated Chrome use the SAME real Keychain
        # key as the seed → cookies decrypt → logins persist across
        # seed → verify → run. Real (non-automated) Chrome never sets this flag, so
        # this also makes the automated browser look MORE like real Chrome (a net
        # positive for the patchright stealth layer, not a regression).
        # Proven on-device (Chrome 150, launchd + Terminal): with the flag the
        # reopen reads 0 cookies and wipes the jar; without it, the seeded cookies
        # decrypt and persist. Scoped to Darwin so Windows/Linux launch is byte-for-
        # byte unchanged.
        _launch_kwargs = dict(
            user_data_dir=self.profile_dir,
            channel="chrome",
            headless=self.headless,
            viewport={"width": API_WIDTH, "height": API_HEIGHT},
            no_viewport=False,
        )
        if sys.platform == "darwin":
            _launch_kwargs["ignore_default_args"] = ["--use-mock-keychain"]
        # 2026-07-13 (user screenshot): patchright injects --no-sandbox unless
        # chromiumSandbox=true, and Chrome then paints a permanent "unsupported
        # command-line flag: --no-sandbox. Stability and security will suffer"
        # infobar — a bot-detection tell (real Chrome never shows it), a ~40px
        # band that shifts page geometry under every vision screenshot, and a
        # genuine security downgrade. Real Chrome runs sandboxed on macOS +
        # Windows with zero setup, so turn the sandbox ON there. Linux is left
        # as patchright ships it (--no-sandbox) — sandboxing needs unprivileged
        # user-namespaces and hard-fails under root/containers.
        if sys.platform in ("darwin", "win32"):
            _launch_kwargs["chromium_sandbox"] = True
        # Instrumentation (mac login-profile bug): make backend.log ALONE able to
        # root-cause a profile / keychain mismatch — the fully-resolved abspath,
        # HOME (Path.home() differs if a supervisor launched us with another HOME),
        # WORKER_ID (which _profile_dir slot), the channel, and whether the macOS
        # real-Keychain fix is active for this launch.
        try:
            _abs_profile = str(Path(self.profile_dir).resolve())
        except Exception:
            _abs_profile = str(self.profile_dir)
        log(f"[browser] launch profile_dir={_abs_profile} home={Path.home()} "
            f"worker={WORKER_ID} channel=chrome headless={self.headless} "
            f"real_keychain={sys.platform == 'darwin'}")
        self.context = await self.playwright.chromium.launch_persistent_context(
            **_launch_kwargs
        )
        # patchright owns the stealth layer from here. The prior hand-rolled
        # add_init_script (webdriver/plugins/languages/vendor/platform/
        # hardwareConcurrency/deviceMemory/chrome.runtime/permissions/WebGL)
        # ran AFTER patchright's own patches and overwrote them with values
        # that don't match what real Chrome actually exposes, producing
        # fingerprints worse than either layer alone. Keep the file-chooser
        # wiring; that's unrelated to stealth.
        if self.context.pages:
            self.page = self.context.pages[0]
        else:
            self.page = await self.context.new_page()
        self._known_pages.add(self.page)
        self.context.on("page", self._attach_file_handler)
        self.context.on("page", self._guard_popup)
        self._attach_file_handler(self.page)

        # Clipboard read/write — granted ONCE here at browser bootstrap.
        # Browser.grantPermissions (CDP, no origin) applies to the persistent
        # context and persists for the session, so this single grant covers
        # every agent tab in every phase (new_tab + open_isolated_tab both
        # reuse this same context). Without it, navigator.clipboard.writeText/
        # readText are denied in the automated context, which SILENTLY breaks
        # both P1/P2 brief-paste (Strategy A: clipboard + Ctrl+V) AND P2
        # response extraction (Gemini "Copy contents" → clipboard, ChatGPT/
        # Claude copy). verified_paste_brief still grants per-paste as a
        # defensive fallback in case this bootstrap grant ever fails.
        if await _grant_clipboard_permission(self.page):
            log("[browser] clipboard read/write permission granted browser-wide")
        else:
            log("[browser] clipboard permission grant failed — paste/extraction may degrade", "WARN")

        # F4 / DGOPS-7451 — security deny-list at the Playwright route layer.
        # Blocks ANY navigation, sub-frame request, fetch, or XHR to internal
        # infrastructure hostnames (web.app / firebaseapp.com /
        # distributedglobal.com / dg-eng.com). Catches the "agent wanders into
        # internal infra and rides a persisted Workspace session" class of
        # leak at the network layer — which is exactly what happened on
        # 2026-05-05 when Gemini Deep Research scraped dg-security-monitor.
        async def _security_deny_route(route, request):
            try:
                from urllib.parse import urlparse
                host = (urlparse(request.url).hostname or "").lower()
                pattern = _matches_security_deny_host(host)
                if pattern:
                    # Capture referrer for audit-log payload (PR review J1).
                    # Answers "which page tried to navigate to the blocked
                    # host?" — critical early-warning when the deny-list
                    # has a gap (next internal app deployed to *.appspot.com
                    # / *.run.app / custom DG domain). Best-effort: header
                    # read can fail on some request types — fall through to
                    # empty referrer rather than block the audit emit.
                    referrer = ""
                    try:
                        hdrs = await request.all_headers()
                        referrer = (hdrs.get("referer", "") or
                                    hdrs.get("referrer", "") or "")
                    except Exception:
                        pass
                    log(f"[security] BLOCKED agent navigation to {host} "
                        f"(matches deny-list pattern={pattern}, "
                        f"url={request.url[:200]}, "
                        f"referrer={referrer[:120]})", "WARN")
                    try:
                        emit_event("security_blocked_navigation",
                                   host=host, pattern=pattern,
                                   url=request.url[:300],
                                   resourceType=request.resource_type,
                                   referrer=referrer[:300])
                    except Exception:
                        pass
                    await route.abort("blockedbyclient")
                    return
            except Exception as _e:
                # Never let route handler exceptions leak — it would block
                # all navigation. Fall through to continue_ on any error.
                log(f"[security] route handler error (continuing): {_e}", "DEBUG")
            try:
                await route.continue_()
            except Exception:
                pass

        # PR review J2 principle preserved via emergency env-gate. Default
        # active. When DG_SECURITY_DENY_LIST_ENABLED=0, the deny-list is
        # bypassed entirely (no install, no per-request overhead). The
        # route deny-list is now the only load-bearing F4 defense (after
        # storage scrub was removed in DGOPS-7451), so this gate matters
        # for operators who need to disable it during incident response.
        if DG_SECURITY_DENY_LIST_ENABLED:
            try:
                await self.context.route("**/*", _security_deny_route)
            except Exception as _re:
                log(f"[security] failed to install route deny-list: {_re}", "WARN")
            # State the EFFECTIVE list, not just that a list exists (DGOPS-9505).
            # An operator setting DG_SECURITY_DENY_HOSTS previously had no way to
            # see what they had actually ended up with, which is what let a
            # silent replace go unnoticed; now the defaults-plus-additions
            # result is in the log next to the run it protected.
            try:
                _extra = [h for h in _SECURITY_DENY_HOSTS
                          if h not in _SECURITY_DENY_HOSTS_DEFAULT]
                log(f"[security] route deny-list active — {len(_SECURITY_DENY_HOSTS)} "
                    f"host(s): {', '.join(_SECURITY_DENY_HOSTS)}"
                    + (f"  (+{len(_extra)} from DG_SECURITY_DENY_HOSTS)" if _extra else ""))
            except Exception:
                pass
        else:
            log("[security] route deny-list DISABLED via "
                "DG_SECURITY_DENY_LIST_ENABLED=0 — M4 F4 defense is OFF",
                "WARN")

        log("Browser started (stealth: patchright + channel=chrome)")

    def _attach_file_handler(self, page):
        page.on("filechooser", self._on_file_chooser)

    async def _guard_popup(self, page):
        """Auto-close popup tabs that aren't on the agent host allow-list.

        Fires for BOTH our own new_tab() calls AND spontaneous popups
        (social-share window.open, target=_blank). Polls page.url for up to
        ~4s waiting for the URL to settle past about:blank — then matches
        the host against the allow-list. Tabs explicitly registered in
        _known_pages by new_tab() are never closed (belt-and-suspenders for
        race cases).

        Allow-list covers every host we drive a flow through (chatgpt/
        claude/gemini/notebooklm/youtube/gmail/gdocs/google-auth). Anything
        else (linkedin/facebook/x/reddit etc. from Gemini's share dialog
        social icons, ads, OAuth redirects we don't drive) gets closed.
        """
        try:
            if page in self._known_pages:
                return
            url = ""
            for _ in range(8):  # ~4s window for URL to settle
                try:
                    url = page.url or ""
                except Exception:
                    return
                if url and url != "about:blank":
                    break
                await asyncio.sleep(0.5)
            if not url or url == "about:blank":
                # Stayed at about:blank — likely a still-loading agent tab.
                # Don't close; the caller's flow will manage it.
                return
            try:
                from urllib.parse import urlparse
                host = (urlparse(url).hostname or "").lower()
            except Exception:
                return
            host_norm = host[4:] if host.startswith("www.") else host
            if host_norm and any(host_norm == a or host_norm.endswith("." + a)
                                  for a in self._POPUP_ALLOWED_HOSTS):
                # Treat as legitimate — register so a subsequent event won't
                # re-evaluate it, and exit.
                self._known_pages.add(page)
                return
            log(f"[popup-guard] Closing off-allowlist popup: {host} ({url[:80]})", "INFO")
            try:
                await page.close()
            except Exception as e:
                log(f"[popup-guard] close failed: {e}", "WARN")
        except Exception as e:
            log(f"[popup-guard] error: {e}", "WARN")

    async def _on_file_chooser(self, file_chooser):
        if not self._upload_queue:
            log("File dialog opened but upload queue is empty", "WARN")
            return
        # 2026-04-30: type-aware routing. Pre-fix the queue was strict FIFO,
        # so YouTube uploads broke whenever the thumbnail file dialog opened
        # before the video dialog (or CUA misclicked into thumbnail first):
        # the PNG fed into the video picker → "Invalid file format" banner.
        # Now we read the input element's `accept` attribute and pop the
        # queued file whose extension matches. Falls back to FIFO when the
        # accept attribute is unset / ambiguous.
        accept = ""
        try:
            handle = await file_chooser.element_handle()
            if handle is not None:
                accept = (await handle.get_attribute("accept")) or ""
        except Exception:
            accept = ""
        accept_lower = accept.lower()
        VIDEO_EXTS = {".mp4", ".mov", ".webm", ".mkv", ".avi", ".m4v"}
        IMAGE_EXTS = {".png", ".jpg", ".jpeg", ".gif", ".webp"}
        wants_image = ("image" in accept_lower) or any(ext in accept_lower for ext in IMAGE_EXTS)
        wants_video = ("video" in accept_lower) or any(ext in accept_lower for ext in VIDEO_EXTS)
        chosen_idx = 0  # default FIFO
        if wants_image and not wants_video:
            for i, p in enumerate(self._upload_queue):
                if Path(p).suffix.lower() in IMAGE_EXTS:
                    chosen_idx = i
                    break
        elif wants_video and not wants_image:
            for i, p in enumerate(self._upload_queue):
                if Path(p).suffix.lower() in VIDEO_EXTS:
                    chosen_idx = i
                    break
        path = self._upload_queue.pop(chosen_idx)
        if Path(path).exists():
            log(f"File dialog intercepted — uploading: {Path(path).name} (accept={accept[:60] or 'unset'})")
            # Wrap in try/except — pyee's AsyncIOEventEmitter turns any
            # unhandled exception in this `page.on("filechooser", ...)`
            # callback into a process-killing `raise error` (pyee/base.py
            # _emit_handle_potential_error). Pre-fix, a TargetClosedError
            # raised here when the page closed mid-upload (popup-guard
            # racing the dialog, EPIPE from the Patchright Node driver
            # during HV recovery, etc.) escalated the whole BE process
            # to exit code 0xFFFFFFFF and the daemon-loop respawned —
            # losing the in-flight pipeline and leaving the queue-gate
            # wedged on a stale prior-run pointer. The page is gone; we
            # have nothing useful to do with the file. Drop a WARN and
            # let the caller's own retry / timeout path handle it.
            try:
                await file_chooser.set_files(path)
            except Exception as _set_err:
                log(
                    f"File dialog set_files failed ({type(_set_err).__name__}): {_set_err} "
                    f"— page may have closed mid-upload; swallowing to keep BE alive",
                    "WARN",
                )
        else:
            log(f"File dialog — queued file not found: {path}", "WARN")

    def set_upload_file(self, path):
        """Set the file for the next file dialog (replaces any queued files)."""
        self._upload_queue = [str(path)]

    def queue_upload_file(self, path):
        """Add a file to the upload queue (for sequential file dialogs like video + thumbnail)."""
        self._upload_queue.append(str(path))

    def clear_upload_file(self):
        self._upload_queue = []

    async def screenshot(self) -> str:
        try:
            buf = await self.page.screenshot(type="png", timeout=10000)
            return base64.b64encode(buf).decode("ascii")
        except Exception as e:
            log(f"Screenshot failed: {e}", "WARN")
            await asyncio.sleep(2)
            try:
                buf = await self.page.screenshot(type="png", timeout=15000)
                return base64.b64encode(buf).decode("ascii")
            except Exception:
                return ""

    async def left_click(self, x, y):
        await self.page.mouse.click(x, y)

    async def right_click(self, x, y):
        await self.page.mouse.click(x, y, button="right")

    async def double_click(self, x, y):
        await self.page.mouse.dblclick(x, y)

    async def triple_click(self, x, y):
        await self.page.mouse.click(x, y, click_count=3)

    async def middle_click(self, x, y):
        await self.page.mouse.click(x, y, button="middle")

    async def type_text(self, text):
        await self.page.keyboard.type(text, delay=20)

    async def key(self, combo):
        mapping = {
            "ctrl": "Control", "alt": "Alt", "shift": "Shift",
            "meta": "Meta", "super": "Meta", "cmd": "Meta",
            "return": "Enter", "enter": "Enter",
            "backspace": "Backspace", "delete": "Delete",
            "tab": "Tab", "escape": "Escape", "esc": "Escape",
            "space": " ", "up": "ArrowUp", "down": "ArrowDown",
            "left": "ArrowLeft", "right": "ArrowRight",
            "pageup": "PageUp", "pagedown": "PageDown",
            "home": "Home", "end": "End",
        }
        parts = combo.split("+")
        translated = [mapping.get(p.strip().lower(), p.strip()) for p in parts]
        await self.page.keyboard.press("+".join(translated))

    async def mouse_move(self, x, y):
        await self.page.mouse.move(x, y)

    async def scroll(self, x, y, direction, amount=3):
        await self.page.mouse.move(x, y)
        delta_map = {"up": (0, -100*amount), "down": (0, 100*amount),
                     "left": (-100*amount, 0), "right": (100*amount, 0)}
        dx, dy = delta_map.get(direction, (0, 100*amount))
        await self.page.mouse.wheel(dx, dy)

    async def left_click_drag(self, sx, sy, ex, ey):
        await self.page.mouse.move(sx, sy)
        await self.page.mouse.down()
        await self.page.mouse.move(ex, ey)
        await self.page.mouse.up()

    async def navigate(self, url):
        log(f"Navigating: {url}")
        # Self-heal if self.page was closed out from under us. Common
        # trigger: a throwaway tab opened via new_tab() (which reassigns
        # self.page) and then close()'d by the caller — e.g. the verify-
        # at-phase-time flow at :7718 / :7851. Pre-fix, run_phase1's
        # first navigate hit TargetClosedError on the stale self.page
        # because nothing restored it post-verify. context.new_page()
        # gives us a live page on the same persistent profile (logins
        # survive) so the goto below lands somewhere alive.
        if self.page is None or self.page.is_closed():
            log("navigate: self.page closed — opening fresh page", "WARN")
            self.page = await self.context.new_page()
            self._known_pages.add(self.page)
            try:
                self.page.on("close", lambda p: self._known_pages.discard(p))
            except Exception:
                pass
            self._attach_file_handler(self.page)
        try:
            await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
        except Exception as e:
            # One retry on page-death-class failures (TargetClosedError
            # surfaces as "Target page, context or browser has been closed").
            # Bounded to one retry so context-level death (driver EPIPE,
            # network) still surfaces to the caller's snag handler instead
            # of looping forever.
            msg = str(e).lower()
            if ("target page" in msg or "browser has been closed" in msg
                    or "page, context" in msg):
                log(f"navigate: page died mid-goto ({type(e).__name__}) — recreating + retry once", "WARN")
                try: await self.page.close()
                except Exception: pass
                self.page = await self.context.new_page()
                self._known_pages.add(self.page)
                try:
                    self.page.on("close", lambda p: self._known_pages.discard(p))
                except Exception:
                    pass
                self._attach_file_handler(self.page)
                await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
            else:
                raise

    async def new_tab(self, url=None):
        """Open new tab. Sets self.page to the new tab."""
        self.page = await self.context.new_page()
        # Register BEFORE goto so the popup guard's race window (between
        # context "page" event firing and goto completing) sees this as
        # a known agent tab and skips closing it.
        self._known_pages.add(self.page)
        # Discard from set on close so _known_pages doesn't grow unbounded
        # across hard-retries that close+reopen agent tabs.
        try:
            self.page.on("close", lambda p: self._known_pages.discard(p))
        except Exception:
            pass
        if url:
            log(f"New tab: {url}")
            await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
        self._attach_file_handler(self.page)
        return self.page

    async def open_isolated_tab(self, url=None):
        """Open a throwaway tab WITHOUT touching self.page. Use for
        verify/probe tabs the caller will close in a finally. Critical
        because new_tab() reassigns self.page — closing the returned
        page would leave self.page pointing at a dead page and break
        the next Browser-level navigate. See verify_at_phase_time
        (:7718) — pre-fix, that flow used new_tab + tab.close() and
        crashed P1's first navigate with TargetClosedError every time
        skipInitVerify was on."""
        page = await self.context.new_page()
        self._known_pages.add(page)
        try:
            page.on("close", lambda p: self._known_pages.discard(p))
        except Exception:
            pass
        if url:
            log(f"New tab: {url}")
            await page.goto(url, wait_until="domcontentloaded", timeout=30000)
        self._attach_file_handler(page)
        return page

    async def switch_to_page(self, page):
        self.page = page
        await page.bring_to_front()

    async def current_url(self):
        return self.page.url

    async def close(self):
        try:
            if self.context: await self.context.close()
            if self.playwright: await self.playwright.stop()
            log("Browser closed")
        except Exception as e:
            log(f"Browser close error: {e}", "WARN")
            # Kill only OUR profile's chromium — never nuke all chrome.exe
            try:
                import psutil
                our_profile = str(Path(self.profile_dir).resolve()).lower().replace("\\", "/")
                for proc in psutil.process_iter(["pid", "name", "cmdline"]):
                    try:
                        if proc.info["name"] and "chrom" in proc.info["name"].lower():
                            cmdline = " ".join(proc.info["cmdline"] or []).lower().replace("\\", "/")
                            if _profile_matches_cmdline(our_profile, cmdline):
                                proc.kill()
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        pass
            except Exception:
                pass


# ── Action Executor ────────────────────────────────────────────────────────────

async def execute_action(browser, action, params):
    """Execute a CUA action. Returns screenshot base64."""
    if action == "screenshot":
        return None
    try:
        if action == "left_click":
            x, y = params["coordinate"]; log_action("left_click", f"({x}, {y})"); await browser.left_click(x, y)
        elif action == "right_click":
            x, y = params["coordinate"]; log_action("right_click", f"({x}, {y})"); await browser.right_click(x, y)
        elif action == "double_click":
            x, y = params["coordinate"]; log_action("double_click", f"({x}, {y})"); await browser.double_click(x, y)
        elif action == "triple_click":
            x, y = params["coordinate"]; log_action("triple_click", f"({x}, {y})"); await browser.triple_click(x, y)
        elif action == "middle_click":
            x, y = params["coordinate"]; log_action("middle_click", f"({x}, {y})"); await browser.middle_click(x, y)
        elif action == "type":
            text = params["text"]; log_action("type", f"{len(text)} chars")
            if len(text) > 200:
                # insertText for long text — avoids clipboard file-paste issue
                try:
                    await browser.page.keyboard.insert_text(text)
                except Exception:
                    await browser.type_text(text[:2000])
            else:
                await browser.type_text(text)
        elif action == "key":
            combo = params.get("key") or params.get("text", "")
            if not combo:
                log("Empty key — skipping", "WARN"); return await browser.screenshot()
            log_action("key", combo); await browser.key(combo)
        elif action == "mouse_move":
            x, y = params["coordinate"]; log_action("mouse_move", f"({x}, {y})"); await browser.mouse_move(x, y)
        elif action == "scroll":
            x, y = params.get("coordinate", (640, 400))
            d = params.get("direction", "down")
            a = params.get("amount", 3)
            log_action("scroll", f"({x},{y}) {d}"); await browser.scroll(x, y, d, a)
        elif action == "left_click_drag":
            sx, sy = params.get("start_coordinate", (0, 0))
            ex, ey = params.get("end_coordinate", (0, 0))
            log_action("drag", f"({sx},{sy})->({ex},{ey})"); await browser.left_click_drag(sx, sy, ex, ey)
        elif action == "wait":
            d = params.get("duration", 1); log_action("wait", f"{d}s"); await asyncio.sleep(d)
        else:
            log(f"Unknown action: {action}", "WARN")
    except Exception as e:
        log(f"Action '{action}' failed: {e} — continuing", "WARN")
    await asyncio.sleep(0.5)
    return await browser.screenshot()


# ── Agent Loop ─────────────────────────────────────────────────────────────────

async def agent_loop(client, browser, system_prompt, user_message,
                     model=CUA_MODEL, max_iterations=30, verbose=False,
                     phase=None, agent_name=None, target_page=None,
                     abort_event=None):
    """CUA agent loop — proven from original research.py.

    target_page (optional): Playwright Page reference. When provided, every
    screenshot re-anchors to this tab via bring_to_front. Prevents the
    "Claude polls screenshotted Gemini's tab" race when another async path
    swaps browser.page between iterations.

    abort_event (optional): asyncio.Event the caller sets to make the loop
    stop deterministically (#732). Checked at the top of every iteration AND
    before each tool_use is dispatched, so once it fires the loop issues NO
    further clicks — even mid-turn. Used by _extract_via_cua_download to halt
    CUA the moment the first download lands (a plain task .cancel() is
    unreliable here because the synchronous Anthropic call freezes the event
    loop, delaying both the download event and the cancel). Returns
    status="aborted" when it trips.
    """
    async def _anchored_screenshot():
        if target_page is not None:
            try:
                await browser.switch_to_page(target_page)
            except Exception:
                pass
        return await browser.screenshot()

    initial_ss = await _anchored_screenshot()
    if not initial_ss:
        return {"status": "error", "text": "Could not take initial screenshot"}

    messages = [{"role": "user", "content": [
        {"type": "text", "text": user_message},
        {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": initial_ss}},
    ]}]
    tools = [{"type": "computer_20251124", "name": "computer",
              "display_width_px": API_WIDTH, "display_height_px": API_HEIGHT}]

    last_text = ""
    recent_actions = []
    transient_api_retries = 0
    # #61: mission-wide budgets for the transient-then-escalate Anthropic classes.
    # A 429/529 that clears within budget self-heals SILENTLY (no card — matches
    # decision #2 + the FE isAnthropicRuntimeError quiet set); one that survives
    # the budget escalates to a paused blocker card (#705: a persistent rate-limit
    # / overload must not hide behind a forever-"retrying" banner and strand the
    # run). Placed before the loop so the budget is cumulative across iterations —
    # the 429/529 branches `continue` back into the loop without resetting them.
    rate_limit_retries = 0
    overload_retries = 0

    for iteration in range(1, max_iterations + 1):
        # ── Check stop/pause before each CUA API call ──
        if _controls.is_stop():
            return {"status": "stopped", "text": last_text}
        if _controls.is_pause():
            await _controls.wait_if_paused()
            if _controls.is_stop():
                return {"status": "stopped", "text": last_text}
        # Caller early-exit (#732): a download already landed — stop before
        # issuing another click (the menu doesn't visibly close, so CUA would
        # otherwise re-click and trigger duplicate downloads).
        if abort_event is not None and abort_event.is_set():
            return {"status": "aborted", "text": last_text}

        if verbose: log(f"Iteration {iteration}/{max_iterations}")
        try:
            # 2026-07-11 (+review r2): transient server-side 5xx errors retry
            # INSIDE the create call so they don't burn mission iterations (a
            # 500 on the final iteration used to exit as max_iterations
            # without retrying; before that, a single mid-mission 500
            # TERMINATED the whole CUA task — FIFA run 15:28:50: the P3
            # create-notebook task died at iteration 4 and gemini.md never
            # reached the file dialog). 429/529/cap/401 keep their existing
            # handling in the except branches below. Bounded per mission.
            while True:
                try:
                    response = client.beta.messages.create(
                        model=model, max_tokens=4096, system=system_prompt,
                        tools=tools, messages=messages, betas=[BETA_FLAG],
                    )
                    break
                except Exception as _api_e:
                    _api_s = str(_api_e)
                    _api_l = _api_s.lower()
                    _is_5xx = ("internal server error" in _api_l
                               or "api_error" in _api_l
                               or re.search(r"error code:\s*5\d\d", _api_l))
                    _is_rate_limit = ("429" in _api_s or "rate_limit" in _api_l)
                    _is_overload = ("overloaded" in _api_l or "529" in _api_s)
                    # #61: 429/529 are transient — bounded SILENT retry IN PLACE
                    # (the same shape as the 5xx path below) so the backoff never
                    # burns a mission iteration. Retrying via the OUTER loop's
                    # `continue` instead would drain a short-budget caller
                    # (max_iterations ≤ budget) before the escalation could fire,
                    # returning a mute status="max_iterations" with no card. Only
                    # once the mission-wide budget is spent do we `raise` to the
                    # paused-blocker escalation in the outer handler. Stop-aware:
                    # a Stop skips the retry so it lands within the current sleep,
                    # not after the whole 90s / 5-min backoff.
                    if _is_rate_limit and rate_limit_retries < 3 and not _controls.is_stop():
                        rate_limit_retries += 1
                        log(f"Claude API rate limited (429) — transient retry "
                            f"{rate_limit_retries}/3 in 30s: {_api_s[:160]}", "WARN")
                        await asyncio.sleep(30)
                        continue
                    if _is_overload and overload_retries < 5 and not _controls.is_stop():
                        overload_retries += 1
                        log(f"API overloaded (529) — transient retry {overload_retries}/5 in 60s", "WARN")
                        await asyncio.sleep(60)
                        continue
                    if _is_5xx and not (_is_rate_limit or _is_overload) and transient_api_retries < 3:
                        transient_api_retries += 1
                        log(f"API transient 5xx — retry {transient_api_retries}/3 "
                            f"in 20s: {_api_s[:160]}", "WARN")
                        await asyncio.sleep(20)
                        continue
                    raise
        except Exception as e:
            err = str(e)
            # Resolve which phase/agent this CUA call is serving so the
            # frontend can route the warning to the correct per-agent
            # badge inside Phase 2 instead of collapsing into a phase-wide
            # banner. Fall back to _runtime.phase when caller omitted it.
            _phase = phase if phase is not None else _runtime.phase
            _agent = agent_name or None
            low = err.lower()
            # #61: a Stop during the in-place transient backoff (or any error the
            # user chose to abort through) returns cleanly — never fire a card.
            if _controls.is_stop():
                return {"status": "stopped", "text": last_text}
            if "rate_limit" in low or "429" in err:
                # #61: reached here only AFTER the in-place silent-retry budget (in
                # the create loop above) is exhausted — a PERSISTENT 429 is a
                # key/quota problem the user must act on (#705 preserved via
                # escalation, not pause-on-first-429). Escalate to a paused BLOCKER
                # whose title dodges the FE quiet set ("rate limit" with a SPACE ≠
                # "rate_limit"/"rate-limit", no "429"), so it can never be swallowed
                # into "retrying automatically" while the run sits paused — the
                # appear-then-vanish strand #705 feared (which the OLD title "API
                # key is rate-limited" still caused).
                log(f"Claude API 429 persisted past the retry budget "
                    f"— escalating to paused key card: {err[:160]}", "ERROR")
                _rl_msg = _anthropic_key_card_copy("rate_limit")
                if _phase == 2 and _agent:
                    fail_agent(_agent, "API key rate limit persists", _rl_msg,
                               recoverability="blocker")
                else:
                    # #63: distinct alert_id (was the generic phase{n}_error).
                    # The four Anthropic key cards (rate-limit / overload / cap /
                    # rejected) are distinct blockers that can SEQUENCE at one
                    # phase (e.g. rate-limit → user swaps key → Retry → rejected).
                    # Sharing phase{n}_error meant the FE dismiss-resurface ledger
                    # (store.ts, keyed on alert_id) let a dismissed earlier card
                    # silence the later one within its 5-min window — a paused run
                    # with no visible reason. Distinct ids can't cross-silence and
                    # don't double-card (phaseAlerts is one slot per phase, so it's
                    # still last-write-wins on the tile). The P2 per-agent path
                    # above keeps phase{n}_agent_{key}_error on purpose — that's the
                    # intentional one-card-per-agent slot.
                    fail_phase(_phase, "API key rate limit persists", _rl_msg,
                               recoverability="blocker",
                               alert_id=f"phase{_phase}_ai_rate_limit")
                return {"status": "error", "text": str(e)}
            elif "overloaded" in low or "529" in err:
                # #61: reached here only AFTER the in-place 529 retry budget is
                # exhausted — a sustained Anthropic outage. Escalate to a paused
                # blocker (the user can wait it out or Stop; Retry re-probes once
                # Anthropic recovers). The old unbounded sleep(60)+continue silently
                # burned the whole iteration budget and ended as a mute
                # status="max_iterations" partial with no actionable card. Title
                # carries no "overloaded"/"529" substring so it never re-enters the
                # FE quiet branch (belt; recoverability="blocker" is the real guard).
                log("API overloaded (529) persisted past the retry budget — escalating to paused card", "ERROR")
                _ov_msg = ("Anthropic's servers are overloaded and haven't recovered. "
                           "Wait a few minutes and Retry, or Stop the run.")
                if _phase == 2 and _agent:
                    fail_agent(_agent, "AI service unavailable", _ov_msg,
                               recoverability="blocker")
                else:
                    fail_phase(_phase, "AI service unavailable", _ov_msg,
                               recoverability="blocker",
                               alert_id=f"phase{_phase}_ai_unavailable")  # #63: distinct id
                return {"status": "error", "text": str(e)}
            elif "workspace api usage limits" in low or ("400" in err and "usage limit" in low):
                log(f"Workspace API cap hit — aborting CUA loop: {err[:200]}", "ERROR")
                _cap_hint = _anthropic_key_card_copy("cap")
                # #61: a workspace cap is a genuine must-act key problem — mark it a
                # blocker (class-honesty; keeps the per-agent card, adds the FE
                # un-swallowable gate). Title already dodges the FE quiet set.
                if _phase == 2 and _agent:
                    fail_agent(_agent, "API key is over its limit", _cap_hint,
                               recoverability="blocker")
                else:
                    fail_phase(_phase, "API key is over its limit", _cap_hint,
                               recoverability="blocker",
                               alert_id=f"phase{_phase}_ai_cap")  # #63: distinct id
                return {"status": "error", "text": str(e)}
            elif "401" in err and ("unauthorized" in low or "invalid" in low or "api_key" in low):
                log(f"Claude API key rejected — aborting CUA loop: {err[:200]}", "ERROR")
                _bad_key_hint = _anthropic_key_card_copy("invalid")
                # #61: a rejected key is must-act — mark it a blocker (class-honesty).
                if _phase == 2 and _agent:
                    fail_agent(_agent, "API key was rejected", _bad_key_hint,
                               recoverability="blocker")
                else:
                    fail_phase(_phase, "API key was rejected", _bad_key_hint,
                               recoverability="blocker",
                               alert_id=f"phase{_phase}_ai_key_rejected")  # #63: distinct id
                return {"status": "error", "text": str(e)}
            else:
                # Transient 5xx already exhausted its bounded in-place retries
                # in the inner loop above — anything landing here is terminal.
                log(f"API error: {e}", "ERROR")
                return {"status": "error", "text": str(e)}

        assistant_content = response.content
        messages.append({"role": "assistant", "content": assistant_content})

        tool_uses = []
        for block in assistant_content:
            if hasattr(block, "text"):
                last_text = block.text
                # 2026-07-11: 200→400 chars — verdict rationales (completion
                # checks, source verify, stuck arbiter) were losing their
                # decisive tail to the truncation, making the log alone
                # unable to explain WHY a vision check concluded what it did.
                if verbose: log(f"Claude: {last_text[:400]}")
            if block.type == "tool_use":
                tool_uses.append(block)

        if not tool_uses:
            return {"status": "done", "text": last_text}

        tool_results = []
        for tb in tool_uses:
            # #732: stop before dispatching another action once the abort
            # fired (the first download was captured) — closes the same-turn
            # re-click window that the per-iteration check above can't.
            if abort_event is not None and abort_event.is_set():
                break
            act = tb.input.get("action", "")
            # Stuck detection
            sig = f"{act}:{tb.input.get('coordinate', '')}"
            recent_actions.append(sig)
            if len(recent_actions) > 5: recent_actions.pop(0)
            if len(recent_actions) == 5 and len(set(recent_actions)) == 1:
                log("Stuck — same action 5x. Injecting hint.", "WARN")
                tool_results.append({"type": "tool_result", "tool_use_id": tb.id, "content": [
                    {"type": "text", "text": "You seem stuck. Try a different approach."},
                    {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": await _anchored_screenshot()}},
                ]})
                recent_actions.clear()
                continue

            if act == "screenshot":
                ss = await _anchored_screenshot()
                tool_results.append({"type": "tool_result", "tool_use_id": tb.id,
                    "content": [{"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": ss}}]})
            else:
                ss = await execute_action(browser, act, tb.input)
                # Re-anchor after action — execute_action may have navigated,
                # opened a new tab, or the OS swapped focus during the click.
                if target_page is not None:
                    try:
                        await browser.switch_to_page(target_page)
                    except Exception:
                        pass
                tool_results.append({"type": "tool_result", "tool_use_id": tb.id, "content": [
                    {"type": "text", "text": f"Action '{act}' executed."},
                    {"type": "image", "source": {"type": "base64", "media_type": "image/png", "data": ss}},
                ]})
            # Emit CUA action event for frontend visibility
            if agent_name and act != "screenshot":
                emit_event("cua_action", phase=phase, agent=agent_name,
                    action=act, description=last_text[:200] if last_text else f"Action: {act}",
                    iteration=iteration)
        # #732: a download captured mid-turn → return now, before another loop.
        if abort_event is not None and abort_event.is_set():
            return {"status": "aborted", "text": last_text}
        messages.append({"role": "user", "content": tool_results})

    return {"status": "max_iterations", "text": last_text}


# ── Verification Helpers ───────────────────────────────────────────────────────

async def verify_chatgpt_generating(page) -> bool:
    """Check if ChatGPT is actively generating (stop button visible).
    Scrolls both page body AND chat container — DR stop button is in chat UI, not input area.

    2026-04 iframe fix: ChatGPT Deep Research renders inside a cross-origin
    sandbox iframe (connector_openai_deep_research.web-sandbox.oaiusercontent.com).
    Host-page selectors miss the DR stop button + progress entirely, so we
    walk `page.frames` and check inside the DR iframe for any "researching"/
    "sources"/"stop" signal. Matches the detect_completion_chatgpt pattern."""
    try:
        await page.evaluate("""() => {
            // Scroll the page body
            window.scrollTo(0, document.body.scrollHeight);
            // Also scroll common chat containers (DR stop button is inside the chat, not input)
            const containers = document.querySelectorAll(
                '[class*="react-scroll"], [class*="chat-messages"], main, [role="presentation"]');
            containers.forEach(c => c.scrollTop = c.scrollHeight);
        }""")
        await asyncio.sleep(0.3)
        host_hit = await page.evaluate("""() => {
            // Check standard composer stop buttons
            const stop = document.querySelector('button[aria-label="Stop generating"]')
                || document.querySelector('button[data-testid="stop-button"]')
                || document.querySelector('button[aria-label="Stop streaming"]')
                || document.querySelector('button[aria-label="Stop"]');
            if (stop) return true;
            // ChatGPT Deep Research: stop button lives INSIDE the research card/dialog
            // (not in the composer). Look for buttons inside research/canvas containers.
            const cards = document.querySelectorAll(
                '[data-testid*="research"], [data-testid*="canvas"], [class*="research"], ' +
                '[aria-label*="Deep research"], [aria-label*="deep research"]'
            );
            for (const c of cards) {
                const cBtns = c.querySelectorAll('button');
                for (const b of cBtns) {
                    const lbl = (b.getAttribute('aria-label') || '').toLowerCase();
                    const t = (b.textContent || '').trim().toLowerCase();
                    if (lbl.includes('stop') || lbl.includes('cancel') || t === 'stop') return true;
                }
                // Progress/loading indicator inside the card
                if (c.querySelector('[role="progressbar"], [class*="progress"], [class*="spinner"]')) return true;
            }
            // Check by button content (square icon = stop)
            const btns = document.querySelectorAll('button');
            for (const b of btns) {
                const svg = b.querySelector('svg rect, svg path');
                const label = (b.getAttribute('aria-label') || '').toLowerCase();
                if (label.includes('stop')) return true;
            }
            // 2026-05-14: CSS-animation fallback (mirrors verify_gemini_generating /
            // verify_claude_generating). Catches the gap between "Thought for X
            // seconds" badge appearing and the iframe-scoped stop button rendering
            // — the previous code's 'thought for ' short-circuit was firing as a
            // false done-signal during that window. E2E hit this: CUA clicked
            // Start research on the clarification panel, research went to
            // "Researching..." state, but no host-level stop button + a stale
            // "Thought for" badge made the host check return false 15× and the
            // outer loop spawned a 2nd ChatGPT tab.
            // 2026-05-14 (refined): use getAnimations() + playState === 'running'.
            // CSS animationName remains set on elements with completed/never-
            // run animations, so the prior check returned true forever on
            // persistent UI chrome (avatars, fade-ins) and caused Phase 1
            // brief verify to read as "generating" for 27 min after the brief
            // actually completed, leading the multi-signal stall watchdog to
            // fire as a false alarm. Visibility gate added to skip hidden
            // animated nodes that some component libraries keep mounted.
            const animated = document.querySelectorAll(
                '[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"], [class*="streaming"]'
            );
            for (const el of animated) {
                if (el.offsetParent === null) continue;
                if (typeof el.getAnimations !== 'function') continue;
                const anims = el.getAnimations();
                if (anims.some(a => a.playState === 'running')) return true;
            }
            // 2026-05-24 P1-stall fix: gate body-text keyword checks on the
            // presence of DR-mode UI. hostKws ('searching the web' / 'reading
            // sources' / 'sources and counting') and 'researching...' literal
            // were added (2026-05-14, commit 4003d38) to catch P2 DR active
            // state when the clarification card transitions post-Start-click.
            // For P1 Pro + Extended Thinking, no DR card exists — and the
            // brief response for research-themed prompts (e.g. movie research
            // briefs) naturally writes literal phrases like "searching the
            // web" / "reading sources" / "researching..." in its narrative
            // content. That made the body-text sweep return true forever
            // after a P1 brief completed, stalling verify for 27+ minutes
            // (Salaar/Kalki E2E 2026-05-24). The fix: only run keyword sweep
            // when a DR-mode marker is actually mounted; for non-DR pages,
            // rely on CSS-animation + .result-streaming structural signals.
            // Gate selectors are narrow on purpose: [class*="research"] from
            // the cards loop above is too broad (response containers can have
            // research-themed class names); data-testid + aria-label are
            // DR-specific affordances that don't appear in P1.
            const bl = (document.body?.innerText || '').toLowerCase();
            const drModePresent = document.querySelector(
                '[data-testid*="research"], [data-testid*="canvas"], '
                + '[aria-label*="Deep research"], [aria-label*="deep research"]'
            ) !== null;
            if (drModePresent) {
                const hostKws = ['sources and counting', 'searching the web', 'reading sources'];
                if (hostKws.some(k => bl.includes(k))) return true;
                // post-Start "Researching..." status lives inside the DR
                // clarification card affordance. Gated on drModePresent so it
                // can't false-positive on P1 brief narrative that writes
                // "researching..." in prose.
                if (bl.includes('researching...')) return true;
            }
            // "Thought for X seconds" badge persists during Extended Thinking
            // (P1 Pro) and DR (P2). With stop button + cards + CSS-animation
            // all negative above, this confirms the page is settled. Kept
            // outside the DR gate — it's a NEGATIVE (done) signal.
            // 2026-05-24: tightened from `includes('thought for ')` to require
            // a digit, so assistant narrative like "I thought for a moment
            // about Salaar..." could not declare done prematurely when the
            // earlier stop/animation checks happened to be momentarily
            // negative between token batches.
            // ⭐ 2026-08-12: and widened from that one verb to the shared
            // pattern. This line is the reason the 2026-08-12 P1 run polled
            // 44 minutes past a finished brief: the page read "Worked for 16m
            // 26s", the vision classifier recognised it, and THIS check — the
            // one the poll loop actually asks — did not. The unit is now
            // required as well as the digit, which is what keeps "worked for
            // 3 years" in the brief's own prose from reading as done.
            // See _THINKING_TIME_HEADER_SRC.
            if (__DONE_BADGE_RE__.test(bl)) return false;
            return !!document.querySelector('.result-streaming, [data-is-streaming="true"]');
        }""".replace("__DONE_BADGE_RE__", _THINKING_TIME_HEADER_JS))
        if host_hit:
            return True

        # ── DR iframe walk ──
        # Deep Research renders inside a sandboxed frame. 2026-08-06: the frame
        # list comes from `_chatgpt_surface_frame_targets` rather than a local
        # URL-substring copy — this gate decides "is ChatGPT still generating",
        # and a filter that skips the `about:blank` surface answers it from an
        # empty document. Same defect the completion detector carried.
        try:
            for frame in _chatgpt_surface_frame_targets(page)[1:]:
                try:
                    active = await frame.evaluate("""() => {
                        // Any stop button
                        for (const b of document.querySelectorAll('button')) {
                            const t = (b.textContent || '').trim().toLowerCase();
                            const al = (b.getAttribute('aria-label') || '').toLowerCase();
                            if (t === 'stop' || t === 'stop research' ||
                                al.includes('stop')) return true;
                        }
                        // Spinner / progress
                        if (document.querySelector(
                            '[role="progressbar"], [class*="progress"], [class*="spinner"], ' +
                            '[class*="loading"], [data-is-streaming="true"]'
                        )) return true;
                        // 2026-05-14: CSS-animation fallback (mirrors verify_gemini /
                        // verify_claude). ChatGPT DR's "Researching..." state has
                        // animated text-shimmer + dot-flashing inside the iframe
                        // that don't always have a [class*="spinner"] marker at
                        // the exact poll moment — without this fallback the
                        // iframe walk returned false during legitimate research
                        // and the outer loop spawned a 2nd tab. E2E 2026-05-14:
                        // CUA had clicked Start research and the iframe was
                        // visibly rendering when this returned false 15×.
                        // 2026-05-14 (refined): use getAnimations() + playState ===
                        // 'running' to avoid false-positives from completed
                        // animations whose CSS animationName remains set.
                        const animated = document.querySelectorAll(
                            '[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"], [class*="streaming"]'
                        );
                        for (const el of animated) {
                            if (el.offsetParent === null) continue;
                            if (typeof el.getAnimations !== 'function') continue;
                            const anims = el.getAnimations();
                            if (anims.some(a => a.playState === 'running')) return true;
                        }
                        const bl = (document.body?.innerText || '').toLowerCase();
                        // 2026-05-14 (post-E2E): the post-Start status bar inside
                        // the DR iframe shows literal "Researching..." (with
                        // ellipsis) while research is active. The ellipsis is
                        // what makes this safe — bare "researching" would
                        // false-positive on narrative prose, but the ellipsis
                        // pattern is the live status indicator, not story text.
                        // Must beat the 'thought for ' short-circuit below.
                        if (bl.includes('researching...')) return true;
                        // "Thought for X seconds" badge persists while DR
                        // continues — it's NOT a definitive done signal. With
                        // stop button + spinner + CSS animation all negative
                        // above, treat the iframe as settled. Keyword fallthrough
                        // intentionally not re-added: inside the DR iframe, body
                        // text IS the rendered brief itself (could legitimately
                        // contain "after reading sources" / "searching the web"),
                        // and any keyword match would re-introduce the same
                        // false-positive class as the deleted length>200 fallback.
                        // 2026-05-24: same regex tightening as host path —
                        // require a digit to lock to badge format and not
                        // match narrative prose. 2026-08-12: and the same
                        // widening — see the host copy above and
                        // _THINKING_TIME_HEADER_SRC.
                        if (__DONE_BADGE_RE__.test(bl)) return false;
                        return false;
                    }""".replace("__DONE_BADGE_RE__", _THINKING_TIME_HEADER_JS))
                    if active:
                        return True
                except Exception:
                    pass
                # ⛔ NO `break` HERE. It used to sit at the end of this body,
                # inside the URL-substring `if`, so the walk stopped at the FIRST
                # matching frame. With the candidate list widened, keeping it
                # would only change WHICH single frame gets asked — and on
                # 2026-08-06 the first match was the connector shell, which
                # answers from an empty document. Ask all of them.
        except Exception:
            pass
        return False
    except Exception:
        return False


async def _verify_chatgpt_generating_diag(page) -> str:
    """Diagnostic twin of verify_chatgpt_generating's host_hit JS — returns
    the reason string for "still generating" instead of just a bool. Used
    by poll_until_done's safety-net CUA escalation so the log shows
    WHICH path inside the verify function is the false-positive when DOM
    keeps reporting generating but content is flat.

    Returns empty string when the verify would have returned False (done).
    Returns one of: "stop_composer:<aria-label>", "card_stop:<class>",
    "card_progress:<class>", "generic_stop_label:<label>",
    "css_animation:<class>", "host_kw:<phrase>", "researching_ellipsis",
    "data_streaming_attr", or "no_hit" (which should round-trip to False
    in the real verify too).

    NOTE: kept in sync MANUALLY with verify_chatgpt_generating's host_hit
    block (research.py:~14495-14597). If you touch one, touch the other.
    Drift only affects diagnostic accuracy — the real verify path is
    unaffected and the safety-net CUA escalation still works."""
    try:
        return await page.evaluate("""() => {
            const stop = document.querySelector('button[aria-label="Stop generating"]')
                || document.querySelector('button[data-testid="stop-button"]')
                || document.querySelector('button[aria-label="Stop streaming"]')
                || document.querySelector('button[aria-label="Stop"]');
            if (stop) return "stop_composer:" + (stop.getAttribute('aria-label') || stop.getAttribute('data-testid') || '?');

            const cards = document.querySelectorAll(
                '[data-testid*="research"], [data-testid*="canvas"], [class*="research"], ' +
                '[aria-label*="Deep research"], [aria-label*="deep research"]'
            );
            for (const c of cards) {
                const cBtns = c.querySelectorAll('button');
                for (const b of cBtns) {
                    const lbl = (b.getAttribute('aria-label') || '').toLowerCase();
                    const t = (b.textContent || '').trim().toLowerCase();
                    if (lbl.includes('stop') || lbl.includes('cancel') || t === 'stop')
                        return "card_stop:" + ((c.className || c.getAttribute('data-testid') || '?') + '').slice(0, 60);
                }
                if (c.querySelector('[role="progressbar"], [class*="progress"], [class*="spinner"]'))
                    return "card_progress:" + ((c.className || c.getAttribute('data-testid') || '?') + '').slice(0, 60);
            }

            const btns = document.querySelectorAll('button');
            for (const b of btns) {
                const label = (b.getAttribute('aria-label') || '').toLowerCase();
                if (label.includes('stop'))
                    return "generic_stop_label:" + label.slice(0, 60);
            }

            const animated = document.querySelectorAll(
                '[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"], [class*="streaming"]'
            );
            for (const el of animated) {
                if (el.offsetParent === null) continue;
                if (typeof el.getAnimations !== 'function') continue;
                const anims = el.getAnimations();
                if (anims.some(a => a.playState === 'running'))
                    return "css_animation:" + ((el.className || el.tagName) + '').slice(0, 80);
            }

            const bl = (document.body?.innerText || '').toLowerCase();
            const drModePresent = document.querySelector(
                '[data-testid*="research"], [data-testid*="canvas"], '
                + '[aria-label*="Deep research"], [aria-label*="deep research"]'
            ) !== null;
            if (drModePresent) {
                const hostKws = ['sources and counting', 'searching the web', 'reading sources'];
                const hit = hostKws.find(k => bl.includes(k));
                if (hit) return "host_kw:" + hit;
                if (bl.includes('researching...')) return "researching_ellipsis";
            }

            if (__DONE_BADGE_RE__.test(bl)) return "";
            return document.querySelector('.result-streaming, [data-is-streaming="true"]') ? "data_streaming_attr" : "";
        }""".replace("__DONE_BADGE_RE__", _THINKING_TIME_HEADER_JS)) or "no_hit"
    except Exception as e:
        return f"diag_error:{type(e).__name__}"


async def verify_gemini_generating(page) -> bool:
    """Check if Gemini is actively generating — broad stop button + animation detection.

    ⛔⛔ DO NOT ADD A VISIBILITY GATE TO THE BUTTON SCAN BELOW. It looks like the
    obvious missing guard — the Start scans in scrape_progress_gemini and
    detect_completion_gemini both have one, and this function has none — and
    adding it would break the one Gemini probe that works. Measured 2026-08-19 on
    a live Deep Research: the ONLY stop-ish control in the document while Gemini
    researches is `<button aria-label="Stop response">` with offsetParent null
    and a 0×0 box. This scan lowercases the attributes, so it matches that button
    and returns True — which is why "[2D] Gemini is researching ✓" fires at all.
    A visibility gate here would reject the only evidence there is, and 2D would
    fall through to "may not be running" on every healthy run.

    ⭐ The asymmetry is correct rather than sloppy: this function answers "is it
    alive", where a hidden stop is good enough evidence, while
    detect_completion_gemini answers "is it finished", where the same button must
    never veto a done-marker. Same DOM fact, two different questions, two
    different rankings — see the stop-split note in that detector."""
    try:
        await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        await asyncio.sleep(0.3)
        return await page.evaluate("""() => {
            // Broad button scan — any button with stop-related text/label
            const btns = document.querySelectorAll('button');
            for (const b of btns) {
                const a = (b.getAttribute('aria-label') || '').toLowerCase();
                const t = (b.getAttribute('title') || '').toLowerCase();
                const txt = (b.textContent || '').trim().toLowerCase();
                if (a.includes('stop') || t.includes('stop') || txt === 'stop') return true;
            }
            // Animation/streaming indicators
            if (document.querySelector('[data-is-streaming="true"], .loading-indicator')) return true;
            // CSS animation on any element (spinning, pulsing).
            // 2026-05-14: use getAnimations() + playState === 'running' so
            // persisted-but-completed CSS animations on UI chrome don't
            // false-positive (see verify_chatgpt_generating note).
            const animated = document.querySelectorAll('[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"]');
            for (const el of animated) {
                if (el.offsetParent === null) continue;
                if (typeof el.getAnimations !== 'function') continue;
                const anims = el.getAnimations();
                if (anims.some(a => a.playState === 'running')) return true;
            }
            return false;
        }""")
    except Exception:
        return False


def _claude_conversation_url(page) -> bool:
    """True when the tab is on an actual Claude conversation (`/chat/<uuid>`).

    A real submit NAVIGATES claude.ai/new → /chat/<uuid>. While the tab is still on
    /new (or the root, or the chat list) nothing has been sent, so no amount of DOM
    activity is evidence that Claude is generating. Kept separate from the DOM probe
    so both the verifier and the poll loop can gate on the same fact."""
    try:
        u = (page.url or "").split("?", 1)[0].split("#", 1)[0].rstrip("/").lower()
    except Exception:
        return True  # unreadable URL must not gate — fall back to the DOM probe
    if not u:
        return True
    return "/chat/" in u or "/project/" in u


async def verify_claude_generating(page) -> bool:
    """Check if Claude is actively generating — URL gate, then broad stop button +
    animation detection.

    THE URL GATE IS LOAD-BEARING. Without it this function returned True on ANY
    button whose aria-label/title/text merely contained "stop", or ANY visible
    element matching [class*=animate|spin|pulse|loading|streaming] with a running
    animation — none of which implies a send ever landed. On 2026-07-27 it reported
    `[2B] ✓ Verified — actively generating` and the system called the agent healthy
    for 8m18s while claude.ai sat on https://claude.ai/new behind a "We couldn't
    connect to Claude" banner with brief.md still unsent in the composer: `frames`
    stayed on /new, `text_len` stayed at exactly 74 across both polls, sources=0,
    steps=0. Only a CUA screenshot eventually caught it, by which point the agent
    was dropped from rotation and needed a manual hard retry.

    A generating Claude is ALWAYS on a conversation URL, so the gate cannot produce a
    false negative — it only removes a class of false positive."""
    if not _claude_conversation_url(page):
        # Deliberately not silent: "not yet generating" alone would hide the fact
        # that nothing was ever sent, which is a different problem with a different fix.
        try:
            _u = page.url
        except Exception:
            _u = "?"
        log(f"[Claude] not generating — tab is not on a conversation yet (url={_u}); "
            "the send never landed", "WARN")
        return False
    try:
        await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
        await asyncio.sleep(0.3)
        return await page.evaluate("""() => {
            // Broad button scan — any button with stop-related text/label/icon
            const btns = document.querySelectorAll('button');
            for (const b of btns) {
                const a = (b.getAttribute('aria-label') || '').toLowerCase();
                const t = (b.getAttribute('title') || '').toLowerCase();
                const txt = (b.textContent || '').trim().toLowerCase();
                if (a.includes('stop') || t.includes('stop') || txt === 'stop'
                    || a.includes('cancel gen') || a.includes('stop gen')) return true;
            }
            // Streaming/animation indicators
            if (document.querySelector('[data-is-streaming="true"]')) return true;
            // CSS animation check (Claude uses spinning asterisk, pulsing indicators).
            // 2026-05-14: use getAnimations() + playState === 'running' so
            // persisted-but-completed CSS animations on UI chrome don't
            // false-positive (see verify_chatgpt_generating note).
            const animated = document.querySelectorAll('[class*="animate"], [class*="spin"], [class*="pulse"], [class*="loading"], [class*="streaming"]');
            for (const el of animated) {
                if (el.offsetParent === null) continue;
                if (typeof el.getAnimations !== 'function') continue;
                const anims = el.getAnimations();
                if (anims.some(a => a.playState === 'running')) return true;
            }
            return false;
        }""")
    except Exception:
        return False


async def wait_until_verified(verify_fn, page, label, browser=None, cua_client=None,
                              max_retries=20, interval=3, verbose=False, phase=None):
    """Smart verification: DOM check first, then CUA diagnosis if failing.

    Phase 1 (retries 1-5): Quick DOM checks — maybe it just needs a moment.
    Phase 2 (retry 6): CUA diagnoses what's on screen.
    Phase 3 (retry 7): CUA tries to fix the issue (click buttons, dismiss dialogs).
    Phase 4 (retries 8-20): Continue DOM checks after CUA fix.
    """
    for i in range(max_retries):
        if await verify_fn(page):
            log(f"[{label}] ✓ Verified — actively generating")
            agent_key = normalize_agent_key(label)
            emit_event("agent_verified", phase=phase, agent=agent_key,
                verified=True, method="dom",
                message=f"{label} confirmed actively generating",
                attempts=i + 1)
            return True

        # Phase 1: Quick DOM checks
        if i < 5:
            log(f"[{label}] Not yet generating... check {i+1}/5")
            await asyncio.sleep(interval)
            continue

        # Phase 2: CUA diagnosis (once, at retry 6)
        if i == 5 and browser and cua_client:
            log(f"[{label}] DOM checks failed 5x — scrolling to bottom, asking CUA to diagnose...")
            await browser.switch_to_page(page)
            try:
                await page.evaluate("""() => {
                    window.scrollTo(0, document.body.scrollHeight);
                    document.querySelectorAll('[class*="react-scroll"], [class*="chat-messages"], main, [role="presentation"]')
                        .forEach(c => { try { c.scrollTop = c.scrollHeight; } catch(e){} });
                }""")
                await asyncio.sleep(0.4)
            except Exception:
                pass
            async def _diag_cua():
                return await agent_loop(cua_client, browser, PROMPT_DIAGNOSE,
                    "Look at the BOTTOM of the chat. Is there a Stop button visible? "
                    "Is there a loading animation or spinner? Is the AI actively generating?",
                    model=CUA_MODEL, max_iterations=3, verbose=verbose)

            # #839 act tier (read_only): a Vision verdict must land in the
            # returned text with the same plain-English signals the parser
            # below greps ("stop"+"yes" / "loading" / "still generating") —
            # the mission text instructs exactly that phrasing.
            diag = await _shadow_observed_cua(
                page, hotspot_id="poll-diagnose", phase=2,
                platform=normalize_agent_key(label),
                current_step="diagnose_generating_state",
                context_hint="DOM verify missed 5x — READ the bottom of the chat and "
                             "report: Stop button? spinner/loading? still generating?",
                expected_outcome="an honest text verdict on whether generation is running",
                cua_coro_factory=_diag_cua,
                mission_prompt=PROMPT_DIAGNOSE,
                read_only=True)
            diag_text = ((diag or {}).get("text") or "").lower()
            log(f"[{label}] CUA diagnosis: {(diag or {}).get('text', '')[:200]}")

            # ⭐ 2026-08-05 — EVERY signal here must be AFFIRMED, never merely
            # mentioned. This block used to read:
            #
            #     has_loading = (...) or "progress bar" in diag_text
            #
            # justified (2026-05-14) by "the phrase only appears when the bar is
            # actually present". It does not. The CUA enumerates the things it
            # looked for in order to deny them, and on the 2026-08-05 prod run it
            # wrote "No spinning ring, pulsing dot, or progress bar is visible."
            # — three explicit NOs — and this returned True. The send had never
            # landed; the tab was still showing the PREVIOUS conversation's
            # finished answer, and that answer was later harvested as the run's
            # output. One unconditional substring cost the whole leg.
            #
            # `has_stop` was loose the same way: `"stop" in t and "yes" in t`
            # matched the word "stop" inside the ECHOED QUESTION ("Stop button?")
            # with a 'yes' answering some other question paragraphs away.
            #
            # Everything now goes through the one polarity primitive. The cost
            # asymmetry runs OPPOSITE to _classify_completion_verdict's: there,
            # an unclear read must mean "keep polling"; here, an unclear read
            # must mean "no evidence of generation" so we fall through to the
            # Phase-3 diagnosis instead of declaring a dead send healthy.
            has_stop = (_cua_affirms(diag_text, "stop button")
                        or _cua_affirms(diag_text, "stop:")
                        or _cua_affirms(diag_text, "stop icon"))
            has_loading = (_cua_affirms(diag_text, "loading")
                           or _cua_affirms(diag_text, "spinner")
                           or _cua_affirms(diag_text, "spinning")
                           or _cua_affirms(diag_text, "animation")
                           or _cua_affirms(diag_text, "progress bar"))
            # A volunteered present-tense statement still counts — but the CUA
            # ECHOES each question before answering it ("**AI actively
            # generating?** No — ..."), so bare phrase-presence matches the
            # question rather than the answer. Require that the phrase is not
            # answered "no" on the spot, and not negated ahead of it.
            _gen_phrases = ("still generating", "actively generating",
                            "is generating", "currently generating")
            says_generating = any(
                p in diag_text and not _cua_denies(diag_text, p) for p in _gen_phrases
            ) and not any(
                n in diag_text for n in ("not still generating", "not actively generating",
                                         "not generating", "isn't generating",
                                         "is not generating", "no longer generating")
            )
            if has_stop or has_loading or says_generating:
                log(f"[{label}] ✓ CUA confirms generating "
                    f"(stop={has_stop} loading={has_loading} says={says_generating})")
                return True
            if "needs click" in diag_text or "start research" in diag_text:
                log(f"[{label}] CUA says button needs clicking")
                # Will be handled in Phase 3 (CUA fix)

            continue

        # Phase 3: CUA fix attempt (once, at retry 7)
        if i == 6 and browser and cua_client:
            log(f"[{label}] CUA attempting to fix the issue...")
            await browser.switch_to_page(page)

            async def _fix_cua():
                return await agent_loop(cua_client, browser, PROMPT_FIX_ISSUE,
                    "Fix whatever is blocking the research from starting. Click any needed buttons.",
                    model=CUA_MODEL, max_iterations=10, verbose=verbose)

            # #839 act tier: click-only recovery (the mission forbids typing);
            # success is judged by the Phase-4 DOM re-checks either way.
            fix = await _shadow_observed_cua(
                page, hotspot_id="poll-fix", phase=2,
                platform=normalize_agent_key(label),
                current_step="fix_blocked_generation",
                context_hint="generation hasn't started — click whatever blocks it "
                             "(Start/confirm/Send). NEVER type or paste text",
                expected_outcome="the blocking button is clicked and generation starts",
                cua_coro_factory=_fix_cua,
                mission_prompt=PROMPT_FIX_ISSUE)
            log(f"[{label}] CUA fix attempt: {(fix or {}).get('text', '')[:200]}")
            await asyncio.sleep(5)
            continue

        # Phase 4: Continue DOM checks after CUA intervention
        log(f"[{label}] Post-fix check {i-6}/{max_retries-7}")
        await asyncio.sleep(interval)

    log(f"[{label}] ✗ Could not verify after {max_retries} attempts (including CUA)", "WARN")
    return False


# ── DOM Polling (zero CUA cost) ───────────────────────────────────────────────

_last_progress: dict = {}  # Deduplication cache for agent_progress events


# ── MutationObserver streaming (real-time partial text per agent page) ───
#
# We inject a throttled MutationObserver into each agent page that watches
# the assistant's response container. It fires `window.onStream({len,text})`
# every ~500ms while the response grows. The callback here updates a shared
# dict keyed by page id, so the poll loop (Phase 1 or Phase 2) can read the
# latest `observer_text_len` + `observer_preview` when it emits agent_progress.
#
# This gives the frontend true token-level streaming while the 30s DOM poll
# keeps structured fields (sources/sections/steps) fresh. No polling wasted
# on just-a-few-more-chars-every-second — the observer handles that slice.

_OBSERVER_SELECTORS = {
    "chatgpt": ['[data-message-author-role="assistant"]:last-of-type',
                'main [data-message-id]:last-of-type',
                'article.text-token-text-primary:last-of-type'],
    "gemini":  ['message-content:last-of-type',
                '.model-response-text:last-of-type',
                '.response-container:last-of-type'],
    "claude":  ['[data-testid="assistant-message"]:last-of-type',
                '.font-claude-message:last-of-type',
                '[data-is-streaming]:last-of-type'],
}

# Keyed by id(page) — each page gets its own stream state
_agent_streams: dict[int, dict] = {}


def _make_stream_callback(page_id: int):
    """Return a callback for page.expose_function('onStream', ...)"""
    def cb(data):
        try:
            st = _agent_streams.setdefault(page_id, {})
            st["observer_text_len"] = int(data.get("len", 0) or 0)
            # 2026-05-25: strip ChatGPT's PUA-delimited citation runs from
            # the streamed preview. Without this, ChatGPT DR's mid-flight
            # observer text gets emitted into `partialTextPreview` via
            # agent_progress events, and the FE wraps the unbreakable
            # citation blobs as a wall of low-information noise — exact
            # symptom in the user's 2026-05-25 P2 ChatGPT MD screenshot.
            # No-op for Gemini/Claude (no PUA sentinels in their DOM).
            st["observer_preview"] = _strip_chatgpt_citation_tokens(
                str(data.get("text", "") or "")
            )[:500]
            st["last_update"] = time.time()
        except Exception:
            pass
    return cb


async def inject_agent_observer(page, agent_key: str):
    """Inject a throttled MutationObserver on `page` that streams the assistant
    response's partial text length + last 500 chars to Python.

    Idempotent: re-call after navigations to re-attach. The exposed function
    `onStream` is registered once per page (Playwright will raise on
    re-expose — we catch that).
    """
    page_id = id(page)
    _agent_streams.setdefault(page_id, {
        "observer_text_len": 0, "observer_preview": "", "last_update": 0.0,
    })
    try:
        await page.expose_function("onStream", _make_stream_callback(page_id))
    except Exception:
        # Already exposed — safe to ignore, callback is already bound
        pass

    selectors = _OBSERVER_SELECTORS.get(agent_key, [])
    if not selectors:
        return False

    script = """
    (selectors) => {
        if (window.__agentObserver) {
            try { window.__agentObserver.disconnect(); } catch(e) {}
        }
        let container = null;
        for (const sel of selectors) {
            try { container = document.querySelector(sel); } catch(e) {}
            if (container) break;
        }
        if (!container) {
            window.__agentObserverActive = false;
            return false;
        }
        let lastLen = 0;
        let timer = null;
        const mo = new MutationObserver(() => {
            clearTimeout(timer);
            timer = setTimeout(() => {
                const text = container.innerText || '';
                if (text.length === lastLen) return;
                lastLen = text.length;
                try {
                    window.onStream({ text: text.slice(-500), len: text.length, ts: Date.now() });
                } catch(e) {}
            }, 500);
        });
        mo.observe(container, {childList: true, subtree: true, characterData: true});
        window.__agentObserver = mo;
        window.__agentObserverActive = true;
        return true;
    }
    """
    try:
        ok = await page.evaluate(script, selectors)
        return bool(ok)
    except Exception as e:
        log(f"[observer-{agent_key}] inject failed: {e}", "WARN")
        return False


async def inject_chatgpt_dr_iframe_observer(page) -> bool:
    """Inject MutationObserver INSIDE the cross-origin DR iframe (Block 1b).

    The host-page observer (inject_agent_observer) cannot see iframe content
    because the iframe is cross-origin. Without this, partial_text_len
    flatlines while the DR iframe is actively streaming the report.

    Mirrors host-page observer state into the same _agent_streams[id(page)]
    entry by taking max(host_len, iframe_len), so get_observer_state(page)
    naturally reads the combined value.

    Gated by DG_CHATGPT_IFRAME_OBSERVER=1 (off by default — opt-in).
    Returns True if injected, False if no DR iframe found / inject failed.
    """
    # 2026-08-06: same candidate list as every other ChatGPT frame consumer —
    # see `_chatgpt_surface_frame_targets`. Off by default, but a private copy of
    # the URL substrings is exactly how the completion detector went blind.
    _cands = _chatgpt_surface_frame_targets(page)[1:]
    target_frame = _cands[0] if _cands else None
    if not target_frame:
        return False

    page_id = id(page)
    _agent_streams.setdefault(page_id, {
        "observer_text_len": 0, "observer_preview": "", "last_update": 0.0,
    })

    def _iframe_cb(data):
        try:
            iframe_len = int(data.get("len", 0) or 0)
            # 2026-05-25: strip ChatGPT's PUA-delimited citation runs from
            # iframe-side observer preview. This callback fires for the DR
            # sandbox iframe specifically — the same noise source as the
            # host-page callback above (citation tokens render to the DR
            # canvas DOM). Mirror the host-side strip so both observer
            # paths emit clean text.
            iframe_preview = _strip_chatgpt_citation_tokens(
                str(data.get("text", "") or "")
            )[:500]
            st = _agent_streams.setdefault(page_id, {})
            # Take max — host and iframe observers may both fire
            if iframe_len > int(st.get("observer_text_len", 0) or 0):
                st["observer_text_len"] = iframe_len
                st["observer_preview"] = iframe_preview
                st["last_update"] = time.time()
        except Exception:
            pass

    try:
        await target_frame.expose_function("onStreamIframe", _iframe_cb)
    except Exception:
        # Already exposed — safe to ignore
        pass

    iframe_selectors = ['main', 'article', '[class*="report"]', 'body']
    script = """
    (selectors) => {
        if (window.__agentObserverIframe) {
            try { window.__agentObserverIframe.disconnect(); } catch(e) {}
        }
        let container = null;
        for (const sel of selectors) {
            try { container = document.querySelector(sel); } catch(e) {}
            if (container) break;
        }
        if (!container) {
            window.__agentObserverIframeActive = false;
            return false;
        }
        let lastLen = 0;
        let timer = null;
        const mo = new MutationObserver(() => {
            clearTimeout(timer);
            timer = setTimeout(() => {
                const text = container.innerText || '';
                if (text.length === lastLen) return;
                lastLen = text.length;
                try {
                    window.onStreamIframe({ text: text.slice(-500), len: text.length, ts: Date.now() });
                } catch(e) {}
            }, 500);
        });
        mo.observe(container, {childList: true, subtree: true, characterData: true});
        window.__agentObserverIframe = mo;
        window.__agentObserverIframeActive = true;
        return true;
    }
    """
    try:
        ok = await target_frame.evaluate(script, iframe_selectors)
        if ok:
            log("[observer-chatgpt-iframe] injected into DR iframe", "INFO")
        return bool(ok)
    except Exception as e:
        log(f"[observer-chatgpt-iframe] inject failed: {e}", "WARN")
        return False


def get_observer_state(page) -> dict:
    """Read the latest MutationObserver snapshot for this page.
    Returns {} if observer hasn't been injected or hasn't fired yet."""
    try:
        return _agent_streams.get(id(page), {}) or {}
    except Exception:
        return {}


_VISION_URL_SCHEMA = {
    "type": "OBJECT",
    "properties": {
        "urls": {"type": "ARRAY", "items": {"type": "STRING"}},
        "confidence": {"type": "NUMBER"},
    },
    "required": ["urls", "confidence"],
}

_VISION_URL_PROMPT = (
    "Extract every source URL visible in this screenshot of an AI research "
    "panel (ChatGPT/Claude/Gemini side panel showing cited sources).\n"
    "RULES:\n"
    "1. Output only http:// or https:// URLs, verbatim.\n"
    "2. Skip platform chrome: chatgpt.com, openai.com, oaiusercontent, "
    "claude.ai, anthropic.com, gemini.google.com, accounts.google.com.\n"
    "3. If a URL is truncated with '...', skip it entirely. Never invent.\n"
    "4. confidence: 0.7+ if URLs read clearly, 0.4-0.7 partial, <0.4 if "
    "no URLs visible (return empty list)."
)

# ⭐ 2026-08-12 — THE OUTPUT BUDGET AND THE READ TIMEOUT ARE ONE DECISION.
# Yesterday's fix raised the budget here from 800 and left the clock at 10s, and
# that pairing is not arbitrary: at 800 tokens the answer arrived CLIPPED, which
# is itself proof it arrived inside ten seconds. Tripling what the model has to
# write without touching how long we wait for it turned a truncated-but-delivered
# response into a timed-out one — the same lost sources, a new cause, introduced
# by the repair.
#
# The floor below is the invariant worth keeping, not the arithmetic: assume the
# Flash tier emits no fewer than _VISION_URL_MIN_TOKENS_PER_SEC and require the
# timeout to cover the WHOLE budget at that rate. 800/100 = 8s is why the
# original pairing worked; 2400/100 = 24s is why it stopped. A test asserts the
# relation, so raising one of these again without the other fails in the suite
# instead of in a run.
#
# Sized generously rather than tightly on purpose. The caller is ONE-SHOT per
# agent — `vision_urls_done` is set on failure too — so a timeout costs the run
# every source in that panel with no retry to recover them, while the cost of
# waiting is one stretched round-robin leg inside a 120-second poll interval.
_VISION_URL_MIN_TOKENS_PER_SEC = 100
_VISION_URL_MAX_TOKENS = int(os.environ.get("DG_VISION_URL_MAX_TOKENS", "2400"))
_VISION_URL_TIMEOUT_S = float(os.environ.get("DG_VISION_URL_TIMEOUT_S", "30.0"))

# Confidence assigned to URLs recovered from a response that ran out of tokens.
# Above the 0.4 floor because a model that wrote out whole URLs demonstrably read
# the panel; below the 0.7 the prompt reserves for a clean read, because we never
# saw the model's own verdict — the `confidence` field is the LAST thing in the
# schema and a truncated response stops before it.
_VISION_URL_SALVAGE_CONFIDENCE = 0.5

# Only a URL that reached its CLOSING quote. A clipped last entry
# (`"https://example.com/artic`) has no closing quote and is skipped, which is
# the same instruction the prompt gives the model about truncated text on screen.
_VISION_URL_SALVAGE_RE = re.compile(r'"(https?://[^"\\\s]{4,500})"')


def _salvage_urls_from_truncated_json(text: str) -> "list[str]":
    """Whole URLs from a JSON response that stopped mid-object.

    ⭐ 2026-08-11. The alternative is returning nothing, and returning nothing
    is how the activity panel lost 56% of its sources on 08-06: one late failure
    discarding an entire batch that was overwhelmingly fine. A response clipped
    at the token ceiling still contains every URL the model finished writing.

    Deliberately a scan for closed quoted strings rather than a partial-JSON
    parser: it cannot half-read a URL, and everything it returns still goes
    through the scheme / length / platform-domain filter that the parsed path
    uses. Order is preserved and duplicates are left to that filter."""
    if not text:
        return []
    return _VISION_URL_SALVAGE_RE.findall(text)


_VISION_URL_SKIP_DOMAINS = (
    "chatgpt.com", "openai.com", "oaiusercontent",
    "claude.ai", "anthropic.com",
    "gemini.google.com", "accounts.google.com",
)


async def extract_source_urls_via_vision(page, agent_key: str,
                                          last_dom_count: int = 0) -> list:
    """Vision-extract source URLs from the agent's side panel (Block 3).

    Used as a supplementary signal when DOM scraping misses URLs (collapsed
    rows, popovers, lazy-loaded content, anchor-less click targets). Returns
    list of validated http(s) URLs (deduped, length-capped, platform-chrome
    filtered). Empty list on any failure — caller treats as no-op union.

    Disabled by setting DG_VISION_URL_EXTRACT=0.
    """
    api_key = resolve_gemini_api_key()
    if not api_key:
        return []

    try:
        png = await page.screenshot(type="png", full_page=False)
    except Exception as e:
        log(f"[{agent_key}] vision-urls screenshot failed: {e}", "DEBUG")
        return []

    # Crop heuristic: ChatGPT/Gemini panels are right ~45%; Claude artifact
    # panel can be center/right depending on layout — keep full frame.
    try:
        from narrate import _crop_right_fraction
        if agent_key in ("chatgpt", "gemini"):
            png = _crop_right_fraction(png, 0.45)
    except Exception:
        pass

    user_msg = (
        f"Agent: {agent_key}. DOM scrape found {last_dom_count} URLs. "
        "Extract every additional source URL visible in the side panel."
    )

    # Model resolved from models.GEMINI_NARRATE (env override:
    # GEMINI_NARRATE_MODEL) — see there for the current GA default.
    model = GEMINI_NARRATE
    url = (f"https://generativelanguage.googleapis.com/v1beta/models/"
           f"{model}:generateContent?key={api_key}")
    payload = {
        "contents": [{
            "role": "user",
            "parts": [
                {"inlineData": {
                    "mimeType": "image/png",
                    "data": base64.standard_b64encode(png).decode("ascii"),
                }},
                {"text": user_msg},
            ],
        }],
        "systemInstruction": {"parts": [{"text": _VISION_URL_PROMPT}]},
        "generationConfig": {
            "temperature": 0.0,
            # 2026-08-11: 800 → 2400. Same defect narrate.py fixed on 08-05 and
            # this call site never got: the ceiling was sized for a request that
            # disabled thinking, `thinkingConfig` was removed when the live
            # endpoint started rejecting it, and reasoning tokens now come out of
            # this budget. narrate.py needed 1400 for a sentence of prose; this
            # returns a list of full URLs, which is far longer. Both runs on
            # 08-11 died mid-object — "Expecting property name enclosed in
            # double quotes: line 7 column 1" is what a clipped array looks like
            # — and every source in the panel was lost with it.
            # Read this together with the timeout it is paired to — see
            # _VISION_URL_MAX_TOKENS.
            "maxOutputTokens": _VISION_URL_MAX_TOKENS,
            "responseMimeType": "application/json",
            "responseSchema": _VISION_URL_SCHEMA,
        },
    }

    def _sync_call():
        try:
            import requests as _req
            resp = _req.post(url, json=payload, timeout=_VISION_URL_TIMEOUT_S)
            if resp.status_code != 200:
                log(f"[{agent_key}] vision-urls http {resp.status_code}: "
                    f"{resp.text[:140]}", "WARN")
                return [], 0.0
            j = resp.json()
            _cand = (j.get("candidates") or [{}])[0]
            _finish = _cand.get("finishReason") or ""
            text = (_cand.get("content", {}).get("parts", [{}])[0]
                        .get("text", ""))
            try:
                data = json.loads(text)
            except ValueError as _je:
                # The answer was cut off, not malformed. Say which — the old
                # line reported a parse error for what was really an exhausted
                # token budget, and that reading sent the 08-11 investigation
                # after the prompt instead of the ceiling.
                _salvaged = _salvage_urls_from_truncated_json(text)
                log(f"[{agent_key}] vision-urls response was not complete JSON "
                    f"(finishReason={_finish or 'unset'}, {len(text)} chars): {_je} — "
                    f"salvaged {len(_salvaged)} whole URLs from it", "WARN")
                # A truncated object never reaches its trailing `confidence`
                # field, so there is none to read. URLs the model finished
                # writing are their own evidence that it could read the panel;
                # they still pass the scheme/domain filter below like any other.
                return _salvaged, (_VISION_URL_SALVAGE_CONFIDENCE if _salvaged else 0.0)
            return (data.get("urls") or []), float(data.get("confidence", 0) or 0)
        except Exception as e:
            log(f"[{agent_key}] vision-urls call error: {e}", "WARN")
            return [], 0.0

    try:
        raw_urls, conf = await asyncio.to_thread(_sync_call)
    except Exception as e:
        log(f"[{agent_key}] vision-urls call failed: {e}", "WARN")
        return []

    if conf < 0.4 or not raw_urls:
        return []

    # Validate + filter — drop anything that isn't a real http(s) URL or
    # references platform chrome.
    filtered = []
    seen = set()
    for u in raw_urls:
        if not isinstance(u, str):
            continue
        u = u.strip()
        if not (u.startswith("http://") or u.startswith("https://")):
            continue
        if len(u) > 500:
            continue
        if u in seen:
            continue
        if any(d in u.lower() for d in _VISION_URL_SKIP_DOMAINS):
            continue
        seen.add(u)
        filtered.append(u)
    return filtered[:_SOURCE_LIST_CAP]


# Below this, a stalled screen has nothing worth continuing with. Same figure as
# the safety-net's `_SAFETY_NET_MIN_BRIEF_LEN` extract-accept gate, deliberately:
# the two answer the same question ("is this a brief or a streaming stub?") and
# letting them drift would offer the user a salvage the extractor then rejects.
_MIN_SALVAGEABLE_BRIEF_LEN = 2000


def _state_says_brief_is_done(*, verdict: str, hard_stop_signal: bool,
                              text_len: int, flat_sec: float,
                              page_dead_reason, min_len: int,
                              window_sec: float) -> bool:
    """Is the brief finished, decided WITHOUT reading any page label?

    ⭐ 2026-08-11. This exists because the alternative rotted. ChatGPT renamed
    its finished-response header from "Thought for 1m 14s" to "Worked for 9m",
    the done-marker list had only the old literal, and a brief that was complete
    at 62492 chars polled for 40 more minutes and then waited on a human. Adding
    the new word would only have moved the expiry date.

    So when the vision read recognises NOTHING — no stop button, no finalizing
    indicator, and no phrase we know for done, which is exactly the shape a
    relabel makes — the answer comes from state this pipeline measures itself:

      * `hard_stop_signal` — the DOM's own reason for saying "generating" is a
        live Stop button rather than a residual animation. The #755 note in
        `poll_until_done` already records that every genuine success arrived via
        a lingering animation (33024 and 68349 chars) and never via a Stop
        button; it simply never acted on it.
      * `text_len` — a real brief's worth of text, not a streaming stub.
      * `flat_sec` — text AND sources AND steps all flat for the full window. A
        Deep Research run that is still working grows sources or steps even when
        text does not; that is the same multi-signal argument the 20-minute
        stall surface rests on, applied 15 minutes earlier.
      * `page_dead_reason` — a closed or `about:blank` tab has no Stop button
        either. Conflating "finished" with "gone" declared a run complete after
        3289 seconds on 2026-08-09.

    ⛔ `verdict != "ambiguous"` returns False, and that is the load-bearing
    guard, not a formality. A positively observed "still generating" is BELIEVED
    — state must never out-vote it, because the resulting false "complete"
    extracts an in-flight brief and reports "no brief generated", which is the
    strictly worse failure and the one #753 and #755 both exist to prevent.

    Extracted as a function rather than left inline because an inline condition
    can only be tested by reading the source, and a source test passes against a
    guard that has been disabled — which is how five mutants survived the first
    version of this fix."""
    if verdict != "ambiguous":
        return False
    if hard_stop_signal:
        return False
    if text_len < min_len:
        return False
    if flat_sec < window_sec:
        return False
    if page_dead_reason:
        return False
    return True


def _p1_stall_card_copy(*, contested: bool, salvageable: bool,
                        text_len: int) -> "tuple[str, str]":
    """The (title, body) for the phase-1 stall card. Two axes, four cells.

    ⭐ 2026-08-12. `poll_until_done` now raises `_BriefStreamStalled` for a
    SECOND reason, and the copy had exactly one sentence for both. The original
    reads "ChatGPT stopped updating while writing the brief" — true of a frozen
    stream, and a claim we specifically know may be FALSE of the new case, where
    the DOM detector reports a finished answer and the visual check reports a
    live Stop button. If the visual check is the one telling the truth, the page
    never stopped at all.

    The ACTIONS are identical in both (retry, or use what is on screen), which
    is exactly why the sentence has to carry the difference — a card whose words
    and whose state disagree is the failure the 2026-08-11 "Skip" relabel was
    written for, one level up.

    Extracted rather than left inline for the reason `_state_says_brief_is_done`
    records: an inline branch can only be tested by reading the source, and a
    source test passes against a branch that has been disabled.
    """
    chars = f"{int(text_len or 0):,}"
    if contested:
        if salvageable:
            return ("Couldn't confirm ChatGPT finished",
                    f"Two checks disagree about whether the brief is done — the page "
                    f"structure says finished, the visual check still sees a stop "
                    f"button. {chars} characters are on screen. Retry starts the brief "
                    f"over. Use what's on screen keeps that text and continues to the "
                    f"research phase.")
        return ("Couldn't confirm ChatGPT finished",
                "Two checks disagree about whether ChatGPT is still writing, and "
                "there isn't enough on screen to use either way. Retry starts the "
                "brief over — the run cannot continue without a brief.")
    if salvageable:
        return ("ChatGPT stopped responding",
                f"ChatGPT stopped updating while writing the brief, but {chars} "
                f"characters are already on screen. Retry starts the brief over. Use "
                f"what's on screen keeps that text and continues to the research phase.")
    return ("ChatGPT stopped responding",
            "ChatGPT stalled before producing a usable brief. Retry starts it over — "
            "the run cannot continue without a brief.")


class _BriefStreamStalled(Exception):
    """Raised by poll_until_done when ChatGPT's brief stream goes flat on
    text + sources + steps for STALL_THRESHOLD_SEC. Distinct from a wall-
    clock timeout so the P1 caller can show stall-specific copy
    ('ChatGPT stream stalled — text + sources flat for 20 min') instead
    of the legacy 'Brief generation timed out after 45 min' message.

    ⭐ `text_len` — how much brief text was on screen when the stream went
    flat. It is carried because the caller's offer to the user DEPENDS on it:
    the salvage action extracts whatever streamed, so offering it against an
    empty screen produces a 0-char brief and the false "no brief generated"
    failure. Defaults to 0, which is the safe reading (offer nothing).

    ⭐ `contested` — 2026-08-12. The SECOND way this exception is now raised:
    not "nothing moved for 20 minutes" but "the two sensors disagree and the
    disagreement did not resolve". The page has a live Stop button according to
    the vision model and no Stop button according to the DOM, on every read, for
    the whole confirm budget. The ACTIONS the caller offers are identical
    (retry, or use what is on screen) — but the copy must not be, because
    "ChatGPT stopped updating" is a false statement about a page that, if the
    vision model is the one telling the truth, is still writing. Naming the
    state honestly is the same rule the 2026-08-11 "Skip" fix was written for:
    a control whose label and behaviour disagree is worse than no control."""

    def __init__(self, message: str = "", text_len: int = 0, contested: bool = False):
        super().__init__(message)
        self.text_len = int(text_len or 0)
        self.contested = bool(contested)


def _cua_affirms(cua_text: str, key: str) -> bool:
    """Did the CUA answer YES to the question named by `key`?

    ⭐ THE ONE POLARITY PRIMITIVE. A vision answer is prose, and the only thing
    that makes a keyword evidence is an affirmation attached to it. Three
    separate hand-rolled versions of this test existed, and the loosest of them
    cost a whole production run on 2026-08-05: a P2 poll-diagnose block counted
    a bare `"progress bar" in text` as proof of generation, unconditioned by any
    answer. The CUA had written

        "No spinning ring, pulsing dot, or progress bar is visible."

    — enumerating the thing in order to DENY it — and the pipeline logged
    "✓ CUA confirms generating" three minutes after a send that never landed.
    A dead leg then ran 36 more minutes and was harvested into the report.

    So: `key` is affirmed only when a 'yes' follows it WITHIN ITS OWN CLAUSE,
    e.g. "Stop button: Yes" — NOT "Stop button: No", and NOT a 'yes' that
    answers a LATER question ("Stop button: No. Is it complete: yes").

    ⚠ Deliberately one-directional: it reads FORWARD from the key only. The
    observed CUA format answers after the label ("Stop button: Yes"), and a
    backward window would re-open the leak this closes. A phrasing that leads
    with the affirmation ("Yes, a Stop button is visible") therefore reads as
    unaffirmed — which is the safe direction for every caller here, since each
    treats an unaffirmed signal as "no evidence" rather than as a negative.
    """
    t = (cua_text or "").lower()
    i = t.find(key)
    if i == -1:
        return False
    window = t[i + len(key): i + len(key) + 30]
    for delim in (".", ",", ";", "\n", "?", "!"):
        cut = window.find(delim)
        if cut != -1:
            window = window[:cut]
    return "yes" in window


def _cua_denies(cua_text: str, key: str) -> bool:
    """Did the CUA answer NO to the question named by `key`?

    The companion to `_cua_affirms`, and it exists because affirmation alone is
    not enough for a VOLUNTEERED phrase. The CUA echoes each question before
    answering it —

        "**AI actively generating?** No — the response shows ..."

    — so a plain `"actively generating" in text` test matches the question, not
    the answer. (That is not hypothetical: it is the bug this module's own
    2026-08-05 fix introduced on its first pass, caught by the test that
    replays the incident's answer.)

    So: skip the markdown and the question mark, and read whether the answer
    OPENS with a negative. Only the answer's own opening counts — a later "no"
    belongs to a later question.
    """
    t = (cua_text or "").lower()
    i = t.find(key)
    if i == -1:
        return False
    tail = t[i + len(key): i + len(key) + 40].lstrip("?*:—- \t\n.")
    return bool(re.match(r"(no\b|not\b|none\b|nope\b|n/a\b)", tail))


# ChatGPT's thinking-time header, which renders ONLY once the model has finished
# thinking — the strongest DONE marker on the page.
#
# ⭐ 2026-08-11 — WHY THIS IS A PATTERN AND NOT A LITERAL. The done-marker list
# below was written 2026-06-02 with the single literal "thought for". ChatGPT has
# since relabelled it: the live page now reads "Worked for 9m". Nothing in this
# repo knew that string, so on 2026-08-11 a brief that was COMPLETE at 62492
# chars kept polling for 40 more minutes — the vision check read the screen
# correctly every time ("no stop button", "Worked for 9m" visible) and the
# classifier had no rule that matched, so it fell through to the ambiguous
# default and answered "generating". The run only moved when the owner pressed a
# button. (Independent corroboration that the label changed, from a day earlier:
# `queues/Worked_for_10m_32s_20260810_205153` — a run whose TITLE was scraped as
# "Worked for 10m 32s".)
#
# The time unit is REQUIRED, deliberately. Without it "worked for 3 teams" in the
# report's own prose reads as a completion marker; with it, only the header form
# matches. The verb family is small and closed on purpose — this is a page label,
# not free text, and a wider pattern would trade this bug for a false-complete,
# which is the strictly worse failure (see the cost asymmetry below).
#
# ⭐ 2026-08-12 — the pattern itself now lives at `_THINKING_TIME_HEADER_SRC`,
# shared with the four page-side JS checks. It was widened HERE on 2026-08-11 and
# nowhere else, so for a day the vision classifier and the DOM detector read the
# same page label with different vocabularies — which is what let a finished brief
# poll for 44 more minutes on 2026-08-12. One label, one pattern.
_THINKING_TIME_HEADER = re.compile(_THINKING_TIME_HEADER_SRC)


def _classify_completion_verdict(cua_text: str) -> str:
    """#753 — interpret a safety-net CUA diagnosis of whether a response is
    done. Returns "complete", "generating", or "ambiguous".

    ⭐ "ambiguous" means NO signal was found in either direction — it is not a
    reading of the screen, it is the absence of one. Callers must treat it as
    "keep waiting" (the cost asymmetry below is unchanged), but they must SAY SO
    distinctly: for two months this case was folded into "generating" and logged
    as "CUA confirms still generating", which is a claim the parser never made.
    That wording is precisely what hid the 2026-08-11 relabel — the log asserted
    a positive observation where the truth was "I recognised nothing."

    ROOT CAUSE this fixes (logs 05:05/06:31/09:10 worker-1, 05:07/06:34/09:08
    worker-2): the safety-net CUA prompt's PRIMARY directive is "if a Stop
    button is visible anywhere, say 'still generating'", and the CUA OBEYED —
    it reported `Stop button: Yes` while ChatGPT was wedged on "Finalizing
    answer". But the old inline parse checked `if "response complete" in text`
    FIRST, which matched the phrase the model echoed from the instruction (or
    used in a negated/conditional clause "I would NOT say response complete"),
    so a clearly-still-generating screen was flipped to "complete ✓" → the
    pipeline extracted an in-flight brief → 0 chars → false "no brief
    generated". (The old Stop-button fallback was also broken — it looked for
    'yes' BEFORE 'stop', but the CUA writes "Stop button: Yes".)

    Fix: generating signals (an AFFIRMED Stop button, 'finalizing', 'still
    generating', a loading indicator) WIN over a bare "response complete"
    substring, and an ambiguous read defaults to "generating". Cost asymmetry
    drives the bias — a false "complete" wrecks the run with a misleading
    failure; a false "generating" merely keeps polling (bounded by the caller's
    20-min stall surface, and the DOM detector already exits healthy
    completions without ever reaching the safety net)."""
    t = (cua_text or "").lower()

    def _affirmed(key: str) -> bool:
        # Delegates to the module-level primitive — see `_cua_affirms`. This
        # clause-scoped rule was written here first and then NOT reused by the
        # two sibling parsers, which is how the 2026-08-05 inversion survived.
        return _cua_affirms(t, key)

    generating_phrase = any(p in t for p in (
        "still generating", "finalizing", "finalising", "still processing",
        "needs click", "in progress", "still researching", "still working",
        "working on", "still loading", "still running",
        # incomplete / negated-done
        "not complete", "isn't complete", "is not complete", "incomplete",
        "hasn't finished", "has not finished", "not finished", "not yet",
        # hedges — an uncertain read must NOT count as done (cost asymmetry)
        "cannot tell", "can't tell", "can not tell", "not sure", "unsure",
        "might be", "hard to tell", "unclear",
    ))
    stop_visible = _affirmed("stop button") or _affirmed("stop:") or _affirmed("stop icon")
    loading_visible = _affirmed("loading") or _affirmed("animation") or _affirmed("spinner")
    if generating_phrase or stop_visible or loading_visible:
        return "generating"
    # Only reached when NO generating signal is present. The canonical complete
    # phrase the prompt instructs is "response complete"; the others are safe
    # declaratives. NOTE (review r2): do NOT use a bare "completed" — it matches
    # stale activity-card step labels like "completed 47 sources" / "completed
    # 3 steps" and would read as done. Require a response/render-scoped phrase.
    # "thought for X min Y sec" is ChatGPT's thinking-time summary — it renders
    # ONLY once the model has finished thinking, so (with no stop/finalizing
    # signal present, which the override above already excludes) it is a strong
    # DONE marker for the brief.
    if any(p in t for p in ("response complete", "response visible",
                            "is complete", "fully visible", "fully rendered",
                            "completed rendering", "finished rendering",
                            "done rendering", "report is complete",
                            "brief is complete", "report complete")):
        return "complete"
    # The thinking-time header, matched as a shape rather than one literal.
    # See `_THINKING_TIME_HEADER` — the literal is what rotted.
    if _THINKING_TIME_HEADER.search(t):
        return "complete"
    # Nothing recognised in either direction. Behaviourally this still means
    # "keep polling" — but it is reported as what it is, so the next label
    # change shows up as a line in the log instead of a 40-minute hang.
    return "ambiguous"


# ── The CUA verdict contract (⭐ 2026-08-12) ─────────────────────────────────
#
# WHY: every completion decision vision makes is read back out of FREE PROSE by
# `_classify_completion_verdict`, which matches ~30 substrings. That parser is
# the most-patched thing in this file and every patch has the same shape — a
# phrase that meant the opposite of what the match assumed:
#
#   * #753: "response complete" ECHOED from the instruction, and in one case
#     negated ("I would NOT say response complete"), read as done.
#   * 2026-08-05: "progress bar" inside a sentence ENUMERATING it in order to
#     DENY it ("No spinning ring, pulsing dot, or progress bar is visible"),
#     read as generation. Cost a whole production run.
#   * The hedge list still standing below: a careful, CORRECT answer — "the
#     canvas is complete, though I can't tell whether more sources load below"
#     — hits "can't tell" and reads as still generating.
#
# The common cause is not the individual keywords. It is that we ask a model to
# REASON and then recover its conclusion by sniffing the reasoning. Prose is
# where it thinks; it is not an answer channel.
#
# So the model now reasons freely and then states its conclusion on its own
# lines, in a fixed shape, and those lines are what we read. The prose parser
# stays as the FALLBACK — a model that ignores the format must still be
# understood, and every historical read in the test corpus must keep resolving
# the way it does today.
#
# ⭐ `STOP_BUTTON` is a separate field on purpose, not a detail of the verdict.
# The confirm budget's polarity rule — three positive Stop sightings against a
# DOM that says finished is a real sensor conflict, not noise — is what makes
# bounding the loop safe at all, and it was previously derived by looking for
# "yes" near the words "stop button" in prose. Under a contract that says
# "EVIDENCE: a filled-square Stop button in the composer", that search finds
# nothing. Asking for the field directly keeps the rule readable and makes it
# stronger, since "unsure" is now expressible.
_CUA_CONTRACT_BLOCK = (
    "\nFinish your reply with EXACTLY these three lines, each on its own line, "
    "nothing after them:\n"
    "VERDICT: complete | generating | unknown\n"
    "STOP_BUTTON: yes | no | unsure\n"
    "EVIDENCE: <one short line naming what you actually saw>\n"
    "Think it through first if that helps — the three lines just have to come "
    "last. Pick exactly one value on each line. 'unknown' and 'unsure' are real "
    "answers: use them rather than guessing.")

# Anchored to the START OF A LINE, and horizontal whitespace only — `\s` would
# span newlines and undo the anchoring. That anchoring is the point: an
# instruction echoed mid-sentence ("I would reply 'VERDICT: complete'") does not
# begin a line, so it cannot be mistaken for the conclusion. That exact echo is
# the #753 defect.
def _verdict_line_re(field: str, *values: str) -> "re.Pattern":
    r"""Build the reader for ONE field of a stated-conclusion contract.

    ⭐⭐ ONE READER FOR EVERY VERIFIER. Each property below is a defect this
    file has already paid for, and each was fixed in ONE reader while the
    others kept the old shape:

      * ANCHORED to the start of a line (`^` with `re.M`). An instruction
        echoed mid-sentence — "I would reply 'VERDICT: complete'" — does not
        begin a line, so it cannot be mistaken for the conclusion. That echo
        is #753.
      * HORIZONTAL whitespace only. `\s` spans newlines and would quietly
        undo the anchoring written beside it.
      * Case-insensitive, because a contract that says the value in capitals
        and a reader that matches lower case agree only by accident.

    `field` is a regex fragment, not a literal — `stop[_ -]?button` has to
    tolerate the three spellings models actually write.

    ⛔ The reader does NOT choose among matches; `_last_verdict` does, and it
    takes the LAST. A model that reasons out loud names values on the way to
    its conclusion, and the conclusion is the one it wrote last.
    """
    return re.compile(
        r"^[^\S\n]*" + field + r"[^\S\n]*[:=][^\S\n]*(" + "|".join(values) + r")\b",
        re.I | re.M)


def _last_verdict(text: str, pattern: "re.Pattern") -> str:
    r"""The last stated value for a contract field, lower-cased, or "".

    ⭐ LAST, not first — see `_verdict_line_re`. The prompts that mandate these
    lines also PRINT the whole menu of legal values above the answer, so the
    first match in a reply that quotes its instructions is the first item on
    that menu rather than anything the model decided.
    """
    hits = pattern.findall(text or "")
    return hits[-1].lower() if hits else ""


_CUA_VERDICT_LINE = _verdict_line_re("verdict", "complete", "generating", "unknown")
_CUA_STOP_LINE = _verdict_line_re("stop[_ -]?button", "yes", "no", "unsure")
# The diagnose mission states its answer under a DIFFERENT keyword and a
# different vocabulary — deliberately, because it answers a different question
# (what is on screen) than the completion verifier (is it finished).
_CUA_CONCLUSION_LINE = _verdict_line_re(
    "conclusion", "generating", "done", "needs_click", "error")


def _cua_completion_report(cua_text: str) -> dict:
    """Read a vision completion answer. Returns {verdict, stop_seen, source}.

    `verdict` uses the existing vocabulary — "complete" / "generating" /
    "ambiguous" — so callers are unchanged; the contract's "unknown" maps onto
    "ambiguous", which is what it has always meant.

    THE LAST matching line wins. A model that reasons out loud may name a
    verdict on the way to a different conclusion, and the conclusion is the one
    it wrote last. Combined with the line anchoring, that is what separates a
    decision from a deliberation.

    ⛔ A reported Stop button OVERRIDES a "complete" verdict, and that ordering
    is load-bearing, not tidiness. The cost asymmetry every note in this file
    rests on is unchanged: a false "generating" costs a poll interval, a false
    "complete" extracts an in-flight response and reports "no brief generated".
    An answer that says both is internally inconsistent, and the safe reading of
    an inconsistent answer is the cheap one.

    `source` is "contract" or "prose" so the log can say which channel decided.
    A run whose confirms are all reading "prose" means the format is being
    ignored and the fallback is carrying the feature — worth seeing before it
    becomes an incident rather than after.
    """
    t = cua_text or ""
    verdict = _last_verdict(t, _CUA_VERDICT_LINE)
    stop = _last_verdict(t, _CUA_STOP_LINE)

    if verdict:
        if verdict == "unknown":
            verdict = "ambiguous"
        source = "contract"
    else:
        # No contract line. Fall back to reading the prose exactly as before —
        # every historical answer in the test corpus must keep resolving the way
        # it does today, because that corpus IS the incident record.
        verdict = _classify_completion_verdict(t)
        source = "prose"

    if stop:
        stop_seen = (stop == "yes")
    else:
        # The pre-contract derivation, kept for the fallback path. Reads FORWARD
        # within the clause — the CUA writes "Stop button: Yes". See
        # `_cua_affirms` for the 2026-08-05 run this direction cost.
        stop_seen = (_cua_affirms(t, "stop button")
                     or _cua_affirms(t, "stop:")
                     or _cua_affirms(t, "stop icon"))

    if stop_seen and verdict != "generating":
        verdict = "generating"
    return {"verdict": verdict, "stop_seen": stop_seen, "source": source}


# The page-side half of the badge read, as a probe rather than a predicate: it
# returns WHAT it matched so the log can quote it. `_chatgpt_done_badge` below
# is the only caller.
_DONE_BADGE_PROBE_JS = """() => {
    const bl = (document.body?.innerText || '').toLowerCase();
    const m = bl.match(__DONE_BADGE_RE__);
    return m ? m[0] : "";
}""".replace("__DONE_BADGE_RE__", _THINKING_TIME_HEADER_JS)


async def _chatgpt_done_badge(page) -> str:
    """The thinking-time header ON THE PAGE, or "" when it is not there.

    ⭐ 2026-08-12 — THIS IS WHAT LETS THE PIPELINE STOP ASKING.

    `poll_until_done`'s verify-False path used to escalate to a vision confirm
    on every "the DOM says not generating" — and the vision model, given a
    prompt it could not satisfy in that layout, answered "still generating" to a
    finished brief roughly forty times over forty-four minutes. The design rule
    that got lost is that vision exists to resolve DOM UNCERTAINTY. When the
    page itself carries a positive completion trace, there is no uncertainty to
    resolve and no confirm is owed.

    The header is the right trace, and the only one used here:

      * it renders ONLY after the model has finished thinking, so it is a
        statement about this response rather than about the page furniture;
      * it lives in the HOST document even when the answer itself is inside a
        canvas or a DR sandbox frame, which is exactly the layout that made the
        text-length signals unreadable on 2026-08-12;
      * it is already the marker `_classify_completion_verdict` treats as
        conclusive when the vision model reports seeing it — so believing it
        when we can read it ourselves is not a new claim, it is the same claim
        without the round trip.

    ⛔ WHAT IS DELIBERATELY *NOT* A CORROBORATOR: "there is a lot of text on
    screen". The build plan proposed `last_seen_len >= 2000` as an alternative,
    and it is unsound in precisely the case the confirm exists for. If ChatGPT
    renames its stop-button markup the DOM detector goes blind and starts
    reporting "not generating" MID-STREAM — at which point there is plenty of
    text, and a length corroborator would skip the confirm and extract an
    in-flight brief. That is the #753 false-complete, reintroduced through the
    front door. Length says a response is BIG; only the header says it is DONE.

    ⚠ Reading the whole body means a header from an EARLIER turn in the same
    conversation can match. That staleness is bounded by the caller's
    precondition and not by this probe: it is only consulted after `verify_fn`
    has returned False twice, i.e. with no stop button, no running animation and
    no streaming attribute anywhere on the page. A second turn genuinely
    mid-flight trips at least one of those. It is the same bound the host
    detector's own badge short-circuit has always relied on.

    Returns the matched text (for the log) rather than a bool, because a line
    that says WHICH label it read is what makes the next vendor rename visible.
    """
    try:
        hit = await page.evaluate(_DONE_BADGE_PROBE_JS)
        if hit:
            return str(hit)
    except Exception:
        # A page that cannot be read is not a page that says "done". Returning
        # "" routes to the visual confirm, which is the correct fallback: no
        # corroboration means the DOM is on its own.
        return ""
    # The DR sandbox frames, for the layouts that render the answer inside one.
    # Empty for every non-ChatGPT platform, so this stays a no-op there.
    try:
        for frame in _chatgpt_surface_frame_targets(page)[1:]:
            try:
                hit = await frame.evaluate(_DONE_BADGE_PROBE_JS)
                if hit:
                    return str(hit)
            except Exception:
                continue
    except Exception:
        pass
    return ""


# ⭐ 2026-08-12 — THE PROMPT THAT COULD NOT BE ANSWERED.
#
# The mission this replaces read:
#
#   "Look at the BOTTOM of the chat (composer / end of response). Is there a
#    Stop button visible? ... If a Stop button is visible anywhere, say 'still
#    generating'. Only say 'response complete' if there is NO stop button AND
#    the final paragraph of the response is visible."
#
# Three defects, and they compound:
#
#  1. COMPLETION IS AN AND. The model must see no stop button AND the final
#     paragraph. On 2026-08-12 the answer was in a canvas with the Activity
#     panel open over it, so the final paragraph was not visible ANYWHERE on
#     screen — the right-hand branch was unsatisfiable no matter how finished
#     the response was. The model reported, accurately, that it could see
#     "Worked for 16m 26s" and no stop button, and then obeyed the instruction
#     and said "still generating".
#  2. THERE IS NO THIRD ANSWER. With only two verdicts offered, "I cannot tell"
#     has to be spelled as one of them, and the safer-sounding one is "still
#     generating" — so a failure to read the screen came back as a positive
#     observation of generation, which is the exact confusion #753 was written
#     to end on the sibling path.
#  3. IT LOOKS ONLY AT THE BOTTOM. Every completion trace ChatGPT renders —
#     the thinking-time header, a document card, a citations list — is at the
#     TOP of the response.
#
# So: completion is a DISJUNCTION of layout-independent traces, any one of
# which is sufficient; generation still OVERRIDES, because a positively
# observed Stop button is the one thing that must always win; and "cannot
# determine" is offered explicitly, named as useful, so the parser's
# "ambiguous" verdict gets used for what it means instead of arriving
# disguised as an observation.
_CONFIRM_COMPLETION_MISSION = (
    "You are checking whether ChatGPT has finished answering. The answer may be "
    "an inline message, a document/canvas card, or partly hidden behind an open "
    "'Activity' side panel — all of those are normal. Observe only; do not click "
    "anything.\n"
    "1) STILL WORKING — any ONE of these is enough: a filled-square Stop button "
    "in the composer; a 'Researching…', 'Thinking' or 'Finalizing' status; a "
    "spinner or a shimmering animated status line. If you see any of them, reply "
    "'still generating' and name what you saw and where.\n"
    "2) FINISHED — any ONE of these is enough: a time badge above the answer such "
    "as 'Thought for 1m 14s' or 'Worked for 16m 26s'; a completed document or "
    "canvas card; a sources/citations list; a composer sitting idle and ready for "
    "input. If you see any of these and nothing from (1), reply 'response "
    "complete' and name what you saw.\n"
    "3) If you can see neither — the screen is blank, obscured, or you genuinely "
    "cannot tell — reply 'cannot determine' and describe what IS on screen. Never "
    "guess: 'cannot determine' is a valid and useful answer."
    + _CUA_CONTRACT_BLOCK)


async def _page_is_dead(page):
    """Why this page can no longer be producing anything, or None if it is alive.

    "Not generating" has two causes that look identical to every DOM selector and
    to a screenshot: the answer FINISHED, or the page is GONE. The completion path
    treated them as one, and on 2026-08-09 a ChatGPT tab that had navigated to
    `about:blank` was declared complete after 3289 seconds — the visual check was
    asked to confirm and reported, accurately, that it could see no chat interface,
    no composer, no Stop button and no response. Every one of those is absent on a
    dead page and present on a finished one, and the check had no way to say so:
    anything that was not "still generating" fell through to "complete".

    So this answers the third question. It is deliberately about the PAGE and not
    the content — an empty answer is a different bug with a different fix, and
    conflating them is what produced a 55-minute run that ended in 0 chars.
    """
    try:
        if page.is_closed():
            return "the tab has been closed"
    except Exception:
        return "the tab is gone"
    try:
        url = (page.url or "").strip()
    except Exception:
        return "the tab has no address"
    # `about:blank` is the shape the live failure took. Any non-http surface gets
    # the same answer: a research agent's answer never lives on one, and every
    # platform this polls is https. Written as "must be http(s)" rather than as a
    # list of bad prefixes because the list was the bug in miniature — it named
    # `about:` and `chrome-error` and silently passed `chrome://`, `file://`,
    # `data:` and `blob:`, each of which is just as dead and none of which anyone
    # would think to add until it appeared in a log.
    if not url or not url.startswith(("http://", "https://")):
        return f"the tab is at {url or 'no address'}"
    try:
        if not await page.evaluate("() => !!(document && document.body)"):
            return "the document has no body"
    except Exception as exc:
        return f"the document cannot be read ({type(exc).__name__})"
    return None


async def poll_until_done(page, verify_fn, label, poll_interval, max_wait_min,
                          browser=None, cua_client=None, verbose=False, phase=2):
    """Poll page until response is complete. Smart: uses CUA to check if DOM selectors fail."""
    wait_start = time.time()
    paused_total = 0.0  # accumulator: time spent in wait_if_paused (pause-aware)
    consecutive_not_generating = 0
    cua_checked = False
    last_heartbeat = time.time()
    # ── ChatGPT activity-strip open state (P1 only — Phase1 / Phase1-followup) ──
    # Mirrors the per-agent dict P2 round-robin uses, scoped to this single
    # poll call. Flips _panel_open_done True on first verified open. DOM
    # misses count both "found:false" AND "clicked but verify:false". CUA
    # tier-3 capped at 1/call. The same robust helper (research.py:5048)
    # works regardless of phase — Pro+ET in P1 produces the same React-
    # rendered styled <div> strip that DR in P2 does.
    _panel_open_done = False
    _panel_dom_misses = 0
    _panel_cua_attempts = 0
    _panel_poll_cycles = 0  # ticks once per ChatGPT P1 poll while panel still closed
    _panel_reopens = 0      # #913: bounded drawer re-opens after auto-collapse (max 3)
    _last_panel_walk = 0.0  # 2026-07-13: throttle for the P1 panel WALK (live steps/links)
    # Stall detector — multi-signal (2026-04-25 strictness rewrite):
    # tracks text + sources + steps. ChatGPT DR's "researching" phase
    # legitimately produces zero text growth for 5-15 min while sources
    # and steps accumulate, so a text-only stall detector false-fired
    # during normal in-progress work. Now stall fires only when ALL
    # THREE signals flatline for 20 min (was 10 min text-only) AND the
    # detector still says "generating" — a genuinely-done response is
    # caught earlier by the verify_fn=False completion path.
    last_seen_len = 0
    last_seen_sources = 0
    last_seen_steps_sig = 0
    stall_window_start = None  # time.time() when ALL signals stopped growing
    STALL_THRESHOLD_SEC = 1200  # 20 min of multi-signal flatness → likely stuck
    # 2026-05-25: secondary safety-net CUA escalation at 5 min of flatness
    # (well before the 20 min stall-surface). The polling loop's existing
    # CUA path only fires when verify_fn returns False — if DOM detection
    # has a false-positive that keeps verify returning True forever, CUA
    # never gets asked. This safety-net triggers a visual CUA confirm
    # solely on content-flat-while-detector-says-generating. CUA can
    # override the stuck DOM read and let us extract early. Per-agent
    # gated so verify_fn != verify_chatgpt_generating skips the diagnostic
    # (other verify functions don't have a matching diag helper yet) but
    # the CUA escalation still fires. Tracked separately from cua_checked
    # so it doesn't collide with the verify-False path.
    SAFETY_NET_CUA_SEC = 300
    safety_net_cua_asked = False
    # #753: the safety-net's re-check cadence is tracked HERE, decoupled from
    # stall_window_start. A confirmed-"generating" verdict used to reset
    # stall_window_start to re-arm the safety-net — but the multi-signal stall
    # surface reads the SAME timer, so on a persistent "Finalizing answer" wedge
    # the stall window oscillated 0→300→0 and the 20-min _BriefStreamStalled
    # card never fired (the run fell through to the 60-min soft-warn instead).
    # Re-arming on this separate clock lets the safety-net re-check ~every
    # SAFETY_NET_CUA_SEC while the stall window keeps accumulating to its 20-min
    # threshold.
    _safety_net_next_check = 0.0

    # ── The visual-confirm budget (⭐ 2026-08-12) ─────────────────────────────
    # Phase 1's brief finished at t=1014s and phase 2 started 44 minutes later.
    # The DOM detector was RIGHT on every one of the ~40 reads in between. The
    # code asked the vision model to confirm each one, with a prompt it could
    # not satisfy in that layout (see `_CONFIRM_COMPLETION_MISSION`), and
    # nothing bounded the disagreement: a "still generating" answer reset the
    # DOM streak to zero and re-armed the check, so the two sensors argued at
    # roughly one call a minute until a human intervened. One call ran 10.5
    # minutes on its own.
    #
    # Nothing else in this function could have stopped it. The stall surface is
    # in the OTHER arm of this `if` and is unreachable once the DOM says done;
    # `max_wait_min` is accepted and never referenced (the outer deadline is a
    # 60-minute advisory soft-warn that does not abort); and this call site,
    # unlike its sibling at the activity-panel tier, had no timeout.
    #
    # Three bounds, each answering a different failure:
    #   * BUDGET — at most this many confirms per poll, of ANY outcome. Caps
    #     what the argument can cost.
    #   * BACKOFF — each disagreement waits longer than the last, so a genuine
    #     slow finish is still caught without paying for a tight loop.
    #   * TIMEOUT — the call itself, matching the sibling at the panel tier.
    #
    # ⛔ The budget deliberately does NOT reset when the DOM flips back to
    # "generating". That makes the ceiling a property of the whole poll — "this
    # phase spends at most three confirms" — rather than of a streak that an
    # oscillating page can restart at will, which is exactly how 44 minutes
    # accumulated. The cost of that choice is that a page which genuinely
    # resumes and then finishes gets its second completion decided by the DOM
    # alone; the DOM is the correct owner of that decision here, and the
    # safety-net twin below still covers the opposite error.
    _CUA_CONFIRM_BUDGET = 3
    _CUA_CONFIRM_BACKOFF = (60, 120, 240)
    _CUA_CONFIRM_TIMEOUT_S = 120.0
    cua_confirms_spent = 0    # confirms made on this path, whatever they returned
    cua_stop_sightings = 0    # of those, ones that POSITIVELY affirmed a Stop button

    # 2026-05-06 (Stream 2 D2): no inner wall-clock cap. The outer
    # _await_phase_with_active_deadline at the call site is the sole
    # ceiling (P1: 60m advisory soft-warn). paused_total / max_wait
    # accumulators kept as harmless dead state to preserve the function
    # signature; only the multi-signal stall detector below raises
    # _BriefStreamStalled.
    while True:
        # ── Browser-crash detection ──
        # If the underlying tab closed unexpectedly (Chromium crash, OOM,
        # user closed it, profile lock fight) every page op below will
        # raise. Emit Template A/B alert and return False so the caller
        # advances to the await_*_decision path.
        try:
            if page.is_closed():
                log(f"[{label}] Browser tab closed unexpectedly", "WARN")
                _ag_norm_crash = normalize_agent_key(label)
                # Browser crashes are always-auto: human can't do anything
                # useful here, so emit passive banner and let the outer
                # auto-retry rebuild the session. last_failure_kind tells
                # run_pipeline.finally to bypass the not-resume_dir gate.
                # #907: a fresh --login marker means the death was the login
                # command closing our Chrome — classify accordingly (no
                # auto-retry; honest card from run_pipeline's failure path).
                _runtime.last_failure_kind = ("login_interrupt"
                                              if _login_interrupt_active()
                                              else "browser_crash")
                emit_browser_recovery_status(
                    phase, agent=_ag_norm_crash if (phase == 2 and _ag_norm_crash) else None)
                return False
        except Exception:
            # is_closed() itself can throw if the page handle is already
            # garbage; treat that as a crash too.
            log(f"[{label}] Page handle invalid — treating as crash", "WARN")
            _ag_norm_crash = normalize_agent_key(label)
            _runtime.last_failure_kind = ("login_interrupt"
                                          if _login_interrupt_active()
                                          else "browser_crash")
            emit_browser_recovery_status(
                phase, agent=_ag_norm_crash if (phase == 2 and _ag_norm_crash) else None)
            return False
        # ── Stop/Pause check ──
        if _controls.is_stop():
            log(f"[{label}] STOP requested — aborting poll")
            return False
        # ── Skip checks (agent-level + phase-level) ──
        # Honor the same skip set the round-robin uses, so a user "Skip"
        # tap inside a P1 brief poll exits cleanly (poll loops historically
        # ignored skipped_agents and ran until the wall-clock cap).
        _ag_norm = normalize_agent_key(label)
        if _ag_norm and _ag_norm in (_controls.skipped_agents or set()):
            log(f"[{label}] SKIP requested for agent — aborting poll")
            return False
        if _controls.consume_phase_skip(phase):
            log(f"[{label}] SKIP requested for phase {phase} — aborting poll")
            return False
        if _controls.is_pause():
            emit_event("pipeline_paused", phase=phase)
            _pause_t0 = time.monotonic()
            await _controls.wait_if_paused()
            _this_pause = time.monotonic() - _pause_t0
            paused_total += _this_pause
            # Don't count user pause time toward stall — push the stall
            # window forward so a long pause doesn't false-fire on the
            # next post-resume tick.
            if stall_window_start is not None:
                stall_window_start += _this_pause
            if _controls.is_stop():
                log(f"[{label}] STOP after pause — aborting poll")
                return False
            # Pause+input+resume = rerun the phase from the start. Bail out so
            # the orchestrator can detect `_runtime.restart_requested` and loop.
            if _controls.peek_extra_context():
                _runtime.restart_requested = True
                log(f"[{label}] Extra context during pause — signalling phase restart")
                return False

        # ── Heartbeat every 60s so frontend knows we're alive ──
        if time.time() - last_heartbeat >= 60:
            emit_event("heartbeat", phase=phase, agent=normalize_agent_key(label))
            last_heartbeat = time.time()

        # Scrape progress FIRST — every cycle, regardless of state
        scrape_fn = SCRAPE_FNS.get(label)
        if scrape_fn:
            try:
                progress = await scrape_fn(page)
                # Hoisted from dedupe block — needed by panel-open gate below.
                elapsed_sec = int(time.time() - wait_start)

                # ── ChatGPT activity-strip open (P1 mirror of P2 round-robin) ──
                # Pro+ET sometimes does mid-thinking web searches → "Looking
                # into X… N searches" strip at bottom of chat. Same robust
                # DOM helper (walks * + dispatches full event chain — v1
                # narrow selector matched 0 candidates because the strip is
                # a styled <div>). Gate: 180s wall-clock. After 2 DOM misses
                # → CUA tier-3 (capped 1/call). Only fires for ChatGPT P1
                # entry points; Gemini/Claude have own paths.
                if label in ("Phase1", "Phase1-followup") and not _panel_open_done:
                    _panel_poll_cycles += 1
                # #913: once open, cheap per-cycle state check — the inline
                # drawer auto-collapses on some UI transitions. Bounded
                # re-open (3 max) instead of the old fire-and-forget.
                if (label in ("Phase1", "Phase1-followup") and _panel_open_done):
                    try:
                        _st_now = await _chatgpt_activity_state(page)
                        # ⛔⛔ 2026-08-19 — THIS LINE UN-LATCHED AN OPEN DRAWER. At
                        # 02:59:32, 31 seconds after CUA opened the chip row, this
                        # said "collapsed" and handed the toggle back to the
                        # opener, which then clicked it eight times. The chip row
                        # is what P1 opens, so P1 has to be able to see it.
                        if not _chatgpt_p1_activity_open(_st_now):
                            _panel_reopens += 1
                            if _panel_reopens <= 3:
                                _panel_open_done = False
                                _panel_dom_misses = 0
                                log(f"[{label}] activity drawer collapsed — will re-open "
                                    f"(reopen #{_panel_reopens}/3)", "DEBUG")
                    except Exception:
                        pass
                if (label in ("Phase1", "Phase1-followup")
                        and (_panel_poll_cycles >= 2 or elapsed_sec >= 60)
                        and not _panel_open_done):
                    try:
                        # #913 anti-toggle: the status line is a TOGGLE — the
                        # pre-#913 loop re-clicked it every cycle because the
                        # verifier's width/text gates rejected the narrow,
                        # skeleton-only Activity panel it had already opened.
                        # NEVER click while a shape is open.
                        _st_pre = await _chatgpt_activity_state(page)
                        if _chatgpt_p1_activity_open(_st_pre):
                            _panel_open_done = True
                            _shape = _chatgpt_open_shape(_st_pre)
                            log(f"[{label}] activity already open (shape={_shape}"
                                + (f", {_st_pre.get('inline_chips', 0)} chips"
                                   if _shape == "chips" else "")
                                + f") at elapsed={elapsed_sec}s — no click needed")
                            res = None
                        else:
                            res = await _open_chatgpt_activity_panel(
                                page, skip_structural=(_panel_dom_misses >= 2))
                        cands = (res or {}).get("candidates", 0)
                        if _panel_open_done:
                            pass
                        elif not res or not res.get("found"):
                            _panel_dom_misses += 1
                            log(f"[{label}] panel DOM miss #{_panel_dom_misses} "
                                f"(elapsed={elapsed_sec}s, walked_hits={cands}) — "
                                f"{_panel_miss_reason(res)}", "DEBUG")
                            if _panel_dom_misses in (2, 5):
                                await _log_chatgpt_thread_snapshot(page, tag=f"p1-miss{_panel_dom_misses}")
                        elif res.get("alreadyExpanded"):
                            _panel_open_done = True
                            log(f"[{label}] activity panel already expanded at "
                                f"elapsed={elapsed_sec}s — label: \"{res.get('label','')[:80]}\"")
                            _observe_dom_success(page, hotspot_id="7c-p1", phase=phase,
                                                 platform="chatgpt",
                                                 current_step="open_activity_panel_p1",
                                                 dom_ground_truth=_dom_gt_from_res(res))
                        elif res.get("clicked"):
                            await asyncio.sleep(2.0)
                            _st_post = await _chatgpt_activity_state(page)
                            verified = _chatgpt_p1_activity_open(_st_post)
                            if verified:
                                _panel_open_done = True
                                _shape = _chatgpt_open_shape(_st_post)
                                log(f"[{label}] activity opened via DOM at "
                                    f"elapsed={elapsed_sec}s — shape={_shape} "
                                    f"anchor={res.get('anchor', res.get('scope', '?'))} "
                                    f"clickedTag={res.get('clickedTag','?')} "
                                    f"frame={res.get('frameUrl','host')} "
                                    f"label=\"{res.get('label','')[:60]}\"")
                                _observe_dom_success(page, hotspot_id="7c-p1", phase=phase,
                                                     platform="chatgpt",
                                                     current_step="open_activity_panel_p1",
                                                     dom_ground_truth=_dom_gt_from_res(res))
                            else:
                                _panel_dom_misses += 1
                                # ⭐ THE CHIP DELTA, because "not verified" is
                                # ambiguous in the one way that matters: the press
                                # is a TOGGLE, so a miss can mean we failed to
                                # open OR that we just CLOSED what was already
                                # open. On 19 August it meant the second thing,
                                # eight times, and no line said so. Diagnostic
                                # only — a restoring click is a behaviour change
                                # and does not belong in the same wave as the fix
                                # that makes it unnecessary.
                                _cb = int(_st_pre.get("inline_chips", 0) or 0)
                                _ca = int(_st_post.get("inline_chips", 0) or 0)
                                log(f"[{label}] DOM clicked but no activity shape "
                                    f"verified — miss #{_panel_dom_misses} "
                                    f"(anchor={res.get('anchor', res.get('scope', '?'))} "
                                    f"label=\"{res.get('label','')[:60]}\" "
                                    f"chips {_cb}->{_ca}"
                                    + (" ⛔ THE PRESS CLOSED AN OPEN DRAWER"
                                       if _ca < _cb else "") + ")", "WARN")
                                if _panel_dom_misses in (2, 5):
                                    await _log_chatgpt_thread_snapshot(page, tag=f"p1-miss{_panel_dom_misses}")
                        else:
                            _panel_dom_misses += 1
                            log(f"[{label}] panel found but click failed — "
                                f"err={res.get('error','?')}", "WARN")
                    except Exception as _pe:
                        log(f"[{label}] activity panel open failed: {_pe}", "WARN")
                        _panel_dom_misses += 1

                    # CUA tier-3 escalation, retried on a miss-count schedule.
                    # See `panel_cua_should_escalate`: one flaky click used to
                    # cost the phase its entire narration while ten minutes of
                    # polling sat idle.
                    if (panel_cua_should_escalate(
                                dom_misses=_panel_dom_misses,
                                attempts=_panel_cua_attempts,
                                panel_open=_panel_open_done)
                            and cua_client and browser):
                        _panel_cua_attempts += 1
                        log(f"[{label}] DOM missed strip {_panel_dom_misses}x — "
                            f"escalating to CUA tier-3 (attempt "
                            f"{_panel_cua_attempts}/{_PANEL_CUA_MAX_ATTEMPTS}, "
                            f"elapsed={elapsed_sec}s)")
                        emit_tier_transition(phase=phase, agent="chatgpt",
                            op="open_activity_panel_p1", from_tier="dom",
                            to_tier="cua",
                            reason=f"dom_misses_{_panel_dom_misses}")
                        async def _cgpt_p1_cua():
                            return await asyncio.wait_for(
                                agent_loop(cua_client, browser,
                                    PROMPT_OPEN_CHATGPT_SOURCE_PANEL,
                                    # ⛔⛔ 2026-08-19 — REWRITTEN AGAINST THE LIVE UI.
                                    # The old text promised a right-side "Activity ·
                                    # <seconds>" panel. That panel is GONE from P1:
                                    # the press expands a row of website chips under
                                    # the line, in the conversation. CUA reported the
                                    # truth twice while the instruction said otherwise
                                    # ("An inline activity section has expanded ...
                                    # showing the source URLs", 02:59:01), so the two
                                    # verifiers disagreed about the same open drawer.
                                    # Telling the model to expect a panel that cannot
                                    # appear is an instruction to keep clicking.
                                    "Open the research activity for the latest response in "
                                    "this ChatGPT Pro/Thinking conversation: click the "
                                    "shimmering status line directly below the last sent "
                                    "message — whatever its wording, the shimmer is the "
                                    "target. ONE click only — it is a toggle. Expected "
                                    "result: a row of small website chips (favicon + "
                                    "domain, e.g. a few site names side by side, possibly "
                                    "ending in an 'N more' chip) appears INLINE directly "
                                    "under that line. If those chips are ALREADY showing, "
                                    "it is already open — do not click at all. A right-"
                                    "side panel is a valid outcome too but is not what "
                                    "this mode does any more. Never click 'Answer now', "
                                    "the X, or a chip.",
                                    model=CUA_MODEL, max_iterations=5,
                                    verbose=verbose, target_page=page),
                                timeout=120.0)
                        try:
                            cua_res = await _shadow_observed_cua(
                                page, hotspot_id="7c-p1", phase=phase, platform="chatgpt",
                                current_step="open_activity_panel_p1",
                                context_hint=f"P1 brief poll DOM 2-miss at elapsed={elapsed_sec}s",
                                expected_outcome="side panel mounts OR inline thoughts drawer expands",
                                cua_coro_factory=_cgpt_p1_cua,
                                mission_prompt=PROMPT_OPEN_CHATGPT_SOURCE_PANEL,
                                success_text="panel: open")
                            out = ((cua_res or {}).get("text") or "").lower()
                            if "panel: open" in out or "panel: already_open" in out:
                                _panel_open_done = True
                                log(f"[{label}] activity panel opened via CUA tier-3")
                            else:
                                log(f"[{label}] CUA tier-3 didn't confirm panel: {out[:120]}", "WARN")
                        except asyncio.TimeoutError:
                            log(f"[{label}] CUA tier-3 timed out after 120s", "WARN")
                        except Exception as _ce:
                            log(f"[{label}] CUA tier-3 failed: {_ce}", "WARN")

                # ── P1 activity-panel WALK (2026-07-13, user request) ──
                # The opener above gets the sources/Activity side panel open
                # within ~30s, but nothing ever READ it during P1 — the FE's
                # raw-activity drilldown stayed EMPTY until the run finished
                # (all the rich steps/links appear only at extraction time).
                # Mirror P2's Block 1c: walk the open panel every cycle
                # (throttled) and merge steps/source urls/titles into the
                # emitted progress so the panel fills LIVE as ChatGPT
                # searches — exactly the "show stuff from the source panel,
                # links etc." ask. Cheap DOM walk, no CUA.
                # 2026-07-20: run the walk on the throttle REGARDLESS of
                # _panel_open_done. scrape_chatgpt_activity_panel_tracking
                # self-guards (returns None when the panel isn't mounted /
                # mounted-but-empty), so this only ADDS scrape attempts — it
                # costs nothing when there is no panel. Since #952 clears a
                # sticky Deep Research tool, P1 now runs pure Pro + Extended
                # Thinking, whose activity surface is narrower; the opener's
                # verify gates can reject it and never flip _panel_open_done,
                # which starved the walk and left the raw-activity popup empty
                # until the run finished. Decoupling lets the walk scrape
                # whatever panel the opener managed to expand even when the
                # verify step didn't confirm it. (The opener block above still
                # keeps trying to open/expand the panel independently.)
                if (label in ("Phase1", "Phase1-followup")
                        and (time.time() - _last_panel_walk) > 45):
                    _last_panel_walk = time.time()
                    try:
                        _pd = await scrape_chatgpt_activity_panel_tracking(page)
                        if _pd:
                            for _k in ("source_urls", "steps", "sections"):
                                if _pd.get(_k):
                                    _existing = progress.get(_k, []) or []
                                    progress[_k] = list(dict.fromkeys(_existing + _pd[_k]))
                            progress["sources"] = len(progress.get("source_urls", []) or [])
                            if _pd.get("source_items"):
                                _by_url = {}
                                for _it in (progress.get("source_items") or []):
                                    if isinstance(_it, dict) and _it.get("url"):
                                        _by_url[_it["url"]] = _it
                                for _it in _pd["source_items"]:
                                    if not isinstance(_it, dict) or not _it.get("url"):
                                        continue
                                    _prev = _by_url.get(_it["url"]) or {}
                                    _title = (_it.get("title") or _prev.get("title") or "").strip()
                                    _by_url[_it["url"]] = {"url": _it["url"], "title": _title}
                                progress["source_items"] = list(_by_url.values())[:_SOURCE_LIST_CAP]
                            # ⛔ AFTER both merges, never before: the placeholder
                            # and the real page for a host arrive on different
                            # polls, so the only list that can be cleaned is the
                            # accumulated one. `sources` is recomputed here rather
                            # than above because it is the number the owner
                            # compares against ChatGPT's own "Searched N
                            # websites", and a stale count is worse than none.
                            # ⛔ The chip-host set accumulates too. A host taken
                            # from a chip on poll 2 must still be prunable on
                            # poll 12, when the panel finally yields a page on it —
                            # and a bare URL this run never saw as a chip is
                            # somebody's real homepage citation and is never touched.
                            progress["chip_hosts"] = sorted(
                                set(progress.get("chip_hosts") or [])
                                | set(_pd.get("chip_hosts") or []))
                            progress["source_urls"], progress["source_items"] = (
                                _drop_covered_host_placeholders(
                                    progress.get("source_urls") or [],
                                    progress.get("source_items") or [],
                                    progress["chip_hosts"]))
                            progress["sources"] = len(progress.get("source_urls", []) or [])
                            _ps = int(_pd.get("searches", 0) or 0)
                            if _ps > int(progress.get("searches", 0) or 0):
                                progress["searches"] = _ps
                            progress["panel_open"] = True
                            if (_pd.get("progress")
                                    and not (progress.get("progress") or "").strip()):
                                progress["progress"] = _pd["progress"]
                            if (_pd.get("source_urls") or _pd.get("steps")):
                                log(f"[{label}] panel tracking (P1): "
                                    f"{len(_pd.get('source_urls', []) or [])} URLs, "
                                    f"{len(_pd.get('steps', []) or [])} steps, "
                                    f"searches={_pd.get('searches', 0)} "
                                    # shape + chips: the 19 August phase logged
                                    # this line ZERO times in 13.7 minutes, so
                                    # when it next goes quiet the shape it was
                                    # reading has to be part of the record.
                                    f"shape={_pd.get('panel_shape', '?')} "
                                    f"chips={_pd.get('chips', 0)}")
                    except Exception as _pw:
                        log(f"[{label}] P1 panel walk failed: {_pw}", "DEBUG")

                # Enrich with MutationObserver data (token-level stream)
                _obs = get_observer_state(page)
                _obs_len = _obs.get("observer_text_len", 0) or 0
                _obs_preview = _obs.get("observer_preview", "") or ""
                # partialTextLen is max of DOM scrape + observer (observer is usually fresher)
                _merged_partial_len = max(progress.get("partial_text_len", 0) or 0, _obs_len)
                # Multi-signal stall tracking (2026-04-25): stamp time when
                # ALL signals stop growing; reset on any growth in any
                # signal. ChatGPT DR's researching phase produces no text
                # growth but sources and steps continue — text-only stall
                # detection false-fired during legit in-progress work.
                # observed_sources (Claude text count, ChatGPT vision count)
                # captures growth that URL extraction can't see. Treat as
                # liveness signal so the stall window doesn't open during
                # legit URL-light progress.
                _p1_sources = max(
                    int(progress.get("sources", 0) or 0),
                    int(progress.get("observed_sources", 0) or 0),
                )
                _p1_steps_sig = len(progress.get("steps", []) or [])
                _grew = (_merged_partial_len > last_seen_len
                         or _p1_sources > last_seen_sources
                         or _p1_steps_sig > last_seen_steps_sig)
                if _grew:
                    last_seen_len = max(last_seen_len, _merged_partial_len)
                    last_seen_sources = max(last_seen_sources, _p1_sources)
                    last_seen_steps_sig = max(last_seen_steps_sig, _p1_steps_sig)
                    stall_window_start = None
                    # Content actively growing → arm safety-net for the
                    # next flat window. Without this reset, a single CUA
                    # safety-net trigger early in the run would suppress
                    # re-checks even if a real stall hits later.
                    safety_net_cua_asked = False
                elif (_merged_partial_len > 0 or _p1_sources > 0) and stall_window_start is None:
                    stall_window_start = time.time()
                # Vision fallback merge (Gemini Flash) — fills gaps when the
                # DOM walker returns empty + provides richer narration. Cooldown
                # / budget enforced inside narrate.narrate_panel. Two
                # triggers: (a) walker is empty/ET-state past the 60s warmup,
                # or (b) every Nth poll for a fresh narration sentence even
                # when the walker IS producing data.
                _vn_steps_n = len(progress.get("steps", []) or [])
                _vn_progress_str = (progress.get("progress") or "").strip()
                _vn_sources = int(progress.get("sources", 0) or 0)
                _vn_panel_open = bool(progress.get("panel_open", False))
                # 2026-04-29: aggressive vision narration cadence. With a
                # working GEMINI_API_KEY the narrator should fire often
                # enough that the FE always has a fresh sentence. Lowered
                # the DOM-empty warmup from 60s → 20s and the panel-open
                # gate from 90s → 30s. The narrator's own MIN_GAP_S
                # (30s default) bounds the actual call frequency, so
                # these warmups just decide WHEN the first call happens.
                _vn_should_call = (
                    elapsed_sec > 20
                    and _vn_steps_n < 2
                    and _vn_sources == 0
                ) or (
                    elapsed_sec > 30 and _vn_panel_open
                )
                # Force every Nth poll so the narrator fires even when
                # DOM is producing data (keeps FE narration fresh during
                # rich-DOM windows). Default 2 (every other poll).
                _vn_force_every_n = int(os.environ.get("GEMINI_NARRATE_FORCE_EVERY_N", "2"))
                if _vn_force_every_n > 0 and elapsed_sec > 0:
                    try:
                        _poll_interval = max(int(POLL_PRO if phase == 1 else POLL_DEEP_RESEARCH), 1)
                    except Exception:
                        _poll_interval = 30
                    _poll_tick = elapsed_sec // _poll_interval
                    if _poll_tick > 0 and _poll_tick % _vn_force_every_n == 0:
                        _vn_should_call = True
                _vision_data = None
                _scrape_source = "dom"
                _vision_narration = ""
                _vision_phase_signal = ""
                if _vn_should_call:
                    try:
                        import narrate as _vn
                        _vision_data = await _vn.narrate_panel(
                            page,
                            agent=normalize_agent_key(label),
                            phase=phase,
                            workflow_name=label,
                            last_dom_progress=_vn_progress_str,
                            last_dom_sources=_vn_sources,
                            last_dom_steps_n=_vn_steps_n,
                        )
                    except Exception as _vne:
                        log(f"[{label}] narrate failed: {_vne}", "DEBUG")
                        _vision_data = None
                # Confidence floor lowered 0.4 → 0.3 (2026-04-29). The
                # narrator self-tags low-confidence reads as < 0.4 when
                # the panel is closed/empty, so 0.3 still filters the
                # totally-blank cases while accepting "partial-but-real"
                # narration the user benefits from seeing.
                if _vision_data and float(_vision_data.get("confidence", 0)) >= 0.3:
                    _scrape_source = "vision"
                    _vision_narration = _vision_data.get("narration", "")
                    _vision_phase_signal = _vision_data.get("phase_signal", "") or ""
                    _v_progress = _vision_data.get("progress", "")
                    if _v_progress and len(_v_progress) > len(_vn_progress_str):
                        progress["progress"] = _v_progress
                    _v_steps = _vision_data.get("steps") or []
                    if _v_steps:
                        _seen = set(s[:80] for s in (progress.get("steps") or []))
                        _merged = list(progress.get("steps") or [])
                        for s in _v_steps:
                            k = s[:80]
                            if k not in _seen:
                                _seen.add(k); _merged.append(s)
                        progress["steps"] = _merged[-15:]
                    if (not progress.get("sections")) and _vision_data.get("sections"):
                        progress["sections"] = _vision_data["sections"]
                    # Vision-derived source-count estimate. Kept SEPARATE from
                    # progress["sources"] (URL-derived) so the chip count and
                    # the expanded URL list never disagree. Watchdog can still
                    # see this signal via observed_sources.
                    _so = int(_vision_data.get("sources_observed") or 0)
                    if _so > 0:
                        progress["observed_sources"] = _so
                    log(f"[{label}] narrate hit: phase_signal={_vision_data.get('phase_signal')} "
                        f"conf={_vision_data.get('confidence',0):.2f} steps+={len(_v_steps)} "
                        f"narration=\"{_vision_narration[:80]}\"", "INFO")

                # Deduplicate: emit if data changed OR every 30s (elapsed_bucket).
                # Without elapsed_bucket, P1's Extended Thinking window (5-15 min
                # of zero text/source growth) would suppress every emit for the
                # whole window, leaving the FE stuck on "Opening ChatGPT…". The
                # 30s tick guarantees the dropdown narration stays alive — same
                # pattern P2's round-robin polling uses.
                # elapsed_sec hoisted to top of try block for panel-open gate.
                progress_key = json.dumps({
                    "status": progress.get("status", ""),
                    "sources": progress.get("sources", 0),
                    "partialTextLen": _merged_partial_len,
                    "sections_len": len(progress.get("sections", [])),
                    "steps_len": len(progress.get("steps", []) or []),
                    # Coarse-bucket the observer length so small bumps don't spam Firestore
                    "obs_bucket": _merged_partial_len // 200,
                    # 30s tick keeps narration live during long ET windows
                    "elapsed_bucket": elapsed_sec // 30,
                    # Vision narration changes should also break the dedupe
                    "vision_n": _vision_narration[:60] if _vision_narration else "",
                    # Without progress_label + tool_uses, transitions like
                    # "Reading source 3" → "Reading source 4" with no text-len /
                    # source delta get suppressed and starve the watchdog.
                    "progress_label": (progress.get("progress", "") or "")[:80],
                    "tool_uses_len": len(progress.get("tool_uses", []) or []),
                    # Without these, a search-count change alone (or a
                    # sectionsDone tick) gets suppressed by every other
                    # field staying constant — leaving the FE chart
                    # series flat through whole search bursts. The
                    # graphs need these deltas to draw real curves.
                    "searches": int(progress.get("searches", 0) or 0),
                    "sections_done": int(progress.get("sections_done", 0) or 0),
                    "sections_total": int(progress.get("sections_total", 0) or 0),
                    "observed_sources": int(progress.get("observed_sources", 0) or 0),
                }, sort_keys=True)
                # Phase prefix: _last_progress is process-global, so without
                # it a P1 entry could dedupe a P2 emit with the same key.
                _dedupe_key = f"p{phase}:{label}"
                if _last_progress.get(_dedupe_key) != progress_key:
                    _last_progress[_dedupe_key] = progress_key
                    expected_min = get_expected_minutes(phase)
                    # Loosen ET gate: P1 brief mode (Pro + Extended Thinking, NOT
                    # Deep Research) returns status="idle" pre-stream because
                    # scrape_progress_chatgpt has no DR signals + zero tokens.
                    # We're inside poll_until_done so by definition the agent
                    # IS working — show "Extended Thinking active" rather than
                    # the stale pre-poll string ("Opening ChatGPT…").
                    is_et = (progress.get("status") in ("generating", "idle")
                             and progress.get("sources", 0) == 0
                             and _merged_partial_len < 500)
                    if is_et:
                        # Agent-specific label: ChatGPT kept "Extended Thinking",
                        # Gemini uses "Planning" (pre-research planning step).
                        # Emitting the wrong label on Claude misleads users into
                        # thinking a deprecated setting is on — which is exactly
                        # why this is now plain "Thinking" (2026-07-30): Opus 5
                        # dropped the separate Adaptive Thinking toggle, so
                        # naming it would advertise a control that no longer
                        # exists. Effort is the reasoning lever there now.
                        _nk = normalize_agent_key(label)
                        _think_label = (
                            "Thinking" if _nk == "claude" else
                            "Planning" if _nk == "gemini" else
                            "Extended Thinking"
                        )
                        progress["status"] = "extended_thinking"
                        # Prefer vision's rich narration over the generic
                        # "<X> active" fallback when vision gave us a
                        # confident reading. Otherwise build a dynamic
                        # fallback from whatever DOM data we have so the
                        # dropdown isn't a static "Extended Thinking
                        # active" string for the entire 10-20 min ET
                        # window. Includes elapsed minutes + drafted
                        # chars when those grow — gives the user
                        # something to watch even when vision is between
                        # cooldown ticks.
                        if _vision_narration:
                            progress["progress"] = _vision_narration
                        elif (progress.get("progress") or "").strip():
                            # #913: the inline-activity sweep now scrapes the
                            # LIVE status line ("Pro thinking" → "Searching
                            # the web — <topic>…") every cycle — that beats
                            # any generic fallback. Keep it.
                            pass
                        else:
                            # Elapsed time deliberately omitted — the parent
                            # phase card already shows "N.N min elapsed" at the
                            # top of the progress bar; duplicating it on the
                            # agent narration line is just visual noise.
                            _et_parts = [f"{_think_label} active"]
                            if _merged_partial_len >= 200:
                                _et_parts.append(f"{_merged_partial_len:,} chars drafted")
                            progress["progress"] = " · ".join(_et_parts)
                    agent_key = normalize_agent_key(label)
                    # P1 milestone stepper (#924): the brief has NO research
                    # counters (it's Pro + Extended Thinking, not Deep Research)
                    # and the poll emit carried no `stage`, so the stepper sat on
                    # "Submitted" for the whole phase even while the brief was
                    # plainly generating (user-captured: stuck at Submitted 4.2m
                    # in). We're inside poll_until_done → the agent is verified
                    # generating → emit an honest stage so the stepper advances
                    # off Submitted the instant polling starts (the scrape+emit is
                    # at the top of the loop, before any sleep, so this fires ~1s
                    # after the send is confirmed). Writing once real brief text
                    # streams (matches the is_et <500-char boundary) or an outline
                    # exists. poll_until_done is P1-only, so this never touches P2.
                    _p1_stage = ""
                    if phase == 1:
                        _p1_stage = ("writing"
                                     if (_merged_partial_len >= 500
                                         or len(progress.get("sections", []) or []) > 0)
                                     else "researching")
                    emit_event("agent_progress", phase=phase, agent=agent_key,
                        status=progress.get("status", ""),
                        stage=_p1_stage,
                        progress=progress.get("progress", ""),
                        sources=progress.get("sources", 0),
                        sourceUrls=progress.get("source_urls", []),
                        # 2026-07-20: emit the titled {url,title} items too, at
                        # parity with the P2 round-robin emit (~27303). The P1
                        # panel walk above builds progress["source_items"] but
                        # this emit only ever sent bare sourceUrls, so the
                        # raw-activity popup could show hostnames but never the
                        # source TITLES during a P1 run (the FE drilldown prefers
                        # sourceItems and falls back to sourceUrls).
                        sourceItems=progress.get("source_items", []),
                        sections=progress.get("sections", []),
                        partialTextLen=_merged_partial_len,
                        partialTextPreview=_obs_preview,
                        model=progress.get("model", ""),
                        thinking=progress.get("thinking", ""),
                        steps=progress.get("steps", []),
                        plan=progress.get("plan", ""),
                        toolUses=progress.get("tool_uses", []),
                        title=progress.get("title", ""),
                        scrapeHealth="limited" if is_et else "full",
                        scrapeSource=_scrape_source,
                        visionNarration=_vision_narration,
                        phaseSignal=_vision_phase_signal,
                        panelOpen=bool(progress.get("panel_open", False)),
                        observedSources=int(progress.get("observed_sources", 0) or 0),
                        searches=int(progress.get("searches", 0) or 0),
                        elapsedSec=elapsed_sec,
                        expectedMinutes=expected_min,
                    )
                    # Append a snapshot to the per-agent history ring so
                    # post-completion graphs / sparklines have a real time
                    # series, not just end-state scalars. Capped at 240 raw
                    # entries; downsampled to 60 at finalize time.
                    try:
                        _hist = _runtime.agent_progress_history.setdefault(agent_key, [])
                        _hist.append({
                            "t": int(elapsed_sec * 1000),
                            "sources": int(progress.get("sources", 0) or 0),
                            "chars": int(_merged_partial_len or 0),
                            "sections": int(len(progress.get("sections", []) or [])),
                            "searches": int(progress.get("searches", 0) or 0),
                            "sectionsDone": int(progress.get("sections_done", 0) or 0),
                            "sectionsTotal": int(progress.get("sections_total", 0) or 0),
                        })
                        if len(_hist) > 240:
                            del _hist[:len(_hist) - 240]
                    except Exception:
                        pass
            except Exception:
                pass

        generating = await verify_fn(page)

        if not generating:
            # Is the page GONE, rather than finished? Checked here, before anything
            # downstream can read "not generating" as "done" — the visual confirm
            # below, and the final DOM double-check after it, both accept a dead
            # page otherwise, and the visual one actively argues for it (a blank
            # screen has no Stop button and no loading indicator).
            #
            # Returning False rather than raising: it is the established "abort this
            # poll, not complete" signal in this function, the caller already handles
            # it, and a dead tab is exactly the situation where the retry machinery
            # above us is the right owner.
            _dead = await _page_is_dead(page)
            if _dead:
                log(f"[{label}] the page is gone — {_dead}. Not treating this as a "
                    f"finished answer (elapsed {int(time.time() - wait_start)}s)", "ERROR")
                return False

            consecutive_not_generating += 1

            # First "not generating" could be a DOM selector issue or a
            # split-second between tokens. Drop to 2-consecutive (was 3)
            # — saves 30s of slack per phase. The DOM selectors are tight
            # post-2026-04 overhaul; false-positive risk is low. CUA is
            # still the visual fallback after 2 consecutive.
            if consecutive_not_generating <= 1:
                await asyncio.sleep(5)
                continue

            # ── ⭐ 2026-08-12: CORROBORATE, DON'T CONFIRM ─────────────────────
            # The DOM has now said "not generating" twice. Before spending a
            # visual confirm on that, ask the page whether it AGREES: the
            # thinking-time header renders only once the model has finished, and
            # it sits in the host document even when the answer itself is in a
            # canvas. When it is there, the DOM is not uncertain and there is
            # nothing for vision to resolve — which is the whole design rule
            # this restores. See `_chatgpt_done_badge`, including why "there is
            # a lot of text on screen" is deliberately NOT a corroborator.
            #
            # This alone is what takes the 2026-08-12 incident from ~40 visual
            # confirms to zero: the page was showing "Worked for 16m 26s" the
            # entire time, and the vision model kept quoting it back while
            # answering "still generating" because the prompt left it no way to
            # say anything else.
            _done_badge = await _chatgpt_done_badge(page)

            # ── The confirm budget: decide, never loop ────────────────────────
            _skip_confirm = ""
            if _done_badge:
                _skip_confirm = f"the page itself shows {_done_badge!r}"
            elif cua_confirms_spent >= _CUA_CONFIRM_BUDGET:
                # Budget spent. Which way it resolves depends on WHAT the
                # confirms actually saw — polarity, not a bare call count.
                #
                # A bare cap would silently extract in the one case this check
                # exists for: ChatGPT renames its stop-button markup, the DOM
                # detector goes blind and starts reporting "not generating"
                # mid-stream, and the vision model is the only sensor still
                # telling the truth. So a confirm that POSITIVELY affirmed a
                # Stop button every single time is not overruled — it is a real
                # sensor conflict, and the honest move is to stop and ask,
                # exactly as the stall surface does in the other arm.
                if cua_stop_sightings >= _CUA_CONFIRM_BUDGET:
                    log(f"[{label}] the DOM reports finished and the visual confirm "
                        f"reported a live Stop button on all {cua_stop_sightings} reads "
                        f"— the two sensors disagree and neither is winning. Surfacing "
                        f"for a user decision rather than guessing (text={last_seen_len})",
                        "WARN")
                    raise _BriefStreamStalled(
                        f"phase {phase} completion is contested "
                        f"(DOM says finished; {cua_stop_sightings} visual reads saw a "
                        f"live Stop button; text={last_seen_len})",
                        text_len=last_seen_len,
                        contested=True,
                    )
                _skip_confirm = (f"the visual confirm disagreed {cua_confirms_spent}× "
                                 f"without once naming a Stop button")

            if _skip_confirm and browser and cua_client:
                log(f"[{label}] DOM says not generating and {_skip_confirm} — "
                    f"no visual confirm needed "
                    f"({cua_confirms_spent}/{_CUA_CONFIRM_BUDGET} spent this poll)")

            # After 2 consecutive "not generating", with nothing corroborating
            # it and budget left — ask the vision model.
            if not _skip_confirm and not cua_checked and browser and cua_client:
                agent_key = normalize_agent_key(label)
                cua_confirms_spent += 1
                log(f"[{label}] DOM says not generating after {int(time.time() - wait_start)}s "
                    f"and no completion trace is readable on the page — scrolling + visual "
                    f"confirm {cua_confirms_spent}/{_CUA_CONFIRM_BUDGET}...")
                await browser.switch_to_page(page)
                try:
                    await page.evaluate("""() => {
                        window.scrollTo(0, document.body.scrollHeight);
                        document.querySelectorAll('[class*="react-scroll"], [class*="chat-messages"], main, [role="presentation"]')
                            .forEach(c => { try { c.scrollTop = c.scrollHeight; } catch(e){} });
                    }""")
                    await asyncio.sleep(0.4)
                except Exception:
                    pass

                async def _p1_diag_cua():
                    # ⛔ THE TIMEOUT IS NOT OPTIONAL. Its sibling at the
                    # activity-panel tier has wrapped at 120s since 2026-07; this
                    # call never did, and on 2026-08-12 one diagnosis ran 10.5
                    # minutes — a quarter of the whole stall — inside a loop that
                    # had no other ceiling.
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser, PROMPT_DIAGNOSE,
                            _CONFIRM_COMPLETION_MISSION,
                            model=CUA_MODEL, max_iterations=3, verbose=verbose),
                        timeout=_CUA_CONFIRM_TIMEOUT_S)

                # #839 act tier (read_only): the verdict phrases land in the
                # returned text for `_classify_completion_verdict` below, and
                # read_only blocks every click — so this inspector can never
                # touch the Stop button it is looking for.
                try:
                    diag = await _shadow_observed_cua(
                        page, hotspot_id="poll-diagnose", phase=phase,
                        platform=agent_key,
                        current_step="confirm_not_generating",
                        context_hint="DOM said not-generating 2× and no completion trace "
                                     "was readable on the page — say what is on screen: "
                                     "any working indicator → 'still generating'; any "
                                     "finished trace → 'response complete'; if you cannot "
                                     "tell → 'cannot determine'",
                        expected_outcome="'still generating', 'response complete', or an "
                                         "honest 'cannot determine'",
                        cua_coro_factory=_p1_diag_cua,
                        mission_prompt=PROMPT_DIAGNOSE,
                        read_only=True) or {"status": "error", "text": ""}
                except asyncio.TimeoutError:
                    diag = {"status": "error",
                            "text": f"timed out after {int(_CUA_CONFIRM_TIMEOUT_S)}s"}

                # A structural CUA failure (workspace cap, 401, 529, the timeout
                # above) returns {"status": "error", ...}, and `max_iterations`
                # returns only the LAST text block — possibly mid-reasoning
                # rather than a conclusion. Neither is a verdict, so neither is
                # parsed: keep polling and let the DOM be re-checked next tick.
                #
                # It DID consume budget, deliberately. Three failed confirms is
                # three chances to contradict the DOM that produced nothing, and
                # the old code's `cua_checked = False; continue` had no counter
                # at all — a CUA that errors every tick kept the loop alive
                # forever with no evidence on either side.
                if diag.get("status") in ("error", "max_iterations"):
                    log(f"[{label}] visual confirm unavailable "
                        f"(status={diag.get('status')}: {(diag.get('text') or '')[:80]}) — "
                        f"keeping the DOM's answer under review, "
                        f"{cua_confirms_spent}/{_CUA_CONFIRM_BUDGET} spent", "WARN")
                    cua_checked = False
                    await asyncio.sleep(poll_interval)
                    continue

                diag_text = (diag.get("text") or "")
                cua_checked = True

                # ⭐ ONE PARSER FOR BOTH TWINS. This branch used to keep its own
                # inline parse — a greedy "response complete" substring test, an
                # inverted Stop-button fallback, and an assume-complete default —
                # justified by the fact that it does not early-return. The
                # justification held; what it could not do is TELL THE
                # DIFFERENCE between "the model observed generation" and "the
                # model recognised nothing", so a screen it could not read came
                # back as a positive observation of generation, and the log said
                # "CUA says still generating" forty times about a finished brief.
                # #753's note here named routing through the hardened classifier
                # as the precondition for restructuring this block. This is that.
                _report = _cua_completion_report(diag_text)
                _verdict = _report["verdict"]
                _stop_seen = _report["stop_seen"]
                if _stop_seen:
                    cua_stop_sightings += 1

                if _verdict == "generating":
                    # ⛔ `consecutive_not_generating` is NOT reset here. Resetting
                    # it is what made this unbounded: it sent the loop back to
                    # "wait for two more DOM reads, then confirm again", forever,
                    # with the disagreement itself leaving no trace. The
                    # disagreement now has its own counter and its own ceiling.
                    cua_checked = False
                    _backoff = _CUA_CONFIRM_BACKOFF[
                        min(cua_confirms_spent, len(_CUA_CONFIRM_BACKOFF)) - 1]
                    log(f"[{label}] visual confirm disagrees — it reports generation"
                        + (" and names a live Stop button" if _stop_seen else
                           " (no Stop button named)")
                        + f" while the DOM says finished "
                          f"[{cua_confirms_spent}/{_CUA_CONFIRM_BUDGET}, "
                          f"stop sightings {cua_stop_sightings}] — "
                          f"waiting {_backoff}s before re-reading", "WARN")
                    if "needs click" in diag_text.lower():
                        async def _p1_fix_cua():
                            return await agent_loop(cua_client, browser, PROMPT_FIX_ISSUE,
                                "Click whatever button needs clicking.", model=CUA_MODEL, max_iterations=5, verbose=verbose)

                        await _shadow_observed_cua(
                            page, hotspot_id="poll-fix", phase=phase,
                            platform=agent_key,
                            current_step="click_blocking_button",
                            context_hint="diagnosis said a button needs clicking — click it. "
                                         "NEVER type or paste text",
                            expected_outcome="the blocking button is clicked and generation resumes",
                            cua_coro_factory=_p1_fix_cua,
                            mission_prompt=PROMPT_FIX_ISSUE)
                        # A short wait, not the backoff: the page was just
                        # changed, so the next read is about the click's effect.
                        await asyncio.sleep(5)
                    else:
                        await asyncio.sleep(_backoff)
                    continue

                # "complete" and "ambiguous" BOTH fall through to the DOM
                # re-verify below, and they are logged as the different
                # statements they are.
                #
                # ⚠ This is where the two twins deliberately diverge, and the
                # reason is which sensor is claiming what. In the safety net the
                # DOM says GENERATING, so an unreadable screen leaves a live
                # contradiction and "keep waiting" is the only safe reading. Here
                # the DOM says FINISHED and nothing contradicts it: "I recognised
                # nothing" is not evidence against a decision that has already
                # been made correctly, and treating it as a veto is exactly what
                # cost 44 minutes. The DOM re-verify below still has to agree
                # before this returns True.
                if _verdict == "complete":
                    log(f"[{label}] visual confirm agrees the response is complete ✓ "
                        f"(via {_report['source']})")
                else:
                    log(f"[{label}] visual confirm recognised nothing conclusive — no "
                        f"working indicator and no completion trace in its read "
                        f"(via {_report['source']}). The DOM has said finished "
                        f"{consecutive_not_generating}× and nothing contradicts it, so "
                        f"the DOM decides. This is also the shape a changed page label "
                        f"makes: text={diag_text[:200]!r}", "WARN")

            # Double-check DOM
            await asyncio.sleep(3)
            still = await verify_fn(page)
            if not still:
                elapsed = int(time.time() - wait_start)
                log(f"[{label}] Response complete ({elapsed}s)")
                return True
        else:
            consecutive_not_generating = 0
            cua_checked = False  # Reset so CUA can check again if needed

            # 2026-05-25 safety-net CUA escalation: content flat 5+ min
            # while detector says generating → most likely a DOM-detector
            # false-positive (Salaar/Kalki movie briefs hit this when
            # CSS-animation / card-progress / data-streaming-attr checks
            # match persistent post-stream-end UI chrome). Without this
            # path the loop would wait the full 20 min STALL_THRESHOLD_SEC
            # before surfacing Retry/Skip to the user — way too slow.
            # Diagnostic log captures WHICH verify check is firing so a
            # follow-up commit can fix the root cause; CUA visual confirm
            # is the immediate mitigation.
            if (browser and cua_client
                    and stall_window_start is not None
                    and (time.time() - stall_window_start) > SAFETY_NET_CUA_SEC
                    and time.time() >= _safety_net_next_check
                    and not safety_net_cua_asked):
                safety_net_cua_asked = True
                _flat_sec = int(time.time() - stall_window_start)
                # Diagnostic: log which verify path is producing the
                # false-positive. ChatGPT-only for now — other verify
                # functions don't have a matching diag helper. Doesn't
                # block the CUA call if the diag eval fails.
                _verify_fn_name = getattr(verify_fn, "__name__", "")
                _diag_reason = ""  # #755: kept in scope for the stop-button veto below
                if _verify_fn_name == "verify_chatgpt_generating":
                    try:
                        _diag_reason = await _verify_chatgpt_generating_diag(page)
                        log(f"[{label}] Safety-net diag: verify_chatgpt_generating "
                            f"true via [{_diag_reason}] "
                            f"(text={last_seen_len}, sources={last_seen_sources}, "
                            f"steps={last_seen_steps_sig}, flat={_flat_sec}s)", "INFO")
                    except Exception as _sde:
                        log(f"[{label}] Safety-net diag failed: {_sde}", "DEBUG")
                log(f"[{label}] Safety-net: content flat for {_flat_sec}s while "
                    f"detector says generating — CUA visual confirm "
                    f"(threshold={SAFETY_NET_CUA_SEC}s)", "INFO")
                await browser.switch_to_page(page)
                try:
                    await page.evaluate("""() => {
                        window.scrollTo(0, document.body.scrollHeight);
                        document.querySelectorAll('[class*="react-scroll"], [class*="chat-messages"], main, [role="presentation"]')
                            .forEach(c => { try { c.scrollTop = c.scrollHeight; } catch(e){} });
                    }""")
                    await asyncio.sleep(0.4)
                except Exception:
                    pass
                # #753 enrichment: don't decide on a single bottom-of-page
                # glance — SCROLL the latest response and weigh both negative
                # (stop/finalizing) and POSITIVE (rendered report, artifact
                # card, sources) signals. A stop button / 'Finalizing answer' /
                # loading indicator OVERRIDES everything (→ still generating),
                # so a half-rendered finalizing screen can't read as done. The
                # no-click guard is critical: this inspector must never touch
                # the Stop button (that would kill an in-flight brief).
                _sn_mission = (
                    "You are checking whether a ChatGPT Deep Research BRIEF has finished generating. "
                    "Scroll through the latest assistant response from top to bottom and observe — do NOT click anything. "
                    "FIRST look for signs it is STILL GENERATING: a Stop button (filled square) in the composer; "
                    "a 'Finalizing answer', 'Researching…', or 'Thinking' status; a loading spinner or animation. "
                    "If ANY of those are present, say exactly 'still generating' — this OVERRIDES everything else, "
                    "even if some text already looks rendered. "
                    "ONLY when NONE of those are present, look for COMPLETION TRACES: the STRONGEST is a "
                    "time badge at the TOP of the latest response, just above the research content — it reads "
                    "'Thought for 1m 14s' or 'Worked for 16m 26s' or 'Researched for 5m', and it appears ONLY "
                    "once ChatGPT has finished thinking, so scroll up to the start of the latest answer to check "
                    "for it. Other traces: a fully rendered report/brief, a document or canvas "
                    "card, a sources/citations list, a clearly-finished final paragraph. "
                    "Say exactly 'response complete' only if there is NO stop button, NO finalizing/loading indicator, "
                    "AND a finished response is visible (ideally with the 'Thought for …' header). "
                    "If you are unsure, say 'still generating'. "
                    "Remember: observe only — never click the Stop button or any control."
                    + _CUA_CONTRACT_BLOCK)

                async def _sn_diag_cua():
                    return await agent_loop(cua_client, browser, PROMPT_DIAGNOSE,
                        _sn_mission, model=CUA_MODEL, max_iterations=5, verbose=verbose)

                # #839 act tier (read_only): scroll-to-inspect is allowed for a
                # single Vision step ONLY as a verdict — read_only blocks any
                # click, so the Stop button can never be touched (#753's no-click
                # guard). Verdict phrases land in text for the parser below.
                _sn_diag = await _shadow_observed_cua(
                    page, hotspot_id="poll-diagnose", phase=phase,
                    platform=normalize_agent_key(label),
                    current_step="safety_net_completion_check",
                    context_hint="content flat 5+ min while detector says generating — "
                                 "READ the latest response: Stop/finalizing/loading → "
                                 "'still generating'; finished brief with a "
                                 "'Thought for …' / 'Worked for …' time badge → "
                                 "'response complete'; unsure → 'still generating'",
                    expected_outcome="an honest 'still generating' or 'response complete' verdict",
                    cua_coro_factory=_sn_diag_cua,
                    mission_prompt=f"{PROMPT_DIAGNOSE}\n\nTASK: {_sn_mission}",
                    read_only=True) or {"status": "error", "text": ""}
                # #753 (review r2): treat 'max_iterations' like 'error'. When
                # agent_loop exhausts its turns it returns only the LAST text
                # block — possibly mid-reasoning, not the CONCLUSION — which
                # could carry a stray 'completed'/'is complete' with no
                # generating signal and be misread as done. Skip the verdict
                # this tick and keep polling; the stall surface stays the
                # backstop. A clean read returns status='done' well under 5
                # turns, so this only guards the rare exhausted case.
                if _sn_diag.get("status") in ("error", "max_iterations"):
                    log(f"[{label}] Safety-net CUA inconclusive "
                        f"(status={_sn_diag.get('status')}: {(_sn_diag.get('text') or '')[:60]}) — "
                        f"keep polling, 20m stall surface remains the backstop", "WARN")
                    # Don't reset stall_window_start; existing stall path fires
                else:
                    _sn_text = (_sn_diag.get("text") or "")
                    # #753: a visible Stop button / 'finalizing' / loading
                    # indicator WINS over a bare "response complete" substring
                    # (which the model echoes from the prompt or negates),
                    # ambiguous → keep waiting. See _classify_completion_verdict
                    # for the full root-cause writeup — this replaced an inline
                    # parse that flipped a "Stop button: Yes" verdict to
                    # "complete" and made the pipeline extract an in-flight brief.
                    # ⭐ 2026-08-12: read the verdict CONTRACT first and fall
                    # back to the prose parser. Both twins go through the same
                    # reader for the same reason they go through the same
                    # parser — two ways of understanding one answer is the
                    # defect this whole area keeps producing.
                    _sn_verdict = _cua_completion_report(_sn_text)["verdict"]
                    _sn_is_complete = (_sn_verdict == "complete")
                    # "ambiguous" keeps polling exactly like "generating" — the
                    # cost asymmetry is unchanged — but it is NOT the same
                    # statement, and conflating them is what let a vendor label
                    # change cost 40 minutes with a log that read as healthy.
                    _sn_is_generating = _sn_verdict in ("generating", "ambiguous")
                    if _sn_verdict == "ambiguous":
                        log(f"[{label}] Safety-net CUA verdict UNRECOGNISED — no "
                            f"generating signal and no completion marker in its read. "
                            f"Treating as still-generating and continuing to poll, but "
                            f"this is the shape a changed page label makes: "
                            f"text={(_sn_text or '')[:200]!r}", "WARN")
                    # #755 — DETERMINISTIC stop-button VETO over the fuzzy CUA read.
                    # The safety-net only fires because the DOM detector is signalling
                    # "generating"; #753 hardened the CUA *text* parse, but when the
                    # CUA's text is clean-but-wrong ("looks complete, final paragraph
                    # shown") the classifier returns "complete" and we'd extract an
                    # in-flight stub. The recurring P1 false-fail (worker-1 09:00/05/10,
                    # worker-2 09:08/12:05) is ALWAYS the same shape: ChatGPT wedges on
                    # "Finalizing answer" → ~185-387 chars + a LIVE "Stop answering"
                    # composer button, and the CUA non-deterministically flips to
                    # "complete" (it said "still generating" at 09:00/09:05 on the
                    # IDENTICAL state, then "complete" at 09:10). Every genuine success
                    # carried >33K chars (06:34=33024, 12:13=68349) via a residual
                    # css_animation — NOT a stop button. So: a CUA "complete" on a
                    # response still below a real brief's floor, while the DOM detector
                    # insists it's generating, is the wedge — never a finished brief.
                    # Veto it and keep polling; the 20-min stall then surfaces the
                    # honest Retry card instead of a 0-char false "no brief". (Large
                    # content is untouched — a near-done big response that races a
                    # lingering Stop button still reads complete.)
                    _SAFETY_NET_MIN_BRIEF_LEN = 2000  # the extract accept gate; below it + DOM-generating = a streaming wedge, not a done brief
                    _hard_stop_signal = _diag_reason.startswith(("stop_composer", "card_stop", "generic_stop_label"))
                    if _sn_is_complete and last_seen_len < _SAFETY_NET_MIN_BRIEF_LEN:
                        log(f"[{label}] Safety-net: CUA read 'complete' but only "
                            f"{last_seen_len} chars (< {_SAFETY_NET_MIN_BRIEF_LEN}) while the DOM detector "
                            f"still signals generating"
                            f"{' via a live Stop button [' + _diag_reason + ']' if _hard_stop_signal else ''}"
                            f" — that's a still-streaming wedge, NOT a finished brief; "
                            f"vetoing the false-complete and continuing to poll", "WARN")
                        _sn_is_complete = False
                        _sn_is_generating = True
                    # ⭐ 2026-08-11 — LABEL-FREE COMPLETION. The counterpart to the
                    # veto above, and the reason a renamed page label can no longer
                    # cost a stall window.
                    #
                    # Reaching here with an "ambiguous" verdict means the vision
                    # model looked and recognised NOTHING — no stop button, no
                    # finalizing indicator, and no phrase we know for "done". That
                    # is exactly what a relabel looks like, and wording alone can
                    # never resolve it. So decide from state instead, using only
                    # facts this pipeline measures itself:
                    #
                    #   * the DOM's own reason for saying "generating" is SOFT — a
                    #     residual CSS animation, not a Stop button. The #755 note
                    #     above already records that every genuine success came in
                    #     this shape (33024 and 68349 chars via a lingering
                    #     animation); it just never acted on it.
                    #   * there is a real brief's worth of text, not a stub.
                    #   * text AND sources AND steps have ALL been flat for the
                    #     full safety-net window. A Deep Research run that is still
                    #     working grows sources or steps even while text doesn't —
                    #     which is the same multi-signal argument the 20-minute
                    #     stall surface is built on, applied 15 minutes earlier.
                    #   * the tab is alive, so "no stop button" means finished and
                    #     not gone (the 2026-08-09 about:blank failure, where a dead
                    #     page was declared complete after 3289s).
                    #
                    # A positively-observed "still generating" is NEVER overridden —
                    # if the model says it sees generation, it is believed. This
                    # only decides the case where nothing was recognised at all,
                    # which previously fell through to a 20-minute wait and a card.
                    # The page probe is async and costs a round trip, so it only
                    # runs in the case that can possibly qualify: nothing
                    # recognised, and no hard stop signal. `_state_says_brief_is_done`
                    # remains the single authority — it re-checks both.
                    if (not _sn_is_complete and _sn_verdict == "ambiguous"
                            and not _hard_stop_signal):
                        _lf_flat = ((time.time() - stall_window_start)
                                    if stall_window_start is not None else -1.0)
                        _lf_dead = await _page_is_dead(page)
                        if _state_says_brief_is_done(
                                verdict=_sn_verdict,
                                hard_stop_signal=_hard_stop_signal,
                                text_len=last_seen_len,
                                flat_sec=_lf_flat,
                                page_dead_reason=_lf_dead,
                                min_len=_SAFETY_NET_MIN_BRIEF_LEN,
                                window_sec=SAFETY_NET_CUA_SEC):
                            log(f"[{label}] Safety-net: no completion WORDING recognised, but "
                                f"the state says done — {last_seen_len} chars with text, sources "
                                f"and steps all flat for {int(_lf_flat)}s, no Stop button "
                                f"(DOM reason='{_diag_reason}'), page alive. Treating as "
                                f"complete without relying on any page label.", "WARN")
                            _sn_is_complete = True
                            _sn_is_generating = False
                        elif _lf_dead:
                            log(f"[{label}] Safety-net: nothing recognised and the page "
                                f"is not usable ({_lf_dead}) — NOT calling that complete", "WARN")
                    if _sn_is_complete:
                        _elapsed = int(time.time() - wait_start)
                        log(f"[{label}] Safety-net CUA confirms response complete ✓ "
                            f"({_elapsed}s) — DOM detector was the false-positive")
                        return True
                    if _sn_is_generating:
                        log(f"[{label}] "
                            + ("Safety-net CUA confirms still generating"
                               if _sn_verdict == "generating"
                               else "Safety-net CUA read nothing conclusive (see above)")
                            + " — re-arm safety-net (stall window UNTOUCHED), continue poll")
                        # #753: do NOT reset stall_window_start — the stall
                        # surface reads it, and resetting made the 20-min
                        # _BriefStreamStalled card unreachable on a persistent
                        # wedge. Re-arm the safety-net on its OWN cadence so it
                        # re-checks ~every SAFETY_NET_CUA_SEC (in case a DOM
                        # false-positive later clarifies to complete) WHILE the
                        # stall window keeps accumulating. If content actually
                        # grows, the growth-detection branch above clears
                        # stall_window_start and resets safety_net_cua_asked.
                        _safety_net_next_check = time.time() + SAFETY_NET_CUA_SEC
                        safety_net_cua_asked = False

            # Stall surface: detector still says "running" but ALL three
            # signals (text + sources + steps) stopped growing for
            # STALL_THRESHOLD_SEC. Catches the "ChatGPT alive but frozen
            # mid-stream" case proactively — raises _BriefStreamStalled
            # (Stream 2 D3) so the P1 caller can show stall-specific copy
            # distinct from a wall-clock timeout. Multi-signal makes false
            # alarms vanishingly rare: ChatGPT DR's researching phase
            # always grows sources/steps even when text doesn't.
            # (Now serves as final fallback — safety-net above should
            # catch DOM false-positives at the 5m mark.)
            if (stall_window_start is not None
                    and (time.time() - stall_window_start) > STALL_THRESHOLD_SEC):
                _stall = int(time.time() - stall_window_start)
                log(f"[{label}] Stall detected: text={last_seen_len}, "
                    f"sources={last_seen_sources}, steps={last_seen_steps_sig} — "
                    f"all flat for {_stall}s while detector says generating "
                    f"→ surfacing for user decision (Retry/Skip)", "WARN")
                raise _BriefStreamStalled(
                    f"phase {phase} response stalled "
                    f"(text={last_seen_len}, sources={last_seen_sources}, "
                    f"steps={last_seen_steps_sig}; flat for {_stall}s)",
                    text_len=last_seen_len,
                )

        elapsed_min = int(time.time() - wait_start) // 60
        log(f"[{label}] Still generating... ({elapsed_min}m elapsed)")
        await asyncio.sleep(poll_interval)


# ── Round-Robin Polling (Phase 2) ─────────────────────────────────────────────

async def _restart_phase2_agent(name: str, browser, cua_client, brief_text: str,
                                 brief_path, verbose: bool, reuse_page=None):
    """Hard-retry helper: re-run the per-agent setup for a Phase 2 agent from
    scratch (Pro/DR mode selection, brief paste, submit, verify).

    reuse_page (Gap #3, 2026-07-15): when the caller passes the agent's still-
    alive tab, the restart REUSES it (client-side New chat) instead of a cold
    top-level load — every fresh chatgpt.com/claude.ai/gemini load is a
    Cloudflare bot-score event, and a warm, challenge-passed tab avoids it.
    Forwarded straight into start_agent_no_gemini_wait; None (or a dead page)
    falls back to a fresh tab, so recovery always has a clean-slate escape.

    Mirrors the per-agent setup blocks inside `run_phase2` — kept in sync
    manually because run_phase2's setup is entangled with agent startup
    ordering (Gemini waits for Start-research button AFTER ChatGPT/Claude
    submit). For a single-agent restart, ordering doesn't matter: run the
    agent's own setup in isolation.

    Returns `(new_page, verified_bool)` or `None` on hard failure (including
    paste/setup failure where start_agent_no_gemini_wait returned ok=False)."""
    # Re-deliver user source docs on hard-retry too (read from disk so the
    # retried agent gets the same attachments the original run did).
    source_paths = _read_p2_source_paths()
    if name == "ChatGPT":
        new_page, _setup_ok = await start_agent_no_gemini_wait(
            browser, cua_client, "https://chatgpt.com",
            PROMPT_CHATGPT_DEEP_RESEARCH,
            "Enable Deep Research mode in ChatGPT. Do NOT type — just set up and focus input. Say 'ready for paste'.",
            brief_text, "2A-retry", "ChatGPT", verbose, brief_path=brief_path,
            source_paths=source_paths, reuse_page=reuse_page)
        if not _setup_ok:
            return (new_page, False)
        verified = await wait_until_verified(
            verify_chatgpt_generating, new_page, "2A-retry",
            browser=browser, cua_client=cua_client,
            max_retries=15, interval=3, verbose=verbose)
        return (new_page, verified)

    if name == "Claude":
        new_page, _setup_ok = await start_agent_no_gemini_wait(
            browser, cua_client, "https://claude.ai/new",
            # Rendered here, not imported: by the time a hard retry runs, an
            # earlier pass may already have proved this account's plan excludes
            # the primary family, and the CUA fallback must not be sent hunting
            # for it again.
            claude_deep_research_prompt(_p2_active_family("claude")),
            p2_claude_setup_directive(_p2_active_family("claude")),
            brief_text, "2B-retry", "Claude", verbose, brief_path=brief_path,
            source_paths=source_paths, reuse_page=reuse_page)
        if not _setup_ok:
            return (new_page, False)
        verified = await wait_until_verified(
            verify_claude_generating, new_page, "2B-retry",
            browser=browser, cua_client=cua_client,
            max_retries=15, interval=3, verbose=verbose)
        return (new_page, verified)

    if name == "Gemini":
        new_page, _setup_ok = await start_agent_no_gemini_wait(
            browser, cua_client, "https://gemini.google.com",
            PROMPT_GEMINI_DEEP_RESEARCH,
            "Enable Deep Research mode in Gemini. Do NOT type — just set up and focus input. Say 'ready for paste'.",
            brief_text, "2C-retry", "Gemini", verbose, brief_path=brief_path,
            source_paths=source_paths, reuse_page=reuse_page)
        if not _setup_ok:
            return (new_page, False)
        await browser.switch_to_page(new_page)
        await asyncio.sleep(2)

        # Gemini needs an extra click: wait up to 90s for "Start research"
        # button, click via JS, fall back to CUA if JS can't find it.
        # #953 (audit): use the module-hoisted, #905-hardened finder
        # (_GEMINI_CLICK_START_JS: enabled + visible + role/aria) — the old
        # inline `<button>`-only match here clicked disabled skeleton buttons
        # (a DOM no-op that reported success) and today's auto-start makes the
        # disabled Start the COMMON state on this path.
        start_clicked = False
        _auto_started = False
        for attempt in range(45):
            # Auto-start: Gemini began researching WITHOUT a Start click — the
            # plan bubble's Start stays grayed forever, so stop waiting for it.
            if await _gemini_research_started(new_page):
                _auto_started = True
                log("[2C-retry] Gemini auto-started its research (no Start click needed)", "INFO")
                break
            try:
                clicked = await new_page.evaluate(_GEMINI_CLICK_START_JS)
                if clicked:
                    start_clicked = True
                    await asyncio.sleep(5)
                    break
            except Exception:
                pass
            await asyncio.sleep(2)
        if not start_clicked and not _auto_started and cua_client:
            await browser.switch_to_page(new_page)
            # agent_loop CLICK dismisses the plan-FAIL screen; return text unused (#776).
            # #953: the mission forbids clicking a grayed/disabled Start (that
            # adds nothing and, on the auto-start layout, means research is
            # already running) — aligned with PROMPT_GEMINI_START_RESEARCH.
            await agent_loop(cua_client, browser,
                PROMPT_GEMINI_START_RESEARCH,
                "If an ENABLED (blue) 'Start research' button is visible, click it "
                "ONCE. If it is grayed/disabled or research is already running, do "
                "NOT click — say 'research already running'. Do NOT type.",
                model=CUA_MODEL, max_iterations=10, verbose=verbose)
            # #776: confirm the click via the DOM, not the CUA narration (see the
            # 2D note) — re-poll the deterministic JS after the CUA returns so a
            # post-Retry re-draft's fresh "Start research" button is actually
            # clicked, instead of inferring success from prose like "clicked retry".
            for _i in range(24):   # ~120s — covers a slow post-Retry re-draft
                if _controls.is_stop():
                    break
                if await _gemini_research_started(new_page):
                    _auto_started = True
                    break
                try:
                    _rb = await new_page.evaluate(_GEMINI_CLICK_START_JS)
                except Exception:
                    _rb = False
                if _rb:
                    start_clicked = True
                    await asyncio.sleep(5)
                    break
                await asyncio.sleep(5)

        # #776: don't let the spinner-based verify stamp a not-yet-started run as
        # researching when "Start research" was never confirmed-clicked. Returning
        # verified=False keeps the tab in the round-robin (it doesn't drop a
        # not-verified agent) so the wall-clock cap can surface an honest failure.
        # #953: an auto-started research needs no click — treat it as started so
        # the fresh retry isn't failed while it's genuinely researching.
        if _auto_started:
            log("[2C-retry] Gemini researching after auto-start — handing to round-robin", "INFO")
            return (new_page, True)
        if not start_clicked:
            # The user-retry's fresh chat ALSO failed to produce a startable plan
            # — re-raise the Retry/Skip alert immediately (close the gap where a
            # second failure silently dropped to the wall-clock cap). dedup-safe.
            if not _controls.is_stop():
                fail_agent("gemini", *_GEMINI_CANT_START)  # #63: centralized copy
            return (new_page, False)
        verified = await wait_until_verified(
            verify_gemini_generating, new_page, "2C-retry",
            browser=browser, cua_client=cua_client,
            max_retries=15, interval=3, verbose=verbose)
        return (new_page, verified)

    return None


# ── Per-Agent Extract + Record (content-first, link-second) ──────────────────
# Called by poll_all_agents_round_robin the moment detect_completion_* flips
# True for an agent. Runs the locked 2026-04 emission ladder end-to-end so the
# frontend gets the MD, the public link (or chat-URL fallback), and the
# `complete` status all together — backend and frontend stay in sync, and the
# frontend tick mark appears at the same moment the backend marks completed_set.
#
# Emission order (user-locked):
#   1. agent_progress status=extracting          (before we touch anything)
#   2. extract content → save documents/<agent>.md + Firestore mirror
#   3. attempt public Share/Publish link (short-circuited for ChatGPT iframe)
#   4. emit link_extracted { url, verified, fallback? }
#      (public if verified, else chat-URL fallback with verified=False)
#   5. agent_progress status=complete
#   Caller then does completed_set.add(agent) and clears extraction_in_progress.

async def extract_and_record_agent(name, page, browser, cua_client, queue_dir,
                                    elapsed_sec=0, verbose=False,
                                    expected_text_len=0):
    """Per-agent extract + save + emit ladder. Returns a result dict
    the caller drops into results[]. Never raises — on any internal failure
    returns status='failed' so the poll loop can decide whether to retry.

    2026-04-25: Markdown-as-primary architecture (mirrors P1).
    The moment markdown lands in Firestore, the function emits link_extracted
    (in-app /documents URL, primary=True, verified=True) + agent_progress
    complete. The in-app /documents?open=… link is the only link FE renders in
    PhaseDropdown.

    ⛔ 2026-08-28 (stretch 6.6B): share-link extraction is NOW genuinely removed
    from P2 — this docstring claimed it was on 2026-04-25 and it was not. Step 4
    and Step 4b ran three platform extractors and a CUA fallback here until
    today, and an auditor reading the old line concluded the work was done.
    Phase 5 delivers Super Research's own snapshot pages (`/shared/doc/{id}`,
    minted from the markdown in Firestore), not a platform link.

    Result dict semantics:
      url          — conversation URL (page.url) for downstream resume
      _in_app_url  — /documents?open=… for the FE primary link
      verified     — True if MD text > 0 (the in-app primary IS verified)
    """
    agent_key = name.lower().replace(" ", "")

    # Step 1 — Emit extracting so the frontend can show "Extracting…" spinner
    try:
        emit_event("agent_progress", phase=2, agent=agent_key,
                   status="extracting",
                   progress=f"Extracting {name} research content…")
    except Exception:
        pass

    # Pull the agent's tab to the foreground so extract_*_response can operate
    try:
        await browser.switch_to_page(page)
        await asyncio.sleep(1)
    except Exception as e:
        log(f"[{name}] switch_to_page failed: {e}", "WARN")

    # Step 2 — Content extraction (HTML→MD → copy button → JS → clipboard)
    extract_fn_map = {
        "ChatGPT": extract_chatgpt_response,
        "Gemini":  extract_gemini_response,
        "Claude":  extract_claude_response,
    }
    extract_fn = extract_fn_map.get(name)
    text = ""
    if extract_fn:
        try:
            # Claude: poll-loop kept artifact-1 panel open via scrape_claude_artifact_tracking
            # (commit d45807f). Pass that signal so the extractor closes-1 before clicking
            # the LAST card (which opens artifact-2, the final report). Without this hand-off,
            # the LAST-card click can no-op (artifact_count==1) or race the panel swap.
            extra_kw = {}
            if name == "Claude":
                extra_kw["artifact_panel_open"] = bool(getattr(_runtime, "claude_artifact_panel_open", False))
            text = await extract_fn(page, browser=browser, cua_client=cua_client,
                                     label=name, verbose=verbose, **extra_kw) or ""
        except Exception as e:
            log(f"[{name}] Content extraction error: {e}", "WARN")
            text = ""
        # Panel state mutated: extract_claude_response (when it ran) opened artifact-2,
        # so the polling-loop's "panel 1 is open" signal is no longer accurate. Clear
        # it so a subsequent retry/poke doesn't make scrape_claude_artifact_tracking
        # skip the click (already_open=True) and read artifact-2 into the running tracker.
        if name == "Claude":
            try:
                _runtime.claude_artifact_panel_open = False
            except Exception:
                pass
            # Length-sanity (2026-05-02): if streamed partial text accumulated
            # during round-robin was substantial AND the extracted text is
            # <30% of it, the extractor likely grabbed the wrong artifact
            # (e.g. an early summary tile). Reject and let the failed-status
            # branch fire so the caller's retry budget kicks in.
            if (text and expected_text_len >= 1000
                    and len(text) < int(0.3 * expected_text_len)):
                log(f"[{name}] Length-sanity rejection: {len(text)} chars < 30% of "
                    f"streamed {expected_text_len} chars — likely wrong artifact", "WARN")
                try:
                    emit_event("wrong_artifact_rejected", phase=2, agent="claude",
                               op="finalize_length_sanity",
                               length=len(text),
                               expected=expected_text_len,
                               tier="length_sanity")
                except Exception:
                    pass
                text = ""

    # ── Step 2a½ — 2026-08-05: is this document even about the run's topic? ──
    #
    # The last chance before the extraction becomes the run's output. Prod
    # 2026-08-05: 121KB about golden retrievers was written to
    # documents/chatgpt.md, reported `status=done`, uploaded to NotebookLM as
    # source 3-of-3, and Phase 3 began generating a Deep Dive podcast from it.
    # Zero of the topic's four distinctive words appear in it. Nothing anywhere
    # in the pipeline compared the two — a grep for off_topic/relevance/
    # topic_guard across all ~58,800 lines returned nothing.
    #
    # This sits BEFORE the write deliberately. Bolting it on where the
    # conversation URL is read further down would be too late: the markdown save
    # and the Firestore mirror both happen above that point.
    #
    # `text_is_off_topic` abstains on anything it cannot judge confidently, so
    # the failure mode here is "misses an off-topic doc", never "fails a healthy
    # run". A zero-anchor hit in a 20KB+ document has no innocent explanation.
    text = reject_off_topic_text(text, queue_dir, name, agent_key,
                                 op="finalize_topic_guard")

    n_chars = len(text)

    # Step 2b — Save MD to disk (Phase 3 input) + Firestore mirror (FE doc).
    # md_saved tracks the FIRESTORE write because that's what gates the FE's
    # `docReachable` accordion check. A successful local-only save is not
    # enough — without the subcollection write, the FE accordion would sit
    # in `isAgentSyncing` until the run ends. Retry once (transient quota /
    # network blips) before accepting the failure.
    local_saved = False
    md_saved = False
    md_content = ""
    if text and queue_dir:
        try:
            documents_dir = queue_dir / "documents"
            documents_dir.mkdir(parents=True, exist_ok=True)
            fname = agent_key + ".md"
            md_content = f"# {name} Deep Research\n\n{text}"
            (documents_dir / fname).write_text(md_content, encoding="utf-8")
            local_saved = True
            log(f"[{name}] Saved {n_chars} chars to documents/{fname}")
            # Extract real cited-source findings from the just-written
            # markdown so the FE GraphAnalysis Findings tab can render
            # rich {url, snippet, sourceTitle} cards instead of just
            # section headings. Persisted by save_meta's agents map
            # writer (research.py:~17686). Source URLs come from the
            # in-memory progress snapshot (already deduped).
            try:
                _src_urls = list(getattr(_runtime, "agent_progress_snapshots", {}).get(agent_key, {}).get("source_urls", []) or [])
                # ⛔ NO LONGER GATED ON THE PANEL LIST. `if _src_urls:` meant a
                # report full of citations produced no findings whenever the
                # panel scrape came back empty — which is most Claude runs. The
                # report is the other input now, so the only thing that can
                # make findings impossible is having no report.
                if md_content:
                    _findings = _extract_findings(md_content, _src_urls)
                    if _findings:
                        _runtime.agent_findings[agent_key] = _findings
                        _from_panel = sum(
                            1 for f in _findings if f.get("url") in set(_src_urls))
                        log(f"[{name}] Extracted {len(_findings)} cited-source "
                            f"findings (panel {_from_panel}, "
                            f"report {len(_findings) - _from_panel})")
            except Exception as _ef:
                log(f"[{name}] findings extraction failed: {_ef}", "DEBUG")
        except Exception as e:
            log(f"[{name}] Local MD save failed: {e}", "WARN")
        if local_saved:
            if _firebase_db and _fb_uid and _fb_research_id:
                # F5 (2026-05-13): 4 attempts (1s/4s/16s backoff) replaces the
                # prior 2-attempt/2s loop. Most transient Firestore blips
                # (429 / Unavailable / network flap) resolve well inside 21s.
                # Persistent failures (auth/quota/schema) still get caught and
                # the agent flips to "errored" via the failed branch below.
                md_saved = await save_document_to_firestore_with_retry(
                    agent_key, md_content, f"{name} Deep Research", label=name)
            else:
                # Unpaired / local-only run — no Firestore configured, so the
                # FE doc-reachable gate doesn't apply. Treat the local-disk
                # save as authoritative success so downstream status="done"
                # holds (preserves pre-F5 behaviour for headless runs).
                md_saved = True

    # Conversation URL — captured NOW because the page may navigate during the
    # parallel share-link worker (Gemini's Share & Export modal can redirect).
    conversation_url = ""
    try:
        conversation_url = (page.url or "") if page else ""
    except Exception:
        conversation_url = ""

    # Step 3 — Markdown-as-primary emit (P1 mirror), STRICT gate.
    # The FE flips an agent to ✓ only when it sees:
    #   (a) link_extracted with primary=true + verified=true, AND
    #   (b) the doc reachable via useResearches (subcollection sync).
    # Therefore we must NOT emit `complete` unless both _fb_research_id (so the
    # in-app URL has an anchor) AND n_chars > 0 (so a doc actually exists in
    # Firestore for the FE to find). A bare /documents URL without anchor is
    # not enough — it would let the FE flip ✓ without a real target.
    has_anchor = bool(_fb_research_id)
    _in_app_url = (f"/documents?open={_fb_research_id}:{agent_key}"
                   if has_anchor else "/documents")
    _in_app_label = f"Read {name} report"
    if n_chars > 0 and has_anchor and md_saved:
        try:
            emit_event("link_extracted", phase=2, agent=agent_key,
                       url=_in_app_url, label=_in_app_label,
                       verified=True, primary=True)
        except Exception:
            pass
        # 2026-05-03: pull the latest rich progress snapshot so the
        # completion emit carries sourceUrls / sections / steps / searches
        # alongside partialTextLen + links. Without this enrichment, the
        # FE persistence in usePipeline at phase_complete only had
        # partialTextLen to write — agents[key].sourceUrls landed empty
        # and the post-completion dropdown card showed the bare stub.
        _snap = {}
        try:
            _snap = dict(getattr(_runtime, "agent_progress_snapshots", {}).get(agent_key, {}) or {})
        except Exception:
            _snap = {}
        try:
            emit_event("agent_progress", phase=2, agent=agent_key,
                       status="complete",
                       progress=f"Content extracted: {n_chars} chars ({elapsed_sec}s)",
                       partialTextLen=n_chars,
                       elapsedSec=int(elapsed_sec or 0),
                       sourceUrls=_snap.get("source_urls", []),
                       sections=_snap.get("sections", []),
                       steps=_snap.get("steps", []),
                       searches=int(_snap.get("searches", 0) or 0),
                       observedSources=int(_snap.get("observed_sources", 0) or 0),
                       sources=max(int(_snap.get("sources", 0) or 0),
                                   len(_snap.get("source_urls", []) or [])),
                       links=[{"label": _in_app_label, "url": _in_app_url,
                               "verified": True, "primary": True}])
        except Exception:
            pass
        # F4 (2026-05-06): persist agent terminal status to root doc on
        # the individual complete-emit instead of waiting for the bulk
        # phase_complete write at :19641. On chat reopen mid-Phase-2,
        # an agent that finished early (e.g. ChatGPT done while Claude
        # is still researching) should already show as 100% complete in
        # research.agents[k].status — pre-fix, only the message bucket
        # carried the done state, and reopen rebuilt the bucket from
        # Firestore which lacked the runtime status until phase_complete
        # bulk-flushed all three. Idempotent with the bulk write — same
        # field, same value. FE companion at usePipeline.ts agent_progress
        # handler also writes this client-side for redundancy.
        try:
            _write_agent_terminal_status(agent_key, "complete")
        except Exception:
            pass
        # #953 (2026-07-13 run): a completed agent must never keep a stale
        # failure card. Gemini finished at 98k chars while the earlier (false)
        # "couldn't start" card was still up — nothing retracted it, the user
        # pressed its Retry, and the retry destroyed the completed agent. If
        # fail_agent ever carded this agent (monotonic stamp in
        # _AGENT_ERROR_CARD_TS, #950), retract the card + its durable
        # pendingDecision now that the report is recorded — same emit shape as
        # the #921 plan-alert retraction.
        if _AGENT_ERROR_CARD_TS.get(agent_key):
            try:
                emit_event("pipeline_warning", phase=2, agent=agent_key,
                           error=f"{name} finished — earlier alert cleared",
                           details=f"{name} completed its research ({n_chars} chars extracted); "
                                   "the earlier failure alert is stale.",
                           actions=[], alert_id=_agent_error_alert_id(agent_key, 2),
                           auto_clear_on_resume=True)
                _clear_pending_decision(agent_key)
                _AGENT_ERROR_CARD_TS.pop(agent_key, None)
                log(f"[{name}] Retracted the stale failure card — agent completed")
            except Exception:
                pass
    else:
        # No content extracted OR no anchor OR Firestore write failed — emit
        # failed (FE keeps spinner, never flips ✓ without a reachable doc).
        _why = ("0 chars" if n_chars <= 0
                else "no research anchor (_fb_research_id missing)" if not has_anchor
                else "Firestore document sync failed after retry — FE doc-reachable would never flip")
        # ⛔⛔ 2026-08-29 — THE SOURCES RIDE ALONG NOW. The completion emit a few
        # lines above carries `sourceUrls` / `sources` off the same snapshot and
        # this one carried three keys and none of them. So an agent that gathered
        # sources for forty minutes and then failed to hand over its text sent the
        # UI nothing to show, and the dead-agent card was empty even DURING the
        # run — before the reload that also loses them. Owner, 2026-08-29: "if
        # there are sources, let the narration show the sources and stuff."
        try:
            _fail_snap = dict(getattr(_runtime, "agent_progress_snapshots", {}).get(agent_key, {}) or {})
        except Exception:
            _fail_snap = {}
        _fail_urls = list(_fail_snap.get("source_urls", []) or [])[:_SOURCE_LIST_CAP]
        try:
            emit_event("agent_progress", phase=2, agent=agent_key,
                       status="failed",
                       progress=f"Content extraction failed — {_why} ({elapsed_sec}s)",
                       partialTextLen=max(int(n_chars), 0),
                       sourceUrls=_fail_urls,
                       # ⛔ THE LARGER OF THE TWO, the same way the completion emit
                       # does it: the counter and the url list are gathered by
                       # different readers and either can be the fuller one.
                       sources=max(int(_fail_snap.get("sources", 0) or 0), len(_fail_urls)),
                       searches=int(_fail_snap.get("searches", 0) or 0),
                       observedSources=int(_fail_snap.get("observed_sources", 0) or 0),
                       elapsedSec=int(elapsed_sec or 0))
        except Exception:
            pass
        # F5 (2026-05-13): persist terminal "errored" on the root doc so
        # post-reload tile/icon state shows the red badge instead of the
        # last running snapshot. Mirrors fail_agent's behaviour at 7403.
        # Idempotent with any user-initiated Retry path (retry writes
        # "running"; subsequent success/failure overwrites this).
        try:
            _write_agent_terminal_status(agent_key, "errored")
        except Exception:
            pass

    # F5 (2026-05-13): status="done" now requires `md_saved=True`. Prior
    # gate was `n_chars > 0` alone, which let Firestore-sync-failed agents
    # report status="done" in the Phase 2 summary log while the FE
    # doc-reachable gate sat unflipped (because the subcollection write
    # never landed). Phase 2 finalize consumers (done_count, terminal-status
    # backstop, _p2_links builder) all read this status — keeping them in
    # sync with what the FE actually sees prevents the worst-of-both-worlds
    # "log says done, FE says spinner" state inconsistency.
    return {
        "status": "done" if (n_chars > 0 and md_saved) else "failed",
        "text": text,
        "url": conversation_url,        # conversation URL — for resume reconnect
        "_in_app_url": _in_app_url,     # in-app /documents primary — FE link
        "verified": (n_chars > 0 and md_saved),
        "page": page,
        "elapsed_sec": int(elapsed_sec or 0),
        "md_saved": md_saved,
    }


async def _spotlight_latest_response(page, agent_name: str):
    """A4 (2026-05-01): briefly select the latest response paragraph via
    DOM Range API so the user can SEE which agent the round-robin is
    currently polling. Symmetric across ChatGPT/Gemini/Claude — no CUA
    cost, no screenshot, no click. Auto-clears after 900ms so the user's
    own selection isn't held hostage. Failures are silent (visual cue
    is non-essential — polling/scraping is what actually matters).
    """
    if not page:
        return
    # Per-platform selectors for the response container. Walk last→first
    # and pick the first on-screen match. Fallback: any visible <article>
    # or <p> chunk so the spotlight still flashes if selectors drift.
    sel_map = {
        "ChatGPT": (
            '[data-message-author-role="assistant"] .markdown, '
            '[data-message-author-role="assistant"], '
            '[data-testid^="conversation-turn"] .markdown, '
            'main article'
        ),
        "Gemini": (
            'message-content, '
            '.response-content, '
            '.markdown-main-panel, '
            'model-response, '
            'main .markdown'
        ),
        "Claude": (
            '[data-test-render-count] .font-claude-message, '
            '.font-claude-message, '
            '[data-testid="user-message"] ~ * .prose, '
            '.prose, '
            'main article'
        ),
    }
    css = sel_map.get(agent_name, "main article, main .markdown, p")
    try:
        await page.evaluate(
            """(css) => {
                try {
                    const els = Array.from(document.querySelectorAll(css));
                    if (!els.length) return false;
                    // pick the LAST visible-on-screen element so we spotlight
                    // the freshest paragraph, not the user's prompt at top.
                    let target = null;
                    for (let i = els.length - 1; i >= 0; i--) {
                        const r = els[i].getBoundingClientRect();
                        if (r.height > 18 && r.bottom > 0
                                && r.top < (window.innerHeight + 200)) {
                            target = els[i]; break;
                        }
                    }
                    target = target || els[els.length - 1];
                    const range = document.createRange();
                    range.selectNodeContents(target);
                    const s = window.getSelection();
                    if (!s) return false;
                    s.removeAllRanges();
                    s.addRange(range);
                    setTimeout(() => {
                        try { window.getSelection()?.removeAllRanges(); }
                        catch (_) {}
                    }, 900);
                    return true;
                } catch (_) { return false; }
            }""",
            css,
        )
    except Exception:
        pass


# ── Claude clarification-question detector (2026-05-18) ──────────────────────
# When the user submits a vague / template brief, Claude responds with a chat
# message asking clarifying questions INSTEAD of starting Deep Research.
# Without the auto-reply below, the BE waits for an artifact that never
# appears and surfaces a generic "Hit a snag" alert at the wall-clock cap,
# requiring the operator to manually type a defer message into the Claude tab.
#
# Sign-off pattern: Claude's clarification responses consistently end with a
# variant of "Once you {clarify|confirm|...}, I'll {launch|start|...} the
# research" — that exact structure is the gating signal here (5th condition
# alongside elapsed window, not-generating, no-artifact, short-text-with-?s).
# Mid-research statements like "I'll start with the analysis of X" don't
# match because they lack the "once you" / "let me know" / "with those"
# clarification-pending opener.
_CLAUDE_CLARIFICATION_SIGNOFF_RE = re.compile(
    r"(?:once\s+(?:you\s+)?(?:clarify|confirm|share|provide|specify|tell\s+me|answer)|"
    r"let\s+me\s+know|"
    r"with\s+(?:those|that|these)\s+(?:answers|details|specifics|clarifications))"
    r"[^.!?]{0,180}"
    r"(?:I[''’]?ll|I\s+will)\s+(?:launch|start|begin|dive|jump|kick\s+off|get\s+started)"
    r"[^.!?]{0,80}"
    r"research",
    re.IGNORECASE | re.DOTALL,
)


async def _claude_asking_clarification(page):
    """Lightweight DOM read of the last assistant message + sign-off regex
    match. Does NOT touch clipboard or open artifact panels (cheaper than
    extract_claude_response — safe to call every round-robin tick).

    Returns (matched: bool, last_text: str, q_count: int)."""
    try:
        last_text = await page.evaluate("""() => {
            const candidates = [
                '.font-claude-message',
                '[data-message-author-role="assistant"]',
                '.contents .prose',
            ];
            for (const sel of candidates) {
                const all = document.querySelectorAll(sel);
                if (all.length > 0) {
                    const last = all[all.length - 1];
                    const t = (last.innerText || last.textContent || "").trim();
                    if (t.length > 30) return t;
                }
            }
            return "";
        }""")
    except Exception:
        return False, "", 0
    if not last_text:
        return False, "", 0
    q_count = last_text.count("?")
    # Sign-off lives in the tail — match on last 600 chars so a mid-message
    # "I'll start with..." aside doesn't false-positive.
    tail = last_text[-600:] if len(last_text) > 600 else last_text
    matched = bool(_CLAUDE_CLARIFICATION_SIGNOFF_RE.search(tail))
    return matched, last_text, q_count


async def _claude_send_clarification_reply(page, label):
    """Type the defer-to-Claude reply into the chat input, then submit.

    Submit strategy: try the Send button first (matches paste_followup at
    research.py:5170), fall back to Enter if no enabled button is found.
    Send-button-first protects against future Claude composer A/B tests
    that might bind Enter to newline (Shift+Enter→Enter swap pattern).

    Returns True on send, False if no composer was reachable."""
    reply = "Up to Claude to decide for the best output."
    typed_into = None
    for sel in ('div[contenteditable="true"]', '.ProseMirror', 'textarea', '[role="textbox"]'):
        try:
            inp = await page.query_selector(sel)
            if not inp:
                continue
            await inp.click()
            await asyncio.sleep(0.3)
            await page.keyboard.type(reply, delay=10)
            await asyncio.sleep(0.4)
            typed_into = sel
            break
        except Exception as _te:
            log(f"[{label}] Clarification type attempt on {sel} failed: {_te}", "DEBUG")
            continue
    if typed_into is None:
        log(f"[{label}] No composer found for clarification reply", "WARN")
        return False
    # Send-button-first (mirror paste_followup pattern at research.py:5170).
    for sel in (
        'button[data-testid="send-button"]',
        'button[aria-label="Send prompt"]',
        'button[aria-label="Send"]',
        'button[aria-label="Send message"]',
        'button[aria-label="Submit"]',
    ):
        try:
            btn = await page.query_selector(sel)
            if btn and await btn.is_enabled():
                await btn.click()
                log(f"[{label}] Sent clarification-defer reply via {sel}: {reply!r}", "INFO")
                return True
        except Exception:
            continue
    # Enter fallback.
    try:
        await page.keyboard.press("Enter")
        log(f"[{label}] Sent clarification-defer reply via Enter: {reply!r}", "INFO")
        return True
    except Exception as _ee:
        log(f"[{label}] Clarification reply Enter-fallback failed: {_ee}", "WARN")
        return False


# ── Claude interactive question card → click Skip (#953, 2026-07-13) ─────────
# Claude (Opus 4.8 research flow) can reply to the brief with an INTERACTIVE
# question card instead of (or before) starting research: a "1 of N" pager, a
# stack of numbered option rows, a pencil "Something else" free-text row, and a
# "Skip" button bottom-right (user screenshot 2026-07-13 18:37). Research does
# NOT start until the questions are answered or skipped. The 2026-05-18
# text-regex clarification path (above) can't see this card — the card question
# carries ONE '?' (detector demands ≥2) and no sign-off sentence — and its
# defer-reply types text, while the card's first-class dismissal is the Skip
# button. USER DIRECTIVE: "we just click skip for all questions so the research
# starts."
#
# Detection is deliberately conservative — a visible, enabled button whose
# exact text is "Skip", inside a container that ALSO shows a question-card
# signature ("N of M" pager, numbered option rows, or the "Something else"
# row). A bare "Skip" anywhere else (e.g. report prose) never matches.
# One click per call; the caller loops (each Skip advances the pager to the
# next question or dismisses the card and the research launches).
# Probe/click the card. Takes a `doClick` arg: false = read-only probe
# (returns {present, pager}); true = also click the Skip button. Splitting
# probe from click lets the caller EFFECT-VERIFY (audit #953-2): a click that
# doesn't advance the card (untrusted .click() the handler ignores, or a
# re-render with the same question) must NOT be counted — else the round-robin
# leg re-skips + rebases the wall-clock every tick forever, starving the
# completion/timeout backstops (silent phase-2 hang).
_CLAUDE_QUESTION_CARD_JS = r"""(doClick) => {
    const norm = s => (s || '').replace(/\s+/g, ' ').trim();
    const out = { present: false, clicked: false, pager: '' };
    for (const btn of document.querySelectorAll('button, [role="button"]')) {
        if (!btn.offsetParent) continue;
        if (norm(btn.textContent).toLowerCase() !== 'skip') continue;
        if (btn.disabled || btn.getAttribute('aria-disabled') === 'true') continue;
        // Walk up looking for the question-card container signature.
        let card = btn.parentElement;
        for (let i = 0; i < 8 && card; i++, card = card.parentElement) {
            const txt = norm(card.innerText || '');
            // #953-7: the real card (pager + a few option rows + Skip) is
            // compact. Once the ancestor's text exceeds ~1500 chars we've
            // climbed into page prose — stop MATCHING here so a report that
            // happens to contain "N of M"/"something else" can't bind a Skip.
            if (txt.length > 1500) break;
            const pager = txt.match(/\b(\d+)\s+of\s+(\d+)\b/);
            const somethingElse = /something else/i.test(txt);
            let optionRows = 0;
            for (const row of card.querySelectorAll('button, [role="button"], [role="option"], li')) {
                const rt = norm(row.textContent);
                if (/^\d{1,2}\s+\S/.test(rt) && rt.length > 8) optionRows++;
            }
            if (pager || somethingElse || optionRows >= 2) {
                out.present = true;
                out.pager = pager ? pager[0] : '';
                if (doClick) { btn.click(); out.clicked = true; }
                return out;
            }
        }
    }
    return out;
}"""


async def _claude_skip_question_cards(page, label, max_skips=6) -> int:
    """Click Skip on Claude's interactive question card(s) until none remain.

    EFFECT-VERIFIED (audit #953-2): probe → click → settle → re-probe, and
    count a skip ONLY when the card actually changed (gone, or its pager
    advanced). A click that leaves the SAME card+pager on screen is treated as
    ineffective — break immediately so an unadvanceable Skip never drives the
    caller's rebase-and-continue loop. Returns the number of EFFECTIVE skips
    (0 = no card, or a card the click couldn't move). Fail-safe throughout."""
    _skips = 0
    for _ in range(max_skips):
        try:
            before = await page.evaluate(_CLAUDE_QUESTION_CARD_JS, False)
        except Exception as _qe:
            log(f"[{label}] Question-card probe failed ({_qe})", "DEBUG")
            break
        if not before or not before.get("present"):
            break
        try:
            await page.evaluate(_CLAUDE_QUESTION_CARD_JS, True)   # click Skip
        except Exception as _ce:
            log(f"[{label}] Question-card Skip click failed ({_ce})", "DEBUG")
            break
        await asyncio.sleep(1.5)
        try:
            after = await page.evaluate(_CLAUDE_QUESTION_CARD_JS, False)
        except Exception:
            after = {"present": False}
        # Effective iff the card is gone OR the pager advanced.
        if after.get("present") and after.get("pager") == before.get("pager"):
            log(f"[{label}] Skip click didn't advance the card "
                f"({before.get('pager') or 'no pager'}) — stopping (ineffective)", "INFO")
            break
        _skips += 1
        log(f"[{label}] Clarifying-question card ({before.get('pager') or 'no pager'}) "
            f"— Skip #{_skips} took effect", "INFO")
    if _skips:
        log(f"[{label}] Skipped {_skips} clarifying question(s) — research can start", "INFO")
    return _skips


# ─────────────────────────────────────────────────────────────────────
# Gemini Deep Research — kickoff-stall detection
# ─────────────────────────────────────────────────────────────────────
#
# Failure mode (observed in production 2026-05-22 — user screenshot):
# After "Start research" is sent, Gemini sometimes ACKs with "OK,
# starting now. As soon as your report is ready, I'll let you know"
# but never actually kicks off — the canonical "Researching N sources"
# card never appears and the run silently stalls. A single polite
# follow-up nudge reliably re-triggers the kickoff (the user
# previously unblocked these stalls by typing "Done?" which produced
# the same "I'm on it" → card-appears sequence).
#
# Mirrors the Claude clarification block above (research.py:16179):
# regex + lightweight DOM probe + one-shot nudge + state reset.

# ACK patterns Gemini emits after "Start research" — confirm Gemini
# DID respond. Anchored on phrases unique to the start-ack UX
# ("starting now", "let you know when", "feel free to leave this
# chat", "I'm on it"). Permissive — any ACK variant should match.
_GEMINI_KICKOFF_ACK_RE = re.compile(
    r"(starting\s+now|"
    r"let\s+you\s+know\s+when|"
    r"feel\s+free\s+to\s+leave\s+this\s+chat|"
    r"i[''’]?m\s+on\s+it)",
    re.IGNORECASE,
)

# Canonical "research is actually running" card text. Gemini Deep
# Research renders varying card text while the worker scrapes:
#   - "Researching 25 sources..." (numbered count — Golden Retrievers run)
#   - "Researching websites..." (no number — Salaar Part 2 run 2026-05-24)
#   - "Researching N searches..." / "Researching N sites..." (variants)
# Match any of these to suppress the nudge once kickoff succeeded.
# Mirrors the noun list in scrape_progress_gemini at research.py:~12054
# (`websites?|sources?|searches?|sites?`).
_GEMINI_RESEARCH_CARD_RE = re.compile(
    r"researching\s+(?:\d+\s+)?(?:websites?|sources?|searches?|sites?)",
    re.IGNORECASE,
)

# Completion message Gemini emits when the report is ready — same
# pattern as the in-app "research complete" banner. Suppresses the
# nudge if the report already arrived between ticks.
_GEMINI_COMPLETION_RE = re.compile(
    r"(completed\s+your\s+research|"
    r"feel\s+free\s+to\s+ask\s+me\s+follow[\s-]?up)",
    re.IGNORECASE,
)

# #897a (2026-07-04): the periodic-reload recovery subsystem
# (_GEMINI_CONVERSATION_PRESENT_JS / _gemini_conversation_id /
# _gemini_conversation_present / _gemini_reopen_from_sidebar /
# _gemini_recover_if_empty) was deleted along with the reload itself —
# Gemini is never reloaded mid-run anymore, so there is nothing to recover.


async def _gemini_kickoff_pending(page):
    """Lightweight DOM probe: did Gemini ACK without actually starting?

    Returns (pending: bool, reason: str). pending=True iff:
      - ACK pattern matches somewhere in page innerText (Gemini DID respond)
      - "Researching N sources" card is NOT visible (research has NOT started)
      - Completion pattern is NOT visible (research is not already done)

    Safe to call every round-robin tick — reads first 8000 chars of
    body innerText only.
    """
    try:
        body = await page.evaluate("""() => (document.body.innerText || "").slice(0, 8000)""")
    except Exception:
        return False, "evaluate-failed"
    if not body:
        return False, "empty-body"
    if _GEMINI_COMPLETION_RE.search(body):
        return False, "completion-present"
    if _GEMINI_RESEARCH_CARD_RE.search(body):
        return False, "card-present"
    if not _GEMINI_KICKOFF_ACK_RE.search(body):
        return False, "no-ack-yet"
    return True, "ack-no-card"


async def _gemini_research_started(page) -> bool:
    """True when Gemini's DEEP RESEARCH has genuinely started or finished.

    #953: research-SPECIFIC evidence — the "Researching N websites/sources"
    card or the completion line. verify_gemini_generating CANNOT be used for
    this: it green-lights on ANY stop button / running CSS animation, which a
    plan still DRAFTING also shows, so it can't tell a drafting plan from
    running research (the exact conflation behind the 2026-07-13 auto-start
    incident). Reads the first 8000 chars of body innerText only; safe every
    tick. Fail-closed (False) on any error so a probe miss never fakes a start."""
    try:
        body = await page.evaluate("""() => (document.body.innerText || "").slice(0, 8000)""")
    except Exception:
        return False
    if not body:
        return False
    return bool(_GEMINI_RESEARCH_CARD_RE.search(body) or _GEMINI_COMPLETION_RE.search(body))


# Escalating nudge wording — attempt 0 is a polite directive, attempt 1
# is a yes/no check-in question, attempt 2 mirrors the terse "Done?" that
# empirically jolted Gemini in the user's manual intervention (2026-05-24).
# Each wording targets a different parser path; if Gemini ignores the
# polite directive, the question may engage it, and if both ignored, the
# terse one-word check is the empirical last resort.
_GEMINI_KICKOFF_NUDGES = (
    "Please proceed with the deep research now.",
    "Are you researching?",
    "Done?",
)


# ── Gemini "Start research" click/probe JS (#905, hoisted #953) ───────────────
# Shared by the 2D plan-wait AND the round-robin's late-Start watch leg (#953:
# 2D now hands a still-streaming Gemini to the round-robin instead of dwelling,
# so the round-robin must be able to click a Start button that renders late).
# 2026-07-06 (#905, live-run forensics): the old `<button>`-only text match had
# two failure modes seen in one run — (a) it clicked the DISABLED skeleton
# Start button Gemini renders while the plan is still streaming, and (b) it
# went blind while its own stall diagnostic dumped a visible
# {"aria":"Start research"} control, because Gemini renders the control as
# [role="button"] in some states. Match BOTH element shapes + aria-label, and
# require enabled + actually rendered (≥8px rect) before clicking/counting.
_GEMINI_START_PREDICATE_JS = (
    " const CAND = document.querySelectorAll('button, [role=\"button\"]');"
    " for (const b of CAND) {"
    "   const t = ((b.textContent) || '').trim().toLowerCase();"
    "   const a = ((b.getAttribute && b.getAttribute('aria-label')) || '').trim().toLowerCase();"
    "   if (!t.includes('start research') && !a.includes('start research')) continue;"
    "   if (b.disabled || b.getAttribute('aria-disabled') === 'true') continue;"
    "   const r = b.getBoundingClientRect();"
    "   if (r.width < 8 || r.height < 8) continue;"
)
_GEMINI_CLICK_START_JS = (
    "() => {" + _GEMINI_START_PREDICATE_JS +
    "   b.click(); return true;"
    " } return false; }"
)
_GEMINI_START_PRESENT_JS = (
    "() => {" + _GEMINI_START_PREDICATE_JS +
    "   return true;"
    " } return false; }"
)


async def _gemini_send_kickoff_nudge(page, label, attempt_idx=0):
    """Send a kickoff nudge to re-trigger Gemini's research with escalating
    wording across attempts (0-indexed). Clamps to the final wording for
    any attempt_idx beyond the list length.

    Reuses paste_followup so the nudge picks up _PASTE_SELECTORS["gemini"]
    composer selectors + the unified Send-button fallback chain — same
    machinery as the existing user-poke follow-up at research.py:~17498.
    Returns True on send, False if the composer was unreachable."""
    idx = max(0, min(attempt_idx, len(_GEMINI_KICKOFF_NUDGES) - 1))
    nudge = _GEMINI_KICKOFF_NUDGES[idx]
    ok = await paste_followup(
        page, nudge, "gemini",
        label=f"{label}-kickoff-nudge-{idx + 1}",
    )
    if ok:
        log(f"[{label}] Sent Gemini kickoff nudge #{idx + 1}/{len(_GEMINI_KICKOFF_NUDGES)}: {nudge!r}", "INFO")
    else:
        log(f"[{label}] Gemini kickoff nudge #{idx + 1} failed to send", "WARN")
    return ok


async def _resolve_parked_agent_decision(kind, action, p, name, key, elapsed,
                                         browser, cua_client, results, pending,
                                         extract_fns, max_wait_min,
                                         verbose=False) -> str:
    """#953 (audit): apply a resolved parked-decision — the retry / timeout
    action that used to run inline right after a blocking `await_agent_decision`
    in the Phase-2 round-robin. `action` is one of the poll verdicts
    ('retry'/'wait_longer'/'continue_partial'/'continue_anyway') or 'timeout'
    (the park window elapsed with no user input). 'stop'/'skip' are handled by
    the caller. Returns 'break' (unused today) or 'continue'; the caller
    always `continue`s the round-robin afterwards, so every path here just
    mutates `p` / finalizes into `results` and returns 'continue'."""
    # Gap #1 belt-and-braces (HV never-touch): several resolver branches
    # interact with the tab (session_expiry reload @~24336, switch_to_page in
    # the extract branches) and are NOT individually hv_blocked-guarded. A
    # verification-walled agent must never reach them — today that state is
    # unreachable (an agent is non-hv_blocked when it parks, and hv_blocked is
    # never set from inside the round-robin), but this guard removes the reliance
    # on that invariant so a future edit can't route a walled tab into a reload.
    if key in _controls.hv_blocked:
        log(f"[{name}] parked-decision resolver: {key} is verification-walled "
            "(hv_blocked) — hands-off no-op, never touching the wall", "WARN")
        return "continue"
    _retry = (action == "retry")

    # ── Session expiry: retry = reload the tab so the re-auth cookie lands ──
    if kind == "session_expiry":
        if _retry:
            _cur_url = ""
            try:
                _cur_url = (p["page"].url or "").lower()
            except Exception:
                pass
            # #897a: never reload a MOUNTED Gemini conversation (the SPA drops
            # it → empty home); the fresh cookie applies to its background
            # requests in place. A tab redirected OFF gemini (a login URL) has
            # no conversation to lose and the reload un-sticks it.
            _gemini_mounted = name == "Gemini" and "gemini.google.com" in _cur_url
            if not _gemini_mounted:
                try:
                    await p["page"].reload(wait_until="domcontentloaded", timeout=15000)
                    await asyncio.sleep(3)
                except Exception as _e:
                    log(f"[{name}] Reload after re-auth failed: {_e}", "WARN")
            p["last_auth_check"] = time.time()
        # retry / timeout / wait → keep polling with the (now hopefully re-authed
        # or 30-min-regraced) session.
        return "continue"

    # ── Mid-run agent error: retry = HARD retry; timeout = honest auto-skip ──
    # 2026-07-31. The other parked kinds take a SOFT action on Retry (reload,
    # re-extract, nudge) because their page is still healthy. This one's page is
    # showing a failure state, so a nudge recovers nothing — the corpus recovery
    # was `RETRY_AGENT mode=hard` → "Hard retry successful ✓" → 61,023 chars.
    #
    # Re-arming the marker rather than restarting inline is deliberate: the
    # loop-top hard-retry consumer skips PARKED agents without consuming (so the
    # soft resolvers keep their markers), and it carries every race guard that
    # path needs — the completion race, the mid-completion window, the
    # Skip-supersedes-Retry rule, the retry cap. The park is cleared by the
    # caller before we get here, so the marker is picked up on the next tick with
    # all of that intact. Same "re-arm the marker path" idiom the skip branch
    # already uses.
    if kind == "agent_error":
        if _retry:
            log(f"[{name}] error card retried — re-arming a HARD retry (a soft "
                "nudge cannot recover a page in a failure state)", "INFO")
            _controls.request_retry_agent_hard(key)
            return "continue"
        # timeout → NOW the "went unanswered" copy is true: the card really did
        # sit for the full window. Finalize through the one auto-skip shape, with
        # the honest mid-run reason rather than the "couldn't start" default.
        _ae_reason, _ae_copy, _ae_why = autoskip_reason_for_status(
            (results.get(name) or {}).get("status", "agent_error"))
        log(f"[{name}] error card sat unanswered for the full window — "
            f"auto-skipping ({_ae_why})", "WARN")
        await _finalize_agent_autoskip(
            browser, p.get("page"), key, name,
            reason=_ae_reason, copy_key=_ae_copy, why=_ae_why,
            partial=(results.get(name) or {}).get("text", "") or "",
            url=p.get("url", ""), elapsed_sec=int(elapsed),
            results=results, results_name=name)
        _disarm_registry(key)
        if name in pending:
            del pending[name]
        return "continue"

    # ── Playwright-path empty extraction: retry = re-run the tier ladder ──
    if kind == "extract_empty_pw":
        if _retry:
            p["extraction_attempts"] = 0
            p["flat_history"] = []
        return "continue"

    # ── CUA-path empty final: retry = nudge + re-poll; timeout = accept empty ──
    if kind == "extract_empty_cua":
        if _retry:
            followup = (
                "It looks like your final response didn't come through. Please output "
                "the complete research report now — include all sources, sections, and findings. "
                "No preamble or post-amble."
            )
            try:
                await browser.switch_to_page(p["page"])
                await paste_followup(p["page"], followup, name.lower(), label=f"{name}-retry-empty")
            except Exception as e:
                log(f"[{name}] Retry follow-up failed: {e}", "WARN")
            # #953 (audit #7): roll back from the elapsed captured AT PARK time,
            # not the freshly-recomputed elapsed — so the user's decision-wait
            # doesn't get folded into the budget rollback (pre-#953 parity).
            _elapsed_rb = int(p.get("_empty_elapsed_at_park", elapsed) or elapsed)
            p["start_time"] = time.time() - max(0, _elapsed_rb - (15 * 60))
            p["done_count"] = 0
            p["cua_confirmed"] = False
            p["last_cua_check"] = time.time()
            p["empty_retries"] = 0
            return "continue"
        # timeout / wait_longer / continue_partial → accept the empty result
        # (parity with the pre-#953 fall-through) and finalize the agent.
        # #953 (audit #3/#4): retract this agent's own fail_agent card + red
        # tile (mirroring the sibling auto-skip) and CLOSE its tab / null the
        # page handle — the pre-refactor fall-through left the card up and the
        # tab open with a live handle in results.
        results[name] = {"status": "empty", "text": "",
                         "url": p["page"].url if p.get("page") else "",
                         "page": None, "elapsed_sec": int(elapsed)}
        emit_event("agent_skipped", phase=2, agent=key,
                   reason="accept_empty_unanswered_timeout", partial_chars=0)
        emit_event("pipeline_warning", phase=2, agent=key,
                   error=f"{name} finished empty — moved on",
                   details=(f"{name} came back empty and the retry prompt went unanswered "
                            "— accepted the empty result so your run can finish. The other "
                            "agents aren't affected."),
                   actions=[], alert_id=f"agent_{key}_autoskip",
                   auto_clear_on_resume=True)
        try:
            await _close_skipped_agent_tab(browser, p.get("page"), key, name,
                                           final_status="empty")
        except Exception:
            pass
        if name in pending:
            del pending[name]
        return "continue"

    # ── Claude 2-artifact hard-fail: retry = nudge; timeout = auto-skip after 2 ──
    if kind == "claude_2artifact_hf":
        if _retry:
            p["hf_timeouts"] = 0
            followup = (
                "Your research is incomplete — the final comprehensive report artifact is missing. "
                "Please produce the complete research document artifact now — include every section, "
                "finding, and source. This is the deliverable document, not the references list."
            )
            try:
                await browser.switch_to_page(p["page"])
                await paste_followup(p["page"], followup, "claude", label="Claude-retry-artifact")
            except Exception as _e:
                log(f"[Claude] Retry follow-up failed: {_e}", "WARN")
            p["start_time"] = time.time() - (max_wait_min * 60) + (15 * 60)
            p["done_count"] = 0
            p["cua_confirmed"] = False
            p["last_cua_check"] = time.time()
            p.pop("_cached_text", None)
            p["empty_retries"] = 0
            return "continue"
        # wait_longer / timeout → extend budget ONCE; after the 2nd unanswered
        # timeout, auto-skip instead of looping hard-fails forever.
        #
        # 2026-08-02: gated on the user's auto-skip setting, the fifth site in
        # this family and the one nobody had noticed. This park carries a 300 s
        # literal and its card is emitted with NO deadline, so with auto-skip OFF
        # the user saw a Retry/Skip card with no countdown while a hidden ~10-min
        # fuse burned down to a greyed tile and a closed tab. With the setting off
        # we keep extending the budget and re-polling instead, so the card
        # survives for a manual decision — the same stance the L3 hard cap and the
        # registry firer already take.
        p["hf_timeouts"] = int(p.get("hf_timeouts", 0)) + 1
        if p["hf_timeouts"] >= 2 and _runtime.auto_skip_stuck:
            log(f"[Claude] 2-artifact hard-fail timed out {p['hf_timeouts']}× without a "
                "user decision — auto-skipping agent", "WARN")
            _hf_partial = ""
            if key in _controls.hv_blocked:
                log("[Claude] Auto-skip — verification-walled tab, skipping partial "
                    "extraction (hands-off)", "WARN")
            else:
                try:
                    await browser.switch_to_page(p["page"])
                    _hf_partial = await extract_fns[name](
                        p["page"], browser=browser, cua_client=cua_client,
                        label=name, verbose=verbose) or ""
                except Exception as _hfe:
                    log(f"[Claude] Auto-skip salvage extract failed: {_hfe}", "WARN")
            # #955: one finalize shape for every auto-skip.
            await _finalize_agent_autoskip(
                browser, p.get("page"), key, name,
                reason="auto_skip_unanswered_timeout",
                copy_key="claude_2artifact",
                partial=_hf_partial, url=p.get("url", ""),
                elapsed_sec=int(elapsed),
                results=results, results_name=name)
            if name in pending:
                del pending[name]
            return "continue"
        if p["hf_timeouts"] < 2:
            # First timeout — extend budget ONCE and keep polling.
            p["start_time"] = time.time() - (max_wait_min * 60) + (15 * 60)
            p["done_count"] = 0
            p["cua_confirmed"] = False
            return "continue"
        # 2026-08-02: auto-skip OFF, and the one budget extension is already
        # spent. Keep polling on the EXISTING clock — extending again would rewind
        # `elapsed` to max_wait-15min on every 5-minute re-park, so the agent's own
        # absolute limit could never be reached and an unattended run would loop
        # here forever. The card is still up (nothing retracted it), so a manual
        # Retry/Skip resolves it whenever the user gets to it.
        p["done_count"] = 0
        p["cua_confirmed"] = False
        return "continue"

    # ── Gap #1 non-blocking chat_mode: continue = keep the chat answer; ──────
    # timeout = discard + auto-skip (grey + close). Skip is handled upstream by
    # the loop-top skip consumer. The card has NO Retry (a stray retry maps to
    # timeout here → a non-degrading skip, never a silent chat-mode consent).
    if kind == "chat_mode":
        if action == "continue_anyway":
            # User KEPT chat-mode output — acknowledge; the agent stays in
            # pending and the round-robin finalizes the chat answer normally
            # (awaiting_decision was already cleared by the caller).
            _runtime.agent_modes[key] = {
                "requested": "research", "actual": "chat",
                "user_acknowledged_chat": True}
            # ⭐ 2026-08-05 — RETRACT THE CARD. This branch used to update state,
            # log, and return, emitting nothing at all. Every OTHER resolution of
            # this park emits something the clear-seam recognises (the skip path
            # emits agent_skipped), so KEEP was the one outcome that left both
            # the durable pendingDecision mirror and the volatile card standing.
            #
            # What the owner saw on 2026-08-05: clicked "Continue in chat mode",
            # the button re-enabled ~4s later, the card still read "Auto-skipping…",
            # and nothing else changed — so they clicked again 23s later. Two
            # commands for one intent, and a report of "my action didn't work".
            # It had worked; it just never said so.
            #
            # `pipeline_resumed` is the seam's agent-scoped resolve signal (see the
            # event_type list at the mirror writer) — the same one the non-blocking
            # model already emits on chat-mode-skip and retry.
            _clear_pending_decision(key)
            emit_event("pipeline_resumed", phase=2, agent=key,
                       reason="chat_mode_kept")
            log(f"[{name}] chat_mode KEPT — actual=chat acknowledged; finalizing "
                "the chat answer normally (card retracted)", "INFO")
            return "continue"
        # timeout / any non-continue → discard the chat output, grey + close.
        log(f"[{name}] chat_mode {action} → discarding chat output, greying + "
            "closing (no silent auto-degrade to chat without consent)", "WARN")
        await _finalize_agent_autoskip(
            browser, p.get("page"), key, name,
            reason=("research_unavailable_timeout_default_skip"
                    if action == "timeout" else "chat_mode_skip"),
            copy_key="chat_mode", partial="", url=p.get("url", ""),
            elapsed_sec=int(elapsed), results=results, results_name=name)
        if name in pending:
            del pending[name]
        return "continue"

    return "continue"


def _sweep_foreign_chatgpt_tabs(pending: dict, results: dict) -> "list[str]":
    """Drop any ChatGPT leg found polling a conversation that predates this run.

    Mutates `pending` and `results` in place; returns the names dropped.

    ⛔ 2026-08-05 (review, f1) — THE IDENTITY CHECK HAD FIVE CALL SITES AND NONE WAS
    ON THE POLL PATH. Every refusal upstream hands back a live page handle on the
    conversation it just declared foreign, and both seed paths put that handle into
    `pending` regardless: the pre-pending loop keeps any agent whose tab exists
    ("detectors will decide"), and the hard-retry re-seeds unconditionally. So the
    round-robin resumed polling, scraping and finally EXTRACTING someone else's
    finished thread — which is how 39 minutes and a 121KB off-topic report happened.
    The sink guard blocks the harvest, but only while the topic is judgeable; below
    the anchor floor or the size floor it abstains and the report lands.

    Running per tick covers poll, scrape AND extract in one gate, because extraction
    reads `pending`. It also covers drift that STARTS mid-poll rather than at setup:
    the panel-open rungs press real controls on this tab every few ticks, and a press
    that navigates is the defect this whole wave began with.

    ⚠ Reads the LIVE url, not `p["url"]` — that field is stamped at seed time and
    would report the tab we meant to be on rather than the one we are on.
    `_chatgpt_tab_is_foreign` abstains unless it can positively date the conversation
    as older than the run, so a bare composer, an unreadable id, and an undatable run
    all pass untouched.

    A separate function rather than a loop inline in the round-robin for the reason
    the rest of this wave learned the hard way: nothing in the suite executes
    `poll_all_agents_round_robin`, so a guard written inline there could only ever be
    source-scanned — and mutation proved that a source-scanned gate can ship inverted.
    """
    dropped = []
    for name in list(pending.keys()):
        key = normalize_agent_key(name)
        if key != "chatgpt":
            continue
        p = pending.get(name) or {}
        try:
            url = (p.get("page").url or "")
        except Exception:
            continue          # unreadable handle — the crash sweep owns that
        if not _chatgpt_tab_is_foreign(url):
            continue
        epoch = _chatgpt_convo_epoch(url)
        when = (datetime.fromtimestamp(epoch).strftime("%Y-%m-%d %H:%M:%S")
                if epoch else "unknown")
        log(f"[{name}] ⛔ polling a conversation that predates this run (created "
            f"{when}, url={url!r}) — dropping it from the round-robin rather than "
            f"harvesting someone else's thread", "ERROR")
        # A parked chat-mode decision on this leg belongs to a send into a
        # conversation we are now refusing; retract it with the leg.
        _controls.chat_mode_pending.pop(key, None)
        results[name] = {
            "status": "wrong_conversation", "text": "", "url": url, "page": None,
            "elapsed_sec": int(time.time() - p.get("start_time", time.time()))}
        _disarm_registry(key)
        del pending[name]
        # Retry restarts the agent (close tab + re-run setup), which is exactly the
        # recovery this needs — unlike a crash, nothing auto-recovers a tab sitting
        # in the wrong conversation.
        fail_agent(key, *_wrong_conversation_copy(name))
        dropped.append(name)
    return dropped


async def poll_all_agents_round_robin(agents, browser, cua_client,
                                       max_wait_min=90, poll_interval=30, verbose=False):
    """Round-robin poll all verified agents until each completes or times out.

    ChatGPT DR: polls for document card/canvas appearance (no stop button).
    Gemini/Claude: polls for stop button disappearance.
    Minimum wait enforced per agent to prevent false-positive early completion.
    """
    extract_fns = {
        "ChatGPT": extract_chatgpt_response,
        "Gemini": extract_gemini_response,
        "Claude": extract_claude_response,
    }
    # Used by the reload rescues (error-verdict and confirmed-stuck branches) to
    # decide whether a reloaded page actually came back generating. Referenced by
    # BRANCH, not line number — line refs rot, and a stale one already sent one
    # diagnosis down the wrong path this cycle.
    verify_fns = {
        "ChatGPT": verify_chatgpt_generating,
        "Gemini": verify_gemini_generating,
        "Claude": verify_claude_generating,
    }
    # Agents whose conversation SURVIVES a reload, so the error-verdict rescue may
    # re-navigate them. GEMINI IS DELIBERATELY EXCLUDED: its SPA no longer restores
    # the conversation on reload, it lands on the empty home (#897a — the same reason
    # the periodic Gemini refresh was deleted). Reloading Gemini to rescue it would
    # destroy the very run being rescued.
    RELOAD_SAFE = {"ChatGPT", "Claude"}
    # CUA completion check: first at 5 min (MIN_WAIT), then every 5 min.
    # 2026-04-25: dropped from 20→5 to mirror P1 cadence (catches fast finishers).
    _min_agent_wait = int(os.environ.get("MIN_AGENT_WAIT_MIN", "5")) * 60
    MIN_WAIT = {"ChatGPT": _min_agent_wait, "Gemini": _min_agent_wait, "Claude": _min_agent_wait}
    CUA_CHECK_INTERVAL = 300   # 5 min between CUA completion checks
    # #897a: GEMINI_REFRESH_INTERVAL / GEMINI_REFRESH_GRACE deleted with the
    # periodic reload — Gemini is never reloaded mid-run (its SPA no longer
    # restores the conversation on reload; it lands on the empty home).
    ARTIFACT_SCRAPE_INTERVAL = 60   # 1 min between Claude artifact-tracking scrapes (was 180; iteration #1 must pass — see init at last_artifact_scrape=0 below)

    # ── #921 per-agent stuck escalation (Layer 1) + auto-skip backstop (Layer 3) ──
    # The 2026-07-08 stale runs proved the old detection dead: the no-growth
    # watchdog was gated behind `_cua_check_age > 1200` (never true — the CUA
    # completion check refreshes last_cua_check every CUA_CHECK_INTERVAL), and
    # the per-agent wall-clock cap had been removed in 2026-05 — so a genuinely
    # stuck agent produced NO user-facing card and the phase hung until a manual
    # Stop. Progress here means growth in extracted chars/sources, NEVER
    # heartbeats or narration churn (a stuck agent narrates "still generating"
    # the whole time). All env-overridable for live tuning.
    # #929 (2026-07-09): 600→900 / 1200→1800 after a live false alarm — a
    # healthy Gemini took >10 min on its research plan, got carded at the
    # old 10-min mark and auto-skipped 20 min later. 15 min before the
    # arbiter is even consulted + 30 min of card-unacted grace gives the
    # WORKING re-verdict (throttled to every 10 min) two chances to
    # retract a false card before Layer 3 can act on it.
    STUCK_NO_GROWTH_SEC = int(os.environ.get("DG_STUCK_NO_GROWTH_SEC", "900"))       # L1: 15 min flat → CUA arbiter → [Retry][Skip] card
    STUCK_MIN_ELAPSED_SEC = int(os.environ.get("DG_STUCK_MIN_ELAPSED_SEC", "600"))   # never stuck-check in the first 10 min
    STUCK_WARN_THROTTLE_SEC = int(os.environ.get("DG_STUCK_WARN_THROTTLE_SEC", "600"))  # ≥10 min between arbiter probes / re-warns
    # 2026-08-05: how many times a vision WORKING verdict may rewind the growth
    # clock. Each one buys another full STUCK_NO_GROWTH_SEC, and before this the
    # count was unbounded — so a model that kept answering "working" could hold a
    # dead leg open until the wall-clock cap, which the user can switch off. Two
    # extensions = 30 min of arbiter-granted grace, comfortably covering the
    # cross-origin-iframe false-positive class the branch exists for.
    _ARBITER_MAX_WORKING_RESETS = int(os.environ.get("DG_ARBITER_MAX_WORKING_RESETS", "2"))
    AUTO_SKIP_UNACTED_SEC = auto_skip_unacted_sec()  # L3: 30 min after the card sits unacted → auto-skip THIS agent (module-level so P3 shares the value)
    PER_AGENT_HARD_CAP_SEC = int(os.environ.get("DG_PER_AGENT_HARD_CAP_SEC", "5400"))  # L3: 90 min absolute per-agent ceiling → auto-skip

    pending = {}
    results = {}

    for name, agent in agents.items():
        # 2026-04 fix: don't drop an agent just because verify_*_generating
        # returned False. Verifiers can miss real activity (e.g. ChatGPT DR
        # lives in a cross-origin iframe that host-side selectors can't see).
        # As long as the tab exists we keep it in the round-robin — the
        # Playwright detectors + CUA fallback decide completion. If the tab
        # is truly dead, #921's PER_AGENT_HARD_CAP_SEC (90-min absolute cap)
        # auto-skips it — restored after the 2026-05 removal left this
        # false-negative handoff with no backstop (2026-07-08 stale runs).
        # Only skip when there's no page handle at all (tab never opened).
        if not agent.get("page"):
            results[name] = {"status": "not_verified", "text": "", "url": agent.get("url", "")}
            continue
        if not agent["verified"]:
            log(f"[{name}] verify_{name.lower()}_generating returned False but page exists — "
                f"keeping in round-robin (detectors will decide).", "WARN")
            # No immediate alert: the round-robin keeps polling; #921's
            # stuck arbiter (10-min no-growth) or the 90-min hard cap
            # surfaces a card / auto-skip if no real output ever appears.
        # Use research_started_at if available (e.g., Gemini waits for "Start research")
        # so elapsed/MIN_WAIT are computed from actual research start, not submission.
        _research_t = agent.get("research_started_at", time.time())
        pending[name] = {
            "page": agent["page"],
            "url": agent["url"],
            "start_time": _research_t,
            "done_count": 0,
            "cua_confirmed": False,
            "last_heartbeat": _research_t,
            "last_cua_check": _research_t,       # CUA check gate — MIN_WAIT from research start
            "last_artifact_scrape": 0,           # 0 → iteration #1 always passes the gate (Claude opens artifact ASAP)
            "chatgpt_activity_panel_open": False,  # ChatGPT activity-strip click flag — mirror Claude pattern
            "poll_cycles": 0,                    # increments once per round-robin tick — gates iter-#3 panel-open
            "chatgpt_panel_dom_misses": 0,       # consecutive DOM "found:false" — escalates to CUA after 2
            "chatgpt_panel_cua_attempts": 0,     # capped at 1/agent/phase
            "claude_artifact_dom_misses": 0,
            "claude_artifact_cua_attempts": 0,
            "observer_text_len": 0,              # MutationObserver sets this (see B2)
            "claude_clarification_replied": False,  # one-shot flag for clarification-defer reply
            "gemini_kickoff_nudge_count": 0,        # multi-shot nudge counter (max 3, 3min apart) for Gemini kickoff-stall
            "gemini_last_kickoff_nudge_at": 0.0,    # timestamp gate enforcing 3min spacing between Gemini kickoff nudges
            # #905: 2D hands off right after a confirmed "Start research"
            # click so cycle 1 can open the ChatGPT/Claude panels first; the
            # cycle-1 Gemini leg then finishes the start-verify.
            "needs_start_verify": bool(agent.get("needs_start_verify")),
            # #953: 2D handed off a still-streaming Gemini (auto-start or a
            # slow plan) — the Gemini leg watches for a late 'Start research'
            # button and clicks it, or clears the watch once verified running.
            "gemini_watch_start": bool(agent.get("gemini_watch_start")),
            # 2026-08-19: did ANY probe ever confirm this agent actually
            # RUNNING? Read by detect_completion_gemini's last resort so it
            # stops calling a started run "pre-research".
            # ⛔ NOT "did we click Start". That was true in the 2026-08-17
            # ninety-minute failure as well — the click reported success and the
            # verify disagreed — and `pre-research` was the CORRECT label there.
            # A confirmed running verify is the ONE fact that separates the run
            # that started from the run that never did.
            "gemini_running_confirmed": bool(agent.get("verified")),
        }
        # Register for mid-run input dispatcher
        platform_key = name.lower().replace(" ", "")
        _runtime.register_page(platform_key, agent["page"], agent["url"])
        # Gap #1 (non-blocking chat_mode): an agent that submitted its brief in
        # chat mode during setup left a chat_mode_pending marker — seed its
        # kind="chat_mode" park so the round-robin gates finalization (#709) and
        # resolves keep/skip WITHOUT a setup-context pause.
        _cm = _controls.chat_mode_pending.pop(platform_key, None)
        if _cm:
            pending[name]["awaiting_decision"] = {
                "kind": "chat_mode", "key": platform_key,
                "since": _cm.get("since", time.time()),
                "timeout": _cm.get("timeout", 1800.0)}
            log(f"[round-robin] {name} parked kind=chat_mode (submitted in chat "
                "mode, awaiting keep/skip) — siblings keep polling", "INFO")

    # ── Auto-skip finalization (bug 2.5): make an unresolved failure LOOK ────
    # ── exactly like a normal skip ──────────────────────────────────────────
    # Any ENABLED agent that finished UNRESOLVED — a setup/verify failure
    # (2A/2B/2C fail_agent → red 'errored' tile + Retry/Skip card + internal
    # skip marker), a signed-out wall, or a hard-retry exhaustion — was dropped
    # WITHOUT being greyed or having its tab closed. The run proceeds regardless,
    # so to the user that agent WAS auto-skipped — yet it kept a red 'errored'
    # tile, an open browser tab, and (because phase_complete still fires) a lying
    # "Completed in X min" stepper (live 2026-07-13: Gemini brief-send failed,
    # ran to P3 still red + tab open + "Complete"). Finalize each such agent
    # exactly like a user Skip / the Layer-3 stuck auto-skip: emit agent_skipped
    # (greys the tile + clears the Retry/Skip card, durable pendingDecision
    # included + persists status='skipped'), close its tab, and drop an
    # informational notice. One consistent shape for EVERY auto-skip.
    #
    # Runs at BOTH round-robin exits — the natural loop exit AND the
    # `pending`-empty-at-entry early return below (every enabled agent failed
    # setup with a null page handle, so none entered the poll set). It never
    # runs on a stop/pause return (those return from INSIDE the while-loop,
    # before the natural exit). Respects the user's auto-skip setting: OFF leaves
    # the card up for a manual decision (never silently greys).
    async def _finalize_unresolved_autoskips():
        if not _runtime.auto_skip_stuck:
            return
        for _fin_name, _fin_agent in list(agents.items()):
            _fin_key = normalize_agent_key(_fin_name)
            _fin_r = results.get(_fin_name) or {}
            _fin_st = (_fin_r.get("status") or "").lower()
            _fin_persisted = (_agent_status_by_rid.get(_fb_research_id, {}) or {}).get(_fin_key)
            # Already resolved by the user (retried-to-done / Skip) or by an
            # earlier auto-skip path (Layer-3) — never touch a green ✓ or an
            # existing grey skip.
            if _fin_persisted in ("complete", "skipped"):
                continue
            # Produced real output (incl. a fail_agent'd agent the user retried
            # to completion, whose persisted 'errored' may not yet be flipped to
            # 'complete' — phase_complete does that AFTER this returns) → done,
            # never auto-skip it.
            _produced_output = bool(_fin_r.get("text")) or _fin_st in (
                "done", "complete", "completed", "done_partial", "partial")
            if _produced_output:
                continue
            # 2026-07-31: never finalize an agent whose card is STILL LIVE.
            #
            # This sweep is the reason a Retry/Skip card could be raised and
            # destroyed in the same second. It ran at loop exit and finalized
            # anything unresolved with NO deadline test whatsoever — verified: no
            # reference to AUTO_SKIP_UNACTED_SEC, no timestamp, no deadline. The
            # mid-run error path now parks instead of dropping, which keeps the
            # loop alive and hands the timeout to the parked-decision resolver;
            # this guard is the second half, so a card that is still inside its
            # window survives a sweep triggered by a SIBLING agent finishing.
            #
            # It is a backstop, not a timer: by the time the loop legitimately
            # exits, every park has either been resolved or timed out. If one is
            # somehow still parked here, leaving the card up is the correct
            # failure mode — it is what the user is being asked to act on.
            if (pending.get(_fin_name) or {}).get("awaiting_decision"):
                log(f"[{_fin_name}] exit sweep: card still live (parked, awaiting "
                    "the user) — NOT auto-skipping; the parked resolver owns its "
                    "deadline", "INFO")
                continue
            # Target: an UNRESOLVED failure with no output. fail_agent persisted
            # 'errored' (setup fail, signed-out, hard-retry-exhausted), or the
            # poll set dropped it with a start-failure status.
            _needs_finalize = (
                _fin_persisted == "errored"
                or _fin_st in ("failed_setup", "not_verified")
            )
            if not _needs_finalize:
                continue
            # 2026-07-31: pick the HONEST reason instead of calling everything a
            # startup failure. The reason string reaches the FE verbatim, so a
            # wrong one here is a wrong story in the phase dropdown AND in the
            # durable record. See autoskip_reason_for_status for the rationale.
            _fin_reason, _fin_copy, _fin_why = autoskip_reason_for_status(_fin_st)
            log(f"[{_fin_name}] Auto-skip finalize — {_fin_why} and its "
                "Retry/Skip alert went unanswered; greying the tile + closing "
                f"the tab so it matches a normal skip (bug 2.5). "
                f"[status={_fin_st or '?'} persisted={_fin_persisted or '?'}]", "WARN")
            # #955: one finalize shape for every auto-skip (agent_skipped greys
            # the tile + clears the card and durable mirror; notice explains WHY).
            await _finalize_agent_autoskip(
                browser, _fin_agent.get("page"), _fin_key, _fin_name,
                reason=_fin_reason,
                copy_key=_fin_copy,
                url=_fin_r.get("url", "") or _fin_agent.get("url", ""),
                elapsed_sec=int(_fin_r.get("elapsed_sec", 0) or 0),
                results=results, results_name=_fin_name)

    async def _fire_due_autoskips():
        # #955 Phase 2: THE registry-driven auto-skip firer (design G(i)). Once
        # per tick, auto-skip any in-`pending` agent whose armed deadline has
        # passed. This is the single SOURCE→FIRE pairing for the stuck card:
        # emit_decision stamps `auto_skip_deadline` (the FE counts down to the
        # exact same epoch), the round-robin arms it at the stuck site, and this
        # fires it — no drift between the shown countdown and when the BE acts.
        # It REPLACES the old in-loop `_unacted_too_long` timer (which counted
        # from `stuck_alerted_at` and was never reflected on the FE deadline
        # field, so the countdown and the real fire could disagree).
        #
        # Gated on the user's auto-skip setting (parity with the old L3 gate +
        # the HV finalize). Fires ONLY `recoverable` entries — in Phase 2 the
        # sole in-`pending` armed card is the stuck card, so the finalize copy is
        # the stuck copy. hands_off HV walls fire loop-locally from their own
        # wait (design G(ii)) and never enter this registry; blocker/infra never
        # arm at all (emit_decision refuses). A defensive WARN+skip on any other
        # class means a future in-`pending` card that needs different copy must
        # extend this firer, not silently inherit the stuck wording.
        # Bail under stop/pause — the firer does real page I/O (salvage-extract +
        # tab close); a resume clears the whole registry (agent-less
        # pipeline_resumed → seam clear-all) so nothing fires stale post-resume.
        if not _runtime.auto_skip_stuck or _controls.is_stop() or _controls.is_pause():
            return
        _now_ms = time.time() * 1000
        _name_by_key = {normalize_agent_key(_n): _n for _n in pending}
        for _did, _entry in list(_pending_decisions.items()):
            _dl = _entry.get("deadline")
            if _dl is None or _now_ms < _dl:
                continue
            _key = _entry.get("agent")
            _nm = _name_by_key.get(_key)
            if not _key or not _nm or _nm not in pending:
                continue   # not one of our live pending agents (a setup/P1/P3 card)
            if _entry.get("recoverability") != "recoverable":
                log(f"[{_nm}] registry firer saw a {_entry.get('recoverability')!r} "
                    "armed entry — skipping (only the recoverable stuck card fires "
                    "here; other classes fire loop-locally)", "WARN")
                continue
            _p = pending[_nm]
            # #955 Phase 2 (adversarial finding #6): a PARKED agent (session
            # expiry / empty extraction / missing artifact) is governed by the
            # parked-decision resolver, NOT this firer — its live card is no
            # longer the stuck card, so a stale stuck deadline must not auto-skip
            # it (off "stayed frozen" copy) while the user is being told to sign
            # back in and Retry. The supersede purge above normally drops the
            # stale deadline on the re-card, but this is a belt-and-braces guard.
            if _p.get("awaiting_decision"):
                continue
            _elapsed = time.time() - _p.get("start_time", time.time())
            log(f"[{_nm}] Auto-skip — the [Retry][Skip] card sat unanswered past its "
                f"deadline (elapsed {int(_elapsed/60)}m). Salvaging partial output, "
                "closing tab, continuing other agents.", "WARN")
            # #929 hands-off parity: never run the extraction ladder against a
            # verification-walled tab (the touches the Cloudflare directive
            # forbids), and a walled agent has nothing to salvage anyway.
            _partial = ""
            if _key in _controls.hv_blocked:
                log(f"[{_nm}] Auto-skip — verification-walled tab, skipping partial "
                    "extraction (hands-off)", "WARN")
            else:
                try:
                    await browser.switch_to_page(_p["page"])
                    _partial = await extract_fns[_nm](
                        _p["page"], browser=browser, cua_client=cua_client,
                        label=_nm, verbose=verbose) or ""
                except Exception as _fe:
                    log(f"[{_nm}] Auto-skip salvage extract failed: {_fe}", "WARN")
            # #955 Phase 2 (adversarial finding #4): the salvage-extract above
            # awaits real page I/O for seconds. A user Retry/Skip (dispatched onto
            # the loop by the Firestore command listener) that lands DURING that
            # await disarms this entry (and the retry/skip consumers resolve the
            # agent next tick). Re-validate against LIVE state before committing —
            # an explicit user action inside the window must WIN, not be
            # overridden by this firer's stale pre-await snapshot (which would
            # finalize an auto_skipped result that then vetoes the user's retry).
            if _did not in _pending_decisions or _nm not in pending:
                log(f"[{_nm}] Auto-skip aborted — card resolved during salvage "
                    "(user acted / agent recovered mid-extract)", "INFO")
                continue
            await _finalize_agent_autoskip(
                browser, _p.get("page"), _key, _nm,
                reason="auto_skip_stuck_no_response",
                copy_key="stuck", why="stayed frozen with no response",
                partial=_partial, url=_p.get("url", ""),
                elapsed_sec=int(_elapsed),
                results=results, results_name=_nm)
            # Purge ALL of this agent's registry entries (agent_skipped's central
            # clear also disarms, but be explicit — one-live-entry invariant).
            _disarm_registry(_key)
            if _nm in pending:
                del pending[_nm]

    if not pending:
        # Every enabled agent failed setup with a null page handle — none
        # entered the poll set. Still finalize them as clean auto-skips.
        await _finalize_unresolved_autoskips()
        return results

    _runtime.phase = 2
    _runtime.sub_state = "2_parallel_polling"
    log(f"\n--- Round-robin polling {len(pending)} agents (max {max_wait_min}min each) ---")

    # ── C1: tick counter drives strict-rotation cursor ──
    # Every tick shifts the per-agent iteration order by one, so after a
    # full rotation every agent has had its turn at being processed first.
    # Fixes the "only one agent gets polled" starvation that appears when
    # an earlier agent's await_agent_decision or long CUA check eats the
    # tick's budget before later agents are reached.
    _tick_counter = 0
    # Target 5 min of cursor dwell per agent — at the default 30s poll
    # interval that's 10 ticks between full rotations, still giving each
    # agent a shot at foreground focus every single tick via the shift.
    _tick_counter_initial = 0

    while pending:
        _tick_counter += 1
        # ── Browser-crash sweep (per-tick, before any per-agent work) ──
        # If any pending agent's tab crashed since the last tick, fail it
        # via Template B and drop it from pending so the rotation isn't
        # starved waiting on a dead handle.
        for _crash_name in list(pending.keys()):
            _crash_p = pending.get(_crash_name) or {}
            _crash_page = _crash_p.get("page")
            try:
                _crashed = bool(_crash_page is None or _crash_page.is_closed())
            except Exception:
                _crashed = True
            if _crashed:
                _crash_key = normalize_agent_key(_crash_name)
                # #906: a tab we closed on a user Skip is not a crash — leave
                # the agent for the skip consumer just below this sweep.
                if _crash_key in _controls.skipped_agents:
                    continue
                # #907: --login killed this Chrome ON PURPOSE (it takes every
                # tab at once). Don't fail agents one by one into a phantom
                # "PHASE 2 COMPLETE: 0/3" → phase-3 gate card — unwind the
                # whole pipeline so run_pipeline's failure path pauses at the
                # checkpoint with the honest "Interrupted by the login
                # command" card (Retry = resume_from_checkpoint).
                if _login_interrupt_active():
                    log(f"[{_crash_name}] Browser closed by the login command — "
                        "pausing the run at its checkpoint", "WARN")
                    _runtime.last_failure_kind = "login_interrupt"
                    raise RuntimeError(
                        "research browser closed by the login command (login interrupt)")
                log(f"[{_crash_name}] Browser tab crashed — failing agent", "WARN")
                # Always-auto: passive banner, outer run_pipeline.finally
                # rebuilds the browser session and resumes from checkpoint.
                _runtime.last_failure_kind = "browser_crash"
                # ⭐ THE FACTS LIVE ON THE PENDING ENTRY AND DIE WITH IT. `_crash_p`
                # is deleted four lines below, and the exit sweep never sees this
                # agent at all (a crash calls no `fail_agent`, so nothing persists
                # "errored" and `_needs_finalize` is false). If the notice does not
                # carry the clocks here, nothing downstream can.
                # ⚠ `last_growth_time` defaults to `start_time`, so a leg that
                # never grew once would otherwise report its whole life as silence.
                _crash_grew = (_crash_p.get("last_growth_len", 0) > 0
                               or _crash_p.get("last_growth_sources", 0) > 0)
                _crash_quiet = (int(time.time() - _crash_p["last_growth_time"])
                                if _crash_grew and _crash_p.get("last_growth_time") else None)
                # ⛔ Computed here, not read from `results` — this notice is
                # emitted BEFORE the results row is written four lines below.
                _crash_elapsed = int(time.time() - _crash_p.get("start_time", time.time()))
                emit_browser_recovery_status(
                    2, agent=_crash_key,
                    elapsed_sec=_crash_elapsed,
                    quiet_sec=_crash_quiet,
                    rechecks=int(_crash_p.get("arbiter_working_resets", 0) or 0))
                results[_crash_name] = {"status": "browser_crashed", "text": "",
                                        "url": _crash_p.get("url", ""),
                                        "page": None,
                                        "elapsed_sec": int(time.time() - _crash_p.get("start_time", time.time()))}
                # #955 Phase 2 (adversarial finding #1): a crashed tab emits only
                # a passive browser-recovery banner — NOT a resolve-seam signal —
                # so drop its armed deadline explicitly, else the stale entry
                # (module-global registry) auto-skips a healthy same-key agent on
                # the first tick of the next run in this long-lived worker.
                _disarm_registry(_crash_key)
                del pending[_crash_name]
                continue
        # ── Foreign-conversation sweep (per-tick, sibling of the crash sweep) ──
        _sweep_foreign_chatgpt_tabs(pending, results)
        # ── Stop/Pause check via asyncio Events ──
        if _controls.is_stop() or _controls.is_pause():
            is_stop = _controls.is_stop()
            signal = "STOP" if is_stop else "PAUSE"
            log(f"[Round-robin] {signal} requested — collecting partial results from completed agents")
            if is_stop:
                for name in list(pending.keys()):
                    p = pending[name]
                    try:
                        await browser.switch_to_page(p["page"])
                        text = await extract_fns[name](p["page"], browser=browser,
                            cua_client=cua_client, label=name, verbose=verbose)
                        elapsed = time.time() - p["start_time"]
                        status = "partial" if text and len(text) > 100 else "interrupted"
                        results[name] = {"status": status, "text": text or "",
                                         "url": p["page"].url, "page": p["page"],
                                         "elapsed_sec": int(elapsed)}
                        log(f"  [{name}] {status} — {len(text or '')} chars")
                    except Exception as e:
                        results[name] = {"status": "interrupted", "text": "",
                                         "url": p.get("url", ""), "page": p["page"]}
                        log(f"  [{name}] extraction failed: {e}", "WARN")
            else:
                # On PAUSE: snapshot current agent URLs, close browser, block, then relaunch+reopen
                for name in list(pending.keys()):
                    p = pending[name]
                    plat = name.lower().replace(" ", "")
                    url = ""
                    try:
                        url = p["page"].url
                    except Exception:
                        url = p.get("url", "")
                    _runtime.agent_chat_urls[plat] = url
                    _runtime.agent_statuses[plat] = "generating"
                    results[name] = {"status": "paused", "text": "",
                                     "url": url, "page": None,  # Page dies on close
                                     "elapsed_sec": int(time.time() - p["start_time"])}
                _runtime.phase = 2
                _runtime.sub_state = "2_parallel_polling"
                # Pause/resume helpers expect the actual queue dir (where
                # `checkpoint_pause.json` lives). Passing `_tracks_dir`
                # here was a silent bug — the variable now just holds the
                # run name, so the write would land at `<run_name>/`
                # relative to cwd and almost always fail. Resolve to the
                # real queue dir before calling.
                _qd = (Path(__file__).parent / "queues" / _tracks_dir.name) if _tracks_dir else None
                stopped = await pause_and_close_browser(browser, _qd, phase=2)
                if stopped:
                    return results
                # If user added input during the pause, bail out of the
                # round-robin so the orchestrator can rerun Phase 2 with the
                # combined brief (matches "pause + input + resume = rerun").
                if _controls.peek_extra_context():
                    _runtime.restart_requested = True
                    log("[Round-robin] Extra context during pause — signalling Phase 2 restart")
                    return results
                # Relaunch browser + reopen agent tabs
                await browser.start()
                restored = await resume_browser_from_checkpoint(browser, _qd)
                # Reconstruct pending from restored pages
                for name in list(results.keys()):
                    if results[name]["status"] != "paused":
                        continue
                    plat = name.lower().replace(" ", "")
                    if plat in restored:
                        results[name]["page"] = restored[plat]
                        results[name]["url"] = restored[plat].url
                # Resumed — re-read config and only restore agents that are still enabled
                updated_cfg = _controls.pop_config_updates()
                # Also check disk config
                _cfg_path = Path(__file__).parent / "queues"
                if _tracks_dir:
                    _cfg_disk = _cfg_path / _tracks_dir.name / "config.json"
                    if _cfg_disk.exists():
                        try:
                            _disk_cfg = json.loads(_cfg_disk.read_text(encoding="utf-8"))
                            updated_cfg = {**_disk_cfg, **updated_cfg}  # in-memory overrides disk
                        except Exception:
                            pass
                _resume_agents = updated_cfg.get("agents", {"chatgpt": True, "gemini": True, "claude": True})
                _agent_name_map = {"ChatGPT": "chatgpt", "Gemini": "gemini", "Claude": "claude"}
                for name in list(results.keys()):
                    if results[name]["status"] == "paused":
                        agent_key = _agent_name_map.get(name, name.lower())
                        if _resume_agents.get(agent_key, True):
                            # Agent still enabled — restore to polling
                            pending[name] = {"page": results[name]["page"], "url": results[name]["url"],
                                             "start_time": time.time() - results[name]["elapsed_sec"],
                                             "done_count": 0, "cua_confirmed": False,
                                             "last_heartbeat": time.time(),
                                             "last_cua_check": time.time(),
                                             "last_artifact_scrape": 0,
                                             "chatgpt_activity_panel_open": False,
                                             "poll_cycles": 0,
                                             "chatgpt_panel_dom_misses": 0,
                                             "chatgpt_panel_cua_attempts": 0,
                                             "claude_artifact_dom_misses": 0,
                                             "claude_artifact_cua_attempts": 0,
                                             "observer_text_len": 0,
                                             "claude_clarification_replied": False}
                            del results[name]
                            log(f"  [{name}] Restored to polling")
                        else:
                            # Agent disabled during pause — extract what we have and skip
                            log(f"  [{name}] Disabled during pause — extracting partial results")
                            try:
                                await browser.switch_to_page(results[name]["page"])
                                text = await extract_fns[name](results[name]["page"], browser=browser,
                                    cua_client=cua_client, label=name, verbose=verbose)
                                results[name] = {"status": "disabled_during_pause", "text": text or "",
                                                 "url": results[name]["url"], "page": results[name]["page"],
                                                 "elapsed_sec": results[name]["elapsed_sec"]}
                            except Exception:
                                results[name] = {"status": "disabled_during_pause", "text": "",
                                                 "url": results[name]["url"], "page": results[name]["page"],
                                                 "elapsed_sec": results[name]["elapsed_sec"]}
                            emit_event("agent_skipped", phase=2, agent=agent_key)
                            _write_agent_terminal_status(agent_key, "skipped")
                emit_event("pipeline_resumed", phase=2)
                continue
            return results

        # ── Mid-run skip (from BackendSilentBanner or HumanVerifyBanner) ──
        # User hit "Skip [agent]" in the UI → _controls.skipped_agents has
        # the lowercase name. Extract whatever partial output exists from
        # that tab and drop it from `pending` so the rest of Phase 2 keeps
        # going with the remaining agents.
        _skip_name_map = {"chatgpt": "ChatGPT", "gemini": "Gemini", "claude": "Claude"}
        for _ag_key in list(_controls.skipped_agents):
            _agent_name = _skip_name_map.get(_ag_key)
            if _ag_key in _controls.hv_auto_skipped:
                # Already finalized by the HV auto-skip (greyed + tab closed +
                # decision cleared at skip time). Just drop it from the poll set
                # so we don't re-emit agent_skipped (with a wrong user_skip
                # reason), re-extract, or re-close.
                if _agent_name and _agent_name in pending:
                    _p = pending[_agent_name]
                    results[_agent_name] = {
                        "status": "skipped_auto_hv",
                        "text": "",
                        "url": _p.get("url", ""),
                        "page": None,
                        "elapsed_sec": int(time.time() - _p["start_time"]),
                    }
                    del pending[_agent_name]
                _controls.consume_skip_marker(_ag_key)
                continue
            # 2026-07-11 incident (Gemini 2C brief never sent): NON-user
            # markers must not ride the user-skip rails below. The 2A/2B/2C
            # setup-fail paths park the agent here only to keep it out of the
            # poll/scrape (their fail_agent already reported the truth:
            # status="failed", "errored" tile, Retry/Skip card), and the
            # login-gate timeout already emitted its own honest agent_skipped.
            # Routing them below stamped reason="user_skip*" on a skip nobody
            # chose AND the emit auto-retracted the live Retry/Skip card via
            # the emit_event pending-decision clear seam (card raised 02:50:13,
            # phantom-cleared 02:50:17). #929 precedent: finalize honest skips
            # at their source; the consumer's user-skip copy is ONLY for taps.
            if _ag_key not in _controls.user_skip_taps:
                _auto_reason = _controls.auto_skip_reasons.pop(_ag_key, "internal_marker")
                if _agent_name and _agent_name in pending:
                    _p_int = pending[_agent_name]
                    results[_agent_name] = {
                        "status": "failed_setup", "text": "",
                        "url": _p_int.get("url", ""), "page": None,
                        "elapsed_sec": int(time.time() - _p_int["start_time"]),
                    }
                    del pending[_agent_name]
                    log(f"[{_agent_name}] dropped from the poll set ({_auto_reason}) — "
                        "NOT a user skip; failed status + Retry/Skip card stay up", "INFO")
                else:
                    log(f"[{_agent_name or _ag_key}] internal skip marker consumed "
                        f"({_auto_reason}) — no user_skip emit (source already "
                        "reported failed/skipped honestly)", "INFO")
                _controls.consume_skip_marker(_ag_key)
                continue
            if _agent_name and _agent_name in pending:
                p = pending[_agent_name]
                # #953: never clobber a recorded successful result. If this
                # agent already completed (its results entry holds real text —
                # e.g. a stale hard-retry re-seeded `pending` after the fact),
                # a Skip must keep the good report: drop the stub from the
                # poll set, close its tab, consume the marker — but leave
                # `results` and the persisted status untouched.
                _prior_done = results.get(_agent_name) or {}
                if _prior_done.get("status") == "done" and (_prior_done.get("text") or ""):
                    log(f"[{_agent_name}] Skip on an already-completed agent — keeping "
                        f"the recorded {len(_prior_done.get('text') or '')}-char report; "
                        "dropping the leftover poll stub only", "INFO")
                    _stub_page = p.get("page")
                    del pending[_agent_name]
                    _controls.consume_skip_marker(_ag_key)
                    if _stub_page is not None:
                        # final_status="done": closing this leftover stub tab must
                        # NOT demote the completed agent's runtime status (#953
                        # audit — a 'skipped' demotion makes pause/resume re-poll
                        # the finished conversation).
                        await _close_skipped_agent_tab(browser, _stub_page, _ag_key,
                                                       _agent_name, final_status="done")
                    continue
                # #906 hands-off: never run the extraction ladder against a
                # verification-walled tab — DOM walks + the CUA fallback ARE
                # the touches the 2026-07-06 Cloudflare directive forbids
                # (live repro: skip-extract drove the full ladder against the
                # challenge_redirect page), and there's nothing to extract
                # from an agent that never got past the wall anyway.
                if _ag_key in _controls.hv_blocked:
                    log(f"[{_agent_name}] Skipped by user — verification-walled tab, "
                        "skipping partial extraction (hands-off)", "WARN")
                    _partial = ""
                else:
                    log(f"[{_agent_name}] Skipped by user — extracting partial output", "WARN")
                    try:
                        await browser.switch_to_page(p["page"])
                        _partial = await extract_fns[_agent_name](
                            p["page"], browser=browser, cua_client=cua_client,
                            label=_agent_name, verbose=verbose)
                    except Exception as _e:
                        log(f"[{_agent_name}] Skip-extract failed: {_e}", "WARN")
                        _partial = ""
                    # ⭐ 2026-08-05 — this branch bypasses `extract_and_record_agent`
                    # entirely, so it also bypassed the only off-topic guard that
                    # existed. It is the path that shipped 121KB about golden
                    # retrievers on 2026-08-05: the leg had drifted into a foreign
                    # conversation, the user pressed Skip after 45 minutes, and the
                    # foreign report went straight into results → disk → Firestore →
                    # NotebookLM. A partial extraction is exactly where a wrong-tab
                    # harvest is MOST likely, not least.
                    #
                    # `_p2_run_dir()` rather than a `queue_dir` parameter: this
                    # loop never receives one (its own
                    # `extract_and_record_agent` calls get it from the caller's
                    # scope), and the resolver is the file's existing idiom for
                    # the same directory — see `_p2_sources_manifest_path`.
                    # It returns None before a run is bound, which the guard
                    # treats as ABSTAIN.
                    _partial = reject_off_topic_text(
                        _partial, _p2_run_dir(), _agent_name, _ag_key,
                        op="skip_extract_topic_guard")
                results[_agent_name] = {
                    "status": "skipped_by_user",
                    "text": _partial or "",
                    "url": p.get("url", ""),
                    # #906: the tab is closed below — never hand a dead page
                    # handle downstream (nothing consumes it for skipped
                    # agents; run_phase2's caller only reads .text).
                    "page": None,
                    "elapsed_sec": int(time.time() - p["start_time"]),
                }
                del pending[_agent_name]
                emit_event("agent_skipped", phase=2, agent=_ag_key,
                           reason="user_skip",
                           partial_chars=len(_partial or ""))
                # status="skipped" auto-persisted by emit_event hook (runtime reason set).
                # #906: Skip means skip — close the platform's tab (guards
                # inside: main/last tab is left open, just unregistered).
                await _close_skipped_agent_tab(browser, p.get("page"), _ag_key, _agent_name)
            elif _agent_name:
                # #912: the agent already left `pending` (an earlier fail/
                # empty/timeout path dropped it with its tab still open,
                # awaiting this very decision) — Skip must still clean up the
                # browser side, not just the marker. Prefer the dispatcher
                # registry (hard retry re-registers its fresh tab there); fall
                # back to the original setup handle. _close_skipped_agent_tab's
                # guards (None / already closed / main / last tab) make a stale
                # handle safe.
                _left_page = (_runtime.active_pages.get(_ag_key)
                              or (agents.get(_agent_name) or {}).get("page"))
                if _left_page is not None:
                    log(f"[{_agent_name}] Skipped by user after leaving the poll "
                        "set — closing its leftover tab", "INFO")
                    await _close_skipped_agent_tab(browser, _left_page, _ag_key, _agent_name)
                # #921 incident-1: an agent that left `pending` via an earlier
                # fail_agent carries a persisted status="errored" (red ✕ tile).
                # Skipping it here used to ONLY close the tab — no agent_skipped,
                # no terminal-status write — so the tile stayed red ✕ forever
                # (the FE tile binds to the persisted agents[key].status; the
                # optimistic "Skipping…" card rides a layer the tile ignores),
                # and the user re-clicked Skip to no visible effect. Emit
                # agent_skipped so the emit_event hook flips the persisted
                # status errored→skipped (greying the tile) AND retracts the
                # card's durable pendingDecision mirror — a single Skip now
                # resolves. Guard: never overwrite a genuinely-COMPLETE agent
                # (a stale/duplicate skip command must not grey a green ✓ tile).
                # #953 defense-in-depth (audit): check BOTH the persisted map
                # (now poison-proof — 'running' can't overwrite 'complete') AND
                # the in-scope results dict (status 'done' + text) — either
                # proving completion vetoes the skip clobber.
                _recorded_status = (_agent_status_by_rid.get(_fb_research_id, {})
                                    or {}).get(_ag_key)
                _left_results = results.get(_agent_name) or {}
                _left_done = (_left_results.get("status") == "done"
                              and bool(_left_results.get("text")))
                if _recorded_status != "complete" and not _left_done:
                    if isinstance(_left_results, dict) and _left_results:
                        _left_results["status"] = "skipped_by_user"
                    emit_event("agent_skipped", phase=2, agent=_ag_key,
                               reason="user_skip_after_leaving_poll")
                else:
                    log(f"[{_agent_name}] Skip after leaving poll — agent already "
                        f"completed (persisted={_recorded_status!r}, results_done="
                        f"{_left_done}); keeping the report, not greying the tile", "INFO")
            # Whether or not the agent was actually in pending, clear it from
            # the skip set so we don't keep firing agent_skipped every tick.
            _controls.consume_skip_marker(_ag_key)

        # ── Hard retry (close tab + re-run setup from scratch) ──
        # Unlike the soft retry (pastes a follow-up into the same tab and
        # extends the budget — handled per-agent in the timeout branch
        # below), hard retry throws away the tab and starts the agent
        # fresh. Use when the session died or the tab is otherwise
        # unrecoverable. Other agents keep running untouched.
        _hard_name_map = {"chatgpt": "ChatGPT", "gemini": "Gemini", "claude": "Claude"}
        for _agent_key in ("chatgpt", "gemini", "claude"):
            # #953 (audit): a PARKED agent (session-expiry / empty-extraction /
            # missing-artifact card) owns its own retry marker — the non-blocking
            # parked-decision resolver consumes it and runs the SOFT action
            # (reload / re-extract / nudge). The FE Retry button sends mode=hard,
            # so without this guard the loop-top hard-retry consumer would drain
            # that marker FIRST and do a full setup restart (re-run the whole
            # research from scratch, discarding a finished-but-unread report) —
            # the opposite of what these cards intend. Skip parked agents here
            # WITHOUT consuming, leaving the marker for the resolver.
            _pk_name = _hard_name_map.get(_agent_key)
            if _pk_name and (pending.get(_pk_name) or {}).get("awaiting_decision"):
                continue
            if not _controls.consume_retry_agent_hard(_agent_key):
                continue
            # #955 Phase 2: an explicit hard retry resolves the card and restarts
            # the agent from scratch (fresh `pending` entry, new clock). Drop any
            # stale stuck deadline now so _fire_due_autoskips can't auto-skip the
            # freshly-restarted agent off the OLD (already-passed) deadline.
            _disarm_registry(_agent_key)
            _agent_name = _hard_name_map.get(_agent_key)
            if not _agent_name:
                continue
            # #953 (2026-07-13 run): a Retry click races completion. The user
            # clicked "Retry (hard)" on a (false) failure card while Gemini was
            # mid-research; the marker was consumed at 19:03:47 — the very
            # second extraction finished recording 101k chars — and this path
            # then CLOSED the completed agent's tab, re-ran setup with an empty
            # brief (fired an honest-at-the-time "couldn't send the brief"
            # card), and the eventual skip clobbered the good result with a
            # 0-char skipped_by_user. A hard retry against an agent that
            # already has a recorded successful result is ALWAYS stale — drop
            # it and retract the card it came from.
            _rec_done = results.get(_agent_name) or {}
            _persisted_st = (_agent_status_by_rid.get(_fb_research_id, {})
                             or {}).get(_agent_key)
            # #953 (audit): also treat an agent that is MID-COMPLETION as done —
            # the done-marker/extraction window spans several minutes and the
            # recorded result appears only at its END. A Retry consumed inside
            # that window (the exact 19:03:47 timing) would otherwise pass the
            # recorded-result check, close the tab, and destroy the run. The
            # live poll signals (`done_marker_first_at`, `done_count`) flag it.
            _p_inflight = pending.get(_agent_name) or {}
            _inflight_done = inflight_looks_done(_p_inflight)
            # #953 (audit fold-in, race-safe): a Skip is a TERMINAL decision and
            # must supersede a co-queued Retry. When a parked agent is skipped
            # AND hard-retried in the same tick, the loop-top skip consumer
            # finalizes it FIRST (results status skipped_by_user/auto_skipped +
            # persisted 'skipped', removed from pending), so this guard — running
            # later in the SAME tick on the SAME (loop) thread — sees that
            # terminal state and drops the stale retry instead of resurrecting a
            # fresh setup. (This replaces an earlier attempt to drain the retry
            # marker inside consume_skip_marker, which raced the command thread's
            # deferred request_retry_agent_hard and could silently lose a
            # legitimate pre-failed retry.) Setup-FAILURE statuses
            # (failed_setup / not_verified / hard_retry_* / interrupted) stay
            # retryable — only completed / skipped outcomes block.
            _rec_status = (_rec_done.get("status") or "").lower()
            _terminal_skip = (_persisted_st == "skipped"
                              or _rec_status in ("skipped_by_user", "auto_skipped"))
            if (_persisted_st == "complete"
                    or (_rec_done.get("status") == "done" and (_rec_done.get("text") or ""))
                    or _inflight_done
                    or _terminal_skip):
                log(f"[{_agent_name}] Hard retry ignored — the agent already "
                    f"completed, is finishing, or was skipped (persisted={_persisted_st!r}, "
                    f"recorded={_rec_done.get('status')!r}, "
                    f"{len(_rec_done.get('text') or '')} chars, inflight_done={_inflight_done}, "
                    f"terminal_skip={_terminal_skip}). Clearing the stale card instead.", "INFO")
                try:
                    emit_event("pipeline_warning", phase=2, agent=_agent_key,
                               error=f"{_agent_name} already finished",
                               details=f"{_agent_name} completed its research before the retry "
                                       "was processed — nothing to retry.",
                               actions=[], alert_id=_agent_error_alert_id(_agent_key, 2),
                               auto_clear_on_resume=True)
                    _clear_pending_decision(_agent_key)
                except Exception:
                    pass
                # 2026-08-02: the card this just retracted is gone from the UI, so
                # the "already raised it" latch must go with it. Leaving it set
                # means a LATER failure on the same agent parks in silence — the
                # error branch skips fail_agent entirely when the latch is on, so
                # there would be a countdown running against no visible card.
                _p_inflight["failed_alert_emitted"] = False
                continue
            # 2026-04-25: when an agent failed pre-pending (setup/paste
            # failed during initial Phase 2 startup), `pending` won't have
            # an entry for it. Seed a stub so the hard-retry codepath below
            # can run from scratch. hard_retry_count starts at 0 since
            # there was no prior attempt counted.
            if _agent_name not in pending:
                # Recover the agent's still-open tab so Gap #3's warm-tab reuse can
                # engage. An agent DROPPED from rotation (e.g. the CUA ERROR verdict)
                # hands its page to `results[name]["page"]` and is never closed, so the
                # warm, challenge-passed tab is usually still alive. Seeding
                # "page": None unconditionally is what forced the 2026-07-27 Claude
                # hard retry onto a COLD claude.ai load — a Cloudflare bot-score event,
                # the same cost that made P1/P2 share one ChatGPT tab — even though
                # reuse was already wired and platform-aware: it keys on p["page"],
                # which the stub had erased. Falls back to a fresh tab if the page is
                # gone, and hard retry #2 still forces a clean slate.
                _stub_page = None
                try:
                    _prev = results.get(_agent_name) or {}
                    _cand = _prev.get("page")
                    if _cand is not None and not _cand.is_closed():
                        _stub_page = _cand
                except Exception:
                    _stub_page = None
                log(f"[{_agent_name}] Hard retry requested for agent that failed "
                    f"pre-pending — seeding pending stub"
                    f"{' (recovered its still-open tab)' if _stub_page else ''}", "INFO")
                pending[_agent_name] = {
                    "page": _stub_page,
                    "url": "",
                    "start_time": time.time(),
                    "done_count": 0,
                    "cua_confirmed": False,
                    "last_heartbeat": time.time(),
                    "last_cua_check": time.time(),
                    "last_artifact_scrape": 0,
                    "chatgpt_activity_panel_open": False,
                    "poll_cycles": 0,
                    "chatgpt_panel_dom_misses": 0,
                    "chatgpt_panel_cua_attempts": 0,
                    "claude_artifact_dom_misses": 0,
                    "claude_artifact_cua_attempts": 0,
                    "observer_text_len": 0,
                    "empty_retries": 0,
                    "hard_retry_count": 0,
                    "claude_clarification_replied": False,
                }
            p = pending[_agent_name]
            _hard_count = int(p.get("hard_retry_count", 0)) + 1
            # Cap: 2 hard retries per agent per phase. Above the cap we
            # used to fall through to soft retry (follow-up in same tab),
            # but: (a) if the tab is dead, soft retry is a silent no-op
            # because there's no live page to paste into, and (b) the
            # retry_agents set has no consumer in the P2 main loop, so
            # even with a live tab the soft-retry path was effectively
            # dead. Dead-tab guard surfaces fail_agent so the agent
            # doesn't sit in pending forever.
            if _hard_count > 2:
                _tab_dead = False
                try:
                    _old_p = p.get("page")
                    _tab_dead = (_old_p is None or _old_p.is_closed())
                except Exception:
                    _tab_dead = True
                if _tab_dead:
                    log(f"[{_agent_name}] Hard retry cap + dead tab — failing agent", "WARN")
                    fail_agent(_agent_key,
                               f"{_agent_name} couldn't recover",
                               f"{_agent_name} kept failing and its browser tab "
                               "closed. Retry to start it fresh, or Skip it and "
                               "keep the others.")
                    del pending[_agent_name]
                    results[_agent_name] = {
                        "status": "hard_retry_exhausted_dead_tab",
                        "text": "", "url": "", "page": None, "elapsed_sec": 0}
                    continue
                log(f"[{_agent_name}] Hard retry cap hit (tab still alive) — queuing soft retry", "WARN")
                _controls.retry_agents.add(_agent_key)
                continue
            log(f"[{_agent_name}] Hard retry #{_hard_count} — closing tab, re-running setup", "WARN")
            # Resolve the brief from runtime state (populated before Phase 2 kicks
            # off at line ~10050: `_runtime.original_inputs = {..., 'brief': ...}`).
            _brief_text_hr = _runtime.original_inputs.get("brief") or ""
            _brief_path_hr = None
            if _tracks_dir:
                _bp = Path(__file__).parent / "queues" / _tracks_dir.name / "documents" / "brief.md"
                if _bp.exists():
                    _brief_path_hr = str(_bp)
            # #953: original_inputs carries 'brief' only on the brief-provided
            # start path (research.py:~39749); the full-pipeline path (~39230)
            # stores topic+pdf_paths and P1 WRITES the brief to disk later. The
            # 2026-07-13 hard retry pasted a 0-char brief into Gemini ("Paste
            # verify: 1/0 chars") and manufactured a "couldn't send the brief"
            # failure. Fall back to the on-disk brief.md (the same file the
            # attach path sends) so a retry always carries the real brief.
            if not _brief_text_hr and _brief_path_hr:
                try:
                    _brief_text_hr = Path(_brief_path_hr).read_text(encoding="utf-8")
                    log(f"[{_agent_name}] Hard retry: brief text recovered from disk "
                        f"({len(_brief_text_hr)} chars — original_inputs had none)", "INFO")
                except Exception as _bre:
                    log(f"[{_agent_name}] Hard retry: brief.md read failed ({_bre})", "WARN")
            old_page = p.get("page")
            # Gap #3 (2026-07-15): reuse the warm, challenge-passed tab for the
            # restart (same-tab New chat) instead of a cold load, which is a
            # Cloudflare bot-score event. Fall back to a FRESH tab when the page
            # is dead/closed, or on hard-retry #2 (wedged-DOM escape hatch →
            # guaranteed clean slate). This reverses the old "retries always
            # pass None" stance but keeps the clean-slate hatch on #2.
            _reuse_page = None
            if old_page is not None and _hard_count < 2:
                try:
                    if not old_page.is_closed():
                        _reuse_page = old_page
                except Exception:
                    _reuse_page = None
            if _reuse_page is not None:
                log(f"[{_agent_name}] Hard retry #{_hard_count}: reusing the warm "
                    "tab (same-tab New chat) — no cold navigation", "INFO")
            else:
                # Fresh-tab fallback (dead page, or the #2 escape hatch). Close
                # the old tab, honoring the main/last-tab guard (2026-07-06
                # review): NEVER close browser.page or the persistent context's
                # LAST page — doing so drops the main handle / exits headful
                # Chrome, and the restart's new_tab then dies on a closed
                # context. Leaving it open is harmless — the restart opens a
                # fresh one.
                try:
                    if old_page is not None:
                        _keep_open = old_page is getattr(browser, "page", None)
                        if not _keep_open:
                            try:
                                _keep_open = len(old_page.context.pages) <= 1
                            except Exception:
                                _keep_open = False
                        if _keep_open:
                            log(f"[{_agent_name}] Hard retry: keeping the old tab open "
                                "(main/last tab) — the restart opens a fresh one", "INFO")
                        else:
                            await old_page.close()
                except Exception:
                    pass
            # Re-run agent setup. On crash, drop the agent from pending so
            # the phase can proceed with whoever else is still healthy.
            try:
                restart = await _restart_phase2_agent(
                    _agent_name, browser, cua_client,
                    _brief_text_hr, _brief_path_hr, verbose,
                    reuse_page=_reuse_page)
            except Exception as _e:
                log(f"[{_agent_name}] Hard retry setup crashed: {_e}", "ERROR")
                fail_agent(_agent_key, f"{_agent_name} couldn't restart", f"{_agent_name} hit an error while restarting. Retry to try again, or Skip it.")
                del pending[_agent_name]
                results[_agent_name] = {"status": "hard_retry_failed", "text": "",
                                         "url": "", "page": None, "elapsed_sec": 0}
                continue
            if restart is None:
                log(f"[{_agent_name}] Hard retry returned None — dropping agent", "WARN")
                del pending[_agent_name]
                results[_agent_name] = {"status": "hard_retry_failed", "text": "",
                                         "url": "", "page": None, "elapsed_sec": 0}
                continue
            new_page, verified_h = restart
            # Gap #3 leak-guard: if the in-helper reuse threw AFTER the
            # is_closed() check (e.g. a slow same-tab goto timed out), it fell
            # back to a fresh tab, leaving the warm tab we handed in orphaned —
            # two authenticated surfaces persisting until browser close. Close
            # the orphan here, honoring the same main/last-tab guard. No-op on
            # the happy path (new_page IS _reuse_page) and on the fresh-tab
            # branch (_reuse_page is None).
            if (_reuse_page is not None and new_page is not None
                    and new_page is not _reuse_page):
                try:
                    _keep_open = _reuse_page is getattr(browser, "page", None)
                    if not _keep_open:
                        try:
                            _keep_open = len(_reuse_page.context.pages) <= 1
                        except Exception:
                            _keep_open = False
                    if not _keep_open and not _reuse_page.is_closed():
                        log(f"[{_agent_name}] Hard retry: reuse fell back to a fresh "
                            "tab — closing the orphaned warm tab", "INFO")
                        await _reuse_page.close()
                except Exception:
                    pass
            # If the restart's setup/paste failed (verified_h False AND we
            # got a non-verified page back from start_agent_no_gemini_wait
            # ok=False), the helper already emitted pipeline_error with
            # Retry/Skip actions. Drop the agent from pending so the user's
            # next Retry click cleanly re-seeds via the pre-pending path
            # above.
            if not verified_h:
                # verified_h could legitimately be False if generation
                # verification didn't land within the window — that's the
                # benign case the WARN below handles. But if start_agent
                # itself returned ok=False, the page was set up but paste
                # failed — `_restart_phase2_agent` would have returned
                # (page, False) and emitted pipeline_error already. Either
                # way, we keep `pending` populated so polling can retry,
                # but emit a clear status.
                pass
            _now = time.time()
            pending[_agent_name] = {
                "page": new_page,
                "url": new_page.url if new_page else "",
                "start_time": _now,
                "done_count": 0,
                "cua_confirmed": False,
                "last_heartbeat": _now,
                "last_cua_check": _now,
                "last_artifact_scrape": 0,
                "chatgpt_activity_panel_open": False,
                "poll_cycles": 0,
                "chatgpt_panel_dom_misses": 0,
                "chatgpt_panel_cua_attempts": 0,
                "claude_artifact_dom_misses": 0,
                "claude_artifact_cua_attempts": 0,
                "observer_text_len": 0,
                "empty_retries": 0,
                "hard_retry_count": _hard_count,
                "claude_clarification_replied": False,
            }
            _runtime.register_page(_agent_key, new_page,
                                    new_page.url if new_page else "")
            # Gap #1: a hard-retry that landed in chat mode (DR still
            # unavailable) left a chat_mode_pending marker; re-seed the
            # kind="chat_mode" park on the rebuilt entry (a marker on the old `p`
            # would be lost — the _controls-level dict survives the rebuild).
            _cm_hr = _controls.chat_mode_pending.pop(_agent_key, None)
            if _cm_hr:
                pending[_agent_name]["awaiting_decision"] = {
                    "kind": "chat_mode", "key": _agent_key,
                    "since": _cm_hr.get("since", time.time()),
                    "timeout": _cm_hr.get("timeout", 1800.0)}
                log(f"[{_agent_name}] parked kind=chat_mode after hard-retry "
                    "(submitted in chat mode, awaiting keep/skip)", "INFO")
            if verified_h:
                try:
                    await inject_agent_observer(new_page, _agent_key)
                except Exception:
                    pass
                try:
                    # #930: carry stage — the FE just reset this agent's tile on
                    # retry, and a fresh DR legitimately shows 0 sources/0 chars
                    # for minutes. Without stage the milestone stepper re-parks
                    # on "Submitted" until a counter comes alive (never, for a
                    # scrape-blind ChatGPT iframe). verified_h == generation was
                    # re-verified, so "researching" is honest here.
                    emit_event("agent_progress", phase=2, agent=_agent_key,
                               status="generating", stage="researching",
                               progress=f"{_agent_name} restarted (hard retry #{_hard_count}) — running")
                except Exception:
                    pass
                log(f"[{_agent_name}] Hard retry successful ✓")
            else:
                log(f"[{_agent_name}] Hard retry tab opened but not verified yet — polling will re-check", "WARN")

        # ── pro_required ack consumer (Gap #1) ──────────────────────────────
        # The P2 pro_required card is now NON-BLOCKING (no setup-context pause),
        # so "Continue with Free" is resolved HERE, once per tick, before the
        # per-agent leg. Agent-scoped (pro_ack_agents / free_tier_consent /
        # per-agent alert clear) so two simultaneous pro cards (ChatGPT + Gemini
        # both Free) resolve INDEPENDENTLY — a Free-accept on one never dismisses
        # or Free-consents the other (Finding 1). Skip needs no consumer here:
        # skip_pro → skip_agent → the existing skip path greys + closes the tab.
        for _pn in list(pending.keys()):
            _pk = normalize_agent_key(_pn)
            if _controls.consume_pro_continue_free(_pk):
                _controls.free_tier_consent[_pk] = True
                # Agent-scoped clear (NOT the global pro_warning_acknowledged,
                # which would suppress + sweep the sibling's still-live card).
                _clear_pro_required_alerts(triggered_at_phase=2, agent=_pk)
                # pipeline_resumed triggers the FE auto-clear sweep of the
                # transient _clear_pro_required_alerts just emitted (nothing is
                # BE-paused in the non-blocking model — this is FE housekeeping).
                emit_event("pipeline_resumed", phase=2, agent=_pk,
                           reason="continue_with_free")
                log(f"[round-robin] pro_required ack consumed for {_pk} — Free "
                    "accepted, agent stays live, card cleared", "INFO")

        # Rotate iteration order so no agent is always "first". With 3
        # agents, the order cycles A→B→C, B→C→A, C→A→B, A→B→C, ensuring
        # that over 3 ticks every agent has been processed first.
        # #905: shift is (_tick_counter - 1) so CYCLE 1 runs in insertion
        # order — ChatGPT → Claude → Gemini — i.e. "open both source panels
        # first, then come back to check Gemini" (2026-07-06 user directive).
        # The old `_tick_counter %` made tick 1 start at Claude.
        _pending_keys = list(pending.keys())
        if _pending_keys:
            _shift = (_tick_counter - 1) % len(_pending_keys)
            _pending_keys = _pending_keys[_shift:] + _pending_keys[:_shift]

        # #905 "60 secs at each platform": each platform KEEPS the foreground
        # for ~60s after its leg (interruptible on stop/pause/skip/retry),
        # instead of the old all-legs-back-to-back + one flat 120s sleep
        # parked on whichever agent happened to be last. Cycle 1 runs with NO
        # dwell — its whole job is opening the panels + re-checking Gemini
        # immediately after "Start research".
        async def _leg_dwell():
            try:
                _dwell_target = int(os.environ.get("P2_AGENT_DWELL_SEC", "60"))
            except ValueError:
                _dwell_target = 60
            # Fast cadence once any agent shows a done-marker (mirrors the
            # old 30s-when-done cycle sleep — the 2-snapshot confirm gate
            # wants a quick second tick).
            if any(pp.get("done_marker_first_at", 0.0) > 0.0 for pp in pending.values()):
                _dwell_target = 10
            _dw0 = time.time()
            while time.time() - _dw0 < _dwell_target:
                # ⭐ 2026-08-05 — a QUEUED DECISION cuts the dwell. Stop, pause,
                # Skip and hard-Retry already did; every other answer the user can
                # give a card — Continue in chat mode, soft retry, wait longer,
                # continue with partial — did not, because none of them pauses the
                # pipeline, so the dispatcher's request_resume is a no-op and the
                # decision simply waited for the rotation to come back around.
                #
                # With three agents the rotation costs 3 x P2_AGENT_DWELL_SEC of
                # dwell alone, so "I clicked and nothing happened for two and a
                # half minutes" was the designed behaviour (prod 2026-08-05:
                # 07:31:49 command → 07:34:21 resolve, 152s).
                if (_controls.is_stop() or _controls.is_pause()
                        or _controls.skipped_agents or _controls.retry_agents_hard
                        or _controls.pending_agent_decision):
                    return
                # ⭐ …and so does a park whose OWN deadline just ran out. The
                # auto-skip window had no actor scheduled to fire at its epoch:
                # the web app's countdown is display-only (it renders
                # "Auto-skipping…" at zero and sends nothing), and the backend
                # read the window once per full rotation. On 2026-08-05 the
                # deadline fell at 07:31:34 and the earliest the backend could
                # have looked was 07:34:21 — so the owner watched a timer reach
                # zero and stay there. Sampling here bounds the lateness to this
                # loop's own 5s cadence instead of the rotation's minutes.
                #
                # ⚠ `park_window_elapsed(None)` returns TRUE (an absent `since`
                # defaults to 0, and now-0 clears any window), so an entry with
                # no park MUST be excluded before asking. Sweeping unguarded
                # would end every dwell immediately.
                if any(pp.get("awaiting_decision")
                       and park_window_elapsed(pp["awaiting_decision"])
                       for pp in pending.values()):
                    return
                await asyncio.sleep(min(5.0, max(0.1, _dwell_target - (time.time() - _dw0))))

        _first_leg_of_tick = True
        for name in _pending_keys:
            # Dwell on the PREVIOUS platform before moving here (cycle 1 and
            # the first leg of every tick run immediately — the tick's own
            # trailing dwell already paced the rotation).
            if not _first_leg_of_tick and _tick_counter > 1:
                await _leg_dwell()
                if _controls.is_stop() or _controls.is_pause():
                    break
            _first_leg_of_tick = False
            if name not in pending:
                continue  # dropped by a signal handled mid-tick
            p = pending[name]
            elapsed = time.time() - p["start_time"]

            # ── Gap #1 defense-in-depth (HV never-touch) ──────────────────────
            # A verification-walled agent must NEVER reach the poll body's page
            # interactions (switch_to_page, spotlight/scrape evaluate, CUA
            # vision) — each re-issues the challenge and RAISES the bot score.
            # The setup path hands walls off before they enter pending, but a
            # hard-retry that HITS a wall can re-seed a walled page here (with
            # auto-skip off it isn't in skipped_agents, so the loop-top consumer
            # doesn't catch it). hv_blocked is cleared on any clean nav, so a
            # still-set verdict means genuinely walled. Bail BEFORE any touch:
            # finalize (grey + close) when auto-skip is on, else just idle the
            # leg (card stays up for a manual Skip). Either way, zero wall touch.
            _leg_hv_key = normalize_agent_key(name)
            if _leg_hv_key in _controls.hv_blocked and not p.get("awaiting_decision"):
                if _runtime.auto_skip_stuck:
                    log(f"[{name}] walled tab (hv_blocked) reached the poll leg — "
                        "hands-off skip (grey + close), never touching the wall", "WARN")
                    await _hv_auto_skip_finalize(browser, p.get("page"), _leg_hv_key, name, phase=2)
                    results[name] = {"status": "skipped_auto_hv", "text": "",
                                     "url": p.get("url", ""), "page": None,
                                     "elapsed_sec": int(elapsed)}
                    if name in pending:
                        del pending[name]
                else:
                    log(f"[{name}] walled tab (hv_blocked) — idling the poll leg "
                        "(auto-skip off; Skip-only card stays up, wall untouched)", "DEBUG")
                continue

            # ── #953 (audit): NON-BLOCKING parked-decision resolver ──
            # A per-agent decision card (session expiry, empty extraction,
            # missing artifact) used to `await await_agent_decision(...)` INSIDE
            # this leg — which froze the WHOLE round-robin (no other agent
            # polled, no completion detected, no skip/retry consumed) for up to
            # 30 minutes: the same "one agent's dwell starves the others" class
            # as the 2D incident. Those sites now PARK the agent
            # (p['awaiting_decision']) and `continue`; this resolver checks the
            # decision ONCE per tick so the OTHER agents keep polling while this
            # one waits. Skip is handled upstream by the loop-top skip consumer
            # (it finalizes any pending agent), so the crash sweep / skip / hard-
            # retry consumers all still see a parked agent normally — the resolver
            # only handles retry / wait / stop / its own park-deadline timeout.
            _parked = p.get("awaiting_decision")
            if _parked:
                _pk_key = _parked.get("key") or normalize_agent_key(name)
                # #953 (audit #5): the absolute per-agent hard cap must bite even
                # while parked — otherwise a re-parking kind (session_expiry 1800s
                # / extract_empty_pw 600s keeps polling on timeout, then re-parks)
                # can ride up to one park window PAST the 90-min ceiling. Force an
                # auto-skip finalize (salvage + grey tile + close tab) at the cap.
                if elapsed >= PER_AGENT_HARD_CAP_SEC:
                    log(f"[{name}] Parked agent hit the {PER_AGENT_HARD_CAP_SEC}s hard "
                        "cap — auto-skipping (the card went unanswered too long)", "WARN")
                    p["awaiting_decision"] = None
                    _hc_partial = ""
                    if _pk_key not in _controls.hv_blocked:
                        try:
                            await browser.switch_to_page(p["page"])
                            _hc_partial = await extract_fns[name](
                                p["page"], browser=browser, cua_client=cua_client,
                                label=name, verbose=verbose) or ""
                        except Exception:
                            _hc_partial = ""
                    # #955: one finalize shape for every auto-skip.
                    await _finalize_agent_autoskip(
                        browser, p.get("page"), _pk_key, name,
                        reason="auto_skip_hard_cap",
                        copy_key="hard_cap_parked",
                        partial=_hc_partial, url=p.get("url", ""),
                        elapsed_sec=int(elapsed),
                        results=results, results_name=name)
                    _disarm_registry(_pk_key)   # #955 P2: purge any stale deadline
                    if name in pending:
                        del pending[name]
                    continue
                _pk_dec = _controls.poll_agent_decision(_pk_key)
                if _pk_dec == "stop":
                    break
                # 2026-08-02: a park window of 0 means NO DEADLINE (see
                # park_window_elapsed) — the mid-run error park sets it when the
                # user turned auto-skip OFF, and the old inline `>= timeout`
                # comparison would have expired it on the very first tick.
                _pk_expired = (_pk_dec == "pending" and park_window_elapsed(_parked))
                if _pk_dec == "pending" and not _pk_expired:
                    continue  # still waiting on the user — do NOT block the loop
                # A decision arrived (or the park window elapsed) — clear the
                # park and act. 'skip' is defensive (the loop-top consumer
                # normally finalizes first); treat it as keep-in-set so that
                # consumer resolves it next tick.
                p["awaiting_decision"] = None
                _pk_kind = _parked.get("kind", "")
                _pk_action = _pk_dec if _pk_dec != "pending" else "timeout"
                log(f"[{name}] Parked decision resolved (kind={_pk_kind}, action={_pk_action})", "INFO")
                if _pk_dec == "skip":
                    # Re-arm the marker path: leave the skip marker for the
                    # loop-top consumer (already consumed here → re-request so it
                    # finalizes with the standard partial-extract + tab close).
                    _controls.request_skip_agent(_pk_key)
                    continue
                _pk_handled = await _resolve_parked_agent_decision(
                    _pk_kind, _pk_action, p, name, _pk_key, elapsed,
                    browser, cua_client, results, pending, extract_fns,
                    max_wait_min, verbose=verbose)
                if _pk_handled == "break":
                    break
                continue

            # Per-agent cycle counter (used for "give research time to settle"
            # gate before opening Claude/ChatGPT panels — see iter-#3 logic
            # below). Increment ONCE per round-robin tick per agent.
            p["poll_cycles"] = p.get("poll_cycles", 0) + 1

            # ── C6: cursor foreground + partial-content refresh ──
            # Bring this agent's tab to the front before any scrape/check so
            # its MutationObserver has the freshest token stream (Chromium
            # throttles background tabs less under Playwright than a normal
            # browser, but foregrounding still produces materially fresher
            # data — especially after a long blocking await on another agent).
            try:
                await browser.switch_to_page(p["page"])
            except Exception as _sw_err:
                log(f"[{name}] switch_to_page at cursor start failed: {_sw_err}", "WARN")

            # A4 (2026-05-01): visible spotlight — DOM Range select on the
            # latest response paragraph so the user can SEE the round-robin
            # land on this agent. Symmetric across all 3 (Claude already
            # had a CUA-side-effect "highlight" via artifact panel open;
            # this gives ChatGPT/Gemini matching visibility without the
            # ~$0.05/round CUA cost). Throttled to once per 30s/agent so
            # it doesn't fight rapidly with the user's manual selection.
            _last_spotlight = p.get("last_spotlight_at", 0)
            if (time.time() - _last_spotlight) > 30:
                p["last_spotlight_at"] = time.time()
                try:
                    await _spotlight_latest_response(p["page"], name)
                except Exception:
                    pass

            # #905: deferred Gemini start-verify — 2D hands off right after a
            # confirmed "Start research" click so cycle 1 can open the other
            # panels first; this leg closes the loop ("come back to check
            # Gemini is all good"). Cheap DOM probe, retried each cycle until
            # it flips (the detectors + wall-clock cap cover a never-started
            # plan exactly as for any other not-verified agent).
            if name == "Gemini" and p.get("needs_start_verify"):
                try:
                    if await verify_gemini_generating(p["page"]):
                        p["needs_start_verify"] = False
                        p["gemini_running_confirmed"] = True
                        emit_event("agent_progress", phase=2, agent="gemini",
                                   status="generating", stage="researching",
                                   progress="Gemini Deep Research plan created and started")
                        log("[2D] Gemini is researching ✓ (confirmed on round-robin re-check)")
                        # ⭐ 2026-08-17 — retract the plan-stall card HERE too.
                        # 2D stopped retracting on a click that merely returned
                        # true (it claimed a start the verify disagreed with six
                        # seconds later), which left one gap: a click that DID
                        # work but verified a beat too late. This is where that
                        # verification lands, so it is where the card's claim
                        # becomes true. Same alert_id, so it is the same
                        # retraction and a no-op if 2D already did it.
                        try:
                            emit_event("pipeline_warning", phase=2, agent="gemini",
                                       error="Gemini's research plan started",
                                       details="Gemini recovered and began its deep research.",
                                       actions=[],
                                       alert_id=_agent_error_alert_id("gemini", 2),
                                       auto_clear_on_resume=True)
                            _clear_pending_decision("gemini")
                        except Exception:
                            pass
                        try:
                            await inject_agent_observer(p["page"], "gemini")
                        except Exception:
                            pass
                except Exception:
                    pass

            # #953: late-Start watch — 2D handed off a still-streaming Gemini
            # (auto-started research OR a slow plan still drafting). Each
            # Gemini leg:
            #   (a) research genuinely running/done (the "Researching N …" card
            #       or completion line, or a CUA done-confirm) → clear the watch
            #       (auto-start case — the plan bubble's Start stays grayed
            #       forever; nothing to click). Uses research-SPECIFIC evidence,
            #       NEVER verify_gemini_generating alone — that green-lights a
            #       plan still DRAFTING too, which would clear the watch on a
            #       slow plan and leave its late Start unclicked (audit #953-1).
            #   (b) else an ENABLED 'Start research' has rendered (slow plan
            #       finished drafting after hand-off, and nobody else clicks it)
            #       → click it (bounded, enabled-only so it can never spam the
            #       grayed button), keep the watch ARMED so the NEXT leg's
            #       (a)/(b) is the took-check (audit #953-4), rebase the
            #       wall-clock on the first click.
            #   (c) else the plan is still drafting (streaming, no enabled Start
            #       yet) → leave the watch armed and wait.
            if name == "Gemini" and p.get("gemini_watch_start"):
                try:
                    _ws_running = (p.get("done_count", 0) > 0
                                   or await _gemini_research_started(p["page"]))
                    if _ws_running:
                        p["gemini_watch_start"] = False
                        p["gemini_running_confirmed"] = True
                        log("[Gemini] Watch-start: research is running/complete "
                            "(auto-started without a Start click) — watch cleared ✓")
                        emit_event("agent_progress", phase=2, agent="gemini",
                                   status="generating", stage="researching",
                                   progress="Gemini started its research — monitoring")
                        try:
                            await inject_agent_observer(p["page"], "gemini")
                        except Exception:
                            pass
                    else:
                        _enabled_start = await p["page"].evaluate(_GEMINI_START_PRESENT_JS)
                        if _enabled_start:
                            _wc = p.get("gemini_watch_click_count", 0)
                            if _wc < 3:
                                await p["page"].evaluate(_GEMINI_CLICK_START_JS)
                                p["gemini_watch_click_count"] = _wc + 1
                                log(f"[Gemini] Watch-start: late 'Start research' appeared "
                                    f"— clicked #{_wc + 1}/3 (watch stays armed; next leg "
                                    "verifies it took)")
                                if _wc == 0:
                                    # Research starts NOW — rebase the wall-clock
                                    # once so completion checks don't fire early.
                                    _now_ws = time.time()
                                    p["start_time"] = _now_ws
                                    p["last_heartbeat"] = _now_ws
                                    p["last_growth_time"] = _now_ws
                            else:
                                # An enabled Start persisted after 3 clicks — give
                                # up the watch; the stuck arbiter / 90-min cap
                                # backstops a plan that won't start.
                                p["gemini_watch_start"] = False
                                log("[Gemini] Watch-start: enabled 'Start research' "
                                    "persisted after 3 clicks — clearing watch "
                                    "(arbiter/hard-cap takes over)", "WARN")
                        # else (c): plan still drafting — leave the watch armed.
                except Exception as _ws_err:
                    log(f"[Gemini] Watch-start probe failed (non-fatal): {_ws_err}", "DEBUG")

            # ── Claude interactive question card → Skip (#953) ──
            # Presence-driven, every Claude leg: the Opus 4.8 research flow
            # can raise a "1 of N" question card (numbered options + Skip)
            # instead of starting research; the card sits until answered or
            # skipped. Click Skip for every question (user directive) so the
            # research launches. Cheap DOM probe; a page with no card is a
            # single evaluate. On skips, rebase the wall-clock (research
            # starts NOW) — same reset rationale as the text-clarification
            # block below.
            # Cumulative bound (audit #953-2): a card that keeps yielding new
            # EFFECTIVE skips forever (pathological) must not rebase the
            # wall-clock + `continue` past the completion/timeout backstops on
            # every tick. After this many total skips, stop intervening and let
            # the normal flow (completion detectors, stuck arbiter, hard cap)
            # re-engage — Claude's real card is 1-of-2 / 1-of-3, never dozens.
            _Q_SKIP_TOTAL_CAP = 8
            if name == "Claude" and p.get("question_card_skips", 0) < _Q_SKIP_TOTAL_CAP:
                try:
                    _q_skips = await _claude_skip_question_cards(p["page"], name)
                except Exception:
                    _q_skips = 0
                if _q_skips:
                    p["question_card_skips"] = p.get("question_card_skips", 0) + _q_skips
                    emit_event("agent_progress", phase=2, agent="claude",
                               status="generating",
                               progress=f"Claude asked {_q_skips} clarifying question(s) — "
                                        "skipped them so the research starts.")
                    _now = time.time()
                    p["start_time"] = _now
                    p["last_heartbeat"] = _now
                    p["last_growth_time"] = _now
                    p["stuck_warned_at"] = 0
                    p["last_artifact_scrape"] = 0
                    continue

            # ── Claude clarification auto-reply (2026-05-18) ──
            # When the brief is vague/template, Claude responds with chat
            # text asking clarifying questions INSTEAD of starting Deep
            # Research. Without this block the BE would wait for an
            # artifact that never appears and eventually surface a generic
            # "Hit a snag" alert at the wall-clock cap.
            #
            # 5 conjoint conditions (all must hold) — tight enough that a
            # real research-in-progress response can't false-fire:
            #   (1) name == "Claude" and not already replied for this agent
            #   (2) 180s ≤ elapsed ≤ 900s (clarifications come fast; if
            #       research already started by 15min we shouldn't intervene)
            #   (3) verify_claude_generating == False (Claude finished its
            #       chat reply and is idle, not mid-stream)
            #   (4) No artifact / side-panel visible in DOM (research
            #       artifact has NOT appeared yet)
            #   (5) Last assistant message contains ≥2 '?' chars AND its
            #       tail matches _CLAUDE_CLARIFICATION_SIGNOFF_RE (the
            #       "Once you ... I'll launch the research" signature)
            # On match: type "Up to Claude to decide for the best output."
            # + Enter, reset start_time + last_heartbeat so the wall-clock
            # doesn't fire mid-recompose, set one-shot flag, skip rest of
            # tick.
            if (
                name == "Claude"
                and not p.get("claude_clarification_replied")
                # #953: upper bound 900→2700 — the 2026-07-13 run's first
                # Claude poll landed at ~1500s (the Gemini 2D dwell ate the
                # window), so a real clarification stall aged out unhandled.
                # The other four gates (idle, no artifact, ≥2 '?', sign-off)
                # keep a mid/late-research response from false-firing.
                and 180 <= elapsed <= 2700
            ):
                try:
                    if not await verify_claude_generating(p["page"]):
                        # Cheap artifact-panel probe — if a right-side
                        # artifact panel is already open, this isn't a
                        # clarification scenario.
                        #
                        # Bare-aside REMOVED 2026-05-18: Claude.ai's LEFT
                        # navigation ("New chat / Recents / Projects") is
                        # rendered as <aside> and exceeds any reasonable
                        # bbox lower bound, so a bare-aside check would
                        # always match and the no-panel gate would never
                        # be true. Tightened gate ports _PANEL_GATE_JS at
                        # research.py:10639 — must be right-half-of-
                        # viewport, ≥400px wide, and innerText must not
                        # read like nav chrome (≥2 nav markers).
                        try:
                            _has_panel = await p["page"].evaluate(r"""() => {
                                const NAV_MARKERS = /\b(new chat|recents?|projects|search|topic generator|starred|home|chats?\b)\b/i;
                                const _vw = window.innerWidth || document.documentElement.clientWidth;
                                const sels = [
                                    '[class*="artifact-panel" i]',
                                    '[data-testid*="artifact-panel"]',
                                    '[role="complementary"][class*="artifact" i]',
                                    '[class*="right-panel"][class*="artifact" i]',
                                    '[class*="side-panel"][class*="artifact" i]',
                                    'div[class*="artifact"][class*="open" i]'
                                ];
                                const seen = new Set();
                                const candidates = [];
                                for (const s of sels) {
                                    for (const el of document.querySelectorAll(s)) {
                                        if (seen.has(el)) continue;
                                        seen.add(el);
                                        candidates.push(el);
                                    }
                                }
                                for (const el of candidates) {
                                    const r = el.getBoundingClientRect();
                                    if (r.width < 400) continue;
                                    if (r.right < _vw * 0.5) continue;
                                    const head = (el.innerText || '').slice(0, 500);
                                    if (NAV_MARKERS.test(head)) {
                                        let n = 0;
                                        const re = new RegExp(NAV_MARKERS.source, 'gi');
                                        while (re.exec(head) !== null) n++;
                                        if (n >= 2) continue;
                                    }
                                    return true;
                                }
                                return false;
                            }""")
                        except Exception:
                            _has_panel = False
                        if not _has_panel:
                            matched, last_text, q_count = await _claude_asking_clarification(p["page"])
                            if matched and q_count >= 2 and 0 < len(last_text) < 3000:
                                log(f"[{name}] Clarification scenario detected — "
                                    f"sign-off matched, {q_count} '?'s, {len(last_text)} chars. "
                                    f"Auto-sending defer reply.", "INFO")
                                emit_event(
                                    "agent_progress", phase=2, agent="claude",
                                    status="generating",
                                    progress="Claude was asking for clarification — auto-replied to continue research.",
                                )
                                sent = await _claude_send_clarification_reply(p["page"], name)
                                p["claude_clarification_replied"] = True
                                if sent:
                                    # Reset all wall-clock / growth baselines
                                    # so neither the wall-clock nor the no-
                                    # growth watchdog (research.py:~14987,
                                    # requires elapsed>1200 AND no_growth>1200)
                                    # fires a false-positive snag while Claude
                                    # composes the new response. Without
                                    # last_growth_time reset, no_growth_secs
                                    # would carry the clarification-window's
                                    # ~200-900s into the new run and trigger
                                    # the watchdog ~1000s sooner than designed.
                                    _now = time.time()
                                    p["start_time"] = _now
                                    p["last_heartbeat"] = _now
                                    p["last_growth_time"] = _now
                                    p["stuck_warned_at"] = 0
                                    p["last_artifact_scrape"] = 0  # let next tick re-probe
                                    continue
                except Exception as _cer:
                    log(f"[{name}] Clarification-check failed (non-fatal): {_cer}", "DEBUG")

            # ── Gemini kickoff-stall auto-nudge (multi-shot) ──
            # User-observed (2026-05-22 + 2026-05-24): Gemini ACKs "Great,
            # I'm on it" but the "Researching N sources" / "Researching
            # websites..." card never appears — silently stalls. A single
            # polite nudge ("Please proceed with the deep research now.")
            # sometimes works but Gemini also sometimes ignores it
            # (observed in the 2026-05-24 E2E), and the user had to
            # manually type "Done?" to unstick. Multi-shot with escalating
            # wording across attempts hardens against this:
            #   - Nudge 1 (polite directive)       at ~45s
            #   - Nudge 2 (yes/no check-in)        at ~225s (180s spacing)
            #   - Nudge 3 (terse, "Done?")         at ~405s (180s spacing)
            # All three fit inside the 600s outer cap, well before the
            # 20-min general no-growth watchdog at research.py:~17441
            # takes over.
            #
            # Gates (all must hold):
            #   - name == Gemini
            #   - nudge count < 3
            #   - 45s ≤ elapsed ≤ 600s (since last reset)
            #   - either no prior nudge OR ≥180s since the last one
            if (
                name == "Gemini"
                and p.get("gemini_kickoff_nudge_count", 0) < len(_GEMINI_KICKOFF_NUDGES)
                and 45 <= elapsed <= 600
                and (
                    p.get("gemini_last_kickoff_nudge_at", 0.0) == 0.0
                    or (time.time() - p.get("gemini_last_kickoff_nudge_at", 0.0)) >= 180
                )
            ):
                try:
                    pending_kickoff, reason = await _gemini_kickoff_pending(p["page"])
                    if pending_kickoff:
                        attempt_idx = p.get("gemini_kickoff_nudge_count", 0)
                        total = len(_GEMINI_KICKOFF_NUDGES)
                        log(f"[{name}] Kickoff-stall detected ({reason}) — "
                            f"sending nudge #{attempt_idx + 1}/{total}.", "INFO")
                        emit_event(
                            "agent_progress", phase=2, agent="gemini",
                            status="generating",
                            progress=(
                                f"Gemini stalled after ACK — auto-nudge "
                                f"#{attempt_idx + 1}/{total} to start research."
                            ),
                        )
                        sent = await _gemini_send_kickoff_nudge(
                            p["page"], name, attempt_idx=attempt_idx,
                        )
                        p["gemini_kickoff_nudge_count"] = attempt_idx + 1
                        p["gemini_last_kickoff_nudge_at"] = time.time()
                        if sent:
                            # #955 Phase 2G: a kickoff nudge is a genuine recovery
                            # prod, but it must NOT reset start_time /
                            # last_growth_time / stuck_warned_at. Doing so deferred
                            # the unified stall-detection + auto-skip by up to
                            # ~7 min PER nudge (3 nudges ⇒ the 15-min stuck arbiter
                            # AND the 90-min absolute hard cap never accumulated),
                            # masking a Gemini that never answers the prod. The
                            # nudge fires early (45-600s); if it works, real growth
                            # advances last_growth_time on its own; if not, the
                            # stuck arbiter cards at 15-min no-growth and the hard
                            # cap stays absolute from the real research start. Only
                            # the FE liveness heartbeat is refreshed — the nudge IS
                            # backend activity and must not trip the dead-backend
                            # watchdog — never the growth / stall clocks.
                            p["last_heartbeat"] = time.time()
                            continue
                except Exception as _gke:
                    log(f"[{name}] Gemini-kickoff-check failed (non-fatal): {_gke}", "DEBUG")

            # #921 (2026-07-08): the per-agent wall-clock cap is BACK, as the
            # Layer-3 auto-skip above (PER_AGENT_HARD_CAP_SEC). It was removed
            # 2026-05-04 on the assumption the no-growth watchdog caught stalls
            # "within ~20 min" — but the 2026-07-08 stale runs proved that gate
            # (`_cua_check_age > 1200`) never fired, so a genuinely-stuck agent
            # rode with NO card until a manual Stop. The phase-level soft warn
            # is NOT a substitute: it's amber/advisory and fires at the whole-
            # phase budget, not per agent.
            #
            # Safety nets in this loop (all still live):
            #   • #921 stuck arbiter + auto-skip (above): no-growth → card → auto-skip
            #   • #921 hard cap (above): 90-min absolute per-agent ceiling
            #   • Browser-crash sweep: page.is_closed → fail_agent
            #   • Skipped_agents handler: user explicit skip
            #   • Hard retry: user-driven, capped at 2/agent
            #   • Session-expiry mid-run: /login redirect detection
            #   • Stop button: 5s short-circuit at the helper level

            # ── Mid-run session expiry check ──
            # Agent tabs sometimes get logged out silently (cookie expiry,
            # background re-auth failure). Catch it here so the user gets a
            # clear banner instead of the polling loop churning indefinitely
            # against a login page. Throttled — one check every 2 min per agent.
            # Require 2 consecutive detections before firing the alert to avoid
            # false alarms from transient modals / loading states.
            _last_auth_check = p.get("last_auth_check", 0)
            if (time.time() - _last_auth_check) > 120:
                p["last_auth_check"] = time.time()
                agent_key_auth = normalize_agent_key(name)
                platform_key = name.lower().replace(" ", "")
                expired, reason = await detect_session_expiry(p["page"], platform_key, name)
                if not expired:
                    p["session_expiry_hits"] = 0
                else:
                    p.setdefault("session_expiry_hits", 0)
                    p["session_expiry_hits"] += 1
                if expired and p.get("session_expiry_hits", 0) < 2:
                    log(f"[{name}] Possible session expiry ({reason}) — waiting for 2nd confirmation before alerting", "WARN")
                    expired = False  # Suppress alert this tick
                if expired:
                    log(f"[{name}] Session expired mid-run ({reason}) — confirmed by 2 consecutive checks", "WARN")
                    p["session_expiry_hits"] = 0  # reset for next time
                    fail_agent(agent_key_auth,
                               f"{name} signed out",
                               (f"{name} got logged out mid-run. Sign back in using "
                                "the open browser, then Retry — or Skip it."))
                    # #953 (audit): PARK the agent instead of blocking the whole
                    # round-robin for 30 min. The parked-decision resolver at the
                    # leg top handles Retry (reload the re-authed tab) / Skip (the
                    # loop-top consumer) / Stop / timeout — while the OTHER agents
                    # keep polling. 30-min park window preserves the old timeout.
                    p["awaiting_decision"] = {
                        "kind": "session_expiry", "key": agent_key_auth,
                        "since": time.time(), "timeout": 1800.0,
                    }
                    continue

            # ── Gemini periodic refresh: REMOVED (#897a, 2026-07-04) ──
            # The 2026-05-26 ~10-min reload existed because Gemini then didn't
            # push the completed DR panel into the live DOM. The 2026-07 Gemini
            # SPA no longer restores the conversation on reload AT ALL — every
            # reload landed on the empty "new chat" home (image-verified live),
            # so the reload + its sidebar-reopen recovery subsystem were pure
            # hazard. Do NOT reload Gemini mid-run for any reason; completion
            # is detected in-place by detect_completion_gemini (new-UI text
            # signals) + the CUA visual check. If extraction ever comes back
            # short, fix it with an in-place DOM re-read/scroll at EXTRACTION
            # time — never by restoring the reload.

            # DOM scrape (primary); MutationObserver handles token-level stream separately.
            scrape_fn = SCRAPE_FNS.get(name)
            progress = {}
            scrape_ok = False
            if scrape_fn:
                try:
                    progress = await scrape_fn(p["page"]) or {}
                    scrape_ok = True
                except Exception as _scrape_err:
                    # Don't mask scrape failures — tell frontend the scrape degraded
                    log(f"[{name}] DOM scrape failed: {_scrape_err}", "WARN")

            # ── Claude's source count, from the union of every place it is stated ──
            # ⭐ READ-ONLY. The disclosure is a TOGGLE, so pressing it on the
            # scrape path would close an already-open panel; the press happens
            # once, at the confirmed-done read below. The union goes to
            # `observed_sources` and NEVER to `sources` — `sources ==
            # len(source_urls)` is load-bearing, and `liveSrcCount`'s own
            # behavioural uses (the "still generating" test in particular) must
            # keep reading the ticker text alone.
            if name == "Claude" and scrape_ok:
                try:
                    _cl_tog = await _claude_sources_toggle_state(p["page"])
                    progress["observed_sources"] = claude_source_count(
                        live=int(progress.get("observed_sources", 0) or 0),
                        printed=int(progress.get("printed_sources", 0) or 0),
                        toggle_label=int(_cl_tog.get("count", 0) or 0)
                        if _cl_tog.get("found") else 0,
                    )
                    # A signature, not a counter: the same shape says so once, a
                    # NEW shape says so immediately. `found=False` and
                    # `count=0` are different facts and both are printed.
                    _cl_sig = (bool(_cl_tog.get("found")),
                               int(_cl_tog.get("count", 0) or 0),
                               bool(_cl_tog.get("disabled")),
                               bool(_cl_tog.get("expanded")),
                               int(progress.get("printed_sources", 0) or 0))
                    if p.get("_claude_src_sig") != _cl_sig:
                        p["_claude_src_sig"] = _cl_sig
                        log(f"[Claude] source count: observed="
                            f"{progress.get('observed_sources', 0)} "
                            f"url={len(progress.get('source_urls') or [])} "
                            f"ticker={int(progress.get('searches', 0) or 0)} "
                            f"printed={int(progress.get('printed_sources', 0) or 0)} "
                            f"toggle={'absent' if not _cl_tog.get('found') else _cl_tog.get('count')}"
                            f" disabled={bool(_cl_tog.get('disabled'))}"
                            f" expanded={bool(_cl_tog.get('expanded'))}", "DEBUG")
                except Exception as _cl_se:
                    log(f"[Claude] source-count union skipped: {_cl_se}", "DEBUG")

            # Claude artifact tracking — open the FIRST artifact and keep it open
            # so subsequent polls re-read live (URLs / steps / sections) without
            # re-clicking. Auto-close removed: the second artifact (final report) is
            # detected/opened separately by extract_claude_response at completion.
            #
            # 2026-04-26 (v3): iter-#3 settle gate — wait until ≥3 polling cycles
            # OR ≥180s wall-clock (whichever first) so research is actually
            # ongoing and the artifact card has spawned. Same gate applied to
            # ChatGPT below for symmetry. After 2 consecutive DOM "no artifact"
            # readings (after the gate clears), escalate to CUA tier-3 once.
            #
            # ── Claude cycle-2 "unstick prophylaxis" refresh: REMOVED (2026-07-06) ──
            # The 2026-04-26 one-shot reload existed for a rare "DOM hangs while
            # server-side generation continues" failure. On the 2026-07 claude.ai
            # SPA a mid-run reload no longer restores the conversation cleanly
            # (same behavior #897a image-verified for Gemini) — the artifact card
            # vanished from the DOM, _count_claude_artifacts read 0 twice, and the
            # CUA tier-3 fallback then vision-misclicked the SIDEBAR chat's ⋮ menu
            # (Star/Rename popup, user-screenshot 2026-07-06). The reload was the
            # root of that whole cascade and pure hazard on the happy path. Do NOT
            # reload Claude mid-run for any reason; the artifact/sources panel
            # opens in-place from the live DOM below, and a genuinely stalled run
            # is covered by the silence watchdogs + completion detector. The
            # DGOPS-7367 DNS-backoff retry machinery existed ONLY to retry this
            # reload and was removed with it.

            # 2026-05-03: lowered cycle gate 3→2 and elapsed 180s→90s.
            # 2026-07-06: lowered again to cycle 1 (open on the FIRST poll
            # tick). By the time the round-robin starts, the agents have
            # ALREADY been researching for minutes (through P2 setup + the
            # Gemini plan-wait that gates round-robin entry), so the artifact
            # panel exists immediately — waiting for cycle 2 (~120s at the
            # 120s tick cadence, since a Claude/ChatGPT `start_time` is
            # stamped at round-robin start so cycle-1 elapsed≈0) just delayed
            # first narration + source chips by a full tick for no benefit.
            # Open + narrate on cycle 1.
            _claude_gate_ok = (p.get("poll_cycles", 0) >= 1)
            if (name == "Claude" and _claude_gate_ok and
                    (time.time() - p.get("last_artifact_scrape", 0)) > ARTIFACT_SCRAPE_INTERVAL):
                try:
                    # ── #914 anti-churn pre-check (mirror of ChatGPT #913) ──
                    # Probe the REAL panel state before deciding whether to
                    # click. The old flow inferred "open" from "the scrape
                    # returned data", but that data could come from the CUA
                    # fallback whose task text used to CLOSE the panel — the
                    # flag lied open, the re-click was skipped forever, and
                    # every cycle re-ran CUA open→read→close (the visible
                    # panel toggling in the 2026-07-08 E2E).
                    _panel_pre = await _claude_artifact_panel_state(p["page"])
                    _probe_open = bool(_panel_pre.get("open"))
                    _reopens = p.get("claude_panel_reopens", 0)
                    if not _probe_open and _reopens >= 3:
                        # #914b: cap checked at ENTRY, independent of the
                        # flag. The old cap only engaged on the flag-open→
                        # probe-closed transition, so a panel whose clicks
                        # never stick (post-probe always closed → flag never
                        # True) re-clicked UNBOUNDED every tick — churn with
                        # extra steps. After 3 burned attempts nothing
                        # re-clicks; reads continue best-effort.
                        if not p.get("_claude_reclick_cap_logged"):
                            p["_claude_reclick_cap_logged"] = True
                            log("[Claude] artifact panel click budget exhausted "
                                "(3) — suppressing further re-clicks for this "
                                "phase; reads continue best-effort", "WARN")
                        _probe_open = True
                    elif p.get("artifact_panel_open") and not _probe_open:
                        p["claude_panel_reopens"] = _reopens + 1
                        log(f"[Claude] artifact panel collapsed (probe width="
                            f"{_panel_pre.get('width')}, text_len="
                            f"{_panel_pre.get('text_len')}) — re-click allowed "
                            f"({p['claude_panel_reopens']}/3)")
                    _attempted_open = not _probe_open
                    artifact_data = await scrape_claude_artifact_tracking(
                        p["page"], browser=browser, cua_client=cua_client,
                        verbose=verbose, keep_open=True,
                        already_open=_probe_open)
                    # ── #914 truthful flag: probe AGAIN after the scrape ──
                    # The flag must reflect the DOM, not "data came back"
                    # (CUA text ≠ open panel). Downstream consumers: the
                    # already_open skip above, extract's close-1-before-
                    # final-extract, and the vision URL-extract gate.
                    _panel_post = await _claude_artifact_panel_state(p["page"])
                    _now_open = bool(_panel_post.get("open"))
                    if _now_open and not p.get("artifact_panel_open"):
                        # #914b: "(first time)" only once — a reopen-after-
                        # collapse logging as "first time" would corrupt the
                        # forensic signal (grep counts opens per run).
                        _tag = ("first time" if not p.get("_claude_panel_ever_open")
                                else f"re-opened, reopens={p.get('claude_panel_reopens', 0)}/3")
                        p["_claude_panel_ever_open"] = True
                        log(f"[Claude] artifact panel opened ({_tag}) at "
                            f"elapsed={int(elapsed)}s, cycle={p.get('poll_cycles')} "
                            f"(width={_panel_post.get('width')}, "
                            f"text_len={_panel_post.get('text_len')})")
                    elif _attempted_open and artifact_data and not _now_open:
                        # #914b: we clicked, data even came back (geo read /
                        # CUA text), but no panel is mounted — the click
                        # didn't stick. Burn the click budget so this can't
                        # run unbounded (see the entry cap above).
                        p["claude_panel_reopens"] = p.get("claude_panel_reopens", 0) + 1
                        log(f"[Claude] artifact click didn't stick (post-probe "
                            f"closed, layer={artifact_data.get('layer')}) — "
                            f"click budget {p['claude_panel_reopens']}/3", "WARN")
                    p["artifact_panel_open"] = _now_open
                    # Mirror onto runtime singleton so extract_and_record_agent
                    # (which has no `p` handle) can close-1 before clicking the
                    # final artifact card. See extract_claude_response signature.
                    try:
                        _runtime.claude_artifact_panel_open = _now_open
                    except Exception:
                        pass
                    if artifact_data:
                        # ⛔⛔ THE RESET USED TO SIT HERE, one level out, so ANY
                        # returned data — a checklist with steps and sections and
                        # not one url — cleared the miss counter. That counter is
                        # the sole input to `panel_cua_should_escalate`, so a
                        # panel that reliably rendered its checklist and never a
                        # citation DISARMED the escalation written for exactly
                        # that case, on every cycle, forever. "Data came back" is
                        # not "the read worked": what this path is trying to
                        # obtain is SOURCES, and 74 of 78 reads in the corpus
                        # returned exactly one url.
                        if artifact_data.get("source_urls"):
                            p["claude_artifact_dom_misses"] = 0  # reset on a real read
                            for key in ("source_urls", "steps", "sections", "tool_uses"):
                                if artifact_data.get(key):
                                    existing = progress.get(key, []) or []
                                    merged = list(dict.fromkeys(existing + artifact_data[key]))
                                    progress[key] = merged
                            # Invariant: progress["sources"] == len(progress["source_urls"]).
                            # Without this, the merge can grow source_urls past
                            # artifact_data's count, leaving the chip stuck at
                            # the smaller number while the URL list is longer.
                            progress["sources"] = len(progress.get("source_urls", []) or [])
                            if artifact_data.get("partial_text_len", 0) > progress.get("partial_text_len", 0):
                                progress["partial_text_len"] = artifact_data["partial_text_len"]
                            progress["artifact_count"] = artifact_data.get("artifact_count", 0)
                            scrape_ok = True
                            _first_step = (artifact_data.get("steps") or [""])[0]
                            log(f"[Claude] Artifact tracking: {len(artifact_data.get('source_urls', []))} URLs, "
                                f"{len(artifact_data.get('steps', []))} steps, "
                                f"{len(artifact_data.get('sections', []))} sections "
                                f"(layer={artifact_data.get('layer')}, "
                                f"walker_root={artifact_data.get('walker_root') or 'none'}, "
                                f"panel_open={_now_open}, "
                                f"step0={_first_step[:60]!r})")
                            # Track-B success-path observe (once/run — independent samples).
                            # click_box is the true target ONLY when WE clicked this poll
                            # (already_open=False); on later polls it's None (no fresh click).
                            if not p.get("_obs7d_done"):
                                p["_obs7d_done"] = True
                                _observe_dom_success(p["page"], hotspot_id="7d", phase=2,
                                                     platform="claude", current_step="open_artifact_1",
                                                     dom_ground_truth=_gt_from_box(
                                                         artifact_data.get("click_box"),
                                                         artifact_count=artifact_data.get("artifact_count")))
                        else:
                            # ⛔ THE QUIETEST OUTCOME IN THE PATH: the panel was
                            # read, it returned steps and sections, and not one
                            # source url — and nothing was logged at all. This is
                            # the shape 74 of 78 corpus reads had, so it is the
                            # NORMAL case, not an edge one.
                            #
                            # ⚠ The DOM-miss counter is deliberately NOT bumped
                            # here. That counter drives the CUA tier-3, whose job
                            # is to OPEN the panel — and the panel is open. The
                            # rescue for "open but source-less" is the vision
                            # pass, which already takes its panel-open arm.
                            log(f"[Claude] artifact panel read returned no source "
                                f"urls (steps={len(artifact_data.get('steps') or [])}, "
                                f"sections={len(artifact_data.get('sections') or [])}, "
                                f"layer={artifact_data.get('layer')}, "
                                f"walker_root={artifact_data.get('walker_root') or 'none'}, "
                                f"panel_open={_now_open}) — the checklist is not "
                                f"the source list", "INFO")
                    else:
                        # No artifact detected — count as DOM miss for CUA escalation.
                        if not _now_open:
                            p["claude_artifact_dom_misses"] = p.get("claude_artifact_dom_misses", 0) + 1
                            log(f"[Claude] artifact DOM miss "
                                f"#{p['claude_artifact_dom_misses']} at cycle={p.get('poll_cycles')}",
                                "DEBUG")
                            # #914 forensics: snapshot the card candidates +
                            # right-half containers at misses #2/#5 so the next
                            # selector drift is diagnosable from backend.log.
                            if p["claude_artifact_dom_misses"] in (2, 5):
                                await _log_claude_artifact_snapshot(
                                    p["page"],
                                    f"miss-{p['claude_artifact_dom_misses']}")
                    p["last_artifact_scrape"] = time.time()
                except Exception as e:
                    log(f"[Claude] Artifact tracking scrape failed: {e}", "WARN")
                    p["last_artifact_scrape"] = time.time()

                # CUA tier-3 escalation — fires after 2 consecutive DOM misses,
                # capped at 1/agent/phase. Tries to find + click the FIRST
                # artifact card visually.
                # 2026-07-06 guard: ONLY escalate when the DOM actually SEES an
                # artifact card (count > 0) that it failed to open. If no card
                # exists yet (early in the run — polling now starts ~30s after
                # Gemini's Start click, so Claude may not have spawned its
                # tracking artifact), vision has nothing legitimate to click and
                # historically mis-clicked the sidebar chat's ⋮ menu
                # (Star/Rename/Delete popup). No card → just wait for the next
                # tick; the DOM path opens it the moment it renders.
                # The artifact count stays LAST: it is an await, and the pure
                # schedule check above short-circuits it on every quiet cycle.
                if (panel_cua_should_escalate(
                            dom_misses=p.get("claude_artifact_dom_misses", 0),
                            attempts=p.get("claude_artifact_cua_attempts", 0),
                            panel_open=bool(p.get("artifact_panel_open")))
                        and cua_client
                        and await _count_claude_artifacts(p["page"]) > 0):
                    p["claude_artifact_cua_attempts"] = p.get("claude_artifact_cua_attempts", 0) + 1
                    log(f"[Claude] DOM missed artifact "
                        f"{p.get('claude_artifact_dom_misses', 0)}x — escalating to "
                        f"CUA tier-3 (attempt {p['claude_artifact_cua_attempts']}"
                        f"/{_PANEL_CUA_MAX_ATTEMPTS}, cycle={p.get('poll_cycles')})")
                    emit_tier_transition(phase=2, agent="claude",
                        op="open_artifact_1", from_tier="dom", to_tier="cua",
                        reason=f"dom_misses_{p.get('claude_artifact_dom_misses', 0)}")
                    async def _claude_p2_cua():
                        return await asyncio.wait_for(
                            agent_loop(cua_client, browser,
                                PROMPT_OPEN_CLAUDE_SOURCE_ARTIFACT,
                                "Open the FIRST artifact card (research/sources tracking) "
                                "in the Claude conversation. NEVER click the last artifact.",
                                model=CUA_MODEL, max_iterations=5,
                                verbose=verbose, target_page=p["page"]),
                            timeout=120.0)
                    try:
                        cua_res = await _shadow_observed_cua(
                            p["page"], hotspot_id="7d", phase=2, platform="claude",
                            current_step="open_artifact_1",
                            context_hint=f"DOM 2-miss at cycle={p.get('poll_cycles')}",
                            expected_outcome="right panel mounts artifact-1 checklist",
                            cua_coro_factory=_claude_p2_cua,
                            mission_prompt=PROMPT_OPEN_CLAUDE_SOURCE_ARTIFACT,
                            success_text="panel: open")
                        out = ((cua_res or {}).get("text") or "").lower()
                        if "panel: open" in out or "panel: already_open" in out:
                            # #914: trust the DOM probe over the CUA's claim —
                            # a hallucinated "panel: open" would freeze the
                            # already_open skip on a closed panel.
                            _p3 = await _claude_artifact_panel_state(p["page"])
                            p["artifact_panel_open"] = bool(_p3.get("open"))
                            try:
                                _runtime.claude_artifact_panel_open = p["artifact_panel_open"]
                            except Exception:
                                pass
                            log(f"[Claude] artifact panel opened via CUA tier-3 "
                                f"(probe_open={p['artifact_panel_open']}, "
                                f"width={_p3.get('width')})")
                        else:
                            log(f"[Claude] CUA tier-3 didn't confirm panel open: {out[:120]}", "WARN")
                    except asyncio.TimeoutError:
                        log("[Claude] CUA tier-3 timed out after 120s", "WARN")
                    except Exception as _ce:
                        log(f"[Claude] CUA tier-3 failed: {_ce}", "WARN")

            # ── Block 1b: inject MutationObserver INSIDE DR iframe ──
            # Host-page observer cannot see cross-origin iframe content;
            # without this, partial_text_len flatlines while DR streams.
            # Off by default — opt in via DG_CHATGPT_IFRAME_OBSERVER=1.
            # Retried each cycle until iframe exists (returns False if not yet).
            if (name == "ChatGPT"
                    and os.environ.get("DG_CHATGPT_IFRAME_OBSERVER", "0") == "1"
                    and not p.get("iframe_observer_injected")):
                try:
                    if await inject_chatgpt_dr_iframe_observer(p["page"]):
                        p["iframe_observer_injected"] = True
                except Exception as _ioe:
                    log(f"[ChatGPT] iframe observer inject failed: {_ioe}", "WARN")

            # ChatGPT activity-strip open — DOM tier-1 → CUA tier-3 fallback.
            # Strip rendered as styled <div> at bottom of chat thread reading
            # "Looking into X... N searches". Side panel with full step list +
            # source URLs only mounts AFTER click. Without it polling sees only
            # the truncated preview.
            #
            # 2026-04-26 (v3) lessons from 3 failed runs:
            #  - v1 narrow selector (button/[role="button"]) matched 0
            #    candidates because strip is a bare <div> — fix: walk * with
            #    full pointer/mouse event chain (see _open_chatgpt_activity_panel).
            #  - Iter-#1 fired before strip rendered — fix: iter-#3 gate
            #    (poll_cycles>=3 or elapsed>=180s — whichever first).
            #  - DOM "click" silently swallowed — fix: post-click verifier
            #    (`_verify_chatgpt_panel_open`) confirms side panel actually
            #    rendered before flipping the flag.
            #  - After 2 DOM misses → CUA tier-3 fallback (capped at 1/phase).
            # 2026-04-29: lowered gate from iter-#3/180s to iter-#2/90s.
            # 2026-07-06: lowered to cycle 1 (open on the FIRST poll tick) —
            # same rationale as Claude's gate above: the round-robin only
            # starts after the agents have researched for minutes (P2 setup +
            # Gemini plan-wait), so the activity strip is already present on
            # cycle 1; the cycle-2 gate cost a full ~120s tick of dead
            # narration for nothing. Open + narrate immediately.
            _cgpt_gate_ok = (p.get("poll_cycles", 0) >= 1)
            # Re-verify each cycle — ChatGPT auto-collapses the panel when
            # the user navigates sub-views or after long idle. The verifier
            # is a cheap JS call; if the panel stays open across cycles
            # this is a no-op early exit. If it collapsed, we re-open.
            if name == "ChatGPT" and _cgpt_gate_ok and p.get("chatgpt_activity_panel_open"):
                try:
                    if not await _verify_chatgpt_panel_open(p["page"]):
                        p["chatgpt_activity_panel_open"] = False
                        log(f"[ChatGPT] activity panel collapsed (cycle="
                            f"{p.get('poll_cycles')}) — will re-open this cycle",
                            "DEBUG")
                except Exception:
                    pass
            if (name == "ChatGPT" and _cgpt_gate_ok and
                    not p.get("chatgpt_activity_panel_open") and
                    not p.get("chatgpt_done_chip_anchor") and
                    not p.get("chatgpt_panel_stand_down")):
                try:
                    # #913 anti-toggle: the strip/status line is a TOGGLE.
                    # Never click while a shape is already open — the
                    # pre-#913 verifier's width/text gates rejected the
                    # narrow, skeleton-only Activity panel and re-clicked
                    # every cycle, closing what it had just opened.
                    _st_pre = await _chatgpt_activity_state(p["page"])
                    if _st_pre.get("side_panel") or _st_pre.get("inline_expanded"):
                        p["chatgpt_activity_panel_open"] = True
                        p["chatgpt_panel_dom_misses"] = 0
                        # A verified open clears the press history: the budget bounds a
                        # RUN of failures, not the phase.
                        p["chatgpt_panel_click_misses"] = 0
                        p["chatgpt_last_panel_label"] = None
                        _shape = "side" if _st_pre.get("side_panel") else "inline"
                        _sid = _st_pre.get("side_panel_id") or {}
                        log(f"[ChatGPT] activity already open (shape={_shape}) at "
                            f"elapsed={int(elapsed)}s — no click needed"
                            # 2026-08-06: name it. This decision suppresses the
                            # opener for the rest of the phase; on the 21:00 run
                            # it was wrong and the log could not say why.
                            + (f" [{_sid.get('why','?')} {_sid.get('tag','?')} "
                               f"anchors={_sid.get('anchors','?')} "
                               f"rows={_sid.get('rows','?')} "
                               f"ctx={_st_pre.get('side_panel_ctx') or '?'}]"
                               if _sid else ""))
                        res = None
                    else:
                        res = await _open_chatgpt_activity_panel(
                            p["page"],
                            skip_structural=(p.get("chatgpt_panel_dom_misses", 0) >= 2))
                    cands = (res or {}).get("candidates", 0)
                    # 2026-07-13: when the click anchor itself reads the
                    # COMPLETED chip ("Research completed in Xm · …"), the
                    # Researching panel no longer exists — DR is finished and
                    # there is nothing to (re-)open. Pre-fix this looped:
                    # 21 click-misses into the finished document + a CUA
                    # tier-3 scroll hunt (the user-observed "stuck scrolling
                    # the finished doc for 30 minutes"). Halt re-open attempts
                    # for the rest of the phase; the completion detector's
                    # completed-chip marker carries it from here.
                    _res_lbl = ((res or {}).get("label") or "")
                    if (not p.get("chatgpt_activity_panel_open")
                            and re.search(r"research\s+complete", _res_lbl, re.I)):
                        p["chatgpt_done_chip_anchor"] = True
                        log(f"[ChatGPT] activity anchor reads the COMPLETED chip "
                            f"(\"{_res_lbl[:60]}\") — DR finished, researching panel "
                            f"is gone; halting panel re-open attempts")
                    elif p.get("chatgpt_activity_panel_open"):
                        pass
                    elif not res or not res.get("found"):
                        p["chatgpt_panel_dom_misses"] = p.get("chatgpt_panel_dom_misses", 0) + 1
                        log(f"[ChatGPT] panel DOM miss #{p['chatgpt_panel_dom_misses']} "
                            f"(cycle={p.get('poll_cycles')}, walked_hits={cands}) — "
                            f"{_panel_miss_reason(res)}", "DEBUG")
                        if p["chatgpt_panel_dom_misses"] in (2, 6):
                            await _log_chatgpt_thread_snapshot(
                                p["page"], tag=f"p2-miss{p['chatgpt_panel_dom_misses']}")
                    elif res.get("alreadyExpanded"):
                        p["chatgpt_activity_panel_open"] = True
                        p["chatgpt_panel_dom_misses"] = 0
                        # A verified open clears the press history: the budget bounds a
                        # RUN of failures, not the phase.
                        p["chatgpt_panel_click_misses"] = 0
                        p["chatgpt_last_panel_label"] = None
                        log(f"[ChatGPT] activity panel already expanded at "
                            f"elapsed={int(elapsed)}s — label: \"{res.get('label','')[:80]}\"")
                        _observe_dom_success(p["page"], hotspot_id="7c", phase=2,
                                             platform="chatgpt", current_step="open_activity_panel",
                                             dom_ground_truth=_dom_gt_from_res(res))
                    elif res.get("clicked"):
                        # Verify a shape actually mounted (side panel OR
                        # inline drawer — silent click failures still count
                        # as misses).
                        await asyncio.sleep(2.0)
                        _st_post = await _chatgpt_activity_state(p["page"])
                        verified = bool(_st_post.get("side_panel")
                                        or _st_post.get("inline_expanded"))
                        if verified:
                            p["chatgpt_activity_panel_open"] = True
                            # A press we watched mount a shape is proof of a real
                            # panel — the bare-read override must never overturn
                            # THAT, only a latch the pre-check set on its own.
                            p["chatgpt_panel_click_verified"] = True
                            p["chatgpt_panel_bare_reads"] = 0
                            p["chatgpt_panel_dom_misses"] = 0
                            # A verified open clears the press history: the budget bounds a
                            # RUN of failures, not the phase.
                            p["chatgpt_panel_click_misses"] = 0
                            p["chatgpt_last_panel_label"] = None
                            _shape = "side" if _st_post.get("side_panel") else "inline"
                            log(f"[ChatGPT] activity opened via DOM at "
                                f"elapsed={int(elapsed)}s — shape={_shape} "
                                f"anchor={res.get('anchor', res.get('scope', '?'))} "
                                f"clickedTag={res.get('clickedTag','?')} "
                                f"frame={res.get('frameUrl','host')} "
                                f"label=\"{res.get('label','')[:60]}\"")
                            _observe_dom_success(p["page"], hotspot_id="7c", phase=2,
                                                 platform="chatgpt", current_step="open_activity_panel",
                                                 dom_ground_truth=_dom_gt_from_res(res))
                        else:
                            p["chatgpt_panel_dom_misses"] = p.get("chatgpt_panel_dom_misses", 0) + 1
                            p["chatgpt_panel_click_misses"] = p.get(
                                "chatgpt_panel_click_misses", 0) + 1
                            # ⭐ 2026-08-06: say WHAT was pressed, not just what
                            # we hoped it was. The success line has printed
                            # clickedTag + frameUrl since #913; the miss line
                            # dropped both, so twelve presses were logged
                            # without ever naming the element — and the element
                            # was the whole story (a markdown table cell in the
                            # agent's own report, in the about:blank frame).
                            log(f"[ChatGPT] DOM clicked but neither panel nor inline "
                                f"drawer verified — miss #{p['chatgpt_panel_dom_misses']} "
                                f"(anchor={res.get('anchor', res.get('scope', '?'))} "
                                f"clickedTag={res.get('clickedTag','?')} "
                                f"frame={res.get('frameUrl','host')} "
                                f"label=\"{res.get('label','')[:60]}\")", "WARN")
                            if p["chatgpt_panel_dom_misses"] in (2, 6):
                                await _log_chatgpt_thread_snapshot(
                                    p["page"], tag=f"p2-miss{p['chatgpt_panel_dom_misses']}")
                            _stand_down = _chatgpt_panel_stand_down_reason(
                                p, res.get("label") or "")
                            if _stand_down:
                                p["chatgpt_panel_stand_down"] = _stand_down
                                log(f"[ChatGPT] standing down from re-opening the "
                                    f"activity panel — {_stand_down}. Source counts "
                                    f"stop updating; completion is unaffected.", "INFO")
                    else:
                        p["chatgpt_panel_dom_misses"] = p.get("chatgpt_panel_dom_misses", 0) + 1
                        log(f"[ChatGPT] panel found but click failed — "
                            f"label: \"{res.get('label','')[:80]}\" "
                            f"err={res.get('error','?')}", "WARN")
                except Exception as e:
                    log(f"[ChatGPT] activity panel open failed: {e}", "WARN")
                    p["chatgpt_panel_dom_misses"] = p.get("chatgpt_panel_dom_misses", 0) + 1

                # CUA tier-3 escalation, retried on a miss-count schedule (see
                # `panel_cua_should_escalate`).
                # 2026-07-13: never escalate once the completed chip is the
                # anchor — the panel is legitimately gone, not "missed". That
                # stays a hard block, so the retries below cannot make a phase
                # that should be quiet start clicking.
                if (panel_cua_should_escalate(
                            dom_misses=p.get("chatgpt_panel_dom_misses", 0),
                            attempts=p.get("chatgpt_panel_cua_attempts", 0),
                            panel_open=bool(p.get("chatgpt_activity_panel_open")),
                            blocked=bool(p.get("chatgpt_done_chip_anchor")))
                        and cua_client):
                    p["chatgpt_panel_cua_attempts"] = p.get("chatgpt_panel_cua_attempts", 0) + 1
                    log(f"[ChatGPT] DOM missed strip "
                        f"{p.get('chatgpt_panel_dom_misses', 0)}x — escalating to "
                        f"CUA tier-3 (attempt {p['chatgpt_panel_cua_attempts']}"
                        f"/{_PANEL_CUA_MAX_ATTEMPTS}, cycle={p.get('poll_cycles')})")
                    emit_tier_transition(phase=2, agent="chatgpt",
                        op="open_activity_panel", from_tier="dom", to_tier="cua",
                        reason=f"dom_misses_{p.get('chatgpt_panel_dom_misses', 0)}")
                    async def _cgpt_p2_cua():
                        return await asyncio.wait_for(
                            agent_loop(cua_client, browser,
                                PROMPT_OPEN_CHATGPT_SOURCE_PANEL,
                                "Open the research activity for the latest response in "
                                "this ChatGPT Deep Research conversation: click the live "
                                "activity strip / shimmering status line attached to it. "
                                "ONE click only — it is a toggle. Expected result: a side "
                                "panel on the right (execution plan / step list, or a "
                                "narrow 'Activity' panel — skeleton bars still count as "
                                "open). Never click 'Answer now' or the X.",
                                model=CUA_MODEL, max_iterations=5,
                                verbose=verbose, target_page=p["page"]),
                            timeout=120.0)
                    try:
                        cua_res = await _shadow_observed_cua(
                            p["page"], hotspot_id="7c", phase=2, platform="chatgpt",
                            current_step="open_activity_panel",
                            context_hint=f"DOM 2-miss at cycle={p.get('poll_cycles')}",
                            expected_outcome="side panel mounts OR inline thoughts drawer expands",
                            cua_coro_factory=_cgpt_p2_cua,
                            mission_prompt=PROMPT_OPEN_CHATGPT_SOURCE_PANEL,
                            success_text="panel: open")
                        out = ((cua_res or {}).get("text") or "").lower()
                        if "panel: open" in out or "panel: already_open" in out:
                            p["chatgpt_activity_panel_open"] = True
                            log("[ChatGPT] activity panel opened via CUA tier-3")
                        else:
                            log(f"[ChatGPT] CUA tier-3 didn't confirm panel open: {out[:120]}", "WARN")
                    except asyncio.TimeoutError:
                        log("[ChatGPT] CUA tier-3 timed out after 120s", "WARN")
                    except Exception as _ce:
                        log(f"[ChatGPT] CUA tier-3 failed: {_ce}", "WARN")

            # ── Block 1c: ChatGPT activity-panel scrape (mirror of Claude
            # artifact tracking). Runs every cycle once the panel is open,
            # walking the side panel for live steps/sections/source_urls/
            # searches count. Without this, _open_chatgpt_activity_panel
            # opens the panel for URL extraction at end-of-phase but
            # leaves the FE staring at "Deep Research in progress" the
            # whole run — Claude reads its artifact panel continuously
            # for the gold-standard narration; ChatGPT now does the same.
            # DOM-only: no CUA fallback. Reading from an already-open
            # panel is a cheap structural walk; if the walker yields
            # nothing the vision narration block below picks up the slack.
            if (name == "ChatGPT"
                    and p.get("chatgpt_activity_panel_open")
                    and (time.time() - p.get("last_chatgpt_panel_scrape", 0))
                            > ARTIFACT_SCRAPE_INTERVAL):
                try:
                    panel_data = await scrape_chatgpt_activity_panel_tracking(p["page"])
                    if panel_data:
                        # Merge into outer progress dict using dedupe-keep-
                        # first semantics (mirrors Claude artifact merge).
                        for key in ("source_urls", "steps", "sections"):
                            if panel_data.get(key):
                                existing = progress.get(key, []) or []
                                merged = list(dict.fromkeys(existing + panel_data[key]))
                                progress[key] = merged
                        # Invariant: progress["sources"] == len(progress["source_urls"]).
                        progress["sources"] = len(progress.get("source_urls", []) or [])
                        # Merge source_items ({url,title}) by url — dicts aren't
                        # hashable so this can't ride the dict.fromkeys() union
                        # above. Keep the first non-empty title seen per url so
                        # a later title-less scrape doesn't erase it.
                        if panel_data.get("source_items"):
                            _by_url = {}
                            for _it in (progress.get("source_items") or []):
                                if isinstance(_it, dict) and _it.get("url"):
                                    _by_url[_it["url"]] = _it
                            for _it in panel_data["source_items"]:
                                if not isinstance(_it, dict) or not _it.get("url"):
                                    continue
                                _prev = _by_url.get(_it["url"]) or {}
                                _title = (_it.get("title") or _prev.get("title") or "").strip()
                                _by_url[_it["url"]] = {"url": _it["url"], "title": _title}
                            progress["source_items"] = list(_by_url.values())[:_SOURCE_LIST_CAP]
                        # Searches count — take max so transient lower
                        # reads don't shrink the chip.
                        _ps = int(panel_data.get("searches", 0) or 0)
                        if _ps > int(progress.get("searches", 0) or 0):
                            progress["searches"] = _ps
                        # Mark panel_open=True so the FE chip + the vision
                        # narration block both see the panel as live.
                        progress["panel_open"] = True
                        # Refresh progress text from latest step if our
                        # pre-scrape progress was empty (don't override a
                        # rich pre-existing string).
                        if (panel_data.get("progress")
                                and not (progress.get("progress") or "").strip()):
                            progress["progress"] = panel_data["progress"]
                        if int(panel_data.get("partial_text_len", 0) or 0) > int(progress.get("partial_text_len", 0) or 0):
                            progress["partial_text_len"] = panel_data["partial_text_len"]
                        scrape_ok = True
                        log(f"[ChatGPT] panel tracking "
                            f"(shape={panel_data.get('panel_shape', 'side')}): "
                            f"{len(panel_data.get('source_urls', []))} URLs, "
                            f"{len(panel_data.get('steps', []))} steps, "
                            f"{len(panel_data.get('sections', []))} sections, "
                            f"searches={panel_data.get('searches', 0)}")
                        # ⭐⭐ 2026-08-06 — LET THE READER OVERTURN THE PRE-CHECK.
                        # The anti-toggle pre-check latches
                        # `chatgpt_activity_panel_open` for the phase, and the
                        # ONLY thing that can clear it calls the same predicate
                        # that set it — so a false positive re-confirms itself
                        # forever. On the 21:00 run it did: five consecutive
                        # samples of "0 URLs, 0 steps, searches=0" from a node
                        # that was a conversation turn, and nothing fed that back.
                        # The reader had the disproof in its hands every cycle.
                        #
                        # Empty ONCE is normal (a freshly opened panel is sparse,
                        # which is exactly why #913 removed the text floor).
                        # Empty repeatedly, on a panel we never clicked open, is
                        # not — so require a run of them AND that we never
                        # verified a click, then drop the latch and let the
                        # opener try. It re-checks before clicking, so a panel
                        # that IS open cannot be toggled shut by this.
                        _bare = (not panel_data.get("source_urls")
                                 and not panel_data.get("steps")
                                 and not int(panel_data.get("searches", 0) or 0))
                        p["chatgpt_panel_bare_reads"] = (
                            p.get("chatgpt_panel_bare_reads", 0) + 1 if _bare else 0)
                        if (p["chatgpt_panel_bare_reads"] >= _CHATGPT_PANEL_BARE_LIMIT
                                and p.get("chatgpt_activity_panel_open")
                                and not p.get("chatgpt_panel_click_verified")):
                            p["chatgpt_activity_panel_open"] = False
                            p["chatgpt_panel_bare_reads"] = 0
                            log(f"[ChatGPT] the panel we never clicked has read "
                                f"empty {_CHATGPT_PANEL_BARE_LIMIT}x — it is not "
                                f"the sources panel; clearing the flag so the "
                                f"opener runs", "WARN")
                except Exception as _e:
                    log(f"[ChatGPT] activity panel scrape failed: {_e}", "DEBUG")
                p["last_chatgpt_panel_scrape"] = time.time()

            # ── Block 2: per-agent vision narration (P2 mirror of P1) ──
            # Same cooldown (90s) + budget (30/phase) enforced inside
            # narrate. Two triggers: (a) DOM walker is empty past
            # 60s warmup, or (b) every Nth poll for a fresh narration even
            # when DOM IS producing data. Continuous narration throughout
            # the phase — not one-shot at end.
            _elapsed_sec_now = int(time.time() - p["start_time"])
            _vn_steps_n = len(progress.get("steps", []) or [])
            _vn_progress_str = (progress.get("progress") or "").strip()
            _vn_sources = int(progress.get("sources", 0) or 0)
            _vn_panel_open = bool(progress.get("panel_open", False))
            # 2026-04-29: aggressive vision cadence (mirrors the P1 block
            # above). DOM-empty warmup 60s → 20s, panel-open gate 90s →
            # 30s. Narrator's MIN_GAP_S (30s) bounds actual call
            # frequency. With a working GEMINI_API_KEY the FE should see
            # a fresh narration sentence ~every poll once the agent is
            # past the 20s warmup.
            _vn_should_call = (
                _elapsed_sec_now > 20
                and _vn_steps_n < 2
                and _vn_sources == 0
            ) or (
                _elapsed_sec_now > 30 and _vn_panel_open
            )
            _vn_force_every_n = int(os.environ.get("GEMINI_NARRATE_FORCE_EVERY_N", "2"))
            if _vn_force_every_n > 0 and _elapsed_sec_now > 0:
                try:
                    _poll_interval = max(int(POLL_DEEP_RESEARCH), 1)
                except Exception:
                    _poll_interval = 30
                _poll_tick = _elapsed_sec_now // _poll_interval
                if _poll_tick > 0 and _poll_tick % _vn_force_every_n == 0:
                    _vn_should_call = True
            _vision_narration_p2 = ""
            _vision_phase_signal_p2 = ""
            if _vn_should_call:
                _vision_data_p2 = None
                try:
                    import narrate as _vn
                    _vision_data_p2 = await _vn.narrate_panel(
                        p["page"],
                        agent=normalize_agent_key(name),
                        phase=2,
                        workflow_name=name,
                        last_dom_progress=_vn_progress_str,
                        last_dom_sources=_vn_sources,
                        last_dom_steps_n=_vn_steps_n,
                    )
                except Exception as _vne:
                    log(f"[{name}] narrate failed: {_vne}", "DEBUG")
                    _vision_data_p2 = None
                # Confidence floor lowered 0.4 → 0.3 (matches P1 block).
                if _vision_data_p2 and float(_vision_data_p2.get("confidence", 0)) >= 0.3:
                    _vision_narration_p2 = _vision_data_p2.get("narration", "")
                    _vision_phase_signal_p2 = _vision_data_p2.get("phase_signal", "") or ""
                    _v_progress = _vision_data_p2.get("progress", "")
                    if _v_progress and len(_v_progress) > len(_vn_progress_str):
                        progress["progress"] = _v_progress
                    _v_steps = _vision_data_p2.get("steps") or []
                    if _v_steps:
                        _seen = set(s[:80] for s in (progress.get("steps") or []))
                        _merged = list(progress.get("steps") or [])
                        for s in _v_steps:
                            k = s[:80]
                            if k not in _seen:
                                _seen.add(k); _merged.append(s)
                        progress["steps"] = _merged[-15:]
                    if (not progress.get("sections")) and _vision_data_p2.get("sections"):
                        progress["sections"] = _vision_data_p2["sections"]
                    # Vision-derived source-count estimate kept SEPARATE from
                    # progress["sources"] (URL-derived) per Group B fix.
                    _so = int(_vision_data_p2.get("sources_observed") or 0)
                    if _so > 0:
                        progress["observed_sources"] = _so
                    log(f"[{name}] narrate hit: phase_signal={_vision_data_p2.get('phase_signal')} "
                        f"conf={_vision_data_p2.get('confidence',0):.2f} steps+={len(_v_steps)} "
                        f"narration=\"{_vision_narration_p2[:80]}\"", "INFO")
                    # Emit agent_narration so PhaseDropdown agent card updates
                    # mid-phase (the dedicated event stream Block 6 wired up).
                    # Same quality gate as the narrator loop — vision rarely
                    # fragments but the symmetric coverage is cheap.
                    # ⛔⛔ 2026-08-17 — THIS SLICE RAN BEFORE THE GATE. `[:140]`
                    # cuts wherever the 140th character lands, mid-word as often
                    # as not, and the gate then inspected the damage instead of
                    # the model's output — it can only see a fragment it did not
                    # cause. Shortening by SENTENCE answers both: the result is a
                    # whole sentence within the budget, or nothing.
                    _vn_text = _narration_last_sentence(_vision_narration_p2, limit=140)
                    if _vn_text and _is_acceptable_narration(_vn_text):
                        try:
                            emit_event("agent_narration", phase=2,
                                       agent=normalize_agent_key(name),
                                       text=_vn_text)
                        except Exception as _en:
                            log(f"[{name}] agent_narration emit failed: {_en}", "DEBUG")

            # ── Block 3: vision-extract source URLs from side panel ──
            # One-shot per agent. Gated on panel-open success so screenshot
            # has real content. Supplements DOM scraping when URLs are in
            # collapsed rows / popovers / non-anchor click handlers.
            # Disabled by setting DG_VISION_URL_EXTRACT=0.
            if (os.environ.get("DG_VISION_URL_EXTRACT", "1") == "1"
                    and not p.get("vision_urls_done")):
                _panel_open_now = bool(
                    p.get("chatgpt_activity_panel_open") if name == "ChatGPT"
                    else p.get("artifact_panel_open"))
                _gate_ok, _gate_why = vision_url_rescue_should_run(
                    agent=name,
                    panel_open=_panel_open_now,
                    elapsed_sec=int(elapsed),
                    dom_source_count=int(progress.get("sources", 0) or 0),
                    # Claude's real poll-state keys. The never-opened arm is
                    # Claude-only (see the predicate), so these are read
                    # unconditionally rather than through an agent branch that
                    # would need names ChatGPT does not have.
                    open_attempts_burned=int(p.get("claude_panel_reopens", 0) or 0),
                    dom_misses=int(p.get("claude_artifact_dom_misses", 0) or 0),
                    ever_opened=bool(p.get("_claude_panel_ever_open")),
                )
                if _gate_ok:
                    if _gate_why.startswith("panel-never-opened"):
                        # The rescue firing on a never-opened panel is not
                        # owner-actionable — but "ran and found nothing" and
                        # "never ran" were indistinguishable before, and that is
                        # the whole reason this line exists.
                        log(f"[{name}] vision-urls rescue on a panel that never "
                            f"opened ({_gate_why})", "INFO")
                    try:
                        _vu = await extract_source_urls_via_vision(
                            p["page"], normalize_agent_key(name),
                            last_dom_count=int(progress.get("sources", 0) or 0))
                        if not _vu:
                            log(f"[{name}] vision-urls found no urls "
                                f"(gate={_gate_why})", "INFO")
                        if _vu:
                            existing = progress.get("source_urls") or []
                            seen_v = set(existing)
                            unioned_v = list(existing)
                            for u in _vu:
                                if u not in seen_v:
                                    seen_v.add(u); unioned_v.append(u)
                            if len(unioned_v) > len(existing):
                                progress["source_urls"] = unioned_v[:_SOURCE_LIST_CAP]
                                progress["sources"] = len(progress["source_urls"])
                                log(f"[{name}] vision-urls extracted {len(_vu)} URLs "
                                    f"(DOM had {len(existing)}, union now "
                                    f"{len(progress['source_urls'])})", "INFO")
                        p["vision_urls_done"] = True
                    except Exception as _vue:
                        log(f"[{name}] vision-urls failed: {_vue}", "WARN")
                        p["vision_urls_done"] = True  # don't retry on failure

            # Emit agent_progress to frontend (critical for real-time UI)
            agent_key = normalize_agent_key(name)
            # If scrape failed we don't know the agent's real status — keep
            # elapsed-time progress text but omit stale/fake fields
            _status_val = progress.get("status") if scrape_ok else "generating"
            _progress_val = progress.get("progress") if scrape_ok else None
            if not _progress_val:
                _progress_val = f"Researching... ({int(time.time() - p['start_time']) // 60}m elapsed)"
            elapsed_sec = int(time.time() - p["start_time"])

            # DOM partial text length + MutationObserver stream.
            # Observer fires every ~500ms as tokens arrive (see inject_agent_observer);
            # DOM scrape runs every 30s. Use whichever is larger so the progress bar
            # climbs monotonically even between DOM scrapes.
            _obs = get_observer_state(p["page"])
            _obs_len = int(_obs.get("observer_text_len", 0) or 0)
            _obs_preview = str(_obs.get("observer_preview", "") or "")
            _partial_text_len = max(progress.get("partial_text_len", 0) or 0, _obs_len)
            p["observer_text_len"] = _obs_len  # Keep shared-dict snapshot fresh

            # ── Stuck-agent detection ──
            # Compare current text length AND source count against the last-
            # growth checkpoint. Only alert if BOTH haven't moved for 20 min
            # AND the agent isn't in a known "planning/thinking" status.
            # These gates avoid false alarms on agents mid-research (planning
            # phases are often 10+ min with no text growth but active sources).
            agent_key_stuck = normalize_agent_key(name)
            # observed_sources (Claude text count, ChatGPT vision count)
            # captures growth that URL extraction can't see. Treat as
            # liveness signal so the stall watchdog doesn't false-fire
            # during URL-light progress.
            _src_count = max(
                int(progress.get("sources", 0) or 0),
                int(progress.get("observed_sources", 0) or 0),
            )
            p.setdefault("last_growth_len", 0)
            p.setdefault("last_growth_sources", 0)
            p.setdefault("last_growth_time", p["start_time"])
            p.setdefault("stuck_warned_at", 0.0)
            if _partial_text_len > p["last_growth_len"] or _src_count > p["last_growth_sources"]:
                p["last_growth_len"] = max(p["last_growth_len"], _partial_text_len)
                p["last_growth_sources"] = max(p["last_growth_sources"], _src_count)
                p["last_growth_time"] = time.time()
                # #921 false-positive guard: real growth AFTER a stuck card means
                # the agent RECOVERED. Cancel the Layer-3 auto-skip countdown
                # (stuck_alerted_at) and retract the card — otherwise we'd
                # auto-skip a now-producing agent 20 min after a stale alert.
                if p.get("stuck_alerted_at", 0.0):
                    p["stuck_alerted_at"] = 0.0
                    p["stuck_warned_at"] = 0.0
                    _disarm_registry(agent_key_stuck)   # #955 P2: flag↔registry lockstep
                    log(f"[{name}] Recovered after a stuck alert (growth resumed) — "
                        "retracting card, cancelling auto-skip", "INFO")
                    try:
                        emit_event("pipeline_warning", phase=2, agent=agent_key_stuck,
                                   error=f"{name} resumed",
                                   details=f"{name} started producing output again.",
                                   actions=[], alert_id=_agent_error_alert_id(agent_key_stuck, 2),
                                   auto_clear_on_resume=True)
                        _clear_pending_decision(agent_key_stuck)
                    except Exception:
                        pass
            no_growth_secs = time.time() - p["last_growth_time"]
            since_warn = time.time() - p["stuck_warned_at"]
            # 2026-08-20: Gemini's source count has never been logged, which is
            # why "Gemini shows zero sources" could not be diagnosed from a run.
            # ChatGPT and Claude each have a tracking line; this is Gemini's.
            # ⭐ ON CHANGE ONLY — wave 2's flood lesson: a per-cycle restatement
            # of an unchanging number is a true statement worth one bit.
            if name == "Gemini" and scrape_ok:
                _gsrc = (int(progress.get("sources", 0) or 0),
                         int(progress.get("src_page", 0) or 0),
                         int(progress.get("src_panel", 0) or 0),
                         int(progress.get("searches", 0) or 0))
                if _gsrc != p.get("gemini_src_last"):
                    p["gemini_src_last"] = _gsrc
                    log(f"[Gemini] source tracking: {_gsrc[0]} URLs "
                        f"(page={_gsrc[1]}, panel={_gsrc[2]}, searches={_gsrc[3]})")

            _active_statuses = ("planning", "thinking", "researching", "searching")
            # ⛔⛔ 2026-08-19 — NOT ONE OF THOSE FOUR VALUES IS EVER PRODUCED. All
            # three scrapers in SCRAPE_FNS emit exactly `generating`, `complete`,
            # `idle` or `scrape_error`, so the status half of `status_is_active`
            # below has never once been true for any platform: the ONLY live gate
            # is `_scrape_phase == "planning"`. That is why the 08-19 e2e met the
            # 15-minute no-growth arbiter while Gemini was researching perfectly
            # happily, and it is a SEPARATE cause from the detector misses fixed
            # in detect_completion_gemini the same day — the arbiter never reads
            # the detector's verdict or its reason.
            # ⛔ AND THE FIX IS NOT TO ADD "generating" HERE. The note below
            # already explains why a broad liveness signal must not gate L1: the
            # scraper reports movement off stale panel steps on a frozen page, so
            # widening this list silences the stuck arbiter entirely — the
            # promote-a-skipped-low-into-a-healthy-leg-killer shape. Left dead
            # and documented on purpose; deciding what "active" should mean needs a
            # judgement about which evidence is trustworthy, not a wider tuple.
            # #929: also honor the scraper's separate `phase` field — but ONLY
            # for "planning". Gemini's scraper never returns status="planning"
            # (its plan states read status='generating' with the planning
            # signal in `phase` — scrape_progress_gemini ~16663), so the
            # status-only gate never protected a legitimately long plan draft
            # (2026-07-09 false alarm: healthy 10-min plan → stuck card →
            # auto-skip). `phase` values OTHER than planning must NOT gate:
            # the scraper reports phase='researching' off stale panel steps
            # even on a frozen page, which would silence L1 entirely.
            _scrape_phase = ((progress.get("phase") or "") if scrape_ok else "").lower()
            status_is_active = ((_status_val or "").lower() in _active_statuses
                                or _scrape_phase == "planning")

            # ── #921 Layer 3 — auto-skip backstop (checked first) ──────────
            # Guarantees a run can't hang on an AFK operator. Two triggers,
            # both auto-skip JUST this agent (the others keep their output):
            #   (a) PER_AGENT_HARD_CAP_SEC (90 min) absolute ceiling — catches
            #       the "slowly emitting but never actually finishing" agent
            #       (which a no-growth timer never trips) and the verified=False
            #       handoff that never yields a CUA done/error verdict.
            #   (b) a raised stuck card (below) left unacted for
            #       AUTO_SKIP_UNACTED_SEC (30 min since #929) — the user was
            #       already shown the card + pinged, so this is "not coming back".
            # Mirrors the existing chat-mode 3h auto-skip precedent. Partial
            # output is salvaged before the tab closes.
            # #955 Phase 2: the UNACTED-card auto-skip (trigger (b)) moved to the
            # registry firer (_fire_due_autoskips), which auto-skips off the SAME
            # deadline the FE counts down to (armed at the stuck site below) — no
            # drift between the shown countdown and the real fire, and it fires
            # from the tick even when this per-agent leg is dwelling on a sibling.
            # This branch keeps ONLY the independent 90-min ceiling (trigger (a)):
            # it catches the agent that was never carded stuck (slowly emitting
            # but never finishing, or a verified=False handoff that yields no CUA
            # verdict), which a card-driven deadline can't see. Deliberately OFF
            # the registry (a silent backstop, no user-facing countdown). `>=`
            # standardized (matches the parked-resolver hard cap).
            _hit_hard_cap = elapsed >= PER_AGENT_HARD_CAP_SEC
            # #921: auto-skip is user-controllable (Settings → Pipeline). When
            # OFF, the stuck card + FE watchdog still surface, but we never
            # auto-resolve — the card waits for a manual Retry/Skip.
            if _runtime.auto_skip_stuck and _hit_hard_cap:
                _as_why = f"ran past the {PER_AGENT_HARD_CAP_SEC // 60}-min limit"
                _as_reason = "auto_skip_hard_cap"
                log(f"[{name}] Auto-skip — {_as_why} (elapsed {int(elapsed/60)}m). "
                    "Salvaging partial output, closing tab, continuing other agents.", "WARN")
                _as_partial = ""
                # #929 hands-off parity with the user-skip consumer (22555):
                # never run the extraction ladder (DOM walks + CUA fallback)
                # against a verification-walled tab — those touches are
                # exactly what the 2026-07-06 Cloudflare directive forbids,
                # and a walled agent has nothing to salvage anyway.
                if agent_key_stuck in _controls.hv_blocked:
                    log(f"[{name}] Auto-skip — verification-walled tab, "
                        "skipping partial extraction (hands-off)", "WARN")
                else:
                    try:
                        await browser.switch_to_page(p["page"])
                        _as_partial = await extract_fns[name](
                            p["page"], browser=browser, cua_client=cua_client,
                            label=name, verbose=verbose) or ""
                    except Exception as _ase:
                        log(f"[{name}] Auto-skip salvage extract failed: {_ase}", "WARN")
                # #955: one finalize shape for every auto-skip (agent_skipped
                # greys the tile + retracts any live stuck card; the notice
                # explains WHY — the agent is resolved, not awaiting a decision).
                await _finalize_agent_autoskip(
                    browser, p.get("page"), agent_key_stuck, name,
                    reason=_as_reason,
                    copy_key="stuck", why=_as_why,
                    partial=_as_partial, url=p.get("url", ""),
                    elapsed_sec=int(elapsed),
                    results=results, results_name=name)
                del pending[name]
                continue

            # ── #921 Layer 1 — CUA-arbitrated stuck card at 10 min no-growth ──
            # When nothing has grown for STUCK_NO_GROWTH_SEC (and we're past the
            # warm-up, not in an active planning/thinking status, and off the
            # re-warn throttle), a CUA ARBITER decides stuck-vs-slow. This is the
            # fix for the 2026-04-28 false-positive class: back then a
            # 1,289-source ChatGPT DR read 0/0 to every scraper (cross-origin
            # iframe + a 404 narrator) yet was alive — the old code papered over
            # it with a "CUA checked in recently" gate that ALSO silenced the
            # genuinely-stuck case (incident #2: a frozen empty placeholder that
            # CUA kept honestly calling "still generating"). The arbiter looks at
            # the actual page and distinguishes SUBSTANTIAL output (working, even
            # if scrape-blind) from an EMPTY/placeholder/frozen state (stuck),
            # defaulting to WORKING on any doubt so a healthy agent is never
            # wrongly carded (and, with Layer 3 live, never wrongly auto-skipped).
            _active_no_growth = (no_growth_secs > STUCK_NO_GROWTH_SEC
                                 and elapsed > STUCK_MIN_ELAPSED_SEC
                                 and since_warn > STUCK_WARN_THROTTLE_SEC
                                 and not status_is_active)
            if _active_no_growth:
                # ⭐ 2026-08-12 — THE THROTTLE HELD ONLY WHILE IT WAS NOT NEEDED.
                # `since_warn` is the whole re-probe throttle, and `stuck_warned_at`
                # was stamped ONLY on the CONFIRMED-STUCK path below; the WORKING
                # branch was expected to throttle itself by rewinding the growth
                # clock instead (the note in the probe's except-block says so).
                # But that rewind is capped at _ARBITER_MAX_WORKING_RESETS. Once
                # the extensions are spent the clock is never reset again, so
                # `no_growth_secs` stays permanently above STUCK_NO_GROWTH_SEC —
                # and with `stuck_warned_at` still 0.0, `since_warn` is the whole
                # run. Every gate in `_active_no_growth` is then true on EVERY
                # tick: the 08-11 ChatGPT freeze took verdicts #1 and #2 fifteen
                # minutes apart and then ran 28 probes in 31 minutes, none of
                # which could reset the clock or raise a card. The safety limit
                # engaging is exactly what removed the throttle.
                #
                # Stamped at ENTRY, before the verdict, so it holds for every
                # outcome — stuck, working, reset-refused, and the CUA probe
                # raising. The confirmed-stuck path below re-stamps it; that is
                # now redundant and kept deliberately, so this line moving can
                # never leave the card path unthrottled.
                p["stuck_warned_at"] = time.time()
                log(f"[{name}] No observed growth for {int(no_growth_secs/60)}m "
                    f"(elapsed {int(elapsed/60)}m) — CUA arbiter deciding stuck-vs-slow", "WARN")
                _stuck_mission = (
                    "This deep-research agent has shown NO new output to our scrapers "
                    "for several minutes. Decide whether it is GENUINELY STUCK or "
                    "merely SLOW.\n"
                    "Look at the page: is there SUBSTANTIAL research output visible — a "
                    "populated report, many sources/citations, long generated text — "
                    "even if a spinner is still running? Or is there only an EMPTY / "
                    "PLACEHOLDER / loading state (e.g. 'Preparing…', a skeleton) that "
                    "looks frozen?\n"
                    "IMPORTANT — planning is NOT stuck: if the page shows a research "
                    "plan being drafted or already drafted ('Generating research plan', "
                    "a streaming plan outline, a plan with a 'Start research' button, "
                    "an active stop/streaming control), answer 'CONCLUSION: working' — "
                    "plan generation legitimately takes 10+ minutes with zero sources "
                    "and zero findings.\n"
                    "Answer 'CONCLUSION: stuck' ONLY if there is essentially no real "
                    "research output AND no plan activity (empty / placeholder / "
                    "frozen). Answer 'CONCLUSION: working' if substantial output is "
                    "visible OR a counter / progress indicator is actively climbing "
                    "OR plan generation is visible. If unsure, answer "
                    "'CONCLUSION: working'.")
                _confirmed_stuck = False
                try:
                    async def _stuck_probe_cua():
                        return await agent_loop(cua_client, browser, PROMPT_DIAGNOSE,
                            _stuck_mission, model=CUA_MODEL, max_iterations=3,
                            verbose=verbose, phase=2,
                            agent_name=agent_key_stuck, target_page=p["page"])
                    _sp = await _shadow_observed_cua(
                        p["page"], hotspot_id="poll-stuck-arbiter", phase=2,
                        platform=agent_key_stuck,
                        current_step="round_robin_stuck_arbiter",
                        context_hint=f"P2 stuck arbiter for {name} at {int(elapsed/60)}m — "
                                     "substantial output vs empty/frozen",
                        expected_outcome="'CONCLUSION: stuck' or 'CONCLUSION: working'",
                        cua_coro_factory=_stuck_probe_cua,
                        mission_prompt=f"{PROMPT_DIAGNOSE}\n\nTASK: {_stuck_mission}",
                        read_only=True) or {"text": ""}
                    _sp_text = (_sp.get("text") or "").lower()
                    _sp_match = re.search(r'conclusion\s*:\s*(stuck|working)', _sp_text)
                    _confirmed_stuck = bool(_sp_match and _sp_match.group(1) == "stuck")
                    # 2026-07-11: deliberately NOT stamping last_cua_check
                    # here — the arbiter probe used to, silently deferring the
                    # COMPLETION check by up to a full CUA_CHECK_INTERVAL on a
                    # WORKING verdict (FIFA run: the 15:17 arbiter pushed the
                    # next completion check from ~15:17 to 15:22, part of the
                    # anomalous 23m→33m gap on an already-complete report).
                    # Arbiter re-probe throttling comes from `stuck_warned_at`,
                    # stamped at probe entry above, not from this key. It used
                    # to be delegated to the WORKING branch's growth-clock reset
                    # below — which stops resetting after
                    # _ARBITER_MAX_WORKING_RESETS and left the probe running
                    # every tick from then on (08-11).
                except Exception as _spe:
                    log(f"[{name}] Stuck-arbiter CUA probe failed ({_spe}) — treating as "
                        "WORKING (conservative; no false card / auto-skip)", "WARN")
                    _confirmed_stuck = False
                if _confirmed_stuck:
                    p["stuck_warned_at"] = time.time()
                    p["stuck_alerted_at"] = time.time()
                    log(f"[{name}] CUA arbiter: CONFIRMED STUCK", "WARN")
                    # Try a reload FIRST — a confirmed-stuck page is the one state where
                    # re-navigating costs nothing, because the alternative is a card the
                    # user has to answer (or a 30-min auto-skip). The research itself
                    # runs platform-side; the tab is only a view onto it. Bounded the
                    # same three ways as the error-verdict rescue: once per agent per
                    # phase (SHARED latch, so an agent can't get two reloads), only for
                    # agents whose conversation survives a reload (never Gemini — its
                    # SPA lands on the empty home, #897a), and only here, never on the
                    # normal polling path. A recovered agent raises NO card at all.
                    if (name in RELOAD_SAFE and not p.get("_reload_rescue_used")
                            and p.get("page") is not None):
                        p["_reload_rescue_used"] = True
                        log(f"[{name}] stuck — reloading the tab once before carding it", "WARN")
                        _unstuck = False
                        try:
                            await p["page"].reload(wait_until="domcontentloaded", timeout=30000)
                            await asyncio.sleep(5)
                            _unstuck = bool(await verify_fns[name](p["page"]))
                        except Exception as _sr_err:
                            log(f"[{name}] stuck-reload failed ({_sr_err}) — carding", "WARN")
                        if _unstuck:
                            p["last_growth_time"] = time.time()
                            p["last_heartbeat"] = time.time()
                            p["stuck_alerted_at"] = 0.0  # match the retract path's type
                            log(f"[{name}] recovered after reload — still generating, no "
                                "card raised (silent self-heal)", "INFO")
                            continue
                        log(f"[{name}] still stuck after the reload — raising the "
                            "[Retry][Skip] card", "WARN")
                    else:
                        log(f"[{name}] raising the [Retry][Skip] card (no reload rescue "
                            f"available for this agent)", "WARN")
                    # #955 Phase 2: ARM the auto-skip deadline on the card itself
                    # (epoch-ms — the FE <AutoSkipCountdown> counts down to this
                    # exact value). _fire_due_autoskips fires it off the SAME
                    # deadline on the tick once it passes; a Retry / Skip / growth
                    # / WORKING re-verdict / poke / wait-longer disarms it first.
                    # stuck_alerted_at (set above) stays the in-loop "carded" flag,
                    # kept in lockstep with the registry at every disarm site.
                    # Arm ONLY when auto-skip is ON — otherwise the FE would count
                    # down to a fire that (correctly) never happens (the firer is
                    # gated on the same setting). Auto-skip OFF ⇒ no countdown, the
                    # card just waits for a manual Retry/Skip (pre-#955 behavior).
                    fail_agent(agent_key_stuck,
                               f"{name} seems stuck",
                               (f"{name} stopped producing output — likely a platform-side "
                                "glitch. Retry to restart it, or Skip to continue without it."),
                               auto_skip_deadline=(
                                   int((time.time() + AUTO_SKIP_UNACTED_SEC) * 1000)
                                   if _runtime.auto_skip_stuck else None))
                    # Non-blocking: the other agents keep polling; the command
                    # bus applies a user Retry/Skip on the next tick. If none
                    # comes, _fire_due_autoskips auto-skips after AUTO_SKIP_UNACTED_SEC.
                else:
                    # CUA saw real output the scraper couldn't (cross-origin
                    # iframe etc.). Reset the growth clock so we never
                    # false-alert (the 2026-04-28 class). Re-probe spacing is
                    # NOT this reset's job any more — it never was on a leg that
                    # had spent its extensions, which is how 08-11 got 28 probes
                    # in 31 minutes. `stuck_warned_at` at probe entry owns it.
                    #
                    # ⭐ 2026-08-05 — "STOPPED GROWING" AND "NEVER GREW ONCE" ARE
                    # NOT THE SAME FAILURE, and this branch treated them as one.
                    # `last_growth_len`/`last_growth_sources` start at 0 and are
                    # only ever raised by observed growth, so both still being 0
                    # means we have never read a single character or source since
                    # polling began. That is not a scraper blind spot on OUR
                    # conversation — it is the signature of a tab whose content
                    # does not belong to our send.
                    #
                    # In prod the arbiter reset the clock after 31 minutes of
                    # text_len:0/sources:0, on a screenshot whose own narration
                    # named a different subject out loud, and its verdict was
                    # reduced to one boolean and discarded. The reset also had no
                    # counter and no cap: each WORKING bought another full
                    # STUCK_NO_GROWTH_SEC, indefinitely.
                    #
                    # A WORKING verdict may still SUPPRESS the card — the
                    # cross-origin class this branch exists for is real — but on a
                    # never-grew leg it must not rewind the clock, so the next
                    # window arrives on schedule instead of never.
                    _never_grew = (p.get("last_growth_len", 0) == 0
                                   and p.get("last_growth_sources", 0) == 0)
                    p["arbiter_working_resets"] = p.get("arbiter_working_resets", 0) + 1
                    _reset_ok = (not _never_grew
                                 and p["arbiter_working_resets"] <= _ARBITER_MAX_WORKING_RESETS)
                    log(f"[{name}] CUA arbiter: WORKING — output visible despite flat "
                        f"scrape (verdict #{p['arbiter_working_resets']}); "
                        + ("resetting growth clock (no stuck alert)" if _reset_ok else
                           "NOT resetting the growth clock: " + (
                               f"we have never scraped a single character or source in "
                               f"{int(elapsed/60)}m — the visible output may predate our send"
                               if _never_grew else
                               f"the arbiter has already granted "
                               f"{_ARBITER_MAX_WORKING_RESETS} extensions")),
                        "INFO" if _reset_ok else "WARN")
                    # The arbiter's own reasoning, logged. It existed only in the
                    # narrator stream before, which is why a run whose vision text
                    # twice named the wrong topic took a forensic pass to read back.
                    if _sp_text:
                        log(f"[{name}] arbiter said: {_sp_text[:300]}", "DEBUG")
                    if _reset_ok:
                        p["last_growth_time"] = time.time()
                    # #929: a WORKING verdict must also DISARM Layer 3 and
                    # retract any earlier stuck card. Pre-fix, only renewed
                    # GROWTH cleared stuck_alerted_at — so an agent the
                    # arbiter itself just re-judged healthy (e.g. a long
                    # Gemini plan that shows no text growth) still hit the
                    # unacted-card auto-skip measured from the stale alert.
                    if p.get("stuck_alerted_at", 0.0):
                        p["stuck_alerted_at"] = 0.0
                        p["stuck_warned_at"] = 0.0
                        _disarm_registry(agent_key_stuck)   # #955 P2: flag↔registry lockstep
                        log(f"[{name}] WORKING re-verdict after a stuck alert — "
                            "retracting card, cancelling auto-skip", "INFO")
                        try:
                            emit_event("pipeline_warning", phase=2, agent=agent_key_stuck,
                                       error=f"{name} is working",
                                       details=f"{name} was re-checked and is still working — earlier alert withdrawn.",
                                       actions=[], alert_id=_agent_error_alert_id(agent_key_stuck, 2),
                                       auto_clear_on_resume=True)
                            _clear_pending_decision(agent_key_stuck)
                        except Exception:
                            pass
            # Apply any async decision that landed since last tick.
            if _controls.consume_poke_agent(agent_key_stuck):
                log(f"[{name}] User poked — sending 'please continue' follow-up")
                try:
                    await browser.switch_to_page(p["page"])
                    await paste_followup(p["page"], "Please continue — output the rest of your research.",
                                         name.lower(), label=f"{name}-poke")
                except Exception as _e:
                    log(f"[{name}] Poke failed: {_e}", "WARN")
                p["last_growth_time"] = time.time()
                # #929: a user interaction restarts the whole escalation —
                # pre-fix only the growth clock reset, so the Layer-3
                # unacted-card countdown (measured from stuck_alerted_at)
                # kept running and could auto-skip right after the poke.
                p["stuck_alerted_at"] = 0.0
                p["stuck_warned_at"] = 0.0
                _disarm_registry(agent_key_stuck)   # #955 P2: poke disarms the deadline
            if _controls.consume_wait_longer_agent(agent_key_stuck):
                log(f"[{name}] User granted another 20 min of no-growth budget")
                p["last_growth_time"] = time.time()
                # #929: same disarm as poke — "wait longer" is an explicit
                # user decision that the agent should keep running.
                p["stuck_alerted_at"] = 0.0
                p["stuck_warned_at"] = 0.0
                _disarm_registry(agent_key_stuck)   # #955 P2: wait-longer disarms the deadline

            # #930: continuous stage for the FE milestone stepper. The launch
            # sites emit stage="researching" exactly once (post-verify); if the
            # FE misses that one-shot (mid-run reload, hard retry, phase
            # restart) NOTHING in this poller moved the stepper off
            # "Submitted" while counters are scrape-blind (ChatGPT's
            # cross-origin iframe reads 0 sources/0 chars on a healthy run).
            # Re-affirm stage on every emit: "planning" while the scraper
            # reports a plan page (the FE keeps planning on Submitted by
            # design), "researching" otherwise — every agent in this loop was
            # verified generating (or alive-handed-off) at launch, and
            # genuinely-stuck agents are the L1/L2/L3 escalation's job, not
            # the stepper's. Terminal/idle statuses carry no stage, and an
            # empty stage is OMITTED from the emit so it never clobbers a
            # previously-set value in the FE's details merge.
            _p2_stage = ""
            if _scrape_phase == "planning":
                _p2_stage = "planning"
            elif (_status_val or "generating").lower() not in (
                    "done", "complete", "completed", "waiting", "queued",
                    "error", "failed"):
                _p2_stage = "researching"

            # Dedup: only emit when something meaningful changed (status / sources /
            # partialTextLen / sections-count). Otherwise we spam Firestore ~180 writes
            # per agent per run with identical payloads. Heartbeat still covers liveness.
            progress_key = json.dumps({
                "status": _status_val or "",
                "stage": _p2_stage,
                "sources": progress.get("sources", 0),
                "partialTextLen": _partial_text_len,
                "sections_len": len(progress.get("sections", []) or []),
                "steps_len": len(progress.get("steps", []) or []),
                # Coarse elapsed bucket so slow-moving scrapes still re-emit occasionally
                "elapsed_bucket": elapsed_sec // 30,
                # Without progress_label + tool_uses, transitions like
                # "Reading source 3" → "Reading source 4" with no text-len /
                # source delta get suppressed and starve the watchdog.
                "progress_label": (_progress_val or "")[:80],
                "tool_uses_len": len(progress.get("tool_uses", []) or []),
                # Same gap as P1 (research.py:~10515) — without these
                # entries, a search-only or sectionsDone-only delta is
                # suppressed and the FE graph series flat-lines through
                # whole search bursts. Required for real-curve rendering.
                "searches": int(progress.get("searches", 0) or 0),
                "sections_done": int(progress.get("sections_done", 0) or 0),
                "sections_total": int(progress.get("sections_total", 0) or 0),
                "observed_sources": int(progress.get("observed_sources", 0) or 0),
            }, sort_keys=True)
            # Phase prefix: _last_progress is process-global, so without it
            # a P1 entry could dedupe a P2 emit with the same key.
            _dedupe_key = f"p2:{agent_key}"
            if _last_progress.get(_dedupe_key) != progress_key:
                _last_progress[_dedupe_key] = progress_key
                emit_event("agent_progress", phase=2, agent=agent_key,
                    status=_status_val or "generating",
                    progress=_progress_val,
                    # #930: omit (don't blank) stage when we have no verdict
                    **({"stage": _p2_stage} if _p2_stage else {}),
                    sources=progress.get("sources", 0),
                    sourceUrls=progress.get("source_urls", []),
                    # {url,title} pairs — the REAL scraped source-panel titles
                    # (the raw-activity popup renders these instead of bare
                    # hostnames). Empty/absent → FE falls back to sourceUrls.
                    sourceItems=progress.get("source_items", []),
                    sections=progress.get("sections", []),
                    partialTextLen=_partial_text_len,
                    partialTextPreview=_obs_preview,
                    model=progress.get("model", ""),
                    thinking=progress.get("thinking", ""),
                    steps=progress.get("steps", []),
                    plan=progress.get("plan", ""),
                    toolUses=progress.get("tool_uses", []),
                    title=progress.get("title", ""),
                    visionNarration=_vision_narration_p2,
                    phaseSignal=_vision_phase_signal_p2,
                    panelOpen=bool(progress.get("panel_open", False)),
                    observedSources=int(progress.get("observed_sources", 0) or 0),
                    searches=int(progress.get("searches", 0) or 0),
                    # New rich-narration fields (2026-04-29). Consumed by the
                    # BE per-agent narrator + FE PhaseDropdown so the cards
                    # show "drafted 4/8 sections" / "currently focused on X"
                    # instead of "0 sources, 0 chars" stub copy.
                    sectionsDone=int(progress.get("sections_done", 0) or 0),
                    sectionsTotal=int(progress.get("sections_total", 0) or 0),
                    currentFocus=str(progress.get("progress", "") or "")[:200],
                    websitesCount=int(progress.get("searches", 0) or 0),
                    artifactCount=int(progress.get("artifact_count", 0) or 0),
                    elapsedSec=elapsed_sec,
                    expectedMinutes=get_expected_minutes(2),
                    scrapeOk=scrape_ok)
                # Per-agent progressHistory ring (mirrors P1 emit). Persisted
                # post-run for the FE GraphAnalysis sparklines + post-reload
                # in-tile chart restoration.
                try:
                    _hist_p2 = _runtime.agent_progress_history.setdefault(agent_key, [])
                    _hist_p2.append({
                        "t": int(elapsed_sec * 1000),
                        "sources": int(progress.get("sources", 0) or 0),
                        "chars": int(_partial_text_len or 0),
                        "sections": int(len(progress.get("sections", []) or [])),
                        "searches": int(progress.get("searches", 0) or 0),
                        "sectionsDone": int(progress.get("sections_done", 0) or 0),
                        "sectionsTotal": int(progress.get("sections_total", 0) or 0),
                    })
                    if len(_hist_p2) > 240:
                        del _hist_p2[:len(_hist_p2) - 240]
                except Exception:
                    pass
                # 2026-05-03: snapshot the rich fields so the P2 completion
                # emit at extract_and_record_agent can ship the same data to
                # the FE — without this, the `complete` event was bare and
                # the persisted Firestore agents map ended up missing
                # sourceUrls/sections/steps/searches, leaving the dropdown
                # post-completion card empty.
                try:
                    _runtime.agent_progress_snapshots[agent_key] = {
                        "source_urls": list(progress.get("source_urls", []) or [])[:_SOURCE_LIST_CAP],
                        "sections":    list(progress.get("sections", []) or [])[:20],
                        "steps":       list(progress.get("steps", []) or [])[:15],
                        "searches":    int(progress.get("searches", 0) or 0),
                        "observed_sources": int(progress.get("observed_sources", 0) or 0),
                        "sources":     int(progress.get("sources", 0) or 0),
                        "partial_text_len": int(_partial_text_len or 0),
                        "current_focus": str(progress.get("progress", "") or "")[:200],
                    }
                except Exception:
                    pass

            # Heartbeat every 60s per agent
            if time.time() - p.get("last_heartbeat", 0) >= 60:
                emit_event("heartbeat", phase=2, agent=agent_key)
                p["last_heartbeat"] = time.time()

            # ── Playwright-primary completion check (2026-04-25 strict) ─────
            # The detect_completion_* functions return (done, reason, snap)
            # where snap = {text_len, sources, steps}. They report done=True
            # ONLY when the platform's definitive done-marker is present
            # (Stop button gone + "Thought for X" / Share & Export visible /
            # research_complete card). Caller-side 2-cycle gate confirms
            # text + sources + steps are all flat across 2 polling cycles
            # before extracting — eliminates the partial_len>5000,
            # artifacts>=2, transient-keyword false positives.
            detect_fn = DETECT_FNS.get(name)
            # 2026-04-28: drop the MIN_WAIT shadow on completion detection.
            # MIN_WAIT was a CUA-cost gate (the CUA fallback at the bottom
            # of this loop still respects it). detect_completion_* is
            # cheap Playwright scraping with strict done-markers, so it's
            # safe to run from t=0 — and ChatGPT can finish in 54s flat
            # for some prompts, which the 5-min MIN_WAIT was hiding from
            # the FE entirely (agent stayed "generating" until MIN_WAIT
            # cleared, ~5 min after the BE could SEE it was done).
            if detect_fn:
                # 2026-07-10: Claude renders a FINISHED deep-research report — and
                # its "Research complete · N sources · Xm Ys" done-marker — inside a
                # VIRTUALIZED artifact/research panel. The bulk of it (the marker +
                # most source rows) is NOT in document.body.innerText until the
                # panel is scrolled, so the cheap DOM detector below kept returning
                # not-done on a genuinely-complete report and the run limped along
                # on the slow 5-min CUA fallback (live E2E 2026-07-10: ~50m flat at
                # "5 URLs, 15 steps", only CUA — which scrolls first, :24444 — ever
                # caught it). Scroll the panel + window to the bottom first so the
                # marker + full sources render into the DOM before we read them.
                # Claude-scoped: ChatGPT/Gemini detectors weren't affected and we
                # don't want to perturb their timing. Best-effort; a scroll failure
                # just leaves the prior (unscrolled) behavior.
                if name == "Claude":
                    try:
                        await p["page"].evaluate("""() => {
                            window.scrollTo(0, document.body.scrollHeight);
                            document.querySelectorAll(
                                'aside, [class*="artifact"], [class*="overflow-y"], '
                                + '[class*="overflow-auto"], [class*="scroll"], main'
                            ).forEach(c => { try { c.scrollTop = c.scrollHeight; } catch(e){} });
                        }""")
                        await asyncio.sleep(0.4)  # let the virtualizer render the newly-visible range
                    except Exception:
                        pass
                # 2026-08-19: Gemini's last-resort reason used to assert
                # "pre-research" about a run whose start we had confirmed ten
                # seconds earlier. The fact lives on the per-agent state, so it
                # is passed here rather than re-derived from the DOM — a DOM
                # re-derivation would be a fourth opinion about a question three
                # probes have already answered.
                _detect_kw = ({"running_confirmed": bool(p.get("gemini_running_confirmed"))}
                              if name == "Gemini" else {})
                try:
                    dom_done, dom_reason, snap = await detect_fn(p["page"], **_detect_kw)
                except Exception as _de:
                    log(f"[{name}] detect_completion error: {_de}", "WARN")
                    dom_done, dom_reason, snap = (False, f"detect_error: {_de}", {})
                p.setdefault("flat_history", [])
                p.setdefault("done_marker_first_at", 0.0)
                p.setdefault("extraction_attempts", 0)
                p.setdefault("last_notdone_log_at", 0.0)
                if not dom_done:
                    # Diagnostics (2026-07-10): surface WHY the cheap DOM detector
                    # isn't confirming done, throttled to ~2 min so a long run
                    # doesn't spam backend.log. Makes "stuck despite complete" a
                    # one-grep root-cause from the log alone (distinguishes
                    # stop_btn_present / running_weak_signal / no_done_marker /
                    # the empty-snapshot guard) — the old code logged nothing on
                    # the persistent not-done path, which is why this stall
                    # needed a code read to diagnose.
                    # ⭐ 2026-08-19: Gemini's reasons now carry WHICH signal
                    # spoke — `running_weak_signal (anim:…_pulse, …)`,
                    # `running_hidden_stop_btn`, `stale_start_btn_no_done_marker`
                    # — because the 08-19 stall was diagnosed from a reason
                    # string that named a state the run had already disproved.
                    # A reason that names its evidence is the difference between
                    # a grep and a code read.
                    _nd_now = time.time()
                    if _nd_now - p.get("last_notdone_log_at", 0.0) >= 120:
                        p["last_notdone_log_at"] = _nd_now
                        log(f"[{name}] DOM not-done: {dom_reason}; snap={snap}")
                    # Definitive done-marker absent — discard any flat history.
                    if p["flat_history"]:
                        log(f"[{name}] Done-marker lost — clearing flat_history ({dom_reason})")
                    p["flat_history"] = []
                    p["done_marker_first_at"] = 0.0
                else:
                    # Done-marker present — append snapshot. Need 2 snapshots
                    # over ≥30s all flat to extract (was 3 over ≥240s before
                    # 2026-04-28 v2; see history block below).
                    is_first_detection = (p["done_marker_first_at"] == 0.0)
                    if is_first_detection:
                        p["done_marker_first_at"] = time.time()
                    p["flat_history"].append((
                        int(snap.get("text_len", 0) or 0),
                        int(snap.get("sources", 0) or 0),
                        int(snap.get("steps", 0) or 0),
                    ))
                    p["flat_history"] = p["flat_history"][-2:]
                    log(f"[{name}] Done-marker confirmed #{len(p['flat_history'])} — "
                        f"{dom_reason}; snap={snap}")
                    # 2026-05-07 fast-confirm: on FIRST done-marker detection,
                    # do an inline re-poll instead of waiting for the next
                    # main-rotation tick (~120s at POLL_DEEP_RESEARCH cadence).
                    # Without this, even though the 2-snapshot gate is
                    # cheap to satisfy, the gap BETWEEN polling cycles is
                    # the dominant post-completion wait — user-observed
                    # "ChatGPT just finished but extraction hasn't started
                    # yet". Sleep matches the elapsed_done floor (30s) so
                    # the gate below clears in one shot. Trade-off: the
                    # other pending agents' status updates are delayed by
                    # ~30s on the iteration where any agent first detects
                    # done-marker — one-time per agent, net win.
                    if is_first_detection and len(p["flat_history"]) == 1:
                        _confirm_secs = int(os.environ.get("DG_DONE_FAST_CONFIRM_SECS", "30"))
                        log(f"[{name}] First done-marker — fast-confirm re-poll "
                            f"in {_confirm_secs}s (skipping wait for next main-rotation tick)")
                        await asyncio.sleep(_confirm_secs)
                        try:
                            dom_done2, dom_reason2, snap2 = await detect_fn(
                                p["page"], **_detect_kw)
                        except Exception as _de2:
                            log(f"[{name}] fast-confirm detect_completion error: {_de2}", "WARN")
                            dom_done2, dom_reason2, snap2 = (False, f"detect_error: {_de2}", {})
                        if not dom_done2:
                            # Done-marker disappeared during fast-confirm window —
                            # agent transitioned between phases or streaming
                            # resumed. Reset and let the main loop poll normally.
                            p["flat_history"] = []
                            p["done_marker_first_at"] = 0.0
                            log(f"[{name}] Fast-confirm: done-marker lost after "
                                f"{_confirm_secs}s — back to streaming. "
                                f"Reason: {dom_reason2}")
                            continue
                        p["flat_history"].append((
                            int(snap2.get("text_len", 0) or 0),
                            int(snap2.get("sources", 0) or 0),
                            int(snap2.get("steps", 0) or 0),
                        ))
                        p["flat_history"] = p["flat_history"][-2:]
                        log(f"[{name}] Fast-confirm snapshot #2 captured — "
                            f"{dom_reason2}; snap={snap2}")
                    elapsed_done = time.time() - p["done_marker_first_at"]
                    # 2026-04-28 v2: tightened gate — 2 snapshots over ≥30s
                    # (was 3 snapshots over ≥90s). Reason: at the default
                    # 120s POLL_DEEP_RESEARCH cadence, "3 snapshots" needed
                    # 240s of wall-clock minimum even when the agent was
                    # visibly done — that 4-minute gate was the dominant
                    # contributor to the user-reported "gap before phase
                    # end starts" (advisor 2026-04-28). The tolerance gate
                    # below already prevents false-positives on signal
                    # jitter from auto-expand mutators, so 2 snapshots are
                    # enough confirmation. Saves ~120-240s per agent.
                    if len(p["flat_history"]) < 2 or elapsed_done < 30:
                        # Not enough samples yet — keep polling.
                        continue
                    t0, s0, st0 = p["flat_history"][0]
                    t1, s1, st1 = p["flat_history"][1]
                    def _stable(a, b, tol=0.05):
                        hi = max(a, b); lo = min(a, b)
                        return hi == 0 or (hi - lo) <= max(2, hi * tol)
                    flat = (
                        _stable(t0, t1)
                        and s1 <= int(s0 * 1.02) + 1
                        and st1 <= st0 + 1
                    )
                    if not flat:
                        log(f"[{name}] Done-marker present but signals still moving — "
                            f"text {t0}→{t1}, sources {s0}→{s1}, "
                            f"steps {st0}→{st1}; keep polling")
                        # Trim history so we re-anchor on the next snapshot —
                        # if a single late mutation slipped through, the next
                        # tick's snapshot becomes the new baseline.
                        p["flat_history"] = p["flat_history"][-1:]
                        continue
                    p["extraction_attempts"] += 1
                    log(f"[{name}] CONFIRMED DONE — done-marker + 2 cycles flat "
                        f"(text={t1}, sources={s1}, steps={st1}, "
                        f"elapsed_since_marker={int(elapsed_done)}s). "
                        f"Starting extract_and_record (attempt {p['extraction_attempts']})")
                    # Read Claude's sources disclosure while the run is finished
                    # and the tab is still un-mutated. This has to happen BEFORE
                    # extract_claude_response, whose first act is to close the
                    # artifact panel. Mirrored at the CUA-confirmed-done site.
                    if name == "Claude":
                        await claude_finished_sources_read(
                            p["page"], p, _runtime.agent_progress_snapshots)
                    _queue_dir = (Path(__file__).parent / "queues" / _tracks_dir.name) \
                                 if _tracks_dir else None
                    res = await extract_and_record_agent(
                        name, p["page"], browser, cua_client,
                        queue_dir=_queue_dir,
                        elapsed_sec=int(elapsed),
                        verbose=verbose,
                        expected_text_len=int(_partial_text_len or 0),
                    )
                    # 2026-04-25: markdown-as-primary. "done" means text>0 +
                    # in-app primary emitted. res["url"] is the conversation
                    # URL (page.url) for resume; res["_in_app_url"] is the
                    # FE primary /documents?open=… link.
                    if res["status"] == "done":
                        _runtime.unregister_page(
                            name.lower().replace(" ", ""),
                            final_status="done",
                        )
                        _runtime.agent_chat_urls[
                            name.lower().replace(" ", "")
                        ] = res.get("url") or ""
                        results[name] = res
                        del pending[name]
                        log(f"[{name}] Extraction complete — "
                            f"{len(res['text'])} chars, "
                            f"in_app={(res.get('_in_app_url') or '')[:60]}, "
                            f"convo={(res.get('url') or '')[:60]}")
                        continue
                    # E4 (DGOPS-7366) cost guardrail: empty extraction → surface
                    # user decision on attempt 1, not 3. The DOM-primary
                    # ladder in extract_chatgpt_response means a real
                    # transient blip would be caught by the ladder itself,
                    # not by retrying the whole extraction 3 times.
                    log(f"[{name}] Extraction attempt {p['extraction_attempts']} "
                        f"returned no content — surfacing user decision", "WARN")
                    p["flat_history"] = []
                    p["done_marker_first_at"] = 0.0
                    # #777 (a): Claude's Tier-3 clipboard-hijack extraction can read
                    # back 0 chars on a GENUINELY-complete report (clipboard not yet
                    # populated / focus race — log shows "captured 0 chars … lens=[0,0]"),
                    # and when the WHOLE ladder comes back empty the E4/DGOPS-7366
                    # guardrail assumption (a real transient is caught INSIDE the
                    # ladder) doesn't hold → it surfaced a false "Hit a snag" on a
                    # successful run. Give Claude ONE silent re-extraction first: the
                    # done_marker_first_at / flat_history reset above makes the next
                    # ticks re-confirm the artifact is still complete, THEN re-run
                    # extract_and_record_agent (re-open canvas / re-copy) — far cheaper
                    # than the user's manual hard re-run and it recovers the transient
                    # clipboard read. ChatGPT/Gemini stay at attempt-1 (cap 1) → their
                    # behavior is byte-identical. A 2nd consecutive empty read for
                    # Claude (genuinely unreadable) still escalates to the user.
                    _empty_extract_cap = 2 if name == "Claude" else 1
                    if p["extraction_attempts"] < _empty_extract_cap:
                        log(f"[{name}] Empty extraction (attempt "
                            f"{p['extraction_attempts']}/{_empty_extract_cap}) on a "
                            f"confirmed-complete report — silent re-extraction before "
                            f"alerting (transient clipboard/focus race)", "INFO")
                        continue
                    fail_agent(agent_key,
                               f"Couldn't read {name}'s report",
                               (f"{name} finished but we couldn't pull its results. "
                                "Retry to try again, or Skip it."))
                    # #953 (audit): park (non-blocking) instead of freezing the
                    # loop for 10 min. Resolver: Retry → reset + re-run the tier
                    # ladder; Skip → loop-top consumer finalizes; Stop → break.
                    p["awaiting_decision"] = {
                        "kind": "extract_empty_pw", "key": agent_key,
                        "since": time.time(), "timeout": 600.0,
                    }
                    continue

            # Check completion — CUA-primary fallback (only if Playwright was
            # not confident within the MIN_WAIT + budget window). CUA checks
            # every 5 min per agent (cost-effective, actually works).
            if (time.time() - p.get("last_cua_check", 0)) < CUA_CHECK_INTERVAL:
                # Not time for CUA check yet — skip this agent this cycle
                continue

            # Enforce minimum wait before first check
            min_wait = MIN_WAIT.get(name, 180)
            if elapsed < min_wait:
                continue

            # CUA visual check — SCROLL TO BOTTOM first (stop button + loading indicator live near composer/end)
            await browser.switch_to_page(p["page"])
            try:
                await p["page"].evaluate("""() => {
                    window.scrollTo(0, document.body.scrollHeight);
                    // Also scroll common chat containers (ChatGPT DR has internal scroll)
                    // 2026-07-11: + aside/artifact/overflow containers (parity with the
                    // DOM detector's pre-scroll) — Claude renders the "Research
                    // complete · N sources" marker inside a VIRTUALIZED panel, and a
                    // screenshot that never scrolled it can hide the very completion
                    // evidence the vision check is asked to find.
                    const containers = document.querySelectorAll(
                        '[class*="react-scroll"], [class*="chat-messages"], main, [role="presentation"], [data-testid*="conversation"], ' +
                        'aside, [class*="artifact"], [class*="overflow-y"], [class*="overflow-auto"], [class*="scroll"]');
                    containers.forEach(c => { try { c.scrollTop = c.scrollHeight; } catch(e){} });
                }""")
                await asyncio.sleep(0.5)
            except Exception:
                pass
            log(f"[{name}] CUA checking completion ({int(elapsed/60)}m) — scrolled to bottom")
            # Platform-specific instruction for where to look for the stop signal
            platform_hint = {
                "ChatGPT": ("ChatGPT Deep Research renders the research output inside a RESEARCH CARD / DIALOG "
                            "(embedded in the chat, looks like a document panel). The stop button and progress "
                            "indicator live ON THAT CARD, not in the composer. Check if it still shows "
                            "'Researching...', a progress bar, or a stop button on the card. "
                            "Treat these as COMPLETE — no scrolling through the document needed: "
                            "(a) a chip/label reading 'Research completed in Xm · N citations' (it replaces the "
                            "'Researching…' chip when DR finishes), or (b) the Researching side panel replaced by "
                            "a DOCUMENT panel whose header has download and expand/enlarge buttons with NO stop "
                            "button and NO progress bar anywhere. A long finished document is COMPLETE — do NOT "
                            "answer 'still generating' just because you cannot see its end."),
                "Gemini": ("Gemini's 2026-07 UI has NO persistent bottom input box — a small launcher button "
                            "becomes the input only when clicked, so don't judge by the composer. A COMPLETED "
                            "deep research shows a report panel with a button row 'Contents', 'Share & Export', "
                            "'Create' (left to right) and a chat line \"I've completed your research. Feel free "
                            "to ask me follow-up questions or request changes.\" above the report tile. Say "
                            "'response complete' ONLY if those are visible AND there is no running spinner or "
                            "progress indicator; otherwise say 'still generating'."),
                "Claude": ("Claude shows a stop button in the composer/input area while generating. After completion, "
                            "two document artifact buttons/cards may appear. Check composer for stop button; absence "
                            "means done. IMPORTANT: a right-side artifact panel is usually OPEN (our tracker keeps it "
                            "open) and may still display a stale 'N sources and counting' progress label AFTER the "
                            "research has finished — that label alone is NOT evidence of generation, and the panel "
                            "covering the chat is NOT a reason to say generating. Treat these as COMPLETE: a card or "
                            "text reading 'Research complete · N sources · Xm Ys', or an artifact panel header with "
                            "Copy / Publish buttons — as long as there is no Stop button and no running spinner."),
            }.get(name, "")
            _rr_diag_mission = (
                f"{platform_hint}\n\n"
                "Is the AI still generating (stop button visible, loading animation, spinner, 'Researching...' indicator)? "
                "Or is the response FULLY complete (no stop button anywhere, no loading, the final paragraph visible)? "
                "Answer 'still generating' or 'response complete'. "
                "If you see a Stop button ANYWHERE on the page (composer OR research card), answer 'still generating'.")

            async def _rr_diag_cua():
                return await agent_loop(cua_client, browser, PROMPT_DIAGNOSE,
                    _rr_diag_mission,
                    model=CUA_MODEL, max_iterations=3, verbose=verbose,
                    phase=2, agent_name=normalize_agent_key(name), target_page=p["page"])

            # #839 act tier (read_only): the round-robin diagnose has its own
            # CONCLUSION:-marker parser below; read_only keeps Vision a pure
            # verdict (never a click), and mission_prompt carries the platform
            # hint + the exact answer protocol so Vision emits a parseable line.
            diag = await _shadow_observed_cua(
                p["page"], hotspot_id="poll-diagnose", phase=2,
                platform=normalize_agent_key(name),
                current_step="round_robin_completion_check",
                context_hint=f"P2 round-robin completion check for {name} at "
                             f"{int(elapsed/60)}m — {platform_hint[:200]}",
                expected_outcome="an honest 'still generating' or 'response complete' verdict",
                cua_coro_factory=_rr_diag_cua,
                mission_prompt=f"{PROMPT_DIAGNOSE}\n\nTASK: {_rr_diag_mission}",
                read_only=True) or {"status": "error", "text": ""}
            diag_text_raw = (diag.get("text") or "")
            diag_text = diag_text_raw.lower()
            p["last_cua_check"] = time.time()

            # ── Parse CUA diagnosis ──────────────────────────────────────
            # Old logic used bare substring matches — vulnerable to false
            # positives (e.g. "is NOT complete" contained "complete" →
            # is_done=True while agent was still running, causing premature
            # 0-char extractions at 23m). New logic:
            #   1. Prefer the structured "CONCLUSION: <verdict>" line that
            #      PROMPT_DIAGNOSE now mandates.
            #   2. If missing, use negation-aware heuristics.
            #   3. Stop-button-visible always vetos (per prompt decision rule).
            #   4. Default to still-generating on ambiguity (one extra CUA
            #      check is far cheaper than a zero-char extraction).
            # ⛔⛔ 2026-08-23 — THIS READER NEVER GOT THE CONTRACT'S DISCIPLINE.
            # It was `re.search(r'conclusion\s*:\s*(...)')`: unanchored, and
            # FIRST match wins. The prompt above says "the LAST line of your
            # response must be exactly one of" and then PRINTS ALL FOUR VALUES,
            # each on its own `CONCLUSION:` line — so a reply that quotes its
            # instructions, or reasons aloud before deciding, was read as the
            # first item on that menu rather than as the answer. That is the
            # #753 shape exactly, one function over from where it was fixed.
            #
            # ⭐ Cost, stated honestly. That rationale used to read "GENERATING
            # heads the list, so the likeliest misread turns a DONE into another
            # poll" — which was a property of the FIRST-match reader being
            # removed, left standing beside the LAST-match reader that replaced
            # it. Corrected 2026-08-23. Under the new reader the exposure moves
            # the other way and downward: a mid-sentence echo ("this is not the
            # NEEDS_CLICK state") no longer decides anything, so the expensive
            # misreads — a spurious `error` that drops the agent, a spurious
            # `needs_click` that re-arms the late-Start watch — get rarer, not
            # commoner. What remains is a reply that states two anchored
            # conclusions and means the last, which is what the prompt asks for.
            #
            # The unanchored search stays as the FALLBACK so no answer that
            # resolves today resolves differently, including the `CONCLUSION:`
            # and its value split across two lines.
            verdict = _last_verdict(diag_text, _CUA_CONCLUSION_LINE)
            if not verdict:
                _loose = re.search(
                    r'conclusion\s*:\s*(generating|done|needs_click|error)',
                    diag_text,
                )
                verdict = _loose.group(1) if _loose else ""

            is_error = False
            if verdict:
                is_done = verdict == "done"
                is_generating = verdict == "generating"
                is_error = verdict == "error"
                # ⛔⛔ 2026-08-17 — `needs_click` WAS PARSED AND THEN DROPPED.
                # The prompt mandates this verdict, the regex above captures it,
                # a variable holds it — and no branch ever acted on it, so it
                # collapsed into "none of the above", which the caller reads as
                # keep-waiting. During the 90-minute Gemini loss the vision tier
                # said, in as many words, "This is the NEEDS_CLICK state — a
                # 'Start research' button is visible and needs to be clicked",
                # and the run did nothing with it. Re-arm the late-Start watch:
                # the leg that owns pressing it is already bounded, enabled-only
                # and took-checked, so this hands the verdict to the one place
                # equipped to act on it rather than clicking from here.
                if verdict == "needs_click" and name.lower() == "gemini":
                    if not p.get("gemini_watch_start"):
                        log(f"[{name}] CUA says the run still NEEDS a Start click "
                            f"— re-arming the late-Start watch", "WARN")
                    p["gemini_watch_start"] = True
            else:
                still_running_phrases = (
                    "still in progress", "still running", "still researching",
                    "still being generated", "still working", "still generating",
                    "not complete", "not yet complete", "hasn't completed",
                    "has not completed", "not finished", "not yet done",
                    "not done yet", "isn't done", "is not done", "incomplete",
                )
                done_phrases = (
                    "response complete", "fully complete", "is complete",
                    "has completed", "appears complete", "finished generating",
                    "done generating", "no stop button", "no progress indicator",
                )
                stop_button_visible = bool(
                    re.search(r'stop button[^.]*\byes\b', diag_text) or
                    re.search(r'\bstop button\b[^.]{0,60}\b(visible|present|displayed|showing)\b', diag_text)
                )
                has_still_running = any(ph in diag_text for ph in still_running_phrases)
                has_done = any(ph in diag_text for ph in done_phrases)

                if stop_button_visible or has_still_running:
                    is_generating = True
                    is_done = False
                elif has_done:
                    is_done = True
                    is_generating = False
                else:
                    # Ambiguous — safer default
                    is_generating = True
                    is_done = False
                log(f"[{name}] CUA diag missing CONCLUSION line — heuristic verdict: "
                    f"{'generating' if is_generating else 'done' if is_done else 'unknown'}", "WARN")

            # ── Agent-side error verdict (e.g. ChatGPT "Research failed") ──
            # Without this branch the polling loop spins forever — neither
            # is_done nor is_generating fires and the agent gets stuck in
            # pending. Salvage whatever's on the page, fire fail_agent
            # once, drop the agent from rotation.
            if is_error:
                agent_key_err = normalize_agent_key(name)
                log(f"[{name}] CUA reported CONCLUSION: ERROR — agent UI shows a failure state. "
                    f"Salvaging partial output and dropping from rotation.", "WARN")
                _err_text = ""
                try:
                    _err_text = await extract_fns[name](
                        p["page"], browser=browser, cua_client=cua_client,
                        label=name, verbose=verbose) or ""
                except Exception as _e_err:
                    log(f"[{name}] Salvage extract during error verdict failed: {_e_err}", "WARN")

                # ── Reload rescue (ONE per agent per phase) ──────────────────────
                # Before this, an ERROR verdict was terminal: salvage + fail card +
                # drop, with no page action of any kind. Nothing in the whole poll
                # loop could reload or re-navigate — every navigation site in the
                # module is login, Cloudflare, post-completion extraction, or Gemini
                # *setup*. So on 2026-07-27 Claude was dropped over a TRANSIENT "We
                # couldn't connect to Claude. Please check your network connection and
                # try again." banner, which forced a manual hard retry that then cost
                # a cold tab and ~20 minutes.
                #
                # DELIBERATELY AFTER THE SALVAGE. A mid-run reload can BLANK the
                # claude.ai conversation — that is exactly why the old cycle-2
                # prophylaxis reload was removed (#953 / 2026-07-06) — so reloading
                # first would risk destroying the partial output we are about to keep.
                # Salvaging first makes the rescue free: worst case we drop with the
                # same text we would have had anyway.
                #
                # Safe because it is bounded three ways: once per agent per phase,
                # only for agents whose conversation survives a reload (never
                # Gemini), and only in the error branch — never the normal poll path.
                # A recovered agent raises NO alert: silent self-heal.
                if (name in RELOAD_SAFE and not p.get("_reload_rescue_used")
                        and p.get("page") is not None):
                    p["_reload_rescue_used"] = True
                    log(f"[{name}] error verdict — reloading the tab once to rule out "
                        "a transient page-level failure before dropping the agent "
                        f"(partial output already salvaged: {len(_err_text)} chars)", "WARN")
                    _rescued = False
                    try:
                        await p["page"].reload(wait_until="domcontentloaded", timeout=30000)
                        await asyncio.sleep(5)  # let the SPA rehydrate the conversation
                        # verify_*_generating gates on being on a real conversation
                        # URL, so a reload that lands blank cannot read as rescued.
                        _rescued = bool(await verify_fns[name](p["page"]))
                    except Exception as _rl_err:
                        log(f"[{name}] error-verdict reload failed ({_rl_err}) — "
                            "continuing to the drop path", "WARN")
                    if _rescued:
                        # Reset the growth clock: what stalled was the broken page,
                        # not the research.
                        p["last_heartbeat"] = time.time()
                        p["last_growth_time"] = time.time()
                        log(f"[{name}] recovered after reload — still generating, "
                            "keeping it in rotation (no alert: silent self-heal)", "INFO")
                        continue
                    log(f"[{name}] still not generating after the reload — dropping "
                        "from rotation", "WARN")
                # 2026-07-31 — THE 0-SECOND CARD RETRACTION.
                #
                # This branch used to raise the Retry/Skip card and then
                # `del pending[name]`. When this was the last polling agent, that
                # emptied `pending`, the round-robin exited on the same tick, and
                # the exit sweep (_finalize_unresolved_autoskips) auto-skipped the
                # agent immediately — logging "its Retry/Skip alert went
                # unanswered" about a card that had existed for ZERO seconds.
                # Observed: persisted 14:36:55, cleared 14:36:55. The user got 0
                # of the configured 1800 s.
                #
                # It cost a whole leg. The corpus has the counter-example: the
                # identical phase2_agent_claude_error card stood for 63 s on an
                # earlier run, the user clicked Retry, and the agent recovered to
                # status=done with 61,023 chars.
                #
                # Fix: PARK the agent instead of dropping it — the codebase's own
                # idiom for "this agent is waiting on a human" (session_expiry,
                # extract_empty_pw, claude_2artifact_hf all use it). The agent
                # stays in `pending`, so the loop keeps ticking and the other
                # agents keep polling, while the parked-decision resolver checks
                # for a decision once per tick and applies the park timeout.
                #
                # The deadline is stamped on the card with `arm_registry=False`:
                # the FE renders a countdown to the same epoch the park will
                # expire at, but no registry entry is created — _fire_due_autoskips
                # deliberately skips parked agents (line ~26141), so an armed
                # entry would be dead weight that could still fire if the park
                # were ever cleared without disarming. One timer, one actor.
                #
                # 2026-08-02 — the park must honour Settings → Pipeline →
                # auto-skip. Arming AUTO_SKIP_UNACTED_SEC unconditionally meant a
                # user who switched auto-skip OFF was shown a countdown to a fire
                # their setting says can never happen, and the agent was dropped
                # 30 minutes later anyway. Every sibling path honours the flag —
                # the stuck card, the L3 hard cap, the registry firer, the exit
                # sweep, and the P3 half of the very commit that introduced this
                # one.
                #
                # With the flag OFF the window is 0, which the parked block reads
                # as "no deadline, ever". We still PARK rather than dropping the
                # agent. The first attempt at this fix did drop it — reasoning
                # that a card with no timer needs no consumer, and that the two
                # backend finalizers (_finalize_unresolved_autoskips,
                # _fire_due_autoskips) both early-return when auto-skip is off so
                # nothing could retract it. Both halves were true and the
                # conclusion was still wrong: dropping the last polling agent
                # empties `pending`, which exits the round-robin, which lets
                # Phase 2 complete — and the WEB APP's phase_complete:2 handler
                # rewrites every agent alert whose status is not clean to
                # `type: "warn", actions: undefined`. The [Retry][Skip] buttons
                # vanish. That is the 0-second retraction again, reached through a
                # third actor in the other repo. Parking keeps `pending` non-empty,
                # so the phase stays open and the card stays answerable.
                _ae_window = unacted_window_sec(_runtime.auto_skip_stuck)
                if not p.get("failed_alert_emitted"):
                    fail_agent(agent_key_err,
                               f"{name} reported an error",
                               (f"{name} showed a 'research failed' error and we kept "
                                "what little it produced. Retry to run it fresh, or Skip it."),
                               **({"auto_skip_deadline": (time.time() + _ae_window) * 1000,
                                   "arm_registry": False} if _ae_window else {}))
                    p["failed_alert_emitted"] = True
                results[name] = {
                    "status": "agent_error",
                    "text": _err_text,
                    "url": p.get("url", ""),
                    "page": p["page"],
                    "elapsed_sec": int(elapsed),
                }
                # 2026-08-02 — void the stale completion signals before parking.
                #
                # The CUA just said the page is in a FAILURE state, so any earlier
                # "looks done" reading is void. This matters only because we PARK:
                # dropping used to throw the whole dict away, and the loop-top
                # hard-retry consumer reads exactly these two fields to decide a
                # Retry is stale. A leftover done_count of 1 from the tick before
                # the error (one CUA "done" needs two to confirm, so a single
                # reading survives) made that consumer log "the agent already
                # completed", retract the card, restart nothing, and auto-skip 30
                # minutes later with no second card — the user's Retry silently
                # swallowed by a guard meant for a completion race.
                void_completion_signals(p)
                p["awaiting_decision"] = {
                    "kind": "agent_error", "key": agent_key_err,
                    "since": time.time(), "timeout": _ae_window,
                }
                log(f"[{name}] parked kind=agent_error — "
                    + (f"its Retry/Skip card has {int(_ae_window / 60)} min before auto-skip"
                       if _ae_window else
                       "auto-skip is OFF, so its Retry/Skip card has no deadline and "
                       "waits for you (the agent's absolute "
                       f"{PER_AGENT_HARD_CAP_SEC // 60}-min limit is the only ceiling)")
                    + "; siblings keep polling", "INFO")
                continue

            if is_generating and not is_done:
                log(f"[{name}] CUA: still generating ({int(elapsed/60)}m)")
                p["done_count"] = 0
                continue

            if is_done:
                p["done_count"] += 1
                # Need 2 consecutive CUA "done" readings to confirm
                if p["done_count"] < 2:
                    # 2026-07-11 DOM corroboration (Claude): if the modern
                    # completion marker is ALREADY in the DOM, one CUA verdict
                    # + the marker is confirmation enough — waiting for a
                    # second vision pass costs a full rotation (~3-10 min) and
                    # a single misread resets the counter (FIFA run: the 15:12
                    # misread turned a ~6-min confirm into a ~24-min one). The
                    # marker only renders when streaming ends, and the
                    # downstream artifact-count gate re-checks it anyway.
                    _marker_corroborates = False
                    if name == "Claude":
                        # strict=True: only the anchored marker forms may
                        # substitute for the second CUA confirmation.
                        _marker_corroborates = await _claude_modern_marker(
                            p["page"], strict=True)
                    if not _marker_corroborates:
                        log(f"[{name}] CUA says done ({p['done_count']}/2 confirmations)")
                        p["last_cua_check"] = time.time() - 120  # Check again soon
                        continue
                    log(f"[{name}] CUA says done (1/2) + modern completion marker "
                        f"in DOM — accepting without a second CUA pass")
                    p["done_count"] = 2
                log(f"[{name}] CUA confirms complete ✓ ({int(elapsed/60)}m)")

                # ⭐ 2026-08-05 — ChatGPT-specific: NEVER-GREW veto. This is the
                # path that actually authorised the harvest, and ChatGPT was the
                # only agent arriving here unchecked: Gemini's source/length rule
                # is below, Claude's artifact rule after it, and control used to
                # fall straight past both to the extraction.
                #
                # The incident's scrape read `text_len: 0, sources: 0` for 31
                # minutes — the DOM correctly saying "this conversation produced
                # nothing for us" — and two vision "done" readings were enough to
                # save 120KB of someone else's finished report.
                #
                # ⚠ Deliberately NARROWER than Gemini's `< 3 sources / < 2000
                # chars`: ChatGPT Deep Research genuinely renders inside surfaces
                # the host-side scrapers can miss (the 2026-04-28 cross-origin
                # class), so a low count must stay acceptable. Requiring
                # literally-never-anything is the one reading that cannot be a
                # false positive — if we have never scraped a single character or
                # source, we have no evidence this conversation is ours at all.
                if (name == "ChatGPT"
                        and p.get("last_growth_len", 0) == 0
                        and p.get("last_growth_sources", 0) == 0):
                    p["never_grew_vetoes"] = p.get("never_grew_vetoes", 0) + 1
                    if p["never_grew_vetoes"] <= 1:
                        log(f"[ChatGPT] CUA says done but our scrapers have NEVER read a "
                            f"single character or source from this conversation in "
                            f"{int(elapsed/60)}m — refusing the verdict once "
                            f"(the visible output may predate our send)", "WARN")
                        p["done_count"] = 0
                        p["cua_confirmed"] = False
                        p["last_cua_check"] = time.time()
                        continue
                    log(f"[ChatGPT] second never-grew completion verdict at "
                        f"{int(elapsed/60)}m — not extracting; raising the card so a "
                        f"person decides", "ERROR")
                    # Mirror the mid-run error park exactly: honour the auto-skip
                    # setting (0 = no deadline, the card waits for a human), park
                    # rather than drop so `pending` stays non-empty and the card
                    # keeps its buttons, and void the stale done signals so the
                    # loop-top Retry consumer cannot mistake this for a
                    # completion race.
                    _ng_window = unacted_window_sec(_runtime.auto_skip_stuck)
                    if not p.get("failed_alert_emitted"):
                        fail_agent(
                            "chatgpt",
                            f"{name} may be showing another conversation",
                            (f"{name}'s page looks finished, but nothing we can read "
                             "ever came from it — the report on screen may not be "
                             "this run's. Retry to run it fresh, or Skip it."),
                            **({"auto_skip_deadline": (time.time() + _ng_window) * 1000,
                                "arm_registry": False} if _ng_window else {}))
                        p["failed_alert_emitted"] = True
                    void_completion_signals(p)
                    p["awaiting_decision"] = {
                        "kind": "agent_error", "key": "chatgpt",
                        "since": time.time(), "timeout": _ng_window,
                    }
                    continue

                # Gemini-specific: validate completion via source count + content length
                # Gemini Deep Research typically finds 10+ sources. If we have 0 sources
                # and minimal text early in the run, the "done" verdict is likely false.
                if name == "Gemini" and elapsed < (max_wait_min * 60 * 0.7):
                    try:
                        _gm_progress = await scrape_progress_gemini(p["page"])
                        _gm_sources = _gm_progress.get("sources", 0)
                        _gm_text = _gm_progress.get("partial_text_len", 0)
                        _gm_steps = len(_gm_progress.get("steps", []))
                        if _gm_sources < 3 and _gm_text < 2000:
                            log(f"[Gemini] CUA says done but only {_gm_sources} sources, "
                                f"{_gm_text} chars, {_gm_steps} steps at {int(elapsed/60)}m "
                                f"— likely still researching. Reverting.", "WARN")
                            p["done_count"] = 0
                            p["cua_confirmed"] = False
                            p["last_cua_check"] = time.time()
                            emit_event("agent_progress", phase=2, agent="gemini",
                                       status="generating",
                                       progress=f"Still researching — {_gm_sources} sources so far",
                                       elapsedSec=int(elapsed))
                            continue
                    except Exception:
                        pass

                # Claude-specific: validate completion via artifact count.
                # Research mode on Opus 4.8 with Adaptive Thinking USED to
                # produce TWO artifacts — (1) references, (2) the final
                # report. The 2026 layout collapses to ONE artifact card
                # whose text reads "Research complete · N sources · Xm Ys"
                # AND contains the full report inline. So:
                #
                #   • If body-text matches the "Research complete" marker
                #     → trust the done verdict regardless of artifact count
                #     (the marker only appears when streaming ends).
                #   • Else, fall through to the legacy artifact-count gate:
                #     < 80% budget + < 2 → revert to polling; ≥ 80% + < 2 →
                #     hard-fail with Retry/Skip/Wait modal.
                if name == "Claude":
                    try:
                        _art_count = await _count_claude_artifacts(p["page"])
                    except Exception:
                        _art_count = 2  # on DOM query failure, trust extraction
                    # 2026-04-26: bypass the artifact-count gate when the
                    # modern "Research complete · N sources · Xm Ys" marker
                    # is present. This lets the 1-artifact-card layout pass
                    # without nudging or hard-failing.
                    # 2026-05-04 marker set, 2026-07-11 hoisted into the shared
                    # _claude_modern_marker helper (also consulted at
                    # done_count==1 above so a single CUA misread can't cost a
                    # full extra confirmation round-trip).
                    _claude_completion_marker = await _claude_modern_marker(p["page"])
                    if _claude_completion_marker:
                        log(f"[Claude] Modern completion marker detected — accepting 1-artifact layout (art_count={_art_count})", "INFO")
                        # A1: telemetry so we can see how often this layout fires
                        # in the wild vs the legacy 2-artifact path.
                        try:
                            emit_event("agent_completion_detected", phase=2, agent="claude",
                                       layout="1-artifact-modern", art_count=_art_count)
                        except Exception:
                            pass
                        # Fall through to extraction (skip both gates below).
                    elif _art_count < 2 and elapsed < (max_wait_min * 60 * 0.8):
                        log(f"[Claude] CUA says done but only {_art_count} artifact(s) at "
                            f"{int(elapsed/60)}m — likely still researching. Reverting.", "WARN")
                        p["done_count"] = 0
                        p["cua_confirmed"] = False
                        p["last_cua_check"] = time.time()
                        emit_event("agent_progress", phase=2, agent="claude",
                                   status="generating",
                                   progress=f"Still researching — only {_art_count} artifact(s) so far",
                                   elapsedSec=int(elapsed))
                        continue
                    elif not _claude_completion_marker and _art_count < 2:
                        # ── C2: one-shot auto-nudge before the hard-fail modal ──
                        # Give Claude 90s to produce artifact 2 after an explicit
                        # ask, before interrupting the user. Fires once per agent
                        # per phase (p["nudged_artifact"]).
                        if not p.get("nudged_artifact"):
                            p["nudged_artifact"] = True
                            nudge_art = (
                                "Your research is incomplete — the final comprehensive report "
                                "artifact is missing. Please produce the complete research "
                                "document artifact now — include every section, finding, and "
                                "source. This is the deliverable document, not the references list."
                            )
                            try:
                                emit_event("agent_progress", phase=2, agent="claude",
                                           status="nudging",
                                           progress="Nudging Claude to publish artifact 2 (90s)…")
                                await browser.switch_to_page(p["page"])
                                await paste_followup(p["page"], nudge_art, "claude",
                                                     label="Claude-nudge-artifact")
                                log("[Claude] Sent artifact-2 nudge — waiting 90s")
                                await asyncio.sleep(90)
                            except Exception as _ne:
                                log(f"[Claude] Artifact nudge failed: {_ne}", "WARN")
                            # Rewind so next CUA tick re-checks artifact count
                            p["done_count"] = 0
                            p["cua_confirmed"] = False
                            p["last_cua_check"] = time.time()
                            p["start_time"] = time.time() - (max_wait_min * 60) + (10 * 60)
                            continue
                        # Hard-fail path — budget 80%+ spent and the 2nd
                        # artifact never materialized. Don't silently accept
                        # the 1st one (that's the references, not the report).
                        log(f"[Claude] Hard-fail: {int(elapsed/60)}m elapsed with only "
                            f"{_art_count} artifact(s) — final document missing", "ERROR")
                        agent_key_hf = "claude"
                        # agent_link_failed → AgentLinkFailedBanner with
                        # Retry · Skip. pipeline_warning lands on a phase-
                        # level surface the user won't notice.
                        # #955 Phase 5: author through the seam. This gains a
                        # stable alert_id (was missing → the card couldn't dedup
                        # or dismiss-latch) + decision_id, and pairs with the
                        # consumer fix (poll_agent_decision now consumes the
                        # agent_decision command agent-scoped) so the card's
                        # Retry/Skip finally work instead of resolving only on the
                        # 300s timeout. lastError/attempts preserved verbatim via
                        # **extra; title/details match the FE card (FE-inert). No
                        # mirror — the park is transient + non-blocking, and the
                        # decision_id lingering is harmless (no ai_upgrade after
                        # the catalog drop; no deadline).
                        try:
                            emit_decision(
                                intent="agent_link_failed",
                                event_name="agent_link_failed",
                                phase=2, agent=agent_key_hf,
                                facts={"title": "Couldn't get Claude's report link",
                                       "details": "Claude finished but we couldn't grab its result link."},
                                actions=_alert_actions_for("agent_link_failed", 2, agent_key_hf),
                                alert_id=f"phase2_agent_link_{agent_key_hf}",
                                attempts=1,
                                lastError="Claude produced its sources but not the full report. Retry to let it finish, or Skip it.")
                        except Exception:
                            pass
                        p.setdefault("hf_timeouts", 0)
                        # #953 (audit): park (non-blocking) instead of freezing
                        # the round-robin for 5 min. The resolver handles Retry
                        # (nudge for artifact 2) / Skip (loop-top consumer) /
                        # Stop / timeout — and its timeout path keeps the
                        # #929 "auto-skip after the 2nd unanswered timeout"
                        # behavior (salvage + agent_skipped + close tab).
                        p["awaiting_decision"] = {
                            "kind": "claude_2artifact_hf", "key": agent_key_hf,
                            "since": time.time(), "timeout": 300.0,
                        }
                        continue

                # 2026-04-25: CUA-confirmed done → run the same extract +
                # emit ladder used by the Playwright-confirmed path. Single
                # source of truth for save+emit (extract_and_record_agent),
                # no inline duplication. Empty extractions still revert to
                # polling (CUA likely misread completion).
                #
                # ⛔ The sources read is mirrored here deliberately, not by
                # oversight at one site: Claude completing via the CUA never
                # reaches the Playwright-confirmed path above, and the corpus run
                # this read exists for went through THIS one. One-shot latched on
                # `p`, so whichever path arrives first does the read and the other
                # is a no-op.
                if name == "Claude":
                    await claude_finished_sources_read(
                        p["page"], p, _runtime.agent_progress_snapshots)
                _queue_dir = (Path(__file__).parent / "queues" / _tracks_dir.name) \
                             if _tracks_dir else None
                res = await extract_and_record_agent(
                    name, p["page"], browser, cua_client,
                    queue_dir=_queue_dir, elapsed_sec=int(elapsed),
                    verbose=verbose,
                    expected_text_len=int(_partial_text_len or 0),
                )
                if res["status"] == "done":
                    _runtime.unregister_page(name.lower().replace(" ", ""),
                                              final_status="done")
                    _runtime.agent_chat_urls[name.lower().replace(" ", "")] = res.get("url") or ""
                    results[name] = res
                    del pending[name]
                    log(f"[{name}] CUA-confirmed extraction complete — "
                        f"{len(res['text'])} chars, "
                        f"in_app={(res.get('_in_app_url') or '')[:60]}")
                    continue
                # E4 (DGOPS-7366) cost guardrail: empty extraction → ask the
                # user immediately. The previous 3-attempt silent retry loop
                # could burn 30+ min wall time and $5-10 in CUA spend on a
                # Wayland clipboard-fail run that produced zero output. With
                # DOM extraction now primary in extract_chatgpt_response, an
                # empty result here means the canvas DOM is genuinely missing
                # — alert once, decide once.
                p.setdefault("empty_retries", 0)
                p["empty_retries"] += 1
                log(f"[{name}] CUA said done but extraction empty (attempt "
                    f"{p['empty_retries']}) — surfacing user decision", "WARN")
                ag_key_empty = name.lower().replace(" ", "")
                fail_agent(ag_key_empty,
                           f"Couldn't read {name}'s report",
                           (f"{name} finished but came back empty. "
                            "Retry to run it fresh, or Skip it."))
                # #953 (audit): park (non-blocking) instead of freezing the loop
                # for 5 min. Resolver: Retry → nudge + re-poll; Skip → loop-top
                # consumer; Stop → break; timeout → accept the empty result
                # (parity with the pre-#953 fall-through).
                # #953 (audit #7): remember elapsed AT PARK so a later Retry rolls
                # the budget back from here, not from a time that includes the
                # user's decision-wait.
                p["_empty_elapsed_at_park"] = int(elapsed)
                p["awaiting_decision"] = {
                    "kind": "extract_empty_cua", "key": ag_key_empty,
                    "since": time.time(), "timeout": 300.0,
                }
                continue
            else:
                p["done_count"] = 0
                p["cua_confirmed"] = False

        # #955 Phase 2: fire any due auto-skip deadline at the END of the tick —
        # AFTER every per-agent leg has scraped and had its chance to disarm
        # (growth-recovery / WORKING re-verdict / poke / wait-longer). Firing at
        # the TOP of the tick raced those disarms: an agent that resumed in the
        # last poll interval was auto-skipped one cycle before this tick's scrape
        # would have cleared its card (adversarial re-verify finding). User
        # skip/hard-retry commands were already consumed at the tick top, so an
        # explicit action still wins; the firer bails under stop/pause.
        await _fire_due_autoskips()

        # Status update per cycle
        if pending:
            parts = []
            for n, p in pending.items():
                m = int((time.time() - p["start_time"]) / 60)
                parts.append(f"{n}:{m}m")
            log(f"Still polling: {', '.join(parts)}")
            # #905: the trailing dwell is the LAST platform's "60 secs at
            # each platform" leg (the per-leg dwell above only fires between
            # platforms). Interruptible; drops to 10s once any agent shows a
            # done-marker (the 2-snapshot confirm gate wants a quick second
            # tick — successor of the 2026-04-28 30s fast path). Cycle 1 has
            # no dwell at all: panels first, Gemini check, straight into
            # cycle 2 which paces normally.
            if _tick_counter > 1:
                await _leg_dwell()

    # Auto-skip finalization (bug 2.5) — see the helper defined above. Natural
    # loop exit: every agent left `pending`; grey + close-tab any that ended
    # unresolved so the run never trails a red tile / open tab / "Complete" lie.
    await _finalize_unresolved_autoskips()

    return results


# ── Direct Playwright Submit (zero CUA cost) ─────────────────────────────────

async def submit_chatgpt_direct(browser, prompt):
    """Submit prompt to ChatGPT using direct Playwright selectors."""
    page = browser.page
    try:
        await asyncio.sleep(2)
        # Dismiss overlays
        for sel in ['button:has-text("Okay")', 'button:has-text("Got it")',
                    'button:has-text("Dismiss")', '[aria-label="Close"]']:
            try:
                btn = await page.query_selector(sel)
                if btn and await btn.is_visible(): await btn.click(); await asyncio.sleep(0.5)
            except Exception: pass

        # Find input
        textarea = None
        for sel in ['#prompt-textarea', 'div[contenteditable="true"]#prompt-textarea',
                    'textarea[placeholder*="Message"]', 'div[contenteditable="true"][data-placeholder]']:
            try:
                textarea = await page.wait_for_selector(sel, timeout=5000)
                if textarea: break
            except Exception: continue

        if not textarea:
            log("Direct submit: no textarea found", "WARN")
            return False

        await textarea.click()
        await asyncio.sleep(0.3)

        # insertText — instant, avoids ChatGPT's clipboard-to-file behavior
        try:
            await page.keyboard.insert_text(prompt)
        except Exception:
            try:
                await textarea.fill(prompt)
            except Exception:
                await page.keyboard.type(prompt, delay=5)

        await asyncio.sleep(0.5)

        # Send
        send_btn = None
        for sel in ['button[data-testid="send-button"]', 'button[aria-label="Send prompt"]', 'button[aria-label="Send"]']:
            try:
                send_btn = await page.query_selector(sel)
                if send_btn and await send_btn.is_enabled(): break
                send_btn = None
            except Exception: continue
        if send_btn:
            await send_btn.click()
        else:
            await page.keyboard.press("Enter")

        await asyncio.sleep(2)
        sent = await page.evaluate("""() => {
            const msgs = document.querySelectorAll('[data-message-author-role="user"]');
            return msgs.length > 0;
        }""")
        if sent: log("Direct submit: message sent ✓")
        return sent

    except Exception as e:
        log(f"Direct submit failed: {e}", "WARN")
        return False


# ── PDF Attachment (Playwright) ──────────────────────────────────────────────

async def attach_pdf_chatgpt(browser, pdf_path):
    """Attach a PDF to ChatGPT input via file chooser."""
    page = browser.page
    try:
        # Look for hidden file input first (most reliable)
        file_input = await page.query_selector('input[type="file"]')
        if file_input:
            await file_input.set_input_files(str(pdf_path))
            log(f"Attached PDF via hidden input: {Path(pdf_path).name}")
            await asyncio.sleep(2)
            return True

        # Fallback: click the attachment button and handle file chooser
        browser.set_upload_file(str(pdf_path))
        for sel in ['button[aria-label="Attach files"]', 'button[aria-label="Attach"]',
                    'button[data-testid="upload-button"]']:
            try:
                btn = await page.query_selector(sel)
                if btn and await btn.is_visible():
                    await btn.click()
                    await asyncio.sleep(3)
                    log(f"Attached PDF via button click: {Path(pdf_path).name}")
                    browser.clear_upload_file()
                    return True
            except Exception: continue

        browser.clear_upload_file()
        log(f"Could not find attachment button for: {Path(pdf_path).name}", "WARN")
        return False
    except Exception as e:
        browser.clear_upload_file()
        log(f"PDF attachment failed: {e}", "WARN")
        return False


# ── Response Extraction ──────────────────────────────────────────────────────
# Goal: extract the FULL response with proper formatting. Try platform's copy
# Extraction chain: HTML→MD (best formatting) → copy button → JS innerText → clipboard.


def html_to_markdown(html):
    """Convert HTML to clean markdown using markdownify. Preserves all formatting."""
    try:
        from markdownify import markdownify as md
        text = md(html, heading_style="ATX", bullets="-", strip=['img', 'script', 'style'])
        # Clean up excessive whitespace
        lines = text.split('\n')
        cleaned = []
        prev_empty = False
        for line in lines:
            is_empty = not line.strip()
            if is_empty and prev_empty:
                continue
            cleaned.append(line.rstrip())
            prev_empty = is_empty
        return '\n'.join(cleaned).strip()
    except ImportError:
        log("markdownify not installed — falling back to innerText", "WARN")
        return ""


# ChatGPT Deep Research wraps inline citation markers in Private Use Area
# sentinels:  starts a run,  separates tokens,  ends it.
# Two known prefix variants: "cite" (web/view/search citations) and
# "filecite" (file citations from user-attached docs). The PUA glyphs
# render as nothing in most fonts, so the user sees a long unbreakable
# token blob ("citeturn18view0turn18view1...") that the FE wraps as a
# wall of low-information noise. Stripping is safe by construction —
# PUA codepoints cannot appear in any legitimate prose (browser would
# render them as boxes), and the regex only matches between the two
# specific sentinels, so it cannot collide with the literal word "cite"
# elsewhere in text. Verified 2026-05-25 against a 39KB chatgpt.md
# from prod: 67 runs matched, 3,657 chars removed, zero PUA residue,
# zero false-matches on legitimate prose. Gemini/Claude extractors
# don't emit these sentinels (verified on same-day gemini.md / claude.md).
#
# Converting to numbered footnotes [1][2][3] was considered + rejected:
# the turn{N}{view|search|file}{M} indices reference ChatGPT's internal
# source list, NOT the source URLs we capture via observer-side
# extraction (research.py:~18261). Without a mapping we'd produce
# footnotes that point nowhere — strip is the correct choice.
_CHATGPT_CITE_TOKEN_RE = re.compile('[^]*')


def _strip_chatgpt_citation_tokens(md: str) -> str:
    """Strip ChatGPT's PUA-delimited citation token runs from extracted MD.
    Idempotent. No-op on input that doesn't contain the sentinels (e.g.,
    Gemini/Claude extractions), so safe to call from shared helpers if
    needed later."""
    if not md:
        return md
    return _CHATGPT_CITE_TOKEN_RE.sub('', md)


async def _extract_html_to_md(page, selectors, label):
    """Extract response HTML from page, convert to clean markdown.

    Returns a tuple-like sequence via the existing string return, but emits
    DEBUG telemetry on miss so the caller (and the next E2E) can see
    selector-level hit counts. Previously every miss was silent — when T2
    fell through on P2 ChatGPT we had no way to tell whether (a) no
    selectors matched, (b) selectors matched but innerHTML was too short,
    or (c) html_to_markdown returned an empty string."""
    biggest_html_len = 0
    biggest_sel = ""
    matched_sels = 0
    for sel in selectors:
        try:
            html = await page.evaluate(f"""() => {{
                const els = document.querySelectorAll('{sel}');
                if (els.length > 0) return els[els.length - 1].innerHTML;
                return '';
            }}""")
            if html:
                matched_sels += 1
                if len(html) > biggest_html_len:
                    biggest_html_len = len(html)
                    biggest_sel = sel
            if html and len(html) > 200:
                md_text = html_to_markdown(html)
                if md_text and len(md_text) > 100:
                    log(f"[{label}] Extracted via HTML→MD: {len(md_text)} chars")
                    return md_text
        except Exception:
            continue
    # Miss path — log what we found so the next failing E2E doesn't leave
    # us blind. matched_sels=0 means no selector hit any element (most
    # likely cause: DOM uses different class/data-testid conventions);
    # matched_sels>0 with biggest_html_len<=200 means content selectors
    # matched but the elements were empty/sparse (likely the wrong
    # container — narrow your selectors). INFO level so it survives
    # default log-level filters in prod.
    log(f"[{label}] HTML→MD miss: tried={len(selectors)} sels, matched={matched_sels}, "
        f"biggest_html_len={biggest_html_len}"
        + (f" (sel='{biggest_sel}')" if biggest_sel else ""), "INFO")
    return ""


def _chatgpt_dr_frame_targets(page):
    """Return the list of frame targets worth running hijack/HTML→MD
    against for ChatGPT Deep Research. Always begins with the main page,
    then appends any iframe whose URL matches the Deep Research sandbox.

    Why this exists (2026-05-13): the DR canvas/artifact lives inside a
    cross-origin sandboxed iframe (e.g.
    `connector_openai_deep_research.web-sandbox.oaiusercontent.com`).
    `page.evaluate` only sees the parent document, so every hijack
    attempt against the parent logged `no_button_clicked` and every
    HTML→MD scrape returned 0 chars — the chain fell through to CUA
    (Tier 3) which doesn't work on Wayland. Iterating frames here lets
    Tier 1 and Tier 2 actually reach the DR DOM.

    2026-08-06: delegates to `_chatgpt_surface_frame_targets`. It used to carry
    its own copy of the URL-substring list, and that list cannot describe an
    `about:blank`-mounted surface — the extraction tiers were as blind to the
    2026-08-06 canvas as the completion detector was, which is why that run fell
    all the way to the CUA download tier for a report sitting in a frame.
    """
    return _chatgpt_surface_frame_targets(page)


async def _extract_html_to_md_anyframe(page, selectors, label):
    """Frame-aware HTML→MD scrape. Tries the main page first, then any
    iframe matching the ChatGPT Deep Research sandbox URL.

    Mirrors `_extract_html_to_md` per-frame so the existing call-site
    semantics (returns "" on miss, logs the first selector that landed)
    stay intact. Sibling of `_chatgpt_dr_frame_targets`; same 2026-05-13
    motivation.

    DR-iframe density fallback (2026-05-14): when none of the supplied
    selectors matched a rich-enough container INSIDE the DR sandbox
    iframe, ask the iframe for its largest text-rich block (single
    element with the most non-whitespace text content, excluding nav/
    toolbar/composer chrome). Catches the "DR canvas uses plain divs,
    none of our `.markdown`/`.prose` selectors match" case that silently
    fell through to T3 clipboard hijack — and gives T2 a real chance to
    win even on DOM-drifted pages.

    Intentionally NOT applied to the main page: the conversation thread
    is a giant text-rich `<div>` (prompt + prior assistant turns) that
    would falsely outrank the DR document on cumulative textContent."""
    targets = _chatgpt_dr_frame_targets(page)
    for idx, target in enumerate(targets):
        try:
            md = await _extract_html_to_md(target, selectors, label)
        except Exception:
            md = ""
        if md:
            return md
        # Density fallback runs ONLY inside the DR sandbox iframe (idx > 0;
        # idx == 0 is the main page target which contains the chat thread).
        if idx == 0:
            continue
        try:
            html = await target.evaluate(r"""() => {
                // Chrome exclusion via TAGS + ARIA roles + data-testid (no
                // class-substring matches — those false-excluded real
                // content nodes named "section-header", "response-header-
                // wrapper", etc.).
                const isChrome = (el) => !!el.closest(
                    'nav, header, footer, aside, ' +
                    '[role="navigation"], [role="banner"], ' +
                    '[role="contentinfo"], [role="toolbar"], ' +
                    '[data-testid*="composer"], [data-testid*="sidebar"]'
                );
                let best = null;
                let bestLen = 0;
                // article/main/section are usually <100 nodes; div is the
                // long-tail. Cap div iteration at 500 to avoid O(n*subtree)
                // walks on huge thread-like DOMs.
                const tags = ['article', 'main', 'section', 'div'];
                const CAP_PER_TAG = 500;
                for (const tag of tags) {
                    const allEls = document.querySelectorAll(tag);
                    const limit = Math.min(allEls.length, CAP_PER_TAG);
                    for (let i = 0; i < limit; i++) {
                        const el = allEls[i];
                        if (isChrome(el)) continue;
                        const txt = (el.textContent || '').trim();
                        if (txt.length <= bestLen) continue;
                        // Skip wrappers that are just the page-body parent
                        // of the real content; require some structure
                        // (>=2 child text-bearing nodes) to bias toward
                        // content-rich containers over the body root.
                        const childCount = el.children?.length || 0;
                        if (childCount < 2) continue;
                        bestLen = txt.length;
                        best = el;
                    }
                }
                return best ? best.innerHTML : '';
            }""")
            if html and len(html) > 200:
                md_text = html_to_markdown(html)
                if md_text and len(md_text) > 500:
                    log(f"[{label}] Extracted via HTML→MD density fallback: {len(md_text)} chars (iframe target {idx})")
                    return md_text
        except Exception:
            pass
    return ""


async def _copy_via_hijack(
    page,
    label,
    *,
    canvas_root_selectors=None,
    kebab_selectors=None,
    menuitem_text_pattern=None,
    direct_copy_selectors=None,
    scoping_excludes=None,
    wait_ms=5000,
    min_chars=500,
):
    """Click an agent's Copy button while a JS hijack captures the
    markdown the page writes to navigator.clipboard.writeText /
    navigator.clipboard.write / synthetic copy event. Bypasses the OS
    clipboard entirely — works on Wayland, X11, Windows, macOS.

    Closes DGOPS-7366 (ChatGPT canvas selector drift) AND the Wayland
    0-char clipboard bug in one pattern: the agent's own Copy button is
    the canonical-markdown emitter, and the hijack catches it before it
    leaves the page context.

    Two click patterns supported:
    - direct_copy_selectors=[…]: click the first matching, visible,
      non-excluded button.
    - canvas_root_selectors + kebab_selectors + menuitem_text_pattern:
      scope to a canvas root, click a kebab/more button, then click the
      revealed menuitem whose text matches the regex pattern
      (case-insensitive).

    Robustness (per advisor cross-check 2026-05-12):
    - Single atomic page.evaluate so install + click + capture + restore
      runs in one JS lifetime. A thrown exception inside JS still hits
      the `restoreAll()` in the wrapping try/catch.
    - window.__dg_hijack_lock guard prevents concurrent hijacks on the
      same page from clobbering each other.
    - beforeunload listener auto-restores if the page navigates mid-
      hijack.
    - Hooks copy event (text/plain + text/html), navigator.clipboard.
      writeText (legacy/string), navigator.clipboard.write (modern/
      ClipboardItem). Belt-and-suspenders — agents use different paths.
    - Scoping excludes (defaults: dialogs, code blocks, nav, code-copy
      buttons) prevent the click from misfiring onto a "Copy code" or
      "Copy link" button.
    """
    DEFAULT_EXCLUDES = [
        'mat-dialog-container',
        'pre code',
        '[class*="code-block"]',
        '[class*="codeblock"]',
        'nav',
        '[role="navigation"]',
    ]
    excludes = scoping_excludes if scoping_excludes is not None else DEFAULT_EXCLUDES
    try:
        result = await page.evaluate(r"""(opts) => new Promise(async (resolve) => {
            const {
                canvas_root_selectors,
                kebab_selectors,
                menuitem_text_pattern,
                direct_copy_selectors,
                scoping_excludes,
                wait_ms,
            } = opts;
            if (window.__dg_hijack_lock) {
                resolve({ ok: false, reason: 'hijack_in_progress' });
                return;
            }
            window.__dg_hijack_lock = true;

            let capturedText = null;
            let capturedHtml = null;
            let captureSource = '';

            const copyHandler = (e) => {
                try {
                    if (!e.clipboardData) return;
                    const t = e.clipboardData.getData('text/plain');
                    const h = e.clipboardData.getData('text/html');
                    if (t && (!capturedText || t.length > capturedText.length)) {
                        capturedText = t;
                        captureSource = 'copy_event:text/plain';
                    }
                    if (h && (!capturedHtml || h.length > capturedHtml.length)) {
                        capturedHtml = h;
                        if (!capturedText) captureSource = 'copy_event:text/html';
                    }
                } catch {}
            };
            document.addEventListener('copy', copyHandler, { capture: true });

            const origWriteText = navigator.clipboard && navigator.clipboard.writeText
                ? navigator.clipboard.writeText.bind(navigator.clipboard) : null;
            if (origWriteText) {
                navigator.clipboard.writeText = async (t) => {
                    try {
                        if (t && (!capturedText || t.length > capturedText.length)) {
                            capturedText = t;
                            captureSource = 'writeText';
                        }
                    } catch {}
                    return origWriteText(t);
                };
            }

            const origWrite = navigator.clipboard && navigator.clipboard.write
                ? navigator.clipboard.write.bind(navigator.clipboard) : null;
            if (origWrite) {
                navigator.clipboard.write = async (items) => {
                    try {
                        for (const item of items || []) {
                            for (const t of (item.types || [])) {
                                try {
                                    const blob = await item.getType(t);
                                    const s = await blob.text();
                                    if (t === 'text/plain' && s
                                        && (!capturedText || s.length > capturedText.length)) {
                                        capturedText = s;
                                        captureSource = 'write:text/plain';
                                    } else if (t === 'text/html' && s
                                        && (!capturedHtml || s.length > capturedHtml.length)) {
                                        capturedHtml = s;
                                        if (!capturedText) captureSource = 'write:text/html';
                                    }
                                } catch {}
                            }
                        }
                    } catch {}
                    return origWrite(items);
                };
            }

            const beforeUnload = () => restoreAll();
            window.addEventListener('beforeunload', beforeUnload, { once: true });

            function restoreAll() {
                try { document.removeEventListener('copy', copyHandler, { capture: true }); } catch {}
                if (origWriteText) {
                    try { navigator.clipboard.writeText = origWriteText; } catch {}
                }
                if (origWrite) {
                    try { navigator.clipboard.write = origWrite; } catch {}
                }
                try { window.removeEventListener('beforeunload', beforeUnload); } catch {}
                window.__dg_hijack_lock = false;
            }

            function isExcluded(btn) {
                if (!scoping_excludes) return false;
                for (const ex of scoping_excludes) {
                    try {
                        if (btn.closest(ex)) return true;
                    } catch {}
                }
                return false;
            }

            try {
                let clickedSel = null;
                if (direct_copy_selectors && direct_copy_selectors.length > 0) {
                    for (const sel of direct_copy_selectors) {
                        try {
                            const btns = document.querySelectorAll(sel);
                            for (const b of btns) {
                                if (b.offsetWidth === 0 && b.offsetHeight === 0) continue;
                                if (isExcluded(b)) continue;
                                b.click();
                                clickedSel = sel;
                                break;
                            }
                            if (clickedSel) break;
                        } catch {}
                    }
                }
                if (!clickedSel && kebab_selectors && menuitem_text_pattern) {
                    let canvasRoot = document;
                    if (canvas_root_selectors) {
                        for (const sel of canvas_root_selectors) {
                            try {
                                const r = document.querySelector(sel);
                                if (r) { canvasRoot = r; break; }
                            } catch {}
                        }
                    }
                    let kebabSel = null;
                    for (const sel of kebab_selectors) {
                        try {
                            const btns = canvasRoot.querySelectorAll(sel);
                            for (const b of btns) {
                                if (b.offsetWidth === 0 && b.offsetHeight === 0) continue;
                                b.click();
                                kebabSel = sel;
                                break;
                            }
                            if (kebabSel) break;
                        } catch {}
                    }
                    if (kebabSel) {
                        await new Promise(r => setTimeout(r, 400));
                        const pat = new RegExp(menuitem_text_pattern, 'i');
                        const items = document.querySelectorAll(
                            '[role="menuitem"], [role="menu"] button, [role="menu"] [role="button"]'
                        );
                        for (const it of items) {
                            const txt = (it.textContent || '').trim();
                            if (pat.test(txt)) {
                                it.click();
                                clickedSel = 'kebab(' + kebabSel + ') → menuitem(' + txt.slice(0, 40) + ')';
                                break;
                            }
                        }
                    }
                }

                if (!clickedSel) {
                    restoreAll();
                    resolve({ ok: false, reason: 'no_button_clicked' });
                    return;
                }

                const start = Date.now();
                while (Date.now() - start < wait_ms) {
                    if (capturedText || capturedHtml) break;
                    await new Promise(r => setTimeout(r, 100));
                }

                restoreAll();
                resolve({
                    ok: !!(capturedText || capturedHtml),
                    text: capturedText,
                    html: capturedHtml,
                    source: captureSource,
                    clicked: clickedSel,
                });
            } catch (e) {
                restoreAll();
                resolve({ ok: false, reason: 'error:' + (e && e.message || String(e)) });
            }
        })""", {
            "canvas_root_selectors": canvas_root_selectors,
            "kebab_selectors": kebab_selectors,
            "menuitem_text_pattern": menuitem_text_pattern,
            "direct_copy_selectors": direct_copy_selectors,
            "scoping_excludes": excludes,
            "wait_ms": wait_ms,
        })

        if not result or not result.get("ok"):
            # 2026-05-13 diagnostic: surface what (if anything) the hijack
            # actually clicked. `no_capture` (button clicked, no clipboard
            # write within wait_ms) is the silent-fail case we couldn't
            # diagnose before — knowing the clicked selector lets us see
            # whether the wrong button was hit or the right button just
            # doesn't fire a copy event with hijackable mime types.
            _rclick = (result or {}).get("clicked") or "—"
            _rreason = (result or {}).get("reason") or "no_capture"
            log(f"[{label}] Copy hijack: {_rreason} (clicked={_rclick})", "DEBUG")
            return ""
        text = result.get("text") or ""
        html = result.get("html") or ""
        src = result.get("source", "")
        clicked = result.get("clicked", "")
        # Prefer text/plain (canonical markdown). Fall through to html→md
        # if text was empty or below min_chars but html is rich.
        if text and len(text) >= min_chars:
            log(f"[{label}] Copy hijack captured {len(text)} chars via {src} (clicked: {clicked})")
            return text
        if html and len(html) >= max(200, min_chars // 4):
            md = html_to_markdown(html)
            if md and len(md) >= min_chars:
                log(f"[{label}] Copy hijack captured {len(html)}B HTML → {len(md)} chars MD via {src} (clicked: {clicked})")
                return md
        log(f"[{label}] Copy hijack captured but too short (text={len(text)}, html={len(html)}, src={src})", "DEBUG")
        return ""
    except Exception as e:
        log(f"[{label}] Copy hijack exception: {e}", "WARN")
        return ""


async def _extract_via_cua_download(
    page,
    browser,
    cua_client,
    label,
    cua_prompt,
    cua_user_msg,
    *,
    max_iterations=12,
    cua_timeout_s=180.0,
    # Must be >= cua_timeout_s * 1000 + a small grace, because
    # page.expect_download() starts its clock when the async-with enters
    # (BEFORE the CUA loop runs). With the prior 30s default, a future
    # caller using defaults would race the listener vs the CUA loop's
    # cua_timeout_s=180s wall-clock cap. cua_timeout_s + 15s grace.
    download_timeout_ms=195000,
    min_chars=500,
    verbose=False,
):
    """Tier 1 primitive for CUA-driven download flows (ChatGPT + Claude).

    CUA navigates the UI per the prompt (close panel, open canvas, click
    download icon, click Export/Download as Markdown menu item). Playwright's
    `expect_download()` captures the resulting file. Read as UTF-8 markdown.

    Wayland-safe: no OS clipboard. Selector-free: CUA does all clicking.

    Why this is Tier 1: it sidesteps DOM selector drift entirely. ChatGPT
    canvas / Claude artifact download buttons are visually consistent
    across versions; CUA finds them by sight. The download event hook is
    selector-independent — Playwright intercepts whichever file the menu
    item triggers.

    Returns "" on any failure (CUA exhausts iterations → expect_download
    never fires; or CUA cap hit → asyncio.TimeoutError; or content <
    min_chars). The empty return is the contract for the caller's Tier-2
    fallback.
    """
    if browser is None or cua_client is None:
        return ""
    try:
        await browser.switch_to_page(page)
    except Exception as e:
        log(f"[{label}] CUA download: switch_to_page failed: {e}", "WARN")
        return ""

    download = None
    cua_completed = False
    # Idempotency (#732): CUA is a vision agent, and Claude's artifact
    # "Download as Markdown" menu item does NOT visibly close after a click,
    # so the agent concludes the click "didn't register" and re-clicks —
    # observed up to 6× in prod (backend.log 14:36), each click a real .md
    # download. (Stuck-detection didn't help: it keys on action+coordinate
    # and CUA's repeat clicks drift by a pixel or two.) The old
    # expect_download captured only the FIRST file but let agent_loop keep
    # running — and clicking. Fix: capture via an explicit listener that sets
    # _dl_event on the first file, and pass _dl_event into agent_loop as its
    # abort signal — the loop checks it every iteration AND before each tool
    # dispatch, so it issues NO further clicks once a file lands (deterministic
    # even though the sync Anthropic call freezes the loop between turns). A
    # task .cancel() is kept as a backstop; any straggler is deleted in finally.
    _extra_downloads = []
    _dl_event = asyncio.Event()

    def _capture_download(dl):
        nonlocal download
        if download is None:
            download = dl
            _dl_event.set()
        else:
            _extra_downloads.append(dl)

    page.on("download", _capture_download)
    loop_task = None
    dl_task = None
    try:
        # Run the CUA loop and the first-download wait concurrently. The loop
        # self-bounds at cua_timeout_s (asyncio.wait_for); download_timeout_ms
        # is only a backstop on the race coordinator.
        loop_task = asyncio.ensure_future(
            asyncio.wait_for(
                agent_loop(
                    cua_client, browser,
                    cua_prompt, cua_user_msg,
                    model=CUA_MODEL,
                    max_iterations=max_iterations,
                    verbose=verbose,
                    target_page=page,
                    abort_event=_dl_event,
                ),
                timeout=cua_timeout_s,
            )
        )
        dl_task = asyncio.ensure_future(_dl_event.wait())
        try:
            await asyncio.wait(
                {loop_task, dl_task},
                timeout=download_timeout_ms / 1000.0,
                return_when=asyncio.FIRST_COMPLETED,
            )
        except Exception:
            pass

        # Download landed first → stop CUA before it can re-click the menu
        # item and trigger duplicate downloads.
        if _dl_event.is_set() and not loop_task.done():
            loop_task.cancel()

        # Settle the loop task (consume its result/exception so it isn't
        # reported as never-retrieved). A cancel here is the SUCCESS path —
        # we already captured the file.
        try:
            await loop_task
            cua_completed = True
        except asyncio.CancelledError:
            pass
        except asyncio.TimeoutError:
            log(f"[{label}] CUA download: CUA timed out after {cua_timeout_s}s", "WARN")
        except Exception as e:
            log(f"[{label}] CUA download: CUA raised: {e}", "WARN")

        # CUA finished/timed out without a download yet — give a short grace
        # window for an in-flight file (mirrors the old expect_download
        # post-body grace).
        if download is None:
            try:
                await asyncio.wait_for(_dl_event.wait(), timeout=15.0)
            except asyncio.TimeoutError:
                pass

        if download is None:
            log(f"[{label}] CUA download: no download event within "
                f"{download_timeout_ms}ms (cua_completed={cua_completed})", "WARN")
            return ""

        # Read the captured file off-thread — a research report can be 100KB+
        # and a sync read would block the event loop (codebase to_thread norm).
        try:
            path = await download.path()
            if not path:
                log(f"[{label}] CUA download: download.path() returned None", "WARN")
                return ""

            def _read_md(p):
                with open(p, "r", encoding="utf-8", errors="replace") as f:
                    return f.read()

            content = await asyncio.to_thread(_read_md, path)
        except Exception as e:
            log(f"[{label}] CUA download: file read failed: {e}", "WARN")
            return ""

        if not content or len(content) < min_chars:
            log(f"[{label}] CUA download: captured {len(content or '')} "
                f"chars < min {min_chars} (cua_completed={cua_completed})", "WARN")
            return ""
        log(f"[{label}] CUA download captured {len(content)} chars "
            f"(cua_completed={cua_completed})")
        return content
    finally:
        # Detach the listener so it can't fire on a later phase's download
        # (e.g. the NotebookLM audio handler) or leak across runs.
        try:
            page.remove_listener("download", _capture_download)
        except Exception:
            pass
        # Cancel the download waiter if it never fired (avoid a dangling task).
        if dl_task is not None and not dl_task.done():
            dl_task.cancel()
        # Stop the CUA loop on EVERY exit path (incl. an outer cancel of this
        # coroutine), so a still-running agent_loop can't keep clicking.
        if loop_task is not None and not loop_task.done():
            loop_task.cancel()
        # Best-effort cleanup of Playwright temp files — the captured file
        # plus any duplicate downloads CUA triggered before we stopped it.
        for _extra in _extra_downloads:
            try:
                await _extra.delete()
            except Exception:
                pass
        if download is not None:
            try:
                await download.delete()
            except Exception:
                pass


async def _run_with_clipboard_hijack(
    page,
    label,
    trigger,
    *,
    timeout_ms=30000,
    min_chars=500,
):
    """Tier 3 primitive — install JS clipboard hooks in main page + all
    frames, run a caller-supplied async trigger (Playwright keyboard chord,
    button click, CUA agent_loop), then read the longest captured text
    back from `window.__dg_cb_captured_text` across every frame.
    Wayland-safe — never reads the OS clipboard.

    Captures from THREE sources per frame (longest wins):
    - `copy` event `clipboardData.getData('text/plain')` (page-side
      handlers that call setData — e.g. Gemini's Copy contents).
    - `window.getSelection().toString()` from inside the copy handler
      (RAW Ctrl+C path: the browser's default copy puts text onto the
      OS clipboard WITHOUT populating clipboardData, but the selection
      object still reflects what got copied).
    - navigator.clipboard.writeText / write (modern async API).

    Iframe coverage (2026-05-14): ChatGPT Deep Research canvas + Claude
    artifact bodies render inside sandbox iframes. CUA's Ctrl+A selects
    text INSIDE the iframe, so main-page getSelection() returns empty.
    We install the hook in EACH frame; each writes to its own window-
    scoped __dg_cb_captured_text; the poll step reads from every frame
    and returns the longest.

    `__dg_cb_*` global namespace is distinct from the older
    `_copy_via_hijack` (`__dg_hijack_lock`) so both helpers can coexist
    on the same page without races.

    `timeout_ms` bounds the trigger's run time. Set it ABOVE the trigger's
    own internal wait_for cap when wrapping a CUA loop (e.g. 200000 around
    an inner wait_for(180.0)) — otherwise the helper kills CUA prematurely.
    """
    install_script = r"""() => {
        if (window.__dg_cb_hijack_active) return false;
        window.__dg_cb_hijack_active = true;
        window.__dg_cb_captured_text = '';

        const setIfLonger = (s) => {
            try {
                if (s && s.length > (window.__dg_cb_captured_text || '').length) {
                    window.__dg_cb_captured_text = s;
                }
            } catch {}
        };

        const copyHandler = (e) => {
            // Source A: clipboardData (page-side setData path — works for
            // Copy buttons whose handlers call setData explicitly).
            try {
                if (e && e.clipboardData) {
                    setIfLonger(e.clipboardData.getData('text/plain') || '');
                }
            } catch {}
            // Source B (2026-05-14 fix): window.getSelection() — captures
            // the visually-selected text regardless of who triggered the
            // copy. Required for the RAW Ctrl+C path (CUA / Playwright
            // keyboard chord) where the browser's default copy puts text
            // onto the OS clipboard WITHOUT populating clipboardData.
            try {
                const sel = (window.getSelection && window.getSelection())
                    ? window.getSelection().toString() : '';
                setIfLonger(sel || '');
            } catch {}
        };
        document.addEventListener('copy', copyHandler, { capture: true });

        const origWriteText = navigator.clipboard && navigator.clipboard.writeText
            ? navigator.clipboard.writeText.bind(navigator.clipboard) : null;
        if (origWriteText) {
            navigator.clipboard.writeText = async (t) => {
                setIfLonger(t || '');
                return origWriteText(t);
            };
        }

        const origWrite = navigator.clipboard && navigator.clipboard.write
            ? navigator.clipboard.write.bind(navigator.clipboard) : null;
        if (origWrite) {
            navigator.clipboard.write = async (items) => {
                try {
                    for (const item of items || []) {
                        for (const ty of (item.types || [])) {
                            try {
                                const blob = await item.getType(ty);
                                const s = await blob.text();
                                if (ty === 'text/plain') setIfLonger(s || '');
                            } catch {}
                        }
                    }
                } catch {}
                return origWrite(items);
            };
        }

        const beforeUnload = () => { try { window.__dg_unhook?.(); } catch {} };
        window.addEventListener('beforeunload', beforeUnload, { once: true });

        window.__dg_unhook = () => {
            try { document.removeEventListener('copy', copyHandler, { capture: true }); } catch {}
            if (origWriteText) {
                try { navigator.clipboard.writeText = origWriteText; } catch {}
            }
            if (origWrite) {
                try { navigator.clipboard.write = origWrite; } catch {}
            }
            try { window.removeEventListener('beforeunload', beforeUnload); } catch {}
            window.__dg_cb_hijack_active = false;
        };
        return true;
    }"""

    # Collect every frame target (main + iframes). `page` itself covers
    # the main frame's window scope; iterate page.frames to pick up
    # iframes (skipping main_frame to avoid double-install).
    try:
        frame_list = list(page.frames)
    except Exception:
        frame_list = []
    targets = [page]
    for f in frame_list:
        try:
            if f is page.main_frame:
                continue
        except Exception:
            continue
        targets.append(f)

    installed_targets = []
    try:
        # ── Step 1: install hook in every target ──
        for tgt in targets:
            try:
                ok = await tgt.evaluate(install_script)
                if ok is not False:
                    installed_targets.append(tgt)
            except Exception as e:
                # Frame detached, cross-origin restriction we can't bypass,
                # or sandbox refusal. Skip and continue.
                try:
                    _url = getattr(tgt, "url", None) or "—"
                except Exception:
                    _url = "—"
                log(f"[{label}] Clipboard hijack: install skipped on frame "
                    f"({_url[:80]}): {type(e).__name__}", "DEBUG")
        if not installed_targets:
            log(f"[{label}] Clipboard hijack: install failed on all frames", "WARN")
            return ""

        # ── Step 2: run trigger (Playwright/CUA/whatever the caller wants) ──
        try:
            await asyncio.wait_for(trigger(), timeout=timeout_ms / 1000.0)
        except asyncio.TimeoutError:
            log(f"[{label}] Clipboard hijack: trigger exceeded {timeout_ms}ms", "WARN")
        except Exception as e:
            log(f"[{label}] Clipboard hijack: trigger raised: {e}", "WARN")

        # ── Step 3: poll for async clipboard writes across all frames ──
        captured = ""
        for _ in range(5):
            for tgt in list(installed_targets):
                try:
                    v = await tgt.evaluate(
                        "() => window.__dg_cb_captured_text || ''"
                    )
                except Exception:
                    # Frame detached mid-poll (canvas closed by CUA's
                    # final click). Drop it from the active set and keep
                    # reading the others.
                    try:
                        installed_targets.remove(tgt)
                    except ValueError:
                        pass
                    continue
                if v and len(v) > len(captured):
                    captured = v
            if captured and len(captured) >= min_chars:
                break
            await asyncio.sleep(0.2)

        if not captured or len(captured) < min_chars:
            # Per-frame capture-length distribution — distinguishes
            # "one frame caught a short capture, others dry" (selector
            # / scope problem) from "all frames dry" (trigger never
            # produced a copy event in any frame at all). The aggregate
            # `frames=N` count alone can't tell those apart, which made
            # the 2026-05-25 Kalki Gemini T1 zero-char failure hard to
            # diagnose. -1 entries mean the frame detached between the
            # poll loop and this introspection.
            per_frame_lens = []
            for tgt in installed_targets:
                try:
                    _l = await tgt.evaluate(
                        "() => (window.__dg_cb_captured_text || '').length"
                    )
                    per_frame_lens.append(int(_l))
                except Exception:
                    per_frame_lens.append(-1)
            log(f"[{label}] Clipboard hijack: captured {len(captured or '')} "
                f"chars < min {min_chars} (frames={len(installed_targets)} "
                f"lens={per_frame_lens})", "WARN")
            return ""
        log(f"[{label}] Clipboard hijack captured {len(captured)} chars "
            f"(across {len(installed_targets)} frame target(s))")
        return captured
    finally:
        # Restore originals on every frame we installed into.
        for tgt in installed_targets:
            try:
                await tgt.evaluate(
                    "() => { try { window.__dg_unhook && window.__dg_unhook(); } catch {} }"
                )
            except Exception:
                pass


async def extract_chatgpt_response(page, browser=None, cua_client=None, label="ChatGPT", verbose=False):
    """Extract ChatGPT response — 3 Wayland-safe tiers (rewritten 2026-05-14).

    Per-agent extraction model is intentionally divergent (the PR body's
    "T1 = X, T2 = Y, T3 = Z" describes the META-pattern — DOM → CUA →
    clipboard-hijack — not a uniform per-agent mapping):
      - ChatGPT (this fn): CUA download → HTML→MD → CUA copy hijack
      - Gemini (`extract_gemini_response`, research.py:19575): Share&Export
        hijack → HTML→MD → Ctrl+A/C hijack (reordered 2026-05-24 — native
        Share & Export menu is Gemini's authoritative export path; DOM
        scrape is the deterministic fallback when CUA can't drive the menu)
      - Claude (`extract_claude_response`, research.py:16640): two-mode —
        3 tiers in Deep Research artifact-aware mode (T1 CUA-download →
        T2 HTML→MD of the open artifact panel → T3 CUA + clipboard hijack;
        publish moved OUT of T2 to the end share-link step on 2026-06-03 so
        Claude matches ChatGPT/Gemini's DOM-scrape fallback — was T2 publish
        + claude.site HTML→MD, collapsed from a 4-tier ladder 2026-05-13).
        Targets the LAST
        artifact since DR produces 2 (tracking checklist + final report).
        Chat-mode branch has its own Tier 1/2 (HTML→MD primary, Copy
        hijack fallback) — fires when Research wasn't enabled and the
        operator continued in chat.

    ChatGPT-specific tier ordering:
      Tier 1: CUA-driven download flow (close source panel, open canvas
              full-page, click download icon, click "Export to Markdown",
              expect_download captures the .md). Selector-free; CUA does
              all clicking. Wayland-safe.
      Tier 2: HTML→MD on whatever canvas state Tier 1 left mounted (canvas
              should be open full-page from CUA's enlarge click).
      Tier 3: CUA Copy + JS clipboard hijack (Ctrl+A/C with getSelection
              + iframe-aware install). Wayland-safe.

    Phase 1 (brief extraction) calls with browser=None / cua_client=None so
    Tier 1 + Tier 3 gate off — Tier 2 HTML→MD is its SOLE path (the brief is
    inline extended-thinking text: no result panel / download button / canvas
    for a CUA tier to act on, so HTML→MD is both correct and sufficient there;
    P1's own extraction-fail auto-retry in run_phase1 re-pulls via HTML→MD).

    ChatGPT Deep Research (P2) outputs a document/artifact card, not regular
    chat text — which is why P2 passes browser+cua to enable Tier 1/3."""
    await asyncio.sleep(2)
    await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    await asyncio.sleep(1)

    # ── Tier 1: CUA-driven download flow ──
    # CUA handles: close any open side panel, click the artifact-card
    # enlarge button (opens canvas full-page), click the canvas's
    # download icon (top-right, distinct from Share icon), click
    # "Export to Markdown" in the dropdown. Playwright `expect_download()`
    # captures the resulting .md file. Selector-free end-to-end; CUA's
    # vision finds buttons regardless of DOM drift.
    if browser and cua_client:
        md = await _extract_via_cua_download(
            page, browser, cua_client, label,
            PROMPT_CHATGPT_DOWNLOAD_MD,
            "Close any open side panel, open the canvas, then click the "
            "download icon and choose Export to Markdown.",
            max_iterations=12, cua_timeout_s=180.0,
            # download_timeout_ms must exceed cua_timeout_s, since
            # page.expect_download() starts its clock when the `async with`
            # enters — which is BEFORE the CUA loop runs. With the prior
            # 30s value, ChatGPT's CUA loop (which takes ~30-45s to reach
            # the final 'Export to Markdown' click) would race the
            # listener: the listener expired ~2s before the click fired,
            # so the actual download wasn't captured and T1 silently
            # fell back to T3 clipboard hijack (which loses markdown
            # structure). cua_timeout_s + 15s grace covers the final
            # click + download-event RTT.
            download_timeout_ms=195000, min_chars=500, verbose=verbose,
        )
        if md and len(md) >= 500:
            if _is_sources_not_document(md, platform="chatgpt"):
                log(f"[{label}] T1 download wrong-artifact ({len(md)} chars) — falling to Tier 2", "WARN")
                try:
                    emit_event("wrong_artifact_rejected", phase=2, agent="chatgpt",
                               op="finalize_copy", length=len(md), tier="cua_download_md")
                except Exception:
                    pass
            else:
                md = _strip_chatgpt_citation_tokens(md)
                log(f"[{label}] Extracted via T1 CUA download (Export to Markdown): {len(md)} chars")
                return md

    # ── Tier 2: HTML→MD scrape (canvas should be open from T1) ──
    # If T1 succeeded in enlarging the canvas but the download itself
    # failed, the canvas DOM is now mounted — these selectors hit it.
    # If T1 never ran (P1 brief path, browser=None), HTML→MD against
    # the chat-side selectors still works for the brief.
    md = await _extract_html_to_md_anyframe(page, [
        '.canvas-content', '.artifact-content', '[data-testid="canvas-content"]',
        '[role="dialog"] .markdown', '[role="dialog"] .prose',
        '[role="dialog"] article',
        '[role="dialog"] [class*="markdown-content"]',
        'main [class*="canvas"] .markdown',
        'main [class*="canvas"] [class*="prose"]',
        'main [class*="artifact"] [class*="prose"]',
        '[data-testid*="canvas"] [class*="prose"]',
        '[data-testid*="canvas"] [class*="markdown"]',
        'aside[role="dialog"] [class*="prose"]',
        '[data-message-author-role="assistant"]:last-of-type .markdown',
        '[data-message-author-role="assistant"]:last-of-type [class*="prose"]',
        # Iframe-side: DR document body markup. These selectors don't
        # exist on chatgpt.com proper (the parent) so they only match
        # when we descend into the DR sandbox frame.
        'article',
        '.markdown',
        '.prose',
        'main article',
        'main .markdown',
        'main .prose',
    ], label)
    if md and len(md) > 2000:
        if _is_sources_not_document(md, platform="chatgpt"):
            log(f"[{label}] T2 HTML→MD wrong-artifact ({len(md)} chars source-panel-shape) "
                f"— falling to Tier 3", "WARN")
            try:
                emit_event("wrong_artifact_rejected", phase=2, agent="chatgpt",
                           op="finalize_copy", length=len(md), tier="dom_html_md")
            except Exception:
                pass
        elif _looks_like_nav_sidebar(md):
            log(f"[{label}] T2 HTML→MD looks-like-nav-sidebar ({len(md)} chars) — falling to Tier 3", "WARN")
        else:
            md = _strip_chatgpt_citation_tokens(md)
            log(f"[{label}] Extracted via T2 HTML→MD (canvas/artifact): {len(md)} chars")
            return md

    # ── Tier 3 (LAST RESORT, Wayland-safe): CUA + clipboard hijack ──
    # JS clipboard hijack reads window.getSelection().toString() inside
    # the copy event handler, so raw Ctrl+C captures selected text even
    # when no page-side setData fires. Iframe-aware install covers the
    # DR canvas sandbox iframe. Helper timeout_ms = 200000 sits ABOVE
    # the inner asyncio.wait_for(180.0) so the inner CUA cap fires first.
    # When the #839 act tier is armed, the trigger ALSO runs a Vision act leg
    # (act_timeout_s=150) BEFORE the CUA leg inside this same cap, so the cap is
    # padded by _act_pad_ms(150) — else the outer wait_for could cancel the
    # trigger mid-CUA-copy and starve the safety net to 0 chars. Off/shadow: pad
    # 0 → byte-identical 200000ms.
    # Gated on browser+cua (P2 only). P1 never reaches here — it calls with
    # browser=None/cua_client=None, so Tier 3 is off for the brief.
    if browser and cua_client:
        async def _cgpt_t3_trigger():
            await browser.switch_to_page(page)

            async def _cgpt_t3_cua():
                return await asyncio.wait_for(
                    agent_loop(cua_client, browser, PROMPT_COPY_ARTIFACT_CHATGPT,
                        "Open the research report document and copy its full "
                        "content to clipboard.",
                        model=CUA_MODEL, max_iterations=12,
                        verbose=verbose, target_page=page),
                    timeout=180.0)

            # #839 act tier: Vision drives the same copy mission under the SAME
            # clipboard hijack (hooks are already installed around this trigger);
            # its Ctrl+A/Ctrl+C or Copy-button click feeds the identical capture.
            # Success truth stays the hijack text (>=500 chars + wrong-artifact
            # guard below) — the returned text is ignored either way.
            await _shadow_observed_cua(
                page, hotspot_id="2c", phase=2, platform="chatgpt",
                current_step="copy_final_report_t3",
                context_hint="T3 final-report copy — T1 .md download and T2 HTML->MD both missed",
                expected_outcome="the full research report text lands on the clipboard",
                cua_coro_factory=_cgpt_t3_cua,
                mission_prompt=PROMPT_COPY_ARTIFACT_CHATGPT,
                act_timeout_s=150.0)

        log(f"[{label}] CUA: Tier 3 copy with clipboard hijack")
        try:
            md = await _run_with_clipboard_hijack(
                page, label, _cgpt_t3_trigger,
                timeout_ms=200000 + _act_pad_ms(150), min_chars=500)
        except Exception as _e:
            log(f"[{label}] T3 clipboard hijack raised: {_e}", "WARN")
            md = ""
        if md and len(md) >= 500:
            if _is_sources_not_document(md, platform="chatgpt"):
                log(f"[{label}] T3 hijack wrong-artifact ({len(md)} chars) — rejecting", "WARN")
                try:
                    emit_event("wrong_artifact_rejected", phase=2, agent="chatgpt",
                               op="finalize_copy", length=len(md), tier="cua_hijack")
                except Exception:
                    pass
            else:
                md = _strip_chatgpt_citation_tokens(md)
                log(f"[{label}] Extracted via T3 CUA + clipboard hijack: {len(md)} chars")
                return md

    try:
        emit_event("extract_failed", phase=2, agent="chatgpt",
                   op="finalize_copy",
                   reason="all_methods_returned_empty_or_wrong_artifact")
    except Exception:
        pass
    log(f"[{label}] All extraction methods failed (canvas may not have opened)", "WARN")
    return ""


async def extract_gemini_response(page, browser=None, cua_client=None, label="Gemini", verbose=False):
    """Dedicated Gemini extractor — 3 panel-aware tiers:
      Tier 1: HTML→MD from Gemini's strict side-panel containers (DOM-scrape
              from immersive-panel / deep-research-panel — returns the full
              90k-146k-char report with heading hierarchy preserved by the
              semantic HTML, which the clipboard dump sometimes flattens).
      Tier 2: CUA Share & Export → "Copy contents", then read the OS
              clipboard (Gemini's native authoritative export; we read the
              clipboard because the in-page hijack misses Gemini's async-
              Clipboard-API copy — see the T2 fix note below).
      Tier 3: Ctrl+A / Ctrl+C with JS clipboard hijack (panel-focused).
    Each tier emits an explicit log line so the path that succeeded (or
    silently returned empty) is visible in the run log.
    Returns the markdown/text or "" on total failure."""
    await asyncio.sleep(2)
    await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    await asyncio.sleep(1)

    # 2026-05-25 PRE-FLIGHT: verify a Deep Research side-panel exists
    # before any tier runs. Two recent E2Es (Kalki + Golden Retriever)
    # saved 318/101,274 chars of CHAT-side content as gemini.md because
    # the panel selectors didn't match and tiers fell through to chat
    # selectors. Failing fast with status=failed (no MD upload) is
    # better than silently shipping chat as the research output.
    # Best-effort poll up to ~10s to absorb transient render lag.
    _panel_selectors_preflight = [
        'immersive-panel',
        'deep-research-panel',
        'aside[class*="artifact" i]',
        'aside[class*="report" i]',
        'aside[class*="research" i]',
        '[role="complementary"][aria-label*="research" i]',
        '[role="region"][aria-label*="research" i]',
    ]
    _panel_found_sel = ""
    for _attempt in range(5):
        for _sel in _panel_selectors_preflight:
            try:
                _count = await page.evaluate(
                    f"() => document.querySelectorAll('{_sel}').length"
                )
                if _count and int(_count) > 0:
                    _panel_found_sel = _sel
                    break
            except Exception:
                continue
        if _panel_found_sel:
            break
        await asyncio.sleep(2.0)
    if _panel_found_sel:
        log(f"[{label}] DR panel present (selector='{_panel_found_sel}')")
    else:
        log(f"[{label}] DR panel NOT present after 10s — upstream submit/Start "
            f"likely failed; running tiers anyway but expect failure", "WARN")

    # 2026-05-28 ARCHITECTURE (T1↔T2 swap from 2026-05-26 ordering): T1 =
    # HTML→MD side-panel scrape (the report DOM is already authoritative; the
    # markdown rendered from the panel's semantic HTML preserves heading
    # hierarchy + list structure that the clipboard dump occasionally
    # flattens — cross-run comparisons showed the HTML→MD output looked
    # cleaner than the CUA Copy-contents output). T2 = CUA Share & Export →
    # "Copy contents" (Gemini's native authoritative export, kept as the
    # fallback when panel selectors don't match the latest UI revision).
    # T3 = CUA Ctrl+A/C select-all. All three are PANEL-AWARE — the
    # post-2026-05 Gemini UI renders the report in a right-side panel
    # (immersive-panel / deep-research-panel) and Share & Export lives on
    # that panel's toolbar.
    #
    # T2 0-char FIX (2026-05-26, originally a T1 fix pre-swap): the CUA
    # click was always working (backend-2 logs: CUA clicks Share & Export →
    # Copy contents, page shows "copied") but the in-page clipboard hijack
    # captured 0 chars. Root cause: Gemini's "Copy contents" writes the
    # markdown to the REAL OS clipboard via the async Clipboard API against
    # a writeText reference it cached at page-load, so our late writeText
    # monkey-patch never sees it (and no `copy` event fires for the async
    # API, and nothing is visually selected, so the copy-event + getSelection
    # sources are dry too). The fix: after the click, READ the OS clipboard
    # (navigator.clipboard.readText → PowerShell get_clipboard fallback —
    # the same ladder the share-link extractor uses). The hijack capture is
    # still attempted first for the cases where it works.

    # ── Tier 1 (PRIMARY): HTML→MD from Gemini's research-panel containers ──
    # Panel-aware: STRICT side-panel scopes only (no chat-side ack). Reads
    # the report straight from the panel DOM and renders it through the
    # same html_to_md path the brief extractor uses — historically the path
    # that reliably got 90k-146k chars in prior E2Es and (per the user's
    # cross-run review on 2026-05-28) produced cleaner markdown than the
    # CUA Copy-contents export (semantic HTML preserves heading hierarchy +
    # list structure that the clipboard dump occasionally flattens). Falls
    # to T2 only when the panel selectors don't match the current UI.
    #
    # 2026-05-25 selector tighten: prior list included `[class*="immersive" i]
    # message-content` and `[class*="immersive" i] .markdown` — these are
    # TOO GREEDY because Gemini's 2026-05+ app wraps EVERYTHING (chat
    # included) in immersive ancestors. The greedy descendants matched
    # the chat's <message-content>, returning 101,274 chars of chat
    # (Golden Retriever E2E) as gemini.md. Legacy chat-inline fallbacks
    # (`message-content`, `.model-response-text`, `.response-container`)
    # also stripped — they would catch chat-side content when no real
    # panel exists. Now keep only STRICT side-panel scopes: custom
    # elements (`immersive-panel`, `deep-research-panel`), aside scopes
    # with class wildcards, and ARIA role-complementary/role-region
    # with aria-label="research". If none match, return empty (T2 follows).
    md = await _extract_html_to_md(page, [
        # Custom elements — only match the actual panel, not descendants
        'immersive-panel',
        'deep-research-panel',
        # Aside-scoped (aside is structural for side content)
        'aside immersive-panel',
        'aside deep-research-panel',
        'aside[class*="artifact" i] .markdown',
        'aside[class*="artifact" i]',
        'aside[class*="report" i] .markdown',
        'aside[class*="report" i]',
        'aside[class*="research" i] .markdown',
        'aside[class*="research" i]',
        # ARIA role-scoped — explicit research panel intent
        '[role="complementary"][aria-label*="research" i] .markdown',
        '[role="complementary"][aria-label*="research" i]',
        '[role="region"][aria-label*="research" i] .markdown',
        '[role="region"][aria-label*="research" i]',
    ], label)
    # 2026-05-25: strip Gemini's panel chrome + post-report sources/
    # thinking-trace noise BEFORE the threshold check. The 146kb Kalki
    # gemini.md (2026-05-25 E2E) had ~70kb of clean report and ~76kb of
    # citation chips + planning narration after a "Sources used in the
    # report" marker; selectors can't exclude that because it lives
    # inside the same panel DOM. Helper is idempotent.
    if md:
        md = _strip_gemini_panel_noise(md)
    # 2026-05-21: threshold raised 100 → 2000. The new UI's chat side
    # carries a ~200-char ack that would pass both _is_sources_not_
    # document and _looks_like_nav_sidebar — shipping it as the report
    # is the "stuck post-completion / wrong md" symptom. Real Deep
    # Research reports are >5000 chars; 2000 is a safe floor that
    # tolerates partial-render glitches while rejecting the ack shape.
    if md and len(md) > 2000:
        if _is_sources_not_document(md, platform="generic"):
            log(f"[{label}] T1 HTML→MD wrong-artifact — falling to Tier 2", "WARN")
        elif _looks_like_nav_sidebar(md):
            log(f"[{label}] T1 HTML→MD looks-like-nav-sidebar — falling to Tier 2", "WARN")
        else:
            log(f"[{label}] Extracted via T1 HTML→MD: {len(md)} chars")
            return md
    elif md:
        log(f"[{label}] T1 HTML→MD returned {len(md)} chars (below 2000-char threshold — "
            f"likely chat-side ack, not the report panel) — falling to Tier 2", "WARN")

    # ── Tier 2 (FALLBACK): CUA Share & Export → "Copy contents" + clipboard ──
    # The "Copy contents" action lives in the Share & Export dropdown on the
    # report PANEL's toolbar (top-right, same row as Contents / Create / X).
    # CUA opens it and clicks "Copy contents"; the report markdown lands on
    # the OS clipboard. We capture via (a) the in-page hijack, then (b)
    # navigator.clipboard.readText(), then (c) the OS clipboard (get_clipboard).
    # min_chars=2000 rejects a partial copy / chat ack. Kept as fallback for
    # the case where T1's panel selectors don't match the current UI revision.
    if browser and cua_client:
        async def _gemini_t2_trigger():
            await browser.switch_to_page(page)
            # Clear the clipboard first so a stale read (e.g. a prior copy)
            # can't masquerade as this run's "Copy contents". Best-effort —
            # if clipboard-write is denied, the post-copy read still gets the
            # fresh report (we just clicked Copy contents this iteration).
            try:
                await asyncio.wait_for(
                    page.evaluate("() => navigator.clipboard.writeText('')"),
                    timeout=2.0)
            except Exception:
                pass
            await asyncio.wait_for(
                agent_loop(cua_client, browser, PROMPT_GEMINI_COPY_CONTENTS,
                    "Click the Share & Export button in the response toolbar, "
                    "then click Copy contents in the dropdown menu.",
                    model=CUA_MODEL, max_iterations=8,
                    verbose=verbose, target_page=page),
                timeout=90.0)

        log(f"[{label}] T2: CUA Share & Export → Copy contents")
        try:
            md = await _run_with_clipboard_hijack(
                page, label, _gemini_t2_trigger,
                timeout_ms=120000, min_chars=2000,
            )
        except Exception as _e:
            log(f"[{label}] T2 clipboard hijack raised: {_e}", "WARN")
            md = ""
        # The hijack misses Gemini's async-Clipboard-API copy (see the
        # ARCHITECTURE note above) — so read the OS clipboard, where the
        # report markdown actually landed. readText() first (in-browser, 2s
        # cap for the permission-prompt hang), then PowerShell get_clipboard()
        # (3s cap for a locked clipboard). Longest wins.
        if not md or len(md) < 2000:
            _clip = ""
            try:
                _clip = await asyncio.wait_for(
                    page.evaluate("() => navigator.clipboard.readText()"),
                    timeout=2.0,
                ) or ""
            except (asyncio.TimeoutError, Exception):
                _clip = ""
            if not _clip or len(_clip) < 2000:
                try:
                    _os_clip = await asyncio.wait_for(
                        asyncio.to_thread(get_clipboard),
                        timeout=3.0,
                    )
                    if _os_clip and len(_os_clip) > len(_clip):
                        _clip = _os_clip
                except (asyncio.TimeoutError, Exception):
                    pass
            if _clip and len(_clip) >= 2000:
                md = _clip
                log(f"[{label}] T2 recovered {len(md)} chars from OS clipboard "
                    f"after Copy contents")
        if md and len(md) >= 2000:
            log(f"[{label}] Extracted via T2 CUA Share & Export + clipboard: {len(md)} chars")
            return md
        elif md:
            log(f"[{label}] T2 returned {len(md)} chars (below 2000-char threshold — "
                f"likely partial copy or chat ack) — falling to Tier 3", "WARN")

    # ── Tier 3 (LAST RESORT, Wayland-safe): Ctrl+A/C + clipboard hijack ──
    # JS clipboard hijack intercepts the browser's own copy event before
    # the OS clipboard is touched, so this works on Wayland, X11, Windows,
    # and macOS uniformly. No _IS_WAYLAND gate (that was the old OS-
    # clipboard path's limitation). First click the research panel to
    # ensure focus is on it (not the chat or composer); otherwise Ctrl+A
    # would select chat history or only the composer's input text.
    async def _gemini_t3_trigger():
        # Focus the research panel before select-all.
        # 2026-05-25: focus selectors tightened to side-panel ONLY —
        # prior list included `[class*="immersive" i]` (too greedy,
        # matches whole-app immersive wrapper) and chat selectors
        # `message-content`, `.model-response-text` (selecting these
        # makes Ctrl+A grab chat transcript, not the research). Now
        # restricted to explicit panel scopes; if none match, Ctrl+A
        # selects the page focus default (which is often the panel
        # after a completed run, but if not, we'll reject by threshold).
        try:
            await page.click(
                'immersive-panel, deep-research-panel, '
                'aside[class*="artifact" i], '
                'aside[class*="report" i], aside[class*="research" i], '
                '[role="complementary"][aria-label*="research" i], '
                '[role="region"][aria-label*="research" i]',
                timeout=2000)
        except Exception:
            # Best-effort — proceed even if click missed; the response
            # area is typically already focused after a completed turn.
            pass
        await asyncio.sleep(0.3)
        await page.keyboard.press("ControlOrMeta+a")
        await asyncio.sleep(0.5)
        await page.keyboard.press("ControlOrMeta+c")
        await asyncio.sleep(0.5)
        # 2026-05-24: clear the highlight after the copy event fires.
        # Without this, the full-page selection persists visually for
        # the user (observed on Claude where a Publish modal opens
        # shortly after — the highlighted text is visible behind the
        # modal). The hijack JS hook has already captured clipboardData
        # by this point, so removing the selection is safe.
        try:
            await page.evaluate(
                "() => { try { window.getSelection()?.removeAllRanges(); } catch (_) {} }"
            )
        except Exception:
            pass

    # 2026-05-25 min_chars raised 100 → 2000 to match T1/T2 floor.
    # Prior Kalki E2E captured 318 chars of chat fragments and saved
    # it; with the 2000 floor that path now rejects, agent flips to
    # status=failed (which is the correct outcome over "ship chat
    # as research").
    log(f"[{label}] Falling back to select-all + clipboard hijack (Tier 3)", "WARN")
    md = await _run_with_clipboard_hijack(
        page, label, _gemini_t3_trigger,
        timeout_ms=30000, min_chars=2000,
    )
    # 2026-05-25: same noise strip as T2 — select-all can grab the
    # panel chrome + sources tail too.
    if md:
        md = _strip_gemini_panel_noise(md)
    if md and len(md) >= 2000:
        # Apply same wrong-artifact filters as T2 — T3 has historically
        # been too permissive (raw select-all can grab anything).
        if _is_sources_not_document(md, platform="generic"):
            log(f"[{label}] T3 hijack wrong-artifact ({len(md)} chars) — rejecting", "WARN")
        elif _looks_like_nav_sidebar(md):
            log(f"[{label}] T3 hijack looks-like-nav-sidebar ({len(md)} chars) — rejecting", "WARN")
        else:
            log(f"[{label}] Extracted via select-all + clipboard hijack: {len(md)} chars")
            return md
    elif md:
        log(f"[{label}] T3 returned {len(md)} chars (below 2000-char threshold — "
            f"likely chat fragment, not research panel) — rejecting", "WARN")

    log(f"[{label}] All extraction tiers failed — returning empty", "ERROR")
    return ""


async def extract_claude_response(page, browser=None, cua_client=None, label="Claude", verbose=False,
                                   artifact_panel_open=False):
    """Extract Claude response — artifact-aware extraction.
    Claude Deep Research produces 2 artifacts: first = intermediate tracking
    (kept open during polling for live source streaming), second = final report.
    Targets the LAST artifact for extraction, with multiple fallback methods.

    artifact_panel_open: poll-loop signal that artifact 1's panel is currently
    open (commit d45807f keeps it open across polls via keep_open=True). When
    True we explicitly CLOSE artifact-1 first so the subsequent LAST-card click
    definitely opens a fresh panel onto artifact-2 (final report) — without
    this, relying on a panel-swap can race or no-op (artifact_count==1 case)
    and silently extract artifact-1's references instead of the final report.

    E2 / DGOPS-7364 — when the run is in user-acknowledged chat mode (Research
    setup couldn't be enabled and the operator chose Continue in chat mode),
    Claude returns a regular chat reply with NO research artifact. Skip the
    artifact-aware logic entirely and use the mode-agnostic DOM/JS extraction
    tail. _is_sources_not_document rejection also bypassed in chat mode (it
    expects the artifact shape that doesn't exist here)."""
    # E2 / DGOPS-7364 — read sticky chat-mode flag set by start_agent_no_gemini_wait.
    chat_mode = (getattr(_runtime, "agent_modes", {}) or {}).get("claude", {}).get("actual") == "chat"
    if chat_mode:
        log(f"[{label}] Running in CHAT MODE (user-acknowledged Research-unavailable) "
            f"— bypassing artifact-aware extraction, using DOM/JS tail only")
    # Clear clipboard first so stale brief text doesn't get returned
    clear_clipboard()
    await asyncio.sleep(2)
    await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
    await asyncio.sleep(1)

    # ── Step 0 (BROADENED 2026-04-26 v3): probe DOM directly, not just flag ──
    # Polling sets artifact_panel_open=True, but if extract is reached via a
    # different path (Phase-2 timeout, hard-retry recovery, manual continue) the
    # flag may be stale or False while the panel IS still visually open. Directly
    # probe the DOM for any visible side artifact panel (>200px wide). Close it
    # if present — without this, the LAST-card click silently opens the wrong
    # artifact (the still-foregrounded artifact-1 / sources checklist).
    panel_visible_dom = False
    try:
        panel_visible_dom = await page.evaluate("""() => {
            const sels = [
                'aside',
                '[class*="artifact-panel" i]',
                '[class*="side-panel" i]',
                '[role="complementary"]'
            ];
            for (const s of sels) {
                for (const el of document.querySelectorAll(s)) {
                    const r = el.getBoundingClientRect();
                    if (r.width > 200 && r.height > 200) return true;
                }
            }
            return false;
        }""")
    except Exception:
        pass
    if panel_visible_dom or artifact_panel_open:
        log(f"[{label}] Closing artifact panel (visible_dom={panel_visible_dom}, "
            f"flag={artifact_panel_open}) before final extract")
        try:
            # Blur composer first so Escape isn't swallowed by textarea focus.
            try:
                await page.evaluate(
                    "document.activeElement && document.activeElement.blur && document.activeElement.blur()")
            except Exception:
                pass
            await _close_claude_artifact_panel(page)
            await asyncio.sleep(0.6)
        except Exception as _ce:
            log(f"[{label}] artifact-1 close before extract failed (continuing): {_ce}", "DEBUG")

    # ── Step 1: Count artifacts so we know which index = final report ──
    # 2026-04-26: scroll-to-bottom warmup forces lazy-load of latest turn —
    # without this, an early-rendered DOM may report artifact_count=1 when
    # artifact-2 (final report) is in the not-yet-mounted bottom portion →
    # target_idx=0 clicks artifact-1 (tracking checklist).
    try:
        for _ in range(2):
            await page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
            await asyncio.sleep(0.5)
    except Exception:
        pass
    # E2 / DGOPS-7364 — chat mode early return.
    # Claude in chat mode emits a regular assistant reply, NO artifact.
    # The artifact-aware Tiers 1-3 below (Research-mode path, line ~16877
    # onward — CUA download / publish + claude.site / CUA + clipboard
    # hijack) all target aside / artifact-panel / [class*="artifact"]
    # selectors that don't exist in chat mode, so they'd all return empty
    # and the function would falsely report "All extraction methods
    # failed". Instead, read the last assistant message via a tight
    # selector list scoped to chat-turn content.
    if chat_mode:
        # 2026-05-13 TIER SWAP (chat-mode branch): HTML→MD promoted to
        # Tier 1; Copy hijack demoted to Tier 2. Hijack-first never
        # succeeded in any prior log; HTML→MD is the proven path.
        #
        # Tier 1 (NEW PRIMARY): HTML→MD scoped to chat-turn content.
        try:
            md_chat = await _extract_html_to_md(page, [
                '[data-message-author-role="assistant"]:last-of-type .markdown',
                '[data-test-render-count] .font-claude-message:last-of-type',
                '.font-claude-message:last-of-type',
                'div[data-streamed]:last-of-type .markdown',
                'div[data-is-streaming="false"]:last-of-type .markdown',
            ], label)
            if md_chat and len(md_chat) > 100:
                if _looks_like_nav_sidebar(md_chat):
                    log(f"[{label}] chat-mode HTML→MD looks-like-nav-sidebar — falling to Tier 2", "WARN")
                else:
                    log(f"[{label}] Extracted via chat-mode HTML→MD: {len(md_chat)} chars")
                    return md_chat
        except Exception as _e:
            log(f"[{label}] chat-mode HTML→MD failed: {_e}", "WARN")

        # Tier 2 (FALLBACK): Copy hijack on the last assistant message Copy button.
        md_chat = await _copy_via_hijack(
            page, label,
            direct_copy_selectors=[
                '[data-message-author-role="assistant"]:last-of-type button[aria-label*="copy" i]:not([aria-label*="code" i]):not([aria-label*="link" i])',
                '.font-claude-message:last-of-type button[aria-label*="copy" i]',
                '[data-test-render-count]:last-of-type button[aria-label*="copy" i]',
            ],
            min_chars=100,
        )
        if md_chat and len(md_chat) >= 100:
            log(f"[{label}] Extracted via Copy hijack (chat-mode): {len(md_chat)} chars")
            return md_chat
        log(f"[{label}] Chat-mode extraction returned no readable content", "WARN")
        return ""
    # Research-mode path below (unchanged from pre-E2 — the artifact-aware ladder).
    artifact_count = await _count_claude_artifacts(page)
    log(f"[{label}] Post-completion: found {artifact_count} artifact(s)")

    # ── Step 2 — EXPLICITLY open the LAST artifact card (= final report) ──
    # The "LAST" artifact is the final research report. For 2-artifact runs this
    # is artifact-2 (after Step 0's close-1, panel is now closed → click opens
    # fresh onto artifact-2). For 1-artifact runs this is just the one artifact.
    if artifact_count > 0:
        target_idx = max(0, artifact_count - 1)  # Last artifact = final report
        log(f"[{label}] Post-completion: opening artifact[{target_idx}] (final report)")
        clicked = await _click_claude_artifact(page, index=target_idx)
        # 2026-05-14: when the DOM pre-click can't resolve a real artifact
        # button (Claude's `[data-testid*="artifact"]` selector can match
        # research-tracking cards, context-menu triggers, etc.), fall back
        # to CUA to open the LAST artifact card before running the tiers.
        # Without this fallback the entire tier ladder used to skip
        # silently — see 2026-05-13 run where T1/T2/T3 all returned in the
        # same second as the count log because every tier was nested
        # inside `if clicked:`. T1 and T2 require the artifact panel open
        # (Copy/down-arrow trio for T1, Publish button for T2); T3 has its
        # own navigate preamble so it can recover even when this CUA
        # fallback also misses.
        if not clicked and browser and cua_client and not chat_mode:
            log(f"[{label}] DOM pre-click missed — CUA fallback to open last artifact", "WARN")
            try:
                async def _nav_a_cua():
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser,
                            PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                            f"There are {artifact_count} artifact(s) in this "
                            f"conversation. Open the LAST (bottom) artifact card "
                            f"— that's the final research report.",
                            model=CUA_MODEL, max_iterations=8,
                            verbose=verbose, target_page=page),
                        timeout=120.0)

                await _shadow_observed_cua(
                    page, hotspot_id="2d-nav", phase=2, platform="claude",
                    current_step="open_final_artifact_preclick_missed",
                    context_hint=f"DOM pre-click missed; {artifact_count} artifact(s) present — "
                                 "open the LAST (bottom) card, never the first/tracking one",
                    expected_outcome="the final report artifact panel opens on the right",
                    cua_coro_factory=_nav_a_cua,
                    mission_prompt=PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                    act_timeout_s=90.0)
                clicked = True
                await asyncio.sleep(1.5)
            except asyncio.TimeoutError:
                log(f"[{label}] CUA fallback open timed out after 120s", "WARN")
            except Exception as _fe:
                log(f"[{label}] CUA fallback open raised: {_fe}", "WARN")

        # A1 (2026-05-01): content-driven wait — yields fast on a
        # normal mount, gives slow renders up to 8s before falling
        # through to CUA. Forgiving — if panel never mounts, T3's own
        # navigate preamble still has a shot.
        _panel_open = True
        try:
            await page.wait_for_selector(
                'aside [class*="markdown"], aside .prose, '
                '[class*="artifact-panel"] [class*="markdown"], '
                '[class*="artifact-panel"] .prose',
                timeout=8000)
        except Exception:
            _panel_open = False
            await asyncio.sleep(1.5)

        # #777 ROOT FIX: the DOM pre-click (_click_claude_artifact) sometimes
        # reports success but matched a WRONG element (research-tracking card /
        # context-menu trigger — see the comment at ~23130) so the final-report
        # panel never actually opened. The CUA open above only ran on `not
        # clicked`, so a FALSE-success pre-click SKIPPED it → Tier 1's Download
        # menu, Tier 2's Publish button, and Tier 3's Ctrl+A all run against a
        # closed/empty panel and ALL return empty (the 2026-06-03 false "Hit a
        # snag": T1 "no download event within 165s", T2 "Publish never mounted",
        # T3 "captured 0 chars lens=[0,0]" — while a user hard-retry opened the
        # panel cleanly and T1 pulled 45k chars). If the panel content never
        # mounted, open it via the CUA NOW — regardless of `clicked` — so the
        # tiers (esp. the reliable T1 .md download) run against an open report.
        if not _panel_open and browser and cua_client and not chat_mode:
            log(f"[{label}] Artifact panel content not mounted after click — CUA "
                f"fallback to open the final report before running extraction tiers", "WARN")
            try:
                async def _nav_b_cua():
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser,
                            PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                            f"There are {artifact_count} artifact(s) in this conversation. "
                            f"Open the LAST (bottom) artifact card — that's the final "
                            f"research report — so its panel is visible on the right.",
                            model=CUA_MODEL, max_iterations=8,
                            verbose=verbose, target_page=page),
                        timeout=120.0)

                await _shadow_observed_cua(
                    page, hotspot_id="2d-nav", phase=2, platform="claude",
                    current_step="open_final_artifact_panel_not_mounted",
                    context_hint=f"panel content never mounted (a pre-click may have false-succeeded); "
                                 f"{artifact_count} artifact(s) — open the LAST (bottom) card so its "
                                 "panel is visible on the right",
                    expected_outcome="the final report artifact panel is visibly mounted on the right",
                    cua_coro_factory=_nav_b_cua,
                    mission_prompt=PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                    act_timeout_s=90.0)
                await asyncio.sleep(1.5)
                # Re-confirm the panel content mounted (best-effort; tiers still try regardless).
                try:
                    await page.wait_for_selector(
                        'aside [class*="markdown"], aside .prose, '
                        '[class*="artifact-panel"] [class*="markdown"], '
                        '[class*="artifact-panel"] .prose',
                        timeout=8000)
                    log(f"[{label}] CUA panel-open recovery: final-report panel now mounted ✓")
                except Exception:
                    # ⛔⛔ 2026-08-20 — THIS WARNED FOUR SECONDS BEFORE WE READ THE
                    # REPORT OUT OF THAT PANEL. Live 08-19: this line at 19:41:12,
                    # the vision tier reporting "I can see the artifact panel is
                    # open on the right showing the research report" at 19:41:16,
                    # and 39,831 characters extracted from it at 19:41:20. The
                    # panel was open; our probe could not see it — the same
                    # two-verifiers-two-definitions split that left the P1 row
                    # unpressed, and the one that was wrong is the one that wrote
                    # to the log. The owner read my report of this as a defect and
                    # was right to push back.
                    # ⭐ NOT silenced and the probe is NOT touched: a
                    # probe-vs-reality disagreement is worth a record. DEBUG,
                    # because what usually happens next is a successful
                    # extraction, and the wording no longer asserts a shut panel.
                    log(f"[{label}] the probe still cannot confirm the artifact "
                        f"panel after CUA recovery — extraction tiers run anyway "
                        f"and normally succeed; a probe gap, not a closed panel",
                        "DEBUG")
            except asyncio.TimeoutError:
                log(f"[{label}] CUA panel-open recovery timed out after 120s", "WARN")
            except Exception as _pe:
                log(f"[{label}] CUA panel-open recovery raised: {_pe}", "WARN")

        # 2026-05-13 ARCHITECTURE: collapsed from 4-tier ladder (panel-
        # reader + publish + html-md + copy-hijack + CUA-OS-clipboard)
        # into exactly 3 Wayland-safe tiers per user sign-off. Removes
        # the _IS_WAYLAND gate (Tier 3 now uses a JS clipboard hijack
        # that works on every backend) and removes the OS-clipboard
        # `get_clipboard()` read entirely.
        # 2026-05-14: tiers de-indented out of the prior `if clicked:`
        # gate so a missed pre-click doesn't silently skip everything.

        # ── Tier 1 (CUA-driven download): Download as Markdown ──
        # CUA finds the small down-arrow button next to the Copy button
        # in the artifact-panel header (Copy/▼/Published trio per user
        # screenshot), clicks it, then clicks "Download as Markdown".
        # Playwright expect_download() captures the .md file. Selector-
        # free; CUA's vision handles DOM drift. Wayland-safe.
        if browser and cua_client:
            md_dl = await _extract_via_cua_download(
                page, browser, cua_client, label,
                PROMPT_CLAUDE_DOWNLOAD_MD,
                "The artifact panel should be open on the right showing the "
                "final research report. If it isn't open yet, click the LAST "
                "artifact card in the chat to open it first. Then click the "
                "small down-arrow button next to the Copy button, and click "
                "Download as Markdown.",
                max_iterations=12, cua_timeout_s=150.0,
                # See ChatGPT T1 note above: download_timeout_ms must
                # exceed cua_timeout_s so the listener stays alive past
                # the final click. cua_timeout_s + 15s grace.
                download_timeout_ms=165000, min_chars=500, verbose=verbose,
            )
            if md_dl and len(md_dl) >= 500:
                if _is_sources_not_document(md_dl, platform="claude"):
                    log(f"[{label}] T1 CUA download wrong-artifact "
                        f"({len(md_dl)} chars) — falling to Tier 2", "WARN")
                    try:
                        emit_event("wrong_artifact_rejected", phase=2, agent="claude",
                                   op="finalize_copy", length=len(md_dl),
                                   tier="cua_download_md")
                    except Exception:
                        pass
                else:
                    log(f"[{label}] Extracted via T1 CUA download (.md): {len(md_dl)} chars")
                    return md_dl

        # ── Tier 2: HTML→MD of the OPEN artifact panel ──
        # #777 (2026-06-03, user-directed): Claude's T2 used to PUBLISH the
        # artifact to claude.site and HTML→MD-scrape that page — the ONLY
        # extractor that published mid-extraction (ChatGPT T2 and Gemini T1 both
        # DOM-scrape the open panel directly). Publishing is heavier + flakier
        # ("Publish/Share button never mounted within 12s" in the 2026-06-03
        # false-snag run) and the artifact is ALSO published independently by the
        # end-of-pipeline share-link step (removed 2026-08-28), so the
        # mid-extraction publish was redundant. T2 is now a plain HTML→MD of the
        # OPEN artifact panel — the same panel the panel-open recovery above
        # guarantees is mounted — scoped to the artifact/complementary side-panel
        # containers (NOT chat). Cheap, deterministic, Wayland-safe. Publishing
        # stays ONLY in the share-link step. The ladder is now consistent across
        # all three agents: CUA-download → HTML→MD-of-panel → clipboard-hijack.
        md_dom = await _extract_html_to_md(page, [
            'aside [class*="markdown"]',
            'aside .prose',
            'aside [class*="prose"]',
            '[class*="artifact-panel"] [class*="markdown"]',
            '[class*="artifact-panel"] .prose',
            '[class*="artifact-panel"] [class*="prose"]',
            '[role="complementary"] [class*="markdown"]',
            '[role="complementary"] .prose',
        ], label)
        # Floor = 2000 to match Gemini's sibling DOM-scrape tier (research.py
        # ~22824): a DOM panel scrape can catch a sparse PARTIAL render that is
        # NEITHER a checklist nor a nav-sidebar (so both reject guards miss it).
        # Genuine Claude DR reports are >5000 chars, so a 2000 floor rejects a
        # truncated panel while accepting every real report; a short-but-real doc
        # (rare) still gets a shot at T3's CUA copy below. T1 (.md download) and
        # T3 (clipboard hijack) keep their 500 floor — a downloaded file / clean
        # CUA copy is authoritative even when short; a raw DOM scrape is not.
        if md_dom and len(md_dom) > 2000:
            if _is_sources_not_document(md_dom, platform="claude"):
                log(f"[{label}] T2 HTML→MD wrong-artifact "
                    f"({len(md_dom)} chars) — falling to Tier 3", "WARN")
            elif _looks_like_nav_sidebar(md_dom):
                log(f"[{label}] T2 HTML→MD looks-like-nav-sidebar "
                    f"({len(md_dom)} chars) — falling to Tier 3", "WARN")
            else:
                log(f"[{label}] Extracted via T2 HTML→MD (artifact panel): {len(md_dom)} chars")
                return md_dom
        elif md_dom:
            log(f"[{label}] T2 HTML→MD returned {len(md_dom)} chars (below 2000-char "
                f"floor — likely a partial render or wrong panel) — falling to Tier 3", "WARN")

        # ── Tier 3 (LAST RESORT, Wayland-safe): CUA + clipboard hijack ──
        # _run_with_clipboard_hijack installs the JS hook before CUA's
        # Ctrl+A/C so the page's own copy event is intercepted in-DOM.
        # No OS clipboard read → Wayland-safe. Trigger chains the
        # existing two CUA prompts: navigate to LAST artifact (if
        # multiple), then Ctrl+A/C inside the open panel. No retry
        # loop, no _IS_WAYLAND gate — helper owns retry policy. Helper
        # timeout_ms sits ABOVE the inner CUA wait_for budgets so the inner
        # caps fire first. When the #839 act tier is armed, the trigger ALSO
        # runs a Vision act leg BEFORE each CUA leg (nav act 120 + copy act
        # 150) inside this same cap, so it is padded by _act_pad_ms(120, 150)
        # — else the outer wait_for could cancel the trigger before/during the
        # copy CUA and starve the safety net to 0 chars. Off/shadow: pad 0.
        if browser and cua_client and not chat_mode:
            async def _claude_t3_trigger():
                await browser.switch_to_page(page)
                if artifact_count >= 2:
                    try:
                        async def _nav_c_cua():
                            return await asyncio.wait_for(
                                agent_loop(cua_client, browser,
                                    PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                                    f"There are {artifact_count} artifacts in this "
                                    f"conversation. Open the LAST (bottom) artifact — "
                                    f"that's the final research report.",
                                    model=CUA_MODEL, max_iterations=8,
                                    verbose=verbose, target_page=page),
                                timeout=180.0)

                        await _shadow_observed_cua(
                            page, hotspot_id="2d-nav", phase=2, platform="claude",
                            current_step="open_final_artifact_pre_t3_copy",
                            context_hint=f"pre-copy navigate inside the T3 hijack trigger; "
                                         f"{artifact_count} artifacts — open the LAST (bottom) one",
                            expected_outcome="the final report artifact panel opens on the right",
                            cua_coro_factory=_nav_c_cua,
                            mission_prompt=PROMPT_NAVIGATE_CLAUDE_FINAL_ARTIFACT,
                            act_timeout_s=120.0)
                        await asyncio.sleep(1)
                    except asyncio.TimeoutError:
                        log(f"[{label}] T3 CUA nav timed out after 180s", "WARN")
                    except Exception as _ne:
                        log(f"[{label}] T3 CUA nav raised: {_ne}", "WARN")

                async def _claude_t3_copy_cua():
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser, PROMPT_COPY_ARTIFACT_CLAUDE,
                            "Copy the full content of the artifact currently open "
                            "in the right panel to clipboard.",
                            model=CUA_MODEL, max_iterations=12,
                            verbose=verbose, target_page=page),
                        timeout=180.0)

                # #839 act tier: same copy mission under the SAME clipboard hijack
                # (hooks already installed around this trigger). The hijack capture
                # (>=500 chars + wrong-artifact guard) stays the only success truth.
                await _shadow_observed_cua(
                    page, hotspot_id="2d-copy", phase=2, platform="claude",
                    current_step="copy_final_artifact_t3",
                    context_hint="T3 final-artifact copy — select all inside the OPEN right "
                                 "panel and copy; never the chat column",
                    expected_outcome="the full artifact text lands on the clipboard",
                    cua_coro_factory=_claude_t3_copy_cua,
                    mission_prompt=PROMPT_COPY_ARTIFACT_CLAUDE,
                    act_timeout_s=150.0)
                await asyncio.sleep(1)
                # 2026-05-24: clear the selection the CUA's Ctrl+A
                # left behind. Without this, the artifact text stays
                # visibly highlighted while the subsequent
                # the removed publish flow used to open the Publish
                # modal — the user sees the blue highlight bleeding
                # behind the modal. Hijack JS hook has already
                # captured clipboardData (sleep 1 above), so removing
                # the selection is safe.
                try:
                    await page.evaluate(
                        "() => { try { window.getSelection()?.removeAllRanges(); } catch (_) {} }"
                    )
                except Exception:
                    pass

            log(f"[{label}] CUA: Tier 3 navigate + copy with clipboard hijack")
            try:
                md_hj = await _run_with_clipboard_hijack(
                    page, label, _claude_t3_trigger,
                    timeout_ms=400000 + _act_pad_ms(120, 150), min_chars=500,
                )
            except Exception as _te:
                log(f"[{label}] T3 clipboard-hijack raised: {_te}", "WARN")
                md_hj = ""
            if md_hj and len(md_hj) >= 500:
                if _is_sources_not_document(md_hj, platform="claude"):
                    log(f"[{label}] T3 hijack wrong-artifact "
                        f"({len(md_hj)} chars) — rejecting", "WARN")
                    try:
                        emit_event("wrong_artifact_rejected", phase=2, agent="claude",
                                   op="finalize_copy", length=len(md_hj),
                                   tier="clipboard_hijack")
                    except Exception:
                        pass
                else:
                    log(f"[{label}] Extracted via T3 clipboard hijack: {len(md_hj)} chars")
                    return md_hj

    try:
        emit_event("extract_failed", phase=2, agent="claude",
                   op="finalize_copy",
                   reason="all_methods_returned_empty_or_wrong_artifact")
    except Exception:
        pass
    log(f"[{label}] All extraction methods failed", "WARN")
    return ""


# ── Phase 1: Research Brief Generation ───────────────────────────────────────

async def run_phase1(browser, cua_client, topic, pdf_paths, verbose=False, feedback="", _retry_count=0):
    """Phase 1: ChatGPT Pro + Extended Thinking → research brief.

    _retry_count: internal counter bounded to P1_MAX_USER_RETRIES. Incremented
    when the brief-short branch restarts Phase 1 at the user's request. Caps
    total attempts to avoid infinite loops."""
    log("=" * 60)
    log("PHASE 1: Research Brief Generation (ChatGPT Pro + Extended Thinking)")
    log("=" * 60)

    # Navigate to ChatGPT
    emit_event("agent_progress", phase=1, agent="chatgpt",
               status="starting",
               progress="Opening ChatGPT…")
    await browser.navigate("https://chatgpt.com")
    await asyncio.sleep(3)

    # #899 work-tab preflight: confirmed signed-out probe on the tab P1 is
    # about to drive (the isolated verify tab is being retired; the gate's
    # cookie fast path can't catch a session that died SERVER-side). Runs regardless
    # of verifyLogins — cheap insurance for sessions dying after a P0 walk.
    # P1 has a single agent, so unlike P2 this PAUSES (nothing else could
    # keep running anyway); signing in inside the open tab auto-resumes.
    if await _work_tab_signed_out(browser.page, "chatgpt", "ChatGPT"):
        _p1_preflight = await _work_tab_login_pause(
            browser.page, "chatgpt", 1, "ChatGPT",
            work_url="https://chatgpt.com")
        if _p1_preflight == "stop":
            return None
        if _p1_preflight == "skipped":
            # chatgpt stays in skipped_agents — the caller keys the
            # manual-brief flow off exactly that membership.
            log("Phase 1: ChatGPT skipped at the work-tab login pause — caller collects a manual brief", "INFO")
            return None
        # 'ok' → signed in, confirmed on the work page; proceed.

    # Inject MutationObserver early — right after navigate, before HV check.
    # The scrape selector (`[data-message-author-role="assistant"]`) doesn't
    # exist on HV/login pages, so early-inject produces no false positives
    # and captures any brief streaming that starts before `verify-generating`
    # closes. `inject_agent_observer` is idempotent on re-call.
    try:
        await inject_agent_observer(browser.page, "chatgpt")
    except Exception:
        pass

    # Early HV check — if Cloudflare Turnstile / CAPTCHA is gating ChatGPT,
    # resolve it BEFORE running Pro-model selection. Those CUA calls can't
    # succeed on a blocked page and will burn workspace quota for nothing.
    # On clear-failure, return None so the pipeline runner emits
    # pipeline_error + pipeline_stopped via fail_phase(...) downstream.
    if cua_client:
        emit_event("agent_progress", phase=1, agent="chatgpt",
                   status="verifying",
                   progress="Checking for CAPTCHA / human-verification gate…")
        cleared = await check_hv_gate(browser, cua_client, "chatgpt", "ChatGPT",
                                       phase=1, verbose=verbose)
        if not cleared:
            log("Phase 1: HV gate could not be cleared — aborting phase", "ERROR")
            return None

    # ── RUNG 1: the DOM tier. ──
    # ⭐ (2026-08-03) The tier selection had NO DOM rung at all: it was a Vision/
    # CUA mission or nothing, and the whole block was gated behind `if cua_client`
    # — so on a host with no CUA key configured the P1 brief ran on whatever tier
    # the account happened to be left on, silently. The picker below reads the
    # trigger first and opens nothing when the pill is already on target, so the
    # common case costs one page.evaluate.
    #
    # A POSITIVE, MECHANICALLY VERIFIED result is the only thing allowed to skip
    # the rungs below it. `no_target` (nothing on the menu names the tier) does
    # NOT short-circuit: that verdict belongs to the CUA path, which owns the
    # no-subscription escalation, and a DOM miss must never be able to fabricate
    # one. Every other verdict falls through to exactly today's behaviour.
    _p1_tier = "unsure"
    emit_event("agent_progress", phase=1, agent="chatgpt",
               status="selecting_model",
               progress="Selecting ChatGPT's highest reasoning tier…")
    try:
        _p1_tier = await _chatgpt_select_effort_tier(browser.page, label="ChatGPT", phase=1)
    except Exception as _tse:
        log(f"Phase 1: DOM tier picker errored ({_tse}) — falling through to Vision/CUA", "INFO")
    _p1_tier_ok = _p1_tier in ("already", "selected")
    # ⚠ Bound OUTSIDE the block below. It used to be defined inside it and read
    # afterwards as `if cua_client and _pro_select_claimed` — safe only while the
    # two conditions were the same one. Now that the DOM rung can skip the block
    # with `cua_client` still set, an unbound name would raise there.
    _pro_select_claimed = False  # #759: only DOM-confirm when the CUA path claimed Pro
    if _p1_tier_ok:
        log(f"Phase 1: model tier settled by the DOM rung ({_p1_tier}) — "
            f"not running the Vision/CUA selector for it")

    # Select Pro model via CUA. Hard 180s ceiling — max_iterations=15 is
    # generous enough that a stuck CUA could loiter for many minutes
    # without this wait_for. If timed out, log + assume Pro is unavailable
    # so the rest of Phase 1 falls through gracefully (the pipeline still
    # gets an Extended Thinking attempt without the Pro model upgrade).
    if cua_client and not _p1_tier_ok:
        # DGOPS-7363 retry-aware Pro selection. Wrapped in a while-True so the
        # backstop alert's Retry button can re-run PROMPT_SELECT_PRO inline
        # after the user signs in with a Pro account. Exits the loop on:
        #  • Pro selected (no "no pro" in output) → break to PDFs
        #  • Stop pressed during the alert → return None
        #  • Continue with Free / generic resume → ack flag set, break
        #  • pro_warning_acknowledged already set on entry → break
        # #705 item 5: silent Tier-1 retries before any pro_required card —
        # a "no pro" verdict is usually a transient detection miss (cua_timeout
        # / picker not yet rendered), not a real downgrade. Counter persists
        # across loop iterations so a user-driven Retry re-escalates instead of
        # silently swallowing a genuine no-Pro.
        _pro_silent_retries = 0
        _PRO_SILENT_RETRY_MAX = 2
        while True:
            log("Selecting ChatGPT's highest reasoning tier via Vision/CUA...")
            emit_event("agent_progress", phase=1, agent="chatgpt",
                       status="selecting_model",
                       progress="Selecting ChatGPT's highest reasoning tier…")
            try:
                async def _select_pro_cua():
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser, PROMPT_SELECT_PRO,
                            _p1_tier_mission(),   # policy-rendered; no phantom thinking toggle
                            model=CUA_MODEL, max_iterations=15, verbose=verbose),
                        timeout=180.0,
                    )

                # #839 act tier: Vision drives the model picker with the SAME
                # PROMPT_SELECT_PRO (which carries the #744 never-re-click-correct
                # + #745 set-Thinking-before-Max invariants). No success_text —
                # the caller's contract is the ABSENCE of "no pro"/"not available",
                # so a Vision success (reason lacks those) reads as claimed, while
                # a can't-find escalates to CUA which owns the authoritative
                # no-Pro verdict. Highest-risk act hotspot; default-off + CUA net.
                result = await _shadow_observed_cua(
                    browser.page, hotspot_id="1a-select-pro", phase=1, platform="chatgpt",
                    current_step="select_effort_tier",
                    # ⚠ Rendered, not written out. _shadow_observed_cua APPENDS this
                    # as "run detail" to the hotspot hint, so a phantom-toggle
                    # instruction here reaches the Vision actor no matter how clean
                    # the hint above it is — the fourth copy of the same sentence.
                    context_hint=_p1_tier_mission() + " Use the model picker.",
                    expected_outcome=_p1_select_pro_hotspot()["expected_outcome"],
                    cua_coro_factory=_select_pro_cua,
                    mission_prompt=PROMPT_SELECT_PRO,
                    act_timeout_s=150.0) or {"text": ""}
            except asyncio.TimeoutError:
                log("Phase 1: Pro+Extended Thinking selection timed out (180s) — proceeding without explicit Pro upgrade", "WARN")
                result = {"text": "no pro available (cua_timeout)"}
            last = (result.get("text") or "").lower()
            if not ("no pro" in last or "not available" in last):
                _pro_select_claimed = True  # #759: CUA claims Pro selected
                break  # Pro selected — exit the retry loop
            # Backstop: Phase 0 normally catches Pro-Free downgrade and pauses
            # for the alert. This branch fires only when:
            #  • skipInitVerify=true (Phase 0 was bypassed entirely), OR
            #  • Pro was revoked between Phase 0 verify and Phase 1 active
            #    (rare — usually means the subscription expired mid-day).
            if _controls.pro_warning_acknowledged:
                log("Phase 1: Pro unavailable — user opted into Free at Phase 0 (continuing)", "INFO")
                break
            # #705 item 5: Tier-1 silent retry. A "no pro" verdict is most often
            # a TRANSIENT detection miss — the CUA selection timed out
            # ("no pro available (cua_timeout)") or the model-picker menu hadn't
            # finished rendering when CUA looked. Re-run PROMPT_SELECT_PRO a
            # bounded number of times silently (no card, no pause) to recover
            # those. A GENUINE no-Pro subscription returns "no pro" on every
            # attempt, so we still escalate once the retries exhaust — the only
            # cost on a real downgrade is a few extra seconds.
            if _pro_silent_retries < _PRO_SILENT_RETRY_MAX:
                _pro_silent_retries += 1
                log(f"Phase 1: Pro selector returned no-Pro (verdict: {last[:80]!r}) — "
                    f"silent retry {_pro_silent_retries}/{_PRO_SILENT_RETRY_MAX} before escalating", "INFO")
                await asyncio.sleep(2)
                continue
            # Silent retries exhausted. #893: with verification off by default
            # a STALE trusted cookie serves ChatGPT's ANONYMOUS landing (which
            # has a composer) — a signed-out session reads as "no Pro". Probe
            # the already-open page (zero navigations) and surface the honest
            # login_required card instead of misattributing it to the tier.
            # #899: routed through the work-tab login pause helper — same
            # card, plus the auto-resume poll and a working Skip branch (the
            # old inline pause had no Skip: skip_agent left it spinning).
            _p1_wall = await _work_tab_signed_out(browser.page, "chatgpt", "ChatGPT")
            if _p1_wall:
                log(f"Phase 1: ChatGPT shows {_p1_wall} — the no-Pro verdict is a signed-out session; surfacing login_required", "WARN")
                _p1_wall_pause = await _work_tab_login_pause(
                    browser.page, "chatgpt", 1, "ChatGPT",
                    work_url="https://chatgpt.com")
                if _p1_wall_pause == "stop":
                    return None
                if _p1_wall_pause == "skipped":
                    log("Phase 1: ChatGPT skipped at the mid-P1 login pause — caller collects a manual brief", "INFO")
                    return None
                continue  # 'ok' — re-run the Pro selector on the now-signed-in page
            # A genuine downgrade (or a persistent detection failure). Log the
            # exact CUA verdict so a post-E2E review can confirm it wasn't a
            # transient miss, then escalate to the Tier-2 pro_required card.
            log(f"Phase 1: Pro mode not available (cua verdict: {last[:120]!r}) — Phase 0 was skipped or Pro was revoked; surfacing alert", "WARN")
            _emit_pro_required_alert(phase=1, agent="chatgpt", source="phase1/setup_pro_backstop")
            _controls.request_pause("pro_required")
            emit_event("pipeline_paused", phase=1, reason="pro_required")
            await _controls.wait_if_paused()
            if _controls.is_stop():
                emit_event("pipeline_stopped", phase=1, reason="user_stop_pro_required")
                return None
            if _controls.consume_retry_phase(1):
                # User clicked Retry — re-run PROMPT_SELECT_PRO. Likely the
                # user signed into a Pro account in the open browser; the
                # next iteration will detect Pro and break.
                log("Phase 1: user clicked Retry on pro_required — re-running Pro selector", "INFO")
                emit_event("pipeline_resumed", phase=1, reason="pro_retry")
                continue
            # continue_anyway / generic resume → ack and proceed on Free.
            chose_free = _controls.consume_continue_anyway()
            _controls.pro_warning_acknowledged = True
            log("Phase 1: user opted into Free — proceeding with Free-tier brief", "INFO")
            # F3: clear stale pro_required alert documents from FE store BEFORE
            # the resumed event fires (resumed is what triggers the auto-clear
            # sweep on the FE). Order: flag → clear emit → resumed emit.
            _clear_pro_required_alerts(triggered_at_phase=1)
            emit_event("pipeline_resumed", phase=1,
                       reason="continue_with_free" if chose_free else "resume")
            break

    # #759 (2026-06-02): post-select DOM confirm that Pro + Extended Thinking
    # actually STUCK (vs a silent revert to Instant/Auto). Runs only when the CUA
    # selector CLAIMED success — never on a user-opted-Free path. FAIL-OPEN: only
    # a confirmed downgrade does ONE silent re-run of the selector; everything
    # else proceeds. No card/pause/badge — this is a quality knob (like Claude's
    # Effort/Thinking), WARN-only.
    #
    # ⚠ It does NOT run when the DOM rung settled the tier: `_pro_select_claimed`
    # stays False on that path by construction. The confirm exists to check a
    # PROSE claim ("no 'no pro' in the verdict") against the DOM; the DOM rung's
    # verdict already IS a DOM read of the same trigger, so re-reading it would
    # be the same evidence twice and a `downgrade` verdict there would fire a CUA
    # re-select against a tier we just watched land.
    if _p1_tier_ok:
        log(f"[Phase1] Tier confirmed by the DOM rung ({_p1_tier}) — skipping the "
            f"post-select confirm (it re-reads the same trigger)", "INFO")
    if cua_client and _pro_select_claimed:
        try:
            _epc = await _chatgpt_extended_pro_confirm(browser.page)
        except Exception:
            _epc = "unsure"
        if _epc == "downgrade":
            log("[Phase1] Post-select confirm: ChatGPT shows a non-Pro thinking "
                "mode (Instant/Auto) with no Extended-Pro marker — silently "
                "re-running the Pro+Extended selector ONCE", "WARN")
            try:
                async def _select_pro_rerun_cua():
                    return await asyncio.wait_for(
                        agent_loop(cua_client, browser, PROMPT_SELECT_PRO,
                            _p1_tier_mission(),   # policy-rendered; no phantom thinking toggle
                            model=CUA_MODEL, max_iterations=15, verbose=verbose),
                        timeout=180.0,
                    )

                # #839 act tier: fail-open re-select (result ignored — the log
                # trail re-confirm below is all that reads state). Same picker
                # invariants via PROMPT_SELECT_PRO.
                await _shadow_observed_cua(
                    browser.page, hotspot_id="1a-select-pro", phase=1, platform="chatgpt",
                    current_step="reselect_effort_tier_after_downgrade",
                    context_hint="post-select DOM confirm saw a non-Pro mode — re-select. "
                                 + _p1_tier_mission(),
                    expected_outcome=_p1_select_pro_hotspot()["expected_outcome"],
                    cua_coro_factory=_select_pro_rerun_cua,
                    mission_prompt=PROMPT_SELECT_PRO,
                    act_timeout_s=150.0)
            except Exception as _epc_e:
                log(f"[Phase1] Extended-Pro re-run did not complete "
                    f"({type(_epc_e).__name__}) — proceeding (fail-open)", "INFO")
            # Re-confirm once for the log trail only; proceed regardless.
            try:
                _epc2 = await _chatgpt_extended_pro_confirm(browser.page)
                log(f"[Phase1] Post re-run Extended-Pro confirm: {_epc2}", "INFO")
            except Exception:
                pass
        else:
            log(f"[Phase1] Post-select Extended-Pro confirm: {_epc} (proceeding)", "INFO")

    # Attach PDFs
    _pdf_total = len(pdf_paths) if pdf_paths else 0
    for _pdf_idx, pdf in enumerate(pdf_paths, 1):
        _pdf_name = Path(pdf).name
        log(f"Attaching PDF: {_pdf_name}")
        _pdf_progress = (f"Attaching {_pdf_name} ({_pdf_idx}/{_pdf_total})…"
                         if _pdf_total > 1 else f"Attaching {_pdf_name}…")
        emit_event("agent_progress", phase=1, agent="chatgpt",
                   status="attaching_pdf",
                   progress=_pdf_progress)
        attached = await attach_pdf_chatgpt(browser, pdf)
        if not attached and cua_client:
            log("Trying CUA for PDF attachment...")
            browser.set_upload_file(str(pdf))

            async def _attach_pdf_cua():
                return await agent_loop(cua_client, browser, PROMPT_ATTACH_PDF,
                    "Attach the file. The file dialog will auto-select it — just click the attachment button.",
                    model=CUA_MODEL, max_iterations=10, verbose=verbose)

            # #839 act tier: the OS file chooser is auto-answered by
            # BrowserSession's filechooser handler consuming the upload queue —
            # Vision only needs to click the attach/+ control, NOT drive the
            # native dialog. set/clear_upload_file bracket stays in place.
            try:
                await _shadow_observed_cua(
                    browser.page, hotspot_id="1a-attach-pdf", phase=1, platform="chatgpt",
                    current_step="attach_brief_pdf",
                    context_hint="click ChatGPT's attach / + / paperclip control to open the "
                                 "file picker (the OS dialog auto-selects the file) — do NOT "
                                 "try to drive the native file dialog yourself",
                    expected_outcome="the brief PDF is attached to the composer",
                    cua_coro_factory=_attach_pdf_cua,
                    mission_prompt=PROMPT_ATTACH_PDF)
            finally:
                browser.clear_upload_file()

    # Deep Research belongs to Phase 2 ONLY. ChatGPT persists the last-used
    # composer tool per account, so a prior run's P2 'Deep research' pill can be
    # sticky-on here and would silently run the brief as a deep research (wrong
    # output type + a Start-gate card + a burned DR slot — user-captured
    # 2026-07-08). Clear it just before submit so the composer is guaranteed in
    # normal Pro+Extended mode. Fully fail-safe: a miss only logs + proceeds.
    try:
        await _chatgpt_clear_deep_research(browser, cua_client, verbose=verbose)
    except Exception as _cdr_e:
        log(f"Phase 1: clear-Deep-Research step errored ({_cdr_e}) — proceeding", "WARN")

    # Build and submit the brief prompt
    prompt = (
        f'Please create a detailed research report brief for a deep research LLM agent '
        f'that covers this topic: {topic}. Be as thorough as you can. Simply output the '
        f'research brief, no preamble or post-amble. I just need something I can copy and '
        f'paste into a research agent LLM.'
    )
    if feedback:
        prompt += f'\n\nUSER FEEDBACK (incorporate this): {feedback}'
        log(f"Phase 1: Injecting user feedback: {feedback[:100]}")
    emit_event("agent_progress", phase=1, agent="chatgpt",
               status="submitting",
               progress="Submitting the research-brief prompt…")
    submitted = await submit_chatgpt_direct(browser, prompt)
    if not submitted and cua_client:
        log("Falling back to CUA for submit...")

        async def _submit_cua():
            return await agent_loop(cua_client, browser, PROMPT_SUBMIT_FALLBACK,
                f"Submit this prompt to ChatGPT:\n\n{prompt}",
                model=CUA_MODEL, max_iterations=15, verbose=verbose)

        # #839 act tier: side-effect-only (result ignored); success is judged
        # by the wait_until_verified(verify_chatgpt_generating) gate right below.
        await _shadow_observed_cua(
            browser.page, hotspot_id="1a-submit", phase=1, platform="chatgpt",
            current_step="submit_brief_prompt",
            context_hint="the brief prompt is in the composer — click Send to submit it "
                         "(the DOM submit already failed once)",
            expected_outcome="the research-brief prompt is submitted and ChatGPT starts generating",
            cua_coro_factory=_submit_cua,
            mission_prompt=PROMPT_SUBMIT_FALLBACK)

    # VERIFY: confirm ChatGPT is generating
    emit_event("agent_progress", phase=1, agent="chatgpt",
               status="verifying_generation",
               progress="Waiting for ChatGPT Pro + Thinking to start generating…")
    verified = await wait_until_verified(verify_chatgpt_generating, browser.page, "Phase1",
        browser=browser, cua_client=cua_client, max_retries=15, interval=3, verbose=verbose)
    if not verified:
        log("Phase 1: Could not verify ChatGPT is generating", "ERROR")
        # No alert: orchestrator's outer retry loop handles re-attempts; if
        # it exhausts retries, fail_phase fires upstream.
        return None

    # Register brief page with dispatcher for mid-run user input.
    # MutationObserver was already injected earlier (right after navigate) so
    # the observer has been capturing token-level stream during verify.
    _runtime.phase = 1
    _runtime.sub_state = "1_brief_generating"
    _runtime.register_page("chatgpt", browser.page, browser.page.url)

    # Wait for response. 2026-05-06 (Stream 2 D2/D3): no inner wall-clock
    # cap — the outer _await_phase_with_active_deadline(1, PHASE_1_MAX_MIN,
    # soft_warn_only=True) is the sole P1 ceiling. Multi-signal stall
    # detector inside poll_until_done raises _BriefStreamStalled if
    # ChatGPT freezes mid-stream (text + sources + steps flat for 20m).
    log(f"Polling for response (every {POLL_PRO}s)...")
    try:
        completed = await poll_until_done(browser.page, verify_chatgpt_generating, "Phase1", POLL_PRO, MAX_WAIT_PRO,
            browser=browser, cua_client=cua_client, verbose=verbose, phase=1)
    except _BriefStreamStalled as _bs:
        log(f"Phase 1: brief stream stalled — {_bs}", "WARN")
        _runtime.unregister_page("chatgpt", final_status="stalled")
        retries_left_p1s = max(0, 2 - _retry_count)
        # ⭐ 2026-08-11 — "Skip" was a lie on this card, and the copy promised
        # something the code does not do.
        #
        # There is no such thing as skipping phase 1: phase 2 attaches brief.md
        # to every agent, so a run without a brief cannot continue. What the
        # skip branch ACTUALLY does is fall through and extract whatever has
        # streamed so far. On 2026-08-11 that was the right outcome and rescued
        # the run — the brief was complete (65707 chars); only the completion
        # DETECTOR was wrong — but the owner pressed a button labelled "Skip"
        # that said it would let them "write your own", and got a finished
        # brief and a seamless phase 2 instead. A control whose label and
        # behaviour disagree is worse than a missing control.
        #
        # So the action is named for what it does, and it is only OFFERED when
        # it can work. Against an empty screen the same button yields a 0-char
        # brief and the false "no brief generated" failure, which is how this
        # path has burned runs before.
        _p1s_salvageable = int(getattr(_bs, "text_len", 0) or 0) >= _MIN_SALVAGEABLE_BRIEF_LEN
        _p1s_actions = []
        if retries_left_p1s > 0:
            _p1s_actions.append({"id": "retry", "label": "Retry", "style": "primary",
                                 "command": {"action": "retry_phase", "phase": 1}})
        if _p1s_salvageable:
            _p1s_actions.append({"id": "skip", "label": "Use what's on screen",
                                 "style": "default",
                                 "command": {"action": "skip_phase", "phase": 1}})
        _p1s_title, _p1s_body = _p1_stall_card_copy(
            contested=bool(getattr(_bs, "contested", False)),
            salvageable=_p1s_salvageable,
            text_len=int(getattr(_bs, "text_len", 0) or 0))
        fail_phase(1,
                   _p1s_title,
                   _p1s_body,
                   agent="chatgpt",
                   can_retry=retries_left_p1s > 0,
                   actions=_p1s_actions)
        if retries_left_p1s > 0 or _p1s_salvageable:
            p1s_decision = await _controls.await_phase_decision(1)
            log(f"Phase 1 stall decision: {p1s_decision}")
            if p1s_decision == "stop":
                return None
            if p1s_decision == "retry" and retries_left_p1s > 0:
                try:
                    emit_event("phase_restart", phase=1,
                               reason="user_retry_brief_stall",
                               attempt=_retry_count + 2)
                except Exception:
                    pass
                return await run_phase1(browser, cua_client, topic, pdf_paths,
                                        verbose=verbose, feedback=feedback,
                                        _retry_count=_retry_count + 1)
            # "Use what's on screen" → fall through and extract what streamed.
            # Only reachable when the card offered it, i.e. there IS enough text;
            # a retry arriving with no retries left (a stale card in a reopened
            # tab) falls through here too rather than recursing past the cap.
        completed = False
    # Unregister once brief is done (also covers stall-skip fall-through;
    # idempotent — safe to call even if already unregistered above).
    _runtime.unregister_page("chatgpt", final_status="done" if completed else "stalled-skipped")

    # ── Mid-Phase-1 injection: if user sent context while brief was generating,
    #    submit it as a follow-up to ChatGPT and wait for the updated brief ──
    # Only pop the buffer if we're going to use it — otherwise leave it for
    # Phase 2 / NotebookLM to consume (pop is destructive, so peek first).
    extra_ctx = None
    if completed and _controls.peek_extra_context():
        extra_ctx = _controls.pop_extra_context()
    if extra_ctx and completed:
        log(f"Phase 1: Injecting user context as follow-up ({len(extra_ctx)} chars)")
        emit_event("agent_progress", phase=1, agent="chatgpt",
                   status="refining", progress=f"Incorporating user input: {extra_ctx[:80]}...")
        followup = (
            f"Please update and improve the research brief above to also incorporate "
            f"the following additional context from the user:\n\n{extra_ctx}\n\n"
            f"Output the complete updated research brief. No preamble."
        )
        submitted_fu = await submit_chatgpt_direct(browser, followup)
        if not submitted_fu and cua_client:
            async def _submit_fu_cua():
                return await agent_loop(cua_client, browser, PROMPT_SUBMIT_FALLBACK,
                    f"Submit this follow-up prompt to ChatGPT:\n\n{followup[:500]}",
                    model=CUA_MODEL, max_iterations=10, verbose=verbose)

            # #839 act tier: side-effect-only; the follow-up verify gate below
            # is the ground truth.
            await _shadow_observed_cua(
                browser.page, hotspot_id="1a-submit", phase=1, platform="chatgpt",
                current_step="submit_followup_prompt",
                context_hint="a follow-up prompt is in the composer — click Send to submit it",
                expected_outcome="the follow-up prompt is submitted and ChatGPT regenerates",
                cua_coro_factory=_submit_fu_cua,
                mission_prompt=PROMPT_SUBMIT_FALLBACK)
        # Wait for the updated response
        await asyncio.sleep(5)
        verified_fu = await wait_until_verified(verify_chatgpt_generating, browser.page, "Phase1-followup",
            browser=browser, cua_client=cua_client, max_retries=10, interval=3, verbose=verbose)
        if verified_fu:
            log("Phase 1: Waiting for updated brief...")
            try:
                await poll_until_done(browser.page, verify_chatgpt_generating, "Phase1-followup",
                    POLL_PRO, 15,  # 15 min max — dead arg post-D2; kept for signature stability
                    browser=browser, cua_client=cua_client, verbose=verbose, phase=1)
            except _BriefStreamStalled as _bs_fu:
                log(f"Phase 1 followup stalled — using pre-followup brief: {_bs_fu}", "WARN")
        else:
            log("Phase 1: Follow-up may not have triggered generation — using original brief", "WARN")

    # Extract
    brief_text = await extract_chatgpt_response(browser.page)
    chat_url = await browser.current_url()

    brief_len = len(brief_text or "")

    # #754 (2026-06-02): EXTRACTION-FAIL auto-retry. The P1 brief is inline
    # extended-thinking text — there is NO result panel / download button for it
    # — so the #752 canvas-open re-extract had nothing to act on (it fired 4×
    # in E2E across 05:05/06:31/09:08/09:10 and recovered a brief ZERO times).
    # Removed. HTML→MD is P1's only sensible extractor.
    #
    # This handles a DIFFERENT case from a failed brief: the brief GENERATED
    # fine (completed=True) but the HTML→MD pull came back empty — a transient
    # DOM-render / selector miss, not a wedge. Re-pull HTML→MD up to
    # P1_EXTRACT_RETRY_MAX times, P1_EXTRACT_RETRY_GAP_SEC apart, and STOP the
    # instant real text appears. Strictly gated:
    #   • completed   → only when generation genuinely finished (a FAILED brief
    #                   is the stall path's job: poll_until_done raises
    #                   _BriefStreamStalled → user alert to retry the whole run;
    #                   we must NOT auto-retry extraction there).
    #   • brief_len<100 → only on an EMPTY pull (a short-but-present brief is
    #                   handled by the brief-short guard below — not a retry).
    # So it never fires on success and never on a wedge — no false retries.
    P1_EXTRACT_RETRY_MAX = 2
    P1_EXTRACT_RETRY_GAP_SEC = 180  # 3 min between pulls — let a slow DOM settle
    _extract_attempt = 0
    while completed and brief_len < 100 and _extract_attempt < P1_EXTRACT_RETRY_MAX:
        if _controls.is_stop():
            log("Phase 1: stop requested during extraction-retry — aborting")
            return None
        _extract_attempt += 1
        log(f"Phase 1: brief generated but extraction empty ({brief_len} chars) — "
            f"re-pulling HTML→MD in {P1_EXTRACT_RETRY_GAP_SEC // 60} min "
            f"(attempt {_extract_attempt}/{P1_EXTRACT_RETRY_MAX})", "WARN")
        # Stop-aware wait: poll is_stop every few seconds so a Stop during the
        # 3-min gap is honored promptly (not after the full sleep + another pull).
        _waited = 0.0
        while _waited < P1_EXTRACT_RETRY_GAP_SEC and not _controls.is_stop():
            await asyncio.sleep(min(5.0, P1_EXTRACT_RETRY_GAP_SEC - _waited))
            _waited += 5.0
        if _controls.is_stop():
            log("Phase 1: stop requested during extraction-retry wait — aborting")
            return None
        try:
            _retry_text = await extract_chatgpt_response(browser.page)
        except Exception as _re_exc:
            log(f"Phase 1: extraction re-pull errored ({_re_exc}) — "
                f"{'retrying' if _extract_attempt < P1_EXTRACT_RETRY_MAX else 'giving up'}", "WARN")
            _retry_text = ""
        _retry_len = len(_retry_text or "")
        if _retry_len > brief_len:
            log(f"Phase 1: extraction re-pull recovered {_retry_len} chars (was {brief_len})")
            brief_text = _retry_text
            brief_len = _retry_len
            try:
                chat_url = await browser.current_url()
            except Exception:
                pass
        # Loop condition re-checks brief_len<100 → exits the moment text appears.

    # Brief-short guard: DR briefs are typically 2-5k chars. Under 500 while
    # we were expecting >1000 usually means ChatGPT errored or the extractor
    # grabbed the wrong element. Warn (not error) so the frontend can offer
    # [continue_anyway] / [retry] — the caller polls consume_continue_anyway()
    # to decide whether to accept the short brief.
    P1_MAX_USER_RETRIES = 2  # total attempts = 1 + P1_MAX_USER_RETRIES
    if brief_text and brief_len >= 100 and brief_len < 500:
        retries_left = max(0, P1_MAX_USER_RETRIES - _retry_count)
        fail_phase(1,
                   "The brief looks unusually short",
                   "ChatGPT's brief came back much shorter than expected. Retry to regenerate it, or continue with it.",
                   agent="chatgpt",
                   can_retry=retries_left > 0)
        # Wait for the user's decision via the standard phase-decision bus.
        if retries_left > 0:
            decision = await _controls.await_phase_decision(1)
            log(f"Phase 1 brief-short decision: {decision}")
            if decision == "stop":
                return None
            if decision == "retry":
                try:
                    emit_event("phase_restart", phase=1,
                               reason="user_retry_brief_short",
                               attempt=_retry_count + 2,
                               chars=brief_len)
                except Exception:
                    pass
                log(f"Phase 1: User requested retry (attempt {_retry_count + 2}/{P1_MAX_USER_RETRIES + 1})")
                return await run_phase1(browser, cua_client, topic, pdf_paths,
                                        verbose=verbose, feedback=feedback,
                                        _retry_count=_retry_count + 1)
            # 'continue_anyway' or 'timeout' → fall through and return short brief

    if brief_text and brief_len > 100:
        log(f"Brief extracted: {brief_len} chars")
        return {"text": brief_text, "url": chat_url}
    else:
        log(f"Brief too short ({brief_len} chars)", "WARN")
        return {"text": brief_text or "", "url": chat_url}


# ── Phase 2: Parallel Deep Research (Sequential Start + Verify) ──────────────

# ── Playwright-direct platform setup (replaces vision-based CUA setup) ────────

async def setup_chatgpt_dr(page, allow_model_pick=False, *,
                           _drift_retry: bool = False) -> bool:
    """Enable ChatGPT Deep Research mode via direct selectors. Returns True on success.

    Step-by-step logs emit on every branch so next run's log tells us
    exactly which step broke — previously this was one-line "setup failed"
    with no detail, leaving us guessing whether the + menu opened, whether
    the DR option was found, or whether verification landed.

    ⭐ (2026-08-03) READ-FIRST. Step 0 asks whether Deep Research is ALREADY on
    before touching anything. It is sticky per account, and
    ``ensure_deep_mode_active`` re-enters this function whenever its own state
    read comes back false — so the old unconditional "open the menu, click Deep
    research" could arrive at an already-selected tool and click it, which on the
    current UI ADDS A SECOND Deep Research rather than toggling it off. That is
    the same firewall ``selfheal.decide_toggle`` was extracted for, and it is now
    the first thing this function does.

    ``allow_model_pick`` is the exact analogue of ``setup_claude_dr``'s
    ``allow_probe``, and exists for the same reason. This function is re-entered
    from ``ensure_deep_mode_active``'s PRE-SEND check and from the mid-run
    recovery paths, where the composer already holds the brief — opening the
    effort menu there is the #744 screenshot, a popover sitting over a loaded
    composer seconds before send. Only the INITIAL P2 setup passes True.
    """
    try:
        await asyncio.sleep(2)
        _tiers, _verbs, _tool_word = _chatgpt_tier_policy()

        async def _dr_state():
            try:
                return await page.evaluate(_CHATGPT_DR_ACTIVE_JS) or {}
            except Exception as _se:
                log(f"[setup_chatgpt_dr] composer probe failed ({_se})", "INFO")
                return {}

        # ── Step 0: the pre-act toggle guard (#709). ──
        # `confirmed_off` is a POSITIVE off-signal, not merely "the predicate said
        # false": the composer has to be READABLE (a placeholder came back) before
        # an absent pill counts as evidence it is off.
        #
        # ⛔ ALL THREE DECISIONS ARE LOAD-BEARING, including `ambiguous`. The
        # firewall's rule is that a toggle may only ever move a CONFIRMED-opposite
        # control, and this platform is the strongest case for it: a click on an
        # already-selected Deep Research does not toggle it off, it ADDS A SECOND
        # ONE. An unreadable composer is not evidence of anything, so we decline
        # to click and return False — which hands the intent to the ladder's next
        # rung rather than gambling. The cost of that is one Vision/CUA fallback,
        # i.e. exactly what this step did on every run before it worked at all.
        _st0 = await _dr_state()
        _confirmed_off = bool(_st0) and not _st0.get("active") and bool(_st0.get("placeholder"))
        _toggle_dec = _toggle_decision(bool(_st0.get("active")), _confirmed_off)
        if _toggle_dec == "skip":
            log(f"[setup_chatgpt_dr] Step 0: Deep Research is ALREADY active "
                f"(pill={_st0.get('pillText')!r} placeholder={_st0.get('placeholder')!r}) — "
                f"NOT clicking the menu item (a second click adds a second Deep Research)")
            if allow_model_pick:
                await _chatgpt_p2_effort_tier(page)
            return True
        if _toggle_dec == "ambiguous":
            log(f"[setup_chatgpt_dr] Step 0: cannot read the composer "
                f"(state={_st0!r}) — declining to click Deep Research on an "
                f"ambiguous read; the next rung takes it", "WARN")
            return False
        log(f"[setup_chatgpt_dr] Step 0: Deep Research not active "
            f"(decision={_toggle_dec}, placeholder={(_st0 or {}).get('placeholder')!r}) — enabling it")

        # Step 1: open the + / tools menu in the composer.
        # Ordered hooks, most-durable first. The captured control is
        # `button[data-testid="composer-plus-btn"]` with aria-label "Add files and
        # more" — which is why the testid leads: the two aria patterns that used
        # to run ahead of it match nothing on that label ("Attach" is absent, and
        # `*="More"` is case-SENSITIVE so it misses "more"), and `*="Attach"`
        # reaching a real attachment button would open a file chooser instead of
        # the tools menu.
        #
        # ⭐ The URL is read HERE, before the first press, and re-read after Step 2.
        # On 2026-08-05 this function navigated the tab into a five-hour-old
        # conversation and reported success, twice, and nothing between the
        # new-chat proof and the send ever looked at the tab's identity again.
        _url_at_entry = ""
        try:
            _url_at_entry = page.url or ""
        except Exception:
            pass

        # The pre-open census — see `_CHATGPT_ROW_FILTER_JS`. Taken BEFORE the "+"
        # is pressed so the row read below can tell the menu's own rows (which
        # appear on the press) from everything that was already on screen (the
        # sidebar's recent-conversation links, the suggestion strip).
        try:
            _seen_rows = await page.evaluate(
                _CHATGPT_ROWS_SEEN_JS, {"groups": _CHATGPT_TOOL_ROW_GROUPS}) or []
        except Exception:
            _seen_rows = []

        menu_sel = None
        for sel in ['button[data-testid="composer-plus-btn"]',
                    'button[aria-label*="Add files" i]',
                    'button[aria-label*="Use a tool" i]',
                    'button[aria-label*="Attach" i]',
                    'button[aria-label*="more" i]']:
            try:
                btn = await page.query_selector(sel)
                if btn:
                    await btn.click()
                    await asyncio.sleep(0.8)
                    menu_sel = sel
                    break
            except Exception:
                continue
        if not menu_sel:
            log("[setup_chatgpt_dr] Step 1 FAIL: tools/+ menu button not found — selectors may have rotated", "WARN")
            return False
        log(f"[setup_chatgpt_dr] Step 1 OK: opened tools menu via {menu_sel} "
            f"({len(_seen_rows)} row(s) already on screen before the press)")

        # Step 2: click the Deep-Research row in the menu.
        #
        # ⭐ (2026-08-03) The user-captured "+" menu is not a portal, not
        # `[role=menu]`, not `[data-state=open]`: it renders inline in the body and
        # its rows are plain DIVs with NO role, NO aria-label and NO data-testid —
        # `class="group __menu-item gap-1.5"` is the only hook. So the prior
        # role-based candidate set could not match a single row, Step 2 missed on
        # every run, and the CUA fallback had been carrying this step for months.
        #
        # ⛔ The candidate set does NOT include `button, a, li`, and that is the
        # safety half of the fix. ChatGPT renders a SUGGESTION STRIP whose chips
        # carry near-identical labels with a DIFFERENT class ("Search the web" vs
        # the menu's "Web search", "Create an image" vs "Create image"). An
        # unscoped element search reaches those chips, clicks one, and the tool is
        # silently never enabled — a failure that looks exactly like success from
        # here. Excluding them by class, not by label, means a new chip label
        # cannot re-open that hole.
        #
        # ⚠ 2026-08-05 — THE COMMENT THAT USED TO OPEN THIS BLOCK CLAIMED THE
        # SEARCH WAS "SCOPED TO THE MENU'S OWN ROWS". It never was: `.__menu-item`
        # is a bare class matched against `document`, with no container test, and
        # ChatGPT's sidebar recents rows answer it too. The scoping now lives in
        # `_CHATGPT_ROW_FILTER_JS` and is real — an anchor exclusion plus the
        # pre-open census above. Read that block for the History-DB evidence.
        #
        # The target word is the policy's tool label, not a literal.
        try:
            _snap = await page.evaluate(_CHATGPT_MENU_ROWS_JS,
                                        {"groups": _CHATGPT_TOOL_ROW_GROUPS,
                                         "seen": _seen_rows})
        except Exception as _me:
            log(f"[setup_chatgpt_dr] Step 2: menu row read failed ({_me})", "WARN")
            _snap = {}
        _rows = list((_snap or {}).get("rows") or [])
        _via = (_snap or {}).get("via") or ""
        # The census the READ actually applied — it switches its advisory arm off
        # when that arm would have emptied the set, and the click must resolve its
        # index against the same list or the two disagree again.
        _seen_used = list((_snap or {}).get("seen_used") or [])
        if (_snap or {}).get("census_ignored"):
            log(f"[setup_chatgpt_dr] Step 2: the pre-open census matched every "
                f"candidate, so it was ignored for this read — the conversation-link "
                f"exclusion still applies", "WARN")
        # Title and description are CONCATENATED in these rows ("Deep research Get
        # a detailed report"), so the match is a prefix-or-word test, never `===`.
        _idx = -1
        for _i, _r in enumerate(_rows):
            _rl = (_r or "").strip().lower()
            if _rl.startswith(_tool_word) or has_term(_rl, [_tool_word]):
                _idx = _i
                break
        clicked = False
        if _idx >= 0:
            try:
                _res = await page.evaluate(_CHATGPT_CLICK_ROW_JS,
                                           {"groups": _CHATGPT_TOOL_ROW_GROUPS, "via": _via,
                                            "index": _idx, "expect": _rows[_idx],
                                            "seen": _seen_used,
                                            "attr": _SR_CLICK_MARK, "value": "tool-row"})
                clicked = bool(isinstance(_res, dict) and _res.get("clicked"))
                if clicked:
                    # The row is only MARKED at this point — see _sr_real_click.
                    # A row that cannot be pressed is not a row that was clicked,
                    # and reporting it as one is what sends the caller past its
                    # own verification with nothing having happened.
                    clicked = bool(await _sr_real_click(
                        page, "tool-row", tag="[setup_chatgpt_dr]"))
                    # ⭐ SAY WHICH ROW. `_CHATGPT_CLICK_ROW_JS` has always returned
                    # the text it marked and Python threw it away, so on the
                    # 2026-08-05 runs where the pressed element was a sidebar
                    # conversation link the log said only "Step 2 OK: clicked Deep
                    # research menu option" — naming the intent, never the target.
                    if clicked:
                        log(f"[setup_chatgpt_dr] Step 2 pressed "
                            f"{str((_res or {}).get('text') or '')[:48]!r} "
                            f"(via {_via or '-'}, {len(_rows)} new row(s), "
                            f"{(_snap or {}).get('rejected', 0)} rejected by the filter)")
                    if not clicked:
                        log(f"[setup_chatgpt_dr] Step 2: row {_rows[_idx][:40]!r} was "
                            f"located but could not be pressed", "WARN")
                else:
                    log(f"[setup_chatgpt_dr] Step 2: row {_rows[_idx][:40]!r} not clicked "
                        f"(reason={(_res or {}).get('reason')})", "WARN")
            except Exception as _ce:
                log(f"[setup_chatgpt_dr] Step 2: row click errored ({_ce})", "WARN")
        else:
            log(f"[setup_chatgpt_dr] Step 2: no '{_tool_word}' row among {len(_rows)} "
                f"menu rows via {_via or '-'} "
                f"({(_snap or {}).get('rejected', 0)} candidate(s) rejected as "
                f"conversation links or already-on-screen): "
                f"{json.dumps([r[:32] for r in _rows[:8]], ensure_ascii=False)}", "INFO")
        if not clicked:
            # One-shot diagnostic dump (mirrors #708 Step 3A) so the NEXT E2E
            # pins the exact menu-item structure instead of us guessing the
            # selector. Grep backend.log for "Step 2 menu-item dump".
            try:
                # Diagnostic ONLY — this one stays document-wide on purpose (it
                # has to be able to show us a control no selector reached), and
                # it now reports `cls` because the live rows turned out to be
                # class-only DIVs, which a role/aria/testid dump could not have
                # revealed. Nothing here clicks.
                dump = await page.evaluate("""() => {
                    const out = [];
                    for (const el of document.querySelectorAll(
                            '[role="menuitem"], [role="menuitemradio"], [role="option"], '
                            + '.__menu-item, button, a, li')) {
                        if (!el.offsetParent) continue;
                        const t = (el.textContent || '').replace(/\\s+/g, ' ').trim();
                        const a = el.getAttribute('aria-label') || '';
                        if (!t && !a) continue;
                        const c = (el.className && el.className.toString) ? el.className.toString() : '';
                        out.push({ role: el.getAttribute('role') || el.tagName.toLowerCase(),
                                   text: t.slice(0, 60), aria: a.slice(0, 60),
                                   testid: el.getAttribute('data-testid') || '',
                                   // ⭐ 2026-08-05: `href` was the missing column.
                                   // Every past dump was 30 rows of the sidebar
                                   // with no way to tell a conversation LINK from
                                   // a menu row — which is precisely what this
                                   // dump existed to reveal and never did.
                                   href: (el.getAttribute('href') || '').slice(0, 46),
                                   cls: c.slice(0, 60) });
                    }
                    // 30 was the cap, and ChatGPT's sidebar spends all 30 before
                    // document order reaches the composer.
                    return out.slice(0, 80);
                }""")
                log("[setup_chatgpt_dr] Step 2 menu-item dump: " + json.dumps(dump))
            except Exception as _de:
                log(f"[setup_chatgpt_dr] Step 2 dump failed: {_de}", "WARN")
            # #739: DOM menu-item miss is expected (selectors rotated) and the
            # CUA fallback enables Deep Research every time — INFO, not a WARN
            # (the diagnostic dump above still pins the rotated selector).
            log("[setup_chatgpt_dr] Step 2: DOM 'Deep research' menu item not found (selectors rotated) — CUA fallback will enable DR", "INFO")
            return False
        log("[setup_chatgpt_dr] Step 2 OK: clicked Deep research menu option")
        await asyncio.sleep(1.5)

        # ── Step 2½ — did that press MOVE THE TAB? (2026-08-05) ──
        #
        # ⛔ This runs BEFORE Step 3, and the order is the point. Step 3's detector
        # reads the composer PLACEHOLDER, and an old Deep-Research conversation's
        # composer reads "Get a detailed report" — so on 2026-08-05 Step 3 verified
        # "DR active" on a page we had just navigated away to, and the mis-click was
        # confirmed by its own consequence. Asking "is this still the same page?"
        # cannot be answered by anything on the new page, only by comparing.
        #
        # Returning False hands the intent to the ladder's next rung, which is the
        # same contract every other failure in this function follows.
        # ⚠ Compare the PATH, not the raw string. ChatGPT appends query params to
        # the same conversation as it streams — `?messageId=finalAgentTurnStart` is
        # on the incident's own URLs in Chrome's history — so a raw comparison
        # reports a tab move on a tab that never moved, and this branch gives the
        # intent up entirely rather than handing it down. Every sibling comparison
        # in this wave already strips the query; this one was the outlier. The log
        # keeps the RAW urls, because that is the diagnostic.
        _url_after = ""
        try:
            _url_after = page.url or ""
        except Exception:
            pass
        if (_url_at_entry and _url_after
                and _url_after.split("?", 1)[0] != _url_at_entry.split("?", 1)[0]):
            log(f"[setup_chatgpt_dr] Step 2½ ABORT: the tab MOVED while enabling "
                f"Deep Research — {_url_at_entry!r} → {_url_after!r}. The row that "
                f"was pressed navigated instead of toggling a tool; refusing to "
                f"verify anything on this page", "ERROR")
            # ⛔ RECOVER, don't merely refuse. Returning False here hands the intent
            # to the ladder's next rung — and that rung is a VISION/CUA pass with a
            # real mouse, which would then act on the foreign conversation we just
            # detected. Refusing while leaving the tab where it landed moves the
            # problem one rung down instead of solving it.
            #
            # One attempt, and only when the new chat is VERIFIED (the helper returns
            # True only on a fresh composer holding zero messages). `_drift_retry`
            # bounds it: a page that navigates on every press must not recurse.
            if not _drift_retry:
                try:
                    if await _chatgpt_force_new_chat(page, "setup_chatgpt_dr"):
                        log("[setup_chatgpt_dr] recovered to a fresh chat — retrying "
                            "Deep-Research setup once", "WARN")
                        return await setup_chatgpt_dr(
                            page, allow_model_pick=allow_model_pick,
                            _drift_retry=True)
                except Exception as _rc:
                    log(f"[setup_chatgpt_dr] new-chat recovery errored ({_rc})", "WARN")
            log("[setup_chatgpt_dr] could not get back to a fresh chat — the next "
                "rung must not act on a foreign conversation, so this intent is "
                "given up rather than handed on", "ERROR")
            return False

        # Step 3: verify DR actually activated.
        #
        # ⭐ THE SHARED DETECTOR, not a second opinion. This step used to carry
        # its own inline check and the two had drifted apart in both directions:
        # it demanded the pill's text be EXACTLY "deep research" (the shared
        # detector allows the label to carry a suffix), and its placeholder
        # signal tested for the word "research" when the real Deep-Research
        # placeholder is "Get a detailed report" — which contains neither. So a
        # correctly-enabled tool could verify as FAILED here and drop the run
        # into the CUA fallback for nothing. `_CHATGPT_DR_ACTIVE_JS` is also the
        # outcome predicate the self-heal contract declares for this intent, and
        # the contract's rule is that predicates are reused, never duplicated.
        active = await _dr_state()
        if not active or not active.get("active"):
            log("[setup_chatgpt_dr] Step 3 FAIL: clicked DR but the composer shows no "
                "Deep-Research pill or placeholder after 1.5s "
                f"(placeholder={(active or {}).get('placeholder')!r}) — click may have "
                "been intercepted", "WARN")
            return False
        log(f"[setup_chatgpt_dr] Step 3 OK: verified DR active "
            f"(pill={active.get('pillText')!r} placeholder={active.get('placeholder')!r})")
        if allow_model_pick:
            await _chatgpt_p2_effort_tier(page)
        return True
    except Exception as e:
        log(f"[setup_chatgpt_dr] exception: {e}", "WARN")
        return False


async def _chatgpt_p2_effort_tier(page) -> str:
    """Run the effort-tier picker on the P2 composer and shadow-log the intent.

    ⭐ THE SAME CONTROL AS PHASE 1. The capture's headline for ChatGPT is that
    effort and model are ONE menu, reached from the composer pill — so there is
    no separate "P2 model lever" to build, and this is the P1 picker pointed at
    the P2 page. In practice it opens nothing: ChatGPT persists the tier per
    account, P1 already put the pill on target, so the read-first branch returns
    ``already`` and the menu stays shut. That is deliberate — an extra popover
    over the composer is the #744 complaint, not a feature.

    Never raises and never gates: the P2 deliverable is Deep Research, and the
    tier is a quality knob (the same status Claude's effort has).
    """
    try:
        verdict = await _chatgpt_select_effort_tier(page, label="ChatGPT", phase=2)
    except Exception as e:
        log(f"[setup_chatgpt_dr] effort-tier pick errored ({e}) — non-fatal", "INFO")
        verdict = "unsure"
    if selfheal and selfheal.is_enabled():
        # ⚠ outcome_pass is the REAL verdict now. This call used to pass a
        # hardcoded True against a "a model selector is ABSENT" predicate, so the
        # shadow log recorded a pass for an intent that was asserting something
        # the live DOM disproves — every sample from it was noise.
        await _selfheal_shadow_observe(page, "chatgpt.select_model",
                                       outcome_pass=verdict in ("already", "selected"))
    return verdict


# Phoenix (model_refresh) — last-observed advisory thinking/effort confirmation
# per platform, written by setup_*_dr and read by the caller to surface a soft
# notice when the policy's thinking config (Claude max-effort + thinking toggle,
# Gemini extended thinking) couldn't be applied. ADVISORY ONLY — never gates a
# run (user decision #4 = verify + soft-escalate, not hard-gate). Process-local
# (each worker is its own process); last write wins = the final setup state.
_P2_THINKING_STATE: dict = {}

# Phoenix (model_refresh) — last model VERSION the setup actually selected per
# platform (numeric), written by setup_*_dr and read by the caller to record
# the latest verified-working model as known_good (on-the-fly learning). Float
# or None; process-local; last write wins.
_P2_PICKED_VERSION: dict = {}

# Phoenix — the model FAMILY this run is actually on, per platform, when it is
# NOT the policy's primary family. Written by setup_*_dr the moment the DOM
# proves the account's plan excludes the primary family and the fallback is
# selected instead; every downstream reader goes through `_p2_active_family`.
#
# ⭐ WHY A RUN-SCOPED DICT AND NOT THE OVERLAY. The overlay is disk state shared
# by every run on this machine and every account those runs sign into. Writing
# `family: sonnet` there because ONE non-pro account was seen would downgrade
# the next pro run — permanently, silently, and with the model selection code
# reporting complete success. The fallback is a fact about an ACCOUNT, and the
# only thing here that is scoped to an account is the run.
#
# ⛔ ABSENT MEANS "THE POLICY FAMILY", never "unknown". Every reader falls back
# to `p2_family`, so a run that never reached the detection behaves exactly as
# it did before this existed — which is what keeps the fallback strictly
# additive for the pro path.
_P2_ACTIVE_FAMILY: dict = {}


def _p2_active_family(platform: str) -> str:
    """The family word THIS run should be reading and asserting on `platform`.

    ⚠ Not a convenience wrapper. Six surfaces need this answer — the picker, the
    pre-send re-activation check, the ladder's outcome probe, the two CUA
    missions and the known-good ledger — and the failure when one of them keeps
    its own idea is not cosmetic: `ensure_deep_mode_active` reads the family to
    decide whether the model "regressed", so a reader still hardcoded to the
    primary family sees a deliberate fallback pick as a regression and re-runs
    the whole Claude setup before EVERY send, on every run, forever."""
    p = (platform or "").lower()
    fam = str(_P2_ACTIVE_FAMILY.get(p) or "").strip().lower()
    # Only a family the policy actually names is honored. A stale value left by
    # a previous policy edit must degrade to the primary family, not to a word
    # that no longer means anything to the pickers it is interpolated into.
    if fam and fam in (p2_family(p), p2_free_family(p)):
        return fam
    return p2_family(p)


# One-shot latch so a persistently unwritable state dir WARNs once per process
# instead of on every setup. See the record_probe call site for why a silent
# stamp failure matters: it turns the periodic model check into a per-run
# popover, which is the #744 complaint.
_PROBE_STAMP_WARNED = False


async def _selfheal_shadow_observe(page, intent_id: str, *, outcome_pass) -> None:
    """Phoenix self-heal SELECTOR engine (PX-0) — SHADOW observation, no action.

    Records what the self-heal engine WOULD see at one P2 setup intent: the
    intent's outcome predicate (REUSED verbatim from the live verify and passed
    in as ``outcome_pass``) plus a read-only ``probe_region`` snapshot of the
    intent's DOM region. Writes one line to ``logs/selfheal_shadow.jsonl`` and
    NOTHING else — it resolves no selector and clicks nothing (PX-2 turns these
    observations into real heals). Callers gate on ``selfheal.is_enabled()``
    (default OFF) so this is inert in production; it is additionally fully
    isolated here so any failure is swallowed and can never perturb a run.
    """
    if selfheal is None:
        return
    try:
        intent = selfheal.load_intents().get(intent_id) or {}
        region = intent.get("region") or "document"
        snap = await selfheal.probe_region(page, region)
        ok = bool(outcome_pass)
        # PX-2 (shadow): what the Tier-1.5 heal WOULD resolve here — the matched
        # element, its confidence, and the selector it would persist. Pure; acts
        # on nothing. selector_or_box stays None (PX-0/shadow resolves/clicks
        # nothing); the candidate lives in heal_* so the report can grade match
        # quality before activation.
        heal = selfheal.shadow_heal_decision(snap, intent)
        # ⭐ 2026-08-13 — `would_heal` WAS `not ok`, and nothing else.
        #
        # An observation whose probe came back EMPTY looked identical in the log
        # to one that examined the region and found it broken: both wrote
        # `would_heal: true`. They are not the same claim. An empty probe means
        # the engine had NOTHING TO LOOK AT — no drift was observed, because no
        # observation happened.
        #
        # It surfaced on the first real shadow run (2026-08-13). Three of eleven
        # records were `probe_count: 0` with `ui_fingerprint` da39a3ee5e6b — the
        # SHA-1 of the empty string — and all three counted as heals. That number
        # feeds `heals_by_platform`, which feeds the "≥1 heal shadowed per
        # platform" Definition-of-Done gate: the gate that decides shadow has
        # collected enough evidence to consider activation was about to be
        # satisfied by three observations of a blank document.
        #
        # Same defect the note at the `chatgpt.select_model` call site records —
        # "every sample from it was noise" — and the same lesson as the panel
        # audit: A COUNT IS NOT PROOF.
        #
        # `heal_match_found` still carries whether the attempt would LAND; this
        # only asserts that an attempt is a coherent thing to talk about.
        _observed = bool(snap)
        selfheal.shadow_log({
            "platform": intent.get("platform") or intent_id.split(".", 1)[0],
            "intent": intent_id,
            "tier": "builtin",          # the existing DOM heuristic just ran
            "outcome_pass": ok,
            # PX-2 would attempt a heal at this point — which requires having
            # seen the region at all.
            "would_heal": (not ok) and _observed,
            # Explicit rather than left to be inferred from probe_count, because
            # inferring it is exactly what nobody did for three records.
            "probe_empty": not _observed,
            "probe_count": len(snap),
            "selector_or_box": None,    # shadow resolves/acts nothing
            "confidence": None,
            "resolved_by": "shadow",
            "heal_match_found": heal.get("match_found"),
            "heal_confidence": heal.get("match_confidence"),
            "heal_selector": heal.get("inferred_selector"),
            "heal_reason": heal.get("match_reason"),
            "ui_fingerprint": heal.get("ui_fingerprint"),
        })
        # Optional corpus capture (DG_SELFHEAL_CAPTURE, default OFF): dump the FULL
        # probe snapshot so a real golden corpus + drift fixtures can be built from
        # live DOM. Self-gates; pure data capture.
        selfheal.capture_snapshot(
            intent.get("platform") or intent_id.split(".", 1)[0],
            intent_id, snap, outcome_pass=ok, fingerprint=heal.get("ui_fingerprint"),
        )
    except Exception as exc:
        # The log() call itself is guarded: this helper's whole contract is that
        # NOTHING escapes into the caller (ensure_deep_mode_active's outer except
        # treats a raise as active=True, which would flip a genuine active=False
        # under flag-ON). A log/stdout failure must not breach that.
        try:
            log(f"[selfheal] shadow observe {intent_id} skipped: {exc}", "INFO")
        except Exception:
            pass


async def _selfheal_try(page, intent_id: str, *, check_active, confirmed_off) -> bool:
    """Phoenix self-heal SELECTOR engine (PX-2 ACTIVATION) — attempt ONE bounded
    Tier-1.5 selector heal after the built-in DOM heuristic FAILED its predicate,
    before escalating to CUA/Decision-alert.

    DOUBLE-GATED: callers invoke this only behind ``selfheal.act_enabled()``
    (``DG_SELFHEAL_ACT`` AND ``DG_SELFHEAL_ENABLED``, both default OFF), so the
    live pipeline is unchanged until BOTH are flipped after a clean shadow window.
    Returns True iff the heal verified the intent active (re-ran the real
    predicate). Fully isolated — never raises into the verify path.

    ``check_active`` is the platform's REAL outcome predicate (async/sync -> bool);
    ``confirmed_off`` is its POSITIVE off-signal (gates the click per #709, so a
    false-negative predicate can't toggle a live control OFF).
    """
    if selfheal is None:
        return False
    try:
        intent = selfheal.load_intents().get(intent_id) or {}
        if not intent:
            return False
        res = await selfheal.heal_once(
            page, intent, check_active=check_active, confirmed_off=confirmed_off, do_act=True
        )
        try:
            log(f"[selfheal] heal {intent_id}: tier={res.get('tier')} acted={res.get('acted')} "
                f"healed={res.get('healed')} reason={res.get('reason')}", "INFO")
            selfheal.shadow_log({
                "platform": intent.get("platform"), "intent": intent_id,
                "tier": res.get("tier"), "outcome_pass": res.get("healed"),
                "would_heal": False, "acted": res.get("acted"),
                "selector_or_box": res.get("strategy"), "confidence": None,
                "resolved_by": "heal", "reason": res.get("reason"),
                "ui_fingerprint": res.get("fingerprint"),
            })
        except Exception:
            pass
        return bool(res.get("healed"))
    except Exception as exc:
        try:
            log(f"[selfheal] heal {intent_id} skipped: {exc}", "INFO")
        except Exception:
            pass
        return False


# Gemini "pick the newest Flash" ranker. Mirrors models.pick_highest_model
# (Python, unit-tested): among visible dropdown rows, reject Flash-Lite / Pro /
# Deep-Think FIRST, parse the version (row text is title+desc concatenated, so no
# trailing boundary after the family word), and pick the HIGHEST offered
# (tie → shortest text = leaf row). With doClick it clicks the winner; otherwise
# it is a read-only probe.
#
# ⭐ NO FLOOR, NO FAMILY LITERAL (2026-08-01). "Highest offered" cannot pick a
# downgrade, so a floor could only reject the row that should have won; and the
# family word now comes from policy. `below` is the step-back tool used when the
# newest model failed to enter Deep Research. A row naming the family with no
# parseable version is a last-resort candidate so a version-less rename does not
# empty the menu — but it is never a step-back target, since it cannot be proven
# older than what just failed.
_GEMINI_FLASH_RANK_JS = """({below, doClick, pin, fam, reject, triggerText,
                             nouns, verbs, upsellWindow, dropUpsell}) => {
    const items = [...document.querySelectorAll(
        '[role="menuitem"], [role="menuitemradio"], [role="option"], button, a, li')];
    const famRe = new RegExp(fam, 'i');
    // ⭐ BOTH VERSION ORDERS, deliberately — see models.parse_family_version,
    // which tries exactly these two patterns in exactly this order. Gemini ships
    // number-first ("3.6 Flash") and Claude family-first ("Opus 5") TODAY, so a
    // single-order parser is correct only until ITS OWN vendor renames. When that
    // happens every row parses as version-less, the ranking collapses to the
    // "shortest label" tie-break, and this selects an OLDER Flash while reporting
    // success — a silent downgrade, and `version: null` also disarms the step-back.
    const verFamFirst = new RegExp(fam + '[ ._/()-]{0,3}([0-9]+(?:\\\\.[0-9]+)?)', 'i');
    const verNumFirst = new RegExp('([0-9]+(?:\\\\.[0-9]+)?)[ ._/()-]{0,3}' + fam, 'i');
    const flashVer = t => {
        const m = (t || '').match(verFamFirst) || (t || '').match(verNumFirst);
        return m ? parseFloat(m[1]) : null;
    };
    // Character-level port of models.reject_matches — ONE definition of reject
    // semantics, not a second opinion. A term matches at a word boundary on the
    // left and, unless it ends in '*', on the right too:
    //   'lite*' rejects "flash-litefastest" but not "elite"
    //   'pro'   rejects " pro " but NOT "productivity"/"improve" — a substring
    //           match there would bin a Flash row over a word in its blurb, and
    //           if that bins every Flash row the run falls back to whatever the
    //           dropdown defaulted to (the Gemini-Pro DR hang).
    // Regex-free on purpose: this is a non-raw Python string, where a lone \\b
    // once became a literal backspace and silently killed a gate (#913).
    const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
    const rejected = (t) => {
        for (let raw of (reject || [])) {
            let term = String(raw).toLowerCase();
            const prefix = term.endsWith('*');
            if (prefix) term = term.slice(0, -1);
            if (!term) continue;
            let i = t.indexOf(term);
            while (i !== -1) {
                const leftOk = i === 0 || !isAlnum(t[i - 1]);
                const end = i + term.length;
                const rightOk = prefix || end >= t.length || !isAlnum(t[end]);
                if (leftOk && rightOk) return true;
                i = t.indexOf(term, i + 1);
            }
        }
        return false;
    };
    // Character-level port of models.is_upsell_any — ONE definition of what a
    // sales prompt looks like, shared with the Claude ranker's port and with
    // the Python mirror, not a third opinion.
    //
    // ⭐⭐ THE NOUNS ARE PLAN NAMES, NOT THE FAMILY WORD, and that is the
    // difference between a guard and a no-op. Claude sells with the family next
    // to the verb ("Upgrade to Opus"); Google sells with the PLAN next to it
    // ("Upgrade to Google AI Ultra"), and the model name, when the row carries
    // one at all, sits further along in the concatenated description. Keying
    // this on `fam` would ask for "upgrade" followed by "flash" inside the
    // window, which Google's copy does not produce — it would match nothing and
    // still read as shipped. The nouns come from policy for the same reason the
    // family and the reject terms do.
    //
    // Whitespace is collapsed HERE, over the SAME set models._collapse_ws uses
    // rather than this language's own \\s: Python calls \\x1c-\\x1f and \\x85
    // whitespace and JS does not, JS calls \\ufeff (a BOM, which does turn up in
    // page text) whitespace and Python does not, and the window below is
    // counted in CHARACTERS on the collapsed string. Regex-free boundaries for
    // the #913 reason the rest of this file states.
    const normU = s => (s || '').replace(/[\\s\\x1c-\\x1f\\x85\\ufeff]+/g, ' ').trim();
    const isUpsell = (raw) => {
        const s = normU(raw).toLowerCase();
        if (!s) return false;
        for (const rawNoun of (nouns || [])) {
            const n = normU(rawNoun).toLowerCase();
            if (!n) continue;
            for (const rawVerb of (verbs || [])) {
                const verb = String(rawVerb).toLowerCase();
                if (!verb) continue;
                let i = s.indexOf(verb);
                while (i !== -1) {
                    const end = i + verb.length;
                    const leftOk = i === 0 || !isAlnum(s[i - 1]);
                    const rightOk = end >= s.length || !isAlnum(s[end]);
                    if (leftOk && rightOk) {
                        const j = s.indexOf(n, end);
                        if (j !== -1 && j - end <= upsellWindow) return true;
                    }
                    i = s.indexOf(verb, i + 1);
                }
            }
        }
        return false;
    };
    // The dropdown TRIGGER names the current model too. With version-less rows
    // now acceptable, on a rename day (no numbered rows anywhere) the shortest
    // element containing the family word is plausibly the trigger itself —
    // clicking it just shuts the menu while we report a successful pick.
    const trig = (triggerText || '').replace(/\\s+/g, ' ').trim().toLowerCase();
    let bestEl = null, best = '', bestRank = null, bestLen = Infinity, bestAdv = false;
    const adverts = [];
    for (const el of items) {
        if (!el.offsetParent) continue;
        const t = (el.textContent || '').trim().toLowerCase();
        if (!t) continue;
        if (trig && t.replace(/\\s+/g, ' ') === trig) continue;   // never click the trigger
        // ⭐ SCORED BEFORE `rejected`, SKIPPED AFTER IT, and the split is the
        // point of shadow mode. Most of Google's sales copy names a plan whose
        // own name contains "pro", so the reject list already bins it — and if
        // adverts were only counted on rows that survived reject, the very
        // measurement this ships to collect would report near zero and be read
        // as "no adverts in this menu". Counting first records what the advert
        // rule WOULD have caught; the skip below still runs after reject so the
        // live ordering ("Flash-Lite" also contains "flash") is untouched.
        const adv = isUpsell(el.textContent || '');
        if (adv && adverts.length < 8) adverts.push(t.slice(0, 60));
        // Reject siblings FIRST (order matters — "Flash-Lite" also has "flash").
        if (rejected(t)) continue;
        // ⚠ WHILE `dropUpsell` IS FALSE THIS ROW IS STILL ELIGIBLE. That is
        // deliberate: the nouns above are unmeasured against a real Gemini
        // menu, this platform has no `free_family` to fall back to, and a guard
        // that empties the menu here does not produce an error — it leaves the
        // run on whatever the dropdown defaulted to, which on Gemini Pro is a
        // 1-2h Deep Research hang. `advertPick` below reports when the winner
        // WOULD have been dropped, which is the number that decides whether
        // this flips.
        if (dropUpsell && adv) continue;
        const v = flashVer(t);
        if (v === null && !famRe.test(t)) continue;
        let rank;
        if (pin != null && v !== null && Math.abs(v - pin) <= 0.001) {
            // ⭐ Exact known-good — outranks everything below, but as a RANK TIER,
            // never a `break`. `items` is a document-wide query returned in
            // document order, so the first element whose text carries the pinned
            // version is routinely a wrapper li/a around the row (or an earlier
            // page element naming that version). Clicking it does not change the
            // model, yet clicked:true is returned and the caller logs a successful
            // pick. Falling through applies the same shortest-text leaf preference
            // the rest of this ranker uses — the same fix as in _pick_opus_js.
            rank = [2, v];
        } else {
            if (pin != null || below != null) {
                // Step-back: only rows strictly older than what just failed. When a
                // pin was requested this is the FALLBACK for a pin that is no longer
                // on the menu — see the same rule in _pick_opus_js.
                const bound = below != null ? below : pin;
                if (v === null || v >= bound - 0.001) continue;
            }
            rank = v === null ? [0, 0] : [1, v];
        }
        if (bestEl === null || rank[0] > bestRank[0] || (rank[0] === bestRank[0] && rank[1] > bestRank[1])
                || (rank[0] === bestRank[0] && rank[1] === bestRank[1] && t.length < bestLen)) {
            bestEl = el; best = t.slice(0, 40); bestRank = rank; bestLen = t.length;
            bestAdv = adv;
        }
    }
    if (doClick && bestEl) bestEl.click();
    // `advertPick` is the ONE number that decides whether the rule flips on.
    // `adverts` is a bounded sample for reading the vendor's actual copy back
    // out of a log — 60 chars each so a row's plan phrase survives the slice,
    // 8 rows because that is already more than a Gemini model menu holds.
    return { pick: best, version: bestRank && bestRank[0] ? bestRank[1] : null,
             clicked: !!(doClick && bestEl),
             advertPick: !!(bestEl && bestAdv), adverts };
}"""


def _gemini_advert_rule() -> "tuple[list, bool]":
    """The advert nouns for the Gemini ranker, and whether to ACT on them.

    ⭐ A FUNCTION, not two lines inside `_gemini_select_flash_model`, because
    nothing can execute that coroutine without a live page — and "enforce a rule
    nobody has measured, on the one platform with no fallback family" is the
    single most expensive thing in this fix to get wrong. Inline, the only
    available pin would be reading its source, and this wave already recorded
    five mutants walking through exactly that kind of pin.

    ⛔ NO NOUNS MEANS NO RULE, in both halves of the answer. A platform with
    nothing configured must not end up enforcing an empty rule (which skips
    nothing but reads as guarded) nor inherit a noun from somewhere else."""
    nouns = _models_upsell_nouns("gemini")
    return nouns, bool(nouns) and not _models_upsell_shadow("gemini")


def _gemini_advert_lines(rank, *, live: bool, nouns) -> "list[tuple[str, str]]":
    """What to say about the ranker's advert scan. Returns (level, message) pairs.

    ⭐ A FUNCTION AND NOT AN INLINE BLOCK because `_gemini_select_flash_model`
    cannot be executed by a test — it needs a live page — and this wave already
    paid for that lesson twice: a decision written inline is pinned by reading
    its source, and mutation walks straight through such a pin. The caller now
    only logs what this returns.

    ⚠ SILENT WHEN THE RANKER DID NOT RUN. `rank` is `{}` after an eval error,
    and reporting "0 sales rows" for a menu that was never read would be the
    same class of untruth as the source count that said zero on our behalf. The
    scan reports a denominator only when there is one, and the eval error has
    its own line."""
    if not nouns:
        return []
    if not isinstance(rank, dict) or "adverts" not in rank:
        return []
    adverts = rank.get("adverts") or []
    lines: "list[tuple[str, str]]" = []
    mode = "enforced" if live else "shadow (not acted on)"
    if adverts:
        _sample = " | ".join(str(a) for a in adverts[:4])
        lines.append(("INFO",
                      f"[setup_gemini_dr] advert-scan ({mode}): {len(adverts)} row(s) in "
                      f"the model menu read as a sales prompt — {_sample}"))
    else:
        lines.append(("INFO",
                      f"[setup_gemini_dr] advert-scan ({mode}): no row in the model menu "
                      f"reads as a sales prompt"))
    if rank.get("advertPick"):
        if live:
            # Unreachable by construction — the ranker skips advert rows while
            # `dropUpsell` is true — so if it ever fires, the port and the flag
            # have come apart and the log is the only place that would show it.
            lines.append(("WARN",
                          "[setup_gemini_dr] advert-scan: the advert rule is ENFORCED yet "
                          "the clicked row still scores as a sales prompt — the ranker and "
                          "the flag disagree"))
        else:
            lines.append(("WARN",
                          "[setup_gemini_dr] advert-scan: the row this run CLICKED reads as "
                          "a sales prompt. The rule is in shadow, so the click stood — if "
                          "this run's model selection misbehaved, this is the reason"))
    return lines


async def _gemini_select_flash_model(page, pin_model=None, step_below=None) -> bool:
    """Pre-DR step: open the model dropdown and select the newest FLASH.

    Why the family is Flash and not something "better": Flash Deep Research
    completes cleanly and its done-state becomes detectable after the periodic
    refresh, whereas Gemini Pro Deep Research ran 1-2h and needed manual "is it
    done?" nudges to unstick (user-validated 2026-05-26). That family choice is
    deliberate; the VERSION inside it is not pinned at all — we always take the
    highest Flash the dropdown offers, so a release needs no code change.

    Approach: open the model button (data-test-id="bard-mode-menu-button"),
    click the highest Flash row (rejecting the Flash-Lite / Pro / Deep Think
    siblings named in the policy's `reject` list), then open the "Thinking level"
    submenu and click "Extended" — the pipeline wants Flash Extended, not the
    default "Standard". Menu-row text is title+description concatenated
    ("3.5 FlashAll-around help"), so the match avoids a trailing word boundary.
    Best-effort: if the dropdown rotated or no Flash is available, return False —
    the caller enables DR anyway. The Extended step is softer still: a miss only
    leaves the default thinking level (logged).

    Unlike Claude, this opens the dropdown on EVERY run, so the newest Flash
    reaches the account without any probe cadence.

    Returns True when a Flash row was selected (Extended is set best-effort
    within); False if the model couldn't be picked.
    """
    # Clear first — same reason as setup_claude_dr: this is a process-global and
    # the early-return paths below never write it, so a previous run's value
    # would be read as "the version that just failed" by the step-back path.
    _P2_PICKED_VERSION.pop("gemini", None)
    try:
        # Step 1: find the model dropdown button. Gemini's current UI uses
        # a button at the top of the chat header whose text is the current
        # model name ("3.5 Flash", "3.1 Pro", "Gemini 3.5 Flash", etc.). The
        # button usually has aria-haspopup="menu" or a chevron icon.
        # Common selectors across UI versions:
        #   - bard-mode-menu-button (legacy data-test-id)
        #   - button[aria-label*="model" i]
        #   - button[aria-haspopup="menu"] near the top of the page whose
        #     text contains "Gemini" / "3.5" / "Flash" / "Pro"
        opened = await page.evaluate("""() => {
            // No top-of-page guard: on the home-screen UI Gemini centers
            // the composer at ~30-50% of viewport, so the prior < 25%
            // position gate never matched the model button there (the
            // gate was right for sticky-header chat view, wrong for the
            // empty-chat landing). Precise selectors are model-button
            // specific, so we click them unconditionally; the text-
            // pattern fallback still uses a wide-but-bounded position
            // gate so an unrelated menu button (account chip) can't
            // accidentally match.
            const precise = document.querySelectorAll(
                'bard-mode-menu-button button, ' +
                'button[data-test-id="bard-mode-menu-button"], ' +
                'button[aria-label*="model" i], ' +
                'button[aria-label*="Switch model" i]'
            );
            for (const b of precise) {
                if (b.offsetParent) { b.click(); return true; }
            }
            // Fall back to text-pattern match across visible menu buttons.
            // Accept any version-number prefix (3.1 / 3.0 / 2.5) so the
            // probe still finds the dropdown if Google rotates the
            // model-name label between versions. Position gate widened
            // to top 95% so BOTH home-screen-centered composer (~50%
            // viewport) AND new-UI bottom-anchored composer (~85% on
            // tall viewports) qualify. The only thing this rules out is
            // a sub-footer banner.
            const inViewableArea = (b) => {
                const r = b.getBoundingClientRect();
                return r.top >= 0 && r.top < window.innerHeight * 0.95 && r.width > 0;
            };
            const buttons = document.querySelectorAll('button[aria-haspopup="menu"], button[aria-expanded]');
            for (const b of buttons) {
                if (!b.offsetParent || !inViewableArea(b)) continue;
                const t = (b.textContent || '').trim();
                if (/\\b(\\d\\.\\d|Gemini|Flash|Pro|Deep Think)\\b/i.test(t)) {
                    b.click(); return true;
                }
            }
            return false;
        }""")
        if not opened:
            log("[setup_gemini_dr] model-pick: dropdown button not found — skipping Flash selection", "INFO")
            return False
        await asyncio.sleep(0.8)

        # Pick + click the highest Flash the dropdown offers. Family and reject
        # list come from policy; there is no version literal on either side, so
        # the day a newer Flash ships this picks it with no code change. The old
        # `legacy` shadow-comparison against a frozen /3.5 flash/ match is gone —
        # it was log-only, and it was itself a pinned version.
        _gm_family = p2_family("gemini") or "flash"
        _gm_reject = reject_terms("gemini")
        _gm_nouns, _gm_advert_live = _gemini_advert_rule()
        # The thinking-level word, from policy rather than four separate literals
        # in the page.evaluate strings below. The advisory at the end of the P2
        # leg ALREADY reads this key, so while the selectors hardcoded 'extended'
        # a rename would have made the advisory report thinking as missing while
        # every selector kept hunting the old word — the two halves disagreeing
        # about what they are even looking for. Restricted to letters/digits/
        # spaces for the same reason p2_family is: it is interpolated into page
        # JS, and the overlay may supply any string.
        # ⛔ Must be a STRING. The overlay schema admits `thinking` as bool OR str
        # (the Claude entry uses it as a bool flag), so `{"thinking": true}` is a
        # perfectly valid overlay — and `str(True).lower()` is "true", which sails
        # through a character-class check. Every selector below would then hunt
        # the word "true". Before this wave that key only fed an advisory; it now
        # steers four selectors, so the type has to be checked, not just the
        # characters.
        _gm_think_raw = (p2_labels("gemini") or {}).get("thinking")
        _gm_think = (_gm_think_raw.strip().lower()
                     if isinstance(_gm_think_raw, str) else "")
        if not re.fullmatch(r"[a-z0-9 ]+", _gm_think or ""):
            _gm_think = "extended"     # the code default; see P2_MODEL_POLICY
        # The trigger's own text, so the ranker can refuse to click it. Read
        # before the menu opened would be ideal, but the dropdown is already
        # open here — the trigger stays outside [role=menu], which is how we
        # tell them apart.
        try:
            _gm_trigger = await page.evaluate("""(fam) => {
                const famRe = new RegExp(fam, 'i');
                const b = [...document.querySelectorAll('button, [role="button"]')]
                    .filter(x => x.offsetParent
                                 && !x.closest('[role="menu"], [role="listbox"], [role="dialog"]')
                                 && famRe.test(x.textContent || ''))
                    .sort((a, z) => (a.textContent || '').length - (z.textContent || '').length)[0];
                return b ? (b.textContent || '').replace(/\\s+/g, ' ').trim() : '';
            }""", _gm_family)
        except Exception:
            _gm_trigger = ""
        try:
            _rank = await page.evaluate(_GEMINI_FLASH_RANK_JS, {
                "below": step_below, "doClick": True, "pin": pin_model,
                "fam": _gm_family, "reject": _gm_reject, "triggerText": _gm_trigger,
                "nouns": _gm_nouns, "verbs": list(UPSELL_VERBS),
                "upsellWindow": UPSELL_WINDOW, "dropUpsell": _gm_advert_live})
        except Exception as _re:
            log(f"[setup_gemini_dr] model-pick: ranker eval errored ({_re})", "WARN")
            _rank = {}
        for _al in _gemini_advert_lines(_rank, live=_gm_advert_live,
                                        nouns=_gm_nouns):
            log(_al[1], _al[0])
        picked = ((_rank or {}).get("pick") or "") if (_rank or {}).get("clicked") else ""
        if not picked:
            log(f"[setup_gemini_dr] model-pick: no '{_gm_family}' row found in the dropdown "
                f"(pin={pin_model!r} below={step_below!r}) — closing menu", "WARN")
            # Best-effort: close the open dropdown so the next step's + button
            # isn't sitting under an overlay.
            try:
                await page.keyboard.press("Escape")
            except Exception:
                pass
            return False
        await asyncio.sleep(0.6)
        log(f"[setup_gemini_dr] model-pick OK: clicked the highest '{_gm_family}' offered — "
            f"{picked!r} (v{(_rank or {}).get('version')})")
        # Record the selected Flash version for on-the-fly known-good learning.
        _P2_PICKED_VERSION["gemini"] = (_rank or {}).get("version")

        # Step 3: set Thinking level = Extended (the pipeline wants "Flash
        # Extended", not the default "Standard"). The model menu carries a
        # "Thinking level" submenu trigger; clicking it expands a Standard /
        # Extended choice (click-driven, per captured UI). The menu stays open
        # after the model pick, but if it closed we reopen via the mode button.
        # Best-effort: a miss leaves the default level (Standard) and is logged,
        # not fatal.
        #
        # #919 (2026-07-08, user screenshot "Gemini didn't select Extended
        # flash"): the 'Thinking level' trigger stopped being findable
        # overnight (last hit 07-07 21:55, misses from 07-08 02:02) while the
        # Flash row itself was unchanged — a menu-structure rotation, not a
        # model rename. Hardened: (a) trigger match broadened to any item
        # STARTING with 'thinking'; (b) a DIRECT 'Extended…' item inside the
        # open menu counts (covers an Extended-thinking toggle row / an
        # 'Extended Flash' sibling row — both drifts Google has shipped
        # elsewhere); (c) the reopen-retry also HOVERs the picked Flash row
        # first (row-nested submenus only render on hover); (d) every miss
        # dumps the visible menu rows so the NEXT drift is diagnosable from
        # backend.log alone (instrument-with-logs).
        _reopen_js = """() => {
            const b = document.querySelector(
                'button[data-test-id="bard-mode-menu-button"], bard-mode-menu-button button');
            if (b && b.offsetParent) { b.click(); return true; }
            return false;
        }"""
        _click_tl_js = """() => {
            const items = document.querySelectorAll(
                '[role="menuitem"], [role="menuitemradio"], [role="option"], button, a, li');
            for (const el of items) {
                if (!el.offsetParent) continue;
                const t = (el.textContent || '').trim().toLowerCase();
                if (t.includes('thinking level') ||
                        (t.startsWith('thinking') && t.length < 60)) {
                    try { el.dispatchEvent(new MouseEvent('mouseover', {bubbles:true})); } catch(e){}
                    try { el.dispatchEvent(new MouseEvent('pointerover', {bubbles:true})); } catch(e){}
                    el.click();
                    return true;
                }
            }
            return false;
        }"""
        # Direct '<thinking word>…' item INSIDE an open overlay menu (never bare
        # page text — the closest() guard pins it to Angular Material's overlay).
        # This is the branch that carries the CAPTURED menu: 'Extended thinking
        # Complex problem solving' is a peer row of the model rows, so no
        # 'Thinking level' submenu exists to open and _click_tl_js correctly
        # misses. ⭐ The word comes from policy, not a literal — the advisory at
        # the end of the P2 leg already reads P2_MODEL_POLICY['gemini']
        # ['thinking'], so a rename used to make the advisory report thinking as
        # missing while every selector here still hunted the old word.
        # Boundary-checked with string ops rather than a RegExp: `\\b` inside a
        # non-raw Python string is the #913 literal-backspace trap, and the word
        # is interpolated, so a built regex would also be an injection site.
        _click_direct_ext_js = """(think) => { // directExtended
            const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
            // ⚠ startsWith OR a both-boundaries match, exactly as the frozen
            // /\\bextended\\b/ pair did. Menu rows are title+description
            // CONCATENATED ('Extended thinkingComplex problem solving'), so
            // there is NO right boundary after the word on the row we want —
            // a boundaries-only test would reject the very row this selects,
            // while startsWith alone would miss a 'Flash Extended' sibling.
            const isWanted = (t, w) => {
                if (!w) return false;
                if (t.startsWith(w)) return true;
                let i = t.indexOf(w);
                while (i !== -1) {
                    const end = i + w.length;
                    if ((i === 0 || !isAlnum(t[i - 1])) && (end >= t.length || !isAlnum(t[end]))) return true;
                    i = t.indexOf(w, i + 1);
                }
                return false;
            };
            const items = document.querySelectorAll(
                '[role="menuitem"], [role="menuitemradio"], ' +
                '[role="menuitemcheckbox"], [role="option"], button, li');
            for (const el of items) {
                if (!el.offsetParent) continue;
                if (!el.closest('[role="menu"], [class*="menu-panel" i], .cdk-overlay-container')) continue;
                const t = (el.textContent || '').trim().toLowerCase();
                if (t.startsWith('standard') || t.length >= 60) continue;
                if (isWanted(t, think)) {
                    el.click();
                    return t.slice(0, 40);
                }
            }
            return '';
        }"""
        # The SUBMENU choice, once a 'Thinking level' trigger has opened one:
        # pick the <thinking word> radio, never 'Standard'. Unscoped by design —
        # the submenu is not always inside the overlay container the direct
        # variant requires. ⭐ ONE definition: this was previously two
        # byte-similar copies (an inline evaluate for the first attempt and this
        # constant for the retries) that had to be kept in step by hand.
        _click_ext_radio_js = """(think) => { // extendedRadio
            const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
            // ⚠ startsWith OR a both-boundaries match, exactly as the frozen
            // /\\bextended\\b/ pair did. Menu rows are title+description
            // CONCATENATED ('Extended thinkingComplex problem solving'), so
            // there is NO right boundary after the word on the row we want —
            // a boundaries-only test would reject the very row this selects,
            // while startsWith alone would miss a 'Flash Extended' sibling.
            const isWanted = (t, w) => {
                if (!w) return false;
                if (t.startsWith(w)) return true;
                let i = t.indexOf(w);
                while (i !== -1) {
                    const end = i + w.length;
                    if ((i === 0 || !isAlnum(t[i - 1])) && (end >= t.length || !isAlnum(t[end]))) return true;
                    i = t.indexOf(w, i + 1);
                }
                return false;
            };
            for (const el of document.querySelectorAll(
                    '[role="menuitem"], [role="menuitemradio"], [role="option"], button, a, li')) {
                if (!el.offsetParent) continue;
                const t = (el.textContent || '').trim().toLowerCase();
                if (t.startsWith('standard')) continue;
                if (isWanted(t, think)) { el.click(); return t.slice(0, 40); }
            }
            return '';
        }"""
        # ⭐ NO FAMILY OR REJECT LITERAL. This used to hunt /\\bflash\\b/ while
        # excluding /lite|\\bpro\\b|deep think/ — a second, frozen copy of the
        # model policy living in a page.evaluate string, which is exactly what
        # the family-only rule exists to prevent: a rename would leave the
        # ranker picking the right row and this hovering nothing. It now hovers
        # THE ROW THE RANKER JUST PICKED, passed in by text, so there is one
        # decision about which model matters and this simply follows it.
        # Shortest match wins for the same reason it does in the ranker: a
        # wrapper's textContent also starts with the row's text.
        _hover_picked_row_js = """(pickText) => { // hoverPickedRow
            const want = (pickText || '').trim().toLowerCase();
            if (!want) return '';
            let bestEl = null, bestText = '';
            for (const el of document.querySelectorAll(
                    '[role="menuitem"], [role="menuitemradio"], [role="option"], li')) {
                if (!el.offsetParent) continue;
                const t = (el.textContent || '').trim().toLowerCase();
                if (!t || !t.startsWith(want)) continue;
                if (bestEl === null || t.length < bestText.length) { bestEl = el; bestText = t; }
            }
            if (!bestEl) return '';
            try { bestEl.dispatchEvent(new MouseEvent('mouseover', {bubbles:true})); } catch(e){}
            try { bestEl.dispatchEvent(new MouseEvent('pointerover', {bubbles:true})); } catch(e){}
            return bestText.slice(0, 40);
        }"""
        _menu_dump_js = """() => { // menuDump
            const rows = [];
            for (const el of document.querySelectorAll(
                    '[role="menuitem"], [role="menuitemradio"], ' +
                    '[role="menuitemcheckbox"], [role="option"], ' +
                    '.cdk-overlay-container button, .cdk-overlay-container li')) {
                if (!el.offsetParent || rows.length >= 20) continue;
                const t = (el.textContent || '').trim();
                if (!t) continue;
                rows.push({ t: t.slice(0, 60),
                            hp: el.getAttribute('aria-haspopup') || '',
                            ex: el.getAttribute('aria-expanded') || '',
                            ck: el.getAttribute('aria-checked') || '' });
            }
            return { openMenus: document.querySelectorAll('[role="menu"]').length,
                     rows };
        }"""

        async def _dump_thinking_menu(tag):
            try:
                snap = await page.evaluate(_menu_dump_js)
                line = json.dumps(snap, ensure_ascii=True)[:1200]
            except Exception as _de:
                line = f"dump-failed: {_de}"
            log(f"[setup_gemini_dr] thinking-menu snapshot ({tag}): {line}", "DEBUG")

        _gem_ext_confirmed = False  # Phoenix: advisory extended-thinking confirmation
        tl_opened = await page.evaluate(_click_tl_js)
        if not tl_opened:
            _direct = await page.evaluate(_click_direct_ext_js, _gm_think)
            if _direct:
                _gem_ext_confirmed = True
                log(f"[setup_gemini_dr] model-pick: direct {_gm_think} item clicked "
                    f"('{_direct}') — no Thinking-level submenu on this menu variant")
            else:
                await _dump_thinking_menu("first-miss")
                await page.evaluate(_reopen_js)
                await asyncio.sleep(0.6)
                _hovered = await page.evaluate(_hover_picked_row_js, picked)
                if _hovered:
                    await asyncio.sleep(0.5)
                tl_opened = await page.evaluate(_click_tl_js)
                if not tl_opened:
                    _direct = await page.evaluate(_click_direct_ext_js, _gm_think)
                    if _direct:
                        _gem_ext_confirmed = True
                        log(f"[setup_gemini_dr] model-pick: direct {_gm_think} item "
                            f"clicked after reopen+hover ('{_direct}')")
        if tl_opened:
            await asyncio.sleep(0.6)
            ext_picked = await page.evaluate(_click_ext_radio_js, _gm_think)
            await asyncio.sleep(0.5)
            if ext_picked:
                _gem_ext_confirmed = True
                log(f"[setup_gemini_dr] model-pick: Thinking level -> {_gm_think} ('{ext_picked}')")
            else:
                await _dump_thinking_menu("extended-option-miss")
                log(f"[setup_gemini_dr] model-pick: '{_gm_think}' option not found — "
                    "leaving default thinking level", "WARN")
        elif not _gem_ext_confirmed:
            await _dump_thinking_menu("final-miss")
            log("[setup_gemini_dr] model-pick: 'Thinking level' submenu not found — leaving default thinking level", "WARN")

        # ── Verify Extended STUCK, and RETRY until it does ──────────────────
        # The pick above can report a click ('direct Extended item clicked')
        # while the mode button stays 'Flash': the clicked row was a
        # hover-reveal PARENT, not the committed radio, so Extended never took.
        # Live 2026-07-13: three consecutive runs logged "trigger now reads
        # 'Flash'" immediately after "direct Extended item clicked", and Gemini
        # ran Standard-thinking DR instead of Flash Extended. The AUTHORITATIVE
        # signal is the mode button reading 'Extended' — trust THAT, never the
        # click's return value. If it isn't Extended, reopen the model menu,
        # re-hover the Flash row (row-nested submenus only render on hover) and
        # re-click Extended, up to _EXT_TRIES times, re-reading each time. The
        # user requirement is hard ("It must be Flash Extended"), so we retry
        # aggressively; a miss after every try is logged honestly (DR still
        # functions on Standard thinking — this is never fatal to the agent).
        _read_mode_js = """() => {
            const b = document.querySelector(
                'button[data-test-id="bard-mode-menu-button"], bard-mode-menu-button button');
            return b ? ((b.getAttribute('aria-label') || '') + ' ' + (b.textContent || '')).trim() : '';
        }"""

        async def _mode_shows_extended():
            try:
                _m = await page.evaluate(_read_mode_js)
            except Exception:
                _m = ""
            return (_gm_think in (_m or "").lower()), (_m or "")

        _ext_ok, _mode_now = await _mode_shows_extended()
        if _ext_ok:
            _gem_ext_confirmed = True
            log(f"[setup_gemini_dr] model-pick verify: mode button shows Extended ('{_mode_now[:40]}')")
        else:
            try:
                _EXT_TRIES = int(os.environ.get("DG_GEMINI_EXTENDED_TRIES", "3"))
            except ValueError:
                _EXT_TRIES = 3
            for _et in range(1, _EXT_TRIES + 1):
                log(f"[setup_gemini_dr] model-pick verify: Extended NOT stuck "
                    f"(mode reads '{_mode_now[:40]}') — retry {_et}/{_EXT_TRIES}", "WARN")
                # Clean-slate the menu (an open leftover would make _reopen_js
                # TOGGLE it shut), reopen, hover the row the ranker picked so a
                # row-nested Thinking-level submenu renders, then click the
                # thinking row (submenu radio first, direct row as fallback).
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.3)
                    await page.evaluate(_reopen_js)
                    await asyncio.sleep(0.6)
                    await page.evaluate(_hover_picked_row_js, picked)
                    await asyncio.sleep(0.5)
                    if await page.evaluate(_click_tl_js):
                        await asyncio.sleep(0.6)
                        await page.evaluate(_click_ext_radio_js, _gm_think)
                    else:
                        await page.evaluate(_click_direct_ext_js, _gm_think)
                    await asyncio.sleep(0.6)
                except Exception as _ee:
                    log(f"[setup_gemini_dr] model-pick verify: retry {_et} click errored ({_ee})", "WARN")
                _ext_ok, _mode_now = await _mode_shows_extended()
                if _ext_ok:
                    _gem_ext_confirmed = True
                    log(f"[setup_gemini_dr] model-pick verify: mode button shows Extended "
                        f"after retry {_et} ('{_mode_now[:40]}')")
                    break
            if not _ext_ok:
                await _dump_thinking_menu("extended-retry-exhausted")
                log(f"[setup_gemini_dr] model-pick verify: Extended still NOT selected after "
                    f"{_EXT_TRIES} retries (mode reads '{_mode_now[:40]}') — proceeding on "
                    "the default thinking level (DR still runs; NOT Flash Extended)", "WARN")
        # Phoenix model_refresh — record advisory extended-thinking state for the
        # caller's soft notice (never gates _gemini_select_flash_model's return).
        # #951 review: _gem_ext_confirmed was seeded True from the (unreliable)
        # click return in the initial pick block and never reset when the
        # AUTHORITATIVE mode-button verify above proved Extended didn't stick —
        # so a definitive Extended FAILURE was recorded as a confirmed success,
        # masking the exact regression this verify+retry block exists to catch.
        # Bind it to the final verified state instead of the click.
        _gem_ext_confirmed = _ext_ok
        _P2_THINKING_STATE["gemini"] = {"thinking": _gem_ext_confirmed}
        try:
            await page.keyboard.press("Escape")
        except Exception:
            pass
        # Phoenix model_refresh — read-only post-pick predicate: confirm the
        # model-selector TRIGGER now reflects a Flash model (the pick used to
        # trust the click and never re-read → a silent-wrong-model gap). Runs
        # AFTER the menu is closed; must NOT reopen it. Observability only — it
        # does not change setup_gemini_dr's return (DR-placeholder-gated upstream).
        try:
            _trig = await page.evaluate("""() => {
                const b = document.querySelector(
                    'button[data-test-id="bard-mode-menu-button"], bard-mode-menu-button button');
                return b ? (b.textContent || '').trim() : '';
            }""")
            _trig_lc = (_trig or "").lower()
            if _gm_think in _trig_lc:
                log(f"[setup_gemini_dr] model-pick verify: trigger now reads '{_trig[:40]}' "
                    f"({_gm_family} {_gm_think} ✓)")
            elif _gm_family in _trig_lc:
                log(f"[setup_gemini_dr] model-pick verify: trigger reads '{_trig[:40]}' "
                    f"({_gm_family} selected, {_gm_think} NOT active)", "WARN")
            else:
                log(f"[setup_gemini_dr] model-pick verify: trigger does NOT show {_gm_family} "
                    f"(reads '{_trig[:40]}') — pick may not have taken", "WARN")
        except Exception:
            pass
        return True
    except Exception as e:
        log(f"[setup_gemini_dr] model-pick exception: {e}", "WARN")
        return False


# #709 (2026-05-29) — single source of truth for "is Gemini Deep Research
# ACTIVE?". Shared by setup_gemini_dr's verification AND the pre-send
# ensure_deep_mode_active check so both agree exactly. The authoritative signal
# is the COMPOSER PLACEHOLDER (DR ON → "What do you want to research?"; chat →
# "Ask Gemini") — the DR pill's class (mat-tonal-button…) carries NO reliable
# pressed marker, so a pressed-class-only check false-negatived an ACTIVE pill
# last E2E and the CUA fallback then toggled the working DR OFF. Anchored to the
# composer (rich-textarea / lowest contenteditable) to avoid reading a stale
# dialog placeholder. Returns placeholderResearch (active), placeholderChat
# (confidently off), pressed (secondary), + pill diagnostics for the dump.
_GEMINI_DR_STATE_JS = """() => {
    const norm = s => (s || '').replace(/\\s+/g, ' ').trim().toLowerCase();
    let ce = document.querySelector('rich-textarea div[contenteditable="true"]')
          || document.querySelector('rich-textarea')
          || null;
    if (!ce) {
        const cands = [...document.querySelectorAll(
            'div[contenteditable="true"][data-placeholder], textarea[placeholder]')]
            .filter(e => e.offsetParent);
        if (cands.length) {
            cands.sort((a, b) => b.getBoundingClientRect().top - a.getBoundingClientRect().top);
            ce = cands[0];
        }
    }
    let placeholder = '';
    if (ce) placeholder = norm(ce.getAttribute('data-placeholder')
        || ce.getAttribute('placeholder') || ce.getAttribute('aria-label'));
    const placeholderResearch = placeholder.includes('research') ||
        placeholder.includes('what do you want to');
    const placeholderChat = placeholder.includes('ask gemini');
    let pill = null;
    for (const p of document.querySelectorAll('button, [role="button"]')) {
        if (!p.offsetParent) continue;
        if (norm(p.textContent) === 'deep research') { pill = p; break; }
    }
    let pillText = '', pillCls = '', pillAria = '';
    if (pill) {
        pillText = (pill.textContent || '').trim().slice(0, 40);
        pillCls = (pill.className || '').toString().toLowerCase();
        pillAria = (pill.getAttribute('aria-label') || '');
    }
    const pressed = pill ? (
        pill.getAttribute('aria-pressed') === 'true' ||
        pill.getAttribute('aria-selected') === 'true' ||
        pill.getAttribute('data-active') === 'true' ||
        pillCls.includes('--selected') || pillCls.includes('selected') ||
        pillCls.includes('active') || pillCls.includes('--filled')) : false;
    return { pillVisible: !!pill, pressed, placeholderResearch, placeholderChat,
             placeholder: placeholder.slice(0, 60),
             pillText, pillCls: pillCls.slice(0, 100), pillAria };
}"""


# ⭐ Claude's P2 mode state — "is the family selected AND the Research tool
# on?" — as ONE module constant with TWO callers: the pre-send mode check in
# `ensure_deep_mode_active` and the setup ladder's outcome probe.
#
# Hoisted out of the pre-send check rather than re-typed for the probe. Two
# copies of a detector is exactly how the ChatGPT Step-3 verify drifted away
# from the shared composer detector and started failing runs that had actually
# succeeded — it ended up demanding an exact pill label and a placeholder word
# that the real Deep-Research placeholder does not contain.
#
# ⚠ DOCUMENTED BRITTLE. claude.ai renders the Research pill without the
# attributes `researchOn` keys on, so a True here is trustworthy and a False is
# NOT — which is why the ladder probe maps a False to `unknown`, never to `off`.
_CLAUDE_MODE_STATE_JS = """(P) => {
    const fam = P.fam;
    const txt = (document.body.innerText || '').toLowerCase();
    // 2026-05-28: the UI dropped the word "Extended" — the model
    // button now reads "Opus 5 Max" and Adaptive shows as a
    // "Thinking" toggle behind the popover. A body-wide "extended"
    // scan was therefore ALWAYS false → a needless re-activation on
    // EVERY Claude send (backend.log 49728). Read the model-selector
    // button instead: the family showing == the high-tier model is
    // active. (Adaptive/effort live behind the closed popover and are
    // confirmed by the CUA validate layer, not gated here.)
    //
    // ⭐ FAMILY, NOT A VERSION FLOOR. This used to demand
    // `verOf(trigger) >= floor`. Gating a PRE-SEND check on a version
    // number means a platform rollback, an A-B bucket, or a
    // version-less label reads as "mode regressed" and triggers a
    // full re-setup — with the model popover opening seconds before
    // the brief is sent. The family word is the durable signal.
    const famRe = new RegExp(fam, 'i');
    const upsellRe = /(upgrade|subscribe|unlock|try |get )/i;
    // Read the composer's model-selector TRIGGER button only —
    // EXCLUDE any option rendered inside an open dropdown/menu (a
    // stale menu item while a different model is current would
    // otherwise false-positive), and exclude upsell chips, which name
    // the family without being evidence it is selected. The trigger
    // lives outside any [role=menu]/[role=listbox]/[role=dialog].
    // getClientRects() — the version check that used to sit here made
    // an off-screen or hidden element harmless (it needed a number
    // too); the family word alone does not, so a hidden marketing
    // chip on a Sonnet account would now pass this gate.
    const btns = [...document.querySelectorAll('button, [role="button"]')]
        .filter(b => b.getClientRects().length > 0
                     && !b.closest('[role="menu"], [role="listbox"], [role="dialog"]'));
    // ⭐ 2026-08-17 — KEEP THE WINNING BUTTON, don't just answer yes/no. The
    // trigger's own label carries BOTH halves ("Model: Opus 5 Max"), so the
    // effort is knowable from the same element that answers the family — and
    // reading it anywhere else is wrong: this account's PLAN CHIP also says
    // "Max", so a page-wide scan reports effort-is-set on every page.
    // The captured test id is preferred where present; the text scan is the
    // fallback, so an older layout answers exactly as it did before.
    let trigger = null;
    for (const b of btns) {
        if (b.getAttribute('data-testid') === P.trigTestid) { trigger = b; break; }
    }
    if (!trigger) {
        trigger = btns.find(b => { const t = b.textContent || '';
                                   return famRe.test(t) && !upsellRe.test(t); });
    } else {
        // An id is a name, not evidence of the family. Still demand the word.
        const t = (trigger.getAttribute('aria-label') || '') + ' ' + (trigger.textContent || '');
        if (!famRe.test(t) || upsellRe.test(t)) trigger = null;
    }
    const hasExtended = !!trigger;
    // ⚠ REPORTED, NOT GATED HERE. Two callers read this detector and they want
    // different policies: the setup LADDER must descend when the effort is
    // unconfirmed, while the PRE-SEND check must not — gating a pre-send on a
    // quality knob re-runs the entire Claude setup, with the model popover
    // opening seconds before the brief is submitted. One detector, two policies;
    // a second detector is how the two drifted the first time.
    let effortOk = false;
    const ew = String(P.effortWord || '').toLowerCase();
    if (trigger && ew) {
        const label = (trigger.getAttribute('aria-label') || '') + ' '
                    + (trigger.textContent || '');
        // ⚠ `ew` IS ALREADY KNOWN NON-EMPTY — that is what the `&& ew` above is
        // for, and it is the whole guard. It matters because this trigger's text
        // ENDS IN AN ICON GLYPH (the capture shows a chevron span inside the
        // button, and icon fonts render into the Unicode private-use area), so a
        // trailing non-alphanumeric makes `split` emit an empty token — which
        // `indexOf('')` would find. An empty effort word would then read as a SET
        // tier, which is a false confirmation and the one direction this term must
        // never fail in.
        //
        // ⛔ A `.filter(Boolean)` here was tried and REMOVED. It is a second guard
        // against the same thing, so neither could be killed by mutation while the
        // other stood — and this file's own rule applies: a line that cannot change
        // an answer gets read as load-bearing by the next person and tested by
        // nobody. One guard, with a test that fails if it goes.
        effortOk = label.toLowerCase().split(/[^a-z0-9.]+/).indexOf(ew) !== -1;
    }
    // Research tool shows as a magnifying-glass icon / label near composer.
    const researchOn = Array.from(document.querySelectorAll('button, [role="button"]'))
        .some(b => {
            const t = (b.textContent || '').toLowerCase();
            const a = (b.getAttribute('aria-label') || '').toLowerCase();
            return (t.includes('research') || a.includes('research')) &&
                   (b.getAttribute('aria-pressed') === 'true' ||
                    b.getAttribute('data-state') === 'on' ||
                    b.classList.contains('active') ||
                    b.classList.contains('selected'));
        });
    return { hasExtended, researchOn, effortOk };
}"""


# ⭐⭐ Claude's composer test ids, captured live 2026-08-17. The most durable hooks
# either platform gives us: an exact name for the control AND one for every option
# under it. They are tried first and the existing text searches remain as the
# fallback, so an older layout is unaffected.
_CLAUDE_MODEL_TRIGGER_TESTID = "model-selector-dropdown"
_CLAUDE_EFFORT_TRIGGER_TESTID = "effort-menu-trigger"


def _claude_effort_option_testid(effort: str) -> str:
    """The option row's test id for a policy effort word.

    ⚠ `xhigh`, not `extra`. The captured ids are `effort-option-low|medium|high|
    xhigh|max` while the row LABELS read `Low / Medium / High / Extra / Max` — the
    id and the visible word disagree for exactly one rung, and it is the rung
    directly below the one we ask for. A caller that derived the id from the label
    would silently address nothing on the only step where being one rung out
    matters. Unknown words map to "" so the caller falls through to its text
    search rather than addressing a test id that does not exist.
    """
    word = (effort or "").strip().lower()
    known = {"low": "low", "medium": "medium", "high": "high",
             "extra": "xhigh", "extra high": "xhigh", "xhigh": "xhigh",
             "max": "max"}
    slug = known.get(word)
    return f"effort-option-{slug}" if slug else ""


def _claude_effort_is_set(*, marked: bool, already: bool,
                          pressed: bool, checked: bool) -> bool:
    """Was Claude's effort tier ACTUALLY set? The four readings, one verdict.

    ⭐ A pure function because the alternative did not survive mutation. The call
    site used to clear a flag inside two nested `if not …:` branches, and a mutant
    that turned the verification into `if False:` left the whole suite green — the
    tests could see the read was mentioned, not that its answer decided anything.
    Here the answer IS the return value, so a missing term is a wrong value.

      * `marked`   — a row naming the wanted tier was found at all.
      * `already`  — it was the selected one before we touched it. Cost-free and
                     correct; nothing is pressed and nothing needs verifying.
      * `pressed`  — a real, trusted press landed.
      * `checked`  — and the row then READ as selected.

    ⛔ `pressed` alone is never enough. "The click did not throw" as evidence of a
    changed page is the equivalence that produced nine "'Max' not found" WARNs
    against one success, and a report of a set tier from a page that had not moved.
    """
    if not marked:
        return False
    if already:
        return True
    return bool(pressed and checked)


def _claude_validator_effort_ok(thinking_state) -> bool:
    """Should the CUA validator be told the effort tier is already set?

    Extracted from its call site so the POLARITY is testable. Inline it sat in a
    900-line async function nothing in the suite executes, which is the shape
    that has repeatedly let an inverted gate ship green.

    ⭐ DEFAULTS TO TRUE — "assume it is fine". A platform that records nothing,
    or a validate call arriving before any setup ran, then gets today's cheap
    read-only pass. Defaulting the other way would send the validator into the
    model popover on every run of every platform to buy nothing, and reopen the
    "the model selector opens twice" report.
    """
    return bool((thinking_state or {}).get("effort", True))


# Re-open the model popover with a REAL press on the test-id'd trigger, and
# verify from the trigger's own `aria-expanded` that it actually opened.
_CLAUDE_MARK_MODEL_TRIGGER_JS = r"""(P) => {
    for (const el of document.querySelectorAll('[' + P.attr + ']')) {
        el.removeAttribute(P.attr);
    }
    for (const el of document.querySelectorAll('[data-testid="' + P.testid + '"]')) {
        if (!el.getClientRects().length) continue;
        el.setAttribute(P.attr, P.value);
        return { marked: true, expanded: el.getAttribute('aria-expanded'),
                 label: (el.getAttribute('aria-label') || '').slice(0, 60) };
    }
    return { marked: false };
}"""

# Did the effort row actually become the selected one? Read by test id when the
# platform offers it, else by the row's own text with the icon-font private-use
# codepoints stripped — the glyphs that defeated an exact text match nine runs out
# of ten ride on the SELECTED row, which is precisely the row this reads.
_CLAUDE_EFFORT_CHECKED_JS = r"""(P) => {
    const norm = s => (s || '')
        .replace(/[\ue000-\uf8ff]/g, ' ')
        .replace(/\s+/g, ' ').trim().toLowerCase();
    const isOn = el => el.getAttribute('aria-checked') === 'true' ||
                       el.dataset.state === 'checked' || el.dataset.state === 'on';
    if (P.optTestid) {
        const el = document.querySelector('[data-testid="' + P.optTestid + '"]');
        if (el) return { found: true, checked: isOn(el), via: 'testid' };
    }
    // The DEFAULT rung renders as e.g. 'HighDefault', so an exact match alone
    // cannot read it back. Same tolerance the picker uses to choose the row —
    // a verification that cannot see what the picker pressed is worse than no
    // verification, because it reports a correct press as a failure.
    const want = String(P.word || '').toLowerCase();
    for (const el of document.querySelectorAll(
            '[role="menuitemradio"], [role="menuitem"], [role="option"]')) {
        if (!el.getClientRects().length) continue;
        const t = norm(el.textContent);
        if (!want || (t !== want && t !== want + 'default')) continue;
        return { found: true, checked: isOn(el), via: 'text' };
    }
    return { found: false, checked: false, via: '' };
}"""

_CLAUDE_TRIGGER_EXPANDED_JS = r"""(P) => {
    const el = document.querySelector('[data-testid="' + P.testid + '"]');
    if (!el) return { found: false };
    return { found: true, expanded: el.getAttribute('aria-expanded') === 'true',
             label: (el.getAttribute('aria-label') || '').slice(0, 60) };
}"""

# ⭐⭐ 2026-08-17 — IS THE EFFORT SUBMENU UP? Asked of the OVERLAYS, not the page.
#
# The probe this replaces collected every short visible row in the DOCUMENT, capped
# the list at 20, and declared the submenu mounted only if one of those 20 read like
# an effort rung. Claude's submenu is a portalled popper appended at the END of
# `<body>`, so it is last in document order — and the sidebar ("new", "projects",
# "artifacts", "scheduled", "customize", "pinned", plus icon-only rows) fills the cap
# long before the walk reaches it. The 2026-08-17 run proved it: the gate reported
# "no submenu mounted" while its own diagnostic listed the submenu, five rows,
# Low/Medium/HighDefault/Extra/Max. Effort was then left at the model's default and
# the run reported the tier as unconfirmed.
#
# ⛔ A bigger cap would not have fixed it — document order is the defect, and the
# sink is what needs guarding. This asks each visible overlay separately, so no
# amount of sidebar can crowd the answer out. Same scoping rule Step 1C' already
# uses to PICK the row: the submenu is the visible menu that does NOT contain the
# Effort trigger; the parent popover carries its own 'EffortMax' row.
_CLAUDE_EFFORT_SUBMENU_JS = r"""(P) => {
    // Icon-font ligatures live in the private-use area and are invisible in a
    // screenshot but present in text — strip them before comparing, exactly as
    // the row picker does.
    const norm = s => (s || '')
        .replace(/[\ue000-\uf8ff]/g, ' ')
        .replace(/\s+/g, ' ').trim().toLowerCase();
    const RUNGS = ['low', 'medium', 'high', 'extra', 'max', 'xhigh'];
    // 'HighDefault' is a real captured label — the default rung carries a suffix.
    const isRung = t => RUNGS.indexOf(t) !== -1 ||
                        RUNGS.some(r => t === r + 'default');
    const out = {overlays: []};
    const seen = new Set();
    for (const c of document.querySelectorAll(
            '[role="menu"], [data-radix-menu-content], '
            + '[data-radix-popper-content-wrapper]')) {
        if (!c.getClientRects().length) continue;
        if (seen.has(c)) continue;
        seen.add(c);
        const rows = [...c.querySelectorAll(
            '[role="menuitem"], [role="menuitemradio"], [role="option"], button, li')]
            .filter(e => e.getClientRects().length);
        const labels = rows.map(e => norm(e.textContent))
                           .filter(t => t && t.length <= 24);
        out.overlays.push({
            trigger: !!(P.trigTestid &&
                        c.querySelector('[data-testid="' + P.trigTestid + '"]')),
            option: !!(P.optTestid &&
                       c.querySelector('[data-testid="' + P.optTestid + '"]')),
            rungs: labels.filter(isRung).length,
            labels: labels.slice(0, 12),
        });
    }
    return out;
}"""


def _gemini_plan_card_due(*, elapsed: float, wait_max_sec: float,
                          alert_sec: float, regen_capped: bool,
                          streaming_recent: bool, start_clicked: bool) -> bool:
    """May the early [Retry][Skip] card fire yet?

    ⛔ THE FALSE ALARM (owner's e2e, 2026-08-17). The card went up at 248s and
    Gemini's plan arrived 25 seconds later; the very next line in the log was
    "Still waiting for Gemini research plan... (248s / 300s)". We told the owner
    Gemini could not start while we ourselves were still waiting patiently, with
    52 seconds of our own budget left — and then retracted it 43 seconds later.
    Owner: keep it non-blocking, which it is, but stop crying wolf.

    ⭐⭐ The two numbers were configured INDEPENDENTLY: `GEMINI_PLAN_ALERT_SEC`
    (240) and the loop's own `_start_wait_max_sec` (300). Nothing tied them, so
    the alarm was free to drift in front of the patience it describes. Tying them
    is the fix, and it is not a tuning change — an alert that fires while its own
    caller intends to keep waiting is wrong at ANY pair of numbers.

    ⭐ The REGEN arm is untouched and still fires the instant it is true: three
    exhausted re-drafts is evidence of failure, not a timer, and #921 exists so
    that evidence reaches the owner early instead of after a 17-minute ladder.

    `streaming_recent` keeps its #929 meaning: a plan that is visibly still
    generating is healthy-slow, and `start_clicked` means there is nothing to
    alert about at all.
    """
    if start_clicked:
        return False
    if streaming_recent:
        return False
    if regen_capped:
        return True
    return elapsed >= max(float(alert_sec), float(wait_max_sec))


def _claude_effort_submenu_verdict(probe) -> str:
    """'open' | 'maybe' | 'closed' — one verdict from the overlay readings.

    ⭐ Pure, because the gate it replaces could veto a working picker and no test
    could see it: the old version's answer lived inside an 8-round poll in a
    900-line async function. Here the answer IS the return value.

      * 'open'   — an overlay that is NOT the parent popover carries the wanted
                   option's test id, or two rows that read as effort rungs.
      * 'maybe'  — some overlay other than the parent is up, but nothing in it
                   was recognised. Worth attempting: Step 1C' is scoped and
                   verifies its own press, so it can diagnose this far better
                   than a gate that just says no.
      * 'closed' — the only thing open is the popover holding the trigger, or
                   nothing is open at all.

    ⛔ TWO rungs, not one. A single 'max' anywhere in a stray overlay — a tooltip,
    a toast — is not a menu. Two is enough to name this menu and still tolerate a
    relabelled rung.
    ⛔ The parent popover is excluded by the trigger, not by its rungs. It shows
    the current value as its own 'EffortMax' row, and a future build that hangs
    the option's test id on that row would otherwise satisfy this from a submenu
    that never opened — the precise failure being fixed here, inverted.
    """
    overlays = [o for o in ((probe or {}).get("overlays") or [])
                if isinstance(o, dict)]
    candidates = [o for o in overlays if not o.get("trigger")]
    for o in candidates:
        if o.get("option"):
            return "open"
        try:
            rungs = int(o.get("rungs") or 0)
        except (TypeError, ValueError):
            rungs = 0
        if rungs >= 2:
            return "open"
    return "maybe" if candidates else "closed"


async def _claude_reopen_model_popover(page) -> bool:
    """Re-open Claude's model popover after a model pick closed it.

    ⭐ Verifies the OUTCOME — the trigger's own `aria-expanded` — never the press.
    "The click did not throw" is the equivalence this file has spent three waves
    removing, and re-opening a popover is precisely a case where a press can land
    on a control that is already busy and change nothing.

    Returns False rather than raising: the caller's next step already knows how to
    report an unconfirmed effort, and a failure here must not lose a run whose
    model and research tool are both correct.
    """
    try:
        marked = await page.evaluate(
            _CLAUDE_MARK_MODEL_TRIGGER_JS,
            {"testid": _CLAUDE_MODEL_TRIGGER_TESTID,
             "attr": _SR_CLICK_MARK, "value": "claude-model-trigger"}) or {}
    except Exception as e:
        log(f"[setup_claude_dr] could not locate the model trigger to re-open ({e})",
            "INFO")
        return False
    if not marked.get("marked"):
        return False
    # Already open is a success, and pressing anyway would CLOSE it — the one
    # outcome this helper must never produce.
    if str(marked.get("expanded")) == "true":
        return True
    if not await _sr_real_click(page, "claude-model-trigger", tag="[setup_claude_dr]"):
        return False
    for _try in range(8):
        await asyncio.sleep(0.25)
        try:
            st = await page.evaluate(_CLAUDE_TRIGGER_EXPANDED_JS,
                                     {"testid": _CLAUDE_MODEL_TRIGGER_TESTID}) or {}
        except Exception:
            return False
        if st.get("expanded"):
            return True
    return False


async def setup_gemini_dr(page, pin_model=None, step_below=None) -> bool:
    """Enable Gemini Deep Research. Returns True only when DR is verified
    ACTIVE (pill visible + pressed/selected). Returns False otherwise so
    the caller's CUA fallback kicks in instead of letting the run proceed
    silently in chat mode.

    UI history:
      • 2026-05: + (attach) → "More tools" → "Deep Research" (current).
      • 2026-04: "Tools" → "Deep Research".
      • Older: direct DR pill in composer / DR in model dropdown.

    Tries the current path first, falls through each legacy path on miss,
    then strictly verifies the resulting pill state. Pre-fix, a missing
    active-state attribute downgraded to a WARN-and-return-True — that
    silently shipped chat-mode briefs as Deep Research output. Strict
    verification is the cost of avoiding that class of bug.

    2026-05-26: pre-selects the newest Flash via _gemini_select_flash_model
    before enabling DR (the pipeline runs Gemini DR on the Flash family — see
    that helper's docstring for why Flash and not Pro). Without an explicit
    pick, the dropdown's default could carry the wrong model into the DR run.
    """
    try:
        await asyncio.sleep(2)
        # Best-effort: pick the latest Flash before opening + menu. Non-fatal if
        # it misses (run proceeds on whatever model the dropdown was on).
        # pin_model (Phoenix known-good fallback) forces an exact-version pick.
        _gem_model_ok = await _gemini_select_flash_model(
            page, pin_model=pin_model, step_below=step_below)
        if selfheal and selfheal.is_enabled():
            await _selfheal_shadow_observe(page, "gemini.select_model", outcome_pass=_gem_model_ok)
        await asyncio.sleep(0.5)
        direct_clicked = False

        # ── Step 1 (current UI 2026-05): + → More tools → Deep Research ──
        # The + button sits in the composer toolbar (left of the textarea).
        # As of 2026-05 it's an SVG icon that morphs +↔× on tap — it has NO
        # stable text "+", NO whitelisted aria-label in some builds, and is
        # NOT a Material FONT glyph, so the old text/label/mat-icon matching
        # missed it entirely ("+ button not in composer" every run). Detect it
        # by STRUCTURE instead: anchor on the composer input, then take visible
        # buttons to its LEFT on the same row (this excludes send/mic/stop,
        # which sit right of or are labelled), label-matchers ranked first.
        # We then click candidates best-first and REQUIRE a popup menu to open
        # before accepting — a wrong click can't silently arm mic/attach.
        n_cands = await page.evaluate("""() => {
            document.querySelectorAll('[data-dg-plus-cand]').forEach(
                el => el.removeAttribute('data-dg-plus-cand'));
            const input = document.querySelector(
                'rich-textarea div[contenteditable="true"], rich-textarea, '
                + 'div[contenteditable="true"][data-placeholder], '
                + 'div[contenteditable="true"], textarea');
            const ir = input ? input.getBoundingClientRect() : null;
            const looksPlus = (b) => {
                const a = (b.getAttribute('aria-label') || '').toLowerCase();
                const tt = (b.getAttribute('title') || '').toLowerCase();
                const tx = (b.textContent || '').trim();
                const addIcon = [...b.querySelectorAll(
                        'mat-icon, .material-symbols-outlined, .material-icons')]
                    .some(ic => { const n = (ic.textContent || '').trim().toLowerCase();
                                  return n === 'add' || n === 'add_circle'; });
                // "Upload & tools" is the current (2026-05) Gemini composer +
                // button aria-label (an mdc-icon-button with aria-haspopup=menu);
                // older builds used add/attach/more — keep them all.
                return a.includes('upload') || a === 'add' || a === 'add files' ||
                       a.includes('add files') || a === 'attach' || a === 'attachments' ||
                       a === 'more' || a === 'more options' || tt === 'add' ||
                       tt === 'more' || tt.includes('attach') || tx === '+' || addIcon;
            };
            const isBad = (b) => {
                const lbl = ((b.getAttribute('aria-label') || '') + ' '
                          + (b.getAttribute('title') || '')).toLowerCase();
                if (/mic|microph|voice|dictat|speak|send|submit|stop|cancel/.test(lbl))
                    return true;
                // Recent-chats sidebar "More options for <chat>" menus sit on
                // the composer's row when the sidebar is expanded, so same-row +
                // left-of-input would otherwise match them — exclude explicitly.
                const cls = (b.className || '').toString().toLowerCase();
                const tid = (b.getAttribute('data-test-id') || '').toLowerCase();
                return tid === 'actions-menu-button' ||
                       cls.includes('conversation-actions') ||
                       /more options for/.test(lbl);
            };
            const cands = [];
            for (const b of document.querySelectorAll('button, [role="button"]')) {
                if (!b.offsetParent || isBad(b)) continue;
                const r = b.getBoundingClientRect();
                if (r.width <= 0 || r.height <= 0) continue;
                const labelHit = looksPlus(b);
                let score = 0;
                if (ir) {
                    // Input anchor available: candidate MUST sit on the
                    // composer's row, left of the input (where + lives). Ties
                    // us to the composer by STRUCTURE regardless of absolute
                    // position — setup runs on the empty new-chat page where
                    // Gemini centers the composer (~30-50% of viewport), so an
                    // absolute "bottom-half only" gate would wrongly drop it.
                    const sameRow = r.top < ir.bottom && r.bottom > ir.top;
                    const leftOfInput = r.right <= ir.left + 8;
                    if (!(sameRow && leftOfInput)) continue;
                    score = 50 + (labelHit ? 100 : 0)
                          + Math.max(0, 20 - Math.round((ir.left - r.right) / 10));
                } else {
                    // No input anchor: fall back to a labelled button in the
                    // bottom region (the pre-2026-05 heuristic).
                    if (r.top < window.innerHeight * 0.4 || !labelHit) continue;
                    score = 100;
                }
                cands.push({ b, score, x: r.left });
            }
            cands.sort((p, q) => q.score - p.score || p.x - q.x);
            cands.slice(0, 5).forEach((c, i) =>
                c.b.setAttribute('data-dg-plus-cand', String(i)));
            return Math.min(cands.length, 5);
        }""")

        _count_visible_menus = """() => {
            let v = 0;
            for (const m of document.querySelectorAll(
                    '[role="menu"], [role="listbox"], [role="menuitem"], [role="option"]'))
                if (m.offsetParent) v++;
            return v;
        }"""
        plus_opened = False
        for _ci in range(int(n_cands or 0)):
            # Baseline visible-menu count BEFORE the click so the assertion
            # measures a DELTA, not an absolute — a menu/listbox already open
            # on the page can't false-positive us into accepting a dead click.
            _menu_before = await page.evaluate(_count_visible_menus)
            clicked = await page.evaluate(
                """(i) => { const el = document.querySelector(
                    '[data-dg-plus-cand="' + i + '"]');
                    if (!el) return false; el.click(); return true; }""", _ci)
            if not clicked:
                continue
            await asyncio.sleep(0.7)
            # Mandatory "menu opened" assertion — a real "+" click renders a
            # popup menu (and morphs the button to ×/aria-expanded). No new
            # menu = wrong control: dismiss and try the next candidate.
            menu_open = await page.evaluate("""(before) => {
                let v = 0;
                for (const m of document.querySelectorAll(
                        '[role="menu"], [role="listbox"], [role="menuitem"], [role="option"]'))
                    if (m.offsetParent) v++;
                const expanded = document.querySelector(
                    '[data-dg-plus-cand][aria-expanded="true"]');
                return v > before || !!expanded;
            }""", _menu_before)
            if menu_open:
                plus_opened = True
                break
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.2)
            except Exception:
                pass
        try:
            await page.evaluate(
                """() => document.querySelectorAll('[data-dg-plus-cand]').forEach(
                    el => el.removeAttribute('data-dg-plus-cand'))""")
        except Exception:
            pass
        if plus_opened:
            await asyncio.sleep(0.8)
            log("[setup_gemini_dr] Step 1 (current UI): opened + menu")
            # Step 1a: scan the + tray top level for "Deep research" — current
            # 2026-05 UI places it as a SIBLING of "More tools", not inside
            # the submenu. Prior code descended into More tools first and
            # never found DR (More tools submenu now contains: Create music,
            # Learning, Guided learning, Personal Intelligence).
            direct_clicked = await page.evaluate("""() => {
                const items = document.querySelectorAll(
                    '[role="menuitem"], [role="option"], button, a, li');
                for (const el of items) {
                    if (!el.offsetParent) continue;
                    const t = (el.textContent || '').trim().toLowerCase();
                    const a = (el.getAttribute('aria-label') || '').toLowerCase();
                    if (t === 'deep research' || a === 'deep research' ||
                        t.startsWith('deep research') || a.startsWith('deep research')) {
                        el.click();
                        return true;
                    }
                }
                return false;
            }""")
            if direct_clicked:
                log("[setup_gemini_dr] Step 1 OK (current UI): + → Deep Research (top-level)")
            else:
                # Step 1b (older UI variant): + → More tools → Deep Research.
                # Kept as fallback for accounts still on the prior layout.
                more_tools_opened = await page.evaluate("""() => {
                    const items = document.querySelectorAll(
                        '[role="menuitem"], [role="option"], button, a, li');
                    for (const el of items) {
                        if (!el.offsetParent) continue;
                        const t = (el.textContent || '').trim().toLowerCase();
                        const a = (el.getAttribute('aria-label') || '').toLowerCase();
                        if (t === 'more tools' || t.startsWith('more tools') ||
                            a === 'more tools' || a.startsWith('more tools')) {
                            el.click();
                            return true;
                        }
                    }
                    return false;
                }""")
                if more_tools_opened:
                    await asyncio.sleep(0.8)
                    log("[setup_gemini_dr] Step 1b (older UI): opened More tools submenu")
                    direct_clicked = await page.evaluate("""() => {
                        const items = document.querySelectorAll(
                            '[role="menuitem"], [role="option"], button, a, li');
                        for (const el of items) {
                            if (!el.offsetParent) continue;
                            const t = (el.textContent || '').trim().toLowerCase();
                            const a = (el.getAttribute('aria-label') || '').toLowerCase();
                            if (t === 'deep research' || a === 'deep research' ||
                                t.startsWith('deep research') || a.startsWith('deep research')) {
                                el.click();
                                return true;
                            }
                        }
                        return false;
                    }""")
                    if direct_clicked:
                        log("[setup_gemini_dr] Step 1b OK (older UI): + → More tools → Deep Research")
                    else:
                        log("[setup_gemini_dr] Step 1b (older UI): More tools submenu missing Deep Research — falling back", "WARN")
                else:
                    log("[setup_gemini_dr] Step 1 (current UI): no Deep Research top-level AND no More tools — falling back", "INFO")
        else:
            log("[setup_gemini_dr] Step 1 (current UI): no + candidate opened a menu — trying legacy paths", "INFO")

        # ── Step 2 (legacy 2026-04): Tools button → Deep Research ────
        if not direct_clicked:
            tools_opened = await page.evaluate("""() => {
                const candidates = document.querySelectorAll('button, [role="button"]');
                for (const b of candidates) {
                    if (!b.offsetParent) continue;
                    const t = (b.textContent || '').trim().toLowerCase();
                    const a = (b.getAttribute('aria-label') || '').toLowerCase();
                    const tt = (b.getAttribute('title') || '').toLowerCase();
                    if (t === 'tools' || a === 'tools' ||
                        a.includes('tools') || tt.includes('tools') ||
                        t.startsWith('tools')) {
                        b.click();
                        return true;
                    }
                }
                return false;
            }""")
            if tools_opened:
                await asyncio.sleep(0.8)
                log("[setup_gemini_dr] Step 2 (legacy): opened Tools menu")
                direct_clicked = await page.evaluate("""() => {
                    const items = document.querySelectorAll('[role="menuitem"], [role="option"], button, a, li');
                    for (const el of items) {
                        if (!el.offsetParent) continue;
                        const t = (el.textContent || '').trim().toLowerCase();
                        const a = (el.getAttribute('aria-label') || '').toLowerCase();
                        if (t === 'deep research' || a === 'deep research' ||
                            t.startsWith('deep research') || a.startsWith('deep research')) {
                            el.click();
                            return true;
                        }
                    }
                    return false;
                }""")
                if direct_clicked:
                    log("[setup_gemini_dr] Step 2 OK (legacy): Tools → Deep Research")

        # ── Step 3 (legacy): direct DR pill in the composer ────────────
        if not direct_clicked:
            direct_clicked = await page.evaluate("""() => {
                const candidates = document.querySelectorAll('button, [role="button"], [role="menuitem"]');
                for (const b of candidates) {
                    if (!b.offsetParent) continue;
                    const t = (b.textContent || '').trim().toLowerCase();
                    const a = (b.getAttribute('aria-label') || '').toLowerCase();
                    if (t === 'deep research' || a === 'deep research' || t.startsWith('deep research')) {
                        b.click();
                        return true;
                    }
                }
                return false;
            }""")
            if direct_clicked:
                log("[setup_gemini_dr] Step 3 OK (legacy): clicked DR pill directly in composer")

        # ── Step 4 (legacy): DR inside the model dropdown ──────────────
        if not direct_clicked:
            for sel in ['button[aria-label*="model"]', 'button[data-test-id*="model"]']:
                try:
                    btn = await page.query_selector(sel)
                    if btn:
                        await btn.click()
                        await asyncio.sleep(0.8)
                        log(f"[setup_gemini_dr] Step 4 (legacy): opened {sel}")
                        direct_clicked = await page.evaluate("""() => {
                            const items = document.querySelectorAll('[role="menuitem"], [role="option"], button');
                            for (const el of items) {
                                const t = (el.textContent || '').trim().toLowerCase();
                                if (t.includes('deep research')) { el.click(); return true; }
                            }
                            return false;
                        }""")
                        if direct_clicked:
                            log(f"[setup_gemini_dr] Step 4 OK (legacy): DR selected via {sel} dropdown")
                            break
                        else:
                            log(f"[setup_gemini_dr] Step 4 {sel}: dropdown opened but DR option absent", "WARN")
                except Exception as e:
                    log(f"[setup_gemini_dr] Step 4 {sel} errored: {e}", "WARN")
                    continue

        if not direct_clicked:
            log("[setup_gemini_dr] FAIL: + menu, Tools menu, direct pill, and model-dropdown fallbacks all missed DR — selectors rotated", "WARN")
            return False

        await asyncio.sleep(1.5)

        # ── Verification: STRICT. DR must be visibly active before True.
        # 2026-05-29 (#709): the prior check relied SOLELY on the pill's
        # pressed/selected class. The real Gemini DR pill class
        # (`mdc-button mat-mdc-button-base mat-badge mat-tonal-button …`)
        # carries NONE of aria-pressed / --selected / .active even when DR is
        # OFF, so a present-but-INACTIVE pill returned False → CUA fallback →
        # the CUA falsely reported "chip already visible and active" → the run
        # proceeded in Flash chat mode (last E2E). The authoritative, cross-
        # version signal is the COMPOSER PLACEHOLDER: DR mode shows
        # "What do you want to research?"; chat mode shows "Ask Gemini". Lead
        # with the placeholder; treat the pressed-class as a secondary signal.
        _gem_active_js = _GEMINI_DR_STATE_JS
        st = await page.evaluate(_gem_active_js)
        # If — and ONLY if — we are CONFIDENT Deep Research is OFF (the composer
        # placeholder explicitly reads "Ask Gemini"), click the pill once to arm
        # the mode, then re-measure. This is the #709 "don't remove the working
        # DOM" guard: last E2E our verify false-negatived an ALREADY-ACTIVE pill
        # (its mat-tonal-button class has no pressed marker), the CUA fallback
        # then clicked that active pill and TOGGLED DEEP RESEARCH OFF. We never
        # click on an ambiguous read (placeholder unreadable / no chat signal) —
        # a toggle can only ever turn a confirmed-off pill ON, never an on pill
        # OFF.
        if (st.get("pillVisible") and st.get("placeholderChat")
                and not st.get("placeholderResearch") and not st.get("pressed")):
            log("[setup_gemini_dr] Verify: composer in chat mode ('Ask Gemini') "
                "with DR pill present — clicking pill to arm Deep Research")
            try:
                await page.evaluate("""() => {
                    const norm = s => (s || '').replace(/\\s+/g, ' ').trim().toLowerCase();
                    for (const p of document.querySelectorAll('button, [role="button"]')) {
                        if (p.offsetParent && norm(p.textContent) === 'deep research') {
                            p.click(); return true;
                        }
                    }
                    return false;
                }""")
                await asyncio.sleep(1.2)
            except Exception:
                pass
            st = await page.evaluate(_gem_active_js)
        active_ok = bool(st.get("placeholderResearch") or st.get("pressed"))
        if not active_ok:
            # One-shot diagnostic dump (mirrors #708) so the next E2E pins the
            # real active class / placeholder. Grep backend.log for
            # "Verify FAIL: DR not active — dump".
            try:
                log("[setup_gemini_dr] Verify FAIL: DR not active — dump " + json.dumps(st))
            except Exception:
                pass
            log(f"[setup_gemini_dr] Verify FAIL: DR pill visible but NOT active "
                f"(placeholder={st.get('placeholder')!r} pillCls={st.get('pillCls')!r}) "
                f"— returning False so CUA fallback retries", "WARN")
            return False
        log(f"[setup_gemini_dr] Verify OK: DR active "
            f"(placeholder={st.get('placeholder')!r}, pressed={st.get('pressed')})")
        return True
    except Exception as e:
        log(f"[setup_gemini_dr] exception: {e}", "WARN")
        return False


async def _claude_plan_limited(page, probe_js, probe_args) -> bool:
    """Does the OPEN model menu prove this account's plan excludes the family?

    True only for the one shape that can mean nothing else: family rows are
    present, and EVERY one of them is a sales chip.

    ⛔ THE THREE CASES ARE NOT INTERCHANGEABLE, which is why this reads `chips`
    rather than "the picker found nothing":
      * n > 0             — the family is genuinely offered; the picker missing
                            it is a selector bug and must stay loud.
      * n == 0, chips > 0 — the plan does not include the family. Permanent for
                            this account; retrying it forever is the current bug.
      * n == 0, chips == 0 — the family is not in this menu at all: a rename, a
                            rollout difference, or a menu read mid-render. NOT a
                            plan limit, and answering it with a family switch
                            would hide a real regression behind a silent
                            downgrade — the worst of the three outcomes.

    ⚠ Retries for the same reason Step 1B* does: a menu one beat from finishing
    its render reads as case three, and treating that as "no fallback needed" on
    the first look costs the whole run. Never raises — an unreadable probe is
    "not proved", which lands on today's behaviour.
    """
    for _attempt in range(3):
        try:
            probe = await page.evaluate(probe_js, probe_args) or {}
        except Exception as exc:
            log(f"[setup_claude_dr] Step 1B† plan probe errored "
                f"({type(exc).__name__}) — not treating this as a plan limit", "WARN")
            return False
        # ⚠ `chipsAny`, NOT `chips`. The row-filtered count exists to be a
        # sensible NUMBER; it is blind to a chip rendered as a plain div, and a
        # verdict resting on it silently did nothing on that markup. The fact
        # that a sales prompt was seen is the part this decision needs.
        if probe.get("menu") and not probe.get("n") and probe.get("chipsAny"):
            return True
        # A mounted menu that already offers real rows answers the question in
        # the negative — no amount of waiting turns those into chips.
        if probe.get("menu") and probe.get("n"):
            return False
        await asyncio.sleep(0.4)
    return False


def _report_claude_plan_limit(excluded: str, using: str) -> None:
    """Tell the user WHY this run is on a different model family — once.

    ⛔ DELIBERATELY NOT AN ALERT, and not a new decision card. The user is not
    being asked anything: the account's plan is a fact the run cannot change and
    has already worked around. A blocking card here would also be the SECOND
    thing to ask about one decision — Phase 0's pro_required card, with its
    Continue-with-Free action, is where that question belongs, and re-asking it
    mid-run is exactly the "user clicks Continue two or three times for what
    they perceive as one decision" regression F3 removed.

    Reuses the status the agent is already in, so the milestone stepper does not
    move: this is a caption on the current step, not a new one."""
    log(f"[setup_claude_dr] plan limit: {excluded} is not on this account's plan — "
        f"running Claude on the {using} family instead", "INFO")
    try:
        emit_event("agent_progress", phase=2, agent="claude", status="starting",
                   progress=f"Claude's plan doesn't include {excluded.capitalize()} — "
                            f"using the latest {using.capitalize()} instead")
    except Exception:
        pass


async def setup_claude_dr(page, pin_model=None, step_below=None, allow_probe=False) -> bool:
    """Enable Claude Opus (the newest offered) + Max Effort + Research tool via
    direct Playwright selectors. As of 2026-05-28 the claude.ai UI splits these
    across the model popover + the tools menu:
        1. Model dropdown        → the HIGHEST Opus offered
        2. Effort submenu        → Max          (inside the model popover)
        3. Research tool         → on (inside the "+" tools menu)
    Every label above comes from P2_MODEL_POLICY["claude"], and there is
    deliberately NO version number anywhere in this function.

    ⭐ FAMILY + HIGHEST-OFFERED (2026-08-01). The old rule was "Opus >= 4.8",
    and `model_ok` meant "the trigger reads at least the floor". On an account
    already above the floor that skipped the popover entirely, so the upgrade
    probe (Step 1B*) could never run and the account stayed on its current model
    for good — the exact way P2 sat on Opus 4.8 through the whole Opus-5
    rollout. Now `model_ok` only means "the trigger names the family", the pick
    is always the highest row offered, and `allow_probe` + the cadence below are
    what make sure we periodically LOOK.

    `allow_probe` is passed True ONLY by the initial P2 setup. The pre-send
    re-activation path (ensure_deep_mode_active) passes it False on purpose:
    opening the model popover seconds before the brief is sent is the stranded-
    popover-over-the-composer failure from the #744 screenshot.

    THE POPOVER IS NOW OPENED ONLY WHEN IT HAS SOMETHING TO DO (2026-07-30).
    It used to open on every call because the Thinking toggle lived inside the
    Effort submenu and had to be re-asserted (#745). Opus 5 removed that toggle,
    and the model-selector trigger already displays the effort ("Opus 5 Max") —
    so when the trigger reads a model at/above the floor AND the target effort,
    both knobs are confirmed without touching the UI and Step 1A is skipped.
    That is what stopped the run from logging "NOT re-picking" and then opening
    the model menu anyway, and from handing the quality knobs to the CUA
    validate layer, which produced a second model-menu interaction.
    The skip requires POSITIVE reads of both facts; any uncertainty falls
    through and opens the popover exactly as before.

    The model PICK still runs only when the trigger isn't already at/above the
    floor (#744 — never re-click a correct model). Effort is a quality knob
    (best-effort: WARN on miss). Correctness gates are the model + Research tool
    — those hard-return False on miss. The CUA fallback lives one layer up in
    setup_agent + validate_setup_with_cua so this routine can fail fast without
    fighting the DOM."""
    # ⚠ Clear FIRST. `_P2_PICKED_VERSION` is a process-global that survives for
    # the daemon's lifetime, and several paths below return before writing it
    # (Step 1A FAIL, Step 1B FAIL, the outer except). A stale entry from a
    # PREVIOUS run would then be read as "the version that just failed" by the
    # step-back path and steer the retry off a number from another run.
    _P2_PICKED_VERSION.pop("claude", None)
    try:
        await asyncio.sleep(2)

        # ── Step 0: ensure the composer is on the "Chat" tab, NOT "Cowork" ──
        # (2026-07-16) claude.ai added a Chat|Cowork segmented control to the
        # composer. Deep Research — the "+" tools menu + Research tool that
        # Step 3 enables — lives under CHAT; Cowork has no Research tool, so a
        # run that lands on Cowork (Claude persists composer mode across
        # sessions) would fail Step 3 outright. Ground-truth DOM (live console
        # dump 2026-07-16): a radiogroup of span[role="radio"] options, each
        # carrying a stable span[data-surface-segment="chat"|"cowork"] label;
        # active = aria-checked="true" / data-checked. Click Chat when it isn't
        # active. No-op on the older UI (segment absent). Best-effort: WARN on a
        # miss — the CUA setup-validate one layer up still catches a wrong mode.
        _ENSURE_CHAT_JS = """
        () => {
          const seg = document.querySelector('[data-surface-segment="chat"]');
          if (!seg) return 'no-toggle';
          const radio = seg.closest('[role="radio"]') || seg.parentElement;
          if (!radio) return 'no-toggle';
          const onChat = radio.getAttribute('aria-checked') === 'true'
                         || radio.hasAttribute('data-checked');
          if (onChat) return 'already-chat';
          radio.click();
          return 'clicked-chat';
        }
        """
        _VERIFY_CHAT_JS = """
        () => {
          const seg = document.querySelector('[data-surface-segment="chat"]');
          if (!seg) return 'no-toggle';
          const radio = seg.closest('[role="radio"]') || seg.parentElement;
          return (radio && (radio.getAttribute('aria-checked') === 'true'
                  || radio.hasAttribute('data-checked'))) ? 'chat' : 'cowork';
        }
        """
        try:
            _chat_state = await page.evaluate(_ENSURE_CHAT_JS)
            if _chat_state == "clicked-chat":
                await asyncio.sleep(1.2)  # let the composer re-render into Chat
                _cs = await page.evaluate(_VERIFY_CHAT_JS)
                if _cs != "chat":
                    # one retry — the first click can race the control's mount
                    await page.evaluate(_ENSURE_CHAT_JS)
                    await asyncio.sleep(1.2)
                    _cs = await page.evaluate(_VERIFY_CHAT_JS)
                log(f"[setup_claude_dr] Step 0: switched composer Cowork→Chat (now={_cs})",
                    "INFO" if _cs == "chat" else "WARN")
            elif _chat_state == "already-chat":
                log("[setup_claude_dr] Step 0 OK: composer already on Chat")
            else:
                log("[setup_claude_dr] Step 0: no Chat/Cowork toggle present "
                    "(older UI) — nothing to switch", "INFO")
        except Exception as _ce:
            log(f"[setup_claude_dr] Step 0: Chat-tab guard errored "
                f"(non-fatal, CUA validate will catch a wrong mode): {_ce}", "WARN")

        # The model FAMILY word — the only model identity in this function.
        # Injected into every JS below so a rename is one policy edit, and so no
        # version literal can creep back into a page.evaluate string.
        # ⭐ THE RUN'S family, not the policy's. On a pro account these are the
        # same word and everything below behaves exactly as it did. On an
        # account whose plan excludes the primary family, a prior pass in THIS
        # run has already proved that from the DOM and recorded the fallback —
        # and reading the policy here instead would send the step-back and the
        # pre-send re-activation hunting for a family this account cannot select,
        # undoing the fallback pick on the very next pass.
        _claude_family = _p2_active_family("claude") or "opus"
        # The family the policy WANTS, kept separate: the fallback is only ever
        # entered from the primary, and the CUA missions have to be able to name
        # the excluded family to tell the agent what the chips are.
        _claude_primary = p2_family("claude") or "opus"
        _claude_free_family = p2_free_family("claude")
        # Effort + thinking come from the SAME policy dict, so the quality knobs
        # can never drift from it. `thinking` is False since Opus 5 removed the
        # toggle — see the note on P2_MODEL_POLICY["claude"].
        _cl_pol = p2_labels("claude")
        _claude_effort = _cl_pol.get("effort")            # "max"
        _claude_wants_thinking = bool(_cl_pol.get("thinking"))

        # ── Step 1: model = Opus >= floor, Effort = Max, Thinking toggle ON ──
        # (#744) Read the model-selector TRIGGER first — it shows BOTH the
        # current model AND its effort, e.g. "Opus 4.8 Max". NEVER re-pick an
        # already-correct model (re-clicking a correct option was the loop that
        # wedged P2: "clicking the model selector repeatedly inspite of choosing
        # the right model and tool").
        # (#745, 2026-06-02) The Thinking toggle is NOT on the trigger — it
        # lives inside the Effort submenu of the model popover — so we still
        # open the popover ONCE to set Effort=Max + Thinking ON via DOM. The
        # user asked for this to be done seamlessly by DOM ("like gemini");
        # CUA's screenshots kept collapsing the Effort submenu. The model PICK
        # (Step 1B) is the only sub-step gated to "not already >= floor" —
        # opening the popover to set the quality knobs is safe (we always
        # Escape after, and we never re-click a correct model option, so the
        # #744 loop can't recur).
        # (2026-07-26) "at or above the floor" is NOT the same as "the latest".
        # Claude.ai defaults to the previous flagship, so once the trigger read
        # >= floor this skipped the picker entirely and the account stayed on the
        # OLD model for good — the family shipped Opus 5 and P2 kept running 4.8.
        # Step 1B* below fixes that: while the popover is open ANYWAY, upgrade to
        # a STRICTLY higher Opus when one is offered. Strictly-higher is what
        # keeps #744 dead — the currently-selected option can never be re-clicked.
        # ⛔ HOISTED TO A NAME so the fallback path can re-ask this exact
        # question about a DIFFERENT family. A second inline copy would be a
        # fifth parsing site — and the trigger parser is already documented as
        # "the FOURTH parsing site and the easiest to forget", whose answer
        # decides whether an upgrade fires. Two copies drifting is not a
        # hypothetical here; it is the failure this file keeps recording.
        _TRIGGER_READ_JS = """({effortWord, fam}) => {
            const famRe = new RegExp(fam, 'i');
            // The SAME two-order, adjacency-bounded parse as the picker and the
            // probe. This is the FOURTH parsing site and the easiest to forget:
            // its answer is `_cur`, the number Step 1B* compares the probe's
            // `_offered` against. Leave it single-order and a renamed label makes
            // the trigger read null while the probe still reads a version — "we
            // cannot compare, so anything numbered counts as newer" — and the
            // upgrade re-fires on every single run.
            const verFamFirst = new RegExp(fam + '[ ._/()-]{0,3}([0-9]+(?:\\\\.[0-9]+)?)', 'i');
            const verNumFirst = new RegExp('([0-9]+(?:\\\\.[0-9]+)?)[ ._/()-]{0,3}' + fam, 'i');
            const verOf = t => {
                const m = (t || '').match(verFamFirst) || (t || '').match(verNumFirst);
                return m ? parseFloat(m[1]) : null;
            };
            // An upsell chip ("Try Opus 6", "Upgrade to Opus") names the family
            // and a version without being the selected model. Reading one as the
            // trigger used to only mis-LOG; now the value is learned and reused
            // as the fallback pin target, so a poisoned read outlives the run.
            const verbRe = /(upgrade|subscribe|unlock|try |get )/i;
            const vis = el => el.getClientRects().length > 0;   // fixed-position triggers have offsetParent === null
            // The trigger lives OUTSIDE any open popover — exclude menu/
            // listbox/dialog descendants so a stale option can't be read.
            const btns = [...document.querySelectorAll('button, [role="button"]')]
                .filter(b => vis(b) && !b.closest('[role="menu"], [role="listbox"], [role="dialog"]'))
                .filter(b => !verbRe.test(b.textContent || ''));
            // ⛔ A version-LESS family word is only trusted from a button that is
            // actually a MODEL CONTROL. Page-wide it is far too weak: on a
            // Sonnet-only account a marketing chip ("Opus — included in Max",
            // "Opus trial") would read as "the family is selected", setup would
            // skip the picker AND report success, and the run would go out on
            // Sonnet. A versioned read stays page-wide (that is long-standing
            // behaviour and a bare version next to the family word is strong
            // evidence); only the new, weaker signal is scoped.
            const isModelCtl = b => {
                const a = (b.getAttribute('aria-label') || '').toLowerCase();
                const tid = (b.getAttribute('data-testid') || '').toLowerCase();
                return a.includes('model') || tid.includes('model');
            };
            let best = null, bestText = '', famOnly = '';
            for (const b of btns) {
                const t = b.textContent || '';
                const v = verOf(t);
                if (v !== null && (best === null || v > best)) { best = v; bestText = t; }
                // Family word with NO version: the day the platform drops version
                // numbers from the label, this is the only evidence the family is
                // selected. Shortest such button wins (a leaf, not a wrapper).
                if (v === null && famRe.test(t) && isModelCtl(b)
                        && (!famOnly || t.length < famOnly.length)) famOnly = t;
            }
            if (best === null && famOnly) bestText = famOnly;
            // (2026-07-30) The SAME trigger that carries the model also carries
            // the effort — it reads "Opus 5 Max" — so effort is knowable WITHOUT
            // opening the popover. Read it only off the winning button's text,
            // never page-wide: this account's plan chip also says "Max", and a
            // document-wide scan would report effort-is-set on every page.
            // Token-split rather than a constructed RegExp on purpose — a lone
            // \\b inside a non-raw Python string once became a literal backspace
            // and silently disabled a gate for months (see the #913 note).
            let effort = null;
            if (bestText && effortWord) {
                const toks = bestText.toLowerCase().split(/[^a-z0-9.]+/);
                if (toks.indexOf(String(effortWord).toLowerCase()) !== -1) effort = effortWord;
            }
            return { ver: best, fam: !!bestText,
                     trigger_text: bestText.replace(/\\s+/g, ' ').trim().slice(0, 120),
                     effort: effort };
        }"""
        _trigger_read = await page.evaluate(
            _TRIGGER_READ_JS, {"effortWord": _claude_effort, "fam": _claude_family})
        model_trigger_ver = _trigger_read.get("ver") if isinstance(_trigger_read, dict) else _trigger_read
        # Effort read straight off the trigger. Only ever a POSITIVE signal: when
        # it is None we fall through to the popover exactly as before, so an
        # unrecognised trigger layout degrades to today's behaviour, never worse.
        _trigger_effort_ok = bool(isinstance(_trigger_read, dict) and _trigger_read.get("effort"))
        # Known-good fallback: when pin_model is set (the latest model just failed
        # Deep-Research verification), FORCE a re-pick to a DIFFERENT model — even
        # if the trigger already shows a higher Opus (that higher model is the one
        # that failed). A deliberate one-shot switch, NOT the #744 loop.
        #
        # ⭐ `model_ok` = "the trigger names the family", NOT ">= some version".
        # This is the whole family-only change: there is no number to compare
        # against, so no constant can go stale, and a version-LESS label ("Opus
        # Max") still counts as the family being selected.
        _trigger_has_family = bool(isinstance(_trigger_read, dict) and _trigger_read.get("fam"))
        model_ok = (pin_model is None and step_below is None) and _trigger_has_family
        if pin_model is not None or step_below is not None:
            log(f"[setup_claude_dr] step-back: re-picking away from the model that failed "
                f"(pin={pin_model!r} below={step_below!r})")
        opus_selected = None
        # The version we actually SELECTED. Kept separate from the trigger read so
        # the learned known-good comes from a real pick, never from a page-wide
        # scan that an upsell chip could poison.
        _picked_version = None
        # Did we CLICK a model this run? Effort is stored per model on this
        # family, so a click invalidates any effort read taken off the trigger
        # before it (see the Step 1C guard).
        _model_changed = False
        # Phoenix model_refresh — advisory thinking/effort confirmation (never
        # gates; the caller surfaces a soft amber notice if a policy-required
        # knob couldn't be set). Initialized here because _think/_eff_set are
        # bound only on the popover-opened path (avoids an unset-local read).
        _effort_confirmed = False
        _thinking_confirmed = False
        # HOW the effort tier came to be confirmed — "trigger" when the composer
        # already showed it, "submenu" when we opened the popover and set it.
        # Carried so the single intent record at the end of this function can tell
        # a correct skip from a real verification, which the boolean alone cannot.
        _effort_via = ""
        if model_ok:
            # Model already correct — record it but DO NOT re-pick (the #744
            # re-click loop). We still open the popover below for Effort/Thinking.
            opus_selected = f"{_claude_family} {model_trigger_ver} (trigger — not re-picked)"
            log(f"[setup_claude_dr] Step 1 OK: model already {_claude_family} "
                f"v{model_trigger_ver} (trigger) — NOT re-picking (#744)")

        # Step 1B picker. Scopes to the OPEN popover so the trigger button
        # (showing the current model) is excluded; sees role="menuitemradio"/div
        # options and uses getClientRects() so a fixed-position popover isn't
        # filtered by offsetParent (#708/#744).
        #
        # ⭐ NO FLOOR. The rule is simply the HIGHEST family row offered — which
        # by construction can never be a downgrade, because nothing else on the
        # menu is higher. A floor could only ever reject the row that should have
        # won. `below` is the opposite tool: the step-back path passes the version
        # that just failed and takes the best row strictly beneath it, so the
        # pipeline can retreat one release without any hardcoded "previous
        # version". A family row with NO version is a valid last-resort candidate
        # (a version-less rename must not empty the menu), but it is never a
        # step-back target — we cannot prove it is below what just failed.
        _pick_opus_js = """({pin, below, fam, triggerText, verbs, upsellWindow}) => {
            const vis = el => el.getClientRects().length > 0;
            const famRe = new RegExp(fam, 'i');
            // ⭐ BOTH VERSION ORDERS, deliberately — see models.parse_family_version,
            // which tries exactly these two patterns in exactly this order. Claude
            // ships family-first ("Opus 5") and Gemini number-first ("3.6 Flash")
            // TODAY, so a single-order parser is correct only until ITS OWN vendor
            // renames. When that happens every row parses as version-less, the
            // ranking collapses to the "shortest label" tie-break, and the picker
            // selects an OLDER model while reporting success — a silent downgrade,
            // which is the one outcome this whole path exists to prevent.
            const verFamFirst = new RegExp(fam + '[ ._/()-]{0,3}([0-9]+(?:\\\\.[0-9]+)?)', 'i');
            const verNumFirst = new RegExp('([0-9]+(?:\\\\.[0-9]+)?)[ ._/()-]{0,3}' + fam, 'i');
            const menus = [...document.querySelectorAll('[role="menu"], [role="listbox"], [role="dialog"]')]
                .filter(vis);
            const roots = menus.length ? menus : [document.body];
            const seen = new Set();
            const items = roots.flatMap(m => [...m.querySelectorAll('[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"], [role="option"], button, a, li, div, span')])
                .filter(el => vis(el) && !seen.has(el) && seen.add(el));
            const norm = s => (s || '').replace(/\\s+/g, ' ').trim();
            const verOf = t => {
                const m = (t || '').match(verFamFirst) || (t || '').match(verNumFirst);
                return m ? parseFloat(m[1]) : null;
            };
            // Character-level port of models.is_upsell — ONE definition of what
            // a sales prompt looks like, not a second opinion. "Upgrade to Opus"
            // names the family exactly as a real row does, so famRe and verOf
            // both accept it; without this the ranker CLICKS the billing chip,
            // the upsell surface opens over the composer, and the truthy return
            // is reported as a successful model pick.
            //
            // VERB-THEN-FAMILY WITHIN A WINDOW, not a bare verb test: row text
            // here is title+description concatenated, so "try our most capable
            // model" would disqualify a genuine row and empty the menu.
            // Regex-free, like the reject port in the Gemini ranker — this is a
            // non-raw Python string, where a lone \\b once became a literal
            // backspace and silently killed a gate (#913).
            const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
            // Whitespace collapsed over the SAME set models._collapse_ws uses,
            // NOT this language's own `\\s`. Python calls \\x1c-\\x1f and \\x85
            // whitespace and JS does not; JS calls \\ufeff (a BOM, which does
            // turn up in page text) whitespace and Python does not. The window
            // below is counted in CHARACTERS on the collapsed string, so a label
            // padded with either class was an upsell to one implementation and a
            // model row to the other — measured on this exact pair, which is how
            // a "character-for-character port" turned out not to be one.
            const normU = s => (s || '').replace(/[\\s\\x1c-\\x1f\\x85\\ufeff]+/g, ' ').trim();
            const isUpsell = (raw) => {
                const s = normU(raw).toLowerCase(), n = normU(fam).toLowerCase();
                if (!s || !n) return false;
                // ⛔ NO "FAMILY NAMED FIRST" EXEMPTION, and this comment used to
                // describe one that is not here. It was tried and REVERTED
                // 2026-08-14 because it re-opened the blocking finding: driven
                // through this very JS, a menu whose top row read
                // "Opus 5 · Upgrade to Opus Max for more usage" was clicked and
                // returned as a confirmed pick. So a genuine row whose blurb
                // happens to read verb-then-family IS dropped here, on purpose.
                // See models.is_upsell for the full account.
                for (const rawVerb of (verbs || [])) {
                    const verb = String(rawVerb).toLowerCase();
                    if (!verb) continue;
                    let i = s.indexOf(verb);
                    while (i !== -1) {
                        const end = i + verb.length;
                        const leftOk = i === 0 || !isAlnum(s[i - 1]);
                        const rightOk = end >= s.length || !isAlnum(s[end]);
                        if (leftOk && rightOk) {
                            const j = s.indexOf(n, end);
                            if (j !== -1 && j - end <= upsellWindow) return true;
                        }
                        i = s.indexOf(verb, i + 1);
                    }
                }
                return false;
            };
            // Without a floor the body fallback (used when no menu has mounted)
            // would happily treat the TRIGGER BUTTON as a row and click it,
            // which just toggles the popover shut while reporting success.
            const trig = norm(triggerText);
            let best = null, bestRank = null, bestLen = Infinity;
            for (const el of items) {
                const t = (el.textContent || '').trim();
                if (trig && norm(t) === trig) continue;        // never click the trigger
                // BEFORE the version parse, and unconditionally. A VERSIONED
                // upsell ("Upgrade to Opus 5.2") parses, so a check reached
                // only on the version-less branch would let the worst case
                // through: a chip that outranks every genuine row on version.
                if (isUpsell(t)) continue;
                const v = verOf(t);
                const isFam = v !== null || famRe.test(t);
                if (!isFam) continue;
                let rank;
                if (pin != null && v !== null && Math.abs(v - pin) <= 0.001) {
                    // ⭐ Exact known-good — outranks every other candidate, but as a
                    // RANK TIER, never a `break`. `items` is document order,
                    // ancestors first, so the FIRST element carrying the pinned
                    // version is usually the menu's own wrapper (its textContent
                    // concatenates every row). A click on an ancestor never reaches
                    // the row's handler: the model does not change, yet this returns
                    // truthy and the caller logs an upgrade and records a known-good.
                    // Falling through keeps the shortest-text leaf preference the
                    // rest of this function already applies.
                    rank = [2, v];
                } else {
                    if (pin != null || below != null) {
                        // ⭐ A PIN THAT IS NO LONGER ON THE MENU MUST NOT PARK THE RUN.
                        // The learned known-good has no expiry, so weeks later the
                        // platform may have retired it. Treating "exact pin absent"
                        // as "nothing to pick" threw away a perfectly good older row
                        // and sent the leg to the chat-mode gate — losing the retry
                        // this whole path exists to provide. Fall back to the same
                        // strictly-older rule the no-history route uses.
                        const bound = below != null ? below : pin;
                        if (v === null || v >= bound - 0.001) continue;
                    }
                    // Any version outranks no version; then higher wins; tie → shorter
                    // text (a leaf menu item, not a wrapper listing several models).
                    rank = v === null ? [0, 0] : [1, v];
                }
                if (best === null || rank[0] > bestRank[0] || (rank[0] === bestRank[0] && rank[1] > bestRank[1])
                        || (rank[0] === bestRank[0] && rank[1] === bestRank[1] && t.length < bestLen)) {
                    best = el; bestRank = rank; bestLen = t.length;
                }
            }
            if (best) {
                best.click();
                return { label: best.textContent.trim().slice(0, 60),
                         version: bestRank[0] === 0 ? null : bestRank[1] };
            }
            return null;
        }"""

        # Read-only companion to _pick_opus_js: what is the highest family member
        # the OPEN popover offers? Clicks nothing; the upgrade click goes through
        # _pick_opus_js so there is exactly ONE code path that ever selects a model.
        #
        # ⛔ REQUIRES A MOUNTED MENU. The body fallback the picker keeps would let
        # the trigger button itself count as a row — "highest offered == what we
        # already have" — so a popover that mounts a beat slowly would report
        # "nothing newer" and, under the weekly cadence, burn the whole interval's
        # check on a no-op. `menu` tells the caller whether the answer is real.
        _probe_opus_js = """({fam, verbs, upsellWindow}) => {
            const vis = el => el.getClientRects().length > 0;
            // Same two-order parse as the picker — they must agree on what a row
            // is worth. A probe that could not read the renamed order would report
            // "nothing newer offered" while the picker could have selected it, so
            // the weekly upgrade would go quiet exactly when a release ships.
            const verFamFirst = new RegExp(fam + '[ ._/()-]{0,3}([0-9]+(?:\\\\.[0-9]+)?)', 'i');
            const verNumFirst = new RegExp('([0-9]+(?:\\\\.[0-9]+)?)[ ._/()-]{0,3}' + fam, 'i');
            const menus = [...document.querySelectorAll('[role="menu"], [role="listbox"], [role="dialog"]')]
                .filter(vis);
            // ⚠ `chips: 0` is not decoration — the shape must be the SAME on
            // every return, because the caller's plan-limit rule reads three
            // fields and a missing one is falsy in a way that happens to give
            // the right answer today. "Right by accident" is what breaks when
            // someone reorders the rule.
            if (!menus.length) return {menu: false, n: 0, highest: null, chips: 0, chipsAny: false};
            const seen = new Set();
            const items = menus.flatMap(m => [...m.querySelectorAll('[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"], [role="option"], button, a, li, div, span')])
                .filter(el => vis(el) && !seen.has(el) && seen.add(el));
            const verOf = t => {
                const m = (t || '').match(verFamFirst) || (t || '').match(verNumFirst);
                return m ? parseFloat(m[1]) : null;
            };
            // Same port, same reason, as the picker's — and it has to be here
            // too or the two disagree in the one direction that costs a run
            // every time. This probe counts only VERSIONED rows, so a
            // version-less chip could never reach it; a versioned one
            // ("Upgrade to Opus 5.2") would become `highest`, the caller would
            // read a newer model as offered, and the picker — which now
            // excludes it — would find nothing to click. That is not a silent
            // no-op: it is "offered but not clickable" logged on every run,
            // forever, with no version anywhere that can satisfy it.
            const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
            // Same whitespace set as the picker's port and models._collapse_ws —
            // see the picker for why JS's own `\\s` is the wrong set here.
            const normU = s => (s || '').replace(/[\\s\\x1c-\\x1f\\x85\\ufeff]+/g, ' ').trim();
            const isUpsell = (raw) => {
                const s = normU(raw).toLowerCase(), nn = normU(fam).toLowerCase();
                if (!s || !nn) return false;
                for (const rawVerb of (verbs || [])) {
                    const verb = String(rawVerb).toLowerCase();
                    if (!verb) continue;
                    let i = s.indexOf(verb);
                    while (i !== -1) {
                        const end = i + verb.length;
                        const leftOk = i === 0 || !isAlnum(s[i - 1]);
                        const rightOk = end >= s.length || !isAlnum(s[end]);
                        if (leftOk && rightOk) {
                            const j = s.indexOf(nn, end);
                            if (j !== -1 && j - end <= upsellWindow) return true;
                        }
                        i = s.indexOf(verb, i + 1);
                    }
                }
                return false;
            };
            // `chips` is the whole non-pro signal, and it is counted here rather
            // than inferred by the caller because only this loop can tell the
            // three cases apart:
            //   n>0            — the family is genuinely offered
            //   n==0, chips>0  — the family is offered ONLY as a sales prompt,
            //                    i.e. this plan does not include it
            //   n==0, chips==0 — the family is not in this menu at all (a
            //                    rename, or a menu read mid-render)
            // Reading "no rows" alone cannot separate a plan limit from a
            // rollout change, and those want opposite responses: one is a
            // permanent fact about the account, the other is a transient we must
            // keep retrying and eventually shout about.
            // ⛔⛔ TWO SIGNALS, AND THE VERDICT USES THE SECOND. `chips` counts
            // chip ROWS and is telemetry; `chipsAny` is "a sales prompt was seen
            // at all" and is what decides a plan limit. Measured 2026-08-14
            // against this exact JS: with only the row-filtered count, a chip
            // rendered as a plain <div> or <li> — both of which ARE in the item
            // list above — reported `chips: 0`, so the whole fallback silently
            // did nothing on that markup. A count that is right about the number
            // and blind to the fact is worse than no count: the fact is the part
            // a decision rests on.
            let n = 0, highest = null, chips = 0, chipsAny = false;
            for (const el of items) {
                const raw = (el.textContent || '').trim();
                if (isUpsell(raw)) {
                    chipsAny = true;
                    // Count ROWS, not every node whose text contains the chip:
                    // the item list walks div/span too, so one chip is seen at
                    // several depths and a naive count reads 5 for 1. Kept
                    // separate precisely so this narrowing can never again
                    // decide anything.
                    if (el.matches('[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"], [role="option"], button, a')) chips += 1;
                    continue;
                }
                const v = verOf(raw);
                if (v === null) continue;
                n += 1;
                if (highest === null || v > highest) highest = v;
            }
            return {menu: true, n: n, highest: highest, chips: chips, chipsAny: chipsAny};
        }"""

        # ── Step 1A: open the model popover ONCE (model pick if needed +
        #              to reach the Effort submenu when it is still needed) ──
        # (2026-07-30) It used to open on EVERY run, unconditionally, because the
        # Thinking toggle lived behind it. Opus 5 removed that toggle, and the
        # trigger already exposes the effort ("Opus 5 Max"), so when the model is
        # at/above the floor AND the trigger already shows the target effort there
        # is nothing left behind the popover to set. Opening it anyway is what
        # made the log say "NOT re-picking" and then immediately open the model
        # menu — and what invited the CUA validate layer in to "fix" the quality
        # knobs, producing the second interaction. Every conjunct is a POSITIVE
        # read; any uncertainty falls through and opens the popover as before.
        #
        # ⭐ (2026-08-01) …but skipping FOREVER is how the account gets stranded.
        # With the floor gone, `model_ok` is just "the trigger names the family",
        # so on a healthy account this skip would fire on every run and the
        # highest-offered upgrade (Step 1B*) would never execute — the same
        # stranding the floor used to cause, one step earlier. `_probe_due` is the
        # weekly look: the popover opens on a cadence purely to see whether a
        # newer family member has appeared. It runs on the pipeline's own
        # authenticated page, so there is no separate canary process, no extra
        # credentials, and the cost is one popover per platform per interval.
        # ⛔ Only on the INITIAL setup call (allow_probe) — never on the pre-send
        # re-activation, where an open popover lands over the composer.
        _probe_due = bool(allow_probe and model_probe_due("claude"))
        _skip_popover = bool(model_ok and _trigger_effort_ok
                             and not _claude_wants_thinking and not _probe_due)
        if _skip_popover:
            # Read off the trigger, not assumed: this is the same evidence the
            # popover path would have produced, without touching the UI.
            _effort_confirmed = True
            _effort_via = "trigger"
            log(f"[setup_claude_dr] Step 1A SKIPPED: trigger already reads "
                f"{_trigger_read.get('trigger_text')!r} — family '{_claude_family}' and "
                f"effort '{_claude_effort}' both confirmed without opening the popover")
        elif _probe_due and model_ok and _trigger_effort_ok:
            log(f"[setup_claude_dr] Step 1A: model+effort already confirmed off the "
                f"trigger, but the periodic model-menu check is due — opening the "
                f"popover once to look for a newer {_claude_family}")
        dropdown_clicked = False if _skip_popover else await page.evaluate("""(a) => {
            const fam = a.fam, verbs = a.verbs || [], upsellWindow = a.upsellWindow || 24;
            const btns = [...document.querySelectorAll('button, [role="button"]')]
                .filter(b => b.getClientRects().length > 0 && !b.closest('[role="menu"], [role="listbox"], [role="dialog"]'));
            const famRe = new RegExp(fam, 'i');
            // ⭐ THE OPENER NEEDS THE UPSELL RULE TOO. It takes the FIRST visible
            // button naming the family, in document order — and an "Upgrade to
            // Opus" banner sitting above the composer names the family exactly
            // the way the trigger does. Clicking it opens the billing surface
            // over the composer.
            //
            // ⓘ This is not the blocking finding: the pick that follows finds
            // only excluded chips inside whatever mounted, gives up, and Escapes
            // — so nothing is ever REPORTED as a successful model selection. But
            // the user still gets a payment modal in the middle of a run, and
            // the guard existed one function away.
            const isAlnum = c => !!c && ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'));
            const normU = s => (s || '').replace(/[\\s\\x1c-\\x1f\\x85\\ufeff]+/g, ' ').trim();
            const isUpsell = (raw) => {
                const s = normU(raw).toLowerCase(), n = normU(fam).toLowerCase();
                if (!s || !n) return false;
                for (const rawVerb of verbs) {
                    const verb = String(rawVerb).toLowerCase();
                    if (!verb) continue;
                    let i = s.indexOf(verb);
                    while (i !== -1) {
                        const end = i + verb.length;
                        const leftOk = i === 0 || !isAlnum(s[i - 1]);
                        const rightOk = end >= s.length || !isAlnum(s[end]);
                        if (leftOk && rightOk) {
                            const j = s.indexOf(n, end);
                            if (j !== -1 && j - end <= upsellWindow) return true;
                        }
                        i = s.indexOf(verb, i + 1);
                    }
                }
                return false;
            };
            const openable = btns.filter(b => !isUpsell(b.textContent || ''));
            // The model-selector trigger shows the currently-selected model name.
            let trigger = openable.find(b => famRe.test(b.textContent || ''));
            if (!trigger) trigger = openable.find(b => {
                const t = (b.textContent || '').toLowerCase();
                return t.includes('sonnet') || t.includes('haiku') || t.includes('claude');
            });
            if (trigger) { trigger.click(); return true; }
            return false;
        }""", {"fam": _claude_family, "verbs": list(UPSELL_VERBS),
               "upsellWindow": UPSELL_WINDOW})
        # The cadence clock is stamped on the ATTEMPT, not on a successful read.
        # A success-only stamp would leave the check permanently due the moment
        # the popover markup rotates, re-opening it on every run — one dead canary
        # turning into a per-run regression.
        _probe_saw_menu = False
        if dropdown_clicked:
            log("[setup_claude_dr] Step 1A OK: opened model popover")
            await asyncio.sleep(0.8)
            # ── Step 1B: pick the highest family member — ONLY when the model
            #              isn't already correct (no re-click, #744) ──
            # `verbs`/`upsellWindow` come from models.py rather than being
            # written into the JS, so the browser and the Python spec
            # (`is_upsell`, which the unit tests drive through
            # `pick_highest_model(..., drop_upsell=True)`) read the SAME list.
            # A literal here is how the reject rule drifted the first time.
            _pick_args = {"pin": pin_model, "below": step_below, "fam": _claude_family,
                          "triggerText": (_trigger_read or {}).get("trigger_text") or "",
                          "verbs": list(UPSELL_VERBS), "upsellWindow": UPSELL_WINDOW}
            _probe_args = {"fam": _claude_family, "verbs": list(UPSELL_VERBS),
                           "upsellWindow": UPSELL_WINDOW}
            if not model_ok:
                try:
                    for _attempt in range(8):
                        _picked = await page.evaluate(_pick_opus_js, _pick_args)
                        if _picked:
                            opus_selected = _picked.get("label")
                            _picked_version = _picked.get("version")
                            _model_changed = True
                            break
                        await asyncio.sleep(0.4)
                except Exception as _pe:
                    # A page.evaluate timeout/error during the poll must NOT
                    # propagate with the popover still open (R1) — fall into the
                    # FAIL branch below, which Escapes before returning False.
                    log(f"[setup_claude_dr] Step 1B poll errored ({_pe}) — dismissing popover", "WARN")
                    opus_selected = None
                if not opus_selected and _claude_family == _claude_primary \
                        and _claude_free_family:
                    # ── Step 1B†: is this a PLAN LIMIT rather than a miss? ──
                    # ⭐ "No family row was clickable" has two causes that want
                    # opposite responses, and until now they were indistinguish-
                    # able: a rollout/rename (transient — keep failing loudly so
                    # it gets fixed) versus an account whose plan does not
                    # include this family at all (permanent — nothing here will
                    # ever change, and failing forever means every run goes out
                    # on whatever the menu was left defaulting to, at whatever
                    # effort that model happened to carry).
                    #
                    # The probe separates them from the DOM itself: family rows
                    # present but ALL of them sales chips is the plan limit,
                    # stated by the page rather than inferred from a tier
                    # verdict a CUA pass guessed at. That matters — the tier
                    # read fails open to "assume Pro", so it cannot be what
                    # selects a model.
                    #
                    # ⛔ Guarded to the PRIMARY family: once we are already on
                    # the fallback there is nothing further to fall back to, and
                    # re-entering would re-open the same menu forever.
                    _limited = await _claude_plan_limited(page, _probe_opus_js, _probe_args)
                    if _limited:
                        log(f"[setup_claude_dr] Step 1B†: every '{_claude_family}' row in the "
                            f"menu is a sales prompt — this account's plan does not include "
                            f"{_claude_family}. Falling back to the '{_claude_free_family}' "
                            f"family (highest offered, same effort policy).", "INFO")
                        _claude_family = _claude_free_family
                        _pick_args = {**_pick_args, "fam": _claude_family,
                                      "pin": None, "below": None}
                        _probe_args = {**_probe_args, "fam": _claude_family}
                        try:
                            for _attempt in range(8):
                                _picked = await page.evaluate(_pick_opus_js, _pick_args)
                                if _picked:
                                    opus_selected = _picked.get("label")
                                    _picked_version = _picked.get("version")
                                    _model_changed = True
                                    break
                                await asyncio.sleep(0.4)
                        except Exception as _fe:
                            log(f"[setup_claude_dr] Step 1B† fallback poll errored ({_fe})",
                                "WARN")
                            opus_selected = None
                        if opus_selected:
                            # ⚠ RECORDED BEFORE Step 1C runs and before this
                            # function can return, because every later reader —
                            # the pre-send re-activation, the ladder's outcome
                            # probe, both CUA missions, the known-good ledger —
                            # asks this dict which family to assert on. A pick
                            # that is not recorded is a pick the very next pass
                            # reads as a regression and undoes.
                            _P2_ACTIVE_FAMILY["claude"] = _claude_family
                            _report_claude_plan_limit(_claude_primary, _claude_family)
                        else:
                            log(f"[setup_claude_dr] Step 1B†: no '{_claude_free_family}' row was "
                                f"clickable either — leaving the model untouched", "WARN")
                if opus_selected:
                    log(f"[setup_claude_dr] Step 1B OK: selected {opus_selected!r} "
                        f"(v{_picked_version})")
                else:
                    log(f"[setup_claude_dr] Step 1B FAIL: no '{_claude_family}' option found in "
                        f"the popover after polling (pin={pin_model!r} below={step_below!r}) — "
                        f"rollout/A-B difference, or the family was renamed?", "WARN")
                    # Never strand an OPEN dropdown over the composer (the bug
                    # screenshot) — dismiss it before bailing to the CUA fallback.
                    try:
                        await page.keyboard.press("Escape")
                        await asyncio.sleep(0.3)
                    except Exception:
                        pass
                    return False
                await asyncio.sleep(0.6)
            else:
                # ── Step 1B*: the family is right — is a NEWER one offered? ──
                # This is the whole "most recent model of the family" guarantee.
                # Claude.ai keeps an account on the previous flagship after a
                # release, so without this the pipeline sits on whatever it landed
                # on forever (it ran Opus 4.8 through the entire Opus-5 rollout).
                # We click ONLY when a STRICTLY higher version exists, which is
                # what makes re-clicking the current model (#744's loop)
                # impossible by construction. `_probe_saw_menu` decides nothing
                # here — it is telemetry for the cadence stamp.
                try:
                    _probe = None
                    for _attempt in range(3):
                        _probe = await page.evaluate(_probe_opus_js, _probe_args)
                        # A mounted menu with rows is the only trustworthy answer;
                        # anything else means "hasn't rendered yet" → retry.
                        if (_probe or {}).get("menu") and (_probe or {}).get("n"):
                            break
                        await asyncio.sleep(0.4)
                    _probe_saw_menu = bool((_probe or {}).get("menu") and (_probe or {}).get("n"))
                    _offered = (_probe or {}).get("highest")
                    # `model_trigger_ver` is None on a version-less label; any
                    # numbered row then counts as newer (we can't compare, and a
                    # named version is the more specific choice).
                    _cur = model_trigger_ver if isinstance(model_trigger_ver, (int, float)) else None
                    if isinstance(_offered, (int, float)) and (
                            _cur is None or _offered > _cur + 0.001):
                        # Select it through the ONE picker that exists, stepping
                        # everything below the newer version out of contention.
                        _up = await page.evaluate(
                            _pick_opus_js, {**_pick_args, "pin": _offered, "below": None})
                        if _up:
                            opus_selected = _up.get("label")
                            _picked_version = _up.get("version")
                            _model_changed = True
                            log(f"[setup_claude_dr] Step 1B* UPGRADE: {_claude_family} "
                                f"{_cur} → {_offered} ({opus_selected!r})")
                            await asyncio.sleep(0.6)
                        else:
                            log(f"[setup_claude_dr] Step 1B*: {_claude_family} {_offered} offered "
                                f"but not clickable — staying on {_cur}", "WARN")
                    elif _offered is not None:
                        log(f"[setup_claude_dr] Step 1B*: {_claude_family} {_cur} is already "
                            f"the highest offered ({_offered}) — no re-pick (#744)")
                    elif not _probe_saw_menu:
                        log(f"[setup_claude_dr] Step 1B*: model menu never mounted — cannot tell "
                            f"whether a newer {_claude_family} exists; keeping {_cur}", "WARN")
                except Exception as _ue:
                    # Advisory only: a probe failure must never break a run that
                    # already has the right family selected.
                    log(f"[setup_claude_dr] Step 1B* upgrade probe errored "
                        f"({type(_ue).__name__}) — keeping {_claude_family} "
                        f"{model_trigger_ver}", "WARN")

            # ── Step 1C: open the Effort submenu ───────────────────────
            # 2026-05-28: claude.ai split the old single "Opus 4.7 Adaptive"
            # option into Model (Opus 4.8) + an Effort submenu (Low/Medium/
            # High/Extra/Max) that ALSO holds the "Thinking" toggle. We open it
            # to reach BOTH Max and the Thinking toggle, and set Thinking BEFORE
            # picking Max (selecting an effort radio can collapse the submenu —
            # which is exactly why the old page-wide Adaptive-Thinking search
            # ran on a closed submenu and never found the toggle). Best-effort:
            # Effort/Thinking are quality knobs, not correctness gates, so a
            # miss here only WARNs — the CUA validate layer is the backstop.
            #
            # ⛔ SKIPPED on the periodic-probe path. When the popover was opened
            # purely to look for a newer model and the trigger ALREADY showed the
            # target effort, walking into the Effort submenu is exactly the
            # pointless churn the 2026-07-30 change removed — and re-entering the
            # submenu is how it ends up left open under the composer.
            # ⚠ …but NOT when the probe just switched models. Claude stores
            # effort PER MODEL, so the effort read off the trigger described the
            # OLD model; skipping here would leave the newly-selected one on its
            # default effort while telemetry reported effort confirmed. Effort is
            # the reasoning lever on this family, so that is a silent quality
            # downgrade for every run after the weekly upgrade.
            _effort_already_known = bool(_probe_due and _trigger_effort_ok
                                         and not _model_changed)
            if _effort_already_known:
                _effort_confirmed = True
                _effort_via = "trigger"
                log(f"[setup_claude_dr] Step 1C SKIPPED: effort '{_claude_effort}' already "
                    f"read off the trigger — the popover is open only for the model check")
            # ⭐⭐ 2026-08-17 — PICKING THE MODEL CLOSES THE WHOLE POPOVER. Proven
            # from a live capture: immediately after the Opus row is clicked the
            # page has NO open overlay at all and the trigger is back to
            # `aria-expanded="false"`. That is the entire content of the WARN this
            # step has been emitting — "Effort control not found (older UI /
            # popover closed?)" — and the question mark can come off: closed.
            #
            # Everything downstream then searched a popover that no longer
            # existed, failed to find Effort, warned, and let the run continue at
            # whatever effort the newly-selected model happened to default to,
            # while reporting the model selection as a success. Effort is stored
            # PER MODEL on this family, so the run after a model change is exactly
            # the run whose effort is least likely to be right.
            #
            # Re-open rather than reorder. Setting effort BEFORE the model would
            # also work and would save a popover, but only if an effort click
            # leaves the popover up — which the capture does not settle, and
            # guessing about it is how this step got here. Re-opening is correct
            # under either behaviour.
            if _model_changed and not _effort_already_known:
                if await _claude_reopen_model_popover(page):
                    log("[setup_claude_dr] Step 1C: re-opened the model popover — "
                        "picking a model closes it, and Effort lives inside it")
                else:
                    log("[setup_claude_dr] Step 1C: the model popover could not be "
                        "re-opened after the model change; effort stays as the new "
                        "model's default and is NOT reported as confirmed", "WARN")
            try:
                # 2026-08-04: MARK the Effort row, open it with a real hover +
                # click, and verify the submenu MOUNTED. The old version clicked
                # from inside page.evaluate and returned `true` for "a row was
                # found" — so `_eff_opened` said yes on every run while the
                # submenu stayed shut, and the corpus reads "Step 1C WARN: 'Max'
                # effort not found in submenu" nine times against ONE success.
                # Same defect as ChatGPT's model menu, same evidence, same fix.
                #
                # ⛔ 2026-08-05 (review of the tab-drift wave): NEVER A LINK. This is
                # the one `_SR_CLICK_MARK` writer the new ChatGPT row filter does not
                # cover, and it has the exact shape that navigated the ChatGPT tab —
                # a candidate set matched against `document`, chosen by a TEXT PREFIX,
                # then handed to a real Playwright press. `li` is in that set and
                # claude.ai's sidebar lists conversations as links; a thread titled
                # "Effort…" is therefore reachable, and pressing a link navigates.
                # Three arms, because `li` can relate to an anchor three ways: be one,
                # sit inside one, or wrap one.
                #
                # The length bound is the second half. A real Effort row reads "Effort
                # Max" — its own value plus a chevron. Claude's own reply, rendered as
                # a markdown bullet starting with "Effort", is also an `li`, and
                # marking one of those is a plausible reading of this step's corpus:
                # nine "'Max' effort not found in submenu" WARNs against one success,
                # i.e. a press that landed on something that was never a menu. 40 chars
                # is generous for a row and short for prose. Container-scoping would be
                # the stronger fix; it needs a live claude.ai capture we do not have, so
                # the rejected candidates are reported instead — the next run's log is
                # what will settle it.
                _eff_mark = {} if _effort_already_known else await page.evaluate("""(P) => {
                    for (const el of document.querySelectorAll('[' + P.attr + ']')) {
                        el.removeAttribute(P.attr);
                    }
                    // Icon-font ligatures land in the private-use area: they are
                    // invisible on screen but present in text, and they are why the
                    // log read the row as 'effortmax' plus a stray glyph. It also
                    // makes the length bound below measure real characters.
                    const norm = s => (s || '')
                        .replace(/[\\ue000-\\uf8ff]/g, ' ')
                        .replace(/\\s+/g, ' ').trim().toLowerCase();
                    const linky = el => (el.tagName === 'A' && el.getAttribute('href'))
                        || (el.closest && el.closest('a[href]'))
                        || (el.querySelector && el.querySelector('a[href]'));
                    const rejected = [];
                    let trigger = null, via = '';
                    // ⭐⭐ 2026-08-17 — THE TEST ID, FIRST. The comment below asked
                    // for "container-scoping … it needs a live claude.ai capture
                    // we do not have". The capture arrived, and it is better than
                    // a container: the row carries `data-testid="effort-menu-
                    // trigger"` and every option under it is likewise named. An
                    // exact id retires this whole hazard class at once — no text
                    // prefix, no length bound, no anchor arms, nothing that a
                    // sidebar conversation or a markdown bullet can satisfy.
                    if (P.testid) {
                        for (const el of document.querySelectorAll(
                                '[data-testid="' + P.testid + '"]')) {
                            if (!el.getClientRects().length) continue;
                            trigger = el; via = 'testid'; break;
                        }
                    }
                    // The text search stays as the FALLBACK, unchanged, for an
                    // older layout that predates the id. It keeps its guards: they
                    // are what make it survivable, and it is now reached only when
                    // the exact hook is absent.
                    if (!trigger) {
                        for (const el of document.querySelectorAll(
                                '[role="menuitem"], button, [role="option"], li')) {
                            if (!el.getClientRects().length) continue;
                            const t = norm(el.textContent);
                            if (!t.startsWith('effort')) continue;
                            // The Effort row shows its current value + a submenu chevron.
                            if (linky(el)) { rejected.push(['link', t.slice(0, 60)]); continue; }
                            if (t.length > 40) { rejected.push(['long', t.slice(0, 60)]); continue; }
                            trigger = el; via = 'text';
                            break;
                        }
                    }
                    // ⭐ 2026-08-17 — THE ANCESTRY IS CAPTURED **HERE**, while the
                    // row is in hand. The diagnostic below used to rebuild it by
                    // re-reading the marker, and `_sr_real_click` removes that
                    // marker in a `finally` — by contract, on every path. So the
                    // half of the diagnostic that says WHAT WAS PRESSED could
                    // never once produce data: it printed `"chain": []` and
                    // `"marked": false` on every failure, including the run where
                    // the press had landed on exactly the right row.
                    const desc = el => {
                        if (!el || !el.tagName) return null;
                        const d = {tag: el.tagName.toLowerCase()};
                        const r = el.getAttribute && el.getAttribute('role');
                        if (r) d.role = r;
                        if (el.id) d.id = String(el.id).slice(0, 40);
                        const cls = String((el.getAttribute
                                            && el.getAttribute('class')) || '')
                            .trim().split(' ').filter(Boolean).slice(0, 3);
                        if (cls.length) d.cls = cls.map(c => c.slice(0, 40));
                        if (el.getAttributeNames) {
                            for (const a of el.getAttributeNames()) {
                                if (a.indexOf('data-radix') === 0 || a === 'data-state'
                                    || a === 'data-side' || a.indexOf('data-testid') === 0) {
                                    (d.data = d.data || {})[a] =
                                        String(el.getAttribute(a)).slice(0, 40);
                                }
                            }
                        }
                        return d;
                    };
                    if (trigger) {
                        trigger.setAttribute(P.attr, P.value);
                        const chain = [];
                        for (let el = trigger, i = 0; el && i < 8; i++, el = el.parentElement) {
                            chain.push(desc(el));
                        }
                        return {marked: true, via: via,
                                text: norm(trigger.textContent).slice(0, 60),
                                chain: chain,
                                rejected: rejected.slice(0, 5)};
                    }
                    return {marked: false, via: '', text: '', chain: [],
                            rejected: rejected.slice(0, 5)};
                }""", {"attr": _SR_CLICK_MARK, "value": "claude-effort",
                       "testid": _CLAUDE_EFFORT_TRIGGER_TESTID}) or {}
                _eff_marked = bool(_eff_mark.get("marked"))
                if _eff_mark.get("rejected"):
                    log(f"[setup_claude_dr] Step 1C: refused "
                        f"{len(_eff_mark['rejected'])} 'Effort…' candidate(s) — "
                        f"{json.dumps(_eff_mark['rejected'], ensure_ascii=False)}", "INFO")
                # 'open' | 'maybe' | 'closed' — see `_claude_effort_submenu_verdict`.
                _eff_state, _eff_opened = "closed", False
                if _eff_marked:
                    log(f"[setup_claude_dr] Step 1C: marked the Effort row "
                        f"{_eff_mark.get('text','')!r} (via {_eff_mark.get('via')})")
                    _how = await _sr_real_click(page, "claude-effort",
                                                tag="[setup_claude_dr]",
                                                hover_first=True)
                    # POLL for the submenu's own rows. "The trigger was pressed"
                    # is not "the submenu is open", and the difference is the
                    # nine WARNs: everything downstream searched a menu that had
                    # never mounted and reported its own target missing.
                    #
                    # ⭐⭐ 2026-08-17 — ASKED OF THE OVERLAYS, NOT THE DOCUMENT.
                    # The previous poll listed every short visible row on the
                    # page, capped it at 20, and looked for an effort word among
                    # them. Claude's submenu is portalled to the END of `<body>`
                    # and the sidebar fills the cap first, so on a real run the
                    # gate answered "no submenu" while the diagnostic printed on
                    # the very next line listed the submenu and all five of its
                    # rungs. Effort silently stayed at the model's default.
                    _eff_probe = {}
                    for _try in range(8):
                        if _try:
                            await asyncio.sleep(0.25)
                        try:
                            _eff_probe = await page.evaluate(
                                _CLAUDE_EFFORT_SUBMENU_JS,
                                {"trigTestid": _CLAUDE_EFFORT_TRIGGER_TESTID,
                                 "optTestid": _claude_effort_option_testid(
                                     _claude_effort)}) or {}
                        except Exception:
                            _eff_probe = {}
                        _eff_state = _claude_effort_submenu_verdict(_eff_probe)
                        if _eff_state == "open":
                            break
                    _eff_opened = _eff_state == "open"
                    if not _eff_opened:
                        # ⭐ 2026-08-05 — SAY WHERE THE ROW WE PRESSED ACTUALLY LIVES.
                        # This step reports "'Max' not found in submenu" nine times
                        # against one success, and that message describes the search
                        # AFTER the press rather than the press itself — so it has
                        # never once identified what was pressed.
                        #
                        # ⛔ STRUCTURE ONLY — tags, roles, ids, a few class names, the
                        # framework's own state attributes. Deliberately NOT raw HTML
                        # and not element text beyond short control labels: the
                        # sidebar and the transcript are the user's own conversations,
                        # and a diagnostic has no business copying those into a log.
                        #
                        # ⛔ THE ANCESTRY IS NOT RE-READ HERE. It is carried down from
                        # the marking pass above, because `_sr_real_click` removes the
                        # marker in a `finally` — so the old `querySelector` on that
                        # attribute was reading an element that is gone by contract,
                        # and printed `"chain": [], "marked": false` on every single
                        # failure regardless of what had been pressed.
                        try:
                            _eff_dbg = await page.evaluate("""() => {
                                const desc = el => {
                                    if (!el || !el.tagName) return null;
                                    const d = {tag: el.tagName.toLowerCase()};
                                    const r = el.getAttribute && el.getAttribute('role');
                                    if (r) d.role = r;
                                    if (el.id) d.id = String(el.id).slice(0, 40);
                                    const cls = (el.getAttribute && el.getAttribute('class') || '')
                                        .split(/\\s+/).filter(Boolean).slice(0, 3);
                                    if (cls.length) d.cls = cls.map(c => c.slice(0, 40));
                                    if (el.getAttributeNames) {
                                        for (const a of el.getAttributeNames()) {
                                            if (a.indexOf('data-radix') === 0 || a === 'data-state'
                                                || a === 'data-side' || a.indexOf('data-testid') === 0) {
                                                (d.data = d.data || {})[a] =
                                                    String(el.getAttribute(a)).slice(0, 40);
                                            }
                                        }
                                    }
                                    return d;
                                };
                                const out = {overlays: []};
                                // Every visible overlay-shaped container, so the
                                // scope can be written against something real.
                                const seen = new Set();
                                for (const c of document.querySelectorAll(
                                        '[role="menu"], [role="dialog"], [role="listbox"], '
                                        + '[data-radix-popper-content-wrapper], [data-radix-menu-content]')) {
                                    if (!c.getClientRects().length) continue;
                                    if (seen.has(c)) continue;
                                    seen.add(c);
                                    const rows = [...c.querySelectorAll(
                                        '[role="menuitem"], [role="menuitemradio"], [role="option"], button, li')]
                                        .filter(e => e.getClientRects().length);
                                    out.overlays.push({
                                        box: desc(c),
                                        rows: rows.length,
                                        // Short control labels only — a menu row, never prose.
                                        labels: rows.map(e => (e.textContent || '')
                                                .replace(/\\s+/g, ' ').trim())
                                            .filter(t => t && t.length <= 28).slice(0, 12),
                                    });
                                }
                                return out;
                            }""") or {}
                        except Exception as _ed_e:
                            _eff_dbg = {"error": str(_ed_e)[:120]}
                        if isinstance(_eff_dbg, dict):
                            _eff_dbg["pressed_chain"] = _eff_mark.get("chain") or []
                        log(f"[setup_claude_dr] Step 1C DIAG (submenu {_eff_state}) — "
                            f"{json.dumps(_eff_dbg, ensure_ascii=False)[:3000]}", "WARN")
                    if _eff_opened:
                        log(f"[setup_claude_dr] Step 1C: Effort submenu opened via a "
                            f"{_how or 'failed'} press")
                    elif _eff_state == "maybe":
                        # ⭐ PROCEED. An overlay other than the parent popover is up
                        # and nothing in it was recognised — which is a description
                        # of the page, not a verdict on the run. Step 1C' is scoped
                        # to that same overlay and verifies its own press before
                        # claiming anything, so letting it try converts a blind veto
                        # into a named diagnosis. The gate must not be able to
                        # overrule a picker that checks its own work.
                        log(f"[setup_claude_dr] Step 1C: the Effort row was pressed "
                            f"({_how or 'no press landed'}) and an overlay is open but "
                            f"unrecognised — trying the submenu anyway; the row picker "
                            f"verifies its own press", "WARN")
                    else:
                        log(f"[setup_claude_dr] Step 1C WARN: the Effort row was pressed "
                            f"({_how or 'no press landed'}) but no submenu mounted within "
                            f"2s — visible overlays were "
                            f"{json.dumps((_eff_probe or {}).get('overlays') or [], ensure_ascii=False)[:600]}",
                            "WARN")
                if _eff_state != "closed":
                    await asyncio.sleep(0.5)
                    # ── Step 1D: toggle "Thinking" ON (inside the submenu) ──
                    # #745: the toggle is labeled "Thinking" (NOT "Adaptive
                    # Thinking" — that old label is why the page-wide search
                    # missed it) and lives in the just-opened Effort submenu.
                    # State-aware: only click when it reads off.
                    # (2026-07-30) POLICY-GATED. Opus 5 removed this toggle, so
                    # with `thinking: False` the probe is skipped rather than
                    # hunting a control that cannot exist and WARNing on every
                    # run. Kept rather than deleted because the policy dict is
                    # the lever: an older Opus, or a future model that reinstates
                    # the toggle, re-arms this by flipping one value.
                    # ⛔ The Thinking search below is PAGE-WIDE, so it runs only
                    # on a confirmed submenu. Widening the effort attempt to the
                    # 'maybe' state must not also widen an unscoped click.
                    _think_probed = bool(_claude_wants_thinking and _eff_opened)
                    _think = {} if not _think_probed else await page.evaluate("""() => {
                        const norm = s => (s || '').replace(/\\s+/g, ' ').trim().toLowerCase();
                        const vis = el => el.getClientRects().length > 0;
                        const isThinking = el => {
                            const t = norm(el.textContent), a = norm(el.getAttribute('aria-label'));
                            return t === 'thinking' || a === 'thinking' || a.startsWith('thinking') ||
                                   t.startsWith('adaptive thinking') || a.startsWith('adaptive thinking') ||
                                   t.startsWith('extended thinking');
                        };
                        const isOn = el => el.getAttribute('aria-checked') === 'true' ||
                                           el.getAttribute('aria-pressed') === 'true' ||
                                           el.dataset.state === 'checked' || el.dataset.state === 'on';
                        const all = [...document.querySelectorAll('[role="switch"], [role="checkbox"], [role="menuitemcheckbox"], button, label, div')].filter(vis);
                        // Prefer an explicit switch/checkbox whose OWN label is "Thinking".
                        let sw = all.find(el => {
                            const r = el.getAttribute('role');
                            return (r === 'switch' || r === 'checkbox' || r === 'menuitemcheckbox') && isThinking(el);
                        });
                        // Else: a "Thinking"-labelled row that CONTAINS a switch.
                        if (!sw) {
                            const row = all.find(el => {
                                const t = norm(el.textContent);
                                return (t === 'thinking' || t.startsWith('thinking') || t.includes('think for more complex')) &&
                                       el.querySelector('[role="switch"], [role="checkbox"], button');
                            });
                            if (row) sw = row.querySelector('[role="switch"], [role="checkbox"], button');
                        }
                        if (!sw) return { found: false };
                        if (!isOn(sw)) { sw.click(); return { found: true, toggled: true }; }
                        return { found: true, toggled: false };
                    }""")
                    if not _think_probed:
                        # No toggle on this model family — nothing to confirm and
                        # nothing wrong. Deliberately silent: a WARN here is what
                        # made a healthy run look broken every single time.
                        if _claude_wants_thinking:
                            log("[setup_claude_dr] Step 1D SKIPPED: the Effort "
                                "submenu was not confirmed and the Thinking search "
                                "is page-wide — it does not run against a page whose "
                                "submenu may never have opened", "INFO")
                    elif not _think.get("found"):
                        log("[setup_claude_dr] Step 1D WARN: 'Thinking' toggle not found in Effort submenu — UI moved/relabelled it", "WARN")
                    else:
                        _thinking_confirmed = True  # found ⇒ ON (just-toggled or already-on)
                        log(f"[setup_claude_dr] Step 1D OK: Thinking {'just enabled' if _think.get('toggled') else 'already on'}")
                    await asyncio.sleep(0.3)
                    # ── Step 1C': set Effort = Max (state-aware) ──
                    # ⭐⭐ 2026-08-06 — ROOT CAUSE OF THE NINE-IN-TEN, from a live
                    # capture of this exact popover. The old body compared
                    # `norm(el.textContent) === 'max'` — EXACT equality — and the
                    # real row's text is `Max` followed by TWO private-use
                    # codepoints (U+E08F U+E03B), Claude's icon font rendering a
                    # check and a chevron as text. So the comparison could never
                    # be true and the row was never found: that is the whole
                    # "'Max' effort not found in submenu" corpus, nine against one.
                    # The one success was a run that took the already-Max path.
                    #
                    # Measured from the capture: the other tiers ('Low', 'Medium',
                    # 'HighDefault', 'Extra') carry NO private-use glyphs, so the
                    # ligature rides on the SELECTED row — which is exactly why
                    # the failure looked intermittent rather than total.
                    #
                    # Same defect family as the NotebookLM audio menu, where a row
                    # could not be read past its icon ligature. Stripping the
                    # private-use area is the shared cure.
                    #
                    # Second half: the search was document-wide. The Effort submenu
                    # is a SIBLING `[role="menu"]`, not nested inside the model
                    # popover, and the popover carries its own 'EffortMax' rows —
                    # so a page-wide scan is choosing between two menus. Scope to
                    # the menu that does NOT carry the Effort trigger.
                    _eff_set = await page.evaluate("""(P) => {
                        // Icon-font ligatures land in the Unicode private-use area
                        // and are invisible in a screenshot but present in text.
                        const norm = s => (s || '')
                            .replace(/[\\ue000-\\uf8ff]/g, ' ')
                            .replace(/\\s+/g, ' ').trim().toLowerCase();
                        const menus = [...document.querySelectorAll(
                                '[role="menu"], [data-radix-menu-content]')]
                            .filter(el => el.getClientRects().length > 0);
                        // The submenu is a visible menu WITHOUT the trigger in it.
                        // ⭐ 2026-08-17 — EVERY candidate is searched, not just the
                        // first. `find` picked ONE menu and, if the row was not in
                        // it, reported the row missing from a page that was showing
                        // it — the same "chose the wrong sink" shape as the gate
                        // above. Falls back to the newest menu, then the document,
                        // so an older UI without the test id still resolves.
                        const cands = menus.filter(m =>
                            !m.querySelector('[data-testid="' + P.trigTestid + '"]'));
                        // ⛔ 2026-08-17 — NO FALLBACK INTO THE TRIGGER'S OWN MENU.
                        // This used to end `|| menus[menus.length - 1]`, which is
                        // reached in exactly one situation: every visible menu
                        // holds the Effort trigger, i.e. the submenu is NOT open.
                        // The popover DISPLAYS the selected tier ('EffortMax' in
                        // the live capture) and the row search includes `div`, so
                        // the fallback would mark the element rendering that value
                        // — pressing it re-opens the submenu and changes no tier,
                        // and the caller would report the tier as set. Searching
                        // nothing is the honest answer when nothing is open.
                        const pools = cands.length
                            ? cands
                            : (menus.length ? [] : [document]);
                        // ⛔ AND THE TEXT SEARCH IS OFF ON THE DOCUMENT. The last
                        // pool exists for a layout with no menu-shaped container at
                        // all; a test id is globally unique and safe to resolve
                        // there, while matching a page-wide row by the word 'Max'
                        // is the decoy press this file has already paid for once —
                        // Claude's own reply renders list items reading exactly
                        // that.
                        const allowText = cands.length > 0;
                        const rowsIn = c => [...c.querySelectorAll('[role="menuitem"], [role="menuitemradio"], [role="option"], button, li, div')]
                            .filter(el => el.getClientRects().length > 0);
                        // ⭐⭐ 2026-08-17 — THE OPTION'S OWN TEST ID, FIRST. Every
                        // rung is named (`effort-option-low|medium|high|xhigh|max`),
                        // which addresses the row directly instead of matching its
                        // rendered text. That is what makes the whole ligature
                        // problem below unreachable rather than merely handled: the
                        // private-use glyphs that defeated an exact text match for
                        // nine runs out of ten are not in an attribute.
                        //
                        // ⛔ Still scoped, and still checked against the submenu.
                        // An id is a stronger name, not a container — and the
                        // parent popover carries an 'EffortMax' row of its own.
                        // ⛔ 2026-08-17 — THE WANTED WORD COMES FROM THE POLICY.
                        // This read 'max' as a literal while the test id beside it
                        // was derived from the policy, so the two halves of one
                        // search disagreed the moment the policy said anything but
                        // 'max' — and the text half is exactly the half that runs on
                        // the older layout with no ids. `family-only-models` is the
                        // standing rule: no tier literals in a selection path.
                        const want = String(P.word || '').toLowerCase();
                        // 'HighDefault' is a real captured label: the default rung
                        // carries a suffix, so an exact match alone cannot see it.
                        const isWanted = el => {
                            const t = norm(el.textContent);
                            return !!want && (t === want || t === want + ' effort'
                                              || t === want + 'default');
                        };
                        let pick = null, scope = null, items = [];
                        for (const c of pools) {
                            const rows = rowsIn(c);
                            let hit = null;
                            if (P.optTestid) {
                                hit = rows.find(el =>
                                    el.getAttribute('data-testid') === P.optTestid);
                            }
                            // The text search stays as the fallback for an older
                            // layout, with its ligature stripping intact.
                            if (!hit && allowText) hit = rows.find(isWanted);
                            if (!items.length) items = rows;
                            if (hit) { pick = hit; scope = c; items = rows; break; }
                        }
                        if (!pick) {
                            return {set: null, scoped: cands.length > 0,
                                    menus: menus.length, cands: cands.length,
                                    saw: items.map(el => norm(el.textContent))
                                        .filter(t => t && t.length <= 24).slice(0, 10)};
                        }
                        const already = pick.getAttribute('aria-checked') === 'true' ||
                                        pick.dataset.state === 'checked' || pick.dataset.state === 'on';
                        // ⛔ 2026-08-17 — MARK, DO NOT CLICK. This was the last
                        // `el.click()` left in a menu path: a synthetic click
                        // dispatches a click event and nothing else, and this
                        // component library binds its rows on pointerdown. The
                        // corpus already paid for the identical mistake twice —
                        // ChatGPT's model trigger and this step's own submenu
                        // opener — and both times the tell was the same, a report
                        // of success from a page that had not changed.
                        if (!already) pick.setAttribute(P.attr, P.value);
                        return {set: already ? want + ' (already)' : 'marked',
                                already: already,
                                // WHICH row was chosen, so the log names it and a
                                // test can assert identity rather than "something
                                // was chosen" — the distinction that let a decoy
                                // outside every menu be pressed once before.
                                picked: norm(pick.textContent).slice(0, 40),
                                via: P.optTestid &&
                                    pick.getAttribute('data-testid') === P.optTestid
                                    ? 'testid' : 'text',
                                scoped: scope !== document, menus: menus.length,
                                cands: cands.length};
                    }""", {"trigTestid": _CLAUDE_EFFORT_TRIGGER_TESTID,
                           "optTestid": _claude_effort_option_testid(_claude_effort),
                           "word": str(_claude_effort or "").lower(),
                           "attr": _SR_CLICK_MARK,
                           "value": "claude-effort-option"}) or {}
                    # The row report is what makes the next drift diagnosable from
                    # the log alone, instead of needing another capture.
                    if not _eff_set.get("set"):
                        log(f"[setup_claude_dr] Step 1C: no {_claude_effort!r} row in "
                            f"the submenu — menus={_eff_set.get('menus')} "
                            f"scoped={_eff_set.get('scoped')} rows="
                            f"{json.dumps(_eff_set.get('saw') or [], ensure_ascii=False)}",
                            "WARN")
                    _eff_already = bool(_eff_set.get("already"))
                    _eff_via_hook = _eff_set.get("via") or ""
                    _eff_picked = str(_eff_set.get("picked") or "")
                    _eff_set = _eff_set.get("set")
                    # ⭐⭐ RESTRUCTURED after a mutation survivor. This used to be
                    # a chain of `if not …: _eff_set = None` clears, and a mutant
                    # that neutered the verification left every test green: the
                    # tests could see that the read was MENTIONED, not that its
                    # answer decided anything. The verdict is now DERIVED from the
                    # readings by a pure function, so removing a term changes a
                    # value a unit test holds rather than deleting a statement
                    # nothing observes. Same lesson as the last wave's C8/D1/D2.
                    _eff_pressed, _eff_checked = False, False
                    if _eff_set and not _eff_already:
                        _eff_pressed = bool(await _sr_real_click(
                            page, "claude-effort-option", tag="[setup_claude_dr]"))
                        if _eff_pressed:
                            await asyncio.sleep(0.4)
                            _eff_ok = {}
                            try:
                                _eff_ok = await page.evaluate(
                                    _CLAUDE_EFFORT_CHECKED_JS,
                                    {"optTestid": _claude_effort_option_testid(
                                        _claude_effort),
                                     "word": str(_claude_effort or "").lower()}) or {}
                            except Exception:
                                _eff_ok = {}
                            _eff_checked = bool(_eff_ok.get("checked"))
                            if not _eff_checked:
                                log(f"[setup_claude_dr] Step 1C WARN: pressed the "
                                    f"{_claude_effort!r} row but it did not become "
                                    f"the selected effort (read "
                                    f"{_eff_ok.get('found') and 'unchecked' or 'nothing'})"
                                    f" — NOT claiming the tier was set", "WARN")
                        else:
                            log(f"[setup_claude_dr] Step 1C WARN: the "
                                f"{_claude_effort!r} row could not be pressed", "WARN")
                    _eff_set = _claude_effort_is_set(
                        marked=bool(_eff_set), already=_eff_already,
                        pressed=_eff_pressed, checked=_eff_checked)
                    if _eff_set:
                        _effort_confirmed = True
                        _effort_via = "submenu"
                        log(f"[setup_claude_dr] Step 1C OK: Effort "
                            f"{_claude_effort!r} "
                            f"{'(already)' if _eff_already else 'selected'} "
                            f"via {_eff_via_hook} (row {_eff_picked!r})")
                    else:
                        log(f"[setup_claude_dr] Step 1C WARN: effort "
                            f"{_claude_effort!r} was NOT confirmed in the submenu "
                            f"— the run proceeds at whatever the model's default "
                            f"is, and reports it as unconfirmed", "WARN")
                elif not _effort_already_known:
                    log("[setup_claude_dr] Step 1C WARN: Effort control not found "
                        "(the popover closes when a model is picked — it should "
                        "have been re-opened above) — reported as unconfirmed", "WARN")
            except Exception as _ee:
                log(f"[setup_claude_dr] Step 1C/1D errored: {_ee}", "WARN")
            await asyncio.sleep(0.3)
            # Dismiss the model popover so the tools menu + input are clickable.
            # #751 (2026-06-02): a SINGLE Escape closed only the inner Effort
            # submenu (opened in Step 1C), leaving the PARENT model popover open
            # over the composer — the #745 restructure added the nested submenu
            # but kept the single Escape. Press TWICE: the 1st closes the submenu
            # (if still open), the 2nd closes the model popover. An Escape with
            # nothing open is a harmless no-op, so this is safe on every path here.
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.2)
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.3)
            except Exception:
                pass
        elif not _skip_popover:
            # Couldn't open the popover. (A deliberate skip is NOT this branch —
            # there the knobs were already confirmed off the trigger, and warning
            # about a popover we chose not to open would be a false alarm.)
            # If the family is already selected the run is still correct (the
            # family is the only hard gate here); the Effort quality knob falls to
            # the CUA validate layer. If the family is NOT selected and we can't
            # even open the picker, the selector list is stale — fail fast to CUA.
            if model_ok:
                log(f"[setup_claude_dr] Step 1A WARN: couldn't open model popover — the trigger "
                    f"already reads '{_claude_family}' so the run is correct; CUA validate will "
                    f"confirm the quality knobs", "WARN")
            else:
                log("[setup_claude_dr] Step 1A FAIL: model popover button not found — selector list likely stale", "WARN")
                return False
        # Stamp the cadence clock for ANY run that tried to open the popover,
        # including one where the button was missing. See record_probe: stamping
        # only on success is what would turn a rotated popover into a per-run
        # re-open, and the whole point of the cadence is a bounded cost.
        if _probe_due:
            # ⚠ A FAILED STAMP MUST NOT BE SILENT. record_probe swallows every
            # write error (read-only home, full disk, bad perms) and returns
            # False. With no stamp the check is due again next run — so the model
            # popover would open on EVERY run, which is precisely the behaviour
            # the 2026-07-30 skip was added to stop, reintroduced invisibly on
            # exactly the machines whose disk state nobody can see. Log it once
            # per process: enough to diagnose, not enough to spam.
            global _PROBE_STAMP_WARNED
            if not record_probe("claude", saw_menu=_probe_saw_menu) and not _PROBE_STAMP_WARNED:
                _PROBE_STAMP_WARNED = True
                log(f"[setup_claude_dr] could not record the model-check timestamp "
                    f"({overlay_path()}) — the periodic check will be due "
                    f"again next run, so the model popover will keep opening. Check that "
                    f"the directory is writable.", "WARN")

        # ── Step 3: open tools menu and enable Research ────────────────
        # Precise selectors first — the old `button[aria-label*="+"]`
        # wildcard was matching unrelated buttons ("New chat", etc.)
        # and occasionally opened the wrong surface.
        # 2026-05-29 (#708): these precise selectors matched NOTHING on every
        # prod run (backend.log Step 3A FAIL x100%), so Research never enabled
        # via DOM → setup returned False → the CUA fallback fired needlessly on
        # EVERY run. The CUA fallback proved the real control is the composer's
        # "+" button. So after the precise selectors we add a composer-scoped
        # "+" detector, and on total failure we DUMP the composer buttons so a
        # single E2E reveals the exact selector (no more blind selector-guessing).
        tools_opened = False
        tools_sel_used = None
        for sel in ['button[aria-label="Open tools menu"]',
                    'button[aria-label*="tools menu"]',
                    'button[aria-label*="Tools menu"]',
                    'button[data-testid*="tools"]',
                    'button[aria-label*="attach"]',
                    'button[aria-haspopup="menu"][aria-label*="tools"]']:
            try:
                btn = await page.query_selector(sel)
                if btn:
                    await btn.click()
                    await asyncio.sleep(0.6)
                    tools_opened = True
                    tools_sel_used = sel
                    break
            except Exception:
                continue
        if not tools_opened:
            # Composer-scoped "+" detector. Bounded to the editor's container
            # (NOT the whole page like the old wildcard), and explicitly skips
            # the model selector (opus/sonnet/haiku text) and the send button.
            try:
                plus_label = await page.evaluate("""() => {
                    const ce = document.querySelector('div[contenteditable="true"], .ProseMirror, [role="textbox"]');
                    // No composer found → do NOT click anything page-wide (would
                    // risk a sidebar "+"/menu button). Bail so the diagnostic
                    // dump runs and the CUA fallback handles it instead.
                    if (!ce) return null;
                    let scope = ce;
                    for (let i = 0; i < 5 && scope && scope.parentElement; i++) scope = scope.parentElement;
                    const root = scope || ce;   // never document.body — stay inside the composer subtree
                    const btns = [...root.querySelectorAll('button')].filter(b => b.offsetParent !== null);
                    const isModel = s => /opus|sonnet|haiku|claude|model/i.test(s || '');
                    const isSend  = s => /\\bsend\\b|submit/i.test(s || '');
                    // Never the model-selector or the send/submit button (check
                    // BOTH text and aria-label so an icon-only Send is excluded).
                    const skip = b => {
                        const a = (b.getAttribute('aria-label') || '');
                        const t = (b.textContent || '').trim();
                        return isModel(t) || isModel(a) || isSend(t) || isSend(a);
                    };
                    // Primary: an icon button that opens a menu.
                    let cand = btns.find(b => {
                        const pop = b.getAttribute('aria-haspopup');
                        return (pop === 'menu' || pop === 'true') && !skip(b);
                    });
                    // Fallback: an add/attach/tools/plus-labelled button.
                    if (!cand) cand = btns.find(b => {
                        if (skip(b)) return false;
                        const a = (b.getAttribute('aria-label') || '').toLowerCase();
                        const t = (b.textContent || '').trim();
                        return a.includes('attach') || a.includes('tool') || a.includes('add') ||
                               a.includes('plus') || a.includes('upload') || a.includes('more') || t === '+';
                    });
                    if (cand) { cand.click(); return (cand.getAttribute('aria-label') || cand.textContent || '+').trim().slice(0, 40); }
                    return null;
                }""")
                if plus_label:
                    await asyncio.sleep(0.6)
                    tools_opened = True
                    tools_sel_used = f"composer-plus[{plus_label}]"
            except Exception as _pe:
                log(f"[setup_claude_dr] Step 3A '+' detector errored: {_pe}", "WARN")
        if tools_opened:
            log(f"[setup_claude_dr] Step 3A OK: opened tools menu via {tools_sel_used}")
        else:
            log("[setup_claude_dr] Step 3A FAIL: tools menu button not found — aria-labels rotated or language changed", "WARN")
            # Diagnostic: dump the composer's buttons so the next E2E pins the
            # exact selector. Self-documenting — replaces blind selector-guessing.
            try:
                _btn_dump = await page.evaluate("""() => {
                    const ce = document.querySelector('div[contenteditable="true"], .ProseMirror, [role="textbox"]');
                    let scope = ce;
                    for (let i = 0; i < 5 && scope && scope.parentElement; i++) scope = scope.parentElement;
                    const root = scope || document.body;
                    return [...root.querySelectorAll('button')].filter(b => b.offsetParent !== null).slice(0, 25).map(b => ({
                        al: (b.getAttribute('aria-label') || '').slice(0, 40),
                        t: (b.textContent || '').trim().slice(0, 24),
                        pop: b.getAttribute('aria-haspopup') || '',
                        tid: b.getAttribute('data-testid') || ''
                    }));
                }""")
                log(f"[setup_claude_dr] Step 3A composer-button dump (fix selector from this): {json.dumps(_btn_dump, ensure_ascii=False)}", "WARN")
            except Exception as _de:
                # #739: this dump was silently swallowed, so the selector-
                # rotation diagnostic it was meant to provide never appeared —
                # surface WHY it failed so the DOM path can finally self-heal.
                log(f"[setup_claude_dr] Step 3A composer-button dump failed: {_de}", "WARN")
        research_enabled = False
        if tools_opened:
            # State-aware + accept label variations ("Research", "Research
            # tool", "Deep research"). Only clicks when not already on.
            # #751 (2026-06-02): Step 3B failed on 100% of runs ("Research toggle
            # not found (selectors rotated)") → CUA recovered it every time. Root
            # cause: the role list omitted role="menuitemcheckbox" (the standard
            # ARIA role for a toggle menu-item, which is what claude.ai now uses
            # for Research), and the text match wasn't whitespace-normalized.
            # Broaden the roles + normalize, and add the row-CONTAINS-a-switch
            # fallback (same pattern as the Thinking toggle in Step 1D) so a
            # Research row that wraps its toggle is still handled. State-aware:
            # only clicks when not already on.
            research_enabled = await page.evaluate("""() => {
                const norm = s => (s || '').replace(/\\s+/g, ' ').trim().toLowerCase();
                const vis = el => el.offsetParent !== null;
                const isResearch = el => {
                    const t = norm(el.textContent), a = norm(el.getAttribute('aria-label'));
                    // EXACT labels only for the direct match — a prefix like
                    // /^research\\b/ would also catch "Research history" /
                    // "Research projects" nav rows and toggle the wrong thing
                    // (#751 review blocker). The row fallback below handles a
                    // Research TOOL row that carries a description suffix.
                    const hit = s => s === 'research' || s === 'research tool' ||
                                     s === 'deep research' || s === 'research mode';
                    return hit(t) || hit(a);
                };
                const isOn = el => el.getAttribute('aria-checked') === 'true' ||
                                   el.getAttribute('aria-pressed') === 'true' ||
                                   el.dataset.state === 'checked' || el.dataset.state === 'on';
                const items = [...document.querySelectorAll(
                    '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"], button, [role="switch"], [role="checkbox"], label'
                )].filter(vis);
                // Direct: the Research item / toggle itself.
                let target = items.find(isResearch);
                // Fallback: a "Research"-labelled row that CONTAINS a switch.
                if (!target) {
                    const row = items.find(el => {
                        const t = norm(el.textContent);
                        // A "Research"-labelled row that CONTAINS a switch — but
                        // NOT a "Research history"/"Research projects"-style nav
                        // row (#751 review: exclude known non-tool segments so a
                        // prefix match can't toggle the wrong control).
                        const looksResearchTool =
                            (/^research\\b/.test(t) || t.includes('deep research')) &&
                            !/\\b(history|projects|settings|memory|past|recent)\\b/.test(t);
                        return looksResearchTool &&
                               el.querySelector('[role="switch"], [role="checkbox"], button');
                    });
                    if (row) target = row.querySelector('[role="switch"], [role="checkbox"], button') || row;
                }
                if (!target) return false;
                if (!isOn(target)) target.click();
                return true;
            }""")
            await asyncio.sleep(0.4)
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.3)
            except Exception:
                pass
        if research_enabled:
            log("[setup_claude_dr] Step 3B OK: Research tool toggled on")
        else:
            # #739: DOM tools-menu path failing here is EXPECTED (selectors
            # rotated) and is the designed trigger for the CUA tier-3 fallback,
            # which enables Research every time — so this is INFO, not a WARN
            # claiming "chat mode" (that wording was factually wrong and
            # manufactured false-alarm sweep findings). A genuine all-layers
            # failure is reported separately by CUA validation.
            log("[setup_claude_dr] Step 3B: DOM Research toggle not found (selectors rotated) — CUA fallback will enable Research", "INFO")

        # Focus the input so the brief paste/attach lands cleanly.
        for sel in ['div[contenteditable="true"]', '[aria-label*="message"]', '.ProseMirror']:
            try:
                inp = await page.query_selector(sel)
                if inp:
                    await inp.click()
                    break
            except Exception:
                continue
        # Phoenix model_refresh — record the advisory thinking/effort state for
        # the caller's soft notice (NOT part of the success contract — model +
        # research remain the only hard gates).
        _P2_THINKING_STATE["claude"] = {"effort": _effort_confirmed, "thinking": _thinking_confirmed}
        # ⭐⭐ 2026-08-06 — Claude's effort tier had NO entry in the run's DOM-intent
        # ledger while ChatGPT's model pill did, so when the Effort submenu failed
        # to mount the run carried on with whatever tier was already set and the
        # end-of-run summary looked IDENTICAL to a run that confirmed it. A correct
        # skip and a silent quality loss were indistinguishable from the one place
        # an operator looks. On this family the reasoning knob is the quality lever
        # for research work, so "we could not confirm the tier" is the single most
        # worthwhile thing here to be able to grep for.
        #
        # One call, at the one point every path reaches, rather than a note per
        # branch — a note per branch is how a branch gets missed.
        _dom_note(
            "claude.select_effort_tier",
            _claude_effort_outcome(_effort_confirmed, _effort_via),
            phase=2, via=(_effort_via or "none"),
            detail=("" if _effort_confirmed else
                    f"tier left as it was; wanted '{_claude_effort}' — the "
                    f"answer may be weaker than the run reports"))
        # Record the selected model version for on-the-fly known-good learning.
        # ⚠ PREFER THE PICK. The trigger read is a page-wide max over every
        # visible button, so an upsell chip naming a model the account cannot
        # actually use ("Try Opus 6") could be learned and then pinned to on a
        # later fallback — a poisoned value that outlives the run. A version we
        # clicked in the menu is ground truth; the trigger is only the backstop
        # for the path where nothing was picked because nothing needed picking.
        _P2_PICKED_VERSION["claude"] = (
            _picked_version
            if isinstance(_picked_version, (int, float))
            else (parse_family_version(opus_selected or "", _claude_family)
                  or (model_trigger_ver if model_ok else None)))
        # Success only when all three critical knobs are in place
        return bool(opus_selected) and bool(research_enabled)
    except Exception as e:
        log(f"[setup_claude_dr] {e}", "WARN")
        # #744 invariant: NEVER strand an open model popover over the composer
        # (it would trigger the re-click loop on pre-send re-activation). Any
        # exception anywhere above — including a page.evaluate timeout during
        # the Step 1B poll, which propagates past the inner Escape paths — must
        # still dismiss a possibly-open popover. Escape is a harmless no-op when
        # nothing is open.
        try:
            await page.keyboard.press("Escape")
        except Exception:
            pass
        return False


# ═════════════════════════════════════════════════════════════════════════════
# The setup ladder — ordered rungs, ONE outcome predicate, first winner stops it
# ─────────────────────────────────────────────────────────────────────────────
# Three surfaces can act on "Deep Research is on": the DOM tier, a Vision/CUA
# setup mission, and a Vision/CUA validation that is allowed to FIX. They used to
# run as a straight line rather than a ladder — the validation fired
# unconditionally, after the outcome had already been decided — and both failure
# directions were real:
#
#   * After the DOM tier WON, a second surface still opened the model menu. That
#     is the "the model selector opens twice" report; the mitigation at the time
#     was to reword the validator's prompt so it would leave the model alone,
#     which asks a language model not to do the thing it is being pointed at.
#   * After the DOM tier LOST, the setup mission and the validation ran
#     back-to-back on the same control, and a CUA "fix" clicked an already-active
#     Gemini Deep-Research pill and toggled it back OFF (#709).
#
# The ladder makes the sequence explicit: check the outcome, run rungs in order,
# re-check after each, stop at the first rung that VERIFIES, and record what was
# skipped and why. Only a POSITIVE reading may skip a rung — a predicate that
# cannot tell (`unknown`) descends exactly as before, so a brittle read degrades
# to today's behaviour instead of silently disarming a safety net.
# ═════════════════════════════════════════════════════════════════════════════

async def _dr_outcome_state(page, platform: str) -> str:
    """Read-only "is Deep Research active?" → ``'on'`` | ``'off'`` | ``'unknown'``.

    ⭐ TRI-STATE ON PURPOSE. A bool would force every unreadable composer to
    answer "off", and "off" is the reading that lets a caller ACT. The three
    platform probes have genuinely different confidence:

      * chatgpt — the shared composer detector. A readable placeholder with no
        Deep-Research pill is a positive OFF.
      * gemini  — the composer PLACEHOLDER is authoritative (#709): "What do you
        want to research?" is ON, "Ask Gemini" is OFF, and a merely-visible pill
        is neither.
      * claude  — the WHOLE intent, family AND Research tool, from the same
        constant the pre-send check reads. Both halves are required because the
        rung this reading can skip — the CUA validator — checks both, so
        answering ``on`` from the tool alone would drop the model half of a
        surface that was doing two jobs. ``researchOn`` is additionally
        documented BRITTLE (the Research pill renders without the attributes the
        detector keys on, so a TRUE state reads false), which is why a False here
        is ``unknown`` and never ``off``.

    Never raises; an unreadable page is ``unknown``.
    """
    p = (platform or "").lower()
    try:
        if p == "chatgpt":
            st = await page.evaluate(_CHATGPT_DR_ACTIVE_JS) or {}
            if st.get("active"):
                return "on"
            return "off" if st.get("placeholder") else "unknown"
        if p == "gemini":
            st = await page.evaluate(_GEMINI_DR_STATE_JS) or {}
            if st.get("placeholderResearch"):
                return "on"
            if st.get("placeholderChat"):
                return "off"
            return "unknown"
        if p == "claude":
            # ⚠ The RUN's family. Frozen to the policy word, this probe answers
            # "unknown" for every pass of a run that deliberately fell back —
            # and "unknown" is the reading that makes the ladder re-run the CUA
            # validator it exists to skip.
            st = await page.evaluate(_CLAUDE_MODE_STATE_JS, {
                "fam": _p2_active_family("claude") or "opus",
                "effortWord": p2_labels("claude").get("effort") or "",
                "trigTestid": _CLAUDE_MODEL_TRIGGER_TESTID}) or {}
            # ⛔ Never 'off'. This detector's False is not evidence — see above.
            #
            # ⭐⭐ 2026-08-17 — EFFORT IS THE THIRD HALF, and leaving it out is why
            # a run could report success at an unverified reasoning tier. The
            # docstring above already gives the rule this follows: both existing
            # terms are required "because the rung this reading can skip — the CUA
            # validator — checks both, so answering `on` from the tool alone would
            # drop the model half of a surface that was doing two jobs." Effort was
            # doing a third job and was not in the predicate, so a missed effort
            # left the outcome satisfied and `vision_cua` + `cua_validate` were
            # both skipped. The observed line reads:
            #
            #   select_effort_tier: missed via=none — wanted 'max'
            #   [ladder:claude.enable_deep_research] outcome satisfied at 'builtin'
            #                                       — skipping vision_cua, cua_validate
            #
            # ⛔ AND THE OTHER HALF HAD TO SHIP WITH IT. The validator's own prompt
            # used to forbid touching effort, so descending here would have sent
            # the run to a rung instructed not to help — cost with no repair. That
            # ban was itself a workaround for the submenu that would not expand;
            # with the submenu addressed by test id the premise is gone, and the
            # prompt now permits the fix exactly when this term is what failed.
            #
            # Direction is safe either way: a False adds `unknown`, never `off`,
            # so the worst case is a rung that runs when it need not have.
            return ("on" if (st.get("hasExtended") and st.get("researchOn")
                             and st.get("effortOk")) else "unknown")
    except Exception as e:
        log(f"[ladder] outcome probe for {p} failed ({e})", "INFO")
    return "unknown"


async def _run_intent_ladder(intent_key, rungs, *, verify, label=""):
    """Run ORDERED rungs for one intent and stop at the first that VERIFIES.

    ``rungs`` is a list of dicts:
      ``{"tier": <name>, "run": <async no-arg callable>}`` — a rung to run, or
      ``{"tier": <name>, "ran": True}``                    — a rung the caller
          already ran itself (the DOM setup, whose failure has its own
          human-verification consequence that must be handled at the call site).
    Pre-run rungs come FIRST, since that is what "already ran" means in order.

    ``verify`` is an async no-arg callable returning ``'on' | 'off' | 'unknown'``
    (see :func:`_dr_outcome_state`). ONLY ``'on'`` stops the ladder — an
    ``'unknown'`` descends, so a probe that cannot read the page can never
    disarm a lower rung.

    Returns ``{intent, verified, tier, ran, skipped, states}``. ``tier`` is the
    rung that verified, or ``"already"`` when the outcome held before any rung
    ran (nothing is executed in that case — the whole point of a ladder is that
    an achieved outcome is not re-achieved).

    Never raises: a rung that throws is logged, recorded, and the ladder
    continues to the next one. A rung failing is what lower rungs are for.
    """
    tag = f"[{label}] " if label else ""
    out = {"intent": intent_key, "verified": False, "tier": None,
           "ran": [], "skipped": [], "states": []}

    async def _state():
        try:
            return await verify()
        except Exception as e:
            log(f"{tag}[ladder:{intent_key}] outcome check errored ({e}) — treating as unknown", "INFO")
            return "unknown"

    # ⚠ The LEADING pre-run rungs are consumed before the first reading, and that
    # single reading answers both questions at once: "does the outcome already
    # hold?" and "did those rungs achieve it?" are the same question about the
    # same page. Probing once for the pre-check and again for the pre-run rung
    # cost an extra page read AND could log two different answers for one rung
    # with nothing in between, which reads like a bug in the thing you are using
    # to diagnose bugs.
    #
    # Crediting matters too: reporting "no rung ran" on the commonest path there
    # is — the DOM setup succeeded and left the outcome satisfied — would be
    # false, and this log line is the first thing read when working out which
    # surface is carrying a platform.
    start = 0
    while start < len(rungs) and rungs[start].get("ran"):
        out["ran"].append(rungs[start].get("tier") or f"rung{start}")
        start += 1
    st = await _state()
    out["states"].append(st)
    if st == "on":
        out.update(verified=True, tier=(out["ran"][-1] if out["ran"] else "already"))
        out["skipped"] = [r.get("tier") for r in rungs[start:]]
        log(f"{tag}[ladder:{intent_key}] outcome satisfied at "
            f"'{out['tier']}' — skipping {', '.join(out['skipped']) or 'nothing'}")
        return out
    for i in range(start, len(rungs)):
        rung = rungs[i]
        tier = rung.get("tier") or f"rung{i}"
        if not rung.get("ran"):
            runner = rung.get("run")
            if runner is None:
                continue
            try:
                await runner()
            except Exception as e:
                log(f"{tag}[ladder:{intent_key}] rung '{tier}' errored ({e}) — "
                    f"continuing to the next rung", "WARN")
        out["ran"].append(tier)
        st = await _state()
        out["states"].append(st)
        if st == "on":
            out.update(verified=True, tier=tier)
            out["skipped"] = [r.get("tier") for r in rungs[i + 1:]]
            log(f"{tag}[ladder:{intent_key}] verified at rung '{tier}' — "
                f"skipping {', '.join(out['skipped']) or 'nothing (last rung)'}")
            return out
    log(f"{tag}[ladder:{intent_key}] no rung verified the outcome "
        f"(ran: {', '.join(out['ran']) or '-'}, last read: {out['states'][-1]})", "WARN")
    return out


async def validate_setup_with_cua(browser, cua_client, page, platform, label, verbose=False):
    """Extra validation layer: CUA looks at the screen and confirms the intended
    options (Deep Research / Extended / Research tool) are actually active. If not,
    CUA tries to fix.

    Returns a (ok, confirmed) tuple:
      - ok        — False ONLY on an explicit "failed" verdict. True otherwise
                    (verified/fixed/ambiguous/error) so a soft/uncertain
                    validation never blocks the pipeline (unchanged contract).
      - confirmed — True ONLY when CUA POSITIVELY said "verified"/"fixed".
                    #744: the chat-mode gate keys on `confirmed`, NOT `ok` —
                    an ambiguous or errored validation (ok=True, confirmed=False)
                    must NOT be treated as proof Deep Research is on, or a real
                    chat-mode degradation could slip through silently (#709)."""
    # ⭐⭐ 2026-08-17 — DID THE DOM LAYER CONFIRM THE EFFORT TIER? This is what
    # decides whether the validator is permitted to go and set it. Defaults to
    # True — "assume it is fine" — so a platform that records nothing, or a call
    # that arrives before the setup ran, gets today's cheap read-only pass rather
    # than a speculative trip into the model popover on every run.
    #
    # ⛔ The permission has to be granted in BOTH strings or neither: they are
    # sent to one CUA call, and an agent holding a system prompt that forbids the
    # submenu and a user message that demands it will do something arbitrary.
    _claude_effort_ok = _claude_validator_effort_ok(_P2_THINKING_STATE.get("claude"))
    validator_map = {
        "chatgpt": PROMPT_VALIDATE_CHATGPT_SETUP,
        "gemini": PROMPT_VALIDATE_GEMINI_SETUP,
        # ⛔⛔ RENDERED PER CALL with the run's family, not the import-time
        # constant. This validator runs after the DOM setup SUCCEEDED, and its
        # step 1 is "only touch the model if the button doesn't name <fam>". On
        # a run that deliberately fell back, a constant frozen to the primary
        # family makes that clause fire on the CORRECT model and sends the
        # validator into the menu whose only primary-family rows are the sales
        # chips the DOM layer just refused — the pass whose job is to confirm
        # the model would be the pass that undoes it.
        "claude": claude_validate_setup_prompt(_p2_active_family("claude"),
                                               effort_ok=_claude_effort_ok),
    }
    user_msg_map = {
        "chatgpt": "Verify Deep Research mode is ACTIVE in ChatGPT. Fix if not. Do not type.",
        "gemini": "Verify Gemini Deep Research is ACTIVE — the composer placeholder MUST read 'What do you want to research?' (NOT 'Ask Gemini'). A merely-visible chip is NOT enough proof. Fix if not. Do not type.",
        # ⭐ FAMILY ONLY, and it lives in models.py beside the SETUP directive so
        # both CUA strings render from one policy. The two are deliberately
        # different: setup runs after the DOM path FAILED (so it must open the
        # menu and upgrade), this runs after the DOM path SUCCEEDED (so it must
        # leave the model alone — opening the menu here is the second
        # model-menu interaction users saw as "the selector opens twice").
        # `Adaptive thinking` is gone with the toggle — see P2_MODEL_POLICY.
        # Same family, same reason — this string and the system prompt above go
        # to ONE CUA call, so a family that reaches only one of them leaves the
        # agent holding two instructions that disagree about the model.
        "claude": p2_claude_validate_directive(_p2_active_family("claude"),
                                               effort_ok=_claude_effort_ok),
    }
    sys_prompt = validator_map.get(platform.lower())
    user_prompt = user_msg_map.get(platform.lower())
    if not sys_prompt:
        return True, False  # Unknown platform — skip (not a positive confirmation)
    try:
        await browser.switch_to_page(page)

        async def _validate_setup_cua():
            return await agent_loop(cua_client, browser, sys_prompt, user_prompt,
                model=CUA_MODEL, max_iterations=6, verbose=verbose)

        # #839 act tier: the validator can FIX (not read-only), so Vision may
        # act. NO success_text here (review [markers]): "verified" is a
        # CONFIRMATION marker that gates the #744/#709 chat-mode decision, so
        # mechanically stamping it onto ANY Vision declare_success would flip a
        # hedged/soft Vision claim into a hard "DR confirmed on". Instead the
        # Vision reason flows through UNSTAMPED: the mission tells Vision to SAY
        # 'verified'/'fixed' on a real success (→ confirmed below), and a
        # success whose reason lacks those words degrades to the SAFE ambiguous
        # (True, False) — never a false confirmation. #709: the Gemini
        # user_prompt's composer-placeholder demand ('What do you want to
        # research?' vs 'Ask Gemini') rides in verbatim as the mission.
        result = await _shadow_observed_cua(
            page, hotspot_id="validate-setup", phase=2, platform=platform.lower(),
            current_step="validate_deep_research_active",
            context_hint=f"confirm Deep Research / the right model+tools are ACTIVE for "
                         f"{label}, fix if not, do NOT type. {user_prompt}",
            expected_outcome="Deep Research is confirmed active (say 'verified' or 'fixed')",
            cua_coro_factory=_validate_setup_cua,
            mission_prompt=f"{sys_prompt}\n\nTASK: {user_prompt}") or {}
        text = (result.get("text") or "").lower()
        if "verified" in text or "fixed" in text:
            log(f"[{label}] CUA validation: {text[:120]}")
            return True, True
        if "failed" in text:
            log(f"[{label}] CUA validation FAILED: {text[:160]}", "WARN")
            return False, False
        # Ambiguous — don't block the pipeline, but this is NOT a confirmation.
        log(f"[{label}] CUA validation ambiguous: {text[:120]}", "WARN")
        return True, False
    except Exception as e:
        log(f"[{label}] CUA validation error: {e}", "WARN")
        return True, False  # Don't block pipeline on validator error (but not confirmed)


# ═════════════════════════════════════════════════════════════════════
# Phase-2 brief delivery via file attachment (Option A)
# ─────────────────────────────────────────────────────────────────────
# The research brief is ~30 KB. Inline pastes get silently converted
# to attachments by both ChatGPT and Claude, and the resulting state
# is inconsistent (duplicate attachments, empty textareas). We now
# attach the brief as brief.md directly and type a short inline prompt
# that references it. This matches how the platforms actually want to
# receive long input and dodges all the paste-verification issues.
# ═════════════════════════════════════════════════════════════════════

# ── Phase-2 user-source delivery ──────────────────────────────────────────
# When P1 is skipped and the user attaches source files, those files must
# reach every P2 agent. ChatGPT/Claude attach them natively (extra_files on
# the file input); Gemini drops uploads, so it gets their text pasted under
# the brief. The files live in queues/<run>/documents/ alongside the
# synthetic brief.md + (on resume/retry) agent-written artifacts, so we
# track an explicit ALLOWLIST manifest of user-attached filenames rather
# than a brief/consolidated denylist that would sweep agent outputs.

def _p2_run_dir():
    if not _tracks_dir:
        return None
    return Path(__file__).parent / "queues" / _tracks_dir.name


def _chatgpt_convo_id(url: str):
    """The conversation id in a ChatGPT `/c/<id>` URL, or None if there isn't one.

    ⛔⛔ 2026-08-27 — THE DISTINCTION THIS EXISTS TO MAKE. "We are not on a
    conversation" and "we are on a conversation whose id we cannot date" are
    different facts, and treating them alike cost a whole run. ChatGPT served
    `/c/WEB:c3a7026f-…`; `_chatgpt_convo_epoch` returned None for it exactly as
    it does for a bare host, every caller read None as "refuse", and a healthy
    leg was killed seven seconds after Send.

    An id that is PRESENT but not datable means *ask something else* — never
    *this is somebody else's conversation*. See `_chatgpt_landed`.
    """
    u = (url or "").split("?", 1)[0].split("#", 1)[0]
    if "/c/" not in u:
        return None
    cid = u.split("/c/", 1)[1].strip("/").split("/", 1)[0]
    return cid or None


def _chatgpt_convo_epoch(url: str):
    """Unix seconds encoded in a ChatGPT conversation id, or None.

    2026-08-05. ChatGPT mints `/c/<uuid>` where the first group is the creation
    time in hex seconds. That is what let the incident be diagnosed at all: the
    P2 conversation decoded to the previous evening while the run started that
    morning, and the P1 conversation decoded to within seconds of the observed
    P1 start — which is what validates the method rather than assuming it.

    Returns None for anything that is not a conversation URL (`/share/<id>`, a
    custom-GPT page, a bare host). None must FAIL CLOSED at every call site: an
    unreadable id is not permission to proceed.
    """
    try:
        u = (url or "").split("?", 1)[0].split("#", 1)[0]
        if "/c/" not in u:
            return None
        cid = u.split("/c/", 1)[1].strip("/").split("/", 1)[0]
        head = cid.split("-", 1)[0]
        if len(head) != 8:
            return None
        secs = int(head, 16)
    except (ValueError, TypeError, AttributeError, IndexError):
        return None
    # Sanity-bound it: a plausible id decodes to a real recent date. Anything
    # outside that is a coincidence, not a timestamp, so refuse to read it.
    if not (1_600_000_000 < secs < 4_000_000_000):
        return None
    return secs


def _run_start_epoch():
    """When did THIS run start? Unix seconds, or None if it cannot be told.

    ⭐ 2026-08-05 — THE EARLIEST READABLE STAMP WINS, and this used to be
    "config.json's mtime, else the directory name, else meta.json". The old
    docstring justified that order with "config.json is written once in the
    new-run branch (a resume only reads it), so its mtime is the truest start".
    That premise is FALSE twice over: `_write_config_to_disk` rewrites the file
    whenever the user changes a setting MID-RUN, and the resume path merges the
    incoming payload into it. Either one moves the mtime forward to *now*.

    Which turns a mutable file into a moving definition of "this run", and every
    conversation the run legitimately created before that write suddenly predates
    it. That was a LOW while the identity check only ran during setup. It is not
    a low any more: the check now also runs on the round-robin's poll path, every
    tick, so a user toggling a setting at minute 20 would have made the sweep
    declare a healthy ChatGPT leg foreign and kill it.

    Taking the MINIMUM fixes the class rather than the one caller. All three
    candidates are evidence about when the run began, and reading too EARLY is
    the safe direction: it widens the window in which a conversation counts as
    ours, so the failure mode is a missed catch rather than a killed healthy leg.
    Reading too LATE — which is the only thing a forward-moving mtime can do —
    fails a leg that did nothing wrong.

    The directory's own `_%Y%m%d_%H%M%S` suffix is the immutable anchor (LOCAL
    time, the same frame conversation ids decode into) and every producer of a
    run id stamps it. `meta.json`'s createdAt is first saved at P1 completion, so
    on a fresh run it is minutes late and only ever a ceiling — harmless in a
    min(), and still the only answer when the directory name carries no stamp.
    """
    rd = _p2_run_dir()
    if rd is None:
        return None
    stamps = []
    try:
        cfg = rd / "config.json"
        if cfg.exists():
            stamps.append(float(cfg.stat().st_mtime))
    except OSError:
        pass
    try:
        stamp = "_".join(rd.name.rsplit("_", 2)[-2:])
        stamps.append(datetime.strptime(stamp, "%Y%m%d_%H%M%S").timestamp())
    except (ValueError, IndexError):
        pass
    try:
        meta = json.loads((rd / "meta.json").read_text(encoding="utf-8"))
        created = float(meta.get("createdAt") or 0) / 1000.0
        if created:
            stamps.append(created)
    except (OSError, ValueError, TypeError, json.JSONDecodeError):
        pass
    return min(stamps) if stamps else None


# How far BEFORE the run's own start a conversation may have been created and
# still count as ours. Covers clock skew between this machine and ChatGPT's
# minting, plus a resume that reattaches within the same minute.
_CONVO_AGE_SLACK_SEC = 120


def _chatgpt_conversation_is_ours(url: str, run_start: "float | None" = None) -> bool:
    """Was this ChatGPT conversation created by THIS run?

    ⭐ 2026-08-05 — the check whose absence cost a whole run. Two call sites
    treated the mere presence of `/c/` in the tab URL as positive proof the
    brief had been submitted and the agent was healthy. On a warm tab that has
    wandered into a pre-existing thread that predicate is TRUE, so the code
    asserted health from the very fact that proved the failure: the leg spent 39
    minutes on the previous evening's conversation and its finished answer — a
    120KB report on an unrelated topic — was harvested as this run's output.

    Fails CLOSED on an unreadable id and OPEN on an unknowable run start: if we
    cannot date the run we must not start failing healthy legs, but if we cannot
    date the conversation we must not bless it either.
    """
    convo = _chatgpt_convo_epoch(url)
    if convo is None:
        return False
    start = _run_start_epoch() if run_start is None else run_start
    if not start:
        return True
    return convo >= (float(start) - _CONVO_AGE_SLACK_SEC)


def _chatgpt_landing_verdict(url: str, pre_send_url: str,
                             run_start: "float | None" = None) -> str:
    """What one observation of the URL, after Send, tells us. Pure.

    ⛔⛔ THIS IS A MODULE-LEVEL FUNCTION BECAUSE THE DECISION IT REPLACES LIVED IN
    A CLOSURE INSIDE AN ASYNC FUNCTION NO TEST CAN DRIVE — so the only thing the
    suite could do was read it as source text, and source text cannot tell you
    that a guard fails closed on an input you have not thought of. It did, and it
    cost a run on 2026-08-27. As a pure function it is five lines of test.

    One of five words, and the two that are not verdicts are the point:

      * `no_conversation`  — not on a `/c/` URL yet. Keep waiting.
      * `unchanged`        — still the conversation we were on before Send, so the
                             send created nothing. Refuse. (The 2026-06 incident.)
      * `ours`             — datable, and dated at or after this run began. Accept.
      * `foreign`          — datable, and older than this run. Refuse.
                             (The 2026-08-05 incident.)
      * `undatable`        — a NEW conversation whose id carries no timestamp.
                             ⛔ NOT a verdict. Keep waiting; the caller falls back
                             to the observed transition only when the budget runs
                             out. `/c/WEB:<uuid>` lands here.
    """
    if _chatgpt_convo_id(url) is None:
        return "no_conversation"
    if url.split("?", 1)[0] == (pre_send_url or "").split("?", 1)[0]:
        return "unchanged"
    if _chatgpt_convo_epoch(url) is None:
        return "undatable"
    return "ours" if _chatgpt_conversation_is_ours(url, run_start) else "foreign"


def _chatgpt_landing_result(undatable_url: str, last_url: str):
    """What the wait loop returns once its budget is spent. `(ok, url, why)`. Pure.

    ⛔⛔ THIS IS A FUNCTION BECAUSE MUTATION PROVED THE INLINE VERSION HAD NO
    KILLER. It was two lines at the end of the loop, and a mutant that changed
    `if _undatable:` to `if False:` — deleting the entire fallback, the headline
    of the 2026-08-27 fix — SURVIVED. The test asserting the fallback was a source
    pin on the `return` line, and a `return` inside a branch nothing can enter is
    still present in the file. **A presence pin cannot see reachability.**

    ⛔ The condition is load-bearing in the other direction too: firing the
    fallback with no remembered conversation would confirm a run against a tab
    that never moved.
    """
    if undatable_url:
        return True, undatable_url, "undatable_id_transition_observed"
    return False, last_url, "no_conversation_url"


def _chatgpt_tab_is_foreign(url: str) -> bool:
    """True when this tab sits on a ChatGPT conversation that PREDATES the run.

    ⭐ 2026-08-05 — the whole drift wave's decision, in one callable place, and
    that placement is the point. The two refusal sites used to spell it inline as
    `"/c/" in u and not _chatgpt_conversation_is_ours(u)`; nothing executed either
    one (every test in the suite reads `start_agent_no_gemini_wait` as SOURCE),
    so mutation proved that dropping a single `not` left 49 of 49 tests green.
    A guard whose polarity no test can feel is a guard that can ship inverted.

    The two halves are separate on purpose:
      * no `/c/` id → False. A healthy first send happens at `https://chatgpt.com/`
        before the SPA mints one, and a bare host has nothing to date.
      * `_chatgpt_conversation_is_ours` fails OPEN on an unknowable run start, so
        this returns True only for a conversation we can positively date as older
        than the run.

    ⛔⛔ 2026-08-27 — AND THE DOCSTRING ABOVE USED TO SAY THE OPPOSITE OF WHAT THE
    CODE DID. It claimed "only for a conversation we can positively date as older"
    while delegating to a predicate that fails CLOSED on an unreadable id — so an
    id we simply could not parse came back `foreign=True`. When ChatGPT began
    serving `/c/WEB:<uuid>` that killed healthy legs on the poll path, every tick.
    An UNDATABLE id is now explicitly not foreign: it is a question for the other
    detectors, not a verdict here.
    """
    if _chatgpt_convo_id(url) is None:
        return False
    if _chatgpt_convo_epoch(url) is None:
        return False
    return not _chatgpt_conversation_is_ours(url)


async def _refuse_foreign_chatgpt_tab(page, platform, platform_l, label, url,
                                      *, recover: bool, why: str) -> bool:
    """Refuse to act on a tab parked in someone else's finished thread.

    Returns True when it refused — the caller's only job is to hand back
    `(page, False)`. Everything the refusal owes the run happens here: the ERROR
    line, the optional new-chat recovery, retracting the tentative chat-mode
    marker, and the per-agent card.

    `recover=True` presses New chat afterwards. That is for the PRE-SEND site,
    where the next attempt reuses this warm tab and inheriting the parked thread
    is how a second attempt inherits the first one's problem — best effort, and
    its success changes nothing about the outcome here. The setup-failure site
    passes False because `setup_chatgpt_dr` already tried and failed to recover.

    ⚠ The card uses the DEFAULT body, not the `rejected=True` one. Both sites
    used to pass `rejected=True`, which told the user the surface kept bouncing
    the brief upload — and on this path nothing was ever uploaded: the brief
    never left our side. The default body ("we couldn't hand it over") is
    already exactly true here, so no third copy variant is warranted.
    """
    if platform_l != "chatgpt" or not _chatgpt_tab_is_foreign(url):
        return False

    def _url_live() -> str:
        try:
            return (page.url or "")
        except Exception:
            return ""

    _epoch = _chatgpt_convo_epoch(url)
    _when = (datetime.fromtimestamp(_epoch).strftime("%Y-%m-%d %H:%M:%S")
             if _epoch else "unknown")
    log(f"[{label}] ⛔ REFUSING to {why}: the tab is on a conversation created "
        f"{_when}, which predates this run ({url!r})", "ERROR")
    if recover:
        # ⛔ THE LEG ENDS HERE EITHER WAY, and that is not a shortcut — it is the
        # only honest outcome. A fresh composer is EMPTY: the brief and the typed
        # prompt went with the old thread, so there is nothing left to send.
        # Sending an empty composer would mint a conversation with no brief in
        # it, which is worse than not sending. The retry re-runs setup from the
        # top, and the caller's hard-retry is what does that.
        #
        # ⚠ There is deliberately NO `_recovered` flag. It used to exist and pick
        # between two log lines while both branches did the identical three
        # things; mutation testing found it twice, correctly, as carrying no
        # behaviour. The log reports the LIVE url instead, which cannot drift.
        try:
            await _chatgpt_force_new_chat(page, label=label)
        except Exception as _rc_e:
            log(f"[{label}] new-chat recovery errored ({_rc_e})", "WARN")
        log(f"[{label}] tab left at {_url_live()!r}; the brief did not survive "
            f"the move, so this attempt ends and the retry re-runs setup", "WARN")
    _controls.chat_mode_pending.pop(platform_l, None)
    fail_agent(platform_l, *_brief_send_fail_copy(platform))
    return True


def _p2_sources_manifest_path():
    rd = _p2_run_dir()
    return (rd / ".p2_sources.json") if rd else None


def _write_user_sources_manifest(names):
    """Record which documents/ files are user-attached sources. Called by
    Flow B after downloads. `attach_to_p2` stays False until the orchestrator
    confirms P1 didn't run live this session (see _finalize_p2_source_decision)."""
    mp = _p2_sources_manifest_path()
    if not mp:
        return
    try:
        data = {}
        if mp.exists():
            data = json.loads(mp.read_text(encoding="utf-8"))
        merged = list(dict.fromkeys((data.get("files") or []) + [str(n) for n in names]))
        data["files"] = merged
        data.setdefault("attach_to_p2", False)
        mp.write_text(json.dumps(data), encoding="utf-8")
    except Exception as e:
        log(f"[p2-sources] manifest write failed: {e}", "WARN")


def _finalize_p2_source_decision(attach):
    """Record the definitive 'attach user sources to P2' decision exactly once,
    just before P2 runs. `attach` should be True only when P1 did NOT run a
    live brief generation this session (P1-ON already absorbed the files into
    the ChatGPT brief — re-attaching would double-feed). Idempotent via a
    `decided` flag: a P1-ON run that pauses and resumes INTO P2 (where the P1
    block is skipped and the gate would flip) keeps its original decision."""
    mp = _p2_sources_manifest_path()
    if not mp or not mp.exists():
        return
    try:
        data = json.loads(mp.read_text(encoding="utf-8"))
        if data.get("decided"):
            return
        data["attach_to_p2"] = bool(attach) and bool(data.get("files"))
        data["decided"] = True
        mp.write_text(json.dumps(data), encoding="utf-8")
        if data["attach_to_p2"]:
            log(f"[p2-sources] {len(data['files'])} user source(s) flagged for P2 delivery")
    except Exception as e:
        log(f"[p2-sources] manifest finalize failed: {e}", "WARN")


def _read_p2_source_paths():
    """Absolute paths of user source docs to hand each P2 agent. Empty unless
    the manifest exists AND attach_to_p2 is set. Durable across pause/resume
    and hard-retry because it reads from disk, not runtime state."""
    mp = _p2_sources_manifest_path()
    rd = _p2_run_dir()
    if not mp or not rd or not mp.exists():
        return []
    try:
        data = json.loads(mp.read_text(encoding="utf-8"))
        if not data.get("attach_to_p2"):
            return []
        out = []
        for name in (data.get("files") or []):
            p = rd / "documents" / name
            if p.exists() and p.is_file():
                out.append(str(p))
        return out
    except Exception as e:
        log(f"[p2-sources] manifest read failed: {e}", "WARN")
        return []


# Per-doc + total caps so a large PDF can't blow Gemini's composer paste
# (Gemini gets pasted text, not a file attachment).
_P2_SRC_CHARS_PER_DOC = 50000
_P2_SRC_CHARS_TOTAL = 150000


def _extract_source_text(path):
    """Best-effort plaintext of a user source. md/txt read natively; pdf/docx
    via import-guarded optional libs. Returns None when text can't be
    extracted (missing lib / parse failure) — caller logs + skips that file."""
    p = Path(path)
    suf = p.suffix.lower()
    try:
        if suf in (".md", ".txt"):
            return p.read_text(encoding="utf-8", errors="replace")
        if suf == ".pdf":
            try:
                from pypdf import PdfReader
            except Exception:
                try:
                    from PyPDF2 import PdfReader  # legacy fallback name
                except Exception:
                    return None
            parts = []
            for pg in PdfReader(str(p)).pages:
                parts.append(pg.extract_text() or "")
            return "\n".join(parts)
        if suf == ".docx":
            try:
                import docx
            except Exception:
                return None
            return "\n".join(par.text for par in docx.Document(str(p)).paragraphs)
    except Exception as e:
        log(f"[p2-extract] {p.name}: {e}", "WARN")
    return None


def _augment_brief_with_sources(brief, source_paths, label):
    """Append extracted source-doc text to a brief for paste-based delivery
    (Gemini). Honors per-doc + total size caps; returns the brief unchanged
    if nothing could be inlined."""
    if not source_paths:
        return brief
    chunks = []
    total = 0
    inlined = 0
    for sp in source_paths:
        name = Path(sp).name
        txt = _extract_source_text(sp)
        if not txt or not txt.strip():
            log(f"[{label}] Source '{name}' not inlined (no extractable text — "
                f"file still reaches NotebookLM in P3)", "WARN")
            continue
        txt = txt.strip()
        if len(txt) > _P2_SRC_CHARS_PER_DOC:
            txt = txt[:_P2_SRC_CHARS_PER_DOC] + "\n…[truncated]"
            log(f"[{label}] Source '{name}' truncated to {_P2_SRC_CHARS_PER_DOC} chars for paste", "WARN")
        if total + len(txt) > _P2_SRC_CHARS_TOTAL:
            log(f"[{label}] Source paste budget reached — '{name}' and any remaining sources dropped", "WARN")
            break
        chunks.append(f"--- SOURCE DOCUMENT: {name} ---\n{txt}")
        total += len(txt)
        inlined += 1
    if not chunks:
        return brief
    log(f"[{label}] Inlined {inlined} source doc(s) ({total} chars) into brief for paste")
    header = ("\n\n══════ ATTACHED SOURCE DOCUMENTS ══════\n"
              "Below are the full contents of the source files the user attached. "
              "Use them as the primary source material for your research.\n\n")
    return brief + header + "\n\n".join(chunks)


async def attach_brief_file(browser, page, brief_path, platform, label, extra_files=None):
    """Attach brief.md (and optional extra user-supplied files) to the
    composer via the hidden file input. Returns True if at least the
    brief landed.

    extra_files: list[str] of additional paths to attach alongside the
    brief (user_sources downloaded into queue_dir/documents/). Empty/None
    keeps the legacy single-attachment behavior. Playwright's
    set_input_files takes a list and uploads all in one call — most
    composers handle that natively, but we soft-fail per-platform if
    multi-attach doesn't take."""
    extra_files = extra_files or []
    all_paths = [str(brief_path)] + [str(p) for p in extra_files]
    try:
        # Clear any residual attachments from a previous attempt
        try:
            await page.evaluate("""() => {
                document.querySelectorAll(
                    'button[aria-label*="Remove"], button[aria-label*="Delete"], ' +
                    'button[data-testid*="remove-attachment"], button[data-testid*="delete-attachment"]'
                ).forEach(b => { try { b.click(); } catch(e){} });
            }""")
            await asyncio.sleep(0.5)
        except Exception:
            pass

        # PRIMARY — hidden file input. #950 (2026-07-13 03:40 run): the
        # composer's uploader is NOT always the first input[type=file] in
        # document order. 2A reuses P1's warm tab (post-canvas, client-side
        # New chat), which can leave stale file inputs ahead of the live
        # composer's — and set_input_files on a stale input is a SILENT
        # no-op: no chip, no spinner, no toast (the run failed verification
        # 3× exactly that way, while the same attach on a clean page landed
        # its chip in 2.5s). Rank composer-form inputs first, feed each
        # candidate, and accept only when the page actually reacts (chip /
        # spinner / even a failure toast proves the input is wired —
        # _ensure_brief_attached settles and retries from there).
        fname = Path(str(brief_path)).name
        # Rank BEFORE capping — a composer input sitting late in document
        # order must not be dropped by the try-budget.
        handles = (await page.query_selector_all('input[type="file"]'))[:8]
        ranked = []
        for i, h in enumerate(handles):
            try:
                in_composer = await h.evaluate(
                    """el => {
                        const form = el.closest('form');
                        return !!(form && form.querySelector(
                            '#prompt-textarea, .ProseMirror, textarea, '
                            + 'div[contenteditable="true"]'));
                    }""")
            except Exception:
                in_composer = False
            ranked.append((0 if in_composer else 1, i, h))
        ranked.sort(key=lambda t: (t[0], t[1]))
        def _real_err(s):
            e = str(s.get("error") or "")
            return bool(e) and not e.startswith("probe_error")
        for grp, i, file_input in ranked[:4]:
            try:
                # Baseline BEFORE feeding — so a spinner/toast LINGERING from a
                # prior attempt (residual-clear removes chips, not toasts) can't
                # be miscredited to this input (#950 review: the reaction census
                # is page-global; only a NEW signal proves THIS input is wired).
                base = await _brief_attachment_state(page, fname)
                extras_delivered = bool(extra_files)
                try:
                    await file_input.set_input_files(all_paths)
                except Exception as _multi_err:
                    if not extra_files:
                        raise
                    # Multi-file may fail on platforms that allow only one
                    # input file at a time. Retry with brief alone so the
                    # phase still proceeds — extras are still on disk for
                    # P3 NLM upload.
                    log(f"[{label}] Multi-file attach failed ({_multi_err}); retrying with brief only", "WARN")
                    await file_input.set_input_files(str(brief_path))
                    extras_delivered = False
                # Poll for a page reaction (chip census, not blind trust) —
                # the live chip landed in ~2.5s; give each input 7.5s.
                # `found` (the filename chip) is input-specific and always
                # counts. `processing`/`error` are page-global, so they only
                # count when NEW vs baseline AND the input is the composer's
                # (a stale non-composer input must show the actual chip).
                reacted = False
                for _ in range(5):
                    await asyncio.sleep(1.5)
                    st = await _brief_attachment_state(page, fname)
                    if st.get("found"):
                        reacted = True
                        break
                    if grp == 0 and (
                            (st.get("processing") and not base.get("processing"))
                            or (_real_err(st) and not _real_err(base))):
                        reacted = True
                        break
                if reacted:
                    if extras_delivered:
                        log(f"[{label}] Brief + {len(extra_files)} user file(s) attached via "
                            f"file input {i + 1}/{len(handles)} (composer-form={grp == 0})")
                    elif extra_files:
                        log(f"[{label}] Brief attached (extras dropped — will reach NLM via P3) "
                            f"via file input {i + 1}/{len(handles)} (composer-form={grp == 0})")
                    else:
                        log(f"[{label}] Brief attached via file input "
                            f"{i + 1}/{len(handles)} (composer-form={grp == 0})")
                    return True
                log(f"[{label}] file input {i + 1}/{len(handles)} took the file but the page "
                    f"shows no chip/spinner/toast — stale input, trying next", "WARN")
            except Exception as _fi_err:
                log(f"[{label}] file input {i + 1}/{len(handles)} failed: {_fi_err}", "WARN")
        if handles:
            log(f"[{label}] No file input produced a visible attachment "
                f"({len(handles)} candidate(s)) — trying chooser fallback", "WARN")

        # FALLBACK — queue file for OS-level chooser then click attach
        # (single-file path; extras can't be plumbed through this branch).
        # #950 review: census the result here too — a blind True would
        # re-introduce the exact pattern the input loop above removed (and
        # ChatGPT's "+" opens a MENU, not a chooser, so the click can no-op).
        browser.set_upload_file(str(brief_path))
        for sel in ['button[aria-label*="Attach"]', 'button[aria-label*="Upload"]',
                    'button[data-testid*="upload"]', 'button[data-testid*="file"]']:
            try:
                btn = await page.query_selector(sel)
                if btn and await btn.is_visible():
                    await btn.click()
                    reacted = False
                    for _ in range(3):
                        await asyncio.sleep(1.5)
                        st = await _brief_attachment_state(page, fname)
                        if st.get("found") or st.get("processing") or _real_err(st):
                            reacted = True
                            break
                    browser.clear_upload_file()
                    if reacted:
                        log(f"[{label}] Brief attached via button click ({sel})")
                        return True
                    log(f"[{label}] Attach button ({sel}) clicked but no attachment "
                        f"appeared — trying next", "WARN")
            except Exception:
                continue
        browser.clear_upload_file()
        log(f"[{label}] Could not find file input or attach button", "WARN")
        return False
    except Exception as e:
        try: browser.clear_upload_file()
        except Exception: pass
        log(f"[{label}] Brief attach failed: {e}", "WARN")
        return False


async def _brief_attachment_state(page, filename):
    """One-shot composer-attachment probe. Returns a dict:
      {"found": bool, "processing": bool, "error": str}
    found      — a composer ATTACHMENT CHIP is present. The signal is chip
                 PRESENCE, not a literal filename match, because ChatGPT
                 RENAMES a colliding upload: the user has uploaded 'brief.md'
                 hundreds of times, so the new chip reads 'brief(228).md'
                 (live-probed 2026-07-13 — the chip is healthy and the send
                 button enables, but a literal 'brief.md' match reads False
                 forever → endless re-attach → the residual-clear wipes the
                 good chip → the run jams; THE blocker this fixes). Signals,
                 any of which counts:
                   • ChatGPT: a visible button[aria-label^="Remove file …"]
                     (we just attached exactly one file — that chip is ours);
                   • Claude: a visible [data-testid="file-thumbnail"] tile;
                   • the filename in innerText, collision-suffix-tolerant
                     ('brief.md' → /brief\\s*(\\(\\d+\\))?\\s*\\.md/i so
                     'brief(228).md' still matches);
                   • a remove/delete button whose aria matches that same
                     tolerant pattern (or the exact name).
    processing — a visible progress spinner sits in the composer region
                 (bottom ~45% of the viewport); the upload is still being
                 processed and the chip may yet fail.
    error      — a platform upload-failure toast is visible (matched loosely:
                 'There was a problem processing the upload' was the live
                 2026-07-13 ChatGPT toast).
    A probe crash is LOGGED and surfaced as error='probe_error: …' — the
    03:40 run's found=False/error='' was indistinguishable from an
    evaluate() throw, which this closes. Never raises."""
    try:
        return await page.evaluate("""(fname) => {
            const out = { found: false, processing: false, error: '' };
            const body = (document.body?.innerText || '');
            const low = body.toLowerCase();
            for (const e of ['problem processing the upload', 'failed to upload',
                             'upload failed', 'error uploading', "couldn't upload",
                             'could not upload', 'unable to upload',
                             'unsupported file type', 'file exceeds']) {
                if (low.includes(e)) { out.error = e; break; }
            }
            // Collision-suffix-tolerant filename matcher: brief.md also
            // matches brief(228).md / brief (1).md.
            const dot = fname.lastIndexOf('.');
            const stem = dot > 0 ? fname.slice(0, dot) : fname;
            const ext  = dot > 0 ? fname.slice(dot) : '';
            const esc = s => s.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');
            let nameRe = null;
            try {
                nameRe = new RegExp(esc(stem) + '\\\\s*(?:\\\\(\\\\d+\\\\))?\\\\s*' + esc(ext), 'i');
            } catch (e) { nameRe = null; }
            const nameHit = t => !!t && (t.includes(fname) || (nameRe && nameRe.test(t)));

            out.found = nameHit(body);
            // ChatGPT: a "Remove file …" button = an attachment chip is
            // present. We residual-clear + attach exactly one file, so that
            // chip is ours regardless of the rename.
            if (!out.found) {
                for (const b of document.querySelectorAll(
                        'button[aria-label], [role="button"][aria-label]')) {
                    if (b.offsetParent === null) continue;
                    const a = b.getAttribute('aria-label') || '';
                    if (/^\\s*remove file\\b/i.test(a) || nameHit(a)
                            || (/remove|delete/i.test(a) && nameHit(a))) {
                        out.found = true; break;
                    }
                }
            }
            // Claude: the attachment tile (NOT the always-present upload
            // button, data-testid="file-upload").
            if (!out.found) {
                for (const el of document.querySelectorAll(
                        '[data-testid="file-thumbnail"], [class*="attachment" i]')) {
                    if (el.offsetParent === null) continue;
                    if (el.getAttribute('data-testid') === 'file-upload') continue;
                    out.found = true; break;
                }
            }
            const vh = window.innerHeight || document.documentElement.clientHeight;
            for (const el of document.querySelectorAll(
                    '[role="progressbar"], [class*="animate-spin"], ' +
                    'svg[class*="spin"], [class*="loading"]')) {
                if (el.offsetParent === null) continue;
                const r = el.getBoundingClientRect();
                if (r.top < vh * 0.55) continue;   // composer region only
                if (typeof el.getAnimations === 'function'
                        && !el.getAnimations().some(a => a.playState === 'running')
                        && el.getAttribute('role') !== 'progressbar') continue;
                out.processing = true; break;
            }
            return out;
        }""", Path(str(filename)).name)
    except Exception as e:
        log(f"[attach-verify] attachment-state probe crashed: {e}", "WARN")
        return {"found": False, "processing": False, "error": f"probe_error: {e}"}


async def _ensure_brief_attached(browser, page, brief_path, platform, label,
                                 source_paths=None, max_attempts=3):
    """Deterministic post-attach verification + bounded re-attach (2026-07-13).

    LIVE INCIDENT: ChatGPT showed 'There was a problem processing the upload',
    the brief chip never landed, and the run FIRED anyway — Deep Research ran
    on the 218-char inline prompt with no actual brief. attach_brief_file's
    True only means set_input_files didn't throw; this closes the gap: the
    chip must be VISIBLE and upload processing SETTLED (two consecutive
    stable probes) with no failure toast, else re-attach up to max_attempts.
    Returns True only on a verified chip — callers must NOT send without it
    (the caller falls back to the inline-paste path, which delivers the same
    content as text). Gemini never calls this (paste path)."""
    fname = Path(str(brief_path)).name
    for attempt in range(1, max_attempts + 1):
        deadline = time.time() + 25
        stable_hits = 0
        state = {}
        while time.time() < deadline:
            state = await _brief_attachment_state(page, fname)
            if state.get("error"):
                if str(state["error"]).startswith("probe_error"):
                    log(f"[{label}] attachment verify: state probe crashed "
                        f"('{state['error']}') on attempt {attempt} — retrying probe", "WARN")
                    await asyncio.sleep(1.5)
                    continue
                log(f"[{label}] attachment verify: platform reported upload "
                    f"failure ('{state['error']}') on attempt {attempt}", "WARN")
                break
            if state.get("found") and not state.get("processing"):
                stable_hits += 1
                if stable_hits >= 2:
                    log(f"[{label}] Brief attachment VERIFIED — '{fname}' chip "
                        f"present, processing settled (attempt {attempt})")
                    return True
            else:
                stable_hits = 0
            await asyncio.sleep(1.5)
        if attempt < max_attempts:
            log(f"[{label}] attachment NOT verified (found={state.get('found')}, "
                f"processing={state.get('processing')}, error='{state.get('error','')}') "
                f"— re-attaching ({attempt + 1}/{max_attempts})", "WARN")
            try:
                await attach_brief_file(browser, page, brief_path, platform, label,
                                        extra_files=source_paths)
            except Exception as _re:
                log(f"[{label}] re-attach raised: {_re}", "WARN")
    log(f"[{label}] Brief attachment could NOT be verified after "
        f"{max_attempts} attempts — refusing to fire without the brief", "ERROR")
    return False


async def type_short_inline_prompt(page, platform, label):
    """Type a short inline prompt instructing the agent to research the
    attached brief. Keeps the platform's 'Deep Research' mode as the
    operative instruction; the full brief content lives in the file."""
    # One message, short enough that no platform converts it to an attachment.
    prompt = (
        "Please perform deep research on the topic described in the attached brief. "
        "Use the brief as the complete context — objectives, scope, sections, sources to target. "
        "Produce a comprehensive research report with citations."
    )
    try:
        # Find the composer input (contenteditable or textarea) and type
        for sel in ['div[contenteditable="true"]', 'textarea', '.ProseMirror',
                    '[role="textbox"]', '[aria-label*="message"]']:
            try:
                inp = await page.query_selector(sel)
                if inp:
                    await inp.click()
                    await asyncio.sleep(0.3)
                    await page.keyboard.type(prompt, delay=5)
                    await asyncio.sleep(0.5)
                    log(f"[{label}] Inline prompt typed ({len(prompt)} chars)")
                    return True
            except Exception:
                continue
        log(f"[{label}] Could not find composer input for inline prompt", "WARN")
        return False
    except Exception as e:
        log(f"[{label}] Inline prompt type failed: {e}", "WARN")
        return False


async def type_inline_prompt_with_cua(page, browser, cua_client, platform, label, verbose=False):
    """Type the short operative inline prompt; if the deterministic type
    fails (composer selector miss on a warm/canvas tab), escalate to the
    CUA act tier — the DR agent needs an INSTRUCTION, not just an attached
    brief/pasted chip. Shared by the attach path and the paste→chip top-up
    (2026-07-13 #950: the top-up ignored type_short_inline_prompt's False,
    silently sending a bare chip with no instruction on a selector miss —
    exactly the failure the attach path already guarded)."""
    typed = await type_short_inline_prompt(page, platform, label)
    if typed:
        return True
    log(f"[{label}] Inline prompt type failed — trying CUA fallback", "WARN")
    try:
        await browser.switch_to_page(page)
        _inline_type_sys = "Type a short research prompt referring to the attached brief — then stop (do NOT send)."
        _inline_type_user = ("Click the message input, type: 'Please perform deep research on the topic "
                             "described in the attached brief. Use Deep Research mode and produce a "
                             "comprehensive report with citations.' Then STOP — do not click Send.")

        async def _inline_type_cua():
            return await agent_loop(cua_client, browser,
                _inline_type_sys, _inline_type_user,
                model=CUA_MODEL, max_iterations=6, verbose=verbose)

        # #839 act tier: types the reference prompt but must NOT send
        # (the send is a separate deterministic step); result ignored,
        # verify_*_generating downstream is the ground truth.
        await _shadow_observed_cua(
            page, hotspot_id="inline-type", phase=2, platform=platform.lower(),
            current_step="type_reference_prompt_no_send",
            context_hint="click the composer and TYPE a short prompt referring to the "
                         "attached brief (deep research + citations) — then STOP. Do "
                         "NOT click Send; the send is a separate step.",
            expected_outcome="the reference prompt is typed into the composer (not sent)",
            cua_coro_factory=_inline_type_cua,
            mission_prompt=f"{_inline_type_sys}\n\nTASK: {_inline_type_user}")
        return True
    except Exception as _cua_err:
        log(f"[{label}] Inline-prompt CUA fallback errored: {_cua_err}", "WARN")
        return False


async def ensure_deep_mode_active(page, platform, label, reactivate=True) -> dict:
    """Just-before-send check: is the platform still in its required mode?
    Re-activates if it has been toggled off, then RE-EVALUATES state and
    returns it.

    `reactivate` (default True) — when False, MEASURE ONLY: report the current
    state without re-running setup_*_dr. The Phoenix known-good fallback uses
    this so its pinned model isn't silently undone by the default re-activation
    (which re-picks the HIGHEST model = the one that just failed).

    E2 / DGOPS-7364 — return type was always-True; now returns a state
    dict so the caller can gate Send on whether the required mode is
    genuinely active (Claude specifically can fail Layer 1 + Layer 2 +
    re-activation and still arrive here with research=False; old code
    sent anyway, producing chat-mode output).

    Returns:
        {"platform": "chatgpt"|"gemini"|"claude",
         "active": bool,                # platform-specific overall flag
         # Claude only:
         "hasExtended": bool, "researchOn": bool}

    Errors are logged and treated as active=True (don't block the send
    on a measurement failure — measurement bugs shouldn't gate Send).
    The Claude branch is the only one whose caller actually gates on
    the result for now per DGOPS-7364 scope."""
    platform_l = platform.lower()
    try:
        if platform_l == "chatgpt":
            # 2026-05-29 (#709): return the REAL measured state (was always
            # active=True, so the caller could never gate the send).
            #
            # ⭐ 2026-08-05 — THE SHARED DETECTOR, not a private copy. This branch
            # used to carry its own inline JS demanding the pill's text be EXACTLY
            # "deep research" and testing `placeholder.includes('research')`. The
            # real Deep-Research placeholder is "Get a detailed report", which
            # contains neither, and ChatGPT stopped rendering the pill in the
            # composer at all — so this read returned active=False on a composer
            # that was genuinely in Deep Research.
            #
            # `_CHATGPT_DR_ACTIVE_JS` had already been taught both of those facts,
            # and setup_chatgpt_dr's Step 3 verifies with it. Leaving a second
            # predicate here meant setup could log "verified DR active" and this
            # check could call the same DOM OFF six seconds later — a permanent,
            # unclearable chat-mode gate on every ChatGPT P2 leg (prod 0.1.12,
            # backend.log 07:01:26 vs 07:01:32). One question gets ONE predicate;
            # that is the same rule Step 3's comment states, and this was the copy
            # that never got migrated to it.
            state = await page.evaluate(_CHATGPT_DR_ACTIVE_JS) or {}
            if reactivate and not state.get("active"):
                # Log the placeholder, not just the pill. The pill being absent is
                # now the NORMAL case, so "pillVisible=False" on its own described
                # a healthy composer and read as the fault.
                log(f"[{label}] ChatGPT Deep Research OFF before send "
                    f"(pill={state.get('pillText')!r} "
                    f"placeholder={state.get('placeholder')!r}) — re-activating", "WARN")
                await setup_chatgpt_dr(page)
                state = await page.evaluate(_CHATGPT_DR_ACTIVE_JS) or {}
                log(f"[{label}] ChatGPT DR post-re-activate: active={state.get('active')} "
                    f"placeholder={state.get('placeholder')!r}", "INFO")
            if selfheal and selfheal.is_enabled():
                await _selfheal_shadow_observe(page, "chatgpt.enable_deep_research",
                                               outcome_pass=bool(state.get("active")))
            # Log the POSITIVE outcome too. This probe used to log only when it found
            # DR off, so silence meant either "passed" or "never ran" — which made
            # every "DR was fine here" inference unfalsifiable when reading incidents
            # back (2026-07-27 review). One line per call removes the ambiguity.
            log(f"[{label}] ChatGPT DR pre-send check: active={bool(state.get('active'))}"
                f" reactivate={reactivate} placeholder={state.get('placeholder')!r}", "DEBUG")
            return {"platform": "chatgpt", "active": bool(state.get("active"))}
        if platform_l == "gemini":
            # 2026-05-29 (#709): return the REAL state (was always active=True),
            # using the SHARED _GEMINI_DR_STATE_JS (composer-placeholder
            # authoritative) so this pre-send check and setup_gemini_dr's verify
            # agree exactly. A present-but-inactive pill must NOT read as active.
            st = await page.evaluate(_GEMINI_DR_STATE_JS)
            active = bool(st.get("placeholderResearch") or st.get("pressed"))
            if reactivate and not active:
                log(f"[{label}] Gemini Deep Research not active before send "
                    f"(placeholder={st.get('placeholder')!r}) — re-activating", "WARN")
                await setup_gemini_dr(page)
                st = await page.evaluate(_GEMINI_DR_STATE_JS)
                active = bool(st.get("placeholderResearch") or st.get("pressed"))
                log(f"[{label}] Gemini DR post-re-activate: active={active} "
                    f"placeholder={st.get('placeholder')!r}", "INFO")
                # PX-2 selector heal (DOUBLE-GATED, default OFF): the built-in
                # re-activation still left DR off → one bounded Tier-1.5 heal
                # before the run proceeds in chat mode. Gated on the #709 POSITIVE
                # off-signal (composer placeholder explicitly "Ask Gemini"), so the
                # heal can only ever turn a confirmed-off pill ON, never toggle an
                # active one off. Only Gemini is wired for ACTING today (its
                # placeholder gives a clean off-signal + the pill is a single-click
                # composer control); the other intents stay shadow-only.
                if not active and selfheal and selfheal.act_enabled():
                    async def _gem_dr_active():
                        s = await page.evaluate(_GEMINI_DR_STATE_JS)
                        return bool(s.get("placeholderResearch") or s.get("pressed"))
                    _off = bool(st.get("placeholderChat") and not st.get("placeholderResearch")
                                and not st.get("pressed"))
                    if await _selfheal_try(page, "gemini.enable_deep_research",
                                           check_active=_gem_dr_active, confirmed_off=_off):
                        active = True
                        log(f"[{label}] Gemini DR recovered by selfheal", "INFO")
            if selfheal and selfheal.is_enabled():
                await _selfheal_shadow_observe(page, "gemini.enable_deep_research",
                                               outcome_pass=active)
            # Positive branch logged too — see the ChatGPT note above.
            log(f"[{label}] Gemini DR pre-send check: active={active} "
                f"reactivate={reactivate} placeholder={st.get('placeholder')!r}", "DEBUG")
            return {"platform": "gemini", "active": active}
        if platform_l == "claude":
            # Check BOTH: the model FAMILY is selected AND the Research tool is on.
            # Family word from policy (single source of truth) — passed into the JS.
            # ⛔⛔ THE RUN'S family, not the policy's — this is the reader that
            # made the fallback non-additive. `hasExtended` means "the trigger
            # names the family we are supposed to be on". Asked about the
            # primary family on a run that deliberately selected the fallback,
            # it is False on a perfectly correct composer, so this branch reads
            # "mode regressed" and re-runs the ENTIRE Claude setup before every
            # single send — on every run, for the life of that account.
            _cl_family = _p2_active_family("claude") or "opus"
            _claude_state_js = _CLAUDE_MODE_STATE_JS
            # ⚠ The effort word rides along so the detector can REPORT it, but
            # this gate deliberately ignores it — see the note in the script. A
            # pre-send gate on a quality knob re-runs the whole setup, popover
            # and all, seconds before the brief is submitted.
            _claude_state_arg = {"fam": _cl_family,
                                 "effortWord": p2_labels("claude").get("effort") or "",
                                 "trigTestid": _CLAUDE_MODEL_TRIGGER_TESTID}
            state = await page.evaluate(_claude_state_js, _claude_state_arg)
            if reactivate and (not state.get("hasExtended") or not state.get("researchOn")):
                log(f"[{label}] Claude mode regressed before send "
                    f"(extended={state.get('hasExtended')}, research={state.get('researchOn')}) — re-activating", "WARN")
                await setup_claude_dr(page)
                # ⚠ RE-READ the family too, not just the state. The setup we
                # just ran is what discovers a plan limit, so on the first pass
                # of a non-pro run the family it settled on is newer than the
                # one this function read a moment ago — and re-checking with the
                # stale word would report the fix it just made as still broken.
                _cl_family = _p2_active_family("claude") or _cl_family
                # E2 — re-evaluate AFTER the re-activation attempt so the
                # caller sees the actual final state, not the pre-fix one.
                # If Step 3A/3B selectors are still broken, researchOn will
                # remain False and the caller pauses for user decision.
                _claude_state_arg["fam"] = _cl_family
                state = await page.evaluate(_claude_state_js, _claude_state_arg)
                log(f"[{label}] Claude mode post-re-activate: "
                    f"extended={state.get('hasExtended')}, research={state.get('researchOn')}", "INFO")
                # #744 self-documenting dump: when researchOn STILL reads False
                # the detector's attribute keys (aria-pressed/data-state/active)
                # likely don't match claude.ai's current Research pill. The
                # gate now falls back to the positive CUA confirmation
                # (cua_confirmed) so this is no longer fatal — but dump the
                # composer's research-ish
                # elements so the NEXT E2E pins the real "on" selector for a
                # clean DOM fix (mirrors the Step 3A composer-button dump).
                if not state.get("researchOn"):
                    try:
                        _rdump = await page.evaluate("""() => {
                            const ce = document.querySelector('div[contenteditable="true"], .ProseMirror, [role="textbox"]');
                            let scope = ce;
                            for (let i = 0; i < 6 && scope && scope.parentElement; i++) scope = scope.parentElement;
                            const root = scope || document.body;
                            return [...root.querySelectorAll('button, [role="button"], [role="switch"], [role="checkbox"]')]
                                .filter(b => b.getClientRects().length > 0)
                                .filter(b => /research/i.test((b.textContent || '') + ' ' + (b.getAttribute('aria-label') || '')))
                                .slice(0, 12)
                                .map(b => ({
                                    t: (b.textContent || '').trim().slice(0, 24),
                                    al: (b.getAttribute('aria-label') || '').slice(0, 32),
                                    pressed: b.getAttribute('aria-pressed') || '',
                                    state: b.getAttribute('data-state') || '',
                                    cls: (b.className || '').toString().slice(0, 48),
                                }));
                        }""")
                        log(f"[{label}] #744 Research-pill dump (fix detector from this): {json.dumps(_rdump, ensure_ascii=False)}", "INFO")
                    except Exception as _rde:
                        log(f"[{label}] #744 Research-pill dump failed: {_rde}", "INFO")
            ok = bool(state.get("hasExtended") and state.get("researchOn"))
            if selfheal and selfheal.is_enabled():
                await _selfheal_shadow_observe(page, "claude.enable_deep_research",
                                               outcome_pass=bool(state.get("researchOn")))
                await _selfheal_shadow_observe(page, "claude.select_model",
                                               outcome_pass=bool(state.get("hasExtended")))
            # Positive branch logged too — see the ChatGPT note above.
            log(f"[{label}] Claude DR pre-send check: active={ok} reactivate={reactivate}"
                f" extended={bool(state.get('hasExtended'))}"
                f" research={bool(state.get('researchOn'))}", "DEBUG")
            return {"platform": "claude", "active": ok,
                    "hasExtended": bool(state.get("hasExtended")),
                    "researchOn": bool(state.get("researchOn"))}
    except Exception as e:
        log(f"[{label}] ensure_deep_mode_active error: {e}", "WARN")
    return {"platform": platform_l, "active": True}


async def detect_human_verification(page, platform: str, label: str) -> tuple[bool, str]:
    """Detect if the current page is blocked by a human-verification challenge.

    Looks for the most common gates Claude / ChatGPT / Gemini use when they
    flag the automated browser:
      - Cloudflare Turnstile ("Just a moment..." / iframe[src*=challenges])
      - Generic CAPTCHA iframes (reCAPTCHA, hCaptcha)
      - Claude's own "Verify you are human" interstitial
      - Anthropic's "Checking your browser" intermediate page

    Returns (blocked, reason). `reason` is a short, user-readable string like
    "Cloudflare challenge" or "reCAPTCHA" — safe to surface in a chat banner.

    Never raises — on any detection error, returns (False, "").
    """
    try:
        result = await page.evaluate("""(platformKey) => {
            const findings = [];
            let text = (document.body?.innerText || '').toLowerCase();
            // #896 review catch: composer content is part of body.innerText,
            // and the paste-fail probes run exactly when the pasted research
            // BRIEF may still sit in the composer — a brief about
            // bot-mitigation can quote the very phrases these markers key on
            // (#751/#752 lesson: never substring-match text the pipeline
            // itself typed). Scan the page text MINUS composer subtrees;
            // the structural iframe/selector checks are unaffected.
            try {
                for (const c of document.querySelectorAll(
                        'div[contenteditable="true"], .ProseMirror, rich-textarea, textarea')) {
                    const t = ((c.innerText || c.value) || '').toLowerCase();
                    if (t && t.length > 20) text = text.split(t).join(' ');
                }
            } catch (e) {}

            // Cloudflare Turnstile / "Just a moment..."
            if (document.querySelector('iframe[src*="challenges.cloudflare.com"], iframe[src*="turnstile"], .cf-turnstile, .cf-challenge')) {
                findings.push('Cloudflare');
            }
            if (text.includes('just a moment') && text.includes('cloudflare')) {
                findings.push('Cloudflare');
            }
            if (text.includes('checking your browser') || text.includes('checking if the site connection is secure')) {
                findings.push('Cloudflare');
            }
            // #896 (2026-07-02 live): Claude's IN-APP Cloudflare gate. The
            // parent shell says "Performing security verification" while the
            // "Verify you are human" checkbox text lives inside the
            // cross-origin Turnstile iframe — invisible to body.innerText.
            // Without this marker the gate reads as a generic setup failure.
            // Scoped hard (review catch): the phrase is generic English that
            // can appear in research CONTENT (a security-topic brief in a
            // composer, a NotebookLM notebook titled from the topic), and
            // Claude is the only platform behind Cloudflare — so require
            // platform==claude AND the composer to be unmounted (the gate
            // removes it; live signature was "Composer not found").
            if (platformKey === 'claude' &&
                text.includes('performing security verification') &&
                !document.querySelector('div[contenteditable="true"], .ProseMirror')) {
                findings.push('Cloudflare');
            }

            // Google reCAPTCHA
            if (document.querySelector('iframe[src*="recaptcha"], .g-recaptcha, #recaptcha')) {
                findings.push('reCAPTCHA');
            }

            // hCaptcha
            if (document.querySelector('iframe[src*="hcaptcha"], .h-captcha')) {
                findings.push('hCaptcha');
            }

            // Claude / Anthropic human-verification interstitials
            if (text.includes('verify you are human') || text.includes('are you a human') ||
                text.includes('please complete the security check') ||
                text.includes('press and hold') || text.includes('tap and hold')) {
                findings.push('Claude human verification');
            }

            // Generic "blocked" / access-denied pages that we should surface
            if (text.includes('access denied') && text.length < 1000) {
                findings.push('Access denied');
            }

            return { findings: [...new Set(findings)] };
        }""", platform.lower())
        findings = result.get("findings", []) if isinstance(result, dict) else []
        if findings:
            return True, findings[0]
        return False, ""
    except Exception as e:
        log(f"[{label}] human-verification detect error: {e}", "WARN")
        return False, ""


async def detect_session_expiry(page, platform: str, label: str) -> tuple[bool, str]:
    """Detect if an agent page has lost its session mid-run (redirect to
    login URL, login form appeared, or "sign in to continue" message).

    Distinct from detect_human_verification — that handles CAPTCHA / Cloudflare.
    This handles actual logged-out state where the user needs to re-authenticate
    on their PC before the pipeline can resume.

    Returns (expired, reason). Never raises."""
    try:
        url = (page.url or "").lower()
        # URL markers for known login routes per platform
        url_markers = {
            # NB: matched against a LOWERCASED url — markers must be lowercase
            # (the old "…/serviceLogin" camelCase marker could never fire).
            # /v3/signin is where Google's sign-in flow actually RESTS; the
            # legacy /servicelogin is a 302 hop toward it.
            "chatgpt":    ("/auth/login", "/auth/signin", "auth.openai.com"),
            "gemini":     ("accounts.google.com/signin", "accounts.google.com/servicelogin",
                           "accounts.google.com/v3/signin"),
            "claude":     ("/login", "/sign-in", "/auth/"),
            "notebooklm": ("accounts.google.com/signin", "accounts.google.com/servicelogin",
                           "accounts.google.com/v3/signin"),
        }
        markers = url_markers.get(platform.lower(), ("/login", "/signin", "/signup"))
        if any(m in url for m in markers):
            return True, "redirect_to_login_url"

        # DOM markers: visible password field + no active chat UI
        result = await page.evaluate("""() => {
            const pwInput = document.querySelector('input[type="password"]:not([style*="display: none"])');
            if (!pwInput) return { expired: false };
            // Heuristic: if there's a visible password input AND no chat composer/send button,
            // we're on a login page. Use offsetParent check to filter hidden elements.
            if (pwInput.offsetParent === null) return { expired: false };
            const hasComposer = document.querySelector(
                '[data-testid="send-button"], button[aria-label*="Send prompt"], ' +
                'div[contenteditable="true"]#prompt-textarea, ' +
                'textarea[placeholder*="Message"], [data-test-id="send-button"]'
            );
            if (hasComposer) return { expired: false };
            const text = (document.body.innerText || '').toLowerCase();
            const loginPhrases = ['sign in to', 'log in to', 'please sign in',
                'welcome back', 'enter your password', 'email address'];
            const hasLoginText = loginPhrases.some(p => text.includes(p));
            return { expired: hasLoginText };
        }""")
        if isinstance(result, dict) and result.get("expired"):
            return True, "login_form_appeared"
        return False, ""
    except Exception as e:
        log(f"[{label}] session-expiry detect error: {e}", "WARN")
        return False, ""


def _hv_fail_copy(platform: str, reason: str) -> tuple[str, str]:
    """#896: user-facing (title, details) for a human-verification failure.

    Gap #1 + HV never-solve (user directive 2026-07-15): HV == Cloudflare ==
    the SAME — ALL verification walls are hands-off + Skip-only. Any attempt to
    clear one from the automation window (a Retry re-navigates the walled tab,
    a click/CUA hammers the challenge) re-issues it and RAISES the bot score,
    so no card offers Retry. Cloudflare keeps its distinct copy (it self-clears
    on decay); every other challenge shares one hands-off message. The user can
    solve any of them by hand in the open browser and re-run.
    2026-07-09 (user): keep the copy short + to the point and do NOT tell the
    user to run the login command (it isn't the right fix for a wall)."""
    _names = {"claude": "Claude", "gemini": "Gemini", "chatgpt": "ChatGPT"}
    plat = _names.get(platform.lower(), platform.capitalize())
    if "cloudflare" in (reason or "").lower():
        return (
            f"{plat} hit Cloudflare's human check",
            f"It can't be cleared from here — trying only makes Cloudflare ask harder. "
            f"Skip {plat} for this run; if it clears on its own, the run resumes automatically.",
        )
    # Unified hands-off (no "then Retry"): a Retry would re-navigate the walled
    # tab and raise the bot score, the same failure mode as Cloudflare.
    return (
        f"{plat} needs a human check",
        f"{plat} is showing a human-verification challenge"
        f"{f' ({reason})' if reason else ''}. It can't be cleared from here without "
        f"raising the bot score — Skip {plat} for this run. You can solve it by hand "
        f"in the open browser and re-run if you want it back.",
    )


async def _close_skipped_agent_tab(browser, page, platform_key: str, label: str,
                                   preserve_tab: bool = False,
                                   final_status: str = "skipped") -> None:
    """#906: finalize a user Skip by CLOSING the skipped platform's tab.

    Pre-fix, NO skip path anywhere closed a tab — the skipped platform's
    window stayed open, and (for a Cloudflare-walled Claude) the round-robin
    skip consumer even kept touching it. Closing makes Skip mean skip.
    Guards mirror the hard-retry close (~poll_all_agents_round_robin): never
    close the browser's main page or the context's LAST page (headful Chrome
    exits with its last window → dead context for the rest of the run), and
    never close a caller-preserved warm-reuse tab — those are only
    unregistered from the mid-run dispatcher.

    #953 (audit): `final_status` — the runtime agent_status the unregister
    stamps. Defaults to 'skipped', but the completed-agent clobber-guard passes
    'done' so closing a stale leftover STUB tab can't demote a genuinely-done
    agent's status to 'skipped' (which would make pause/resume re-open + re-poll
    the completed conversation)."""
    try:
        _runtime.unregister_page(platform_key, final_status=final_status)
    except Exception:
        pass
    if page is None:
        return
    try:
        if page.is_closed():
            return
    except Exception:
        return
    keep_open = bool(preserve_tab) or (page is getattr(browser, "page", None))
    if not keep_open:
        try:
            keep_open = len(page.context.pages) <= 1
        except Exception:
            keep_open = False
    if keep_open:
        log(f"[{label}] Skip: leaving the {platform_key} tab open (main/last tab)", "INFO")
        return
    try:
        await page.close()
        log(f"[{label}] Skip: closed the {platform_key} tab", "INFO")
    except Exception as _ce:
        log(f"[{label}] Skip: couldn't close the {platform_key} tab: {_ce}", "WARN")


def autoskip_reason_for_status(results_status: str) -> tuple:
    """Classify an unresolved agent's result status into
    ``(reason, copy_key, why)`` for the exit-sweep auto-skip finalize.

    2026-07-31. Every unresolved finalize used to report `auto_skip_setup_failed`
    / "startup failed", whatever had actually happened. The observed cost: a
    Claude leg that was verified running at roll-call, ran a live Deep Research
    for 41 minutes, and then failed on claude.ai's side was reported to the user
    as "couldn't start". That is not just untidy copy — it points the user at
    their own login and setup when nothing there was wrong, and (because the
    reason slug is what reaches the FE) it is why the phase dropdown could only
    ever render the bare word "skipped" for that run.

    Three real outcomes:
      * never started      — `failed_setup` / `not_verified` (also the default
                             for an unrecognised status, since "we don't know"
                             is closer to a setup problem than to a claim that
                             the research ran).
      * failed mid-run     — `agent_error`: the agent WAS verified running and
                             its research then failed platform-side.
      * retried, no output — the hard-retry statuses.
      * tab lost           — `browser_crashed` / `wrong_conversation` / `empty`.

    2026-08-22 — the fourth outcome, and the reason it is not an unknown. All
    three of those statuses are written ONLY while iterating `pending`, and
    `pending` is seeded solely for agents whose page survived 2A/2B/2C setup. So
    STARTUP SUCCEEDING IS A PRECONDITION for any of them existing — a crashed
    tab, a tab that drifted into someone else's conversation, and an extraction
    that came back empty all describe an agent that was up and running. Routing
    them through the "couldn't start" default is the same defect the 2026-07-31
    note below describes, in three statuses that note did not enumerate: it
    points the user at their own login when nothing there was wrong.

    Pure and module-level on purpose: the caller is a closure inside
    ``poll_all_agents_round_robin``, which a test cannot drive, so the decision
    lives somewhere a test can call it directly.
    """
    st = (results_status or "").lower()
    if st == "agent_error":
        return ("auto_skip_agent_error", "mid_run_failed",
                "its research failed on the platform's side partway through")
    if st in ("hard_retry_failed", "hard_retry_exhausted_dead_tab"):
        return ("auto_skip_hard_retry_exhausted", "hard_retry_exhausted",
                "was retried and still produced no report")
    # ⛔⛔ 2026-08-27 — `browser_crashed` IS SPLIT OUT, AND THE OWNER IS RIGHT THAT
    # IT HAD TO BE. It was sharing the "we lost the tab we were reading it through"
    # sentence, which names OUR end of the failure and reads to a user as though
    # our pipeline dropped their research. Measured from a real run: Gemini sat on
    # "Writing your report…" for FORTY-SEVEN MINUTES with zero growth — 133 sites,
    # 37 steps, and not one character of report — and our own arbiter twice looked
    # at the page and ruled "WORKING, not a frozen state" before the page died.
    # The failure began on the platform and ended in our tab.
    # ▶ Owner's standing rule, 08-27: when the platform stalls or hands us
    #   something new, SAY PLATFORM-SIDE. Extraction is good in ordinary
    #   circumstances, so blaming ourselves for their stall teaches the user to
    #   distrust the part that works.
    # ⚠ Scoped deliberately: `wrong_conversation` and `empty` keep the old copy.
    #   A tab that WANDERED is genuinely our end, and an empty read is not
    #   measured yet — neither gets a story it has not earned.
    if st == "browser_crashed":
        return ("auto_skip_platform_crashed", "platform_crashed",
                "was running on the platform's own page when that page failed")
    if st in ("wrong_conversation", "empty"):
        return ("auto_skip_tab_lost", "tab_lost",
                "started and ran, then we lost the tab we were reading it through")
    # ⚠ The default stays "couldn't start", deliberately. It is the honest answer
    # for "" / None / a status this function has never seen: an unknown is closer
    # to a setup problem than to a CLAIM that the research ran and died, which
    # would be a fabricated story. Only statuses proved to require a live page
    # get moved out of it.
    return ("auto_skip_setup_failed", "setup_failed", "couldn't start")


def _autoskip_details(copy_key: str, name: str, why: str = "") -> str:
    """#955: single source for the auto-skip informational notice. One entry
    per finalize site, byte-identical to the pre-refactor inline copies —
    all share the honest tail so the user always learns WHY an agent greyed."""
    _tail = "— skipped so your run can finish. The other agents aren't affected."
    if copy_key == "claude_2artifact":
        return (f"{name}'s report never finished and the retry prompt went "
                f"unanswered {_tail}")
    if copy_key == "setup_failed":
        return (f"{name} couldn't start (a platform-side setup or "
                f"delivery problem) and its Retry/Skip alert wasn't "
                f"answered {_tail}")
    # 2026-07-31: `setup_failed` used to be the copy for EVERY unresolved
    # finalize, including agents that started cleanly, were verified running at
    # roll-call, and then died on the platform's side mid-research. One observed
    # run had Claude verified running, research live for 41 minutes, and the card
    # still told the user "couldn't start". That is not a nicety: it points the
    # user at their login/setup when the actual cause was claude.ai failing
    # server-side, and it is the reason the phase dropdown could only ever say
    # the bare word "skipped".
    if copy_key == "mid_run_failed":
        return (f"{name} started fine but its research failed on the platform's "
                f"side partway through, and its Retry/Skip alert wasn't "
                f"answered {_tail}")
    if copy_key == "hard_retry_exhausted":
        return (f"{name} was retried and still couldn't produce a report {_tail}")
    if copy_key == "hard_cap_parked":
        return (f"{name} sat on an unanswered alert past the time "
                f"limit {_tail}")
    # 2026-08-22. Note this one deliberately DROPS the "and its Retry/Skip alert
    # wasn't answered" clause every neighbour carries: a crashed tab emits a
    # passive recovery banner and no decision card at all, so claiming the user
    # ignored an alert would be a second false statement layered on the first.
    if copy_key == "platform_crashed":
        # ⛔ Says WHERE it failed and stops implying we mislaid it. The research
        # was live on the platform's own page and that page went down; nothing on
        # our side chose this, and a user reading "we lost the tab" would take it
        # as ours. See `_autoskip_reason` for the run this was measured from.
        return (f"{name}'s research was running on {name}'s own page when that "
                f"page stopped responding, so the report could never be read "
                f"{_tail}")
    if copy_key == "tab_lost":
        return (f"{name} started and ran, but its browser tab was lost before "
                f"we could read the report {_tail}")
    if copy_key == "stuck":
        return f"{name} {why} {_tail}"
    if copy_key == "hv_wall":
        return (f"{name} hit a verification wall that wasn't cleared in time "
                f"{_tail}")
    if copy_key == "chat_mode":
        return (f"{name} couldn't run Deep Research and the "
                f"continue-in-chat-mode alert went unanswered {_tail}")
    raise KeyError(f"unknown auto-skip copy_key {copy_key!r}")


async def _finalize_agent_autoskip(browser, page, key: str, name: str, *,
                                   reason: str, copy_key: str,
                                   partial: str = "", url: str = "",
                                   elapsed_sec: int = 0, why: str = "",
                                   phase: int = 2, results=None,
                                   results_name: str | None = None,
                                   final_status: str = "skipped") -> None:
    """#955: THE one auto-skip finalize — replaces the four inline copies
    (Claude 2-artifact hard-fail, the unresolved-setup-fail exit sweep, the
    parked hard-cap, and the stuck Layer-3). One consistent shape for EVERY
    auto-skip: record the result (status='auto_skipped', salvaged partial,
    dead page handle), emit `agent_skipped` (greys the tile + clears the card
    and durable pendingDecision + persists status), post the informational
    `pipeline_warning` notice (NOT an error card — the agent is resolved),
    and close the tab. Salvage extraction stays with the CALLER (it needs
    extract_fns/cua_client and the hv_blocked hands-off guard), as does any
    `del pending[...]`. NB: reason strings are not 1:1 with copy_keys —
    'auto_skip_hard_cap' fires from both the parked-cap and the L3 branch."""
    if results is not None:
        results[results_name or name] = {
            "status": "auto_skipped", "text": partial,
            "url": url, "page": None, "elapsed_sec": int(elapsed_sec),
        }
    _detail = _autoskip_details(copy_key, name, why)
    # 2026-07-31: carry the human-readable WHY on `agent_skipped` itself, not
    # only on the companion notice. The notice is a dismissible banner; the
    # phase dropdown reads the agent's own detail row, and it had nothing to
    # read, so every auto-skip rendered as the bare word "Skipped" no matter how
    # much the backend actually knew. Sending the sentence means the dropdown
    # stays honest for reasons the FE has never heard of — a new auto-skip path
    # explains itself without an FE release, which is the same reason the
    # NotebookLM host became a shape test.
    emit_event("agent_skipped", phase=phase, agent=key,
               reason=reason, partial_chars=len(partial), detail=_detail)
    emit_event("pipeline_warning", phase=phase, agent=key,
               error=f"{name} skipped automatically",
               details=_detail,
               actions=[], alert_id=f"agent_{key}_autoskip",
               auto_clear_on_resume=True)
    try:
        await _close_skipped_agent_tab(browser, page, key, name,
                                       final_status=final_status)
    except Exception as _fce:
        log(f"[{name}] Auto-skip finalize: tab close failed ({_fce})", "WARN")


async def _hv_auto_skip_finalize(browser, page, agent_key: str, label: str,
                                 phase: int = 2, preserve_tab: bool = False,
                                 release_pause: bool = False) -> None:
    """Clean auto-skip for an unacted hands-off HV wall (Skip is the only real
    move for Cloudflare). Mirrors the L3 stuck-agent auto-skip dynamics so the
    UX is consistent: greys the tile (agent_skipped) with an HONEST reason,
    posts an informational notice (NOT a red error card), retracts the decision
    mirror, and closes the walled tab. The agent is marked in hv_auto_skipped so
    the round-robin skip consumer neither re-emits nor re-extracts (hands-off).

    Caller gates this on `_runtime.auto_skip_stuck` — when auto-skip is OFF the
    HV card stays up for a manual Skip instead."""
    # Gap #1: idempotent. The non-blocking HV path can reach this both from
    # start_agent_no_gemini_wait's hands-off handoff AND from the run_phase2
    # setup-fail handler's _hv_setup_fail_card on the same agent — the second
    # call must not re-emit agent_skipped / re-close the (already-closed) tab.
    if agent_key in _controls.hv_auto_skipped:
        log(f"[{label}] HV auto-skip already finalized for {agent_key} — "
            "skipping duplicate", "DEBUG")
        return
    _name = {"chatgpt": "ChatGPT", "claude": "Claude", "gemini": "Gemini"}.get(
        agent_key, agent_key.capitalize())
    log(f"[{label}] HV auto-skip — verification wall unanswered; greying {agent_key} "
        "+ closing tab (hands-off)", "WARN")
    _controls.skipped_agents.add(agent_key)
    _controls.hv_auto_skipped.add(agent_key)
    # agent_skipped greys the tile + retracts any live HV card (emit hook flips
    # the persisted status to "skipped" and clears the pendingDecision mirror).
    emit_event("agent_skipped", phase=phase, agent=agent_key,
               reason="auto_skip_hv_unanswered")
    # If this finalizer resolves an ACTIVE HV pause (the unacted-grace timeout
    # path, release_pause=True), release it. The skipped_agents.add above went
    # in DIRECTLY (not via request_skip_agent), so pause_event is STILL set —
    # the round-robin's per-tick pause check would freeze the whole run, and
    # the FE would stay stuck "Paused MM:SS" with the input locked because no
    # pipeline_resumed ever arrives (the exact bug the user reported for auto
    # skips). Emit pipeline_resumed BEFORE the informational warning below so
    # the resume's auto-clear-on-resume sweep doesn't wipe the notice we post.
    # The setup-fail caller (no active pause) passes release_pause=False so this
    # can't spuriously drop an unrelated agent's live pause.
    if release_pause:
        _controls.request_resume()
        emit_event("pipeline_resumed", phase=phase, agent=agent_key,
                   reason="auto_skip_hv_unanswered")
    # Informational (not an error card — the agent is resolved, not awaiting a
    # decision), so the user learns WHY it greyed. Mirrors the L3 notice.
    emit_event("pipeline_warning", phase=phase, agent=agent_key,
               error=f"{_name} skipped automatically",
               details=_autoskip_details("hv_wall", _name),
               actions=[], alert_id=f"agent_{agent_key}_autoskip",
               auto_clear_on_resume=True)
    _clear_pending_decision()
    await _close_skipped_agent_tab(browser, page, agent_key, label,
                                   preserve_tab=preserve_tab)


async def _hv_setup_fail_card(browser, page, platform: str, label: str) -> bool:
    """#896: when setup/paste fails, check whether the REAL cause is a
    human-verification wall and, if so, emit an honest HV card instead of
    the caller's generic "didn't start" card.

    Probes the already-open page (zero navigations) plus the sticky
    `_controls.hv_blocked` verdict — the HV cascade's kill-tab tier closes
    the caller's page object, so a live probe alone can go blind exactly
    when the wall was worst. Returns True iff an HV card was emitted
    (caller must then skip its generic fail_agent)."""
    platform_key = platform.lower()
    reason = _controls.hv_blocked.get(platform_key, "")
    if not reason:
        try:
            blocked, reason = await detect_human_verification(page, platform, label)
            if not blocked:
                return False
            reason = reason or "Human verification challenge"
            _controls.hv_blocked[platform_key] = reason
        except Exception:
            return False
    title, details = _hv_fail_copy(platform, reason)
    # #896 review catch: a stale-cookie login redirect can be SERVED WITH
    # Cloudflare's challenge (managed challenge at /login for a distrusted
    # client), so an HV verdict does not rule out "also signed out". Keep the
    # HV card (its real-Chrome guidance is the winnable move either way) but
    # preserve #893's bookkeeping so the next gate check runs the full verify
    # instead of re-trusting the stale cookie jar.
    try:
        _wall = await _page_shows_login_wall(page)
    except Exception:
        _wall = None
    if _wall:
        _controls.cookie_trust_broken.add(platform_key)
        log(f"[{label}] HV wall coincides with {_wall} — session also looks signed out; cookie trust broken", "WARN")
        details += (" This profile also looks signed out, so the sign-in via the "
                    "login command is required, not optional.")
    # Auto-skip an unacted hands-off wall (Skip is the only real action) so the
    # run finishes on its own with the agent cleanly GREYED — not a lingering
    # red error card the user must tap. When auto-skip is OFF, keep the Skip-only
    # card for a manual skip.
    if _runtime.auto_skip_stuck:
        log(f"[{label}] setup failed ON a human-verification wall ({reason}) — auto-skipping (grey, hands-off)", "WARN")
        await _hv_auto_skip_finalize(browser, page, platform_key, label, phase=2)
        return True
    log(f"[{label}] setup failed ON a human-verification wall ({reason}) — emitting HV card, not the generic fail", "WARN")
    # Gap #1 + HV never-solve (user directive 2026-07-15): ALL HV is Skip-only,
    # not just Cloudflare. A Retry (hard) re-navigates the walled surface — the
    # exact touch the directive forbids (raises the bot score for reCAPTCHA /
    # hCaptcha / Claude-HV walls too, not only Cloudflare). Unconditional
    # skip_only=True closes the non-Cloudflare Retry-re-nav hole (adversarial
    # finding #6, 2026-07-15).
    fail_agent(platform_key, title, details, skip_only=True)
    return True


async def _playwright_hv_click(page, label: str) -> bool:
    """Cheap DOM-based HV click. Returns True iff we actually clicked
    something. No budget for image-puzzles — those fall through to CUA.

    NEVER-DIE-MIGRATION-2026-04-18: Tier 0 of the HV chain. Cloudflare
    Turnstile is cross-origin-iframe'd so we can't touch its DOM, but we
    can mouse.click at the checkbox's known position inside the iframe.
    For in-page 'Verify you are human' / 'Continue' buttons, plain
    locator clicks work."""
    # Cloudflare Turnstile — checkbox inside a cross-origin iframe.
    try:
        cf = page.locator(
            'iframe[src*="challenges.cloudflare.com"], iframe[src*="turnstile"]'
        ).first
        if await cf.count() > 0:
            box = await cf.bounding_box()
            if box:
                # The checkbox sits ~30px in from the iframe's left edge,
                # vertically centered. Cross-origin body is unreachable
                # but mouse events at page coordinates land inside it.
                cx = box["x"] + 30
                cy = box["y"] + box["height"] / 2
                await page.mouse.click(cx, cy)
                log(f"[{label}] Playwright: clicked Turnstile checkbox at ({cx:.0f},{cy:.0f})")
                return True
    except Exception as e:
        log(f"[{label}] Playwright Turnstile click errored: {e}", "WARN")
    # In-page 'Verify you are human' / 'Continue' / 'I am human' buttons.
    for sel in (
        'button:has-text("Verify you are human")',
        'button:has-text("I am human")',
        'button:has-text("I\'m human")',
        'button:has-text("Continue")',
    ):
        try:
            loc = page.locator(sel).first
            if await loc.count() > 0 and await loc.is_visible():
                await loc.click(timeout=3000)
                log(f"[{label}] Playwright: clicked '{sel}'")
                return True
        except Exception:
            continue
    return False


async def wait_for_verification_clearance(browser, cua_client, page, platform: str, label: str,
                                          verbose=False, max_wait_loops: int = 120,
                                          phase: int = 2, initial_reason: str = "",
                                          preserve_tab: bool = False) -> bool:
    """Handle a human-verification gate on an agent page.

    Flow (NEVER-DIE-MIGRATION-2026-04-18, full HV chain):
      0. Playwright cheap-click — cross-origin iframe click on the
         Turnstile checkbox, or in-page 'Verify you are human' button.
         Zero CUA budget; most Cloudflare checkboxes clear here.
      1. CUA in-place (3 iter) — vision click for whatever Playwright
         missed. Silent on success.
      2. 3-minute cooldown + page reload — lets Cloudflare's bot score
         decay, re-runs stealth init against a fresh document.
      3. CUA retry (5 iter) — second pass on the reloaded page.
      4. Kill-tab — close the page, open a fresh tab at the same URL.
         A new cookie jar + clean document sometimes clears a stuck
         session that the reload alone couldn't.
      5. User pause — human_verification_required alert with
         Resume / Skip agent. Polls every 5s so a manual solve auto-
         resumes even if the user never taps Resume.

    2026-07-06 HANDS-OFF CLOUDFLARE (user directive, supersedes the earlier
    same-day HV-trim): for a POSITIVELY-identified CLOUDFLARE wall the
    automation touches NOTHING — no DOM click (tier 0), no CUA (tiers 1/3),
    no Vision, no cooldown+reload (tier 2: two cold navigations), no
    kill-tab (tier 4). Every interaction is a failed attestation that
    re-issues the challenge and raises the bot score (#896). Cloudflare's
    entire path is: passive 15s settled probe (pure DOM reads — the JS-only
    interstitial often auto-resolves) → tier 5 user alert with SKIP as the
    only action. The wall is left untouched for the user to solve later via
    a real-Chrome sign-in (the login command); the tier-5 poll is passive,
    so a naturally-decayed or hand-solved check still auto-resumes the run.
    Non-Cloudflare and unknown challenges keep the full chain — their
    buttons genuinely work. The Cloudflare verdict is STICKY (see _cf_seen).

    preserve_tab (2026-07-06, warm-tab reuse): True = `page` is a tab the
    caller must keep alive (the reused P1/main ChatGPT tab) — tier-4's
    close+new_tab is skipped for ANY challenge type, because the replacement
    page never reaches the caller (tier-4 rebinds only the local `page`) and
    closing the caller's handle would strand it on a dead tab.

    `phase` parameter routes all emit_event calls to the correct phase tile
    in the frontend — default 2 for Phase 2 agents, pass 1/3/4/5 when
    calling from other phase handlers.
    """
    # Detect the specific challenge for banner copy AND to confirm there
    # IS one to solve before bothering CUA.
    # #896 review catch: this single top probe can land in a detection gap
    # (the in-app gate transitions between its parent-shell-text phase and
    # its iframe phase; a probe error fails open to "") — so seed from the
    # caller's already-confirmed reason and let every later probe REFRESH
    # the value. An empty reason is treated as UNKNOWN, never as "not
    # Cloudflare" — unknown gets the settled double-probe.
    _, _top_reason = await detect_human_verification(page, platform, label)
    reason = _top_reason or initial_reason
    platform_key = platform.lower()
    # 2026-07-06 review catch: the Cloudflare verdict is STICKY for this
    # cascade's lifetime. detect_human_verification's generic "verify you are
    # human" marker can label a REAL Cloudflare wall as a platform check
    # whenever the Turnstile iframe is mid-teardown/re-issue (the #896 gap the
    # tier-0 click itself opens) — an unguarded `reason = _fresh` would then
    # DOWNGRADE a confirmed Cloudflare verdict and re-arm every skipped tier.
    # Once any probe positively says Cloudflare, it stays Cloudflare.
    _cf_seen = False

    def _is_cloudflare() -> bool:
        """2026-07-06 HV-trim: Cloudflare's checkbox is a browser attestation
        the automation window can't pass — it re-issues after every click
        (#896, live 2026-07-02) — and every extra click/navigation RAISES the
        bot-score that caused the challenge, snowballing into the next run
        ("continuous HV after one run"). So for a POSITIVELY-identified
        Cloudflare wall we allow exactly ONE cheap click (Tier 0), keep the
        decay-based cooldown+reload (the code-endorsed move), and skip the
        score-raising tiers: the CUA click passes (they'd hammer the checkbox)
        and the kill-tab (another cold nav; attestation is profile+IP-scoped,
        a fresh tab doesn't reset it). Unknown/non-Cloudflare challenges keep
        the full cascade — their buttons genuinely work. Reads the enclosing
        `reason` (probe-refreshed) and LATCHES: a Cloudflare verdict is never
        downgraded by a later gap-landing probe (see _cf_seen above)."""
        nonlocal _cf_seen
        if "cloudflare" in (reason or "").lower():
            _cf_seen = True
        return _cf_seen

    _is_cloudflare()  # latch a Cloudflare verdict seeded by the caller/top probe

    async def _settled_clear() -> bool:
        """#896: Cloudflare re-issues its checkbox seconds after a click that
        fails browser attestation — a single probe can land in the gap
        between re-issues and report a false clear, after which the run
        burns its setup/paste budget against a walled page (live
        2026-07-02). Only a POSITIVELY-known non-Cloudflare challenge gets
        the single-probe fast path; Cloudflare AND unknown get a second
        probe ~5s later (the fast-path check goes through the STICKY
        _is_cloudflare, so a gap-downgraded reason can't re-open it). A
        closed page can never certify a clear (its probes fail open to "no
        challenge"). Reads the enclosing `page` and refreshes the enclosing
        `reason`, so it follows the kill-tab tier's fresh tab and the gate's
        phase transitions automatically."""
        nonlocal reason
        try:
            if page.is_closed():
                return False
        except Exception:
            return False
        blocked_now, _fresh = await detect_human_verification(page, platform, label)
        if _fresh:
            reason = _fresh
        if blocked_now:
            return False
        if reason and not _is_cloudflare():
            return True
        await asyncio.sleep(5)
        blocked_now, _fresh = await detect_human_verification(page, platform, label)
        if _fresh:
            reason = _fresh
        return not blocked_now

    def _mark_cleared():
        _controls.hv_blocked.pop(platform_key, None)

    # ── Tier 0: Playwright cheap-click ──
    # A direct Playwright click clears simple platform-native checks for
    # zero CUA cost. Keep the banner subtle here — only escalate to
    # "retrying" alert if this attempt fails.
    # 2026-07-06 (user directive, hands-off Cloudflare): SKIPPED for a
    # confirmed Cloudflare wall — even the "one cheap click" is a failed
    # attestation that re-issues the challenge and raises the bot score.
    # NOTHING (DOM, CUA, Vision) touches a Cloudflare wall anymore; it is
    # left untouched for the user to solve later via a real-Chrome login.
    if _is_cloudflare():
        log(f"[{label}] Cloudflare wall — hands-off policy: no DOM click (every touch raises the score)")
    else:
        try:
            clicked = await _playwright_hv_click(page, label)
            if clicked:
                await asyncio.sleep(3)
                if await _settled_clear():
                    log(f"[{label}] Playwright cleared verification ✓ — CUA not needed")
                    emit_event("agent_verified", phase=phase, agent=platform_key)
                    _mark_cleared()
                    return True
                log(f"[{label}] Playwright click didn't clear — escalating to CUA", "WARN")
        except Exception as e:
            log(f"[{label}] Playwright HV tier errored: {e} — escalating to CUA", "WARN")

    # ── CUA fallback — first pass (in place, 3 iterations) ──
    # Most Turnstile gates are a single "I am human" checkbox that CUA can
    # click. This keeps us silent in the common case. Only if it can't do we
    # cool down + reload and try once more, or (last) ask the user.
    # 2026-07-06 HV-trim: SKIPPED for a confirmed Cloudflare wall — Tier 0
    # already spent the one allowed click; a CUA pass would re-click the
    # attestation checkbox up to 3 more times, each a score-raising no-op.
    sys_prompt = (
        "You are looking at a human-verification challenge (Cloudflare, CAPTCHA, or similar) "
        "that is blocking access to an AI agent. If you can see a simple checkbox or button labeled "
        "something like 'I am human', 'Verify', 'Continue', or 'Not a robot' — click it once. "
        "Do NOT try to solve image-selection puzzles or anything requiring complex reasoning. "
        "If there's nothing simple to click, STOP immediately and respond with the word 'blocked'."
    )
    user_prompt = "Click the single human-verification checkbox if one is visible. Otherwise stop and say 'blocked'."
    if _is_cloudflare():
        log(f"[{label}] Cloudflare wall — skipping the CUA click pass (re-clicks re-issue + raise the score; #896)")
        # Cloudflare's JS-only "checking your browser" interstitial (no
        # checkbox) often AUTO-RESOLVES in seconds with zero interaction —
        # wait briefly and settled-probe (pure DOM reads, sends nothing to
        # the page) before bothering the user. This is the ONLY pre-alert
        # step Cloudflare gets: 2026-07-06 user directive makes the wall
        # fully hands-off — no click, no CUA, no Vision, no cooldown
        # reload, no fresh tab. Straight to the user alert below.
        await asyncio.sleep(15)
        if await _settled_clear():
            log(f"[{label}] Cloudflare check auto-resolved ✓ — no interaction needed")
            emit_event("agent_verified", phase=phase, agent=platform_key)
            _mark_cleared()
            return True
    else:
        try:
            log(f"[{label}] Verification detected ({reason or 'unknown'}) — CUA fallback (3 iter, in place)…")
            await browser.switch_to_page(page)
            result = await agent_loop(cua_client, browser, sys_prompt, user_prompt,
                model=CUA_MODEL, max_iterations=3, verbose=verbose)
            # Give the page a moment to re-render after a successful click
            await asyncio.sleep(3)
            if await _settled_clear():
                log(f"[{label}] CUA cleared verification ✓ — proceeding silently")
                # Clear the dropdown badge immediately so the user sees recovery.
                emit_event("agent_verified", phase=phase, agent=platform_key)
                _mark_cleared()
                return True
            _cua_text = (result.get("text") or "")[:120]
            log(f"[{label}] CUA first pass didn't clear ({_cua_text}) — cooldown + reload + retry", "WARN")
        except Exception as e:
            log(f"[{label}] CUA first pass errored: {e} — cooldown + reload + retry", "WARN")

    # ── CUA fallback — second pass (cooldown + reload, 5 iterations) ──
    # The bot-score heuristic partially decays with time, and a clean
    # page navigation (blank → original URL) re-runs the stealth init script
    # against a fresh document, which often defuses a recently-flagged session.
    # If the check still fires, CUA gets more iterations this time around
    # since it's our last auto-resort before bothering the user.
    # 2026-07-06 (user directive, hands-off Cloudflare): the ENTIRE tier is
    # skipped for Cloudflare — the about:blank + reload pair is two cold
    # navigations against a profile+IP-scoped attestation, feeding the very
    # score that fired the challenge. Cloudflare goes straight to the user
    # alert (Skip-only) below.
    if _is_cloudflare():
        log(f"[{label}] Cloudflare wall — hands-off policy: no cooldown/reload; straight to the user alert")
    else:
        try:
            original_url = page.url
            log(f"[{label}] CUA fallback retry: blank → 3 min cooldown → reload → CUA (5 iter)…")
            try:
                await page.goto("about:blank", wait_until="domcontentloaded", timeout=10000)
            except Exception:
                pass
            await asyncio.sleep(180)
            try:
                await page.goto(original_url, wait_until="domcontentloaded", timeout=30000)
                await asyncio.sleep(4)
            except Exception as e:
                log(f"[{label}] Reload failed: {e} — escalating to user", "WARN")

            blocked, _fresh_r = await detect_human_verification(page, platform, label)
            if _fresh_r:
                reason = _fresh_r  # keep the verdict/copy tracking the latest observed wall
            if blocked:
                # A confirmed-Cloudflare verdict can first LATCH here (the top
                # probe landed in a detection gap and the cascade ran as
                # "unknown"): stop re-clicking the moment it's known.
                if _is_cloudflare():
                    log(f"[{label}] Cloudflare still present after cooldown — no re-click; settled probe decides")
                else:
                    log(f"[{label}] Turnstile still present after cooldown — CUA 5-iter retry")
                    await browser.switch_to_page(page)
                    await agent_loop(cua_client, browser, sys_prompt, user_prompt,
                        model=CUA_MODEL, max_iterations=5, verbose=verbose)
                    await asyncio.sleep(3)

            if await _settled_clear():
                # Page just reloaded — re-run platform-specific setup so the
                # caller's subsequent paste/send logic still finds Deep Research
                # pill / Opus Adaptive + Research tool / Pro Extended Thinking
                # active on the fresh page.
                log(f"[{label}] CUA retry cleared verification ✓ — re-running setup")
                emit_event("agent_verified", phase=phase, agent=platform_key)
                _mark_cleared()
                pl = platform.lower()
                try:
                    if pl == "claude":
                        await setup_claude_dr(page)
                    elif pl == "gemini":
                        await setup_gemini_dr(page)
                    elif pl == "chatgpt":
                        await setup_chatgpt_dr(page)
                except Exception as e:
                    log(f"[{label}] Post-clear setup re-run warning: {e}", "WARN")
                return True
            log(f"[{label}] CUA retry still blocked — escalating to tab-kill", "WARN")
        except Exception as e:
            log(f"[{label}] CUA retry errored: {e} — escalating to tab-kill", "WARN")

    # ── Tier 4: Kill the tab, open a fresh one ──
    # NEVER-DIE-MIGRATION-2026-04-18: Last automated tier before
    # surfacing to the user. Close + reopen the page — a fresh cookie
    # context and clean document layout occasionally clears a stubborn
    # bot flag that the cooldown + reload couldn't. Cheap insurance
    # before we interrupt the user.
    # 2026-07-06 HV-trim: SKIPPED for Cloudflare — the attestation is
    # profile+IP-scoped, so a fresh tab can't reset it; the kill-tab's
    # new_tab is just one more cold navigation raising the very score
    # that fired the challenge. Cloudflare goes straight to the user
    # pause (whose 5s poll still auto-resumes on natural decay).
    # ALSO skipped when the caller marked the tab preserve_tab (warm-tab
    # reuse): the replacement page only rebinds the LOCAL `page`, so the
    # caller would be stranded driving a closed handle.
    if _is_cloudflare():
        log(f"[{label}] Cloudflare wall — skipping kill-tab (a fresh tab can't reset a profile-scoped attestation)")
    elif preserve_tab:
        log(f"[{label}] Caller's tab must stay alive (warm-tab reuse) — skipping kill-tab")
    else:
        try:
            original_url = page.url
            log(f"[{label}] CUA exhausted — killing the tab and re-opening for a clean slate")
            try:
                await page.close()
            except Exception:
                pass
            page = await browser.new_tab(original_url)
            await asyncio.sleep(4)
            if await _settled_clear():
                log(f"[{label}] Fresh tab cleared verification ✓ — re-running setup")
                emit_event("agent_verified", phase=phase, agent=platform_key)
                _mark_cleared()
                pl = platform.lower()
                try:
                    if pl == "claude":
                        await setup_claude_dr(page)
                    elif pl == "gemini":
                        await setup_gemini_dr(page)
                    elif pl == "chatgpt":
                        await setup_chatgpt_dr(page)
                except Exception as e:
                    log(f"[{label}] Post-kill-tab setup re-run warning: {e}", "WARN")
                return True
            log(f"[{label}] Fresh tab still blocked — escalating to user", "WARN")
        except Exception as e:
            log(f"[{label}] Kill-tab tier errored: {e} — escalating to user", "WARN")

    # ── User manual fallback — pause pipeline, banner with Resume/Skip ──
    log(f"[{label}] HUMAN VERIFICATION REQUIRED — {reason or 'unknown challenge'} — pausing pipeline", "WARN")
    _controls.hv_blocked[platform_key] = reason or "Human verification challenge"
    _hv_alert_id = f"phase{phase}_human_verify_{platform_key}"
    if "cloudflare" in (reason or "").lower():
        # #896: Cloudflare's checkbox is a browser attestation the automation
        # window can't pass — it re-issues after every click there, so the run
        # leaves it hands-off (Skip-only). 2026-07-09 (user): keep the copy
        # short + to the point; do NOT tell the user to run the login command
        # (it isn't the right fix for a Cloudflare wall).
        _hv_plat = {"claude": "Claude", "gemini": "Gemini", "chatgpt": "ChatGPT"}.get(
            platform_key, platform.capitalize())
        _hv_msg = (
            f"{_hv_plat} hit Cloudflare's 'Verify you are human' check. "
            f"It can't be cleared from here — trying only makes Cloudflare ask harder. "
            f"Skip {_hv_plat} for this run; if it clears on its own, the run resumes automatically."
        )
    else:
        _hv_msg = f"Solve the check ({platform.capitalize()}'s 'are you human' prompt) in the open browser, then Resume — or Skip {platform.capitalize()}."
    # #955 Phase 5: a Cloudflare wall is hands_off (Skip-only, can't be cleared
    # here); every other check is a solvable blocker (Resume + Skip). The intent
    # split mirrors the copy branch above AND the FE's /cloudflare/i test.
    _hv_intent = "hv_wall" if "cloudflare" in (reason or "").lower() else "hv_solvable"
    # Author through the seam. event_name stays "human_verification_required"
    # (FE routing); every legacy kwarg is preserved verbatim via **extra;
    # agent=platform_key stays first-class (the FE keys the per-agent card
    # surface + notification dedup on it). No deadline — the wait loop below is
    # its own firer (_hv_auto_skip_finalize); the hands_off catalog flag is inert
    # at the seam. Capture the decision_id so the still-walled re-emit updates in
    # place under the same id.
    _hv_decision_id = emit_decision(
        intent=_hv_intent, event_name="human_verification_required",
        phase=phase, agent=platform_key,
        facts={"title": _hv_msg, "details": ""},
        actions=_alert_actions_for(_hv_intent, phase, platform_key),
        alert_id=_hv_alert_id,
        platform=platform_key,
        platformLabel=platform.capitalize(),
        reason=reason or "Human verification challenge",
        message=_hv_msg)
    # DGOPS-7710-followup: pause with explicit reason + target agent so the
    # CLI dispatcher's `s` can target THIS platform via request_skip_agent
    # (the poll loop below checks skipped_agents; without target_agent, CLI
    # `s` sets skipped_phases — wrong set — and silently does nothing).
    _controls.pause_target_agent = (platform_key or "").strip().lower()
    _controls.request_pause("human_verification_required")
    emit_event("pipeline_paused", phase=phase, reason="human_verification_required", agent=platform_key)
    # #710 parity: durable mirror so opening this chat re-surfaces the
    # Resume/Skip card even if it wasn't the viewed tab when HV fired.
    # Cleared on the pipeline_resumed/stopped this gate emits when it unblocks.
    _persist_pending_decision({
        "kind": "human_verification_required",
        "phase": phase,
        "agent": platform_key,
        "platformLabel": platform.capitalize(),
        "reason": reason or "Human verification challenge",
        "message": _hv_msg,
        "alert_id": _hv_alert_id,
    })

    # Poll every 5s — if the user solves the challenge without tapping Resume,
    # we still notice and auto-continue. Also yields to stop/skip/resume signals.
    for _ in range(max_wait_loops):
        await asyncio.sleep(5)
        if _controls.is_stop():
            emit_event("pipeline_stopped", phase=phase, reason="stopped during human_verification", agent=platform_key)
            return False
        # User tapped "Skip agent" in the banner → drop this agent cleanly
        if platform_key in _controls.skipped_agents:
            # #906: KEEP the marker in skipped_agents — this function returns
            # a bare bool, so False is ambiguous ("unresolved" vs "user
            # skipped") and the callers previously always followed up with a
            # fail_agent card (the observed SECOND "hit Cloudflare's human
            # check" alert right after the user skipped, which also clobbered
            # the just-persisted "skipped" status with "errored"). Callers
            # now check membership to suppress that card; the round-robin's
            # skip consumer discards the marker when it finalizes the agent.
            log(f"[{label}] User chose Skip agent during human verification — dropping {platform_key}", "INFO")
            emit_event("agent_skipped", phase=phase, agent=platform_key,
                       reason="human_verification_skipped")
            # status="skipped" auto-persisted by emit_event hook.
            emit_event("pipeline_resumed", phase=phase, reason="skip_agent_during_verification", agent=platform_key)
            _controls.request_resume()
            # #906: Skip means skip — close the walled tab NOW (zero further
            # touches; hands-off for Cloudflare) instead of leaving it open
            # for the poll loop to keep probing. Guards inside: never closes
            # the main/last tab or a caller-preserved warm-reuse tab.
            await _close_skipped_agent_tab(browser, page, platform_key, label,
                                           preserve_tab=preserve_tab)
            return False
        if not _controls.is_pause():
            # User tapped Resume — verify the challenge is actually cleared
            # (#896: settled probe — a Cloudflare re-issue gap must not pass)
            if not await _settled_clear():
                log(f"[{label}] Resume tapped but verification still present — re-pausing", "WARN")
                # #955 Phase 5: re-author in place — SAME alert_id + decision_id
                # (update, not a new card). No mirror on the re-emit (the durable
                # mirror keeps the ORIGINAL copy, #710 parity).
                _hv_recheck_msg = "The check isn't cleared yet. Finish it in the open browser, then Resume."
                emit_decision(
                    intent=_hv_intent, event_name="human_verification_required",
                    phase=phase, agent=platform_key,
                    facts={"title": _hv_recheck_msg, "details": ""},
                    actions=_alert_actions_for(_hv_intent, phase, platform_key),
                    alert_id=_hv_alert_id, decision_id=_hv_decision_id,
                    platform=platform_key,
                    platformLabel=platform.capitalize(),
                    reason=reason or "Human verification challenge",
                    message=_hv_recheck_msg)
                # Re-set target_agent (request_resume cleared it on the
                # initial resume) so CLI `s` still targets this platform.
                _controls.pause_target_agent = (platform_key or "").strip().lower()
                _controls.request_pause("human_verification_required")
                continue
            log(f"[{label}] Verification cleared ✓")
            _mark_cleared()
            emit_event("pipeline_resumed", phase=phase, reason="human_verification_cleared", agent=platform_key)
            return True
        # Auto-detect clearance even without explicit resume
        # (#896: settled probe — a Cloudflare re-issue gap must not pass)
        if await _settled_clear():
            log(f"[{label}] Verification auto-cleared ✓")
            _mark_cleared()
            _controls.request_resume()
            emit_event("pipeline_resumed", phase=phase, reason="human_verification_cleared", agent=platform_key)
            return True

    # Unacted for the whole grace window. With auto-skip ON, finalize a CLEAN
    # grey-skip here (agent_skipped + close tab + honest reason) instead of
    # returning False into the caller's red fail_agent card — the caller's
    # `platform in skipped_agents` branch then suppresses that card. The pause
    # already gave the grace period for an out-of-band solve (which auto-resumes
    # anytime it lands). When auto-skip is OFF, fall through to the manual card.
    if _runtime.auto_skip_stuck:
        await _hv_auto_skip_finalize(browser, page, platform_key, label, phase,
                                     preserve_tab=preserve_tab, release_pause=True)
        return False
    log(f"[{label}] Human verification timed out ({max_wait_loops * 5}s) — skipping agent", "WARN")
    # INV #3 / #954 leak class (2026-07-16): auto-skip OFF must STILL release the
    # HV pause before handing back to the caller's manual card. request_pause set
    # pause_event on entry; returning False without clearing it leaves pause_event
    # SET, so the caller's next wait_if_paused() would block the WHOLE run
    # indefinitely (reason=human_verification_required, no resume path). The ON
    # branch releases via _hv_auto_skip_finalize(release_pause=True); this OFF
    # branch had no equivalent. The agent-scoped pipeline_resumed also fires the
    # universal clear seam for THIS agent — retracting its HV mirror + auto-
    # clearing the FE card — so #710's ghost-card concern is handled exactly the
    # way any resolved gate is (superseding the manual retract below).
    if _controls.is_pause():
        _controls.request_resume()
        emit_event("pipeline_resumed", phase=phase, reason="hv_timeout_handoff",
                   agent=platform_key)
    # #710 belt-and-suspenders: retract the durable mirror explicitly too (the
    # login skip_init_verify break does the same) — harmless if the resume seam
    # already cleared it.
    _clear_pending_decision()
    return False


async def check_hv_gate(browser, cua_client, platform: str, label: str,
                         phase: int, verbose: bool = False) -> bool:
    """Early HV (human-verification) gate detection + clearance.

    Call this right after `browser.navigate(url)` in any phase handler. If
    the landing page is behind a Cloudflare / CAPTCHA / "verify you are
    human" gate, we resolve it BEFORE spending CUA budget on the phase's
    actual work (selector clicks, prompt submission, etc.) — those would
    fail anyway on a blocked page and burn rate-limit / workspace quota.

    Returns True if the gate is clear (either was never there, or we
    cleared it via CUA / user pause-resume). Returns False if the gate
    couldn't be cleared — caller should abort the phase cleanly.

    Historically only Phase 2 used this; ports to P1/P3/P4/P5 mirror
    `start_agent_no_gemini_wait` but scope events to the caller's phase."""
    try:
        blocked, reason = await detect_human_verification(browser.page, platform, label)
    except Exception as e:
        log(f"[{label}] HV detection errored ({e}) — assuming clear", "WARN")
        return True
    if not blocked:
        return True
    log(f"[{label}] Phase {phase}: HV gate detected ({reason or 'unknown'}) — clearing before phase work", "WARN")
    # #705 item 6: Tier-1 silent retry around the clearance machinery. The
    # clearance chain (Playwright → CUA → cooldown → kill-tab → user pause)
    # already owns the Tier-2 user escalation as its FINAL tier and returns
    # True/False normally. An EXCEPTION out of it (CUA blip, navigation
    # timeout, page-context teardown) is transient infra noise — hard-failing
    # the phase on it makes a self-recoverable hiccup look like a structural
    # block. So on a raise: re-probe the gate (it often self-cleared while the
    # machinery faulted) and, if still blocked, re-run the chain ONCE more
    # before giving up. A genuine still-present gate just re-enters the chain
    # and reaches the user pause as designed; we never swallow a real block.
    #
    # Cost note: the retry re-runs only on a RAISE (not the normal True/False
    # return — the chain try/excepts each internal tier), which is a rare infra
    # fault. Capped at one extra attempt, so worst case is two passes through
    # the chain's 180s cooldown (~6 min) — acceptable for a rare exception
    # recovery, and far better than hard-aborting the phase on transient noise.
    #
    # 2026-07-06 HV-trim: the silent retry is for NON-Cloudflare walls only.
    # For a confirmed Cloudflare wall a second cascade pass is more cold
    # navigations against a profile+IP-scoped attestation — it raises the very
    # bot-score that fired the challenge and snowballs into the next run
    # ("continuous HV after one run"). One pass already ends at the user pause
    # (whose 5s poll auto-resumes on natural score decay), so nothing is lost.
    for _hv_attempt in range(2):
        try:
            return await wait_for_verification_clearance(
                browser, cua_client, browser.page,
                platform=platform, label=label,
                verbose=verbose, phase=phase,
                # #896: seed the confirmed reason — the chain's own top probe
                # can land in a detection gap (post-click re-issue window on
                # the retry pass) and must not run "unknown" as "no Cloudflare".
                initial_reason=reason,
            )
        except Exception as e:
            log(f"[{label}] wait_for_verification_clearance errored "
                f"(attempt {_hv_attempt + 1}/2): {e}", "WARN")
            _fresh_reason = ""
            try:
                still_blocked, _fresh_reason = await detect_human_verification(browser.page, platform, label)
            except Exception:
                still_blocked = True
            if not still_blocked:
                log(f"[{label}] HV gate clear after a transient clearance error — proceeding silently", "INFO")
                return True
            # Review 2026-07-06: honor the FRESH re-probe verdict, not just the
            # entry one — the entry probe can land in the #896 detection gap and
            # read a Cloudflare wall as unknown; the re-probe often positively
            # identifies it. Losing that verdict would re-run the full cascade
            # against the attestation (the exact snowball this branch prevents).
            if "cloudflare" in ((_fresh_reason or reason) or "").lower():
                log(f"[{label}] Cloudflare wall — not re-running the clearance chain "
                    "(more navigations raise the score); aborting phase", "WARN")
                return False
            if _hv_attempt == 0:
                await asyncio.sleep(3)  # brief backoff before the single silent retry
    log(f"[{label}] HV clearance failed after silent retry — aborting phase", "WARN")
    return False


async def _try_inpage_retry_on_research_fail(page, platform, label, max_wait_s=20):
    """Detect the agent's own in-page Retry button after Send and click it once.

    When Deep Research kicks off but immediately fails (rate limit, internal
    error, brief-parse failure), the agent UI shows a 'Research stopped' /
    'Research failed' / 'Something went wrong' message with a Retry (or
    Regenerate / Try again) button right below it in the assistant area.
    This guard auto-clicks that button ONCE so the round-robin watchdog
    doesn't have to escalate to a human-intervention alert for what is
    effectively a transient agent-side glitch.

    Scope:
      - Only fires when the page actually shows failure-message text — no
        click happens on a healthy research start.
      - Buttons must live inside an assistant message area (not composer /
        toolbar / footer), with aria-label or text matching retry words.
      - Single click per call; idempotent.

    Returns True if a button was clicked, False otherwise. Wayland-safe
    (pure DOM click, no clipboard reads)."""
    platform_l = (platform or "").lower()
    deadline = asyncio.get_event_loop().time() + max_wait_s
    poll_n = 0
    # Failure-message regex — covers ChatGPT / Claude / Gemini wording
    # variants seen across recent runs. Word-boundary-loose because some
    # UIs render the text with extra punctuation.
    fail_re = (
        r"research\\s+stopped|research\\s+failed|"
        r"failed\\s+to\\s+(?:generate|complete|run|continue)|"
        r"something\\s+went\\s+wrong|encountered\\s+an?\\s+(?:issue|error)|"
        r"unable\\s+to\\s+(?:continue|complete|generate)|"
        r"couldn'?t\\s+complete|response\\s+stopped|"
        r"this\\s+research\\s+(?:was\\s+)?(?:stopped|interrupted)|"
        r"sorry,?\\s+(?:i'?m\\s+|i\\s+)?can'?t\\s+help|"
        r"i\\s+can'?t\\s+help\\s+(?:you\\s+)?with\\s+that|"
        r"can'?t\\s+help\\s+(?:you\\s+)?with\\s+that\\s+at\\s+this\\s+time|"
        r"i'?m\\s+(?:unable|not\\s+able)\\s+to\\s+help"
    )
    while asyncio.get_event_loop().time() < deadline:
        poll_n += 1
        try:
            clicked = await page.evaluate(
                f"""() => {{
                    const failPattern = new RegExp(`{fail_re}`, 'i');
                    // 2026-05-14: dropped 'resume' — too generic, could match
                    // Claude's resume-conversation button (unrelated to
                    // research-fail recovery).
                    const retryWords = /(?:^|\\s)(retry|regenerate|try\\s+again|rerun|restart)\\b/i;
                    const isInComposerOrToolbar = (el) => !!el.closest(
                        '[data-testid*="composer"], [data-testid*="prompt-textarea"], ' +
                        '[contenteditable="true"], form[data-message-id], ' +
                        '[role="toolbar"], footer, [class*="composer" i], ' +
                        '[class*="input-area" i], [class*="message-input" i]'
                    );
                    const isAssistantScoped = (el) => !!el.closest(
                        '[data-message-author-role="assistant"], .font-claude-message, ' +
                        '[data-testid*="conversation-turn"], ' +
                        // Gemini custom-element + class selectors for the model
                        // response bubble. Without these the refusal-text
                        // assistant-scope check returned false and the function
                        // skipped the regenerate-button click that the soft-
                        // refusal regex had just matched.
                        'message-content, model-response, ' +
                        '.model-response-text, .response-container'
                    );
                    const isVisible = (el) => {{
                        const r = el.getBoundingClientRect();
                        if (r.width < 16 || r.height < 16) return false;
                        const cs = getComputedStyle(el);
                        if (cs.display === 'none' || cs.visibility === 'hidden') return false;
                        if (parseFloat(cs.opacity) < 0.1) return false;
                        return true;
                    }};
                    // First confirm the failure-text actually shows on the page.
                    // No fail-text → not the failure case this guard is for.
                    const bodyText = document.body ? (document.body.innerText || '') : '';
                    if (!failPattern.test(bodyText)) return '';
                    const btns = Array.from(document.querySelectorAll('button, [role="button"]'));
                    for (const b of btns) {{
                        if (isInComposerOrToolbar(b)) continue;
                        if (!isVisible(b)) continue;
                        const aria = (b.getAttribute('aria-label') || '').toLowerCase();
                        const title = (b.getAttribute('title') || '').toLowerCase();
                        const txt = (b.textContent || '').trim().toLowerCase();
                        if (!(retryWords.test(aria) || retryWords.test(title) || retryWords.test(txt))) continue;
                        // Require either assistant-scope OR a fail-text token
                        // inside the nearest block. Without one of those a
                        // composer regenerate icon outside the toolbar can
                        // sneak through.
                        if (!isAssistantScoped(b)) {{
                            const parent = b.closest('div, section, article, li, [role="dialog"]');
                            if (!parent || !failPattern.test(parent.innerText || '')) continue;
                        }}
                        b.click();
                        return aria || title || txt || 'matched';
                    }}
                    return '';
                }}"""
            )
            if clicked:
                log(f"[{label}] In-page Retry auto-clicked: '{clicked}' (poll {poll_n})", "INFO")
                try:
                    emit_event("inpage_retry_clicked", phase=2, agent=platform_l,
                               match=str(clicked)[:60])
                except Exception:
                    pass
                return True
        except Exception as _pe:
            log(f"[{label}] In-page retry probe raised: {_pe}", "DEBUG")
        await asyncio.sleep(1.5)
    return False


async def _chatgpt_force_new_chat(page, label) -> bool:
    """Client-side "New chat" on an already-open chatgpt.com tab (2A warm-tab
    reuse, 2026-07-06 bot-score work). Returns True when the tab lands on a
    fresh composer WITHOUT a top-level navigation — that's the whole point:
    the cold chatgpt.com page-load is the Cloudflare-scored event, while the
    SPA's New-chat click is history-API routing the edge never sees. Mirrors
    the Gemini Layer-0.6 fresh-chat guard.
    False = caller should fall back to a same-tab goto (still cheaper than a
    second tab: one nav instead of one nav + a lingering duplicate surface).

    Review 2026-07-06: URL heuristics alone aren't proof of a composer — a
    signed-in tab parked on /gpts, /codex, or a read-only /share/<id> page has
    a chatgpt.com URL but no composer, and "success" there would send
    setup_chatgpt_dr into its full CUA fallback. So every True is gated on a
    COMPOSER-PRESENT DOM probe; anything less falls back to the goto."""
    async def _composer_present() -> bool:
        """A composer AND an empty thread.

        ⭐ 2026-08-05 — the composer selector alone is true on EVERY signed-in
        ChatGPT surface that has one, INCLUDING a conversation page with forty
        turns already mounted. On the no-click branch below, the only thing
        separating "fresh composer" from "someone else's thread" was the `/c/`
        substring in the URL — a fair test at that instant and the entire proof.
        Emptiness is the direct question, and the primitive is already proven in
        this module (direct_submit uses the same author-role count as its own
        did-it-land probe).
        """
        try:
            st = await page.evaluate(
                "() => ({ composer: !!document.querySelector("
                "'#prompt-textarea, form [contenteditable=\"true\"], "
                "[data-testid*=\"composer\"] textarea, form textarea'),"
                " msgs: document.querySelectorAll('[data-message-author-role]').length })")
        except Exception:
            return False
        st = st or {}
        if not st.get("composer"):
            log(f"[{label}] New-chat check: no composer on this surface", "INFO")
            return False
        if int(st.get("msgs") or 0) > 0:
            log(f"[{label}] New-chat check: composer present but the thread already "
                f"holds {st.get('msgs')} message(s) — NOT a fresh chat", "WARN")
            return False
        return True

    try:
        cur = (page.url or "").lower()
        if "chatgpt.com" not in cur and "chat.openai.com" not in cur:
            return False
        log(f"[{label}] New-chat check: url={cur}", "INFO")
        if "/c/" not in cur:
            # No conversation mounted — but only a real composer counts
            # (rules out /gpts, /codex, /share/<id>, auth interstitials).
            return await _composer_present()
        # ⭐ 2026-08-05 — MARK, THEN PRESS. This used to call a synthetic
        # `el.click()` inside page.evaluate, the pattern this module has already
        # proved dead on ChatGPT's React surfaces: it dispatches a click event and
        # nothing else, while the trigger listens on pointerdown. The 2026-08-04
        # DOM wave migrated the model menu and the effort submenu and never
        # reached this function.
        #
        # ⚠ And the last-resort loop matched `textContent === 'new chat'` across
        # EVERY button/anchor in the document — while ChatGPT titles an untitled
        # conversation "New chat" in the left sidebar, where each row is an
        # `<a href="/c/<id>">`. A synthetic click on an anchor DOES run its
        # activation behaviour, so that branch could navigate the tab straight
        # INTO an arbitrary old conversation. It was only ever caught by the `/c/`
        # re-check below, silently, which is luck rather than a guard. The
        # fallback now excludes conversation links outright.
        marked = await page.evaluate(
            """(MARK) => {
            document.querySelectorAll('[' + MARK + ']').forEach(
                e => e.removeAttribute(MARK));
            const sels = [
                '[data-testid="create-new-chat-button"]',
                'a[data-testid="create-new-chat-button"]',
                'button[aria-label*="New chat" i]',
                'a[aria-label*="New chat" i]',
            ];
            for (const s of sels) {
                const el = document.querySelector(s);
                if (el && el.offsetParent !== null) {
                    el.setAttribute(MARK, 'newchat'); return s;
                }
            }
            for (const el of document.querySelectorAll('button, a, [role="button"]')) {
                const t = (el.textContent || '').trim().toLowerCase();
                if (t !== 'new chat' || !el.offsetParent) continue;
                // A sidebar row for an UNTITLED conversation reads exactly
                // "New chat" too — and clicking it opens that conversation.
                const href = (el.getAttribute && el.getAttribute('href')) || '';
                if (href.startsWith('/c/') || el.closest('a[href^="/c/"]')) continue;
                el.setAttribute(MARK, 'newchat'); return 'text:new chat';
            }
            return '';
        }""", _SR_CLICK_MARK)
        if not marked:
            log(f"[{label}] New-chat control not found on this page", "WARN")
            return False
        how = await _sr_real_click(page, "newchat", tag=f"[{label}][chatgpt-newchat]")
        if not how:
            return False
        log(f"[{label}] New-chat pressed via {how} (matched {marked})", "INFO")
        await asyncio.sleep(2)
        cur2 = (page.url or "").lower()
        log(f"[{label}] New-chat check: url after press={cur2}", "INFO")
        if "/c/" in cur2:
            return False  # SPA never left the conversation
        return await _composer_present()
    except Exception as e:
        log(f"[{label}] New-chat click errored: {e}", "WARN")
        return False


def _gemini_owns_candidate(candidate_text: str, pasted_head: str) -> bool:
    """True iff a sidebar-entry title (or conversation-body snippet) plausibly
    belongs to the brief we just pasted. Gemini auto-titles a new chat from the
    prompt, so the candidate's significant tokens (len>=4, first 12) must
    largely (>=60%) appear — WORD-BOUNDARY matched, not substring — in the
    head of the pasted text. Fail-closed: empty, too-short, or <3-significant-
    token candidates never match (adversarial review: a 1-2 generic-token
    title like 'Market research' must not pass on template words alone) —
    adopting a WRONG conversation is the "stuck in past run" failure LAYER 0.6
    exists to prevent, so we only adopt on positive evidence. Pure function
    (regression-tested)."""
    cand = re.sub(r"\s+", " ", (candidate_text or "")).strip().lower()
    head = re.sub(r"\s+", " ", (pasted_head or "")).strip().lower()
    if len(cand) < 8 or not head:
        return False
    toks = re.findall(r"[a-z0-9]{4,}", cand)[:12]
    if len(toks) < 3:
        return False
    hits = sum(1 for t in toks if re.search(rf"\b{re.escape(t)}\b", head))
    return hits / len(toks) >= 0.6


async def _gemini_adopt_lost_conversation(page, pasted_text: str, label: str):
    """Last-resort recovery when a Gemini send never surfaced on OUR tab (URL
    pinned at bare /app through every re-submit) — live incident 2026-07-11
    ~02:50 (worker 2): the brief eventually registered platform-side (the user
    later found the conversation waiting at 'Start research'), but 2C had
    already failed the agent because our page kept showing the empty new-chat
    home. Two probes, cheapest first:

      1. TAB CENSUS — a sibling tab in this context already at /app/<id>.
         gemini.google.com is popup-allow-listed (spawned tabs are adopted
         into _known_pages, never closed) but nothing rebinds our handle.
      2. SIDEBAR — expand the left rail's Recent list (expansion ladder
         inherited from the retired #897a recovery) and read the MOST RECENT
         entry.

    Ownership gate for BOTH probes (_gemini_owns_candidate + brief-chunk body
    check): adopt ONLY what provably is THIS run's brief. Logs a full Gemini
    tab census either way so backend.log alone can adjudicate tab-orphan vs
    dropped-send next time. Returns (page, adopted). Never raises."""
    pasted_head = (pasted_text or "")[:600]
    # Build the identity chunk from PAST any shared template header (every
    # brief opens with the same "# Research Brief…" boilerplate — a chunk of
    # it would match every past run; adversarial-review finding).
    _chunk_src = pasted_head
    if _chunk_src.lstrip().lower().startswith("# research brief"):
        _chunk_src = _chunk_src.split("\n", 1)[1] if "\n" in _chunk_src else ""
    _chunk = re.sub(r"\s+", " ", _chunk_src).strip().lower()[:60]

    async def _conversation_matches(p) -> bool:
        # The opened conversation must CONTAIN our brief: read the first
        # user-query bubble (fallback: body text) and match it.
        try:
            body = await p.evaluate(
                "() => { const q = document.querySelector('user-query');"
                " return ((q && q.innerText) || document.body.innerText || '')"
                ".slice(0, 4000); }")
        except Exception:
            return False
        b = re.sub(r"\s+", " ", body or "").strip().lower()
        if _chunk and _chunk in b:
            return True
        return _gemini_owns_candidate(b[:300], pasted_head)

    async def _adoptable_state(p) -> str:
        """Pre-Start states only. A conversation already holding a COMPLETED
        research report is a PREVIOUS run of the same/similar brief (identical
        content passes the ownership gate deterministically on a re-run) —
        adopting it would deliver stale research and strand [2D] hunting a
        'Start research' button that will never appear (adversarial-review
        finding). 'start_waiting' (the incident state) and 'pre_start' (plan
        still generating) are what [2D] is built to drive."""
        try:
            return await p.evaluate(
                """() => {
                  const vis = (el) => !!el && el.offsetParent !== null;
                  for (const b of document.querySelectorAll('button')) {
                    const t = (b.textContent || '').trim().toLowerCase();
                    if (t.includes('start research') && vis(b)) return 'start_waiting';
                  }
                  if (document.querySelector('immersive-panel, [data-test-id*="report"]'))
                    return 'report_present';
                  return 'pre_start';
                }""")
        except Exception:
            return "probe_error"

    # ── Probe 1: sibling-tab census ──
    try:
        _tabs = list(page.context.pages)
    except Exception:
        _tabs = []
    _census = []
    for _t in _tabs:
        try:
            _census.append((_t.url or "?").split("?", 1)[0])
        except Exception:
            _census.append("<err>")
    log(f"[{label}] Gemini tab census: {len(_census)} tab(s): "
        + " | ".join(_census[:8]), "WARN")
    for _t in _tabs:
        if _t is page:
            continue
        try:
            _u = (_t.url or "").split("?", 1)[0].rstrip("/")
        except Exception:
            continue
        if "gemini.google.com" not in _u or "/app/" not in _u:
            continue
        if await _conversation_matches(_t):
            _st = await _adoptable_state(_t)
            if _st == "report_present":
                log(f"[{label}] sibling Gemini tab {_u} matches our brief but "
                    "already holds a COMPLETED report (previous run of the same "
                    "brief) — not adopting", "WARN")
                continue
            log(f"[{label}] ADOPTED sibling Gemini tab at {_u} (state={_st}) — "
                "the send landed in a tab we weren't watching", "WARN")
            try:
                await _t.bring_to_front()
            except Exception:
                pass
            return _t, True
        log(f"[{label}] sibling Gemini tab {_u} does NOT match our brief — "
            "leaving it alone", "INFO")

    # ── Probe 2: most-recent sidebar conversation on OUR page ──
    # 2026-07-13 (user-directed): the send DID register (the conversation is in
    # history), Gemini's SPA just never routed OUR tab into it. Two hard facts
    # from the operator:
    #   • Gemini does NOT restore a conversation from a direct URL — page.goto
    #     /app/<id> lands on the empty home (same reason the periodic reload was
    #     retired). The ONLY reliable adoption is to CLICK the sidebar entry.
    #   • When the send is "lost" our tab is parked on the bare /app home whose
    #     Recent list is STALE (missing the just-created conversation). So we
    #     REFRESH ONCE here — the SOLE place we ever reload, and only because
    #     we're on the empty home — to freshen the Recent list, then open it and
    #     click the most-recent OWNED entry (checking the top one or two). We
    #     never reload once in a conversation, and never after opening one.
    # 2026-07-16 — GROUND-TRUTH selectors captured from the live Gemini rail
    # (console DOM dump). A Recent chat = an anchor
    #   `a[href^="/app/<id>"]` with aria-label=title, wrapped in
    #   `gem-nav-list-item[data-test-id="conversation"]` inside
    #   `conversations-list[data-test-id="all-conversations"]`.
    # Read the anchor's aria-label (the CLEAN title) — innerText on the wrapper
    # concatenates trailing hover-affordance text; aria-label is exactly the
    # title. Dedup so repeated wrappers/anchors don't double-count.
    _SIDEBAR_LIST_JS = """
    (n) => {
      const out = [], seen = new Set();
      const els = document.querySelectorAll('a[href*="/app/"]');
      for (const el of els) {
        const t = ((el.getAttribute('aria-label') || el.innerText
                    || el.textContent) || '').replace(/\\s+/g, ' ').trim();
        if (t && t.length <= 120 && !seen.has(t)) {
          seen.add(t); out.push(t.slice(0, 200)); if (out.length >= n) break;
        }
      }
      return out;
    }
    """
    # The rail has TWO gates: OPEN the side nav (aria "Open sidebar" /
    # data-test-id "side-nav-sparkle-button"), then EXPAND the collapsible
    # "Recent" section (aria "Toggle Recent" / data-test-id
    # "expandable-section-toggle"). The old ladder only clicked ONE generic
    # button and never expanded Recent, so the conversation anchors stayed out
    # of the DOM (live 2026-07-16 stuck run: "no recent conversation entry").
    # Guarded so we never COLLAPSE an already-open section.
    _EXPAND_SIDEBAR_JS = """
    () => {
      let acted = false;
      const q = (s) => document.querySelector(s);
      // Robust visibility — offsetParent is blind to visibility:hidden /
      // opacity:0 / position:fixed, and Gemini toggles the open/close buttons
      // via VISIBILITY (both co-exist in the DOM). Check computed display /
      // visibility / opacity (catches ancestor hiding too — both inherit or
      // zero the box) plus a real rendered box.
      const vis = (el) => {
        if (!el) return false;
        const s = getComputedStyle(el);
        if (s.display === 'none' || s.visibility === 'hidden' || +s.opacity === 0) return false;
        const r = el.getBoundingClientRect();
        return r.width > 1 && r.height > 1;
      };
      // 1) Open the rail ONLY when it's actually collapsed. The stable
      //    data-test-id matches in BOTH states (the open + close buttons can
      //    co-exist in the DOM), so a blind click would TOGGLE an already-open
      //    rail SHUT and hide the very anchors we need (adversarial-review
      //    finding). Gate on VISIBILITY: open only when the opener is visible
      //    and there's no visible "Close sidebar".
      const opener = q('[data-test-id="side-nav-sparkle-button"],'
                       + ' button[aria-label="Open sidebar" i]');
      const closer = q('button[aria-label="Close sidebar" i]');
      if (opener && vis(opener) && !vis(closer)) { opener.click(); acted = true; }
      // 2) Expand "Recent" only when collapsed — authoritative aria-expanded
      //    when present, else a no-anchors proxy SCOPED to conversations-list
      //    (an unscoped a[href*="/app/"] would let a stray /app/ link elsewhere
      //    on the page suppress the expand — adversarial-review finding).
      //
      //    IDENTIFY THE SECTION, DON'T TAKE THE FIRST TOGGLE. `data-test-id=
      //    "expandable-section-toggle"` is NOT unique — the rail renders
      //    Notebooks above Recent and both carry it. querySelector with a
      //    selector LIST returns the first match in DOCUMENT ORDER (it does not
      //    prefer the earlier selector), so the old single-q() grabbed
      //    NOTEBOOKS every time: it read Notebooks' aria-expanded, clicked
      //    Notebooks, and left Recent collapsed with its conversation anchors
      //    out of the DOM — the sidebar read empty through the whole refresh
      //    budget and dropped-send recovery re-submitted into a blank home
      //    instead of adopting. Proven by the rail-diag captured at failure
      //    (2026-07-20 + 2026-07-27): testid "expandable-section-toggle" with
      //    aria-label "Toggle Notebooks", and the one expanded
      //    "expandable-section-content" holding "New notebook". Match the
      //    toggle by its OWN label/text, and never accept the Notebooks one.
      const recentish = (el) => {
        const s = ((el.getAttribute('aria-label') || '') + ' '
                   + (el.textContent || '')).toLowerCase();
        return /recent/.test(s) && !/notebook/.test(s);
      };
      let rec = null;
      for (const t of document.querySelectorAll(
              '[data-test-id="expandable-section-toggle"],'
              + ' button[aria-label*="Recent" i]')) {
        if (recentish(t)) { rec = t; break; }
      }
      // Last resort for LABEL DRIFT (a toggle with no aria-label/text): identify the
      // SECTION instead. Key on its data-test-id — live capture 2026-07-28 shows
      // `notebooks-expandable-section` and `chats-expandable-section` — and only fall
      // back to text that STARTS with "Recent" (the header renders before the rows).
      // Deliberately NOT a /notebook/ test against the section's whole textContent:
      // that text includes the chat TITLES ("RecentOne UI Bug Research Research…"),
      // so a conversation merely titled "Notebook…" would have made us reject the
      // real Recent section and give up.
      if (!rec) {
        for (const sec of document.querySelectorAll('expandable-section')) {
          const sid = (sec.getAttribute('data-test-id') || '').toLowerCase();
          if (sid.includes('notebook')) continue;
          const stext = (sec.textContent || '').replace(/\\s+/g, ' ').trim().toLowerCase();
          if (!(sid.includes('chat') || sid.includes('recent')
                || stext.startsWith('recent'))) continue;
          const t = sec.querySelector('[data-test-id="expandable-section-toggle"], button');
          if (t) { rec = t; break; }
        }
      }
      if (rec) {
        const exp = rec.getAttribute('aria-expanded');
        const hasConvos = !!q('conversations-list a[href*="/app/"]');
        if (exp === 'false' || (exp == null && !hasConvos)) { rec.click(); acted = true; }
      }
      return acted;
    }
    """
    _CLICK_ENTRY_BY_TITLE_JS = """
    (title) => {
      // The anchor IS the routed element — click it directly so the SPA routes
      // to /app/<id> (a wrapper-div click was what "never landed"). Match on the
      // aria-label (the clean title) first, innerText as fallback.
      for (const a of document.querySelectorAll('a[href*="/app/"]')) {
        const t = ((a.getAttribute('aria-label') || a.innerText
                    || a.textContent) || '').replace(/\\s+/g, ' ').trim().slice(0, 200);
        if (t === title) { a.click(); return true; }
      }
      return false;
    }
    """
    # Diagnostic dump — when the Recent read comes back empty after the whole
    # refresh budget, this reveals the ACTUAL left-rail markup (tag/role/aria/
    # test-id/href + short text) so a stuck run tells us the real selector to
    # match, WITHOUT a live bot-score-raising probe. (2026-07-16.)
    _SIDEBAR_DIAG_JS = """
    () => {
      const seen = [];
      const els = document.querySelectorAll(
        'nav a, nav [role="button"], [data-test-id], a[href*="/app/"],'
        + ' conversations-list *, side-nav *, [class*="conversation" i]');
      for (const el of els) {
        const t = ((el.innerText || el.textContent) || '').trim().slice(0, 40);
        if (!t || t.length > 60) continue;
        seen.push({ tag: el.tagName.toLowerCase(),
          role: el.getAttribute('role') || '',
          testid: el.getAttribute('data-test-id') || '',
          aria: (el.getAttribute('aria-label') || '').slice(0, 30),
          href: (el.getAttribute('href') || '').slice(0, 40), text: t });
        if (seen.length >= 20) break;
      }
      return JSON.stringify(seen);
    }
    """
    # 2026-07-16 (user-directed, live incident): a SINGLE refresh + 3 quick reads
    # gave Recent too little time — the just-created conversation can take a few
    # reloads to propagate into Recent AND the rail hydrates lazily, so the probe
    # read empty and the recovery wrongly fell through to the re-paste ladder
    # (which spawned a DUPLICATE conversation, the exact thing adopt-first
    # exists to prevent). REFRESH the empty home UNTIL Recent actually shows
    # entries (bounded). Refresh is safe ONLY on the empty home (never a
    # conversation) — re-checked each pass. Still empty after the budget → dump
    # the rail DOM (markup-drift is the other possible cause we can't see here).
    _titles = []
    _refresh_budget = int(os.environ.get("DG_GEMINI_ADOPT_REFRESHES", "5"))
    for _cyc in range(_refresh_budget):
        # (a) expand the rail (mounts late) + read the top entries.
        for _ in range(2):
            try:
                await page.evaluate(_EXPAND_SIDEBAR_JS)
            except Exception:
                pass
            await asyncio.sleep(1.2)
            try:
                _titles = await page.evaluate(_SIDEBAR_LIST_JS, 3)
            except Exception as _se:
                log(f"[{label}] sidebar probe raised (non-fatal): {_se}", "DEBUG")
                _titles = []
            if _titles:
                break
        if _titles:
            log(f"[{label}] Recent list surfaced {len(_titles)} entr(ies) "
                f"after {_cyc} refresh(es)", "INFO")
            break
        # (b) still empty — refresh the empty home to freshen Recent, then retry.
        try:
            _cur = (page.url or "").split("?", 1)[0].rstrip("/").lower()
        except Exception:
            _cur = ""
        if not (_cur.endswith("gemini.google.com/app")
                or _cur.endswith("gemini.google.com")):
            break  # safety: only ever refresh the empty home, never a conversation
        if _cyc < _refresh_budget - 1:
            log(f"[{label}] Recent list empty — refresh {_cyc + 1}/{_refresh_budget} "
                "to freshen it", "WARN")
            try:
                await page.reload(wait_until="domcontentloaded", timeout=25000)
                await asyncio.sleep(2.5)  # let the SPA hydrate the sidebar
            except Exception as _re:
                log(f"[{label}] empty-home refresh failed ({_re})", "WARN")
    if not _titles:
        try:
            _diag = await page.evaluate(_SIDEBAR_DIAG_JS)
        except Exception:
            _diag = "<diag failed>"
        # Report the RELOAD count, not the probe count. The loop probes
        # `_refresh_budget` times but reloads one fewer (the last pass has nothing
        # left to freshen), so the old wording claimed 5 refreshes where the log
        # above shows 4 — a one-off discrepancy that cost real time to reconcile
        # when reading these incidents back.
        log(f"[{label}] sidebar probe: no recent conversation entry after "
            f"{max(_refresh_budget - 1, 0)} refresh(es) / {_refresh_budget} probe(s)"
            f" — rail-diag: {str(_diag)[:900]}", "WARN")
        return page, False
    # Check the top one or two OWNED entries — a concurrent worker's similar-
    # titled chat can land ABOVE ours and pass the title-level ownership gate,
    # so committing to the FIRST title-match and giving up on a body mismatch
    # would abandon OUR conversation sitting at slot #2 (#951 re-review). Try
    # each owned candidate: click → route → BODY-verify; adopt the first whose
    # body actually holds our brief. Never adopt an entry we can't prove is ours.
    _owned = [_t for _t in _titles if _gemini_owns_candidate(_t, pasted_head)]
    if not _owned:
        log(f"[{label}] top recent sidebar chats {[t[:40] for t in _titles]} do NOT "
            "match our brief — not adopting (won't hijack a past run)", "WARN")
        return page, False
    for _ci, _cand_title in enumerate(_owned):
        log(f"[{label}] opening owned sidebar chat '{_cand_title[:60]}' "
            f"({_ci + 1}/{len(_owned)}) from the sidebar", "WARN")
        # 2026-07-19 e2e: ONE click + one 15s route-wait abandoned adoption of
        # the CORRECT sole candidate — the wedged SPA (the same platform state
        # that dropped our send and left us on the bare /app home) silently ate
        # the sidebar click, and the recovery fell through to the re-paste
        # ladder = the duplicate-run adopt-first exists to prevent. Give each
        # candidate a bounded number of click attempts; between failed attempts
        # reload the EMPTY HOME (the only place reload is safe — same policy as
        # the Recent-list refresh above) to unwedge the SPA, re-expand the rail,
        # and re-click.
        _click_tries = int(os.environ.get("DG_GEMINI_ADOPT_CLICK_TRIES", "3"))
        _routed = False
        _u = ""
        _entry_gone = False
        for _at in range(_click_tries):
            # Capture the pre-click URL so a conv→conv click (when a prior
            # candidate left us in a conversation) is detected by CHANGE, not
            # just "/app/". Re-captured per attempt — a reload can normalize it.
            try:
                _before_u = (page.url or "").split("?", 1)[0].rstrip("/")
            except Exception:
                _before_u = ""
            try:
                if not await page.evaluate(_CLICK_ENTRY_BY_TITLE_JS, _cand_title):
                    log(f"[{label}] sidebar entry '{_cand_title[:40]}' vanished before open — trying next", "WARN")
                    _entry_gone = True
                    break
            except Exception:
                _entry_gone = True
                break
            for _ in range(10):  # wait for the SPA to route to a NEW /app/<id> (a CLICK, not a URL nav)
                await asyncio.sleep(1.5)
                try:
                    _u = (page.url or "").split("?", 1)[0].rstrip("/")
                except Exception:
                    _u = ""
                if "/app/" in _u and _u != _before_u:
                    break
            if "/app/" in _u and _u != _before_u:
                _routed = True
                break
            if _at >= _click_tries - 1:
                break
            # Click didn't route within the wait — but re-read the URL before
            # gating the reload: the SPA can route in the sub-second gap AFTER
            # the inner wait's last read (adversarial-review catch). If we are
            # NOW in a new conversation, count it as routed — the body-verify
            # below decides adoption — rather than abandoning an already-open,
            # possibly-correct chat to the next candidate / re-paste ladder.
            try:
                _cur = (page.url or "").split("?", 1)[0].rstrip("/").lower()
            except Exception:
                _cur = ""
            if "/app/" in _cur and _cur != _before_u.lower():
                _u = _cur
                _routed = True
                break
            # Only reload if we're still on the bare empty home (never a
            # conversation), then re-surface the rail entry.
            if not (_cur.endswith("gemini.google.com/app")
                    or _cur.endswith("gemini.google.com")):
                break
            log(f"[{label}] sidebar click didn't route (attempt {_at + 1}/"
                f"{_click_tries}) — reloading the empty home to unwedge the SPA, "
                "then re-clicking", "WARN")
            try:
                await page.reload(wait_until="domcontentloaded", timeout=25000)
                await asyncio.sleep(2.5)  # let the SPA hydrate the sidebar
            except Exception as _rre:
                log(f"[{label}] unwedge reload failed ({_rre})", "WARN")
            for _ in range(2):
                try:
                    await page.evaluate(_EXPAND_SIDEBAR_JS)
                except Exception:
                    pass
                await asyncio.sleep(1.2)
        if _entry_gone:
            continue
        if not _routed:
            log(f"[{label}] sidebar click never routed to a new /app/<id> after "
                f"{_click_tries} attempt(s) (url={_u or '?'}) — trying next", "WARN")
            continue
        # The conversation content mounts lazily after the URL flips — retry the
        # match a few times before moving on (adversarial-review finding: a
        # single-shot check one render-tick early defeated the whole recovery).
        _matched = False
        for _mi in range(3):
            if await _conversation_matches(page):
                _matched = True
                break
            await asyncio.sleep(2.0)
        if not _matched:
            log(f"[{label}] opened sidebar chat {_u} but its content doesn't contain "
                "our brief — trying next", "WARN")
            continue
        _st = await _adoptable_state(page)
        if _st == "report_present":
            log(f"[{label}] sidebar chat {_u} matches our brief but already holds a "
                "COMPLETED report (previous run of the same brief) — trying next", "WARN")
            continue
        log(f"[{label}] ADOPTED sidebar conversation {_u} (state={_st}) — the send "
            "had registered platform-side after our confirm window", "WARN")
        return page, True
    # None of the top owned candidates body-verified as ours — back out to a
    # fresh home so [2D] doesn't act on a wrong/stale conversation.
    log(f"[{label}] none of the top recent owned chats verified as ours — not adopting", "WARN")
    try:
        await page.goto("https://gemini.google.com/app",
                        wait_until="domcontentloaded", timeout=20000)
    except Exception:
        pass
    return page, False


async def start_agent_no_gemini_wait(browser, cua_client, url, prompt_system, prompt_user,
                                     brief, label, platform, verbose=False,
                                     brief_path=None, source_paths=None,
                                     reuse_page=None):
    """Start agent: open tab → Playwright-direct setup → CUA validation → paste brief → submit.

    source_paths: user-attached source docs (skip-P1 flow). ChatGPT/Claude
    attach them natively alongside the brief; Gemini gets their text pasted
    (it silently drops file uploads). Empty/None = legacy behavior.

    reuse_page (2026-07-06 bot-score work; ChatGPT/2A originally, ALL THREE agents
    since Gap #3 on 2026-07-15 — see the platform-aware branches below): an already-open,
    still-warm tab on this platform (the Phase-1 ChatGPT tab). When given, we
    REUSE it — client-side "New chat" instead of `new_tab(url)` — because every
    cold top-level load of chatgpt.com is a Cloudflare bot-score event, and P2
    was paying a second one per run (plus holding two ChatGPT surfaces) right
    after P1 already established a warm, challenge-passed tab. The reuse path
    falls back to a same-tab goto, and any failure falls all the way back to
    the fresh-tab path — behavior-identical worst case.

    Hard retries DO reuse now (Gap #3 reversed the old "retries always pass None"
    stance): the caller threads the agent's own warm tab and keeps a clean-slate
    escape hatch on hard retry #2. This docstring claimed the opposite long after
    that changed, which sent the 2026-07-27 cold-tab diagnosis down the wrong path —
    the actual gap was the pre-pending stub erasing p["page"].

    Two-layer setup for reliability:
    1. Playwright clicks known selectors (fast, deterministic when UI is stable)
    2. CUA visually validates the intended state and fixes discrepancies
    """
    page = None
    if reuse_page is not None:
        try:
            if not reuse_page.is_closed():
                # Gap #3 (2026-07-15): the reuse path is now platform-aware.
                # Originally ChatGPT/2A-only; the hard-retry restart now threads
                # each agent's own warm tab here so retries reuse the same,
                # challenge-passed tab (a client-side New chat) instead of a cold
                # top-level load (a Cloudflare bot-score event).
                _pl = platform.lower()
                log(f"[{label}] Reusing the warm {platform} tab (client-side New chat — no cold navigation)")
                page = reuse_page
                # Review 2026-07-06: _agent_streams is keyed by id(page) and
                # inject_agent_observer only setdefault-inits it — a reused
                # page would keep the prior run's final text length as this
                # run's starting observer state (wrong partialTextLen from tick
                # 1, poisoned text-growth stall baseline). Hard-reset the entry
                # for EVERY reused platform; the observer injection re-creates
                # it from zero.
                _agent_streams.pop(id(page), None)
                await browser.switch_to_page(page)
                if _pl == "chatgpt":
                    if await _chatgpt_force_new_chat(page, label):
                        await asyncio.sleep(2)
                        # #913: warm-tab hygiene — P1 and P2 share this tab. If
                        # P1's "Activity" panel survived the SPA New chat, P2's
                        # cycle-1 anti-toggle pre-check would flag the panel
                        # open without ever clicking the DR strip and scrape
                        # stale P1 data all phase. Detect + close + log.
                        try:
                            _st_warm = await _chatgpt_activity_state(page)
                            if _st_warm.get("side_panel"):
                                _closed = await _close_chatgpt_side_panel(page)
                                log(f"[{label}] stale P1 activity panel on the reused "
                                    f"tab — close dispatched={_closed} (warm-tab hygiene)")
                                await asyncio.sleep(1)
                        except Exception as _wh_err:
                            log(f"[{label}] warm-tab panel hygiene check failed: {_wh_err}", "DEBUG")
                    else:
                        # SPA New-chat didn't land — same-tab navigation fallback
                        # (one nav; still no second ChatGPT surface).
                        log(f"[{label}] New-chat click didn't land — same-tab nav to {url}", "WARN")
                        await page.goto(url, wait_until="domcontentloaded", timeout=30000)
                        await asyncio.sleep(4)
                else:
                    # Claude: url == https://claude.ai/new — a same-tab nav to
                    #   /new IS Claude's canonical fresh composer (cheaper than a
                    #   fresh tab + a second authenticated surface).
                    # Gemini: url == https://gemini.google.com — a bare /app load
                    #   re-triggers Layer 0.6 below (@~34135), which force-New-
                    #   chats any /app/<id> so we always land on a clean composer.
                    # Both: a same-tab nav on the warm, challenge-passed tab
                    #   AVOIDS a scored cold top-level navigation.
                    log(f"[{label}] Warm-tab reuse ({_pl}) — same-tab nav to {url}")
                    await page.goto(url, wait_until="domcontentloaded", timeout=30000)
                    await asyncio.sleep(4)
        except Exception as _ru_err:
            log(f"[{label}] Warm-tab reuse failed ({_ru_err}) — falling back to a fresh tab", "WARN")
            page = None
    if page is None:
        log(f"[{label}] Opening {url}...")
        page = await browser.new_tab(url)
        await asyncio.sleep(4)

    # LAYER 0: Detect human-verification gates BEFORE Playwright setup tries to
    # click selectors that don't exist under a Cloudflare / CAPTCHA overlay.
    # Gap #1 + HV never-solve: a detected wall is handled HANDS-OFF + NON-BLOCKING
    # below (no tier cascade, no pause) — the automation never touches the wall.
    platform_l = platform.lower()
    blocked, reason = await detect_human_verification(page, platform, label)
    if not blocked:
        # #896: fresh nav landed clean — drop any stale wall verdict from a
        # previous attempt so later fail paths don't blame a wall that's gone.
        # (A wall that re-raises MID-setup is re-detected live by the
        # post-setup-fail probes below, which rebuild the verdict.)
        _controls.hv_blocked.pop(platform_l, None)
    if blocked:
        # Gap #1 + HV never-solve (unified hands-off, user directive 2026-07-15):
        # HV == Cloudflare == the same thing — we do NOT try to clear it. The
        # old wait_for_verification_clearance ran a solve cascade (Playwright
        # click / CUA / cooldown+reload / kill-tab) for non-Cloudflare walls and
        # a tier-5 request_pause + 600s poll for all of them. EVERY interaction
        # with the wall re-issues the challenge and raises the bot score, and the
        # pause froze the single sequential P2 setup coroutine + starved the
        # sibling agents. So P2 no longer calls it: record the sticky verdict and
        # hand straight to _hv_setup_fail_card, which emits the Skip-only
        # hands-off card and (auto-skip on = the default) immediately greys +
        # closes the tab. NON-BLOCKING — 2B/2C keep starting. This covers BOTH
        # the initial-setup path AND the hard-retry path (_restart_phase2_agent
        # has no run_phase2 setup-fail handler of its own). The user solves the
        # wall by hand in the open browser and re-runs if they want the agent.
        # (P1/P5 keep the shared wait_for_verification_clearance — single-surface
        # phases where a pause starves nobody; this change is P2-scoped.)
        _controls.hv_blocked[platform_l] = reason
        log(f"[{label}] HV wall ({reason}) — NON-BLOCKING hands-off handoff: no "
            f"pause, no solve-attempt, no page interaction (unified hands-off)", "WARN")
        await _hv_setup_fail_card(browser, page, platform, label)
        return page, False

    # LAYER 0.5 (#899 work-tab preflight): confirmed signed-out probe on the
    # tab we're about to work in — the isolated verify tab's replacement
    # (that proactive tab was the top bot-score signal; the cookie fast path
    # can't catch a session that died SERVER-side). Non-blocking at P2 by
    # design: a per-agent fail card (Retry/Skip) instead of a pipeline pause,
    # so the other agents keep starting. The card's Retry (hard) re-enters
    # this function fresh and re-probes naturally; the outer 2A/2B/2C fail
    # paths keep their reactive wall probes as backstop.
    _preflight_wall = await _work_tab_signed_out(page, platform_l, label)
    if _preflight_wall:
        emit_event("agent_progress", phase=2, agent=platform_l, status="needs_login",
                   progress=f"{platform}: signed out — not started (sign in, then Retry)")
        fail_agent(platform_l, f"{platform} looks signed out",
                   f"{platform} is showing its sign-in page — the saved session expired. "
                   "Sign in using the open browser (or run the login command on the device), then Retry.")
        return page, False

    # LAYER 0.6 (Gemini-only): force fresh chat. `https://gemini.google.com`
    # natural-redirects to `/app` and Google then auto-routes to the most
    # recent `/app/<chat-id>` for accounts with history. Pasting the brief
    # into a past conversation produces the "stuck in past run" symptom
    # (Gemini answers in the old thread's context, the new run inherits
    # stale state, and detect_completion can fire on the prior turn's
    # Share button). Click "New chat" if URL has a chat id; fall back to
    # a direct nav to /app so we always land on a clean composer.
    if platform_l == "gemini":
        try:
            cur_url = (page.url or "").lower().rstrip("/")
            if "/app/" in cur_url and not cur_url.endswith("/app"):
                log(f"[{label}] Detected past-chat URL ({cur_url}) — forcing New chat")
                clicked = await page.evaluate("""() => {
                    const sel = 'button[aria-label*="New chat" i], a[aria-label*="New chat" i]';
                    const btn = document.querySelector(sel);
                    if (btn && btn.offsetParent !== null) { btn.click(); return true; }
                    for (const el of document.querySelectorAll('button, a, [role="button"]')) {
                        const t = (el.textContent || '').trim().toLowerCase();
                        if (t === 'new chat' && el.offsetParent !== null) { el.click(); return true; }
                    }
                    return false;
                }""")
                if clicked:
                    await asyncio.sleep(2)
                cur2 = (page.url or "").lower().rstrip("/")
                if "/app/" in cur2 and not cur2.endswith("/app"):
                    log(f"[{label}] Still on past chat ({cur2}) — direct nav to /app", "INFO")
                    try:
                        await page.goto("https://gemini.google.com/app")
                        await asyncio.sleep(3)
                    except Exception as _ne:
                        log(f"[{label}] Direct /app nav failed: {_ne}", "WARN")
                else:
                    log(f"[{label}] Fresh chat confirmed ({cur2 or 'unknown'})")
        except Exception as _fe:
            log(f"[{label}] Fresh-chat guard errored (continuing): {_fe}", "WARN")

    # LAYER 1: Playwright-direct setup first
    #
    # Ledgered HERE rather than inside each setup_* — this is the primary
    # attempt, the one whose outcome answers "did the DOM layer do the job, or
    # did vision have to". The recovery re-runs further down deliberately do NOT
    # record: counting a rescue attempt as a separate DOM intent would make the
    # summary read worse the harder the run had to work, which is backwards.
    _setup_t0 = time.time()
    setup_ok = False
    if platform_l == "chatgpt":
        # ⭐ The ONE call site allowed to touch the effort menu — the same rule
        # as setup_claude_dr's allow_probe just below. This is initial setup:
        # the composer is empty and an open popover is harmless. Every other
        # setup_chatgpt_dr call is a pre-send or recovery re-run.
        setup_ok = await setup_chatgpt_dr(page, allow_model_pick=True)
    elif platform_l == "gemini":
        setup_ok = await setup_gemini_dr(page)
    elif platform_l == "claude":
        # ⭐ The ONE call site allowed to run the periodic model-menu check.
        # This is initial setup: the composer is empty, nothing has been sent,
        # and an open popover is harmless. Every other setup_claude_dr call is a
        # recovery/pre-send re-run where opening the model menu would land it
        # over the composer (the #744 screenshot), so they all leave allow_probe
        # at its default False.
        setup_ok = await setup_claude_dr(page, allow_probe=True)
    if platform_l in ("chatgpt", "gemini", "claude"):
        _dom_note(f"{platform_l}.setup_deep_research",
                  "verified" if setup_ok else "missed", phase=2,
                  ms=(time.time() - _setup_t0) * 1000,
                  detail="" if setup_ok else "vision/CUA setup fallback will run")

    # After Playwright tried to set up: if setup failed AND verification is now
    # visible (it can appear mid-setup when Claude's automation detection trips),
    # pause and wait before falling back to CUA.
    if not setup_ok:
        blocked, _hv_reason = await detect_human_verification(page, platform, label)
        if blocked:
            # Gap #1 + HV never-solve (see the Layer-0 twin above): non-blocking
            # hands-off — no clearance cascade, no pause, no page interaction. A
            # wall that surfaces mid-Playwright-setup gets the same treatment,
            # and the CUA setup fallback below is intentionally SKIPPED (running
            # CUA vision against a challenge is itself a score-raising touch).
            _controls.hv_blocked[platform_l] = _hv_reason
            log(f"[{label}] HV wall mid-setup ({_hv_reason}) — NON-BLOCKING "
                f"hands-off handoff (no pause / no solve / no CUA)", "WARN")
            await _hv_setup_fail_card(browser, page, platform, label)
            return page, False
        # ⛔ 2026-08-05 — and the same "do not hand a foreign page to the next rung"
        # rule, enforced here as well. `setup_chatgpt_dr` recovers its own drift and
        # only gives up when it could not get back to a fresh chat, so reaching here
        # on a dated conversation means recovery failed. The rungs below are a VISION
        # pass with a real mouse; pointing one at someone else's finished thread is
        # how the run ends up harvesting it.
        #
        # `recover=False`: setup already tried the new chat and could not get back,
        # so pressing it again here would only add a touch on a walled surface.
        try:
            _u = page.url or ""
        except Exception:
            _u = ""
        if await _refuse_foreign_chatgpt_tab(page, platform, platform_l, label, _u,
                                             recover=False,
                                             why="run the vision/CUA setup rung"):
            return page, False

    if setup_ok:
        log(f"[{label}] Playwright-direct setup OK")

    # ⚠ Explicit, because it used to be a SIDE EFFECT of the validation rung —
    # which the ladder can now skip. `switch_to_page` also brings the tab to the
    # front, and the brief-delivery legs below type and paste into it, so on the
    # happy path (DOM setup wins, validation skipped) the focus guarantee would
    # otherwise have quietly disappeared with the rung that used to provide it.
    # Idempotent: this is already the active page on both entry paths.
    try:
        await browser.switch_to_page(page)
    except Exception as _swe:
        log(f"[{label}] could not bring the agent tab to front ({_swe})", "INFO")

    # ── RUNGS 2 and 3, sequenced. ──
    # See _run_intent_ladder: the rungs below only run while the outcome is NOT
    # verified, and a rung that verifies stops the ladder. Rung 1 (the DOM setup
    # above) is declared as already-run rather than driven from here, because its
    # failure carries the human-verification consequence handled just above and a
    # rung cannot return out of this function.
    _cua_verdict = {}

    async def _rung_cua_setup():
        # Playwright failed — try original CUA setup as a first fallback (tight iterations)
        log(f"[{label}] Playwright setup failed — CUA fallback setup (tight)...")

        async def _setup_fallback_cua():
            return await agent_loop(cua_client, browser, prompt_system, prompt_user,
                model=CUA_MODEL, max_iterations=8, verbose=verbose)

        # #839 act tier: side-effect-only setup (result ignored — the ladder's
        # own outcome probe is the confirmation). #709: DR-active is judged by
        # the composer PLACEHOLDER, never a pill-pressed heuristic — the
        # context_hint encodes it so a Vision actor doesn't toggle a working
        # DR off by misreading a merely-visible chip.
        _setup_placeholder_hint = {
            "gemini": "DR is ON only when the composer placeholder reads 'What do you "
                      "want to research?' (chat mode = 'Ask Gemini'); a visible DR chip "
                      "alone is NOT proof — don't toggle a pill that's already active.",
            "chatgpt": "enable Deep Research mode; do NOT type — set up and focus the input.",
            "claude": "enable Research + the right model/effort; do NOT type.",
        }.get(platform_l, "enable Deep Research mode; do NOT type.")
        await _shadow_observed_cua(
            page, hotspot_id="setup-dr", phase=2, platform=platform_l,
            current_step="setup_deep_research_mode",
            context_hint=f"Playwright DR setup failed — enable Deep Research for {platform}. "
                         + _setup_placeholder_hint,
            expected_outcome="Deep Research mode is active and the input is focused (not typed)",
            cua_coro_factory=_setup_fallback_cua,
            mission_prompt=f"{prompt_system}\n\nTASK: {prompt_user}",
            act_timeout_s=120.0)

    async def _rung_cua_validate():
        # CUA visual validation — confirms options are ACTUALLY active, and may FIX.
        log(f"[{label}] CUA validating setup state...")
        _ok, _confirmed = await validate_setup_with_cua(
            browser, cua_client, page, platform, label, verbose)
        _cua_verdict["ok"] = _ok
        _cua_verdict["confirmed"] = _confirmed
        if not _ok:
            log(f"[{label}] CUA validation failed — proceeding anyway but agent may misbehave", "WARN")

    _ladder = await _run_intent_ladder(
        f"{platform_l}.enable_deep_research",
        [{"tier": "builtin", "ran": True},
         {"tier": "vision_cua", "run": (None if setup_ok else _rung_cua_setup)},
         {"tier": "cua_validate", "run": _rung_cua_validate}],
        verify=lambda: _dr_outcome_state(page, platform_l),
        label=label)

    # `cua_ok`'s only consumer was the "validation failed — proceeding anyway"
    # warning, which now lives inside the rung that produces it. That removes the
    # question of what it should default to when the rung never runs: a rung that
    # did not run cannot have failed, and nothing has to encode that.
    #
    # ⭐ The chat-mode gate below asks "do we have a POSITIVE confirmation that
    # Deep Research is on?" — it used to be able to get one only from the CUA
    # validator, which is why that surface had to run even after the DOM tier had
    # already won. The ladder's own outcome probe is the same kind of evidence
    # (stronger, in fact: it is a mechanical read of the live composer rather
    # than a model's prose), so either source satisfies it and the second surface
    # is no longer needed to produce it.
    setup_confirmed = bool(_cua_verdict.get("confirmed")) or bool(_ladder.get("verified"))

    # ── Brief delivery ──
    # ChatGPT + Claude accept .md file attachments in Deep Research mode and
    # use them as the research plan input. Prefer file-attach for those two
    # platforms when we have a brief_path on disk — it sidesteps composer-
    # truncation edge cases (ChatGPT auto-converts large pastes to
    # attachments and the paste verification then fails).
    #
    # GEMINI EXCEPTION (2026-05-24 revert): file-attach `set_input_files()`
    # returns True (DOM call succeeds) but Gemini's UI silently drops the
    # upload — observed in production E2E where the conversation only
    # contained the inline prompt with no file chip, and extraction yielded
    # 2476 chars of chat transcript instead of the 20-45k char research
    # report seen historically with the paste path. Revert to text paste
    # for Gemini only; ChatGPT + Claude file-attach remains untouched.
    # Fall back to inline paste also when brief_path is missing/unavailable.
    is_gemini = platform.lower() == "gemini"
    use_file_attach = brief_path and Path(brief_path).exists() and not is_gemini
    _brief_via_attach = False  # True only after a VERIFIED attach (see below)
    _paste_chip_head = None    # set when a ChatGPT paste auto-converted to a chip

    if use_file_attach:
        if source_paths:
            log(f"[{label}] Attaching brief file + {len(source_paths)} user source(s): {Path(brief_path).name}")
        else:
            log(f"[{label}] Attaching brief file: {Path(brief_path).name}")
        attached = await attach_brief_file(browser, page, brief_path, platform, label,
                                           extra_files=source_paths)
        if attached:
            # 2026-07-13 (live incident): attach_brief_file's True only means
            # set_input_files didn't throw. ChatGPT showed "There was a
            # problem processing the upload" and the run FIRED with no brief
            # — DR ran on the 218-char inline prompt alone. Verify the chip
            # actually landed (visible + processing settled, no failure
            # toast) with bounded re-attach; on failure fall through to the
            # inline-paste path below so the agent still gets the full brief
            # as text (never a stale run).
            attached = await _ensure_brief_attached(
                browser, page, brief_path, platform, label,
                source_paths=source_paths)
        _brief_via_attach = bool(attached)  # pre-send re-check gate (below)
        if attached:
            await type_inline_prompt_with_cua(page, browser, cua_client,
                                              platform, label, verbose)
        else:
            log(f"[{label}] Brief attachment failed — falling back to inline paste", "WARN")
            # Attach failed → inline the source docs' text so the agent still
            # gets the primary material it would have received as files.
            brief_to_paste = _augment_brief_with_sources(brief, source_paths, label)
            # DOM-once → CUA contract.
            paste_ok = await verified_paste_brief(page, brief_to_paste, platform, label)
            if not paste_ok:
                paste_ok = await cua_paste_fallback(page, browser, cua_client,
                                                     brief_to_paste, platform, label, verbose)
            if not paste_ok:
                log(f"[{label}] CRITICAL: Both attach and paste (DOM+CUA) failed — skipping this agent", "ERROR")
                # #896: attach+paste failing together is the live signature of
                # a human-verification wall raised mid-setup (Composer absent,
                # Clipboard API blocked by the challenge page's permissions
                # policy). Name the real cause instead of the generic card.
                if not await _hv_setup_fail_card(browser, page, platform, label):
                    # #929: `platform` (display name, e.g. "Gemini"), never
                    # `label` — that's the internal step tag ("2C") and it
                    # leaked into user-facing copy ("…hand the brief to 2C").
                    # #63: copy centralized in _brief_send_fail_copy.
                    fail_agent(platform_l, *_brief_send_fail_copy(platform))
                return page, False
    else:
        # Inline paste path — engaged in two cases:
        #   (a) Gemini (file-attach silently drops the upload on Gemini's
        #       UI as of 2026-05-24; paste is the empirically reliable path
        #       that yielded 15-45k char extractions historically)
        #   (b) brief_path not on disk (in-memory brief from older callers)
        if is_gemini:
            log(f"[{label}] Pasting brief directly (Gemini file-attach silently "
                f"drops the upload; paste path empirically works)")
        else:
            log(f"[{label}] Pasting full brief ({len(brief)} chars) with verification...")
        # Gemini (and the brief_path-missing fallback): inline the user's
        # source docs into the pasted brief. Gemini silently drops file
        # uploads, so paste is the only way it sees the primary material.
        brief_to_paste = _augment_brief_with_sources(brief, source_paths, label)
        # DOM-once → CUA contract: single DOM attempt, then a CUA-assisted
        # fallback (CUA focuses composer, Python pastes via clipboard).
        # Removed the old page-reload + 2nd-DOM-retry path — it amplified
        # tab-spam risk (off-target click on a fresh page) without buying
        # reliability that CUA doesn't provide.
        paste_ok = await verified_paste_brief(page, brief_to_paste, platform, label)
        if not paste_ok:
            paste_ok = await cua_paste_fallback(page, browser, cua_client,
                                                 brief_to_paste, platform, label, verbose)
        if not paste_ok:
            log(f"[{label}] CRITICAL: Brief paste failed (DOM + CUA) — skipping this agent", "ERROR")
            # #896: paste-blocked can mean a human-verification wall is up —
            # probe before blaming the paste machinery.
            if not await _hv_setup_fail_card(browser, page, platform, label):
                # #929: platform display name, not the internal step label.
                # #63: copy centralized in _brief_send_fail_copy.
                fail_agent(platform_l, *_brief_send_fail_copy(platform))
            return page, False

    # ── Paste→chip top-up (2026-07-13) ──
    # ChatGPT (and Claude) auto-convert a brief-sized paste into an
    # attachment chip/tile, leaving the composer EMPTY. Send needs an
    # operative message — and the DR agent needs an instruction, not just
    # a bare attachment — so after a converted paste, type the same short
    # inline prompt the attach path uses. Composer-emptiness gates it: a
    # paste that stayed text (Gemini always; small briefs) skips this.
    if not _brief_via_attach and not is_gemini:
        try:
            _comp_len = await page.evaluate(_VERIFY_PASTE_JS)
            if _comp_len < 200:
                log(f"[{label}] Pasted brief auto-converted to an attachment chip "
                    f"(composer at {_comp_len} chars) — typing the operative inline prompt")
                if platform_l == "chatgpt":
                    # remember the chip's head text — the pre-send re-check
                    # verifies the pasted chip survived (it is an upload too
                    # and can die to a late processing failure, same as the
                    # attach path's chip).
                    _pc_lines = brief_to_paste.strip().splitlines() or [""]
                    _paste_chip_head = _pc_lines[0][:12]
                # #950 review: escalate to CUA on a type miss — the same
                # guard the attach path has. A silently-failed type here
                # would send a bare chip with NO operative instruction.
                await type_inline_prompt_with_cua(page, browser, cua_client,
                                                  platform, label, verbose)
        except Exception:
            pass

    # ── Just-before-send: ensure the required mode is STILL active ──
    # Claude especially can silently drop Research tool / Extended model
    # between setup and send. Re-activate if needed.
    mode_state = await ensure_deep_mode_active(page, platform, label)

    # ── E2/DGOPS-7364 + #709 — Deep-Research chat-mode gate (all P2 agents) ──
    # If Layer 1 (setup_*_dr) + Layer 2 (CUA validation) + the just-done
    # pre-send re-activation have all failed to enable Deep Research, do NOT
    # silently send a regular chat prompt — that produces wrong-output (a fast
    # chat reply) instead of a Deep Research report AND the completion ladder
    # then green-ticks the short answer prematurely (#709). Pause and emit a
    # decision alert so the operator decides. Originally Claude-only
    # (DGOPS-7364); generalized to ChatGPT + Gemini on 2026-05-29 (#709) after
    # both stuck in chat mode in E2E (ChatGPT Extended Pro, Gemini Flash).
    if platform_l in ("claude", "gemini", "chatgpt"):
        _name_map = {"claude": "Claude", "gemini": "Gemini", "chatgpt": "ChatGPT"}
        _agent_name = _name_map.get(platform_l, platform_l.title())
        # Per-platform "is Deep Research actually active?" signal. Claude
        # carries an explicit researchOn flag; ChatGPT/Gemini report `active`.
        if platform_l == "claude":
            # #744 (2026-06-01): also honor the Layer-2 CUA visual
            # confirmation. The DOM researchOn read is brittle (the Research
            # pill renders without the aria-pressed/data-state attributes the
            # detector keys on), so a TRUE Research-on state false-negatived
            # → the gate wedged P2 with a chat-mode alert even though Research
            # was on (backend.log 22:39:47). The gate's own contract is "fire
            # only when Layer 1 + Layer 2 + re-activation ALL failed"; OR-ing
            # the Layer-2 confirmation makes the code match that contract.
            # IMPORTANT: key on `setup_confirmed` (a POSITIVE confirmation —
            # either the CUA validator's "verified"/"fixed" verdict or the
            # ladder's own outcome probe), NOT the looser `cua_ok`, which is also
            # True on an ambiguous/errored validation; trusting that would let a
            # real chat-mode degradation slip through silently (#709). A positive
            # confirmation is authoritative over the brittle DOM read.
            research_ok = bool((mode_state or {}).get("researchOn")) or bool(setup_confirmed)
        else:
            research_ok = bool((mode_state or {}).get("active"))

        # ── Step-back fallback: the newest model didn't reach Deep Research ──
        # Retry ONCE on an OLDER model before the chat-mode gate fires, so a
        # just-shipped release that doesn't support Deep Research yet degrades to
        # a working model instead of a Skip. Single-shot (straight-line, no loop);
        # ChatGPT has no model lever → not eligible. The re-pick reuses setup_*_dr
        # so the #744/#751 popover/Escape invariants stay intact, and a failure
        # here just falls through to the existing gate (worst case = today's Skip).
        #
        # ⭐ TWO WAYS TO NAME THE TARGET, NEITHER OF THEM A LITERAL.
        #   • `pin`   — the learned known-good, used only when it is genuinely
        #               BELOW the version that just failed.
        #   • `below` — otherwise: "the highest row strictly older than the one
        #               that failed", resolved from the live menu.
        # The old code fell back to the policy floor (4.8). That was a frozen
        # number AND it went to nothing on a fresh install once the floor was
        # removed; `below` needs no history, so the very first run after an
        # install can still step back.
        if not research_ok and platform_l in ("claude", "gemini"):
            _failed = _P2_PICKED_VERSION.get(platform_l)
            # ⛔ The version that failed belongs to the family this run is on,
            # and so must the pin we retreat to. Without the family, a run that
            # fell back would pin to a number learned from the OTHER family —
            # "4.6" names a real model in both and the same model in neither —
            # and the single retry this path exists to provide would be spent
            # hunting a row that was never on the menu.
            _step_fam = _p2_active_family(platform_l)
            try:
                _kg = p2_known_good(platform_l, _step_fam)
            except Exception:
                _kg = None      # a malformed overlay must never kill the retry
            _failed_f = float(_failed) if isinstance(_failed, (int, float)) else None
            # Only pin to known-good when it is a strictly OLDER model than the
            # one that just failed: re-pinning the same version can't help (it
            # just failed) and would needlessly re-click an already-correct model
            # (the #744-adjacent action).
            # ⚠ `_failed_f is None` is NOT "any pin is fine". With the failed
            # version unknown we cannot prove the pin is older, so pinning could
            # re-select the model that just failed and burn the single retry.
            _pin = (_kg if isinstance(_kg, (int, float))
                    and _failed_f is not None and _kg < _failed_f - 0.001 else None)
            # `below` rides along WITH the pin, not instead of it: the picker
            # prefers an exact pin match and falls back to the best strictly-older
            # row when the pinned version is no longer on the menu (a learned
            # known-good never expires, so weeks later it may simply be gone).
            _below = _failed_f
            if _pin is not None or _below is not None:
                log(f"[{label}] step-back: {platform_l} v{_failed} did not verify into Deep "
                    f"Research — retrying once on an older model "
                    f"({'known-good v%s' % _pin if _pin is not None else 'the highest below v%s' % _below})",
                    "WARN")
                try:
                    if platform_l == "claude":
                        await setup_claude_dr(page, pin_model=_pin, step_below=_below)
                    else:
                        await setup_gemini_dr(page, pin_model=_pin, step_below=_below)
                    # Measure WITHOUT the un-pinned re-activation (reactivate=False)
                    # so the pin HOLDS — the default ensure path re-runs setup
                    # unpinned, which would re-pick the highest (= the model that
                    # just failed) and silently undo the fallback.
                    mode_state = await ensure_deep_mode_active(page, platform, label, reactivate=False)
                    if platform_l == "claude":
                        research_ok = bool((mode_state or {}).get("researchOn")) or bool(setup_confirmed)
                    else:
                        research_ok = bool((mode_state or {}).get("active"))
                except Exception as _kge:
                    log(f"[{label}] step-back retry errored (non-fatal): {_kge}", "WARN")
                if research_ok:
                    # ⛔ "The retry worked" is NOT "a step-back happened", and the
                    # notice may only claim what we can prove. The selectors POP
                    # _P2_PICKED_VERSION on entry and write it only after a row is
                    # actually clicked, so in the COMMON case — no row strictly
                    # older than the one that failed, which is what a platform
                    # offering one current family member plus rejected siblings
                    # looks like — the re-pick early-returns, Deep Research is
                    # enabled anyway and succeeds, and `_stepped_to` is None. The
                    # user then read "used an older model (vNone)" while the
                    # platform sat on exactly the model that had just failed:
                    # a literal "vNone" in an amber notice, attached to a claim
                    # that was false. Prove the retreat before reporting it.
                    _stepped_to = _P2_PICKED_VERSION.get(platform_l)
                    # `_below` IS `_failed_f` and `_pin` can only be set when
                    # `_failed_f` is a number, so the guard above guarantees a
                    # reachable step-back knows the version that failed.
                    if stepped_back_to(_stepped_to, _failed_f):
                        _emit_model_drift_alert(
                            platform_l,
                            f"{_agent_name} used an older model (v{_stepped_to}) for Deep Research",
                            "The newest model couldn't be verified into Deep Research, so the "
                            f"agent stepped back to v{_stepped_to}. The run continues normally.")
                        log(f"[{label}] step-back verified — proceeding on v{_stepped_to}")
                    else:
                        # ⚠ States what was OBSERVED, not a cause. "No row was
                        # clicked" is all we know: no older row on the menu is the
                        # usual reason, but a selector miss or an exception looks
                        # identical from here. Asserting the reason we did not
                        # verify is the same mistake as the vNone notice.
                        log(f"[{label}] Deep Research recovered without a model change"
                            f" — the re-pick selected nothing below v{_failed} on "
                            f"{platform_l} (no older row offered, or the re-pick "
                            "missed), so no step-back is claimed")

        # ── Phoenix model_refresh — thinking-config telemetry (NO user alert) ──
        # When we're proceeding in RESEARCH mode but a policy thinking knob (Claude
        # max-effort + thinking toggle, Gemini extended thinking) couldn't be
        # CONFIRMED at setup, record it to the log + telemetry ONLY — never a
        # user-facing alert. Rationale (live finding 2026-06-22): this confirmation
        # is inherently unreliable — the effort/thinking controls are the most
        # label-volatile in the UI, and Claude has folded "Max effort" into the
        # Extended Pro model so the separate control is simply ABSENT, making the
        # exact-match read miss on essentially every run. Surfacing that as an amber
        # notice is therefore a false alarm nearly every time (the model + Deep
        # Research are correctly selected). Thinking is advisory and never gates, so
        # we keep the signal in the log + _P2_THINKING_STATE telemetry for measuring
        # confirm rates, but we do NOT alert the user.
        if research_ok and platform_l in ("claude", "gemini"):
            # Phoenix on-the-fly learning: this run verified Deep Research on the
            # selected model → record it as the known-good fallback target so it
            # tracks the latest PROVEN model as platforms advance. Pure side-
            # channel (only the fallback TARGET; never the gates); no-op unless
            # DG_MODEL_REFRESH_ENABLED is armed.
            # Family-scoped for the same reason the pin read is — see the
            # step-back note above. A Sonnet version written into the Opus slot
            # is not a smaller mistake than reading it out of one.
            record_known_good(platform_l, _P2_PICKED_VERSION.get(platform_l),
                              _p2_active_family(platform_l))
            _tstate = _P2_THINKING_STATE.get(platform_l) or {}
            _pol = p2_labels(platform_l)
            _missing = []
            if _pol.get("thinking") and not _tstate.get("thinking"):
                _missing.append("extended thinking" if platform_l == "gemini" else "the thinking toggle")
            if platform_l == "claude" and _pol.get("effort") and not _tstate.get("effort"):
                _missing.append("max effort")
            if _missing:
                _ms = " + ".join(_missing)
                # Telemetry only — deliberately NOT an _emit_model_drift_alert (see
                # the block comment above: it false-alarms on nearly every run).
                log(f"[{label}] Phoenix: proceeding with Deep Research; thinking config "
                    f"unconfirmed ({_ms}) — telemetry only, no user alert (advisory, never gates)", "WARN")

        if not research_ok:
            log(f"[{label}] Deep Research unavailable after Layer 1 + Layer 2 + "
                f"pre-send re-activation — chat-mode gate (non-blocking)", "WARN")
            # Gap #1: NON-BLOCKING chat_mode (send-before-decision). The old gate
            # request_pause + wait_if_paused + await_agent_decision(1800) froze
            # the single sequential P2 setup coroutine + starved siblings for up
            # to 30 min. Instead: submit the brief in chat mode NOW (the Send
            # block below is mode-agnostic — same composer, the pill state set by
            # ensure_deep_mode_active decides DR-vs-chat), PARK the keep/skip
            # decision, and fall through. The round-robin resolves it (Continue
            # in chat mode / Skip / auto-skip on timeout) without any pause.
            # Tentative: actual=chat but NOT acknowledged — the park gates
            # finalization (#709 premature green-tick of the fast chat answer)
            # until the user consents.
            _park_chat_mode_decision(
                platform_l, label,
                why="Layer 1 + Layer 2 + pre-send re-activation all failed")
            # fall through to the Send block → return page, True (parked in the
            # round-robin, which finalizes on Continue or discards on Skip/timeout)
        else:
            _runtime.agent_modes[platform_l] = {
                "requested": "research", "actual": "research",
                "user_acknowledged_chat": False,
            }

    # Brief ready — now click Send.
    # #752 (2026-06-02): POLL for an ENABLED send button instead of checking
    # once. ROOT CAUSE (backend-2.log 06:35:24→06:35:25): the send button is
    # transiently DISABLED for several seconds after the composer is filled —
    # most often because the attached brief FILE is still uploading/processing
    # (an upload spinner sits on the file chip), and/or because the just-before-
    # send ensure_deep_mode_active() above can re-invoke setup_chatgpt_dr and
    # briefly reset/blur the composer. The old code checked the selectors
    # exactly ONCE, ~1s after typing — finding the button disabled it logged
    # "Playwright can't find Send" and fell to the slow, non-deterministic CUA
    # fallback whose 90s decision wait left the typed brief sitting unsent in the
    # composer (the "stuck stale, text in the chat box" the user reported; CUA
    # only barely recovered at 06:37:08). Polling clicks the instant the composer
    # is ready (healthy paste/Gemini case fires on the FIRST iteration —
    # behaviour unchanged) and otherwise waits out the disabled window. Bounded
    # at ~20s, after which the JS + CUA fallbacks below still run as before. (The
    # downstream verify_chatgpt_generating gate in run_phase2 2A remains the
    # backstop if an enabled-but-intercepted click ever no-ops.)
    # ── Pre-send attachment re-check (2026-07-13, attach path only) ──
    # A late "problem processing the upload" toast can kill the chip AFTER
    # verification (the mode gates above take seconds). Never click Send
    # while the brief chip is gone — one re-attach round, then an honest
    # Retry/Skip card instead of firing a stale run (the composer already
    # holds the typed prompt, so the paste fallback isn't clean here).
    # A SINGLE probe must not condemn a live attach: typing the inline prompt
    # re-renders the composer, and a one-off found=False there triggered the
    # ruinous re-attach (2026-07-13 blocker). Re-probe a few times; only an
    # EXPLICIT error toast is decided on the first read.
    if _brief_via_attach:
        _pre_send = await _brief_attachment_state(page, Path(brief_path).name)
        if not _pre_send.get("error"):
            for _ in range(3):
                if _pre_send.get("found"):
                    break
                await asyncio.sleep(1.5)
                _pre_send = await _brief_attachment_state(page, Path(brief_path).name)
                if _pre_send.get("error"):
                    break
        if not _pre_send.get("found") or _pre_send.get("error"):
            log(f"[{label}] pre-send re-check: brief chip gone "
                f"(found={_pre_send.get('found')}, error='{_pre_send.get('error','')}') "
                f"— re-attaching before Send", "WARN")
            if not await _ensure_brief_attached(browser, page, brief_path,
                                                platform, label,
                                                source_paths=source_paths,
                                                max_attempts=2):
                log(f"[{label}] CRITICAL: brief chip lost at send time and "
                    f"re-attach failed — NOT sending a brief-less run", "ERROR")
                # Gap #1: the brief never sent, so undo the tentative chat_mode
                # marker (set before this Send). Otherwise a Send-failed but
                # /c/-alive ChatGPT hands off to the round-robin, gets parked
                # kind=chat_mode, and its fail-card Retry is silently converted
                # to a skip by the parked resolver.
                _controls.chat_mode_pending.pop(platform_l, None)
                # #63: copy centralized in _brief_send_fail_copy (rejected variant).
                fail_agent(platform_l, *_brief_send_fail_copy(platform, rejected=True))
                return page, False
    elif _paste_chip_head is not None:
        # Converted-paste twin of the check above: the "Pasted text" chip is
        # an upload too — a late processing failure can kill it after verify,
        # and the composer now only holds the short inline prompt (the exact
        # stale-run the attach-path check exists to prevent).
        try:
            _pc_chips = await page.evaluate(_CHATGPT_PASTED_CHIP_JS, _paste_chip_head)
        except Exception as _pc_err:
            _pc_chips = -1  # probe crashed — don't block the send on a broken probe
            log(f"[{label}] pre-send pasted-chip probe crashed: {_pc_err}", "WARN")
        if _pc_chips == 0:
            log(f"[{label}] pre-send re-check: pasted-text chip gone — "
                f"re-pasting before Send", "WARN")
            if not await verified_paste_brief(page, brief_to_paste, platform, label):
                log(f"[{label}] CRITICAL: pasted brief lost at send time and "
                    f"re-paste failed — NOT sending a brief-less run", "ERROR")
                # Gap #1: undo the tentative chat_mode marker — see the attach-path
                # twin above (a Send-failed /c/-alive agent must not park chat_mode).
                _controls.chat_mode_pending.pop(platform_l, None)
                # #63: copy centralized in _brief_send_fail_copy (rejected variant).
                fail_agent(platform_l, *_brief_send_fail_copy(platform, rejected=True))
                return page, False

    # ⭐ 2026-08-05 — the tab's identity AT THE MOMENT OF SEND. `_chatgpt_force_new_chat`
    # proved the tab was not on a conversation back at setup time, and that proof was
    # never restated: between it and here the run does DR setup, a CUA/Vision setup
    # ladder, a file attach, prompt typing, a DR re-activation and possibly a chat-mode
    # park. On 2026-08-05 the tab was on a fresh composer at 07:01:11 and on the
    # previous evening's conversation by 07:04:00, and nothing in between ever looked.
    def _url_now() -> str:
        try:
            return (page.url or "")
        except Exception:
            return ""

    _pre_send_url = _url_now()

    # ⭐⭐ 2026-08-05 — A GATE, NOT A NOTE. `_pre_send_url` used to be recorded here
    # and only compared AFTER the send; the refusal downstream was an autopsy. On
    # the 11:14 retry that autopsy is exactly what happened: Playwright found an
    # enabled Send at 11:14:58, clicked it, and the brief was submitted into a
    # conversation created the previous evening at 22:46 — three seconds before
    # anything objected. `url_unchanged_from_pre_send` is a true statement about a
    # send that should never have been made.
    #
    # ⛔ Scoped to ChatGPT, and only to a conversation we can DATE as pre-dating
    # the run. `_chatgpt_conversation_is_ours` fails OPEN on an unknowable run
    # start and on a bare `/` (no `/c/` id to read), so a healthy first send —
    # which happens at `https://chatgpt.com/` before the SPA mints an id — passes
    # untouched. The only shape this stops is the one shape that has no innocent
    # explanation: a composer loaded with THIS run's brief sitting in SOMEONE
    # ELSE'S finished thread.
    if await _refuse_foreign_chatgpt_tab(page, platform, platform_l, label,
                                         _pre_send_url, recover=True, why="send"):
        return page, False

    _send_sels = ['button[data-testid="send-button"]', 'button[aria-label="Send prompt"]',
                  'button[aria-label="Send"]', 'button[aria-label="Send message"]',
                  'button[aria-label="Send Message"]', 'button[aria-label="Submit"]']
    sent = False
    await asyncio.sleep(1)
    _send_waited = 0.0
    _send_deadline = 20.0
    while not sent:
        for sel in _send_sels:
            try:
                btn = await page.query_selector(sel)
                if btn and await btn.is_enabled():
                    await btn.click()
                    log(f"[{label}] Send clicked ✓"
                        + (f" (after {_send_waited:.0f}s wait for enable)" if _send_waited >= 1.5 else ""))
                    sent = True
                    break
            except Exception:
                continue
        if sent or _send_waited >= _send_deadline:
            break
        await asyncio.sleep(1.5)
        _send_waited += 1.5
    if not sent:
        try:
            sent = await page.evaluate("""() => {
                const btns = document.querySelectorAll('button');
                for (const b of btns) {
                    const a = (b.getAttribute('aria-label') || '').toLowerCase();
                    const t = b.textContent.trim().toLowerCase();
                    if ((a.includes('send') || t === 'send' || t === 'submit' || a.includes('submit'))
                        && !b.disabled) {
                        b.click(); return true;
                    }
                }
                return false;
            }""")
            if sent:
                log(f"[{label}] Send clicked via JS ✓")
        except Exception:
            pass
    if not sent:
        log(f"[{label}] Playwright can't find Send — CUA clicking...")
        await browser.switch_to_page(page)

        async def _click_send_cua():
            return await agent_loop(cua_client, browser, PROMPT_CLICK_SEND,
                "Click the Send button to submit the message.",
                model=CUA_MODEL, max_iterations=5, verbose=verbose)

        # #839 act tier: side-effect-only last-resort send; success is judged
        # downstream by verify_*_generating in run_phase2's 2A/2B/2C gates.
        await _shadow_observed_cua(
            page, hotspot_id="click-send", phase=2, platform=(platform or "").lower(),
            current_step="click_send_button",
            context_hint="the message is typed — click the composer's Send button "
                         "(Playwright couldn't find it via any selector)",
            expected_outcome="the message is sent and the agent starts responding",
            cua_coro_factory=_click_send_cua,
            mission_prompt=PROMPT_CLICK_SEND)
        # ⭐ 2026-08-05 — URL TRIPWIRE around the vision pass. This is the only
        # actor with a real mouse on this tab, and it is the one that can miss
        # Send and land on a sidebar conversation row instead. Nothing recorded
        # that it had happened: the leg simply continued against a foreign
        # thread whose finished answer it later harvested. A vision agent's aim
        # cannot be fixed from here — its blast radius can.
        _post_cua_url = _url_now()
        if _post_cua_url != _pre_send_url:
            log(f"[{label}] ⚠ the page MOVED during the CUA send pass: "
                f"{_pre_send_url!r} → {_post_cua_url!r}", "WARN")
        log(f"[{label}] CUA send attempted")
        # CUA send is a last resort — Playwright couldn't find a send button
        # via any selector. The click may or may not have landed depending
        # on what CUA saw. Offer the user [Retry send] [Continue (trust it)]
        # [Skip agent] so they can course-correct without waiting 60s for the
        # agent to (maybe) start generating.
        ag_key_send = (platform or "").lower() or None
        # No alert: round-robin proceeds assuming the CUA click landed.
        # If the agent never produces output, fail_agent surfaces from
        # the wall-clock or stall path. Avoiding a banner here keeps
        # the per-agent dropdown clean during normal startup.
        # Wait up to 90s — agent startup is time-sensitive so don't block
        # polling long. Default (timeout) = continue (trust the CUA click).
        if ag_key_send:
            try:
                decision = await _controls.await_agent_decision(ag_key_send, timeout=90.0)
                log(f"[{label}] Send-fallback user decision: {decision}")
                if decision == "retry":
                    try:
                        await browser.switch_to_page(page)

                        async def _click_send_retry_cua():
                            return await agent_loop(cua_client, browser, PROMPT_CLICK_SEND,
                                "Click the Send button to submit the message. The previous attempt may have missed — look carefully for the Send icon.",
                                model=CUA_MODEL, max_iterations=5, verbose=verbose)

                        await _shadow_observed_cua(
                            page, hotspot_id="click-send", phase=2,
                            platform=(platform or "").lower(),
                            current_step="click_send_button_retry",
                            context_hint="user asked to retry the send — the previous click may "
                                         "have missed; look carefully for the Send icon and click it",
                            expected_outcome="the message is sent and the agent starts responding",
                            cua_coro_factory=_click_send_retry_cua,
                            mission_prompt=PROMPT_CLICK_SEND)
                        log(f"[{label}] CUA send retry attempted")
                    except Exception as e:
                        log(f"[{label}] CUA send retry failed: {e}", "WARN")
                # 'skip' → skipped_agents set already populated; polling loop
                # drops the agent on its next tick. 'continue_partial' /
                # 'timeout' → proceed as-is. 'stop' → outer stop handler.
            except Exception as _e:
                log(f"[{label}] Send-decision wait errored: {_e}", "WARN")

    await asyncio.sleep(3)
    # 2026-05-14: in-page Retry auto-click guard (Fix #515) — Gemini-only.
    # When Gemini's "show thinking" path lands on a soft-refusal screen
    # ("Sorry, I can't help…") this clicks the in-page Retry button so
    # the round-robin watchdog doesn't escalate a transient soft-refusal
    # to a human-intervention alert.
    #
    # Originally invoked for all 3 platforms (Fix #515). Re-scoped on
    # 2026-05-14 to Gemini-only: ChatGPT/Claude soft-refusals are rarer,
    # and the fail-text regex could (rarely) match unrelated body text
    # on a healthy "Researching..." page, risking a false-fire that
    # closes a working DR session. Watchdog + verify recover real
    # failures for ChatGPT/Claude.
    if platform_l == "gemini":
        try:
            retried = await _try_inpage_retry_on_research_fail(
                page, platform, label, max_wait_s=90,
            )
            if retried:
                log(f"[{label}] In-page Retry auto-click handled — research re-kicked", "INFO")
                await asyncio.sleep(2)
        except Exception as _re:
            log(f"[{label}] In-page Retry guard raised (non-fatal): {_re}", "DEBUG")

    # ── 2026-08-05: ChatGPT submit-verification — the twin of Gemini's, below ──
    #
    # The comment under this one has stated the principle since 2026-06-23:
    # "confirm the brief actually started a conversation (the URL advances to
    # /app/<id> — the reliable signal: every healthy run gets one, a dropped send
    # never does)". It was applied to exactly one platform out of three. For
    # ChatGPT there was NOTHING between the Send click and `return page, True`
    # that read page.url, counted messages, or proved a conversation had been
    # created by this send.
    #
    # ChatGPT gives us a STRONGER signal than Gemini does: `/c/<uuid>` is minted
    # when a thread's first message is accepted, and the uuid's first group is
    # the creation time in hex seconds. So we can ask not merely "are we in a
    # conversation" but "are we in OURS" — which is the question that matters,
    # because the failure mode is landing in a real, healthy, finished
    # conversation belonging to someone else's evening.
    #
    # Prod 2026-08-05: send at ~07:02, conversation 6a72ce1e = 2026-08-04
    # 22:46:06, run start 06:47:15. 8 hours stale, 39 minutes spent on it, a
    # 120KB off-topic report saved as the run's ChatGPT output. Every one of the
    # four checks below independently fails that run.
    if platform_l == "chatgpt":
        async def _chatgpt_landed(deadline_s: float):
            """(ok, url, reason). Waits for a conversation we can IDENTIFY.

            ⛔⛔ 2026-08-27 — IT USED TO STOP AT THE FIRST THING SHAPED LIKE A
            CONVERSATION AND THEN JUDGE IT. Measured from a real run: three
            seconds after Send, ChatGPT's URL read `/c/WEB:c3a7026f-…`. The id
            carries no timestamp, `_chatgpt_conversation_is_ours` fails closed on
            one it cannot read, and a healthy Deep Research leg was declared
            foreign and skipped SEVEN SECONDS into a 34-minute run. The very next
            run, same code, got a normal id inside the same three seconds and
            sailed through. A race, not a regression.

            ▶ Two changes, and the second is what makes it survive the NEXT
            format change rather than this one:

              1. AN ID WE CANNOT READ MEANS "NOT YET", NOT "FOREIGN". We have a
                 thirty-second budget; spend it. A readable id is still a verdict
                 the moment it appears — in either direction.
              2. IF THE BUDGET RUNS OUT AND THE ID IS STILL UNREADABLE, fall back
                 to what we WATCHED: the URL moved off `_pre_send_url` onto a new
                 conversation, inside our own post-send window. That is direct
                 evidence it is ours, and it does not depend on the id's format.

            ⛔ THE 2026-08-05 INCIDENT STAYS CAUGHT, and this is the line that
            keeps it caught: a conversation whose id we CAN date and which
            predates the run is refused immediately, exactly as before. The
            fallback is reached only by an id nothing can date — never by one that
            can be dated and is old. A warm tab parked in last night's thread has
            a perfectly readable id.

            ⛔ And stripping the `WEB:` prefix is NOT the fix, which is why this
            does not do it. That id decoded to 2074; it would have passed only
            because a random value happened to land in the future, and the next
            one would be rejected all over again.
            """
            _t0 = time.time()
            _last = ""
            _undatable = ""     # a new conversation we watched appear but cannot date
            while time.time() - _t0 < deadline_s:
                _last = _url_now()
                _verdict = _chatgpt_landing_verdict(_last, _pre_send_url)
                if _verdict == "unchanged":
                    return False, _last, "url_unchanged_from_pre_send"
                if _verdict == "ours":
                    return True, _last, "ok"
                if _verdict == "foreign":
                    return False, _last, "conversation_predates_this_run"
                if _verdict == "undatable":
                    # Present, new, and not datable → keep the budget running.
                    _undatable = _last
                if _controls.is_stop():
                    return False, _last, "stopped"
                await asyncio.sleep(1.0)
            return _chatgpt_landing_result(_undatable, _last)

        _cg_ok, _cg_url, _cg_why = await _chatgpt_landed(30.0)
        if not _cg_ok:
            _epoch = _chatgpt_convo_epoch(_cg_url)
            _when = (datetime.fromtimestamp(_epoch).strftime("%Y-%m-%d %H:%M:%S")
                     if _epoch else "unknown")
            _started = _run_start_epoch()
            log(f"[{label}] ChatGPT send did NOT land in a conversation of this run "
                f"({_cg_why}) — url={_cg_url!r} conversation_created={_when} "
                f"run_started="
                f"{datetime.fromtimestamp(_started).strftime('%Y-%m-%d %H:%M:%S') if _started else 'unknown'}",
                "ERROR")
            # A parked chat-mode decision belongs to a send that happened. This
            # one did not, so retract it rather than leave a card asking the user
            # to keep output that will never exist (mirrors the rejected-send twin
            # above).
            _controls.chat_mode_pending.pop(platform_l, None)
            fail_agent(platform_l, *_brief_send_fail_copy(platform))
            return page, False
        # ⭐ SAY WHICH EVIDENCE CONFIRMED IT. "Created by this run" is a claim, and
        # the two routes to it are not equally strong: a datable id is arithmetic,
        # a watched transition is an observation. When the next format change
        # arrives, this line is what tells us the fallback is carrying runs — and
        # a silent fallback is how a weaker check becomes the only check.
        if _cg_why == "undatable_id_transition_observed":
            log(f"[{label}] ChatGPT submission confirmed ✓ — conversation {_cg_url} "
                f"carries no readable timestamp, so this is confirmed by the "
                f"transition we watched: the tab moved off {_pre_send_url!r} onto a "
                f"new conversation within {30.0:.0f}s of Send", "WARN")
        else:
            log(f"[{label}] ChatGPT submission confirmed ✓ — conversation {_cg_url} "
                f"created by this run")

    # 2026-06-23: Gemini submit-verification. Gemini intermittently DROPS a clicked
    # submission — the DOM click "succeeds" but the brief never enters a
    # conversation: the composer reverts to the empty new-chat home and the URL
    # stays the bare .../app (backend-2.log 2026-06-23 ~12:14: Send clicked, URL
    # frozen at bare /app, 0 sources / 0 chars to 23m, user stopped it). The old
    # code returned True regardless, so the [2D] plan-wait burned its full 10-min
    # budget waiting for a 'Start research' that could never appear. Confirm the
    # brief actually started a conversation (the URL advances to /app/<id> — the
    # reliable signal: every healthy run gets one, a dropped send never does);
    # re-submit ONCE; else return False so the caller's skip-gate (run_phase2 2C)
    # marks Gemini failed and skips the dead 10-min dwell.
    if platform_l == "gemini":
        def _gemini_in_conversation() -> bool:
            try:
                u = (page.url or "").split("?", 1)[0].rstrip("/")
                return "/app/" in u  # /app/<conversation-id>, not the bare /app home
            except Exception:
                return False

        async def _gemini_landed(deadline_s: float) -> bool:
            waited = 0.0
            while waited <= deadline_s:
                if _gemini_in_conversation():
                    return True
                await asyncio.sleep(1.5)
                waited += 1.5
            return False

        if not await _gemini_landed(15.0):
            # The conversation URL hasn't advanced to /app/<id>. Under concurrent
            # Deep-Research load Gemini is often just SLOW, or it errors ("Sorry,
            # something went wrong" / "I encountered an error … try again") — OR
            # the send SUCCEEDED into a conversation our tab simply never routed
            # into (the live 2026-07-11 "empty new-chat after the brief" bug: the
            # real conversation is in the sidebar, our tab is stranded on bare
            # /app). #955 Phase 2G: ADOPT that lost conversation FIRST — re-pasting
            # first (the old order) spawned a DUPLICATE run into a fresh chat and
            # orphaned the real one. Only a genuine dropped send (adoption finds
            # nothing) falls through to the re-paste/re-submit ladder. The whole
            # recovery is SILENT (see below) — no alert, no pause — with the
            # terminal blocker firing ONLY if every recovery path is exhausted.

            # ── Silent self-heal (no alert) ──
            # #955 (e2e 2026-07-16): the lost-send recovery is a SELF-HEAL, not a
            # user-action gate — so it must NOT raise an alert and must NOT pause.
            # The old code emitted a recoverable [Retry][Skip] card HERE (a
            # pipeline_error the FE auto-pauses on) BEFORE even attempting the
            # sidebar adopt — which normally resolves in seconds. Its "retract" only
            # emitted a pipeline_warning, which neither un-pauses the FE nor clears
            # the card, so an adopt-SUCCESS stranded the run "Paused" needing a
            # manual resume (the exact live report). We recover QUIETLY instead: a
            # single agent_progress keeps the tile alive (a 2-3 min recovery is well
            # inside the 30-min P2 event-silence watchdog window) with no pausing
            # alert. Only if recovery is EXHAUSTED does the terminal fail_agent
            # [Retry][Skip] blocker fire below — the one genuine user-action alert.
            log(f"[{label}] Gemini submission not confirmed (URL still bare /app) — "
                "adopting a lost conversation before any re-submit (silent self-heal)", "WARN")
            try:
                emit_event("agent_progress", phase=2, agent="gemini",
                           status="starting",
                           progress="Reconnecting to Gemini's research…")
            except Exception:
                pass

            # ── Adopt FIRST (correctness) ──
            # The send may have SUCCEEDED into a conversation our tab never routed
            # into — re-pasting would spawn a DUPLICATE and orphan the real one.
            # Find + adopt the owned, brief-matching, pre-Start conversation
            # (sibling tab / sidebar's most-recent chat) BEFORE any re-submit.
            # Reuses _gemini_adopt_lost_conversation verbatim (a REORDER, not new
            # mechanics). Skipped after a user Stop (#737 spirit — no post-Stop
            # DOM driving). On failure it returns our tab reset to the bare home,
            # so the re-paste ladder below runs cleanly.
            _adopted = False
            if not _controls.is_stop() and not _gemini_in_conversation():
                _pre_adopt_page = page
                try:
                    page, _adopted = await _gemini_adopt_lost_conversation(
                        page, brief_to_paste, label)
                except Exception as _ae:
                    _adopted = False
                    log(f"[{label}] lost-conversation adoption raised "
                        f"(non-fatal): {_ae}", "WARN")
                if _adopted:
                    try:
                        _runtime.register_page("gemini", page)
                    except Exception:
                        pass
                    if page is not _pre_adopt_page:
                        # Sibling-tab adoption — retire the abandoned bare-/app
                        # tab (guard: never the main handle or the last page).
                        try:
                            if (_pre_adopt_page is not getattr(browser, "page", None)
                                    and not _pre_adopt_page.is_closed()
                                    and len(_pre_adopt_page.context.pages) > 1):
                                await _pre_adopt_page.close()
                                log(f"[{label}] closed the abandoned bare-/app tab", "INFO")
                        except Exception:
                            pass
                    # Adopt succeeded — a silent self-heal (no card was ever shown).
                    log(f"[{label}] Gemini submission confirmed ✓ (adopted lost conversation)")
                    return page, True

            # #955 Phase 2G (adversarial finding): a FAILED adoption can leave the
            # tab stranded on a REJECTED candidate's /app/<id> — a concurrent
            # worker's similar-titled chat, or a PREVIOUS run's finished report
            # the ownership / report_present gates refused. The helper's reset-to-
            # home is best-effort (page.goto in try/except) and can time out under
            # load, so DON'T trust it: if we're still in a conversation, force the
            # tab back to the empty home so the ladder below starts from a
            # known-empty composer and its _gemini_in_conversation() landing check
            # stays truthful. If the tab STILL won't leave the stale conversation,
            # FAIL to the terminal blocker — never let the ladder misread that
            # stale chat as a landing and silently confirm Gemini on the WRONG
            # conversation (delivering someone else's / a previous run's report).
            if not _adopted and _gemini_in_conversation():
                log(f"[{label}] adoption rejected the sidebar candidate(s) but left "
                    "the tab on a stale /app/<id> — resetting to the empty home", "WARN")
                for _hg in range(3):
                    try:
                        await page.goto("https://gemini.google.com/app",
                                        wait_until="domcontentloaded", timeout=20000)
                    except Exception as _hge:
                        log(f"[{label}] home reset attempt {_hg + 1}/3 failed ({_hge})", "WARN")
                    if not _gemini_in_conversation():
                        break
                    await asyncio.sleep(1.5)
                if _gemini_in_conversation():
                    log(f"[{label}] tab stuck on a stale conversation we can't leave — "
                        "surfacing the Retry/Skip blocker (refusing to confirm on the "
                        "wrong chat)", "ERROR")
                    try:
                        fail_agent("gemini", *_GEMINI_CANT_START)  # #63: centralized copy
                    except Exception:
                        pass
                    return page, False

            # ── No conversation exists → the send was genuinely dropped →
            # re-paste/re-submit ladder (create it for the FIRST time). ──
            _max_attempts = 3   # #921: standardized to 3 auto-retries before the card
            _landed = False
            log(f"[{label}] no lost conversation to adopt — the send was dropped; "
                "re-pasting + re-submitting", "WARN")
            for _att in range(1, _max_attempts + 1):
                if _controls.is_stop() or _gemini_in_conversation():
                    break
                _retried = await _try_inpage_retry_on_research_fail(
                    page, platform, label, max_wait_s=20)
                if _retried:
                    log(f"[{label}] Gemini error → clicked in-page Retry "
                        f"(attempt {_att}/{_max_attempts})")
                elif not _gemini_in_conversation():
                    # 2026-07-11 incident: the documented drop REVERTS the
                    # composer to empty, so re-clicking Send / pressing Enter
                    # against it is a guaranteed no-op (all 3 retries in the
                    # incident were no-ops). Re-paste the brief first when the
                    # composer is empty — that's what makes a retry real.
                    try:
                        # -1 when the selector finds nothing: selector drift
                        # must degrade to the old re-click behavior, not a
                        # blind re-paste ladder (adversarial-review finding).
                        _composer_len = await page.evaluate(
                            "() => { const c = document.querySelector("
                            "'rich-textarea div[contenteditable=\"true\"]')"
                            " || document.querySelector('rich-textarea');"
                            " return c ? ((c.innerText || '').trim().length) : -1; }")
                    except Exception:
                        _composer_len = -1  # unreadable — don't re-paste blind
                    if _composer_len == 0:
                        log(f"[{label}] composer is EMPTY on retry (dropped send "
                            "reverts it) — re-pasting brief before re-submit", "WARN")
                        try:
                            await verified_paste_brief(page, brief_to_paste,
                                                       platform, label)
                        except Exception as _pe:
                            log(f"[{label}] re-paste raised (non-fatal): {_pe}",
                                "DEBUG")
                    elif _composer_len > 0:
                        log(f"[{label}] composer holds {_composer_len} chars on "
                            "retry — re-submitting as-is", "INFO")
                    else:
                        log(f"[{label}] composer unreadable (selector miss) — "
                            "re-clicking Send as-is, no blind re-paste", "INFO")
                    # 2026-07-19 e2e: the dropped send ALSO reverts the Deep
                    # Research tool selection (and adopt's empty-home reloads
                    # reset the composer to chat mode), so a re-submit without
                    # re-arming DR lands as a PLAIN CHAT message — Gemini
                    # answers the brief inline, no 'Start research' ever
                    # appears, and 2D burns its whole plan-wait + CUA budget on
                    # a research that never existed. Re-arm via the same
                    # pre-send helper the normal path uses (paste → ensure →
                    # send order mirrors it).
                    #
                    # 2026-07-27: this used to log "sending anyway (2D verifies
                    # the plan)" and send. That justification was never true —
                    # the 2D block has NO DR predicate at all, it only waits for
                    # and clicks 'Start research' — so a measured-OFF re-submit
                    # went to chat mode silently. Observed cost on
                    # agent-18df1b0011fc4625: DR read active=False at 14:47:08,
                    # submitted 14:47:11, no plan ever produced, CUA recovery
                    # exhausted 3 attempts over ~6 min, run finished 2/3.
                    # setup_gemini_dr's whole contract is "return False so the
                    # caller's CUA fallback kicks in instead of letting the run
                    # proceed silently in chat mode" — so honour it here: try the
                    # CUA setup tier, RE-MEASURE, and only if it is still off park
                    # the same non-blocking keep/skip gate the pre-send path uses.
                    # Never a silent chat-mode research.
                    #
                    # ⭐ 2026-08-05: the paragraph above was the INTENT and the code
                    # only honoured it on the LAST attempt. Attempts 1 and 2 logged
                    # "still off — will re-arm again", then fell straight through to
                    # the re-submit below and sent anyway. The send returns a plain
                    # chat answer, and `_gemini_landed` accepts the resulting
                    # conversation URL as success — so the run proceeds on a chat
                    # answer dressed as recovered research, which is the exact
                    # outcome this block exists to prevent. `_dr_ok_for_submit`
                    # carries the measurement out to the send gate.
                    _dr_ok_for_submit = True
                    try:
                        _dr_st = await ensure_deep_mode_active(page, platform, label)
                        if not _dr_st.get("active", True):
                            log(f"[{label}] Deep Research still OFF after re-arm "
                                f"(attempt {_att}/{_max_attempts}) — escalating to "
                                "the CUA setup tier before re-submitting", "WARN")

                            async def _resubmit_dr_cua():
                                return await agent_loop(
                                    cua_client, browser, prompt_system, prompt_user,
                                    model=CUA_MODEL, max_iterations=8, verbose=verbose)

                            try:
                                await _shadow_observed_cua(
                                    page, hotspot_id="setup-dr", phase=2,
                                    platform=platform_l,
                                    current_step="setup_deep_research_mode",
                                    context_hint=(
                                        "A dropped send reverted the composer to chat "
                                        "mode. Re-enable Deep Research for Gemini. DR is "
                                        "ON only when the composer placeholder reads "
                                        "'What do you want to research?' (chat mode = "
                                        "'Ask Gemini'); a visible DR chip alone is NOT "
                                        "proof — don't toggle a pill that's already "
                                        "active."),
                                    expected_outcome=("Deep Research mode is active and "
                                                      "the input is focused (not typed)"),
                                    cua_coro_factory=_resubmit_dr_cua,
                                    mission_prompt=f"{prompt_system}\n\nTASK: {prompt_user}",
                                    act_timeout_s=120.0)
                            except Exception as _ce:
                                log(f"[{label}] DR CUA re-arm raised (non-fatal): {_ce}",
                                    "DEBUG")
                            # RE-VERIFY. The CUA tier's own result is not
                            # trustworthy as proof (that is exactly the
                            # "proceeding anyway" hole on the first-pass path);
                            # only a fresh DOM measurement counts.
                            try:
                                _dr_st = await ensure_deep_mode_active(page, platform, label)
                            except Exception:
                                pass
                            if _dr_st.get("active", True):
                                log(f"[{label}] Deep Research recovered by the CUA "
                                    "setup tier — re-submitting as a real research")
                            elif (_att >= _max_attempts
                                    and platform_l not in _controls.chat_mode_pending):
                                # Park ONLY once, and only after the attempts are
                                # genuinely spent. This loop runs 3×, so parking on
                                # first sight would emit three chat-mode cards for one
                                # agent (a duplicate-alert bug) AND ask the user to
                                # decide while we were still going to retry the enable
                                # ladder twice more. The membership check is the
                                # authoritative de-dupe — the marker survives even a
                                # hard-retry rebuild of the pending entry.
                                _park_chat_mode_decision(
                                    platform_l, label,
                                    why=f"dropped-send re-submit: DR still off after "
                                        f"{_max_attempts} re-arm + CUA attempts")
                                _dr_ok_for_submit = False
                            else:
                                log(f"[{label}] Deep Research still off (attempt "
                                    f"{_att}/{_max_attempts}) — will re-arm again on "
                                    "the next attempt", "WARN")
                                _dr_ok_for_submit = False
                    except Exception as _dre:
                        # ⚠ A RAISE is not a measurement. We do not know whether Deep
                        # Research is on, so this deliberately leaves the send enabled
                        # — the previous behaviour — rather than parking a run that
                        # may be perfectly healthy. Only a measurement that actually
                        # read "off" blocks the send.
                        log(f"[{label}] DR re-arm raised (non-fatal): {_dre}", "DEBUG")
                    if not _dr_ok_for_submit:
                        log(f"[{label}] NOT re-submitting on attempt "
                            f"{_att}/{_max_attempts} — Deep Research measured off, and "
                            f"a send now returns a plain chat answer that would be "
                            f"accepted as the recovered research run", "WARN")
                        continue
                    log(f"[{label}] Gemini URL still bare, no error yet — re-submitting "
                        f"(attempt {_att}/{_max_attempts})", "WARN")
                    try:
                        resent = False
                        for _sel in _send_sels:
                            try:
                                _b = await page.query_selector(_sel)
                                if _b and await _b.is_enabled():
                                    await _b.click()
                                    resent = True
                                    break
                            except Exception:
                                continue
                        if not resent:
                            try:
                                await page.keyboard.press("Enter")  # last-resort composer submit
                            except Exception:
                                pass
                    except Exception as _se:
                        log(f"[{label}] Gemini re-submit raised (non-fatal): {_se}", "DEBUG")
                if await _gemini_landed(40.0):
                    _landed = True
                    break
            if _landed or _gemini_in_conversation():
                # A re-submit created the conversation (the send really was
                # dropped, now recovered) — a silent self-heal, no card to clear.
                log(f"[{label}] Gemini submission confirmed ✓ (re-submit landed)")
                return page, True
            # Adoption found nothing AND every re-submit failed → recovery is
            # EXHAUSTED, so NOW surface the terminal Retry/Skip blocker (the one
            # genuine user-action alert; fail_agent also persists the errored
            # tile). Never a silent drop — if the user doesn't act on it, the
            # round-robin auto-skips Gemini anyway (the setup-fail sweep at phase
            # end, or the stuck-card deadline if it enters polling) so the run
            # still finishes.
            log(f"[{label}] Gemini brief never started a research plan after "
                f"{_max_attempts} retries — surfacing a Retry/Skip blocker (no silent skip)", "ERROR")
            try:
                fail_agent("gemini", *_GEMINI_CANT_START)  # #63: centralized copy
            except Exception:
                pass
            return page, False
        log(f"[{label}] Gemini submission confirmed ✓ (conversation started)")
    return page, True


async def run_phase2(browser, cua_client, brief_text, verbose=False, enabled_agents=None):
    """Phase 2: ChatGPT → Claude → Gemini (submit+plan) → scrape-pass → Gemini (Start) → Poll all.

    Sequence change: Gemini moved to last of the setup trio. One round-robin scrape
    pass (ChatGPT → Claude → Gemini) is inserted between Gemini's brief submission and
    the 'Start research' click — it primes the frontend with rich agent_progress data
    (sources, partial_text_len, steps) immediately, instead of waiting for the first
    main-rotation poll tick. Gemini stays in 'planning' (never 'complete') until its
    'Start research' button is clicked — gated by scrape_progress_gemini's planning-gate.

    enabled_agents: list of agent keys to run (e.g. ["chatgpt", "gemini"]). None = all."""
    log("=" * 60)
    log("PHASE 2: Deep Research")
    if enabled_agents:
        log(f"  Enabled agents: {enabled_agents}")
    log("  Sequence: ChatGPT → Claude → Gemini (submit+plan) → scrape-pass → Gemini (Start) → Poll all")
    log("=" * 60)

    # #906: clear STALE skip markers for the agents this pass launches. The
    # tier-5 HV skip now keeps its marker (callers check membership to
    # suppress the duplicate fail card) and the round-robin consumer only
    # discards markers when it actually runs — so a marker could survive a
    # phase-2 restart (e.g. the P3 gate's "Retry Phase 2") and instantly
    # auto-"skip" the relaunched agent at its next HV wait, or silently
    # suppress a legit failure card. A skip is a this-attempt decision, not
    # a persistent config: consume leftovers up front (matches the pre-fix
    # semantics where the consumer discarded every marker each tick).
    for _stale_ag in (enabled_agents if enabled_agents is not None
                      else ("chatgpt", "gemini", "claude")):
        if _stale_ag in _controls.skipped_agents:
            log(f"Phase 2: clearing stale skip marker for {_stale_ag} (fresh launch)", "INFO")
            _controls.consume_skip_marker(_stale_ag)
    # #929: the persisted per-agent tile-status reset ("running") lives at
    # each agent's LAUNCH site (2A/2B/2C "starting" emits below), NOT here —
    # a phase-entry write would strand a never-launched agent on a persisted
    # "running" when the user stops the run during the sequential launch
    # window (review finding, 2026-07-09).

    # Ensure brief.md is on disk for file-attachment delivery (Option A).
    brief_path = None
    if _tracks_dir:
        brief_path = Path(__file__).parent / "queues" / _tracks_dir.name / "documents" / "brief.md"
        try:
            brief_path.parent.mkdir(parents=True, exist_ok=True)
            if not brief_path.exists() or brief_path.stat().st_size < 100:
                brief_path.write_text(
                    f"# Research Brief\n\n{brief_text}", encoding="utf-8")
                log(f"Wrote brief to disk for attachment: {brief_path.name} ({len(brief_text)} chars)")
            else:
                log(f"Using existing brief.md ({brief_path.stat().st_size} bytes)")
        except Exception as e:
            log(f"Could not prepare brief.md for attachment: {e}", "WARN")
            brief_path = None

    # User-attached source docs to deliver to every agent (skip-P1 flow).
    # Empty unless the orchestrator flagged them (P1 didn't run live). Read
    # from disk so it survives pause/resume + hard-retry.
    source_paths = _read_p2_source_paths()
    if source_paths:
        log(f"Phase 2: delivering {len(source_paths)} user source doc(s) to each agent: "
            f"{[Path(p).name for p in source_paths]}")

    agents = {}
    chatgpt_page = None
    claude_page = None
    gemini_page = None

    # ── Step 1 (2A): ChatGPT — already in ChatGPT from Phase 1, just open Deep Research ──
    if enabled_agents is None or "chatgpt" in enabled_agents:
        log("\n--- 2A: ChatGPT Deep Research (already in ChatGPT) ---")
        emit_event("agent_progress", phase=2, agent="chatgpt", status="starting", progress="Opening ChatGPT Deep Research mode...")
        # #929: reset the PERSISTED tile status at actual launch. A checkpoint
        # resume (or a P3-gate "Retry Phase 2") relaunches previously
        # skipped/errored agents, but their stale root-doc "skipped"/"errored"
        # kept the FE icon grey/red through the whole fresh attempt (bug 0 —
        # Claude skipped pre-login stayed grey after resume). Launch-site, not
        # phase-entry, so an early Stop can't strand a never-launched agent on
        # a persisted "running". Same transient value the Retry-intake writes.
        # force=True: this is a legitimate relaunch reset, so it must override a
        # stale "skipped"/"errored" (the guard blocks only the stale retry path).
        _write_agent_terminal_status("chatgpt", "running", force=True)
        # 2026-07-06 bot-score work: REUSE the warm Phase-1 ChatGPT tab instead
        # of opening a second one. Every cold top-level chatgpt.com load is a
        # Cloudflare-scored event; P1 already paid it and left a warm,
        # challenge-passed tab at /c/<brief-id> — 2A now just clicks "New chat"
        # there (client-side routing, invisible to the edge). Detected at
        # runtime by URL so a skip-P1 run (main tab never visited ChatGPT)
        # falls back to today's fresh-tab path automatically.
        _warm_chatgpt_tab = None
        try:
            if (browser.page is not None and not browser.page.is_closed()
                    and "chatgpt.com" in (browser.page.url or "").lower()):
                _warm_chatgpt_tab = browser.page
        except Exception:
            _warm_chatgpt_tab = None
        for attempt in range(2):
            if attempt > 0:
                log("[2A] Retrying ChatGPT (fresh tab)...", "WARN")
                # Never close the reused P1/main tab — the retry gets a clean
                # fresh tab below (reuse_page=None on attempt 1) and closing
                # the main tab would leave browser.page dangling.
                if chatgpt_page is not None and chatgpt_page is not _warm_chatgpt_tab:
                    try: await chatgpt_page.close()
                    except Exception: pass
            chatgpt_page, _chatgpt_setup_ok = await start_agent_no_gemini_wait(
                browser, cua_client, "https://chatgpt.com",
                PROMPT_CHATGPT_DEEP_RESEARCH,
                "Enable Deep Research mode in ChatGPT. Do NOT type — just set up and focus input. Say 'ready for paste'.",
                brief_text, "2A", "ChatGPT", verbose, brief_path=brief_path,
                source_paths=source_paths,
                reuse_page=_warm_chatgpt_tab if attempt == 0 else None)
            if not _chatgpt_setup_ok:
                # Setup/paste failed — start_agent_no_gemini_wait already
                # emitted pipeline_error with Retry/Skip actions. Don't try
                # to verify — there's nothing to verify.
                verified_a = False
                break
            verified_a = await wait_until_verified(verify_chatgpt_generating, chatgpt_page, "2A",
                browser=browser, cua_client=cua_client, max_retries=15, interval=3, verbose=verbose)
            if verified_a:
                break
        # #905: stamp research start at SUBMIT time (like Gemini's post-click
        # stamp) — the round-robin previously stamped start_time at its own
        # entry, minutes later, so MIN_WAIT-gated completion checks ignored
        # a ChatGPT that had already finished during the Gemini plan-wait.
        agents["ChatGPT"] = {"page": chatgpt_page, "verified": verified_a,
                             "url": chatgpt_page.url if chatgpt_page else "",
                             "research_started_at": time.time()}
        if verified_a:
            emit_event("agent_progress", phase=2, agent="chatgpt", status="generating",
                       stage="researching",
                       progress="ChatGPT Deep Research started and verified")
            log("[2A] ChatGPT Deep Research is running ✓")
            await inject_agent_observer(chatgpt_page, "chatgpt")
        else:
            # 2026-05-14: page-alive gating before fail_agent. If the URL
            # transitioned to /c/<id>, the brief WAS submitted and a
            # conversation was started — verify just couldn't read the
            # active state (cross-origin DR iframe). The round-robin
            # poller at poll_all_agents_round_robin already handles the
            # "verified=False but page exists" case (line ~13515), so we
            # hand off without firing the false-alarm banner that would
            # tempt the user into a hard retry that closes the working
            # tab. The fail_agent path remains for genuinely dead pages
            # (still on the bare chatgpt.com URL).
            _chatgpt_url = ""
            try:
                _chatgpt_url = (chatgpt_page.url or "").lower() if chatgpt_page else ""
            except Exception:
                pass
            # ⭐ 2026-08-05 — "at /c/<id>" is not "alive", it is "in SOME
            # conversation". On a tab that has wandered into a pre-existing
            # thread this predicate is true, so the code asserted health from the
            # very fact that proved the failure — and stamped stage="researching"
            # over a leg that was reading last night's finished answer. The
            # liveness semantics are still wanted (a cross-origin DR iframe is
            # unreadable and legitimately false-negatives here); it just has to be
            # liveness of OUR conversation.
            _chatgpt_alive = _chatgpt_conversation_is_ours(_chatgpt_url)
            if "chatgpt.com/c/" in _chatgpt_url and not _chatgpt_alive:
                log(f"[2A] page is at a conversation that is NOT this run's "
                    f"({_chatgpt_url}) — refusing to read it as liveness", "ERROR")
            if _chatgpt_alive:
                log("[2A] verify_chatgpt_generating returned False but page is at this run's /c/<id> — handing off to round-robin polling (no fail_agent banner)", "WARN")
                # stage="researching": the page reaching /c/<id> IS evidence the
                # DR run started — same signal the verified path stamps. Without
                # it, a cross-origin-iframe DR (unreadable → zero counters) would
                # leave the milestone stepper pinned on "Submitted" for the whole
                # run (#922 stepper drives off stage/counters, not status alone).
                emit_event("agent_progress", phase=2, agent="chatgpt", status="generating",
                           stage="researching",
                           progress="ChatGPT DR submitted — verifying via round-robin polling")
                await inject_agent_observer(chatgpt_page, "chatgpt")
            elif _controls.is_stop():
                # #737: a user Stop during the setup/chat-mode pause returns
                # (page, False). Don't mislabel a clean cancellation as a hard
                # agent failure — no red fail_agent banner, no 'errored' status.
                log("[2A] ChatGPT setup ended on user stop — clean cancel, no failure banner", "INFO")
            elif "chatgpt" in _controls.skipped_agents:
                # #906: the user already skipped this agent (e.g. during the
                # HV wait — the tier-5 loop now KEEPS the marker for exactly
                # this check). agent_skipped/status were emitted there; a
                # failure card or "setup/paste failed" progress line here
                # would contradict + duplicate that decision.
                log("[2A] ChatGPT setup ended after a user Skip — no failure card", "INFO")
            else:
                log("[2A] ChatGPT setup failed", "ERROR")
                # Snapshot BEFORE the page probes below (#950 review): those
                # probes (_hv_setup_fail_card / _page_shows_login_wall) can
                # run seconds on a stalled page, and the specific card was
                # already emitted by the launch flow — reading the window
                # after the probes could let it expire and clobber the card.
                _cg_specific_already = _agent_error_recently_carded("chatgpt")
                # Mark as terminally failed so the round-robin doesn't sit on it
                # forever waiting for events that will never arrive.
                emit_event("agent_progress", phase=2, agent="chatgpt", status="failed",
                           progress="ChatGPT setup/paste failed — agent did not start.")
                # #896: a human-verification wall is the most specific cause —
                # probe it before the login-wall check (the sticky hv_blocked
                # verdict also survives a dead page reference).
                if await _hv_setup_fail_card(browser, chatgpt_page, "chatgpt", "2A"):
                    pass
                else:
                    # #893: a stale trusted cookie lands here via a login wall —
                    # name the real cause so Retry is winnable (the generic card
                    # sent users into an identical losing retry loop).
                    _cg_wall = await _page_shows_login_wall(chatgpt_page)
                    if _cg_wall:
                        _controls.cookie_trust_broken.add("chatgpt")
                        log(f"[2A] ChatGPT shows {_cg_wall} — session expired (stale cookie)", "WARN")
                        fail_agent("chatgpt", "ChatGPT looks signed out",
                                   "ChatGPT is showing its sign-in page — the saved session expired. "
                                   "Sign in using the open browser (or run the login command on the device), then Retry.")
                    elif _cg_specific_already:
                        # The launch flow already carded the SPECIFIC cause
                        # seconds ago (e.g. "Couldn't send the brief") — the
                        # generic card shares its alert_id and would overwrite
                        # the better message (live 2026-07-13 03:42). Snapshot
                        # taken before the probes above so it can't expire.
                        log("[2A] specific failure card already up — skipping the generic 'didn't start' card", "INFO")
                    else:
                        fail_agent("chatgpt", "ChatGPT didn't start",
                                   "ChatGPT failed to launch after two tries. Retry to start it fresh, or Skip it.")
                try:
                    # INTERNAL marker (keeps the dead agent out of the poll +
                    # scrape) — NOT a user tap; the consumer must not stamp
                    # user_skip on it (2026-07-11 incident).
                    _controls.skipped_agents.add("chatgpt")
                    _controls.auto_skip_reasons["chatgpt"] = "setup_failed"
                except Exception:
                    pass
    else:
        log("\n--- 2A: ChatGPT SKIPPED (disabled in config) ---")

    # ── Startup gap before opening the next agent ──
    # Human-cadence stagger reduces anti-bot signal and lets ChatGPT's DR
    # iframe settle before we start issuing Claude commands. User-locked
    # 2026-04 overhaul: sequential gaps, each agent verify-started before
    # moving on. Env-tunable (2026-07-02, bot-score work): DG_P2_STAGGER_SEC.
    try:
        _p2_stagger_sec = int(os.environ.get("DG_P2_STAGGER_SEC", "30"))
    except ValueError:
        log("DG_P2_STAGGER_SEC is not an integer — using 30", "WARN")
        _p2_stagger_sec = 30
    if enabled_agents is None or "claude" in enabled_agents:
        log(f"\n[Startup gap] Waiting {_p2_stagger_sec}s before opening Claude...")
        await asyncio.sleep(_p2_stagger_sec)

    # ── Step 2 (2B): Claude — Opus (>= policy floor) + Max effort + Research tool ──
    if enabled_agents is None or "claude" in enabled_agents:
        log("\n--- 2B: Claude Deep Research ---")
        # Version-free like the Phase-2 timeline copy above: the runtime picks the
        # highest Opus offered, so a pinned "4.8" here misreports the moment the
        # family moves on — and it did, the account has been on Opus 5.
        # The family word comes from policy for the same reason the version was
        # removed: a literal here is user-facing copy that goes stale silently.
        emit_event("agent_progress", phase=2, agent="claude", status="starting",
                   progress=f"Opening Claude with the latest "
                            f"{(p2_family('claude') or 'Opus').capitalize()} "
                            f"({str(p2_labels('claude').get('effort', 'max')).capitalize()} "
                            f"effort) + Research tools...")
        # #929: launch-site persisted-status reset — see the 2A note.
        _write_agent_terminal_status("claude", "running", force=True)
        for attempt in range(2):
            if attempt > 0:
                log("[2B] Retrying Claude (fresh tab)...", "WARN")
                try: await claude_page.close()
                except Exception: pass
            claude_page, _claude_setup_ok = await start_agent_no_gemini_wait(
                browser, cua_client, "https://claude.ai/new",
                # Re-rendered on EACH attempt: attempt 1's DOM setup is what
                # discovers a plan limit, so attempt 2 must be told about it.
                claude_deep_research_prompt(_p2_active_family("claude")),
                p2_claude_setup_directive(_p2_active_family("claude")),
                brief_text, "2B", "Claude", verbose, brief_path=brief_path,
                source_paths=source_paths)
            if not _claude_setup_ok:
                verified_c = False
                break
            verified_c = await wait_until_verified(verify_claude_generating, claude_page, "2B",
                browser=browser, cua_client=cua_client, max_retries=15, interval=3, verbose=verbose)
            if verified_c:
                break
        # #905: research start = submit time (see the ChatGPT note above).
        agents["Claude"] = {"page": claude_page, "verified": verified_c,
                            "url": claude_page.url if claude_page else "",
                            "research_started_at": time.time()}
        if verified_c:
            emit_event("agent_progress", phase=2, agent="claude", status="generating",
                       stage="researching",
                       progress="Claude deep research started and verified")
            log("[2B] Claude is running ✓")
            await inject_agent_observer(claude_page, "claude")
        else:
            # 2026-05-14: mirror Fix #5 from ChatGPT 2A. If the URL
            # transitioned from claude.ai/new to claude.ai/chat/<id>, the
            # brief was submitted and a conversation started — verify just
            # couldn't read the active state. Hand off to round-robin
            # polling without firing the false-alarm banner.
            _claude_url = ""
            try:
                _claude_url = (claude_page.url or "").lower() if claude_page else ""
            except Exception:
                pass
            _claude_alive = "claude.ai/chat/" in _claude_url
            if _claude_alive:
                log("[2B] verify_claude_generating returned False but page is at /chat/<id> — handing off to round-robin polling (no fail_agent banner)", "WARN")
                # stage="researching": reaching /chat/<id> IS evidence the run
                # started (mirrors the verified path). Prevents the #922 stepper
                # from stranding a live-but-unreadable Claude on "Submitted".
                emit_event("agent_progress", phase=2, agent="claude", status="generating",
                           stage="researching",
                           progress="Claude DR submitted — verifying via round-robin polling")
                await inject_agent_observer(claude_page, "claude")
            elif _controls.is_stop():
                # #737: a user Stop during the setup/chat-mode pause returns
                # (page, False). Don't mislabel a clean cancellation as a hard
                # agent failure — no red fail_agent banner, no 'errored' status.
                log("[2B] Claude setup ended on user stop — clean cancel, no failure banner", "INFO")
            elif "claude" in _controls.skipped_agents:
                # #906: user already skipped during the HV wait (live repro
                # 2026-07-06: the Skip-only Cloudflare card was answered, and
                # THIS path then emitted the second "hit Cloudflare's human
                # check" card with Retry (hard) + Skip, forcing a second
                # skip). agent_skipped/status were emitted by the HV loop.
                log("[2B] Claude setup ended after a user Skip — no failure card", "INFO")
            else:
                log("[2B] Claude setup failed", "ERROR")
                # Snapshot before the page probes (#950 review — see the 2A twin).
                _cl_specific_already = _agent_error_recently_carded("claude")
                emit_event("agent_progress", phase=2, agent="claude", status="failed",
                           progress="Claude setup/paste failed — agent did not start.")
                # #896: human-verification wall first — Claude's in-app
                # Cloudflare gate is exactly what used to land here as the
                # misleading generic "didn't start" card (live 2026-07-02).
                if await _hv_setup_fail_card(browser, claude_page, "claude", "2B"):
                    pass
                else:
                    # #893: stale-cookie login wall → honest signed-out card.
                    _cl_wall = await _page_shows_login_wall(claude_page)
                    if _cl_wall:
                        _controls.cookie_trust_broken.add("claude")
                        log(f"[2B] Claude shows {_cl_wall} — session expired (stale cookie)", "WARN")
                        fail_agent("claude", "Claude looks signed out",
                                   "Claude is showing its sign-in page — the saved session expired. "
                                   "Sign in using the open browser (or run the login command on the device), then Retry.")
                    elif _cl_specific_already:
                        # See the 2A twin — don't clobber the specific card
                        # (snapshot taken before the probes above).
                        log("[2B] specific failure card already up — skipping the generic 'didn't start' card", "INFO")
                    else:
                        fail_agent("claude", "Claude didn't start",
                                   "Claude failed to launch after two tries. Retry to start it fresh, or Skip it.")
                try:
                    # INTERNAL marker — NOT a user tap (see the 2A note).
                    _controls.skipped_agents.add("claude")
                    _controls.auto_skip_reasons["claude"] = "setup_failed"
                except Exception:
                    pass
    else:
        log("\n--- 2B: Claude SKIPPED (disabled in config) ---")

    # ── Startup gap before opening Gemini (same DG_P2_STAGGER_SEC knob) ──
    if enabled_agents is None or "gemini" in enabled_agents:
        log(f"\n[Startup gap] Waiting {_p2_stagger_sec}s before opening Gemini...")
        await asyncio.sleep(_p2_stagger_sec)

    # ── Step 3 (2C): Gemini — submit brief, let it generate plan (don't click Start yet) ──
    gemini_setup_ok = False
    if enabled_agents is None or "gemini" in enabled_agents:
        log("\n--- 2C: Gemini Deep Research (submit + let it plan) ---")
        emit_event("agent_progress", phase=2, agent="gemini", status="starting", progress="Opening Gemini and submitting research brief...")
        # #929: launch-site persisted-status reset — see the 2A note.
        _write_agent_terminal_status("gemini", "running", force=True)
        gemini_page, gemini_setup_ok = await start_agent_no_gemini_wait(
            browser, cua_client, "https://gemini.google.com",
            PROMPT_GEMINI_DEEP_RESEARCH,
            "Enable Deep Research mode in Gemini. Do NOT type — just set up and focus input. Say 'ready for paste'.",
            brief_text, "2C", "Gemini", verbose, brief_path=brief_path,
            source_paths=source_paths)
        if gemini_setup_ok:
            log("[2C] Gemini brief submitted — letting it generate research plan")
            emit_event("agent_progress", phase=2, agent="gemini", status="generating", stage="planning", progress="Gemini generating research plan...")
            # #893 tier backstop: with verification off by default, the P0
            # walk + gate tier checks no longer run — this DOM read on the
            # ALREADY-OPEN work page (zero navigations, no CUA) is Gemini's
            # only Free-tier tell. Free output silently degrades DR quality,
            # which is exactly what pro_required exists to surface. Fail-open
            # ("unsure" → no card), one-shot, respects prior consent.
            if (not _controls.pro_warning_acknowledged
                    and not _controls.free_tier_consent.get("gemini", False)
                    and "gemini" not in _controls.skipped_agents):
                try:
                    _gm_tier = await _gemini_dom_tier(gemini_page)
                except Exception:
                    _gm_tier = "unsure"
                if _gm_tier == "free":
                    # Round 2 (#60): Free-tier is NOT a user-action gate. The Deep
                    # Research is already generating server-side and the run
                    # continues on Free regardless; Skip stays reachable via the
                    # normal agent-tile control. Downgrade the (already
                    # non-blocking) pro_required card to a PASSIVE status: no card,
                    # no ack to chase, no round-robin consumer needed. stage=
                    # "planning" preserves the milestone the emit above just set
                    # (a bare status="generating" would reset the stepper).
                    log("[2C] Gemini DOM tier reads FREE — passive Free-tier status "
                        "(no pro_required card; run continues on Free)", "INFO")
                    emit_event("agent_progress", phase=2, agent="gemini",
                               status="generating", stage="planning",
                               progress="Running Gemini on the Free tier — Deep Research quality may be lower")
        elif "gemini" in _controls.skipped_agents:
            # #906: the user already skipped Gemini (e.g. during the HV wait
            # — the tier-5 loop keeps the marker for this check). The skip
            # emitted agent_skipped/status there; a "failed" status here
            # would clobber it. The marker also skips the [2D] plan wait.
            log("[2C] Gemini setup ended after a user Skip — no failure status", "INFO")
        else:
            # Setup or paste failed — start_agent_no_gemini_wait already emitted
            # pipeline_error with Retry/Skip actions. Mark Gemini terminally
            # failed so the [2D] wait loop is skipped and the round-robin
            # poller treats it as done. No more lying about "generating plan".
            log("[2C] Gemini setup/brief delivery failed — marking agent failed, skipping [2D] plan wait", "ERROR")
            emit_event("agent_progress", phase=2, agent="gemini", status="failed",
                       progress="Gemini setup/brief delivery failed — agent did not start.")
            # #893: stale-cookie login wall → record it so the next gate check
            # runs the full verify (the pipeline_error card already offers
            # Retry/Skip; a Google login redirect is the giveaway here).
            # #896: skip the wall probe when a human-verification wall is the
            # known cause — the inner fail path already named it.
            if "gemini" not in _controls.hv_blocked:
                _gm_wall = await _page_shows_login_wall(gemini_page)
                if _gm_wall:
                    _controls.cookie_trust_broken.add("gemini")
                    log(f"[2C] Gemini shows {_gm_wall} — session expired (stale cookie)", "WARN")
            # bug 2.5: register the FAILED Gemini in `agents` (ChatGPT/Claude
            # already are, even on failure) so the round-robin's auto-skip
            # FINALIZATION can reach its tab handle and grey it + close the tab
            # exactly like a normal skip. verified=False + the skip marker below
            # mean the poll set drops it on tick 1 (never polled); the tab stays
            # open as the live Retry/Skip target until the run finalizes P2
            # without it, at which point the finalizer auto-skips it cleanly.
            agents["Gemini"] = {"page": gemini_page, "verified": False,
                                "url": (gemini_page.url if gemini_page else ""),
                                "research_started_at": time.time(),
                                "setup_failed": True}
            try:
                # INTERNAL marker — NOT a user tap. This exact add is what the
                # 2026-07-11 incident leaked through the user-skip consumer:
                # Gemini's failed brief was reported "skipped by user" and the
                # honest Retry/Skip card was phantom-cleared 4s after raise.
                # ([2D] is independently gated on gemini_setup_ok; the poll's
                # internal branch consumes this marker silently on its first
                # tick — no user_skip emit, card/tile untouched. The card is
                # finalized to a clean auto-skip at P2 exit — see the
                # auto-skip finalizer in poll_all_agents_round_robin.)
                _controls.skipped_agents.add("gemini")
                _controls.auto_skip_reasons["gemini"] = "setup_failed"
            except Exception:
                pass
    else:
        log("\n--- 2C: Gemini SKIPPED (disabled in config) ---")

    # ── #899 tier backstop (ChatGPT) — deliberately positioned AFTER 2C, once
    # all three agents have launched. A pro_required pause here only delays
    # the round-robin polling start (the DRs generate server-side) — pausing
    # inside 2A would freeze Claude + Gemini startup behind a fail-open DOM
    # heuristic, the exact phase-blocking the Layer 0.5 preflight design
    # forbids. With verification off by default and the gate's isolated-tab
    # tier check retired, this DOM read on the ALREADY-OPEN work page (zero
    # navigations, no CUA) is ChatGPT's Free-tier tell on runs where the P1
    # Pro-selector backstop never runs (skip-P1 / attached-sources runs).
    # Fail-open ("unsure" → no card), one-shot, respects prior consent.
    # Liveness accepts the 2A alive-handoff too (verify read False but the
    # page is at /c/<id> — the cross-origin-DR-iframe false negative): that
    # run IS generating, so it deserves the same tier tell.
    _cg_entry = agents.get("ChatGPT", {})
    # 2026-08-05: same correction as the 2A handoff — being in A conversation is
    # not being in OURS, and a stale thread must not gate a tier probe as though
    # the run were live in it.
    _cg_alive = bool(_cg_entry.get("verified")) or \
        _chatgpt_conversation_is_ours((_cg_entry.get("url") or "").lower())
    if (_cg_alive
            and not _controls.pro_warning_acknowledged
            and not _controls.free_tier_consent.get("chatgpt", False)
            and "chatgpt" not in _controls.skipped_agents):
        try:
            _cg_tier = await _chatgpt_dom_tier(chatgpt_page)
        except Exception:
            _cg_tier = "unsure"
        if _cg_tier == "free":
            # Round 2 (#60): Free-tier is not a user-action gate — the ChatGPT DR
            # is already generating server-side and the run continues on Free.
            # Passive status instead of the (non-blocking) pro_required card.
            # stage="researching" matches the live DR stage at this post-2C point
            # (the round-robin corrects it next tick regardless).
            log("[2A] ChatGPT DOM tier reads FREE — passive Free-tier status "
                "(no pro_required card; run continues on Free)", "INFO")
            emit_event("agent_progress", phase=2, agent="chatgpt",
                       status="generating", stage="researching",
                       progress="Running ChatGPT on the Free tier — Deep Research quality may be lower")

    # ── First wave: 60s sequential per agent (2026-04 overhaul) ──
    # Instead of one instant snapshot, dwell on each agent's tab for 60s and
    # emit agent_progress every ~15s. This gives the frontend a richer,
    # ladder-like narration start while staying at human cadence. Sequence
    # order matches the original submission: ChatGPT → Claude → Gemini.
    # Gemini's planning-gate inside scrape_progress_gemini keeps its status
    # pinned to 'planning' while the Start-research button is still visible.
    # 2026-04-25: First-wave dwell DROPPED from 60s/agent (180s total) to 0s.
    # Round-robin starts immediately and emits agent_progress live as it
    # observes each tab; the dwell delayed real round-robin start without
    # adding signal the round-robin couldn't deliver itself.
    log("\n--- 2 first-wave (skipped — round-robin starts immediately) ---")
    _scrape_targets = [
        ("chatgpt", "ChatGPT", chatgpt_page, scrape_progress_chatgpt),
        ("claude",  "Claude",  claude_page,  scrape_progress_claude),
        ("gemini",  "Gemini",  gemini_page,  scrape_progress_gemini),
    ]
    _FIRST_WAVE_SEC = 0
    _FIRST_WAVE_TICK = 15
    for _ag_key, _ag_name, _ag_page, _scrape_fn in _scrape_targets:
        if _ag_page is None:
            continue
        try:
            await browser.switch_to_page(_ag_page)
            await asyncio.sleep(1)
        except Exception as _e:
            log(f"  [First-wave] switch to {_ag_name} failed: {_e}", "WARN")
            continue
        log(f"  [First-wave] Dwelling on {_ag_name} for {_FIRST_WAVE_SEC}s...")
        _wave_start = time.time()
        _last_emit_len = -1
        while time.time() - _wave_start < _FIRST_WAVE_SEC:
            try:
                _snap = await _scrape_fn(_ag_page) or {}
                if _ag_key == "gemini":
                    _st = (_snap.get("status") or "").lower()
                    if _st in ("complete", "done"):
                        _snap["status"] = "generating"
                        _snap["phase"] = "planning"
                _sources = int(_snap.get("sources", 0) or 0)
                _partial = int(_snap.get("partial_text_len", 0) or 0)
                _steps = _snap.get("steps", []) or []
                _progress = _snap.get("progress") or (
                    f"Working — {_sources} sources, {_partial} chars" if _partial else
                    (_steps[-1] if _steps else f"{_ag_name} starting up")
                )
                # Only emit if something actually changed to avoid frontend churn
                if _partial != _last_emit_len or _last_emit_len < 0:
                    emit_event("agent_progress", phase=2, agent=_ag_key,
                               status=_snap.get("status", "generating"),
                               progress=_progress,
                               sources=_sources,
                               source_urls=(_snap.get("source_urls", []) or [])[:_SOURCE_LIST_CAP],
                               partial_text_len=_partial,
                               steps=_steps[-3:] if _steps else [],
                               thinking=(_snap.get("thinking") or "")[:300])
                    _last_emit_len = _partial
                    log(f"  [First-wave/{_ag_name}] status={_snap.get('status')}, "
                        f"sources={_sources}, partial_len={_partial}")
            except Exception as _e:
                log(f"  [First-wave/{_ag_name}] tick failed (non-fatal): {_e}", "WARN")
            await asyncio.sleep(_FIRST_WAVE_TICK)

    # ── Step 4 (2D): Return to Gemini — wait for plan + click "Start research" ──
    # 2026-04 overhaul: no rotation to ChatGPT/Claude during this wait. We
    # dwell on the Gemini tab until the Start-research button is clicked;
    # the OFFICIAL round-robin only begins after that click. ChatGPT/Claude
    # keep running in the background — their state from the first-wave dwell
    # is the last frontend update until the round-robin picks them up.
    #
    # Skip the entire [2D] loop if Gemini's setup failed (setup_ok == False)
    # OR was marked skipped (e.g. via Retry/Skip Skip path). Without this
    # gate the loop sits 10 minutes waiting for a "Start research" button
    # that will never appear because no plan was ever generated.
    _gemini_skipped = False
    try:
        _gemini_skipped = "gemini" in (_controls.skipped_agents or set())
    except Exception:
        _gemini_skipped = False
    if gemini_page is not None and gemini_setup_ok and not _gemini_skipped:
        log("\n--- 2D: Gemini — waiting for research plan + clicking 'Start research' (focused, no rotation) ---")
        await browser.switch_to_page(gemini_page)
        await asyncio.sleep(2)

        start_clicked = False
        # #929: set when the user skips Gemini mid-2D (plan wait or CUA
        # recovery). The skip is finalized in place (agent_skipped + tab
        # close), so the recovery/verify/round-robin hand-off below must
        # all stand down for this agent.
        _gemini_2d_skipped = False
        # Cap the plan-draft wait near the user's "Start research in 3-5 min max"
        # expectation (was a flat 10 min, which felt far too long on a stuck plan).
        # Env-overridable for a genuinely slow-but-healthy plan. After this window
        # the bounded CUA recovery runs, then an honest fail_agent (Retry/Skip).
        _start_wait_max_sec = int(os.environ.get("GEMINI_PLAN_WAIT_SEC", str(5 * 60)))
        # Shared JS: click the "Start research" button, and a sibling probe for
        # whether it's STILL present (used to confirm a click actually took).
        # #953: hoisted to module scope (_GEMINI_CLICK_START_JS /
        # _GEMINI_START_PRESENT_JS) so the round-robin's late-Start watch leg
        # runs the exact same #905-hardened predicate — local aliases kept so
        # this block reads unchanged.
        _click_start_js = _GEMINI_CLICK_START_JS
        _start_present_js = _GEMINI_START_PRESENT_JS
        _loop_start = time.time()
        _last_plan_emit = 0.0
        _last_claude_q_probe = 0.0  # #953: background Claude question-card sweep
        # #755 (2026-06-02): Gemini sometimes fails to draft the research plan
        # (shows "...something went wrong" + a Regenerate/Retry button instead of
        # "Start research"). Auto-click that retry, bounded, so the plan re-drafts
        # and the loop can then click "Start research" — instead of dwelling the
        # full 10 min and escalating to a needless human alert.
        _regen_count = 0
        _GEMINI_MAX_PLAN_REGEN = 3
        _GEMINI_REGEN_COOLDOWN_SEC = 45   # space attempts so a slow-but-healthy
        _last_regen_at = 0.0              # re-draft can't burn the 3-cap
        _regen_cap_emitted = False
        _logged_stall_diag = False
        # #921 incident-3: surface a [Retry][Skip] card EARLY. Before this, the
        # honest fail_agent lived only after the full 300s plan-wait + a 3× CUA
        # recovery ladder (~17 min) — so the 2026-07-08 stale run (Gemini
        # answered the brief as plain chat, no plan / no 'Start research' ever
        # rendered) sat with no card until the user hit Stop. We now raise a
        # NON-BLOCKING card the moment the plan has clearly failed (3 error
        # regens OR no plan at all after _PLAN_ALERT_SEC), while the loop + CUA
        # recovery keep self-healing. If a plan then appears we retract it.
        _plan_alert_emitted = False
        _PLAN_ALERT_SEC = int(os.environ.get("GEMINI_PLAN_ALERT_SEC", "240"))  # 4 min: a plan normally drafts in 1-3 min
        # #929: plan-STREAMING hold-off. The flat 300s budget + 4-min card
        # fired on a healthy plan that simply took >5 min to draft
        # (2026-07-09 live false alarm → card → auto-skip of a working
        # Gemini). While the heartbeat scrape shows the plan actively
        # generating (status='generating': stop button / streaming attr /
        # running animation — scrape_progress_gemini ~16620), we hold the
        # early card and extend the wait, bounded by a hard cap so a
        # misread animation can't dwell forever.
        _stream_max_sec = int(os.environ.get("GEMINI_PLAN_STREAM_MAX_SEC", "900"))
        _last_stream_seen_at = time.time()  # grace: the submit just happened
        # #953 (2026-07-13 run): Gemini AUTO-STARTED its research (plan at
        # ~95s, Start button rendered already-disabled, research ran with no
        # click) — the streaming heartbeat then read the RUNNING RESEARCH as
        # "plan still streaming", so the #929 extension dwelt the full 900s
        # cap, the CUA recovery ladder spent ~7 min re-clicking the grayed
        # Start button ("spamming Start Research"), a false "couldn't start"
        # card fired on a healthy agent, and ChatGPT/Claude went unpolled for
        # 22 minutes. A PLAN never streams for more than a few minutes — so
        # past this hand-off point, persistent streaming means the research
        # is (almost certainly) already running. Instead of dwelling, HAND
        # OFF to the round-robin: its detectors decide (they correctly
        # declared this very run done at 98k chars), and its late-Start
        # watch leg (#953, poll loop) clicks a slow plan's Start button if
        # one appears after all. No CUA ladder, no card — both are for the
        # truly-dead (non-streaming) plan only.
        _stream_handoff_sec = int(os.environ.get("GEMINI_PLAN_STREAM_HANDOFF_SEC", "360"))
        _streaming_handoff = False

        def _raise_plan_alert(where: str):
            """Put the non-blocking [Retry][Skip] card up, once."""
            nonlocal _plan_alert_emitted
            if _plan_alert_emitted or _controls.is_stop():
                return
            _plan_alert_emitted = True
            log(f"[2D] Plan not started after {int(time.time() - _loop_start)}s "
                f"(regens={_regen_count}) — surfacing early [Retry][Skip] card "
                f"({where}; non-blocking, recovery continues)", "WARN")
            try:
                fail_agent("gemini", *_GEMINI_CANT_START)  # #63: centralized copy
            except Exception:
                pass

        def _retract_plan_alert(where: str):
            # #921/#929: retract the early plan-stall card once the plan
            # recovers. The main-loop click path always did this; the two
            # CUA-recovery success paths didn't — leaving a stale
            # [Retry][Skip] card sitting on a healthy researching Gemini.
            nonlocal _plan_alert_emitted
            if not _plan_alert_emitted:
                return
            try:
                emit_event("pipeline_warning", phase=2, agent="gemini",
                           error="Gemini's research plan started",
                           details="Gemini recovered and began its deep research.",
                           actions=[], alert_id=_agent_error_alert_id("gemini", 2),
                           auto_clear_on_resume=True)
                _clear_pending_decision("gemini")
            except Exception:
                pass
            _plan_alert_emitted = False
            log(f"[2D] Retracted the early plan-stall card — plan recovered ({where})", "INFO")

        while True:
            # #929: dynamic budget — original 300s window, extended while the
            # plan is visibly streaming, hard-capped at _stream_max_sec.
            _elapsed = int(time.time() - _loop_start)
            _streaming_recent = (time.time() - _last_stream_seen_at) < 45
            # #953: still streaming past the hand-off point → the research
            # (almost certainly) auto-started — hand off to the round-robin
            # instead of dwelling to the hard cap + CUA ladder + false card.
            if _elapsed >= _stream_handoff_sec and _streaming_recent:
                _streaming_handoff = True
                log(f"[2D] Still streaming at {_elapsed}s (≥ {_stream_handoff_sec}s) — a plan "
                    "never streams this long, so Gemini has almost certainly auto-started its "
                    "research. Handing off to the round-robin (detectors decide; its watch leg "
                    "clicks a late 'Start research' if one appears)", "INFO")
                break
            if _elapsed >= _stream_max_sec:
                log(f"[2D] Plan wait hard cap reached ({_elapsed}s ≥ {_stream_max_sec}s) "
                    "— handing off to recovery", "WARN")
                break
            if _elapsed >= _start_wait_max_sec and not _streaming_recent:
                # ⛔ THE CARD HAS TO GO UP HERE, not merely be allowed to. The
                # timer arm is now tied to this same budget, and this break sits
                # ABOVE the card block — so leaving it out would make that arm
                # unreachable and quietly delete the #921 protection, which is
                # the exact "a guard that can never fire" shape this file spent
                # 2026-08-17 removing from two other steps.
                if _gemini_plan_card_due(
                        elapsed=_elapsed, wait_max_sec=_start_wait_max_sec,
                        alert_sec=_PLAN_ALERT_SEC,
                        regen_capped=_regen_cap_emitted,
                        streaming_recent=_streaming_recent,
                        start_clicked=bool(start_clicked)):
                    _raise_plan_alert("our own plan-wait budget is spent")
                break
            # #755: stop/pause-aware — a 10-min plan wait must honor Stop/Pause.
            if _controls.is_stop():
                log("[2D] Stop requested during plan wait — exiting loop", "INFO")
                break
            if _controls.is_pause():
                await _controls.wait_if_paused()
                if _controls.is_stop():
                    break
            # #929: consume a user Skip DURING the plan wait — pre-fix this
            # loop only honored Stop, so a Skip on the early card left it
            # regenerating/waiting on a dismissed agent with NO agent_skipped
            # ever emitted (persisted tile stayed red — the grey-fade-on-skip
            # rule broke) and the tab left open.
            if "gemini" in _controls.skipped_agents:
                log("[2D] User skipped Gemini during the plan wait — finalizing skip", "INFO")
                _controls.consume_skip_marker("gemini")
                _gemini_2d_skipped = True
                emit_event("agent_skipped", phase=2, agent="gemini", reason="user_skip")
                await _close_skipped_agent_tab(browser, gemini_page, "gemini", "Gemini")
                break
            # 1. Check Start-research button on Gemini and click if present
            try:
                await browser.switch_to_page(gemini_page)
                clicked = await gemini_page.evaluate(_click_start_js)
                if clicked:
                    # Guard: confirm the click actually TOOK — the button should
                    # vanish (or disable) as the research begins. #953 (user
                    # directive): click ONCE and WAIT — the old 2s-spaced triple
                    # re-click spammed a button that just needed a moment to
                    # react ("send Start Research and wait, only retry if it
                    # doesn't fire"). Now: after the click, watch for up to 15s
                    # (5×3s) before concluding it missed; only then ONE re-click
                    # and one more 15s watch. The present-probe counts only an
                    # ENABLED button, so a click that disabled it reads as took.
                    _took = False
                    _reclicks = 0
                    for _vi in range(10):
                        await asyncio.sleep(3)
                        try:
                            _still = await gemini_page.evaluate(_start_present_js)
                        except Exception:
                            _still = False
                        if not _still:
                            _took = True
                            break
                        if _vi == 4 and _reclicks == 0:
                            _reclicks = 1
                            log("[2D] 'Start research' still present 15s after the "
                                "click — one re-click, then waiting again", "INFO")
                            try:
                                await gemini_page.evaluate(_click_start_js)
                            except Exception:
                                pass
                    if _took:
                        log("[2D] Clicked 'Start research' via JS ✓ (confirmed it took)")
                        start_clicked = True
                        # #921: the plan recovered after we'd raised the early
                        # [Retry][Skip] card — retract it so a stale error card
                        # doesn't sit on a now-healthy agent (#929: shared
                        # helper, also used by the CUA-recovery success paths).
                        _retract_plan_alert("main loop")
                        await asyncio.sleep(5)
                        break
                    log("[2D] 'Start research' click didn't take after a patient "
                        "re-click (30s watch) — continuing to poll", "WARN")
            except Exception:
                pass

            # 1b. (#755) No "Start research" yet — if Gemini is in a plan-FAIL
            # state, auto-click its Regenerate/Retry (bounded + stop-aware) so the
            # plan re-drafts. _try_inpage_retry_on_research_fail only clicks when
            # the page actually shows failure text AND finds a retry-labeled
            # button in the assistant area, so a healthy "still drafting" plan is
            # never touched. The 30s loop sleep below spaces successive attempts
            # so each re-draft has time to produce a plan (or a fresh failure).
            if (not start_clicked and _regen_count < _GEMINI_MAX_PLAN_REGEN
                    and not _controls.is_stop()
                    and (time.time() - _last_regen_at) > _GEMINI_REGEN_COOLDOWN_SEC):
                try:
                    _regened = await _try_inpage_retry_on_research_fail(
                        gemini_page, "gemini", "2D-plan", max_wait_s=4)
                except Exception:
                    _regened = False
                if _regened:
                    _regen_count += 1
                    _last_regen_at = time.time()
                    log(f"[2D] Gemini plan failed — auto-clicked Regenerate "
                        f"{_regen_count}/{_GEMINI_MAX_PLAN_REGEN}; re-drafting plan, "
                        f"will re-check for 'Start research'", "INFO")
                    try:
                        emit_event("agent_progress", phase=2, agent="gemini",
                                   status="generating", stage="planning",
                                   progress=(f"Gemini plan hit an error — retrying "
                                             f"({_regen_count}/{_GEMINI_MAX_PLAN_REGEN})…"))
                    except Exception:
                        pass
                elif not _logged_stall_diag and _elapsed > 90:
                    # No labeled Retry was clickable but we're stuck past 90s with
                    # no "Start research". Capture the assistant-area buttons ONCE
                    # (read-only) so a future E2E can pin the icon-only Regenerate
                    # selector for the silent-stall case. We do NOT blind-click —
                    # clicking an unidentified control risks a destructive misclick.
                    try:
                        _cands = await gemini_page.evaluate("""() => {
                            const scope = document.querySelector(
                                'message-content, model-response, .response-container, main') || document.body;
                            const out = [];
                            for (const b of scope.querySelectorAll('button, [role="button"]')) {
                                const r = b.getBoundingClientRect();
                                if (r.width < 8 || r.height < 8) continue;
                                out.push({
                                    aria: (b.getAttribute('aria-label') || '').slice(0, 40),
                                    title: (b.getAttribute('title') || '').slice(0, 40),
                                    cls: ((b.className && b.className.toString) ? b.className.toString() : '').slice(0, 60),
                                    svg: !!b.querySelector('svg'),
                                    txt: (b.textContent || '').trim().slice(0, 30),
                                });
                                if (out.length >= 12) break;
                            }
                            return JSON.stringify(out);
                        }""")
                        log(f"[2D] Gemini plan stall diag @ {_elapsed}s (no labeled "
                            f"Retry found, no 'Start research'): {_cands}", "WARN")
                    except Exception:
                        pass
                    _logged_stall_diag = True

            # 1c. (#755) Auto-regenerate exhausted but still no plan — surface it
            # ONCE so the eventual not-verified outcome reads as a known repeated
            # failure in the FE, not a silent stall (the user previously had to
            # retry by hand ~3×). We keep polling until the window/CUA fallback.
            if (not start_clicked and _regen_count >= _GEMINI_MAX_PLAN_REGEN
                    and not _regen_cap_emitted and not _controls.is_stop()):
                _regen_cap_emitted = True
                log(f"[2D] Gemini plan auto-regenerate exhausted ({_regen_count} tries) "
                    f"— still no 'Start research'; will keep polling then escalate", "WARN")
                try:
                    emit_event("agent_progress", phase=2, agent="gemini",
                               status="generating", stage="planning",
                               progress=(f"Gemini's plan keeps failing — retried "
                                         f"{_regen_count}× and still waiting…"))
                except Exception:
                    pass

            # 1d. (#921 incident-3) Raise the [Retry][Skip] card EARLY, the
            # moment the plan has clearly failed — either 3 error-regens are
            # exhausted, or no plan has appeared at all after _PLAN_ALERT_SEC
            # (the plain-chat/DR-dropped case: no error, no 'Start research',
            # just a stalled turn). NON-BLOCKING: the loop + CUA recovery below
            # keep trying to self-heal, and the recovery path retracts this card
            # if a plan appears. Fires ONCE (idempotent alert_id agent_gemini_error;
            # the terminal fail_agent after the CUA ladder reuses the same id).
            # #929 `not _streaming_recent`: a plan that is VISIBLY still
            # generating is healthy-slow, not failed — carding it was the
            # 2026-07-09 false alarm. `_gemini_plan_card_due` also ties the
            # timer arm to the loop's OWN patience, which is the 2026-08-17
            # false alarm: the card cannot precede the wait it describes.
            if _gemini_plan_card_due(
                    elapsed=_elapsed, wait_max_sec=_start_wait_max_sec,
                    alert_sec=_PLAN_ALERT_SEC, regen_capped=_regen_cap_emitted,
                    streaming_recent=_streaming_recent,
                    start_clicked=bool(start_clicked)):
                _raise_plan_alert("plan clearly failed")

            # 2. Emit a Gemini planning heartbeat every ~15s so the frontend
            # shows smooth live motion while Gemini drafts the plan (was 60s,
            # which read as frozen during the wait). No rotation — we do NOT
            # scrape ChatGPT/Claude here; they kept their first-wave state and
            # will refresh on the official round-robin.
            if time.time() - _last_plan_emit >= 15:
                try:
                    _gm = await scrape_progress_gemini(gemini_page) or {}
                    # #929: streaming clock — RAW scrape status only ('generating'
                    # = stop button / streaming attr / running animation, incl.
                    # the plan-ready-awaiting-Start state, which the clicker
                    # resolves within a tick). A failed scrape ('scrape_error')
                    # or idle/complete page does NOT feed the clock, so a dead
                    # plan still ages out on the original 300s budget.
                    if (_gm.get("status") or "") == "generating":
                        _last_stream_seen_at = time.time()
                    _gm_status = (_gm.get("status") or "generating")
                    if _gm_status in ("complete", "done"):
                        _gm_status = "generating"
                    # stage="planning" (2026-07-06 milestone stepper): the FE
                    # can't tell Gemini's plan-draft from research via counters
                    # — this explicit stage drives the Planning milestone.
                    emit_event("agent_progress", phase=2, agent="gemini",
                               status=_gm_status, stage="planning",
                               progress=_gm.get("progress") or "Gemini drafting research plan...",
                               sources=int(_gm.get("sources", 0) or 0),
                               source_urls=(_gm.get("source_urls", []) or [])[:_SOURCE_LIST_CAP],
                               partial_text_len=int(_gm.get("partial_text_len", 0) or 0),
                               steps=(_gm.get("steps") or [])[-3:],
                               plan=(_gm.get("plan") or "")[:500])
                    _last_plan_emit = time.time()
                except Exception:
                    pass
                # #953: background Claude question-card sweep. Claude's "1 of N"
                # clarifying-question card (options + Skip) can render while we
                # dwell here on Gemini — pre-fix it sat unanswered for the whole
                # 2D window (22 min on 2026-07-13) because only the round-robin
                # checked. JS-only (evaluate + click, no foreground switch, no
                # CUA) so the Gemini dwell is undisturbed. ~30s cadence.
                if time.time() - _last_claude_q_probe >= 30:
                    _last_claude_q_probe = time.time()
                    try:
                        _cl_page = (agents.get("Claude") or {}).get("page")
                        if _cl_page is not None and not _cl_page.is_closed():
                            _q_bg = await _claude_skip_question_cards(_cl_page, "Claude/2D-bg")
                            if _q_bg:
                                emit_event("agent_progress", phase=2, agent="claude",
                                           status="generating",
                                           progress=f"Claude asked {_q_bg} clarifying question(s) — "
                                                    "skipped them so the research starts.")
                    except Exception:
                        pass

            # #929: name the wait mode — past the base budget the loop only
            # keeps going while streaming evidence is fresh, and the log must
            # say so (a "320s / 300s" line read as a bug).
            if _elapsed >= _start_wait_max_sec:
                log(f"[2D] Plan still visibly streaming — extended wait ({_elapsed}s / "
                    f"hard cap {_stream_max_sec}s)")
            else:
                log(f"[2D] Still waiting for Gemini research plan... ({_elapsed}s / {_start_wait_max_sec}s)")
            # Tighter tick (was 30s) so a "Start research" button is clicked within
            # ~10s of appearing and the wait feels responsive, not stalled.
            await asyncio.sleep(10)

        # CUA recovery for "Start research" (#776 + #755). #755: skip on Stop —
        # agent_loop would just return status='stopped' and the round-robin is
        # itself stop-aware. The 10-min loop above exited without a click, which on
        # a plan-FAIL screen means Gemini showed "…something went wrong" with an
        # ICON-ONLY Regenerate/Retry control the in-page JS selector can't match
        # (only the CUA's vision can click it). Per user spec (2026-06-03): KEEP
        # retrying the plan via the CUA, wait ~2 min after each retry for the plan
        # to re-draft, and the instant a real "Start research" button renders,
        # click it via deterministic JS — then verify + hand back to the
        # round-robin. Bounded so a permanently-failing plan still escalates
        # honestly (verified_b=False below) instead of dwelling forever.
        # #953: `not _streaming_handoff` — a STREAMING Gemini is healthy (plan
        # drafting or auto-started research); pointing the CUA at it is what
        # produced the 2026-07-13 "spamming Start Research" (3 vision clicks on
        # the grayed button) + the false "couldn't start" card. The ladder is
        # for the truly-dead, non-streaming plan only.
        if (not _gemini_2d_skipped and not start_clicked and not _streaming_handoff
                and not _controls.is_stop()):
            _FALLBACK_MAX_REGEN = 3   # CUA-driven re-draft attempts (the in-loop #755 path already tried 3 via JS)
            log(f"[2D] No 'Start research' after {_start_wait_max_sec}s — CUA recovery: "
                f"retry the plan (≤{_FALLBACK_MAX_REGEN}×) until 'Start research' appears, then click it")
            # #905: reuse the hardened _click_start_js from the plan-wait loop
            # above — the recovery path previously redefined a `<button>`-only
            # variant, so the two finders could disagree about the same DOM.
            for _regen_attempt in range(_FALLBACK_MAX_REGEN):
                if _controls.is_stop():
                    break
                # #929: honor a user Skip between recovery attempts — same
                # finalize as the plan-wait loop (agent_skipped + tab close),
                # and never point the CUA at an agent the user dismissed.
                if "gemini" in _controls.skipped_agents:
                    log("[2D] User skipped Gemini during CUA recovery — finalizing skip", "INFO")
                    _controls.consume_skip_marker("gemini")
                    _gemini_2d_skipped = True
                    emit_event("agent_skipped", phase=2, agent="gemini", reason="user_skip")
                    await _close_skipped_agent_tab(browser, gemini_page, "gemini", "Gemini")
                    break
                # #953: re-probe streaming before poking the page — Gemini may
                # have (re)started generating since the wait loop's last scrape
                # (e.g. research auto-started late). A streaming page is healthy;
                # the CUA must never click at it (that's the spam + false card).
                try:
                    _gm_lad = await scrape_progress_gemini(gemini_page) or {}
                except Exception:
                    _gm_lad = {}
                if (_gm_lad.get("status") or "") == "generating":
                    _streaming_handoff = True
                    log("[2D] Gemini is streaming again mid-recovery — standing down the "
                        "CUA ladder and handing off to the round-robin", "INFO")
                    break
                # 1. The plan may already expose a Start-research button (a prior
                #    re-draft just succeeded, or it was simply slow) — click it.
                try:
                    await browser.switch_to_page(gemini_page)
                    _sr = await gemini_page.evaluate(_click_start_js)
                except Exception:
                    _sr = False
                if _sr:
                    start_clicked = True
                    log("[2D] CUA recovery: clicked 'Start research' via JS ✓")
                    # #929 (B4iii gap): this success path never retracted the
                    # early plan-stall card — a healthy researching Gemini kept
                    # a stale [Retry][Skip] card for the rest of the run.
                    _retract_plan_alert("CUA recovery")
                    await asyncio.sleep(5)
                    break
                # 2. No Start-research → the plan is in a FAIL state. CUA clicks the
                #    Regenerate/Retry control (or Start research if it IS there).
                #    Return text intentionally unused — #776 confirms via the DOM,
                #    never by parsing the CUA's narration.
                log(f"[2D] CUA recovery: plan not ready — CUA retrying the plan "
                    f"(attempt {_regen_attempt + 1}/{_FALLBACK_MAX_REGEN})")
                await browser.switch_to_page(gemini_page)

                async def _gemini_start_cua():
                    return await agent_loop(cua_client, browser,
                        PROMPT_GEMINI_START_RESEARCH,
                        "If an ENABLED (blue) 'Start research' button is visible, click it "
                        "ONCE. If it is grayed out/disabled or the page shows research "
                        "progress or a finished report, do NOT click — say 'research "
                        "already running'. Only on a failed plan ('something went wrong') "
                        "click Retry/Regenerate once. Do NOT type anything.",
                        model=CUA_MODEL, max_iterations=10, verbose=verbose)

                # #839 act tier: DUAL-target mission — click 'Start research' OR
                # the icon-only Regenerate/Retry the JS selector can't match.
                # Return text is unused in EVERY mode (#776 confirms via the
                # deterministic JS poll below), so an act success vs a CUA run
                # is indistinguishable downstream — start_clicked is set only by
                # _click_start_js. Non-blocking recovery, never the pipeline pause.
                await _shadow_observed_cua(
                    gemini_page, hotspot_id="gemini-start", phase=2, platform="gemini",
                    current_step="start_or_regenerate_plan",
                    context_hint="Gemini plan not ready — click an ENABLED (blue) 'Start "
                                 "research' button ONCE if present; if it is grayed/disabled "
                                 "or research is already running, do NOT click (say 'research "
                                 "already running'); else click the Retry/Regenerate control "
                                 "on the 'something went wrong' error once. NEVER type",
                    expected_outcome="the research plan starts or is re-drafted",
                    cua_coro_factory=_gemini_start_cua,
                    mission_prompt=PROMPT_GEMINI_START_RESEARCH,
                    act_timeout_s=120.0)
                try:
                    emit_event("agent_progress", phase=2, agent="gemini", status="generating",
                               stage="planning",
                               progress=(f"Gemini's plan didn't start — retrying "
                                         f"({_regen_attempt + 1}/{_FALLBACK_MAX_REGEN})…"))
                except Exception:
                    pass
                # 3. Wait ~2 min for the re-draft, polling for "Start research"
                #    every ~5s and clicking it the instant it renders.
                for _i in range(24):   # ~120s
                    # #929: a Skip mid-poll exits fast — the next outer-attempt
                    # check finalizes it (or the loop ends and the guard below
                    # stands down).
                    if _controls.is_stop() or "gemini" in _controls.skipped_agents:
                        break
                    try:
                        await browser.switch_to_page(gemini_page)
                        _sr2 = await gemini_page.evaluate(_click_start_js)
                    except Exception:
                        _sr2 = False
                    if _sr2:
                        start_clicked = True
                        log("[2D] CUA recovery: 'Start research' appeared after re-draft — clicked ✓")
                        # #929 (B4iii gap): same retraction as the other
                        # success paths — was missing here too.
                        #
                        # ⛔ 2026-08-17 — but NOT from here any more. The card it
                        # withdraws says "Gemini recovered and began its deep
                        # research", and a click that returned true is not that
                        # evidence: in the live run this retraction fired at
                        # 08:51:26 and the verify disagreed six seconds later, so
                        # the user's only actionable surface was taken away from a
                        # run that was already dead. The retraction now happens
                        # where the claim can be proven — the verified_b block
                        # below.
                        await asyncio.sleep(5)
                        break
                    await asyncio.sleep(5)
                if start_clicked:
                    break
            # #929: a Skip that landed during the FINAL attempt's poll loop
            # exits the for-loop without hitting the top-of-attempt finalize —
            # consume it here so the skip is never silently dropped.
            if (not _gemini_2d_skipped and not start_clicked
                    and "gemini" in _controls.skipped_agents):
                log("[2D] User skipped Gemini at the end of CUA recovery — finalizing skip", "INFO")
                _controls.consume_skip_marker("gemini")
                _gemini_2d_skipped = True
                emit_event("agent_skipped", phase=2, agent="gemini", reason="user_skip")
                await _close_skipped_agent_tab(browser, gemini_page, "gemini", "Gemini")
            if not start_clicked and not _gemini_2d_skipped and not _streaming_handoff:
                log(f"[2D] CUA recovery exhausted ({_FALLBACK_MAX_REGEN} attempts) — "
                    f"plan never produced a clickable 'Start research'", "WARN")
                # Surface the Retry/Skip alert NOW — don't make the user wait for
                # the wall-clock cap. Per spec: after the bounded plan retries fail
                # (or 'Start research' never appears), raise skip/retry. Retry runs
                # a HARD retry = fresh Gemini chat + re-submitted topic. fail_agent
                # dedups by alert_id, so a later wall-clock re-assert is harmless.
                # #953: one last streaming probe guards the card — a Gemini that
                # is actively generating is NOT failed, whatever the ladder saw
                # (the 2026-07-13 false "couldn't start" card fired on an agent
                # that was mid-research and finished 4 min later at 98k chars).
                _final_streaming = False
                try:
                    _gm_fin = await scrape_progress_gemini(gemini_page) or {}
                    _final_streaming = (_gm_fin.get("status") or "") == "generating"
                except Exception:
                    _final_streaming = False
                if _final_streaming:
                    _streaming_handoff = True
                    log("[2D] Final probe: Gemini is streaming — suppressing the "
                        "'couldn't start' card and handing off to the round-robin", "INFO")
                elif not _controls.is_stop():
                    fail_agent("gemini", *_GEMINI_CANT_START)  # #63: centralized copy

        # Verify Gemini is actually researching. #755: on Stop, skip the ~45s
        # DOM-verify retry churn — record not-verified and let the stop-aware
        # round-robin unwind cleanly. #776: ALSO skip verify when "Start research"
        # was never CONFIRMED-clicked — verify_gemini_generating green-lights on a
        # stop button / running CSS animation and CANNOT distinguish "drafting the
        # plan" from "running the research", so without a confirmed click it would
        # falsely stamp a not-yet-started run as researching (+ research_started_at).
        # No confirmed click ⇒ not running; the round-robin keeps the tab (it does
        # NOT drop a not-verified agent — see ~19298) and the wall-clock cap
        # surfaces an honest fail_agent if the plan never starts.
        if _gemini_2d_skipped:
            # #929: the skip was finalized in place (agent_skipped emitted,
            # tab closed) — Gemini must NOT be handed to the round-robin,
            # whose pollers would touch a dead page handle.
            log("[2D] Gemini skipped during the plan wait — tab closed, "
                "not handed to the round-robin", "INFO")
            verified_b = False
        elif _controls.is_stop():
            log("[2D] Stop requested — skipping Gemini verify", "INFO")
            verified_b = False
        elif _streaming_handoff:
            # #953: Gemini was still actively streaming past the hand-off point —
            # research almost certainly auto-started (2026-07-13 run: plan at
            # 95s, Start rendered pre-disabled, research ran unclicked to 98k
            # chars). Not CONFIRMED researching (no click took), so verified
            # stays False and the round-robin's detectors + late-Start watch
            # leg decide — but this is a healthy hand-off, not a failure.
            log("[2D] Gemini handed off while streaming — round-robin detectors "
                "decide (late 'Start research' is clicked by the watch leg)", "INFO")
            verified_b = False
            try:
                _retract_plan_alert("streaming hand-off")
                emit_event("agent_progress", phase=2, agent="gemini",
                           status="generating", stage="planning",
                           progress="Gemini is taking its time — monitoring in the "
                                    "background while the other agents are polled")
            except Exception:
                pass
        elif not start_clicked:
            log("[2D] 'Start research' never confirmed-clicked — not marking Gemini "
                "as researching (avoids a false 'running' on a stale/failed plan)", "WARN")
            verified_b = False
        else:
            # #905 (2026-07-06 user directive, superseding the same-day ≤30s
            # verify): after a CONFIRMED "Start research" click, the round-
            # robin must start IMMEDIATELY — cycle 1 opens the ChatGPT +
            # Claude source panels FIRST, then comes back to confirm Gemini.
            # So: one instant DOM probe here (usually already true — the
            # click was confirmed-taken via the re-click loop), and if it
            # hasn't flipped yet, the cycle-1 Gemini leg finishes the verify
            # (needs_start_verify below) seconds later.
            verified_b = False
            try:
                verified_b = bool(await verify_gemini_generating(gemini_page))
            except Exception:
                verified_b = False
            if not verified_b:
                log("[2D] Instant DOM verify didn't confirm — the cycle-1 Gemini "
                    "leg re-checks (click was confirmed; detectors decide)", "WARN")
        # Record when research actually started (after "Start research" click)
        # so the round-robin doesn't check for completion prematurely.
        # #929: a mid-2D skip never registers — the tab is already closed.
        if not _gemini_2d_skipped:
            agents["Gemini"] = {"page": gemini_page, "verified": verified_b, "url": gemini_page.url,
                                "research_started_at": time.time(),
                                "needs_start_verify": bool(start_clicked and not verified_b),
                                # #953: streaming hand-off — the round-robin's
                                # Gemini leg watches for a late 'Start research'
                                # (slow plan) and clicks it; a verified-running
                                # probe clears the watch (auto-started case).
                                #
                                # ⛔⛔ 2026-08-17 — AND THE CASE IT WAS MISSING,
                                # which cost a whole agent. `start_clicked and not
                                # verified_b` is the single most obvious state in
                                # which a 'Start research' button may still need
                                # pressing: we pressed it and could not confirm it
                                # took. Two live runs ended there — the click
                                # reported success, the verify disagreed, and
                                # because only the streaming path armed this
                                # watch, nobody ever pressed again. The round-robin
                                # then read `start_research_btn_visible
                                # (pre-research)` once a minute for NINETY MINUTES
                                # and auto-skipped, salvaging the plan instead of
                                # a research. Five earlier runs were fine for one
                                # reason: their click verified, so neither flag
                                # was ever set.
                                #
                                # ⭐ Nothing new is trusted here. The watch's own
                                # (a)/(b)/(c) ladder is already bounded,
                                # enabled-only so it cannot spam a grayed button,
                                # and took-checked on the following leg. This
                                # arms machinery that was already correct.
                                "gemini_watch_start": bool(
                                    _streaming_handoff
                                    or (start_clicked and not verified_b))}
        if verified_b:
            emit_event("agent_progress", phase=2, agent="gemini", status="generating",
                       stage="researching",
                       progress="Gemini Deep Research plan created and started")
            log("[2D] Gemini is researching ✓")
            # The one place the plan-stall card's claim ("Gemini recovered and
            # began its deep research") is actually true. Idempotent — a no-op
            # when an earlier path already retracted it.
            _retract_plan_alert("verified running")
            await inject_agent_observer(gemini_page, "gemini")
        elif _streaming_handoff:
            log("[2D] Gemini streaming hand-off — round-robin takes it from here")
        elif not _gemini_2d_skipped:
            log("[2D] Gemini may not be running", "WARN")

    # ── Verify all launched agents are running ──
    total = len(agents)
    verified_count = sum(1 for a in agents.values() if a["verified"])
    log(f"\n{'='*60}")
    log(f"Agents started. {verified_count}/{total} verified as running.")
    for name, a in agents.items():
        log(f"  {name:10s} {'✓ running' if a['verified'] else '✗ not verified'}  {a['url'][:60]}")
    log(f"{'='*60}")

    # Round-robin poll all agents — checks each agent every cycle instead of blocking per-agent
    if not agents:
        log("No agents to poll — all were disabled or skipped")
        return {}
    results = await poll_all_agents_round_robin(
        agents, browser, cua_client,
        max_wait_min=MAX_WAIT_DEEP, poll_interval=POLL_DEEP_RESEARCH, verbose=verbose)

    # ⭐⭐ THE SWEEP LIVES AT THE RETURN, and getting that placement wrong is this
    # guard's entire history. Round one put it at ONE writer
    # (`extract_and_record_agent`) and the 2026-08-05 run shipped 121KB about golden
    # retrievers through the two other paths that reach the same files. Round two moved
    # it to "the finalize block" — which widened the same mistake, because `run_phase2`
    # has THREE consumers and the other two each re-write `documents/<agent>.md` and
    # mirror it to Firestore from a `results` this function had handed back UNSWEPT:
    #   * the pause + extra-context resume path, and
    #   * the Retry at the Phase-3 "no documents" gate.
    # Adversarial review found both. There is exactly ONE return, so guarding it is the
    # only placement a future consumer cannot out-flank.
    #
    # `_p2_run_dir()` because this function is handed no `queue_dir` — the same resolver
    # the skip-extract guard uses; it returns None before a run is bound, which the
    # guard treats as ABSTAIN. The finalize-block call is deliberately KEPT as a belt
    # (it runs with the caller's own `queue_dir`), and text this sweep already blanked
    # is skipped there without a second log line.
    #
    # Wrapped: a broken guard must never lose a healthy run's results.
    try:
        _swept = apply_off_topic_sweep(results, _p2_run_dir())
        if _swept:
            log(f"[Phase 2] off-topic sweep rejected {_swept} — their text will not be "
                f"written to documents/, mirrored to Firestore, merged into "
                f"consolidated.md, or handed to NotebookLM", "ERROR")
    except Exception as _swe:
        log(f"[Phase 2] off-topic sweep errored ({_swe}) — results unchanged", "WARN")

    return results


# ── Phase 2 → Phase 3 handoff ────────────────────────────────────────────────

def _build_phase2_to_phase3_handoff(results: dict, queue_dir) -> None:
    """Populate _runtime.p2_links_for_p3 + _runtime.p2_md_files_for_p3 from
    P2 state (results + on-disk MDs). Idempotent.

    Called at end of P2 (the canonical population point) and as a no-op
    safety net at start of P3 (only does real work if _runtime was wiped
    on a process restart between P2 and P3 — i.e. resume-from-P3 case).

    P2 captures each agent's conversation URL as it reads the report. P3 just
    consumes this state and uploads to NotebookLM. No browser activity, no
    agent re-visits, no CUA in P3.
    """
    p3_links: dict[str, str] = {}
    p3_md_files: list = []
    for _name, _r in (results or {}).items():
        _md_name = _name.lower().replace(" ", "") + ".md"
        _md_path = Path(queue_dir) / "documents" / _md_name
        _has_md = _md_path.exists() and _md_path.stat().st_size > 100
        # The conversation URL captured at extraction time.
        #
        # ⛔ 2026-08-28 — it used to prefer a PUBLIC SHARE url stashed by P2's
        # inline extractor. That extractor is gone (stretch 6.6B): it cost 2.2
        # minutes and 21.7 CUA calls a run to produce a link nothing gated on,
        # and P5 now delivers our own durable snapshot pages instead. The
        # fallback that always sat behind it is now the whole answer, so this
        # handoff is unchanged in shape and one indirection shorter.
        _url = _r.get("url") or ""
        # ⛔ 2026-08-05 (review, f10) — a link is a SOURCE, so it is published only
        # when this agent's contribution survived. Two ways it can fail to:
        #
        #   * the off-topic sweep rejected it. Blanking `text` was believed to cover
        #     this handoff; it does not, because the url is read on its own line. The
        #     11:08 run logged `Links saved: {'ChatGPT': '…/c/6a72ce1e…'}` and shipped
        #     the previous evening's unrelated conversation to NotebookLM as a source.
        #   * it is a ChatGPT conversation that predates the run. Belt for the case
        #     the sweep cannot judge — a topic under the anchor floor, or text under
        #     the size floor — where nothing gets marked rejected but the tab is
        #     provably not ours. This one does not depend on the topic guard at all.
        #
        # ⚠ NOT gated on `text` being present. A share URL with a failed text
        # extraction is a legitimate, useful source: the conversation is this run's
        # and on topic, and NotebookLM can read it even when our scrape could not.
        if _url and _r.get("off_topic_rejected"):
            log(f"[Phase 2→3 handoff] dropping {_name}'s link — its output was "
                f"rejected as off-topic, so the conversation is not a source", "WARN")
            _url = ""
        # ⚠ Scoped by AGENT KEY, not by hostname. `_chatgpt_tab_is_foreign` reads an
        # id out of `/c/<hex>` and dates it; run any other platform's url through that
        # and a Claude or Gemini id whose first hex group happens to decode to a
        # plausible older timestamp would lose its link for nothing. And the scoping
        # is deliberately OURS (the agent we are iterating) rather than a
        # `"chatgpt.com" in _url` literal — a hostname literal in a gate is what took
        # Phase 3 down when NotebookLM's domain moved, four gates at once.
        if _url and normalize_agent_key(_name) == "chatgpt" and _chatgpt_tab_is_foreign(_url):
            log(f"[Phase 2→3 handoff] dropping {_name}'s link {_url!r} — that "
                f"conversation predates this run", "WARN")
            _url = ""
        if _url:
            p3_links[_name] = _url
        if _has_md:
            p3_md_files.append(_md_path)
    # Flow B: P1 + all P2 skipped means `results` is empty, so the loop
    # above adds no md files. Scan documents/ for any user-supplied source
    # files (md/txt/pdf/docx — anything except brief.md / derived MDs) so
    # P3 still has something to upload to NotebookLM.
    #
    # GATE (2026-04-30): only scan when the per-agent loop above added
    # NOTHING. With agents present, p3_md_files already has every MD that
    # belongs in NotebookLM; running the scan anyway picks up derived
    # artifacts (consolidated.md is the offender — it's a P2 byproduct of
    # claude+gemini concatenation, used for the Documents page only) and
    # uploads them as duplicate sources. The Flow B scenario the scan was
    # written for has p3_md_files empty by definition (no agents ran).
    _DERIVED_STEMS = {"brief", "consolidated"}
    if not p3_md_files:
        _docs_dir = Path(queue_dir) / "documents"
        if _docs_dir.exists():
            _already = {p.name for p in p3_md_files}
            for _f in sorted(_docs_dir.iterdir()):
                if not _f.is_file():
                    continue
                # 2026-05-11: lowercase the stem to match _scan_p3_docs
                # below — defensive in case a future write path drops a
                # Capitalised filename onto disk (current code always
                # writes lowercase, but the file is the source of truth
                # for what NLM uploads so this guard is cheap).
                if _f.stem.lower() in _DERIVED_STEMS:
                    continue
                if _f.suffix.lower() not in (".md", ".txt", ".pdf", ".docx"):
                    continue
                if _f.name in _already:
                    continue
                if _f.stat().st_size < 32:
                    continue   # Empty / placeholder file — skip
                p3_md_files.append(_f)
    _runtime.p2_links_for_p3 = p3_links
    _runtime.p2_md_files_for_p3 = p3_md_files
    log(f"[Phase 2→3 handoff] {len(p3_links)} links, {len(p3_md_files)} files ready for NotebookLM")


# ── Phase 3: NotebookLM Upload ───────────────────────────────────────────────
#
# 2026-07-11 DOM-first upload rework (FIFA run incident): the per-file CUA
# vision tasks were the ONLY upload path, and the whole chain was fail-open —
# an Anthropic API 500 killed the gemini.md task before the file dialog ever
# opened, the call sites discarded the returned error dict, clear_upload_file
# wiped the still-queued file, and the red-state-only source verify passed a
# 2/3 notebook as "all sources OK". The primitives below drive NotebookLM's
# own DOM (create notebook, hidden <input type=file> multi-upload, source-row
# census, rename) so the happy path needs NO vision at all; the CUA missions
# remain as the fallback tier, now with per-file DOM verification.

_NLM_CLICK_JS = """(patterns) => {
    const MARK = \"""" + _SR_CLICK_MARK + """\";""" + _NLM_ONSCREEN_JS + """
    // Click the first button-ish element matching a pattern. PATTERN ORDER IS
    // AUTHORITATIVE (review r2): the pattern loop is outermost, so a specific
    // pattern ('add source') is exhausted page-wide before a generic one
    // ('upload') is tried — pre-fix, DOM order won and a stray generic match
    // (e.g. a Studio '+ Add note' button whose mat-icon ligature 'add' leads
    // its textContent) could shadow the real control. Within a pattern,
    // dialog-scoped candidates win over page-wide ones. aria-label is
    // matched first; textContent is normalized to strip a leading icon
    // ligature (doubled token or snake_case icon name).
    const scopes = [];
    for (const d of document.querySelectorAll(
            '[role="dialog"], mat-dialog-container, [class*="dialog"]')) {
        const r = d.getBoundingClientRect();
        if (r.width > 200 && r.height > 100) scopes.push(d);
    }
    scopes.push(document);
    const norm = (el) => {
        const aria = (el.getAttribute('aria-label') || '').replace(/\\s+/g, ' ').trim();
        let txt = (el.textContent || '').replace(/\\s+/g, ' ').trim();
        txt = txt.replace(/^([\\w]+)\\s+(?=\\1\\b)/i, '');   // 'add Add note' → 'Add note'
        txt = txt.replace(/^[a-z]+(?:_[a-z]+)+\\s+/, '');    // 'upload_file Upload' → 'Upload'
        return { aria, txt };
    };
    for (const p of patterns) {
        const re = new RegExp(p, 'i');
        for (const scope of scopes) {
            for (const el of scope.querySelectorAll(
                    'button, [role="button"], [class*="create-new"], ' +
                    'create-new-button, label[for], [class*="dropzone" i]')) {
                // ⭐ 2026-08-05 — CENTRE ON SCREEN, and not disabled. An 8x8 rect
                // was the whole gate, and this very file added `onScreen` because
                // "NotebookLM parks button[aria-label='Chat options'] at x=-36
                // with a full-size rect and a live offsetParent". So a control
                // that is off-canvas, or disabled, could win the match and be
                // "clicked" with no effect — which is what a 0/3 upload with
                // three identical warnings looks like from the outside.
                if (!onScreen(el)) continue;
                if (el.disabled) continue;
                const ad = (el.getAttribute('aria-disabled') || '').toLowerCase();
                if (ad === 'true') continue;
                const { aria, txt } = norm(el);
                if (re.test(aria) || re.test(txt)) {
                    // ⭐⭐ 2026-08-06 — PREFER THE LEAF. `textContent` on a
                    // container is the concatenation of everything inside it, so
                    // the Add-sources DROPZONE matches /upload file/i through its
                    // own children and — because `querySelectorAll` returns
                    // DOCUMENT order, and an ancestor always precedes its
                    // descendants — wins before the "Upload files" chip is ever
                    // examined. The live proof is the label the run logged,
                    // exactly 80 characters of concatenated child text:
                    //   'or drop your filespdf, images, docs, audio, and
                    //    moreuploadUpload fileslinkvideo_'
                    // 3 of 3 uploads, in two independent runs.
                    let best = el;
                    try {
                        for (const inner of el.querySelectorAll(
                                'button, [role="button"], label[for]')) {
                            if (!onScreen(inner) || inner.disabled) continue;
                            const n2 = norm(inner);
                            if (re.test(n2.aria) || re.test(n2.txt)) { best = inner; break; }
                        }
                    } catch (e) {}
                    const b = norm(best);
                    // ⭐ MARK, DO NOT CLICK. A synthetic `el.click()` inside
                    // page.evaluate carries no USER ACTIVATION, and a native file
                    // chooser is gated on exactly that — so this could never have
                    // opened one however well it aimed. The rest of this codebase
                    // presses through `_sr_real_click`; the NotebookLM tier was
                    // the only DOM path that never adopted it.
                    best.setAttribute(MARK, 'nlm-click');
                    return { label: (b.aria || b.txt).slice(0, 80),
                             tag: (best.tagName || '') };
                }
            }
        }
    }
    return null;
}"""


# How long Playwright's trusted press gets on a NotebookLM control before the
# dispatched-pointer fallback takes over.
#
# ⭐ 2026-08-06 — A NEW TIER MUST SIT ABOVE THE OLD ONE, NOT REPLACE IT. This path
# used a synthetic in-page click, which worked for the notebook-create control and
# could never work for a file chooser. Swapping it wholesale for the trusted press
# bought the chooser and cost two 4-second stalls on controls the old way handled:
#   [21:36:18] real click on the marked element failed (TimeoutError) - falling back
#   [21:36:24] real click on the marked element failed (TimeoutError) - falling back
# Same outcome, eight seconds slower, and a new warning in a log we read for signal.
# So the press stays first — it is the only rung that can open a chooser — but it
# gives up fast, which turns a replacement back into a ladder.
_NLM_PRESS_TIMEOUT_MS = 1200


async def _nlm_click_first(page, patterns, *, expect_chooser=False):
    """Press the first NotebookLM control matching any regex pattern.

    Returns the matched label text ('' = nothing matched). Best-effort.

    2026-08-06: the JS MARKS and Playwright PRESSES (`_sr_real_click`) instead of
    calling `el.click()` inside the page. Two independent reasons, either
    sufficient on its own: a synthetic click carries no user activation, so it
    can never open a native file chooser; and it does not scroll, does not wait
    for actionability, and is not a trusted event sequence.

    `expect_chooser=True` arms Playwright's file-chooser wait AROUND the press,
    which is what turns "the chooser never opened" from an inference into a
    fact — and gives the caller the chooser to set files on. The label comes
    back with a "|chooser" suffix when one actually opened.
    """
    try:
        picked = await page.evaluate(_NLM_CLICK_JS, list(patterns))
    except Exception:
        return ""
    if not isinstance(picked, dict) or not picked.get("label"):
        return ""
    label = str(picked.get("label") or "")
    try:
        if expect_chooser:
            try:
                async with page.expect_file_chooser(timeout=6000):
                    await _sr_real_click(page, "nlm-click", tag="[NotebookLM]",
                                         timeout_ms=_NLM_PRESS_TIMEOUT_MS)
                return f"{label}|chooser"
            except Exception:
                return label
        await _sr_real_click(page, "nlm-click", tag="[NotebookLM]",
                             timeout_ms=_NLM_PRESS_TIMEOUT_MS)
    except Exception:
        pass
    return label


# ── The audio card's ⋮ menu — scoped, never document-wide ──────────────
#
# ⛔ THE BUG THIS EXISTS TO KILL: the audio-share step opened a menu with a
# document-wide `button[aria-label*="More"]` query and took the first visible
# match. EVERY source row exposes exactly that button (chatgpt.md at y364,
# claude.md at y406, gemini.md at y458), and the audio card's own kebab sits
# BELOW them at y398 — so the first match is always a source row, and the menu
# that opened was the one whose destructive item is "Remove source". The audio
# kebab and a source kebab carry an IDENTICAL aria-label and near-identical x, so
# no attribute and no coordinate can tell them apart. The container can:
#     studio-panel → artifact-library → artifact-library-item → button[More]
#
# Scoping is stated as SCOPE IN, never EXCLUDE BY NAME. An exclusion list keyed
# on source-row labels reopens the hole the day a source is named differently;
# a container scope does not care what the rows are called.
#
# The first scope is the same population `_count_nlm_audio_cards` and
# `_pick_nlm_audio_card` already count — a visible <artifact-library-item>
# carrying the `audio_magic_eraser` ligature — so all three agree on what an
# audio card is. WHICH audio card does not matter here: NotebookLM emits one
# `/notebook/{id}` link for the notebook however you reach the share dialog, so
# a duplicate changes nothing about the URL, only about whose menu opens.
_NLM_AUDIO_MENU_SCOPES = [
    {"name": "audio-card", "sel": "artifact-library-item", "needs": "audio_magic_eraser"},
    {"name": "artifact-item", "sel": "studio-panel artifact-library artifact-library-item", "needs": ""},
    {"name": "studio-panel", "sel": "studio-panel", "needs": ""},
]

# Ordered hooks within the scope. Exact label first so a rename to "More
# options" degrades to the substring rung instead of silently matching nothing.
_NLM_AUDIO_TRIGGER_SELS = [
    'button[aria-label="More"]',
    'button[aria-label*="more" i]',
    'button[aria-haspopup="menu"]',
]

# ONE definition of "which button is the audio ⋮", shared by the opener and the
# verifier. They MUST agree: the verifier's whole job is to ask whether the
# button the opener clicked is now expanded, and if the two could resolve
# differently that sentence would be about two different buttons.
#
# ⚠ The CONTAINER is deliberately not gated on visibility. Its job is
# containment, and a Studio panel taller than the viewport has its centre below
# the fold — gating it would reject the very page this is meant to work on. A
# collapsed or hidden panel needs no special case either: its buttons inherit
# zero rects and fail the gate that matters, which is the one on the button
# being clicked.
_NLM_FIND_AUDIO_TRIGGER_JS = r"""
    const findTrigger = (P) => {
        for (const g of (P.scopes || [])) {
            for (const scope of document.querySelectorAll(g.sel)) {
                if (g.needs) {
                    const st = (scope.innerText || scope.textContent || '');
                    if (st.indexOf(g.needs) === -1) continue;
                }
                for (const sel of (P.triggers || [])) {
                    for (const btn of scope.querySelectorAll(sel)) {
                        if (!onScreen(btn)) continue;
                        return { btn: btn, via: g.name, hook: sel };
                    }
                }
            }
        }
        return null;
    };
"""

_NLM_OPEN_AUDIO_MENU_JS = (r"""(P) => {"""
                           + _NLM_ONSCREEN_JS + _NLM_FIND_AUDIO_TRIGGER_JS + r"""
    const hit = findTrigger(P);
    if (!hit) return { opened: false, via: '', reason: 'no_scoped_trigger' };
    // Read BEFORE the click so the answer describes the button we chose, not
    // whatever the click re-rendered. The aria-label cannot carry this: a
    // source row's kebab has the identical one, which is the whole reason the
    // old query could not tell it had opened the wrong menu.
    const inCard = !!hit.btn.closest('artifact-library-item');
    const inStudio = !!hit.btn.closest('studio-panel');
    try { hit.btn.click(); }
    catch (e) { return { opened: false, via: hit.via, reason: 'click_threw' }; }
    return { opened: true, via: hit.via, hook: hit.hook,
             in_audio_card: inCard, in_studio: inStudio,
             label: (hit.btn.getAttribute('aria-label') || '').slice(0, 40) };
}""")

# Positive proof that the trigger WE meant is the one that opened.
#
# ⚠ A COUNT IS NOT PROOF. "Something inside the Studio panel is expanded" is
# also true when a section header in that panel was already open before we
# touched anything — so a count would verify a click that did nothing. The
# question has to be asked of the button itself, which is why the trigger is
# re-resolved here through the shared finder rather than counted. The counts are
# still returned, for the log: `outside` is what the old document-wide query was
# always hitting, and seeing it non-zero names the failure.
_NLM_AUDIO_MENU_VERIFY_JS = (r"""(P) => {"""
                             + _NLM_ONSCREEN_JS + _NLM_FIND_AUDIO_TRIGGER_JS + r"""
    const scopeSel = (P.scopes || []).map(g => g.sel).join(', ');
    let inScope = 0, outside = 0;
    for (const b of document.querySelectorAll('[aria-expanded="true"]')) {
        if (scopeSel && b.closest(scopeSel)) inScope++; else outside++;
    }
    const hit = findTrigger(P);
    return { in_scope: inScope, outside: outside,
             trigger_found: !!hit,
             trigger_expanded: !!hit && hit.btn.getAttribute('aria-expanded') === 'true' };
}""")

# Rows of an open Material menu, and the panels they live in.
_NLM_MENU_PANEL_SCOPES = [
    '[role="menu"]', '.mat-mdc-menu-panel', '.mat-menu-panel', '.cdk-overlay-pane',
]
_NLM_MENU_ROW_SEL = '[role="menuitem"], [role="menuitemradio"], [role="option"], button, li'

# ⛔ Rows that must NEVER be clicked by a menu pick, whatever was asked for.
# NotebookLM is detect-and-fail_phase only — the pipeline does not delete a card,
# a source, or a notebook, ever. `Delete` sits two rows below `Download` in the
# audio menu, so an off-by-two is not a failed download, it is a destroyed one.
_NLM_MENU_DENY = ("delete", "remove", "trash", "discard")

_NLM_MENU_PICK_JS = (r"""(P) => {""" + _NLM_ONSCREEN_JS + _NLM_LABEL_JS + r"""
    const want = (P.want || []).map(s => String(s).toLowerCase());
    const deny = (P.deny || []).map(s => String(s).toLowerCase());
    const denied = (t) => deny.some(d => new RegExp('\\b' + d + '\\b', 'i').test(t));
    let rows = [], via = '';
    for (const sc of (P.scopes || [])) {
        for (const panel of document.querySelectorAll(sc)) {
            if (!onScreen(panel)) continue;
            for (const el of panel.querySelectorAll(P.rowSel)) {
                if (!onScreen(el)) continue;
                const t = nlmLabel(el).toLowerCase();
                if (!t) continue;
                rows.push({ el: el, t: t });
            }
            if (rows.length) { via = sc; break; }
        }
        if (rows.length) break;
    }
    if (!rows.length) return { clicked: false, reason: 'no_menu_rows' };
    const blocked = rows.filter(r => denied(r.t)).map(r => r.t.slice(0, 40));
    const safe = rows.filter(r => !denied(r.t));
    // Identity, never position: exact label first, then a prefix — a bare
    // substring would let "Delete this share" answer a request for "share".
    let hit = safe.filter(r => want.indexOf(r.t) !== -1)[0];
    if (!hit) hit = safe.filter(r => want.some(w => r.t.indexOf(w) === 0))[0];
    if (!hit) return { clicked: false, reason: 'no_match', via: via, blocked: blocked,
                       rows: rows.map(r => r.t.slice(0, 40)) };
    try { hit.el.click(); } catch (e) { return { clicked: false, reason: 'click_threw' }; }
    return { clicked: true, label: hit.t.slice(0, 60), via: via, blocked: blocked };
}""")


async def _nlm_open_audio_menu(page, label="Audio") -> dict:
    """Open the AUDIO card's ⋮ menu — and prove it was that one.

    Returns {opened, verified, via, hook, reason, outside}. `verified` is the
    only field a caller should act on: `opened` alone means a click landed, which
    is precisely the claim the old document-wide query could make while having
    opened a source row's menu.
    """
    try:
        res = await page.evaluate(_NLM_OPEN_AUDIO_MENU_JS,
                                  {"scopes": _NLM_AUDIO_MENU_SCOPES,
                                   "triggers": _NLM_AUDIO_TRIGGER_SELS}) or {}
    except Exception as _e:
        return {"opened": False, "verified": False, "via": "",
                "reason": f"evaluate_failed:{type(_e).__name__}", "outside": 0}
    if not res.get("opened"):
        return {**res, "opened": False, "verified": False, "outside": 0}
    # POLL the verify rather than looking once after a fixed second. The verify
    # itself is right — it re-resolves the trigger and asks THAT button — but a
    # menu that mounts a moment late failed it, and the caller reads a failed
    # verify as "a menu opened somewhere else", which is a different and more
    # alarming thing than "not yet". Same fault the ChatGPT menus were fixed for.
    chk = {}
    for _try in range(5):
        if _try:
            await asyncio.sleep(0.25)
        try:
            chk = await page.evaluate(_NLM_AUDIO_MENU_VERIFY_JS,
                                      {"scopes": _NLM_AUDIO_MENU_SCOPES,
                                       "triggers": _NLM_AUDIO_TRIGGER_SELS}) or {}
        except Exception as _e:
            chk = {}
            log(f"[{label}] audio ⋮ open-verify skipped: {_e}", "DEBUG")
            break
        if chk.get("trigger_expanded"):
            break
    verified = bool(chk.get("trigger_expanded"))
    _dom_note("notebooklm.open_audio_menu", "verified" if verified else "missed",
              phase=3, via=str(res.get("via") or ""),
              detail=("" if verified else
                      f"trigger_found={chk.get('trigger_found')} "
                      f"expanded_outside_scope={chk.get('outside')} "
                      f"hook={res.get('hook')!r}"))
    return {**res, "verified": verified, "outside": int(chk.get("outside", 0) or 0),
            "in_scope": int(chk.get("in_scope", 0) or 0)}


async def _nlm_menu_pick(page, want, deny=_NLM_MENU_DENY) -> dict:
    """Click one row of an open NotebookLM menu, by label, never by index."""
    try:
        return await page.evaluate(_NLM_MENU_PICK_JS,
                                   {"scopes": _NLM_MENU_PANEL_SCOPES,
                                    "rowSel": _NLM_MENU_ROW_SEL,
                                    "want": list(want),
                                    "deny": list(deny)}) or {}
    except Exception as _e:
        return {"clicked": False, "reason": f"evaluate_failed:{type(_e).__name__}"}


async def _nlm_close_dialogs(page, label="NotebookLM"):
    """Best-effort close of any open NotebookLM modal (the FIFA source verify
    ran BEHIND a leftover Add-sources dialog). Close-button first, Escape
    fallback; silent no-op when nothing is open."""
    try:
        closed = await page.evaluate("""() => {
            let n = 0;
            for (const d of document.querySelectorAll(
                    '[role="dialog"], mat-dialog-container')) {
                const r = d.getBoundingClientRect();
                if (r.width < 200 || r.height < 100) continue;
                const btn = d.querySelector(
                    'button[aria-label*="lose" i], button[aria-label*="ancel" i], ' +
                    '[class*="close"] button, button [class*="close"]');
                if (btn) { (btn.closest('button') || btn).click(); n++; }
            }
            return n;
        }""")
        if closed:
            log(f"[{label}] closed {closed} leftover dialog(s) via DOM")
            await asyncio.sleep(1)
        else:
            await page.keyboard.press("Escape")
            await asyncio.sleep(0.5)
    except Exception:
        pass


async def _nlm_visible_source_names(page, expected_names):
    """DOM census of the Sources panel against the expected upload manifest.
    Returns (present: set[str], row_count: int). row_count = -1 when no
    structured source rows matched and the fallback body-text scan was used.

    Matching: exact filename anywhere in the harvested text; a stem match
    (name minus extension — NotebookLM sometimes titles the source without
    it) is accepted only inside structured rows, never against body text
    (report prose can legitimately contain a bare agent name like 'gemini')."""
    try:
        res = await page.evaluate("""(expected) => {
            const rowSel = 'source-item, [class*="source-item" i], ' +
                '[class*="single-source" i], [class*="source-title" i], ' +
                'mat-list-item, [role="listitem"]';
            const rows = [];
            for (const el of document.querySelectorAll(rowSel)) {
                const t = (el.innerText || '').replace(/\\s+/g, ' ').trim();
                if (t && t.length < 300) rows.push(t);
            }
            const hay = rows.length ? rows.join('\\n') : (document.body?.innerText || '');
            const present = [];
            for (const name of expected) {
                let hit = hay.includes(name);
                if (!hit && rows.length) {
                    const stem = name.replace(/\\.[a-z0-9]+$/i, '');
                    hit = rows.some(t => t.includes(stem));
                }
                if (hit) present.push(name);
            }
            return { present, rowCount: rows.length ? rows.length : -1 };
        }""", list(expected_names))
        return set(res.get("present") or []), int(res.get("rowCount") or -1)
    except Exception as e:
        log(f"[NotebookLM] source census failed: {e}", "DEBUG")
        return set(), -1


async def _nlm_census_settled(page, expected_names, attempts=4, interval=3.0):
    """Census with settle-polling (review r2): NotebookLM ingests sources
    ASYNC, so a single census taken seconds after a submission can miss a
    row that renders moments later — which used to trigger duplicate re-adds
    and, at the final gate, a spurious 'upload failed' Retry/Skip card for
    an upload that actually succeeded. Polls until every expected name is
    visible or attempts exhaust. Returns (present, row_count) of the LAST
    census."""
    present: set = set()
    row_count = -1
    for i in range(max(1, attempts)):
        present, row_count = await _nlm_visible_source_names(page, expected_names)
        if len(present) == len(list(expected_names)):
            break
        if i < attempts - 1:
            await asyncio.sleep(interval)
    return present, row_count


async def _nlm_dom_add_files(browser, page, paths, label="NotebookLM"):
    """Add files to the CURRENT notebook via NotebookLM's own DOM. Opens the
    Add-sources dialog if needed, then feeds every path in ONE go through the
    hidden <input type=file> (multi-select). Falls back to the armed-queue
    file chooser (one click per file) when no input is reachable. Returns
    True when a submission mechanism fired (ingestion verified by caller)."""
    paths = [str(p) for p in paths]
    try:
        # The Add-sources dialog auto-opens on a fresh notebook; otherwise
        # open it ("Add source" / "+" in the sources panel).
        inp = None
        for attempt in range(3):
            try:
                inp = await page.query_selector('input[type="file"]')
            except Exception:
                inp = None
            if inp:
                break
            # (review r2) no bare '^add' pattern — mat-icon ligatures make
            # every '+' button's textContent start with 'add', and a stray
            # match creates notes / opens the wrong dialog.
            clicked = await _nlm_click_first(page, (
                r"^add source", r"\badd sources?\b", r"upload sources?"))
            if attempt and not clicked:
                break
            await asyncio.sleep(2)
        if inp:
            try:
                await inp.set_input_files(paths)
            except Exception:
                # Non-multiple input rejects a list — feed one at a time,
                # re-querying between files (the dialog may re-render).
                for p in paths:
                    _inp = await page.query_selector('input[type="file"]')
                    if _inp is None:
                        await _nlm_click_first(page, (
                            r"^add source", r"\badd sources?\b", r"upload sources?"))
                        await asyncio.sleep(2)
                        _inp = await page.query_selector('input[type="file"]')
                    if _inp is None:
                        return False
                    await _inp.set_input_files([p])
                    await asyncio.sleep(2)
            log(f"[{label}] DOM upload: set {len(paths)} file(s) on hidden "
                f"input[type=file] — {[Path(p).name for p in paths]}")
            await asyncio.sleep(2)
            return True
        # Chooser fallback: the global filechooser handler answers one dialog
        # per armed file, so click the Upload control once per path.
        fired_any = False
        for p in paths:
            browser.set_upload_file(p)
            # ⭐ 2026-08-06 — RE-OPEN THE PICKER BETWEEN FILES. Setting a file on
            # the revealed input CLOSES the Add-sources dialog, so the next
            # iteration found no Upload control and the loop broke: the 21:00 run
            # got gemini.md through and abandoned the other two to the CUA in the
            # same second. The dialog is cheap to re-open and a no-op when it is
            # already up.
            if fired_any:
                try:
                    await _nlm_click_first(page, (
                        r"^add source", r"\badd sources?\b", r"upload sources?"))
                    await asyncio.sleep(1.5)
                except Exception:
                    pass
            # 2026-08-06: arm Playwright's chooser wait AROUND the press. The
            # global handler below can only answer a chooser that opened; this is
            # what makes "it opened" an observation rather than an inference, and
            # a synthetic in-page click could never have produced one at all.
            clicked = await _nlm_click_first(page, (
                r"upload file", r"choose file", r"select file", r"\bbrowse\b",
                r"\bupload\b"), expect_chooser=True)
            if clicked.endswith("|chooser"):
                clicked = clicked[: -len("|chooser")]
                log(f"[{label}] DOM upload: file chooser opened from "
                    f"{clicked!r} — the global handler is answering it")
            if not clicked:
                browser.clear_upload_file()
                log(f"[{label}] DOM upload: no Upload control found for "
                    f"{Path(p).name} — leaving it to the CUA fallback", "WARN")
                break
            # ⭐ 2026-08-05 — RE-QUERY THE HIDDEN INPUT FIRST. The click we just
            # made is the most likely thing to have opened the Add-sources dialog
            # that CONTAINS `input[type="file"]`; the loop below instead waited
            # ten seconds for a chooser that was never going to appear, three
            # times in a row (prod: 0/3, everything fell to the CUA fallback).
            # Setting files directly on the input is both faster and more reliable
            # than intercepting a dialog — it is why the primary path above exists
            # — and this branch already knows the idiom from the retry loop there.
            _late_inp = await page.query_selector('input[type="file"]')
            if _late_inp is not None:
                try:
                    await _late_inp.set_input_files([p])
                    await asyncio.sleep(2)
                    log(f"[{label}] DOM upload: the Upload click revealed the hidden "
                        f"input — set {Path(p).name} on it directly")
                    fired_any = True
                    browser.clear_upload_file()
                    continue
                except Exception as _se:
                    log(f"[{label}] DOM upload: late input rejected "
                        f"{Path(p).name} ({_se}) — waiting for a chooser instead",
                        "DEBUG")
            # Interception empties the one-entry queue; wait briefly for it.
            for _ in range(10):
                await asyncio.sleep(1)
                if not getattr(browser, "_upload_queue", None):
                    fired_any = True
                    break
            else:
                # ⚠ Name the CONTROL, not the file. The filename is the one thing
                # we already knew; the label is the whole diagnosis. Three
                # identical warnings in the prod log could not distinguish "we
                # pressed the right control and Chrome refused" from "we pressed a
                # heading" — and since this branch does not break, the same
                # control was pressed three times over 30 seconds with no way to
                # tell which.
                log(f"[{label}] DOM upload: chooser never opened for "
                    f"{Path(p).name} after pressing {clicked!r}", "WARN")
            browser.clear_upload_file()
        return fired_any
    except Exception as e:
        log(f"[{label}] DOM upload attempt failed: {e}", "WARN")
        try:
            browser.clear_upload_file()
        except Exception:
            pass
        return False


async def _nlm_dom_upload_sources(browser, page, md_files, label="NotebookLM"):
    """DOM-first NotebookLM upload: create a notebook if we're on the home
    page, submit ALL md files, then census the Sources panel until every
    expected filename is visible (ingestion is async). Returns the set of
    DOM-confirmed uploaded names — caller hands anything missing to the CUA
    fallback. Never raises."""
    expected = [p.name for p in md_files]
    try:
        url = ""
        try:
            url = page.url or ""
        except Exception:
            pass
        if "/notebook/" not in url:
            clicked = await _nlm_click_first(page, (
                r"create new notebook", r"new notebook", r"create new", r"^create\b"))
            if not clicked:
                log(f"[{label}] DOM-first: create-notebook control not found — "
                    f"falling back to CUA", "WARN")
                return set()
            log(f"[{label}] DOM-first: clicked create ('{clicked}')")
            for _ in range(15):
                await asyncio.sleep(1)
                try:
                    if "/notebook/" in (page.url or ""):
                        break
                except Exception:
                    pass
            # (review r2) post-wait guard: never run the add/chooser dance
            # against the HOME page — a slow create would waste ~15s of
            # misclicks and could false-match home-page cards in the census.
            try:
                if "/notebook/" not in (page.url or ""):
                    log(f"[{label}] DOM-first: create never reached a "
                        f"/notebook/ URL — falling back to CUA", "WARN")
                    return set()
            except Exception:
                return set()
        if not await _nlm_dom_add_files(browser, page, md_files, label=label):
            return set()
        # Census until every name shows up (ingestion is async; rows usually
        # appear within seconds, processing continues after).
        present: set = set()
        for _ in range(30):
            await asyncio.sleep(3)
            present, row_count = await _nlm_visible_source_names(page, expected)
            if len(present) == len(expected):
                break
        log(f"[{label}] DOM-first upload census: {sorted(present)} of "
            f"{expected} visible")
        # (review r2) close dialogs unconditionally — a leftover Add-sources
        # modal otherwise greets the CUA fallback (and the FIFA source verify
        # ran behind exactly such a modal).
        await _nlm_close_dialogs(page, label=label)
        return present
    except Exception as e:
        log(f"[{label}] DOM-first upload failed ({e}) — falling back to CUA", "WARN")
        return set()


async def _nlm_dom_rename(page, title, label="NotebookLM"):
    """DOM-first notebook rename. NotebookLM's title field ignores Ctrl+A
    (FIFA run: typed text APPENDED, leaving 'FIFA World Cup Evolution And
    EconomicsThe FIFA W' — the CUA burned 8/8 iterations failing to clear
    it). Set the input value natively + fire Angular-visible events instead.
    Returns True when the title verifiably matches afterwards."""
    try:
        ok = await page.evaluate("""(title) => {
            const findInput = () => {
                for (const el of document.querySelectorAll(
                        'input[aria-label*="title" i], input[class*="title" i], ' +
                        '[class*="notebook-title" i] input, [class*="project-title" i] input')) {
                    const r = el.getBoundingClientRect();
                    if (r.width > 60 && r.top < 120) return el;
                }
                return null;
            };
            let inp = findInput();
            if (!inp) {
                // The field may mount only after clicking the header title.
                for (const el of document.querySelectorAll(
                        '[class*="notebook-title" i], [class*="project-title" i], ' +
                        'h1, header [class*="title" i]')) {
                    const r = el.getBoundingClientRect();
                    if (r.top < 120 && r.width > 60) { el.click(); break; }
                }
                inp = findInput();
            }
            if (!inp) return false;
            const setter = Object.getOwnPropertyDescriptor(
                window.HTMLInputElement.prototype, 'value').set;
            setter.call(inp, title);
            inp.dispatchEvent(new Event('input', { bubbles: true }));
            inp.dispatchEvent(new Event('change', { bubbles: true }));
            inp.blur();
            return inp.value === title;
        }""", title)
        if not ok:
            return False
        # Read-back from a FRESH query after a settle (review r2): the
        # immediate `inp.value === title` only proves the native setter ran —
        # if Angular ignores synthetic events and reverts on its next change
        # detection, returning True here would silently skip the CUA
        # fallback in exactly the failure mode this helper was built for.
        await asyncio.sleep(1.5)
        committed = await page.evaluate("""(title) => {
            for (const el of document.querySelectorAll(
                    'input[aria-label*="title" i], input[class*="title" i], ' +
                    '[class*="notebook-title" i] input, [class*="project-title" i] input, ' +
                    '[class*="notebook-title" i], [class*="project-title" i], h1')) {
                const r = el.getBoundingClientRect();
                if (r.top > 120 || r.width < 60) continue;
                const v = ('value' in el && el.value) ? el.value
                          : (el.innerText || '').trim();
                if (v === title) return true;
            }
            return false;
        }""", title)
        if committed:
            log(f"[{label}] DOM rename OK (read-back verified): '{title}'")
            return True
        log(f"[{label}] DOM rename did not commit (read-back mismatch) — "
            f"CUA fallback will handle it", "WARN")
        return False
    except Exception as e:
        log(f"[{label}] DOM rename failed: {e}", "DEBUG")
        return False


async def _verify_and_repair_nlm_sources(browser, cua_client, md_files, verbose=False, max_rounds=2):
    """Post-upload health check for NotebookLM sources.

    NotebookLM ingests sources ASYNC after the file lands in the panel, so a
    source can appear (the per-file CUA "uploaded" check passes) and then flip
    to a red "failed" state during processing — observed 2026-05 where the
    first source uploaded *during notebook creation* (claude.md) went red and
    the audio overview was built from only 2/3 sources, silently.

    Gives ingestion a moment to settle, asks the CUA to report any source stuck
    in an error state BY FILENAME, and silently re-uploads each failed one
    (preferring NotebookLM's in-place retry over delete+re-add). Bounded to
    `max_rounds`. CONSERVATIVE: an "ALL OK" / ambiguous / unmappable verdict
    takes NO action, so the outcome is never worse than skipping this step.
    The caller wraps this so any exception just proceeds with what processed.

    2026-07-11 (FIFA run, gemini.md silently absent): the red-state-only CUA
    probe passes a MISSING source — no row, no error icon, "all sources OK"
    on a 2/3 notebook. Each round now starts with a DOM census against the
    expected manifest (also closing any leftover Add-sources modal — the
    FIFA verify ran behind one): missing names are re-added DOM-first, CUA
    re-upload as fallback, and the CUA red-state mission now carries the
    manifest so vision can flag absences too. Census runs even without a
    cua_client. Returns the set of names still missing after all rounds."""
    if not md_files:
        return set()
    by_name = {p.name: p for p in md_files}
    expected = list(by_name.keys())
    missing: set = set()
    for _round in range(1, max_rounds + 1):
        # Let async ingestion settle before judging (spinners → ✓ or red).
        await asyncio.sleep(8)
        await _nlm_close_dialogs(browser.page)
        present, _rows = await _nlm_census_settled(browser.page, expected,
                                                   attempts=4, interval=3.0)
        missing = {n for n in expected if n not in present}
        if missing:
            log(f"[NotebookLM] source census (round {_round}): "
                f"{len(present)}/{len(expected)} present — missing {sorted(missing)}", "WARN")
            try:
                emit_event("agent_progress", phase=3, agent="notebooklm",
                           status="repairing", stage="uploading",
                           progress=f"Re-adding {len(missing)} missing source(s)…")
            except Exception:
                pass
            _missing_paths = [by_name[n] for n in sorted(missing)]
            if await _nlm_dom_add_files(browser, browser.page, _missing_paths):
                continue  # next round re-censuses
            if not cua_client:
                continue
            for name in sorted(missing):
                browser.set_upload_file(str(by_name[name]))
                try:
                    async def _readd_cua(_name=name):
                        return await agent_loop(
                            cua_client, browser, PROMPT_NOTEBOOKLM_UPLOAD,  # noqa: F405
                            f"The source file '{_name}' is MISSING from this notebook. "
                            f"Add it: click 'Add source' (or '+') then the Upload files "
                            f"control. The file dialog is auto-handled. Add exactly this "
                            f"ONE file and nothing else.",
                            model=CUA_MODEL, max_iterations=8, verbose=verbose)
                    await _shadow_observed_cua(
                        browser.page, hotspot_id="nlm-add-source", phase=3,
                        platform="notebooklm",
                        current_step=f"readd_missing_source_{name}",
                        context_hint=f"the source '{name}' never made it into the "
                                     "notebook — add it via Add source/Upload files "
                                     "(the OS file dialog auto-selects the file)",
                        expected_outcome=f"the source '{name}' appears in the panel",
                        cua_coro_factory=_readd_cua,
                        mission_prompt=PROMPT_NOTEBOOKLM_UPLOAD,  # noqa: F405
                        act_timeout_s=150.0)
                finally:
                    browser.clear_upload_file()
                await asyncio.sleep(3)
            continue  # next round re-censuses
        if not cua_client:
            log(f"[NotebookLM] source census (round {_round}): all "
                f"{len(expected)} present (no CUA for red-state check)")
            return set()
        async def _verify_sources_cua():
            return await agent_loop(
                cua_client, browser, PROMPT_NOTEBOOKLM_VERIFY_SOURCES,
                f"The notebook is expected to contain exactly these "
                f"{len(expected)} sources: {', '.join(expected)}. Check the "
                f"Sources panel and report any of them in a failed/error (red) "
                f"state — or expected but entirely ABSENT — as FAILED: <filename>.",
                model=CUA_MODEL, max_iterations=8, verbose=verbose)

        # #839 act tier — READ_ONLY: this is a source-health probe (returns
        # 'ALL OK' / 'FAILED: <filename>'); it must never click. The FAILED:
        # verdict is token-parsed below in every mode.
        verdict = await _shadow_observed_cua(
            browser.page, hotspot_id="nlm-verify-sources", phase=3, platform="notebooklm",
            current_step="verify_sources_health",
            context_hint="READ ONLY — do not click. Check the Sources panel; report any "
                         "source in a failed/error (red) state BY FILENAME, or say 'ALL OK'.",
            expected_outcome="an honest 'ALL OK' or 'FAILED: <filename>' verdict",
            cua_coro_factory=_verify_sources_cua,
            mission_prompt=PROMPT_NOTEBOOKLM_VERIFY_SOURCES,
            read_only=True) or {}
        text = (verdict.get("text") if isinstance(verdict, dict) else "") or ""
        low = text.lower()
        # Conservative parse: only act on an explicit "FAILED:" verdict. "ALL
        # OK", empty, or anything without "failed:" → assume healthy and stop
        # (never blind-delete/re-add a good source on an ambiguous read).
        if "failed:" not in low:
            log(f"[NotebookLM] source verify (round {_round}): all sources OK")
            return set()
        failed_part = low.split("failed:", 1)[1]
        # Bail on explicit "no failure" phrasing the model may put after FAILED:.
        if failed_part.strip().split(",")[0].strip() in ("", "none", "n/a", "-", "nothing"):
            log(f"[NotebookLM] source verify (round {_round}): all sources OK")
            return set()
        # Token-equality match (split on commas/whitespace, trim stray
        # punctuation) — NOT a raw substring scan. A healthy filename mentioned
        # in prose after FAILED: (e.g. "FAILED: claude.md (gemini.md is fine)")
        # must NOT be matched and "repaired" by mistake.
        import re as _re
        _tokens = {t.strip().strip(".,;:()[]'\"") for t in _re.split(r"[\s,]+", failed_part) if t.strip()}
        failed = [name for name in by_name if name.lower() in _tokens]
        if not failed:
            log(f"[NotebookLM] source verify: failure reported but no known filename matched — "
                f"verdict='{text[:160]}' (skipping repair to avoid touching healthy sources)", "WARN")
            return set()
        log(f"[NotebookLM] source verify (round {_round}): {len(failed)} failed → re-uploading {failed}", "WARN")
        try:
            emit_event("agent_progress", phase=3, agent="notebooklm", status="repairing",
                       stage="uploading",
                       progress=f"Re-uploading {len(failed)} source(s) that failed to import…")
        except Exception:
            pass
        for name in failed:
            md_path = by_name[name]
            browser.set_upload_file(str(md_path))
            try:
                async def _reupload_cua():
                    return await agent_loop(
                        cua_client, browser, PROMPT_NOTEBOOKLM_REUPLOAD,
                        f"The source '{name}' failed to import. Retry it in place if possible, "
                        f"otherwise remove that one failed source and re-add the file (dialog auto-handled).",
                        model=CUA_MODEL, max_iterations=12, verbose=verbose)

                # #839 act tier: repairs ONE named failed source; the OS file
                # dialog is auto-answered (set/clear_upload_file bracket + the
                # filechooser handler), so Vision only drives the retry/re-add
                # clicks — never the native dialog.
                await _shadow_observed_cua(
                    browser.page, hotspot_id="nlm-reupload", phase=3, platform="notebooklm",
                    current_step=f"reupload_failed_source_{name}",
                    context_hint=f"the source '{name}' failed to import — use its in-place "
                                 "Retry if present, else remove ONLY that one failed source "
                                 "and re-add it (the OS file dialog auto-selects the file)",
                    expected_outcome=f"the source '{name}' is re-imported successfully",
                    cua_coro_factory=_reupload_cua,
                    mission_prompt=PROMPT_NOTEBOOKLM_REUPLOAD,
                    act_timeout_s=150.0)
            finally:
                browser.clear_upload_file()
            await asyncio.sleep(3)
    log("[NotebookLM] source verify: re-upload rounds exhausted — proceeding with whatever processed", "WARN")
    # Final honest census so the caller can decide (raise → Retry/Skip card)
    # instead of silently shipping a partial notebook. Settle-polled ~30s
    # (review r2): a round-2 re-add fires just seconds before this line, and
    # judging it instantly would raise a FALSE 'upload failed' card for an
    # upload that is about to succeed.
    try:
        present, _ = await _nlm_census_settled(browser.page, expected,
                                               attempts=6, interval=6.0)
        return {n for n in expected if n not in present}
    except Exception:
        return missing


async def run_phase3_upload(browser, cua_client, results, topic, queue_dir, verbose=False):
    """Phase 3: upload P2-built MDs to NotebookLM and make notebook public.
    Share-URL extraction lives entirely in P2 — this phase is pure NotebookLM."""
    log("=" * 60)
    log("PHASE 3: NotebookLM Upload")
    log("=" * 60)

    # 2026-04-26: log every MD on disk in queue_dir/documents/ at P3 entry.
    # Makes P2→P3 handoff debugging trivial — we can see at a glance which
    # of the 3 agent .md files made it to disk and at what size. If one is
    # missing or 0 bytes, P3 NotebookLM upload will silently miss that
    # source.
    try:
        _docs = queue_dir / "documents"
        if _docs.exists():
            _on_disk = [(f.name, f.stat().st_size) for f in sorted(_docs.glob("*.md"))]
            log("Phase 3: queue MDs on disk: " +
                (", ".join(f"{n}={s}b" for n, s in _on_disk) if _on_disk else "(none)"))
        else:
            log("Phase 3: queue_dir/documents does not exist — no MDs", "WARN")
    except Exception as _de:
        log(f"Phase 3: MD-on-disk audit failed: {_de}", "DEBUG")

    # Hydrate share links + MD files from P2's handoff (built at end of P2).
    # Resume safety: if _runtime was wiped (process restart between P2 and P3
    # — e.g. resume-from-P3 path), rebuild handoff state from results + disk.
    if not _runtime.p2_links_for_p3 and not _runtime.p2_md_files_for_p3:
        _build_phase2_to_phase3_handoff(results, queue_dir)
    links: dict[str, str] = dict(_runtime.p2_links_for_p3 or {})
    md_files: list = list(_runtime.p2_md_files_for_p3 or [])
    log(f"Phase 3: hydrated {len(links)} share links + {len(md_files)} MDs from P2 handoff")

    # Save links
    links_file = queue_dir / "links.json"
    links_file.write_text(json.dumps(links, indent=2), encoding="utf-8")
    log(f"Links saved: {links}")

    # Upload MDs to NotebookLM (wrapped in retry loop — user can re-attempt
    # after a login-expired or generic upload failure without losing the rest
    # of the pipeline).
    notebook_url = ""
    p3_max_retries = 2
    p3_attempt = 0
    while md_files and p3_attempt <= p3_max_retries:
        # Respect a prior Skip: the #899 login pause leaves notebooklm in
        # skipped_agents so re-entries never re-prompt (gate parity) — and
        # driving CUA uploads at a signed-out page the user already gave up
        # on would only burn quota.
        if "notebooklm" in _controls.skipped_agents:
            log("Phase 3: NotebookLM was skipped earlier this run — not re-attempting the upload", "INFO")
            break
        log(f"\n--- Uploading {len(md_files)} MDs to NotebookLM (attempt {p3_attempt + 1}/{p3_max_retries + 1}) ---")
        try:
            page = await browser.new_tab("https://notebooklm.google.com")
            await asyncio.sleep(4)

            # Early HV check — NotebookLM occasionally hits Google's bot gate
            # on fresh tabs when the session fingerprint looks suspicious.
            # Clearing first avoids wasted CUA calls on a blocked page.
            if cua_client:
                cleared = await check_hv_gate(browser, cua_client, "notebooklm", "NotebookLM",
                                               phase=3, verbose=verbose)
                if not cleared:
                    log("Phase 3: HV gate on NotebookLM could not be cleared — retrying or aborting", "ERROR")
                    p3_attempt += 1
                    continue

            # #899 work-tab preflight: confirmed signed-out probe on the
            # NotebookLM tab itself (the isolated verify tab is being retired).
            # Single-agent phase → pause like P1; signing in inside the open
            # tab auto-resumes. Skip/timeout → proceed without NotebookLM
            # (empty notebook_url; the caller cascades P4 off).
            if await _work_tab_signed_out(page, "notebooklm", "NotebookLM"):
                _p3_preflight = await _work_tab_login_pause(
                    page, "notebooklm", 3, "NotebookLM",
                    work_url="https://notebooklm.google.com")
                if _p3_preflight in ("stop", "skipped"):
                    log(f"Phase 3: NotebookLM login pause ended '{_p3_preflight}' — proceeding without the notebook", "WARN")
                    break
                # 'ok' → signed in, confirmed on the work page; proceed.

            # ── 2026-07-11 DOM-first upload ──────────────────────────────
            # Drive NotebookLM's own DOM (create notebook + hidden
            # input[type=file] multi-upload + source-row census) before any
            # CUA vision task. The FIFA run showed the CUA-only path is
            # fail-open end to end: an API 500 killed the gemini.md task
            # before the file dialog opened, both call sites discarded the
            # returned error dict, and the red-state-only verify passed the
            # 2/3 notebook — the source was simply never added.
            emit_event("agent_progress", phase=3, agent="notebooklm",
                       status="uploading", stage="uploading",
                       progress=f"Uploading {len(md_files)} source(s)…")
            _dom_uploaded = await _nlm_dom_upload_sources(browser, page, md_files)
            _remaining = [p for p in md_files if p.name not in _dom_uploaded]
            if _remaining:
                log(f"[NotebookLM] {len(_remaining)} file(s) left for the CUA "
                    f"fallback: {[p.name for p in _remaining]}",
                    "WARN" if _dom_uploaded else "INFO")

            for i, md_path in enumerate(_remaining):
                log(f"Uploading {md_path.name} ({i+1}/{len(_remaining)}) via CUA fallback...")
                # stage= (2026-07-06 milestone stepper): P3's three milestones
                # — uploading → notebook → podcast — tick off these explicit
                # stages (keyword fallback covers older events).
                emit_event("agent_progress", phase=3, agent="notebooklm",
                           status="uploading", stage="uploading",
                           progress=f"Uploading source: {md_path.name}")
                browser.set_upload_file(str(md_path))

                # Row watcher doubles as the CUA abort signal (#732 plumbing):
                # the moment the source row is DOM-visible the mission is over
                # — pre-fix the CUA burned its remaining iterations re-clicking
                # "Upload files" against an empty queue (6 warnings/4 wasted
                # minutes in the FIFA run) hunting phantom extra files.
                _row_evt = asyncio.Event()
                async def _row_watch(_name=md_path.name, _evt=_row_evt):
                    # (review r2) guards: only structured source ROWS on a
                    # /notebook/ page may abort the mission — the body-text
                    # fallback could match a home-page recent-notebook card
                    # or a transient "<name> failed" toast.
                    try:
                        while not _evt.is_set():
                            await asyncio.sleep(3)
                            try:
                                if "/notebook/" not in (page.url or ""):
                                    continue
                            except Exception:
                                continue
                            _seen, _rows = await _nlm_visible_source_names(page, [_name])
                            if _name in _seen and _rows != -1:
                                _evt.set()
                                return
                    except Exception:
                        pass
                _watch_task = asyncio.create_task(_row_watch())

                _stop, _task = start_narration_ticker(
                    3, "notebooklm",
                    f"NotebookLM uploading source: {md_path.name}",
                    interval=20)
                _cua_res = None
                try:
                    if "/notebook/" not in (page.url or ""):
                        async def _nlm_create_cua():
                            return await agent_loop(cua_client, browser, PROMPT_NOTEBOOKLM_UPLOAD,
                                f"Create a new notebook and upload the file '{md_path.name}'. "
                                f"File dialog is auto-handled. Upload exactly this ONE file.",
                                model=CUA_MODEL, max_iterations=15, verbose=verbose,
                                abort_event=_row_evt)

                        # #839 act tier: the OS file chooser is auto-answered
                        # (filechooser handler + upload queue) — Vision clicks
                        # the create/Add-source control only. set/clear bracket
                        # stays; success is judged per-file + by _verify below.
                        _cua_res = await _shadow_observed_cua(
                            browser.page, hotspot_id="nlm-create-upload", phase=3, platform="notebooklm",
                            current_step="create_notebook_upload_first",
                            context_hint="create a NEW NotebookLM notebook and upload the first "
                                         "source — click Create/New then the Add source/Upload "
                                         "control; the OS file dialog auto-selects the file",
                            expected_outcome="a new notebook exists with the first source uploading",
                            cua_coro_factory=_nlm_create_cua,
                            mission_prompt=PROMPT_NOTEBOOKLM_UPLOAD,
                            act_timeout_s=180.0)
                    else:
                        async def _nlm_add_cua():
                            return await agent_loop(cua_client, browser, PROMPT_NOTEBOOKLM_UPLOAD,
                                f"Add the source file '{md_path.name}'. Click 'Add source' or '+'. "
                                f"File dialog is auto-handled. Add exactly this ONE file.",
                                model=CUA_MODEL, max_iterations=10, verbose=verbose,
                                abort_event=_row_evt)

                        _cua_res = await _shadow_observed_cua(
                            browser.page, hotspot_id="nlm-add-source", phase=3, platform="notebooklm",
                            current_step=f"add_source_{md_path.name}",
                            context_hint=f"add source file {md_path.name} — click 'Add source' or "
                                         "the '+' control; the OS file dialog auto-selects the file",
                            expected_outcome=f"source {md_path.name} is added to the notebook",
                            cua_coro_factory=_nlm_add_cua,
                            mission_prompt=PROMPT_NOTEBOOKLM_UPLOAD,
                            act_timeout_s=150.0)
                finally:
                    await stop_narration_ticker(_stop, _task)
                    _row_evt.set()
                    _watch_task.cancel()

                browser.clear_upload_file()
                await asyncio.sleep(3)
                # Per-file deterministic check — a CUA task that DIED (API
                # error) or exhausted its iterations is otherwise
                # indistinguishable from success here.
                _cua_status = (_cua_res or {}).get("status", "") if isinstance(_cua_res, dict) else ""
                # Settled census (review r2): ingestion is async — a single
                # 3s-old census here used to re-add a file whose row was
                # about to render, landing the same source twice.
                _seen, _ = await _nlm_census_settled(page, [md_path.name],
                                                     attempts=5, interval=3.0)
                if md_path.name not in _seen:
                    log(f"[NotebookLM] {md_path.name} NOT visible after CUA task "
                        f"(status={_cua_status or 'unknown'}) — DOM re-add attempt", "WARN")
                    await _nlm_dom_add_files(browser, page, [md_path])
                    # _verify_and_repair below re-censuses and escalates.

            # Verify each source actually PROCESSED. NotebookLM ingests sources
            # ASYNC after the file lands in the panel, so a source can pass the
            # per-file "uploaded" check above and then flip to a red "failed"
            # state during processing — observed 2026-05: claude.md (the first
            # source, uploaded during notebook creation) went red and the audio
            # overview was built from only 2/3 sources, silently. This settles +
            # verifies + silently re-uploads any failed source. Best-effort:
            # wrapped so any error just proceeds with whatever processed.
            _still_missing: set = set()
            try:
                _still_missing = await _verify_and_repair_nlm_sources(
                    browser, cua_client, md_files, verbose=verbose) or set()
            except Exception as _ve:
                log(f"[NotebookLM] source verify/repair skipped (non-fatal): {_ve}", "WARN")
            if _still_missing:
                # 2026-07-11: don't silently ship a partial notebook (the FIFA
                # run published 2/3 sources with no signal anywhere). Raising
                # lands in the except below → honest "NotebookLM upload
                # failed" Retry/Skip card; Retry re-runs the upload in a fresh
                # tab, Skip proceeds without the notebook — the user's call.
                raise RuntimeError(
                    f"notebook is missing {len(_still_missing)} source(s) after "
                    f"upload + repair: {sorted(_still_missing)}")

            # Rename notebook — use the smart title (Firestore-synced) so NotebookLM,
            # YouTube, and the email subject all line up on the same short name.
            title = smart_title(topic)
            log(f"Renaming notebook to '{title}'...")
            emit_event("agent_progress", phase=3, agent="notebooklm",
                       status="renaming", stage="notebook",
                       progress=f"Renaming notebook to '{title}'…")
            # 2026-07-11 DOM-first rename: NotebookLM's title input ignores
            # Ctrl+A, so CUA typing APPENDS — the FIFA run shipped the title
            # 'FIFA World Cup Evolution And EconomicsThe FIFA W' after the
            # CUA burned 8/8 iterations failing to clear the field. Native
            # value-set + Angular events sidesteps the keyboard entirely;
            # CUA stays as fallback (best-effort — nothing downstream gates
            # on the notebook name).
            if not await _nlm_dom_rename(page, title):
                async def _nlm_rename_cua():
                    return await agent_loop(cua_client, browser, PROMPT_NOTEBOOKLM_RENAME,
                        f"Rename this notebook to: {title}. If Ctrl+A does not select the "
                        f"existing text, TRIPLE-CLICK the title field to select it first.",
                        model=CUA_MODEL, max_iterations=8, verbose=verbose)

                # #839 act tier: this site TYPES (the only P3 upload-family site
                # that types into the page).
                await _shadow_observed_cua(
                    browser.page, hotspot_id="nlm-rename", phase=3, platform="notebooklm",
                    current_step="rename_notebook",
                    context_hint=f"rename the notebook to '{title}': click the notebook title, "
                                 "clear it (triple-click to select), type the new name, press Enter",
                    expected_outcome=f"the notebook is titled '{title}'",
                    cua_coro_factory=_nlm_rename_cua,
                    mission_prompt=PROMPT_NOTEBOOKLM_RENAME,
                    act_timeout_s=90.0)

            # C1: make notebook public (Share → "Anyone with the link" → Save)
            # BEFORE emitting the URL, so the frontend's link is always viewable.
            emit_event("agent_progress", phase=3, agent="notebooklm",
                       status="sharing", stage="notebook",
                       progress="Setting notebook to 'Anyone with the link can view'…")
            notebook_url = await browser.current_url()
            try:
                log("NotebookLM: opening share dialog to set 'Anyone with link'...")
                nlm_share_res = await extract_notebooklm_url(browser, cua_client=cua_client, verbose=verbose)
                # 2026-07-31: this used to require `verified`, i.e. URL shape AND
                # a DOM-confirmed "Anyone with the link". `Public share
                # DOM-verified` has NEVER once appeared in the corpus, so the
                # extracted share URL was discarded on 100% of runs and the tab
                # URL was a silent crutch on every "successful" Phase 3. When the
                # share affordance changed, the crutch was all that was left —
                # which is how a hostname rename became a total outage.
                # The recovery loop in run_pipeline already accepts shape-only
                # (with a WARN); this is the same rule, so the primary path is no
                # longer STRICTER than its own fallback. `public_verified` stays
                # a separate, honest signal — logged, not gating.
                if is_notebooklm_url(nlm_share_res.url):
                    notebook_url = nlm_share_res.url
                    if nlm_share_res.verified:
                        log(f"NotebookLM public share OK (DOM-verified): {notebook_url}")
                    else:
                        # 2026-08-11: was a WARN saying "the link may be private".
                        # It isn't — the share step ran and reported success, and
                        # the owner confirms these notebooks come out public every
                        # time. What failed is the READ-BACK: the control that used
                        # to expose "Anyone with the link" no longer matches, and
                        # the comment above records that `verified` has never once
                        # been true in the corpus. A detector that is wrong on 100%
                        # of runs must not speak in the voice of a broken feature,
                        # so this states what actually happened and stays quiet.
                        log(f"NotebookLM shared; could not read the sharing state back "
                            f"(the confirmation control no longer matches — detector "
                            f"gap, not evidence the link is private): {notebook_url}",
                            "DEBUG")
                    # Track-B success-path observe (P3 notebook public share).
                    _observe_dom_success(browser.page, hotspot_id="p3-share", phase=3,
                                         platform="notebooklm", current_step="open_share_set_public_get_link",
                                         dom_ground_truth=_gt_from_box(None, url=notebook_url))
                else:
                    log(f"NotebookLM public share uncertain — falling back to tab URL "
                        f"'{notebook_url}': {nlm_share_res.error or 'no reason reported'}", "WARN")
                    # Track-B: observe on the FALLBACK path too. The share FLOW ran
                    # (dialog opened) even when the public link wasn't verified, so
                    # Vision's read is just as valid a sample. Gating the observe on
                    # `verified` alone made p3-share record 0 events whenever the
                    # share fell back to the tab URL.
                    _observe_dom_success(browser.page, hotspot_id="p3-share", phase=3,
                                         platform="notebooklm", current_step="open_share_set_public_get_link",
                                         dom_ground_truth=_gt_from_box(None, url=notebook_url, share="fallback"))
            except Exception as e:
                log(f"NotebookLM public share flow error: {e} — falling back to tab URL", "WARN")
            log(f"NotebookLM: {notebook_url}")
            # Emit notebook link immediately — frontend shows it without waiting for phase end
            if is_notebooklm_url(notebook_url):
                emit_validated_link(3, "notebooklm", notebook_url, "NotebookLM Notebook")
            break  # Successful upload — exit retry loop
        except Exception as e:
            log(f"NotebookLM upload error: {e}", "ERROR")
            # Distinguish session-expired from generic upload failure — the
            # frontend can offer "re-login then retry" vs "just retry".
            _err_msg = str(e)
            _low = _err_msg.lower()
            is_login_err = any(k in _low for k in ("login", "signin", "auth", "unauthor"))
            retries_left = max(0, p3_max_retries - p3_attempt)
            _title = ("Sign in to NotebookLM"
                      if is_login_err else
                      "NotebookLM upload failed")
            _details = ("NotebookLM signed out. Sign back in using the open browser, then Retry."
                        if is_login_err else
                        "We couldn't upload the reports to NotebookLM. Retry to try again, or Skip it.")
            fail_phase(3, _title, _details, agent="notebooklm",
                       can_retry=retries_left > 0)
            # Wait up to 10 min for user decision. Retry → re-run upload; skip →
            # proceed without NotebookLM; timeout → skip (don't hang pipeline).
            if retries_left > 0:
                p3_decision = await _controls.await_phase_decision(3)
                log(f"Phase 3 upload decision: {p3_decision}")
                if p3_decision == "stop":
                    break
                if p3_decision == "retry":
                    p3_attempt += 1
                    # Close the (possibly borked) NotebookLM tab so the retry
                    # opens a clean one.
                    try:
                        await page.close()
                    except Exception:
                        pass
                    try:
                        emit_event("phase_restart", phase=3,
                                   reason="user_retry_notebooklm_upload",
                                   attempt=p3_attempt + 1)
                    except Exception:
                        pass
                    continue  # retry the upload loop
                # continue_anyway / skip / timeout → break out; proceed with empty notebook_url
                break
            else:
                # No retries left — log and proceed with empty notebook_url
                log("Phase 3: No NotebookLM retries left — proceeding without it", "WARN")
                break
    if not md_files:
        log("No MD files to upload to NotebookLM", "WARN")

    return {"links": links, "notebook_url": notebook_url, "md_files": [str(p) for p in md_files]}


# ── Phase 3 (audio): Audio Overview Generation ───────────────────────────────

# ── The audio the pipeline could not find ────────────────────────────────────
# Magic bytes, because the file we are looking for HAS NO EXTENSION.
_AUDIO_MAGIC = (
    (b"ID3", ".mp3"),
    (b"\xff\xfb", ".mp3"), (b"\xff\xf3", ".mp3"), (b"\xff\xf2", ".mp3"),
    (b"RIFF", ".wav"),
    (b"\x1a\x45\xdf\xa3", ".webm"),
    (b"OggS", ".ogg"),
)


def _is_audio_only(path) -> bool | None:
    """True when ffprobe finds an audio stream and no video stream.

    False when it ran and the answer was no — a video, or bytes it cannot read as
    media at all. None ONLY when ffprobe itself is unavailable, which is a
    different situation and gets a different answer at the call site.

    The honest discriminator between a podcast and a holiday video, which is what
    the ISO-BMFF major brand was being asked — and failing — to answer.
    """
    probe = _ffprobe_bin()
    if probe is None:
        return None
    try:
        out = subprocess.run(
            [probe, "-v", "error", "-show_entries", "stream=codec_type",
             "-of", "default=noprint_wrappers=1:nokey=1", str(path)],
            capture_output=True, text=True, timeout=30,
        )
    except (OSError, ValueError, subprocess.SubprocessError):
        return None
    # ffprobe RAN. A non-zero exit or no streams means it could not read this as
    # media — that is a real answer ("not usable audio"), not an absence of one.
    # Collapsing the two is how a truncated download, or a stub of zero bytes
    # behind an mp4 header, would be published as somebody's podcast.
    if out.returncode != 0:
        return False
    kinds = {ln.strip() for ln in (out.stdout or "").splitlines() if ln.strip()}
    if not kinds:
        return False
    return ("audio" in kinds) and ("video" not in kinds)


def _audio_kind(path, *, trusted=False) -> str:
    """The extension this file's CONTENT says it should have, or "".

    ⛔ 2026-08-06 (review) — THE FIRST VERSION OF THIS WOULD HAVE CALLED A HOLIDAY
    VIDEO AN AUDIO FILE. `ftyp` at offset 4 is ISO-BMFF, which covers mp4, mov,
    heic and m4a alike; a bare `RIFF` covers wav, avi and webp alike. Combined
    with a recursive scan of the user's Downloads folder and a `shutil.move`,
    that could have taken someone's photo or video and published it as the
    podcast. The brand and the RIFF form are checked now, so only audio answers.

    ⭐⭐ 2026-08-09 — AND THEN IT REJECTED THE PODCAST. Chrome's own history records
    the audio overview completing at 23:03:01, 3,487,728 bytes, state=1, straight
    into Playwright's artifacts directory. The scan ran 34 seconds later, walked
    that directory, found the file — and threw it away, because the major brand was
    not literally `M4A `. NotebookLM serves a generic ISO brand. The run then
    reported "audio file missing" and retried against a notebook that had already
    produced it. The 08-06 hardening fixed the half it could see (extension, dirs)
    and made the other half stricter than the real artifact.

    The brand was never the right question. "Is this a video?" is, and ffprobe
    answers it — so a generic ISO container is accepted when the file has an audio
    stream and no video stream.

    `trusted` is the second half. Playwright's artifacts directory contains only
    what THIS run downloaded; the user's Downloads folder is where the holiday
    video lives. So an unprobeable generic container is accepted from the first and
    never from the second — the 08-06 hazard was always about the user's files, and
    that guard stays exactly as strict as it was.
    """
    try:
        with open(path, "rb") as fh:
            head = fh.read(16)
    except Exception:
        return ""
    if not head:
        return ""
    if len(head) >= 12 and head[4:8] == b"ftyp":
        # M4A/M4B say audio outright, wherever they came from.
        if head[8:12] in (b"M4A ", b"M4B "):
            return ".m4a"
        # Anything else ISO-BMFF (isom, mp42, dash, qt, heic…) needs PROOF, and
        # only a positive one counts. ffprobe saying "I cannot read this" is a no,
        # not a maybe — an earlier draft treated it as a maybe and accepted a
        # zero-filled mp4 stub out of the trusted directory, which is the holiday
        # video hazard wearing a different hat. The existing 08-06 test caught it.
        proof = _is_audio_only(path)
        if proof is True:
            return ".m4a"
        if proof is None and trusted:
            # ffprobe is not installed at all. The file is still ours by
            # construction — this directory holds only what this run downloaded —
            # so accept it rather than repeat the 08-09 outage. P3 needs ffmpeg to
            # transcode anyway, so a box without it has a louder problem than this.
            log("[Audio] ffprobe unavailable — accepting the downloaded container "
                "on directory trust alone", "WARN")
            return ".m4a"
        return ""
    if head.startswith(b"RIFF"):
        return ".wav" if len(head) >= 12 and head[8:12] == b"WAVE" else ""
    for sig, ext in _AUDIO_MAGIC:
        if head.startswith(sig):
            return ext
    return ""


# A file the browser is still writing is not a file we may take.
_INCOMPLETE_SUFFIXES = (".crdownload", ".part", ".download", ".tmp", ".partial")


def _is_settled(path, *, pause_s=1.0) -> bool:
    """True when the file has stopped being written to.

    Two stats a second apart: an in-flight download grows between them. Without
    it, the 30-second event wait can expire while Chrome is still writing and the
    fallback moves the file out from under the writer — on a slow connection,
    that would be this run's OWN audio.
    """
    try:
        a = Path(path).stat()
        time.sleep(pause_s)
        b = Path(path).stat()
    except Exception:
        return False
    return a.st_size == b.st_size and a.st_mtime == b.st_mtime and b.st_size > 0


def _find_recent_audio(dirs, *, min_bytes=4096):
    """The newest real audio file across `dirs`, identified by CONTENT.

    Each entry is `(path, recursive, max_age_s, may_move)`. Per-directory policy,
    not one blanket sweep: Playwright's own artifacts directory is ours to
    recurse and to move from; the user's Downloads folder is neither.

    ⭐⭐ 2026-08-06 — THE DOWNLOAD SUCCEEDED AND WE COULD NOT SEE IT. Chrome's own
    history records the audio completing at 21:43:40 and the vision agent said so
    too. The page-scoped event never reached us, so the fallback ran — and it
    globbed `*.mp3 *.wav *.m4a *.webm` under `~/Downloads` while Playwright had
    saved the file into its OWN artifacts directory, under a GUID, with no
    extension at all. Two independent reasons it could never match.
    ⛔ So: no extension filter. Match on mtime, confirm on magic bytes, take the
    name from what the bytes say it is.
    """
    best = None
    now = time.time()
    for entry in dirs:
        try:
            d, recursive, age, may_move = entry
            if not d or not Path(d).exists():
                continue
            it = Path(d).rglob("*") if recursive else Path(d).glob("*")
            for f in it:
                try:
                    if not f.is_file() or f.name.startswith("."):
                        continue
                    if f.suffix.lower() in _INCOMPLETE_SUFFIXES:
                        continue
                    st = f.stat()
                    if (now - st.st_mtime) > age or st.st_size < min_bytes:
                        continue
                    if best is not None and st.st_mtime <= best[0]:
                        continue
                    # `may_move` already encodes the trust this needs: it is True
                    # only for Playwright's own artifacts directory, which contains
                    # nothing but what this run downloaded. The user's Downloads
                    # folder is may_move=False and stays under the strict rule.
                    kind = _audio_kind(f, trusted=may_move)
                    if not kind:
                        continue
                    best = (st.st_mtime, f, kind, may_move)
                except Exception:
                    continue
        except Exception:
            continue
    if best is None:
        return (None, "", False)
    return (best[1], best[2], best[3])


def _audio_search_plan(browser):
    """Where to look for the podcast, and what we are allowed to do there.

    (path, recursive, max_age_s, may_move). Playwright's artifacts directory is
    ours: recurse it, give it the full window, move from it. The human Downloads
    folder is not: top level only, a tight window, and COPY — never take a file
    out of somebody's Downloads because it happened to be recent and audio.
    """
    plan = [(p, True, 300, True) for p in _playwright_download_dirs(browser)]
    # ⛔ 2026-08-11 (review). Temp artifact directories that are NOT this
    # context's are still worth SCANNING — on a host where the context reports a
    # directory we would otherwise never look at a sibling worker's, and the
    # 08-09 outage was caused by not finding a file that existed. But they are
    # emphatically not ours to MOVE from: the newer file there may be another
    # run's podcast, mid-download, and `shutil.move` would take it. So: recurse,
    # same window, may_move=False — which also keeps them under the strict
    # content rule, since `_find_recent_audio` derives its trust from may_move.
    plan += [(p, True, 300, False) for p in _playwright_foreign_artifact_dirs(browser)]
    plan += [(Path.home() / "Downloads", False, 120, False),
             (Path("D:/Downloads"), False, 120, False)]
    return plan


def _playwright_download_dirs(browser):
    """Where Playwright puts a download when nobody calls `save_as`: a
    GUID-named, extensionless file under `playwright-artifacts-*` in the system
    temp dir — invisible to any glob that assumes a Downloads folder."""
    out = []
    try:
        _ctx = getattr(getattr(browser, "page", None), "context", None)
        _impl = getattr(_ctx, "_impl_obj", None)
        for attr in ("_download_dir", "_artifacts_dir"):
            _d = getattr(_impl, attr, None)
            if _d:
                out.append(Path(str(_d)))
    except Exception:
        pass
    # ⛔ 2026-08-11 (review). The temp-wide glob below returned EVERY
    # `playwright-artifacts-*` directory on the host, and `_find_recent_audio`
    # treats each as trusted AND movable — "this directory holds only what this
    # run downloaded" is the entire basis for both. With two workers downloading
    # on one host that is false: the newer file could belong to the other run,
    # and `shutil.move` would take it out from under them. The trust half got
    # worse on 08-10, when a missing ffprobe started accepting an unrecognised
    # container purely on directory trust.
    #
    # So the context's OWN directories are authoritative when it reports any, and
    # the glob is only a fallback for the case it does not. Even then the extra
    # directories are handed back separately, so the caller can scan them without
    # claiming they are ours to move.
    if out:
        return out

    # ⛔ 2026-08-11, SECOND PASS. The attribute probe above returns NOTHING on the
    # installed Playwright — `_download_dir` and `_artifacts_dir` do not exist in
    # patchright or playwright at this version (grep: zero hits). The first
    # version of this function treated that empty result as authoritative, so
    # every artifacts directory became "foreign", and two things followed that the
    # commit message claimed the opposite of:
    #
    #   * the multi-worker protection never engaged, because our OWN directory was
    #     the one being classified as somebody else's;
    #   * `_find_recent_audio` derives trust from may_move, so trusted went
    #     permanently False — which disables the ffprobe-absent acceptance in
    #     `_audio_kind` and REINSTATES the 2026-08-09 outage on any machine
    #     without ffmpeg. Exactly the outage that fallback exists to prevent.
    #
    # The e2e caught it: the two runs before this change logged "moved", the run
    # after logged "copied", on a host with no sibling worker at all.
    #
    # So identify ourselves by the one discriminator that actually holds. With a
    # SINGLE artifacts directory on the host there is no sibling run to confuse it
    # with, and it is ours — trusted and movable, exactly as before. With more than
    # one we genuinely cannot tell, so none of them is claimed and they all go
    # through the scan-only path, which is where the hazard was real in the first
    # place.
    try:
        import tempfile as _tf
        _dirs = sorted(Path(_tf.gettempdir()).glob("playwright-artifacts-*"))
    except Exception:
        return []
    return _dirs if len(_dirs) == 1 else []


def _playwright_foreign_artifact_dirs(browser):
    """Temp `playwright-artifacts-*` directories that are NOT this context's.

    Kept separate from `_playwright_download_dirs` so the caller has to decide,
    explicitly, whether a directory it does not own may be moved from. The answer
    is always no.
    """
    own = set()
    try:
        _ctx = getattr(getattr(browser, "page", None), "context", None)
        _impl = getattr(_ctx, "_impl_obj", None)
        for attr in ("_download_dir", "_artifacts_dir"):
            _d = getattr(_impl, attr, None)
            if _d:
                own.add(Path(str(_d)))
    except Exception:
        pass
    # Whatever `_playwright_download_dirs` claims is ours is excluded here, so no
    # directory can reach the search plan twice with contradictory move flags.
    try:
        own.update(_playwright_download_dirs(browser))
    except Exception:
        pass
    out = []
    try:
        import tempfile as _tf
        for _d in Path(_tf.gettempdir()).glob("playwright-artifacts-*"):
            if not any(_d == _o or _d in _o.parents for _o in own):
                out.append(_d)
    except Exception:
        pass
    return out


async def run_phase3_audio(browser, cua_client, notebook_url, queue_dir, verbose=False, podcast_length="long", prefer_existing_audio: bool = False):
    """Phase 3 (step b): Generate audio overview in NotebookLM + share public.

    `prefer_existing_audio` (2026-05-27, Fix B): set by the no-audio
    auto-retry. When True and the notebook already holds exactly ONE
    completed audio card, treat it as THIS run's own (a prior attempt
    generated it but the download failed) — skip Generate + verification
    and go straight to the (re-anchored) download. Without this, a retry
    re-trips the "1 completed audio from a prior run" pre-flight guard and
    never downloads, or re-runs generation and risks a duplicate card.

    `podcast_length` (2026-05-13 feature): "short" / "default" / "long".
    Drives the customize-panel Format/Length selection via the
    make_prompt_audio_generate factory. Defaults to "long" for backward
    compatibility with callers that don't yet pass the kwarg."""
    log("=" * 60)
    log("PHASE 3 (audio): Audio Overview Generation")
    log("=" * 60)

    if not notebook_url:
        log("No NotebookLM notebook — skipping Phase 3 (audio)", "WARN")
        return {"audio_path": None}

    # Respect a prior Skip (the #899 login pause leaves notebooklm in
    # skipped_agents) — the no-audio auto-retry loop re-enters this function,
    # and re-prompting a decision the user already made would be a re-card
    # loop with 5-min waits between rounds.
    if "notebooklm" in _controls.skipped_agents:
        log("Phase 3 (audio): NotebookLM was skipped earlier this run — not re-attempting", "INFO")
        return {"audio_path": None}

    # Navigate to notebook if not already there
    current = await browser.current_url()
    if "notebooklm" not in current:
        await browser.navigate(notebook_url)
        await asyncio.sleep(4)

    # Early HV gate check — NotebookLM occasionally sits behind Google's bot
    # challenge when the session fingerprint drifts. Clearing it upfront
    # saves us from a cascade of failed CUA clicks that would consume
    # workspace quota without moving forward.
    if cua_client:
        cleared = await check_hv_gate(browser, cua_client, "notebooklm", "NotebookLM",
                                       phase=3, verbose=verbose)
        if not cleared:
            log("Phase 3: HV gate on NotebookLM could not be cleared — aborting audio step", "ERROR")
            return {"audio_path": None}

    # #899 work-tab preflight: the Google session can die between the upload
    # step and this audio step (long gap on big source sets). Confirm the
    # sign-in on the notebook tab itself before spending CUA on Generate.
    if await _work_tab_signed_out(browser.page, "notebooklm", "NotebookLM"):
        _p3b_preflight = await _work_tab_login_pause(
            browser.page, "notebooklm", 3, "NotebookLM",
            work_url=notebook_url)
        if _p3b_preflight in ("stop", "skipped"):
            log(f"Phase 3 (audio): NotebookLM login pause ended '{_p3b_preflight}' — no audio", "WARN")
            return {"audio_path": None}
        # 'ok' → signed in, confirmed on the notebook; proceed.

    # 2026-05-06 (Stream 2 D1): single-attempt audio generation. The outer
    # _await_phase_with_active_deadline(3, PHASE_3_AUDIO_MAX_MIN,
    # soft_warn_only=True) at the call site (:20049) is the sole audio
    # ceiling. User retry routes through that helper's
    # _PhaseSoftDecision('retry') OR through the post-helper no-audio loop
    # — no inner retry/timeout machinery here.
    audio_done = False
    # Fix B (2026-05-27): set when prefer_existing_audio + a single complete
    # card → reuse it (skip Generate + verification, download only).
    _reuse_existing = False

    # Pre-flight invariant check (2026-05-02). Per the user's
    # no-delete constraint, we cannot recover from a duplicate-audio
    # state — we have to prevent it. Two failure modes guarded:
    #   (a) >1 audio card visible → orphaned + duplicate state we
    #       can't safely resolve without deleting one. fail_phase.
    #   (b) exactly 1 card AND not generating → completed orphan
    #       from a prior run. fail_phase asks user to clean it up.
    # The 5s sleep absorbs panel-render lag after the navigate/reload
    # that preceded this loop iteration — without it the count can
    # come back as 0 prematurely.
    await asyncio.sleep(5)
    existing_cards = await _count_nlm_audio_cards(browser.page)
    existing_generating = await _count_nlm_audio_generating(browser.page)
    already_generating = await _check_audio_generating(browser.page)
    log(f"[Phase3] Pre-flight inventory: {existing_cards} ready + "
        f"{existing_generating} generating audio card(s), "
        f"generating={already_generating}")

    # #778 (2026-06-03): counter-independent GENERATION POLICY — no fail_phase,
    # no delete. The NotebookLM notebook is created FRESH for THIS run (Phase 3
    # step a), so any audio card present here is this run's own (a prior
    # attempt's) — never a foreign orphan the user must delete. Decision table:
    #   >= 2 cards   → a duplicate slipped past prevention. Do NOT generate
    #                  (a 3rd would compound it); reuse-path → poll + download
    #                  the requested one via the resilient picker.
    #                  (WAS: fail_phase "Extra audio" → wedged the retry loop on
    #                   a state the user couldn't clear without deleting.)
    #   == 1 card    → reuse it (download only, never generate) regardless of
    #                  prefer_existing_audio. On a per-run notebook the lone
    #                  card is this run's own. (WAS: fail_phase "Old audio" on
    #                  the non-retry path.)
    #   == 0, retry  → a no-audio auto-retry with nothing to reuse. Do NOT
    #                  regenerate — DOWNLOAD-ONLY retry policy bounds
    #                  accumulation (each generate would spawn another card).
    #                  Return so the bounded loop falls back to notebook-only.
    #   == 0, fresh  → generate once (the else branch below).
    # The dup-count guards downstream (post-generate / mid-poll) are likewise
    # demoted to log+continue; the resilient download picker targets the right
    # card. This is the user's hard rule: never fail on a dup — always download
    # the right audio — and NEVER delete.
    if existing_cards >= 2:
        log(f"[Phase3] Pre-flight: {existing_cards} audio cards present — a duplicate "
            f"exists; NOT generating, will poll + download the requested one via the "
            f"resilient picker (no-delete)", "WARN")
        _reuse_existing = True
    elif existing_cards == 1:
        log("[Phase3] Pre-flight: 1 audio card already present — reusing it "
            "(download only, no Generate)")
        _reuse_existing = True
    elif prefer_existing_audio:
        log("[Phase3] Retry with 0 audio cards — NOT regenerating (download-only "
            "retry policy bounds accumulation); audio unavailable this attempt", "WARN")
        return {"audio_path": None}

    if _reuse_existing:
        # Do NOT click Generate. The poll loop's first DOM check
        # (_check_audio_complete_dom) confirms the existing card is complete
        # and breaks straight into the download.
        log("[Phase3] Reuse path: skipping Generate — poll loop will confirm the existing card and download it")
    elif already_generating:
        log("Audio already generating — skipping Generate click")
    else:
        # 2026-05-13: per-variant format + length names for log / narrator
        # / CUA task copy. Mirrors make_prompt_audio_generate's table.
        _variant_label = {
            "short": ("Brief", "the Brief format (no separate length step)"),
            "default": ("Deep Dive", "Deep Dive + Default length"),
            "long": ("Deep Dive", "Deep Dive + Long length"),
        }.get(podcast_length, ("Deep Dive", "Deep Dive + Long length"))
        _fmt_short, _human_desc = _variant_label
        log(f"Starting audio generation ({_human_desc})...")
        _stop, _task = start_narration_ticker(
            3, "notebooklm",
            f"Configuring audio overview ({_human_desc}) and clicking Generate",
            interval=20)
        try:
            # #778 PREVENTION (the deterministic dup-kill): DOM-click the
            # Customise ARROW to open the customize panel WITHOUT ever clicking
            # the card body. The card BODY fires NotebookLM's one-click DEFAULT
            # audio = the duplicate; the CUA agent, hunting for the
            # open-affordance, was the one occasionally hitting the body. With
            # the arrow DOM-clicked first, CUA starts from an already-open panel
            # (panel_already_open=True) and only touches Format/Length + the
            # terminal Generate — far from the body. Fail-open: if the arrow
            # can't be found, panel_already_open=False runs the unchanged full
            # CUA flow (its #757-A body-misclick guardrails hold). All calls
            # here are exception-safe, but keeping them inside the try means the
            # narration ticker's finally always stops it.
            _panel_opened = await _open_nlm_audio_customize(browser.page)
            if _panel_opened:
                log("[Phase3] Customize panel opened via DOM arrow-click ✓ (no card-body click)")
                await asyncio.sleep(1.5)  # let the panel render before CUA looks
                # One-time-per-process READ-ONLY canary: dump the OPEN customize
                # panel so the next E2E can pin the (un-supplied) Generate +
                # length controls AND confirm the arrow opened the right panel.
                # Gated so a healthy run logs it at most once per worker process.
                if "customize-open" not in _NLM_CANARY_STATE:
                    _NLM_CANARY_STATE.add("customize-open")
                    await _dump_nlm_audio_dom(browser.page, "customize-open")
                # Track-B success-path observe (P3 customize-open). Fire-and-forget,
                # default-OFF; boolean ground-truth (the dup-kill arrow-click is JS,
                # no bbox — deferred to avoid touching the #778 path).
                _observe_dom_success(browser.page, hotspot_id="p3-audio-customize", phase=3,
                                     platform="notebooklm", current_step="open_audio_customize_panel",
                                     dom_ground_truth=_gt_from_box(None, label="Customise Audio Overview",
                                                                   clickedTag="button"))
            else:
                log("[Phase3] DOM arrow-click didn't find the Customise control — "
                    "CUA will open customize itself (fail-open)", "WARN")
            _prompt = make_prompt_audio_generate(podcast_length,
                                                 panel_already_open=_panel_opened)
            _task_str = (
                f"The Audio Overview customize panel is already OPEN. Set "
                f"{_human_desc} in that panel, then click Generate ONCE. Say "
                f"'generating' when started. Do NOT click the audio card body."
            ) if _panel_opened else (
                f"Generate ONE audio overview. Select all sources, set "
                f"{_human_desc}, click Generate ONCE. Say 'generating' when started."
            )
            # #757 (2026-06-02): keep max_iterations at 15 — do NOT lower it to
            # "kill" the duplicate. The duplicate is a card-body misclick on the
            # iteration RIGHT AFTER Generate (logged at iter ~4), so any cap ≥ 4
            # can't stop it; the real fix is the terminal "STOP — no clicks after
            # Generate" prompt (prompts.py make_prompt_audio_generate step 7),
            # which exits the loop at `not tool_uses` the moment CUA says
            # "generating". 15 only bites on a stuck run, and the long-variant
            # customize flow (sources→count→gear→panel→format-dropdown→select→
            # length-dropdown→select→Generate) can legitimately need ~10 iters —
            # capping at 6 would truncate a valid run BEFORE Generate and produce
            # NO audio at all, a worse failure than a detectable duplicate.
            async def _audio_generate_cua():
                return await agent_loop(cua_client, browser, _prompt, _task_str,
                    model=CUA_MODEL, max_iterations=15, verbose=verbose)

            # #839 act tier — HIGHEST-RISK P3 hotspot. #778: NEVER click the
            # Audio Overview card body/title/thumbnail/gear/arrow once the panel
            # is open (fires an undeletable DEFAULT-audio duplicate). The full
            # make_prompt_audio_generate mission (with the panel_already_open
            # step-neutralization + the terminal "STOP — no clicks after
            # Generate") is passed verbatim, and its 'abort:' contract is parsed
            # from the returned text below in EVERY mode. A Vision success returns
            # the same {text} shape; CUA is the safety net on anything else.
            #
            # #839 review [4] DOUBLE-GENERATE GUARD: this is the one non-idempotent
            # P3 act site. If a Vision act attempt clicked Generate but ended
            # without declare_success (timeout/step-cap/escalate), re-running the
            # FULL CUA mission would click Generate a SECOND time — the exact
            # undeletable-duplicate #778 forbids (and CUA can't undo). So before
            # the CUA net fires, re-probe: if generation is already in flight OR a
            # card appeared since the pre-flight count, SKIP CUA and return a
            # synthetic "generating" result (no 'abort:') so the caller falls
            # straight into the authoritative verify + poll loop. Off/shadow never
            # invoke the probe.
            async def _audio_gen_net_probe():
                try:
                    if await _check_audio_generating(browser.page):
                        log("[Phase3] act-net guard: audio already generating after the "
                            "Vision attempt — skipping the CUA re-generate to avoid a "
                            "duplicate (#778); handing to the poll loop")
                        return {"status": "vision_partial", "text": "generating"}
                    if await _count_nlm_audio_cards(browser.page) > existing_cards:
                        log("[Phase3] act-net guard: a new audio card appeared after the "
                            "Vision attempt — skipping the CUA re-generate (#778)")
                        return {"status": "vision_partial", "text": "generating"}
                except Exception as _pge:
                    log(f"[Phase3] act-net guard probe errored ({_pge}) — allowing CUA net", "WARN")
                return None

            _ag_result = await _shadow_observed_cua(
                browser.page, hotspot_id="audio-generate", phase=3, platform="notebooklm",
                current_step=("configure_generate_audio_panel_open" if _panel_opened
                              else "configure_generate_audio_full"),
                context_hint=(_task_str + " CRITICAL: only touch the Format/Length "
                              "controls and the Generate button — NEVER the audio card "
                              "body/title/thumbnail (that makes an undeletable duplicate)."),
                expected_outcome="one audio overview starts generating with the requested format/length",
                cua_coro_factory=_audio_generate_cua,
                mission_prompt=f"{_prompt}\n\nTASK: {_task_str}",
                act_timeout_s=180.0,
                pre_cua_net_probe=_audio_gen_net_probe) or {}
        finally:
            await stop_narration_ticker(_stop, _task)

        # 2026-05-14: capture CUA abort signals. The audio-generate prompt
        # (prompts.py:674-688) instructs CUA to emit exact "abort: …"
        # strings when it detects unsafe states (no customize affordance,
        # customize panel never opened, default audio fired by misclick,
        # or audio already present). Previously the caller ignored the
        # return value, so a CUA-detected misclick would fall through to
        # the post-generate invariant — which runs too early to catch a
        # delayed-rendering default audio card. Surfacing the abort lets
        # the user retry from a clean state instead of polling a confused
        # dual-audio panel for the full audio window.
        _ag_text = (_ag_result.get("text") or "").lower() if isinstance(_ag_result, dict) else ""
        if "abort:" in _ag_text:
            _reason_phrase = _ag_text.split("abort:", 1)[1].split("\n", 1)[0].strip()[:160]
            # #778 (2026-06-03): dup-related aborts no longer fail_phase. Both
            # "audio already present" (a card rendered between the pre-flight
            # count=0 and CUA's own count — panel-render lag) and "misclick —
            # default audio fired" mean an audio card EXISTS. Per the hard
            # no-delete + never-fail-on-dup policy, fall through to the poll loop
            # — the resilient download picker resolves the requested card. Only
            # GENUINE setup failures (no customize affordance / panel never
            # opened → generation didn't start, so polling can't succeed) still
            # surface a Retry.
            if ("audio already present" in _ag_text
                    or "misclick" in _ag_text
                    or "default audio" in _ag_text):
                log(f"[Phase3] CUA abort '{_reason_phrase}' indicates an audio card "
                    f"exists — proceeding to poll + download it (no-delete, no-fail)", "WARN")
            else:
                # no_customize_affordance / customize_did_not_open: generation
                # never started. Log the verbatim phrase (the card stays plain)
                # and surface a Retry.
                log(f"[Phase3] Audio generation aborted by CUA: {_reason_phrase}", "ERROR")
                fail_phase(
                    3,
                    "Couldn't create the audio overview",
                    "NotebookLM's audio step couldn't complete safely. "
                    "Retry to try again — or open the notebook and make the "
                    "audio overview yourself.",
                    agent="notebooklm",
                    can_retry=True,
                )
                return {"audio_path": None}

    # Verify it started. Fix B (2026-05-27): on the reuse path the card is
    # ALREADY complete, so "verify generation started" is both meaningless
    # and dangerous — wait_until_verified escalates to a CUA "click any
    # needed buttons" fix attempt at its retry 7 (research.py wait_until_verified
    # Phase 3), which on a finished notebook can fire a duplicate/default
    # audio — the exact state the no-delete invariant can't recover from.
    if _reuse_existing:
        verified = True
    else:
        # #757 (2026-06-02): do NOT hand wait_until_verified a cua_client here.
        # Its Phase-3 escalation (retry 7) runs PROMPT_FIX_ISSUE — "click any
        # needed buttons" — and on a notebook the only button it can find to
        # "fix" a not-yet-detected audio is the Audio Overview card body, which
        # fires NLM's one-click DEFAULT audio = the exact duplicate we're
        # killing. Fix B already guarded the reuse path; the non-reuse path was
        # the remaining open vector. The code-side _check_audio_generating DOM
        # check + the download poll loop below are the authoritative backstops,
        # so a missed verify here only WARNs (harmless) — it never needs CUA to
        # click anything.
        verified = await wait_until_verified(
            lambda page: _check_audio_generating(page),
            browser.page, "Phase3-audio", browser=browser, cua_client=None,
            max_retries=10, interval=5, verbose=verbose)

    if not verified:
        log("Could not verify audio generation started", "WARN")

    # Post-generate invariant check (2026-05-02). If CUA misclicked
    # the Audio Overview tile body during the customize flow, the
    # NLM Studio panel auto-fires a default short audio in addition
    # to the one we explicitly requested — leaving the user with two
    # in-flight entries. We can't delete (user constraint), so we
    # fail_phase loud and ask the user to manually clean up the
    # unwanted entry. The 5s sleep gives the new card time to render
    # in the panel before the count.
    await asyncio.sleep(5)
    post_gen_cards = await _count_nlm_audio_cards(browser.page)
    post_gen_generating = await _count_nlm_audio_generating(browser.page)
    log(f"[Phase3] Post-generate inventory: {post_gen_cards} ready + "
        f"{post_gen_generating} generating audio card(s)")
    if post_gen_cards == 0 and post_gen_generating == 0:
        # #757-B capture: a card should exist right after Generate — 0 means the
        # counter selectors missed a live (in-flight) card. Dump it (read-only).
        #
        # Both counts, because five seconds after Generate the expected state is
        # 0 ready + 1 generating — the ready-only test made a healthy run fire a
        # WARN dump every time, which is the noise that hides a real anomaly.
        await _dump_nlm_audio_dom(browser.page, "post-generate")
    if post_gen_cards > 1:
        # #778 (2026-06-03): a duplicate slipped past prevention (the DOM
        # arrow-click). Per the hard NO-DELETE constraint we do not delete — and
        # we no longer fail_phase here. The old fail_phase wedged the no-audio
        # retry loop on a state the user couldn't clear without deleting (and
        # Skip was ignored), which is exactly the bug being fixed. LOG and
        # CONTINUE: the resilient download picker (_pick_nlm_audio_card) targets
        # the user-requested card by format + DOM order at download time.
        log(f"[Phase3] Post-generate: {post_gen_cards} audio cards (duplicate) — "
            f"continuing; resilient download will target the requested one "
            f"(no-delete, no-fail)", "WARN")

    # Minimum 2 minute wait — audio generation typically starts within 1-2 min;
    # waiting 5 min was burning slack for no reason. First poll at 2 min is
    # safe (NotebookLM has reliably emitted progress signals by then).
    # Fix B: skip the pre-poll wait on the reuse path — the card is already
    # done, so the poll loop's first DOM check detects + breaks immediately.
    if not _reuse_existing:
        log("Waiting 2 minutes before first audio check (generation takes ~10-20 min)...")
    interrupt = await _controls.interruptible_sleep(0 if _reuse_existing else 2 * 60, check_interval=10)
    if interrupt == "stop":
        log("[Phase3] STOP during initial wait — aborting", "WARN")
        return {"audio_path": None}
    if interrupt == "pause":
        emit_event("pipeline_paused", phase=3)
        await _controls.wait_if_paused()
        if _controls.is_stop():
            return {"audio_path": None}

    # Poll for completion — refresh + CUA check every 3 min. No inner cap;
    # the outer _await_phase_with_active_deadline at :20049 (soft_warn_only=True)
    # is the sole audio ceiling.
    log("Polling for audio completion (every 3 min with refresh; outer soft-warn handles ceiling)...")
    poll_start = time.time()
    _dup_logged = False  # #778: surface the mid-poll duplicate at most once per run

    while True:
        # ── Stop/Pause check per cycle ──
        if _controls.is_stop():
            log("[Phase3] STOP requested — aborting audio poll")
            break
        if _controls.is_pause():
            emit_event("pipeline_paused", phase=3)
            await _controls.wait_if_paused()
            if _controls.is_stop():
                break

        # ── #910: dead-browser check per cycle ──
        # Every per-step failure below is deliberately swallowed (reload,
        # screenshot retry, DOM read, CUA) — so a dead browser previously
        # looped "Audio still generating…" FOREVER (live 2026-07-06:
        # --login killed Chrome mid-audio at 22:19; 8 stale cycles of
        # "Screenshot failed → still generating" until a manual Stop at
        # 22:30, and the run never got the login-interrupt card). Detect
        # the dead browser explicitly and unwind so run_pipeline's failure
        # path classifies it: login interrupt → pause-at-checkpoint +
        # honest card; real crash → silent auto-retry from checkpoint.
        _poll_pg = getattr(browser, "page", None)
        try:
            _browser_dead = _poll_pg is None or _poll_pg.is_closed()
        except Exception:
            _browser_dead = True
        if _browser_dead:
            if _login_interrupt_active():
                _runtime.last_failure_kind = "login_interrupt"
                log("[Phase3] Browser closed by the login command mid-audio-poll "
                    "— pausing the run at its checkpoint", "WARN")
                raise RuntimeError(
                    "research browser closed by the login command (login interrupt)")
            _runtime.last_failure_kind = "browser_crash"
            log("[Phase3] Browser closed mid-audio-poll — unwinding for "
                "checkpoint recovery", "WARN")
            raise RuntimeError(
                "research browser closed mid-audio-poll (browser crash)")

        # Refresh page every cycle (NotebookLM doesn't always auto-update)
        try:
            await browser.page.reload(wait_until="domcontentloaded", timeout=15000)
            await asyncio.sleep(5)
        except Exception:
            pass

        # Mid-poll auth check — NotebookLM session can expire during the
        # audio window. Without this, CUA keeps clicking on a logged-out
        # page. #899: upgraded from a bare per-cycle login_required emit
        # (no pause request → wait_if_paused returned instantly, so it
        # re-carded EVERY cycle with no alert_id and no durable mirror) to
        # the work-tab login pause helper: one real pause, auto-resume when
        # the user signs back in, Skip/timeout ends the audio step cleanly.
        try:
            if await _work_tab_signed_out(browser.page, "notebooklm", "NotebookLM"):
                log("[Phase3] NotebookLM session expired mid-audio-poll — pausing on the notebook tab")
                _p3_poll_login = await _work_tab_login_pause(
                    browser.page, "notebooklm", 3, "NotebookLM",
                    work_url=notebook_url or "https://notebooklm.google.com")
                if _p3_poll_login in ("stop", "skipped"):
                    log(f"[Phase3] audio poll ending on login pause result: {_p3_poll_login}", "WARN")
                    break
                # 'ok' → signed back in on the notebook — keep polling (the
                # helper already reloaded the notebook to confirm).
        except Exception:
            pass

        # Mid-poll duplicate detection (2026-05-14). The post-generate
        # +5s invariant at :19518 only catches duplicates that render
        # immediately. In practice the misclick-fired default audio
        # can take 5-10 min to appear in the Studio panel — long after
        # the post-gen check has passed. Recount every poll cycle so
        # a duplicate caught mid-flight surfaces inside 3-4 min instead
        # of polling for the full audio window with a confused download
        # picker at the end.
        #
        # 3-min elapsed gate absorbs panel-render lag for the FIRST
        # card; without it a normal single-audio run could trip the
        # check on the first poll when the card is still pending.
        if (time.time() - poll_start) >= 180:
            _live_ready = await _count_nlm_audio_cards(browser.page)
            # A duplicate spawned by a misclick starts as a PLACEHOLDER and only
            # becomes an artifact-library-item minutes later, so a ready-only
            # count surfaces it long after the fact — or, if both are still in
            # flight, not at all. Counting both is safe here precisely because
            # the action is log-once-and-continue: no fail, no delete.
            _live_generating = await _count_nlm_audio_generating(browser.page)
            _live_cards = _live_ready + _live_generating
            if _live_cards > 1 and not _dup_logged:
                # #778 (2026-06-03): a duplicate is visible mid-poll. NO-DELETE
                # + never-fail-on-dup: do NOT fail_phase (the old behavior wedged
                # the no-audio retry loop on an unclearable state and Skip was
                # ignored). Log ONCE and keep polling — the resilient download
                # picker (_pick_nlm_audio_card) targets the requested card by
                # format + DOM order. Logged once so a long audio window doesn't
                # repeat the same WARN every poll cycle.
                _dup_logged = True
                log(f"[Phase3] Mid-poll: {_live_cards} audio cards "
                    f"({_live_ready} ready + {_live_generating} generating, "
                    f"duplicate) — continuing; resilient download will target "
                    f"the requested one (no-delete, no-fail)", "WARN")

        # DOM-first: read the audio card directly. Avoids CUA's
        # page-wide-chrome confusion where unrelated NLM panel
        # spinners triggered "still generating" answers even after
        # the audio itself was done. CUA still runs as fallback.
        dom_complete = await _check_audio_complete_dom(browser.page)
        if dom_complete:
            log("Audio generation complete ✓ (DOM-detected)")
            audio_done = True
            break

        # CUA fallback — strict: only "audio complete" counts.
        # 2026-05-14: prompt is length-aware so CUA looks at the SAME
        # card the generate step produced (not a hardcoded Long + Deep
        # Dive that doesn't exist for short/default runs).
        _audio_check_mission = make_prompt_audio_check(podcast_length)

        async def _audio_check_cua():
            return await agent_loop(cua_client, browser, _audio_check_mission,
                "Check: Has audio generation FINISHED? Is there a completed audio player "
                "with NO progress indicator? Answer 'audio complete' ONLY if fully done.",
                model=CUA_MODEL, max_iterations=3, verbose=verbose)

        # #839 act tier — STRICTLY READ_ONLY (#778): a single click on any audio
        # card here fires the DEFAULT-audio duplicate, so Vision may only READ
        # and return a verdict; any proposed action defers to CUA unexecuted.
        # The 'audio complete' marker is parsed from the returned text below in
        # every mode; DOM (_check_audio_complete_dom) above is authoritative.
        diag = await _shadow_observed_cua(
            browser.page, hotspot_id="audio-check", phase=3, platform="notebooklm",
            current_step="poll_audio_complete",
            context_hint="READ ONLY — do not click anything. Is there a COMPLETED audio "
                         "player with NO progress indicator/spinner? Say 'audio complete' "
                         "only if fully done, otherwise say it is still generating.",
            expected_outcome="an honest 'audio complete' verdict only when fully done",
            cua_coro_factory=_audio_check_cua,
            mission_prompt=_audio_check_mission,
            read_only=True) or {}
        diag_text = (diag.get("text") or "").lower()

        if "audio complete" in diag_text:
            if not dom_complete:
                # #757-B capture: CUA confirms complete but _check_audio_complete_dom
                # missed it — dump the COMPLETE-card markup (read-only) to pin it.
                await _dump_nlm_audio_dom(browser.page, "cua-complete-dom-missed")
            log("Audio generation complete ✓ (CUA-detected)")
            audio_done = True
            break

        elapsed_min = 5 + int((time.time() - poll_start) / 60)
        log(f"[Phase3] Audio still generating... ({elapsed_min}m total)")
        # Live narration tick — without this the FE dropdown sits on the
        # last pre-poll string ("Setting notebook to…") for the full audio
        # window. Match the P2 round-robin cadence.
        try:
            _len_key = (podcast_length or "default").lower()
            _typ_low, _typ_high = _AUDIO_TYPICAL_RANGE_MIN.get(
                _len_key, _AUDIO_TYPICAL_RANGE_MIN["default"])
            emit_event("agent_progress", phase=3, agent="notebooklm",
                       status="generating", stage="podcast",
                       progress=f"NotebookLM still generating audio overview… "
                                f"({elapsed_min}m total / {_typ_low}–{_typ_high}m typical)",
                       elapsedSec=elapsed_min * 60,
                       expectedMinutes=_typ_high)
        except Exception:
            pass
        interrupt = await _controls.interruptible_sleep(90, check_interval=10)
        if interrupt == "stop":
            log("[Phase3] STOP during poll wait — aborting")
            break
        if interrupt == "pause":
            emit_event("pipeline_paused", phase=3)
            await _controls.wait_if_paused()
            if _controls.is_stop():
                break

    # Download audio
    audio_path = None
    if audio_done:
        (queue_dir / "podcasts").mkdir(exist_ok=True)

        # Fix A (2026-05-27): re-anchor to THIS run's notebook before the
        # download agent_loop. Between generate and download the page can
        # drift (a stray CUA navigation, an NLM redirect, a recent-notebooks
        # click) and a drifted page surfaces a DIFFERENT notebook's audio
        # card — the verified root cause of a failed audio stream (the
        # download CUA saw two cards incl. a foreign prior-run one and
        # downloaded nothing). Re-assert the held notebook_url so the Studio
        # panel shows only this notebook's single card. No-op when already
        # anchored (happy path), so it can't disturb a correctly-placed page.
        try:
            _cur_url = await browser.current_url()
        except Exception:
            _cur_url = ""
        _want_nb = _nlm_notebook_id(notebook_url)
        if _want_nb and _want_nb != _nlm_notebook_id(_cur_url):
            log(f"[Phase3] Download re-anchor: page drifted to '{_cur_url[:70]}' — navigating back to this notebook", "WARN")
            try:
                await browser.navigate(notebook_url)
                await asyncio.sleep(5)
            except Exception as _ra_e:
                log(f"[Phase3] Download re-anchor navigate failed: {_ra_e}", "WARN")

        # #778 (2026-06-03): resilient download target selection. After the
        # Fix-A re-anchor, READ (never click) which audio card is the
        # user-requested one. On the happy single-card path the ordinal is
        # omitted → the download prompt is byte-identical to before. When a
        # duplicate slipped past prevention the picker resolves the target by
        # format + DOM order (duration is absent from the card) and the prompt
        # is told to download ONLY that entry — so a dup never blocks delivery.
        _pick = await _pick_nlm_audio_card(browser.page, podcast_length)
        _target_ord = _pick.get("target_ordinal") if _pick.get("count", 0) > 1 else None
        log(f"[Phase3] Download target: ordinal={_pick.get('target_ordinal')}/"
            f"{_pick.get('count')} (ambiguous={_pick.get('ambiguous')}, "
            f"{_pick.get('reason', '')})"
            + ("" if _target_ord else " — single card, default download"))
        # Cross-check guard: audio_done=True should mean a card is complete, but
        # the CUA-visual completion path can break the poll loop while cards are
        # still in-flight. If the picker found cards yet none is complete, WARN —
        # the download is best-effort; an empty grab routes to the bounded
        # no-audio retry loop (which is now Skip-aware). Never blocks delivery.
        if _pick.get("count", 0) > 0 and not _pick.get("complete", True):
            log(f"[Phase3] Download picker found no COMPLETE card "
                f"({_pick.get('count')} in-flight) — best-effort download, may recover via retry", "WARN")

        # Use Playwright download event to capture the file reliably
        download_future = asyncio.get_event_loop().create_future()

        async def _on_download(download):
            try:
                # Sanitize filename — special chars like $ break ffmpeg
                clean_name = re.sub(r'[^\w\s.-]', '', download.suggested_filename).strip() or "audio_overview.m4a"
                dest = queue_dir / "podcasts" / clean_name
                await download.save_as(str(dest))
                if not download_future.done():
                    download_future.set_result(dest)
                log(f"Audio downloaded via Playwright: {dest.name}")
            except Exception as e:
                log(f"Download save failed: {e}", "WARN")
                if not download_future.done():
                    download_future.set_result(None)

        browser.page.on("download", _on_download)

        emit_event("agent_progress", phase=3, agent="notebooklm",
                   status="downloading", stage="podcast",
                   progress="Downloading audio file from NotebookLM…")

        # ── DOM rung: open the audio card's ⋮ and click Download BY LABEL ──
        #
        # This existed and was wired to exactly one thing. `_nlm_open_audio_menu`
        # and `_nlm_menu_pick` were built for this menu — the deny-list comment
        # names the download case explicitly ("`Delete` sits two rows below
        # `Download`, so an off-by-two is not a failed download, it is a destroyed
        # one") — and then only Share ever called them. The download, the step that
        # actually blocks the pipeline, stayed vision-only: a model clicking a
        # coordinate, a 30s wait, and a Downloads-folder scan.
        #
        # 2026-08-09 is what that costs. The model reported "the download has been
        # initiated" and the menu did close, but no download event fired and no file
        # existed anywhere on disk. Thirty seconds later the DOM rung opened the very
        # same menu successfully for Share:
        #     [dom] p3 notebooklm.open_audio_menu: verified via=audio-card
        # The deterministic path was available the whole time and nothing called it.
        #
        # Same shape as every other rung here: DOM first, CUA only if it misses.
        # Never by index — `Delete` is two rows away, so an ordinal click is one
        # layout change from destroying the user's audio instead of saving it.
        _dl_via_dom = False
        try:
            _dl_menu = await _nlm_open_audio_menu(browser.page)
            if _dl_menu.get("verified"):
                _dl_pick = await _nlm_menu_pick(browser.page, want=("download",))
                # `blocked` is ADVISORY — the denied rows the picker filtered out
                # and skipped — and it is returned ALONGSIDE `clicked: true`. The
                # audio menu always contains Delete, so it is always non-empty.
                # Treating it as a failure (as the first version of this rung did)
                # meant the rung clicked Download, reported failure, and the visual
                # agent then clicked Download again: two files, one run. `clicked`
                # is the only field that says what happened. The share flow below
                # has always read it this way.
                if _dl_pick.get("blocked"):
                    log(f"[Audio] download menu skipped destructive row(s): "
                        f"{_dl_pick.get('blocked')}", "DEBUG")
                if _dl_pick.get("clicked"):
                    _dl_via_dom = True
                    log(f"[dom] p3 notebooklm.download_audio: verified "
                        f"via={_dl_pick.get('via')!r}")
                else:
                    log(f"[dom] p3 notebooklm.download_audio: missed "
                        f"({_dl_pick.get('reason', 'no Download row')}) — CUA will drive it",
                        "WARN")
                    await _nlm_close_dialogs(browser.page, label="Audio")
            else:
                log(f"[dom] p3 notebooklm.download_audio: menu not opened "
                    f"({_dl_menu.get('why', 'unknown')}) — CUA will drive it", "WARN")
        except Exception as _dl_dom_err:
            log(f"[dom] p3 notebooklm.download_audio: errored "
                f"({type(_dl_dom_err).__name__}) — CUA will drive it", "WARN")

        # ── did the click actually download something? ──
        #
        # Wait for EVIDENCE, then skip the vision agent. The Playwright `download`
        # event is NOT that evidence on its own: it has never once reached us from
        # NotebookLM — 2026-08-09 and again on 08-10, both logged its absence while
        # the finished file sat in Playwright's artifacts directory. Gating the skip
        # on the event alone therefore guarantees the agent runs after a perfectly
        # good DOM click, which is the second half of how one run produced two files.
        #
        # So the test is the event OR a settled file on disk — the same two channels
        # the collection step below already uses. `_is_settled` is load-bearing: a
        # file still growing is a download in flight, and calling it done is how the
        # fallback moves a partial file out from under Chrome.
        #
        # This does NOT return early, whatever it finds. Everything past the download
        # block still has to run — the mp3 transcode, the panel cleanup, and the
        # share-link extract the podcast delivery depends on. An early return here
        # would trade a missing file for a missing link: the same outage wearing a
        # different message.
        #
        # WHICH channel answered is kept, not just whether one did. The collection
        # step waits on the download event, and the event is the one that never
        # comes — so on the happy path that wait is a guaranteed 30 seconds of
        # nothing, after we have already held the finished file in our hand.
        _dl_seen = False
        _dl_evidence = ""
        if _dl_via_dom:
            _dl_deadline = time.time() + 25
            while time.time() < _dl_deadline:
                if download_future.done() and download_future.result() is not None:
                    _dl_seen, _dl_evidence = True, "event"
                    break
                try:
                    _cand, _, _ = _find_recent_audio(_audio_search_plan(browser))
                    if _cand is not None and _is_settled(_cand):
                        _dl_seen, _dl_evidence = True, "file"
                        break
                except Exception:
                    pass
                await asyncio.sleep(1.5)
            if _dl_seen:
                log("[Phase3] audio downloaded by the DOM rung — not running the visual agent")
            else:
                log("[dom] p3 notebooklm.download_audio: clicked but no file appeared "
                    "in 25s — falling through to the visual agent", "WARN")

        _stop_d, _task_d = start_narration_ticker(
            3, "notebooklm",
            "Downloading audio overview from NotebookLM",
            interval=20)
        try:
            # 2026-05-14: length-aware download prompt — CUA targets the
            # SAME card the generate step created (Brief / Deep Dive Default
            # / Long Deep Dive), not the hardcoded Long + Deep Dive that
            # would either not exist (short) or pick the wrong card if a
            # parallel Deep Dive misclick existed (default).
            _audio_dl_mission = make_prompt_audio_download(podcast_length, target_ordinal=_target_ord)

            async def _audio_download_cua():
                return await agent_loop(cua_client, browser,
                    _audio_dl_mission,
                    "Download the audio file.", model=CUA_MODEL, max_iterations=8, verbose=verbose)

            # #839 act tier: the page.on('download', _on_download) listener +
            # 30s Future + Downloads-folder fallback (registered ABOVE, torn
            # down below) are the real capture mechanism — the act path keeps
            # them intact and only drives the download click. #778: target ONLY
            # the requested card (target_ordinal), never another entry's
            # play/menu, never navigate away. 'abort:' is diagnostic-only below.
            # Skipped entirely when the DOM rung already produced the file. Not just
            # a saving: a second driver on a menu whose `Delete` row sits two below
            # `Download` is a real hazard, and re-clicking Download would leave a
            # duplicate for the dup-count guards to trip over.
            _dl_result = None if _dl_seen else await _shadow_observed_cua(
                browser.page, hotspot_id="audio-download", phase=3, platform="notebooklm",
                current_step="download_audio_overview",
                context_hint=("download the completed audio overview via its ⋮/three-dot "
                              "menu → Download (or a direct download icon)"
                              + (f" — target ONLY entry #{_target_ord} from the top"
                                 if _target_ord else "")
                              + ". Never click another entry's play/menu; never leave this notebook."),
                expected_outcome="the requested audio overview's .m4a file begins downloading",
                cua_coro_factory=_audio_download_cua,
                mission_prompt=_audio_dl_mission,
                act_timeout_s=120.0)
            # Fix A (2026-05-27): the download agent_loop return was previously
            # ignored, so the new "abort: not on notebook" guard would be
            # swallowed. Surface it in the log for diagnostics — the existing
            # no-file fail_phase below still handles the recovery.
            _dl_text = (_dl_result.get("text") or "").lower() if isinstance(_dl_result, dict) else ""
            if "abort:" in _dl_text:
                log(f"[Phase3] Download CUA reported abort: {_dl_text[:160]}", "WARN")
        finally:
            await stop_narration_ticker(_stop_d, _task_d)

        # Wait for the download event — unless a settled file on disk has already
        # answered the same question. NotebookLM has never delivered this event
        # (08-09 and 08-10 both logged its absence beside a complete file), so
        # waiting the full 30s on the one path where we KNOW the download finished
        # is 30s of dead time on every healthy run. Not zero: the event may still
        # be a tick behind the file, and if it lands, `audio_path` comes straight
        # from Playwright with no scan at all. When it doesn't, the timeout falls
        # into the very same scan that would have run at 30s, having found the same
        # file — the fallback below is unchanged and still owns every other path.
        _dl_wait_s = 0.5 if _dl_evidence == "file" else 30
        try:
            audio_path = await asyncio.wait_for(download_future, timeout=_dl_wait_s)
            # Track-B success-path observe (P3 audio download). Page still alive here
            # (before the download-listener teardown). Post-download screenshot, so
            # action agreement is noisier — boolean ground-truth, action-only scoring.
            if audio_path:
                _observe_dom_success(browser.page, hotspot_id="p3-audio-download", phase=3,
                                     platform="notebooklm", current_step="download_audio_overview",
                                     dom_ground_truth=_gt_from_box(None, label="audio download",
                                                                   scope="studio-panel"))
        except asyncio.TimeoutError:
            log("Download event not received — checking common download dirs...", "WARN")
            # Silent: the Downloads-folder scan below has its own fail_phase
            # if it also turns up empty.
            # Fallback: scan by CONTENT, not by extension — see `_find_recent_audio`.
            _found, _ext, _may_move = _find_recent_audio(_audio_search_plan(browser))
            if _found is not None and not _is_settled(_found):
                log(f"Audio candidate {_found.name} is still being written — "
                    f"leaving it alone", "WARN")
                _found = None
            if _found is not None:
                _suffix_ok = _found.suffix.lower() in (
                    ".m4a", ".m4b", ".mp3", ".wav", ".webm", ".ogg")
                dest = (queue_dir / "podcasts"
                        / (_found.name if _suffix_ok else _found.name + _ext))
                try:
                    # ⛔ COPY out of the user's Downloads, MOVE only out of
                    # Playwright's own artifacts directory. Taking a file from
                    # somebody's Downloads folder because it was recent and
                    # happened to be audio is not ours to do.
                    if _may_move:
                        shutil.move(str(_found), str(dest))
                    else:
                        shutil.copy2(str(_found), str(dest))
                    audio_path = dest
                    log(f"Audio recovered by content from {_found.parent.name} "
                        f"({_ext}, {dest.stat().st_size} bytes, "
                        f"{'moved' if _may_move else 'copied'}) — the download "
                        f"event never reached us")
                except Exception as _mv:
                    log(f"Audio found at {_found} but could not be taken: {_mv}",
                        "WARN")

        try:
            browser.page.remove_listener("download", _on_download)
        except Exception:
            pass

        # If we got here with audio_done=True but no audio_path, both the
        # Playwright download event AND the Downloads-folder scan failed.
        # That's a real error — surface it so the user knows Phase 5 will
        # skip and can decide whether to re-run or accept report-only.
        if not audio_path:
            fail_phase(3, "Couldn't save the audio file",
                       "NotebookLM finished the audio but we couldn't download it. Retry to try again, or Skip it.",
                       agent="notebooklm")

    # ── Transcode to a streamable mp3 (2026-07-23) ──
    # NotebookLM's .m4a keeps its moov atom at the end of the file, so a
    # cloud-hosted agent that STREAMS the URL can't start playback. Convert
    # to a plain CBR mp3 (progressively streamable everywhere) so EVERY agent
    # can stream it. Best-effort: a missing ffmpeg / failed encode delivers
    # the original .m4a unchanged. to_thread keeps the event loop (heartbeat)
    # ticking during the encode; reassigning audio_path means the duration
    # probe, Storage upload, Firestore audios doc, save_meta scan, and the
    # returned path all operate on the mp3. Downstream mime handling is
    # extension-driven (Storage content-type, /audio server, bridge), so no
    # other change is needed; old runs stay .m4a and still resolve correctly.
    if audio_path and audio_path.exists():
        audio_path = await asyncio.to_thread(_transcode_audio_to_mp3, audio_path)

    # Strict-keep cleanup (moved 2026-05-02). Was inside the poll loop at
    # the audio-complete detection point — but cleanup-before-download is
    # structurally fragile: if the post-cleanup invariant fail_phased OR
    # cleanup's DOM manipulation re-rendered the panel before the
    # download click landed, the download below never ran. Cleanup
    # post-download means we already have the file on disk; cleanup then
    # prepares the panel for the share-link extract that follows. The
    # invariant degrades from fail_phase to log-warn — share-link extract
    # uses a notebook-level API that doesn't depend on card count.
    if audio_done and audio_path:
        # #767 (2026-06-03): the auto-delete cleanup
        # (_cleanup_nlm_keep_requested_audio) is NO LONGER CALLED — it actively
        # clicked Delete on cards, which violates the hard no-delete constraint
        # (NotebookLM is detect-and-fail_phase only, never delete a card). It was
        # a silent no-op anyway (its own broken selectors matched nothing); and
        # now that the dup-count guards actually work, a duplicate is caught and
        # surfaced upstream (pre-flight / post-generate / mid-poll) BEFORE we
        # reach here. This block is now a READ-ONLY invariant check.
        try:
            await asyncio.sleep(2)  # let the panel settle after the download
            dd_count = await _count_nlm_deep_dive_cards(browser.page)
            total_count = await _count_nlm_audio_cards(browser.page)
            log(f"[Phase3] Post-cleanup inventory ({podcast_length}): {dd_count} Deep Dive / {total_count} total audio card(s)")
            if total_count == 0:
                # #757-B capture: audio is done + downloaded, so a complete card
                # must exist — 0 means the counter missed it. Dump (read-only).
                await _dump_nlm_audio_dom(browser.page, "post-cleanup")
            # Invariant (#767 → relaxed #778, 2026-06-03): TOTAL-count, and now
            # >= 1 (was == 1). The new NLM markup no longer surfaces a "Deep
            # Dive" label, so dd_count is telemetry-only. Under #778 a DUPLICATE
            # (total > 1) is NO LONGER a failure: the dup-count guards are
            # demoted to log+continue and the resilient download picker already
            # targeted the requested card — the right audio is on disk. So the
            # only anomaly worth a WARN here is total_count == 0 (the counter
            # missed a card that must exist), which the read-only dump above
            # captures. >= 1 (including a tolerated dup) is healthy.
            _ok = (total_count >= 1)
            if not _ok:
                log(f"[Phase3] Post-cleanup invariant warning ({podcast_length}): {dd_count} Deep Dive + {total_count} total — proceeding with share-link extract anyway since audio is already on disk", "WARN")
        except Exception as _ie:
            log(f"[Phase3] Post-cleanup invariant check failed: {_ie}", "WARN")

    audio_stored_url = ""

    # ── The audio SHARE page: REMOVED 2026-08-28 (stretch 6.6C) ──
    #
    # ⛔⛔ IT SPENT CUA CALLS TO PRODUCE A URL ITS OWN FALLBACK ALREADY HELD.
    # The block that stood here opened the audio card's ⋮ menu, picked Share,
    # set "Anyone with the link" and read the URL back — and its documented
    # fallback (below the read, since #778) was: "NLM emits the SAME
    # /notebook/{id} URL whether you click Share notebook or the audio's
    # three-dot Share", falling through to `current_url()` and then to
    # `notebook_url`. So on the healthy path it re-derived the notebook link we
    # were already holding, and on the unhealthy path it returned that link
    # anyway. `links.audio` and `links.notebooklm` carried the same string.
    #
    # ⛔ THE PLAYABLE FILE IS `links.audio_file`, WRITTEN BELOW, and that is what
    # every consumer actually reads: FE-P4's video gate, the /shared/podcast
    # player, and — since this wave — the in-chat Play button, which used to
    # render off the row this block emitted while resolving its audio from
    # Storage regardless.
    #
    # ⛔ `_nlm_open_audio_menu` / `_nlm_menu_pick` STAY. Their other caller is the
    # audio DOWNLOAD above, which is the step that produces the file this phase
    # now completes on — and `_NLM_MENU_DENY` protects exactly that caller
    # ("Delete" sits two rows below "Download").

    # ── Sync to Firebase Storage + Firestore audios subcollection ──
    # Upload the audio file so the Vercel Podcasts page can stream it
    # without needing the local backend to be reachable. Duration via
    # ffprobe for nice display (M:SS). Best-effort — pipeline continues
    # even if sync fails.
    if audio_path and audio_path.exists():
        try:
            # B2 (2026-05-01): to_thread so the asyncio event loop (and
            # _heartbeat_loop on it) keeps ticking — a blocking probe ate
            # 1/3 of the 15s offline threshold. 2026-07-12: probing goes
            # through _audio_duration_sec (tinytag primary — pure Python,
            # pip-installed, works on a clean machine with no ffmpeg;
            # ffprobe fallback). durationSec: 0 froze the FE player's
            # progress bar (seek clamps to 0), so a failed probe WARNs.
            dur_sec = await asyncio.to_thread(_audio_duration_sec, audio_path)
            if dur_sec <= 0:
                log("[Phase3] audio duration probe failed (tinytag + ffprobe) "
                    "— writing durationSec=0; FE will self-heal from media "
                    "metadata", "WARN")
            # B2: Firebase Storage upload (50-100MB on slow uplinks) was the
            # biggest single blocker — easily blew past the 15s offline window.
            audio_url = await asyncio.to_thread(upload_audio_to_storage, audio_path)
            # Use the filename stem as doc id so re-runs upsert in place
            # instead of stacking duplicates. Display name = research
            # title from Firestore (set by FE's /api/title early in P1)
            # so the Podcasts page shows one human-readable title instead
            # of the auto-generated underscore .m4a filename. If the
            # Firestore title isn't set (rare P3-before-P1-write race),
            # smart_title falls back to a stem-derived topic with
            # underscores swapped for spaces — still readable.
            display_name = smart_title(audio_path.stem.replace("_", " "))
            # B2: sync Firestore .set() — small payload but on slow links
            # still worth offloading.
            await asyncio.to_thread(save_audio_to_firestore,
                                    audio_path.stem, display_name, dur_sec, audio_url)
            # FE-P4 cutover (2026-05-10): also pin the Storage URL into
            # research.links.audio_file so the FE-P4 trigger
            # (readResearchForP4 → /api/uploadYouTube) can fetch the
            # downloadable audio without query-walking the audios
            # subcollection. links.audio stays as the NLM share URL
            # (page, not a media file) — the Doc still renders that as
            # "Audio Overview"; links.audio_file is purely for the FE
            # YouTube upload step.
            if audio_url:
                update_link_in_firestore("audio_file", audio_url,
                                         label="Podcast Audio (Storage)", phase=3,
                                         verified=True)
                # ⛔⛔ RETURNED, NOT JUST WRITTEN. Until 2026-08-28 this URL was
                # written to Firestore and then dropped on the floor — the return
                # below carried only `audio_path`, so the phase's own completion
                # gate could not see whether the bytes had actually reached
                # Storage. A local file with a failed upload emitted a green
                # phase_complete:3 and a "Podcast ready" notice, while FE-P4 read
                # `links.audio_file`, found nothing, and silently skipped the
                # video. Completion and delivery disagreed about the same run.
                audio_stored_url = audio_url
            # Storage upload is best-effort — local playback still works via
            # the backend, and Phase 5 can still upload to YouTube from the
            # local file. Warn (not error) if it failed.
            if not audio_url:
                log("[Phase3] Firebase Storage upload failed — audio still saved locally", "WARN")
        except Exception as e:
            log(f"Audio Firestore/Storage sync failed: {e}", "WARN")

    # ⛔ `audio_stored_url` IS THE COMPLETION ARTEFACT. It is non-empty only when
    # `upload_audio_to_storage` returned a URL, which means firebasestorage
    # answered 200 AND handed back a download token — i.e. the podcast is where
    # every consumer looks for it. `audio_path` alone proves only that a file is
    # on the research computer, and on the Playwright-download path it is set
    # from `download.save_as()` with no size, format or settle check at all.
    return {"audio_path": audio_path, "audio_stored_url": audio_stored_url}


async def _check_audio_generating(page):
    """Check if NotebookLM is generating audio."""
    try:
        return await page.evaluate("""() => {
            const text = document.body.innerText.toLowerCase();
            return text.includes('generating') || text.includes('creating audio') || text.includes('in progress');
        }""")
    except Exception:
        return False


async def _check_audio_complete_dom(page) -> bool:
    """Detect a completed NLM audio overview by reading the Studio panel DOM.
    Returns True only when a generated audio card is present AND the
    "Generating Audio Overview" placeholder is gone. Used as a DOM-first
    check before CUA — avoids the page-wide-chrome false negatives where CUA
    reports "still generating" because some unrelated NLM panel still shows a
    spinner while the audio itself is done.

    Markup pinned from the #757-B dom-dump (2026-06-03): the OLD selectors
    gated on a present <audio> element + [role=progressbar] inside a
    [role=article]/[class*=audio-card] card — NONE of which exist in the live
    panel, so this DOM-complete check could NEVER fire (CUA carried completion
    detection alone). The real panel renders a "Generating Audio Overview…"
    placeholder in .artifact-library-container while in flight (with NO
    artifact-library-item yet), then an <artifact-library-item> bearing the
    "audio_magic_eraser" icon ligature + the real title once done.
    """
    try:
        return await page.evaluate("""() => {
            // Still generating → the placeholder is present and no audio card
            // has materialized. Cross-checks _check_audio_generating's
            // body-wide read but scoped to the artifact container.
            const cont = document.querySelector(
                'artifact-library, .artifact-library-container') || document.body;
            const contText = (cont.innerText || cont.textContent || '');
            if (/generating audio overview/i.test(contText)) return false;
            // Done → at least one visible audio artifact-library-item.
            const items = document.querySelectorAll('artifact-library-item');
            for (const el of items) {
                if (el.offsetParent === null) continue;
                if ((el.innerText || el.textContent || '').includes('audio_magic_eraser')) return true;
            }
            return false;
        }""") or False
    except Exception:
        return False


async def _dump_nlm_audio_dom(page, ctx: str) -> None:
    """#757-B capture (READ-ONLY — never clicks): when _count_nlm_audio_cards
    reads 0 at a point where a card MUST exist (post-generate / CUA-complete /
    post-cleanup), dump the live NotebookLM Studio-panel DOM structure so the
    counter selectors (_count_nlm_audio_cards / _check_audio_complete_dom) can be
    pinned from REAL markup instead of the current guessed selectors that never
    match live NLM (every count=0 → all dup-guards are dead no-ops). Fires ONLY
    on the anomalous-zero path, so a healthy run never logs it. Bounded output,
    fully exception-safe, WARN so it surfaces. Grep the next E2E for
    '[#757-B dom-dump'. This is the sole blocker on repairing the counters.
    """
    try:
        dump = await page.evaluate(r"""() => {
            const trunc = (s, n) => (s == null ? '' : s.toString())
                .replace(/\s+/g, ' ').trim().slice(0, n);
            const attrsOf = (el) => {
                const o = {};
                for (const a of (el.attributes || [])) {
                    if (a.name === 'class' || a.name === 'style') continue;
                    if (a.name === 'id' || a.name === 'role'
                        || a.name.indexOf('data-') === 0
                        || a.name.indexOf('aria-') === 0) {
                        o[a.name] = trunc(a.value, 40);
                    }
                }
                return o;
            };
            const brief = (el) => el ? {
                tag: (el.tagName || '').toLowerCase(),
                cls: trunc((el.className && el.className.toString)
                    ? el.className.toString() : '', 80),
                attrs: attrsOf(el),
            } : null;
            // What the CURRENT (broken) selectors actually see — should be 0.
            const curPanel = document.querySelector(
                '[aria-label*="Studio" i], [data-testid*="studio" i], aside');
            const curCand = (curPanel || document.body).querySelectorAll(
                '[role="article"], [role="listitem"], [class*="audio-card"], '
                + '[class*="AudioCard"], [data-testid*="audio"], '
                + '[data-testid*="overview-item"]');
            // Find the real audio card(s) by CONTENT / structure, doc-wide, and
            // record each one's ancestor chain so the true container selectors
            // (class / data-testid / role) are visible.
            const kw = /(audio overview|deep dive|conversation|discussion|podcast)/i;
            const seen = new Set();
            const picked = [];
            const add = (el) => {
                if (!el || seen.has(el) || el.offsetParent === null) return;
                seen.add(el); picked.push(el);
            };
            // Cheap DIRECT global selectors first (no per-element subtree scans).
            document.querySelectorAll('audio, [role="progressbar"]').forEach((node) => {
                if (picked.length >= 6) return;
                let c = node;                                      // climb to a visible container
                for (let i = 0; i < 4 && c && c.offsetParent === null; i++) c = c.parentElement;
                add(c || node);
            });
            // Keyword scan — regex on text ONLY (O(n); no querySelector per element).
            if (picked.length < 6) {
                for (const el of document.querySelectorAll('*')) {
                    if (picked.length >= 6) break;
                    if (el.offsetParent === null) continue;        // visible only
                    const txt = trunc(el.textContent, 200);
                    if (txt.length < 120 && kw.test(txt)) add(el); // a label, not prose
                }
            }
            // Subtree checks (querySelector) run on the <= 6 kept anchors only.
            const anchors = picked.slice(0, 6).map((el) => {
                const chain = [];
                let p = el;
                for (let i = 0; i < 7 && p && p !== document.body; i++) {
                    chain.push(brief(p));
                    p = p.parentElement;
                }
                // A keyword anchor is usually a leaf TITLE node whose OWN subtree
                // holds neither <audio> nor the progress bar (those are siblings
                // under the card container) — so its self-level hasAudioEl/isProg
                // read false even on a complete card. Climb to the nearest
                // ancestor (incl self) that actually contains one, and report THAT
                // as cardEl so the true card container + state are unambiguous.
                let cardEl = el;
                for (let i = 0; i < 7 && cardEl && cardEl !== document.body; i++) {
                    if (cardEl.querySelector('audio')
                        || cardEl.querySelector('[role="progressbar"]')) break;
                    cardEl = cardEl.parentElement;
                }
                const cardHasAudio = !!(cardEl && cardEl.querySelector('audio'));
                const cardProg = !!(cardEl && cardEl.querySelector('[role="progressbar"]'));
                return {
                    text: trunc(el.textContent, 60),
                    hasAudioEl: !!el.querySelector('audio'),       // leaf-anchor only
                    isProg: el.getAttribute('role') === 'progressbar'
                        || !!el.querySelector('[role="progressbar"]'),
                    self: brief(el),
                    // climbed card container — the load-bearing fields for pinning
                    cardEl: (cardEl && cardHasAudio) || cardProg ? brief(cardEl) : null,
                    cardHasAudioEl: cardHasAudio,
                    cardIsProg: cardProg,
                    chain,
                };
            });
            return JSON.stringify({
                url: trunc(location.href, 90),
                curPanelTag: curPanel ? (curPanel.tagName || '').toLowerCase() : null,
                curPanelAttrs: curPanel ? attrsOf(curPanel) : null,
                curSelectorMatches: curCand.length,
                anchorsFound: anchors.length,
                anchors,
            });
        }""")
        log(f"[Phase3][#757-B dom-dump:{ctx}] {dump}", "WARN")
    except Exception as _e:
        log(f"[Phase3][#757-B dom-dump:{ctx}] capture failed: {_e}", "WARN")


def _nlm_notebook_id(url: str) -> str:
    """Extract the NotebookLM notebook id from a /notebook/{id} URL.
    Used to detect CUA drift off the run's own notebook before the audio
    download (Fix A 2026-05-27): a drifted page surfaces a DIFFERENT
    notebook's audio card and breaks the download target. Returns "" when
    no id is present (e.g. the page navigated off NotebookLM entirely)."""
    try:
        m = re.search(r"/notebook/([\w-]+)", url or "")
        return m.group(1) if m else ""
    except Exception:
        return ""


# ── Audio-card invariant helpers (2026-05-02; selectors repaired #767 2026-06-03) ──
# Pure READ helpers used to enforce "exactly one audio overview" without ever
# clicking or deleting. Pair with the pre-flight check before agent_loop and the
# post-generate / mid-poll checks — all fail_phase loud if the count is wrong,
# letting the user clean up manually (per the hard no-delete constraint).
#
# _count_nlm_audio_cards / _count_nlm_deep_dive_cards / _check_audio_complete_dom
# all count the SAME population — visible <artifact-library-item> elements
# whose text carries the "audio_magic_eraser" Material-icon ligature — pinned
# from the #757-B dom-dump (2026-06-03). The OLD guessed selectors
# ([role=article]/[class*=audio-card]/[data-testid*=audio] + an <audio> element +
# [role=progressbar]) matched NOTHING in the live Studio panel, so every count
# read 0 and every dup-guard was a dead no-op. If NotebookLM ships a Studio
# redesign that drops the artifact-library-item tag or the audio_magic_eraser
# ligature (e.g. re-renders the icon as an SVG / CSS ::before, where the literal
# string leaves both innerText AND textContent), all three break together and
# revert to 0 — fail-OPEN (healthy runs proceed, dups slip) — and the read-only
# _dump_nlm_audio_dom on the zero-path is the canary to re-pin them.
#
# _count_nlm_audio_generating counts a DIFFERENT population on purpose: the
# in-flight placeholder, which by construction has no artifact-library-item yet.
# The two are complements, not variants — "how many audio overviews exist right
# now" is their sum, and reading either one alone is what made P3 report zero
# cards with a generation visibly running.

async def _count_nlm_audio_cards(page) -> int:
    """Count visible READY audio-overview cards in the NLM Studio panel.

    READY, not total. This docstring used to promise "in-flight + completed",
    and the markup makes that impossible: while NotebookLM is generating there
    is a "Generating Audio Overview…" placeholder and NO <artifact-library-item>
    at all — the item is what appears when generation FINISHES. So this returned
    0 with an audio overview visibly generating on screen, and the post-generate
    log said "0 audio card(s)" while the panel said otherwise.

    In-flight entries are counted by _count_nlm_audio_generating(); callers that
    mean "how many audio overviews exist right now" need both. Read-only — never
    clicks anything. Returns 0 on any DOM exception.
    """
    try:
        return await page.evaluate("""() => {
            // Real NLM Studio markup (pinned from the #757-B dom-dump,
            // 2026-06-03): a generated audio is an <artifact-library-item>
            // whose text carries the "audio_magic_eraser" Material-icon
            // ligature. The "Audio Overview" CREATE button is a
            // <basic-create-artifact-button> (NOT an artifact-library-item),
            // so scoping the count to artifact-library-item structurally
            // excludes it — even though its text ALSO contains
            // "audio_magic_eraser". Other artifact types (study guide, mind
            // map, …) are artifact-library-item too but carry a DIFFERENT icon
            // ligature, so the audio_magic_eraser check keeps the count
            // audio-only. The OLD selectors
            // ([role=article]/[class*=audio-card]/[data-testid*=audio]) matched
            // NOTHING in the live panel — every count read 0, so every dup-guard
            // was a dead no-op (#757-B).
            const items = document.querySelectorAll('artifact-library-item');
            let count = 0;
            items.forEach((el) => {
                if (el.offsetParent === null) return;
                const t = (el.innerText || el.textContent || '');
                // Excluded so this counter and _count_nlm_audio_generating stay
                // DISJOINT. Callers add them, and today nothing satisfies both
                // (a generating entry has no artifact-library-item at all). The
                // day NotebookLM renders one as a skeleton row it would, and
                // the sum would report one audio overview as two — a false
                // duplicate WARN, from the very fix that exists to stop the
                // count disagreeing with the screen.
                if (/generating audio overview/i.test(t)) return;
                if (t.includes('audio_magic_eraser')) count++;
            });
            return count;
        }""") or 0
    except Exception:
        return 0


async def _count_nlm_audio_generating(page) -> int:
    """Count audio overviews currently GENERATING in the NLM Studio panel.

    The population _count_nlm_audio_cards structurally cannot see: while in
    flight NotebookLM renders a "Generating Audio Overview…" placeholder inside
    .artifact-library-container and no <artifact-library-item> exists yet
    (pinned in _check_audio_complete_dom from the #757-B dom-dump).

    Counted by finding the DEEPEST elements carrying that phrase rather than by
    a tag name, because the placeholder's tag is not in the corpus and guessing
    one is how the previous generation of these selectors came to match nothing.
    Deepest-only matters: every ancestor of a placeholder also contains the
    phrase, so counting all matches would multiply one placeholder by its depth.

    Falls back to 1 when the container names the placeholder but no single
    element resolves as its owner — the phrase being present is already proof
    that at least one is generating, and reporting 0 there would reproduce
    exactly the contradiction this helper exists to remove.

    Read-only. Returns 0 on any DOM exception.
    """
    try:
        return await page.evaluate("""() => {
            const cont = document.querySelector(
                'artifact-library, .artifact-library-container') || document.body;
            const RE = /generating audio overview/i;
            if (!RE.test(cont.innerText || cont.textContent || '')) return 0;
            let n = 0;
            for (const el of cont.querySelectorAll('*')) {
                if (el.offsetParent === null) continue;
                if (!RE.test(el.innerText || el.textContent || '')) continue;
                let deeper = false;
                for (const kid of el.children) {
                    if (RE.test(kid.innerText || kid.textContent || '')) {
                        deeper = true;
                        break;
                    }
                }
                if (!deeper) n++;
            }
            return n || 1;
        }""") or 0
    except Exception:
        return 0


async def _count_nlm_deep_dive_cards(page) -> int:
    """Count visible Deep Dive audio cards specifically (TELEMETRY ONLY).

    Lockstep with _count_nlm_audio_cards (artifact-library-item + the
    audio_magic_eraser ligature), additionally requiring the card text to name
    "deep dive". CAVEAT (#767, 2026-06-03): the new NLM artifact title is the
    generated topic (e.g. "The Genetic Tragedy of Golden Retrievers"), NOT a
    "Deep Dive" label — so this typically reads 0 even on a real Deep Dive. It
    is kept for the post-cleanup LOG line only; the invariant no longer gates on
    it (Format + Length are enforced upstream by make_prompt_audio_generate).
    """
    try:
        return await page.evaluate("""() => {
            const items = document.querySelectorAll('artifact-library-item');
            let count = 0;
            items.forEach((el) => {
                if (el.offsetParent === null) return;
                const t = (el.innerText || el.textContent || '');
                if (t.includes('audio_magic_eraser') && /deep dive/i.test(t)) count++;
            });
            return count;
        }""") or 0
    except Exception:
        return 0


# #778 (2026-06-03): one-time-per-process canary gate. The customize-open DOM
# dump fires on the FIRST fresh-run Generate after a worker (re)start to confirm
# the arrow-click actually opened the panel + capture the (un-pinned) length /
# Generate controls — without spamming a WARN on every healthy run.
_NLM_CANARY_STATE: set = set()


async def _open_nlm_audio_customize(page) -> bool:
    """#778 PREVENTION (the deterministic dup-kill): DOM-click the Audio
    Overview *Customise* ARROW to open the customize panel WITHOUT ever clicking
    the card body. Clicking the card BODY fires NotebookLM's one-click DEFAULT
    audio = the unwanted duplicate (the confirmed dup source — the CUA agent,
    hunting for the open-affordance, would sometimes hit the body instead of the
    arrow). The arrow is a SEPARATE control, pinned from the user's console dump
    (2026-06-03): `button[aria-label="Customise Audio Overview"]` (British
    spelling; also bears data-edit-button-type="1" + class "edit", nested in
    `basic-create-artifact-button > div[aria-label="Audio Overview"]`).

    Defensive selector chain (most→least specific), spelling/locale-tolerant.
    Clicks the FIRST visible match. Returns True if a click landed (the caller
    still lets the CUA prompt confirm the panel actually opened — its step 5
    re-finds the gear if not), False if no arrow was found (caller falls open to
    the full CUA flow, whose own #757-A guardrails forbid the card body).

    READ-ONLY except for the single arrow .click(): never touches the card body,
    never opens a menu, never deletes.
    """
    try:
        return await page.evaluate(r"""() => {
            const isVis = (el) => el && el.offsetParent !== null;
            const sels = [
                'button[aria-label="Customise Audio Overview"]',
                'button[aria-label="Customize Audio Overview"]',
                'basic-create-artifact-button button[data-edit-button-type="1"]',
                'basic-create-artifact-button button.edit',
            ];
            for (const s of sels) {
                const el = document.querySelector(s);
                if (isVis(el)) { el.click(); return true; }
            }
            // Spelling/locale-tolerant fallback: a BUTTON (never the card body)
            // whose aria-label names a custom* audio control. Covers
            // "Customise"/"Customize" and minor future label tweaks.
            const btns = document.querySelectorAll(
                'basic-create-artifact-button button[aria-label], button[aria-label]');
            for (const b of btns) {
                if (!isVis(b)) continue;
                const lab = (b.getAttribute('aria-label') || '').toLowerCase();
                if (lab.indexOf('ustom') !== -1 && lab.indexOf('udio') !== -1) {
                    b.click(); return true;
                }
            }
            return false;
        }""") or False
    except Exception:
        return False


async def _pick_nlm_audio_card(page, podcast_length: str = "long") -> dict:
    """#778 RESILIENT DOWNLOAD (the guaranteed net): READ-ONLY picker that
    chooses WHICH audio card to download when more than one is visible (a
    duplicate slipped past prevention). NEVER clicks, NEVER opens a menu, NEVER
    deletes (the hard no-delete constraint). Scopes to the SAME population as
    _count_nlm_audio_cards — visible <artifact-library-item> carrying the
    "audio_magic_eraser" Material-icon ligature.

    Duration is NOT in the card text (confirmed user dump 2026-06-03: a completed
    card reads "audio_magic_eraser <Title> Deep dive · N sources · <ago> ..." —
    no MM:SS / "N min" token), so the pick uses FORMAT (Brief vs Deep dive, which
    IS in the text) + DOM order:
      - short        → the first BRIEF card (text lacks "deep dive"); falls back
                       to the first complete card if no Brief label is present.
      - long/default → the LAST complete Deep-dive card. The misclick default
                       fires FIRST (so completes first) → the user-requested
                       length is typically the LATER card. Best-effort;
                       ambiguous=True whenever >1 Deep-dive card exists (they are
                       indistinguishable by text).

    Returns {count, target_ordinal (1-based, top-down DOM order), complete,
    ambiguous, reason, snippet}. Best-effort and exception-safe: on any
    uncertainty it STILL returns a usable ordinal (never raises, never blocks the
    download) — Part A prevention is the real guarantee; this is the safety net.
    """
    try:
        info = await page.evaluate(r"""() => {
            const items = Array.from(document.querySelectorAll('artifact-library-item'))
                .filter((el) => el.offsetParent !== null
                    && ((el.innerText || el.textContent || '').includes('audio_magic_eraser')));
            const cards = items.map((el, i) => {
                const t = (el.innerText || el.textContent || '');
                const low = t.toLowerCase();
                return {
                    ordinal: i + 1,                                   // 1-based DOM order
                    isDeepDive: low.indexOf('deep dive') !== -1,
                    isBrief: low.indexOf('brief') !== -1,
                    // in-flight cards still show the "Generating Audio Overview…"
                    // text; a completed card does not.
                    generating: /generating audio overview/i.test(t),
                    snippet: t.replace(/\s+/g, ' ').trim().slice(0, 80),
                };
            });
            return { count: cards.length, cards };
        }""")
    except Exception as _e:
        return {"count": 0, "target_ordinal": 1, "complete": False,
                "ambiguous": False, "reason": f"evaluate_failed:{type(_e).__name__}",
                "snippet": ""}

    info = info or {}
    cards = info.get("cards") or []
    count = info.get("count", len(cards))
    if not cards:
        return {"count": 0, "target_ordinal": 1, "complete": False,
                "ambiguous": False, "reason": "no_cards", "snippet": ""}

    # #778 cross-check hardening: select ONLY from COMPLETE cards whenever any
    # complete card exists, so the picker can NEVER target an in-flight card —
    # even if a future NLM markup change starts rendering generating cards as
    # artifact-library-items (today they render as a separate "Generating Audio
    # Overview…" placeholder with no item, so this is belt-and-suspenders). Only
    # when NOTHING is complete (a CUA-visual false-complete broke the poll loop
    # early) do we fall back to all cards, flagged complete=False so the caller
    # can WARN — the download will then best-effort and, if it grabs nothing,
    # the bounded no-audio retry loop recovers.
    complete_cards = [c for c in cards if not c.get("generating")]
    cpool = complete_cards or cards
    _all_generating = not complete_cards
    length = (podcast_length or "long").lower()

    if length == "short":
        # Prefer an explicit "Brief" card; else any non-Deep-Dive card (the
        # Brief can render before its label); else the first card. The requested
        # short audio is Brief and the misclick default is Deep Dive, so
        # excluding Deep Dive isolates the Brief.
        explicit_brief = [c for c in cpool if c.get("isBrief")]
        non_dd = [c for c in cpool if not c.get("isDeepDive")]
        cand = explicit_brief or non_dd or cpool
        target = cand[0]
        reason = ("short→explicit Brief card" if explicit_brief
                  else "short→first non-deep-dive card" if non_dd
                  else "short→first card (no Brief label found)")
    else:
        # long/default → the LAST complete Deep-dive card. The dominant residual
        # dup vector (a fail-open CUA body-misclick during the OPEN step) fires
        # the default FIRST, so the user-requested card completes LATER → last.
        # Best-effort + ambiguous when >1 (text can't distinguish two Deep
        # Dives); worst case streams a valid complete Deep-dive podcast.
        deep = [c for c in cpool if c.get("isDeepDive")]
        cand = deep or cpool
        target = cand[-1]
        reason = f"{length}→last deep-dive card"

    return {
        "count": count,
        "target_ordinal": target["ordinal"],
        "complete": not target.get("generating", False),
        "ambiguous": bool(len(cand) > 1 or count > 1),
        "reason": (reason + " [all-generating: no complete card yet]") if _all_generating else reason,
        "snippet": target.get("snippet", ""),
    }


async def _cleanup_nlm_keep_requested_audio(page, podcast_length: str = "long") -> dict:
    """⚠️ DEAD / UNCALLED since #767 (2026-06-03) — DO NOT RE-WIRE. This
    function actively clicks Delete on Studio cards, which VIOLATES the hard
    NotebookLM no-delete constraint (detect-and-fail_phase only, never delete a
    card). It was already a silent no-op (its selectors never matched live NLM);
    duplicate handling is now owned by the working dup-count fail_phase guards
    (pre-flight / post-generate / mid-poll). Retained only as reference for the
    old length-aware keep logic; slated for full removal under #771 (prod-grade
    cleanup). If you ever need NLM dedup, it MUST be detect-and-surface, never a
    delete.

    Strict-keep cleanup. Identifies the SINGLE NLM Studio audio card
    that matches the user-requested `podcast_length` and deletes every
    other audio card around it. If the keep target is missing or
    ambiguous, deletes NOTHING and reports the skip reason — the caller
    can then surface the issue to the user rather than risk nuking the
    real audio.

    2026-05-14: length-aware. Previously hardcoded to "long Deep Dive"
    which broke when the user picked "default" / "short" via the chat
    long-press. Length-specific keep predicates below.

    Length predicates:
      - "long":    hasDeepDive AND (hasLong OR durationMin >= 15)
      - "default": SKIP — both the requested Deep-Dive-Default and the
                   misclick-fired default audio are Deep Dive, so we
                   can't distinguish them by text. Log + warn instead
                   of risking the wrong delete.
      - "short":   NOT hasDeepDive AND durationMin < 10
                   (Brief format ≈ 3-5min; auto-fired default is also
                   Deep Dive so the !hasDeepDive predicate isolates the
                   Brief target cleanly when present.)

    Safety rails:
      - keep_candidates count must be EXACTLY 1; 0 → skip, >1 → skip.
      - delete only cards whose data-cleanup-idx differs from the keep.
      - log every intended deletion via emit_event for audit.
      - caller is expected to verify post-cleanup card count separately;
        this function reports `remaining_after` from a fresh count call
        so the caller doesn't have to re-scan.

    Returns a dict with keys:
      scanned, kept_idx, deleted, remaining_after, skipped_reason,
      podcast_length (echoed for telemetry).
    """
    result = {
        "scanned": 0,
        "kept_idx": None,
        "deleted": 0,
        "remaining_after": None,
        "skipped_reason": None,
        "podcast_length": podcast_length,
    }

    # "default" length: indistinguishable from the misclick-fired audio.
    # Skip cleanup entirely rather than risk a wrong delete — the caller
    # surfaces this via the post-cleanup invariant check.
    if podcast_length == "default":
        result["skipped_reason"] = "default_length_indistinguishable"
        result["remaining_after"] = await _count_nlm_audio_cards(page)
        try:
            emit_event("nlm_cleanup_skipped", phase=3,
                       reason="default_length_indistinguishable",
                       podcast_length=podcast_length)
        except Exception:
            pass
        return result

    try:
        cards = await page.evaluate(f"""() => {{
            const podcastLength = {json.dumps(podcast_length)};
            const panel = document.querySelector(
                '[aria-label*="Studio" i], [data-testid*="studio" i], aside'
            ) || document.body;
            const candidates = panel.querySelectorAll(
                '[role="article"], [role="listitem"], '
                + '[class*="audio-card"], [class*="AudioCard"], '
                + '[data-testid*="audio"], [data-testid*="overview-item"]'
            );
            const out = [];
            candidates.forEach((el, i) => {{
                if (el.offsetParent === null) return;
                const t = (el.innerText || '').toLowerCase();
                const isAudio = t.includes('audio overview')
                    || t.includes('conversation') || t.includes('discussion')
                    || t.includes('podcast');
                const isConfigTile = t.includes('customize');
                if (!isAudio || isConfigTile) return;
                // Length-aware keep predicate (2026-05-14):
                //   "long"  → deep dive AND (long-tag OR duration >= 15min)
                //   "short" → NOT deep dive AND duration < 10min (Brief)
                // "default" never reaches this block (early return above).
                const hasDeepDive = t.includes('deep dive');
                const hasLong = t.includes('long');
                const durMatch = t.match(/(\\d+):(\\d+)/);
                const durMinutes = durMatch ? parseInt(durMatch[1], 10) : 0;
                let isKeep = false;
                if (podcastLength === "short") {{
                    // Brief format audio: not Deep Dive AND short duration.
                    // durMinutes==0 happens when NLM hasn't rendered the
                    // duration yet — accept that as a candidate so we
                    // don't lose track of an in-flight Brief.
                    isKeep = !hasDeepDive && (durMinutes === 0 || durMinutes < 10);
                }} else {{
                    // "long" (and any unknown value falls back here)
                    const isLongDuration = durMinutes >= 15;
                    isKeep = hasDeepDive && (hasLong || isLongDuration);
                }}
                el.setAttribute('data-cleanup-idx', String(i));
                out.push({{
                    idx: i,
                    isKeep: isKeep,
                    hasDeepDive: hasDeepDive,
                    hasLong: hasLong,
                    durationMin: durMinutes,
                    snippet: t.slice(0, 100),
                }});
            }});
            return out;
        }}""") or []

        result["scanned"] = len(cards)
        keep_candidates = [c for c in cards if c["isKeep"]]

        # Safety rail: must have EXACTLY one unambiguous keep target.
        if len(keep_candidates) == 0:
            result["skipped_reason"] = "no_keep_target_found"
            try:
                emit_event("nlm_cleanup_skipped", phase=3,
                           reason="no_keep_target_found",
                           scanned=result["scanned"])
            except Exception:
                pass
            return result
        if len(keep_candidates) > 1:
            result["skipped_reason"] = f"ambiguous_keep_targets ({len(keep_candidates)} matches)"
            try:
                emit_event("nlm_cleanup_skipped", phase=3,
                           reason="ambiguous_keep_targets",
                           scanned=result["scanned"],
                           keep_count=len(keep_candidates))
            except Exception:
                pass
            return result

        keep = keep_candidates[0]
        result["kept_idx"] = keep["idx"]
        delete_targets = [c for c in cards if c["idx"] != keep["idx"]]

        # Nothing to delete — the panel is already in the desired state.
        if not delete_targets:
            result["remaining_after"] = await _count_nlm_audio_cards(page)
            return result

        # Audit log every intended deletion BEFORE clicking, so we have a
        # paper trail in telemetry even if the click sequence half-fails.
        try:
            emit_event("nlm_cleanup_plan", phase=3,
                       keep_snippet=keep["snippet"],
                       deletes=[d["snippet"] for d in delete_targets])
        except Exception:
            pass

        for card in delete_targets:
            # Open the card's "..." / More menu.
            opened = await page.evaluate(f"""() => {{
                const c = document.querySelector('[data-cleanup-idx="{card["idx"]}"]');
                if (!c) return false;
                const m = c.querySelector(
                    'button[aria-label*="More" i], button[aria-label*="Options" i], '
                    + 'button[aria-haspopup="menu"]'
                );
                if (!m) return false;
                m.click(); return true;
            }}""")
            if not opened:
                continue
            await asyncio.sleep(0.6)

            # Click Delete in the menu.
            deleted = await page.evaluate("""() => {
                const items = document.querySelectorAll(
                    '[role="menuitem"], [role="menuitemradio"]'
                );
                for (const m of items) {
                    const t = (m.innerText || '').trim().toLowerCase();
                    if (t === 'delete' || t === 'remove' || t.startsWith('delete')) {
                        m.click(); return true;
                    }
                }
                return false;
            }""")
            if not deleted:
                try:
                    await page.keyboard.press("Escape")
                except Exception:
                    pass
                continue
            await asyncio.sleep(0.5)

            # Confirm in the secondary dialog if NLM shows one.
            try:
                await page.evaluate("""() => {
                    const dlg = document.querySelector('[role="dialog"], [role="alertdialog"]');
                    if (!dlg) return false;
                    const btns = dlg.querySelectorAll('button');
                    for (const b of btns) {
                        const t = (b.innerText || '').trim().toLowerCase();
                        if (t === 'delete' || t === 'remove' || t === 'confirm') {
                            b.click(); return true;
                        }
                    }
                    return false;
                }""")
            except Exception:
                pass
            await asyncio.sleep(0.8)
            result["deleted"] += 1
            try:
                emit_event("nlm_cleanup_deleted", phase=3,
                           card_snippet=card["snippet"],
                           had_deep_dive=card["hasDeepDive"],
                           duration_min=card["durationMin"])
            except Exception:
                pass

        # Defensive: close any lingering menu/dialog so share-link
        # extraction runs against a clean DOM.
        try:
            await page.keyboard.press("Escape")
            await asyncio.sleep(0.3)
        except Exception:
            pass

        # Re-count so the caller can verify the invariant in one place.
        result["remaining_after"] = await _count_nlm_audio_cards(page)
        try:
            emit_event("nlm_cleanup_done", phase=3,
                       scanned=result["scanned"],
                       deleted=result["deleted"],
                       remaining_after=result["remaining_after"])
        except Exception:
            pass
        return result
    except Exception as e:
        result["skipped_reason"] = f"{type(e).__name__}: {e}"
        try:
            emit_event("nlm_cleanup_error", phase=3, error=str(e)[:200])
        except Exception:
            pass
        return result



# ── Checkpoint & Resume ───────────────────────────────────────────────────────

def save_checkpoint(queue_dir, phase, **kwargs):
    """Save pipeline checkpoint after completing a phase."""
    cp = {"last_completed_phase": phase, "timestamp": datetime.now().isoformat()}
    cp.update(kwargs)
    # Enrichment (2026-04-28, Commit 1 of error-redesign): persist tier
    # escalation history, per-agent state, and last_event_id so a Phoenix
    # restart can resume retry budgets fairly + dedupe replayed events.
    # Caller-supplied kwargs win — we only fill if not already passed.
    try:
        snap = _runtime.snapshot()
        for key in ("tier_escalation_history", "agent_states", "last_event_id"):
            if key not in cp and key in snap:
                cp[key] = snap[key]
    except Exception:
        pass
    (Path(queue_dir) / "checkpoint.json").write_text(json.dumps(cp, indent=2), encoding="utf-8")


def _run_topic_for_guard(queue_dir) -> str:
    """The run's topic, read from disk, for the off-topic guard.

    2026-08-05. `extract_and_record_agent` has `queue_dir` but not `topic`, and
    neither does its caller or `run_phase2` — so the guard reads it rather than
    having it threaded through five signatures. Three sources, best first:
    meta.json (written with the topic verbatim), checkpoint.json, then the run
    directory's own name, which is the same fallback the resume path uses.

    Returns "" when the topic cannot be established. The guard treats that as
    ABSTAIN, never as a failure.
    """
    try:
        qd = Path(queue_dir)
    except (TypeError, ValueError):
        return ""
    for fname, key in (("meta.json", "topic"), ("checkpoint.json", "topic")):
        try:
            data = json.loads((qd / fname).read_text(encoding="utf-8"))
            t = (data.get(key) or "").strip()
            if t:
                return t
        except (OSError, ValueError, TypeError, AttributeError,
                json.JSONDecodeError):
            continue
    try:
        # Same idiom as the resume path's fallback.
        return qd.name.rsplit("_", 2)[0].replace("_", " ").strip()
    except (AttributeError, IndexError):
        return ""


def load_checkpoint(queue_dir):
    """Load checkpoint from a previous run. Returns dict or None."""
    cp_file = Path(queue_dir) / "checkpoint.json"
    if cp_file.exists():
        try:
            return json.loads(cp_file.read_text(encoding="utf-8"))
        except Exception:
            pass
    return None


# Sentence-boundary chars used to expand a URL match into its enclosing
# citation snippet. Treats double-newline (paragraph break) the same as
# a hard sentence ending so we don't bleed across markdown paragraphs.
_FIND_SENT_TAIL_RE = re.compile(r'(?:[.!?]\s|\n\n|\n#{1,4}\s)', re.MULTILINE)
_FIND_SENT_HEAD_RE = re.compile(r'(?:[.!?]\s|\n\n|\n#{1,4}\s)', re.MULTILINE)
_FIND_HEADING_RE = re.compile(r'^#{2,4}\s+(.{2,80})$', re.MULTILINE)
_FIND_MD_LINK_RE = re.compile(r'\[([^\]]{1,200})\]\(([^)]+)\)')
#: Bare URLs in a report. Hoisted out of `save_meta` (which harvests the same
#: markdown for `sourceUrls`) so one definition serves both — the two disagreeing
#: about what a URL is would put a source in the list and not in the findings.
# ⛔ `)` IS CAPTURED, THEN TRIMMED BY BALANCE — not excluded here. Excluding it
# truncated a legitimately parenthesised path at CAPTURE time
# (`.../wiki/Mercury_(planet)` -> `.../wiki/Mercury_(planet`), which no later
# trimming can undo, so the report-extracted half of the fix for that defect
# could not reach it. Capturing greedily and letting
# `_find_trim_trailing_punct` drop only an UNBALANCED bracket handles both
# shapes: "(see https://x.com/a)" still yields `https://x.com/a`.
_FIND_BARE_URL_RE = re.compile(r'https?://[^\s\]\"\'>]+')
#: Query keys dropped before comparing two URLs. Ported from the JS `cleanUrl`
#: the panel scrape already applies, so a panel row and the report's own citation
#: of the same page compare EQUAL — otherwise `?utm_source=chatgpt.com` makes one
#: page into two findings.
_FIND_TRACKING_PREFIX = "utm_"



def _find_trim_trailing_punct(u: str) -> str:
    """Drop sentence punctuation a report glued to the end of a url.

    ⛔ A CLOSING BRACKET IS NOT ALWAYS PUNCTUATION. `rstrip('.,;:)')` was
    applied to EVERY candidate, including the panel's own already-clean urls,
    and it truncates a legitimately parenthesised path —
    `…/wiki/Mercury_(planet)` became `…/wiki/Mercury_(planet`. The lookup still
    matched (a prefix of the text) so a finding was still emitted, carrying a
    url that 404s: worse than dropping it, because it looks right.

    ⭐ So a `)` is only punctuation when it has no `(` to close. Everything else
    in the set is unambiguous and is stripped as before.
    """
    u = (u or "").rstrip('.,;:')
    while u.endswith(')') and u.count('(') < u.count(')'):
        u = u[:-1].rstrip('.,;:')
    return u

def _find_normalize_url(u: str) -> str:
    """A comparison key for two URLs that mean the same page.

    Lowercases the host, drops `www.`, strips only the `utm_*` family from the
    query and keeps everything else — a bare "drop the query" would merge two
    genuinely different pages on a site that paginates or filters there.

    Returns the input unchanged when it cannot be parsed: an unparseable string
    is still a valid dedupe key for itself, and dropping it would be worse.
    """
    try:
        from urllib.parse import urlsplit, urlunsplit, parse_qsl, urlencode
        s = urlsplit(u)
        host = (s.hostname or "").lower()
        if host.startswith("www."):
            host = host[4:]
        if s.port:
            host = f"{host}:{s.port}"
        q = urlencode([(k, v) for k, v in parse_qsl(s.query, keep_blank_values=True)
                       if not k.lower().startswith(_FIND_TRACKING_PREFIX)])
        path = s.path.rstrip("/") or "/"
        return urlunsplit((s.scheme.lower(), host, path, q, s.fragment))
    except Exception:
        return u


def _find_is_platform_host(u: str) -> bool:
    """Is this URL one of the agents' own pages rather than a research source?

    ⚠ SUFFIX-aware, unlike the bare `host in _HOST_DENYLIST` membership tests
    elsewhere. Those are fed hosts the panel scrape already normalised; a report
    cites whatever the agent wrote, which includes `cdn.openai.com` and
    `files.oaiusercontent.com` — subdomains an exact-set test lets straight
    through. This is the same "guard the HOST, not the whole URL" rule that a
    substring filter here once broke by discarding 56% of a run's sources.
    """
    try:
        from urllib.parse import urlsplit
        host = (urlsplit(u).hostname or "").lower()
    except Exception:
        return False
    if not host:
        return False
    if host.startswith("www."):
        host = host[4:]
    return any(host == d or host.endswith("." + d) for d in _HOST_DENYLIST)


def _extract_findings(md: str, source_urls: list) -> list:
    """For each cited source URL, locate the enclosing sentence in the
    agent's markdown report and return a structured finding entry:
    `{"url": str, "snippet": str, "sourceTitle": str}`.

    Approach is regex-based — the agents' markdown is LLM-generated and
    not adversarial; URL substring matching plus sentence-boundary
    expansion (lookback to last `.`/`?`/`!`/double-newline, lookforward
    to next) gives a robust 80-280 char snippet without needing a full
    markdown AST.

    Snippet rules:
      - Strip markdown link syntax `[label](url)` → `label` so the
        body reads as prose, not raw markdown.
      - Cap at 280 chars with `…` suffix when sliced.
      - Skip when expanded snippet is < 30 chars (almost certainly a
        bare reference list entry, not a real cited mention).

    SourceTitle = first non-empty heading (`##` / `###`) preceding the
    URL, or hostname fallback if no heading is found before it.

    Caps result list at 12 per agent. Order = first-mention order in
    the markdown, deduped by URL.

    ⭐⭐ 2026-08-22 — THE REPORT IS NOW AN INPUT, not just a haystack. This used
    to take its candidate list solely from `source_urls`, i.e. the panel scrape,
    and return `[]` the moment that list was empty — so a Claude report carrying
    forty markdown citations produced NO findings at all, and the Findings tab
    fell back to bare section headings for a document full of sources. Measured:
    13 of 22 finished Claude runs in this machine's logs recorded zero panel
    sources, and `save_meta` was meanwhile harvesting that same report's URLs
    into `sourceUrls` — the two halves of one agent entry disagreeing about
    whether the run had sources.

    Candidates are now the UNION of the panel list and the report's own URLs
    (markdown-link targets plus bare), deduped on a normalised key so
    `?utm_source=…` does not make one page into two.

    ⭐ And the order changed with it. The docstring has always claimed
    "first-mention order in the markdown"; the loop actually walked panel order,
    so the 12-cap took the first twelve PANEL rows regardless of whether the
    report cited them. Sorting by position of first mention makes the claim true
    and makes the cap select the twelve most prominently cited sources.
    """
    if not md:
        return []
    # Report-derived candidates. Platform chrome is dropped by HOST — the
    # agents cite their own CDNs, and an exact-host membership test lets
    # `cdn.openai.com` through.
    #
    # ⭐ ONE SCAN, and mutation is why. This first ran `_FIND_MD_LINK_RE` over the
    # markdown as well, on the reasonable-sounding theory that a report which
    # LINKS rather than pastes needs its link targets read separately. Deleting
    # that scan changed no test, so it was measured instead of argued: because
    # `_FIND_BARE_URL_RE` already stops at `)`, `]`, `"`, `'` and `>`, it finds
    # every markdown target the link regex does — and on the two forms where they
    # differ the link regex is WORSE, yielding `https://ex.com/a "Nice Title"`
    # for a titled link and `<https://ex.com/x>` for an angle-bracketed one. The
    # first of those passes the http check and would have been emitted to the
    # user as a URL with a title glued to it. A redundant scan that can only make
    # the answer worse is not belt-and-braces.
    _report = _FIND_BARE_URL_RE.findall(md)
    # ⛔ TWO FORMS PER SOURCE, and a test caught why one is not enough. Dedupe
    # keeps the panel's cleaner URL, but the snippet is located by a LITERAL
    # `md.find`. So when the report spells the same page differently
    # (`https://www.Example.com/a` against the panel's `https://example.com/a`)
    # a single-form merge is strictly worse than no merge at all: the report's
    # own form is discarded as a duplicate, the surviving panel form is not
    # present in the text, and the finding vanishes. `emit` is what the user
    # sees; `lookup` is whatever actually appears in the report.
    _by_key: dict = {}
    _order: list = []
    for u in list(source_urls or []) + _report:
        u = _find_trim_trailing_punct((u or "").strip())
        if not u.lower().startswith(("http://", "https://")):
            continue
        if _find_is_platform_host(u):
            continue
        k = _find_normalize_url(u)
        if k not in _by_key:
            _by_key[k] = {"emit": u, "lookup": u if md.find(u) >= 0 else ""}
            _order.append(k)
        elif not _by_key[k]["lookup"] and md.find(u) >= 0:
            _by_key[k]["lookup"] = u
    _candidates = [_by_key[k] for k in _order if _by_key[k]["lookup"]]
    if not _candidates:
        return []
    # First-MENTION order, which is what the docstring has always promised and
    # the panel-ordered loop never delivered.
    _candidates.sort(key=lambda c: md.find(c["lookup"]))
    _candidates = _candidates[:_SOURCE_LIST_CAP]
    source_urls = [c["lookup"] for c in _candidates]
    _emit_for = {c["lookup"]: c["emit"] for c in _candidates}
    findings: list = []
    seen_urls: set = set()
    # Pre-scan headings so we can find the nearest preceding heading
    # for any URL match in O(1) per match — without this, a huge md
    # would re-scan from start for every URL.
    headings: list = []
    for hm in _FIND_HEADING_RE.finditer(md):
        headings.append((hm.start(), hm.group(1).strip()))
    for url in source_urls:
        if not url or url in seen_urls:
            continue
        seen_urls.add(url)
        idx = md.find(url)
        if idx < 0:
            continue
        # Find sentence start: last sentence-end token BEFORE idx.
        head_search = md[:idx]
        head_match = None
        for m in _FIND_SENT_HEAD_RE.finditer(head_search):
            head_match = m
        sent_start = head_match.end() if head_match else 0
        # Find sentence end: first sentence-end token AFTER idx + len(url).
        url_end = idx + len(url)
        tail_match = _FIND_SENT_TAIL_RE.search(md, url_end)
        sent_end = tail_match.start() if tail_match else min(url_end + 200, len(md))
        snippet = md[sent_start:sent_end].strip()
        if len(snippet) < 30:
            continue
        # Replace markdown links with their label text — keeps prose
        # readable and avoids "click 'http://...'" awkwardness.
        snippet = _FIND_MD_LINK_RE.sub(lambda m: m.group(1), snippet)
        # Collapse internal whitespace so "  \n   " runs read as a
        # single space in the rendered card.
        snippet = re.sub(r'\s+', ' ', snippet).strip()
        if len(snippet) > 280:
            snippet = snippet[:279].rstrip() + "…"
        # Locate nearest preceding heading.
        title = ""
        for h_pos, h_text in headings:
            if h_pos > idx:
                break
            title = h_text
        if not title:
            try:
                from urllib.parse import urlparse as _urlparse
                _h = (_urlparse(url).hostname or "").lower()
                if _h.startswith("www."):
                    _h = _h[4:]
                title = _h
            except Exception:
                title = ""
        title = title[:80]
        # Emit the canonical form (the panel's, when it supplied one), not the
        # spelling that happened to be in the prose.
        findings.append({"url": _emit_for.get(url, url), "snippet": snippet,
                         "sourceTitle": title})
        if len(findings) >= 12:
            break
    return findings


def _run_started_ms(queue_dir) -> int:
    """When the RUN began — not when meta.json first happened to be written.

    ⭐ 2026-08-11. `createdAt` used to be stamped `now` on the first write, and
    the first write is the END of Phase 1. Every backfilled phase takes its
    start from `createdAt`, so Phase 1 was born already finished: the 11 August
    run spent 14m33s on the Research Brief and recorded `durationSec: 0`. Not a
    rounding error and not occasional — structurally guaranteed on every run,
    for the one phase the owner waits through most visibly.

    `config.json` and `owner.json` are written once, at queue-dir creation, and
    never touched again, so the earlier of their timestamps is when the run
    started. Falls back to now, which is exactly the old behaviour.
    """
    stamps = []
    for name in ("config.json", "owner.json"):
        try:
            p = Path(queue_dir) / name
            if p.exists():
                stamps.append(int(p.stat().st_mtime * 1000))
        except Exception:
            pass
    return min(stamps) if stamps else int(time.time() * 1000)


def save_meta(queue_dir, topic, phase, status="ongoing", **extra):
    """Save/update meta.json — powers ALL frontend components (graphs, analytics, tracking).
    Contains: Research object + per-agent stats + phase timeline + source references."""
    queue_dir = Path(queue_dir)
    meta_path = queue_dir / "meta.json"
    meta = {}
    if meta_path.exists():
        try:
            meta = json.loads(meta_path.read_text(encoding="utf-8"))
        except Exception:
            pass
    if "id" not in meta:
        meta["id"] = queue_dir.name
        # NOT `now` — see `_run_started_ms`. This value is the start of every
        # phase that gets backfilled below, and the first write lands at the
        # end of Phase 1.
        meta["createdAt"] = _run_started_ms(queue_dir)

    # ── Scan documents/ for files ──
    docs = []
    doc_dir = queue_dir / "documents"
    if doc_dir.exists():
        for f in sorted(doc_dir.glob("*.md")):
            if f.stat().st_size > 50:
                docs.append({"id": f.stem, "name": f.name, "type": f.stem,
                              "size": f"{f.stat().st_size / 1024:.0f} KB",
                              "createdAt": int(f.stat().st_mtime * 1000)})

    # ── Scan podcasts/ for audio files ──
    podcasts = []
    pod_dir = queue_dir / "podcasts"
    if pod_dir.exists():
        # De-dup by stem, preferring the streamable .mp3 over a same-stem .m4a.
        # _transcode_audio_to_mp3 deletes the source .m4a on success, so the
        # happy path already has one file per stem — but if that unlink lost a
        # rare race (a Windows AV/indexer lock on the just-downloaded file),
        # BOTH would linger and the id=stem entries would collide. Prefer the
        # mp3 (what actually got uploaded to Storage + the Firestore audios
        # doc) so meta.json can't double-count. Format-agnostic: a stem with a
        # single file (any extension, incl. legacy m4a runs) is unaffected.
        _by_stem: dict[str, Path] = {}
        for f in pod_dir.glob("*.*"):
            prev = _by_stem.get(f.stem)
            if prev is None or (prev.suffix.lower() != ".mp3" and f.suffix.lower() == ".mp3"):
                _by_stem[f.stem] = f
        for f in sorted(_by_stem.values(), key=lambda p: p.name):
            # tinytag primary / ffprobe fallback — see _audio_duration_sec.
            dur_sec = _audio_duration_sec(f)
            mins, secs = divmod(dur_sec, 60)
            podcasts.append({"id": f.stem, "name": f.name,
                             "duration": f"{mins}:{secs:02d}" if dur_sec else "",
                             "durationSec": dur_sec,
                             "createdAt": int(f.stat().st_mtime * 1000)})

    # ── Per-agent stats (for analytics graphs, radar chart, health score) ──
    agents = meta.get("agents", {})
    # #722 Bug A: snapshot any status ALREADY persisted (from a prior tick /
    # a prior worker on resume) BEFORE the rebuild below replaces the entries
    # wholesale — so the status re-stamp can fall back to it when the live
    # runtime dict is empty (fresh resumed process).
    _prior_agent_status = {
        _p: ((agents.get(_p, {}) or {}).get("status")) for _p in ["chatgpt", "gemini", "claude"]
    }
    for platform in ["chatgpt", "gemini", "claude"]:
        md_file = doc_dir / f"{platform}.md" if doc_dir.exists() else None
        if md_file and md_file.exists() and md_file.stat().st_size > 100:
            content = md_file.read_text(encoding="utf-8")
            # Extract sections — markdown headings + bold standalone lines (ChatGPT style)
            sections = re.findall(r'^#{1,3}\s+(.+)$', content, re.MULTILINE)
            if len(sections) <= 2:
                # ChatGPT often uses **Bold Title** instead of # headings
                bold_sections = re.findall(r'^\*\*(.{5,80})\*\*\s*$', content, re.MULTILINE)
                # Also try numbered bold: **1. Title**
                numbered = re.findall(r'^\*\*\d+[\.\)]\s*(.{5,80})\*\*', content, re.MULTILINE)
                sections = sections + bold_sections + numbered
                sections = list(dict.fromkeys(sections))[:20]  # Dedupe
            # Filter out the file header we added
            sections = [s for s in sections if s not in ("ChatGPT Deep Research", "Gemini Deep Research", "Claude Deep Research")]
            # Extract source URLs from markdown links and references
            urls = _FIND_BARE_URL_RE.findall(content)
            unique_urls = list(dict.fromkeys(urls))[:_SOURCE_LIST_CAP]  # Dedupe, cap at the shared ceiling
            # Build/update agent entry. unique_urls is already capped at 50.
            existing = agents.get(platform, {})
            # 2026-05-04: pull the runtime per-agent progress snapshot so
            # searches + observedSources land in the persisted Firestore
            # agents map alongside the markdown-derived fields above. The
            # FE post-completion stub (PhaseDropdown.tsx _postCompletionStub)
            # reads these to recap "Xk chars, N sources, M searches" on
            # chat reopen — without persistence, the live pipeline_events
            # window prunes past 50 entries and the values defaulted to 0,
            # making the stub show only chars+sources after a long break.
            try:
                _snap = dict(getattr(_runtime, "agent_progress_snapshots", {}).get(platform, {}) or {})
            except Exception:
                _snap = {}
            # Downsample the per-agent progressHistory ring (cap 240) to
            # 60 evenly-spaced points + first + last. The FE GraphAnalysis
            # All-Agents sparklines + the post-reload chart restoration
            # both consume this — without persistence, reopening a
            # finished run shows flat "No data" because the in-memory
            # ring is already gone.
            try:
                _raw_hist = list(getattr(_runtime, "agent_progress_history", {}).get(platform, []) or [])
            except Exception:
                _raw_hist = []
            _down_hist: list = []
            if len(_raw_hist) <= 60:
                _down_hist = _raw_hist
            elif _raw_hist:
                _step = (len(_raw_hist) - 1) / 59.0
                _seen: set = set()
                for _i in range(60):
                    _idx = min(int(round(_i * _step)), len(_raw_hist) - 1)
                    if _idx not in _seen:
                        _seen.add(_idx)
                        _down_hist.append(_raw_hist[_idx])
                # Always pin first + last so the curve endpoints land on
                # real values, not the closest sampled neighbor.
                if _down_hist and _down_hist[0] is not _raw_hist[0]:
                    _down_hist[0] = _raw_hist[0]
                if _down_hist and _down_hist[-1] is not _raw_hist[-1]:
                    _down_hist[-1] = _raw_hist[-1]
            try:
                _findings = list(getattr(_runtime, "agent_findings", {}).get(platform, []) or [])
            except Exception:
                _findings = []
            agents[platform] = {
                "sources": len(unique_urls),
                "sourceUrls": unique_urls,
                "sections": sections[:15],
                "outputChars": len(content),
                "completionTimeSec": existing.get("completionTimeSec", 0),
                # Real cited-source findings populated by C4b (extractor
                # runs after each agent's markdown is written). Falls
                # back to section headings when the extractor returns
                # empty so legacy reads don't break — see C4b for the
                # extractor wiring.
                "findings": _findings if _findings else (sections[:3] if sections else []),
                "searches": int(_snap.get("searches", 0) or existing.get("searches", 0) or 0),
                "observedSources": int(_snap.get("observed_sources", 0) or existing.get("observedSources", 0) or 0),
                # ⭐ The panel rows that named a DOMAIN and carried no link.
                # Nonzero beside `sources: 0` is the difference between "Claude
                # cited nothing" and "Claude cited eight sites we could not turn
                # into urls" — which is exactly the distinction the zero-source
                # investigation needed and did not have.
                "sourceHostCount": int(_snap.get("source_host_count", 0)
                                       or existing.get("sourceHostCount", 0) or 0),
                "progressHistory": _down_hist,
            }
        # #722 Bug A: carry the per-agent terminal status (written by
        # _write_agent_terminal_status) onto the entry for EVERY platform —
        # NOT just those with a markdown file. A skipped/errored agent has no
        # .md, so it never entered the rebuild above; without this, the
        # whole-field .update({"agents": …}) below would DROP its merge-written
        # status (the agent vanishes from the map entirely), reverting the tile
        # to a stale all-green check. Runs once per platform regardless of md:
        # use the live runtime status, falling back to a status already
        # persisted in meta.json (survives resume into a fresh worker), and
        # setdefault so a no-md skipped/errored agent still gets a minimal
        # entry to hold the status. Config-disabled agents never call
        # _write_agent_terminal_status and have no md, so _astat stays falsy →
        # no spurious entry is created for them.
        _astat = (_agent_status_by_rid.get(_fb_research_id, {}) or {}).get(platform) \
            or _prior_agent_status.get(platform)
        if _astat:
            agents.setdefault(platform, {})["status"] = _astat

        # ⛔⛔ 2026-08-29 — AN AGENT WITH NO REPORT PERSISTED NO SOURCES AT ALL, and
        # the rebuild above is why: `sources` / `sourceUrls` are a regex sweep over
        # the agent's MARKDOWN FILE, so they exist only where a report does. An
        # agent that ran forty minutes, gathered sources and then died recorded
        # nothing but a status — and the UI, which is now asked to show a dead
        # agent's sources, had nothing to show after a reload.
        #
        # ⭐ THE DATA ALWAYS EXISTED. The live poll writes per-agent source urls
        # and counts into `agent_progress_snapshots` on every tick, independently
        # of any text. It was simply never persisted for the one population that
        # needed it. Owner, 2026-08-29: "if there are sources, let the narration
        # show the sources and stuff."
        #
        # ⛔ ONLY WHERE THE REBUILD DID NOT RUN. An agent WITH a report already has
        # citation-derived sources from its own text, and those are the better
        # list — they are what the report actually cited, not what the panel
        # happened to show. This must never overwrite them.
        if platform not in agents or "sources" not in agents.get(platform, {}):
            try:
                _fallback_snap = dict(
                    getattr(_runtime, "agent_progress_snapshots", {}).get(platform, {}) or {})
            except Exception:
                _fallback_snap = {}
            _fallback_urls = list(_fallback_snap.get("source_urls", []) or [])[:_SOURCE_LIST_CAP]
            _fallback_searches = int(_fallback_snap.get("searches", 0) or 0)
            _fallback_observed = int(_fallback_snap.get("observed_sources", 0) or 0)
            # ⛔ AND ONLY WHEN THERE IS SOMETHING TO SAY. Writing a row of zeroes
            # for an agent the user turned off upfront would invent an entry for a
            # platform that never ran, which is the exact thing the status
            # re-stamp above is careful not to do.
            if _fallback_urls or _fallback_searches or _fallback_observed:
                _entry = agents.setdefault(platform, {})
                _entry.setdefault("sources", len(_fallback_urls))
                _entry.setdefault("sourceUrls", _fallback_urls)
                _entry.setdefault("searches", _fallback_searches)
                _entry.setdefault("observedSources", _fallback_observed)
                # ⛔ EXPLICITLY ZERO, NOT ABSENT. The frontend reads a missing
                # `outputChars` and a zero one the same way — as "no report" — but
                # only the explicit zero says we LOOKED. It is also what stops the
                # sources below being mistaken for a report that was produced.
                _entry.setdefault("outputChars", 0)

    # ── Phase timeline (for timeline graph) ──
    phases = meta.get("phases", [])
    # Canonical 6-phase timeline (0-5). Audio is part of NotebookLM (phase 3),
    # NOT a separate phase — the BE records the whole NLM+audio span as phase 3
    # (see the phase_complete phase=3 with the full _p3_start duration). Phase 4
    # is YouTube, phase 5 is Delivery (both FE-stamped). The old 7-entry array
    # split "Audio Overview" out as its own phase, which mislabeled the Analytics
    # timeline; kept in lockstep with web PHASE_META + the FE P4/P5 phase stamps.
    phase_labels = ["Initializing", "Research Brief", "Deep Research",
                    "Links + NotebookLM + Audio", "Video + YouTube", "Delivery"]
    now_ms = int(time.time() * 1000)
    # Ensure all phases up to current exist
    while len(phases) <= phase:
        p_idx = len(phases)
        # Start time: use previous phase's completedAt, or createdAt for first phase
        start = meta.get("createdAt", now_ms)
        if p_idx > 0 and len(phases) > 0 and phases[-1].get("completedAt"):
            start = phases[-1]["completedAt"]
        phases.append({
            "phase": p_idx,
            "label": phase_labels[p_idx] if p_idx < len(phase_labels) else f"Phase {p_idx}",
            "startedAt": start,
            "completedAt": None,
            "durationSec": 0,
        })
    # Mark current phase as completed with actual duration
    if phase < len(phases) and phases[phase]["completedAt"] is None:
        phases[phase]["completedAt"] = now_ms
        started = phases[phase].get("startedAt", now_ms)
        phases[phase]["durationSec"] = max(0, (now_ms - started) // 1000)

    # #722 Bug A: carry per-phase terminal status onto the rebuilt entries.
    # A Firestore array can't be dotted-merged, so the whole-array
    # .update({"phases": …}) below always replaces it — the status that
    # _write_phase_terminal_status wrote (via the daemon-thread read-modify-
    # write) would be lost unless we re-stamp it here. Only overwrite when the
    # runtime knows a status for that phase; otherwise leave any status already
    # carried in meta.json (resume) intact.
    _pstat = _phase_status_by_rid.get(_fb_research_id, {}) or {}
    for _entry in phases:
        if isinstance(_entry, dict):
            _ps = _pstat.get(_entry.get("phase"))
            if _ps:
                _entry["status"] = _ps

    # ── Write meta ──
    meta.update({
        "title": topic[:100] if topic else meta.get("title", ""),
        "topic": topic or meta.get("topic", ""),
        "summary": extra.get("summary", meta.get("summary", "")),
        "status": status,
        "phase": phase,
        "platforms": ["chatgpt", "gemini", "claude"],
        "documents": docs,
        "audios": podcasts,
        "agents": agents,
        "phases": phases,
        "updatedAt": now_ms,
    })
    meta_path.write_text(json.dumps(meta, indent=2), encoding="utf-8")

    # ── Propagate structured agents/phases to Firestore research doc ──
    # Without this, the frontend Analytics page never sees per-agent stats or
    # phase timelines for live runs — they live only on disk. Uses a shallow
    # update so we don't clobber other fields (like pipelineConfig).
    try:
        _update_firestore_research({
            "agents": agents,
            "phases": phases,
            "status": status,
            "phase": phase,
            "updatedAt": now_ms,
        })
    except Exception as _e:
        log(f"save_meta: firestore propagation failed: {_e}", "WARN")


def detect_resume_phase(queue_dir):
    """Detect which phase to resume from based on existing output files.
    Returns (phase_number, description). 5-phase BE model (0-4) plus
    FE-owned Phase 5 (Doc + email). Return value of 5 means "BE work is
    done, FE-P5 still needs to fire" — run_pipeline handles this by
    re-emitting phase_complete phase=4 to retrigger triggerFeP5 on the
    frontend (its CAS guard makes a re-trigger idempotent). 6 means
    "delivery.json marks the run completed — nothing to resume"."""
    queue_dir = Path(queue_dir)
    if (queue_dir / "delivery.json").exists():
        try:
            delivery = json.loads((queue_dir / "delivery.json").read_text(encoding="utf-8"))
            if delivery.get("status") == "completed":
                return 6, "Pipeline already complete"
        except Exception:
            pass
    cp = load_checkpoint(queue_dir)
    # Phase 4 done — BE work complete, FE-P5 retriggered via re-emit of
    # phase_complete phase=4 inside run_pipeline.
    if cp and cp.get("youtube_url"):
        return 5, "YouTube done — Phase 4 complete, FE will pick up Phase 5"
    # Phase 3 done → resume from Phase 4: check if audio exists
    if cp and cp.get("audio_path") and Path(cp["audio_path"]).exists():
        return 4, "Audio exists — Phase 3 done, resuming from Phase 4 (YouTube)"
    audio_dir = queue_dir / "podcasts"
    if audio_dir.exists() and any(audio_dir.glob("*.*")):
        return 4, "Audio exists — Phase 3 done, resuming from Phase 4 (YouTube)"
    # Phase 2 done but no audio → resume from Phase 3: check if links/notebook exist
    if (queue_dir / "links.json").exists():
        return 3, "Links exist — resuming from Phase 3 (NotebookLM)"
    # Phase 2 done → resume from Phase 3 ONLY if the Phase-2 completion
    # marker is present. The marker is written after the round-robin poller
    # returned (i.e. all agents reached a terminal state). Without the
    # marker, "any non-brief MD >100 bytes" was too coarse — a backend crash
    # mid-P2 with only one agent's MD on disk would falsely jump to Phase 3,
    # silently skipping the agents that hadn't finished yet.
    marker = queue_dir / "phase2_complete.marker"
    if marker.exists():
        return 3, "Phase 2 complete marker present — resuming from Phase 3"
    # No marker but some MDs on disk → P2 was interrupted. Restart Phase 2
    # so the unfinished agents complete. NOTE: re-running P2 re-extracts
    # ALL enabled agents from scratch (`run_phase2` doesn't currently scan
    # disk to skip already-finished agents). Existing MDs are overwritten
    # via the Firestore upsert in `save_document_to_firestore`. Wasteful
    # on time but safe — the only correctness cost is a few extra minutes
    # of agent work; data-wise the new MDs are at least as good as the
    # old. An idempotency guard ("if documents/{agent}.md exists, skip
    # launching") would be a real refactor, not landed here.
    research_dir = queue_dir / "documents"
    has_partial_research = research_dir.exists() and any(
        f for f in research_dir.glob("*.md") if f.stat().st_size > 100 and f.stem != "brief")
    if has_partial_research:
        return 2, "Phase 2 partial MDs present without completion marker — re-running Phase 2 (all agents)"
    # Phase 1 done → resume from Phase 2: check if brief exists
    brief = queue_dir / "documents" / "brief.md"
    if not brief.exists():
        brief = queue_dir / "brief.md"
    if brief.exists() and brief.stat().st_size > 100:
        return 2, "Brief exists — Phase 1 done, resuming from Phase 2"
    return 0, "Starting from Phase 0 (Init)"


# ── Browser-crash recovery (#725) ───────────────────────────────────────────
# Max CONSECUTIVE silent browser-crash auto-retries before run_pipeline
# escalates to a user-facing Retry/Skip card. 2 silent retries = 3 total
# browser launches before we involve the human. Threaded through run_pipeline's
# `_crash_retries` param (NOT _runtime, which `reset()`s per run).
BROWSER_CRASH_MAX_RETRIES = 2


def _is_browser_close_error(exc) -> bool:
    """True when `exc` is a Chromium/patchright "the page or browser went away"
    failure — the user closed the window, an OOM kill, a profile-lock fight, or
    a driver EPIPE. Reuses the SAME string set the navigate() retry path keys
    on (see ~research.py:15975). These strings originate in the CDP driver, not
    the OS, so they read identically on Windows / Linux / macOS — the
    classification is fully cross-platform. `TargetClosedError` is matched by
    type name so a future message-wording change still classifies."""
    msg = (str(exc) or "").lower()
    tname = type(exc).__name__.lower()
    return (
        "target page" in msg
        or "page, context" in msg
        or "context or browser has been closed" in msg
        or "browser has been closed" in msg
        or "bring_to_front" in msg
        or "targetclosed" in tname
    )


def _plan_pipeline_auto_retry(queue_dir, resume_dir, failure_kind, crash_retries):
    """SINGLE source of truth for run_pipeline's post-failure auto-retry
    decision. Returns (will_retry: bool, phase: int, is_browser_crash: bool).

    Called TWICE per failed run with identical inputs: once inside the
    top-level `except` (to decide whether to SUPPRESS the user-facing card
    while a silent retry is incoming — per the "silent self-heal" rule), and
    once in the post-`finally` block (to actually recurse). It's a pure
    function of on-disk state (delivery.json status, .stop/.pause sentinels,
    detect_resume_phase) plus the threaded crash counter; the only thing the
    `finally` mutates between the two calls is `browser.close()`, which touches
    no queue_dir files — so the two evaluations always agree (no divergence
    where we'd hide the card but then NOT retry, or vice-versa)."""
    is_crash = (failure_kind == "browser_crash")
    if not queue_dir:
        return (False, 0, is_crash)
    # Gate 1 — retry budget. A NORMAL (non-crash) failure gets ONE shot: the
    # first run has resume_dir=None, the recursion sets it, so a second normal
    # failure surfaces the card. A browser crash bypasses that gate but is
    # capped at BROWSER_CRASH_MAX_RETRIES consecutive silent retries.
    crash_budget_ok = crash_retries < BROWSER_CRASH_MAX_RETRIES
    if not ((not resume_dir) or (is_crash and crash_budget_ok)):
        return (False, 0, is_crash)
    # Gate 2 — terminal/intentional states never auto-retry.
    try:
        d_path = queue_dir / "delivery.json"
        d_status = json.loads(d_path.read_text(encoding="utf-8")).get("status") if d_path.exists() else ""
    except Exception:
        d_status = ""
    if d_status in ("completed", "stopped", "paused"):
        return (False, 0, is_crash)
    if (queue_dir / ".stop").exists() or (queue_dir / ".pause").exists():
        return (False, 0, is_crash)
    # Gate 2b (#907) — a --login in flight killed our Chrome ON PURPOSE.
    # Auto-retrying would relaunch Chrome onto the very profile the user is
    # signing into (and the login side would kill it again — a fight).
    # Stand down; run_pipeline's failure path emits the "Interrupted by the
    # login command" card whose Retry resumes from this same checkpoint
    # after the login finishes. Marker file = on-disk state, so the
    # called-twice-consistency contract of this function holds (30-min
    # freshness window >> the ms between the two calls).
    if _login_interrupt_active():
        return (False, 0, is_crash)
    # Gate 3 — phase eligibility. Phase 5 = BE done (FE owns P5); >4 = nothing
    # to retry. A browser crash can surface at phase 0/1 (brief not yet written
    # → detect_resume_phase returns 0), which the legacy `1 < phase` gate
    # EXCLUDED — that was the #725 bug (a phase-1 Chrome-close never retried).
    # Include phases 0-4 for crashes; keep the conservative 2-4 window for
    # normal one-shot retries (a blind retry of a phase-0/1 setup/brief failure
    # rarely helps and is better surfaced to the user).
    phase, _ = detect_resume_phase(queue_dir)
    eligible = (1 < phase <= 4) or (is_crash and 0 <= phase <= 4)
    return (eligible, phase, is_crash)


# ── Main Pipeline ─────────────────────────────────────────────────────────────

async def run_pipeline(topic, pdf_paths=None, brief_file=None, verbose=False,
                       api_key=None, email=None, resume_dir=None, config=None,
                       run_id=None, uid=None, research_id=None, brief_text="",
                       user_sources=None, user_links=None, _crash_retries=0):
    """Run the full pipeline. Supports resume from a previous queue directory.

    brief_text (2026-04): inline brief content passed from the frontend when
    the user toggled Phase 1 off. Written to the new run's
    queues/<run>/documents/brief.md before Phase 1 decides its path; this
    makes `brief_file` point at the fresh file and flows through the
    `_brief_from_file` branch, skipping ChatGPT brief generation + share-link
    extraction.

    user_sources (2026-04-29): Flow B. List of {name, storagePath, mime}
    when P1 + all P2 agents are skipped — the user attached source files to
    NotebookLM directly. BE downloads each from Firebase Storage into
    queue_dir/documents/<name>.md before P3 fires; the existing
    _build_phase2_to_phase3_handoff scan then naturally feeds them into NLM.

    user_links (2026-04-29): Flow C. List of {kind, label, url} when P1 + P2
    + P3 are all skipped — the user pasted source URLs and just wants the
    final Doc + email. BE hydrates notebook_url / youtube_url / audio_url /
    links from these in the P3-skip block so P5 has something to compose."""
    # #938: bind the submitter identity BEFORE any key resolution — the
    # Anthropic key is resolved and baked into cua_client a few lines down,
    # and a sharer's own per-device key must win for runs THEY submitted.
    # Entry-only by design; NOT cleared in this function's finally: the
    # auto-retry recursion forwards the resolved key as cli_key (skipping
    # Firestore, so a clear would mis-attribute retry error cards), the
    # post-run title/summary daemon threads resolve keys after we return,
    # and several early returns above the main try would leak past a
    # finally anyway. The next run re-binds at its own entry.
    _set_run_submitter(uid)
    user_sources = user_sources or []
    user_links = user_links or []
    pdf_paths = pdf_paths or []
    # Collapse internal whitespace runs in the topic to single spaces. Multi-
    # line topics (Flow C: user pastes URLs+labels, FE concatenates as topic
    # with newlines) would otherwise leak \n into the queue dir name, the Doc
    # title, the email subject, and FE storage. safe_name() handles the dir
    # part, but we want the topic STRING itself clean for downstream
    # consumers too.
    if isinstance(topic, str):
        topic = re.sub(r'\s+', ' ', topic).strip()
    api_key = resolve_api_key(api_key)
    if not api_key:
        log("No API key (set ANTHROPIC_API_KEY)", "ERROR")
        return

    import anthropic
    cua_client = anthropic.Anthropic(api_key=api_key)
    # #938: freeze WHOSE Anthropic key this client holds, now — the memo it
    # reads from is refreshed by later narrator Gemini resolves, but this
    # client's key is fixed for the run, so its error cards must attribute
    # the key as it was at bake time.
    _capture_anthropic_attribution()

    # ── Initialize pipeline controls + Firestore bridge ──
    _controls.reset()
    _runtime.reset()
    # #955 Phase 2 (adversarial findings #1/#2/#3/#5): wipe the auto-skip
    # deadline registry at every run entry. It's a MODULE global (not owned by
    # _runtime), and jobs run sequentially in one long-lived worker process, so
    # an armed deadline that a prior run left stranded (a crashed/completed/
    # errored agent whose drop path didn't emit a resolve-seam signal) would
    # otherwise survive into THIS run and auto-skip a healthy same-key agent on
    # the first Phase-2 tick. This is the load-bearing cross-run backstop; the
    # per-drop-path disarms keep it clean within a run. Also covers resume
    # re-entries (a stale pre-crash deadline must not ride the checkpoint back).
    _disarm_registry("__all__")
    # Same cross-run-wipe cluster, and the one with the worst failure mode.
    # `_P2_ACTIVE_FAMILY` records "this ACCOUNT's plan excludes the primary
    # model family". The worker is long-lived and runs jobs sequentially, so
    # without this wipe a single non-pro run teaches the process a fallback
    # family that every LATER run inherits — including runs signed into a Pro
    # account, which would then be steered onto the fallback family with model
    # selection reporting complete success. A silent permanent downgrade
    # triggered by one visit from a free account is far worse than re-deriving
    # the fact, which costs one popover read on the runs that need it.
    _P2_ACTIVE_FAMILY.clear()
    # Same cross-run-wipe cluster: Vision's per-run budget/telemetry lives on
    # vision.default_client()'s singleton VisionMetrics, which the long-lived
    # --serve worker reuses across runs. Left un-reset, call_count accumulates
    # since boot and trips the per-run budget gate permanently (the tier then
    # goes dark, falling through to CUA for the process lifetime). Reset it so
    # the budget + analytics are genuinely per-run. No-op + no client
    # construction when Vision was never touched (off path stays byte-identical);
    # never let a Vision hiccup break a run, hence the guard.
    if _vision is not None:
        try:
            _vision.reset_default_metrics()
        except Exception:
            pass
    # Clear dedup cache — stale keys from a prior run in the same process
    # would otherwise suppress early events in this run.
    _last_progress.clear()
    # Stamp the live per-run id into the env so Vision shadow + observe-only records
    # carry the REAL run id (both paths read DG_RUN_ID from the env at log time).
    # Without this they inherit whatever DG_RUN_ID was last set to in the environment
    # (e.g. a lingering Track-A E2E value), which mislabels every record with the same
    # stale id. Process-safe: worker parallelism is one-run-per-process (the per-process
    # _runtime was reset just above), so the process-wide env can't collide across runs.
    if run_id:
        os.environ["DG_RUN_ID"] = str(run_id)
    # Defensive: clear the OS clipboard at run start. Several share-link
    # extractors (NotebookLM, ChatGPT share-URL, Claude artifact copy)
    # fall back to reading the clipboard (_read_clipboard_after_copy) when DOM
    # selectors miss. The OS clipboard is process-global and persists
    # across runs on every platform — a stale share URL from a prior
    # run sitting in the clipboard could be accepted as THIS run's link
    # and emitted to Firestore. Nukes the cross-run bleed channel.
    # (The original YouTube-specific rationale is gone — P4 is now FE-
    # owned and uses the YouTube Data API, no clipboard extraction —
    # but the bleed risk for the remaining BE extractors stands.)
    # This closes the cross-RUN channel ONLY. The same-run channel — one
    # agent's share link being read back as the next agent's — is closed by
    # _arm_clipboard() at each copy site, and cannot be closed from here:
    # the contaminating value does not exist yet when this line runs.
    clear_clipboard()
    # Start the DOM ledger empty so a long-lived worker cannot carry the
    # previous run's verdict into this one.
    _dom_reset()
    brief_artifact = None  # Set after Phase 1 completes
    # Validate email early (email is the user's Google account email from frontend)
    if email:
        ok, reason = validate_email(email)
        if not ok:
            log(f"[email] Invalid email received: {reason} — Phase 5 email will be skipped", "WARN")
            email = None
    if uid:
        # Use frontend research_id for Firestore paths (not run_id which is the backend dir name)
        setup_firestore_run(uid, research_id or run_id, asyncio.get_running_loop(), run_id=run_id)
    if _cli_mode:
        # CLI mode has no Firestore command listener — wire stdin instead so
        # the user can resume/skip/stop from the same terminal.
        _start_cli_command_reader(asyncio.get_running_loop())
    # Start mid-run input dispatcher (watches _controls.extra_context, pastes to active pages)
    try:
        _runtime.dispatcher_task = asyncio.create_task(run_input_dispatcher())
    except Exception as e:
        log(f"[dispatcher] Failed to start: {e}", "WARN")

    # ── Helper: update delivery.json incrementally (frontend reads this for live links) ──
    # DGOPS-9508: defined HERE, above the `if resume_dir:` block, not further down
    # beside its first success-path use. `update_delivery` is a LOCAL of
    # run_pipeline, so every reference in this function resolves to this binding —
    # and the `start_phase == 5` resume branch below calls it ~365 lines BEFORE the
    # old definition site, then `return`s, so that def was never reached and the
    # call raised UnboundLocalError every time. It read as a NameError-shaped
    # crash ("Pipeline job error: cannot access local variable ...") that aborted
    # the resume AFTER phase_complete had already been emitted, so beDone /
    # currentPhase=5 never landed and the FE-P5 trigger never posted. The closure
    # reads `queue_dir` + `topic` at CALL time, so hoisting the def above their
    # assignments is safe — only the call sites need them bound, and they are.
    def update_delivery(**new_fields):
        d_path = queue_dir / "delivery.json"
        d = json.loads(d_path.read_text(encoding="utf-8")) if d_path.exists() else {
            "topic": topic, "status": "ongoing", "brief_url": "", "research_links": {},
            "notebook_url": "", "audio_url": "", "youtube_url": "", "doc_url": "", "email_sent": False,
        }
        d.update(new_fields)
        d_path.write_text(json.dumps(d, indent=2), encoding="utf-8")

    # ── Determine queue directory + start phase ──
    if resume_dir:
        queue_dir = Path(resume_dir)
        if not queue_dir.exists():
            log(f"Resume dir not found: {queue_dir}", "ERROR")
            return
        (queue_dir / "documents").mkdir(exist_ok=True)
        # Set the active-run global as early as possible so the
        # `clear_local_storage` device-command handler treats this dir
        # as protected. Without this, a clear fired during the lengthy
        # checkpoint-restore / config-load block below could rmtree the
        # dir we're about to resume from. Also re-set at line ~17235
        # for symmetry with the new-run branch — idempotent.
        init_tracks(queue_dir.name)
        # Mark as retry/resume so browser-crash sites surface the real alert
        # (auto-retry won't fire from finally for this attempt — the guard
        # at the bottom of run_pipeline gates on `not resume_dir`).
        _runtime.is_retry_attempt = True
        start_phase, reason = detect_resume_phase(queue_dir)
        log(f"RESUME: {reason}")
        # Emit resume marker so frontend knows to ignore events before this point
        emit_event("pipeline_resumed", phase=start_phase, resumeReason=reason)
        # #929: full-restart marker. A checkpoint resume re-runs the phase
        # from scratch (run_phase2 relaunches ALL enabled agents — a pre-pause
        # user skip is a per-attempt decision, not persisted), so the FE must
        # reset that phase's UI state too: per-agent icons/steppers/details
        # and any stale alert cards from the paused attempt. full=True is
        # emitted ONLY here — the many soft-retry phase_restart sites must
        # NOT wipe live phase UI (their agents keep running).
        if isinstance(start_phase, int) and 0 <= start_phase <= 3:
            emit_event("phase_restart", phase=start_phase,
                       reason="resume_from_checkpoint", full=True)
        if start_phase >= 6:
            log("Pipeline already complete — nothing to resume")
            return
        if start_phase == 5:
            # P4 was done before crash but FE-P5 may not have completed
            # (Doc + email is FE-owned post-2026-04-30). Re-emit
            # phase_complete phase=4 with the checkpoint links so the FE
            # listener fires triggerFeP5 again. Its CAS guard
            # (casFeP5 + feP5State) handles "already completed" /
            # "in flight" idempotently.
            cp = load_checkpoint(queue_dir) or {}
            yt_url = cp.get("youtube_url", "")
            nb_url = cp.get("notebook_url", "")
            bf_url = cp.get("brief_url", "")
            _resume_links = []
            if yt_url:
                _resume_links.append({"label": "YouTube Video", "url": yt_url, "verified": True})
            if nb_url:
                _resume_links.append({"label": "NotebookLM", "url": nb_url, "verified": True})
            if bf_url:
                _resume_links.append({"label": "Research Brief", "url": bf_url, "verified": True})
            emit_event("phase_complete", phase=4, durationSec=0, links=_resume_links,
                       summary="Resumed from checkpoint — frontend handles Phase 5")
            log("Resume: P4 already done, re-emitted phase_complete phase=4 to retrigger FE-P5")
            update_delivery(status="completed")
            # Mirror the success-path handoff (~line 18663): advance both
            # phase AND currentPhase to 5 so the homepage tile diagram
            # stops glowing the YouTube node and FE-P5 picks up cleanly.
            # Pre-fix this only wrote phase=4, leaving currentPhase stale
            # at 4 and the diagram painting YouTube as the active node
            # forever post-resume.
            # 2026-05-11: same beDone marker as the main exit so the
            # queue gate also fires for resume-from-checkpoint runs.
            _update_firestore_research({
                "status": "ongoing", "phase": 5, "currentPhase": 5,
                "beDone": True, "beDoneAt": int(time.time() * 1000),
            })
            # 2026-05-12: autonomous P4/P5 trigger also fires on resume-
            # from-checkpoint so a Phoenix restart that lands here doesn't
            # leave the chain dangling on the FE listener (which may not
            # be alive when this resume path runs from the daemon-loop).
            try:
                _post_fe_p4p5_trigger(_fb_uid, _fb_research_id)
            except Exception as _trig_err:
                log(f"FE trigger dispatch failed on resume (non-fatal): {_trig_err}", "WARN")
            return
        cp = load_checkpoint(queue_dir) or {}
        topic = topic or cp.get("topic", queue_dir.name.rsplit("_", 2)[0].replace("_", " "))
        # Load pipeline config on resume
        config_path = queue_dir / "config.json"
        pipeline_config = json.loads(config_path.read_text(encoding="utf-8")) if config_path.exists() else {}
        # Restore tier escalation history so retry budgets carry over from
        # the prior run (a Phoenix restart at T1 attempt 2 doesn't reset to
        # attempt 1 — the framework's 30-min window judges that fairly).
        try:
            for key, esc_dict in (cp.get("tier_escalation_history") or {}).items():
                if isinstance(esc_dict, dict):
                    _tier_escalations[key] = TierEscalation.from_dict(esc_dict)
            # Restore agent_states + last_event_id so a Phoenix-resumed run
            # rebuilds "where each agent was" before silence escalation.
            _runtime.agent_states = dict(cp.get("agent_states") or {})
            _runtime.last_event_id = cp.get("last_event_id", "") or ""
        except Exception as _re:
            log(f"[resume] tier/agent state restore failed: {_re}", "WARN")
    else:
        # Flow C cosmetic — when the user pasted only URLs (no prose), the
        # FE-supplied topic is the raw URL string. That makes for an ugly
        # Doc title, sidebar tile, queue dir name, and email subject.
        # Replace it with a label-based summary derived from the parsed
        # link kinds (e.g. "Research from NotebookLM, YouTube, Google Doc")
        # so every downstream consumer renders something readable. Pure
        # cosmetic — pipeline routing is unaffected.
        if user_links and topic.strip().lower().startswith(("http://", "https://")):
            _labels = []
            _seen_labels = set()
            for _l in user_links:
                _lbl = (_l.get("label") or "").strip()
                if _lbl and _lbl not in _seen_labels:
                    _seen_labels.add(_lbl)
                    _labels.append(_lbl)
            if _labels:
                topic = "Research from " + ", ".join(_labels[:5])
        run_name = run_id or f"{safe_name(topic)}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        queue_dir = Path(__file__).parent / "queues" / run_name
        queue_dir.mkdir(parents=True, exist_ok=True)
        (queue_dir / "documents").mkdir(exist_ok=True)
        # Set the active-run global immediately after mkdir so a
        # `clear_local_storage` device command fired during Flow B
        # source downloads / config write doesn't rmtree this dir
        # mid-construction. The init_tracks call at line ~17235 is
        # now redundant on this branch but harmless (idempotent).
        init_tracks(queue_dir.name)
        start_phase = 1
        cp = {}
        # Save pipeline config for new runs
        pipeline_config = config or {}
        (queue_dir / "config.json").write_text(json.dumps(pipeline_config, indent=2), encoding="utf-8")
        # Inline brief → persist as the new run's brief.md, then route the
        # pipeline through brief_file so Phase 1 lands on the `_brief_from_file`
        # branch (no ChatGPT brief generation, no share-link extraction).
        if brief_text and not brief_file:
            _inline_brief_path = queue_dir / "documents" / "brief.md"
            _inline_md = brief_text if brief_text.lstrip().startswith("# Research Brief") \
                         else f"# Research Brief\n\n{brief_text}"
            _inline_brief_path.write_text(_inline_md, encoding="utf-8")
            brief_file = str(_inline_brief_path)
            log(f"Inline brief persisted ({len(brief_text)} chars) → {_inline_brief_path.name}")

        # Flow B: P1 + all P2 skipped → user attached source files (uploaded
        # to Storage by the FE). Download each into queue_dir/documents/
        # preserving the original extension so NotebookLM ingests them
        # natively (NLM accepts md/txt/pdf/docx). The existing P3 file scan
        # at gate-decision time + run_phase3_upload pick them up like any
        # other agent-generated artifact. Failures are logged but the
        # pipeline continues with whatever sources DID download.
        if user_sources:
            try:
                # The synth device user has read access to
                # `users/{owner}/.../sources/...` when the device is
                # authorized for that owner (storage.rules helper
                # `deviceAuthorizedFor`). Stream each attached source
                # into queue_dir/documents/ before P3 hands them to
                # NotebookLM.
                _bucket_label = _resolve_storage_bucket() or "(unresolved)"
                _ok, _fail = 0, 0
                _dl_names = []  # user-source filenames → P2 delivery allowlist
                for _src in user_sources:
                    _name = (_src.get("name") or "source").strip() or "source"
                    _path = (_src.get("storagePath") or "").strip()
                    if not _path:
                        _fail += 1
                        continue
                    # Sanitize: keep alnum + . _ - and cap length so a
                    # malicious name can't escape queue_dir.
                    _safe = re.sub(r"[^A-Za-z0-9._-]", "-", _name)[:80] or "source"
                    # Avoid clobbering brief.md or another source with the
                    # same sanitized name — append a numeric suffix.
                    _dest = queue_dir / "documents" / _safe
                    if _dest.stem == "brief":
                        _dest = queue_dir / "documents" / f"src-{_safe}"
                    _i = 2
                    while _dest.exists():
                        _stem = _dest.stem
                        _ext = _dest.suffix
                        _dest = queue_dir / "documents" / f"{_stem}-{_i}{_ext}"
                        _i += 1
                    try:
                        if not _download_user_source_via_storage_rest(_path, _dest):
                            raise RuntimeError("Storage REST download failed")
                        log(f"Flow B source: gs://{_bucket_label}/{_path} → {_dest.name} ({_dest.stat().st_size} bytes)")
                        _dl_names.append(_dest.name)
                        _ok += 1
                    except Exception as _e:
                        log(f"Flow B source download FAILED ({_path}): {_e}", "WARN")
                        _fail += 1
                log(f"Flow B sources: {_ok} downloaded, {_fail} failed")
                # Record the allowlist so P2 delivery (and hard-retry) never
                # pick up agent-written artifacts in documents/. attach_to_p2
                # stays False until the orchestrator confirms P1 didn't run.
                if _dl_names:
                    _write_user_sources_manifest(_dl_names)
                # If every download failed, the run is doomed — P3 will trip
                # the gate and surface a generic "no documents" alert. Better
                # to fail fast with the actual reason so the user can retry
                # the upload or fix Storage permissions.
                if _ok == 0 and _fail > 0:
                    log(f"Flow B: ALL {_fail} source downloads failed — aborting", "ERROR")
                    # 2026-05-21: emit at whatever phase the pipeline is
                    # currently at (preflight always runs early so this is
                    # P0 in practice, but we read _runtime.phase dynamically
                    # so the alert always lands on the user's visible tile,
                    # not on the original Flow-B-target P3 NLM dropdown
                    # that the user can't see while the chat is at P0).
                    # Pre-fix: phase=3 hard-coded → alert vanished into the
                    # P3 dropdown the user never opens, manifesting as
                    # "stuck at init with no actionable button anywhere".
                    # Skip action still routes to skip_phase(3) so user can
                    # elect to run without NLM ingestion, but Retry restarts
                    # the current phase since most 403s are token/auth races.
                    _alert_phase = getattr(_runtime, "phase", 0) or 0
                    fail_phase(
                        phase=_alert_phase,
                        error="Couldn't open your attached files",
                        reason="We couldn't load the file(s) you attached. Retry to try again, or Skip them and continue without NotebookLM.",
                        actions=[
                            {"id": "retry", "label": "Retry", "style": "primary",
                             "command": {"action": "retry_phase", "phase": _alert_phase}},
                            {"id": "skip", "label": "Skip attachments", "style": "default",
                             "command": {"action": "skip_phase", "phase": 3}},
                        ],
                    )
                    return
            except Exception as _outer:
                log(f"Flow B handler failed (non-fatal): {_outer}", "WARN")

        # Bridge user_sources → P1/P2 attachments. After the Flow B block
        # downloaded everything into documents/, walk that dir and:
        #   - append any *.pdf / *.docx / *.md to pdf_paths so run_phase1
        #     attaches them to the ChatGPT brief request as context;
        #   - the same files remain on disk so the P2 round-robin pass can
        #     pick them up via _runtime.original_inputs (consumed by
        #     start_agent_no_gemini_wait's brief_path + auxiliary attach).
        # Only run when the user actually attached sources; otherwise leave
        # pdf_paths as the CLI-supplied default.
        if user_sources:
            _docs_dir = queue_dir / "documents"
            if _docs_dir.exists():
                _aux_paths = list(pdf_paths or [])
                for _f in sorted(_docs_dir.iterdir()):
                    if not _f.is_file():
                        continue
                    if _f.stem in ("brief", "consolidated"):
                        continue
                    if _f.suffix.lower() not in (".pdf", ".md", ".docx", ".txt"):
                        continue
                    _full = str(_f)
                    if _full not in _aux_paths:
                        _aux_paths.append(_full)
                if _aux_paths != list(pdf_paths or []):
                    log(f"User sources -> P1 attach list: {[Path(p).name for p in _aux_paths]}")
                pdf_paths = _aux_paths

    log(f"Queue: {queue_dir}")
    # init_tracks just sets the global `_tracks_dir` to a Path holding
    # the run name (same name as the queue dir). The local var is unused;
    # the side effect is what matters.
    init_tracks(queue_dir.name)

    # ── Pipeline config: reload from config.json before each phase (supports mid-pipeline changes) ──
    def reload_config():
        nonlocal pipeline_config
        config_path = queue_dir / "config.json"
        if config_path.exists():
            try:
                pipeline_config = json.loads(config_path.read_text(encoding="utf-8"))
            except Exception:
                pass
        # Merge any in-memory config updates from Firestore commands
        # (in case Firestore config arrived but HTTP PATCH didn't)
        ctrl_updates = _controls.pop_config_updates()
        if ctrl_updates:
            pipeline_config.update(ctrl_updates)
            # Persist merged config back to disk for next reload
            try:
                config_path.write_text(json.dumps(pipeline_config, indent=2), encoding="utf-8")
            except Exception:
                pass
        # 2026-05-13: Firestore overlay — read pipelineConfig from research doc
        # and merge restrictively (skip wins, agents-off wins, video/email-off
        # wins, podcastLength latest wins). Catches queued-state toggles that
        # don't propagate via writeCommand (30s stale-command gate at line
        # ~3348 discards old writes; the BE command listener also isn't
        # attached until the run picks up its slot, so writes from the
        # queued window land in Firestore but never reach _config_updates).
        # The research doc's pipelineConfig is the FE's authoritative snapshot,
        # updated synchronously on every toggle regardless of run status.
        try:
            if _firebase_db and _fb_uid and _fb_research_id:
                _rd_snap = _firebase_db.collection("users").document(_fb_uid) \
                    .collection("researches").document(_fb_research_id).get()
                if _rd_snap.exists:
                    _pc = (_rd_snap.to_dict() or {}).get("pipelineConfig") or {}
                    # skippedPhases (FE field name) or skipPhases (BE) — accept either
                    _fs_skip_raw = _pc.get("skippedPhases") if "skippedPhases" in _pc else _pc.get("skipPhases")
                    if isinstance(_fs_skip_raw, list):
                        _curr_skip = set(pipeline_config.get("skipPhases") or [])
                        _fs_skip = {int(x) for x in _fs_skip_raw if isinstance(x, (int, float))}
                        _added = _fs_skip - _curr_skip
                        if _added:
                            log(f"[config-overlay] FS adds skip phases {sorted(_added)} (disk had {sorted(_curr_skip)})", "WARN")
                            pipeline_config["skipPhases"] = sorted(_curr_skip | _fs_skip)
                    # agents — skip wins (FS off overrides disk on, never the reverse)
                    _fs_agents = _pc.get("agents") or {}
                    if _fs_agents:
                        _curr_agents = dict(pipeline_config.get("agents") or {})
                        for _k in ("chatgpt", "gemini", "claude"):
                            if _k in _fs_agents and not bool(_fs_agents[_k]) and _curr_agents.get(_k, True):
                                log(f"[config-overlay] FS agents.{_k}=false overrides disk", "WARN")
                                _curr_agents[_k] = False
                        pipeline_config["agents"] = _curr_agents
                    # videoEnabled / emailEnabled — false wins
                    if "videoEnabled" in _pc and not bool(_pc["videoEnabled"]) and pipeline_config.get("videoEnabled", True):
                        log("[config-overlay] FS videoEnabled=false overrides", "WARN")
                        pipeline_config["videoEnabled"] = False
                    if "emailEnabled" in _pc and not bool(_pc["emailEnabled"]) and pipeline_config.get("emailEnabled", True):
                        log("[config-overlay] FS emailEnabled=false overrides", "WARN")
                        pipeline_config["emailEnabled"] = False
                    # podcastLength — latest wins (any valid value)
                    _fs_pl = _pc.get("podcastLength")
                    if isinstance(_fs_pl, str) and _fs_pl in ("short", "default", "long"):
                        if _fs_pl != pipeline_config.get("podcastLength"):
                            log(f"[config-overlay] FS podcastLength={_fs_pl} overrides disk={pipeline_config.get('podcastLength')}", "WARN")
                            pipeline_config["podcastLength"] = _fs_pl
        except Exception as _overlay_err:
            _o_err = str(_overlay_err)
            if (
                "403" in _o_err
                or "PERMISSION_DENIED" in _o_err
                or "Missing or insufficient permissions" in _o_err
            ):
                # Track D: synth user denied on user-tree research-doc
                # read. The disk-side pipelineConfig already merged
                # ctrl_updates; FE-side queued-state toggles still need
                # this overlay (see cleanup #552 for structural rule
                # fix that lets synth user read research docs scoped
                # to its deviceId).
                log("[config-overlay] re-read denied (synth user) — using disk pipelineConfig", "DEBUG")
            else:
                log(f"[config-overlay] Firestore re-read failed (non-fatal): {_overlay_err}", "WARN")
        sp = set(pipeline_config.get("skipPhases", []))
        ac = pipeline_config.get("agents", {"chatgpt": True, "gemini": True, "claude": True})
        ve = pipeline_config.get("videoEnabled", True)
        ee = pipeline_config.get("emailEnabled", True)
        # 2026-05-13 (feature): NotebookLM audio-overview length —
        # "short" / "default" / "long". Default to "long" so pre-feature
        # runs preserve the historical hardcoded behavior. The Phase 3
        # audio-generation CUA prompt parameterizes its Length instruction
        # on this value below.
        pl_raw = pipeline_config.get("podcastLength", "long")
        pl = pl_raw if pl_raw in ("short", "default", "long") else "long"
        if 3 in sp:
            sp.add(4)
        # Brief-on requires ≥1 P2 agent — otherwise the brief feeds nothing
        # and Phase 3 has no documents. The FE has 3 separate guards (chat
        # panel, settings page, tile diagram) but a stale config.json or a
        # mid-pipeline command-config update can still land an invalid
        # combo here. Auto-enable ChatGPT silently rather than fail —
        # preserves the brief's investment, matches the FE auto-enable on
        # the skip-brief Settings toggle, and makes downstream phases work.
        # 2026-05-13: also require `2 not in sp` — when the user explicitly
        # toggles all P2 agents off, the FE cascades by adding 2 to
        # skippedPhases (ChatInput.tsx:312). Honoring that explicit intent
        # means we must NOT silently re-enable ChatGPT just because ac is
        # all-False; the user wants P2 skipped wholesale. Without this gate
        # the new Firestore overlay would correctly disable all 3 agents,
        # then this branch would clobber the user's explicit toggle.
        if 1 not in sp and 2 not in sp and not any(ac.values()):
            log("Config: brief on with 0 agents (not explicit skip) — auto-enabling ChatGPT", "WARN")
            ac["chatgpt"] = True
        # 2026-05-20 (queued-run init-skip parity): also honor
        # skipInitVerify from disk config. Pre-fix this was only set via
        # the per-run skip_init_verify action command at runtime — which
        # the queued run can't fire because the per-research command
        # listener isn't attached until after Phase 0 starts. Result:
        # the Settings → Pipeline "Skip verification" toggle worked for
        # immediate runs (whose Phase 0 was already running when the
        # listener attached and the command landed) but was silently
        # ignored for queued runs. Now reload_config returns the
        # disk-config value, and the Phase 0 entry block primes
        # _controls.skip_init_verify from it before the verify loop
        # starts.
        # 2026-07-02: default flipped to TRUE — init verification is OFF for
        # every account unless it explicitly set skipInitVerify=false. On a
        # fresh profile the proactive verify navigations are the strongest
        # bot-score signal; the phase-time gate (now on the work page) and the
        # human-verify cascade still cover a genuinely logged-out platform.
        siv = bool(pipeline_config.get("skipInitVerify", True))
        # #921: prime the user-controllable auto-skip flag from the same run
        # config (default True). Set on every reload_config so a resume/retry
        # re-read stays in sync. Gating lives in poll_all_agents_round_robin's
        # Layer-3 block; Layer-1 stuck cards are unaffected.
        _runtime.auto_skip_stuck = bool(pipeline_config.get("autoSkipStuck", True))
        return sp, ac, ve, ee, pl, siv

    skip_phases, agents_cfg, video_enabled, email_enabled, podcast_length, skip_init_verify_cfg = reload_config()
    # Prime the per-run controls. The FE Settings toggle and per-run
    # command both write to _controls.skip_init_verify; honoring the
    # disk config at Phase 0 entry ensures queued runs respect the
    # global Settings preference without depending on the per-research
    # command listener attaching first.
    if skip_init_verify_cfg:
        try:
            _controls.skip_init_verify = True
            log("[config] skipInitVerify=true from disk config — Phase 0 will skip login verification", "INFO")
        except Exception:
            pass

    # ── Preload data from previous phases (for resume) ──
    brief_text, brief_url = "", cp.get("brief_url", "")
    links, notebook_url, youtube_url = {}, cp.get("notebook_url", ""), cp.get("youtube_url", "")
    # CRITICAL: audio_overview_url must be initialized at module scope so
    # P5 (line ~15272 _effective_audio_url) doesn't NameError when resuming
    # past P3 (start_phase >= 4). The P3 sub-step normally assigns this
    # inside its `elif start_phase <= 3` branch; on resume, we restore it
    # from checkpoint. P4 path also sets `audio_overview_url = ""` so the
    # variable is always defined regardless of which branch P3 takes.
    audio_overview_url = cp.get("audio_overview_url", "")
    # ⛔⛔ SAME REASON, SAME SCOPE, ADDED 2026-08-28 (stretch 6.6C). The Phase-3
    # completion gate and the run-complete summary both read
    # `_p3_audio_stored`, and it is assigned inside `if notebook_url:` in the
    # `elif start_phase <= 3` branch — so a run RESUMED past P3, or one whose
    # notebook never opened, would raise NameError at the two places that are
    # supposed to report what happened. The comment directly above records that
    # this exact trap was already paid for once with `audio_overview_url`.
    _p3_audio_stored = ""

    # #910: a resumed run is ongoing again. Clear a stale local "paused"
    # (login-interrupt / in-process pause) so _plan_pipeline_auto_retry's
    # Gate 2 doesn't read the OLD pause and refuse silent self-heal for the
    # whole resumed run, and so --login's run enumeration stays honest.
    # Narrow on purpose: only paused→ongoing — never touches completed/stopped.
    if resume_dir:
        try:
            _d_path = queue_dir / "delivery.json"
            if (_d_path.exists()
                    and json.loads(_d_path.read_text(encoding="utf-8")).get("status") == "paused"):
                update_delivery(status="ongoing")
                log("Resume: delivery.json status paused → ongoing (stale pause cleared)")
        except Exception:
            pass

    # Stop/pause are driven through `_controls` (asyncio events) now. The
    # .stop and .pause sentinel files are still written by the HTTP endpoints
    # for backward-compat with the resume flow + pipeline_state reporting —
    # no in-pipeline helper needed here.

    # ── Helper: read user feedback for a phase ──
    def get_feedback(phase_num):
        fb_path = queue_dir / "feedback.json"
        if fb_path.exists():
            try:
                fb = json.loads(fb_path.read_text(encoding="utf-8"))
                return fb.get(str(phase_num), "")
            except Exception:
                pass
        return ""

    def clear_feedback(phase_num):
        fb_path = queue_dir / "feedback.json"
        if fb_path.exists():
            try:
                fb = json.loads(fb_path.read_text(encoding="utf-8"))
                fb.pop(str(phase_num), None)
                fb_path.write_text(json.dumps(fb, indent=2), encoding="utf-8")
            except Exception:
                pass

    class _PhaseSoftDecision(Exception):
        """Raised by the soft-warn path of _await_phase_with_active_deadline
        when the user picks Retry or Skip. .decision is "retry" or "skip".
        Wait + Stop are handled inline (Wait = no signal, polling continues;
        Stop = CancelledError). 2026-05-04: introduced to support the user's
        'BE can't bail on long researches' contract — long Claude DR runs
        (1-2h) emit a soft warn at the phase deadline instead of hard-
        cancelling, and the user picks the next move."""
        def __init__(self, decision: str):
            super().__init__(f"phase soft decision: {decision}")
            self.decision = decision

    def _emit_phase_soft_warn(phase: int, max_min: int, alert_id: str):
        """Emit the phase-level soft-timeout pipeline_warning. Used only by
        _await_phase_with_active_deadline's soft path. Round 2 (#60): a phase
        that is merely SLOW (not failed) is a self-healing state, not a user
        decision — so this is a PASSIVE, buttonless (actions=[]) info banner.
        The run is NOT paused and keeps polling to natural completion; the
        FE-dismissible banner is informational only. The genuine-hang path
        (_phase_timeout_decision at the hard ceiling) still pauses and offers
        Retry/Skip, and the global Stop button remains the escape.
        """
        actions = []
        try:
            # #955 Phase 5B / Round 2 (#60): author through the seam in EXPLICIT
            # mode (no catalog row). event_name="pipeline_warning" keeps the FE
            # routing; the FE warning handler renders evt.data.actions (now [] —
            # a passive, dismissible banner) and reads the title from message
            # (never error), so message= is load-bearing via **extra. Fresh id
            # per fire (no re-emit).
            emit_decision(
                phase=phase,
                title="This step is taking a while",
                details=(
                    "This step is still running — it may just be a long one. "
                    "No action needed; it will continue on its own."
                ),
                actions=actions,
                recoverability="recoverable",
                event_name="pipeline_warning",
                alert_id=alert_id,
                dismissible=True,
                alertType="warn",
                message="This step is taking a while",
            )
        except Exception as _e:
            log(f"_emit_phase_soft_warn fallback ({_e})", "WARN")

    async def _phase_timeout_decision(phase: int, max_min: int, agent: str | None = None) -> str:
        """Recoverable response to a per-phase active-time ceiling. Per the
        never-die contract, BE-detected stuck phases do NOT terminate the
        run — they emit pipeline_error with [Retry, Skip] actions and pause
        for the user's call. User decides:
          - retry → restore from checkpoint, rerun the phase (fresh deadline)
          - skip  → mark phase done, advance to next
          - stop  → only fires if user explicitly hit Stop (chat input button)
                    while the alert was up; await_phase_decision picks that up
                    via _controls.is_stop()
        Returns the user's decision string. Does NOT write delivery.json
        status="stopped" — that's reserved for terminal stop paths only.

        2026-05-04: this is the HARD path. Soft-warn coverage:
          - P1 (brief gen, 60m): soft-warn at the deadline so 30+min
            briefs on large PDFs / complex topics aren't bailed on.
          - P2 (deep research, 120m): soft-warn at the deadline so
            1-2h DR runs aren't bailed on.
          - P3 audio sub-step (NLM podcast gen, 90m): soft-warn at
            the deadline so long-podcast generation isn't killed.
        P3 upload (15m) and P4 (15m) keep this hard-cancel + Retry/
        Skip pause-for-decision flow — they're bounded utility ops
        (NLM upload click flow, ffmpeg + YouTube upload)."""
        log(f"Phase {phase}: active-time ceiling {max_min}min hit — surfacing to user as recoverable error", "WARN")
        actions = [
            {"id": "retry", "label": "Retry from checkpoint", "style": "primary",
             "command": {"action": "retry_phase", "phase": phase}},
            {"id": "skip", "label": "Skip phase", "style": "default",
             "command": {"action": "skip_phase", "phase": phase}},
        ]
        try:
            fail_phase(
                phase=phase,
                error="This step seems stuck",
                reason=(
                    "This step has run a long time without finishing. "
                    "Restart it, or skip it and keep going."
                ),
                agent=agent,
                actions=actions,
                # #62: distinct alert_id (was the generic phase{n}_error). The
                # hard phase-timeout card and the crash_loop card both fired at
                # the same phase into one FE dedup/dismiss slot; a dismissed
                # timeout card then permanently silenced the crash card. Distinct
                # from the soft path's phase{n}_soft_timeout_{ts} id.
                alert_id=f"phase{phase}_timeout",
            )
        except Exception as _e:
            log(f"_phase_timeout_decision: fail_phase fallback ({_e})", "WARN")
            fail_phase(phase, "This step seems stuck",
                       "This step has run a long time without finishing. Restart it, or skip it and keep going.",
                       agent=agent, actions=actions, alert_id=f"phase{phase}_timeout")
        # Pause flag freezes the active-time clock during the user's
        # decision wait, so a 20-min decision delay doesn't burn budget
        # against the next retry. Also flips the FE chat input to paused.
        _controls.request_pause()
        emit_event("pipeline_paused", phase=phase, reason="phase_timeout")
        decision = await _controls.await_phase_decision(phase)
        emit_event("pipeline_resumed", phase=phase, reason=f"phase_timeout_{decision}")
        return decision

    async def _await_phase_with_active_deadline(phase: int, max_min: int, coro_factory,
                                                  soft_warn_only: bool = False):
        """Run a phase coroutine factory with an ACTIVE-TIME wall-clock
        deadline. Time spent while `_controls.is_pause()` is True does NOT
        count toward the budget — so a user pausing for an hour doesn't
        kill a healthy phase.

        soft_warn_only=False (default — P3-upload + P4 hard-cap behavior):
          Cancels the coroutine when active-time exhausts and raises
          asyncio.TimeoutError. Caller runs `_phase_timeout_decision` to
          give the user Retry/Skip, and on Retry calls this helper AGAIN
          (factory creates a fresh coro). Existing behavior — unchanged.

        soft_warn_only=True (P1 + P2 + P3-audio — long-running advisory, 2026-05-04):
          Emits a PASSIVE pipeline_warning banner (amber) at the deadline
          and DOES NOT cancel the coroutine — the run_task keeps working to
          natural completion. Round 2 (#60): the banner is now buttonless
          (a slow-but-healthy phase is self-healing, not a user decision),
          so it no longer sources a Retry/Skip. The retry/skip polling below
          stays as a latent honor-path — if a phase-level Retry/Skip command
          arrives from any other surface it is still honored (cancel + raise
          _PhaseSoftDecision) — but nothing sets it during a soft warn in
          practice. User-Stop (chat input) → cancel + raise CancelledError.
          Run_task completing naturally returns its result. The user's
          contract: 'BE can't bail on long researches and fail.' One warn per
          helper invocation (no re-warn / no spam).

        coro_factory is `Callable[[], Coroutine]` — must produce a fresh
        coroutine on each call so retry doesn't await an already-awaited
        coroutine. Tick is 5s — fine-grained enough for any budget."""
        run_task = asyncio.ensure_future(coro_factory())
        active_sec = 0.0
        deadline_sec = float(max_min * 60)
        tick = 5.0
        soft_warn_emitted = False
        # 2026-05-06 (Stream 2 D4): per-invocation nonce so the FE dedup
        # ledger (5-min/1-resurface) doesn't permanently silence the
        # 2nd / 3rd soft-warn emission when callers re-invoke this helper
        # (e.g., P3-audio retry-after-no-audio loop calls it up to 3
        # times per pipeline run). Each helper call gets a fresh
        # alert_id; FE treats them as distinct alerts, not duplicates.
        soft_alert_id = f"phase{phase}_soft_timeout_{int(time.monotonic() * 1000)}"
        while not run_task.done():
            try:
                await asyncio.sleep(tick)
            except asyncio.CancelledError:
                run_task.cancel()
                raise
            # User-Stop short-circuit: the deadline loop used to ignore the
            # Stop button and only react when the phase coroutine itself
            # noticed the stop flag — which could be deep inside a long
            # CUA call. Now we cancel-and-propagate immediately, so user
            # Stop during a stuck phase exits within one tick (5s) instead
            # of waiting up to `max_min` for the deadline.
            if _controls.is_stop():
                run_task.cancel()
                try: await run_task
                except BaseException: pass
                raise asyncio.CancelledError(f"phase {phase} stopped by user")
            # Soft-mode phase-decision polling — only AFTER the warn is
            # emitted. Round 2 (#60): the soft-warn banner is buttonless, so
            # this no longer fires from the card itself; it remains a latent
            # honor-path for a retry_phase/skip_phase command arriving from any
            # other surface while the phase runs long (none does in practice).
            if soft_warn_only and soft_warn_emitted:
                if _controls.consume_retry_phase(phase):
                    log(f"Phase {phase}: user chose Retry on soft-warn — cancelling run_task", "INFO")
                    run_task.cancel()
                    try: await run_task
                    except BaseException: pass
                    raise _PhaseSoftDecision("retry")
                if _controls.consume_phase_skip(phase):
                    log(f"Phase {phase}: user chose Skip on soft-warn — cancelling run_task", "INFO")
                    run_task.cancel()
                    try: await run_task
                    except BaseException: pass
                    raise _PhaseSoftDecision("skip")
            if not _controls.is_pause():
                active_sec += tick
            if active_sec >= deadline_sec and not run_task.done():
                if soft_warn_only and not soft_warn_emitted:
                    # Soft path: emit the passive pipeline_warning ONCE, keep
                    # polling. Run_task continues uninterrupted to natural
                    # completion. Round 2 (#60): the banner is buttonless, so
                    # there is no Wait/Retry/Skip to consume — the run simply
                    # keeps going (global Stop still exits within one tick).
                    log(f"Phase {phase}: active-time {active_sec:.0f}s past "
                        f"{deadline_sec:.0f}s — soft warn emitted, polling continues", "WARN")
                    _emit_phase_soft_warn(phase, max_min, soft_alert_id)
                    soft_warn_emitted = True
                    continue
                if soft_warn_only and soft_warn_emitted:
                    # Already warned, user undecided. Keep polling — the
                    # run_task may finish naturally; if it does, we exit
                    # the while loop and return its result below.
                    continue
                # Hard-cap path (P1/P3/P4 default behavior — unchanged).
                log(f"Phase {phase}: active-time {active_sec:.0f}s exceeded {deadline_sec:.0f}s — cancelling for user decision", "WARN")
                run_task.cancel()
                # CancelledError inherits from BaseException (not Exception)
                # since Python 3.8, so `except Exception: pass` did NOT catch
                # the post-cancel re-raise — and the `raise TimeoutError`
                # below was never reached. Catching BaseException converts
                # the cancel into the TimeoutError the retry loop expects.
                try: await run_task
                except BaseException as _drained:
                    # DEBUG-log the drained class so any future regression
                    # where something unexpected leaks (custom exception,
                    # SystemExit, etc.) doesn't go silent.
                    log(f"Phase {phase}: drained {type(_drained).__name__} post-cancel", "DEBUG")
                raise asyncio.TimeoutError(
                    f"phase {phase} exceeded {max_min}-min active-time budget"
                )
        return await run_task

    # Create delivery.json immediately (frontend can see the run from the start)
    if not (queue_dir / "delivery.json").exists():
        update_delivery()

    browser = Browser(_profile_dir(WORKER_ID), headless=False)
    # Expose the live Browser instance to the stop / discard / hard-reset
    # paths so they can schedule a graceful close without waiting for
    # the pipeline to reach its next is_stop() phase boundary. Pause+resume
    # paths below re-create the Browser and re-assign this ref.
    global _active_browser_ref
    _active_browser_ref = browser
    # #725: snapshotted in the except (BEFORE the finally's _runtime.reset()
    # wipes last_failure_kind) and read by the post-finally auto-retry block.
    # Pre-initialized so the clean-exit path (no exception) reads "".
    _captured_failure_kind = ""
    try:
        # ══════════════════════ PHASE 0: Preflight ══════════════════════
        # Phase 0 does real work now: launch browser, verify each platform's
        # login session, check env dependencies (Gemini key, ffmpeg). If any
        # platform is not logged in, emit `login_required` and pause the
        # pipeline — frontend shows a sticky banner with Retry.
        emit_event("phase_start", phase=0, description="Verifying environment + logins")
        _update_firestore_research({"phase": 0, "currentPhase": 0, "status": "ongoing"})
        _p0_start = time.time()

        emit_event("agent_progress", phase=0, agent="system", status="Launching",
                   progress="Starting Chromium browser with automation profile…")
        # ARCHITECTURE 2026-04-18 (never-die): browser-launch failures are
        # user-recoverable (close other Chrome, run `playwright install`,
        # etc.). Retry re-invokes browser.start() in-place; Stop ends the
        # run. Skip isn't offered — every downstream phase needs a working
        # browser, so skipping Phase 0 is meaningless.
        while True:
            try:
                await browser.start()
                # F4 / DGOPS-7451 — scrub any persisted Google auth state +
                # internal-infra cookies/storage BEFORE Phase 0 runs. Closes
                # the silent session-inheritance vector that let Gemini ride
                # a persisted @distributedglobal.com Workspace session into
                # dg-security-monitor.web.app on 2026-05-05.
                try:
                    await _scrub_persisted_google_auth(
                        browser.context, scope="run_start",
                        reason="DGOPS-7451 F4 — pre-pipeline auth scrub")
                except Exception as _scrub_err:
                    log(f"[security] run-start scrub failed (non-fatal): {_scrub_err}", "WARN")
                break
            except Exception as _launch_err:
                # Most common launch failures:
                #   • Profile locked by another running Chrome instance →
                #     SingletonLock couldn't be removed (another Playwright run)
                #   • Playwright not installed → `playwright install chromium` missing
                #   • Chromium binary missing / corrupt
                _err_msg = str(_launch_err)
                _low = _err_msg.lower()
                if "profile" in _low and ("lock" in _low or "in use" in _low or "singleton" in _low):
                    _friendly = "The automation browser is already open elsewhere. Close any other research runs or browser windows, then Retry."
                elif "executable" in _low or "chromium" in _low or "browser" in _low:
                    _friendly = "The automation browser isn't set up on this machine. Reinstall it, then Retry."
                else:
                    _friendly = "The automation browser couldn't start. Retry — if it keeps failing, check the setup on this machine."
                log(f"Phase 0 browser launch failed: {_err_msg[:200]} — awaiting user decision", "ERROR")
                fail_phase(
                    phase=0,
                    error="Couldn't start the browser",
                    reason=_friendly,
                    agent="system",
                    actions=[
                        {"id": "retry", "label": "Retry", "style": "primary",
                         "command": {"action": "retry_phase", "phase": 0}},
                    ],
                )
                decision = await _controls.await_phase_decision(0)
                if decision == "retry":
                    log("Phase 0 browser launch: user requested retry", "INFO")
                    emit_event("phase_restart", phase=0, reason="user_retry_browser_launch", attempt=0)
                    continue
                # skip (not offered but handled defensively) / stop / timeout
                log(f"Phase 0 browser launch: user {decision} — terminating pipeline", "INFO")
                emit_event("pipeline_stopped", phase=0, reason=f"user_{decision}_browser_launch")
                return

        # Build list of platforms to verify based on enabled agents + phases
        _agents_cfg = config.get("agents", {}) if isinstance(config, dict) else {}
        _need_chatgpt = _agents_cfg.get("chatgpt", True)
        _need_gemini = _agents_cfg.get("gemini", True)
        _need_claude = _agents_cfg.get("claude", True)
        _need_notebooklm = 3 not in skip_phases
        # P4 (YouTube) dropped 2026-05-10 — FE-owned via Data API, no BE
        # browser involvement. P5 (Doc + email) dropped 2026-04-30 — FE-owned
        # via Docs API + Resend. Neither needs login verification in the BE
        # preflight; both use the OAuth refresh token in App Hosting Secrets.

        preflight_platforms = []
        if _need_chatgpt:    preflight_platforms.append(("ChatGPT", "chatgpt"))
        if _need_gemini:     preflight_platforms.append(("Gemini", "gemini"))
        if _need_claude:     preflight_platforms.append(("Claude", "claude"))
        if _need_notebooklm: preflight_platforms.append(("NotebookLM", "notebooklm"))

        # ── #705: CUA/Anthropic availability probe (infra, NOT login) ──
        # The per-platform login walk below is the ONLY place a dead Anthropic
        # key ever surfaced, and `skipInitVerify` blanks that walk entirely
        # (preflight_platforms=[] below). So with "Skip login verification" on,
        # a capped/invalid/429'd key flowed straight into the run and failed
        # open at every phase-time gate, never alerting. The key powers BOTH
        # Vision and CUA, so that's a structural failure, not a login nicety.
        #
        # This probe decouples the two: it runs REGARDLESS of skipInitVerify
        # (it sits ABOVE the _skip_verify_pref blanking), checks availability
        # with ONE minimal Anthropic call, and reuses the same fail-closed
        # `cua_unavailable` card the login walk emits. Gate: only when the run
        # actually uses a CUA-driven platform — `preflight_platforms` here is
        # the real would-verify set (still pre-blanking), so a pure links-only
        # Flow-C run (no agents/NLM → empty list) correctly skips the probe.
        if preflight_platforms:
            while True:
                if _controls.is_stop():
                    emit_event("pipeline_stopped", phase=0, reason="user_stop_cua_probe")
                    return
                emit_event("agent_progress", phase=0, agent="system", status="checking",
                           progress="Checking vision/CUA availability…")
                try:
                    await _probe_cua_available(cua_client)
                    # #724 item 4: a PRIOR failed probe iteration set the queue
                    # gate's "_errored" flag via fail_phase; clear it now that
                    # the probe succeeded, so a run that fully RECOVERED (user
                    # fixed the key + Retry) isn't mis-flagged as errored in the
                    # job-finally gate (which would short-circuit the next
                    # dequeue's FE-P5 wait, "next run starts sooner"). Fail-open
                    # no-op on a first-try success. See gate at job-finally
                    # (_QUEUE_STATE.pop("_errored", ...)).
                    try:
                        _QUEUE_STATE.pop("_errored", None)
                    except Exception:
                        pass
                    break  # reachable — proceed to login walk / phases
                except CuaUnavailableError as cua_err:
                    log(f"Phase 0: CUA availability probe failed — {cua_err}", "ERROR")
                    # #955 Phase 5B: intent=cua_unavailable → blocker (fail-closed;
                    # never auto-fires). The [retry_phase] token expands
                    # byte-identically to the dropped explicit Retry list — and
                    # carries NO skip token, so this stays a Retry-only, fail-
                    # closed card (test_p0_probe_is_fail_closed_with_no_skip_branch).
                    # Distinct alert_id fixes the old phase0_error collision (the
                    # probe + the per-platform cua card + generic P0 errors all
                    # shared one id, differing only by agent).
                    fail_phase(
                        0, "AI service unavailable",
                        _anthropic_key_card_copy("probe"),
                        agent="system",
                        intent="cua_unavailable",
                        alert_id="phase0_cua_unavailable",
                    )
                    _controls.request_pause("cua_unavailable")
                    emit_event("pipeline_paused", phase=0, reason="cua_unavailable")
                    await _controls.wait_if_paused()
                    if _controls.is_stop():
                        emit_event("pipeline_stopped", phase=0, reason="stopped during cua_unavailable")
                        return
                    # Retract the durable pendingDecision the #715 seam mirrored
                    # when fail_phase fired. The central clear keys off
                    # pipeline_resumed/stopped (research.py:~10591); in the
                    # skipInitVerify path NO downstream P0 gate emits one (the
                    # platform walk is blanked + env-check passes), so without
                    # this the card re-surfaces on a cold chat-open during a
                    # HEALTHY run — the exact #705/#715 false-alarm. Emit it
                    # UNCONDITIONALLY on resume (covers Retry; a stray non-retry
                    # resume just re-cards cleanly next cycle). Parity with the
                    # login_required / env-check / pro_required P0 gates. The
                    # platform-walk cua handler omits this but is incidentally
                    # saved by its follow-on login_required gate — this block
                    # has none, so the emit is load-bearing here.
                    emit_event("pipeline_resumed", phase=0, reason="retry")
                    # Retry — re-probe with the (presumably) fixed key. NO Skip
                    # branch here (unlike the login walk): a dead-key infra
                    # failure is fail-closed and skipInitVerify must not bypass
                    # it. Mirrors the platform-walk retry tail at :28229.
                    _controls.consume_retry_phase(0)
                    _controls.retry_init_verify = False
                    continue

        # Honor the user's preference (global Settings → Pipeline → Skip
        # login verification, plus any per-run override in pipeline_config).
        # When on, we skip the per-platform CUA round entirely: browser is
        # already running, Phase 1 will navigate itself to ChatGPT.
        # 2026-07-02: default TRUE — verification is opt-IN (explicit false).
        _skip_verify_pref = bool(pipeline_config.get("skipInitVerify", True)) if isinstance(pipeline_config, dict) else True
        if _skip_verify_pref:
            log("Phase 0: skipInitVerify=true — bypassing login verification per user pref", "INFO")
            emit_event("agent_progress", phase=0, agent="system", status="Skipped",
                       progress="Login verification skipped (per your pipeline settings)")
            preflight_platforms = []  # Nothing to verify below — while loop skipped

        # SEQUENTIAL-2026-04-19: walk platforms one at a time. Old flow
        # opened all 7 tabs in a loop before surfacing a single bulk
        # login_required — that's (a) a Cloudflare-visible robotic burst
        # and (b) overwhelming for the user, who now has to juggle 7
        # partial login flows simultaneously. New flow: cookie-check
        # first, tab-open only on miss, CUA-verify, and if STILL not
        # logged in, emit `login_required` scoped to THAT platform and
        # wait for user retry before touching the next one. This mirrors
        # how the --pair script already walks setup Step 2.
        _preflight_tabs: dict[str, object] = {}
        _pf_opened = 0  # Counts real tab-opens across the whole sequence for stagger pacing
        _global_skip = False
        for idx, (label, key) in enumerate(preflight_platforms):
            if _global_skip or _controls.skip_init_verify:
                _global_skip = True
                log(f"Phase 0: SKIP_INIT_VERIFY — skipping remaining platform {label}", "INFO")
                continue
            attempt = 0
            while True:
                attempt += 1
                if _controls.skip_init_verify:
                    _global_skip = True
                    break
                # NOTE (2026-04-24 #2): cookie + Playwright pre-checks both
                # removed. Cookies lie when the session is server-side
                # invalidated but the cookie hasn't expired yet; Playwright
                # strict DOM selectors match cached sidebar fragments on
                # ChatGPT's logged-out landing (and probably other
                # platforms' skeleton UIs too). Both gave us speed but let
                # false positives through, which was tolerable only until
                # we removed the per-phase login probe safety net — now
                # Phase 0 is the only gate, and it must not lie.
                #
                # Flow below: tab open → 4s settle → URL check → CUA.
                # Vision is the single source of truth. Slower (~5-10s per
                # platform × up to 4 = ~40s worst case on cold starts)
                # but it actually looks at what's on screen. Not a
                # performance win we can afford to keep taking.
                # STEALTH-2026-04-19: jitter between cold-start tab opens.
                # Back-to-back opens in <2s are a strong robotic signal.
                if _pf_opened > 0 and key not in _preflight_tabs:
                    await asyncio.sleep(random.uniform(2.5, 4.5))
                log(f"Phase 0: checking {label} (attempt {attempt})", "INFO")
                emit_event("agent_progress", phase=0, agent=key, status="checking",
                           progress=f"Verifying {label} login…")
                try:
                    info = LOGIN_PLATFORMS.get(key)
                    root = info["root"] if info else "about:blank"
                    tab = _preflight_tabs.get(key)
                    if tab is None:
                        tab = await browser.new_tab(root)
                        _pf_opened += 1
                        _preflight_tabs[key] = tab
                    else:
                        # Retry path — re-navigate so we pick up new login state.
                        try:
                            await tab.goto(root, wait_until="domcontentloaded", timeout=15000)
                        except Exception:
                            pass
                    # Settle for SPA hydration — Claude.ai / Google Docs paint a
                    # neutral "loading" shell for 3-4s that CUA misreads as a
                    # login wall if we peek too early.
                    await asyncio.sleep(4.0)
                    # Cheap negative signal first: URL on a known login host →
                    # definitely logged out. Skip the CUA call to save budget.
                    try:
                        current_url = (tab.url or "").lower()
                    except Exception:
                        current_url = ""
                    if any(h in current_url for h in _LOGIN_HOST_NEGATIVES):
                        log(f"Phase 0: {label} on login URL ({current_url[:60]}) — not logged in", "INFO")
                        ok = False
                    else:
                        # Vision verification is the gate. URL already
                        # cleared the cheap "obvious login wall" case;
                        # everything else is a CUA decision.
                        ok = await verify_login_cua(tab, key, cua_client)
                except CuaUnavailableError as cua_err:
                    # Structural Anthropic failure (billing cap / invalid
                    # key / 529). Surface a distinct alert so the user
                    # doesn't chase a phantom auth issue.
                    # 2026-05-05 (DGOPS-7357 follow-up): Skip removed.
                    # Without CUA the pipeline can't tell login walls
                    # from authenticated sessions, so skipping verification
                    # is a footgun — it lets a logged-out platform flow
                    # into Phase 1/2/3 where it crashes harder and later.
                    # Only Retry. The global Settings → Skip login
                    # verification toggle still bypasses the loop entirely
                    # at the top of the platform-walk (line ~18677); that
                    # path is the right escape hatch for "I know what I'm
                    # doing, run without CUA on purpose".
                    log(f"Phase 0: CUA unavailable for {label}: {cua_err}", "ERROR")
                    # #955 Phase 5B: intent=cua_unavailable → blocker; token
                    # expands byte-identically to the dropped explicit Retry list.
                    # Distinct per-platform alert_id fixes the phase0_error
                    # collision (this loop still honors skip_init_verify below —
                    # test_cli_dispatcher pins that; the card is Retry-only).
                    fail_phase(
                        0, "AI service unavailable",
                        _anthropic_key_card_copy("login_walk", label=label),
                        agent=key,
                        intent="cua_unavailable",
                        alert_id=f"phase0_cua_unavailable_{key}",
                    )
                    _controls.request_pause("cua_unavailable")
                    emit_event("pipeline_paused", phase=0, reason="cua_unavailable")
                    await _controls.wait_if_paused()
                    if _controls.is_stop():
                        emit_event("pipeline_stopped", phase=0, reason="stopped during cua_unavailable")
                        return
                    # DGOPS-7710-followup: honor skip_init_verify so CLI `s`
                    # (or FE Skip-verification toggle) breaks out of the CUA
                    # retry loop. Without this check the function just falls
                    # through to consume_retry_phase and continues, ignoring
                    # the user's skip signal. Mirrors the login_required
                    # pattern at line ~21700.
                    if _controls.skip_init_verify:
                        log("Phase 0: SKIP_INIT_VERIFY during cua_unavailable — bailing CUA loop", "INFO")
                        _global_skip = True
                        break
                    # retry — clear flag + loop continues, fresh CUA call
                    # picks up the new key.
                    _controls.consume_retry_phase(0)
                    _controls.retry_init_verify = False
                    continue
                except Exception as e:
                    log(f"Phase 0: login check failed for {key}: {e}", "WARN")
                    ok = False

                if ok:
                    emit_event("agent_progress", phase=0, agent=key,
                               status="ok", progress=f"{label}: logged in ✓")
                    # Pro-tier verification (DGOPS-7363). Runs only for
                    # platforms that have a Pro/Free split affecting Deep
                    # Research output (ChatGPT/Claude/Gemini). Skipped if
                    # the user already opted into Free on a prior platform
                    # in this run, or if no CUA client is available.
                    if (key in _PRO_TIER_PLATFORMS
                            and cua_client is not None
                            and not _controls.pro_warning_acknowledged):
                        emit_event("agent_progress", phase=0, agent=key,
                                   status="checking_tier",
                                   progress=f"{label}: checking subscription tier…")
                        try:
                            tier = await _cua_pro_tier_call(tab, key, cua_client)
                        except CuaUnavailableError as cua_err:
                            log(f"Phase 0: CUA unavailable during {label} tier check — assuming Pro: {cua_err}", "WARN")
                            tier = "unsure"
                        if tier == "free":
                            log(f"Phase 0: {label} on Free tier — emitting pro_required alert", "INFO")
                            emit_event("agent_progress", phase=0, agent=key,
                                       status="not_pro",
                                       progress=f"{label}: Pro NOT detected — Phase output will be degraded")
                            _emit_pro_required_alert(phase=0, agent=key, source=f"phase0/platform={key}")
                            _controls.request_pause("pro_required")
                            emit_event("pipeline_paused", phase=0, reason="pro_required")
                            await _controls.wait_if_paused()
                            if _controls.is_stop():
                                emit_event("pipeline_stopped", phase=0, reason="user_stop_pro_required")
                                return
                            if _controls.consume_retry_phase(0):
                                # User clicked Retry — they're (presumably)
                                # signing in with a Pro account. Close the
                                # current tab so the next iteration re-opens
                                # fresh and re-runs login + tier checks from
                                # scratch. The while loop's `continue` re-runs
                                # the whole verification for THIS platform.
                                log(f"Phase 0: user clicked Retry on {label} pro_required — re-verifying", "INFO")
                                emit_event("pipeline_resumed", phase=0, reason="pro_retry")
                                _t = _preflight_tabs.pop(key, None)
                                if _t is not None:
                                    try: await _t.close()
                                    except Exception: pass
                                emit_event("phase_start", phase=0,
                                           description=f"Re-checking {label} after Pro retry (attempt {attempt + 1})")
                                _update_firestore_research({"phase": 0, "currentPhase": 0, "status": "ongoing"})
                                continue  # re-run the while loop for this platform
                            if _controls.consume_continue_anyway():
                                _controls.pro_warning_acknowledged = True
                                log("Phase 0: user opted into Free — suppressing further Pro alerts this run", "INFO")
                                # F3: clear stale pro_required alert documents
                                # from FE store BEFORE the resumed event fires
                                # (resumed triggers the FE auto-clear sweep).
                                # Order: flag → clear emit → resumed emit.
                                _clear_pro_required_alerts(triggered_at_phase=0)
                                emit_event("pipeline_resumed", phase=0, reason="continue_with_free")
                                emit_event("agent_progress", phase=0, agent=key,
                                           status="free_acknowledged",
                                           progress=f"{label}: continuing on Free (user-acknowledged)")
                            else:
                                # Resume without continue_anyway / retry — treat
                                # as acknowledgement (user dismissed the alert
                                # then resumed via chat-box).
                                _controls.pro_warning_acknowledged = True
                                log("Phase 0: pro_required pause resumed without explicit choice — treating as Free-acknowledged", "INFO")
                                # F3: same clear pattern — even on a generic
                                # resume the user has effectively acknowledged
                                # Free, so the actionable alert must go away.
                                _clear_pro_required_alerts(triggered_at_phase=0)
                                emit_event("pipeline_resumed", phase=0, reason="resume")
                        elif tier == "pro":
                            log(f"Phase 0: {label} Pro detected ✓", "INFO")
                            emit_event("agent_progress", phase=0, agent=key,
                                       status="pro_ok", progress=f"{label}: Pro tier ✓")
                        else:  # unsure → fail open
                            log(f"Phase 0: {label} tier UNSURE — assuming Pro (fail-open)", "INFO")
                    break  # move to next platform

                # Not logged in — emit login_required scoped to JUST this
                # platform and wait for user retry.
                emit_event("agent_progress", phase=0, agent=key,
                           status="needs_login", progress=f"{label}: login required ✗")
                _login_msg = f"{label} needs a login. Sign in using the open browser, then Retry."
                # alert_id aligns Phase 0 with the phase>=1 path so the live
                # event card and the doc-hydrated card dedup on the same key.
                _login_alert_id = f"phase0_login_required_{key}"
                # #955 Phase 5: author through the seam (event_name unchanged;
                # every legacy kwarg preserved via **extra). Agent-less on the
                # wire (P0 walk carries no agent field); Skip at phase 0 →
                # skip_init_verify (byte-exact to the FE loginDecisionAlert P0
                # card). Fresh decision_id per attempt — the agent-less
                # pipeline_resumed below clears _active_decisions between tries.
                emit_decision(
                    intent="login_required", event_name="login_required",
                    phase=0, agent=None,
                    facts={"title": _login_msg, "details": ""},
                    actions=_alert_actions_for("login_required", 0, None),
                    alert_id=_login_alert_id,
                    platforms=[key], platformLabels=[label],
                    machineName=socket.gethostname(),
                    attempt=attempt, message=_login_msg)
                _controls.request_pause("login_required")
                emit_event("pipeline_paused", phase=0, reason="login_required")
                # Durable mirror so opening this chat re-surfaces the Retry card
                # even when it wasn't the viewed tab as the gate fired.
                _persist_pending_decision({
                    "kind": "login_required",
                    "phase": 0,
                    "platforms": [key],
                    "platformLabels": [label],
                    "machineName": socket.gethostname(),
                    "attempt": attempt,
                    "message": _login_msg,
                    "alert_id": _login_alert_id,
                })
                await _controls.wait_if_paused()
                # Gate resolved (resume / skip / stop) — retract the durable
                # card. A still-failing retry re-persists on the next loop.
                _clear_pending_decision()
                if _controls.is_stop():
                    emit_event("pipeline_stopped", phase=0, reason="stopped during login_required")
                    return
                if _controls.skip_init_verify:
                    log(f"Phase 0: SKIP_INIT_VERIFY during {label} — skipping remaining platforms", "INFO")
                    _global_skip = True
                    break
                # Unify retry signals: the login_required banner's dedicated
                # "Retry" button writes action="retry_init_verify", but the
                # generic PhaseAlertPanel Retry button writes action="retry_phase"
                # with phase=0. Both mean the same thing here — the user
                # acted in the browser, re-check this platform with fresh state.
                if _controls.consume_retry_phase(0):
                    _controls.retry_init_verify = True
                _is_retry = bool(_controls.retry_init_verify)
                emit_event("pipeline_resumed", phase=0, reason="retry" if _is_retry else "resume")
                # Always close the tab on resume. The user just did something
                # in the browser (logged in, solved a CAPTCHA, dismissed a
                # popup) — re-using the stale tab would make the next CUA
                # screenshot identical to the pre-pause one, defeating the retry.
                _t = _preflight_tabs.pop(key, None)
                if _t is not None:
                    try: await _t.close()
                    except Exception: pass
                if _is_retry:
                    _controls.retry_init_verify = False
                    emit_event("phase_start", phase=0,
                               description=f"Re-checking {label} (attempt {attempt + 1})")
                    _update_firestore_research({"phase": 0, "currentPhase": 0, "status": "ongoing"})
                log(f"Phase 0: resumed ({'retry' if _is_retry else 'resume'}) — re-checking {label}", "INFO")
                # while loop continues — re-check same platform with fresh state
            # Inner while exited — either verified, skipped globally, or stopped.
            if _global_skip:
                emit_event("agent_progress", phase=0, agent="system", status="Skipped",
                           progress="Verification skipped by user")
                break  # break outer for

        # 2026-05-11: bridge the silent gap between the last platform's
        # CUA verdict and phase_complete:0. Without an emit here, the
        # dropdown sat quiet after the final ✓ while env_check +
        # preflight tab cleanup ran (~0.5-2s on a warm path; longer when
        # resolve_api_key round-trips to Firestore for a per-user
        # override). User reports a "stuck for a small instance" feel
        # after the 2026-05-10 cutover dropped youtube/gmail/gdocs from
        # preflight — 4 platforms make the trailing env-check window
        # proportionally more visible than it was with 7. Skip when
        # verification was globally bypassed (the _global_skip branch
        # above emits its own status), and skip when no real platforms
        # were verified (env-only path is too short to need a bridge).
        if not _global_skip and preflight_platforms:
            emit_event("agent_progress", phase=0, agent="system",
                       status="Finalizing",
                       progress="All sessions verified — handing off to the research phases…")

        # Env checks: required keys for the pipeline + ffmpeg for video.
        # Run these regardless of whether login verification was skipped —
        # missing env breaks the pipeline whether or not logins are verified.
        # All three checks resolve via the SAME functions the actual call
        # sites use, so a key set in the Account page (Firestore) wins over
        # any local env. Without this, the gate would falsely refuse a run
        # the BE could otherwise complete.
        _env_ok = True
        _env_errors: list[str] = []
        # Anthropic / CUA — needed across phases for vision tier-2 + tier-3
        # (CUA fallback). Hard requirement for any non-trivial run; surface
        # the error before phase 1 so the user gets a clear "add it via
        # Account → API Config" instead of a mid-phase vision crash.
        if not resolve_api_key():
            _env_ok = False
            _missing_msg = _anthropic_key_card_copy("missing")
            _env_errors.append(_missing_msg)
        if not _env_ok:
            # #955 Phase 5B: env-check is its OWN intent (env_missing_key) but
            # shares the login_required EVENT name (the FE's isEnv branch keys on
            # envErrors). event_name unchanged; every legacy kwarg preserved via
            # **extra; agent-less wire. Blocker → no deadline. The FE-inert
            # actions list matches the real FE card (Retry + "Skip sign-in check").
            emit_decision(
                intent="env_missing_key", event_name="login_required",
                phase=0, agent=None,
                facts={"title": _missing_msg, "details": ""},
                actions=_alert_actions_for("env_missing_key", 0, None),
                alert_id="phase0_env_check",
                platforms=[], platformLabels=[],
                machineName=socket.gethostname(),
                envErrors=_env_errors, attempt=1, message=_missing_msg)
            # #710 parity: durable mirror so an env-check failure raised while
            # this chat wasn't the viewed tab re-surfaces the card on open.
            # (Same kind as login_required — the FE's isEnv branch renders it.)
            # Kept explicit (already persisted before the pause today).
            _persist_pending_decision({
                "kind": "login_required",
                "phase": 0,
                "platforms": [],
                "platformLabels": [],
                "machineName": socket.gethostname(),
                "envErrors": _env_errors,
                "attempt": 1,
                "message": _missing_msg,
                "alert_id": "phase0_env_check",
            })
            _controls.request_pause()
            emit_event("pipeline_paused", phase=0, reason="login_required")
            await _controls.wait_if_paused()
            if _controls.is_stop():
                emit_event("pipeline_stopped", phase=0, reason="stopped during env_error")
                return
            emit_event("pipeline_resumed", phase=0, reason="retry")

        # Close the preflight verification tabs so they don't clutter the
        # window through Phases 1-5. CRITICAL: Browser.new_tab() reassigns
        # self.page to each new tab, so `browser.page` is the LAST preflight
        # tab we opened. Phase 1 navigates `browser.page` to ChatGPT — we
        # must KEEP that page alive. So: close every preflight tab EXCEPT
        # whichever one is currently browser.page. Phase 1's navigate() will
        # then reuse that page as its ChatGPT tab.
        primary = browser.page
        for _key, _tab in _preflight_tabs.items():
            if _tab is primary:
                continue
            try:
                await _tab.close()
            except Exception:
                pass
        _preflight_tabs.clear()

        if _skip_verify_pref or _controls.skip_init_verify:
            _p0_summary = "Preflight skipped — trusting existing sessions"
        elif preflight_platforms:
            _p0_summary = f"Preflight passed — {len(preflight_platforms)} platform(s) ready"
        else:
            _p0_summary = "Preflight complete"
        emit_event("phase_complete", phase=0,
                   durationSec=int(time.time() - _p0_start),
                   summary=_p0_summary)

        # Pre-emit phase_start(1) BEFORE the trust gate runs. Still load-
        # bearing post-#899 even though the gate is now milliseconds: the
        # gate's own tile emits ("sign-in trusted ✓" / "unverified") are
        # dropped by the FE unless a P1 phase message already exists
        # (usePipeline bails when getPhaseMessageId returns nothing). If
        # the dispatch below skips P1, phase_skipped follows and the FE
        # flips the chip running → skipped — same as a mid-phase skip.
        _p1_start_emitted = False
        if (start_phase <= 1 and 1 not in skip_phases
                and 1 not in _controls.skipped_phases
                and not _controls.is_stop()):
            emit_event("phase_start", phase=1,
                       description="Generating research brief with ChatGPT Pro + latest thinking model",
                       agents=["chatgpt"])
            _update_firestore_research({"phase": 1, "currentPhase": 1, "status": "ongoing"})
            _p1_start_emitted = True

        # ══════════════════════ PHASE 1 trust gate (BE-2, slimmed by #899) ══════════════════════
        # When init was skipped (skip_init_verify=True), the gate is a
        # zero-navigation cookie TRUST CHECK (no tab, no CUA, no pause —
        # run_phase1's work-tab preflight owns real verification on the
        # page it drives). 'skipped' is only the prior-skip echo: chatgpt
        # already in skipped_agents from an earlier pause/skip. That routes
        # into the manual_brief flow inline — caller pre-populates
        # brief_text + brief_artifact and marks _gate_skipped_p1=True so
        # the dispatch chain steers into the SKIP branch (which then emits
        # phase_skipped + creates BriefArtifact). No-op when init verified.
        _gate_skipped_p1 = False
        # Did Phase 1 run a LIVE brief generation (ChatGPT) this session? Init
        # above the P1 block so it's always defined — including resume-into-P2
        # where the P1 block is skipped. Gates P2 source-doc delivery: only
        # attach the user's sources to P2 when P1 did NOT distill them into a
        # brief itself (P1-ON would double-feed). Set True only at the live
        # `brief_text = p1["text"]` point below.
        _p1_ran_live = False
        if (start_phase <= 1 and 1 not in skip_phases
                and 1 not in _controls.skipped_phases
                and _controls.skip_init_verify
                and not _controls.is_stop()):
            _p1_gate = await _phase_verify_gate(1, "chatgpt", browser, cua_client)
            if _p1_gate == "stop":
                emit_event("pipeline_stopped", phase=1, reason="user_stop_at_verify_gate")
                return
            if _p1_gate == "skipped":
                # ChatGPT was skip-clicked at an earlier pause (the gate
                # itself no longer prompts — #899). Per the
                # ChatGPT-runs-twice design (P1 brief + P2 task), skip-at-P1
                # cannot silently produce an empty brief — Phase 2 hard-fails
                # with "No brief text available". Mirror the existing post-fail
                # manual_brief flow at ~line 20554: emit manual_brief_required,
                # block on extra_context (3h backstop), consume the user-typed
                # brief, then steer the dispatch into SKIP so brief_artifact
                # is created and Phase 2 runs with the manual brief.
                log("Phase 1: verify gate skipped → manual brief flow", "INFO")
                # #955 Phase 5: author through the seam (event_name unchanged).
                # actions=[] is EXPLICIT and load-bearing — manual_brief_required
                # is one of two events whose FE handler RENDERS evt.data.actions,
                # so the empty list is wire parity, not additive; the brief_input
                # token stays unwired (the explicit [] bypasses the expander). The
                # brief still arrives as an add_context command on the 0.5s wait
                # loop below (no button). message preserved verbatim.
                emit_decision(intent="manual_brief", event_name="manual_brief_required",
                              phase=1, actions=[],
                              facts={"title": "Type your research brief into chat, then press Resume."},
                              message="Type your research brief into chat, then press Resume.",
                              dismissible=True, alert_id="phase1_manual_brief_required")
                _BRIEF_WAIT_BACKSTOP_S = 3 * 3600
                _brief_wait_start = time.time()
                while not _controls.peek_extra_context() and not _controls.is_stop():
                    if (time.time() - _brief_wait_start) > _BRIEF_WAIT_BACKSTOP_S:
                        log("Phase 1: manual brief wait exceeded 3h — auto-failing", "WARN")
                        fail_phase(1,
                                   "No brief received",
                                   "We waited for you to type a research brief in chat, "
                                   "but none arrived. Retry to keep waiting, or Skip "
                                   "this step.")
                        emit_event("pipeline_stopped", phase=1,
                                   reason="manual_brief_wait_backstop_3h")
                        return
                    await asyncio.sleep(0.5)
                if _controls.is_stop():
                    log("Phase 1: stop pressed during manual brief wait", "INFO")
                    emit_event("pipeline_stopped", phase=1, reason="user_stop_during_manual_brief")
                    return
                brief_text = (_controls.pop_extra_context() or "").strip()
                brief_url = ""
                log(f"Phase 1: user supplied manual brief via gate ({len(brief_text)} chars)")
                _gate_skipped_p1 = True

        # ══════════════════════ PHASE 1: Brief ══════════════════════
        p1 = None
        _user_skip_p1 = _controls.consume_phase_skip(1)
        if 1 in skip_phases or _user_skip_p1 or _gate_skipped_p1:
            if _gate_skipped_p1:
                _reason = "user_skip_at_verify_gate"
            elif _user_skip_p1:
                _reason = "user_skip"
            else:
                _reason = "Disabled in pipeline config"
            log(f"Phase 1: SKIPPED ({_reason})")
            emit_event("phase_skipped", phase=1, reason=_reason)
            # Phase-1-skip must still hydrate brief_text so Phase 2 has a
            # brief to paste. Priority: explicit brief_file > on-disk
            # documents/brief.md (written by the inline-brief path earlier,
            # or by a previous run we're resuming). Phase 2 hard-fails
            # without this ("No brief text available — cannot run Phase 2").
            _loaded_from = None
            if brief_file and Path(brief_file).exists():
                try:
                    brief_text = Path(brief_file).read_text(encoding="utf-8")
                    _loaded_from = f"brief_file={brief_file}"
                except Exception as _e:
                    log(f"Phase 1 skip: could not read brief_file ({_e})", "WARN")
            if not brief_text:
                for _bp in [queue_dir / "documents" / "brief.md", queue_dir / "brief.md"]:
                    if _bp.exists():
                        try:
                            brief_text = _bp.read_text(encoding="utf-8")
                            _loaded_from = f"disk={_bp}"
                            break
                        except Exception:
                            continue
            if brief_text.startswith("# Research Brief\n\n"):
                brief_text = brief_text[len("# Research Brief\n\n"):]
            brief_artifact = BriefArtifact(text=brief_text, url="")
            if brief_text:
                log(f"Phase 1 skip: loaded brief ({len(brief_text)} chars) from {_loaded_from}")
            else:
                log("Phase 1 skip: no brief source — Phase 2 will fail unless one appears", "WARN")
        elif start_phase <= 1:
            if not _p1_start_emitted:
                # Edge case: pre-emit was gated out above (e.g. stop pressed
                # mid-verify-gate, then cleared). Emit now so the dispatch
                # has a corresponding start event.
                emit_event("phase_start", phase=1, description="Generating research brief with ChatGPT Pro + latest thinking model", agents=["chatgpt"])
                _update_firestore_research({"phase": 1, "currentPhase": 1, "status": "ongoing"})
            _p1_start = time.time()
            # Active-time ceiling for Phase 1 — paused seconds don't count.
            # If the user pauses for lunch, the budget is preserved.
            # Enforced via _await_phase_with_active_deadline at each call
            # below; budget is shared across the for _p1_attempt restart loop.
            # PHASE_1_MAX_MIN is the cap (env-overridable).
            # Per-phase login probe removed (2026-04-24) for the happy
            # path. Phase 0 is the single source of truth for login state
            # — if Phase 0 marked a platform "ok" (cookie + DOM or CUA
            # verdict), we trust it and proceed. On real session drift
            # mid-run, the phase's own navigation + scraping will surface
            # a real failure through fail_phase, which the alert panel
            # handles.
            #
            # 2026-05-08 follow-up, rewritten by #899: on skip-init runs
            # _phase_verify_gate above is now a zero-navigation cookie
            # TRUST CHECK only. Real phase-time verification lives in
            # run_phase1 itself — the work-tab preflight
            # (_work_tab_signed_out + _work_tab_login_pause) probes the
            # page P1 actually drives, and runs REGARDLESS of verifyLogins
            # (cheap insurance for sessions dying after a P0 walk).
            # ARCHITECTURE 2026-04-18: Never-die retry loop. Any fail_phase
            # inside this block awaits the user's Retry/Skip/Stop decision
            # via _controls.await_phase_decision(1). Retry loops back; Skip
            # breaks out with brief_text="" so downstream phases can decide
            # what to do with no brief; Stop returns from the pipeline.
            _p1_skipped_after_error = False
            _brief_from_file = False
            while True:
                if brief_file:
                    brief_text = Path(brief_file).read_text(encoding="utf-8")
                    # Strip the common "# Research Brief\n\n" prefix if present so
                    # downstream token counts / paste ops aren't inflated by it.
                    if brief_text.startswith("# Research Brief\n\n"):
                        brief_text = brief_text[len("# Research Brief\n\n"):]
                    log(f"Phase 1: SKIPPED — loaded brief from {brief_file} ({len(brief_text)} chars)")
                    brief_url = ""
                    _brief_from_file = True
                    break
                fb1 = get_feedback(1)
                # Restart loop: if mid-phase pause+input+resume trips
                # `_runtime.restart_requested`, merge the buffered context into
                # the topic and rerun Phase 1. Capped at 3 attempts.
                p1 = None
                current_topic = topic
                for _p1_attempt in range(3):
                    _runtime.restart_requested = False
                    # Inner timeout-retry loop: if the active-time ceiling
                    # fires, surface to user with [Retry, Skip] (recoverable),
                    # NOT terminate the run. lambda factory creates a fresh
                    # coroutine on each retry — can't await an already-awaited
                    # coroutine, so the helper takes a factory now.
                    while True:
                        try:
                            p1 = await _await_phase_with_active_deadline(
                                1, PHASE_1_MAX_MIN,
                                lambda: run_phase1(browser, cua_client, current_topic, pdf_paths, verbose, feedback=fb1),
                                soft_warn_only=True,  # 2026-05-04: long brief gens (30+m on large PDFs) are legitimate; warn but don't bail
                            )
                            break  # success — exit inner retry loop
                        except _PhaseSoftDecision as _sd:
                            if _sd.decision == "retry":
                                emit_event("phase_restart", phase=1, reason="user_retry_after_soft_timeout")
                                continue
                            if _sd.decision == "skip":
                                emit_event("phase_skipped", phase=1, reason="user_skip_after_soft_timeout")
                                _p1_skipped_after_error = True
                                p1 = None
                                break
                            log(f"[P1] Unexpected _PhaseSoftDecision.decision={_sd.decision!r}", "ERROR")
                            raise
                        except asyncio.TimeoutError:
                            # Legacy hard-path safety net — with soft_warn_only=True the
                            # helper raises _PhaseSoftDecision instead of TimeoutError, so
                            # this branch is normally unreachable. Kept as a guard in case
                            # something inside run_phase1 raises a bare TimeoutError that
                            # escapes the helper's wrap.
                            _decision = await _phase_timeout_decision(1, PHASE_1_MAX_MIN, agent="chatgpt")
                            if _decision == "retry":
                                emit_event("phase_restart", phase=1, reason="user_retry_after_timeout")
                                continue  # rerun via factory with fresh deadline
                            if _decision == "skip":
                                emit_event("phase_skipped", phase=1, reason="user_skip_after_timeout")
                                _p1_skipped_after_error = True
                                p1 = None
                                break
                            # stop / fall-through (user explicitly hit Stop)
                            emit_event("pipeline_stopped", phase=1, reason=f"user_{_decision}_after_timeout")
                            return
                    if _p1_skipped_after_error:
                        break  # exit outer for _p1_attempt loop too
                    if fb1:
                        clear_feedback(1)
                        fb1 = ""  # only feed in on first attempt
                    if not _runtime.restart_requested:
                        break
                    extra_ctx_retry = _controls.pop_extra_context()
                    if not extra_ctx_retry:
                        break
                    current_topic = current_topic + "\n\nADDITIONAL USER CONTEXT:\n" + extra_ctx_retry
                    log(f"[Phase 1] Mid-phase restart with +{len(extra_ctx_retry)} chars of user input")
                    emit_event("phase_restart", phase=1,
                               reason="mid_phase_input_on_resume",
                               chars=len(extra_ctx_retry), attempt=_p1_attempt+1)
                if _controls.is_stop():
                    # User pressed Stop during Phase 1 (e.g. on the Pro-required
                    # backstop alert). Don't fire the "no brief generated"
                    # alert — Stop already emitted pipeline_stopped. Outer
                    # finally cleans up the browser. Pre-existing latent bug
                    # surfaced by DGOPS-7363's Phase 1 backstop.
                    log("Phase 1: stop_event set — exiting cleanly (no fail_phase cascade)", "INFO")
                    return
                if not p1 or not p1["text"]:
                    _p1_login_timeout = "chatgpt" in _controls.login_pause_timeout_agents
                    _p1_login_skipped = ("chatgpt" in _controls.skipped_agents
                                         and not _p1_login_timeout)
                    if _p1_login_skipped:
                        # #899: the user EXPLICITLY chose Skip on the work-tab
                        # login pause inside Phase 1 ("I'll write the brief
                        # myself") — don't re-ask via the generic "No brief
                        # was generated" card; go straight to the manual-brief
                        # flow, exactly like the verify gate's skip did. The
                        # UNATTENDED 10-min timeout deliberately does NOT land
                        # here: it gets the Retry-able card below, so a user
                        # returning at minute 11 can sign in + Retry instead
                        # of finding the run stranded in a 3h typed-brief wait
                        # nobody asked for.
                        log("Phase 1: ChatGPT skipped at the login pause → manual brief flow", "INFO")
                        decision = "skip"
                    else:
                        log("Phase 1 failed — no brief generated; awaiting user decision", "ERROR")
                        fail_phase(
                            phase=1,
                            error="No brief was generated",
                            reason="ChatGPT didn't produce a brief. Make sure ChatGPT is signed in, then Retry — or Skip and write your own.",
                            agent="chatgpt",
                        )
                        decision = await _controls.await_phase_decision(1)
                    if decision == "retry":
                        log("Phase 1: user requested retry — re-running from the top", "INFO")
                        # #899: a Retry supersedes any stale login-pause skip —
                        # without this discard the preflight pause would see
                        # skipped_agents and return 'skipped' on its first
                        # tick, making Retry structurally unable to work.
                        _controls.consume_skip_marker("chatgpt")
                        _controls.login_pause_timeout_agents.discard("chatgpt")
                        emit_event("phase_restart", phase=1, reason="user_retry_after_error", attempt=0)
                        continue
                    if decision == "skip":
                        log("Phase 1: user skipped after error — switching to manual brief entry mode", "INFO")
                        # ONE terminal skip event, with the honest reason for
                        # how we got here (#899 review: the login-pause route
                        # used to double-emit with a phantom 'after_error').
                        emit_event("phase_skipped", phase=1,
                                   reason=("user_skip_at_login_pause" if _p1_login_skipped
                                           else "user_skip_after_error"))
                        # ── P1 skip → manual brief flow ──
                        # Instead of proceeding with an empty brief, ask the
                        # user to paste their own. Emit a Template-shape info
                        # alert with [Dismiss] and block on extra_context
                        # until the chat input lands a brief. On consume,
                        # use the pasted text as the brief and continue.
                        # #955 Phase 5: author through the seam (see Site A note
                        # above — actions=[] load-bearing, message verbatim).
                        emit_decision(intent="manual_brief", event_name="manual_brief_required",
                                      phase=1, actions=[],
                                      facts={"title": "Type your research brief into chat, then press Resume."},
                                      message="Type your research brief into chat, then press Resume.",
                                      dismissible=True, alert_id="phase1_manual_brief_required")
                        # 3h backstop (2026-04-30): if the user walks away
                        # and never pastes a brief or stops, the wait used
                        # to hang forever, leaving the run in `ongoing`
                        # status indefinitely. After 3h we auto-fail the
                        # phase with [Retry, Skip] so the run reaches a
                        # terminal-or-actionable state.
                        _BRIEF_WAIT_BACKSTOP_S = 3 * 3600
                        _brief_wait_start = time.time()
                        while not _controls.peek_extra_context() and not _controls.is_stop():
                            if (time.time() - _brief_wait_start) > _BRIEF_WAIT_BACKSTOP_S:
                                log("Phase 1: manual brief wait exceeded 3h — auto-failing", "WARN")
                                # 2026-05-15: previously this path emitted
                                # fail_phase (recoverable alert with
                                # [Retry, Skip]) THEN immediately
                                # pipeline_stopped + return — tearing down
                                # the run while the user saw Retry/Skip
                                # buttons that did nothing. Honor the
                                # never-die contract: fail_phase emits the
                                # actionable alert, await the user's
                                # decision, and act on it. Mirrors the
                                # pattern at research.py:22131-22146.
                                fail_phase(1,
                                           "No brief received",
                                           "We waited for you to type a research brief in "
                                           "chat, but none arrived. Retry to keep waiting, "
                                           "or Skip this step.")
                                _bs_decision = await _controls.await_phase_decision(1)
                                if _bs_decision == "retry":
                                    emit_event("phase_restart", phase=1,
                                               reason="user_retry_after_brief_wait_backstop")
                                    _brief_wait_start = time.time()
                                    continue
                                if _bs_decision == "skip":
                                    emit_event("phase_skipped", phase=1,
                                               reason="user_skip_after_brief_wait_backstop")
                                    _p1_skipped_after_error = True
                                    # Break out of the inner backstop loop.
                                    # The post-while skip-propagation check
                                    # below carries _p1_skipped_after_error
                                    # out through the outer `while True:` so
                                    # downstream skip handling (stub
                                    # phase_complete, empty brief artifact,
                                    # P2 continues without a brief) actually
                                    # runs — `return` here would discard the
                                    # flag and exit run_phase1 prematurely.
                                    break
                                # "stop" / "timeout" — terminate the run.
                                # pipeline_stopped emit matches the
                                # canonical pattern at research.py:22128.
                                emit_event("pipeline_stopped", phase=1,
                                           reason=f"user_{_bs_decision}_after_brief_wait_backstop")
                                return
                            await asyncio.sleep(0.5)
                        # 2026-05-15: skip-after-backstop propagation.
                        # When the 3h-backstop skip branch breaks the inner
                        # loop with _p1_skipped_after_error=True, exit the
                        # outer `while True:` so the run_phase1 tail at
                        # ~line 22275 sees the flag and emits the stub
                        # phase_complete + sets up an empty brief artifact.
                        # Without this guard we'd fall through to the
                        # "user typed a brief" path below and reset the flag.
                        if _p1_skipped_after_error:
                            break
                        if _controls.is_stop():
                            log("Phase 1: stop pressed during manual brief wait", "INFO")
                            emit_event("pipeline_stopped", phase=1, reason="user_stop_during_manual_brief")
                            return
                        brief_text = (_controls.pop_extra_context() or "").strip()
                        brief_url = ""
                        log(f"Phase 1: user supplied manual brief ({len(brief_text)} chars)")
                        _p1_skipped_after_error = False
                        break
                    # stop / timeout — only way the pipeline actually ends
                    log(f"Phase 1: user {decision} after error — terminating pipeline", "INFO")
                    emit_event("pipeline_stopped", phase=1, reason=f"user_{decision}_after_error")
                    return
                brief_text = p1["text"]
                brief_url = p1.get("url", "")
                _p1_ran_live = True  # ChatGPT generated the brief — sources already absorbed
                # Stamp the "don't attach to P2" decision durably NOW, not at
                # P2 entry — otherwise a pause AFTER P1 but BEFORE P2 entry
                # leaves the manifest un-decided, and resume-into-P2 (where the
                # P1 block is skipped + _p1_ran_live re-inits False) would flip
                # it to attach, double-feeding sources P1 already distilled.
                _finalize_p2_source_decision(False)
                # Propagate the ChatGPT-share / conversation URL to the
                # Firestore aggregate so P5's Doc body shows the
                # "ChatGPT Brief: <url>" line. This URL is NOT emitted as
                # a separate link_extracted (P1 surfaces only the in-app
                # /documents primary to the FE) — but the Doc spec
                # requires it, so we land it directly in the aggregate.
                if brief_url:
                    try:
                        update_link_in_firestore("brief", brief_url,
                                                 label="ChatGPT Brief", phase=1, verified=True)
                    except Exception:
                        pass
                break
            # Save brief in documents/
            if _p1_skipped_after_error:
                # User chose Skip after a brief-generation error — emit a
                # stub phase_complete so the pipeline tile shows the skip
                # outcome instead of hanging, and set brief_artifact to an
                # empty shell so downstream Phase 2 can make its own
                # decision (it has its own fail_phase + await_phase_decision
                # when the paste step finds no content).
                brief_artifact = BriefArtifact(text="", url="")
                # ⭐ `skipped` is what stops the web app announcing "Brief
                # ready" for a brief that does not exist. This branch sets an
                # empty artifact, terminalizes the phase and writes the tile as
                # "skipped" three lines down — but the event it sends is a plain
                # phase_complete, and the notifier has nothing else to read: the
                # summary is prose and phase 1 legitimately completes with no
                # links (the resume-with-input regen path emits `links=[]`
                # whenever no share URL was captured).
                #
                # ⛔ The event itself must still be emitted. Same contract as
                # phase 5's P5-OFF twin: the tile would hang without it. Mark
                # it; don't delete it.
                emit_event("phase_complete", phase=1, durationSec=int(time.time() - _p1_start),
                    skipped=True,
                    summary="Phase 1 skipped after error — no brief generated")
                _update_firestore_research({"phase": 1, "status": "ongoing"})
                # Tile/Icon Consistency (mirrors P2 at line ~19244): persist
                # a terminal P1+ChatGPT status to the root doc so the listing
                # tile + chat phase icon + agent dropdown stay correct after
                # reload. Without this, on reopen the FE falls back to the
                # last volatile per-agent status (e.g. "submitting"), which
                # never matches the green-tick gate.
                _write_phase_terminal_status(1, "skipped")
                # 2026-05-12: REMOVED `_write_agent_terminal_status("chatgpt", "skipped")` —
                # the `chatgpt` agent slot is shared between P1 (brief) and
                # P2 (deep research). Writing P1's status there made the
                # in-chat ChatGPT P2 config icon show a green/skipped badge
                # before P2 ChatGPT had run. P1's status is fully captured by
                # phases[1].status (read by the Brief icon, which has no
                # `agent` field). P2 ChatGPT writes its own agents.chatgpt
                # at P2 finalize (research.py:12716).
            elif _brief_from_file:
                # Phase 1 bypassed via --brief-file (or frontend briefText).
                # Persist to disk + Firestore. The user supplied the text;
                # there's no ChatGPT session to share from. Link to the
                # in-app document viewer (FE Documents page renders the
                # markdown in app theme).
                _brief_md = f"# Research Brief\n\n{brief_text}"
                (queue_dir / "documents" / "brief.md").write_text(_brief_md, encoding="utf-8")
                save_document_to_firestore("brief", _brief_md, "Research Brief")
                _in_app_brief_url = f"/documents?open={_fb_research_id}:brief" if _fb_research_id else "/documents"
                brief_artifact = BriefArtifact(text=brief_text, url=_in_app_brief_url)
                log(f"BriefArtifact (from file): {brief_artifact.chars} chars, "
                    f"{len(brief_artifact.sections)} sections")
                # #746: label MUST match the FE reopen-hydration backfill's
                # `Read ${HYDRATE_TYPE_LABELS.brief} report` = "Read Brief report"
                # (usePipeline.ts). When they differ, a phone/cold reopen replays
                # this phase_complete link ("Read brief") AND the backfill
                # synthesizes its own ("Read Brief report") for the SAME
                # /documents?open=…:brief URL — the FE (label,url) dedup can't
                # collapse them, so the P1 brief renders TWICE. P2 never had this
                # bug precisely because its BE + backfill labels already matched.
                _p1_links = [{"label": "Read Brief report", "url": _in_app_brief_url, "verified": True, "primary": True}]
                save_checkpoint(queue_dir, 1, topic=topic, brief_url=_in_app_brief_url)
                # Same ordering rule as the extract branch below: record the
                # terminal status BEFORE save_meta rebuilds the phases array
                # from it, or an earlier fail_phase's "errored" is what lands
                # on disk and nothing rewrites the file.
                _write_phase_terminal_status(1, "complete")
                save_meta(queue_dir, topic, 1, summary=brief_text[:200].strip())
                emit_event("phase_complete", phase=1,
                    durationSec=int(time.time() - _p1_start), links=_p1_links,
                    summary=f"Research brief loaded from file ({brief_artifact.chars} chars)")
                _update_firestore_research({"phase": 1, "status": "ongoing", "links.phase1": _p1_links})
                _write_phase_terminal_status(1, "complete")
                # 2026-05-12: REMOVED `_write_agent_terminal_status("chatgpt", "complete")` —
                # the chatgpt slot is shared with P2 deep research; writing
                # P1's status there made the P2 ChatGPT config icon show
                # green ✓ before P2 finished. See _p1_skipped_after_error
                # branch above for the full rationale.
            else:
                _brief_md = f"# Research Brief\n\n{brief_text}"
                (queue_dir / "documents" / "brief.md").write_text(_brief_md, encoding="utf-8")
                # Sync to Firestore documents subcollection — this is the
                # source of truth the FE Documents page renders. Phase 2
                # uses brief_artifact.text for paste; the URL is purely for
                # display in the phase dropdown + chat.
                save_document_to_firestore("brief", _brief_md, "Research Brief")
                # ── Markdown-as-primary architecture (2026-04-25) ──
                # phase_complete fires as SOON as the brief markdown is
                # in Firestore. The primary link points at the in-app
                # Documents viewer — guaranteed to work, no platform
                # share-link scraping required. Share-link extraction
                # runs AFTER as a best-effort secondary (90s budget,
                # conversation URL fallback) and lands via link_extracted.
                # Goals: (a) phase_complete is no longer gated on a
                # flaky CUA share-modal flow; (b) the chat/dropdown link
                # always works; (c) the run advances even if ChatGPT's
                # share UI changes overnight.
                _in_app_brief_url = f"/documents?open={_fb_research_id}:brief" if _fb_research_id else "/documents"
                brief_artifact = BriefArtifact(text=brief_text, url=_in_app_brief_url)
                log(f"BriefArtifact: {brief_artifact.chars} chars, {len(brief_artifact.sections)} sections")
                # #746: label MUST match the FE reopen-hydration backfill's
                # `Read ${HYDRATE_TYPE_LABELS.brief} report` = "Read Brief report"
                # (usePipeline.ts). When they differ, a phone/cold reopen replays
                # this phase_complete link ("Read brief") AND the backfill
                # synthesizes its own ("Read Brief report") for the SAME
                # /documents?open=…:brief URL — the FE (label,url) dedup can't
                # collapse them, so the P1 brief renders TWICE. P2 never had this
                # bug precisely because its BE + backfill labels already matched.
                _p1_links = [{"label": "Read Brief report", "url": _in_app_brief_url, "verified": True, "primary": True}]
                save_checkpoint(queue_dir, 1, topic=topic, brief_url=_in_app_brief_url)
                update_delivery(brief_url=_in_app_brief_url)
                # ⭐ 2026-08-11 — ORDER IS THE FIX. `save_meta` rebuilds the whole
                # `phases` array from the recorded terminal statuses, and this
                # call used to sit BEFORE the "complete" was recorded. So when
                # phase 1 had surfaced a stall card earlier in the run,
                # `fail_phase` had already recorded "errored" — meta.json was
                # written carrying it, and nothing rewrote the file afterwards.
                # The 2026-08-11 run shipped a 64 KB brief with
                # `phases[1].status = "errored"` and `durationSec: 0` on disk,
                # while Firestore (written after) said complete. Recording first
                # makes the file and the doc agree.
                _write_phase_terminal_status(1, "complete")
                save_meta(queue_dir, topic, 1, summary=brief_text[:200].strip())
                emit_event("phase_complete", phase=1, durationSec=int(time.time() - _p1_start),
                    links=_p1_links,
                    summary=f"Research brief generated ({brief_artifact.chars} chars, {len(brief_artifact.sections)} sections)")
                _update_firestore_research({"phase": 1, "status": "ongoing", "links.phase1": _p1_links})
                # 2026-05-12: REMOVED `_write_agent_terminal_status("chatgpt", "complete")` —
                # see _p1_skipped_after_error branch above for rationale
                # (chatgpt slot is shared with P2).
                # 2026-04-25: P1 secondary "View on ChatGPT" link removed.
                # The in-app /documents?open=…:brief primary is the only link
                # surfaced to the FE. The conversation URL (brief_url, captured
                # at line ~12209) still propagates to Phase 5 for the Google
                # Doc — it just isn't streamed as a separate link_extracted.
        else:
            # Load brief from documents/ (new location) or root (old location)
            for bp in [queue_dir / "documents" / "brief.md", queue_dir / "brief.md"]:
                if bp.exists():
                    raw = bp.read_text(encoding="utf-8")
                    brief_text = raw.replace("# Research Brief\n\n", "", 1)
                    break
            log(f"Phase 1: Loaded existing brief ({len(brief_text)} chars)")

        if _controls.is_stop_or_pause():
            if _controls.is_stop():
                log("STOP requested after Phase 1 — pipeline terminated", "WARN")
                save_meta(queue_dir, topic, 1, status="stopped")
                update_delivery(status="stopped")
                emit_event("pipeline_stopped", phase=1, reason="stop")
                _update_firestore_research({"status": "stopped", "phase": 1})
            else:
                log("PAUSE requested after Phase 1 — closing browser, awaiting resume", "WARN")
                save_meta(queue_dir, topic, 1, status="paused")
                update_delivery(status="paused")
                _update_firestore_research({"status": "paused", "phase": 1})
                _runtime.original_inputs = {"topic": topic, "pdf_paths": [str(p) for p in (pdf_paths or [])]}
                stopped = await pause_and_close_browser(browser, queue_dir, phase=1,
                                                        extra_kwargs={"topic": topic, "brief_url": brief_url})
                if stopped:
                    save_meta(queue_dir, topic, 1, status="stopped")
                    emit_event("pipeline_stopped", phase=1, reason="stop_after_pause")
                    _update_firestore_research({"status": "stopped", "phase": 1})
                    return
                # Relaunch browser on resume
                browser = Browser(_profile_dir(WORKER_ID), headless=False)
                await browser.start()
                _active_browser_ref = browser  # re-point stop handler at fresh session
                emit_event("pipeline_resumed", phase=1)
                _update_firestore_research({"status": "ongoing"})
                # Pause+resume+input semantics: rerun the paused phase with the
                # user's input folded into the combined topic. The resulting
                # brief carries the new guidance forward into Phase 2 naturally.
                if _controls.peek_extra_context():
                    resume_input = _controls.pop_extra_context()
                    log(f"Phase 1 resume-with-input — regenerating brief with {len(resume_input)} extra chars")
                    emit_event("phase_restart", phase=1, reason="user_input_on_resume", chars=len(resume_input))
                    combined_topic = topic + "\n\nADDITIONAL USER CONTEXT:\n" + resume_input
                    p1_new = await run_phase1(browser, cua_client, combined_topic, pdf_paths, verbose, feedback="")
                    if p1_new and p1_new.get("text"):
                        brief_text = p1_new["text"]
                        brief_url = p1_new.get("url", brief_url)
                        _brief_md_regen = f"# Research Brief\n\n{brief_text}"
                        (queue_dir / "documents" / "brief.md").write_text(_brief_md_regen, encoding="utf-8")
                        save_document_to_firestore("brief", _brief_md_regen, "Research Brief")
                        brief_artifact = BriefArtifact(text=brief_text, url=brief_url)
                        emit_event("phase_complete", phase=1,
                                   summary=f"Brief regenerated with user input ({len(brief_text)} chars)",
                                   links=[{"label": "ChatGPT Brief", "url": brief_url}] if brief_url else [])
                        # Resume-with-input regen still needs the terminal
                        # phase write because the original P1 write (if any)
                        # was for the pre-pause attempt.
                        _write_phase_terminal_status(1, "complete")
                        # 2026-05-12: REMOVED `_write_agent_terminal_status("chatgpt", "complete")` —
                        # chatgpt slot conflict with P2 (see other P1 branches).
            if _controls.is_stop():
                return

        skip_phases, agents_cfg, video_enabled, email_enabled, podcast_length, _ = reload_config()
        # ══════════════════════ PHASE 2: Deep Research ══════════════════════
        results = {}
        _user_skip_p2 = _controls.consume_phase_skip(2)
        # Flow B/C entry: when every P2 agent is disabled in agents_cfg,
        # the FE intent is "skip P2 entirely" (the user toggled all 3
        # agents off) — even though the FE doesn't write `2` into
        # skip_phases. Without this branch the elif below would fail_phase
        # with "No brief text available" because Flow B has no brief by
        # design (the user attached source docs that go straight to NLM).
        _all_agents_off = not any(agents_cfg.values())
        # 2026-05-12: also auto-skip P2 when P1 was skipped + no brief is
        # available + the user supplied Flow B sources. Without this, the
        # FE's "skip brief + pasted sources" UX hard-fails P2 just because
        # the user didn't ALSO toggle every individual P2 agent icon off.
        # Running P2 in this state is impossible (no brief to feed agents)
        # so we choose to skip rather than crash the pipeline.
        _flow_b_no_brief = (
            (1 in skip_phases) and (not brief_text) and bool(user_sources)
        )
        if 2 in skip_phases or _user_skip_p2 or _all_agents_off or _flow_b_no_brief:
            if _user_skip_p2:
                _reason = "user_skip"
            elif _all_agents_off:
                _reason = "All Phase 2 agents disabled"
            elif _flow_b_no_brief:
                _reason = "Flow B (P1 skipped + sources attached, no brief to feed agents)"
            else:
                _reason = "Disabled in pipeline config"
            log(f"Phase 2: SKIPPED ({_reason})")
            emit_event("phase_skipped", phase=2, reason=_reason)
        elif start_phase <= 2:
            if not brief_text:
                log("No brief text available — cannot run Phase 2", "ERROR")
                # #62: honest buttonless terminal notice, NOT a Retry/Skip card.
                # This is an emit-then-return backstop — after run_pipeline
                # returns, teardown_firestore_run() drops the per-run command
                # listener, so Retry/Skip would write to a dead command bus
                # (dead-end buttons). actions=[] renders a title/details card
                # with a corner ✕ and no buttons. fail_phase is KEPT (its
                # unconditional _QUEUE_STATE["_errored"]=True is what lets the
                # next queued run dequeue promptly). Distinct alert_id avoids the
                # generic phase2_error dismiss-ledger collision.
                fail_phase(2, "No brief to research",
                           "There's no research brief yet, so deep research "
                           "can't start. This run stopped here.",
                           actions=[], alert_id="phase2_no_brief")
                # #62: emit the FE run-terminal signal (matches the two
                # all-skipped sites below). Without it, the pipeline_error above
                # auto-pauses the FE (usePipeline flips every error alert to
                # paused) and leaves a chat-input Resume that dead-ends —
                # run_pipeline has already returned, so the per-run command
                # listener is torn down. pipeline_stopped drives the run terminal
                # (follow-up mode) instead of a phantom Resume.
                emit_event("pipeline_stopped", phase=2, reason="no_brief_for_phase2")
                return
            # Record the P2 source-doc decision once, before run_phase2 reads
            # the manifest: attach the user's sources only when P1 did NOT run
            # a live brief generation this session (skip-P1 / manual brief /
            # brief-from-file / resume-into-P2). A no-op when no sources were
            # attached; idempotent so a P1-ON run that resumes into P2 keeps
            # its original "don't re-attach" decision.
            _finalize_p2_source_decision(not _p1_ran_live)
            # Note: pre-2026-05-13 had an inline phase2-config-guard here that
            # re-read pipelineConfig.agents from Firestore. That logic is now
            # in reload_config() above (the [config-overlay] block) so every
            # phase entry — not just P2 — benefits. agents_cfg already
            # reflects the FS overlay by the time we reach this line.
            enabled_agents = [a for a, on in agents_cfg.items() if on]
            disabled_agents = [a for a, on in agents_cfg.items() if not on]
            log(f"[phase2] enabled_agents={enabled_agents} disabled_agents={disabled_agents}")
            # Pre-emit phase_start(2) BEFORE the trust gate. Mirrors the
            # P0→P1 eager-start pattern — and still load-bearing post-#899:
            # the gate's per-agent tile emits ("trusted ✓"/"unverified")
            # need an existing P2 phase message to land on.
            # _p2_initial_enabled remembers the pre-gate roster so the
            # canonical re-emit below can detect whether the gate trimmed
            # the list and re-fire with the corrected agents= field. Also
            # writes "phase: 2, currentPhase: 2, status: ongoing" to root
            # doc so the listing tile + queue gate flip immediately.
            _p2_start_emitted = False
            _p2_initial_enabled = list(enabled_agents)
            if not _controls.is_stop():
                emit_event("phase_start", phase=2, agents=enabled_agents,
                           description="Parallel deep research across AI platforms")
                _update_firestore_research({"phase": 2, "currentPhase": 2, "status": "ongoing"})
                _p2_start_emitted = True

            # ── P2 trust gate (BE-2, slimmed by #899) ──
            # When init was skipped: zero-navigation cookie trust check per
            # agent (no tab/CUA/pause — Layer 0.5 in
            # start_agent_no_gemini_wait owns real verification on each
            # agent's own work tab). 'skipped' = prior-skip echo; it drops
            # just that agent from enabled_agents (P2 continues with the
            # rest). All-skipped → fail_phase since P2 can't run with zero.
            if _controls.skip_init_verify and not _controls.is_stop():
                _p2_dropped_at_gate: list[str] = []
                for _ag in list(enabled_agents):
                    _p2_gate = await _phase_verify_gate(2, _ag, browser, cua_client)
                    if _p2_gate == "stop":
                        emit_event("pipeline_stopped", phase=2, reason="user_stop_at_verify_gate")
                        return
                    if _p2_gate == "skipped":
                        _p2_dropped_at_gate.append(_ag)
                        log(f"Phase 2: {_ag} dropped at verify gate", "INFO")
                        emit_event("agent_skipped", phase=2, agent=_ag,
                                   reason="user_skip_at_verify_gate")
                if _p2_dropped_at_gate:
                    enabled_agents = [a for a in enabled_agents if a not in _p2_dropped_at_gate]
                if not enabled_agents:
                    log("Phase 2: all agents skipped at verify gate — aborting", "WARN")
                    # #62: honest buttonless terminal notice (was a Retry/Skip
                    # card whose buttons dead-end — the paired pipeline_stopped
                    # tears down the FE run + BE command listener). Every agent
                    # was already skipped by the user, so there's no action left
                    # to offer; the per-agent agent_skipped events above carry
                    # the reasons. fail_phase is KEPT (its _errored=True advances
                    # the queue). Both all-skipped sites (verify-gate + preskip)
                    # share one alert_id so they're one logical card, not two
                    # byte-dup cards colliding on the generic phase2_error slot.
                    fail_phase(2,
                               "No agents left to run",
                               "Every research agent was skipped, so there's "
                               "nothing to run. This run stopped here.",
                               actions=[], alert_id="phase2_no_agents")
                    emit_event("pipeline_stopped", phase=2,
                               reason="all_agents_skipped_at_verify_gate")
                    return
            # #899: the work-tab login pauses leave an explicitly-skipped
            # platform in skipped_agents REGARDLESS of verifyLogins — the
            # gate loop above only consumes it on skip-init runs. Trim
            # unconditionally so a decision the user made at a P1 login
            # pause isn't re-asked at P2 (or worse: a fresh DR launched and
            # then killed by the round-robin's skip consumer on its first
            # tick) on init-verified runs.
            _p2_preskipped = [a for a in enabled_agents if a in _controls.skipped_agents]
            if _p2_preskipped and not _controls.is_stop():
                for _ag in _p2_preskipped:
                    log(f"Phase 2: {_ag} was skipped at an earlier login pause — not launching", "INFO")
                    emit_event("agent_skipped", phase=2, agent=_ag,
                               reason=("login_required_timeout"
                                       if _ag in _controls.login_pause_timeout_agents
                                       else "user_skip"))
                enabled_agents = [a for a in enabled_agents if a not in _p2_preskipped]
                if not enabled_agents:
                    log("Phase 2: all agents skipped before launch — aborting", "WARN")
                    # #62: honest buttonless terminal notice (was a Retry/Skip
                    # card whose buttons dead-end — the paired pipeline_stopped
                    # tears down the FE run + BE command listener). Every agent
                    # was already skipped by the user, so there's no action left
                    # to offer; the per-agent agent_skipped events above carry
                    # the reasons. fail_phase is KEPT (its _errored=True advances
                    # the queue). Both all-skipped sites (verify-gate + preskip)
                    # share one alert_id so they're one logical card, not two
                    # byte-dup cards colliding on the generic phase2_error slot.
                    fail_phase(2,
                               "No agents left to run",
                               "Every research agent was skipped, so there's "
                               "nothing to run. This run stopped here.",
                               actions=[], alert_id="phase2_no_agents")
                    emit_event("pipeline_stopped", phase=2,
                               reason="all_agents_skipped_at_verify_gate")
                    return
            # Canonical phase_start(2) re-emit — refreshes the agents= list
            # post-verify-gate (gate may have dropped agents into the
            # _p2_dropped_at_gate set). When the eager pre-emit above already
            # fired with the un-trimmed list, this second emit overwrites the
            # agents field cleanly via deterministic phaseId; if the eager
            # emit was gated out (stop pressed mid-config-reload then cleared),
            # this acts as the primary start.
            if not _p2_start_emitted:
                emit_event("phase_start", phase=2, agents=enabled_agents, description="Parallel deep research across AI platforms")
                _update_firestore_research({"phase": 2, "currentPhase": 2, "status": "ongoing"})
            elif enabled_agents != _p2_initial_enabled:
                # Verify gate dropped one or more agents — re-emit so the FE
                # tile reflects the trimmed enabled set.
                emit_event("phase_start", phase=2, agents=enabled_agents, description="Parallel deep research across AI platforms")
            for da in disabled_agents:
                # F2 (2026-05-06): emit with `reason` so the emit_event hook
                # at :5818-5833 persists agents[<da>].status="skipped" to the
                # root doc. Pre-fix, the for-loop omitted reason and the hook
                # gated persistence on truthy reason — leaving individually-
                # config-skipped agents (e.g. Claude off, others on) without
                # a runtime status. The FE could only fall back to deriving
                # from pipelineConfig.agents which (per F1) wasn't reliably
                # persisted either, so the listing tile rendered the skipped
                # agent as completed (green ✓). Dual-source defense-in-depth.
                emit_event("agent_skipped", phase=2, agent=da, reason="Disabled in pipeline config")
            _p2_start = time.time()
            # Active-time ceiling for Phase 2 — paused seconds don't count.
            # Per-phase login probe removed (2026-04-24) — Phase 0 is the
            # single login gate. See the matching note in the Phase 1
            # block above.
            fb2 = get_feedback(2)
            # Use BriefArtifact for full verified paste (never the "already_sent" heuristic)
            research_brief = (brief_artifact.text if brief_artifact else brief_text)
            # Append any extra context from user
            extra_ctx = _controls.pop_extra_context()
            if extra_ctx:
                research_brief += f'\n\nADDITIONAL CONTEXT: {extra_ctx}'
                log(f"Phase 2: Injecting extra user context ({len(extra_ctx)} chars)")
            if fb2:
                research_brief += f'\n\nUSER FEEDBACK (incorporate this into your research): {fb2}'
                log(f"Phase 2: Injecting user feedback: {fb2[:100]}")
                clear_feedback(2)
            # Restart loop: if mid-phase pause + input triggers a restart, merge
            # the new context into the brief and rerun the whole phase. Cap at
            # 3 restarts to prevent infinite loops if something goes sideways.
            results = {}
            _p2_user_skipped = False
            for _p2_attempt in range(3):
                _runtime.restart_requested = False
                while True:  # timeout-retry loop
                    try:
                        results = await _await_phase_with_active_deadline(
                            2, PHASE_2_MAX_MIN,
                            lambda: run_phase2(browser, cua_client, research_brief, verbose,
                                               enabled_agents=enabled_agents),
                            soft_warn_only=True,  # 2026-05-04: long DR runs are legitimate; warn but don't bail
                        )
                        break  # success
                    except _PhaseSoftDecision as _sd:
                        # User picked Retry/Skip on the soft-timeout warn.
                        # Wait is implicit — never reaches this except (the
                        # helper keeps polling on Wait until run_task either
                        # finishes naturally OR user picks Retry/Skip).
                        if _sd.decision == "retry":
                            emit_event("phase_restart", phase=2, reason="user_retry_after_soft_timeout")
                            results = {}
                            continue
                        if _sd.decision == "skip":
                            emit_event("phase_skipped", phase=2, reason="user_skip_after_soft_timeout")
                            _p2_user_skipped = True
                            results = {}
                            break
                        # Defensive — _PhaseSoftDecision only carries
                        # "retry"/"skip"; anything else means the helper
                        # contract drifted. Log + re-raise so it surfaces.
                        log(f"[P2] Unexpected _PhaseSoftDecision.decision={_sd.decision!r}", "ERROR")
                        raise
                    except asyncio.TimeoutError:
                        # Legacy hard-path. With soft_warn_only=True the
                        # helper raises _PhaseSoftDecision instead of
                        # TimeoutError, so this except block is normally
                        # unreachable for P2. Kept as a safety net in case
                        # something inside run_phase2 raises a bare
                        # TimeoutError that escapes the helper's wrap.
                        _decision = await _phase_timeout_decision(2, PHASE_2_MAX_MIN)
                        if _decision == "retry":
                            emit_event("phase_restart", phase=2, reason="user_retry_after_timeout")
                            results = {}
                            continue
                        if _decision == "skip":
                            emit_event("phase_skipped", phase=2, reason="user_skip_after_timeout")
                            _p2_user_skipped = True
                            results = {}
                            break
                        emit_event("pipeline_stopped", phase=2, reason=f"user_{_decision}_after_timeout")
                        return
                if _p2_user_skipped:
                    break  # exit outer for loop too
                if not _runtime.restart_requested:
                    break
                extra_ctx_retry = _controls.pop_extra_context()
                if not extra_ctx_retry:
                    log("[Phase 2] restart_requested but extra_context empty — continuing", "WARN")
                    break
                research_brief += f'\n\nADDITIONAL USER CONTEXT (restart #{_p2_attempt+1}):\n{extra_ctx_retry}'
                log(f"[Phase 2] Mid-phase restart with +{len(extra_ctx_retry)} chars of user input")
                emit_event("phase_restart", phase=2,
                           reason="mid_phase_input_on_resume",
                           chars=len(extra_ctx_retry), attempt=_p2_attempt+1)
            # Safety filter: ensure only enabled agents appear in results
            if enabled_agents:
                agent_name_map = {"chatgpt": "ChatGPT", "gemini": "Gemini", "claude": "Claude"}
                enabled_names = {agent_name_map.get(a, a) for a in enabled_agents}
                results = {n: r for n, r in results.items() if n in enabled_names}

            # ── ⭐⭐ THE OFF-TOPIC SWEEP AT THE SINK (2026-08-05) ──
            #
            # Everything below this line reads `results[name]["text"]`: the link
            # buckets, the per-agent `documents/<agent>.md` write, the Firestore
            # documents subcollection, consolidated.md, save_meta, and the P2→P3
            # handoff that hands those files to NotebookLM. So this is the ONE
            # place a wrong-topic report can be stopped before it becomes the run's
            # deliverable, regardless of which path produced it.
            #
            # ⛔ It is deliberately NOT a substitute for the per-path guards above.
            # Those exist so the agent is marked honestly and the user sees the
            # rejection at the moment it happens; this exists because on
            # 2026-08-05 the producer-side guard covered exactly one of the three
            # paths that reach these files, and the two it missed are the ones the
            # incident took. A guard on the producer covers the producers you
            # remembered.
            #
            # Abstains on everything uncertain — see `reject_off_topic_text`.
            _off_topic = apply_off_topic_sweep(results, queue_dir)
            if _off_topic:
                log(f"[Phase 2] off-topic sweep rejected {_off_topic} — their text "
                    f"will not be written to documents/, mirrored to Firestore, "
                    f"merged into consolidated.md, or handed to NotebookLM", "ERROR")
            # ── 2026-05-10: Emit phase_complete:2 EARLY (before heavy persistence) ──
            # The MD writes, consolidated.md build, save_meta enrichment, and
            # P2→P3 handoff are BE-internal (FE doesn't gate on them). Emitting
            # phase_complete:2 FIRST:
            #   • Flips the P2 tile to green immediately on the FE.
            #   • Auto-cancels the per-tick narrator (emit_event hook at
            #     ~line 6225) so "Claude is refining..." stops echoing
            #     while the user waits for P3.
            #   • Writes the per-agent terminal status to the root doc so
            #     reopen / tile listing renders correctly post-reload.
            # The marker write also moves up (still gated on a clean finish)
            # so crash-recovery resume sees P2 as done before the heavy
            # persistence below has a chance to run. Resume from a crash in
            # the heavy persistence block is safe: the only thing that hasn't
            # finished is BE-internal disk/Firestore mirroring of agent MDs;
            # the next BE run rebuilds them from results on resume, or P3
            # rebuilds the handoff via its own safety-net call.
            # F5 (2026-05-13): three-way split (linked / errored / skipped)
            # so Firestore-sync-failed agents don't get phantom "Read X report"
            # links pointing at unreachable docs. Bucketing rules:
            #   - has text AND verified (md_saved) → linked
            #   - has text AND NOT verified         → errored (sync failed)
            #   - no text                           → skipped (extraction failed)
            # Linked is the only bucket that surfaces a link button on the FE.
            _p2_links: list[dict] = []
            _p2_errored_agents: list[str] = []
            _p2_skipped_agents: list[str] = []
            for name, r in results.items():
                in_app = r.get("_in_app_url") or ""
                if in_app and r.get("text") and r.get("verified"):
                    _p2_links.append({
                        "label": f"Read {name} report",
                        "url": in_app,
                        "verified": True,
                        "primary": True,
                    })
                elif r.get("text"):
                    # Extraction succeeded locally but Firestore sync failed —
                    # red badge already drives the FE state via the failed
                    # branch in extract_and_record_agent (agent_progress=failed
                    # + _write_agent_terminal_status=errored).
                    _p2_errored_agents.append(name)
                else:
                    _p2_skipped_agents.append(name)
            done_count = sum(1 for r in results.values() if r["status"] == "done")
            total_chars = sum(len(r.get("text", "")) for r in results.values())
            log(f"[Phase 2] Built {len(_p2_links)} in-app primary links, "
                f"{len(_p2_errored_agents)} errored (sync failed), "
                f"{len(_p2_skipped_agents)} skipped (no MD)")
            # ── C8: phase_complete invariant — every non-skipped non-errored ──
            # ── enabled agent should have an in-app primary link entry.       ──
            # ── Missing entries mean MD save itself failed mysteriously.      ──
            _linked_agents = set()
            for _l in _p2_links:
                _lbl = _l.get("label") or ""
                _parts = _lbl.split(" ")
                if len(_parts) >= 2 and _parts[0] == "Read":
                    _linked_agents.add(_parts[1])
            _expected_agents = (
                set(results.keys()) - set(_p2_skipped_agents) - set(_p2_errored_agents)
            )
            _missing_links = _expected_agents - _linked_agents
            if _missing_links:
                log(f"[Phase 2] phase_complete invariant breach: {sorted(_missing_links)} "
                    f"have text + verified=True but no in-app primary link. Emitting "
                    f"phase_complete anyway — these agents will render as unlinked. "
                    f"Investigate the in-app URL build path.", "ERROR")
            # ⛔⛔ 2026-08-29 — THE VERDICT IS DECIDED BEFORE THE EVENT, NOT AFTER
            # IT. The first version of this fix emitted `phase_complete` and THEN
            # corrected the status to "errored" a few lines down, which was wrong
            # in two ways at once. The event is what the frontend turns into a
            # notice, so a run where every agent died still pushed and emailed
            # "Research docs ready". And the emit's own hook writes
            # `_write_phase_terminal_status(2, "complete")` on a daemon thread,
            # so the correction was RACING the thing it was correcting — two
            # non-transactional read-modify-writes on the same phases array, and
            # the later writer wins by luck.
            #
            # ⭐ `skipped=True` IS THE MARKER THE FRONTEND ALREADY READS.
            # `phaseProducedArtifact` in `phase-notice.ts` is exactly
            # `data?.skipped !== true`, and it exists because P3 once announced a
            # podcast that had been skipped. A phase that produced no report at
            # all is the same shape, so it reuses the same gate rather than
            # inventing a second one.
            #
            # ⛔ A PHASE WHERE SOME AGENTS DELIVERED STILL COMPLETES. Two of three
            # is a finished phase; renaming it would be a second lie in the other
            # direction, and the per-agent record below is where a single agent's
            # fate belongs.
            #
            # ⛔ AND `_p2_user_skipped` IS INCLUDED. That path leaves `results`
            # empty, so a `results and done_count == 0` guard let it through to
            # "complete" — a phase the user explicitly skipped, recorded as
            # finished, after `phase_skipped` had already said otherwise.
            _p2_wipeout = (done_count == 0 and (bool(results) or _p2_user_skipped))
            if _p2_wipeout:
                log(f"[Phase 2] 0 of {len(results)} agents produced a report"
                    f"{' (user skipped the phase)' if _p2_user_skipped else ''} — "
                    f"recording the phase as errored, and marking the event so the "
                    f"frontend does not announce documents nobody has", "ERROR")
            emit_event("phase_complete", phase=2, durationSec=int(time.time() - _p2_start), links=_p2_links,
                skippedAgents=_p2_skipped_agents,
                erroredAgents=_p2_errored_agents,
                # ⛔ THE HOOK ON THIS EVENT WRITES THE PHASE STATUS. Passing the
                # verdict in means one writer, not two racing daemon threads.
                skipped=_p2_wipeout,
                summary=f"{done_count}/{len(results)} agents completed — {total_chars:,} chars — "
                        f"{len(_p2_links)} in-app primary links")
            _update_firestore_research({"phase": 2, "links.phase2": _p2_links})
            if _p2_wipeout:
                _write_phase_terminal_status(2, "errored")
            else:
                # Tile/Icon Consistency (2026-05-01): write the phase-complete
                # status to root doc so the listing-page tile + chat phase
                # icons + in-chat config icons stay green post-reload.
                _write_phase_terminal_status(2, "complete")
            # Per-agent terminal status. "done" → "complete".
            #
            # ⛔⛔ 2026-08-29 — THIS LOOP HAD NO `else`, AND ITS COMMENT WAS WRONG.
            # It claimed the other statuses "are written at their own emit sites".
            # Measured, several are not: `partial` and `interrupted` (a Stop
            # mid-round-robin), `browser_crashed` (a crash calls no `fail_agent`,
            # so nothing persists anything), and a leftover `paused`. Those agents
            # were left on the "running" stamped when they were OPENED — a value
            # the frontend's status union did not even list — so a dead agent was
            # indistinguishable from a clean success at every surface. The owner
            # watched exactly that: a green tick over a Gemini that produced
            # nothing.
            #
            # ⛔ IT DOES NOT OVERWRITE A TERMINAL STATUS SOMEBODY ELSE WROTE. The
            # helper's own guard only protects against a transient "running"; this
            # checks the recorded status first so an "errored" with a REASON —
            # which `fail_agent` writes, and which the UI shows as a sentence — is
            # never flattened into a bare "skipped" by this backstop.
            _p2_recorded = _agent_status_by_rid.get(_fb_research_id, {}) or {}
            for _ag_name, _ag_r in results.items():
                _ag_status = (_ag_r.get("status") or "").lower()
                _ag_key_lc = _ag_name.lower().replace(" ", "")
                if _ag_status in ("done", "complete", "completed", "done_partial"):
                    _write_agent_terminal_status(_ag_key_lc, "complete")
                    continue
                # ⛔ THE OFF-TOPIC SWEEP IS WHY THIS BRANCH CANNOT TRUST THE
                # RECORDED VALUE BLINDLY. It runs a few lines above and flips a
                # `done` agent to `failed` — but "complete" was already persisted
                # when the agent finished, and nothing rewrote it. So a report we
                # deliberately rejected as foreign-topic was reported to the user
                # as a completed agent. `off_topic_rejected` is the marker it
                # leaves, and it overrides a stale terminal status.
                if _ag_r.get("off_topic_rejected"):
                    _write_agent_terminal_status(
                        _ag_key_lc, "errored", force=True,
                        reason="off_topic_rejected",
                        detail=f"{_ag_name} returned a report about a different "
                               f"topic, so it was not used.")
                    continue
                if _p2_recorded.get(_ag_key_lc) in ("complete", "skipped", "errored"):
                    continue
                # ⛔⛔ 2026-08-29 — A BLANKET "skipped" WAS ITSELF A LIE FOR TWO OF
                # THESE. `browser_crashed` is a failure we WATCHED happen, and
                # flattening it into the same grey a user's own Skip produces
                # throws away the one thing we know. And an agent interrupted by
                # a user STOP may have salvaged text — the same block writes that
                # text to disk and to Firestore — so telling the person it
                # "finished without producing a report" is contradicted by the
                # report sitting in their documents list.
                if (_ag_r.get("text") or "").strip():
                    # It produced something. Whatever went wrong was on the way
                    # OUT, not on the way through — that is the errored bucket,
                    # and the same one `_p2_errored_agents` uses above.
                    _write_agent_terminal_status(
                        _ag_key_lc, "errored",
                        reason=f"incomplete_{_ag_status or 'unknown'}",
                        detail=f"{_ag_name} produced a partial report that could not be saved.")
                    continue
                if _ag_status in ("browser_crashed", "not_verified", "wrong_conversation"):
                    _write_agent_terminal_status(
                        _ag_key_lc, "errored",
                        reason=_ag_status,
                        detail=_P2_KNOWN_FAILURE_COPY.get(_ag_status, "").format(name=_ag_name)
                               or f"{_ag_name} stopped before it produced a report.")
                    continue
                # Nothing terminal on record, no text, and no named failure. Grey,
                # not red: we do not know that it FAILED, only that the run ended
                # with nothing from it, and saying more than that is a guess.
                _write_agent_terminal_status(
                    _ag_key_lc, "skipped",
                    reason="no_report_at_phase_end",
                    detail=f"{_ag_name} finished without producing a report.")
            # Phase-2 completion marker — only on a CLEAN finish (not stop/pause).
            # Tells detect_resume_phase that P2 actually finished, so resume
            # doesn't re-run P2 mid-flight.
            _p2_clean_finish = (not _controls.is_stop_or_pause())
            if _p2_clean_finish:
                try:
                    (queue_dir / "phase2_complete.marker").write_text(
                        json.dumps({
                            "completedAt": int(time.time() * 1000),
                            "doneCount": done_count,
                            "totalAgents": len(results),
                            "skippedAgents": list(_p2_skipped_agents),
                        }),
                        encoding="utf-8",
                    )
                except Exception as _mk_e:
                    log(f"[Phase 2] failed to write phase2_complete.marker: {_mk_e}", "WARN")
            else:
                log("[Phase 2] stop/pause detected — skipping phase2_complete.marker so resume re-runs P2", "INFO")

            # ── Heavy persistence (BE-internal, FE-invisible) ──
            # Per-agent MD disk writes + Firestore documents subcollection,
            # consolidated.md build, save_meta enrichment, P2→P3 handoff.
            # Runs AFTER phase_complete:2 so the user sees P2 turn green
            # immediately while this work completes invisibly.
            for name, r in results.items():
                if r["text"]:
                    fname = name.lower().replace(" ", "") + ".md"
                    _agent_md = f"# {name} Deep Research\n\n{r['text']}"
                    (queue_dir / "documents" / fname).write_text(_agent_md, encoding="utf-8")
                    # Sync to Firestore documents subcollection — doc_type is the
                    # agent key (chatgpt / gemini / claude), consistent with the
                    # frontend's Documents page expectation.
                    _agent_lc = name.lower().replace(" ", "")
                    save_document_to_firestore(_agent_lc, _agent_md, f"{name} Deep Research")
                    # Backstop findings extraction at the P2 finalize re-save
                    # site. The primary site is in extract_and_record_agent
                    # (~research.py:10988), but this resave path can run on
                    # resume / manual re-finalize when the snapshot ring may
                    # have been cleared. Skip if findings already exist.
                    try:
                        if _agent_lc not in (getattr(_runtime, "agent_findings", {}) or {}):
                            _src_urls = list(getattr(_runtime, "agent_progress_snapshots", {}).get(_agent_lc, {}).get("source_urls", []) or [])
                            # Same de-gating as the primary site: this backstop
                            # exists for resume/re-finalize, exactly when the
                            # snapshot ring may have been cleared — so keying it
                            # on the panel list made it useless in the one case
                            # it was written for.
                            if _agent_md:
                                _findings = _extract_findings(_agent_md, _src_urls)
                                if _findings:
                                    _runtime.agent_findings[_agent_lc] = _findings
                    except Exception:
                        pass
            # Generate consolidated report
            consolidated_parts = [f"# Consolidated Research Report: {topic}\n"]
            for name in ["ChatGPT", "Gemini", "Claude"]:
                r = results.get(name, {})
                if r.get("text"):
                    consolidated_parts.append(f"\n## {name} Research\n\n{r['text']}")
            if len(consolidated_parts) > 1:
                _consolidated_md = "\n".join(consolidated_parts)
                (queue_dir / "documents" / "consolidated.md").write_text(_consolidated_md, encoding="utf-8")
                save_document_to_firestore("consolidated", _consolidated_md, "Consolidated Report")
                log(f"Consolidated report: {len(_consolidated_md)} chars")
                # 2026-05-10: kick off the final post-research summary using
                # the consolidated findings (all 3 agent reports merged).
                # Overwrites the earlier brief-based stub with a "what the
                # research found" line — this is the version users see on
                # /researches after the pipeline finishes. Non-blocking
                # daemon thread; subsequent P3 (podcast) and FE P4/P5
                # (distribution) phases add no new research content, so
                # this is the final summary refresh.
                try:
                    _generate_research_summary_async(
                        topic,
                        brief_artifact.text if brief_artifact else "",
                        _consolidated_md,
                    )
                except Exception as _sum_e:
                    log(f"[summary] post-P2 dispatch failed: {_sum_e}", "WARN")
                # 2026-05-11: also refresh research.title now that we have
                # actual findings (not just the user's raw brief). The FE
                # /api/title call at pipeline start gave us a 4-8 word
                # startup title based ONLY on the user's input — often a
                # paragraph with "Goal:" / "Already sorted" sections that
                # produces a less-focused title. Post-P2 the agents have
                # produced concrete findings; the refresh reflects what
                # was actually researched.
                try:
                    _refresh_research_title_async(
                        topic,
                        brief_artifact.text if brief_artifact else "",
                        _consolidated_md,
                    )
                except Exception as _tit_e:
                    log(f"[title-refresh] post-P2 dispatch failed: {_tit_e}", "WARN")
            log(f"\nPHASE 2 COMPLETE: {done_count}/{len(results)} agents finished")
            for name, r in results.items():
                log(f"  {name:10s} status={r['status']:12s} text={len(r['text']):>6d} chars")
            save_checkpoint(queue_dir, 2, topic=topic, brief_url=brief_url)
            # Update delivery with live agent URLs
            agent_urls = {n: r.get("url", "") for n, r in results.items() if r.get("url")}
            if agent_urls:
                update_delivery(research_links=agent_urls)
            # Enrich meta with per-agent data from results + track events
            save_meta(queue_dir, topic, 2)
            meta_path = queue_dir / "meta.json"
            if meta_path.exists():
                meta = json.loads(meta_path.read_text(encoding="utf-8"))
                agents = meta.get("agents", {})
                for name, r in results.items():
                    key = name.lower().replace(" ", "")
                    if key not in agents:
                        agents[key] = {}
                    agents[key]["completionTimeSec"] = r.get("elapsed_sec", 0)
                # 2026-04-29: events.jsonl scrape merge removed — events.jsonl
                # is no longer written to disk (Firestore pipeline_events is
                # the single transport). The agents map is already kept in
                # sync via per-event `_update_firestore_research` calls
                # during P2; the disk-merge here was a redundant backstop.
                meta["agents"] = agents
                meta_path.write_text(json.dumps(meta, indent=2), encoding="utf-8")
            # ── 2026-04-25: Markdown-as-primary phase_complete (P1 mirror) ──
            # extract_and_record_agent already emitted link_extracted with the
            # in-app /documents primary the moment each agent's MD landed.
            # Share-link extraction is now fully scoped to P2 (DOM tier +
            # vision-shadow-wrapped CUA fallback inside extract_and_record_agent
            # and the removed P2 share step). P3 just consumes _runtime.p2_*
            # state and goes straight to NotebookLM.
            # Build the P2→P3 handoff now so P3 starts clean. Idempotent —
            # safe to call again as a fallback at start of P3 if needed.
            try:
                _build_phase2_to_phase3_handoff(results, queue_dir)
            except Exception as _hoe:
                log(f"[Phase 2→3 handoff] build failed (P3 will rebuild on entry): {_hoe}", "WARN")
        else:
            log("Phase 2: Loading existing research files")

        if _controls.is_stop_or_pause():
            if _controls.is_stop():
                log("STOP requested after Phase 2 — collecting partial results", "WARN")
                doc_dir = queue_dir / "documents"
                partial_agents = []
                for name in ["ChatGPT", "Gemini", "Claude"]:
                    fname = name.lower().replace(" ", "") + ".md"
                    if (doc_dir / fname).exists() and (doc_dir / fname).stat().st_size > 100:
                        partial_agents.append(name)
                log(f"  Partial results saved: {partial_agents or 'none'}")
                save_meta(queue_dir, topic, 2, status="stopped")
                update_delivery(status="stopped")
                emit_event("pipeline_stopped", phase=2, reason="stop",
                           partial_agents=partial_agents)
                _update_firestore_research({"status": "stopped", "phase": 2})
                return
            else:
                log("PAUSE requested after Phase 2 — closing browser, awaiting resume", "WARN")
                save_meta(queue_dir, topic, 2, status="paused")
                update_delivery(status="paused")
                _update_firestore_research({"status": "paused", "phase": 2})
                _runtime.original_inputs = {"topic": topic, "brief": brief_text}
                stopped = await pause_and_close_browser(browser, queue_dir, phase=2,
                                                        extra_kwargs={"topic": topic, "brief_url": brief_url})
                if stopped:
                    save_meta(queue_dir, topic, 2, status="stopped")
                    emit_event("pipeline_stopped", phase=2, reason="stop_after_pause")
                    _update_firestore_research({"status": "stopped", "phase": 2})
                    return
                # Relaunch — agents in Phase 2 are already complete at this boundary
                browser = Browser(_profile_dir(WORKER_ID), headless=False)
                await browser.start()
                _active_browser_ref = browser  # re-point stop handler at fresh session
                emit_event("pipeline_resumed", phase=2)
                _update_firestore_research({"status": "ongoing"})
                # Restart-phase logic: if user supplied input while paused, re-run Phase 2 with combined input
                if _controls.peek_extra_context():
                    resume_input = _controls.pop_extra_context()
                    log(f"Phase 2: Resume-with-input — rerunning 3 agents with {len(resume_input)} extra chars")
                    emit_event("phase_restart", phase=2, reason="user_input_on_resume", chars=len(resume_input))
                    combined_brief = (brief_artifact.text if brief_artifact else brief_text) + \
                                      "\n\nADDITIONAL USER CONTEXT:\n" + resume_input
                    enabled_agents_now = [a for a, on in agents_cfg.items() if on]
                    results = await run_phase2(
                        browser, cua_client, combined_brief, verbose,
                        enabled_agents=enabled_agents_now)
                    # Rewrite documents
                    for name, r in results.items():
                        if r.get("text"):
                            fname = name.lower().replace(" ", "") + ".md"
                            _regen_md = f"# {name} Deep Research (regenerated)\n\n{r['text']}"
                            (queue_dir / "documents" / fname).write_text(_regen_md, encoding="utf-8")
                            save_document_to_firestore(name.lower().replace(" ", ""), _regen_md, f"{name} Deep Research")
                    # Build links from round-robin results — prefer in-app primary
                    # (always present when MD landed) over conversation URL.
                    _p2_links = []
                    for n, r in results.items():
                        in_app = r.get("_in_app_url") or ""
                        if in_app and r.get("text"):
                            _p2_links.append({"label": f"Read {n} report", "url": in_app,
                                              "verified": True, "primary": True})
                    emit_event("phase_complete", phase=2, links=_p2_links,
                               summary="Phase 2 regenerated with user input")

        # ── Check we have research output to continue ──
        # ARCHITECTURE 2026-04-18 (never-die): no retries_left cap. If
        # Phase 2 produced nothing, surface a phase alert and wait for
        # the user to choose Retry / Skip / Stop. Retry re-runs Phase 2;
        # Skip advances past Phase 3 entirely (no notebook/audio); Stop
        # ends the run. Previously we capped at 1 retry and then
        # silently marked the run failed — that broke the contract.
        doc_dir = queue_dir / "documents"
        # Source scan: include user-attached PDFs/DOCX/TXT alongside agent
        # MDs so Flow B (P1+P2 skipped, sources-only) doesn't trip the
        # "no documents" gate. brief.md AND consolidated.md are excluded —
        # brief.md is the P1 input (not a NotebookLM source) and
        # consolidated.md is a P2 byproduct of claude+gemini concatenation
        # used for the Documents page only. 2026-05-11 fix: on a
        # checkpoint resume after PC death, `results` is empty and the
        # synthesis loop at ~21117 used to hydrate results from this scan;
        # consolidated.md slipped in as a fourth "agent" and the rebuilt
        # NotebookLM notebook included it alongside chatgpt/claude/gemini.
        _P3_DERIVED_STEMS = {"brief", "consolidated"}
        def _scan_p3_docs():
            if not doc_dir.exists():
                return []
            return [f for f in doc_dir.iterdir()
                    if f.is_file()
                    and f.suffix.lower() in (".md", ".txt", ".pdf", ".docx")
                    and f.stat().st_size > 100
                    and f.stem.lower() not in _P3_DERIVED_STEMS]
        md_files = _scan_p3_docs()
        has_results = md_files or any(r.get("text") for r in results.values())
        # Flow B context detection: P2 was *deliberately* skipped (config or
        # all-agents-off via the FE), so the user's intent was P3-as-entry
        # with attached source files. The legacy gate ("Phase 2 produced no
        # documents — Retry Phase 2") is wrong for this path: P2 wasn't
        # supposed to produce anything, and Retry would just re-run P2 with
        # the same all-agents-off config and loop forever. Surface a Flow-B-
        # specific error and don't offer Retry P2 in that case.
        _p2_was_skipped = (2 in skip_phases) or (not any(agents_cfg.values()))
        _flow_b_intent = _p2_was_skipped and (1 in skip_phases)
        # Flow C bypass: P3 already in skip_phases means the user's intent
        # was P5-as-entry (or P4-as-entry) with user-pasted URLs hydrating
        # delivery.json. The P3 entry block below detects 3 in skip_phases
        # and runs the user_links hydration flow — no documents required.
        # Skipping the gate here lets Flow C runs proceed without the user
        # having to click "Skip P3" on a misleading "Phase 2 produced no
        # documents" alert.
        _p3_already_skipped = (3 in skip_phases)
        _p3gate_attempt = 0
        while not has_results and not _p3_already_skipped:
            _p3gate_attempt += 1
            log(f"No research output (attempt {_p3gate_attempt}) — awaiting user decision "
                f"(flow_b_intent={_flow_b_intent}, p2_was_skipped={_p2_was_skipped})", "WARN")
            if _flow_b_intent:
                # Flow B: P1+P2 skipped, user expected to bring source docs.
                # Either none were attached, or all downloads failed (the
                # download block at run_pipeline entry already would have
                # fail_phase'd that case explicitly). Reaching here means
                # zero usable sources landed on disk. No Retry P2 action —
                # there's nothing to retry. Offer Skip P3 (run P5 with
                # whatever the pipeline can salvage) or stop.
                # #908: mark_phase_errored=False — this gate fires BEFORE
                # Phase 3 ever starts, and the persistent errored write was
                # painting the NotebookLM tile red while the actual failure
                # is the missing research output (user screenshot 2026-07-06).
                # The decision card + Skip action are unchanged.
                fail_phase(
                    phase=3,
                    error="No files to research",
                    reason=("This run skips the AI agents and needs files you "
                            "attach (PDF, Word, text, or Markdown), but none "
                            "came through. Skip this step, or stop and "
                            "re-attach your files."),
                    mark_phase_errored=False,
                    actions=[
                        {"id": "skip", "label": "Skip Phase 3", "style": "primary",
                         "command": {"action": "skip_phase", "phase": 3}},
                    ],
                )
            else:
                # #908: same rationale — the run is still AT Phase 2 when
                # this fires; NotebookLM hasn't run and must not go red.
                fail_phase(
                    phase=3,
                    error="No research to turn into a notebook",
                    reason="None of the agents produced a report. Retry the research, or Skip the notebook step.",
                    mark_phase_errored=False,
                    actions=[
                        {"id": "retry", "label": "Retry Phase 2", "style": "primary",
                         "command": {"action": "retry_phase", "phase": 3}},
                        {"id": "skip", "label": "Skip Phase 3", "style": "default",
                         "command": {"action": "skip_phase", "phase": 3}},
                    ],
                )
            gate_decision = await _controls.await_phase_decision(3)
            log(f"Phase 3 gate decision: {gate_decision}")
            if gate_decision == "retry" and not _flow_b_intent:
                try:
                    emit_event("phase_restart", phase=2, reason="user_retry_p3_gate", attempt=_p3gate_attempt + 1)
                except Exception:
                    pass
                _retry_brief_text = (brief_artifact.text if brief_artifact else brief_text) or ""
                _retry_enabled = [a for a, on in agents_cfg.items() if on]
                results = await run_phase2(
                    browser, cua_client, _retry_brief_text, verbose,
                    enabled_agents=_retry_enabled)
                # Rewrite documents from the fresh results
                for name, r in results.items():
                    if r.get("text"):
                        fname = name.lower().replace(" ", "") + ".md"
                        _regen_md = f"# {name} Deep Research (retry)\n\n{r['text']}"
                        (queue_dir / "documents" / fname).write_text(_regen_md, encoding="utf-8")
                        save_document_to_firestore(name.lower().replace(" ", ""), _regen_md, f"{name} Deep Research")
                # Re-check gate using the same source scan helper.
                md_files = _scan_p3_docs()
                has_results = md_files or any(r.get("text") for r in results.values())
                continue
            if gate_decision == "skip":
                log("Phase 3 gate: user skipped — continuing past Phase 3 with no documents", "INFO")
                emit_event("phase_skipped", phase=3, reason="user_skip_no_docs")
                # await_phase_decision(3) already consumed the skip flag, so
                # re-add it to the set. The Phase 3 entry block below reads
                # consume_phase_skip(3) and will short-circuit past the upload
                # step when the flag is present — that set IS the mechanism.
                # (A `_p3gate_skipped = True` local used to be set here as well
                # and was never read by anything; removed 2026-07-31 rather than
                # left to imply a second, non-existent channel.)
                _controls.skipped_phases.add(3)
                break
            # stop / timeout → end the run
            log(f"Phase 3 gate: user {gate_decision} — terminating pipeline", "INFO")
            emit_event("pipeline_stopped", phase=3, reason=f"user_{gate_decision}_no_docs")
            return

        # Post-Phase-2: add_context is no longer accepted (guarded at command
        # listener). Any residual extra_context from a pre-P2 race is dropped
        # with a warning — no NotebookLM addendum, no prompt, no cascade.
        if _controls.peek_extra_context():
            dropped = _controls.pop_extra_context()
            log(f"Dropping {len(dropped)} chars of residual extra_context post-P2 "
                f"(add_context disabled for Phase 3+)", "WARN")

        skip_phases, agents_cfg, video_enabled, email_enabled, podcast_length, _ = reload_config()
        # ── 2026-05-10: Eager phase_start:3 BEFORE the verify gate ──
        # Pre-fix, the verify gate (when skip_init_verify=True) ran a 5-15s
        # CUA call BEFORE phase_start:3 was emitted — FE saw P2 done + blank
        # gap. Now: flip P3 to "running" first; the gate runs visibly under
        # the P3 tile (the gate's own agent_progress notebooklm status emits
        # at line ~6529 light up the dropdown). If the gate or downstream
        # skip-check decides skip, the existing phase_skipped:3 emit at
        # line ~20875 cleanly flips running → skipped via the FE's
        # deterministic phaseId. The canonical phase_start:3 emit later in
        # the elif at ~line 20939 is idempotent (same phaseId, just refreshes
        # description).
        if (start_phase <= 3
                and 3 not in skip_phases
                and 3 not in _controls.skipped_phases
                and not _controls.is_stop()):
            emit_event("phase_start", phase=3, description="Preparing NotebookLM…", agents=["notebooklm"])
            _update_firestore_research({"phase": 3, "currentPhase": 3, "status": "ongoing"})
        # ══════════════════════ PHASE 3 trust gate (BE-2, slimmed by #899) ══════════════════════
        # When init was skipped: zero-navigation cookie trust check for
        # NotebookLM (no tab/CUA/pause — run_phase3_upload/audio own real
        # verification via their work-tab preflights). 'skipped' =
        # prior-skip echo; it cascades to P4 (no YouTube without podcast —
        # same rule as the skip_phase command handler at ~line 2833).
        if (start_phase <= 3 and 3 not in skip_phases
                and 3 not in _controls.skipped_phases
                and _controls.skip_init_verify
                and not _controls.is_stop()):
            _p3_gate = await _phase_verify_gate(3, "notebooklm", browser, cua_client)
            if _p3_gate == "stop":
                emit_event("pipeline_stopped", phase=3, reason="user_stop_at_verify_gate")
                return
            if _p3_gate == "skipped":
                log("Phase 3: NLM verify gate skipped → cascade-skipping P4 (no YouTube without podcast)", "INFO")
                _controls.skipped_phases.add(3)
                _controls.skipped_phases.add(4)
        # ══════════════════════ PHASE 3: NotebookLM Processing (upload + audio) ══════════════════════
        audio_path = None
        _user_skip_p3 = _controls.consume_phase_skip(3)
        if 3 in skip_phases or _user_skip_p3:
            _reason = "user_skip" if _user_skip_p3 else "Disabled in pipeline config"
            log(f"Phase 3: SKIPPED ({_reason})")
            emit_event("phase_skipped", phase=3, reason=_reason)
            # Flow C: when P3 is skipped AND the user pasted source URLs at
            # start time, hydrate the P5-bound locals from those URLs so the
            # final Doc + email body have something to render. Every pasted
            # link is appended to a Firestore `userSources` array
            # (collision-safe, validation-skipping, label-preserving) so the
            # FE-P5 Doc composer sees the full list — no link is ever
            # dropped due to key overwrite or strict validate_link rejection.
            #
            # First-of-kind also writes to the keyed `links` aggregate via
            # emit_validated_link (notebook / youtube / audio) so existing
            # FE consumers that key on those slots (P3/P4 dropdowns) keep
            # working uniformly with non-Flow-C runs.
            if user_links:
                _flow_c_count = 0
                for _link in user_links:
                    _kind = (_link.get("kind") or "").lower()
                    _url = (_link.get("url") or "").strip()
                    _label = (_link.get("label") or "Source").strip() or "Source"
                    if not _url:
                        continue
                    # Always append to userSources — guarantees the Doc
                    # renders every pasted link with the user's label.
                    append_user_source_in_firestore(_kind, _url, _label, phase=3)
                    # Populate keyed-aggregate slots for first-of-kind so
                    # phase dropdowns + downstream pipeline consumers find
                    # them at the canonical paths.
                    if _kind == "brief" and not brief_url:
                        # User-pasted brief link (e.g. "ChatGPT Brief:" label
                        # in front of a chatgpt.com/share URL). Routes to
                        # the canonical Research Brief slot so FE-P5 emits
                        # body.brief_url and the Doc renders it under the
                        # standard "Research Brief" HEADING_2 section,
                        # parallel to Flow A/B's pipeline-generated brief.
                        brief_url = _url
                        emit_validated_link(2, "brief", _url, _label or "Research Brief")
                    elif _kind == "notebook" and not notebook_url:
                        notebook_url = _url
                        emit_validated_link(3, "notebooklm", _url, _label or "NotebookLM Notebook")
                    elif _kind == "youtube" and not youtube_url:
                        youtube_url = _url
                        emit_validated_link(4, "youtube", _url, _label or "YouTube Video")
                    elif _kind == "audio" and not audio_overview_url:
                        audio_overview_url = _url
                        emit_validated_link(3, "notebooklm", _url, _label or "Audio Overview", link_kind="audio")
                    elif _kind in ("doc", "agent", "other"):
                        # In-memory map keeps existing label-suffix collision
                        # avoidance for delivery.json mirror + downstream uses.
                        # Firestore truth lives in userSources (above).
                        _key = _label
                        _i = 2
                        while _key in links:
                            _key = f"{_label} ({_i})"
                            _i += 1
                        links[_key] = _url
                    _flow_c_count += 1
                log(f"Flow C hydration: {_flow_c_count} link(s) → notebook={'set' if notebook_url else '∅'} "
                    f"youtube={'set' if youtube_url else '∅'} audio={'set' if audio_overview_url else '∅'} "
                    f"sources={len(links)}")
                # Mirror to delivery.json so P5 reads them on resume + the FE
                # tile shows them as the run progresses.
                update_delivery(notebook_url=notebook_url, youtube_url=youtube_url,
                                audio_url=audio_overview_url, research_links=dict(links))
        elif start_phase <= 3:
            emit_event("phase_start", phase=3, description="Uploading to NotebookLM + generating audio overview", agents=["notebooklm"])
            _update_firestore_research({"phase": 3, "currentPhase": 3, "status": "ongoing"})
            _p3_start = time.time()
            # Phase 3 has two sub-steps with separate budgets:
            #   • upload (3a): PHASE_3_UPLOAD_MAX_MIN=15 — hard-cap, bounded utility op
            #   • audio  (3b): PHASE_3_AUDIO_MAX_MIN=90 — soft-warn (advisory),
            #     long-podcast generation is legitimate.
            # Paused seconds don't count toward either active-time ceiling.
            # Per-phase login probe removed (2026-04-24) — see Phase 1 note.
            if not results:
                # 2026-05-11: only synthesize results for the three known
                # agent stems. Pre-fix, the dict.get(stem, stem) fallback
                # let an unrecognized stem (e.g. consolidated.md after a
                # checkpoint resume) become a synthetic "consolidated"
                # agent that flowed back through the P2→P3 handoff and
                # was uploaded to NotebookLM as a fourth source. The
                # _scan_p3_docs filter above already excludes brief/
                # consolidated stems, but this allowlist is the
                # belt-and-suspenders guard for anything else that ends
                # up in documents/.
                _AGENT_NAME_BY_STEM = {"chatgpt": "ChatGPT", "gemini": "Gemini", "claude": "Claude"}
                for md_file in md_files:
                    stem = md_file.stem.lower()
                    name = _AGENT_NAME_BY_STEM.get(stem)
                    if not name:
                        continue
                    results[name] = {"status": "done", "text": md_file.read_text(encoding="utf-8"),
                                     "url": "", "page": None}
            # Sub-step 3a: Upload to NotebookLM
            _p3a_user_skipped = False
            # Set when the link-extract failure card ends in a skip — either the
            # user clicking Skip or the card going unanswered for its full
            # auto-skip window. Kept separate from `_p3_audio_user_skipped`
            # (which is re-initialised after the link-extract block) and read by
            # the terminal gate so the phase reports a SKIP rather than a green
            # "notebook created".
            _p3_link_skipped = False
            # 2026-05-07 (Bug A1): narrow-retry budget for the upload step.
            # When run_phase3_upload silently completes with a bogus URL
            # (e.g. CUA returned 'blocked: Google Sign-in' because the user
            # got logged out), looping just extract_notebooklm_url against
            # that broken page never recovers. The link-extract decision
            # branch below re-runs run_phase3_upload (up to MAX_REATTEMPTS
            # additional times) when the URL clearly isn't on the NotebookLM
            # domain. Total upload attempts = 1 + MAX_REATTEMPTS.
            _p3_upload_attempt = 0
            _P3_UPLOAD_MAX_REATTEMPTS = 1
            while True:  # timeout-retry loop
                try:
                    p3 = await _await_phase_with_active_deadline(
                        3, PHASE_3_UPLOAD_MAX_MIN,
                        lambda: run_phase3_upload(browser, cua_client, results, topic, queue_dir, verbose),
                    )
                    break
                except asyncio.TimeoutError:
                    _decision = await _phase_timeout_decision(3, PHASE_3_UPLOAD_MAX_MIN, agent="notebooklm")
                    if _decision == "retry":
                        emit_event("phase_restart", phase=3, reason="user_retry_after_timeout")
                        continue
                    if _decision == "skip":
                        emit_event("phase_skipped", phase=3, reason="user_skip_after_timeout")
                        _p3a_user_skipped = True
                        p3 = {"links": {}, "notebook_url": ""}
                        break
                    emit_event("pipeline_stopped", phase=3, reason=f"user_{_decision}_after_timeout")
                    return
            links = p3.get("links", {})
            notebook_url = p3.get("notebook_url", "")
            # B1: Link-first — retry notebook URL extraction on validation failure.
            # ARCHITECTURE 2026-04-18 (never-die): wrap the retry in a decision
            # loop so repeated extract failures surface as a phase alert with
            # Retry / Skip instead of silently terminating.
            #
            # 2026-05-07: when the user picked Skip at the upload-step timeout
            # decision, notebook_url is empty by design — skip the entire
            # link-extract block instead of falling through into a retry loop
            # that would re-prompt for a notebook that doesn't exist.
            _p3_login_skipped = "notebooklm" in _controls.skipped_agents
            if _p3a_user_skipped or _p3_login_skipped or _controls.is_stop():
                # user skipped upload (timeout decision, or the #899 work-tab
                # login pause) / stop — nothing to extract. A login-pause skip
                # cascades P4 off, same as the verify gate's skip did (no
                # YouTube without a podcast), and emits the phase's TERMINAL
                # skip event — without it this path fell through to a false
                # phase_complete:3 claiming "NotebookLM notebook created"
                # (review MAJOR). phase_skipped:3 also live-triggers FE-P4's
                # no-audio fast path → FE-P5, so delivery still completes.
                if _p3_login_skipped:
                    log("Phase 3: NotebookLM skipped at the login pause — no notebook; cascading P4 off", "INFO")
                    _controls.skipped_phases.add(4)
                    emit_event("phase_skipped", phase=3,
                               reason=("login_required_timeout"
                                       if "notebooklm" in _controls.login_pause_timeout_agents
                                       else "user_skip_at_login_pause"))
            elif not (notebook_url and validate_link("notebooklm", notebook_url)):
                log("[NotebookLM] Notebook URL missing/invalid — retrying via extractor (3×)", "WARN")
                while True:
                    nb_res = await extract_with_retry(
                        phase=3, agent="notebooklm", browser=browser, cua_client=cua_client,
                        extractor_fn=extract_notebooklm_url,
                        label="NotebookLM Notebook", verbose=verbose,
                    )
                    # 2026-04-25 (Commit 9 follow-up): `verified` now requires
                    # BOTH a NotebookLM URL shape AND a DOM-confirmed public
                    # share. The DOM-verify can fail for benign reasons
                    # (Material dropdown without aria-selected, transient
                    # eval error, dialog already closed), so gating the
                    # recovery loop on `verified` alone would starve fine
                    # notebooks. Accept URL-shape-only here — the link still
                    # works for the user even if not DOM-confirmed public.
                    # If the link turns out to be private, downstream Doc/email
                    # consumers will surface the auth error to the recipient,
                    # which is the only context where it actually matters.
                    if nb_res.verified or is_notebooklm_url(nb_res.url):
                        notebook_url = nb_res.url
                        if not nb_res.verified:
                            # Same false alarm as the primary path — see there.
                            log("[NotebookLM] shared; sharing state could not be read "
                                "back (detector gap, not evidence the link is private)",
                                "DEBUG")
                        break
                    log(f"Phase 3: no verified NotebookLM URL after retries — awaiting user decision ({nb_res.error})", "ERROR")
                    # #893: a stale trusted Google cookie lands here as a
                    # sign-in redirect — name the real cause so the card is
                    # actionable (and re-verify for real on the next gate).
                    _nb_wall = await _page_shows_login_wall(getattr(browser, "page", None))
                    # 2026-07-31 — the OTHER end of the 0-second retraction.
                    #
                    # Phase 2 retracted its Retry/Skip card in 0 seconds; Phase 3
                    # never retracted this one. `await_phase_decision` defaults to
                    # a 24-hour timeout and the emitter stamped no deadline at
                    # all, so an unattended link failure hung the run until the
                    # outer watchdog killed it — with no countdown shown, because
                    # there was nothing to count down to. Same alert system,
                    # opposite failure modes, both wrong.
                    #
                    # 0 here means "no auto-skip armed" — no countdown is stamped
                    # on the card and none is shown. The wait still falls back to
                    # `await_phase_decision`'s 24-hour outer backstop, which
                    # returns the SAME "timeout" string, so the decision handler
                    # below has to tell the two apart: an ARMED expiry is an
                    # auto-skip, an unarmed one is `link_unresolved_backstop` —
                    # the phase is skipped either way (the run must still deliver)
                    # but only the armed one claims a window the user configured.
                    # Until 2026-08-02 there was no such separation and 0 was
                    # reported as an auto-skip after 24 h. Two cases arm nothing:
                    #   * a SIGN-IN WALL. The taxonomy classes a login card as a
                    #     blocker — the user CAN resolve it, so it must never
                    #     auto-fire. Auto-skipping someone's notebook because they
                    #     were away from a sign-in prompt is the wrong trade.
                    #   * auto-skip turned OFF in settings. Every other auto-skip
                    #     honours that switch; this one must too.
                    _nb_skip_in = 0.0
                    if _nb_wall:
                        _controls.cookie_trust_broken.add("notebooklm")
                        log(f"[NotebookLM] shows {_nb_wall} — Google session expired (stale cookie)", "WARN")
                        fail_phase(
                            phase=3,
                            error="NotebookLM looks signed out",
                            reason="Google is asking to sign in again — the saved session expired. "
                                   "Sign in using the open browser (or run the login command on the device), then Retry.",
                            agent="notebooklm",
                        )
                    else:
                        _nb_skip_in = unacted_window_sec(_runtime.auto_skip_stuck)
                        # `arm_registry=False`: the wait below IS the firer
                        # (design G(ii)). The round-robin registry firer only
                        # fires agents inside its own `pending` set, which a P3
                        # phase card never enters, so an armed entry would just be
                        # a stale row. The deadline still rides the EVENT, so the
                        # FE counts down to the same moment this wait expires.
                        _nb_deadline_kw = (
                            {"auto_skip_deadline": (time.time() + _nb_skip_in) * 1000,
                             "arm_registry": False}
                            if _nb_skip_in else {})
                        fail_phase(
                            phase=3,
                            # ⛔⛔ 2026-08-28: this card used to say "Couldn't get
                            # the NotebookLM link". The gate that raises it fires
                            # when the tab is not sitting on a /notebook/{id}
                            # page — which means the UPLOAD did not land, not
                            # that a share dialog failed. `notebook_url` is
                            # `current_url()`, captured before any share step, so
                            # there is no "link extraction" to fail here. The
                            # retry below re-runs `run_phase3_upload` from
                            # scratch precisely because the upload is what is
                            # missing; the copy now says what the code does.
                            error="Couldn't open the NotebookLM notebook",
                            # ⛔⛔ IT DOES NOT CLAIM THE UPLOAD SUCCEEDED, and the
                            # first version of this copy did. The gate reaches
                            # here from three states, and only one of them has
                            # a notebook: the upload threw and exhausted its
                            # retries (56307), the login pause ended in a skip
                            # (56220), or the upload landed somewhere that is
                            # not a /notebook/{id} page. "We uploaded your
                            # reports but the notebook didn't open" is false on
                            # the first two — and the user has just dismissed a
                            # card saying the upload failed, so it also
                            # contradicts what they were told a moment ago.
                            reason="We couldn't get to your NotebookLM notebook, so the audio overview can't be generated. Retry to upload the reports again, or Skip it.",
                            agent="notebooklm",
                            **_nb_deadline_kw,
                        )
                    decision = await _controls.await_phase_decision(
                        3, timeout=(_nb_skip_in if _nb_skip_in else 86400.0))
                    if decision == "retry":
                        # 2026-05-07 (Bug A1): if the URL we have isn't even on
                        # the NotebookLM domain (sign-in redirect, blank, etc.),
                        # the upload itself never landed — re-running just the
                        # extractor against the same broken page recovers
                        # nothing. Re-run run_phase3_upload from scratch. The
                        # domain-substring gate is more lenient than
                        # validate_link's "/notebook/" check, so a partial-
                        # success URL on notebooklm.google.com (e.g. /home or
                        # a non-canonical path) bypasses re-upload and falls
                        # through to extractor-only retry — bounding the
                        # re-upload to genuine "upload-never-happened" cases.
                        # run_phase3_upload opens a fresh tab via
                        # browser.new_tab(...) on every entry, so no manual
                        # cleanup is needed between attempts.
                        _url_looks_like_notebook = bool(
                            is_notebooklm_url(notebook_url)
                        )
                        if (not _url_looks_like_notebook
                                and _p3_upload_attempt < _P3_UPLOAD_MAX_REATTEMPTS):
                            _p3_upload_attempt += 1
                            log(f"Phase 3 retry: URL '{notebook_url}' not on NotebookLM domain — "
                                f"re-running run_phase3_upload "
                                f"({_p3_upload_attempt}/{_P3_UPLOAD_MAX_REATTEMPTS})", "INFO")
                            emit_event("phase_restart", phase=3, reason="user_retry_re_upload",
                                       attempt=_p3_upload_attempt)
                            try:
                                p3 = await _await_phase_with_active_deadline(
                                    3, PHASE_3_UPLOAD_MAX_MIN,
                                    lambda: run_phase3_upload(browser, cua_client, results, topic, queue_dir, verbose),
                                )
                                links = p3.get("links", {})
                                notebook_url = p3.get("notebook_url", "")
                            except asyncio.TimeoutError:
                                # Hard timeout on the re-upload — leave URLs
                                # as-is and fall through to extractor retry.
                                # User can hit Retry again, exhaust the
                                # re-upload budget, and end up just looping
                                # the extractor (no infinite re-upload).
                                log("Phase 3 re-upload hit hard timeout — falling through to extractor retry", "WARN")
                            continue
                        log("Phase 3 link extraction: user requested retry", "INFO")
                        emit_event("phase_restart", phase=3, reason="user_retry_link_extract", attempt=0)
                        continue
                    # 2026-08-02 — a timeout is an AUTO-SKIP only if an auto-skip
                    # was actually armed.
                    #
                    # This used to read `decision in ("skip", "timeout")` and set
                    # `_nb_auto = decision == "timeout"`, under a comment asserting
                    # that `timeout` could only arrive with a deadline set. It
                    # could not: when `_nb_skip_in` is 0 the wait still falls back
                    # to the 24-hour backstop, and the backstop returns the same
                    # string. So the two cases that deliberately arm NOTHING — a
                    # sign-in wall (a blocker, which the taxonomy says must never
                    # auto-fire) and auto-skip switched OFF in Settings — were both
                    # reported as "card unanswered for its full window", a window
                    # nobody set, under a reason slug the FE renders as an
                    # auto-skip.
                    #
                    # Three outcomes now, three reasons. The unarmed expiry still
                    # ENDS the wait — the module's standing invariant is that no
                    # path waits unboundedly for a human — but it ends it by
                    # skipping the phase and letting the run finish, not by
                    # stopping the run. An earlier version of this fix emitted
                    # `pipeline_stopped` + `return` here; that returns out of
                    # run_pipeline ABOVE the terminal handoff, so a run whose P1
                    # and P2 had fully succeeded lost its Google Doc, its email and
                    # its P3 checkpoint — total loss where the bug it replaced at
                    # least delivered. Skipping keeps the three reports, the Doc
                    # and the email, and `link_unresolved_backstop` tells the truth
                    # about which of the three things happened.
                    _nb_auto = is_armed_timeout(decision, _nb_skip_in)
                    _nb_backstop = decision == "timeout" and not _nb_auto
                    if decision == "skip" or _nb_auto or _nb_backstop:
                        # 2026-07-31 (owner-reported): this branch used to just
                        # blank the URL and break. That made it the ONLY skip
                        # branch in the whole pipeline that emitted no terminal
                        # event and set no skip flag — all thirteen others emit
                        # phase_skipped. The consequences, in order:
                        #   * with notebook_url empty the audio block is skipped
                        #     entirely, so `_p3_audio_user_skipped` stayed False,
                        #   * the no-audio auto-retry loop is `while notebook_url`
                        #     so it never ran either,
                        #   * and the terminal gate therefore saw BOTH flags
                        #     False and emitted phase_complete:3 with the summary
                        #     "NotebookLM notebook created".
                        # So a user who hit Skip on a NotebookLM link failure got
                        # a GREEN, completed Phase 3 claiming a notebook that was
                        # never obtained, instead of the greyed-out skip they
                        # asked for. P4 also wasn't cascaded off, so FE-P4 was
                        # triggered for a podcast that does not exist.
                        log("Phase 3 link extraction: "
                            + ("card unanswered for its full window — auto-skipping"
                               if _nb_auto else
                               "no auto-skip was armed and the card sat to the 24-hour "
                               "backstop — moving on without deciding for the user"
                               if _nb_backstop else "user skipped")
                            + " — proceeding without notebook URL", "INFO")
                        notebook_url = ""
                        emit_event("phase_skipped", phase=3,
                                   reason=("auto_skip_link_unanswered" if _nb_auto
                                           else "link_unresolved_backstop" if _nb_backstop
                                           else "user_skip_at_link_extract"))
                        # NB: a dedicated flag, NOT `_p3_audio_user_skipped` —
                        # that one is re-initialised to False a few lines below
                        # this loop, which would silently undo the fix.
                        _p3_link_skipped = True
                        _controls.skipped_phases.add(4)
                        break
                    # Only a real Stop reaches here now — `timeout` is handled
                    # above, so `user_{decision}_link_extract` can no longer read
                    # "user_timeout", which was never something the user did.
                    log(f"Phase 3 link extraction: user {decision} — terminating pipeline", "INFO")
                    emit_event("pipeline_stopped", phase=3, reason=f"user_{decision}_link_extract")
                    return
            else:
                emit_validated_link(3, "notebooklm", notebook_url, "NotebookLM Notebook")
            (queue_dir / "links.json").write_text(json.dumps(links, indent=2), encoding="utf-8")
            save_checkpoint(queue_dir, 3, topic=topic, brief_url=brief_url,
                            notebook_url=notebook_url)
            update_delivery(research_links=links, notebook_url=notebook_url)
            # Sub-step 3b: Generate audio overview
            audio_overview_url = ""
            _p3_audio_stored = ""
            _p3_audio_user_skipped = False
            if notebook_url:
                while True:  # timeout-retry loop
                    try:
                        _p3_audio = await _await_phase_with_active_deadline(
                            3, PHASE_3_AUDIO_MAX_MIN,
                            lambda: run_phase3_audio(browser, cua_client, notebook_url, queue_dir, verbose, podcast_length=podcast_length),
                            soft_warn_only=True,  # 2026-05-04: NLM audio gen legitimately runs 30-45m on long podcasts; warn but don't bail
                        )
                        break
                    except _PhaseSoftDecision as _sd:
                        # User picked Retry/Skip on the soft-timeout warn.
                        # Wait is implicit — never reaches this except (the
                        # helper keeps polling on Wait until run_task either
                        # finishes naturally OR user picks Retry/Skip).
                        if _sd.decision == "retry":
                            emit_event("phase_restart", phase=3, reason="user_retry_after_audio_soft_timeout")
                            continue
                        if _sd.decision == "skip":
                            emit_event("phase_skipped", phase=3, reason="user_skip_after_audio_soft_timeout")
                            _p3_audio = {"audio_path": None, "audio_overview_url": ""}
                            _p3_audio_user_skipped = True
                            _controls.skipped_phases.add(4)
                            break
                        log(f"[P3-audio] Unexpected _PhaseSoftDecision.decision={_sd.decision!r}", "ERROR")
                        raise
                    except asyncio.TimeoutError:
                        # Legacy hard-path safety net — with soft_warn_only=True
                        # the helper raises _PhaseSoftDecision instead of
                        # TimeoutError, so this branch is normally unreachable.
                        # Kept as a guard in case run_phase3_audio raises a bare
                        # TimeoutError that escapes the helper's wrap.
                        _decision = await _phase_timeout_decision(3, PHASE_3_AUDIO_MAX_MIN, agent="notebooklm")
                        if _decision == "retry":
                            emit_event("phase_restart", phase=3, reason="user_retry_audio_timeout")
                            continue
                        if _decision == "skip":
                            emit_event("phase_skipped", phase=3, reason="user_skip_audio_timeout")
                            _p3_audio = {"audio_path": None, "audio_overview_url": ""}
                            _p3_audio_user_skipped = True
                            _controls.skipped_phases.add(4)
                            break
                        emit_event("pipeline_stopped", phase=3, reason=f"user_{_decision}_audio_timeout")
                        return
                audio_path = _p3_audio.get("audio_path")
                # ⛔ THE PHASE'S OWN VERDICT, and it is a Firebase Storage URL,
                # not a NotebookLM page. Empty means the bytes are not where the
                # app looks for them, whatever else happened.
                _p3_audio_stored = _p3_audio.get("audio_stored_url", "")
                save_checkpoint(queue_dir, 3, topic=topic, brief_url=brief_url,
                                notebook_url=notebook_url,
                                audio_path=str(audio_path) if audio_path else "",
                                audio_overview_url=audio_overview_url)
                # ⛔ 2026-08-28: this was `audio_overview_url or notebook_url` —
                # the audio SHARE page, which the removed block derived from
                # `notebook_url` anyway, so the two arms were the same string on
                # the healthy path. delivery.json's audio reference is now the
                # PLAYABLE file when we hold one, and falls back to the notebook
                # only so an existing consumer never reads an empty field.
                update_delivery(audio_url=_p3_audio_stored or audio_overview_url or notebook_url)
            # B2: save_meta runs ffprobe per podcast file inline (~5s/file).
            # 2026-05-10: spawn on a daemon thread (NOT awaited) so the
            # ffprobe doesn't gate phase_complete:3 emission. FE-P4 was
            # waiting on this and the P3→P4 transition looked stuck for
            # ~5s. save_meta only enriches meta.json with audio duration;
            # no downstream phase reads from meta.json synchronously.
            try:
                _threading.Thread(
                    target=save_meta,
                    args=(queue_dir, topic, 3),
                    name="p3-savemeta-ffprobe",
                    daemon=True,
                ).start()
            except Exception as _smt_e:
                log(f"[Phase 3] failed to dispatch save_meta thread: {_smt_e}", "WARN")
            # Build Phase 3 links — include both notebook and audio overview
            # Only include links that pass validation (no fake/placeholder URLs)
            _p3_links = []
            if notebook_url and validate_link("notebooklm", notebook_url):
                _p3_links.append({"label": "NotebookLM Notebook", "url": notebook_url, "verified": True})
            # ⛔ THE "Audio Overview" ROW LEFT HERE ON 2026-08-28, because on
            # this branch it was DEAD. `audio_overview_url` is `""` for the
            # whole of the ordinary run path — its only other writer is the
            # Flow-C hydration of a link the USER pasted, which is the
            # mutually-exclusive arm of the same if/elif — so the append could
            # never fire, while its comment still explained how the FE would
            # render the row. The frontend now injects that row itself from
            # `research.audios[].audioUrl`, the playable Storage file
            # (`src/lib/audio-row.ts`), which is the artefact this phase
            # completes on rather than a NotebookLM page.
            # Hard rule (user_locked 2026-05-02): P3 marks complete only when
            # both notebook AND audio are obtained. Surface a [Retry, Skip]
            # alert when audio is missing rather than emitting phase_complete
            # with stale-audio risk and tripping P4's no-audio fail_phase.
            # Fix B (2026-05-27): bounded AUTO-retry for missing audio,
            # replacing the old UNBOUNDED await_phase_decision(3). In
            # autonomous/serve mode no human clicks Retry, so that wait
            # dead-hung the run for hours until the outer watchdog killed it
            # (the verified deadlock). Instead, auto-retry up to 3× at 5-min
            # intervals, reusing THIS run's already-generated card via
            # prefer_existing_audio=True (Fix A re-anchors each download to
            # the run's own notebook). Only after all 3 fail do we fall back
            # to notebook-link-only — a non-blocking outcome.
            # INVARIANT: no path here waits unboundedly for a human.
            _AUDIO_MAX_AUTO_RETRIES = 3
            _AUDIO_RETRY_INTERVAL_SEC = 5 * 60
            _audio_auto_retries = 0
            while bool(notebook_url) and not audio_path and not _p3_audio_user_skipped:
                if _controls.is_stop():
                    log("Phase 3: stop requested during no-audio handling — aborting", "INFO")
                    return
                # #778 SKIP FIX: honor a user SKIP_PHASE(3) issued DURING this
                # no-audio retry loop. Pre-fix the loop only checked is_stop +
                # _p3_audio_user_skipped, so a Skip click — which adds 3 (and,
                # via the skip_phase handler's cascade, 4) to skipped_phases —
                # was IGNORED and the loop kept auto-retrying for the full bound
                # (the user's "skip didn't work"). Treat it as a clean skip:
                # notebook-link-only + cascade P4 off.
                if 3 in _controls.skipped_phases:
                    log("Phase 3: user skipped during no-audio handling — continuing with notebook link only", "INFO")
                    emit_event("phase_skipped", phase=3, reason="user_skip_during_audio_auto_retry")
                    _p3_audio_user_skipped = True
                    _controls.skipped_phases.add(4)
                    break
                # #899: a Skip on the work-tab login pause (or its timeout)
                # leaves notebooklm in skipped_agents — run_phase3_audio
                # early-returns on it, so auto-retrying is 3× 5-min waits for
                # nothing. Same clean skip as above, with the HONEST reason
                # (telemetry must distinguish a login-pause skip/timeout from
                # a genuine #778 skip-during-auto-retry).
                if "notebooklm" in _controls.skipped_agents:
                    log("Phase 3: NotebookLM skipped at the login pause — continuing with notebook link only", "INFO")
                    emit_event("phase_skipped", phase=3,
                               reason=("login_required_timeout"
                                       if "notebooklm" in _controls.login_pause_timeout_agents
                                       else "user_skip_at_login_pause"))
                    _p3_audio_user_skipped = True
                    _controls.skipped_phases.add(4)
                    break
                if _audio_auto_retries >= _AUDIO_MAX_AUTO_RETRIES:
                    # Exhausted auto-retries → graceful, non-blocking fallback:
                    # continue with notebook-link-only. P5 still delivers the
                    # notebook link + report; P4 (YouTube) cascades off. Inform
                    # the user with a dismissible amber warning (NOT a red error
                    # — the run succeeded apart from the podcast file).
                    log(f"Phase 3: audio still missing after {_AUDIO_MAX_AUTO_RETRIES} auto-retries — continuing with notebook link only", "WARN")
                    try:
                        emit_event(
                            "pipeline_warning", phase=3, agent="notebooklm",
                            message="Audio Overview couldn't be captured after 3 retries — continuing with the notebook link only.",
                            details=("NotebookLM produced the podcast but the audio file couldn't be downloaded and streamed "
                                     "after 3 attempts. The notebook link is still delivered in your report and email; the "
                                     "YouTube upload step is skipped. Re-run this research if you want to retry the audio."),
                            alertType="warn", dismissible=True,
                            # 2026-08-06: explicit "no buttons". This one is
                            # agent-scoped, so the web app's agent panel already
                            # defaults to none — but the PHASE panel invents a
                            # [Skip] from an undefined `actions`, and a card that
                            # relies on which panel happens to render it is one
                            # refactor from growing a button. Say it here.
                            actions=[],
                            alert_id=f"phase3_audio_giveup_{int(time.time())}",
                        )
                    except Exception:
                        pass
                    # ⭐ Carry the notebook. This branch is the ONLY way a
                    # notebook that was built successfully reaches a terminal
                    # phase-3 event that is not phase_complete — the warning
                    # card right above says so in words ("continuing with the
                    # notebook link only") — and until now the event dropped it,
                    # so the web app announced a skipped phase and never the
                    # thing the phase actually produced.
                    #
                    # ⛔ No other phase_skipped:3 emit carries links, and that is
                    # load-bearing: the notifier keys the notebook notice off
                    # their presence, so a config skip or a user Skip cannot
                    # announce a notebook that the run never made.
                    emit_event("phase_skipped", phase=3, reason="audio_unavailable_after_auto_retries",
                               links=_p3_links)
                    _p3_audio_user_skipped = True
                    _controls.skipped_phases.add(4)
                    break

                _audio_auto_retries += 1
                _wait_min = _AUDIO_RETRY_INTERVAL_SEC // 60
                log(f"Phase 3: audio file missing — auto-retry {_audio_auto_retries}/{_AUDIO_MAX_AUTO_RETRIES} in {_wait_min} min", "WARN")
                emit_event("agent_progress", phase=3, agent="notebooklm", status="downloading",
                           stage="podcast",
                           progress=f"Audio not captured yet — retrying ({_audio_auto_retries}/{_AUDIO_MAX_AUTO_RETRIES}) in {_wait_min} min…")

                # 5-min interval wait — interruptible so Stop/Pause/Skip are
                # honored (the wait must never become an unbounded human hang).
                # #778: skip_phase=3 so a Skip click breaks the wait immediately
                # instead of being ignored until the full 5 min elapses.
                _interrupt = await _controls.interruptible_sleep(
                    _AUDIO_RETRY_INTERVAL_SEC, check_interval=10, skip_phase=3,
                    # ⭐⭐ 2026-08-06 — THE RETRY THE WAIT COULD NOT HEAR. The user
                    # pressed Retry on the phase-3 card; the backend logged
                    # "Command received: RETRY_PHASE phase=3" and then went on
                    # sleeping, because this wait watched only stop / skip /
                    # pause. The app sat on "restarting" with nothing to
                    # acknowledge it, the paused chrome latched, and the user
                    # eventually pressed Stop. The retry it was already going to
                    # perform in five minutes was the very thing being asked for.
                    # ⛔ And leaving the flag unconsumed is its own bug: a later
                    # soft-warn can cash it and restart a phase nobody asked to
                    # restart. Consume it HERE, where it means something.
                    retry_phase=3)
                if _interrupt == "retry":
                    # ⛔⛔ NO `continue` HERE, and the first version of this fix had
                    # one. `continue` restarts the while loop — jumping straight
                    # PAST the retry attempt at the bottom of this body — so the
                    # press announced "restarting the audio attempt now", spent an
                    # auto-retry slot, and began another five-minute sleep having
                    # run nothing. Three presses would exhaust the budget with
                    # `run_phase3_audio` never called once. Fall through instead:
                    # every branch below tests `_interrupt` against a different
                    # value, so control lands on the attempt, which is what was
                    # asked for.
                    log("Phase 3: retry requested during the no-audio wait — "
                        "restarting the audio attempt now", "INFO")
                    emit_event("phase_restart", phase=3, reason="user_retry_audio_missing",
                               attempt=_audio_auto_retries)
                    # A person asking for a retry must not spend one of the three
                    # UNATTENDED attempts; give the slot back.
                    _audio_auto_retries = max(0, _audio_auto_retries - 1)
                if _interrupt == "stop":
                    log("Phase 3: stop during no-audio retry wait — aborting", "INFO")
                    return
                if _interrupt == "skip":
                    # #778 SKIP FIX: a Skip click landed mid-wait — break the
                    # 5-min sleep now → notebook-link-only + cascade P4 off.
                    log("Phase 3: user skipped during no-audio retry wait — continuing with notebook link only", "INFO")
                    emit_event("phase_skipped", phase=3, reason="user_skip_during_audio_auto_retry")
                    _p3_audio_user_skipped = True
                    _controls.skipped_phases.add(4)
                    break
                if _interrupt == "pause":
                    emit_event("pipeline_paused", phase=3)
                    await _controls.wait_if_paused()
                    if _controls.is_stop():
                        return

                if _interrupt != "retry":
                    # The user-retry path already emitted its own restart above.
                    emit_event("phase_restart", phase=3, reason="auto_retry_audio_missing", attempt=_audio_auto_retries)
                try:
                    _p3_audio = await _await_phase_with_active_deadline(
                        3, PHASE_3_AUDIO_MAX_MIN,
                        lambda: run_phase3_audio(browser, cua_client, notebook_url, queue_dir, verbose,
                                                 podcast_length=podcast_length, prefer_existing_audio=True),
                        soft_warn_only=True,
                    )
                    audio_path = _p3_audio.get("audio_path")
                    # ⛔⛔ THIS BRANCH READ A KEY THE FUNCTION NO LONGER RETURNS.
                    # It used to pull `audio_overview_url` — the NotebookLM audio
                    # SHARE page, removed in stretch 6.6C — and would now have
                    # been permanently dead: `.get(…, "")` on a missing key is
                    # falsy, so the recovery leg would have silently stopped
                    # recording anything about the audio it just recovered. It
                    # reads the artefact instead, the same one the primary leg
                    # and the completion gate read.
                    _p3_audio_stored = _p3_audio.get("audio_stored_url", "")
                    if audio_path:
                        log(f"Phase 3: audio recovered on auto-retry {_audio_auto_retries}/{_AUDIO_MAX_AUTO_RETRIES}", "INFO")
                        save_checkpoint(queue_dir, 3, topic=topic, brief_url=brief_url,
                                        notebook_url=notebook_url,
                                        audio_path=str(audio_path),
                                        audio_overview_url=audio_overview_url)
                        # Parity with the primary path: refresh delivery.json's
                        # audio reference so P5's report/email point at the
                        # recovered podcast. (FE streaming uses the Firestore
                        # audioUrl written inside run_phase3_audio's tail,
                        # independent of this.)
                        update_delivery(audio_url=(_p3_audio_stored or audio_overview_url or notebook_url))
                except _PhaseSoftDecision as _sd:
                    # A user clicked Retry/Skip on the soft-timeout warn during
                    # this attempt. Skip → notebook-link-only + cascade P4.
                    # Retry → loop again (the next auto-retry handles it).
                    log(f"Phase 3 audio auto-retry soft decision: {_sd.decision}", "INFO")
                    if _sd.decision == "skip":
                        emit_event("phase_skipped", phase=3, reason="user_skip_during_audio_auto_retry")
                        _p3_audio_user_skipped = True
                        _controls.skipped_phases.add(4)
                        audio_path = None
                        break
                    audio_path = None
                except asyncio.TimeoutError:
                    log("Phase 3 audio auto-retry timed out", "WARN")
                    audio_path = None
                except Exception as _ar:
                    log(f"Phase 3 audio auto-retry failed: {_ar}", "WARN")
                    audio_path = None
                continue
            # #899: a login-pause skip (or a stop) must not read as a green
            # "NotebookLM notebook created" — those paths already emitted
            # their own terminal event (phase_skipped:3 / pipeline_stopped).
            # 2026-07-31: TWO flags joined them, and they are different bugs.
            #
            # `_p3_link_skipped` was the owner-reported one — a Skip on the
            # link-extract failure card emitted no terminal event at all, so it
            # fell through to here and produced a green phase_complete claiming a
            # notebook that was never obtained ("instead of greyed out skip, it
            # got the completed status"). It now also covers that card being
            # auto-skipped after going unanswered for its full window.
            #
            # `_p3a_user_skipped` is the sibling, found in adversarial review of
            # that fix. A Skip on the P3 UPLOAD-timeout card does emit
            # phase_skipped:3 (line ~44346) — so it looked correct — but it was
            # missing from this gate, so the phase then ALSO emitted
            # phase_complete:3: a double terminal event that flips the tile from
            # greyed-skipped back to green and overwrites the durable phase
            # status skipped→complete. "Emits a terminal event" and "emits
            # exactly ONE terminal event" are different guarantees, and only the
            # second one is what the user sees.
            # ⛔⛔ 2026-08-28 (stretch 6.6C) — AND ONE MORE CONDITION, WHICH IS
            # THE ARTEFACT. Every clause above is the ABSENCE of a skip flag;
            # not one of them reads the podcast. The invariant "phase_complete:3
            # implies we have audio" held only by an accident of coupling
            # elsewhere, and `phase-notice.ts` fires "Podcast ready" off this
            # event citing that invariant as "a hard backend rule". It was not a
            # rule, it was a coincidence. Owner decision 2026-08-28: P3 completes
            # on the DOWNLOADED AUDIO FILE — so the gate now says so out loud,
            # and a run that produced no playable podcast reports a skip with the
            # reason, instead of a green tile and a notice for a podcast that is
            # not there.
            _p3_no_skip = (not _p3_audio_user_skipped and not _p3_login_skipped
                           and not _p3_link_skipped
                           and not _p3a_user_skipped
                           and not _controls.is_stop())
            if _p3_no_skip and _p3_audio_stored:
                emit_event("phase_complete", phase=3, durationSec=int(time.time() - _p3_start), links=_p3_links,
                    summary=f"NotebookLM notebook created, audio generated{', notebook link recorded' if notebook_url else ''}")
            elif _p3_no_skip:
                # ⛔ NAME WHICH OF THE TWO FAILED. "No podcast" and "a podcast we
                # could not upload" are different states with different repairs,
                # and the second one still has the file sitting on the research
                # computer — telling the user only that Phase 3 did not finish
                # would throw that away.
                _p3_audio_reason = (
                    "audio_generated_but_upload_failed" if audio_path
                    else "no_audio_generated")
                log(f"[Phase3] no deliverable podcast ({_p3_audio_reason}) — "
                    f"reporting phase 3 as skipped rather than complete", "WARN")
                # ⛔⛔ `detail=`, NOT `summary=`. The frontend's phase_skipped
                # handler reads `evt.data.reason` and renders it through
                # `phaseSkipSummary`; `evt.data.summary` is read ONLY on
                # phase_complete. So the sentence this wave is proudest of — the
                # one telling a user their podcast is sitting on the research
                # computer — reached no surface at all, and the tile showed a
                # de-underscored slug instead. `detail` is the field the notice
                # path already prefers.
                emit_event("phase_skipped", phase=3, reason=_p3_audio_reason,
                           durationSec=int(time.time() - _p3_start), links=_p3_links,
                           detail=("NotebookLM notebook created. The podcast was generated but "
                                   "couldn't be uploaded — it's still on your research computer."
                                   if audio_path else
                                   "NotebookLM notebook created. No audio overview was produced."))
        else:
            links_file = queue_dir / "links.json"
            if links_file.exists():
                links = json.loads(links_file.read_text(encoding="utf-8"))
            audio_str = cp.get("audio_path", "")
            if audio_str and Path(audio_str).exists():
                audio_path = Path(audio_str)
            log(f"Phase 3: Loaded existing (links={len(links)}, audio={'yes' if audio_path else 'no'})")

        if _controls.is_stop_or_pause():
            if _controls.is_stop():
                log("STOP requested after Phase 3 — pipeline terminated", "WARN")
                save_meta(queue_dir, topic, 3, status="stopped")
                update_delivery(status="stopped")
                emit_event("pipeline_stopped", phase=3, reason="stop")
                _update_firestore_research({"status": "stopped", "phase": 3})
                return
            else:
                log("PAUSE requested after Phase 3 — closing browser, awaiting resume", "WARN")
                save_meta(queue_dir, topic, 3, status="paused")
                update_delivery(status="paused")
                _update_firestore_research({"status": "paused", "phase": 3})
                stopped = await pause_and_close_browser(browser, queue_dir, phase=3,
                                                        extra_kwargs={"topic": topic, "brief_url": brief_url,
                                                                      "notebook_url": notebook_url})
                if stopped:
                    save_meta(queue_dir, topic, 3, status="stopped")
                    emit_event("pipeline_stopped", phase=3, reason="stop_after_pause")
                    _update_firestore_research({"status": "stopped", "phase": 3})
                    return
                browser = Browser(_profile_dir(WORKER_ID), headless=False)
                await browser.start()
                _active_browser_ref = browser  # re-point stop handler at fresh session
                emit_event("pipeline_resumed", phase=3)
                _update_firestore_research({"status": "ongoing"})
                # Post-P2 input is disabled. Drop any residual buffer silently.
                if _controls.peek_extra_context():
                    _ = _controls.pop_extra_context()

        # ══════════════════════ P4 + P5 are now FE-owned (cutover 2026-05-10) ══════════════════════
        # Phase 4 (YouTube upload) and Phase 5 (Doc + email) both run in
        # the FE post-2026-05-10. After P3 completes the audio upload to
        # Firebase Storage (links.audio_file written above), the FE
        # listener picks up phase_complete:3, fires triggerFeP4 →
        # /api/uploadYouTube which downloads from Storage,
        # ffmpeg-encodes a static-image+audio mp4, uploads to YouTube
        # unlisted via youtube.videos.insert, then chains directly into
        # triggerFeP5 (Doc + email).
        #
        # BE exits cleanly here. We do NOT:
        #   - run any P4 code (run_phase4, extract_youtube_url, Studio
        #     DOM automation, CUA fallbacks — all dead)
        #   - emit phase_start:4 / phase_complete:4 / phase_skipped:4
        #     (FE-P4 emits those from triggerFeP4 itself)
        #   - touch currentPhase (FE-P4 advances it to 4, FE-P5 to 5)
        #   - emit pipeline_complete (FE-P5 owns it)
        #
        # delivery.status="completed" tells the daemon-loop the BE work
        # is done so it can advance to the next queue item; the
        # user-visible research.status stays "ongoing" until FE-P5's
        # markFeP5Completed flips it to "completed".
        #
        # 2026-07-16 (pause/resume invariant #4 — defensive): release any
        # residual pause / awaiting-user state before the FE handoff. On the
        # golden path nothing is held (await_*_decision clears in its finally),
        # but a non-golden exit into this terminal block must never strand the
        # FE "Paused" — P4/P5 are FE-owned, so the BE emits nothing more and no
        # later BE resume is coming. Emit pipeline_resumed so the FE clears its
        # paused chrome if a pause somehow survived to completion.
        try:
            if _controls.is_pause():
                _controls.request_resume()
                emit_event("pipeline_resumed", phase=3, reason="completion_handoff")
            _controls._awaiting_user = False
        except Exception as _clr_err:
            log(f"terminal pause-clear (non-fatal): {_clr_err}", "WARN")
        update_delivery(status="completed")
        # 2026-05-11: write beDone marker so the queue gate
        # (_wait_for_prior_fe_completion) knows BE handed off to FE.
        # research.status stays "ongoing" until FE-P5 flips it to
        # "completed" — that's the signal the gate actually waits on;
        # beDoneAt anchors the 4200s fallback timer.
        _update_firestore_research({"beDone": True, "beDoneAt": int(time.time() * 1000)})
        # 2026-05-12: autonomous P4/P5 trigger. BE has finished its work
        # through P3 (audio in Firebase Storage). Enqueue a Cloud Task that
        # POSTs to /api/uploadYouTube so Cloud Run runs P4 (YouTube upload)
        # + P5 (Doc + email) + flips status="completed" server-side. The
        # queue gate (_wait_for_prior_fe_completion) waits on status, so
        # this chain advances the queue even when the user's phone or tab
        # isn't open. Cloud Tasks owns delivery + retries; the call below
        # is a fast unary RPC (~50ms typical) — no thread held.
        try:
            _post_fe_p4p5_trigger(_fb_uid, _fb_research_id)
        except Exception as _trig_err:
            log(f"FE trigger dispatch failed (non-fatal): {_trig_err}", "WARN")
        log(f"\n{'='*60}")
        _dom_summary("run complete")
        log(f"\n{'='*60}")
        log("BE PIPELINE COMPLETE — through Phase 3 (FE owns Phases 4 + 5)")
        log(f"  NotebookLM: {notebook_url or 'N/A'}")
        # ⛔ THE PODCAST, NOT THE REMOVED SHARE PAGE. This read
        # `audio_overview_url`, which after 6.6C is `""` on every ordinary run —
        # so the last operator-facing line about a run that generated,
        # downloaded and uploaded a podcast said "Audio Overview: N/A". The
        # artefact the phase now completes on is the Storage URL.
        log(f"  Podcast: {_p3_audio_stored or 'N/A'}")
        log(f"  Queue: {queue_dir}")
        log(f"{'='*60}")

    except KeyboardInterrupt:
        # The verdict is worth MORE on a run that ended early, not less — that
        # is the run someone is about to go and diagnose.
        _dom_summary("run interrupted")
        log("Interrupted — progress saved to checkpoint", "WARN")
        raise
    except Exception as e:
        # Uncaught exception anywhere in the pipeline — surface it with
        # whatever phase context we have so the frontend can route the
        # error to the correct phase tile instead of silently dropping it.
        import traceback
        _dom_summary("run failed")
        log(f"Fatal: {e}", "ERROR")
        traceback.print_exc()
        # _runtime.phase is the most-recently-entered phase — use it as
        # the routing hint so the error lands on the right phase tile
        # instead of defaulting to 0 and polluting the P0 dropdown.
        last_phase = 0
        try:
            rp = getattr(_runtime, "phase", None)
            if isinstance(rp, int):
                last_phase = rp
        except Exception:
            pass
        # ── #725: browser-crash classification + silent self-heal ──
        # A mid-run Chrome death (window closed, OOM, profile-lock fight,
        # driver EPIPE) lands here as a TargetClosedError-class exception. A
        # deep poll-loop site may already have tagged last_failure_kind, but
        # crashes that raise straight out of navigate()/bring_to_front() never
        # reach that site — so classify from the exception itself here too.
        # This is the catch-all that makes the recovery phase-agnostic.
        if _is_browser_close_error(e):
            _runtime.last_failure_kind = "browser_crash"
        # Capture the kind NOW — the finally below calls _runtime.reset(),
        # which clears last_failure_kind BEFORE the post-finally auto-retry
        # block runs. (This is the latent half of the #725 bug: even the
        # poll-loop's browser_crash tag was being wiped before it was read.)
        _captured_failure_kind = getattr(_runtime, "last_failure_kind", "") or ""
        # Will the post-finally block silently re-run this from checkpoint? If
        # so, SUPPRESS the user-facing card — the silent-self-heal rule says we
        # only show Retry/Skip AFTER auto-retries are exhausted. Same predicate
        # the auto-retry block uses, so the two never disagree.
        # queue_dir is assigned (both resume + new-run branches) well before
        # the `try`, so it's always bound here.
        _will_silent_retry, _, _ = _plan_pipeline_auto_retry(
            queue_dir, resume_dir, _captured_failure_kind, _crash_retries)
        if _will_silent_retry:
            _att = _crash_retries + 1
            log(f"Browser crash at phase {last_phase} (attempt {_att}/"
                f"{BROWSER_CRASH_MAX_RETRIES + 1}) — auto-retrying from "
                f"checkpoint, no card shown", "WARN")
        elif (_login_interrupt_active()
              and _captured_failure_kind in ("browser_crash", "login_interrupt")):
            # #907: the browser died because --login closed it ON PURPOSE.
            # Pause semantics + an honest card: Retry resumes from the last
            # checkpoint once the login run is done (same resume_from_
            # checkpoint engine as the crash-loop terminal card below); the
            # chat's Stop button remains the way to end the run instead.
            # mark_phase_errored=False (#908): nothing errored — the phase
            # was interrupted, so no phase tile should paint red.
            log(f"Browser closed by the login command at phase {last_phase} — "
                "pausing at checkpoint (no auto-retry)", "WARN")
            emit_event("pipeline_paused", phase=last_phase, reason="login_interrupt")
            # #910: durable local pause marker. --login's run enumeration skips
            # paused runs (a re-run right after the first must not re-list a
            # run that's already parked), and _plan_pipeline_auto_retry's
            # Gate 2 keeps standing down even past the marker's 30-min
            # staleness cap. The resume path re-asserts "ongoing" on entry.
            try:
                update_delivery(status="paused")
            except Exception:
                pass
            # #911: short card. force_mirror overrides the quiet no-mirror rule
            # so the card survives a cold chat-open AND the agent-chat watchdog
            # posts it (both silently missing pre-fix). Distinct alert_id keeps
            # it clear of the generic phase{N}_error dedup ledger.
            # #955 Phase 5B: author via the catalog. intent=crash_login_interrupt
            # → recoverability="blocker" (the user resolves it; never auto-fires)
            # and the [retry_resume] token expands byte-identically to the
            # explicit Retry→resume_from_checkpoint list this dropped. force_mirror
            # + mark_phase_errored=False + the distinct alert_id ride through.
            fail_phase(
                phase=last_phase,
                error="Paused by the login command",
                reason="Login closed the research browser. Tap Retry after "
                       "login — the run resumes from its checkpoint.\n"
                       "Note: the Stop button ends the run instead.",
                agent=None,
                intent="crash_login_interrupt",
                mark_phase_errored=False,
                force_mirror=True,
                alert_id=f"phase{last_phase}_login_interrupt",
            )
        else:
            # Auto-retries exhausted (or a non-recoverable terminal failure):
            # escalate to a user-facing card. Route Retry through the PROVEN
            # resume engine (resume_from_checkpoint → the always-alive
            # start-listener re-enqueues with resume_dir) rather than the
            # retry_phase command — by the time the user clicks, run_pipeline
            # has returned and teardown_firestore_run() has unsubscribed the
            # per-run command listener, so a retry_phase write would dead-end
            # (#725). resume_from_checkpoint is the SAME command the device-/
            # process-restart recovery banner uses, so both recovery paths
            # converge on one engine. Skip → discard (client-side clear),
            # mirroring that banner's Discard.
            # #955 Phase 5B: intent=crash_loop → recoverable (the round-robin
            # firer is dead post-run, so the catalog correctly omits auto_skip —
            # no deadline is ever armed). [retry_resume, discard] expands
            # byte-identically to the explicit Retry/Skip list this dropped.
            fail_phase(
                phase=last_phase,
                error="The run kept hitting errors",
                reason="We tried to recover a couple of times and it didn't "
                       "take. Retry to start again from the last checkpoint, "
                       "or Skip to stop here.",
                agent=None,
                intent="crash_loop",
                # #62: distinct alert_id so a dismissed phase-timeout card
                # (phase{n}_timeout) can't silence this crash-recovery card via
                # the FE dismiss-resurface ledger (keyed on alert_id). Was
                # sharing the generic phase{n}_error slot with _phase_timeout_
                # decision — a timeout-then-crash at the same phase suppressed
                # the crash card. Mirrors crash_login_interrupt's own id above.
                alert_id=f"phase{last_phase}_crash_loop",
            )
    finally:
        # New pause semantics: browser is closed by pause_and_close_browser when pause fires.
        # Here we just ensure cleanup on stop/complete/error — don't double-close if already closed.
        try:
            if _runtime.dispatcher_task and not _runtime.dispatcher_task.done():
                _runtime.dispatcher_task.cancel()
                try:
                    await _runtime.dispatcher_task
                except (asyncio.CancelledError, Exception):
                    pass
        except Exception:
            pass
        try:
            if browser is not None and browser.context is not None:
                await browser.close()
        except Exception as e:
            log(f"Browser final close error: {e}", "WARN")
        # Clear the active-browser ref AFTER close() runs. _schedule_server_
        # exit's child-PID sweep is the safety net for any chromium that
        # outlived close() (e.g. patchright node-driver hang), but the
        # ref-clear here matters for non-exit shutdowns (clean completes,
        # crashes that recover via auto-retry) where the next pipeline
        # creates a fresh Browser instance.
        _active_browser_ref = None
        # #725: wrap reset + teardown defensively. The post-`finally`
        # auto-retry block (below) is now load-bearing for crash recovery —
        # if anything here threw (e.g. _fb_listener.unsubscribe() raising on a
        # half-torn-down channel) the exception would propagate OUT of the
        # finally and skip the auto-retry entirely, orphaning a recoverable
        # crash with no card and no retry. Each cleanup step is isolated so a
        # failure in one can't suppress the others OR the retry.
        try:
            _runtime.reset()
        except Exception as _re:
            log(f"runtime reset error (non-fatal): {_re}", "WARN")
        try:
            teardown_firestore_run()
        except Exception as _te:
            log(f"firestore teardown error (non-fatal): {_te}", "WARN")
        # Clear the active-run global so subsequent device commands
        # (e.g. `clear_local_storage`) don't preserve a stale dir from
        # the just-finished run. Without this reset, the global keeps
        # pointing at the most recently completed run forever — every
        # idle clear would skip that one dir, leaking it indefinitely.
        global _tracks_dir
        _tracks_dir = None

    # Auto-retry from checkpoint if pipeline failed mid-way (#725).
    #
    # The decision is made by _plan_pipeline_auto_retry — the SAME predicate
    # the except handler above consulted to suppress the user-facing card, so
    # "we hid the card" and "we retried" can never disagree. Retry policies it
    # encodes:
    #   - One-shot retry on the initial run (resume_dir is None at entry); the
    #     recursion sets resume_dir, so a second NORMAL failure surfaces the
    #     escalation card instead of looping.
    #   - Browser-crash retry bypasses that gate and fires across phases 0-4
    #     (the legacy `1 < phase` gate excluded the phase-0/1 Chrome-close that
    #     was the reported bug), capped at BROWSER_CRASH_MAX_RETRIES consecutive
    #     attempts via the `_crash_retries` counter threaded through the param.
    #
    # _captured_failure_kind was snapshotted in the except BEFORE the finally's
    # _runtime.reset() wiped last_failure_kind (pre-initialized "" for the
    # clean-exit path).
    _will_retry, _retry_phase, _is_browser_crash = _plan_pipeline_auto_retry(
        queue_dir, resume_dir, _captured_failure_kind or "", _crash_retries)
    if _will_retry:
        _why = "browser-crash" if _is_browser_crash else f"failed at phase {_retry_phase}"
        log(f"Pipeline {_why} — auto-retrying from checkpoint "
            f"(crash_retries={_crash_retries})...", "WARN")
        await asyncio.sleep(5)
        # Forward uid/research_id/run_id so the retry rebinds its Firestore
        # command listener (cancel/config/retry from FE). Without these,
        # setup_firestore_run is skipped and the FE's Stop button writes to a
        # commands subcollection no one is listening to — the BE keeps running
        # orphaned while the FE shows "stopped". `_crash_retries` increments
        # ONLY for browser crashes (a normal one-shot retry keeps it at 0 so a
        # later crash on the resumed run still gets its full budget).
        await run_pipeline_captured(topic=topic, email=email, verbose=verbose,
                           api_key=api_key, resume_dir=str(queue_dir),
                           config=config,
                           run_id=run_id, uid=uid, research_id=research_id,
                           # ⛔ THE RETRY MUST CARRY IT TOO. Attempt 2 arms its
                           # OWN folder, so a dropped writer here would leave the
                           # retry — the attempt most likely to be the one worth
                           # sending — attributable to nobody.
                           _submitted_by=_run_submitted_by(),
                           _crash_retries=(_crash_retries + 1 if _is_browser_crash else _crash_retries))


# ── Per-run log capture wraps the pipeline ─────────────────────
# `run_pipeline` above is untouched; this is the only thing that arms the
# per-run log folder around it. A wrapper rather than a `with` at the top of
# the body for two measured reasons: the body is ~3,800 lines, and it has
# several early returns ABOVE its main try, so a finally-based disarm would
# leak an armed sink on exactly the failures worth capturing.
#
# ⛔ EVERY call site in this file goes through here — pinned by
# `test_no_call_site_bypasses_the_capture`, because a new caller wired to
# `run_pipeline` directly would get no folder and nothing would say so.
async def run_pipeline_captured(*args, **kwargs):
    # ⛔ POPPED, NOT FORWARDED, and it is deliberately not a `run_pipeline`
    # parameter. The pipeline body has no use for the pinned writer — only the
    # capture does — and adding an unused parameter to a 3,800-line signature
    # to carry one diagnostic field is how a signature stops describing its
    # function. It rides the WRAPPER because the wrapper is the consumer.
    #
    # ⚠ A caller that forgets it resolves to `unclaimed`, i.e. attributable to
    # NOBODY. That is the safe direction and it is the point: an unattributed
    # run cannot be put in anyone's support bundle. The two call sites that must
    # pass it are pinned by test, because a silently-dropped kwarg would look
    # exactly like a legacy start doc.
    _claimed = kwargs.pop("_submitted_by", None)
    _rid, _attempt, _submitter = _run_pipeline_capture_key(args, kwargs)
    with _RunLogCapture(research_id=_rid, attempt=_attempt,
                        submitted_by=_submitter, claimed_by=_claimed):
        return await run_pipeline(*args, **kwargs)


def _run_pipeline_capture_key(args, kwargs) -> "tuple[str | None, int, str | None]":
    """(research_id, attempt, TREE uid) for the folder, read off the REAL call.

    ⛔ THE THIRD VALUE IS THE TREE, NOT THE SUBMITTER — renamed here 2026-08-24
    because calling it the submitter is what let it be stamped as one. `uid` says
    whose Firestore tree the run executes in; it is a claim the queue rules never
    check. The rules-pinned writer arrives separately, as the wrapper's
    `_submitted_by`, and `_resolve_run_submitter` needs both.

    Bound through `inspect.signature` against `run_pipeline` itself, so the
    wrapper cannot drift from the parameter list it forwards, and so
    `research_id` is found whether the caller passed it positionally or by
    keyword. ⛔ `run_id` is deliberately not read here — see
    `_run_log_folder_name`.

    ⭐ `uid` rides the same bind for the same reason: the dequeue site passes it
    by keyword and the CLI sites do not pass it at all, so anything less than a
    real signature bind would read None on one of the two shapes and nobody
    would notice — an unattributed run looks exactly like a local one."""
    try:
        bound = _RUN_PIPELINE_SIG.bind(*args, **kwargs)
        bound.apply_defaults()
        return (bound.arguments.get("research_id"),
                int(bound.arguments.get("_crash_retries") or 0),
                bound.arguments.get("uid") or None)
    except Exception:
        return None, 0, None


import inspect as _inspect_for_capture  # noqa: E402
_RUN_PIPELINE_SIG = _inspect_for_capture.signature(run_pipeline)


# ⛔⛔ THE EVENT NAMES ARE MEASURED, NOT ASSUMED. `emit_event("fail_phase")`
# occurs ZERO times in this file — phase failures ride `emit_decision`, whose
# default `event_name` is `pipeline_error`. Mapping the obvious name would have
# captured no failures at all, and absence reads as health.
_TM_EVENT_MAP = {
    "phase_start": tm.Ev.PHASE_START,
    "phase_complete": tm.Ev.PHASE_COMPLETE,
    "phase_skipped": tm.Ev.PHASE_SKIPPED,
    "agent_skipped": tm.Ev.AGENT_SKIPPED,
    "pipeline_paused": tm.Ev.RUN_PAUSED,
    "pipeline_resumed": tm.Ev.RUN_RESUMED,
    "pipeline_stopped": tm.Ev.RUN_STOPPED,
    "pipeline_error": tm.Ev.PIPELINE_ERROR,
}


def _tm_platform(agent) -> "object | None":
    """An agent key to a Platform, failing CLOSED.

    ⛔ `normalize_agent_key` passes through anything it does not recognise, so an
    unmapped name must land on OTHER rather than reach the wire as itself."""
    if not agent:
        return None
    key = str(agent).strip().lower()
    return {
        "chatgpt": tm.Platform.CHATGPT, "claude": tm.Platform.CLAUDE,
        "gemini": tm.Platform.GEMINI, "notebooklm": tm.Platform.NOTEBOOKLM,
        "youtube": tm.Platform.YOUTUBE, "docs": tm.Platform.GOOGLE_DOCS,
        "google_docs": tm.Platform.GOOGLE_DOCS,
    }.get(key, tm.Platform.OTHER)


def _tm_note_event(event_type, phase=None, agent=None) -> None:
    """`emit_event`'s tap into the content-free tier.

    ⛔⛔ FORWARDS A LITERAL TUPLE — the event, the phase number, and an agent
    mapped onto an enum. `**data` is structurally never passed, and
    `test_the_tier1_tap_forwards_a_literal_tuple` pins that set, because
    "temporarily" adding one field is how free text re-enters a content-free
    path."""
    mapped = _TM_EVENT_MAP.get(str(event_type))
    if mapped is None:
        return
    fields = {}
    if isinstance(phase, int):
        fields["phase"] = phase
    platform = _tm_platform(agent)
    if platform is not None:
        fields["platform"] = platform
    rid = None
    try:
        sink = _active_run_sink()
        rid = sink.research_id if sink is not None else None
    except Exception:
        rid = None
    if rid:
        fields["research_id"] = rid
    tm.tm_emit(mapped, **fields)


def _run_sink_note_event(event_type, phase=None, agent=None) -> None:
    """`emit_event`'s tap into the armed run folder. Content-free by shape."""
    sink = _active_run_sink()
    if sink is None:
        return
    try:
        sink.note_event(event_type, phase, agent)
    except Exception:
        pass


# ── Server Mode (Web App API) ────────────────────────────────────────────────

async def _rehydrate_ongoing_for_tree(tree_uid: str, owner_uid: str, rehydrated_rids: "set[str]") -> "tuple[int, int]":
    """Scan users/{tree_uid}/researches for status=="ongoing" runs left mid-
    flight by a previous daemon session and recover each: auto-resume on a
    supervised device (re-enqueue with resume_dir from the on-disk checkpoint),
    else mark `paused_backend_restart` so the FE surfaces a Resume CTA. Returns
    (auto_resumed_count, paused_marked_count).

    `tree_uid` is the user whose research collection is scanned + written —
    the paired OWNER, or (flag-gated, #724 item 3) a SHARER. `owner_uid` is the
    device's paired owner, used ONLY for the legacy users/{owner}/devices
    supervised-flag fallback (the device subcollection lives in the owner tree;
    the modern top-level devices/{deviceId} read works for any tree).
    `rehydrated_rids` accumulates every research_id touched (shared across the
    owner + sharer scans) so the downstream disk-restore block doesn't re-
    enqueue a run already handled here.

    Factored out of run_server's previously owner-only inline rehydration so the
    SAME recovery logic (sibling-lock guard, supervised auto-resume, paused mark)
    runs for sharer trees too. #966: this helper now runs on EVERY worker and
    keys recovery on per-run ownership (_owner_worker_of) — each worker resumes
    the runs it owns; worker 1 additionally marks orphan (out-of-fleet-owner)
    runs paused. The aggregate log line stays in the caller."""
    rehydrated = 0
    orphaned = 0
    # Fleet size (workers are 1..N). Read once per tree scan — it can't change
    # mid-boot. Used to tell an in-fleet sibling's run (leave it for that worker)
    # from an orphan (owner gone; worker 1 marks it paused as a safety net).
    _fleet_size = load_worker_count()
    researches_col = _firebase_db.collection("users").document(tree_uid) \
        .collection("researches")
    # 2026-05-22: dropped "queued" from rehydration. The
    # Firestore on_snapshot listener replays every existing
    # queue doc as ADDED on first attach (research.py:3458)
    # and the FIFO pre-query (3955-3989) handles ordering
    # across all submitters (owner + sharers). Rehydrating
    # queued docs was owner-tree-only AND created a dual-
    # processing race. "ongoing" status is still rehydrated
    # for paused_backend_restart marking + supervised auto-
    # resume — independent code path.
    for status_val in ("ongoing",):
        try:
            snaps = await asyncio.wait_for(
                asyncio.to_thread(
                    lambda sv=status_val: list(
                        _fs_where(researches_col, "status", "==", sv).get()
                    )
                ),
                timeout=15.0,
            )
        except asyncio.TimeoutError:
            log(f"Rehydrate query ({status_val}) timed out after 15s — skipping", "WARN")
            continue
        except Exception as e:
            err_str = str(e)
            if (
                "403" in err_str
                or "PERMISSION_DENIED" in err_str
                or "Missing or insufficient permissions" in err_str
            ):
                # Track D: synth-device-user read of users/{uid}/researches/*
                # is gated by deviceMemberOf. Owner trees pass; a sharer tree
                # passes only if this device's sharedWith[] lists the sharer.
                # On denial, fall back to device-queue + on-disk state.
                log(
                    f"[rehydrate:{status_val}] read denied for tree {tree_uid[:12]}… "
                    f"— relying on device-queue + on-disk state",
                    "DEBUG",
                )
            else:
                log(f"Rehydrate query ({status_val}) failed: {e}", "WARN")
            continue
        for snap in snaps:
            data = snap.to_dict() or {}
            research_id = snap.id
            rehydrated_rids.add(research_id)
            if status_val == "ongoing":
                # Sibling-claim guard (2026-05-22). If a sibling worker on this
                # device holds the lock for this research_id (.worker.N.lock
                # with live PID + fresh started_at), it's actively running the
                # pipeline. Auto-resuming locally would dual-spawn (two
                # browsers, two FE phase streams, two Doc/Email writes). Skip
                # BOTH the auto-resume AND the paused_backend_restart marker —
                # the sibling owns this run and the FE should keep seeing
                # "ongoing".
                _sibling_holders = _scan_sibling_locks_for_research(
                    research_id, WORKER_ID
                )
                if _sibling_holders:
                    h = _sibling_holders[0]
                    _age_s = (int(time.time() * 1000) - h["started_at"]) // 1000
                    log(
                        f"[rehydrate] {research_id[:24]}… already claimed by sibling "
                        f"worker {h['worker_id']} (PID {h['pid']}, started {_age_s}s ago) "
                        f"— skipping auto-resume + paused mark to avoid dual-spawn",
                        "INFO",
                    )
                    continue
                # #728/#966 worker-affinity + per-worker ownership: each worker
                # runs on its OWN browser profile (_profile_dir(WORKER_ID)) = its
                # own logged-in ChatGPT/Gemini/Claude/NotebookLM accounts. Auto-
                # resuming a run a DIFFERENT worker owned would re-open it against
                # THIS worker's (wrong) accounts. So key recovery on the OWNING
                # worker (assignedWorker; None/"" → worker 1 legacy default):
                #   • I own it            → auto-resume (supervised) or mark paused.
                #   • a live sibling owns → LEAVE IT (that worker rehydrates its
                #     own runs at its boot, on the right profile). Marking it paused
                #     here would pop a needless Resume CTA for a run the fleet is
                #     already auto-recovering — the #966 bug this fixes.
                #   • orphan (owner ∉ fleet) → worker 1 alone marks it paused as a
                #     safety net (a Resume re-routes it via claim); other workers
                #     leave it, so no two workers double-write the same doc.
                _assigned = data.get("assignedWorker")
                _owner_worker = _owner_worker_of(_assigned)
                _i_own = (_owner_worker == WORKER_ID)
                if not _i_own:
                    if 1 <= _owner_worker <= _fleet_size:
                        # KNOWN LIMITATION (#966, documented 2026-07-16): if the
                        # owning sibling is PERMANENTLY dead (the daemon-loop marks
                        # a worker≥2 `_dead` after a crash loop / repeated spawn
                        # failure) it never runs its own rehydration, so this run
                        # stays frozen "ongoing" with no Resume CTA until the
                        # operator repairs that worker (a loud `_sup_audit` ERROR
                        # fires on the death; the on-disk checkpoint survives, so
                        # the run self-heals once the worker is back). A worker-1
                        # backstop that marked such runs paused was prototyped and
                        # REVERTED: the only cheap liveness signal (the per-run
                        # worker-lock) is released the moment BE phases finish, so
                        # it can't tell a dead worker from one whose run is simply
                        # in its long FE-owned P4/P5 tail (or tab-closed) — it
                        # would false-mark routine healthy runs, which is worse
                        # than the rare abandonment. A correct backstop needs a
                        # real per-worker liveness heartbeat (not present in
                        # Firestore today); tracked for a follow-up.
                        log(
                            f"[rehydrate] {research_id[:24]}… owned by sibling "
                            f"worker {_owner_worker} (fleet={_fleet_size}) — leaving "
                            f"it for that worker's own rehydration (no paused mark)",
                            "INFO",
                        )
                        continue
                    if WORKER_ID != 1:
                        # Orphan (owner ∉ fleet), but I'm not the marker of record.
                        continue
                    log(
                        f"[rehydrate] {research_id[:24]}… owned by out-of-fleet "
                        f"worker {_owner_worker} (fleet={_fleet_size}) — marking "
                        f"paused_backend_restart (worker-1 safety net; a Resume "
                        f"re-routes it via claim)",
                        "INFO",
                    )
                # Mid-run runs need either auto-resume (supervised device, MY run)
                # or a paused_backend_restart marker so the FE shows a Resume CTA.
                # Browser + CUA state is gone either way, but on-disk checkpoints
                # (documents/*.md + checkpoint.json + delivery.json under
                # queues/{run}/) let detect_resume_phase() skip completed phases.
                # Only a run I OWN needs the supervised read (an orphan is marked
                # paused regardless — I can't re-open it on my profile).
                is_supervised = False
                if _i_own:
                    device_id = data.get("deviceId") or ""
                    if device_id:
                        # Track D: top-level devices/{deviceId} is the canonical
                        # home; synth user CAN read its own doc. Legacy
                        # users/{ownerUid}/devices/{deviceId} read 403s under synth
                        # auth, so try modern first and only fall back on miss.
                        try:
                            dev_snap = _firebase_db.collection("devices") \
                                .document(device_id).get()
                            if dev_snap.exists:
                                is_supervised = bool(
                                    (dev_snap.to_dict() or {})
                                    .get("supervised", False))
                        except Exception as _de:
                            log(f"Rehydrate: top-level device read failed for {research_id[:24]}…: {_de}", "WARN")
                        if not is_supervised:
                            try:
                                dev_snap = _firebase_db.collection("users") \
                                    .document(owner_uid) \
                                    .collection("devices") \
                                    .document(device_id).get()
                                if dev_snap.exists:
                                    is_supervised = bool(
                                        (dev_snap.to_dict() or {})
                                        .get("supervised", False))
                            except Exception:
                                # Synth user is denied on user-tree devices
                                # subcollection — expected.
                                pass

                auto_resumed = False
                if _i_own and is_supervised:
                    run_id = data.get("backendRunId") or ""
                    if run_id:
                        queue_dir = Path(__file__).parent / "queues" / run_id
                        # Only auto-resume if the on-disk artifacts are intact
                        # and the run wasn't terminally stopped (.stop sentinel).
                        if queue_dir.exists() and not (queue_dir / ".stop").exists():
                            cp = load_checkpoint(queue_dir)
                            topic = (cp or {}).get("topic", "") or data.get("topic", "")
                            cfg = dict(data.get("pipelineConfig") or {})
                            if "skippedPhases" in cfg and "skipPhases" not in cfg:
                                cfg["skipPhases"] = cfg.pop("skippedPhases")
                            if topic:
                                # Clear any stale .pause signal so the resumed
                                # run drains immediately.
                                p_signal = queue_dir / ".pause"
                                if p_signal.exists():
                                    try: p_signal.unlink()
                                    except Exception: pass
                                # DGOPS-9508: reach the in-memory queue via
                                # _QUEUE_STATE["queue_ref"] — assigned unconditionally
                                # right after `_job_queue = asyncio.Queue()` near the
                                # top of run_server, so it is populated before every
                                # rehydrate call site — NOT the bare `_job_queue`.
                                # (No line number on purpose: the previous note here
                                # cited one that had drifted ~70 lines.)
                                # This function is at MODULE scope while `_job_queue`
                                # is a LOCAL of run_server, so the bare name raised
                                # NameError here — the SAME bug already fixed at
                                # research.py:~5405 for the device-cmd listener, and
                                # worse in this spot: the caller's `except Exception`
                                # logs one "Queue rehydration failed" WARN and abandons
                                # the whole block, so neither the auto-resume nor the
                                # paused_backend_restart fallback fired for ANY run.
                                # Masked from the linter by `from prompts import *`,
                                # which downgrades every unresolved global to F405.
                                _qref = _QUEUE_STATE.get("queue_ref")
                                if _qref is None:
                                    log("Rehydrate: no in-memory queue_ref yet (boot race) — "
                                        f"cannot auto-resume {research_id[:24]}…, falling through "
                                        "to paused_backend_restart", "WARN")
                                elif _safe_enqueue(_qref, {
                                    "topic": topic,
                                    "email": "",  # delivery prefs are on disk in delivery.json
                                    "config": cfg,
                                    "run_id": run_id,
                                    "resume_dir": str(queue_dir),
                                    "uid": tree_uid,
                                    "research_id": research_id,
                                    # ⛔ NO QUEUE DOC EXISTS HERE — it was deleted
                                    # when the run was first claimed, so the only
                                    # writer still on record is the research doc's
                                    # own. It sits in the tree being scanned, so it
                                    # attributes an owner's or a sharer's own run
                                    # correctly and refuses to attribute anything
                                    # else. Absent on an old doc ⇒ `unclaimed`,
                                    # i.e. sendable from the terminal but not from
                                    # the app — the fail-closed direction.
                                    "submitted_by": str(
                                        data.get("submittedBy") or "").strip(),
                                }, source="rehydrate-supervised-auto-resume"):
                                    rehydrated += 1
                                    auto_resumed = True
                                    log(f"Rehydrate: auto-resumed {research_id[:24]}… on supervised device")

                if not auto_resumed:
                    # A run I OWN that couldn't auto-resume (unsupervised, or
                    # supervised-but-no-artifacts: queue_dir missing, run_id
                    # absent, .stop sentinel) OR an orphan run worker 1 is marking
                    # as a safety net. Mark paused_backend_restart so the FE
                    # recovery banner fires.
                    # #720: route through _update_research_doc so it gets
                    # _be_payload's deviceId injection AND the gRPC 403 self-heal
                    # — this fires at worker boot, the exact window a stale/
                    # claim-propagation-race token would 403 and the FE Resume
                    # CTA never fire.
                    if _update_research_doc(tree_uid, research_id, {
                        "status": "paused_backend_restart",
                        "summary": "Backend restarted mid-run — hit Resume to pick up from the last checkpoint.",
                    }):
                        orphaned += 1
                    else:
                        log(f"Rehydrate: mark paused_backend_restart failed for {research_id}", "WARN")
            # queued-status branch removed 2026-05-22 — the on_snapshot
            # listener handles queued docs.
    return (rehydrated, orphaned)


async def _reconcile_dead_worker_runs(tree_uid: str, dead_ids: "set[int]") -> int:
    """Worker-1: for each "ongoing" run in `tree_uid` owned by a worker the
    supervisor declared PERMANENTLY dead (`dead_ids` from _read_dead_worker_ids),
    mark it paused_backend_restart so the FE surfaces a Resume CTA. The dead
    worker never reboots (respawn was stopped), so nothing else recovers its runs.

    MARK-ONLY — never auto-resume: the run belongs to another worker's browser
    profile (its own logged-in accounts), which worker-1 can't drive. A Resume
    re-routes the run via the queue claim onto whichever LIVE worker wins it
    (which re-stamps assignedWorker to itself). Returns the number marked.

    Guards, ALL required before marking:
      • status still exactly "ongoing" (the query filter — a completed/paused/
        stopped run isn't returned, so this is idempotent + never re-marks);
      • owner ∈ dead_ids;
      • no LIVE sibling holds the run's lock (a re-claim — mirrors the rehydrate
        sibling-lock guard; a dead worker's stale lock fails the PID-alive check);
      • the BE has NOT handed off to the autonomous Cloud-Run P4/P5 tail
        (delivery.json status=="completed" — research.status deliberately stays
        "ongoing" through that tail, which Cloud Run finishes without any worker,
        so marking it paused would pop a false Resume on a healthy run)."""
    if not dead_ids or not _firebase_db:
        return 0
    researches_col = _firebase_db.collection("users").document(tree_uid) \
        .collection("researches")
    try:
        snaps = await asyncio.wait_for(
            asyncio.to_thread(
                lambda: list(_fs_where(researches_col, "status", "==", "ongoing").get())
            ),
            timeout=15.0,
        )
    except asyncio.TimeoutError:
        log("[dead-worker-reconcile] ongoing-query timed out after 15s — skipping", "WARN")
        return 0
    except Exception as _qe:
        log(f"[dead-worker-reconcile] ongoing-query failed ({_qe}) — skipping", "WARN")
        return 0
    marked = 0
    for snap in snaps:
        data = snap.to_dict() or {}
        research_id = snap.id
        owner = _owner_worker_of(data.get("assignedWorker"))
        if owner not in dead_ids:
            continue
        # A LIVE worker holding the lock means the run was re-claimed and is
        # actively running — leave it (a dead worker's stale lock is filtered by
        # the scanner's PID-alive guard, so it never blocks here).
        if _scan_sibling_locks_for_research(research_id, WORKER_ID):
            continue
        # BE-tail guard: once delivery.json flips to "completed" the BE has handed
        # P4/P5 to an autonomous Cloud-Run task that finishes the run on its own
        # (research.status stays "ongoing" until FE-P5 flips it). Unreadable /
        # missing delivery.json ⇒ treat as BE-incomplete ⇒ mark (recoverable from
        # the on-disk checkpoint).
        run_id = data.get("backendRunId") or ""
        if run_id:
            _dpath = Path(__file__).parent / "queues" / run_id / "delivery.json"
            try:
                if _dpath.exists() and json.loads(
                        _dpath.read_text(encoding="utf-8")).get("status") == "completed":
                    continue
            except Exception:
                pass
        if _update_research_doc(tree_uid, research_id, {
            "status": "paused_backend_restart",
            "summary": "Backend restarted mid-run — hit Resume to pick up from the last checkpoint.",
        }):
            marked += 1
            log(f"[dead-worker-reconcile] {research_id[:24]}… owned by dead worker "
                f"{owner} — marked paused_backend_restart")
        else:
            log(f"[dead-worker-reconcile] mark failed for {research_id[:24]}…", "WARN")
    return marked


# How long a graceful shutdown gets after a stop signal before it is forced.
# Long enough for uvicorn to drain and the pipeline to emit its stopped event,
# short enough that nobody reaches for `kill -9` and orphans a browser.
_STOP_GRACE_S = 8.0

# Which stop signal arrived, if any — read after the server loop returns so the
# conventional 128+signum exit code survives the graceful path.
_server_stop_signal = {"n": None}

# How often the stop handlers are re-asserted, for as long as the server runs.
#
# ⭐ 2026-08-11. Installing them once is not enough. A live serve that had been
# up for four hours and had finished a run was measured in both directions: a
# direct SIGTERM logged, drained and exited in ~3s, while a direct SIGINT to the
# same process did nothing at all — no line, no shutdown, still answering HTTP on
# its port two milliseconds later. Same handler, same install, same loop. So the
# handler was never wrong; SIGINT's DISPOSITION had been reset out from under it
# somewhere in the run, and it stayed reset for the rest of the process's life.
#
# Nothing in this repo, and nothing in any of its Python dependencies, sets
# SIGINT to SIG_IGN — so whatever does it is native and cannot be reached from
# here. Re-asserting is what keeps the banner's "Stop: Ctrl+C" true regardless.
# It does not cure the cause; it bounds the damage to one period, and the drift
# line it prints is what will finally name the culprit.
# ⭐ 2026-08-17: 5.0 → 1.0. This period IS the worst case a user experiences as
# "I pressed Ctrl+C and nothing happened" — the repair, and the delivery of a
# press that was already swallowed, both wait for the next pass. Five seconds of
# that is indistinguishable from broken, which is precisely the report. The pass
# costs one sigaction and two mask reads, so once a second is free.
_STOP_REARM_S = 1.0


def _stop_handler_description(sig_mod, current) -> str:
    """Name whatever `getsignal` handed back, for the drift log line.

    The entire value of that line is naming the culprit the next time this
    happens, so the cases have to stay distinguishable: "being discarded" and
    "back to the OS default" are different bugs with different suspects.

    ⭐ `None` is the interesting one. `signal.getsignal` returns it when the
    disposition was set from OUTSIDE Python — i.e. by native code — which is
    precisely the shape of the failure this was written for."""
    _absent = object()          # never equal to `current`, so a signal module
                                # missing one of these can't match by accident
    if current is getattr(sig_mod, "SIG_IGN", _absent):
        return "SIG_IGN — the signal was being discarded"
    if current is getattr(sig_mod, "SIG_DFL", _absent):
        return "SIG_DFL — back to the OS default"
    if current is getattr(sig_mod, "default_int_handler", _absent):
        return "default_int_handler — Python's own"
    if current is None:
        return "not set from Python — installed by native code"
    return getattr(current, "__qualname__", None) or repr(current)


def _assert_stop_handlers(sig_mod, signums, handler, reported, announce=True):
    """(Re-)install `handler` for each of `signums`; say so if it had drifted.

    ⭐ The install is UNCONDITIONAL, and that is the fix. `getsignal` reports
    Python's own RECORD of the handler, and when the disposition is changed
    below that record the record still reads as ours — that is what a `None`
    return means. So a check-then-install sees "already correct", repairs
    nothing, and leaves Ctrl+C dead. The comparison here only decides whether
    to LOG; the install happens either way.

    `reported` carries the once-per-signal guard between calls, so a permanent
    drift costs one line rather than one every few seconds. `announce` is off
    for the first install, where the handler being someone else's is not drift
    — it is uvicorn's, exactly as expected.

    Returns the names actually installed."""
    installed = []
    for _s in signums:
        try:
            name = sig_mod.Signals(_s).name
        except Exception:
            name = str(_s)
        try:
            current = sig_mod.getsignal(_s)
        except Exception:
            current = None
        if announce and current is not handler and ("drift", _s) not in reported:
            reported.add(("drift", _s))
            log(f"[serve] {name} was no longer ours "
                f"({_stop_handler_description(sig_mod, current)}) — restoring it. "
                f"Stop was being ignored until now.", "WARN")
        try:
            sig_mod.signal(_s, handler)
            installed.append(name)
        except Exception as _se:            # non-main thread, or a platform
            if ("fail", _s) not in reported:
                reported.add(("fail", _s))
                # ⚠ WARN, not DEBUG. This being a whisper is why the failure
                # survived three attempts: there was never a line to find.
                log(f"[serve] could not arm {name}: {_se}", "WARN")
    return installed


def _signal_name(sig_mod, signum):
    try:
        return sig_mod.Signals(signum).name
    except Exception:
        return str(signum)


def _unblock_stop_signals(sig_mod, signums, reported):
    """Make sure a stop signal can ARRIVE, not merely be handled once it does.

    ⛔⛔ 2026-08-17 — THE GAP THE RE-ASSERT LOOP CANNOT REACH. Re-installing a
    handler is powerless against a BLOCKED signal. A blocked SIGINT is not
    discarded: it sits PENDING indefinitely, so the press is swallowed while
    `getsignal` still reports our handler and every re-assert pass reports
    success. From outside, that is indistinguishable from the disposition reset
    this loop was built for — no line, no shutdown, and a process that stays
    perfectly healthy afterwards. The owner hit exactly that on an idle serve:
    three presses, no line of any kind, and the same process went on to claim and
    run a job a minute later.

    Unblocking a signal that is already pending delivers it IMMEDIATELY, so a
    press that was swallowed still stops the server — one re-assert period late
    rather than never.

    ⛔ Called AFTER the handler is installed, never before. Unblocking first would
    deliver a pending signal to whatever the disposition had drifted to, which in
    the SIG_DFL case is an ungraceful kill of the very process we are trying to
    shut down cleanly.

    Returns the names it had to unblock (empty on Windows, which has no mask)."""
    freed = []
    try:
        # Blocking the empty set is the documented way to READ the mask.
        blocked = sig_mod.pthread_sigmask(sig_mod.SIG_BLOCK, [])
    except Exception:
        return freed                        # Windows, or a stripped signal module
    stuck = [_s for _s in signums if _s in blocked]
    if not stuck:
        return freed
    try:
        pending = sig_mod.sigpending()
    except Exception:
        pending = set()
    for _s in stuck:
        name = _signal_name(sig_mod, _s)
        freed.append(name)
        if ("blocked", _s) not in reported:
            reported.add(("blocked", _s))
            # ⭐ The line that names this class. "Blocked" and "blocked AND
            # already pending" are different facts: the second one means a press
            # really did happen and was sitting in the queue unheard.
            _waiting = (" and already pending — a stop had been pressed and "
                        "swallowed") if _s in pending else ""
            log(f"[serve] {name} was BLOCKED{_waiting} — unblocking it. "
                f"Stop could not arrive until now.", "WARN")
    try:
        sig_mod.pthread_sigmask(sig_mod.SIG_UNBLOCK, stuck)
    except Exception as _me:
        if ("unblock", tuple(stuck)) not in reported:
            reported.add(("unblock", tuple(stuck)))
            log(f"[serve] could not unblock {', '.join(freed)}: {_me}", "WARN")
    return freed


def _log_blocked_stop_signals_at(where, sig_mod=None):
    """Report — and do not touch — any stop signal that is already blocked.

    ⭐ Deliberately does NOT repair. Repairing here would erase the evidence the
    arm-time pass exists to collect: if this says "clean" and the arm-time pass
    says "blocked", the block was installed by our own startup, and if BOTH say
    blocked it was inherited from whatever launched us. Naming that is the whole
    point, and the arm-time pass fixes it either way a second later.

    Returns the names found blocked (for tests; the caller only wants the line).
    """
    import signal as _sig
    sig_mod = sig_mod or _sig
    try:
        blocked = sig_mod.pthread_sigmask(sig_mod.SIG_BLOCK, [])
    except Exception:
        return []                            # Windows: no mask to inspect
    names = [_signal_name(sig_mod, _s)
             for _s in (sig_mod.SIGINT, sig_mod.SIGTERM) if _s in blocked]
    if names:
        log(f"[serve] {', '.join(names)} already blocked at {where} — inherited "
            f"from whatever started this process, not installed by it.", "WARN")
    return names


def _hold_stop_signals(sig_mod, signums, handler, reported, announce=True):
    """One pass of holding the stop path open, end to end.

    Two independent things have to be true for Ctrl+C to work, and the loop had
    only ever asserted one of them: the signal must be OURS when it arrives
    (handler installed, unconditionally) AND it must be able to arrive at all
    (not blocked). Order is load-bearing — see `_unblock_stop_signals`.

    Returns (installed_names, unblocked_names)."""
    installed = _assert_stop_handlers(sig_mod, signums, handler, reported,
                                      announce=announce)
    freed = _unblock_stop_signals(sig_mod, signums, reported)
    return installed, freed


async def _arm_stop_signals(server, port):
    """Make Ctrl+C stop the server, say so, and never hang.

    ⭐ 2026-08-10. The banner has always promised "Stop: Ctrl+C" and the code
    relied entirely on uvicorn's own handler to deliver it. On the owner's machine
    that promise failed repeatedly — Ctrl+C did nothing, and neither did a direct
    SIGINT — while the identical build honoured a real Ctrl+C in every environment
    it could be reproduced in (both under a controlling tty and without one, with
    and without the logging pipeline, on this build and on the one before it).

    The cause was never found. What WAS established is that the failure is silent:
    nothing anywhere printed a single line when the signal was sent, so there was
    no way to tell "the signal never arrived" from "it arrived and something
    swallowed it". A stop path with no evidence is unfixable by anyone, which is
    why this exists whether or not it turns out to be the cure.

    ⭐ 2026-08-11 — THE CAUSE, MEASURED. The evidence line above did its job. A
    serve that had been up four hours and had finished a run was probed in both
    directions: SIGTERM logged, drained and exited in ~3s, and SIGINT to the same
    process did nothing whatsoever — no line, no shutdown, still serving HTTP two
    milliseconds later, and no backstop thread, so the handler had not run at all.
    Identical handler, one install, one loop. That rules out the terminal (the
    probe never touched it), delivery (unblocked and not pending) and uvicorn's
    own handler (it never saw a stop either — the listening socket stayed open).
    What is left is that SIGINT's DISPOSITION was reset during the run and stayed
    reset. Nothing in this repo or its Python dependencies does that, so the
    culprit is native and out of reach from here.

    Four things now, in order of how much they matter:

    1. It LOGS on arrival, before doing anything else. That single line settles the
       question the next time this happens.
    2. It sets the same flag uvicorn's handler sets, so the ordinary graceful
       shutdown still runs and nothing about the existing path changes.
    3. It backstops. If the graceful shutdown has not finished within
       `_STOP_GRACE_S`, the process is reaped and exited through the same helper
       the Stop button uses — which kills the patchright driver and Chromium
       first, so a forced stop cannot leave the orphans that hold the profile
       lock. A second Ctrl+C skips the wait entirely, which is what everyone
       expects a second press to do.
    4. It HOLDS. The handlers are re-asserted every `_STOP_REARM_S` for the life
       of the server, unconditionally, and the first time one is found to have
       drifted it says so and names what it drifted to. That is what makes the
       banner's promise survive whatever the run does, and what will identify
       the native caller doing it.
    5. ⛔⛔ 2026-08-17 — it also keeps the signal DELIVERABLE, which items 1-4
       cannot. The owner pressed Ctrl+C three times on an idle serve and got no
       line of any kind, and the same process went on to claim and run a job a
       minute later — so the handler had not run and nothing was wedged. A
       handler that is installed and a signal that can arrive are two different
       properties, and a BLOCKED signal fails the second one while passing every
       check the first four make: it is not discarded but held PENDING, so
       `getsignal` still reports us and every re-assert pass reports success.
       `_unblock_stop_signals` closes that, and unblocking a pending signal
       delivers it at once — so a swallowed press still stops the server, one
       re-assert period late rather than never.
       ⚠ Whether that is what happened to the owner is NOT yet measured; the
       process was gone before it could be probed. This is the one mechanism the
       loop structurally could not repair, and either way it now prints the
       truth the next time.

    Installed AFTER uvicorn is serving, deliberately: uvicorn assigns its handlers
    when `serve()` begins, so anything installed earlier is simply overwritten.
    Waiting on `server.started` makes that ordering deterministic rather than a
    sleep-and-hope."""
    import signal as _sig
    import threading as _th

    for _ in range(2400):                      # ~120s ceiling; startup is ~2s
        if getattr(server, "started", False):
            break
        await asyncio.sleep(0.05)

    _pressed = {"n": 0}

    def _on_stop(signum, _frame):
        _pressed["n"] += 1
        # Remember WHICH signal, so the process can still exit 128+signum below.
        # Letting uvicorn's own handler run used to yield 130 on Ctrl+C; handling
        # it here made the shutdown graceful and the exit code 0, which is a
        # different statement to anything watching (a supervisor keyed on
        # SuccessfulExit reads 0 as "it meant to stop"). Behaviour that was not
        # asked to change does not change.
        _server_stop_signal["n"] = signum
        try:
            name = _sig.Signals(signum).name
        except Exception:
            name = str(signum)
        if _pressed["n"] >= 2:
            log(f"[serve] {name} again — exiting now", "WARN")
            _schedule_server_exit(f"signal-{name}-immediate", delay_sec=0)
            return
        log(f"[serve] stop requested ({name}) — shutting down", "INFO")
        server.should_exit = True
        # Daemon thread: this runs INSIDE a signal handler, where doing real work
        # is how you deadlock. It only waits and then calls the same exit helper
        # the Stop button uses.
        def _backstop():
            for _ in range(int(_STOP_GRACE_S * 10)):
                if getattr(server, "force_exit", False) or _pressed["n"] >= 2:
                    return
                time.sleep(0.1)
            log(f"[serve] graceful shutdown did not finish in {_STOP_GRACE_S:.0f}s "
                f"— forcing exit", "WARN")
            _schedule_server_exit(f"signal-{name}-forced", delay_sec=0)
        _th.Thread(target=_backstop, daemon=True,
                   name="serve-stop-backstop").start()

    _signums = (_sig.SIGINT, _sig.SIGTERM)
    _reported = set()
    # First install: whatever is there now is uvicorn's, which is expected and
    # not drift, so it is not announced. The mask IS checked from the very first
    # pass — a signal blocked before we ever got here is blocked for the life of
    # the process otherwise.
    installed, freed = _hold_stop_signals(_sig, _signums, _on_stop, _reported,
                                          announce=False)
    if installed:
        log(f"[serve] stop signals armed ({', '.join(installed)}) on :{port}", "DEBUG")
    if freed:
        log(f"[serve] {', '.join(freed)} had to be unblocked at arm time", "WARN")

    # Then hold them, for the life of the server. See `_STOP_REARM_S`: one
    # install was measured to be insufficient — SIGINT's disposition was reset
    # underneath it mid-run and stayed reset.
    #
    # ⛔ `_on_stop` is built ONCE, above, and re-installed as the SAME object.
    # Rebuilding it per pass would hand every re-assert a fresh `_pressed`
    # counter, and a second Ctrl+C would never reach the immediate-exit branch —
    # it would keep re-entering the graceful path that the second press exists
    # to escape. Re-arming must restore the stop path, not reset its state.
    while True:
        await asyncio.sleep(_STOP_REARM_S)
        _hold_stop_signals(_sig, _signums, _on_stop, _reported)


async def run_server(port=8000):
    """Start FastAPI server for real-time web app streaming."""
    from fastapi import FastAPI
    from fastapi.responses import JSONResponse
    from fastapi.middleware.cors import CORSMiddleware
    import uvicorn

    # Reset module-level exit-scheduled flag. Daemon-respawn already gives
    # us a fresh process (so the flag resets naturally), but if the same
    # process is somehow re-entering run_server (test harness, future
    # in-process restarts), we want a clean slate so a new stop can
    # actually schedule its exit.
    global _exit_scheduled
    _exit_scheduled = False

    app = FastAPI(title="Research Pipeline API")
    app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])

    queues_root = Path(__file__).parent / "queues"

    # ── Startup sweep: purge stale failed runs older than 7 days ──
    # Without this, queues/ piles up forever with partial MDs, partial
    # audio, and orphaned Firestore docs. We only sweep entries whose
    # delivery.json status is NOT in a clean-parked set, and only if the
    # dir hasn't been touched in > 7 days so active debugging sessions
    # aren't wiped out. (tracks/ removed 2026-04-29 — was the only other
    # local artifact; nothing to sweep there anymore.)
    try:
        now_ts = time.time()
        STALE_SECONDS = 7 * 86400
        KEEP_STATUSES = {"completed", "paused", "paused_backend_restart"}
        swept = 0
        if queues_root.exists():
            for d in queues_root.iterdir():
                if not d.is_dir():
                    continue
                delivery_path = d / "delivery.json"
                status = ""
                try:
                    if delivery_path.exists():
                        status = json.loads(delivery_path.read_text(encoding="utf-8")).get("status", "")
                except Exception:
                    pass
                if status in KEEP_STATUSES:
                    continue
                try:
                    mtime = d.stat().st_mtime
                except Exception:
                    continue
                if (now_ts - mtime) < STALE_SECONDS:
                    continue
                # Cascade Firestore cleanup if owner.json is present
                owner_path = d / "owner.json"
                if owner_path.exists() and _firebase_db:
                    try:
                        owner = json.loads(owner_path.read_text(encoding="utf-8"))
                        uid, rid = owner.get("uid"), owner.get("researchId")
                        if uid and rid:
                            ref = _firebase_db.collection("users").document(uid) \
                                .collection("researches").document(rid)
                            for sub in ("documents", "audios", "messages",
                                        "pipeline_events", "commands"):
                                try:
                                    for sd in ref.collection(sub).stream():
                                        try:
                                            # #720: `commands` deletes are
                                            # deviceMemberOf-gated (heal-eligible on a
                                            # stale token); the other four + the doc
                                            # are OWNER-ONLY in rules (synth user denied
                                            # by design), so leave those bare — wrapping
                                            # them would false-fire the structural latch.
                                            if sub == "commands":
                                                _grpc_write_with_heal(
                                                    lambda sd=sd: sd.reference.delete(),
                                                    what="cascade-sweep cmd delete")
                                            else:
                                                sd.reference.delete()
                                        except Exception: pass
                                except Exception: pass
                            try: ref.delete()
                            except Exception: pass
                    except Exception: pass
                # Nuke local queue dir.
                import shutil as _shutil
                try: _shutil.rmtree(d)
                except Exception: pass
                swept += 1
        if swept:
            log(f"[startup-sweep] purged {swept} stale run(s) older than 7 days", "INFO")
    except Exception as _se:
        log(f"[startup-sweep] failed: {_se}", "WARN")

    # ── Periodic orphan sweep ──
    # Complements the startup time-based sweep above. This one is
    # existence-based: it iterates queues/, reads each owner.json, and
    # nukes the local dirs IF the corresponding Firestore research doc
    # has been deleted (e.g. by the FE deleteResearch cascade). Catches
    # user-initiated deletes within ~5 min instead of waiting 7 days.
    # Race protection:
    #   1) Skip dirs younger than 5 min so a fresh run mid-creation is
    #      never killed before delivery.json/owner.json are written.
    #   2) Re-verify Firestore existence after a 250ms jitter just before
    #      rmtree, in case the doc was created in the same window.
    #   3) Defensive defaults: missing delivery.json/owner.json/status,
    #      Firestore unreachable, or unknown status all SKIP delete.
    ORPHAN_SWEEP_INTERVAL_SEC = 300
    ORPHAN_SWEEP_MIN_AGE_SEC = 300
    ORPHAN_SWEEP_IN_FLIGHT_STATUSES = {"ongoing", "queued"}

    # Its one line is a verdict about OTHER runs' queue directories
    # ("purged N orphan(s)") — measured landing inside two of the five run
    # folders on this machine, describing neither of them.
    @_machine_logged
    async def _orphan_sweep_loop():
        import shutil as _shutil
        while True:
            try:
                await asyncio.sleep(ORPHAN_SWEEP_INTERVAL_SEC)
                if not _firebase_db or not queues_root.exists():
                    continue
                now_ts_inner = time.time()
                swept_n = 0
                for d in queues_root.iterdir():
                    if not d.is_dir():
                        continue
                    try:
                        if (now_ts_inner - d.stat().st_mtime) < ORPHAN_SWEEP_MIN_AGE_SEC:
                            continue
                    except Exception:
                        continue
                    delivery_path = d / "delivery.json"
                    if not delivery_path.exists():
                        continue
                    try:
                        status = json.loads(delivery_path.read_text(encoding="utf-8")).get("status", "")
                    except Exception:
                        continue
                    if not status or status in ORPHAN_SWEEP_IN_FLIGHT_STATUSES:
                        continue
                    owner_path = d / "owner.json"
                    if not owner_path.exists():
                        continue
                    try:
                        owner = json.loads(owner_path.read_text(encoding="utf-8"))
                        uid, rid = owner.get("uid"), owner.get("researchId")
                    except Exception:
                        continue
                    if not uid or not rid:
                        continue
                    try:
                        ref = _firebase_db.collection("users").document(uid) \
                            .collection("researches").document(rid)
                        if ref.get().exists:
                            continue
                    except Exception:
                        continue
                    await asyncio.sleep(0.25)
                    try:
                        if ref.get().exists:
                            continue
                    except Exception:
                        continue
                    try:
                        _shutil.rmtree(d)
                    except Exception as _e:
                        log(f"[orphan-sweep] rmtree {d.name} failed: {_e}", "WARN")
                        continue
                    swept_n += 1
                if swept_n:
                    log(f"[orphan-sweep] purged {swept_n} orphan(s) (Firestore research doc missing)", "INFO")
            except asyncio.CancelledError:
                return
            except Exception as _e:
                log(f"[orphan-sweep] iteration failed: {_e}", "WARN")

    # ── #64: periodic permanently-dead-worker reconcile ──
    # A worker (id>=2) can crash-loop to death AFTER worker-1 has booted; the
    # supervisor drops an on-disk dead-marker and stops respawning it, so its
    # owned "ongoing" runs would freeze with no Resume CTA. Worker-1 (always
    # alive — k=1 is never marked dead) re-scans on an interval and marks those
    # abandoned runs paused_backend_restart (the FE then shows a Resume banner).
    # This periodic loop is the SOLE trigger (no boot pass): on a routine daemon
    # restart every worker retracts its own marker early at boot, well before the
    # first tick, so a healthy worker is never briefly mistaken for dead. ~90s
    # latency is fine for a rare abandonment. Worker-1 only; mark-only.
    DEAD_WORKER_RECONCILE_INTERVAL_SEC = 90

    # Reconciles runs owned by OTHER workers — by definition never this one's.
    @_machine_logged
    async def _dead_worker_reconcile_loop():
        while True:
            try:
                await asyncio.sleep(DEAD_WORKER_RECONCILE_INTERVAL_SEC)
                if not _firebase_db:
                    continue
                _dead_ids = _read_dead_worker_ids()
                if not _dead_ids:
                    continue
                _uid = load_paired_uid()
                if not _uid:
                    continue
                _n = await _reconcile_dead_worker_runs(_uid, _dead_ids)
                if _n:
                    log(f"[dead-worker-reconcile] marked {_n} abandoned run(s) "
                        f"paused_backend_restart (dead workers: {sorted(_dead_ids)})")
            except asyncio.CancelledError:
                return
            except Exception as _e:
                log(f"[dead-worker-reconcile] iteration failed: {_e}", "WARN")

    @app.get("/api/runs")
    async def list_runs():
        """List all pipeline runs — returns frontend-compatible Research objects."""
        runs = []
        if queues_root.exists():
            for d in sorted(queues_root.iterdir(), reverse=True):
                if not d.is_dir():
                    continue
                meta_path = d / "meta.json"
                if meta_path.exists():
                    try:
                        runs.append(json.loads(meta_path.read_text(encoding="utf-8")))
                        continue
                    except Exception:
                        pass
                # Fallback: build from checkpoint
                cp = load_checkpoint(d)
                has_delivery = (d / "delivery.json").exists()
                phase = cp.get("last_completed_phase", 0) if cp else 0
                runs.append({
                    "id": d.name,
                    "title": cp.get("topic", d.name) if cp else d.name,
                    "topic": cp.get("topic", d.name) if cp else d.name,
                    "status": "completed" if has_delivery else "ongoing",
                    "phase": max(0, phase - 1),
                    "platforms": ["chatgpt", "gemini", "claude"],
                    "documents": [], "audios": [],
                    "createdAt": int(d.stat().st_ctime * 1000),
                    "updatedAt": int(d.stat().st_mtime * 1000),
                })
        return runs

    @app.get("/api/runs/{run_id}")
    async def get_run(run_id: str):
        """Get full details — meta.json + delivery + checkpoint + pipeline_state."""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        # Load meta (frontend-compatible Research object)
        meta_path = queue / "meta.json"
        meta = json.loads(meta_path.read_text(encoding="utf-8")) if meta_path.exists() else None
        cp = load_checkpoint(queue)
        delivery_file = queue / "delivery.json"
        delivery = json.loads(delivery_file.read_text(encoding="utf-8")) if delivery_file.exists() else None
        # Pipeline state: stopped is terminal, paused is resumable
        pipeline_state = "running"
        if (queue / ".stop").exists():
            pipeline_state = "stopped"
        elif (queue / ".pause").exists():
            pipeline_state = "paused"
        elif delivery and delivery.get("status") == "completed":
            pipeline_state = "completed"
        return {"meta": meta, "checkpoint": cp, "delivery": delivery, "pipeline_state": pipeline_state}

    # 2026-04-29: GET /api/runs/{id}/events + WS /ws/{run_id} +
    # _find_events_file removed. Both read events.jsonl from disk, but
    # writes were dropped (Firestore pipeline_events is the FE transport).
    # No live FE consumers — verified zero callsites in the FE source.

    @app.post("/api/runs/{run_id}/stop")
    async def stop_run(run_id: str):
        """STOP: terminate pipeline, save partial results, mark as stopped (not resumable).

        Also schedules a hard process exit 3s later — matches the Firestore
        command-listener path so that hitting Stop reliably ends the backend
        no matter which transport got there first.
        """
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        (queue / ".stop").write_text("stop", encoding="utf-8")
        p = queue / ".pause"
        if p.exists():
            p.unlink()
        # Set asyncio event for immediate response, then schedule the backend
        # exit via the shared helper. Idempotent if the Firestore-command path
        # already fired — we won't spawn duplicate exit threads.
        _controls.request_stop()
        # 2026-05-21: schedule graceful browser teardown inline before the
        # exit timer fires — without this, mid-Phase awaits keep the
        # patchright session open until os._exit reaps the process tree.
        # We're already in an async handler so asyncio.create_task works
        # directly (no call_soon_threadsafe needed).
        _b = _active_browser_ref
        if _b is not None:
            try:
                asyncio.create_task(_b.close())
            except Exception as _ce:
                log(f"[http-stop] inline browser.close schedule failed: {_ce}", "WARN")
        _schedule_server_exit("http-endpoint")
        return {"status": "stop_requested", "id": run_id}

    @app.post("/api/runs/{run_id}/pause")
    async def pause_run(run_id: str):
        """PAUSE: freeze pipeline at next checkpoint, save state for resume."""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        (queue / ".pause").write_text("pause", encoding="utf-8")
        _controls.request_pause()
        return {"status": "pause_requested", "id": run_id}

    @app.post("/api/runs/{run_id}/feedback")
    async def submit_feedback(run_id: str, request_data: dict):
        """Submit user feedback for a phase. Stops pipeline + saves feedback for next resume.
        Body: {phase: 1, message: "Brief is too narrow, include biotech"}"""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        phase = str(request_data.get("phase", ""))
        message = request_data.get("message", "")
        if not message:
            return JSONResponse({"error": "message is required"}, 400)
        # Load existing feedback or create new
        fb_path = queue / "feedback.json"
        fb = json.loads(fb_path.read_text(encoding="utf-8")) if fb_path.exists() else {}
        fb[phase] = message
        fb_path.write_text(json.dumps(fb, indent=2), encoding="utf-8")
        # Auto-pause pipeline so it picks up feedback on resume (not terminal stop)
        (queue / ".pause").write_text("pause", encoding="utf-8")
        _controls.request_pause()
        return {"status": "feedback_saved", "phase": phase, "will_redo_from": phase}

    @app.post("/api/runs/{run_id}/add_context")
    async def add_context(run_id: str, request_data: dict):
        """Add context to running pipeline WITHOUT pausing. Context is injected at next opportunity.
        Only valid during Phase 1; Phase 2+ rejects (matches FE input lock + Firestore listener).
        Body: {text: "Also look at biotech angle"}"""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        text = request_data.get("text", "")
        if not text:
            return JSONResponse({"error": "text is required"}, 400)
        if _runtime.phase >= 2:
            log(f"REST add_context REJECTED (phase={_runtime.phase} — input disabled from Phase 2 onward)", "WARN")
            return JSONResponse({"error": f"context rejected — phase {_runtime.phase} does not accept input"}, 409)
        _controls.add_context(text)
        log(f"Context added ({len(text)} chars) — will be injected at next phase boundary")
        return {"status": "context_added", "chars": len(text)}

    @app.post("/api/runs/{run_id}/resume")
    async def resume_run(run_id: str, request_data: dict = None):
        """Resume a paused/failed pipeline run. Queued if another is running.
        If feedback exists, pipeline redoes that phase with feedback injected.
        NOTE: only paused runs can be resumed — stopped runs are terminal."""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        # Block resume of stopped (terminal) runs
        if (queue / ".stop").exists():
            return JSONResponse({"error": "Run was stopped (terminal). Cannot resume — start a new run."}, 409)
        # Clear .pause signal
        p = queue / ".pause"
        if p.exists():
            p.unlink()
        # If feedback targets a specific phase, reset checkpoint to redo from there
        fb_path = queue / "feedback.json"
        cp = load_checkpoint(queue)
        if fb_path.exists() and cp:
            fb = json.loads(fb_path.read_text(encoding="utf-8"))
            if fb:
                earliest_phase = min(int(p) for p in fb.keys())
                # Reset checkpoint so pipeline redoes from the feedback phase
                cp["last_completed_phase"] = max(0, earliest_phase - 1)
                (queue / "checkpoint.json").write_text(json.dumps(cp, indent=2), encoding="utf-8")
                # Remove outputs from that phase onwards so they get regenerated
                if earliest_phase <= 1:
                    for f in (queue / "documents").glob("brief.md"):
                        try: f.unlink()
                        except Exception: pass
                if earliest_phase <= 2:
                    for f in (queue / "documents").glob("*.md"):
                        if f.stem != "brief":
                            try: f.unlink()
                            except Exception: pass
                if earliest_phase <= 3:
                    for p in [queue / "links.json"]:
                        try: p.unlink(missing_ok=True)
                        except Exception: pass
                    podcasts_dir = queue / "podcasts"
                    if podcasts_dir.exists():
                        for f in podcasts_dir.glob("*.*"):
                            try: f.unlink()
                            except Exception: pass
        # If request has config, merge with existing config.json
        if request_data and request_data.get("config"):
            config_path = queue / "config.json"
            existing = json.loads(config_path.read_text(encoding="utf-8")) if config_path.exists() else {}
            existing.update(request_data["config"])
            config_path.write_text(json.dumps(existing, indent=2), encoding="utf-8")
        # Reset delivery + meta status from "paused" back to "ongoing"
        d_path = queue / "delivery.json"
        if d_path.exists():
            try:
                d = json.loads(d_path.read_text(encoding="utf-8"))
                if d.get("status") == "paused":
                    d["status"] = "ongoing"
                    d_path.write_text(json.dumps(d, indent=2), encoding="utf-8")
            except Exception:
                pass
        m_path = queue / "meta.json"
        if m_path.exists():
            try:
                m = json.loads(m_path.read_text(encoding="utf-8"))
                if m.get("status") == "paused":
                    m["status"] = "ongoing"
                    m_path.write_text(json.dumps(m, indent=2), encoding="utf-8")
            except Exception:
                pass
        topic = cp.get("topic", "") if cp else ""
        email = (request_data or {}).get("email", "")
        await _job_queue.put({"topic": topic, "email": email, "resume_dir": str(queue)})
        return {"status": "queued_resume", "id": run_id, "queue_position": _job_queue.qsize()}

    # ── Job queue: one pipeline at a time, multiple can be queued ──
    _job_queue = asyncio.Queue()
    # `_QUEUE_STATE["running"]` is the single source of truth for worker
    # busy-state. The closure-local _queue_running was dropped in Q7 — it
    # was a vestigial duplicate that could diverge from _QUEUE_STATE if a
    # write raised between the two assignments. /api/queue, /api/health,
    # _aegis_pulse_loop, and the listener all now read _QUEUE_STATE.
    _QUEUE_STATE["queue_ref"] = _job_queue
    _QUEUE_STATE["recompute_fn"] = None  # set below after defining helper

    def _flip_txn_stage(tx, root) -> str:
        """Which Firestore RPC was refused — the one thing 20 logged failures
        never said.

        The library masks a denial inside a transaction as "the transaction has
        no transaction ID, so it cannot be rolled back", which describes the
        rollback and not the fault. But that message is itself the evidence:
        `Transaction._id` is set only AFTER BeginTransaction returns, so an
        absent id means BeginTransaction is what was refused — before any
        document was read or written, and therefore upstream of every rule
        predicate about deviceId or ownership. An id that IS present narrows it
        to the read or the commit instead.

        Kept a named function, not an f-string at the call site, so the polarity
        can be tested without provoking a real denial.
        """
        try:
            began = getattr(tx, "_id", None) is not None
        except Exception:
            return "stage=unknown (transaction object unreadable)"
        if not began:
            return ("stage=BeginTransaction — no transaction id was ever issued, "
                    "so the denial is on opening the transaction itself, not on "
                    "the document read or the write payload")
        _dbg = getattr(root, "debug_error_string", "") or ""
        return ("stage=read_or_commit — the transaction opened, so the denial is "
                "on the document"
                + (f" | grpc={str(_dbg)[:200]}" if _dbg else ""))

    def _flip_queued_to_ongoing(uid_val, research_id_val):
        """Worker pickup: flip status from queued → ongoing and clear queue
        fields. Transactional — only flips if current status is "queued",
        so a concurrent cancel that wrote status="stopped" between dequeue
        and this call wins the race. Without this, a cancel landing in the
        ms between worker dequeue and worker.flip() would be silently
        overwritten back to "ongoing" and the user would see "Cancelled" in
        chat while the tile said running. No-op if Firestore is unavailable
        or uid/rid missing (HTTP /api/runs path doesn't carry them)."""
        if not (_firebase_db and uid_val and research_id_val):
            return
        try:
            from google.cloud import firestore as _firestore
            doc_ref = _firebase_db.collection("users").document(uid_val) \
                .collection("researches").document(research_id_val)

            @_firestore.transactional
            def _flip_txn(tx):
                snap = doc_ref.get(transaction=tx)
                if not snap.exists:
                    return "missing"
                cur = (snap.to_dict() or {}).get("status")
                if cur != "queued":
                    return f"skipped({cur})"
                tx.update(doc_ref, _be_payload({
                    "status": "ongoing",
                    "queuePosition": _firestore.DELETE_FIELD,
                    "queuedBehindRunId": _firestore.DELETE_FIELD,
                    "queuedBehindTitle": _firestore.DELETE_FIELD,
                }))
                return "flipped"

            # #720: a stale gRPC idToken (missing the deviceId claim) makes the
            # transaction's first READ fail deviceMemberOf → google-cloud-firestore
            # masks it as "transaction has no transaction ID". Heal re-mints a
            # claim-bearing token and re-runs with a FRESH transaction object.
            #
            # ⚠ 2026-08-06 — THAT DIAGNOSIS IS NOT WHAT THE LIBRARY DOES, and the
            # heal's own output says so: "the re-minted token did NOT clear the
            # denial — so a stale credential was not the cause", 20 occurrences
            # across the corpus and not one success. Reading the installed
            # google-cloud-firestore: `_Transactional._pre_commit` calls
            # `transaction._begin(...)` EAGERLY, `_begin` issues a real
            # BeginTransaction RPC and only sets `self._id` afterwards, and
            # `_rollback` opens with `if not self.in_progress: raise ValueError`
            # where `in_progress` is `self._id is not None`. A denied READ, a
            # denied COMMIT and a denied ROLLBACK all leave `_id` set and would
            # surface as a bare PermissionDenied — so the ValueError we see can
            # only come from BeginTransaction ITSELF being denied, before any
            # document is touched. That is upstream of every rule predicate the
            # heal reasons about, which is exactly why re-minting cannot help.
            # `_flip_tx` is captured so the except block can report whether an id
            # was ever obtained, and turn that reading into proof next run.
            _flip_tx = _firebase_db.transaction()
            outcome = _grpc_write_with_heal(
                lambda: _flip_txn(_flip_tx),
                what=f"flip queued→ongoing {research_id_val[:8]}…",
            )
            if outcome.startswith("skipped"):
                log(f"[flip] {research_id_val[:8]}… {outcome} — leaving status as-is (cancel race won)", "INFO")
            elif outcome == "missing":
                log(f"[flip] {research_id_val[:8]}… research doc missing — Q3 cascade-cancel should catch this", "WARN")
            return outcome
        except Exception as e:
            # 2026-05-28: surface the ROOT cause. A permission error inside the
            # transaction makes google-cloud-firestore raise "transaction has no
            # transaction ID, so it cannot be rolled back", which MASKS the real
            # 403 (the flip's research-doc update was denied — see the
            # deviceUpdatingFor self-heal fix). Log __cause__/__context__ so any
            # future flip failure is diagnosable instead of misleading.
            # ⚠ Lead with the ROOT. Appending it was not enough: the line opened
            # with "The transaction has no transaction ID, so it cannot be rolled
            # back", which is an artifact of the rollback and not a fault anyone
            # can act on, and the PermissionDenied that actually happened sat at
            # the end past a device id. Every occurrence in the live corpus reads
            # that way.
            _root = getattr(e, "__cause__", None) or getattr(e, "__context__", None)
            _head = f"{type(_root).__name__}: {_root}" if _root is not None else str(e)
            # ⛔⛔ 2026-08-20 — THIS WAS A WARN FOR A WRITE THAT IS NEVER NEEDED.
            # The comment on the caller's fallback says it plainly: this flip has
            # failed on EVERY run in the corpus, twenty occurrences and zero
            # successes — and the fallback plain-read has resolved the status
            # every single time, because the app has already set it. So the run is
            # never affected, and the operator was handed two WARNs and a
            # paragraph of transaction diagnostics per run for a no-op.
            #
            # Owner, 2026-08-20, on this exact line: take care of the false alarm.
            # The alerting rule this file already follows is "speak when a PERSON
            # must act"; nobody can act on this and nothing is lost.
            #
            # ⭐ Kept at full detail, ONCE per process, keyed on the root cause's
            # class — via the same `logquiet` primitive wave 2 added for the
            # telemetry flood. The root cause is still unnamed, so the day it
            # changes class the new one still speaks. What stops is the repetition
            # (and the level: the caller downgrades this to DEBUG the moment its
            # read resolves the status, which is the measured 100% case).
            _emit_flip, _flip_dropped = _FLIP_403_QUIET.consider(
                "flip-txn-refused", f"{type(_root).__name__ if _root else type(e).__name__}")
            if _emit_flip:
                log(
                    f"[flip] could not open the queued→ongoing transaction for "
                    f"{research_id_val}: {_head}"
                    + (f" | surfaced as: {e}" if _root is not None else "")
                    + f" | {_flip_txn_stage(locals().get('_flip_tx'), _root)}"
                    + " | the caller falls back to a plain read; this is not a "
                      "run-affecting failure"
                    + logquiet.suppressed_note(_flip_dropped),
                    "DEBUG",
                )
            # ⚠ NOT None. `None` read as "legacy success — proceed", so on every
            # run in this corpus the caller's terminal-status bail was silently
            # switched off: a run cancelled or watchdog-stopped between dequeue
            # and pickup would have launched a browser anyway. "We could not
            # evaluate the flip" is a third answer and the caller now asks again.
            return "error"

    def _recompute_queue_positions():
        """After a job finishes, shift remaining queued jobs' positions up by
        one and re-point their `queuedBehindRunId/Title` at the new head (or
        clear if they're next). Reads `_job_queue._queue` as a snapshot.

        Uses a single Firestore WriteBatch so all N position updates land
        atomically — the FE never sees an inconsistent intermediate state
        where two queued runs both think they're #1 (Q4: cancel #1 →
        positions #2,#3 must become #1,#2 in one render frame, no flicker).
        WriteBatch caps at 500 ops; for typical N (single-digit queued runs)
        this is one batch; safety chunk at 450 ops if ever exceeded."""
        if not _firebase_db:
            return
        # #890: ALWAYS refresh the device-doc queueOwners union afterwards —
        # including when the local deque just drained (last queued job picked
        # up / cancelled): the publisher then drops it from the amber #N
        # badges as the green workers.{id} pill takes over. Threaded because
        # this fn runs on the asyncio loop (call_soon_threadsafe / completion
        # flow) while the publisher does blocking Firestore I/O; it is
        # single-flight guarded so concurrent kicks skip, not pile up.
        def _kick_owner_publish():
            try:
                _threading.Thread(
                    target=_recompute_deferred_queue_positions, daemon=True
                ).start()
            except Exception as _kop_err:
                log(f"[queue-pos] owner-publish kick failed (best-effort): {_kop_err}", "DEBUG")
        try:
            pending = list(_job_queue._queue)
        except Exception:
            return
        if not pending:
            _kick_owner_publish()
            return
        try:
            from google.cloud.firestore import DELETE_FIELD
        except Exception:
            DELETE_FIELD = None  # pyright: ignore[reportConstantRedefinition]
        # Build patch list first so we can chunk into 450-op batches if N
        # ever exceeds Firestore's 500-op WriteBatch ceiling.
        patches: list[tuple[str, str, dict]] = []
        for idx, qjob in enumerate(pending):
            uid_v = qjob.get("uid")
            rid_v = qjob.get("research_id")
            if not uid_v or not rid_v:
                continue
            new_pos = idx + 1
            if idx == 0:
                # Position #1's "behind" is the currently-running pipeline
                # when there is one. Two callers reach this branch with
                # different semantics:
                #   • Completion flow (after task_done at :25549) —
                #     `_QUEUE_STATE["running"]` was just flipped False and
                #     `current_job` set to None. The else-branch clears
                #     behind fields (no run ahead — position #1 is next up).
                #   • Enqueue flow (called from the start-listener lambda
                #     after _safe_enqueue) — `running` is True and
                #     `current_job` is the live pipeline. Set behind to
                #     the running job's title so QueuedBanner reads
                #     "Will play after <running>" instead of either no
                #     reference or (pre-fix) the wrong one the FE wrote
                #     at submit time based on its own activeOnDevice
                #     guess.
                running_job = _QUEUE_STATE.get("current_job")
                if (running_job
                        and _QUEUE_STATE.get("running")
                        and running_job.get("research_id") != rid_v):
                    patch = {
                        "queuePosition": new_pos,
                        "queuedBehindRunId": running_job.get("research_id") or "",
                        "queuedBehindTitle": (running_job.get("topic") or "")[:60],
                    }
                else:
                    patch = {"queuePosition": new_pos}
                    if DELETE_FIELD is not None:
                        patch["queuedBehindRunId"] = DELETE_FIELD
                        patch["queuedBehindTitle"] = DELETE_FIELD
            else:
                prev = pending[idx - 1]
                patch = {
                    "queuePosition": new_pos,
                    "queuedBehindRunId": prev.get("research_id") or "",
                    "queuedBehindTitle": (prev.get("topic") or "")[:60],
                }
            patches.append((uid_v, rid_v, patch))
        CHUNK = 450
        for i in range(0, len(patches), CHUNK):
            chunk = patches[i:i + CHUNK]
            def _commit_chunk(chunk=chunk):
                batch = _firebase_db.batch()
                for uid_v, rid_v, patch in chunk:
                    ref = _firebase_db.collection("users").document(uid_v) \
                        .collection("researches").document(rid_v)
                    batch.update(ref, _be_payload(patch))
                batch.commit()
            try:
                # #720: heal a stale-token 403 on the renumber; rebuild the batch
                # inside the op so a retry commits a fresh batch, not a consumed one.
                _grpc_write_with_heal(_commit_chunk, what=f"queue-pos batch [{i}:{i+CHUNK}]")
            except Exception as e:
                log(f"Failed to commit queue-position batch [{i}:{i+CHUNK}]: {e}", "WARN")
        # #890: publish the refreshed queueOwners union (local + deferred).
        _kick_owner_publish()

    # Expose the recompute helper to the module-level Firestore listener so
    # the cancel-queued action can also trigger a position refresh.
    _QUEUE_STATE["recompute_fn"] = _recompute_queue_positions
    # Real-time deferred-doc renumber (2026-05-22): module-level
    # `_recompute_deferred_queue_positions` updates positions for the
    # Firestore-deferred docs the local recompute can't see. Wired into
    # the listener claim path, idle-rescan after claim, and the
    # _do_cancel deferred-cancel branch. See helper docstring.
    _QUEUE_STATE["recompute_deferred_fn"] = _recompute_deferred_queue_positions
    # 2026-05-15: initialise the hard-reset lock here, before the device-cmd
    # listener thread is spawned at research.py:24898. The lock makes the
    # gate-state clear+persist (in the device-cmd thread) atomic w.r.t. the
    # worker `finally` block writes (in the asyncio main thread). Without it,
    # a worker finishing between the clear (line 1916-1918) and the persist
    # (line 1919) of hard_reset would write stale uid_X back to _QUEUE_STATE,
    # which the persist would then snapshot to disk — defeating the reset.
    _QUEUE_STATE["_hard_reset_lock"] = _threading.Lock()
    _QUEUE_STATE["_pending_enq_lock"] = _threading.Lock()

    # ── pending_queue.json (Phoenix T3 resume) ─────────────────────────────
    # The in-memory _job_queue (asyncio.Queue) is lost when the BE process
    # exits — daemon-loop relaunch otherwise restarts with an empty queue,
    # losing any work that hadn't reached `status=queued` in Firestore yet.
    # Snapshot to disk on every worker boundary so a Phoenix restart can
    # restore. Firestore-driven rehydration (line ~17850) takes precedence;
    # this is a belt-and-suspenders fallback for racing/network-blocked cases.
    # Per-worker pending-queue file (2026-05-21). Pre-multi-worker, all
    # writers raced on `_pending_queue.json` (+ its `.tmp` sibling). With
    # N workers, the tmp-then-replace dance still races: two workers
    # writing different snapshots both name the tmp the same, the second
    # write clobbers the first mid-buffer. Per-worker file isolates each
    # snapshot. Restore (research.py:~26649, 26991) reads MY worker's
    # file only — siblings restore their own. Single-worker installs
    # keep the legacy filename (worker 1 = no suffix) so a pre-PR install
    # that never re-pairs into multi-worker still finds its snapshot.
    if WORKER_ID == 1:
        _pending_queue_path = queues_root / "_pending_queue.json"
    else:
        _pending_queue_path = queues_root / f"_pending_queue_worker_{WORKER_ID}.json"

    # Forward declaration so the module-scope device-cmd listener at
    # research.py:1766 can call this closure via _QUEUE_STATE["persist_fn"].
    # The assignment happens immediately after the function body below.
    def _persist_pending_queue(current_job=None):
        """Snapshot _job_queue contents (+ optional current_job) to disk.
        Returns True on success, False on persist failure. Never raises.

        On failure with a current_job, immediately writes
        status=paused_backend_restart_failed + lastError to the affected
        research's Firestore doc so the FE recovery banner surfaces. The
        Phoenix auto-restore path on respawn relies on this snapshot — if
        it didn't write, there's nothing to restore from, and the run
        would otherwise be silently lost on BE restart."""
        try:
            queues_root.mkdir(parents=True, exist_ok=True)
            try:
                pending = list(_job_queue._queue)
            except Exception:
                pending = []
            payload = {
                "ts_ms": int(time.time() * 1000),
                "current": current_job,
                "pending": pending,
                # 2026-05-11: persist the queue-gate's prior-run state so
                # a daemon restart mid-FE-P5 doesn't lose the wait
                # context. Without this, fresh _QUEUE_STATE after respawn
                # means the gate skips and the next pipeline races
                # against the in-flight FE-P5 of the prior run.
                "gate": {
                    "last_completed_uid": _QUEUE_STATE.get("last_completed_uid"),
                    "last_completed_rid": _QUEUE_STATE.get("last_completed_rid"),
                    "last_be_done_at": int(_QUEUE_STATE.get("last_be_done_at") or 0),
                },
            }
            # 2026-05-11: atomic write — write to tmp, then os.replace
            # (atomic on POSIX and Windows same-volume). Protects against
            # the Q7 watchdog path where _schedule_server_exit's 3s timer
            # can race os._exit(0) past a slow in-progress write_text(),
            # leaving _pending_queue.json truncated. On respawn the
            # truncated file fails json.loads and disk-restore silently
            # skips, losing the gate state for the very FIRST post-restart
            # dequeue (the case the boot-race fix already mitigates, but
            # the truncated-file mode would also lose pending in-memory
            # jobs not yet visible in Firestore).
            _tmp_path = _pending_queue_path.with_suffix(".json.tmp")
            _tmp_path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
            os.replace(str(_tmp_path), str(_pending_queue_path))
            return True
        except Exception as e:
            log(f"[pending_queue] persist failed: {e}", "WARN")
            if current_job and _firebase_db is not None:
                uid = current_job.get("uid")
                rid = current_job.get("research_id")
                if uid and rid:
                    if _update_research_doc(uid, rid, {
                        "status": "paused_backend_restart_failed",
                        "lastError": (
                            "Pipeline state could not be saved before "
                            f"backend restart ({str(e)[:120]}). Tap "
                            "Resume to attempt manual recovery from "
                            "the last checkpoint, or Discard to abandon."
                        ),
                    }):
                        log(f"[pending_queue] Surfaced persist failure for "
                            f"{rid[:24]} — FE will show recovery banner", "WARN")
            return False

    # 2026-05-15: expose the persist closure to the module-scope device-cmd
    # listener at research.py:1766 so hard_reset can flush a clean snapshot
    # to disk before os._exit (the listener can't directly close over this
    # function — it lives in a different scope).
    _QUEUE_STATE["persist_fn"] = _persist_pending_queue

    # Outer ACTIVE-TIME ceiling for a single pipeline run (Fix D 2026-05-27:
    # was raw wall-clock). Phase budgets inside run_pipeline are cooperative
    # — long Playwright/CUA awaits without timeouts can deadlock the worker
    # indefinitely, leaving /api/queue stuck at running:true and pending
    # jobs starved. Q7 watchdog: if a run's ACTIVE work-time exceeds this we
    # declare it stuck, request_stop, mark the doc stopped_by_watchdog, and
    # schedule a process exit so the daemon-loop respawns a fresh worker that
    # drains the rest of the queue. The supervisor at the run_pipeline call
    # site does NOT accrue time while _controls.is_pause() or
    # _controls._awaiting_user (blocked on a user decision) — so legitimate
    # waits never trip it (the old wall-clock version false-killed a run that
    # sat for hours on an unbounded await_phase_decision). Generous 5h of
    # active time — a healthy run is under 90min; sized to allow P1+P2+P3-
    # audio soft-warn advisories (60+120+90 = 270 min) of real work before
    # the deadlock backstop. 2026-05-06 (Stream 2 F12): bumped 4h → 5h.
    WORKER_OUTER_TIMEOUT_SEC = 5 * 60 * 60
    # BE_PHASES_TIMEOUT_SEC lives at module scope (research.py:1224) since
    # 2026-05-12 so the Firestore start listener (also module-level) can
    # predict whether the gate will block when assigning queue position.
    # This block kept as a doc anchor — the constant itself moved.

    async def _wait_for_prior_fe_completion(_current_job=None):
        """Hold the next dequeue until the prior run's FE-P5 reports
        completion via research.status=='completed', or the fallback
        timer expires.

        `_current_job` is the just-dequeued job (passed in by the worker
        BEFORE _QUEUE_STATE["current_job"] is set). Used to detect the
        resume-of-same-rid edge case described below."""
        _puid = _QUEUE_STATE.get("last_completed_uid")
        _prid = _QUEUE_STATE.get("last_completed_rid")
        _pdone = int(_QUEUE_STATE.get("last_be_done_at") or 0)
        if not _firebase_db or not _puid or not _prid:
            return  # first run or missing context — nothing to wait on
        # 2026-05-11: skip the gate when the dequeued job IS the same rid
        # as the just-finished run. This happens on resume-from-checkpoint
        # paths where Firestore re-enqueues the same rid after a BE crash
        # or restart — the "prior" run from the gate's POV is actually
        # the current dequeued run; waiting on its own FE-P5 would
        # circular-deadlock (BE never starts → FE-P5 never fires → gate
        # waits the full 4200s fallback). Resume semantics handle the
        # state machine separately; the gate only matters for the
        # successor-pipeline-after-different-prior case.
        if _current_job and (_current_job.get("research_id") or "") == _prid:
            log(f"[queue-gate] dequeued rid {_prid[:8]}… matches last_completed_rid — resume path, skipping wait")
            return
        if _pdone <= 0:
            # Error path marker: prior run was watchdog-stopped /
            # errored / never reached BE PIPELINE COMPLETE. FE-P5
            # will never write "completed" for it, so don't block.
            log("[queue-gate] prior run errored — skipping FE-completion wait")
            return
        deadline = _pdone + BE_PHASES_TIMEOUT_SEC * 1000
        # Mid-session stuck-status self-heal — if the prior FE-P5 just
        # legitimately ghosted (user closed the tab, FE-P5 errored without
        # flipping status, browser was force-quit), the gate previously
        # waited the full 70-min deadline before giving up. Now: take a
        # snapshot of (status, feP5State) on entry and force-release if
        # both stay unchanged for STUCK_STATUS_RELEASE_MS (5 min). The
        # deadline still backstops the slow-FE-P5 case (large YouTube
        # uploads), but the common-case stuck-prior gets unstuck in 5 min
        # without needing a BE restart or Reset Backend tap.
        STUCK_STATUS_RELEASE_MS = 5 * 60 * 1000
        _stuck_first_seen_ms: int = 0
        _stuck_status_signature: str = ""  # f"{status}|{feP5State}"
        # 2026-08-11: say how long is ACTUALLY left, not the constant. The
        # deadline is anchored to when the PRIOR run finished, not to when this
        # gate opened — so on a device that has been idle for longer than the
        # window (the normal case: the owner starts the next run hours later)
        # it is already in the past. The old line announced a 4200s wait and
        # the very next line, in the same second, announced that 4200s had
        # elapsed. Both were false, and chasing them cost real time.
        _gate_left_ms = deadline - int(time.time() * 1000)
        if _gate_left_ms > 0:
            log(f"[queue-gate] waiting for prior run {_prid[:8]}… FE-P5 completion "
                f"(fallback in {int(_gate_left_ms / 1000)}s)")
        else:
            log(f"[queue-gate] prior run {_prid[:8]}… finished "
                f"{int((int(time.time() * 1000) - _pdone) / 1000)}s ago, past its "
                f"{BE_PHASES_TIMEOUT_SEC}s FE-P5 window — checking its status once, "
                f"not waiting")
        # 2026-05-12: register the gate-pending job so cancel handlers can
        # see it. Without this, a cancel that arrives while the worker is
        # blocked in the gate wait silently no-ops — neither in job_queue
        # (already popped) nor in current_job (not set until after gate).
        # User saw "Cancel: rid=… removed_from_queue=False" with no status
        # flip + no banner unmount. Cleared on gate return.
        if _current_job:
            _QUEUE_STATE["gate_pending_job"] = _current_job
        while True:
            # 2026-05-12: honor explicit stop requests during gate wait.
            # When the cancel handler matches gate_pending_job and calls
            # request_stop, this poll loop exits cleanly so the worker can
            # bail out of the gate and drop the job.
            try:
                if _controls.is_stop():
                    log("[queue-gate] stop requested during gate wait — releasing", "INFO")
                    _QUEUE_STATE.pop("gate_pending_job", None)
                    return
            except Exception:
                pass
            now_ms = int(time.time() * 1000)
            try:
                # 2026-05-11: offload the blocking Firestore .get() to a
                # worker thread so the gate's 2s poll doesn't block the
                # event loop on the round-trip (50-200ms typical, longer
                # under network contention). Keeps heartbeat / listener
                # callbacks responsive while the gate waits.
                _doc_ref = _firebase_db.collection("users").document(_puid) \
                    .collection("researches").document(_prid)
                snap = await asyncio.to_thread(_doc_ref.get)
                if not snap.exists:
                    # Prior research doc was deleted (user purged from
                    # /researches). Treat as terminal — there's nothing
                    # left to wait on. Without this branch the gate
                    # would spin silently until the deadline fires
                    # (worst case BE_PHASES_TIMEOUT_SEC = 70 min).
                    log(f"[queue-gate] prior run {_prid[:8]}… doc missing — dequeueing")
                    _QUEUE_STATE.pop("gate_pending_job", None)
                    return
                if snap.exists:
                    data = snap.to_dict() or {}
                    status = data.get("status", "")
                    fe_p5_state = data.get("feP5State", "")
                    if status in ("completed", "stopped", "stopped_by_watchdog",
                                  "cancelled", "terminated_by_user_discard", "errored"):
                        log(f"[queue-gate] prior run terminal (status={status}) — dequeueing")
                        _QUEUE_STATE.pop("gate_pending_job", None)
                        return
                    # 2026-05-11: markFeP5Failed writes feP5State="failed"
                    # but doesn't flip research.status — so a thrown FE-P5
                    # exception would hang the gate for the full 4200s.
                    # Release the gate on this fast-fail marker too.
                    if fe_p5_state == "failed":
                        log("[queue-gate] prior run's FE-P5 failed — dequeueing")
                        _QUEUE_STATE.pop("gate_pending_job", None)
                        return
                    # Stuck-status self-heal: if (status, feP5State) hasn't
                    # changed in STUCK_STATUS_RELEASE_MS, the prior FE has
                    # ghosted and is never coming back. Force-release. The
                    # first-seen marker resets on any signature change so
                    # a slow-but-progressing FE-P5 (e.g., long YouTube
                    # upload that flips feP5State queued→running→completed
                    # over several minutes) doesn't trip the heal.
                    _sig = f"{status}|{fe_p5_state}"
                    if _sig != _stuck_status_signature:
                        _stuck_status_signature = _sig
                        _stuck_first_seen_ms = now_ms
                    elif (now_ms - _stuck_first_seen_ms) >= STUCK_STATUS_RELEASE_MS:
                        log(
                            f"[queue-gate] prior run {_prid[:8]}… stuck at "
                            f"({status},{fe_p5_state}) for "
                            f"{int((now_ms - _stuck_first_seen_ms) / 1000)}s — "
                            f"FE-P5 ghosted, force-dequeueing"
                        )
                        _QUEUE_STATE.pop("gate_pending_job", None)
                        return
            except Exception as e:
                _e_str = str(e)
                if (
                    "403" in _e_str
                    or "PERMISSION_DENIED" in _e_str
                    or "Missing or insufficient permissions" in _e_str
                ):
                    # Track D: synth user denied on prior run's research
                    # doc. We can't poll its terminal status — but we
                    # also can't sit in a 2-second poll loop spamming
                    # 403s and wedging the queue for BE_PHASES_TIMEOUT_SEC
                    # (4200s by default). The on-disk gate-state and
                    # _safe_enqueue's whitelist already de-dupe restart
                    # races, so release the gate immediately and let
                    # the worker proceed. Under-Track-D this is the
                    # right behavior: every research is owned by some
                    # device, the BE only sees its own device-queue
                    # entries, and two queued runs on the same device
                    # arrive in order via the start listener.
                    log("[queue-gate] read denied (synth user) — releasing gate (Track D)", "DEBUG")
                    _QUEUE_STATE.pop("gate_pending_job", None)
                    return
                log(f"[queue-gate] Firestore read failed: {e}", "WARN")
            # 2026-08-11: deadline check moved BELOW the status read. It used
            # to be the first thing in the loop, so an already-expired deadline
            # returned before the poll had read anything even once — the gate
            # released without ever learning that the prior run was sitting
            # right there at status="completed", and then reported the one
            # thing it had not checked ("FE never reported completed"). Every
            # earlier branch returns, and the read is wrapped, so this stays
            # reachable on every path: no read, failed read, or non-terminal.
            if now_ms >= deadline:
                log(f"[queue-gate] prior run {_prid[:8]}… is "
                    f"{int((now_ms - _pdone) / 1000)}s past its backend finish with no "
                    f"terminal status seen (FE-P5 window {BE_PHASES_TIMEOUT_SEC}s) — "
                    f"force-dequeueing")
                _QUEUE_STATE.pop("gate_pending_job", None)
                return
            await asyncio.sleep(2)

    async def _rescan_queue_for_unclaimed():
        """Multi-worker orphan recovery (2026-05-21).

        Scenario: N workers all busy when doc D arrives → every worker's
        on_snapshot fires but each gates on busy → D sits in
        `devices/{deviceId}/queue/` with no `assignedWorker`. Firestore
        won't re-fire ADDED for D when a worker becomes idle (it's not
        a new doc anymore), so without this rescan D would orphan.

        Called from the worker's finally block (after every job ends).
        On entry, the worker is idle. Scan the queue collection for
        unclaimed start-action docs, attempt Firestore transactional
        claim on the first match, and enqueue locally. Single attempt
        per call — if the claim races and loses, the next worker idle
        triggers another rescan.

        No-op in single-worker mode (workerCount=1): the on_snapshot
        listener doesn't gate on busy there, so all docs are enqueued
        as they arrive; orphan path never reached.
        """
        if not _firebase_db:
            return
        if load_worker_count() <= 1 and not _REST_DEFER_SEEN["v"]:
            # Single-worker mode — the listener never gates on busy, so no
            # orphan can exist… EXCEPT a doc deferred by the #903 rest gate
            # (Firestore won't re-fire ADDED when the owner wakes the worker;
            # this rescan is the wake-side pickup). While the flag is set the
            # LISTENER claims too (mutual exclusion — see the start-listener
            # gate), and the flag clears below once the queue is drained. A
            # restart self-heals without the flag: listener start re-delivers
            # surviving queue docs as ADDED.
            return
        # Shutdown gate (2026-05-22): STOP scheduled exit makes the
        # worker's `finally` block trigger an idle-rescan even though
        # the process is about to die. Without this gate, the rescan
        # would claim a deferred-FIFO doc, log "picking up orphan",
        # then exit before completing the side effects — leaving the
        # doc half-claimed in Firestore (`assignedWorker` set, no
        # actual work happening). The next respawn's stale-skip
        # would then delete the legit FIFO entry. Skip the whole
        # rescan when a stop is in flight.
        if _exit_scheduled:
            log(f"[idle-rescan] worker {WORKER_ID}: skipping — exit scheduled", "INFO")
            return
        if (
            _QUEUE_STATE.get("running")
            or _job_queue.qsize() > 0
            or _QUEUE_STATE.get("gate_pending_job")
        ):
            # Not actually idle: running a job, a job already queued locally, OR
            # blocked in _wait_for_prior_fe_completion (gate_pending_job is set
            # while the worker holds a dequeued job in the FE-completion gate with
            # running=False/qsize=0). Without the gate check a periodic rescan
            # would treat a gated worker as idle and claim a SECOND doc, serializing
            # it behind the still-gated job.
            return
        # #903: a resting worker never claims — neither fresh docs nor
        # orphans. The wake transition is caught by the next rescan tick.
        # AFTER the busy/exit early-outs (review: a busy worker must keep
        # returning traffic-free) and OFF the event loop (the TTL-expired
        # read is a blocking Firestore get).
        # #904: before returning, run the keep-alive/self-heal pass so a
        # parked queue stays durable (restDeferredAt refresh) and a doc
        # that drifted to status="ongoing" is re-asserted queued. Throttled
        # internally to ~1/min; still never claims anything.
        if await asyncio.to_thread(_worker_is_resting):
            await asyncio.to_thread(_rest_keepalive_pass)
            return
        did = load_device_id()
        if not did:
            return
        try:
            col = _firebase_db.collection("devices").document(did).collection("queue")
            candidates = await asyncio.to_thread(lambda: list(col.limit(20).stream()))
        except Exception as e:
            log(f"[idle-rescan] worker {WORKER_ID}: scan failed: {e}", "WARN")
            return

        # #903 level-trigger: awake + no unclaimed start docs → the rest
        # episode is fully drained; clear the flag so single-worker installs
        # return to pristine (no-claim, no-rescan) behavior.
        if _REST_DEFER_SEEN["v"]:
            _has_unclaimed_start = any(
                not (s.to_dict() or {}).get("processed")
                and not (s.to_dict() or {}).get("assignedWorker")
                and ((s.to_dict() or {}).get("action") or "start") == "start"
                for s in candidates
            )
            if not _has_unclaimed_start:
                _REST_DEFER_SEEN["v"] = False
                log(f"[idle-rescan] worker {WORKER_ID}: rest episode drained — flag cleared", "DEBUG")

        # FIFO sort (PR 3, 2026-05-21): pick oldest unclaimed first so an
        # orphan that's been sitting longer gets picked up before a newer
        # one. Stream order is by doc-id (random for auto-IDs), so without
        # sorting the rescan was effectively "first-found-wins" — could
        # leave the OLDEST orphan sitting under a newer one. Sort by
        # client-ms `timestamp` ASC, missing-timestamp docs sort LAST
        # (Firestore `order_by` excludes them entirely, so in-process
        # sort handles them gracefully without a separate fallback pass).
        def _fifo_key(_snap):
            _hd = _snap.to_dict() or {}
            _ts = _hd.get("timestamp")
            if isinstance(_ts, (int, float)) and _ts > 0:
                return (0, _ts, _snap.id)
            return (1, 0, _snap.id)
        candidates.sort(key=_fifo_key)

        for snap in candidates:
            d = snap.to_dict() or {}
            if d.get("processed") or d.get("assignedWorker"):
                continue
            if (d.get("action") or "start") != "start":
                continue  # cancel/resume handled by their own paths
            # Re-check busy + shutdown + rest before each claim attempt
            # (could have flipped mid-scan: a sibling claimed a different
            # doc, a STOP landed, or the owner parked this worker). The rest
            # re-read runs off-loop (TTL-expired = blocking Firestore get).
            if (
                _exit_scheduled
                or _QUEUE_STATE.get("running")
                or _job_queue.qsize() > 0
                or _QUEUE_STATE.get("gate_pending_job")
                or await asyncio.to_thread(_worker_is_resting)
            ):
                return

            # Conditional-update claim (replaces TX-based claim that
            # masked BeginTransaction failures — 2026-05-22 root-cause
            # fix). Helper handles retries + race-loss + unexpected
            # errors with full __context__ surfacing.
            _outcome = await asyncio.to_thread(
                _try_claim_queue_doc, snap.reference, WORKER_ID,
                "[idle-rescan]",
            )
            if _outcome is None:
                # Claim helper logged the root cause — surface a
                # topic-bearing marker too so the silent continue isn't
                # invisible. submittedBy + research_id help cross-
                # account triage when the orphan is a sharer's doc.
                log(
                    f"[idle-rescan] worker {WORKER_ID}: claim error — skipping {(d.get('researchId') or '')[:8]}… "
                    f"topic={(d.get('topic') or '')[:40]!r} submittedBy={(d.get('submittedBy') or '?')[:8]}",
                    "WARN",
                )
                continue
            if _outcome is False:
                log(
                    f"[idle-rescan] worker {WORKER_ID}: lost to sibling — skipping {(d.get('researchId') or '')[:8]}… "
                    f"topic={(d.get('topic') or '')[:40]!r} submittedBy={(d.get('submittedBy') or '?')[:8]}",
                    "INFO",
                )
                continue

            # Final shutdown gate: even with a successful claim, don't
            # proceed if a STOP scheduled exit during the claim RPC.
            # The claim wrote assignedWorker + claimedAt — release them
            # via DELETE_FIELD so the doc returns to "unclaimed" state
            # and the next worker (sibling or respawned-self) can pick
            # it up cleanly. Best-effort: if the release write fails,
            # commit 3's stale-skip discrimination handles the zombie.
            if _exit_scheduled:
                log(
                    f"[idle-rescan] worker {WORKER_ID}: claimed {(d.get('researchId') or '')[:8]}… "
                    f"but exit scheduled — releasing claim",
                    "WARN",
                )
                try:
                    from google.cloud.firestore import DELETE_FIELD as _DF
                    await asyncio.to_thread(
                        snap.reference.update,
                        {"assignedWorker": _DF, "claimedAt": _DF},
                    )
                except Exception as _re:
                    log(f"[idle-rescan] release-claim failed (non-fatal): {_re}", "WARN")
                return

            # Won — replicate the listener's minimal start-action side
            # effects: validate fields, flip research doc to ongoing,
            # delete the queue doc, enqueue locally. We DON'T replicate
            # the full listener (stale-skip, cancel handling, etc.) —
            # those are only relevant for newly-arrived docs the
            # listener already gated.
            uid = (d.get("uid") or "").strip()
            research_id = (d.get("researchId") or "").strip()
            topic = (d.get("topic") or "").strip()
            if not uid or not research_id or not topic:
                log("[idle-rescan] claimed doc missing required fields — deleting", "WARN")
                try:
                    await asyncio.to_thread(snap.reference.delete)
                except Exception:
                    pass
                continue

            # ⭐ THE SECOND CLAIM SITE, refusing the same divergence the listener
            # refuses — see `_start_doc_identity_conflict`. This sweep exists to
            # pick up documents the listener did not take, so a doc the listener
            # declined arrives here next; without this the refusal is a delay.
            if _start_doc_identity_refused(d, "idle-rescan"):
                try:
                    await asyncio.to_thread(snap.reference.delete)
                except Exception:
                    pass
                continue

            run_id = f"{safe_name(topic)}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            log(f"[idle-rescan] worker {WORKER_ID}: picking up orphan {research_id[:8]}… ({topic[:40]}) submittedBy={(d.get('submittedBy') or '?')[:8]}")

            # Flip research-doc status to ongoing (the listener path
            # writes this when the worker is idle on first dequeue;
            # mirror that here for the rescanned doc). Clear the stale
            # queue fields too — pre-fix, the orphan carried its
            # deferred-state `queuePosition` / `queuedBehindRunId` /
            # `queuedBehindTitle` into ongoing, briefly rendering a
            # stale "queue position" badge on the tile during the
            # listener round-trip before the FE filter on `status` took
            # effect. Listener claim path does this cleanup via the
            # status_payload branches; mirror here for parity.
            try:
                from google.cloud.firestore import DELETE_FIELD as _DF_RESCAN
                _update_research_doc(uid, research_id, {
                    "backendRunId": run_id,
                    "status": "ongoing",
                    "queuePosition": _DF_RESCAN,
                    "queuedBehindRunId": _DF_RESCAN,
                    "queuedBehindTitle": _DF_RESCAN,
                })
            except Exception as _ue:
                log(f"[idle-rescan] research-doc update failed: {_ue}", "WARN")

            # Delete the queue doc — we've claimed and are about to run.
            try:
                await asyncio.to_thread(snap.reference.delete)
            except Exception:
                pass

            # Enqueue locally. Use _safe_enqueue mirror of the listener
            # path so cancellations between claim and enqueue still
            # reach the right place.
            _safe_enqueue(_job_queue, {
                "topic": topic,
                "email": d.get("email", ""),
                "config": d.get("config", {}),
                "run_id": run_id,
                "uid": uid,
                "research_id": research_id,
                "brief_text": (d.get("briefText") or "").strip(),
                "user_sources": d.get("userSources") or [],
                "user_links": d.get("userLinks") or [],
                "submitted_by": str(d.get("submittedBy") or "").strip(),
            }, source="idle-rescan")
            # Real-time deferred-doc renumber (2026-05-22): the just-
            # claimed orphan was at some position N in the global FIFO
            # (often head — idle-rescan picks the oldest unclaimed).
            # Shift everyone behind it up by one. Fire-and-forget via
            # to_thread; the scan is bounded to limit(50).
            _recompute_deferred = _QUEUE_STATE.get("recompute_deferred_fn")
            if _recompute_deferred is not None:
                try:
                    asyncio.create_task(asyncio.to_thread(_recompute_deferred))
                except Exception as _re:
                    log(
                        f"[idle-rescan] deferred-recompute launch failed: {_re}",
                        "WARN",
                    )
            return  # one at a time — let the worker process this before next rescan

    async def _job_worker():
        """Process pipeline jobs one at a time from the queue."""
        while True:
            job = await _job_queue.get()
            # 2026-05-25: clear stale stop flag before gate-wait. A
            # prior HARD_RESET that fired while the worker was idle
            # (no run in flight to consume the flag) leaves
            # _controls.is_stop()=True dangling. Without this reset,
            # the next job's gate-wait check at ~29094 sees the stale
            # flag and bails with "cancelled during gate wait — skipping
            # run_pipeline" — the user's Kalki repro from today's E2E
            # (HARD_RESET at 18:13:28 with no active run → Kalki claimed
            # at 18:20:45 → bailed 18:20:46 without ever starting).
            # Safe because (a) cancels for in-queue jobs remove from
            # queue (never reach pop), (b) cancels for THIS job's gate-
            # pending phase will RE-SET the flag via the gate_pending_job
            # match at research.py:4421, (c) cancels for the running job
            # set the flag and run_pipeline consumes it internally.
            try:
                _controls.reset()
            except Exception:
                pass
            # 2026-05-11: gate on prior run's FE-P5 completion. Phases
            # 4+5 are FE-owned — BE PIPELINE COMPLETE fires after P3,
            # but the actual run isn't done until FE Doc+Email lands.
            # Without this gate, the next pipeline's BE phases race
            # against the prior pipeline's FE-P4/P5 (resource contention,
            # listener cross-pollination, the queue-pileup symptom).
            # Pass `job` so the gate can detect resume-of-same-rid and
            # skip (otherwise circular deadlock — see helper docstring).
            await _wait_for_prior_fe_completion(_current_job=job)
            # 2026-05-12: stop-requested-during-gate-wait shortcut. The
            # cancel handler at research.py:2208 flips status="stopped"
            # and request_stop()s when a cancel matches gate_pending_job.
            # Honor it here so we don't proceed to launch a browser for
            # an already-cancelled job. Clear the stop flag so the next
            # job runs clean.
            try:
                if _controls.is_stop():
                    log(f"[worker] job {job.get('research_id', '')[:8]}… cancelled during gate wait — skipping run_pipeline", "INFO")
                    try:
                        _controls.reset()
                    except Exception:
                        pass
                    # The listener bumped the pending counter when it
                    # claimed this job; we're skipping the running-flag
                    # flip below where the normal decrement lands. Drain
                    # the counter here so a stop-during-gate-wait
                    # doesn't leak a slot (would falsely defer all
                    # subsequent submissions on this worker).
                    _pending_enq_dec()
                    _job_queue.task_done()
                    # Keep the queue running but drop this job entirely.
                    continue
            except Exception:
                pass
            _QUEUE_STATE["running"] = True
            _QUEUE_STATE["current_job"] = job
            # Listener-replay counter decrement (Bug B fix). Tied to
            # the running-flag flip rather than the earlier
            # `_job_queue.get()` because `_wait_for_prior_fe_completion`
            # above can suspend the coroutine for the full
            # BE_PHASES_TIMEOUT_SEC window; decrementing at get() would
            # let the gate at research.py:~4106 look idle (counter=0,
            # qsize=0, running still False) for minutes while this
            # worker is occupied waiting on FE-P5. Setting running=True
            # FIRST then dec'ing closes that window.
            _pending_enq_dec()
            # Multi-worker claim sentinel. Written here (at dequeue, the
            # earliest point we own the job) so a sibling worker booting
            # up sees our claim before doing rehydration auto-resume.
            # Cleared in the finally block below. Helper docstring at
            # research.py:_write_worker_lock explains the flat-layout
            # choice + crash-leftover defenses.
            _write_worker_lock(
                WORKER_ID,
                job.get("research_id") or "",
                job.get("run_id") or "",
            )
            # 2026-05-28: mark this worker busy in the device-doc
            # `busyWorkerIds` array. Runs for ALL workers (not gated
            # to worker-1) — FE QueuedBanner stall detector reads
            # `busyWorkerIds.length < workerCount` to know whether
            # any worker is idle while a queued run sits at position
            # #1. Released by _clear_current_run_id_best_effort on
            # finally / exit / next-boot. Idempotent via array_union.
            try:
                _did_bw = load_device_id()
                if _firebase_db and _did_bw:
                    from google.cloud.firestore import ArrayUnion as _AU
                    # 2026-05-28: also seed this worker's per-sharer usage
                    # entry for the owner's "Shared with" popup. Dotted-path
                    # `workers.<id>` merges only this slot (never clobbers a
                    # sibling worker's entry). Runs for ALL workers (mirrors
                    # busyWorkerIds), unlike the worker-1-only currentRun*
                    # block below — so a sharer's run on worker N>=2 still
                    # gets a green badge. Cleared in
                    # _clear_current_run_id_best_effort on every exit. phase
                    # starts at 0; emit_event refreshes it live per worker.
                    _firebase_db.collection("devices").document(_did_bw).update({
                        "busyWorkerIds": _AU([WORKER_ID]),
                        f"workers.{WORKER_ID}": {
                            "uid": job.get("uid") or "",
                            "runId": job.get("research_id") or "",
                            "title": (job.get("topic") or "")[:60],
                            "phase": 0,
                            "totalPhases": 6,
                        },
                    })
            except Exception as _bw_pub_err:
                log(
                    f"[device] busyWorkerIds claim (w{WORKER_ID}) failed (non-fatal): {_bw_pub_err}",
                    "DEBUG",
                )
            # #890: refresh the device-doc queueOwners union — this job just
            # left the local pending deque (amber #N badge) for a worker slot
            # (green workers.{id} pill above). Best-effort daemon thread; the
            # publisher is single-flight guarded and reads the deque fresh.
            try:
                _threading.Thread(
                    target=_recompute_deferred_queue_positions, daemon=True
                ).start()
            except Exception:
                pass
            log(f"Starting queued job: {job['topic'][:60]}")
            # Publish currentRunId on the device doc so sharers / sibling
            # tabs can see "device is busy with run X" and render the
            # QueuedBanner correctly when they submit a NEW research.
            # Pre-fix, sharers' FE only had their OWN cachedResearches to
            # check, so the owner's in-flight run was invisible and the
            # sharer's submission rendered the Phase 0 INIT tile instead
            # of "queued behind X". The synth-user write is gated by the
            # devices-doc allow-list rule (62530fb + 2026-05-20 expansion
            # to include currentRunId fields).
            # Multi-worker (2026-05-21): only worker 1 publishes
            # currentRunId. The device doc has a single currentRunId
            # field; if both workers wrote, the value would flip-flop
            # to whichever flipped last. FE QueuedBanner reads this to
            # show "device busy with X" — with worker-1-only writes,
            # the banner reflects w1's current run while w2's runs
            # complete invisibly to the banner. Sibling tabs / sharers
            # firing a 3rd run still see "queued" status because both
            # worker queues are busy; the specific title may be w1's
            # rather than w2's. Acceptable compromise — FE display
            # quirk does not affect actual execution. PR 3 may expand
            # this to a currentRunIds.{workerId} map field.
            if WORKER_ID == 1:
                try:
                    _did = load_device_id()
                    if _firebase_db and _did:
                        # 2026-05-26: publish phase=0 alongside the run-meta
                        # fields. The phase_start emit at ~line 26504 will
                        # re-write the same value within a few hundred ms
                        # — but BEFORE that fires there's a gap (job claim
                        # → run_pipeline entry → first phase_start) during
                        # which the FE QueuedBanner's "Current run is in
                        # Phase X" head-phase line either rendered the
                        # PRIOR run's stale phase or stayed silent (if the
                        # field was never set on this device). Publishing
                        # phase=0 on pickup eliminates that window. Paired
                        # with the matching clear in
                        # `_clear_current_run_id_best_effort` so STOP /
                        # hard_reset don't leak a stale value into the
                        # next run's pickup.
                        _now_ms = int(time.time() * 1000)
                        _crun_patch: dict = {
                            "currentRunId": job.get("research_id") or "",
                            "currentRunOwnerUid": job.get("uid") or "",
                            "currentRunTitle": (job.get("topic") or "")[:60],
                            "currentRunStartedAt": _now_ms,
                            "currentRunPhase": 0,
                            "currentRunPhaseStartedAt": _now_ms,
                        }
                        _firebase_db.collection("devices").document(_did).update(_crun_patch)
                except Exception as _crun_err:
                    log(f"[device] currentRunId publish failed (non-fatal): {_crun_err}", "DEBUG")
            # Snapshot AFTER popping so an exit during run_pipeline can
            # restore both the running job AND remaining queue. Without the
            # current_job param a Phoenix restart would lose this in-flight
            # research.
            _persist_pending_queue(current_job=job)
            # Flip this run's research doc from queued → ongoing. No-op for
            # the very first start in an idle backend (already ongoing).
            flip_outcome = _flip_queued_to_ongoing(job.get("uid"), job.get("research_id"))
            # Q8 (2026-04-30): bail ONLY when the flip is skipped AND the
            # actual current status is a terminal/recovery state (cancelled
            # mid-run, paused after BE restart, watchdog-stopped, user-
            # discarded, fully completed). For ANY active state — ongoing
            # (FE optimistically pre-flipped before BE picked up the job —
            # this is the normal happy path), paused (user paused mid-run,
            # wants to resume), queued (flip already handled it) — proceed
            # with run_pipeline. The original bug was that a stale
            # paused_backend_restart from a crashing supervisor child
            # caused run_pipeline to launch a browser and the orphan-
            # Chrome killer chewed live siblings. Bailing too eagerly
            # blocks every legitimate run because FE writes ongoing
            # client-side before the BE worker dequeues. None outcome
            # (no firebase / missing args / exception) is treated as
            # legacy success — proceed.
            BAIL_STATUSES = {
                "paused_backend_restart",
                "paused_backend_restart_failed",
                "stopped_by_watchdog",
                "terminated_by_user_discard",
                "stopped",
                "cancelled",
                "completed",
            }
            should_run = True
            # ⚠ 2026-08-06 — "COULD NOT EVALUATE" IS NOT "PROCEED". The flip has
            # failed on every run in this corpus (20 occurrences, zero successes),
            # and it returned None, which fell straight through to should_run=True
            # — so the terminal-status bail below has been switched off the whole
            # time. A plain read answers the same question without a transaction,
            # and the transaction is the thing being denied.
            if flip_outcome == "error":
                try:
                    _snap = (_firebase_db.collection("users").document(job.get("uid"))
                             .collection("researches").document(job.get("research_id"))
                             .get())
                    _cur = ((_snap.to_dict() or {}).get("status")
                            if _snap.exists else None)
                    if _cur:
                        flip_outcome = f"skipped({_cur})"
                        log(f"[flip] the transaction was refused; a plain read says "
                            f"status={_cur!r} — deciding from that", "INFO")
                    else:
                        log("[flip] the transaction was refused and the doc could "
                            "not be read either — proceeding, as before", "WARN")
                except Exception as _fe:
                    log(f"[flip] the transaction was refused and the fallback "
                        f"read also failed ({type(_fe).__name__}) — "
                        f"proceeding, as before", "WARN")
            if flip_outcome and flip_outcome.startswith("skipped(") and flip_outcome.endswith(")"):
                actual_status = flip_outcome[len("skipped("):-1]
                if actual_status in BAIL_STATUSES:
                    should_run = False
                    # 2026-05-11: flag bail as errored so the queue gate
                    # short-circuits on the next dequeue. Without this,
                    # a bail on paused_backend_restart* (which is NOT in
                    # the gate's terminal status set) would wedge the
                    # next gate for the full 4200s fallback.
                    _QUEUE_STATE["_errored"] = True
                    log(f"[worker] Bailing on job — actual_status={actual_status} (terminal/recovery), skipping run_pipeline to spare sibling browsers", "INFO")
                else:
                    log(f"[worker] Proceeding despite skipped flip — actual_status={actual_status} is active (FE pre-flipped or normal mid-run resume)", "INFO")
            try:
                if should_run:
                    # Fix D (2026-05-27): ACTIVE-TIME-aware outer ceiling. The
                    # old asyncio.wait_for counted raw wall-clock, so a run
                    # that legitimately waited on a user decision (or was
                    # paused) got mislabeled "stuck" and killed at the 5h mark.
                    # Run run_pipeline as a task and only accrue toward the
                    # ceiling while it's doing ACTIVE work — never while
                    # _controls.is_pause() (HV/login/user pause) or
                    # _controls._awaiting_user (blocked on await_phase_decision).
                    # Genuine active-spin deadlocks still trip it. _controls is
                    # a per-PROCESS singleton (reset in place, never rebound),
                    # so each worker is independently guarded ⇒ N-worker safe.
                    # On breach we raise asyncio.TimeoutError, reusing the
                    # existing handler below unchanged.
                    _pipe_task = asyncio.ensure_future(
                        run_pipeline_captured(topic=job["topic"], email=job.get("email", ""),
                                     verbose=True, resume_dir=job.get("resume_dir"),
                                     config=job.get("config"), run_id=job.get("run_id"),
                                     uid=job.get("uid"), research_id=job.get("research_id"),
                                     _submitted_by=job.get("submitted_by"),
                                     brief_text=job.get("brief_text", ""),
                                     user_sources=job.get("user_sources") or [],
                                     user_links=job.get("user_links") or []))
                    _wd_active_sec = 0.0
                    _wd_tick = 10.0
                    while not _pipe_task.done():
                        try:
                            await asyncio.sleep(_wd_tick)
                        except asyncio.CancelledError:
                            # Worker loop / server shutting down — cancel the
                            # pipeline and propagate (drain with BaseException
                            # so its finally blocks run first).
                            _pipe_task.cancel()
                            try:
                                await _pipe_task
                            except BaseException:
                                pass
                            raise
                        if not (_controls.is_pause() or _controls._awaiting_user):
                            _wd_active_sec += _wd_tick
                        if _wd_active_sec >= WORKER_OUTER_TIMEOUT_SEC and not _pipe_task.done():
                            _pipe_task.cancel()
                            # Drain with BaseException (CancelledError is
                            # BaseException-derived since 3.8) so run_pipeline's
                            # finally blocks (browser close, etc.) complete
                            # before we raise — mirrors asyncio.wait_for's own
                            # cancel-then-await semantics.
                            try:
                                await _pipe_task
                            except BaseException:
                                pass
                            raise asyncio.TimeoutError(
                                f"pipeline exceeded {WORKER_OUTER_TIMEOUT_SEC}s active-time ceiling")
                    # Natural completion: surface result / re-raise any
                    # run_pipeline exception exactly as asyncio.wait_for did
                    # (the except Exception handler below catches it).
                    await _pipe_task
            except asyncio.TimeoutError:
                # Q7 outer-ceiling deadlock guard. Mark the doc, request
                # cooperative stop, schedule hard exit. Daemon-loop
                # respawns a fresh worker; pending jobs drain on the
                # next process.
                hours = WORKER_OUTER_TIMEOUT_SEC // 3600
                log(f"[worker-watchdog] Pipeline exceeded {hours}h ACTIVE-time ceiling (excludes paused / user-decision waits) — declaring stuck and scheduling restart", "ERROR")
                # The verdict has to reach the run's own folder, or the bundle
                # shows a run that merely "errored" with no cause named.
                _patch_run_log_status("watchdog", watchdogCeilingSec=WORKER_OUTER_TIMEOUT_SEC)
                try:
                    _controls.request_stop()
                except Exception:
                    pass
                if _firebase_db and job.get("uid") and job.get("research_id"):
                    _update_research_doc(job["uid"], job["research_id"], {
                        "status": "stopped_by_watchdog",
                        "summary": f"Stopped — pipeline exceeded {hours}h ceiling",
                    })
                # 2026-05-11: error path — daemon-restart will reset
                # _QUEUE_STATE anyway, but flag for completeness.
                _QUEUE_STATE["_errored"] = True
                _schedule_server_exit("worker-watchdog")
            except Exception as e:
                log(f"Pipeline job error: {e}", "ERROR")
                # 2026-05-11: error path — flag so the next dequeue's
                # gate doesn't block waiting for FE-P5 on a run that
                # will never reach it.
                _QUEUE_STATE["_errored"] = True
            finally:
                # Capture before clearing — `current_job` is the job that
                # just finished. We need its uid+rid to clear stale queue
                # fields below; `_recompute_queue_positions` only patches
                # the *remaining* queued docs, not the one that just left.
                completed = _QUEUE_STATE.get("current_job") or {}
                _QUEUE_STATE["running"] = False
                _QUEUE_STATE["current_job"] = None
                # Release multi-worker claim sentinel. Best-effort —
                # stale locks from process kills are caught by
                # _scan_sibling_locks_for_research's PID-liveness + 8h
                # started_at-age guards.
                _delete_worker_lock(WORKER_ID)
                # Clear currentRunId on device doc — release the "device
                # is busy" signal so the next submitter's FE doesn't think
                # we're still mid-run. Best-effort. Shared helper covers
                # all exit paths (STOP / hard_reset / watchdog / etc.)
                # too via _schedule_server_exit at research.py:_schedule_server_exit
                # 2026-05-22).
                _clear_current_run_id_best_effort("job-finally")
                # 2026-05-11: record what the next dequeue's gate needs.
                # last_be_done_at=0 on error/watchdog paths short-circuits
                # the gate (since FE-P5 will never write "completed").
                _errored = _QUEUE_STATE.pop("_errored", False)
                # 2026-05-15: skip gate-state writes if a hard_reset is
                # in progress. Without this guard, a worker finishing
                # within hard_reset's exit window resurrects the wedged
                # prior-run pointer the user just clicked Reset Backend
                # to escape. The lock acquisition makes the check-and-act
                # atomic w.r.t. hard_reset's clear+persist (research.py:
                # ~1920) — without the lock, a thread schedule between
                # our flag-read and our state-write lets hard_reset's
                # clear land BEFORE our write, and our write resurrects
                # the uid_X we should be discarding.
                _hr_lock = _QUEUE_STATE.get("_hard_reset_lock")
                if _hr_lock is not None:
                    with _hr_lock:
                        if not _QUEUE_STATE.get("_hard_reset_in_progress"):
                            _QUEUE_STATE["last_completed_uid"] = completed.get("uid")
                            _QUEUE_STATE["last_completed_rid"] = completed.get("research_id")
                            _QUEUE_STATE["last_be_done_at"] = 0 if _errored else int(time.time() * 1000)
                else:
                    # Lock not initialised yet (impossible at runtime: the
                    # worker only runs inside run_server, which sets up
                    # the lock at research.py:~24058 before launching the
                    # worker — kept as belt-and-braces).
                    _QUEUE_STATE["last_completed_uid"] = completed.get("uid")
                    _QUEUE_STATE["last_completed_rid"] = completed.get("research_id")
                    _QUEUE_STATE["last_be_done_at"] = 0 if _errored else int(time.time() * 1000)
                _job_queue.task_done()
                # Clear the just-finished job's queue tracking fields from
                # Firestore. `_flip_queued_to_ongoing` already deletes
                # these on the queued→ongoing flip (:20869-20874), but if
                # the worker raced through completion before the listener
                # delivered the "ongoing" intermediate frame — or the run
                # errored / was watchdog-stopped without the flip running
                # — the doc retains stale `queuePosition` /
                # `queuedBehindRunId` / `queuedBehindTitle`. Reopening the
                # chat then wedges QueuedBanner because liveStatus reads
                # them as still-queued. Idempotent on already-cleared docs.
                _cuid, _crid = completed.get("uid"), completed.get("research_id")
                if _firebase_db and _cuid and _crid:
                    from google.cloud.firestore import DELETE_FIELD as _DF
                    _update_research_doc(_cuid, _crid, {
                        "queuePosition": _DF,
                        "queuedBehindRunId": _DF,
                        "queuedBehindTitle": _DF,
                    })
                # Shift remaining queued jobs up one position.
                _recompute_queue_positions()
                # Re-snapshot post-completion (current cleared, pending may
                # have been cancelled/reordered).
                # 2026-05-15: re-check the hard-reset flag under the same
                # lock as hard_reset's clear+persist. Without the lock, a
                # hard_reset can fire between our flag-check and our
                # persist, and we'd snapshot stale memory to disk AFTER
                # hard_reset already wrote a clean snapshot — racing past
                # the very write the lock was added to protect.
                _hr_lock2 = _QUEUE_STATE.get("_hard_reset_lock")
                if _hr_lock2 is not None:
                    with _hr_lock2:
                        if not _QUEUE_STATE.get("_hard_reset_in_progress"):
                            _persist_pending_queue(current_job=None)
                else:
                    _persist_pending_queue(current_job=None)
                # Multi-worker idle rescan (2026-05-21). If a sibling
                # worker was busy when a queue doc arrived AND so was I,
                # the on_snapshot listener gated both of us → doc orphaned
                # in devices/{deviceId}/queue/ with no assignedWorker.
                # Now that I'm idle, check for unclaimed docs and pick
                # one up. No-op in single-worker mode. Fire-and-forget —
                # the worker's next loop iteration awaits _job_queue.get()
                # which the rescan's _safe_enqueue feeds.
                try:
                    asyncio.create_task(_rescan_queue_for_unclaimed())
                except Exception as _re:
                    log(f"[idle-rescan] launch failed (non-fatal): {_re}", "WARN")

    # Worker + Firestore start listener are launched below in the direct
    # startup path (before `await server.serve()`). We used to ALSO register
    # an `@app.on_event("startup")` handler that did the same thing as a
    # belt-and-suspenders fallback — but FastAPI did fire it, and the result
    # was TWO concurrent `_job_worker` tasks. Queue #2 got popped by worker
    # B while worker A was still running #1, a second Browser(PROFILE_DIR)
    # was instantiated, and Browser.start()'s orphan-Chrome sweep killed
    # #1's browser mid-flight. Single-worker startup is now the only path.

    @app.get("/api/queue")
    async def get_queue_status():
        """Get queue status: current job + pending count."""
        return {"running": bool(_QUEUE_STATE.get("running")), "pending": _job_queue.qsize()}

    @app.get("/api/health")
    async def health_check():
        """Server health check. Q8: includes lastHeartbeatAt (millis since
        epoch) + consecutive heartbeat failure count so the FE can sanity-
        check 'device offline despite localhost responsive' cases. The
        Account-tile online indicator reads Firestore lastHeartbeat — if
        Firestore writes are failing but local HTTP is fine, this endpoint
        shows the disparity directly."""
        return {
            "status": "ok",
            "running": bool(_QUEUE_STATE.get("running")),
            "pending": _job_queue.qsize(),
            "lastHeartbeatAt": _last_heartbeat_at_ms,
            "heartbeatFailures": _heartbeat_failures,
            # #717 — supervisor watchdog signals. lastTickAt is a per-worker
            # liveness pulse (every worker bumps it via _firebase_reconnect_loop),
            # so the watchdog spots a wedged event loop on ANY worker — not just
            # worker 1 (the only one that writes lastHeartbeatAt). `relinking`
            # tells the watchdog this worker is in a legit up-to-15-min revoke
            # relink poll and must not be force-respawned.
            "lastTickAt": _last_loop_tick_ms,
            "downReason": _firebase_down_reason,
            "relinking": _firebase_down_reason == "revoked",
        }

    @app.patch("/api/runs/{run_id}/config")
    async def update_config(run_id: str, request_data: dict):
        """Update pipeline config mid-run. Pipeline checks config.json before each phase."""
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)
        config_path = queue / "config.json"
        try:
            existing = json.loads(config_path.read_text(encoding="utf-8")) if config_path.exists() else {}
        except Exception:
            existing = {}
        existing.update(request_data)
        config_path.write_text(json.dumps(existing, indent=2), encoding="utf-8")
        # Forward to in-memory controls (for mid-phase config awareness)
        _controls.update_config(existing)
        # Emit to Firestore pipeline_events so frontend gets it
        emit_event("config_updated", config=existing)
        return {"status": "config_updated", "id": run_id, "config": existing}

    @app.delete("/api/runs/{run_id}")
    async def delete_run(run_id: str):
        """Delete a completed/stopped run's queue dir + cascade-delete the
        matching Firestore documents/audios/messages/pipeline_events/
        commands subcollections. Without the cascade, partial docs from
        failed runs would linger in Firestore forever."""
        import shutil
        queue = queues_root / run_id
        if not queue.exists():
            return JSONResponse({"error": "not found"}, 404)

        # ── Cascade Firestore cleanup before nuking the owner file ──
        owner_path = queue / "owner.json"
        if owner_path.exists() and _firebase_db:
            try:
                owner = json.loads(owner_path.read_text(encoding="utf-8"))
                uid = owner.get("uid")
                rid = owner.get("researchId")
                if uid and rid:
                    research_ref = _firebase_db.collection("users").document(uid) \
                        .collection("researches").document(rid)
                    # Delete known subcollections. Firestore requires enumerating
                    # docs and deleting individually — no native recursive delete
                    # in the Python SDK's positional-arg API.
                    for sub in ("documents", "audios", "messages",
                                "pipeline_events", "commands"):
                        try:
                            for sd in research_ref.collection(sub).stream():
                                try:
                                    # #720: only the deviceMemberOf-gated `commands`
                                    # delete is heal-eligible; the rest are owner-only.
                                    if sub == "commands":
                                        _grpc_write_with_heal(
                                            lambda sd=sd: sd.reference.delete(),
                                            what="delete_run cmd delete")
                                    else:
                                        sd.reference.delete()
                                except Exception: pass
                        except Exception as _se:
                            log(f"[delete_run] subcollection {sub} sweep: {_se}", "WARN")
                    # Finally drop the research doc itself
                    try: research_ref.delete()
                    except Exception as _rde:
                        log(f"[delete_run] research doc delete: {_rde}", "WARN")
                    log(f"[delete_run] cascaded Firestore for users/{uid}/researches/{rid}")
            except Exception as _oe:
                log(f"[delete_run] owner.json parse failed: {_oe}", "WARN")

        try:
            shutil.rmtree(queue)
        except Exception as e:
            return JSONResponse({"error": str(e)}, 500)
        return {"status": "deleted", "id": run_id}

    @app.post("/api/runs")
    async def start_run(request_data: dict):
        """Start a new pipeline run. Queued if another is already running.
        Body: {topic, email?, briefText?, config?: {agents, skipPhases, videoEnabled, emailEnabled}}

        briefText: inline brief content that bypasses Phase 1 brief generation.
        When provided, Phase 1 is skipped and Phase 2 runs against this brief."""
        topic = request_data.get("topic")
        if not topic or not topic.strip():
            return JSONResponse({"error": "topic is required"}, 400)
        topic = topic.strip()
        email = request_data.get("email", "")
        uid = request_data.get("uid", "")  # Firebase user ID for Firestore bridge
        config = request_data.get("config", {})
        brief_text = (request_data.get("briefText") or "").strip()
        # Validate config
        agents_cfg = config.get("agents", {"chatgpt": True, "gemini": True, "claude": True})
        if not any(agents_cfg.values()):
            return JSONResponse({"error": "at least one agent must be enabled"}, 400)
        from datetime import datetime as _dt
        run_id = f"{safe_name(topic)}_{_dt.now().strftime('%Y%m%d_%H%M%S')}"
        await _job_queue.put({"topic": topic, "email": email, "config": config,
                              "run_id": run_id, "uid": uid, "brief_text": brief_text})
        position = _job_queue.qsize()
        is_running = bool(_QUEUE_STATE.get("running"))
        status = "running" if position <= 1 and not is_running else f"queued (position {position})"
        return {"status": status, "topic": topic, "queue_position": position, "id": run_id}

    @app.get("/api/runs/{run_id}/documents/{doc_type}")
    async def get_document(run_id: str, doc_type: str):
        """Get document content. doc_type: brief, chatgpt, gemini, claude."""
        # All documents live in documents/ (brief included)
        path = queues_root / run_id / "documents" / f"{doc_type}.md"
        if not path.exists():
            path = queues_root / run_id / f"{doc_type}.md"  # Legacy fallback
        if not path.exists():
            return JSONResponse({"error": "not found"}, 404)
        content = path.read_text(encoding="utf-8")
        return {
            "type": doc_type,
            "name": f"{doc_type}.md",
            "size": f"{len(content) / 1024:.0f} KB",
            "content": content,
        }

    @app.get("/api/runs/{run_id}/audio/{filename}")
    async def get_audio(run_id: str, filename: str):
        """Serve audio file from podcasts directory."""
        from fastapi.responses import FileResponse as _FileResponse
        # Sanitize filename to prevent path traversal
        safe = Path(filename).name
        path = queues_root / run_id / "podcasts" / safe
        if not path.exists():
            return JSONResponse({"error": "audio not found"}, 404)
        mime_map = {".m4a": "audio/mp4", ".mp3": "audio/mpeg",
                    ".wav": "audio/wav", ".webm": "audio/webm"}
        media_type = mime_map.get(path.suffix.lower(), "application/octet-stream")
        return _FileResponse(str(path), media_type=media_type, filename=safe)

    # ── The crown comes FIRST, like every other subcommand ──────────────────
    # `--help` puts SUPER RESEARCH on line 4. Before this, `--serve` put it on
    # line 26 — behind the route dump, Firestore init, six background loops,
    # queue rehydration and the device-command listener. Serve was the ONE
    # command where the wordmark was buried mid-scroll, which is what made it
    # read as a different program from the rest of the set.
    #
    # The banner is therefore two beats, not one:
    #   1. here — the wordmark + a dim preview of the boot arc (the same shape
    #      as --pair's "Five steps: …" line), printed before any work;
    #   2. after init — the identity strip (Paired to / Device / Local API),
    #      which CANNOT move up: it reads the device doc, so it needs Firestore
    #      to be live. `_serve_boot_preview` is what bridges the two, so the
    #      strip lands as a deliberate second beat instead of an orphan block.
    _branded_header("aegis", _BOLD + _ACCENT, "standing watch")
    _serve_boot_preview(port)
    # Banner shows localhost so users can copy-click; uvicorn still binds
    # to 0.0.0.0 below so the FE web app can reach this BE.
    log(f"Starting API server on http://localhost:{port}")
    # ⭐ 2026-08-17 — WHERE THE BLOCK CAME FROM, asked once at the earliest point
    # the app owns. The arm-time check runs AFTER Firestore, gRPC, four watchers
    # and uvicorn, so on its own it cannot tell an INHERITED block (the launcher,
    # the shell, the terminal) from one this startup installs. Two lines split
    # that in half, and this mystery has already survived four attempts at it.
    # Silent unless something is actually blocked — a healthy boot says nothing.
    _log_blocked_stop_signals_at("startup")
    # #930: log the loaded build so "worker running stale code" is a one-grep
    # diagnosis from backend.log (2026-07-09: a worker up since the prior day
    # ran pre-fix code through a live E2E and the report read as a regression).
    # Source checkouts only — compiled wheels have no .git; stay silent then.
    try:
        _build = subprocess.run(
            ["git", "-C", str(Path(__file__).resolve().parent), "log", "-1",
             "--format=%h %cd %s", "--date=format:%Y-%m-%d %H:%M"],
            capture_output=True, text=True, timeout=5,
            creationflags=_PS_NO_WINDOW).stdout.strip()
        if _build:
            log(f"[build] {_build}")
    except Exception:
        pass
    # ⛔⛔ THE SEARCH PATH, ONCE PER BOOT, and it had never been written down
    # anywhere. Every subprocess this worker starts inherits it, the supervisor
    # bakes it tool-homes-first on purpose, and until now a support bundle from a
    # machine where the wrong `ffmpeg` won contained nothing that could show it.
    # Next to `[build]` because they answer the same kind of question: what is
    # this worker actually running.
    try:
        for _pl in _search_path_report():
            log(_pl)
    except Exception:
        pass
    # The six-line route table that used to print here moved to `--help`'s
    # "Local API" section (`_LOCAL_API_ROUTES`). It was a REFERENCE pushed
    # through the timestamped logger — `[HH:MM:SS] [INFO]   GET /api/runs …` —
    # which no other subcommand does, and `manuale` is the reference surface.
    # Nothing consumed it from the log: it is static text, identical on every
    # boot, so it cost six lines of boot narrative and told an operator nothing
    # about THIS run.
    # Start worker directly (don't rely on @app.on_event which is deprecated and
    # sometimes doesn't fire reliably with newer FastAPI versions)
    # Initialize Firebase Admin SDK for Firestore bridge
    if sys.stdout and sys.stdout.isatty():
        async with _async_spinner_ctx("Connecting to Firestore"):
            await asyncio.to_thread(init_firebase)
    else:
        # Non-TTY (supervisor/pipe): the spinner can't animate, so emit one
        # static progress line — otherwise the ~10-15s cold gRPC init is a
        # silent gap that reads as "stuck". (F/RC-22)
        log("Connecting to Firestore…")
        await asyncio.to_thread(init_firebase)
    # Load run analytics for realistic ETAs
    load_analytics()
    # Track D: device identity loads via load_device_id() / the OS
    # keystore. No legacy researchToken to fetch here — if init_firebase
    # already failed, the user needs to run --pair first.
    # 2026-05-11: hoist queue-gate state rehydration above worker
    # creation. The full disk-restore block at the bottom of serve
    # (rehydrates pending + current_job) runs much later, after the
    # Firestore start listener has already enqueued docs. If the
    # worker had been created first, it could dequeue a Firestore-
    # rehydrated job and call _wait_for_prior_fe_completion() with
    # fresh-init _QUEUE_STATE (last_completed_uid=None → gate skips)
    # BEFORE the disk snapshot's gate sub-object lands. That'd race
    # the first post-restart pipeline against the previous run's
    # in-flight FE-P5. Pure dict mutation here — no I/O dependency on
    # the later block.
    try:
        if _pending_queue_path.exists():
            _snap = json.loads(_pending_queue_path.read_text(encoding="utf-8"))
            _gate = _snap.get("gate") or {}
            _gate_uid = _gate.get("last_completed_uid")
            _gate_rid = _gate.get("last_completed_rid")
            if _gate_uid and _gate_rid:
                # Orphan detection — three cases get treated as terminal so
                # the gate doesn't wedge the next submission:
                #   (a) Prior research doc DELETED (user purged it from
                #       /researches → snap.exists False).
                #   (b) Prior status is non-terminal ("queued"/"ongoing")
                #       → BE crashed mid-run; without a worker to
                #       advance it, the status never becomes terminal.
                #   (c) Read failed entirely (network, transient denial)
                #       → safer to release than wedge for 70 min.
                # In every case we drop the gate-state IN-MEMORY *and* on
                # disk; otherwise the next BE restart's rehydrate re-loads
                # the same zombie pointer and the wedge re-engages.
                _is_orphan = False
                _orphan_reason = ""
                if _firebase_db:
                    try:
                        _prior_snap = _firebase_db.collection("users") \
                            .document(_gate_uid).collection("researches") \
                            .document(_gate_rid).get()
                        if not _prior_snap.exists:
                            _is_orphan = True
                            _orphan_reason = "doc deleted"
                        else:
                            _prior_status = (_prior_snap.to_dict() or {}).get("status", "")
                            # Terminal-non-success statuses also qualify as
                            # orphan: a prior run that errored / stopped /
                            # was watchdog-killed never reaches FE-P5
                            # (Phase 4 + 5 only run on a clean BE finish),
                            # so the queue-gate's wait-for-prior-FE-P5
                            # would block forever (BE_PHASES_TIMEOUT_SEC =
                            # 4200s fallback). Treat them like queued/
                            # ongoing — clear the gate so the next run
                            # can dequeue. Pre-fix the gate wedged every
                            # new submission with "waiting for prior run
                            # … FE-P5 completion" for 70 minutes whenever
                            # the prior run hit any failure path.
                            if _prior_status in (
                                "queued", "ongoing",
                                "error", "errored", "stopped",
                            ):
                                _is_orphan = True
                                _orphan_reason = f"status={_prior_status}"
                    except Exception as _orphan_check_err:
                        log(f"[queue-gate] orphan-check read failed — treating as orphan: {_orphan_check_err}", "DEBUG")
                        _is_orphan = True
                        _orphan_reason = "read failed"
                if _is_orphan:
                    log(f"[queue-gate] prior-run {_gate_rid[:8]}… orphaned ({_orphan_reason}) — clearing gate state")
                    # Best-effort status flip (will silently 403 for legacy
                    # research docs without a deviceId field, since
                    # deviceUpdatingFor requires resource.data.deviceId match;
                    # don't depend on it).
                    try:
                        _update_research_doc(_gate_uid, _gate_rid, {
                            "status": "stopped",
                            "lastError": "Backend restarted before this run reached completion. Resubmit to retry.",
                        })
                    except Exception:
                        pass
                    # Drop gate state both in memory AND on disk so next
                    # restart doesn't re-engage the wedge.
                    _QUEUE_STATE["last_completed_uid"] = None
                    _QUEUE_STATE["last_completed_rid"] = None
                    _QUEUE_STATE["last_be_done_at"] = 0
                    try:
                        _clean = {**_snap, "gate": {
                            "last_completed_uid": None,
                            "last_completed_rid": None,
                            "last_be_done_at": 0,
                        }}
                        _tmp = _pending_queue_path.with_suffix(".json.tmp")
                        _tmp.write_text(json.dumps(_clean, indent=2), encoding="utf-8")
                        os.replace(str(_tmp), str(_pending_queue_path))
                    except Exception as _persist_err:
                        log(f"[queue-gate] orphan-clear persist failed (continuing): {_persist_err}", "WARN")
                else:
                    _QUEUE_STATE["last_completed_uid"] = _gate_uid
                    _QUEUE_STATE["last_completed_rid"] = _gate_rid
                    _QUEUE_STATE["last_be_done_at"] = int(_gate.get("last_be_done_at") or 0)
                    log(f"[queue-gate] pre-worker rehydrate: prior-run {_gate_rid[:8]}…")
    except Exception as _e:
        log(f"[queue-gate] pre-worker rehydrate failed (non-fatal): {_e}", "WARN")

    worker_task = asyncio.create_task(_job_worker())
    log("Job worker started (direct)")
    # Firestore start listener — must fire exactly once per serve session.
    # This used to live inside an @app.on_event("startup") handler alongside
    # a second _job_worker create_task; that duplicated the worker and caused
    # the queue race where #2 killed #1's browser mid-run. Single-start here.
    if _firebase_db:
        start_firestore_start_listener(_job_queue, asyncio.get_event_loop())
    # Reset-recovery watcher. Armed unconditionally so a post-Reset
    # boot (keystore wiped → init_firebase returned False above) can
    # still auto-relink the moment the owner enters the new code at
    # Account → Add Device. Loop is idle while _firebase_db is set.
    asyncio.create_task(_revoked_recovery_loop())
    # Transient-outage reconnect watcher (#717/#718). Armed unconditionally on
    # EVERY worker so a dropped Firestore client (DNS/network blip) self-heals on
    # a tight backoff — no manual restart, no 1-hour-cap wait. Idle while
    # _firebase_db is set. After any reconnect it schedules a clean respawn (when
    # idle) so the fresh boot re-binds every Firestore listener.
    asyncio.create_task(_firebase_reconnect_loop())
    # Start heartbeat so frontend can show Online/Offline status.
    # Multi-worker (2026-05-21): only worker 1 heartbeats. FE only needs
    # a single "device alive" signal and devices/{deviceId}.lastHeartbeat
    # is a single field — both workers writing it would double the
    # Firestore RPC rate for no FE benefit. If worker 1 dies but worker
    # 2 survives, the heartbeat goes stale and FE flips Offline; that's
    # accurate from the FE's perspective because there's no longer a
    # primary serve binding port 8000.
    heartbeat_task = None
    if _firebase_db and WORKER_ID == 1:
        heartbeat_task = asyncio.create_task(_heartbeat_loop())
        log(f"Heartbeat started ({HEARTBEAT_INTERVAL_SEC}s interval)")

    if _firebase_db:
        # Aegis pulse — slow standing-watch heartbeat in the log every 60s
        # while the queue is idle. Suppressed during active pipeline runs (the
        # job worker is already chatty). Per-worker (each prefixed with its ID)
        # so a tail of any worker's log shows liveness. The pulse itself now
        # alternates COLOUR rather than the glyph — see `_aegis_pulse_line`,
        # which owns that decision so a test can assert it without a 60s wait.
        # Supervision pulse: a fixed-cadence heartbeat about the machine's own
        # watch state, with no run in it at any point.
        @_machine_logged
        async def _aegis_pulse_loop():
            i = 0
            # ⛔⛔ THE TICK STAYS AT 60s AND THE EMISSION WIDENS. Those are two
            # different decisions and collapsing them would be a bug: the state
            # check is what notices a broken watch, so slowing the TICK would
            # delay the alarm this loop exists to raise. `Suppressor` restarts
            # its cadence the moment the state string changes, so a transition
            # up→down speaks on the very next tick however quiet it had become.
            _quiet = logquiet.Suppressor()
            _last_state = None
            _state_since = time.time()
            try:
                while True:
                    await asyncio.sleep(60)
                    if _QUEUE_STATE.get("running"):
                        # A run is in flight and the job worker is already
                        # chatty. Skipped WITHOUT consulting the suppressor, so a
                        # two-hour run does not read as a state change and reset
                        # the cadence back to one line a minute afterwards.
                        continue
                    _cut_off = _firebase_db is None
                    _since = _firestore_down_since_ts
                    _state = "down" if _cut_off else "up"
                    if _state != _last_state:
                        _last_state = _state
                        _state_since = time.time()
                    _emit, _dropped = _quiet.consider("aegis-pulse", _state)
                    if not _emit:
                        continue
                    log(_aegis_pulse_line(
                        WORKER_ID, i,
                        down_for=((time.time() - _since) if _since else 0.0)
                        if _cut_off else None,
                        up_for=None if _cut_off else (time.time() - _state_since),
                        suppressed=_dropped,
                    ), "WARN" if _cut_off else "INFO")
                    i += 1
            except asyncio.CancelledError:
                return
        asyncio.create_task(_aegis_pulse_loop())
        # Level-triggered orphan recovery — the multi-worker stale-worker fix.
        # The finally-block `_rescan_queue_for_unclaimed` is EDGE-triggered: it
        # only runs after an IN-PROCESS job completes, and is suppressed entirely
        # on a STOP-scheduled exit. A worker that goes idle via respawn/stop has
        # no completion edge, and Firestore never re-fires ADDED for an already-
        # existing queue doc — so an unclaimed FIFO head would sit forever while
        # that worker blocks on `_job_queue.get()` (the observed "one worker goes
        # stale while the other keeps working"). This standing loop re-offers
        # orphans on a timer so no worker can stand down while claimable head work
        # exists, for ANY worker count. Runs on EVERY worker (not worker-1-only).
        # The rescan it calls is idempotent + CAS-safe (last_update_time
        # precondition) and self-gates on idle/exit/single-worker/FE-gate, so
        # concurrent timers across N workers are safe — at most one wins each doc.
        # ⛔ THE CROSS-PERSON ONE ON THE SWEEP SIDE. It claims orphans belonging
        # to anyone who shares this device and logs each pickup with that
        # person's topic and submitter — a sharer's bundle must not carry those.
        @_machine_logged
        async def _idle_rescan_loop():
            # Base + per-worker jitter so N workers don't scan in lockstep (no
            # thundering-herd of empty-queue reads). ~15-25s recovery latency is
            # fine for this rare path. Single-worker mode is a cheap no-op (the
            # rescan returns immediately on load_worker_count() <= 1).
            BASE_SEC, JITTER_SEC = 15.0, 10.0
            # FIX A2: a leaked `_pending_listener_enqueues` (an inc with no
            # matching dec) permanently arms the busy-defer gate, blocking THIS
            # worker's listener claim path. The periodic rescan recovers orphans
            # regardless, but also self-heal the counter so the listener path is
            # restored. Gate on a tracked idle-since timestamp (NOT first-sight)
            # so we never race the legitimate sub-second window between a listener
            # claim-win (inc) and the worker's running-flip (dec).
            STUCK_COUNTER_RESET_MS = 30_000
            _counter_idle_since = 0
            try:
                while True:
                    await asyncio.sleep(BASE_SEC + random.uniform(0, JITTER_SEC))
                    try:
                        _idle = (
                            not _QUEUE_STATE.get("running")
                            and _job_queue.qsize() == 0
                            and not _QUEUE_STATE.get("gate_pending_job")
                            and not _exit_scheduled
                        )
                        if _idle and _pending_enq_read() > 0:
                            _now_ms = int(time.time() * 1000)
                            if _counter_idle_since == 0:
                                _counter_idle_since = _now_ms
                            elif _now_ms - _counter_idle_since >= STUCK_COUNTER_RESET_MS:
                                log(
                                    f"[idle-rescan] worker {WORKER_ID}: clearing leaked "
                                    f"busy-counter (idle {STUCK_COUNTER_RESET_MS // 1000}s, "
                                    f"pending={_pending_enq_read()})",
                                    "WARN",
                                )
                                _pending_enq_reset()
                                _counter_idle_since = 0
                        else:
                            _counter_idle_since = 0
                        # Level-triggered re-offer. The rescan self-gates on
                        # idle/exit/single-worker/FE-gate, so this is a safe no-op
                        # unless this worker is genuinely idle with an unclaimed
                        # orphan to claim.
                        await _rescan_queue_for_unclaimed()
                    except Exception as _ire:
                        log(f"[idle-rescan-loop] worker {WORKER_ID}: tick error (non-fatal): {_ire}", "WARN")
            except asyncio.CancelledError:
                return
        asyncio.create_task(_idle_rescan_loop())
        log(f"[idle-rescan-loop] worker {WORKER_ID}: started (level-triggered orphan recovery, ~15-25s)")
        # Periodic orphan sweep: existence-based cleanup of local queues/
        # dirs whose Firestore research doc has been deleted. Worker-1
        # only — the queues/ tree is shared across workers and sweep is
        # idempotent; running it N times wastes Firestore RPC budget and
        # opens a small race window where two sweeps could each see the
        # same dir and contend on rmtree.
        if WORKER_ID == 1:
            asyncio.create_task(_orphan_sweep_loop())
            log(f"[orphan-sweep] started ({ORPHAN_SWEEP_INTERVAL_SEC}s interval)")
            asyncio.create_task(_dead_worker_reconcile_loop())
            log(f"[dead-worker-reconcile] started ({DEAD_WORKER_RECONCILE_INTERVAL_SEC}s interval)")
        # Refresh the paired device doc so the Account page sees this PC
        # online immediately on server start.
        paired_uid = load_paired_uid()
        # Boot-clear: release this worker's footprint on the device doc.
        # The helper handles both responsibilities — array_remove'ing
        # THIS WORKER_ID from busyWorkerIds (all workers; powers the FE
        # multi-worker idle signal) AND, for worker-1, clearing the
        # currentRun* mirror fields. Backstop for any exit path that
        # bypassed `_schedule_server_exit` — process SIGKILL, OOM,
        # daemon-loop crash, `--retire` (externally killed). Without
        # this, a stale currentRunId persists into the next session AND
        # a leaked busyWorkerIds entry would make the FE think a worker
        # is busy when it isn't (false-positive on the queue-stall
        # detector's worker-idle check).
        #
        # If a job is auto-resumed by rehydration below, its dequeue at
        # research.py:~26948 will re-write the fields. The 1-15s window
        # between this clear and re-write is invisible to the FE
        # because the cross-user fallback predicate requires
        # `currentRunId` set; cleared state ⇒ fallback not engaged ⇒ no
        # banner.
        _clear_current_run_id_best_effort(f"worker-{WORKER_ID}-boot")
        # #64: this worker reached --serve boot, so it is ALIVE — retract any
        # stale supervisor dead-marker for itself (written if it previously
        # crash-looped). Clearing BEFORE rehydration means worker-1's periodic
        # reconciler won't re-pause the runs this worker is about to recover, so
        # an operator repair needs no manual cleanup step.
        if WORKER_ID >= 2:
            _clear_worker_dead_marker(WORKER_ID)
        # Track every Firestore research_id touched by rehydration — used by
        # the disk-restore block below so an ongoing run that got marked
        # paused_backend_restart isn't falsely re-enqueued from
        # pending_queue.json (would run twice). Hoisted out of the try so
        # the disk-restore block downstream can reference it even if
        # rehydration raised partway through.
        _rehydrated_rids: "set[str]" = set()
        if paired_uid:
            # The heartbeat loop writes lastHeartbeat + status to
            # devices/{deviceId} every 5s, so a startup-side eager write
            # is no longer necessary — the first heartbeat tick (within
            # ~5s of --serve binding the port) brings the Account-page
            # tile online.

            # Queue rehydration: recover mid-run runs from the previous
            # daemon session. Browser/CUA state is gone, so we either
            # mark them paused_backend_restart (FE shows a Resume CTA)
            # or auto-resume on supervised devices (re-enqueue with
            # resume_dir from checkpoint). Queued-status docs are NOT
            # rehydrated here — the on_snapshot listener replays every
            # queue doc as ADDED on first attach and the FIFO pre-query
            # handles them across all submitters (owner + sharers).
            #
            # Per-query 15s wall-clock cap via asyncio.wait_for + to_thread.
            # The sync .get() can hang indefinitely if the gRPC channel got
            # into a bad state (observed once during E2E with the wrong
            # paired_uid synth-vs-owner mismatch). A hung query here blocks
            # the event loop and prevents uvicorn from binding port 8000 ->
            # `--resurrect` handoff fails its API health check.
            #
            # Multi-worker (#966, 2026-07-16): EVERY worker runs the
            # Firestore rehydration, keyed on per-run ownership inside
            # _rehydrate_ongoing_for_tree — each worker auto-resumes the
            # runs IT owns (on its own profile/account) and worker 1 alone
            # marks orphan (out-of-fleet-owner) runs paused. Pre-fix this
            # was worker-1-only, so a sibling-owned run left mid-flight by a
            # fleet-wide respawn got funneled to paused_backend_restart (a
            # needless Resume CTA): worker 1 can't re-open it on its own
            # profile, and the owning worker never scanned Firestore. The
            # re-enqueue race the old gate guarded against is now closed by
            # that ownership check (queued docs aren't rehydrated; each
            # worker only resumes runs it owns) plus the sibling-lock guard.
            # Disk-restore (the per-worker pending_queue_*.json snapshot)
            # stays the gap-filler for runs that never reached status=queued.
            rehydrated = 0
            orphaned = 0
            # #724 item 3 / #725 item 6: surface the flag state at boot so a
            # validation run can confirm BOTH that the new code is loaded
            # (this line exists) AND whether sharer-tree rehydration is armed
            # — removes the PowerShell-`set`-didn't-take ambiguity. Reads
            # env OR research_config.json (the env var didn't propagate to
            # the relaunched daemon; the JSON fallback always does).
            log(f"[rehydration] worker {WORKER_ID}: sharer-rehydration="
                f"{'on' if _sharer_rehydration_enabled() else 'off'} "
                f"(env={os.environ.get('ENABLE_SHARER_REHYDRATION') or 'unset'})", "INFO")
            try:
                # #725 (DRY): owner-tree rehydration delegates to the shared
                # _rehydrate_ongoing_for_tree helper (per-run worker ownership
                # lives inside it). For the owner tree, tree_uid == owner_uid ==
                # paired_uid. The sharer loop and the aggregate log line stay here.
                if sys.stdout and sys.stdout.isatty():
                    async with _async_spinner_ctx("Recovering interrupted runs"):
                        _own_r, _own_o = await _rehydrate_ongoing_for_tree(
                            paired_uid, paired_uid, _rehydrated_rids)
                else:
                    _own_r, _own_o = await _rehydrate_ongoing_for_tree(
                        paired_uid, paired_uid, _rehydrated_rids)
                rehydrated += _own_r
                orphaned += _own_o
                # #724 item 3 (flag-gated): the scan above is OWNER-tree only.
                # A SHARER-submitted run lives in users/{sharer}/researches and
                # was never marked paused_backend_restart on reconnect — it
                # stayed frozen "ongoing" (manual Resume still worked, no passive
                # recovery / no supervised auto-resume). When sharer-rehydration
                # is armed (env var OR research_config.json), also scan each
                # sharer tree via _rehydrate_ongoing_for_tree (which mirrors the
                # owner block above — sibling-lock guard + supervised auto-resume
                # + paused mark; KEEP THE TWO IN SYNC, or migrate the owner path
                # to the helper once this is validated). Per-sharer failures are
                # isolated; the owner recovery already ran regardless.
                if _sharer_rehydration_enabled():
                    _sharers: "list[str]" = []
                    try:
                        _dev_id = load_device_id()
                        if _dev_id:
                            _dd = await asyncio.wait_for(
                                asyncio.to_thread(
                                    lambda di=_dev_id: _firebase_db.collection("devices").document(di).get()
                                ),
                                timeout=10.0,
                            )
                            if _dd.exists:
                                _sharers = [
                                    s for s in ((_dd.to_dict() or {}).get("sharedWith") or [])
                                    if s and s != paired_uid
                                ]
                    except Exception as _se:
                        log(f"[rehydrate:sharers] sharedWith read failed ({_se}) — owner-only rehydration", "WARN")
                    async def _scan_sharer_trees():
                        nonlocal rehydrated, orphaned
                        for _sharer_uid in _sharers:
                            try:
                                _sr, _so = await _rehydrate_ongoing_for_tree(_sharer_uid, paired_uid, _rehydrated_rids)
                                rehydrated += _sr
                                orphaned += _so
                            except Exception as _she:
                                log(f"[rehydrate:sharers] tree {_sharer_uid[:12]}… scan failed ({_she}) — skipping", "WARN")
                    if _sharers and sys.stdout and sys.stdout.isatty():
                        async with _async_spinner_ctx(f"Recovering interrupted runs ({len(_sharers)} devices)"):
                            await _scan_sharer_trees()
                    else:
                        await _scan_sharer_trees()
                    if _sharers:
                        log(f"[rehydrate:sharers] scanned {len(_sharers)} sharer tree(s) (sharer-rehydration armed)")
                if rehydrated or orphaned:
                    log(f"Queue rehydration: auto-resumed {rehydrated} supervised run(s), marked {orphaned} as paused_backend_restart")
            except Exception as e:
                log(f"Queue rehydration failed: {e}", "WARN")

        # ── pending_queue.json restoration (Phoenix T3 fallback) ──────────
        # Firestore-driven rehydration above is the source of truth, but a
        # research that hadn't yet reached `status=queued` (e.g. crashed in
        # the put_nowait → Firestore-write window) won't appear there. The
        # disk snapshot covers that gap. Dedupe by research_id so we don't
        # double-enqueue something Firestore already restored — including
        # ongoing runs that got marked paused_backend_restart and shouldn't
        # silently re-launch from a stale disk snapshot.
        try:
            if _pending_queue_path.exists():
                snap = json.loads(_pending_queue_path.read_text(encoding="utf-8"))
                # 2026-05-11: rehydrate queue-gate state so the worker
                # gate respects a still-in-flight FE-P5 across daemon
                # restart. The "gate" key was added 2026-05-11; legacy
                # snapshots without it default to empty (gate becomes a
                # no-op for that one boot — same as fresh start).
                _gate = snap.get("gate") or {}
                if _gate.get("last_completed_uid"):
                    _QUEUE_STATE["last_completed_uid"] = _gate.get("last_completed_uid")
                    _QUEUE_STATE["last_completed_rid"] = _gate.get("last_completed_rid")
                    _QUEUE_STATE["last_be_done_at"] = int(_gate.get("last_be_done_at") or 0)
                    log(f"[queue-gate] rehydrated prior-run state for {(_gate.get('last_completed_rid') or '')[:8]}…")
                # Seed dedupe with anything Firestore-rehydration touched
                # (ongoing-status only — queued docs are handled by the
                # listener, not rehydration), then add what's currently
                # in the in-memory queue (auto-resumed supervised runs).
                already = set(_rehydrated_rids)
                try:
                    for q in list(_job_queue._queue):
                        rid = (q or {}).get("research_id") or ""
                        if rid:
                            already.add(rid)
                except Exception:
                    pass
                # Restore current_job FIRST if it was mid-flight (so it
                # resumes ahead of pending). Then the rest of pending in
                # original order.
                cur = snap.get("current") or None
                disk_jobs = []
                if cur and (cur.get("research_id") or "") not in already:
                    disk_jobs.append(cur)
                for j in (snap.get("pending") or []):
                    rid = (j or {}).get("research_id") or ""
                    if rid and rid in already:
                        continue
                    disk_jobs.append(j)
                # Funnel each disk-restored job through _safe_enqueue
                # (Q7) — it does the same Firestore existence check the
                # Q1 inline loop did, plus a status-whitelist. Fail-closed
                # posture is preserved (helper skips on missing/error/no-firebase
                # rather than re-fire). The skipped-count is rolled up;
                # per-job reasons are in the helper's own logs.
                # #728: TIGHTER whitelist for the boot disk-restore —
                # ("queued","ongoing") EXCLUDING paused_backend_restart. A run
                # worker-1's rehydration just marked paused_backend_restart is
                # intentionally awaiting a user Resume; auto-relaunching it from a
                # stale per-worker disk snapshot would double-handle it (and on a
                # sibling worker whose `_rehydrated_rids` never saw it, this is the
                # only cross-worker guard). Genuinely-ongoing runs still restore.
                restored = 0
                skipped = 0
                for j in disk_jobs:
                    if _safe_enqueue(_job_queue, j, source="disk-restore",
                                     allowed_statuses=("queued", "ongoing")):
                        restored += 1
                    else:
                        skipped += 1
                if restored or skipped:
                    log(f"[pending_queue] Disk snapshot processed: restored={restored}, skipped={skipped}")
                else:
                    log("[pending_queue] Disk snapshot empty — nothing to restore")
        except Exception as e:
            log(f"[pending_queue] restore failed: {e}", "WARN")

        # Device-scoped command channel — receives hard_reset and any
        # future device-level controls (vs research-scoped commands which
        # ride users/{uid}/researches/{rid}/commands). Listener lives for
        # the lifetime of --serve. Best-effort: if the device isn't
        # paired yet, this no-ops; the next --serve restart after pairing
        # will pick it up.
        try:
            _paired_uid_for_cmds = load_paired_uid() or ""
            _device_id_for_cmds = load_device_id() or ""
            if _paired_uid_for_cmds and _device_id_for_cmds:
                _start_device_command_listener(
                    _paired_uid_for_cmds,
                    _device_id_for_cmds,
                    loop=asyncio.get_event_loop(),
                )
        except Exception as _dce:
            log(f"[device-cmds] listener attach failed: {_dce}", "WARN")

        # ⭐ REGISTERED AT BOOT, because the reconnect loop cannot build this
        # itself. Re-binding the two long-lived watches needs the job queue, the
        # event loop and the paired identity, and all three are locals of this
        # boot path — which is precisely why the old recovery was a whole-process
        # respawn: re-running boot was the only way anyone had to reach them.
        #
        # A closure keeps them without widening any signature, and it is what
        # lets a FOREGROUND serve recover from a Firestore outage without exiting
        # the session the user is sitting in front of. See
        # `_recover_after_reconnect`.
        try:
            global _watch_rebinder
            _rb_uid = load_paired_uid() or ""
            _rb_device = load_device_id() or ""
            _rb_loop = asyncio.get_event_loop()
            _watch_rebinder = lambda: _rebind_firestore_watches(  # noqa: E731
                _job_queue, _rb_loop, _rb_uid, _rb_device,
            )
        except Exception as _rbe:
            # Not fatal: without a rebinder a foreground serve stays up with
            # stale listeners and says so, which is strictly better than the
            # os._exit it replaced.
            log(f"[reconnect] could not register listener rebinder: {_rbe}", "WARN")

    # ── Beat 2 of the --serve banner: the identity strip ────────────────────
    # Shows which account this backend is paired to, where it's listening, and
    # how to tear it down. The wordmark is NOT re-printed here — it now leads
    # the command (see `_serve_boot_preview`'s caller), matching --pair /
    # --resurrect / --retire, which all open with the crown.
    #
    # The advisory pre-bind port probe used to sit BETWEEN this strip and the
    # "Listening for pipeline jobs" footer, so on any busy-port boot its WARN
    # tore the banner in half — observed live. It runs before the strip now:
    # the finding it reports is about the port, which the strip is about to
    # print, so earlier is also the more useful place for it.
    #
    # This used to be advisory: it noticed the port was busy, said "binding
    # anyway", and left uvicorn to fail with a raw errno. It knew, and let the
    # confusing failure happen regardless. It now RESOLVES the conflict — see
    # `_reclaim_port` — clearing a stale copy of ourselves and refusing, by name,
    # for anything that is not ours.
    try:
        _port_state, _port_holders_found = await asyncio.to_thread(_reclaim_port, port)
    except Exception as _pe:
        log(f"[serve] port check failed ({_pe}) — continuing to bind", "WARN")
        _port_state, _port_holders_found = "free", []

    if _port_state == "foreign":
        _who = "; ".join(
            f"pid {h['pid']} ({h['name']}{': ' + h['cmd'][:70] if h['cmd'] else ''})"
            for h in _port_holders_found) or "an unidentified process"
        print(f"[serve] bind refused: port {port} is in use by {_who}",
              file=sys.stderr, flush=True)
        print(f"\n  {_c(_ERR, '⛔')}  Port {port} is already in use by something "
              f"that is not Super Research.")
        print(f"      {_who}")
        print(f"      Stop it, or start this backend on another port.\n")
        raise SystemExit(3)

    if _port_state == "busy":
        # Ours, and mid-flight. This is the one refusal that is NOT about
        # identity — we know exactly what is there and that is why we leave it
        # alone. Say what it is doing, so "in use" does not read as the same
        # dead end the raw EADDRINUSE was.
        _act = next((h.get("activity") or {} for h in _port_holders_found
                     if h.get("activity")), {})
        _pids = ", ".join(str(h["pid"]) for h in _port_holders_found) or "unknown"
        _doing = "running a research" if _act.get("running") else "working"
        _queued = int(_act.get("pending") or 0)
        print(f"[serve] bind refused: port {port} is held by a working backend "
              f"(pid {_pids})", file=sys.stderr, flush=True)
        print(f"\n  {_c(_ERR, '⛔')}  Port {port} is already in use by a Super Research "
              f"backend that is {_doing}.")
        print(f"      pid {_pids}"
              + (f" — {_queued} job(s) queued" if _queued else ""))
        print(f"      Nothing was stopped. Wait for it to finish, or start this "
              f"backend on another port.\n")
        raise SystemExit(3)

    if _port_state == "stuck":
        _pids = ", ".join(str(h["pid"]) for h in _port_holders_found) or "unknown"
        print(f"[serve] bind refused: port {port} did not come free (EADDRINUSE)",
              file=sys.stderr, flush=True)
        print(f"\n  {_c(_ERR, '⛔')}  Port {port} is still held after stopping the "
              f"earlier backend (pid {_pids}).")
        print(f"      Nothing was started. Check with:  "
              f"lsof -nP -iTCP:{port} -sTCP:LISTEN\n")
        raise SystemExit(3)
    _paired_uid_now = load_paired_uid()
    _device_id_now = load_device_id() or ""
    # Pull owner identity + device metadata from the device doc, not
    # the (synth-user-inaccessible) users/{uid}/ path. ownerEmail +
    # ownerDisplayName are written by the claim Cloud Function;
    # name + os are written by initiate-pair and user-editable from
    # the FE Account-page tile.
    if sys.stdout and sys.stdout.isatty():
        async with _async_spinner_ctx("Loading device identity"):
            _meta = await asyncio.to_thread(_fetch_device_meta)
    else:
        _meta = _fetch_device_meta()
    _paired_email = _meta.get("ownerEmail", "") or ""
    _paired_name = _meta.get("ownerDisplayName", "") or ""
    if _paired_name and _paired_email:
        _paired_val = f"{_c(_BOLD, _paired_name)}  {_c(_DIM, '(' + _paired_email + ')')}"
    elif _paired_email:
        _paired_val = _c(_BOLD, _paired_email)
    elif _paired_uid_now:
        _paired_val = f"{_c(_DIM, _paired_uid_now[:8] + '…')}"
    else:
        _paired_val = _c(_DIM, "(not paired)")
    _device_name = (
        _meta.get("name", "")
        or _meta.get("machineName", "")
        or _meta.get("hostname", "")
        or (f"{_device_id_now[:8]}…" if _device_id_now else "(none)")
    )
    _device_os = _meta.get("os", "") or ""
    if _device_id_now:
        if _device_os:
            _device_val = (
                f"{_c(_BOLD, _device_name)}  {_c(_DIM, '(' + _device_os + ')')}  "
                f"{_c(_OK, '(active)')}"
            )
        else:
            _device_val = f"{_c(_BOLD, _device_name)}  {_c(_OK, '(active)')}"
    else:
        _device_val = _c(_DIM, "(none)")
    _ctx_rows_serve = [
        ("Paired to", _paired_val),
        ("Device",    _device_val),
        ("Local API", _c(_BOLD, f"http://localhost:{port}")),
        ("Heartbeat", _c(_BOLD, f"{HEARTBEAT_INTERVAL_SEC}s cadence")),
    ]
    _bat_serve = _battery_state()
    if _bat_serve:
        _ctx_rows_serve.append(("Power", _c(_DIM, _bat_serve)))
    _render_context_strip(_ctx_rows_serve)
    # ⚠ The ADVISORY pre-bind port probe used to live HERE, between the strip
    # and the footer, and split the banner whenever it warned. It moved above
    # the strip — see the comment there. It stays NEVER fatal: uvicorn's own
    # bind is the authority, and the try/except around `server.serve()` turns a
    # real EADDRINUSE into a clean message plus the stderr signature the
    # supervisor's port-recovery greps for. (An earlier version raised
    # SystemExit(3) on a False probe — a speculative gate in the critical
    # startup path that could keep the API from ever binding.)
    print()
    print(f"  {_c(_BOLD + _ACCENT, '  Listening for pipeline jobs.')}  {_c(_DIM, 'Keep this terminal open.')}")
    print()
    print(f"  {_c(_DIM, 'Stop:')}  {_c(_BOLD, 'Ctrl+C')}")

    # Context-aware hint: fresh users running --serve without pairing see
    # the banner succeed (port bound, listeners started) but no jobs will
    # ever arrive until the app claims a token. Surface --pair. If paired
    # but On Startup isn't enabled, surface --resurrect so users discover
    # the "run in background" capability.
    # _detect_supervised runs schtasks subprocess — Windows can occasionally
    # hang the call past its own timeout, parking startup before uvicorn binds.
    # Treat it as best-effort (default to False), banner just shows --resurrect
    # action whether supervised or not — UX is harmless either way.
    try:
        _currently_supervised = await asyncio.wait_for(
            asyncio.to_thread(_detect_supervised), timeout=8.0,
        )
    except (asyncio.TimeoutError, Exception):
        _currently_supervised = False
    if not (_device_id_now and _paired_uid_now):
        print()
        print(f"  {_c(_WARN, '⚠')}  Not paired yet — jobs will be ignored until this machine is paired.")
        _render_next_actions([
            ("python research.py --pair", "pair this machine to your account"),
        ])
    elif not _currently_supervised:
        _render_next_actions([
            ("python research.py --resurrect", "enable On Startup (auto-start in background)"),
            ("python research.py --unpair",    "fully disconnect this machine"),
        ])
    else:
        _render_next_actions([
            ("python research.py --retire", "disable On Startup"),
            ("python research.py --unpair", "fully disconnect this machine"),
        ])

    config = uvicorn.Config(app, host="0.0.0.0", port=port, log_level="info",
                            log_config=_uvicorn_log_config())
    server = uvicorn.Server(config)
    # Ctrl+C is the only stop this screen advertises; it does not get to be
    # best-effort. See `_arm_stop_signals`.
    _stop_arm_task = asyncio.create_task(_arm_stop_signals(server, port))
    try:
        await server.serve()
    except OSError as _bind_err:
        # TOCTOU: a racing process grabbed the port between our probe and
        # uvicorn's bind. Echo the EADDRINUSE signature (supervisor port-recovery
        # keys on it) and exit non-zero with a clean line instead of a raw trace.
        _emsg = str(_bind_err).lower()
        if (
            "address already in use" in _emsg
            or "10048" in _emsg
            or "errno 98" in _emsg
            or "only one usage of each socket address" in _emsg
        ):
            print(
                f"[serve] bind failed: address already in use (EADDRINUSE) on port {port}",
                file=sys.stderr, flush=True,
            )
            print(f"  {_c(_WARN, '⚠')}  Port {port} was taken at bind time — not started.")
            raise SystemExit(3) from _bind_err
        raise
    else:
        # Graceful stop via a signal: keep the conventional exit code (130 for
        # Ctrl+C, 143 for SIGTERM). uvicorn's own handler produced 130 before
        # this path existed, and a supervisor may key on it.
        _sig_n = _server_stop_signal.get("n")
        if _sig_n:
            log(f"[serve] stopped by signal {_sig_n} — exiting {128 + _sig_n}", "DEBUG")
            raise SystemExit(128 + _sig_n)
    finally:
        _stop_arm_task.cancel()
        worker_task.cancel()
        if heartbeat_task:
            heartbeat_task.cancel()
        # ⚠ 2026-08-06: this block used to open with
        #     global _token_relink_watch, _device_cmd_watch
        #     if _token_relink_watch is not None: … .unsubscribe() …
        # and NOTHING in the repo ever assigned `_token_relink_watch` — the
        # relink watcher became an asyncio POLLING loop (`[relink] watcher
        # armed`, which sleeps until `_firebase_db` goes None) and has no
        # subscription handle to release. The cleanup was left pointing at the
        # abandoned Firestore-Watch design, so every `--serve` shutdown raised
        # `NameError: name '_token_relink_watch' is not defined` right here.
        #
        # The consequence was not cosmetic: the finally block aborted at that
        # line, so the `_device_cmd_watch.unsubscribe()` below it had NEVER once
        # run, and serve exited non-zero with a traceback. Deleted rather than
        # defined as None — defining it would silence the crash while keeping
        # code that pretends to release something that does not exist.
        #
        # It stayed invisible because a plain `--serve … | tee log` loses the
        # shutdown tail: Ctrl+C signals the whole process group, tee dies at the
        # same instant, and everything printed after it goes nowhere.
        global _device_cmd_watch
        if _device_cmd_watch is not None:
            try:
                _device_cmd_watch.unsubscribe()
            except Exception:
                pass
            _device_cmd_watch = None
        # No explicit "offline" stamp on shutdown — the FE derives
        # online/offline from heartbeat age (60s threshold), which the
        # device doc ages into naturally once heartbeats stop. Under
        # daemon-loop supervision, stamping on shutdown would oscillate
        # green↔red on every respawn cycle.


# ── Setup ────────────────────────────────────────────────────────────────────

def _fresh_user_mode_id_token() -> "str | None":
    """Return a fresh Firebase ID token for the synth device user, or None
    if the keystore is empty / refresh token revoked. Used by user-mode
    code paths that need to authenticate against an FE Cloud Function
    (e.g. /api/devices/unpair-self, oauth-callback hand-offs). Forces a
    refresh on every call so the token can't be expired by the time the
    HTTP request lands."""
    try:
        from auth import credentials, keystore
        from auth.v2_flow import WEB_API_KEY
    except ImportError as e:
        log(f"user-mode id-token: auth/ import failed: {e}", "WARN")
        return None
    iuid = keystore.install_uuid()
    if keystore.try_recover(iuid) is None:
        return None
    try:
        creds = credentials.RefreshTokenCredentials(iuid, WEB_API_KEY)
        creds.refresh(None)  # type: ignore[arg-type]
        return creds.token  # type: ignore[no-any-return]
    except credentials.RevokedError:
        # Re-read before wiping: a sibling worker may have rotated a fresh token
        # into `current` microseconds ago (cross-process refresh race). Only the
        # token we actually POSTed was rejected — retry once against whatever
        # `current` now holds before declaring a genuine revoke. (RC-5 guard)
        try:
            if keystore.try_recover(iuid) is not None:
                creds2 = credentials.RefreshTokenCredentials(iuid, WEB_API_KEY)
                creds2.refresh(None)  # type: ignore[arg-type]
                return creds2.token  # type: ignore[no-any-return]
        except credentials.RevokedError:
            pass  # re-read token ALSO revoked → genuine, fall through to wipe
        except Exception:
            return None  # transient on the retry — leave keystore intact
        tm.tm_emit(tm.Ev.TOKEN_REFRESH_FAILED,
                   error_class=tm.ErrorClass.AUTH_REVOKED)
        log("user-mode id-token: refresh token revoked — wiping keystore", "WARN")
        keystore.clear_all(iuid, reason="revoke")
        return None
    except Exception as e:
        # ⭐ THE LINE THAT DIAGNOSED THE FOUNDING INCIDENT, and that nobody ever
        # saw: `refresh: network error … Failed to resolve
        # 'securetoken.googleapis.com'`. It reached bare stderr and no file. The
        # class is derived from the exception TYPE — a message here carries a
        # hostname, a path and a Firebase Web API key.
        tm.tm_emit(tm.Ev.TOKEN_REFRESH_FAILED,
                   error_class=tm.classify_exception(e))
        log(f"user-mode id-token: refresh failed: {e}", "WARN")
        return None


def _pair_patch_device(
    device_id: str,
    set_fields: "dict[str, object]",
    delete_fields: "list[str] | None" = None,
) -> bool:
    """PATCH the top-level `devices/{deviceId}` doc directly via Firestore
    REST, authenticated with the synth user's fresh idToken from the
    keystore. Used during pair to mirror state (pairConfirmedAt,
    supervised intent) to Firestore in real time without depending on a
    constructed gRPC client — the keystore is bootstrapped within
    `cmd_pair_v2` but `_firebase_db` (Track-D-user-scoped client) isn't
    initialized until `--serve`.

    `set_fields` accepts bool / str / int values and converts to the
    Firestore REST primitive shape. `delete_fields` are added to the
    updateMask but omitted from the body so the server clears them.
    Best-effort: returns False on any failure, never raises.
    """
    id_token = _fresh_user_mode_id_token()
    if not id_token:
        log("[pair-patch] no id_token — keystore not yet bootstrapped", "WARN")
        return False
    try:
        from auth.v2_flow import PROJECT_ID as _PID
        import requests as _requests
    except ImportError as e:
        log(f"[pair-patch] import failed: {e}", "WARN")
        return False
    update_mask_fields = list(set_fields.keys()) + list(delete_fields or [])
    params = [("updateMask.fieldPaths", f) for f in update_mask_fields]
    fields_body: "dict[str, dict]" = {}
    for k, v in set_fields.items():
        if isinstance(v, bool):
            fields_body[k] = {"booleanValue": v}
        elif isinstance(v, int):
            fields_body[k] = {"integerValue": str(v)}
        elif isinstance(v, str):
            fields_body[k] = {"stringValue": v}
        else:
            fields_body[k] = {"stringValue": str(v)}
    url = (
        f"https://firestore.googleapis.com/v1/projects/{_PID}"
        f"/databases/(default)/documents/devices/{device_id}"
    )
    try:
        resp = _requests.patch(
            url,
            params=params,
            headers={
                "Authorization": f"Bearer {id_token}",
                "Content-Type": "application/json",
            },
            json={"fields": fields_body},
            timeout=10,
        )
    except _requests.RequestException as e:
        log(f"[pair-patch] network error: {e}", "WARN")
        return False
    if resp.status_code == 200:
        return True
    log(
        f"[pair-patch] HTTP {resp.status_code}: {resp.text[:200]}",
        "WARN",
    )
    return False


def _cancel_unclaimed_pair(device_id: "str | None", poll_secret: str) -> str:
    """Undo an initiate-pair that never got claimed, and say what happened.

    By the time the pair code is on screen the server has already created three
    things: the device doc, the pollSecretHash entry, and the synthetic Firebase
    Auth user. Abandoning the flow here used to leave all three behind — the doc
    surfaced later as a stale `awaiting-initial-claim` tile, and the auth user
    surfaced nowhere at all, which is how orphaned machine logins piled up
    unnoticed for months. `expireAt` is a DOCUMENT sweeper; it cannot see the
    login, so it is the backstop for a process that gets killed mid-pair, not
    the plan.

    Deliberately NOT `_cleanup_partial_pair`: that one needs an idToken we do not
    have before the exchange, and it wipes the keystore + research_config.json,
    which at this point still belong to whatever pairing was here before.

    Returns "nothing" | "cancelled" | "claimed" | "failed" — the outcome, so
    callers and tests can distinguish "there was nothing to undo" from "we tried
    and could not". Never raises: every caller is already on a failure path.
    """
    if not device_id:
        # initiate-pair itself never returned, so nothing exists server-side.
        return "nothing"
    from auth import v2_flow as _v2f

    try:
        outcome = _v2f.cancel_pair_remote(
            device_id=device_id, poll_secret=poll_secret
        )
    except Exception as e:  # defence in depth — the helper already swallows
        log(f"[pair] cancel-pair raised unexpectedly: {e}", "WARN")
        outcome = "failed"

    if outcome == "cancelled":
        log("Cleaned up the unclaimed pair — no device was added.", "INFO")
    elif outcome == "claimed":
        # The claim landed while we were failing. That is a real device with a
        # real owner, so the server correctly refuses to delete it for us.
        log(
            "The code was claimed before this failed — the device exists. "
            f"Run `{_PROG} --unpair` to remove it.",
            "WARN",
        )
    else:
        log(
            f"Could not clean up the unclaimed pair (deviceId={device_id[:12]}…). "
            "It expires on its own; remove it from Account → Manage devices "
            "if it lingers.",
            "WARN",
        )
    return outcome


def _cleanup_partial_pair(device_id: str) -> None:
    """Reverse a partially-completed pair when the user Ctrl+Cs (or the
    flow errors out) between Stage 1 exchange and Stage 5 completion.

    Track D writes pairConfirmedAt:true to the device doc the moment
    exchange succeeds so the FE Account tile appears at Stage 1 — but
    that means a mid-flow cancellation would leave a "confirmed" tile
    with no working backend behind it. This helper:
      1) POSTs /api/devices/unpair-self with the just-minted idToken
         (full server-side retire — deletes device doc + revokes synth
         Firebase user, drops the pollSecretHash entry).
      2) Wipes the OS keystore.
      3) Removes research_config.json.
      4) Best-effort supervisor disarm (schtasks /Delete on Windows /
         launchctl bootout on mac / systemctl --user disable on linux)
         in case the cancellation happened during Stage 5 arming.

    Best-effort throughout — never raises, prints WARN on each failed
    step so the user can run `--unpair` manually if anything sticks."""
    import requests as _requests
    import subprocess as _sp
    # Server-side: delete the device doc + revoke synth user. Requires
    # an idToken which is still mintable from the just-bootstrapped
    # keystore at this point (we haven't wiped it yet).
    try:
        from auth.v2_flow import FE_BASE_URL as _FE_BASE_URL
        _id_token = _fresh_user_mode_id_token()
        if _id_token:
            try:
                _resp = _requests.post(
                    f"{_FE_BASE_URL}/api/devices/unpair-self",
                    headers={"Authorization": f"Bearer {_id_token}"},
                    json={"deviceId": device_id},
                    timeout=10,
                )
                if _resp.status_code == 200:
                    log("[cleanup] device retired server-side ✓", "INFO")
                else:
                    log(
                        f"[cleanup] /unpair-self HTTP {_resp.status_code} — "
                        f"run --unpair to clean up manually",
                        "WARN",
                    )
            except Exception as e:
                log(f"[cleanup] server-side retire failed: {e}", "WARN")
        else:
            log("[cleanup] no idToken — skipping server-side retire", "WARN")
    except Exception as e:
        log(f"[cleanup] auth import failed: {e}", "WARN")
    # Local: wipe keystore + research_config.json so the next --pair
    # starts from a clean slate.
    try:
        from auth import keystore as _ks
        _ks.clear_all(_ks.install_uuid(), reason="retire")
        log("[cleanup] OS keystore cleared", "INFO")
    except Exception as e:
        log(f"[cleanup] keystore wipe failed: {e}", "WARN")
    try:
        if RESEARCH_CONFIG_PATH.exists():
            RESEARCH_CONFIG_PATH.unlink()
            log("[cleanup] research_config.json removed", "INFO")
    except Exception as e:
        log(f"[cleanup] config wipe failed: {e}", "WARN")
    # In-memory caches — anything still running in this process can't
    # re-read pre-wipe values.
    global _device_id, _device_paired_uid
    _device_id = None
    _device_paired_uid = None
    # Supervisor: best-effort disarm in case Ctrl+C landed during Stage
    # 5 arming. Failures are silent — `--retire` is the user's fallback.
    try:
        _plat = _supervisor_platform()
        if _plat == "Windows":
            _sp.run(
                ["schtasks", "/Delete", "/TN", _SUPERVISOR_TASK_NAME, "/F"],
                capture_output=True, timeout=10, creationflags=_PS_NO_WINDOW,
            )
        elif _plat == "Darwin":
            _sp.run(
                ["launchctl", "bootout", f"gui/{os.getuid()}/{_SUPERVISOR_PLIST_LABEL}"],
                capture_output=True, timeout=10,
            )
        elif _plat == "Linux":
            _sp.run(
                ["systemctl", "--user", "disable", "--now", _SUPERVISOR_UNIT_NAME],
                capture_output=True, timeout=10,
            )
    except Exception:
        pass


# ── Pair-flow API key verifiers ───────────────────────────────────────
# Cheap live-API calls invoked during --pair Stage 3 to confirm a pasted
# key actually authenticates before we persist it. Verification at paste
# time means the operator catches typos / revoked keys / wrong-account
# pastes immediately, instead of mid-pipeline. All verifiers return one
# of three string statuses:
#   "ok"            — key authenticates
#   "auth_failed"   — provider rejected the key (401/403/specific error
#                     code) — re-prompt makes sense
#   "network_error" — timeout / connection / unrecognized error — the
#                     caller treats this as "save anyway, the user can
#                     run a job and see what happens" so offline pairs
#                     and transient blips don't block setup
def _verify_anthropic_key(key: str) -> str:
    """Verify an Anthropic API key against the live API.

    Calls `models.list()` with a 5s timeout and `max_retries=0` so the
    pair UX feels snappy on flaky connections. `models.list` requires a
    well-formed, recognized key but does NOT exercise message-API
    billing — a never-funded key still passes here and fails at first
    `messages.create`. Good enough for pair-time format-checking; full
    billing verification belongs in the first job's error surface."""
    if not key:
        return "auth_failed"
    try:
        import anthropic as _anth
    except ImportError:
        # Anthropic SDK missing — can't verify; treat as network so the
        # caller saves the key anyway and the operator installs the SDK
        # separately. Unblocks the pair flow.
        return "network_error"
    try:
        _anth.Anthropic(api_key=key, timeout=5.0, max_retries=0).models.list()
        return "ok"
    except _anth.AuthenticationError:
        return "auth_failed"
    except _anth.PermissionDeniedError:
        # 403 — workspace cap / org-disabled. Same UX outcome as a bad
        # key (user needs to paste a different one), so we re-prompt.
        return "auth_failed"
    except (_anth.APITimeoutError, _anth.APIConnectionError):
        return "network_error"
    except Exception:
        # Catch-all for unexpected SDK errors. We'd rather save an
        # unverified key than crash the pair flow.
        return "network_error"


def _verify_gemini_key(key: str) -> str:
    """Verify a Gemini / Google AI API key against the live API.

    Issues an unauthenticated `GET /v1beta/models?key=...` (5s timeout)
    and inspects the JSON error body. Google's URL-param auth returns
    HTTP 400 with `error.status=INVALID_ARGUMENT` and `details[].reason=
    API_KEY_INVALID` for structurally bad keys, and HTTP 403 with
    `PERMISSION_DENIED` for revoked / scope-disabled keys. We only
    re-prompt on those two specific signals — 429 quota and 5xx blips
    fall through to network_error so the user isn't blocked."""
    if not key:
        return "auth_failed"
    try:
        import requests as _requests
    except ImportError:
        return "network_error"
    url = "https://generativelanguage.googleapis.com/v1beta/models"
    try:
        resp = _requests.get(url, params={"key": key}, timeout=5.0)
    except _requests.RequestException:
        return "network_error"
    if resp.status_code == 200:
        return "ok"
    try:
        err = (resp.json() or {}).get("error", {}) or {}
        reasons = {
            str((d or {}).get("reason", ""))
            for d in (err.get("details") or [])
        }
    except Exception:
        return "network_error"
    if "API_KEY_INVALID" in reasons:
        return "auth_failed"
    if str(err.get("status", "")) == "PERMISSION_DENIED":
        return "auth_failed"
    # 429 quota, 5xx, or unrecognized error shape — save and let the
    # operator find out at first run. Don't block the pair flow on a
    # transient provider issue.
    return "network_error"


async def _pair_prompt_one_key(label: str, example: str, help_url: str) -> str:
    """Single-key paste loop for --pair Stage 4/5.

    Returns the trimmed key string on paste, or "" on skip / EOF. Ctrl+C is
    RE-RAISED (universal cancel — the caller reverts the partial pair); type
    's' to skip a single key instead.
    Skip is first-class — pair completes regardless; missing keys surface
    at first-job via the cua_unavailable / narrator-disabled paths (both
    already user-recoverable from the FE alert).

    Uses `getpass.getpass` so the key DOES NOT echo to the terminal or
    scrollback — important on shared Linux/macOS machines and when
    screen-sharing during setup. Falls back to `input` only on platforms
    where getpass can't suppress echo (rare).
    """
    import getpass as _getpass
    print(f"  {_c(_BOLD, label)}  {_c(_DIM, f'— get one at {help_url}')}")
    prompt = (
        f"  {_c(_ACCENT, '>')}  Paste {label} key ({example})  "
        f"{_c(_DIM, 'or [S]kip — input hidden:')} "
    )
    while True:
        try:
            raw = await asyncio.to_thread(_getpass.getpass, prompt)
        except EOFError:
            print()
            return ""
        except KeyboardInterrupt:
            # Ctrl+C = cancel the pair (not "skip this key" — type s to skip).
            # Propagate so Stage 3 / cmd_pair_v2 revert the partial pair.
            print()
            raise
        except _getpass.GetPassWarning:
            # No-echo support unavailable on this terminal — fall back to
            # echoed input rather than crashing. User loses the privacy
            # benefit but the prompt still works.
            try:
                raw = await asyncio.to_thread(input, prompt)
            except EOFError:
                print()
                return ""
            except KeyboardInterrupt:
                print()
                raise
        s = (raw or "").strip()
        # Strip surrounding quotes — users often copy from .env-style snippets
        if len(s) >= 2 and s[0] in ('"', "'") and s[-1] == s[0]:
            s = s[1:-1].strip()
        if not s:
            print(f"  {_c(_WARN, '     Enter a key or type s to skip.')}")
            continue
        if s.lower() in ("s", "skip"):
            return ""
        # Loose sanity: real keys are well over 20 chars and contain no whitespace
        if len(s) < 20 or any(ch.isspace() for ch in s):
            print(f"  {_c(_WARN, '     That does not look like a valid key. Try again or type s to skip.')}")
            continue
        return s


async def _pair_prompt_one_key_with_verify(
    label: str,
    example: str,
    help_url: str,
    verifier,
    max_attempts: int = 3,
) -> str:
    """Paste-and-verify loop for --pair Stage 3.

    Wraps `_pair_prompt_one_key` with an API-call verifier (cheap
    `models.list`-style probe). A visible `_async_spinner_ctx` runs
    during the probe so the operator sees verification is happening
    (the probe itself is up to 5s — silent would feel like a hang).
    On verify result:
      - "ok": print `✓ {label} key verified.` + return the key —
        caller persists it.
      - "auth_failed": warn + re-prompt up to `max_attempts` times.
        After the last fail, ask "save anyway? [y/N]" — yes returns
        the last pasted key with a stern warning, no returns "" (skip).
      - "network_error": warn + return the key as-is. Offline-tolerant
        pair — the user can still set up on a flaky connection; jobs
        fail-loud at first run if the key is actually bad.

    Skip path (`_pair_prompt_one_key` returns "") never invokes the
    verifier — skip is first-class and free.
    """
    attempts = 0
    last_key = ""
    while True:
        key = await _pair_prompt_one_key(label, example, help_url)
        if not key:
            return ""  # Skip — no verification needed
        # Wrap the verifier in to_thread so the 5s network call doesn't
        # block the event loop (defensive; pair has nothing else running).
        # Spinner gives the user visible feedback that the probe is
        # actually running — silent would feel like a hang on slow
        # networks.
        async with _async_spinner_ctx(f"Verifying {label} key"):
            status = await asyncio.to_thread(verifier, key)
        if status == "ok":
            print(f"  {_c(_OK, '✓')}  {label} key verified.")
            return key
        if status == "network_error":
            print(f"  {_c(_WARN, '!')}  Could not reach {label} API to verify "
                  f"{_c(_DIM, '(network error — saving without check).')}")
            print(f"  {_c(_DIM, '     Jobs will fail-loud at first run if the key is invalid.')}")
            return key
        # status == "auth_failed"
        attempts += 1
        last_key = key
        if attempts < max_attempts:
            remaining = max_attempts - attempts
            print(
                f"  {_c(_WARN, '!')}  {label} rejected this key "
                f"{_c(_DIM, f'({remaining} attempt' + ('s' if remaining != 1 else '') + ' left — try again or type s to skip).')}"
            )
            continue
        # Last attempt failed — escape hatch in case the verifier endpoint
        # itself is misbehaving (e.g. enterprise proxy MITM that breaks
        # TLS). Default to no.
        print(
            f"  {_c(_WARN, '!')}  {label} rejected this key on attempt "
            f"{attempts}/{max_attempts}."
        )
        try:
            _save_anyway = await _ask_yes_no("Save this key anyway", default=False)
        except EOFError:
            print()
            return ""
        except KeyboardInterrupt:
            print()
            raise
        if _save_anyway:
            print(
                f"  {_c(_WARN, '⚠')}  Saving unverified key. "
                f"{_c(_DIM, 'Jobs will fail-loud at first run if it remains invalid.')}"
            )
            return last_key
        return ""


async def _pair_prompt_api_keys(uid: str):
    """Stage 3/5 of --pair: detect-or-prompt for Anthropic + Gemini.

    Per key: if any source already resolves (Firestore Account-page key /
    Windows User-scope env / shell env / .dg-supervisor.env via
    _load_env_file), skip the prompt and tell the user we're using that.
    Otherwise prompt with paste-or-skip, then VERIFY the pasted key
    against the provider's API before persisting — typos / revoked keys
    / wrong-account pastes surface immediately, not mid-pipeline. On
    verified paste: write to BE-local persistence (Win User-scope env
    on Windows; `.dg-supervisor.env` on POSIX) + os.environ (in-memory
    for this session) + bust _RESOLVED_KEY_CACHE so the change is picked
    up immediately by Stage 4 browser-login CUA init AND by Stage 5
    supervisor arming.

    Pair-time keys live ONLY on the paired machine — they are NOT
    written to Firestore. The FE Account → API Config page is a
    SEPARATE surface that does write to Firestore; when a user pastes
    a key there it takes precedence over the BE-local pair-time key
    (resolver order: Firestore → User-scope → shell env). Keeping the
    surfaces disjoint prevents the FE Account page from auto-filling
    with a pair-time key the user never typed there.

    Anthropic and Gemini are independent — skipping one doesn't affect
    the other. Pair always completes; degraded modes (cua_unavailable
    for missing Anthropic, narration disabled for missing Gemini) are
    user-recoverable via FE alert + Account → API Config."""
    del uid  # No longer used — pair-time persistence is BE-local, not Firestore.
    # ── Anthropic ─────────────────────────────────────────────────────────
    if resolve_api_key():
        print(f"  {_c(_OK, '✓')}  Anthropic key {_c(_DIM, 'already configured — using existing source.')}")
    else:
        key = await _pair_prompt_one_key_with_verify(
            label="Anthropic",
            example="sk-ant-...",
            help_url="https://console.anthropic.com/settings/keys",
            verifier=_verify_anthropic_key,
        )
        if key:
            # Persist to BE-local FIRST, then mirror to os.environ for the
            # in-flight session (User-scope env / .env file are only seen
            # by *new* processes — the current pair session needs the
            # os.environ mirror to use the key in Stage 4 / Stage 5).
            #
            # Single canonical name only — `CUA_API_KEY` was retired
            # 2026-05-23 in favor of the Anthropic-SDK standard
            # `ANTHROPIC_API_KEY`. Existing devices with a CUA_API_KEY
            # set are migrated to ANTHROPIC_API_KEY by
            # _migrate_legacy_api_keys() at startup.
            ok_anth = _save_api_key_local("ANTHROPIC_API_KEY", key)
            os.environ["ANTHROPIC_API_KEY"] = key
            _RESOLVED_KEY_CACHE.update(key=None, ts=0.0)
            if ok_anth:
                print(f"  {_c(_OK, '✓')}  Saved to this machine {_c(_DIM, '— survives reboots via the supervisor.')}")
            else:
                print(f"  {_c(_WARN, '⚠')}  Could not persist — applied to this session only.")
                print(f"  {_c(_DIM, '     Save permanently from the web app: Account → API Config.')}")
        else:
            print(f"  {_c(_DIM, '─')}  Skipped Anthropic — set later from the web app (Account → API Config).")

    print()

    # ── Gemini ────────────────────────────────────────────────────────────
    if resolve_gemini_api_key():
        print(f"  {_c(_OK, '✓')}  Gemini key {_c(_DIM, 'already configured — using existing source.')}")
    else:
        key = await _pair_prompt_one_key_with_verify(
            label="Gemini",
            example="AIza...",
            help_url="https://aistudio.google.com/app/apikey",
            verifier=_verify_gemini_key,
        )
        if key:
            # Single canonical name only — `GOOGLE_API_KEY` was retired
            # 2026-05-23 in favor of the Gemini-API-docs standard
            # `GEMINI_API_KEY`. Existing devices with GOOGLE_API_KEY set
            # are migrated by _migrate_legacy_api_keys() at startup.
            ok_gem = _save_api_key_local("GEMINI_API_KEY", key)
            os.environ["GEMINI_API_KEY"] = key
            # resolve_gemini_api_key() has no cache — nothing to bust. If a
            # Gemini cache is ever added (mirroring _RESOLVED_KEY_CACHE), add
            # the equivalent reset here so this site doesn't silently break.
            if ok_gem:
                print(f"  {_c(_OK, '✓')}  Saved to this machine {_c(_DIM, '— survives reboots via the supervisor.')}")
            else:
                print(f"  {_c(_WARN, '⚠')}  Could not persist — applied to this session only.")
                print(f"  {_c(_DIM, '     Save permanently from the web app: Account → API Config.')}")
        else:
            print(f"  {_c(_DIM, '─')}  Skipped Gemini — set later from the web app (Account → API Config).")


def _chrome_install_hint() -> str:
    """OS-appropriate one-liner for installing real Google Chrome — the browser
    the pipeline drives via channel='chrome' (research.py:~16137). We never
    auto-install it (needs admin/sudo + an assumed package manager); --pair and
    --doctor surface this hint when Chrome is absent."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return "Install Google Chrome:  winget install --id Google.Chrome -e   (or google.com/chrome)"
    if plat == "Darwin":
        return "Install Google Chrome:  brew install --cask google-chrome   (or google.com/chrome)"
    if plat == "Linux":
        return ("Install Google Chrome:  apt install google-chrome-stable  /  dnf install google-chrome-stable "
                "(add Google's repo first, or grab the .deb/.rpm from google.com/chrome)")
    return "Install Google Chrome from google.com/chrome"


def _ensure_chrome_ready(*, auto_install: bool = True, quiet: bool = False) -> "tuple[bool, str]":
    """Verify the browser stack the pipeline drives — real Google Chrome plus
    patchright's stealth wrapper for channel='chrome' — and, when auto_install,
    fetch the wrapper if it's missing (`patchright install chrome`).

    This is the one network step a fresh `pipx install superresearch` needs
    before its first --pair browser logins: pip installs the patchright PACKAGE
    but not the browser that channel='chrome' resolves to. Idempotent — when the
    wrapper + Chrome are already present the probe just returns ok in a few
    seconds. Never raises; real Chrome itself is an OS-level dep we only detect
    and guide. Returns (ok, detail). Sync (subprocess) — call via asyncio.to_thread
    from async callers."""
    import subprocess as _sp

    def _probe() -> "tuple[bool, str]":
        code = (
            "from patchright.sync_api import sync_playwright; "
            "pp=sync_playwright().start(); "
            "b=pp.chromium.launch(headless=True, channel='chrome'); "
            "b.close(); pp.stop(); "
            "print('OK')"
        )
        try:
            r = _sp.run([sys.executable, "-c", code], capture_output=True, text=True, timeout=90)
        except Exception as e:
            return False, str(e)[:160]
        out = ((r.stdout or "") + " " + (r.stderr or "")).strip()
        return (r.returncode == 0 and "OK" in (r.stdout or "")), out

    ok, detail = _probe()
    if ok:
        return True, "Chrome + patchright wrapper ready"

    low = detail.lower()
    wrapper_missing = (
        "executable doesn't exist" in low or "playwright install" in low
        or "browsertype.launch" in low or "no such file" in low
    )
    if wrapper_missing and auto_install:
        if not quiet:
            print(f"  {_c(_DIM, 'Fetching the Chrome stealth wrapper (patchright install chrome) — one-time…')}")
        pcli = shutil.which("patchright")
        install_cmd = ([pcli, "install", "chrome"] if pcli
                       else [sys.executable, "-m", "patchright", "install", "chrome"])
        try:
            _sp.run(install_cmd, capture_output=True, text=True, timeout=600)
        except Exception:
            pass
        ok, detail = _probe()
        if ok:
            return True, "Chrome + patchright wrapper ready (wrapper fetched)"

    # Still not launchable → real Google Chrome is likely absent (OS-level dep).
    return False, detail or "Chrome not launchable"


async def cmd_pair_v2(profile_dir: "str | None" = None):
    """Track D user-mode pair (post-D5c default — plain `--pair` routes
    here on fresh installs).

    Stage 1: mint a 256-bit pollSecret locally, call the FE Cloud
    Function `/api/devices/initiate-pair`, display the 8-char code (and
    QR), poll the pending-customToken subdoc, exchange the JWT for a
    refresh token, persist it to the OS keystore via
    RefreshTokenCredentials.bootstrap. No Admin SDK, no
    firebase-service-account.json on disk.

    Stages 2-5 are then handled by the shared
    `_continue_pair_stages_2_to_5` helper (same code path the legacy
    `run_pair` uses after its research_token handshake) — On Startup
    prompt, API keys via the FE bridge (D5c-2), browser logins,
    Ready/supervisor.
    """
    from auth import v2_flow
    import socket as _socket
    import platform as _platform

    tm.tm_emit(tm.Ev.PAIR_STARTED, supervised=_detect_supervised())

    # Per-step timing instrumentation, kept at DEBUG so the user-facing
    # terminal stays clean. Set `DG_PAIR_TRACE=1` in the env to re-enable
    # the `[pair +X.XXs]` step prefix on stderr for diagnosis. The
    # actual user-facing progress lines (✓ Refresh token saved, etc.)
    # are plain `print()` calls below so they always show.
    _pair_t0 = time.monotonic()
    _pair_trace = os.environ.get("DG_PAIR_TRACE") == "1"
    def _pt(msg: str, kind: str = "DEBUG") -> None:
        if not _pair_trace and kind == "DEBUG":
            return
        elapsed = time.monotonic() - _pair_t0
        log(f"[pair +{elapsed:5.2f}s] {msg}", kind)

    _setup_logo()
    _setup_step(1, 5, "Token setup")

    existing_secret = load_poll_secret()
    if existing_secret:
        poll_secret = existing_secret
        print(f"  {_c(_DIM, 'Reusing pollSecret from config — same hash → same Firestore subdoc path.')}")
    else:
        poll_secret = v2_flow.generate_poll_secret()
        print(f"  {_c(_OK, '✓')} Minted new 256-bit pollSecret.")

    poll_secret_hash = v2_flow.compute_poll_secret_hash(poll_secret)

    hostname = _socket.gethostname()
    os_string = f"{_platform.system()} {_platform.release()}"

    captured = {"device_id": None, "pair_code": None}

    # Spinner during the initiate-pair POST — the silent 2-15s before the pair
    # code appears. Thread-based (via _sync_spinner_ctx) so it animates even
    # though do_pair_v2 is awaited; stopped the instant on_code fires (success)
    # or by the finally below (error), so it never overruns the code display.
    _init_spinner = {"ctx": None}

    def _stop_init_spinner():
        if _init_spinner["ctx"] is not None:
            try:
                _init_spinner["ctx"].__exit__()
            finally:
                _init_spinner["ctx"] = None

    def _on_code(device_id: str, pair_code: str) -> None:
        _stop_init_spinner()
        captured["device_id"] = device_id
        captured["pair_code"] = pair_code
        formatted = (
            f"{pair_code[:4]}-{pair_code[4:]}" if len(pair_code) == 8 else pair_code
        )
        tm.tm_emit(tm.Ev.PAIR_CODE_SHOWN)
        print()
        print(f"  {_c(_DIM, 'Pair code')}")
        print(f"  {_c(_BOLD + _ACCENT, formatted)}")
        print()
        try:
            import qrcode
            qr = qrcode.QRCode(
                border=1, box_size=1,
                error_correction=qrcode.constants.ERROR_CORRECT_L,
            )
            qr.add_data(pair_code)
            qr.make(fit=True)
            # invert=True uses ANSI reverse-video — only safe when we know
            # the terminal honors color (matches F12 of the CLI audit).
            qr.print_ascii(tty=True, invert=bool(_USE_COLOR))
        except ImportError:
            # Cosmetic only: the pair code is printed as text a few lines below,
            # so nothing is lost and there is nothing for the reader to do. It
            # used to be a WARN in the middle of the branded pairing screen
            # carrying a remedy that cannot run on an installed copy.
            log("    QR image skipped (the qrcode library is not installed) — "
                "type the code below instead; nothing else is affected.", "INFO")
        except Exception as e:
            log(f"    QR render failed: {e}", "WARN")
        print()
        print(f"  {_c(_DIM, 'Enter this code in the Super Research app:')}")
        print(f"       {_c(_ACCENT, '•')} Account → Pipeline Connection → Add Device")
        print()

    last_tick = {"sec": -1}

    def _on_waiting(elapsed: float) -> None:
        sec = int(elapsed)
        # Print every 5s — printing every poll spams the terminal.
        if sec - last_tick["sec"] >= 5:
            last_tick["sec"] = sec
            # \r keeps the line in-place; trailing spaces wipe the previous
            # counter so single-digit→double-digit transitions don't leave
            # stale chars. F7 width clamp would be cleaner but the message
            # is short.
            sys.stdout.write(
                f"  {_c(_DIM, f'Waiting for FE claim... {sec}s')}                 \r"
            )
            sys.stdout.flush()

    _pt("calling /api/devices/initiate-pair...")
    # captured_device_id is set immediately after a successful exchange
    # so the try/finally cleanup at the bottom of this function can
    # reverse a partial pair if the user Ctrl+Cs between Stage 1 and
    # Stage 5.
    captured_device_id: "str | None" = None
    pair_completed = False

    def _cancel_unclaimed() -> None:
        # `captured["device_id"]` is set by _on_code, i.e. the moment the server
        # has actually created something — which is earlier than the exchange and
        # is exactly the window these handlers cover.
        _cancel_unclaimed_pair(captured.get("device_id"), poll_secret)

    try:
        try:
            _init_spinner["ctx"] = _sync_spinner_ctx("Requesting a pair code")
            _init_spinner["ctx"].__enter__()
            try:
                result = await v2_flow.do_pair_v2(
                    poll_secret_hash=poll_secret_hash,
                    machine_name=hostname,
                    hostname=hostname,
                    os_string=os_string,
                    on_code=_on_code,
                    on_waiting=_on_waiting,
                )
            finally:
                _stop_init_spinner()
        except v2_flow.PollTimeout:
            print()
            _cancel_unclaimed()
            tm.tm_emit(tm.Ev.PAIR_FAILED, stage=1,
                       error_class=tm.ErrorClass.TIMEOUT)
            _pt("no answer within the pairing window — nothing was claimed, "
                "so nothing was left half-paired.", "ERROR")
            _pt("Two things produce this, and they need different fixes: "
                "the code was never entered in the web app, or this machine "
                "could not reach us while it waited.", "ERROR")
            _pt(f"Enter the code faster and this works. If you did enter it, "
                f"run  {_PROG} --doctor  — it names which host this machine "
                f"cannot reach and why.", "ERROR")
            _pt(_doctor_share_logs_line(), "ERROR")
            return
        except v2_flow.InitiatePairError as e:
            print()
            tm.tm_emit(tm.Ev.PAIR_FAILED, stage=1,
                       error_class=tm.classify_exception(e))
            _pt(f"could not reach the pairing service "
                f"({type(e).__name__}: {e}).", "ERROR")
            _pt("Nothing was created, so there is nothing to clean up — this is "
                "the network between this machine and us.", "ERROR")
            _pt(f"Run  {_PROG} --doctor  to find out which host is unreachable "
                f"and whether it is DNS, a VPN, a proxy or a firewall.", "ERROR")
            _pt(_doctor_share_logs_line(), "ERROR")
            return
        except KeyboardInterrupt:
            print()
            _cancel_unclaimed()
            tm.tm_emit(tm.Ev.PAIR_CANCELLED, stage=1)
            log("Cancelled before exchange.", "WARN")
            return
        except Exception as e:
            print()
            _cancel_unclaimed()
            # A raw exception string is not a diagnosis, and this is the one
            # branch that by definition has no better one — so it says exactly
            # that, and hands over the log rather than leaving a dead end.
            tm.tm_emit(tm.Ev.PAIR_FAILED, stage=1,
                       error_class=tm.classify_exception(e))
            _pt(f"pairing stopped on an error we have no specific advice for "
                f"({type(e).__name__}: {e}).", "ERROR")
            _pt("Anything part-created has been reverted, so re-running "
                f"{_PROG} --pair  is safe.", "ERROR")
            _pt(_doctor_share_logs_line(), "ERROR")
            return
        # Past this point we have a live device entry in Firestore that
        # cleanup needs to revert if the flow doesn't finish.
        captured_device_id = result["device_id"]

        print()  # Clear the polling line.
        tm.tm_emit(tm.Ev.PAIR_TOKEN_EXCHANGED, ok=True)
        _pt(f"exchange OK — deviceId={result['device_id'][:12]}… uid={result['uid'][:14]}…")

        # Initial save — uses the synth uid as paired_uid until the
        # owner-lookup below resolves the real owner. Without this
        # write-then-rewrite split, a Ctrl+C between save + owner-
        # lookup would leave research_config.json without the real
        # ownerUid, breaking queue rehydration on the next --serve.
        # The post-lookup save below replaces paired_uid with the
        # genuine owner uid.
        save_user_mode_state(
            device_id=result["device_id"],
            paired_uid=result["uid"],
            poll_secret=poll_secret,
        )
        _pt("refresh token saved to OS keystore")
        print(f"  {_c(_OK, '✓')} Refresh token saved to OS keystore.")

        # Real-time atomic-pair confirmation. With the keystore bootstrapped
        # the BE is genuinely paired — Firestore should reflect that right
        # now so the FE Account-page tile appears at Stage 1, not after the
        # supervisor-started --serve eventually heartbeats. Mirrors the
        # contract heartbeat would write: pairConfirmedAt:true + delete
        # expireAt (cancels the 5-min "must confirm" TTL set by the claim
        # Cloud Function). Best-effort — if this fails the heartbeat at
        # Stage 5 still writes both via the same path.
        async with _async_spinner_ctx("Confirming with Super Research"):
            if _pair_patch_device(
                result["device_id"],
                {"pairConfirmedAt": True},
                delete_fields=["expireAt"],
            ):
                _pt("device confirmed in Firestore — FE tile should appear")
            else:
                _pt("device-confirm patch failed (heartbeat will retry)", "WARN")

            # Owner-lookup via Firestore REST GET, authed with the freshly-
            # minted idToken. Sidesteps the cold gRPC client init (~10-15s on
            # Windows the first time) that init_firestore_user_scoped does, so
            # the "Linked to {name} ({email})" banner shows the real owner
            # instead of falling back to the synth uid. Bounded by a 10s HTTP
            # timeout + graceful fallback — pair never blocks here.
            owner_uid = result["uid"]
            owner_label = ""
            owner_email = ""
            try:
                from auth.v2_flow import PROJECT_ID as _PID
                import requests as _requests
                _id_token = result["credentials"].token  # set by RefreshTokenCredentials.bootstrap
                _url = (
                    f"https://firestore.googleapis.com/v1/projects/{_PID}"
                    f"/databases/(default)/documents/devices/{result['device_id']}"
                )
                _resp = await asyncio.to_thread(
                    _requests.get,
                    _url,
                    headers={"Authorization": f"Bearer {_id_token}"},
                    timeout=10,
                )
                if _resp.status_code == 200:
                    _fields = (_resp.json() or {}).get("fields", {}) or {}
                    _owner_field = (_fields.get("ownerUid") or {}).get("stringValue") or ""
                    _label = (_fields.get("ownerDisplayName") or {}).get("stringValue") or ""
                    _email = (_fields.get("ownerEmail") or {}).get("stringValue") or ""
                    owner_uid = _owner_field or owner_uid
                    owner_label = _label or (_email.split("@")[0] if _email else "")
                    owner_email = _email
                    _pt(f"owner resolved — uid={owner_uid[:14]}… label={owner_label!r} email={owner_email!r}")
                else:
                    _pt(f"owner read HTTP {_resp.status_code} — falling back", "DEBUG")
            except Exception as e:
                _pt(f"owner lookup failed: {e} (falling back)", "DEBUG")

        # Re-write research_config.json with the REAL owner uid in
        # paired_uid. The earlier save (right after exchange) used the
        # synth uid as a placeholder — pointing user-tree queries on
        # the next --serve at `users/device-d754.../researches/`
        # instead of the actual owner's collection, which made queue
        # rehydration look at an empty path. Now that we have the real
        # ownerUid from the device doc, overwrite. Atomic-write helper
        # in save_user_mode_state handles partial-file safety.
        if owner_uid and owner_uid != result["uid"]:
            save_user_mode_state(
                device_id=result["device_id"],
                paired_uid=owner_uid,
                poll_secret=poll_secret,
            )
            _pt(f"paired_uid updated: synth → {owner_uid[:14]}…")

        print()
        print(f"  {_c(_DIM, 'Device id  ·')}  {_c(_BOLD, result['device_id'])}")
        print()
        # Banner: "✓ Linked to <name> (user@example.com)" when we have both;
        # falls back to label-only, then email-only, then "your account".
        if owner_label and owner_email:
            _linked_to = f"{_c(_BOLD, owner_label)} {_c(_DIM, '(' + owner_email + ')')}"
        elif owner_label:
            _linked_to = _c(_BOLD, owner_label)
        elif owner_email:
            _linked_to = _c(_BOLD, owner_email)
        else:
            _linked_to = _c(_BOLD, "your account")
        print(f"  {_c(_OK, '✓')}  Linked to {_linked_to}")
        print()

        _pt("entering stages 2-5 (On Startup → API keys → Logins → Ready)")
        # Stages 2-5 — On Startup, API keys (via FE bridge in user-mode),
        # browser logins, Ready/supervisor. The helper writes per-platform
        # login progress to devices/{deviceId}.logins via the user-scoped
        # Firestore client (rule permits synth user updates of `logins`).
        _pair_ok = await _continue_pair_stages_2_to_5(
            profile_dir or str(PROFILE_DIR),
            linked_uid=owner_uid,
            linked_email=owner_email or owner_label or owner_uid[:8],
            initial_paired_uid=None,
            token="",
            device_id_for_progress=result["device_id"],
        )
        # _continue returns True when the pair completed (incl. partial / zero
        # logins) or was intentionally refused, and False only when the user
        # cancelled mid-Stage-4. On cancel we leave pair_completed=False so the
        # finally reverts the partial pair (device doc + token) — no ghost tile
        # left in the app. (Fixes: Ctrl+C at Stage 4 used to keep the device.)
        pair_completed = bool(_pair_ok)
    finally:
        if captured_device_id and not pair_completed:
            print()
            log(
                "Pair interrupted — reverting partial state so your FE "
                "Account doesn't show a half-paired device tile.",
                "WARN",
            )
            _cleanup_partial_pair(captured_device_id)
            log(
                f"Cleanup done. Re-run `{_PROG} --pair` to try "
                "again from a clean slate.",
                "INFO",
            )


# ── Login flow: plain-Chrome sign-in → patchright verify ──────────────────────
#
# WHY (2026-06-30 investigation): Google BotGuard + Cloudflare Turnstile run
# their heaviest automation checks on the SIGN-IN / challenge page specifically.
# A CDP-driven browser (patchright/Playwright) is detected there — Google shows
# "this browser or app may not be secure", Cloudflare loops — so a FRESH login
# through the pipeline's own browser is blocked even with patchright's stealth
# (which still can't pass Google sign-in). Once a profile is ALREADY signed in,
# patchright only NAVIGATES those authenticated pages (never a sign-in form), so
# it isn't gated — which is exactly why a warm profile runs clean.
#
# The fix is two-phase: do the SIGN-IN in the user's REAL Chrome with NO
# automation attached (phase 1 — a normal browser Google/Cloudflare accept),
# then reopen the now-warm profile with patchright and VERIFY logins + Pro tier
# (phase 2). Both phases use the SAME on-disk profile dir the pipeline drives,
# so the saved cookies are exactly what a run reuses. Shared by `--login` and
# (later) pair Step 4.

_LOGIN_SERVICES = [
    ("ChatGPT",    "https://chatgpt.com",           "chatgpt"),
    ("Gemini",     "https://gemini.google.com",     "gemini"),
    ("Claude",     "https://claude.ai",             "claude"),
    ("NotebookLM", "https://notebooklm.google.com", "notebooklm"),
]


def _find_chrome_executable() -> "str | None":
    """Absolute path to the user's REAL Google Chrome binary, for launching a
    PLAIN (non-automated) Chrome — the one surface Google/Cloudflare let a human
    sign in on. Distinct from patchright's channel='chrome' (which drives Chrome
    under CDP = the browser that gets BLOCKED at sign-in). Checks standard
    per-OS install locations + PATH. None if not found."""
    import shutil as _shutil
    plat = _supervisor_platform()
    candidates: "list[str]" = []
    if plat == "Windows":
        pf = os.environ.get("ProgramFiles", r"C:\Program Files")
        pfx86 = os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")
        local = os.environ.get("LOCALAPPDATA", "")
        candidates = [
            os.path.join(pf, "Google", "Chrome", "Application", "chrome.exe"),
            os.path.join(pfx86, "Google", "Chrome", "Application", "chrome.exe"),
        ]
        if local:
            candidates.append(os.path.join(local, "Google", "Chrome", "Application", "chrome.exe"))
    elif plat == "Darwin":
        candidates = [
            "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
            os.path.expanduser("~/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"),
        ]
    else:  # Linux — real Google Chrome only: phase-2 patchright uses
        # channel='chrome' (resolves to Google Chrome, not Chromium), so seeding
        # Chromium would just fail verify — better to surface the install hint.
        for name in ("google-chrome", "google-chrome-stable"):
            p = _shutil.which(name)
            if p:
                return p
    for c in candidates:
        if c and os.path.isfile(c):
            return c
    for name in ("chrome", "google-chrome", "google-chrome-stable"):
        p = _shutil.which(name)
        if p:
            return p
    return None


def _kill_chrome_for_profile(profile_dir: str, graceful: bool = False) -> int:
    """Kill any Chrome (plain OR patchright) whose command line references THIS
    profile dir, so the profile lock is released before the next launcher opens
    it. `graceful=True` asks Chrome to exit CLEANLY so it flushes cookies /
    session to disk first: SIGTERM (proc.terminate) on POSIX, `taskkill /T`
    WITHOUT /F on Windows (#898b — psutil's terminate() is an alias for the
    hard kill() on Windows, so a real WM_CLOSE is required there).
    Boundary-safe via _profile_matches_cmdline — never touches the user's
    personal Chrome (different --user-data-dir) or a sibling worker's profile.
    Best-effort; silent if psutil is absent. Returns the number of processes
    signaled (0 = nothing was running on this profile), so callers can skip
    the flush-grace wait when there was nothing to close.

    Matches on BOTH the raw profile path (as Chrome is launched: the un-resolved
    Path.home()-based `--user-data-dir=`) AND its resolved form, so a home dir
    behind a junction/symlink/8.3-short-name still matches the live Chrome."""
    try:
        import psutil
    except Exception:
        return 0
    raw = str(profile_dir).lower().replace("\\", "/")
    try:
        resolved = str(Path(profile_dir).resolve()).lower().replace("\\", "/")
    except Exception:
        resolved = raw
    targets = {t for t in (raw, resolved) if t}
    signaled = 0
    for proc in psutil.process_iter(["pid", "name", "cmdline"]):
        try:
            if not (proc.info["name"] and "chrom" in proc.info["name"].lower()):
                continue
            cmdline = " ".join(proc.info["cmdline"] or []).lower().replace("\\", "/")
            if any(_profile_matches_cmdline(t, cmdline) for t in targets):
                if graceful:
                    if sys.platform == "win32":
                        # WM_CLOSE to the tree (no /F) — Chrome flushes, then exits.
                        subprocess.run(
                            ["taskkill", "/PID", str(proc.info["pid"]), "/T"],
                            capture_output=True, timeout=10,
                            creationflags=_PS_NO_WINDOW)
                    else:
                        proc.terminate()  # SIGTERM — Chrome flushes cookies, then exits
                else:
                    proc.kill()
                signaled += 1
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        except Exception:
            pass
    return signaled


def _count_chrome_for_profile(profile_dir: str) -> int:
    """#907: read-only sibling of _kill_chrome_for_profile — how many Chrome
    processes currently reference this profile dir. Used to wait for a
    graceful close to actually finish before printing 'Browser closed'."""
    try:
        import psutil
    except Exception:
        return 0
    raw = str(profile_dir).lower().replace("\\", "/")
    try:
        resolved = str(Path(profile_dir).resolve()).lower().replace("\\", "/")
    except Exception:
        resolved = raw
    targets = {t for t in (raw, resolved) if t}
    n = 0
    for proc in psutil.process_iter(["pid", "name", "cmdline"]):
        try:
            if not (proc.info["name"] and "chrom" in proc.info["name"].lower()):
                continue
            cmdline = " ".join(proc.info["cmdline"] or []).lower().replace("\\", "/")
            if any(_profile_matches_cmdline(t, cmdline) for t in targets):
                n += 1
        except Exception:
            pass
    return n


def _chrome_procs_for_profile(profile_dir: str) -> list:
    """#909: ONE process-table scan returning the live psutil.Process objects
    whose cmdline references this profile dir. The old close path re-ran a
    full cmdline scan per signal AND per 0.5s wait tick (up to ~18 scans per
    run close — tens of seconds on a busy machine); callers now scan once and
    wait on the returned handles via psutil.wait_procs."""
    try:
        import psutil
    except Exception:
        return []
    raw = str(profile_dir).lower().replace("\\", "/")
    try:
        resolved = str(Path(profile_dir).resolve()).lower().replace("\\", "/")
    except Exception:
        resolved = raw
    targets = {t for t in (raw, resolved) if t}
    procs = []
    for proc in psutil.process_iter(["pid", "name", "cmdline"]):
        try:
            if not (proc.info["name"] and "chrom" in proc.info["name"].lower()):
                continue
            cmdline = " ".join(proc.info["cmdline"] or []).lower().replace("\\", "/")
            if any(_profile_matches_cmdline(t, cmdline) for t in targets):
                procs.append(proc)
        except Exception:
            pass
    return procs


async def _close_profile_browser_neatly(profile_dir: str) -> dict:
    """#907/#909: graceful close of a profile's Chrome with a bounded wait so
    the caller can honestly report 'Browser closed' — WM_CLOSE/SIGTERM first
    (Chrome flushes cookies + session to the profile; run RESULTS are not
    saved here on purpose — they already ride the run's checkpoints), up to
    ~8s for a clean exit, then a hard sweep of any remnant. Silent (no
    per-PID chatter) by design; returns {procs, elapsed_sec, hard_killed} so
    the --login ✓ line can carry the honest numbers.

    #909 rewrite: ONE scan (_chrome_procs_for_profile) + ONE batched taskkill
    (multi-/PID is a single spawn; the old shape spawned taskkill once per
    Chrome child, 10-30 sequential ~100-300ms spawns) + psutil.wait_procs on
    the collected handles instead of a full process-table rescan every 0.5s.
    All blocking psutil/subprocess work runs via to_thread so the caller's
    terminal spinner keeps animating."""
    _t0 = time.time()
    stats = {"procs": 0, "elapsed_sec": 0.0, "hard_killed": 0}
    try:
        import psutil
    except Exception:
        return stats
    procs = await asyncio.to_thread(_chrome_procs_for_profile, profile_dir)
    stats["procs"] = len(procs)
    if not procs:
        return stats

    def _graceful_signal_all():
        if sys.platform == "win32":
            # One spawn for the whole set: taskkill accepts repeated /PID.
            # No /F — WM_CLOSE lets Chrome flush; per-PID "could not be
            # terminated" noise for mid-tree children is expected and the
            # wait+hard sweep below covers whatever graceful missed.
            args = ["taskkill"]
            for p in procs:
                args += ["/PID", str(p.pid)]
            args.append("/T")
            try:
                subprocess.run(args, capture_output=True, timeout=15,
                               creationflags=_PS_NO_WINDOW)
            except Exception:
                pass
        else:
            for p in procs:
                try:
                    p.terminate()  # SIGTERM — Chrome flushes, then exits
                except Exception:
                    pass

    await asyncio.to_thread(_graceful_signal_all)
    try:
        _gone, _alive = await asyncio.to_thread(psutil.wait_procs, procs, 8)
    except Exception:
        _alive = [p for p in procs if p.is_running()]
    if _alive:
        stats["hard_killed"] = len(_alive)
        for p in _alive:
            try:
                p.kill()
            except Exception:
                pass
        await asyncio.sleep(0.5)  # let the profile lock release
    stats["elapsed_sec"] = round(time.time() - _t0, 1)
    return stats


# ── #907: --login ↔ serve coordination marker ────────────────────────────────
# --login stamps this file before closing the backend's Chrome; the serve
# process checks it when its browser dies so a login interruption is paused
# at a checkpoint with an honest card instead of being treated as a crash
# (whose silent auto-retry would relaunch Chrome onto the profile the user
# is actively signing in on — a kill/relaunch fight).
_LOGIN_MARKER_NAME = "login_in_progress.json"


def _login_marker_path() -> Path:
    return Path.home() / ".super-research" / _LOGIN_MARKER_NAME


def _write_login_marker() -> None:
    try:
        p = _login_marker_path()
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps({"ts": int(time.time() * 1000), "pid": os.getpid()}),
                     encoding="utf-8")
    except Exception:
        pass


def _clear_login_marker() -> None:
    try:
        _login_marker_path().unlink(missing_ok=True)
    except Exception:
        pass


def _login_interrupt_active(max_age_sec: int = 30 * 60) -> bool:
    """True while a --login run is in flight (marker present + fresh + its
    process still ALIVE). The age cap keeps a hard-killed --login (marker
    never cleaned up) from classifying every future browser crash as a
    login interrupt forever.

    #929: pid-liveness gate added. The stakes rose when fail_agent gained
    its login-teardown suppression — with only the age check, a taskkill'd
    /power-lossed --login (atexit clear never ran) would silently swallow
    every REAL per-agent [Retry][Skip] card on a healthy run for up to 30
    minutes. The marker records the --login process pid (_write_login_marker);
    a recorded-but-dead pid means no login is in flight. Same liveness
    pattern as _enumerate_ongoing_runs' worker-lock check. Legacy/pid-less
    markers keep the pure age check."""
    try:
        p = _login_marker_path()
        if not p.exists():
            return False
        data = json.loads(p.read_text(encoding="utf-8"))
        ts = float(data.get("ts", 0)) / 1000.0
        if not (ts > 0 and (time.time() - ts) < max_age_sec):
            return False
        pid = int(data.get("pid", 0) or 0)
        if pid > 0:
            try:
                import psutil
                if not psutil.pid_exists(pid):
                    return False
            except Exception:
                pass  # psutil unavailable → degrade to the age-only check
        return True
    except Exception:
        return False


def _enumerate_ongoing_runs() -> "list[dict]":
    """#907: best-effort list of runs a live backend is mid-flight on —
    [{worker, run_id, title}]. Reads the worker claim locks
    (queues/.worker.N.lock, JSON with pid/run_id — see _write_worker_lock)
    gated on PID-liveness + the 8h stale-age guard, then meta.json for a
    human title. Local-disk only, so it works even when the HTTP API is
    unreachable. Empty list on any failure — callers degrade to the plain
    profile walk."""
    out: "list[dict]" = []
    try:
        import psutil
    except Exception:
        return out
    try:
        lock_dir = Path(__file__).parent / "queues"
        if not lock_dir.exists():
            return out
        now_ms = int(time.time() * 1000)
        for lock_file in sorted(lock_dir.glob(".worker.*.lock")):
            try:
                data = json.loads(lock_file.read_text(encoding="utf-8"))
                wid = int(data.get("worker_id") or 0)
                pid = int(data.get("pid") or 0)
                started = int(data.get("started_at") or 0)
                run_id = str(data.get("run_id") or "").strip()
                if wid <= 0 or pid <= 0 or not run_id:
                    continue
                if not psutil.pid_exists(pid):
                    continue
                if started <= 0 or (now_ms - started) > _WORKER_LOCK_PID_REUSE_MAX_AGE_MS:
                    continue
                qdir = lock_dir / run_id
                if (qdir / ".stop").exists():
                    continue  # already terminally stopped — nothing to close
                # #910: skip runs that are already parked or over. A prior
                # --login (or an in-process pause) leaves delivery.json at
                # "paused" — the run's browser is gone and its card is up,
                # so a --login re-run must not re-list it as "ongoing"
                # (live 2026-07-06: a re-run showed 1 phantom ongoing run).
                try:
                    _dstat = json.loads(
                        (qdir / "delivery.json").read_text(encoding="utf-8")
                    ).get("status", "")
                except Exception:
                    _dstat = ""
                if _dstat in ("completed", "stopped", "paused"):
                    continue
                title = run_id
                try:
                    meta = json.loads((qdir / "meta.json").read_text(encoding="utf-8"))
                    title = str(meta.get("title") or meta.get("topic") or run_id)
                except Exception:
                    pass
                out.append({"worker": wid, "run_id": run_id, "title": title})
            except Exception:
                continue
    except Exception:
        return out
    return out


def _backend_is_running() -> bool:
    """True if a Super Research backend (--serve / --daemon-loop) looks like it's
    running on this machine — so --login can warn before it disrupts an active
    run (killing the profile's Chrome mid-research). Best-effort process scan;
    False if psutil is absent."""
    try:
        import psutil
    except Exception:
        return False
    me = os.getpid()
    for proc in psutil.process_iter(["pid", "cmdline"]):
        try:
            if proc.info["pid"] == me:
                continue
            cl = " ".join(proc.info["cmdline"] or [])
            if ("--serve" in cl or "--daemon-loop" in cl) and (
                "research.py" in cl.lower() or "superresearch" in cl.lower()
            ):
                return True
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            pass
        except Exception:
            pass
    return False


async def _close_chrome_gracefully(proc, profile_dir: str) -> None:
    """Close the seed Chrome so it FLUSHES cookies/session to disk before exit —
    a hard TerminateProcess can drop auth cookies the user just set. Windows uses
    `taskkill /T` WITHOUT /F (a real WM_CLOSE to the tree); POSIX uses SIGTERM
    (Chrome shuts down cleanly on it). Waits a few seconds for a clean exit, then
    hard-kills any remnant + releases the profile lock."""
    import subprocess as _sp
    plat = _supervisor_platform()
    try:
        if plat == "Windows":
            _sp.run(["taskkill", "/PID", str(proc.pid), "/T"],
                    capture_output=True, timeout=15, creationflags=_PS_NO_WINDOW)
        elif plat == "Darwin":
            # `proc` here is the `open -na` launcher (it exits the moment Chrome
            # spawns), so SIGTERM-ing proc.pid does nothing to Chrome. SIGTERM the
            # real Chrome bound to THIS profile so it flushes cookies before exit.
            _kill_chrome_for_profile(profile_dir, graceful=True)
        else:  # Linux — proc.pid IS the Chrome process
            proc.terminate()  # SIGTERM — Chrome flushes + exits cleanly
    except Exception:
        pass
    if plat == "Darwin":
        # No launcher pid to poll (it's already gone) — give the SIGTERM'd Chrome
        # a few seconds to flush + exit before the hard-kill sweep below.
        await asyncio.sleep(6.0)
    else:
        for _ in range(16):  # up to ~8s for a clean flush + exit
            try:
                if proc.poll() is not None:
                    break
            except Exception:
                break
            await asyncio.sleep(0.5)
    # Hard-kill any remnant (detached child, stuck window) + free the lock.
    _kill_chrome_for_profile(profile_dir)
    await asyncio.sleep(1.5)


async def _seed_login_plain_chrome(profile_dir: str, service_urls: "list[str]", label: str, reopen: bool = False) -> bool:
    """Phase 1: open the user's REAL Chrome (NO automation/CDP) on `profile_dir`
    with the platform tabs, so the human signs in + clears any human-check on the
    one surface where automation is blocked. Blocks on Enter, then fully closes
    Chrome so patchright can reopen the profile for phase-2 verify. Returns True
    if Chrome was launched (False = no Chrome found). Re-raises KeyboardInterrupt
    (universal Ctrl+C cancel) after closing Chrome."""
    import subprocess as _sp
    chrome = _find_chrome_executable()
    if not chrome:
        print(f"  {_c(_WARN, 'Google Chrome not found — cannot open a real browser to sign in.')}")
        print(f"  {_c(_DIM, '     ' + _chrome_install_hint())}")
        return False
    # Make sure the profile isn't already open (a live Chrome on this dir would
    # make our launch attach to it / no-op, and would hold the lock).
    # #898b: graceful first — a hard kill here can drop a seconds-old sign-in
    # before Chrome flushes it to disk (the "had to relogin" report). Only if
    # something was actually running: give it a short flush grace, then
    # hard-sweep any remnant so the profile lock is still guaranteed free.
    if _kill_chrome_for_profile(profile_dir, graceful=True):
        await asyncio.sleep(4.0)
        _kill_chrome_for_profile(profile_dir)
    chrome_args = [
        f"--user-data-dir={profile_dir}",
        "--no-first-run",
        "--no-default-browser-check",
    ] + list(service_urls)
    if _supervisor_platform() == "Darwin":
        # macOS: launching the Chrome BINARY directly while the user's normal
        # Chrome is running is intercepted by the app singleton broker — it
        # forwards the URLs to the ALREADY-RUNNING Chrome (their personal default
        # profile) and IGNORES --user-data-dir. The sign-in then lands in the wrong
        # profile, and phase-2 verify (patchright, which bypasses the broker)
        # reopens an EMPTY dedicated profile. `open -na <app> --args …` forces a
        # brand-new instance bound to our dedicated profile dir. Derive the .app
        # bundle from the binary path (…/Google Chrome.app/Contents/MacOS/…).
        app = chrome.split("/Contents/MacOS/")[0] if "/Contents/MacOS/" in chrome else chrome
        args = ["open", "-na", app, "--args"] + chrome_args
    else:
        # Windows + Linux: a direct binary launch honors --user-data-dir — a
        # distinct data-dir gets its own instance even if the user's Chrome runs.
        args = [chrome] + chrome_args
    # Instrumentation (mac login-profile bug): the EXACT seed invocation + the
    # fully-resolved profile abspath + HOME. Diff this against the `[browser]
    # launch` line verify/run emit — they MUST name the same dir, and the seed
    # writes cookies with the REAL macOS Keychain key (plain Chrome via `open`),
    # which the run now also uses (Browser.start drops --use-mock-keychain on macOS).
    try:
        _abs_seed = str(Path(profile_dir).resolve())
    except Exception:
        _abs_seed = str(profile_dir)
    log(f"[login] seed plain-Chrome profile_dir={_abs_seed} home={Path.home()} "
        f"invocation={' '.join(args)}")
    if reopen:
        print(f"  {_c(_DIM, 'Reopening your real Chrome — fix the flagged platforms (sign in / switch to Pro).')}")
    else:
        print(f"  {_c(_DIM, 'Opening your real Chrome — ' + label + '. Sign in normally.')}")
    try:
        proc = _sp.Popen(args)
    except Exception as e:
        log(f"login: failed to launch plain Chrome: {e}", "WARN")
        print(f"  {_c(_WARN, 'Could not launch Chrome: ' + str(e)[:120])}")
        return False
    print()
    print(f"  {_c(_BOLD, 'In the Chrome window that just opened:')}")
    print(f"    {_c(_DIM, '1.')} Sign in to each platform (ChatGPT, Gemini, Claude, NotebookLM).")
    print(f"    {_c(_DIM, '2.')} Complete any \"verify you are human\" check yourself.")
    print(f"    {_c(_DIM, '3.')} Use your Pro / paid account where you have one.")
    print()
    try:
        await asyncio.to_thread(input, f"  {_c(_ACCENT, '>')}  Press Enter when you are signed in and done  ")
        # Give Chrome a beat to flush a just-completed sign-in / cleared security
        # check to the profile's cookie DB before we close it — a login finished a
        # moment before Enter may not be on disk yet, and phase 2 reopens the SAME
        # profile immediately. Cheap insurance on top of the graceful-close flush.
        # Only on the normal path — Ctrl+C must cancel instantly (skips this).
        await asyncio.sleep(2.5)
    except (EOFError, KeyboardInterrupt):
        print()
        raise
    finally:
        # Always close the seed Chrome (gracefully, so cookies flush) so the
        # profile is free for phase 2.
        await _close_chrome_gracefully(proc, profile_dir)
    return True


async def _verify_platform_logins(browser, services, cua_client, *, results, emit_row, flags=None) -> None:
    """Phase 2: on the now-signed-in profile, verify each platform is logged in
    (+ soft Pro-tier where it applies) with patchright + CUA. This only NAVIGATES
    authenticated pages — never a sign-in form — so it isn't hit by the automation
    block. Records per-platform bool into `results` (mutated); if `flags` is given,
    records per-platform status: 'ok' | 'free' | 'missing' | 'no_check'."""
    for idx, (name, url, key) in enumerate(services):
        if idx > 0:
            await asyncio.sleep(random.uniform(1.5, 3.0))
        try:
            # open_isolated_tab (not new_tab) so self.page isn't clobbered by a
            # tab we immediately close (documented anti-pattern at :16891).
            tab = await browser.open_isolated_tab(url)
        except Exception as e:
            log(f"verify: failed to open {name}: {e}", "WARN")
            results[key] = False
            emit_row(name, False, "could not open")
            continue
        await asyncio.sleep(4.0)  # SPA hydration (matches Phase 0 / pair timing)
        # A Cloudflare / human-verification interstitial serves on the CANONICAL
        # host (e.g. claude.ai with no /login path), so it slips past
        # _LOGIN_HOST_NEGATIVES and then reads to vision as "no authenticated app"
        # → a FALSE "not signed in" that nags the user to re-log-in an account that
        # is actually fine (the Claude first-login-didn't-persist E2E). A challenge
        # is NOT a logout — the user already signed in on the plain-Chrome pass.
        # Detect it, give it one beat to settle (managed challenges auto-clear; a
        # freshly-warmed cf_clearance often validates on the second look), and if it
        # still blocks, record no_check ("likely still signed in") instead of missing
        # so we never force a bogus re-login. We never bypass the check — we just
        # refuse to misreport it as a logout.
        _blocked, _cf = await detect_human_verification(tab, key, name)
        if _blocked:
            await asyncio.sleep(6.0)
            _blocked, _cf = await detect_human_verification(tab, key, name)
        status, label = "missing", ""
        try:
            current_url = (tab.url or "").lower()
        except Exception:
            current_url = ""
        # GROUND-TRUTH CROSS-CHECK (2026-07-09). The navigation/vision layer below
        # can be DEFEATED without meaning "logged out": claude.ai (and any
        # Cloudflare-fronted host) can throw a managed challenge on the canonical
        # host, and there may be no API key for the vision pass. The old code
        # fail-OPEN in those cases (status="no_check", which counts as signed in),
        # which SILENTLY accepts a genuinely logged-out platform — live repro
        # 2026-07-09: profile 1's claude.ai jar held only `pendingLogin` (NO
        # `sessionKey`; the login never completed), yet Stage-4 verify passed it
        # because the Cloudflare interstitial forced no_check, so the user was
        # never prompted to finish signing in. The auth-cookie read is the reliable
        # signal (host-only session cookie; it never lies signed-IN for a
        # logged-out jar — see _PHASE_GATE_AUTH_COOKIES), so use it to disambiguate
        # the no_check branches: cookie ABSENT ⇒ genuinely "missing"; cookie
        # PRESENT ⇒ keep the fail-open no_check (a real session the challenge just
        # hid — don't nag a re-login). Only downgrade on an AFFIRMATIVE absent
        # (`is False`); on unknown (no cookie spec / probe error) keep prior behavior.
        # Read the jar OURSELVES (not via _platform_auth_cookie_present) so a
        # read FAILURE stays distinct from cookie ABSENCE: None = couldn't read
        # (keep the prior fail-open no_check); True/False = definitive.
        _has_auth_cookie = None
        if key in _PHASE_GATE_AUTH_COOKIES:
            try:
                _jar = await browser.context.cookies()
                _has_auth_cookie = _auth_cookie_present_in(_jar, key)
            except Exception:
                _has_auth_cookie = None
        if _blocked:
            if _has_auth_cookie is False:
                status, label = "missing", f"not signed in — no session cookie ({_cf} check blocked the visual verify)"
            else:
                status, label = "no_check", f"couldn't verify — {_cf} check in the way (you're likely still signed in)"
        elif any(h in current_url for h in _LOGIN_HOST_NEGATIVES):
            status, label = "missing", "not signed in"
        elif not cua_client:
            if _has_auth_cookie is False:
                status, label = "missing", "not signed in — no session cookie"
            else:
                status, label = "no_check", "no vision check (no API key)"
        else:
            try:
                async with _async_spinner_ctx(f"Verifying {name}"):
                    _ok = await verify_login_cua(tab, key, cua_client)
            except CuaUnavailableError as _cua_err:
                # AI service down / key rate-limited / over cap — NOT a logout.
                # Accept on the URL pass (login-host negatives already cleared)
                # rather than falsely reporting "not signed in" — UNLESS the
                # session cookie is affirmatively absent (then it IS missing, and
                # vision being down must not mask that).
                log(f"verify: CUA unavailable for {key} ({_cua_err}) — cookie cross-check", "WARN")
                if _has_auth_cookie is False:
                    status, label = "missing", "not signed in — no session cookie"
                else:
                    status, label = "no_check", "signed in (vision check unavailable)"
            except Exception as e:
                log(f"verify: CUA error {key}: {e}", "WARN")
                status, label = "missing", "not signed in"
            else:
                if not _ok:
                    status, label = "missing", "not signed in"
                elif key in _PRO_TIER_PLATFORMS:
                    try:
                        tier = await _cua_pro_tier_call(tab, key, cua_client)
                    except Exception:
                        tier = "unsure"
                    if tier == "free":
                        status, label = "free", "Free tier — Phase 1/2 quality will be degraded"
                    elif tier == "pro":
                        status, label = "ok", "Pro ✓"
                    else:  # unsure — fail-open (assume Pro), but show it ran
                        status, label = "ok", "signed in · tier unconfirmed"
                else:
                    status = "ok"
        try:
            await tab.close()
        except Exception:
            pass
        results[key] = (status != "missing")
        if flags is not None:
            flags[key] = status
        emit_row(name, status != "missing", label)


async def _probe_profile_logins(profile_dir, *, security_check, results) -> str:
    """Open the profile READ-ONLY (patchright, ZERO page navigations) and record
    TRUTHFUL per-platform session presence into `results` via cookie reads — the
    profile's sessions are left completely untouched (no Chrome kill/relaunch, no
    sign-in tabs, no clear). Runs the optional `security_check` on the same context
    (a cookie read, zero page loads — DGOPS-7451 must not be skippable). Returns
    'ok' | 'refused' | 'probe_failed' ('probe_failed' = the context/probe itself
    couldn't run, e.g. the profile is locked by a live Chrome — NOT 'signed out').
    Shared by the `--login` pre-probe and the verify_mode='skip' branch."""
    browser = Browser(profile_dir, headless=False)
    # #907: silence Browser.start's orphan-sweep chatter for the login
    # terminal — the per-PID "Closing orphaned Chrome …" flood buried the
    # branded flow (the sweep itself still runs; with the ongoing runs
    # already closed neatly by run_login there's little left to sweep).
    global _BROWSER_SWEEP_QUIET
    _BROWSER_SWEEP_QUIET = True
    try:
        async with _async_spinner_ctx("Checking the profile"):
            await browser.start()
        if security_check is not None:
            try:
                if await security_check(browser):
                    return "refused"
            except Exception as _sec_err:
                log(f"login: security check errored (continuing): {_sec_err}", "WARN")
        for _n2, _u2, _k2 in _LOGIN_SERVICES:
            results[_k2] = await _platform_auth_cookie_present(browser, _k2)
        return "ok"
    except Exception as _pr_err:
        log(f"login: cookie probe unavailable ({_pr_err}) — trusting the sign-in", "WARN")
        return "probe_failed"
    finally:
        _BROWSER_SWEEP_QUIET = False
        try:
            await browser.close()
        except Exception:
            pass


async def _login_one_profile(profile_dir, cua_client, *, label, results, emit_row,
                             security_check=None, verify_mode="verify",
                             ask_reopen_if_signed_in=False) -> str:
    """Sign in ONE profile — the shared engine for `--login` and pair Step 4.
    Phase 1 = the user's plain Chrome (human signs in on the un-detected surface,
    and can clear any Cloudflare check by hand — a REAL human interaction that
    WARMS the profile). Phase 2 (verification) is now OPTIONAL (2026-07-02):
    automated verify navigations on a brand-new profile are the riskiest bot
    signal, and runs recheck logins at phase time anyway.

    verify_mode:
      'verify' — Phase 2 as before: patchright reopens the profile, runs the
                 optional ``security_check(browser) -> refuse-bool``, verifies
                 each login + Pro tier, offers the reopen-to-fix loop.
      'skip'   — trust the sign-in: no platform navigations at all. Every
                 service is recorded True (the human just signed in). The
                 ``security_check`` still runs (a cookie read on the patchright
                 context — zero page loads, so no bot exposure; DGOPS-7451 must
                 not be skippable).
      'ask'    — after Phase 1, ask "Skip the verification step? [Y/n]" —
                 Enter/y ⇒ 'skip' (default: verification is the bot-score
                 risk), n ⇒ 'verify'.

    ask_reopen_if_signed_in ('--login' walk): BEFORE seeding, probe the profile's
    existing sessions read-only (never kills/relaunches Chrome, never clears it).
    This is the fix for `--login` dragging an already-signed-in profile back
    through sign-in (the old flow always opened the sign-in tabs and hard-killed
    live Chrome, which could drop an unflushed session). Behaviour when the probe
    succeeds — a truthful per-profile Y/N gate (vs silently auto-advancing):
      • fully signed in → "re-open anyway (usually to check / do Human
        Verifications, if any)? [y/N]" — DEFAULT SKIP; declining returns 'ok'
        with the probed state, session 100% untouched.
      • some/all signed out → "Open Chrome to sign in? [Y/n]" — DEFAULT open.
    Declining either just leaves the profile as-is (never cleaned, worker count
    unchanged). On a probe failure (e.g. the profile is locked) it falls through
    to seed, i.e. today's behaviour. Off (pair Step 4) the flow is unchanged.

    Mutates `results`. Returns 'ok' | 'no_chrome' | 'refused'. Raises
    KeyboardInterrupt on Ctrl+C (universal cancel) — the caller handles it."""
    service_urls = [u for _n, u, _k in _LOGIN_SERVICES]
    reopen = False
    resolved_mode: "str | None" = None  # 'ask' answers once, then sticks

    # --login pre-probe: don't force a re-login on an already-signed-in profile.
    # Read the profile's sessions WITHOUT touching them, then let the user decide
    # per profile (state-aware Y/N) whether to open Chrome at all.
    if ask_reopen_if_signed_in:
        _pre = await _probe_profile_logins(
            profile_dir, security_check=security_check, results=results)
        if _pre == "refused":
            return "refused"
        if _pre == "ok":
            _held = [nm for nm, _u, k in _LOGIN_SERVICES if results.get(k)]
            _absent = [nm for nm, _u, k in _LOGIN_SERVICES if not results.get(k)]
            print()
            if _held:
                print(f"  {_c(_OK, '✓')}  {_c(_DIM, 'Signed in: ' + ', '.join(_held))}")
            if _absent:
                print(f"  {_c(_WARN, 'No session:')} {_c(_DIM, ', '.join(_absent))}")
            if _held and not _absent:
                # Fully signed in — DEFAULT skip the re-open (keep session intact).
                question = ("Looks signed in — re-open anyway "
                            f"{_c(_DIM, '(usually to check / do Human Verifications, if any)')}?")
                default_open = False
            else:
                # Some/all signed out — DEFAULT open Chrome so the user can sign in.
                question = "Open Chrome to sign in?"
                default_open = True
            # Ctrl+C = cancel (propagates through the shared reader untouched).
            want_open = await _ask_yes_no(question, default=default_open)
            if not want_open:
                print(f"  {_c(_DIM, 'Left as-is — your sign-in is untouched.')}")
                return "ok"
        # _pre == 'probe_failed' → couldn't read the profile (likely locked by a
        # live Chrome); fall through to seed (today's behaviour — no false skip).

    while True:
        # Phase 1 — plain Chrome sign-in (all tabs). On a reopen the user just
        # fixes the flagged platforms.
        seeded = await _seed_login_plain_chrome(profile_dir, service_urls, label, reopen=reopen)  # may raise KeyboardInterrupt
        if not seeded:
            return "no_chrome"
        mode = resolved_mode or verify_mode
        if mode == "ask":
            print()
            print(f"  {_c(_DIM, 'Optional: verify each sign-in with the automated browser (opens every')}")
            print(f"  {_c(_DIM, 'platform once). On a fresh profile this can trip bot checks — skipping')}")
            print(f"  {_c(_DIM, 'is recommended; runs recheck logins at phase time anyway.')}")
            # Ctrl+C propagates — universal cancel.
            _skip_verify = await _ask_yes_no("Skip the verification step?", default=True)
            mode = "skip" if _skip_verify else "verify"
        # Pin the answer for the [r] reopen-to-fix loop — re-asking there let a
        # habitual Enter (default skip) silently defeat the re-verify the user
        # explicitly chose one prompt earlier.
        resolved_mode = mode
        if mode == "skip":
            # Trust the human sign-in — no platform NAVIGATIONS. But record
            # TRUTHFUL per-platform state via a cookie read on the profile
            # (zero page loads): a user who closed Chrome without signing in
            # must not mint green login badges or a worker slot. The security
            # check (pair F4, DGOPS-7451) rides the same context open.
            _probe = await _probe_profile_logins(
                profile_dir, security_check=security_check, results=results)
            if _probe == "refused":
                return "refused"
            if _probe == "probe_failed":
                # Probe itself failed (not "cookies absent") — fail open: the
                # human just signed in, and phase time rechecks anyway.
                for _n2, _u2, _k2 in _LOGIN_SERVICES:
                    results.setdefault(_k2, True)
            _held = [nm for nm, _u, k in _LOGIN_SERVICES if results.get(k)]
            _absent = [nm for nm, _u, k in _LOGIN_SERVICES if not results.get(k)]
            if _held:
                print(f"  {_c(_DIM, 'Sessions found: ' + ', '.join(_held) + ' — trusting your sign-in (no automated verification).')}")
            if _absent:
                print(f"  {_c(_WARN, 'No session found for:')} {_c(_BOLD, ', '.join(_absent))}")
                print(f"  {_c(_DIM, '     Sign in there with another pass, or continue without — runs recheck at phase time.')}")
            return "ok"
        # Phase 2 — patchright reopens the now-warm profile + verifies.
        flags: "dict[str, str]" = {}
        browser = Browser(profile_dir, headless=False)
        try:
            async with _async_spinner_ctx("Reopening the profile to verify"):
                await browser.start()
            if security_check is not None:
                try:
                    if await security_check(browser):
                        return "refused"
                except Exception as _sec_err:
                    log(f"login: security check errored (continuing): {_sec_err}", "WARN")
            print(f"  {_c(_DIM, 'Checking each sign-in…')}")
            await _verify_platform_logins(
                browser, _LOGIN_SERVICES, cua_client, results=results, emit_row=emit_row, flags=flags)
        finally:
            try:
                await browser.close()
            except Exception:
                pass
        # Anything needing attention: not-signed-in OR Free tier. Offer to reopen
        # the REAL Chrome to fix (retry), or continue as-is (keep Free / skip the
        # missing ones) — the intended retry / continue-with-free / skip flows.
        _missing = [nm for nm, _u, k in _LOGIN_SERVICES if flags.get(k) == "missing"]
        _free = [nm for nm, _u, k in _LOGIN_SERVICES if flags.get(k) == "free"]
        if not _missing and not _free:
            return "ok"
        print()
        if _missing:
            print(f"  {_c(_WARN, 'Not signed in:')} {_c(_BOLD, ', '.join(_missing))}")
        if _free:
            print(f"  {_c(_WARN, 'On Free tier')} {_c(_DIM, '(Phase 1/2 quality degraded):')} {_c(_BOLD, ', '.join(_free))}")
        print(f"  {_c(_DIM, '[r] reopen Chrome to fix   ·   [Enter] continue as-is (keep Free / skip missing)')}")
        try:
            _ans = (await asyncio.to_thread(input, f"  {_c(_ACCENT, '>')}  Choose ")).strip().lower()
        except (EOFError, KeyboardInterrupt):
            raise
        if _ans in ("r", "reopen", "retry"):
            reopen = True
            continue
        return "ok"  # continue-with-free / skip missing → accept current state


async def run_login_flow(
    profile_indices,
    *,
    cua_client=None,
    device_id_for_progress: "str | None" = None,
    allow_add: bool = False,
    verify_mode: str = "skip",
) -> "tuple[dict[int, dict], bool]":
    """The login flow shared by `--login` and pair Step 4:
      Phase 1 — plain Chrome (no automation): human signs in + clears any check.
      Phase 2 — OPTIONAL verification (see _login_one_profile.verify_mode;
      `--login` uses 'skip' — automated verify navigations on fresh profiles are
      the top bot-score signal, and runs recheck logins at phase time anyway).
    Runs for each worker profile in `profile_indices` (the existing workers). With
    `allow_add=True` (used by `--login`), it then offers pair-Stage-4-style
    "Add another browser profile?" prompts — running the SAME sign-in per added
    profile and bumping workerCount (save_worker_count) as each COMPLETES
    (sign-in done; verified too when verify_mode ran a verify) — so `--login`
    can grow the multi-worker profile set exactly like pairing does. Returns
    ({profile_n: {key: bool}}, seeded_any) — seeded_any=False means no profile's
    Chrome could even be launched (e.g. Google Chrome not installed)."""
    services = _LOGIN_SERVICES
    pad = max(len(n) for n, _u, _k in services)
    profile_list = list(profile_indices)
    all_results: "dict[int, dict]" = {}
    seeded_any = False

    def _row(nm, ok, lbl=""):
        mark = _c(_OK, "[ok]") if ok else _c(_WARN, "[--]")
        sfx = f"  {_c(_DIM, lbl)}" if lbl else ""
        print(f"        {mark}  {nm.ljust(pad)}{sfx}")

    async def _do_profile(n: int, total: int, *, ask_reopen: bool = False) -> "tuple[dict, str]":
        nonlocal seeded_any
        profile_dir = str(_profile_dir(n))
        label = "profile" if total <= 1 else f"profile {n}"
        # #898a: pair-Stage-4 style — a plain per-profile header, NOT the
        # "[n/total]" step chrome. Profiles are a walk (one after another,
        # open-ended via the add-loop), not a fixed count of setup steps.
        print()
        print(f"  {_c(_BOLD, f'Profile {n}')}  {_c(_DIM, profile_dir)}")
        results: "dict[str, bool]" = {}
        try:
            status = await _login_one_profile(
                profile_dir, cua_client, label=label, results=results, emit_row=_row,
                verify_mode=verify_mode, ask_reopen_if_signed_in=ask_reopen)
        except (EOFError, KeyboardInterrupt):
            raise  # propagate the cancel (caller/main handles it)
        except Exception as e:
            log(f"login: profile {n} failed: {e}", "WARN")
            print(f"  {_c(_WARN, 'Could not complete this profile: ' + str(e)[:120])}")
            status = "error"
        if status != "no_chrome":
            seeded_any = True
        # FE login badges are bound to profile 1 (paired devices only; best-effort).
        if n == 1 and status == "ok" and device_id_for_progress and _firebase_db:
            try:
                _firebase_db.collection("devices").document(device_id_for_progress).update({
                    "logins": {k: bool(results.get(k, False)) for _n, _u, k in services},
                })
            except Exception:
                pass
        all_results[n] = results
        return results, status

    total = max(profile_list) if len(profile_list) > 1 else 1
    # #898a: one-line walk intro — the existing profiles are being CHECKED
    # (eyeball each sign-in, solve any human-check), not re-created.
    if profile_list:
        _n_prof = len(profile_list)
        print()
        print(f"  {_c(_BOLD, str(_n_prof))} browser profile{'s' if _n_prof != 1 else ''} detected — "
              f"walking through each so you can check its sign-ins and solve any human-check.")
    for n in profile_list:
        # ask_reopen: existing profiles get the read-only pre-probe + per-profile
        # Y/N so a signed-in profile isn't dragged back through sign-in (and never
        # auto-advances silently). Added profiles below use the add-loop's own gate.
        await _do_profile(n, total, ask_reopen=True)

    # `--login` add-loop: offer to set up ADDITIONAL worker profiles, pair-style,
    # so a single-worker install can grow to multi-worker from --login (matching
    # pair Stage 4). Only after at least one profile's Chrome launched.
    if allow_add and seeded_any:
        base = max(profile_list) if profile_list else 1
        try:
            save_worker_count(base)  # anchor the floor (also handles a downgrade)
        except Exception as _wc_err:
            log(f"save_worker_count({base}) failed (continuing): {_wc_err}", "WARN")
        print()
        print(f"  {_c(_DIM, 'Each browser profile = 1 concurrent run slot. Recommended: 2 total.')}")
        print(f"  {_c(_DIM, 'Past your slot count, fired runs go into the queue.')}")
        print()
        next_n = base + 1
        while True:
            try:
                _add_more = await _ask_yes_no(
                    f"Add another browser profile (profile {next_n})?",
                    default=False,
                    # The question just named profile N, so N is a yes; the count
                    # they already have reads as "keep what I have" — a no. Both
                    # are echoed back before being acted on.
                    yes_aliases=(str(next_n),),
                    no_aliases=(str(next_n - 1),),
                )
            except (EOFError, KeyboardInterrupt):
                print()
                log(f"login add-loop: cancel at profile {next_n} prompt — keeping workerCount={next_n - 1}", "INFO")
                break
            if not _add_more:
                _say_profile_capacity(next_n - 1)
                break
            try:
                results, status = await _do_profile(next_n, next_n)
            except (EOFError, KeyboardInterrupt):
                print()
                log(f"login add-loop: cancel during profile {next_n} — keeping workerCount={next_n - 1}", "INFO")
                break
            n_all_ok = status == "ok" and all(results.get(k, False) for _n, _u, k in services)
            print()
            if n_all_ok:
                try:
                    save_worker_count(next_n)
                except Exception as _wc_err:
                    log(f"save_worker_count({next_n}) failed (continuing): {_wc_err}", "WARN")
                print(f"  {_c(_OK, '✓')}  Profile {next_n} ready — concurrent capacity is now {next_n}.")
                next_n += 1
            else:
                # Don't increment — the dir may hold partial cookies; user can wipe
                # via --unpair --deep and retry that slot.
                print(f"  {_c(_WARN, '⚠')}  Profile {next_n} incomplete — keeping workerCount={next_n - 1}.")

    return all_results, seeded_any


async def run_login() -> None:
    """`--login`: open a REAL (non-automated) Chrome per worker profile so you can
    sign in to the platforms by hand — the reliable way past Google's
    "browser may not be secure" + Cloudflare's human-check, which block the
    pipeline's automated browser at the sign-in page. Signing in (and solving
    any human-check) in real Chrome also WARMS the profile's trust. There is no
    automated verification pass (2026-07-02 — verify navigations on a fresh
    profile are the top bot-score signal; runs recheck logins at phase time);
    after each profile it offers the pair-style "add another profile?" loop.
    Re-run whenever a session expires. No pairing required; runs from a source
    checkout or the installed command."""
    tm.tm_emit(tm.Ev.LOGIN_STARTED)
    _branded_header("aditus", _BOLD + _ACCENT, "sign in on a real browser")
    print()
    print(f"  {_c(_DIM, 'We open your real Chrome — sign in to each platform (+ solve any check).')}")
    print(f"  {_c(_DIM, 'Your sign-ins are saved to the profile; runs pick them up directly.')}")

    # Guard: --login frees + reopens each profile, which closes the browser a
    # running backend is using. Warn before disrupting an active research.
    # #909: the full-system process scan takes seconds on a busy machine —
    # run it off-thread under a spinner instead of a silent hang.
    async with _async_spinner_ctx("Checking for a running backend"):
        _backend_up = await asyncio.to_thread(_backend_is_running)
    if _backend_up:
        print()
        print(f"  {_c(_WARN, '⚠')}  {_c(_BOLD, 'A Super Research backend is running.')}")
        print(f"  {_c(_DIM, '     --login pauses any ongoing research at a checkpoint and closes its browser.')}")
        print(f"  {_c(_DIM, '     Interrupted runs can be resumed from the app (Retry on the alert) after login.')}")
        try:
            _go_on = await _ask_yes_no("Continue anyway?", default=False)
        except (EOFError, KeyboardInterrupt):
            print()
            return
        if not _go_on:
            print(f"  {_c(_DIM, 'Aborted. Stop the backend, then re-run')}  {_c(_BOLD, _PROG + ' --login')}{_c(_DIM, '.')}")
            return
        # #907: stamp the login marker BEFORE touching any Chrome so the
        # serve process classifies the coming browser death as a login
        # interruption (pause-at-checkpoint + honest "Interrupted by the
        # login command" card with a Retry) instead of a crash it should
        # silently rebuild from — the rebuild would relaunch Chrome onto
        # the very profile the user is about to sign in on. Cleared at
        # process exit (atexit) + a 30-min staleness cap on the serve side
        # covers a hard-killed --login.
        _write_login_marker()
        import atexit as _atexit
        _atexit.register(_clear_login_marker)
        # Neatly close ongoing runs first — one line per run instead of the
        # old per-PID orphan-sweep flood from Browser.start(). #909: live
        # spinner while each close runs (the old shape was silent for its
        # whole 10-30s), and the ✓ line carries the honest numbers.
        _ongoing_runs = _enumerate_ongoing_runs()
        if _ongoing_runs:
            print()
            print(f"  {_c(_BOLD, f'Found {len(_ongoing_runs)} ongoing run(s)')}"
                  f"{_c(_DIM, ' — closing each at a checkpoint (resume from the app after login).')}")
            for _ri, _run in enumerate(_ongoing_runs, 1):
                _title = str(_run["title"])
                if len(_title) > 48:
                    _title = _title[:47] + "…"
                async with _async_spinner_ctx(f"Closing Run {_ri} — {_title}"):
                    _cs = await _close_profile_browser_neatly(str(_profile_dir(_run["worker"])))
                _closed_note = (f"Browser closed ({_cs['elapsed_sec']}s)"
                                if _cs.get("procs") else "Browser already closed")
                print(f"  {_c(_OK, '✓')}  Closing Run {_ri} — {_title} → {_closed_note}")
            await asyncio.sleep(1)

    # CUA vision verifier (optional — verify degrades to a URL-only check without it).
    cua_client = None
    _key = resolve_api_key()
    if _key:
        try:
            import anthropic as _anthropic
            cua_client = _anthropic.Anthropic(api_key=_key)
        except Exception as e:
            log(f"login: could not init CUA client ({e}) — URL-only verification", "WARN")

    device_id = None
    try:
        device_id = load_device_id()
    except Exception:
        device_id = None

    n_workers = load_worker_count()
    results, seeded_any = await run_login_flow(
        range(1, n_workers + 1),
        cua_client=cua_client,
        device_id_for_progress=device_id,
        allow_add=True,  # offer the pair-style "add another profile?" loop
        verify_mode="skip",  # Phase 1 only — no automated verify navigations (2026-07-02)
    )

    # Summary across all profiles (results = cookie-probed session presence).
    print()
    _any_ok = any(any(r.values()) for r in results.values())
    _missing_names = sorted({
        name
        for _n, r in results.items()
        for name, _u, key in _LOGIN_SERVICES if not r.get(key, False)
    })
    if _any_ok:
        print(f"  {_c(_OK, '✓')}  {_c(_BOLD, 'Done.')} {_c(_DIM, 'Signed-in platforms are saved to the profile — runs will reuse them.')}")
        if _missing_names:
            print(f"  {_c(_WARN, '⚠')}  No session found for: {_c(_BOLD, ', '.join(_missing_names))}")
            print(f"  {_c(_DIM, '     Re-run')}  {_c(_BOLD, _PROG + ' --login')}  {_c(_DIM, 'to sign in there (or sign in during the next run).')}")
    elif not seeded_any:
        print(f"  {_c(_WARN, '⚠')}  {_c(_BOLD, 'Could not open Google Chrome.')}")
        print(f"  {_c(_DIM, '     ' + _chrome_install_hint())}")
    else:
        print(f"  {_c(_WARN, '⚠')}  {_c(_BOLD, 'Sign-in did not complete.')}")
        print(f"  {_c(_DIM, '     If Chrome kept looping the human-check, it is likely your network/IP')}")
        print(f"  {_c(_DIM, '     (VPN / datacenter). Try a residential, non-VPN connection and re-run.')}")
    tm.tm_emit(tm.Ev.LOGIN_FINISHED, ok=bool(_any_ok),
               count=len(_missing_names))
    print()
    print(f"  {_c(_ACCENT, 'Next')}")
    print(f"    {_c(_DIM, '›')} {_c(_BOLD, _PROG + ' --serve')}   {_c(_DIM, '# run the backend')}")
    print(f"    {_c(_DIM, '›')} {_c(_BOLD, _PROG + ' --login')}   {_c(_DIM, '# re-run anytime a sign-in expires')}")
    print()


async def _continue_pair_stages_2_to_5(
    profile_dir: str,
    *,
    linked_uid: str,
    linked_email: str,
    initial_paired_uid: "str | None",
    token: str,
    device_id_for_progress: "str | None",
) -> None:
    """Stages 2-5 of pair — On Startup → API keys → Browser logins → Ready.

    Shared between legacy `run_pair` (whose Stage 1 mints a research_token
    and waits for the app to claim it) and user-mode `cmd_pair_v2` (whose
    Stage 1 is the pollSecret + customToken handshake). Each Stage-1
    flow pre-fills the parameters this helper needs.

    `_push_firestore_progress` writes per-platform login state to:
      - `devices/{device_id_for_progress}.logins` when in user-mode
        (rule allows synth-user updates of [lastHeartbeat, status,
        logins, authMode] only — so we don't write setupState /
        lastSetupCheck in this branch),
      - `research_tokens/{token}.{logins, setupState, lastSetupCheck}`
        otherwise (legacy, unchanged behavior).
    """
    _initial_paired_uid = initial_paired_uid  # legacy local-var alias

    # ══════════════════════════════════════════════════════════════════════
    # [2/5] ON STARTUP — ask whether to enable On Startup mode. We only
    #       CAPTURE the answer here; the actual arming (schtasks install
    #       + detached daemon-loop spawn) happens in Stage 5 AFTER logins
    #       succeed, so an aborted login can't leave Firestore with
    #       supervised=true while platforms are half-logged-in.
    # ══════════════════════════════════════════════════════════════════════
    tm.tm_emit(tm.Ev.PAIR_STAGE_REACHED, stage=2)
    _setup_step(2, 5, "On Startup")
    print(f"  {_c(_DIM, 'Keep the backend running in the background?')}")
    print(f"  {_c(_DIM, 'It will auto-start when you log in and stay alive through crashes')}")
    print(f"  {_c(_DIM, 'and reboots. You can turn it off anytime with --retire.')}")
    print()
    enable_on_startup = False
    try:
        enable_on_startup = await _ask_yes_no("Enable On Startup?", default=True)
    except EOFError:
        # No stdin (piped / non-interactive) — keep the safe default (skip
        # arming) and continue, rather than aborting a scripted pair.
        enable_on_startup = False
        print()
    except KeyboardInterrupt:
        # Ctrl+C = cancel the whole pair. Universal rule: Ctrl+C always cancels
        # the command; use the explicit prompt options to skip a step. The
        # browser isn't open yet; returning False makes cmd_pair_v2 revert the
        # partial pair (device doc + token) so no ghost device is left.
        print()
        log("Pairing cancelled by user (Stage 2 — On Startup)", "INFO")
        return False
    print()
    if enable_on_startup:
        print(f"  {_c(_OK, '✓')}  On Startup will be enabled after the logins finish.")
    else:
        print(f"  {_c(_DIM, '     Skipped. You will run --serve manually in step 5.')}")
        print(f"  {_c(_DIM, '     Enable later with:')}  {_c(_BOLD, f'{_PROG} --resurrect')}")
    # Mirror the Stage 2 intent to the device doc so the FE Account-page
    # On Startup toggle flips in real time. The actual supervisor arm
    # still happens in Stage 5; if it fails the user can fix via
    # --resurrect later. Best-effort.
    if device_id_for_progress:
        _pair_patch_device(device_id_for_progress, {"supervised": bool(enable_on_startup)})
    print()

    # ══════════════════════════════════════════════════════════════════════
    # [3/5] API KEYS — detect-or-prompt for Anthropic + Gemini BEFORE
    #       browser logins so the keys (especially Anthropic) are available
    #       for the CUA + Vision verification path during Stage 4. Without
    #       this ordering, login verification falls back to Playwright-only
    #       (less rigorous) and the Pro-tier check can't run at all.
    #       Each key is independently skippable; pair continues either way.
    #       On paste: writes Firestore (canonical, cross-device, matches FE
    #       Account page — or via FE bridge in user-mode, per D5c-2) +
    #       os.environ (current session) + busts the resolver cache so the
    #       very-next resolve_api_key() call (in the CUA-client init at the
    #       top of Stage 4) sees the new key. NOT written to .dg-supervisor
    #       .env — would create a 3rd source of truth and drift on rotation.
    # ══════════════════════════════════════════════════════════════════════
    tm.tm_emit(tm.Ev.PAIR_STAGE_REACHED, stage=3)
    _setup_step(3, 5, "API keys")
    print(f"  {_c(_DIM, 'Anthropic powers the agents (CUA + Vision).  Gemini powers narration.')}")
    print(f"  {_c(_DIM, 'Already-set keys are detected and reused. Skip to set later via the web app.')}")
    print()
    try:
        await _pair_prompt_api_keys(linked_uid)
    except KeyboardInterrupt:
        # Ctrl+C during API-key entry = cancel the pair (universal Ctrl+C rule).
        # Return False so cmd_pair_v2 reverts the partial pair.
        print()
        log("Pairing cancelled by user (Stage 3 — API keys)", "INFO")
        return False
    print()

    # ══════════════════════════════════════════════════════════════════════
    # [4/5] BROWSER LOGINS — open 4 platform tabs and wait for real auth.
    #       Uses CUA + Vision when Anthropic key was set in Stage 3 (above),
    #       or falls back to Playwright-only if user skipped.
    # ══════════════════════════════════════════════════════════════════════
    tm.tm_emit(tm.Ev.PAIR_STAGE_REACHED, stage=4)
    _setup_step(4, 5, "Browser logins")
    print(f"  {_c(_DIM, 'We open your real Chrome — sign in to each platform (+ solve any check).')}")
    print(f"  {_c(_DIM, 'Your sign-ins are saved to the profile (verification optional afterwards).')}")
    print("")

    # Make sure the browser the pipeline drives is actually launchable before we
    # open login tabs. A fresh `pipx install superresearch` ships the patchright
    # PACKAGE but not the Chrome wrapper the channel resolves to — fetch it once
    # here. Real Chrome itself is an OS-level dep: if it's missing, surface an
    # install hint and stop cleanly rather than crash mid-login.
    async with _async_spinner_ctx("Checking the browser"):
        _chrome_ok, _chrome_detail = await asyncio.to_thread(_ensure_chrome_ready)
    if _chrome_ok:
        print(f"  {_c(_OK, '✓')}  Browser ready  {_c(_DIM, '· Google Chrome + patchright wrapper')}")
    else:
        # ADVISORY ONLY — never abort here. The headless probe can false-negative
        # on a machine where the real (headful) launch below works fine, so we
        # surface the install hint but still attempt the launch — that's the
        # real source of truth. A genuinely-missing Chrome fails at browser.start().
        print(f"  {_c(_WARN, '⚠')}  Chrome readiness check didn't pass — trying to launch anyway.")
        if _chrome_detail:
            print(f"       {_c(_DIM, _chrome_detail[:140])}")
        print(f"       {_c(_DIM, 'If logins fail to open:')}  {_c(_BOLD, _chrome_install_hint())}")
    print("")


    # CUA client for visual double-verification. Best-effort: if no key is
    # available, Stage 4 (Browser logins) falls back to Playwright-only
    # verification (same as before). With a key present — set in Stage 3
    # via the API-key prompt OR already resolved via Firestore / user-scope
    # env / shell rc / .dg-supervisor.env — each platform has to pass BOTH
    # Playwright DOM checks AND CUA vision before Stage 4 clears it.
    # Matches Phase 0 init rigor.
    _setup_cua_client = None
    # Route through `resolve_api_key()` (research.py:203) so this site honors
    # the full precedence chain (Firestore → user-scope env → os.environ),
    # not just flat os.environ. Was previously a two-ladder inconsistency
    # with vision.py:269 — both now go through the same resolver. After the
    # 2026-05-18 stage reorder, Stage 3 also busts `_RESOLVED_KEY_CACHE` so
    # a freshly-pasted key is visible here without restart.
    _setup_cua_api_key = resolve_api_key()
    if _setup_cua_api_key:
        try:
            import anthropic as _anthropic
            _setup_cua_client = _anthropic.Anthropic(api_key=_setup_cua_api_key)
            log("Setup Stage 4: CUA vision verifier enabled — each platform will be double-checked.", "INFO")
        except Exception as e:
            log(f"Setup Stage 4: Could not init CUA client ({e}) — Playwright-only verification.", "WARN")
    else:
        log("Setup Stage 4: No ANTHROPIC_API_KEY — Playwright-only verification (less rigorous). Re-run --pair and paste a key at Stage 3 to enable CUA.", "WARN")

    services = _LOGIN_SERVICES
    pad = max(len(n) for n, _u, _k in services)
    results: dict[str, bool] = {}
    cancelled = False
    all_ok = False

    def _emit_row(_name, ok, label=""):
        mark = _c(_OK, "[ok]") if ok else _c(_WARN, "[--]")
        suffix = f"  {_c(_DIM, label)}" if label else ""
        print(f"        {mark}  {_name.ljust(pad)}{suffix}")

    def _push_firestore_progress():
        if not _firebase_db:
            return
        logins_map = {k: bool(results.get(k, False)) for _n, _u, k in services}
        try:
            if device_id_for_progress:
                _firebase_db.collection("devices").document(device_id_for_progress).update({
                    "logins": logins_map,
                })
            elif token:
                _firebase_db.collection("research_tokens").document(token).update({
                    "logins": logins_map,
                    "setupState": "ready" if all(logins_map.values()) else "awaiting_login",
                    "lastSetupCheck": int(time.time()),
                })
        except Exception:
            pass

    # F4 / DGOPS-7451 account-mismatch guard — runs in phase 2 on the patchright
    # context. Refuse (return True) only when re-pairing to a DIFFERENT account
    # with prior Google auth; first-pair / same-account pass with a notice.
    # Dormant for user-mode pair (initial uid None).
    async def _p1_security(browser) -> bool:
        try:
            prior = await _detect_persisted_google_auth(browser.context)
        except Exception as _de:
            log(f"[security] pair preflight detection failed (continuing): {_de}", "WARN")
            return False
        if not prior:
            return False
        if bool(_initial_paired_uid) and (_initial_paired_uid != linked_uid):
            print("")
            print(f"  {_c(_BOLD, 'Refusing to pair: switching to a different account, but prior Google auth still present.')}")
            print(f"  {_c(_DIM,  'Multi-account state is unsafe — agents inherit any persisted Google session and can')}")
            print(f"  {_c(_DIM,  'navigate to Workspace-protected resources silently. See DGOPS-7451 for context.')}")
            print("")
            print(f"  Detected: {prior['cookieMatches']} Google auth cookie(s)  ·  prior uid: {_initial_paired_uid[:8]}…  ·  new uid: {linked_uid[:8]}…")
            for s in prior.get("sample", []):
                print(f"    • {s}")
            print("")
            print(f"  {_c(_BOLD, 'To complete this account switch:')}")
            print(f"    1. {_c(_BOLD, f'{_PROG} --unpair --deep')}  {_c(_DIM, '(clears pairing state + browser profile)')}")
            print(f"    2. {_c(_BOLD, f'{_PROG} --pair')}  {_c(_DIM, '(re-runs the full flow with a fresh browser)')}")
            print("")
            try:
                emit_event("security_pair_refused", reason="account_switch_with_prior_cookies",
                           cookieMatches=prior["cookieMatches"], priorPairedUid=_initial_paired_uid,
                           newLinkedUid=linked_uid, sample=prior.get("sample", []))
            except Exception:
                pass
            return True
        _reason = "first_pair" if not _initial_paired_uid else "same_account_repair"
        log(f"[security] {prior['cookieMatches']} prior Google auth cookie(s) detected — allowing pair through ({_reason}).", "INFO")
        try:
            emit_event("security_pair_allowed_with_prior_cookies", reason=_reason,
                       cookieMatches=prior["cookieMatches"], linkedUid=linked_uid)
        except Exception:
            pass
        return False

    # Profile 1 — real-Chrome sign-in via the shared exception-safe engine
    # (same as profile 2+). Verification is OPTIONAL (ask, default skip): pair
    # is exactly when the profile is brand-new, where automated verify
    # navigations are the strongest bot-score signal (user direction
    # 2026-07-02). The F4 security check runs either way (cookie read only).
    try:
        _p1_status = await _login_one_profile(
            profile_dir, _setup_cua_client, label="profile",
            results=results, emit_row=_emit_row, security_check=_p1_security,
            verify_mode="ask")
    except (EOFError, KeyboardInterrupt):
        print("")
        log("Setup cancelled by user (Stage 4 sign-in)", "INFO")
        return False  # real cancel → cmd_pair_v2 reverts the partial pair
    except Exception as e:
        # A transient launch/verify failure must NOT destroy a real pairing
        # (invariant: partial/zero logins still complete). Complete with current
        # logins; the user can add the rest via --login.
        log(f"Setup: profile-1 login/verify failed ({e}) — completing pair with current logins", "WARN")
        print(f"  {_c(_WARN, 'Could not verify sign-ins: ' + str(e)[:120])}")
        _p1_status = "error"
    if _p1_status == "no_chrome":
        return False  # no Google Chrome — revert cleanly (hint already shown)
    if _p1_status == "refused":
        return True   # F4 refusal — keep device; user runs --unpair --deep

    if not cancelled:
        all_ok = all(results.get(k, False) for _n, _u, k in services)
    last_results = dict(results)
    _push_firestore_progress()

    print("")

    # ══════════════════════════════════════════════════════════════════════
    # Multi-profile login loop (2026-05-21). Each successful profile = 1
    # concurrent run slot. Gated on profile-1 success — no point chaining
    # profiles when the primary failed. workerCount is persisted
    # incrementally so a Ctrl+C mid-loop preserves the profiles that
    # DID complete (e.g. user adds profile 2 ok, bails on profile 3 →
    # workerCount stays at 2). PR 2 (daemon-loop) reads workerCount to
    # spawn N --serve workers, each pinned to _profile_dir(k).
    #
    # Each added profile runs the SAME real-Chrome sign-in + verify flow as
    # profile 1 (_login_one_profile). Firestore's devices/{deviceId}.logins map
    # stays bound to profile-1 (FE-visible status); per-profile logins are
    # tracked locally only.
    # ══════════════════════════════════════════════════════════════════════
    if all_ok and not cancelled:
        # Anchor profile-1 as the baseline (covers the downgrade path: a
        # prior pair may have set workerCount=3, and the user now wants 1.
        # This write resets the floor before the loop bumps it back up.)
        try:
            save_worker_count(1)
        except Exception as _wc_err:
            log(f"save_worker_count(1) failed (continuing): {_wc_err}", "WARN")

        print(f"  {_c(_OK, '✓')}  Profile 1 logins complete.")
        print("")
        print(f"  {_c(_DIM, 'Each browser profile = 1 concurrent run slot. Recommended: 2 profiles total.')}")
        print(f"  {_c(_DIM, 'Past your slot count, fired runs go into the queue.')}")
        print("")

        next_profile_n = 2
        while True:
            try:
                _add_more = await _ask_yes_no(
                    f"Add another browser profile (profile {next_profile_n})?",
                    default=False,
                    # See the --login add-loop: the number the question just used
                    # is a yes, the count already held is a no, and either reading
                    # is echoed before it is acted on.
                    yes_aliases=(str(next_profile_n),),
                    no_aliases=(str(next_profile_n - 1),),
                )
            except (EOFError, KeyboardInterrupt):
                print("")
                log(f"Multi-profile loop: Ctrl+C at profile {next_profile_n} prompt — keeping workerCount={next_profile_n - 1}", "INFO")
                break
            if not _add_more:
                _say_profile_capacity(next_profile_n - 1)
                break

            prof_path = str(_profile_dir(next_profile_n))
            print(f"  {_c(_DIM, f'Profile {next_profile_n} at {prof_path}')}")
            # Same real-Chrome sign-in + patchright verify as profile 1
            # (_login_one_profile runs both phases + closes the browser).
            profile_n_results: "dict[str, bool]" = {}
            n_cancelled = False
            try:
                await _login_one_profile(
                    prof_path, _setup_cua_client, label=f"profile {next_profile_n}",
                    results=profile_n_results, emit_row=_emit_row, verify_mode="ask")
            except (EOFError, KeyboardInterrupt):
                print("")
                log(f"Multi-profile loop: Ctrl+C during profile {next_profile_n} — keeping workerCount={next_profile_n - 1}", "INFO")
                n_cancelled = True
            except Exception as e:
                log(f"Setup: profile {next_profile_n} failed: {e}", "ERROR")
                print(f"  {_c(_WARN, f'Could not set up profile {next_profile_n}: {e}')}")

            n_all_ok = (not n_cancelled) and all(
                profile_n_results.get(k, False) for _n, _u, k in services
            )

            print("")
            if n_all_ok:
                try:
                    save_worker_count(next_profile_n)
                except Exception as _wc_err:
                    log(f"save_worker_count({next_profile_n}) failed (continuing): {_wc_err}", "WARN")
                print(f"  {_c(_OK, '✓')}  Profile {next_profile_n} logins complete — concurrent capacity is now {next_profile_n}.")
                next_profile_n += 1
            else:
                if n_cancelled:
                    print(f"  {_c(_WARN, '⚠')}  Profile {next_profile_n} logins cancelled — keeping workerCount={next_profile_n - 1}.")
                else:
                    _missing = [_name for _name, _u, _key in services if not profile_n_results.get(_key, False)]
                    print(f"  {_c(_WARN, '⚠')}  Profile {next_profile_n} logins incomplete — keeping workerCount={next_profile_n - 1}.")
                    if _missing:
                        print(f"       {_c(_DIM, 'Did not verify: ' + ', '.join(_missing))}")
                # Don't increment — the dir at _profile_dir(next_profile_n)
                # may have stale partial cookies. User can wipe via
                # --unpair --deep and re-pair to retry that slot.
                break
        print("")

    if not cancelled:
        # ⭐⭐ THE DENOMINATOR. Without a completion event, PAIR_FAILED has nothing
        # to be a fraction OF — and "no completions recorded" reads exactly like
        # "nobody ever finishes pairing". `profiles` is the answer to the question
        # the founding incident turned on: the owner wanted two concurrent run
        # slots and got one, and [5/5] Ready reported success without ever naming
        # the capacity.
        tm.tm_emit(tm.Ev.PAIR_COMPLETED, stage=5,
                   profiles=max(1, int(next_profile_n) - 1),
                   supervised=bool(enable_on_startup))
        # ══════════════════════════════════════════════════════════════════════
        # [5/5] READY — pair is complete. If the user opted into On Startup
        #       back in step 2, arm the supervisor NOW (deferred from step 2).
        #
        #       PARTIAL / ZERO logins STILL complete the pair (user direction
        #       2026-06-30): a stuck Stage-4 login must not strand pairing. The
        #       device link (Stages 1-3) is real; Phase 0 re-verifies logins at
        #       run time, so the missing ones can be signed in later. Supervisor
        #       is armed per the On-Startup choice regardless of login count —
        #       an armed backend just idles until a run needs a logged-in tab.
        # ══════════════════════════════════════════════════════════════════════
        _logged_in = [n for n, _u, k in services if results.get(k, False)]
        _not_logged_in = [n for n, _u, k in services if not results.get(k, False)]
        _setup_step(5, 5, "Ready")
        print(f"  {_c(_OK, '✓')}  Paired with {_c(_BOLD, linked_email or '—')}")
        if not _not_logged_in:
            print(f"  {_c(_OK, '✓')}  All {len(services)} platforms logged in")
        elif _logged_in:
            print(f"  {_c(_OK, '✓')}  {len(_logged_in)}/{len(services)} platforms logged in")
            print(f"  {_c(_WARN, '⚠')}  Not logged in yet: {_c(_BOLD, ', '.join(_not_logged_in))}")
            print(f"  {_c(_DIM, '     Sign the rest in with')}  {_c(_BOLD, _PROG + ' --login')}  {_c(_DIM, '(a real browser — no re-pair needed).')}")
        else:
            print(f"  {_c(_WARN, '⚠')}  No platforms logged in yet")
            print(f"  {_c(_DIM, '     Sign in with')}  {_c(_BOLD, _PROG + ' --login')}  {_c(_DIM, '(a real browser), then')}  {_c(_BOLD, _PROG + ' --serve')}{_c(_DIM, '. No re-pair needed.')}")
        # Ready used to report platforms and never capacity, so a user who
        # asked for two concurrent slots and got one saw nothing but success.
        # Read from disk rather than from the add-loop's counter: the loop only
        # runs when profile 1 fully succeeded, and Ready runs regardless.
        _ready_cap = max(1, int(load_worker_count() or 1))
        _ready_profiles = "profile" if _ready_cap == 1 else "profiles"
        _ready_slots = "slot" if _ready_cap == 1 else "slots"
        print(f"  {_c(_OK, '✓')}  {_ready_cap} browser {_ready_profiles} "
              f"{_c(_DIM, f'— {_ready_cap} concurrent run {_ready_slots}')}")
        print(f"  {_c(_OK, '✓')}  Browser closed")

        supervised_armed = False
        if enable_on_startup:
            print()
            # Spin while arming — the 5s daemon-loop detection wait would
            # otherwise look frozen.
            async with _async_spinner_ctx("Enabling On Startup"):
                ok, pid, info, killed_serves = await asyncio.to_thread(_arm_supervisor_quiet)
            if ok:
                supervised_armed = True
                _write_supervised_flag(True)
                _step4_plat = _supervisor_platform()
                if _step4_plat == "Darwin":
                    print(f"  {_c(_OK, '✓')}  LaunchAgent installed ({_SUPERVISOR_PLIST_LABEL})")
                elif _step4_plat == "Linux":
                    print(f"  {_c(_OK, '✓')}  systemd user unit installed ({_SUPERVISOR_UNIT_NAME})")
                else:
                    print(f"  {_c(_OK, '✓')}  Scheduled Task pinned to login ({_SUPERVISOR_TASK_NAME})")
                if killed_serves:
                    plural = "es" if killed_serves != 1 else ""
                    print(f"  {_c(_DIM, f'     Stopped {killed_serves} running --serve process{plural} to free port 8000.')}")
                if pid is not None and info == "already running":
                    print(f"  {_c(_OK, '✓')}  Backend already running (PID {pid})")
                elif pid is not None:
                    print(f"  {_c(_OK, '✓')}  Backend started (PID {pid}, running in background)")
                else:
                    print(f"  {_c(_WARN, '⚠')}  {info or 'Backend did not appear within 5s'}")
                    print(f"  {_c(_DIM, '     The scheduled task still fires at next login as a fallback.')}")
                print(f"  {_c(_OK, '✓')}  Synced to the Super Research app")
            else:
                if info == "unsupported":
                    print(f"  {_c(_WARN, '⚠')}  Only Windows / macOS / Linux desktop is supported.")
                else:
                    print(f"  {_c(_WARN, '⚠')}  Could not enable On Startup: {info}")
                print(f"  {_c(_DIM, '     Run manually with:')}  {_c(_BOLD, f'{_PROG} --resurrect')}")
        else:
            # User chose N to On Startup. Enforce that: remove any
            # previously-installed scheduled task + kill any running
            # daemon-loop / serve from a prior pair, so "N" genuinely means
            # "nothing is running in the background — I will run --serve
            # manually". Without this, a leftover supervisor from an
            # earlier --pair/--resurrect keeps respawning --serve and the
            # user can't tell where the backend is coming from.
            print()
            async with _async_spinner_ctx("Enforcing unsupervised mode"):
                task_info, killed_procs = await asyncio.to_thread(_disarm_supervisor_quiet)
            _write_supervised_flag(False)
            if task_info == "removed":
                print(f"  {_c(_OK, '✓')}  Removed leftover {_supervisor_artifact_label()} ({_SUPERVISOR_TASK_NAME})")
            elif task_info in ("missing", "no-task"):
                # macOS/Linux disarm helpers return "no-task" rather than
                # "missing"; both mean the same thing — nothing to remove.
                print(f"  {_c(_DIM, '     No supervisor was installed.')}")
            elif task_info in ("non-Windows", "unsupported"):
                pass  # silent — no supervisor artifact to remove on this platform
            else:
                print(f"  {_c(_WARN, '⚠')}  Supervisor teardown: {task_info}")
            if killed_procs:
                plural = "es" if killed_procs != 1 else ""
                print(f"  {_c(_OK, '✓')}  Stopped {killed_procs} leftover backend process{plural}")
            else:
                print(f"  {_c(_DIM, '     No backend processes were running.')}")

        print()
        if supervised_armed:
            print(f"  {_c(_BOLD + _ACCENT, '  The bond is forged.')}  {_c(_DIM, 'The backend is live — running in the background.')}")
            _render_next_actions([
                ("python research.py --retire", "disable On Startup"),
                ("python research.py --unpair", "fully disconnect this machine"),
                ("python research.py agent connect", "drive Super Research from chat (Hermes / OpenClaw)"),
            ])
        else:
            print(f"  {_c(_BOLD + _ACCENT, '  The bond is forged.')}  {_c(_DIM, 'Start the backend in this terminal to accept jobs:')}")
            print()
            print(f"       {_c(_BOLD, f'{_PROG} --serve')}")
            print()
            print(
                f"  {_c(_BOLD + _BRIGHT, '◇')}  "
                f"{_c(_BOLD + _ACCENT, 'vinctus est')}  "
                f"{_c(_BOLD + _BRIGHT, '◇')}    "
                f"{_c(_DIM, 'Bound. Backend listening on this machine.')}"
            )
            _render_next_actions([
                ("python research.py --resurrect", "enable On Startup (auto-start in background)"),
                ("python research.py --unpair", "fully disconnect this machine"),
                ("python research.py agent connect", "drive Super Research from chat (Hermes / OpenClaw)"),
            ])
    else:
        print()
        print(f"  {_rule('━', _WARN)}")
        print(f"  {_c(_WARN, 'Pairing cancelled — reverting this partial setup.')}")
        print(f"  {_rule('━', _WARN)}")
        print("")
        if last_results:
            print(f"  {_c(_DIM, 'Signed in before you cancelled:')}")
            for name, _u, key in services:
                ok = last_results.get(key)
                mark = _c(_OK, "[ok]") if ok else _c(_DIM, "[  ]")
                print(f"        {mark}  {name if ok else _c(_DIM, name)}")
            print("")
        print(f"  {_c(_DIM, 'Re-run when ready:')}  {_c(_BOLD, f'{_PROG} --pair')}")
        print("")

    # True = pair completed (incl. partial / zero logins) or was intentionally
    # refused; False = user cancelled mid-flow (Ctrl+C). cmd_pair_v2 maps False
    # to pair_completed=False so its finally reverts the partial pair (device doc
    # + token) — no ghost device is left in the app.
    return not cancelled


# ── Supervised mode (--resurrect / --retire) ───────────────────────────
#
# Installs a Windows Scheduled Task that auto-starts `python research.py
# --serve` at user logon, so a reboot (Windows Update, power blip, crash)
# doesn't need manual re-launch. Paired with the backend's existing startup
# auto-retry (research.py:8099 detects an incomplete checkpoint and resumes),
# this makes the pipeline survive unexpected downtime end-to-end.
#
# Task is scoped to the CURRENT USER — never elevated to SYSTEM — so it
# retains access to the user's Chrome profile / cookies, which Playwright
# needs for the logged-in agents.

_SUPERVISOR_TASK_NAME = "SuperResearchBackend"

# ── Cross-platform supervisor scaffolding (Track C, 2026-05-18) ────────────
# Per-platform bodies live in `*_windows` / `*_macos` / `*_linux` siblings;
# dispatchers at the original names route via `_supervisor_platform()`.
# All three platforms are first-class supported as of the 2026-05-18 gate
# drop. Windows uses a Scheduled Task; macOS uses launchd; Linux uses a
# systemd-user unit. Implementations live in `_arm_supervisor_macos`,
# `_arm_supervisor_linux`, `_arm_supervisor_quiet_windows` + their
# disarm + detect siblings; see README.md § Step 5a / 5b / 5c.

_SUPERVISOR_PLIST_LABEL = "com.dgresearch.supervisor"
_SUPERVISOR_PLIST_PATH = Path.home() / "Library" / "LaunchAgents" / f"{_SUPERVISOR_PLIST_LABEL}.plist"
_SUPERVISOR_UNIT_NAME = "dgresearch-supervisor.service"
_SUPERVISOR_UNIT_PATH = Path.home() / ".config" / "systemd" / "user" / _SUPERVISOR_UNIT_NAME

# Per-machine env file consumed by the supervisor at startup. See PR-Env in
# scripts/dg-supervisor.env.example. Values applied via `os.environ.setdefault()` —
# existing process env (Windows user-scope from "Account → API Config") wins
# for `resolve_api_key` callers (research.py:204-218). Missing file is fail-
# soft (Vision defaults to off per research.py:66, CUA fallthrough is safe).
_SUPERVISOR_ENV_FILE_DEFAULT_PATH = Path(__file__).parent / ".dg-supervisor.env"


def _load_env_file(path) -> dict[str, str]:
    """Parse `KEY=value` lines from `path`; apply via `os.environ.setdefault`.

    Tolerates `#` comments, blank lines, whitespace around `=`, matching
    outer quotes. UTF-8 BOM tolerated via `encoding="utf-8-sig"`. Missing
    file → WARN + {}. Malformed lines → WARN + skip. Returns the subset of
    keys actually applied (skips keys already present in os.environ — so the
    existing Windows user-scope env wins for the resolve_api_key chain).
    """
    if path is None:
        return {}
    p = Path(path) if not isinstance(path, Path) else path
    if not p.exists():
        log(f"[env] {p} not found — supervisor starts without persisted env vars", "WARN")
        return {}
    applied: dict[str, str] = {}
    try:
        text = p.read_text(encoding="utf-8-sig")
    except Exception as e:
        log(f"[env] failed to read {p}: {e}", "WARN")
        return {}
    for lineno, raw in enumerate(text.splitlines(), 1):
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        if "=" not in s:
            log(f"[env] {p}:{lineno} skipped (no '='): {s[:60]}", "WARN")
            continue
        k, _, v = s.partition("=")
        k = k.strip()
        v = v.strip()
        if len(v) >= 2 and v[0] == v[-1] and v[0] in ('"', "'"):
            v = v[1:-1]
        if not k or not all(c.isalnum() or c == "_" for c in k):
            log(f"[env] {p}:{lineno} skipped (bad key): {k!r}", "WARN")
            continue
        if k not in os.environ:
            os.environ[k] = v
            applied[k] = v
    return applied


def _seed_env_file_if_missing() -> bool:
    """Copy scripts/dg-supervisor.env.example to .dg-supervisor.env if absent.
    On POSIX, chmod 0600 (API key sensitivity). Idempotent — no-op if target
    exists. Returns True if a fresh seed was written. Called by `--resurrect`
    so first-time install lays down a documented, all-commented env file."""
    target = _SUPERVISOR_ENV_FILE_DEFAULT_PATH
    if target.exists():
        return False
    example = Path(__file__).parent / "scripts" / "dg-supervisor.env.example"
    if not example.exists():
        log(f"[env] no example template at {example} — skipping seed", "WARN")
        return False
    try:
        target.write_text(example.read_text(encoding="utf-8-sig"), encoding="utf-8")
    except Exception as e:
        log(f"[env] failed to seed {target}: {e}", "WARN")
        return False
    if sys.platform != "win32":
        try:
            os.chmod(target, 0o600)
        except Exception as e:
            log(f"[env] could not chmod 0600 {target}: {e}", "WARN")
    log(f"[env] seeded {target} from scripts/dg-supervisor.env.example", "INFO")
    return True


def _supervisor_platform() -> str:
    """Return 'Windows' | 'Darwin' | 'Linux' | 'Unsupported'.

    Centralizes the platform dispatch so every site is one branch. macOS
    launchd + Linux systemd-user are first-class supported supervisors
    (2026-05-18 — DG_ALLOW_CROSS_PLATFORM=1 gate retired after Linux smoke
    verified the daemon-loop + --serve spawn chain on Crostini). The gate
    served its purpose protecting users from untested code; with smoke
    in hand, the cross-platform paths are production behavior.
    """
    import platform as _p
    sysname = _p.system()
    if sysname in ("Windows", "Darwin", "Linux"):
        return sysname
    return "Unsupported"


def _parse_etime(s: str) -> "float | None":
    """Parse `ps -o etime=` output. Accepts 'MM:SS', 'HH:MM:SS', 'DD-HH:MM:SS'."""
    s = s.strip()
    if not s:
        return None
    try:
        if "-" in s:
            days, rest = s.split("-", 1)
            d = int(days)
        else:
            d = 0
            rest = s
        parts = rest.split(":")
        if len(parts) == 3:
            h, m, sec = int(parts[0]), int(parts[1]), int(parts[2])
        elif len(parts) == 2:
            h, m, sec = 0, int(parts[0]), int(parts[1])
        else:
            return None
        return float(d * 86400 + h * 3600 + m * 60 + sec)
    except (ValueError, IndexError):
        return None


def _wait_for_daemon_loop(enumerate_fn, timeout_s: float = 5.0) -> "int | None":
    """Poll `enumerate_fn()` every 0.5s until a daemon-loop pid appears, or
    timeout. launchctl / systemctl return before the spawned process has
    materialized, so callers that need the pid poll via this helper."""
    import time as _t
    deadline = _t.time() + timeout_s
    while _t.time() < deadline:
        _t.sleep(0.5)
        for pid, _cmd, role in enumerate_fn():
            if role == "daemon-loop":
                return pid
    return None


def _kill_until_clean(enumerate_fn, kill_fn, timeout_s: float = 8.0) -> int:
    """Loop kill+re-enumerate until no daemon-loop or serve procs remain,
    or timeout. Skips the calling process so we don't kill ourselves.
    Returns total kills."""
    import time as _t
    self_pid = os.getpid()
    killed_total = 0
    deadline = _t.time() + timeout_s
    while True:
        procs = [p for p in enumerate_fn() if p[0] != self_pid]
        daemon_pids = [pid for pid, _cmd, role in procs if role == "daemon-loop"]
        serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]
        if not daemon_pids and not serve_pids:
            return killed_total
        killed_total += kill_fn(daemon_pids) + kill_fn(serve_pids)
        if _t.time() >= deadline:
            return killed_total
        _t.sleep(0.5)


def _launcher_path() -> str:
    """Absolute path to the RUNNABLE launcher script for every re-exec — the
    supervisor unit/task/plist and the daemon-loop's child respawns all run
    `<python> <this> --serve|--daemon-loop …`.

    In a source checkout this IS research.py (== __file__). In a compiled
    (Nuitka) build the real code lives in _sr_core.<abi>.pyd beside a readable
    research.py launcher shim, and the runnable target is that shim.

    Always prefer the sibling research.py — the runnable launcher in BOTH modes
    (in source it's this file; compiled it's the shim). We do NOT key off
    __file__'s suffix: Nuitka reports the compiled module's __file__ as
    "_sr_core.py" (cosmetic, .py suffix, and that path does not exist), so a
    suffix check would wrongly hand back a non-existent .py. Falls back to
    __file__ only if no research.py sibling is found (defensive)."""
    here = Path(__file__).resolve()
    shim = here.with_name("research.py")
    return str(shim if shim.exists() else here)


def _supervisor_python_exe() -> str:
    """Return pythonw.exe (no-console interpreter) sibling of the current
    interpreter, falling back to sys.executable. Used for the Scheduled
    Task action and detached daemon-loop spawns so the supervisor doesn't
    pop a visible console window at logon."""
    cur = Path(sys.executable)
    if cur.name.lower() == "python.exe":
        sib = cur.parent / "pythonw.exe"
        if sib.exists():
            return str(sib)
    return str(cur)


def _console_python_exe() -> str:
    """Return python.exe (console interpreter) sibling of the current
    interpreter, falling back to sys.executable. Used by daemon-loop when
    spawning --serve so uvicorn keeps predictable stdio semantics even when
    daemon-loop itself is running under pythonw.exe. Platform-agnostic —
    on POSIX the `pythonw.exe` check fails and the function falls through
    to `sys.executable`, which is the right answer there too."""
    cur = Path(sys.executable)
    if cur.name.lower() == "pythonw.exe":
        sib = cur.parent / "python.exe"
        if sib.exists():
            return str(sib)
    return str(cur)


# ── POSIX-shared helpers (macOS in PR1, reused by Linux in PR2) ────────────

def _enumerate_research_py_procs_posix() -> list[tuple[int, str, str]]:
    """POSIX sibling of `_enumerate_research_py_procs_windows`. Reads
    `ps -ww -eo pid=,command=` and matches the `research.py` substring.
    `-ww` (BSD wide) prevents the default ~80-char cmdline truncation
    that would otherwise mask long invocations. Role logic mirrors
    Windows: --daemon-loop → daemon-loop, --serve → serve, else other."""
    import subprocess as _sp
    try:
        r = _sp.run(
            ["ps", "-ww", "-eo", "pid=,command="],
            capture_output=True, text=True, timeout=10,
        )
    except Exception:
        return []
    if r.returncode != 0:
        return []
    results: list[tuple[int, str, str]] = []
    for line in (r.stdout or "").splitlines():
        line = line.strip()
        if not line or "research.py" not in line:
            continue
        parts = line.split(None, 1)
        if len(parts) != 2:
            continue
        try:
            pid = int(parts[0])
        except ValueError:
            continue
        cmd = parts[1]
        if "--daemon-loop" in cmd:
            role = "daemon-loop"
        elif "--serve" in cmd:
            role = "serve"
        else:
            role = "other"
        results.append((pid, cmd, role))
    return results


def _proc_age_seconds_posix(pid: int) -> "float | None":
    """POSIX sibling of `_proc_age_seconds_windows`. Reads
    `ps -o etime= -p <pid>` and parses via `_parse_etime`. Returns None
    on unknown pid or unparseable output."""
    import subprocess as _sp
    try:
        r = _sp.run(
            ["ps", "-o", "etime=", "-p", str(pid)],
            capture_output=True, text=True, timeout=5,
        )
    except Exception:
        return None
    if r.returncode != 0:
        return None
    return _parse_etime(r.stdout or "")


def _kill_pids_posix(pids: list[int]) -> int:
    """POSIX sibling of `_kill_pids_windows`. SIGTERM each PID, wait 1s,
    SIGKILL survivors. Returns count confirmed terminated via kill(0) probe."""
    import signal as _signal
    import time as _t
    if not pids:
        return 0
    for pid in pids:
        try:
            os.kill(pid, _signal.SIGTERM)
        except (ProcessLookupError, PermissionError, OSError):
            pass
    _t.sleep(1.0)
    for pid in pids:
        try:
            os.kill(pid, _signal.SIGKILL)
        except (ProcessLookupError, PermissionError, OSError):
            pass
    confirmed = 0
    for pid in pids:
        try:
            os.kill(pid, 0)
        except (ProcessLookupError, PermissionError, OSError):
            confirmed += 1
    return confirmed


# ── macOS launchd helpers ───────────────────────────────────────────────────

def _arm_supervisor_macos() -> "tuple[bool, int | None, str, int]":
    """macOS sibling of `_arm_supervisor_quiet_windows`. Writes the launchd
    user agent plist at ~/Library/LaunchAgents/com.dgresearch.supervisor.plist
    and bootstraps it into gui/$(id -u). Returns the same tuple shape as the
    Windows path: (installed_ok, daemon_pid_or_None, info, killed_serve_count).

    `PATH` stays in plist's `EnvironmentVariables` because launchd does not
    inherit shell env and needs it to locate python3. All other env vars
    (Vision, CUA, API key) live in `.dg-supervisor.env` and are loaded by
    Python via `--env-file` before subcommand dispatch.

    That PATH is EVERY CHILD'S PATH, which is why it is built from
    `_lifecycle_path_dirs()` rather than written as a literal. It used to read
    `/usr/local/bin:/usr/bin:/bin`, which has no `/opt/homebrew/bin` — so on
    Apple silicon the supervisor and everything under it could not see Homebrew's
    tools. That is what broke the app-driven update (pipx replays the venv's
    recorded uv backend and can only locate uv via PATH), and it had already
    broken `ffprobe` once before and been patched point-wise. Fixing it here fixes
    the class; `_lifecycle_env` still widens the detached waiter's PATH because a
    plist written by an older build is still out there on real machines.

    EUID guard: refuses to install if running under sudo — would write the
    plist to /root/Library/... and leave it un-managed by the actual user."""
    import subprocess as _sp
    import os as _os
    import time as _time

    if _os.geteuid() == 0:
        return False, None, "refuse: do not run under sudo (user agent must be in your own home)", 0

    _seed_env_file_if_missing()

    script_dir = Path(__file__).parent
    # ⛔⛔ THIS USED TO BE ~/Library/Logs/SuperResearch — platform-canonical,
    # safe from TCC, safe from an update, and NOT COLLECTED BY ANYTHING. The
    # bundle takes `supervisor*.log` from `_logs_root()`, so the one file that
    # explains a machine which never came online reached no support call ever.
    # `_supervisor_log_dir()` keeps both original constraints and puts it where
    # the collector already looks; the reasoning is written out there.
    log_dir = _supervisor_log_dir()
    # Python-attributed ops (reading research.py, the WorkingDirectory) in a
    # TCC-protected folder still need a one-time per-binary grant — surface it
    # loudly instead of letting the agent die silently at first spawn.
    try:
        _rel = script_dir.resolve().relative_to(Path.home())
        if _rel.parts and _rel.parts[0] in ("Downloads", "Desktop", "Documents"):
            log(f"[resurrect] checkout is under ~/{_rel.parts[0]} — macOS TCC can block the "
                f"background service. If the device never comes online: grant Full Disk "
                f"Access to {sys.executable} (System Settings → Privacy & Security → Full "
                f"Disk Access), or move the checkout out of ~/{_rel.parts[0]}.", "WARN")
    except Exception:
        pass
    try:
        log_dir.mkdir(parents=True, exist_ok=True)
        _SUPERVISOR_PLIST_PATH.parent.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return False, None, f"could not create dirs: {e}", 0

    # Every value below is interpolated into XML and every one of them derives
    # from $HOME, so an `&` or `<` anywhere in the user's home path writes a plist
    # launchd cannot parse — the job never loads and the device simply never comes
    # online, with no error the user would connect to their username.
    def _x(v) -> str:
        return (str(v).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))

    python_exe = _x(sys.executable)
    script_path = _x(_launcher_path())
    env_file = _x(_SUPERVISOR_ENV_FILE_DEFAULT_PATH)
    supervisor_path = _x(_supervisor_path_value())
    # ⛔ SAY WHAT IS BEING BAKED IN, at the one moment it is decided. This is
    # EVERY supervised child's search path, the tool homes go first on purpose,
    # and the only record of which value a machine actually got used to be the
    # plist itself — which nothing collects.
    log(f"[resurrect] baking search path into the LaunchAgent: "
        f"{_supervisor_path_value()}")
    work_dir = _x(script_dir)
    out_log = _x(log_dir / 'supervisor.out.log')
    err_log = _x(log_dir / 'supervisor.err.log')
    plist_xml = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key>
  <string>{_SUPERVISOR_PLIST_LABEL}</string>
  <key>ProgramArguments</key>
  <array>
    <string>{python_exe}</string>
    <string>{script_path}</string>
    <string>--daemon-loop</string>
    <string>--env-file</string>
    <string>{env_file}</string>
  </array>
  <key>WorkingDirectory</key>
  <string>{work_dir}</string>
  <key>RunAtLoad</key>
  <true/>
  <key>KeepAlive</key>
  <true/>
  <key>ThrottleInterval</key>
  <integer>10</integer>
  <key>StandardOutPath</key>
  <string>{out_log}</string>
  <key>StandardErrorPath</key>
  <string>{err_log}</string>
  <key>EnvironmentVariables</key>
  <dict>
    <key>PATH</key>
    <string>{supervisor_path}</string>
  </dict>
</dict>
</plist>
"""
    try:
        _SUPERVISOR_PLIST_PATH.write_text(plist_xml, encoding="utf-8")
    except Exception as e:
        return False, None, f"plist write failed: {e}", 0

    uid = _os.getuid()
    domain = f"gui/{uid}"
    label = f"{domain}/{_SUPERVISOR_PLIST_LABEL}"

    def _job_loaded() -> bool:
        """True while launchd still knows the label (bootout is ASYNC)."""
        try:
            return _sp.run(["launchctl", "print", label],
                           capture_output=True, text=True, timeout=10).returncode == 0
        except Exception:
            return False

    # Bootout first (idempotent — clears any prior install). Errors ignored.
    try:
        _sp.run(["launchctl", "bootout", label],
                capture_output=True, text=True, timeout=10)
    except Exception:
        pass

    # …then WAIT for the teardown to actually land. `bootout` returns before the
    # job is gone, so firing `bootstrap` straight after races it and fails with
    # "service already bootstrapped"/EBUSY — which is exactly why `--resurrect`
    # blew up when On-Startup was ALREADY running (the one command a user runs
    # right after an update). Poll up to ~6s; a still-loaded job is handled below.
    for _ in range(30):
        if not _job_loaded():
            break
        _time.sleep(0.2)

    # Bootstrap into gui/$uid so the agent runs in the Aqua session (Chrome
    # needs that scope for display + clipboard).
    try:
        r = _sp.run(["launchctl", "bootstrap", domain, str(_SUPERVISOR_PLIST_PATH)],
                    capture_output=True, text=True, timeout=15)
        if r.returncode != 0:
            # Only a REAL failure if the job isn't loaded. If it is (the bootout
            # hadn't drained, or another arm won the race), the plist on disk is
            # already the fresh one and the `kickstart -k` below force-restarts
            # the job onto it — so treat that as success instead of a hard error.
            if not _job_loaded():
                return False, None, f"bootstrap failed: {(r.stderr or r.stdout).strip()[:120]}", 0
    except Exception as e:
        if not _job_loaded():
            return False, None, f"bootstrap exception: {e}", 0

    # Enable + kickstart (best-effort — bootstrap usually starts the job,
    # kickstart forces a run regardless).
    try:
        _sp.run(["launchctl", "enable", label],
                capture_output=True, text=True, timeout=10)
    except Exception:
        pass
    try:
        _sp.run(["launchctl", "kickstart", "-k", label],
                capture_output=True, text=True, timeout=10)
    except Exception:
        pass

    # Sweep stale --serve procs (port 8000 conflict).
    procs = _enumerate_research_py_procs_posix()
    plain_serve_pids = [pid for pid, _c, role in procs if role == "serve"]
    killed_serve = _kill_pids_posix(plain_serve_pids) if plain_serve_pids else 0

    # Wait for daemon-loop pid (launchctl returns before child materializes).
    daemon_pid = _wait_for_daemon_loop(_enumerate_research_py_procs_posix, timeout_s=5.0)
    if daemon_pid is not None:
        return True, daemon_pid, "", killed_serve
    return True, None, "daemon-loop did not appear within 5s", killed_serve


def _disarm_supervisor_macos() -> "tuple[str, int]":
    """macOS sibling of `_disarm_supervisor_quiet_windows`. Bootout the
    launchd user agent, delete the plist, kill survivors. Returns
    (status, killed_total)."""
    import subprocess as _sp
    import os as _os

    if _os.geteuid() == 0:
        return "refuse: do not run under sudo", 0

    uid = _os.getuid()
    label = f"gui/{uid}/{_SUPERVISOR_PLIST_LABEL}"

    status = "no-task"
    try:
        r = _sp.run(["launchctl", "bootout", label],
                    capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            status = "removed"
        elif "could not find" in (r.stderr or "").lower() or "no such" in (r.stderr or "").lower():
            status = "no-task"
        else:
            status = (r.stderr or r.stdout or "bootout returned non-zero").strip()[:100]
    except Exception as e:
        status = f"bootout exception: {e}"

    # Delete plist regardless of bootout outcome.
    try:
        if _SUPERVISOR_PLIST_PATH.exists():
            _SUPERVISOR_PLIST_PATH.unlink()
    except Exception as e:
        if status == "removed":
            status = f"removed (plist unlink warning: {e})"

    killed = _kill_until_clean(_enumerate_research_py_procs_posix, _kill_pids_posix)
    return status, killed


def _detect_supervised_macos() -> bool:
    """macOS sibling of `_detect_supervised_windows`. Probes both `launchctl
    print gui/$uid/<label>` (definitive but session-scoped) AND `launchctl
    list <label>` (legacy fallback that works in some session-detached
    contexts). Returns True if either returns 0; False on any error /
    not bootstrapped. Belt-and-suspenders parity with the Linux probe at
    research.py:_detect_supervised_linux."""
    import subprocess as _sp
    import os as _os
    print_ok = False
    list_ok = False
    try:
        uid = _os.getuid()
        r = _sp.run(["launchctl", "print", f"gui/{uid}/{_SUPERVISOR_PLIST_LABEL}"],
                    capture_output=True, text=True, timeout=5)
        print_ok = (r.returncode == 0)
    except Exception as e:
        log(f"[supervisor-macos] launchctl print probe failed: {e}", "WARN")
    try:
        r = _sp.run(["launchctl", "list", _SUPERVISOR_PLIST_LABEL],
                    capture_output=True, text=True, timeout=5)
        list_ok = (r.returncode == 0)
    except Exception as e:
        log(f"[supervisor-macos] launchctl list probe failed: {e}", "WARN")
    return print_ok or list_ok


# ── Linux systemd-user helpers ──────────────────────────────────────────────

def _check_linger_status() -> str:
    """Probe `loginctl show-user $USER --property=Linger`. Returns
    'yes' | 'no' | 'unknown'. Linger=yes means the systemd user manager
    survives logout — required for the supervisor to keep daemon-loop
    alive across user sessions. If 'no', the user needs to run
    `sudo loginctl enable-linger $USER` manually (we don't escalate)."""
    import subprocess as _sp
    try:
        user = os.environ.get("USER") or os.environ.get("LOGNAME") or ""
        if not user:
            return "unknown"
        r = _sp.run(["loginctl", "show-user", user, "--property=Linger"],
                    capture_output=True, text=True, timeout=5)
        if r.returncode != 0:
            return "unknown"
        out = (r.stdout or "").strip().lower()
        if "linger=yes" in out:
            return "yes"
        if "linger=no" in out:
            return "no"
        return "unknown"
    except Exception:
        return "unknown"


def _arm_supervisor_linux() -> "tuple[bool, int | None, str, int]":
    """Linux sibling of `_arm_supervisor_macos`. Writes a systemd user
    unit at ~/.config/systemd/user/dgresearch-supervisor.service and
    enables it via `systemctl --user enable --now`. Returns
    (installed_ok, daemon_pid_or_None, info, killed_serve_count).

    `PassEnvironment=DISPLAY WAYLAND_DISPLAY XDG_RUNTIME_DIR` lets the
    supervisor see the graphical session — Chrome needs that for the
    visible browser window. Without this the service starts but Chrome
    has nowhere to render.

    Linger probe: WARN-only if `loginctl Linger=no`. User must run
    `sudo loginctl enable-linger $USER` themselves; we don't escalate.
    Without linger, daemon-loop dies at logout (the user-session systemd
    manager is reaped).

    EUID guard: refuses under sudo — unit would land in
    /root/.config/systemd/user/ (wrong manager)."""
    import subprocess as _sp
    import os as _os

    if _os.geteuid() == 0:
        return False, None, "refuse: do not run under sudo (user unit must be in your own home)", 0

    _seed_env_file_if_missing()

    # Linger probe — warn but don't fail. Without linger the supervisor
    # works while user is logged in but dies on logout. Acceptable for
    # PR2; user can enable linger separately.
    linger = _check_linger_status()
    if linger == "no":
        log("[supervisor-linux] loginctl Linger=no for this user. Run "
            "`sudo loginctl enable-linger $USER` so daemon-loop survives "
            "logout.", "WARN")

    script_dir = Path(__file__).parent
    # ⛔⛔ THIS USED TO BE `script_dir / "logs"`, which for a pipx install is
    # INSIDE site-packages: every `--update` reinstall deleted the supervisor's
    # own output, and the bundle never collected it in the first place. macOS
    # had already moved off that path for the same reason; Linux had not.
    log_dir = _supervisor_log_dir()
    try:
        log_dir.mkdir(parents=True, exist_ok=True)
        _SUPERVISOR_UNIT_PATH.parent.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return False, None, f"could not create dirs: {e}", 0

    python_exe = sys.executable
    script_path = _launcher_path()
    env_file = _SUPERVISOR_ENV_FILE_DEFAULT_PATH

    # Capture display env from the CURRENT shell (the one running
    # --resurrect / --pair). Bake these into the unit's Environment=
    # lines so the supervisor has DISPLAY on every container restart —
    # PassEnvironment alone is a race condition: on Crostini and other
    # Linux desktops without a full DE, the user-systemd manager auto-
    # fires enabled units BEFORE Sommelier / the graphical session
    # populates DISPLAY in the manager env. By the time PassEnvironment
    # runs there's nothing to pass. Hardcoding from --resurrect's shell
    # gives reboot-safe behavior. 2026-05-19 — caught during Linux
    # Chromebook smoke when Playwright failed to launch Chromium under
    # the systemd-spawned --serve despite working from terminal.
    _shell_disp    = (os.environ.get("DISPLAY") or "").strip()
    _shell_wayland = (os.environ.get("WAYLAND_DISPLAY") or "").strip()
    _shell_xauth   = (os.environ.get("XAUTHORITY") or "").strip()
    _shell_xdg_rt  = (os.environ.get("XDG_RUNTIME_DIR") or "").strip()
    # PATH first: a systemd --user unit that states none inherits the manager's
    # narrow default, which has neither ~/.local/bin nor ~/.cargo/bin — the two
    # places uv actually installs itself on Linux. Same root cause as the macOS
    # plist, same fix, one shared list. Stated explicitly rather than left to
    # PassEnvironment, which loses the race against the graphical session for the
    # same reason DISPLAY does (see below).
    env_lines = [f'Environment="PATH={_supervisor_path_value()}"']
    # Same reason as the macOS plist: this is every supervised child's search
    # path, and the unit file is not something a support bundle collects.
    log(f"[resurrect] baking search path into the systemd unit: "
        f"{_supervisor_path_value()}")
    if _shell_disp:
        env_lines.append(f'Environment="DISPLAY={_shell_disp}"')
    if _shell_wayland:
        env_lines.append(f'Environment="WAYLAND_DISPLAY={_shell_wayland}"')
    if _shell_xauth:
        env_lines.append(f'Environment="XAUTHORITY={_shell_xauth}"')
    if _shell_xdg_rt:
        env_lines.append(f'Environment="XDG_RUNTIME_DIR={_shell_xdg_rt}"')
    # NB: PATH is unconditionally present now, so the "did we capture anything?"
    # check has to count the DISPLAY lines specifically — `if not env_lines` would
    # silently never fire again and the reboot-safety warning would be lost.
    if len(env_lines) == 1:
        log("[supervisor-linux] no DISPLAY in the calling shell — unit "
            "will rely on PassEnvironment only. If browser launch fails "
            "post-reboot, re-run --resurrect from a graphical-session "
            "terminal so DISPLAY is captured.", "WARN")
    env_block = "\n".join(env_lines)

    # systemd `ExecStart=` is whitespace-tokenized — any path with a space
    # (we live under "DG Research") must be double-quoted or systemd will
    # split `/home/.../DG` from `Research/research.py` and try to exec a
    # non-existent script in a tight Restart=always loop. `WorkingDirectory=`
    # and `StandardOutput=append:<path>` take single values (not tokenized)
    # but we quote consistently for hygiene.
    unit_content = f"""[Unit]
Description=DG Super Research Backend Supervisor
After=network-online.target graphical-session.target
Wants=network-online.target
StartLimitIntervalSec=120
StartLimitBurst=10

[Service]
Type=simple
WorkingDirectory={script_dir}
ExecStart="{python_exe}" "{script_path}" --daemon-loop --env-file "{env_file}"
Restart=always
RestartSec=10
# The PATH below is this service's AND every child it spawns. Tool homes come
# first, so a binary in a user-writable dir such as ~/.local/bin resolves ahead
# of the OS copy for all of them. That is deliberate: system-first resolved
# tools the user never installed and broke app-driven updates. ExecStart above
# is an absolute interpreter path and cannot be shadowed either way.
{env_block}
PassEnvironment=DISPLAY WAYLAND_DISPLAY XAUTHORITY XDG_RUNTIME_DIR

StandardOutput=append:{log_dir}/supervisor.out.log
StandardError=append:{log_dir}/supervisor.err.log

[Install]
WantedBy=default.target
"""
    try:
        _SUPERVISOR_UNIT_PATH.write_text(unit_content, encoding="utf-8")
    except Exception as e:
        return False, None, f"unit write failed: {e}", 0

    # daemon-reload picks up the new unit (systemd doesn't auto-scan).
    try:
        _sp.run(["systemctl", "--user", "daemon-reload"],
                capture_output=True, text=True, timeout=10)
    except Exception:
        pass

    # Belt-and-suspenders: import current shell's graphical-session env
    # into the user-systemd manager BEFORE enabling the unit. Fixes the
    # immediate post-resurrect run on machines where the manager hadn't
    # picked up DISPLAY yet. The embedded Environment= lines above handle
    # reboot-survival; this handles "I just installed and want it to
    # work without restart" UX. Idempotent — safe to no-op if vars are
    # missing from the shell.
    _import_vars = []
    if _shell_disp:    _import_vars.append("DISPLAY")
    if _shell_wayland: _import_vars.append("WAYLAND_DISPLAY")
    if _shell_xauth:   _import_vars.append("XAUTHORITY")
    if _shell_xdg_rt:  _import_vars.append("XDG_RUNTIME_DIR")
    if _import_vars:
        try:
            _sp.run(["systemctl", "--user", "import-environment", *_import_vars],
                    capture_output=True, text=True, timeout=10)
        except Exception as _ie:
            log(f"[supervisor-linux] import-environment failed (non-fatal): {_ie}", "WARN")

    # enable --now sets WantedBy=default.target AND starts immediately.
    try:
        r = _sp.run(["systemctl", "--user", "enable", "--now", _SUPERVISOR_UNIT_NAME],
                    capture_output=True, text=True, timeout=15)
        if r.returncode != 0:
            return False, None, f"systemctl enable --now failed: {(r.stderr or r.stdout).strip()[:120]}", 0
    except Exception as e:
        return False, None, f"systemctl exception: {e}", 0

    # Sweep stale --serve procs (port 8000 conflict).
    procs = _enumerate_research_py_procs_posix()
    plain_serve_pids = [pid for pid, _c, role in procs if role == "serve"]
    killed_serve = _kill_pids_posix(plain_serve_pids) if plain_serve_pids else 0

    daemon_pid = _wait_for_daemon_loop(_enumerate_research_py_procs_posix, timeout_s=5.0)
    if daemon_pid is not None:
        return True, daemon_pid, "", killed_serve
    return True, None, "daemon-loop did not appear within 5s", killed_serve


def _disarm_supervisor_linux() -> "tuple[str, int]":
    """Linux sibling of `_disarm_supervisor_macos`. `systemctl --user
    disable --now`, delete unit file, daemon-reload, kill survivors."""
    import subprocess as _sp
    import os as _os

    if _os.geteuid() == 0:
        return "refuse: do not run under sudo", 0

    status = "no-task"
    try:
        r = _sp.run(["systemctl", "--user", "disable", "--now", _SUPERVISOR_UNIT_NAME],
                    capture_output=True, text=True, timeout=15)
        if r.returncode == 0:
            status = "removed"
        else:
            combined = ((r.stderr or "") + (r.stdout or "")).lower()
            if "does not exist" in combined or "no such file" in combined or "not loaded" in combined:
                status = "no-task"
            else:
                status = (r.stderr or r.stdout or "systemctl returned non-zero").strip()[:100]
    except Exception as e:
        status = f"systemctl exception: {e}"

    # Delete unit file regardless.
    try:
        if _SUPERVISOR_UNIT_PATH.exists():
            _SUPERVISOR_UNIT_PATH.unlink()
    except Exception as e:
        if status == "removed":
            status = f"removed (unit unlink warning: {e})"

    # daemon-reload to forget the unit.
    try:
        _sp.run(["systemctl", "--user", "daemon-reload"],
                capture_output=True, text=True, timeout=10)
    except Exception:
        pass

    killed = _kill_until_clean(_enumerate_research_py_procs_posix, _kill_pids_posix)
    return status, killed


def _detect_supervised_linux() -> bool:
    """Linux sibling of `_detect_supervised_macos`. Probes BOTH `is-enabled`
    and `is-active` because `is-enabled` alone returns non-zero in legitimate
    "supervisor is running fine" states like `static`, `enabled-runtime`, or
    `linked`, and on Crostini-style transient managers where the unit auto-
    starts via `WantedBy=default.target` but `is-enabled` reports `linked`.
    The toggle should reflect "is the supervisor going to keep --serve alive",
    which is satisfied if EITHER the unit is enabled OR currently active.

    Returns True if either check returns 0; False otherwise (including
    timeout / DBus unavailable / systemctl missing)."""
    import subprocess as _sp
    enabled_ok = False
    active_ok = False
    try:
        r = _sp.run(["systemctl", "--user", "is-enabled", _SUPERVISOR_UNIT_NAME],
                    capture_output=True, text=True, timeout=5)
        # `is-enabled` returns 0 for enabled / static / alias / generated.
        # `enabled-runtime` / `linked` / `linked-runtime` exit 0 in current
        # systemd, but legacy versions exited non-zero on those. Fall back
        # to stdout parse so older systemd doesn't trip us.
        out = (r.stdout or "").strip().lower()
        enabled_ok = (r.returncode == 0) or out in {
            "enabled", "enabled-runtime", "static", "linked",
            "linked-runtime", "alias", "generated",
        }
    except Exception as e:
        log(f"[supervisor-linux] is-enabled probe failed: {e}", "WARN")
    try:
        r = _sp.run(["systemctl", "--user", "is-active", _SUPERVISOR_UNIT_NAME],
                    capture_output=True, text=True, timeout=5)
        active_ok = (r.returncode == 0) or (r.stdout or "").strip() == "active"
    except Exception as e:
        log(f"[supervisor-linux] is-active probe failed: {e}", "WARN")
    return enabled_ok or active_ok


def _enumerate_research_py_procs() -> list[tuple[int, str, str]]:
    """Dispatcher — routes to `_enumerate_research_py_procs_windows` or
    `_enumerate_research_py_procs_posix`. Returns [] on Unsupported."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return _enumerate_research_py_procs_windows()
    if plat in ("Darwin", "Linux"):
        return _enumerate_research_py_procs_posix()
    return []


def _enumerate_research_py_procs_windows() -> list[tuple[int, str, str]]:
    """Return [(pid, cmdline, role), ...] for every python.exe / pythonw.exe
    whose command line references this script. role ∈ {'daemon-loop',
    'serve', 'other'}. Single source of truth for --resurrect (what's
    running before I spawn?) and --retire (what do I need to kill?).

    Matches on "research.py" substring so subprocess invocations launched
    from different cwd styles (absolute, relative, with/without quotes)
    all get caught.

    Includes pythonw.exe because the Scheduled Task action runs the
    supervisor under the no-console interpreter."""
    try:
        ps = subprocess.run(
            ["wmic", "process", "where",
             "(name='python.exe' or name='pythonw.exe')",
             "get", "processid,commandline", "/format:list"],
            capture_output=True, text=True, timeout=15,
            creationflags=_PS_NO_WINDOW,
        )
    except Exception:
        return []
    # wmic /format:list emits blank lines BETWEEN fields of the same entry
    # (CommandLine=...\n\nProcessId=...\n\n\n\n) on Windows 10/11. The old
    # parser treated any blank line as an entry boundary, splitting each
    # process into two single-field entries — silently broke this function
    # on real systems. New parser flushes only when BOTH expected fields
    # have been collected.
    entries: list[dict[str, str]] = []
    cur: dict[str, str] = {}
    for line in (ps.stdout or "").splitlines():
        line = line.strip()
        if not line:
            continue
        if "=" in line:
            k, _, v = line.partition("=")
            cur[k.strip()] = v.strip()
            if "CommandLine" in cur and "ProcessId" in cur:
                entries.append(cur); cur = {}
    if cur:
        entries.append(cur)
    results: list[tuple[int, str, str]] = []
    for e in entries:
        cmdline = e.get("CommandLine", "")
        if "research.py" not in cmdline:
            continue
        try:
            pid = int(e.get("ProcessId", ""))
        except ValueError:
            continue
        if "--daemon-loop" in cmdline:
            role = "daemon-loop"
        elif "--serve" in cmdline:
            role = "serve"
        else:
            role = "other"
        results.append((pid, cmdline, role))
    return results


def _proc_age_seconds(pid: int) -> "float | None":
    """Dispatcher — routes to `_proc_age_seconds_windows` or `_proc_age_seconds_posix`."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return _proc_age_seconds_windows(pid)
    if plat in ("Darwin", "Linux"):
        return _proc_age_seconds_posix(pid)
    return None


def _proc_age_seconds_windows(pid: int) -> "float | None":
    """Return seconds since process creation, or None if unknown.
    Best-effort via wmic CreationDate (yyyymmddHHMMSS.ffffff±zzz)."""
    try:
        r = subprocess.run(
            ["wmic", "process", "where", f"ProcessId={pid}",
             "get", "CreationDate", "/format:list"],
            capture_output=True, text=True, timeout=10,
            creationflags=_PS_NO_WINDOW,
        )
        for line in (r.stdout or "").splitlines():
            if line.startswith("CreationDate="):
                stamp = line.split("=", 1)[1].strip()[:14]
                if len(stamp) == 14:
                    import datetime as _dt
                    created = _dt.datetime.strptime(stamp, "%Y%m%d%H%M%S")
                    return (_dt.datetime.now() - created).total_seconds()
    except Exception:
        return None
    return None


def _kill_pids(pids: list[int]) -> int:
    """Dispatcher — routes to `_kill_pids_windows` or `_kill_pids_posix`."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return _kill_pids_windows(pids)
    if plat in ("Darwin", "Linux"):
        return _kill_pids_posix(pids)
    return 0


def _free_port(port: int = 8000) -> "list[int]":
    """Find and force-kill any process listening on `port` so a fresh --serve
    can bind. Used by --resurrect, the multi-worker port-squatter auto-recovery,
    and any arming path — clears stale squatters (crashed-but-port-leaked
    --serves and accidentally-running third-party apps) on any worker port.

    Returns the list of PIDs that were killed. Returns [] when the port is
    already free or no killable owner could be identified (best-effort).
    Cross-platform — Windows uses netstat, POSIX uses lsof.
    """
    import subprocess as _sp
    plat = _supervisor_platform()
    pids_to_kill: "set[int]" = set()
    _p = str(port)
    try:
        if plat == "Windows":
            r = _sp.run(
                ["netstat", "-ano", "-p", "TCP"],
                capture_output=True, text=True, timeout=8,
                creationflags=_PS_NO_WINDOW,
            )
            for line in (r.stdout or "").splitlines():
                # Format: "  TCP    0.0.0.0:8000    0.0.0.0:0    LISTENING    1234"
                if "LISTENING" not in line:
                    continue
                if f":{_p} " not in line and not line.endswith(f":{_p}"):
                    if f" :{_p}\t" not in line and f"0.0.0.0:{_p}" not in line and f"[::]:{_p}" not in line:
                        continue
                parts = line.split()
                if not parts:
                    continue
                try:
                    pid = int(parts[-1])
                except ValueError:
                    continue
                if pid > 0 and pid != os.getpid():
                    pids_to_kill.add(pid)
        elif plat in ("Darwin", "Linux"):
            r = _sp.run(
                ["lsof", "-ti", f":{_p}"],
                capture_output=True, text=True, timeout=8,
            )
            for line in (r.stdout or "").splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    pid = int(line)
                except ValueError:
                    continue
                if pid > 0 and pid != os.getpid():
                    pids_to_kill.add(pid)
    except Exception:
        return []
    if not pids_to_kill:
        return []
    _kill_pids(list(pids_to_kill))
    return sorted(pids_to_kill)


def _free_port_8000() -> "list[int]":
    """Back-compat alias — see `_free_port`. Retained for existing callers."""
    return _free_port(8000)


def _serve_exit_was_port_conflict(err_log_path: "Path", since_ts: "float | None" = None) -> bool:
    """Best-effort: did the most recent --serve exit fail to BIND its port
    (EADDRINUSE) rather than crash for an internal reason? A port-bind failure
    is a recoverable squatter problem — NOT a token revoke and NOT a code
    crash — so the supervisor frees the port and respawns WITHOUT counting it
    toward the crash-loop tracker. Scans the tail of the worker's stderr log
    for the platform's address-in-use signature.
    """
    try:
        if not err_log_path.exists():
            return False
        # Only the tail matters (the last exit's traceback).
        data = err_log_path.read_text(encoding="utf-8", errors="replace")[-4000:].lower()
    except Exception:
        return False
    return (
        "winerror 10048" in data
        or "errno 10048" in data
        or "address already in use" in data
        or "only one usage of each socket address" in data
        or "[errno 98]" in data  # POSIX EADDRINUSE
    )


def _kill_pids_windows(pids: list[int]) -> int:
    """taskkill /F each PID. Returns count that successfully terminated.
    Silent on individual failures — caller can re-enumerate to confirm."""
    killed = 0
    for pid in pids:
        try:
            r = subprocess.run(
                ["taskkill", "/F", "/PID", str(pid)],
                capture_output=True, text=True, timeout=10,
                creationflags=_PS_NO_WINDOW,
            )
            if r.returncode == 0:
                killed += 1
        except Exception:
            pass
    return killed


def _looks_like_our_backend(cmdline: str) -> bool:
    """Whether a command line is another copy of THIS backend.

    Deliberately narrow. Everything below can end a process, and the difference
    between "a stale copy of me" and "something else the user is running" is the
    only thing standing between reclaiming a port and killing their work. A bare
    "python" match, or a match on the port alone, would not be that difference.
    """
    toks = cmdline.split() if isinstance(cmdline, str) else list(cmdline or [])
    toks = [str(x) for x in toks]
    if "--serve" not in toks:
        return False

    # The PROGRAM being run has to be ours, not merely a word on the line. A
    # substring test called `grep --serve research.py` one of our backends —
    # harmless in that instance, and exactly the shape of false positive that
    # ends someone else's process when it does hold the port.
    # LOWERCASED. On macOS the framework interpreter's real basename is
    # "Python", capital P — a case-sensitive check read our own backend as a
    # stranger and refused to reclaim its port.
    #
    # And `.exe` STRIPPED, for the same class of reason on the other platform.
    # Windows installs the console script as `superresearch.exe`, which matched
    # none of the three tests below — not `runs_console` (bare name), not
    # `is_python`, not `runs_script`. A backend the user started the documented
    # way therefore read as a STRANGER, so when it was later orphaned and still
    # holding the port, the caller printed "already in use by something that is
    # not Super Research" and refused to boot. Fail-safe, but a permanent
    # refusal on the one platform where reclaiming is most needed. `_prog_name`
    # (research.py:210) has always stripped it; this function never did.
    base = [_strip_exe(os.path.basename(x).lower()) for x in toks]
    is_python = any(b.startswith("python") or b.startswith("pypy") for b in base)
    runs_script = any(b == "research.py" for b in base)
    runs_console = any(b == "superresearch" for b in base)
    return (is_python and runs_script) or runs_console


def _port_holders(port: int) -> list:
    """Listening processes on `port`, each tagged with whether it is ours.

    Two sources because neither is reliable alone: psutil's `net_connections`
    raises AccessDenied on macOS without root even for the caller's own sockets,
    and `lsof` is not installed on every Linux image. Whichever answers, answers.
    """
    import os as _os
    me = _os.getpid()
    found: dict = {}

    try:
        import psutil as _ps
        for conn in _ps.net_connections(kind="inet"):
            if conn.status != _ps.CONN_LISTEN or not conn.laddr:
                continue
            if conn.laddr.port != port or not conn.pid or conn.pid == me:
                continue
            found.setdefault(conn.pid, None)
    except Exception:
        pass

    if not found:
        try:
            out = subprocess.run(
                ["lsof", "-nP", f"-iTCP:{port}", "-sTCP:LISTEN", "-t"],
                capture_output=True, text=True, timeout=10)
            for line in (out.stdout or "").split():
                try:
                    pid = int(line.strip())
                except ValueError:
                    continue
                if pid and pid != me:
                    found.setdefault(pid, None)
        except Exception:
            pass

    holders = []
    for pid in found:
        name, cmd, argv = "?", "", []
        try:
            import psutil as _ps
            proc = _ps.Process(pid)
            name = proc.name()
            argv = proc.cmdline()
            cmd = " ".join(argv)
        except Exception:
            pass
        # argv, not the joined string: a path containing a space would split
        # into tokens that match nothing, and this decides whether we signal.
        holders.append({"pid": pid, "name": name, "cmd": cmd,
                        "ours": _looks_like_our_backend(argv or cmd)})
    return holders


def _reclaim_port(port: int, settle_s: float = 12.0):
    """Make `port` bindable, or explain precisely why it cannot be.

    ⭐ 2026-08-10. Closing a terminal tab does NOT stop this backend — it loses
    its terminal, reparents to init and keeps the socket. The next `--serve`
    then failed to bind, and said so only through uvicorn's raw
    "[Errno 48] error while attempting to bind" buried in the boot output. The
    operator's reasonable reading was that serve had "just shut down by itself",
    and the cure — find and kill an invisible process — was neither suggested
    nor discoverable. It cost most of an afternoon across three separate boots.

    So a stale copy of OURSELVES is now cleared automatically: stopped the same
    graceful way the supervisor stops it, escalated only if that does not take,
    and re-probed rather than assumed. Anything that is NOT ours is never
    touched — it is named, with its pid and command, and we refuse. Taking a
    port from a process we cannot identify is not ours to do, and "it was on my
    port" is not a justification anyone would accept afterwards.

    ⭐ 2026-08-13 (review). Clearing a STALE copy of ourselves was the whole
    point; clearing a WORKING one never was. Every holder that matched by name
    was signalled with no test of whether it was doing anything, so a second
    `--serve` — the command this product's own "Start it yourself" hint prints —
    ended a run that was mid-flight and took its partial output with it. A
    holder that is doing work is now refused like a foreign one: named, not
    signalled. See `_port_backend_activity` for why the liveness probe sitting
    just below this function is NOT the predicate for that question.

    Returns (state, holders) where state is one of:
      free      — nothing was holding it
      reclaimed — a stale copy of ours was stopped and the port came back
      foreign   — something else holds it; caller must refuse
      busy      — ours, and running or queueing work; caller must refuse
      stuck     — ours, but it would not let go
    """
    import signal as _sig   # NOT module-level in this file; `_kill_tree` imports
                           # its own for the same reason. Missing it here failed
                           # as a swallowed NameError, so the stale backend was
                           # never signalled and the reclaim reported "stuck".
    import time as _t

    if _wait_for_port_free(port, 0.5):
        return "free", []

    holders = _port_holders(port)
    ours = [h for h in holders if h["ours"]]
    foreign = [h for h in holders if not h["ours"]]

    if foreign:
        return "foreign", foreign
    if not ours:
        # Nothing identifiable: could be a socket in TIME_WAIT after a hard kill,
        # which clears on its own. Wait it out rather than guess at a pid.
        return ("free", []) if _wait_for_port_free(port, settle_s) else ("stuck", [])

    # Ours by name — but not therefore ours to end. Ask the holder what it is
    # doing before signalling it. One probe for the port, not per holder: they
    # are all listening on the same socket, so at most one of them answers.
    #
    # ⛔ Deliberately NOT `_port_answers_health`. It reads the status code, and
    # `/api/health` returns ok on every path, so it is equally true of the
    # orphan this function exists to clear — gating on it would refuse every
    # reclaim and delete the feature while reading like a safety fix.
    #
    # A holder that does not answer at all is still reclaimed: a wedged event
    # loop is precisely the state the terminal-less orphan is in, and refusing
    # there would put us back at the unexplained EADDRINUSE this replaced.
    #
    # ⭐⭐ BUT SILENCE IS ASKED MORE THAN ONCE, and this repo already knew why:
    # `WATCHDOG_HANG_RUNNING_SEC = 420` exists because "runs can briefly block
    # the loop", so a WORKING worker legitimately failing to answer for a few
    # seconds is normal by this codebase's own standard. A single 3s probe that
    # reads silence as idle therefore re-opens the finding for exactly the
    # holders it matters most for — three hours into a run, one blocking
    # section, killed. Retrying across the settle window costs nothing when the
    # holder is genuinely dead (it never answers, and the caller was going to
    # spend that time waiting for the port anyway) and is the difference between
    # "not answering" and "not working" for one that is alive.
    _activity = _probe_backend_activity_until_settled(port, settle_s)
    if _backend_activity_is_work(_activity):
        for h in ours:
            h["activity"] = dict(_activity or {})
        log(f"[serve] port {port} is held by a Super Research backend that is "
            f"working (running={bool((_activity or {}).get('running'))} "
            f"pending={(_activity or {}).get('pending', 0)}) — refusing to stop it",
            "WARN")
        return "busy", ours

    for h in ours:
        log(f"[serve] port {port} is held by an earlier backend (pid {h['pid']}) "
            f"— stopping it", "WARN")
        try:
            os.kill(h["pid"], _sig.SIGTERM)
        except ProcessLookupError:
            pass
        except Exception as _ke:
            log(f"[serve] could not signal pid {h['pid']}: {_ke}", "WARN")

    if _wait_for_port_free(port, settle_s):
        log(f"[serve] port {port} reclaimed from the earlier backend", "INFO")
        return "reclaimed", ours

    for h in ours:
        log(f"[serve] pid {h['pid']} did not stop — escalating", "WARN")
        try:
            # ⛔ Windows has no SIGKILL. Naming it directly raised
            # AttributeError, which the blanket `except Exception` below then
            # SWALLOWED — so this loop logged "escalating" and sent nothing at
            # all. A stop that neither works nor says so is the exact bug this
            # path exists to close, wearing a new hat.
            # os.kill() on Windows maps any signal other than CTRL_*_EVENT onto
            # TerminateProcess, so SIGTERM here IS the forced stop; there is no
            # harder one to escalate to.
            os.kill(h["pid"], getattr(_sig, "SIGKILL", _sig.SIGTERM))
        except ProcessLookupError:
            pass
        except Exception as _ke:
            log(f"[serve] forced stop of pid {h['pid']} failed: {_ke}", "WARN")

    # A killed listener leaves the socket in TIME_WAIT briefly; that is not a
    # failure, it is the kernel finishing up.
    if _wait_for_port_free(port, settle_s):
        log(f"[serve] port {port} reclaimed after a forced stop", "WARN")
        return "reclaimed", ours
    return "stuck", ours


def _wait_for_port_free(port: int, max_wait_s: float = 10.0) -> bool:
    """Poll bindability of 0.0.0.0:<port> until it becomes free or the
    timeout fires. Returns True if the port is bindable, False if we
    gave up. Used by the daemon-loop's restart cycle so a fresh --serve
    isn't immediately wedged by Windows holding the previous socket in
    TIME_WAIT (typically <1s on a clean exit, but can stretch to ~30s
    if uvicorn was force-killed mid-handshake).

    Uses SO_REUSEADDR=0 (default) for the probe — we want to know if
    the port is *truly* free, not whether we could squeeze in. The
    real --serve subprocess will bind without REUSEADDR moments later,
    so a probe success guarantees uvicorn won't hit EADDRINUSE."""
    import socket as _socket
    import time as _t  # `_time` is only imported inside run_daemon_loop;
                       # this helper runs module-level so it imports its own.
    deadline = _t.time() + max_wait_s
    while _t.time() < deadline:
        sock = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
        try:
            sock.bind(("0.0.0.0", port))
            sock.close()
            return True
        except OSError:
            sock.close()
            _t.sleep(0.5)
    return False


def _port_answers_health(port: "int | None", timeout: float = 1.5) -> bool:
    """True if http://127.0.0.1:<port>/api/health responds 2xx. Used by the
    pre-flight sweep to avoid reaping a worker that is currently serving — it
    may belong to a LIVE sibling supervisor (RC-2 collateral protection in the
    degraded no-single-instance-lock case). stdlib only.

    ⛔ This answers "is a process alive there", NOT "is it safe to stop". The
    handler returns `{"status": "ok"}` on every path it can reach, so a 2xx is
    equally true of a backend running a pipeline and of the abandoned orphan
    `_reclaim_port` exists to clear. Where the question is whether stopping it
    would destroy work, use `_port_backend_activity` — see the note there."""
    if not port:
        return False
    try:
        import urllib.request as _u
        with _u.urlopen(f"http://127.0.0.1:{port}/api/health", timeout=timeout) as r:
            return 200 <= getattr(r, "status", 200) < 300
    except Exception:
        return False


def _port_backend_activity(port: "int | None", timeout: float = 3.0) -> "dict | None":
    """What the backend on `port` says it is DOING, or None if nothing answered.

    ⭐ The companion to `_port_answers_health`, and the difference between the
    two is the whole reason this exists. That one reads the STATUS CODE, and
    `/api/health` has exactly one return statement — `{"status": "ok", …}` — so
    a 2xx proves a process is alive and nothing more. It is just as true of a
    worker three hours into a research as of the terminal-less orphan we are
    trying to clear, which means it cannot decide between them in either
    direction: refusing on it would never reclaim anything.

    The BODY is where the answer lives. `running` is this worker's live pipeline
    and `pending` its queued jobs — the same two facts the `restart` and
    `update` command handlers already refuse on, read from the same
    `_QUEUE_STATE`/`_job_queue` pair. Reusing them keeps one definition of
    "this backend is busy" instead of inventing a second.

    Returns `{"running": bool, "pending": int}` when the answer parsed, else
    None. ⚠ None means NOTHING ANSWERED — a wedged event loop, a half-dead
    process, or something that is not us — it does not mean "idle", and a caller
    must not read it as permission on its own evidence. stdlib only, matching
    `_port_answers_health` and the supervisor's `_probe_worker_health`."""
    if not port:
        return None
    try:
        import urllib.request as _u
        with _u.urlopen(f"http://127.0.0.1:{port}/api/health", timeout=timeout) as r:
            if not 200 <= getattr(r, "status", 200) < 300:
                return None
            body = json.loads(r.read().decode("utf-8"))
    except Exception:
        return None
    if not isinstance(body, dict):
        return None
    try:
        pending = int(body.get("pending") or 0)
    except (TypeError, ValueError):
        pending = 0
    return {"running": bool(body.get("running")), "pending": pending}


def _probe_backend_activity_until_settled(port: "int | None",
                                          settle_s: float = 12.0,
                                          attempts: int = 3) -> "dict | None":
    """`_port_backend_activity`, retried until something answers or time is up.

    ⭐ WHY RETRY AT ALL. A single probe conflates "not answering" with "not
    working", and this codebase already documents that those differ: the
    supervisor watchdog allows a mid-run worker **420 seconds** of silence
    (`WATCHDOG_HANG_RUNNING_SEC`) on the stated grounds that "runs can briefly
    block the loop". Against that, one 3-second probe deciding a quiet holder is
    idle is not a liveness test — it is a coin toss weighted against the busiest
    workers, which are the ones with the most to lose.

    Stops at the FIRST answer, whatever it says: an explicit `running: false` is
    a real reading and retrying it would only delay an idle reclaim.

    ⚠ Retries do NOT make silence mean "busy". A holder that never answers is
    still reclaimed — that is the wedged terminal-less orphan this whole feature
    exists to clear, and refusing it would trade one silent failure for another.
    """
    deadline = time.monotonic() + max(0.0, settle_s)
    for n in range(max(1, attempts)):
        found = _port_backend_activity(port)
        if found is not None:
            return found
        if n + 1 >= max(1, attempts) or time.monotonic() >= deadline:
            break
        time.sleep(min(0.5, max(0.0, deadline - time.monotonic())))
    return None


def _backend_activity_is_work(activity: "dict | None") -> bool:
    """Whether `_port_backend_activity`'s answer means "stopping this destroys
    work". Split out from the probe so the DECISION is testable without a socket
    — and so there is one place to look when the rule changes."""
    if not activity:
        return False
    return bool(activity.get("running")) or (activity.get("pending") or 0) > 0


def _parse_serve_port_from_cmd(cmd: str) -> "int | None":
    """Extract the `--port N` value from a --serve process command line, or None
    if absent (a serve with no explicit --port defaults to 8000)."""
    import re
    m = re.search(r"--port[=\s]+(\d+)", cmd or "")
    if m:
        try:
            return int(m.group(1))
        except ValueError:
            return None
    return 8000 if "--serve" in (cmd or "") else None


def _sweep_kill_targets(procs, self_pid, fleet_lo, fleet_hi, max_age_h, *, health_fn, age_fn):
    """Pure kill-list computation for the daemon-loop pre-flight orphan sweep —
    extracted so the ROOT-CAUSE invariant is regression-tested in isolation.

    INVARIANT (the long-standing offline-after-pair bug): a peer `--daemon-loop`
    process is NEVER reaped. Killing one cascaded (parent/child or pid-reused
    ancestry) and terminated the surviving supervisor itself, before it spawned
    any worker → API never bound → offline. Single-instance is guarded by the
    cross-process lock, not by killing peers.

    Returns (kill_pids, skipped_healthy) where kill_pids = stale --serve
    (out-of-fleet-range OR not answering /api/health) + old role=='other';
    skipped_healthy = in-range serve pids left alive for per-worker recovery.
    `health_fn(port)->bool` and `age_fn(pid)->float|None` are injected so the
    logic is unit-testable without touching real processes/sockets.
    """
    kill_pids: list[int] = []
    skipped_healthy: list[int] = []
    for pid, cmd, role in procs:
        if pid == self_pid:
            continue
        if role == "daemon-loop":
            continue  # NEVER reap a peer supervisor — see INVARIANT above
        if role == "serve":
            sp = _parse_serve_port_from_cmd(cmd)
            if sp is not None and fleet_lo <= sp <= fleet_hi and health_fn(sp):
                skipped_healthy.append(pid)
                continue
            kill_pids.append(pid)
        elif role == "other" and max_age_h > 0:
            age_s = age_fn(pid)
            if age_s is not None and age_s > max_age_h * 3600:
                kill_pids.append(pid)
    return kill_pids, skipped_healthy


def _acquire_supervisor_lock():
    """Cross-process single-instance guard for the daemon-loop supervisor (RC-1).

    Returns one of:
      • an open file handle  → WE hold the lock; keep the handle referenced for
                               the supervisor's whole lifetime (do NOT close it).
      • False                → another LIVE supervisor already holds it; the
                               caller must exit immediately WITHOUT sweeping
                               (sweeping would reap the live supervisor's healthy
                               workers — the RC-2 collateral-kill).
      • None                 → the lock primitive is unavailable on this host;
                               degrade to running unlocked (never block startup).

    Two supervisors coexisting is the condition that let a second, single-worker
    supervisor run alongside a healthy multi-worker fleet at 02:44 and (via the
    old crash-loop path) wipe the shared keystore. The OS releases the lock when
    the holder process dies, so a crashed previous supervisor's lock is reclaimed
    automatically on the next attempt — no manual stale-PID cleanup needed.
    """
    try:
        path = Path.home() / ".super-research" / ".supervisor.lock"
        path.parent.mkdir(parents=True, exist_ok=True)
        fh = open(path, "a+")
    except Exception:
        return None  # can't even create the lock file → don't block the supervisor
    try:
        if sys.platform == "win32":
            import msvcrt
            try:
                fh.seek(0)
                msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
            except OSError:
                fh.close()
                return False  # held by a live supervisor
        else:
            import fcntl
            try:
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            except OSError:
                fh.close()
                return False  # held by a live supervisor
    except Exception:
        try:
            fh.close()
        except Exception:
            pass
        return None  # lock primitive missing/unusable → degrade to unlocked
    # Record our PID for human diagnostics (the OS lock is the real guard).
    try:
        fh.seek(0)
        fh.truncate()
        fh.write(f"{os.getpid()}\n")
        fh.flush()
    except Exception:
        pass
    return fh


def _terminate_worker_fleet(workers: dict, reason: str, grace_s: float = 8.0,
                            log_fn=None) -> "tuple[int, int]":
    """Stop every live worker and DON'T RETURN UNTIL THEY ARE GONE. (exited, forced).

    ⭐ 2026-08-05 — the owner's decision, and the thing that made it necessary. The
    KeyboardInterrupt handler used to call `state["process"].terminate()` and return
    immediately: SIGTERM is a REQUEST, so a worker mid-pipeline (uvicorn draining, a
    Chromium teardown in flight) can easily still be alive when the supervisor's own
    process ends. From the outside that is indistinguishable from "Ctrl+C didn't stop
    anything" — which is exactly the report this fix came from.

    So: terminate everything, then wait on each handle against ONE shared deadline
    (not `grace_s` per worker — three workers would otherwise take 24 seconds), then
    SIGKILL whatever is left and wait again. A count of who exited on request versus
    who had to be forced goes in the log, because "forced" is the signal that a
    worker's own shutdown path is too slow or wedged.

    ⚠ The accepted cost, stated once: an in-flight pipeline is ABORTED. `--retire`
    remains the out-of-band stop for a machine that should keep running its run.
    """
    _log = log_fn if log_fn is not None else log
    live = [(k, st) for k, st in sorted((workers or {}).items())
            if st and not st.get("_dead") and st.get("process") is not None]
    if not live:
        _log(f"[daemon-loop] {reason} — no live workers to stop")
        return 0, 0
    _log(f"[daemon-loop] {reason} — stopping {len(live)} worker(s) "
         f"{[st['process'].pid for _k, st in live]} (in-flight runs are aborted)")
    for _k, st in live:
        try:
            st["process"].terminate()
        except Exception:
            pass
    deadline = time.monotonic() + max(0.0, float(grace_s))
    exited, forced = 0, 0
    for k, st in live:
        proc = st["process"]
        try:
            proc.wait(timeout=max(0.0, deadline - time.monotonic()))
            exited += 1
            continue
        except Exception:
            pass
        _log(f"[daemon-loop] worker {k}: still alive {grace_s:.0f}s after SIGTERM "
             f"— killing PID {getattr(proc, 'pid', '?')}", "WARN")
        try:
            proc.kill()
            forced += 1
        except Exception:
            pass
        # A killed child must still be REAPED, or it lingers as a zombie for as
        # long as this supervisor does — and a zombie is visible in the process
        # list, which is the very symptom that started this.
        try:
            proc.wait(timeout=5.0)
        except Exception:
            _log(f"[daemon-loop] worker {k}: did not reap after SIGKILL", "WARN")
    for _k, st in live:
        for _h in ("out_fh", "err_fh"):
            try:
                st[_h].close()
            except Exception:
                pass
    _log(f"[daemon-loop] {reason} — {exited} worker(s) exited on request, "
         f"{forced} needed SIGKILL")
    return exited, forced


def run_daemon_loop(port: int = 8000):
    """Wrapper that keeps `--serve` alive. The scheduled task installed by
    --resurrect invokes this instead of --serve directly so that the
    backend restarts automatically on ANY exit — clean shutdown from the
    Stop button (which calls os._exit to force Chromium cleanup), crashes,
    upstream failures, anything. Without this, --resurrect only fires the
    process once per logon, which defeats the "supervised" promise.

    Loops forever with a 5s delay between restarts. Exits on
    KeyboardInterrupt OR on SIGTERM/taskkill (so --retire can stop
    the live loop without requiring a reboot).

    ⭐ 2026-08-05 — CTRL+C STOPS THE WORKERS TOO, and the paragraph that used to
    stand here said the opposite ("The --serve child process is NOT killed — it
    stays alive so the current pipeline finishes"). That was already untrue of the
    multi-worker branch, which has terminated its workers on KeyboardInterrupt for
    some time, and a stale docstring is worse than none: it sent the investigation
    of "I Ctrl+C'd serve and the backend is still on :8000" down the wrong path
    entirely. Both branches now stop the fleet and WAIT for it (see
    `_terminate_worker_fleet`); the accepted cost is that an in-flight pipeline is
    aborted, and `--retire` stays the out-of-band stop for when it should not be."""
    import sys as _sys
    import subprocess as _subprocess
    import time as _time

    script_path = _launcher_path()
    # Logs live in ~/.super-research/logs/ — NOT in the pipx venv (site-packages).
    # A venv-local log dies the instant `pipx uninstall` rebuilds/removes the
    # venv, which is exactly when post-mortem logs are most needed (a user
    # uninstalling after an offline episode lost the evidence). The state dir
    # survives reinstall. Falls back to the script dir if the state dir is
    # somehow unwritable.
    _log_dir = _STATE_DIR / "logs"
    try:
        _log_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        _log_dir = Path(script_path).parent
    _serve_log = _log_dir / "backend.log"
    _serve_err = _log_dir / "backend.err.log"

    # Rotate BEFORE the pythonw tee below opens either file for append — a
    # rename with our own handle already on it is the case Windows refuses.
    # Silent here by necessity: `_sup_audit` does not exist yet and `log()`
    # crashes under pythonw until the tee is in place, so the sizes are held
    # and audited a few lines below.
    _rotated_out = _rotate_if_oversize(_serve_log)
    _rotated_err = _rotate_if_oversize(_serve_err)

    # When the Scheduled Task action runs the supervisor under pythonw.exe
    # (no-console interpreter — keeps the daemon-loop window from appearing
    # at logon), sys.stdout / sys.stderr are None and any print() inside
    # log() crashes. Tee both to the backend log files BEFORE the first
    # log() call so the supervisor stays observable and never raises on a
    # write. No-op when running under console-attached python.exe.
    if Path(_sys.executable).name.lower() == "pythonw.exe":
        try:
            _sys.stdout = open(_serve_log, "a", encoding="utf-8", buffering=1)
            _sys.stderr = open(_serve_err, "a", encoding="utf-8", buffering=1)
        except Exception:
            pass

    def _sup_audit(msg: str) -> None:
        """Append a supervisor-level event to backend.log REGARDLESS of the
        interpreter. The stdout tee above only fires under pythonw.exe, so a
        console-attached supervisor's own log() lines (crash-loop diagnostics,
        identity) were previously lost to the now-gone terminal — which is why
        the 02:44 wipe had to be reconstructed from absence-of-evidence (RC-6).
        This guarantees those events land in a durable file no matter how the
        supervisor was launched. Best-effort; never raises, never echoes-only."""
        try:
            with open(_serve_log, "a", encoding="utf-8") as _f:
                _f.write(f"[{_time.strftime('%H:%M:%S')}] [daemon-loop] {msg}\n")
                _f.flush()
        except Exception:
            pass

    # Supervisor identity line — pid, interpreter, worker count + branch. Makes
    # a second, overlapping supervisor (the RC-1 condition) instantly visible in
    # backend.log instead of having to be inferred from a stray single-worker
    # startup line.
    try:
        _sup_audit(
            f"supervisor up: pid={os.getpid()} exe={Path(_sys.executable).name} "
            f"workerCount={load_worker_count()} port={port}"
        )
        for _name, _rolled in (("backend.log", _rotated_out),
                               ("backend.err.log", _rotated_err)):
            if _rolled:
                _sup_audit(f"rotated {_name} at {_rolled} bytes → {_name}.1")
        for _stale in _prune_local_logs():
            _sup_audit(f"pruned local log capture: {Path(_stale).name}")
    except Exception:
        pass

    # Single-instance guard (RC-1) — MUST run before any sweep so a refused
    # second supervisor exits WITHOUT reaping the live one's workers (RC-2).
    # Keep `_supervisor_lock` referenced for the whole function lifetime; the OS
    # holds the lock until this process exits.
    _supervisor_lock = _acquire_supervisor_lock()
    if _supervisor_lock is False:
        _sup_audit(
            f"second supervisor refused: single-instance lock held by a live "
            f"supervisor (this pid={os.getpid()} exiting cleanly, no sweep)"
        )
        log(
            "[daemon-loop] Another supervisor is already running — exiting "
            "(single-instance). The existing supervisor keeps the device alive.",
            "WARN",
        )
        return

    # --serve always runs under console python.exe for predictable stdio
    # semantics even when the supervisor itself is pythonw.exe; uvicorn
    # output still flows into the redirected log files below, and
    # CREATE_NO_WINDOW keeps the child invisible regardless of parent.
    python_exe = _console_python_exe()

    # When --resurrect spawns daemon-loop detached (DETACHED_PROCESS), this
    # wrapper runs with no console. A naked `subprocess.run` on python.exe
    # (a console app) then forces Windows to ALLOCATE A NEW CONSOLE for
    # every --serve spawn — and every restart pops another visible terminal
    # window. CREATE_NO_WINDOW suppresses that allocation, and redirecting
    # stdio to the log files keeps uvicorn's output tailable without a
    # window ever appearing.
    #
    # 2026-05-18 (Track C smoke caught this) — `creationflags` is Windows-
    # only at the subprocess level. Passing any non-zero value to Popen on
    # POSIX raises `ValueError: creationflags is only supported on Windows
    # platforms`. The pre-fix `getattr(...CREATE_NO_WINDOW, 0x08000000)`
    # fallback fired on Linux + macOS (CREATE_NO_WINDOW doesn't exist there
    # → 0x08000000 default), making every `--serve` respawn explode in the
    # daemon-loop. Match the module-level `_PS_NO_WINDOW` pattern at
    # research.py:128 — 0 on non-Windows is the only safe value.
    _NO_WINDOW = (
        getattr(_subprocess, "CREATE_NO_WINDOW", 0x08000000)
        if sys.platform == "win32"
        else 0
    )

    # Pre-flight orphan sweep — runs once at wrapper startup. Catches:
    #   (a) other daemon-loop PIDs (only one wrapper at a time; PT5M task
    #       repetition with MultipleInstances=IgnoreNew should prevent this,
    #       but defend in depth in case of manual --daemon-loop alongside),
    #   (b) stale --serve PIDs from a prior wrapper death — port 8000 must
    #       belong to the --serve we're about to spawn,
    #   (c) one-off `python research.py "<topic>"` runs older than
    #       DG_ORPHAN_MAX_AGE_HOURS (default 4h) — manual smoke tests that
    #       were never reaped. Set =0 to disable, =24 for safety on long runs.
    self_pid = os.getpid()
    try:
        max_age_h = float(os.environ.get("DG_ORPHAN_MAX_AGE_HOURS", "4"))
    except ValueError:
        max_age_h = 4.0
    sweep_pids: list[int] = []
    # Our intended worker-port range — a healthy serve INSIDE this range that is
    # currently answering /api/health must NOT be reaped here: it is either a
    # live sibling supervisor's worker (RC-2 — never murder a healthy fleet) or
    # a leftover we'll cleanly reclaim via the per-worker EADDRINUSE port-
    # recovery on collision. Either way, killing it blindly is the bug that made
    # "workers came up healthy then went silent". (The single-instance lock
    # above is the primary guard; this scoping is the no-lock-degraded backstop.)
    try:
        _fleet_lo = port
        _fleet_hi = port + max(1, load_worker_count()) - 1
    except Exception:
        _fleet_lo, _fleet_hi = port, port
    try:
        # ROOT-CAUSE FIX (the long-standing "offline after pair/autostart"):
        # _sweep_kill_targets NEVER reaps a peer `--daemon-loop` — killing one
        # cascaded (parent/child / pid-reused ancestry from pair/resurrect's two
        # daemon-loop procs) and terminated the surviving supervisor itself
        # before it spawned any worker → API never bound → WinError 10061 →
        # offline. Single-instance is guarded by _acquire_supervisor_lock above,
        # not by killing peers. The helper reaps only stale --serve (out-of-
        # fleet-range or unhealthy) + old one-off `research.py <topic>` procs.
        sweep_pids, _skipped = _sweep_kill_targets(
            _enumerate_research_py_procs(), self_pid, _fleet_lo, _fleet_hi, max_age_h,
            health_fn=_port_answers_health, age_fn=_proc_age_seconds,
        )
        for _hp in _skipped:
            log(f"[daemon-loop] Pre-flight sweep: NOT reaping healthy in-range serve "
                f"pid={_hp} (alive); leaving it to per-worker port-recovery if we collide.", "INFO")
    except Exception as _se:
        sweep_pids = []
        log(f"[daemon-loop] Pre-flight sweep enumeration failed: {_se}", "WARN")
    if sweep_pids:
        killed = _kill_pids(sweep_pids)
        log(f"[daemon-loop] Pre-flight sweep: killed {killed}/{len(sweep_pids)} stale --serve/orphan procs ({sweep_pids})")

    # Pre-flight dependency probe — runs once before the respawn loop.
    # Catches the silent-crash trap: when --serve fails its import
    # chain (e.g. fastapi missing, or google.auth transitive dep absent),
    # the supervisor would otherwise retry forever at 5s/cycle with no
    # loud signal. One loud abort is much better than infinite quiet
    # retries — the supervisor's re-fire still gives a second chance
    # after the user reinstalls deps.
    try:
        import importlib
        # Full dotted module paths — importlib.import_module handles
        # submodules (PIL.Image, google.auth, google.cloud.firestore) but
        # `import PIL; getattr(PIL, "Image")` raises AttributeError
        # because PIL.Image is a submodule, not an attribute of the
        # PIL package.
        _critical = [
            "fastapi", "uvicorn", "websockets", "pydantic",
            "typing_extensions", "anthropic", "playwright", "patchright",
            "google.auth", "google.cloud.firestore", "keyring",
            "PIL.Image", "markdownify", "requests", "qrcode",
        ]
        _missing: list[str] = []
        for _mod in _critical:
            try:
                importlib.import_module(_mod)
            except Exception as _ie:
                _missing.append(f"{_mod} ({_ie.__class__.__name__}: {_ie})")
        if _missing:
            # The old line pointed at `{_log_dir}/requirements.txt` — a path
            # that exists on no install of either kind, so the one instruction
            # printed at the moment the product stopped working could not work.
            _msg = (
                f"SUPERVISOR ABORT: {len(_missing)} required import(s) failed under "
                f"{python_exe}, so this machine cannot start. Repair it with: "
                f"{_remedy_reinstall()}. "
                f"Missing: " + "; ".join(_missing)
            )
            try:
                log(_msg, "ERROR")
            except Exception:
                pass
            try:
                with open(_serve_err, "a", encoding="utf-8") as _ef:
                    _bar = "=" * 80
                    _ef.write(f"\n{_bar}\n[{_time.strftime('%H:%M:%S')}] {_msg}\n{_bar}\n")
            except Exception:
                pass
            _sys.exit(2)
    except SystemExit:
        raise
    except Exception as _pe:
        log(f"[daemon-loop] Pre-flight import probe crashed (continuing anyway): {_pe}", "WARN")

    # ──── Multi-worker branch (2026-05-21) ────────────────────────────
    # workerCount > 1 means pair Stage 4 set up N>=2 browser profiles —
    # spawn N --serve subprocesses (one per profile slot) in parallel via
    # Popen + a poll loop. Each worker K binds port (port + K - 1) and
    # is pinned to its own profile dir via --worker-id=K. Single-worker
    # mode (workerCount=1) falls through to the existing subprocess.run
    # blocking loop below — same behavior as pre-PR.
    CRASH_WINDOW_SEC = 30
    CRASH_THRESHOLD = 3
    # #717 — liveness watchdog. The crash tracker above only fires on process
    # EXIT; a worker can also WEDGE (event loop stalled, or Firestore stuck
    # offline despite localhost up) without exiting. The watchdog polls
    # /api/health and force-respawns a wedged worker. It is damped by its OWN
    # window (NOT crash_window) so a watchdog respawn never inflates the crash
    # tracker's stop-respawn/back-off counter, and capped so a sustained global outage (every worker
    # unreachable) doesn't storm. Backstops are idle-only and worker-aware to
    # avoid false-killing a busy run or the heartbeat-silent worker 2.
    WATCHDOG_HANG_SEC = 180          # /api/health unreachable this long while IDLE → wedged
    WATCHDOG_HANG_RUNNING_SEC = 420  # ...lenient if it was mid-run (runs can briefly block the loop)
    WATCHDOG_TICK_STALE_SEC = 120    # health OK but reconnect-loop pulse frozen → event loop wedged
    WATCHDOG_OFFLINE_SEC = 150       # worker-1 only: health OK but device heartbeat stale → reconnect failing
    WATCHDOG_KILL_THRESHOLD = 3      # watchdog respawns within the window → give up (likely a sustained outage)
    WATCHDOG_KILL_WINDOW_SEC = 600
    n_workers = load_worker_count()
    if n_workers > 1:
        log(f"[daemon-loop] Multi-worker mode: spawning {n_workers} workers")
        # Per-worker state: process handle, log file handles, crash window,
        # restart count. {"_dead": True} = won't respawn (a worker 2+ that hit
        # the crash-loop threshold); worker 1 always keeps retrying with backoff
        # (never marked dead) since it owns heartbeat/recovery. (`keystore_wiped`
        # is vestigial — the crash-loop keystore wipe was removed in RC-3.)
        workers: dict[int, dict] = {}

        def _open_logs(k: int):
            # Worker 1 keeps the legacy log filenames so existing tooling
            # (tail backend.log) keeps working. Workers 2+ get -{k} suffix
            # so the streams don't interleave.
            if k == 1:
                return (_log_dir / "backend.log", _log_dir / "backend.err.log")
            return (_log_dir / f"backend-{k}.log", _log_dir / f"backend-{k}.err.log")

        def _spawn_worker(k: int):
            w_port = port + (k - 1)
            log_out_path, log_err_path = _open_logs(k)
            # Port probe — if the port is wedged from a prior session,
            # log it and try anyway (uvicorn will surface EADDRINUSE).
            if not _wait_for_port_free(w_port, max_wait_s=10.0):
                log(f"[daemon-loop] worker {k}: port {w_port} still in use after 10s — spawning anyway", "WARN")
            _rotate_if_oversize(log_out_path, audit=_sup_audit)
            _rotate_if_oversize(log_err_path, audit=_sup_audit)
            try:
                _out_fh = open(log_out_path, "ab")
                _err_fh = open(log_err_path, "ab")
            except Exception as _oe:
                log(f"[daemon-loop] worker {k}: log file open failed: {_oe}", "ERROR")
                return None
            try:
                proc = _subprocess.Popen(
                    [python_exe, script_path, "--serve",
                     "--port", str(w_port), "--worker-id", str(k)],
                    stdin=_subprocess.DEVNULL,
                    stdout=_out_fh,
                    stderr=_err_fh,
                    creationflags=_NO_WINDOW,
                )
            except Exception as _se:
                log(f"[daemon-loop] worker {k}: Popen failed: {_se}", "ERROR")
                try:
                    _out_fh.close()
                    _err_fh.close()
                except Exception:
                    pass
                return None
            log(f"[daemon-loop] worker {k}: started PID={proc.pid} port={w_port}")
            return {
                "process": proc,
                "out_fh": _out_fh,
                "err_fh": _err_fh,
                "port": w_port,
                "crash_window": [],
                "keystore_wiped": False,
                "restarts": 0,
                # #717 watchdog state (separate from crash tracking)
                "watchdog_window": [],
                "unreachable_since": None,
                "last_running": False,
                "watchdog_killing": False,
                "watchdog_gaveup": False,
            }

        def _probe_worker_health(w_port: int):
            """GET /api/health on a worker. Returns the parsed dict, or None if
            unreachable (connection refused / timeout / bad response). stdlib
            urllib so the supervisor needs no extra deps. (#717)"""
            try:
                import urllib.request as _u
                with _u.urlopen(f"http://127.0.0.1:{w_port}/api/health", timeout=3) as _r:
                    return json.loads(_r.read().decode("utf-8"))
            except Exception:
                return None

        def _watchdog_respawn(k: int, state: dict, reason: str):
            """Force-respawn a wedged worker. Uses a SEPARATE damping window so
            it never feeds the crash tracker (which stops respawning / backs off
            a worker on a 3x loop). Hard terminate — a wedged event loop can't run its own
            graceful exit; the respawned worker's Browser.start() orphan sweep
            reaps any leftover chromium. Gives up after WATCHDOG_KILL_THRESHOLD
            respawns in the window so a sustained outage (every worker
            unreachable at once) doesn't storm. (#717)"""
            now = _time.time()
            win = [t for t in state.get("watchdog_window", []) if t > now - WATCHDOG_KILL_WINDOW_SEC]
            if len(win) >= WATCHDOG_KILL_THRESHOLD:
                if not state.get("watchdog_gaveup"):
                    log(f"[watchdog] worker {k}: {WATCHDOG_KILL_THRESHOLD} respawns in "
                        f"<{WATCHDOG_KILL_WINDOW_SEC}s — GIVING UP watchdog respawns "
                        f"(likely a sustained outage, not a per-worker wedge). "
                        f"Last reason: {reason}", "ERROR")
                    state["watchdog_gaveup"] = True
                return
            win.append(now)
            state["watchdog_window"] = win
            state["watchdog_killing"] = True
            state["unreachable_since"] = None
            log(f"[watchdog] worker {k}: force-respawning — {reason}", "WARN")
            try:
                state["process"].terminate()
            except Exception as _te:
                log(f"[watchdog] worker {k}: terminate failed: {_te}", "WARN")

        def _watchdog_check(k: int, state: dict):
            """Poll a RUNNING worker's health and respawn it if wedged. Scoped to
            avoid false-kills: device-heartbeat staleness is worker-1 only (only
            w1 writes it); active-run + relink workers are exempt from the idle
            backstops; the frozen-pulse check uses the per-worker lastTickAt so
            it also covers the heartbeat-silent worker 2. (#717)"""
            if state.get("watchdog_killing"):
                return
            if state.get("watchdog_gaveup"):
                # Re-arm once the give-up window has fully elapsed with no new
                # respawns (RC-30). A give-up must be TIME-BOUNDED: otherwise a
                # single sustained-outage burst disables the watchdog for this
                # worker for the rest of the process's life — and a worker-1 that
                # wedges after that point is a permanent, silent offline.
                _gw = state.get("watchdog_window", [])
                if not _gw or (_time.time() - max(_gw)) > WATCHDOG_KILL_WINDOW_SEC:
                    log(f"[watchdog] worker {k}: re-arming (give-up window of "
                        f"{WATCHDOG_KILL_WINDOW_SEC}s elapsed quietly)", "INFO")
                    state["watchdog_gaveup"] = False
                    state["watchdog_window"] = []
                else:
                    return
            now = _time.time()
            health = _probe_worker_health(state.get("port"))
            if health is None:
                # Unreachable — could be a wedge, or a worker still booting.
                if state.get("unreachable_since") is None:
                    state["unreachable_since"] = now
                was_running = state.get("last_running", False)
                limit = WATCHDOG_HANG_RUNNING_SEC if was_running else WATCHDOG_HANG_SEC
                if now - state["unreachable_since"] > limit:
                    _watchdog_respawn(k, state,
                        f"/api/health unreachable {int(now - state['unreachable_since'])}s "
                        f"(was_running={was_running})")
                return
            # Reachable — refresh cached state, clear the unreachable timer.
            state["unreachable_since"] = None
            running = bool(health.get("running"))
            relinking = bool(health.get("relinking"))
            state["last_running"] = running
            # Idle backstops only — never force-respawn mid-run or mid-relink
            # (defer to the in-run watchdog / the legit 15-min relink poll).
            if running or relinking:
                return
            tick = int(health.get("lastTickAt") or 0)
            if tick > 0 and (now * 1000 - tick) > WATCHDOG_TICK_STALE_SEC * 1000:
                _watchdog_respawn(k, state,
                    f"reconnect-loop pulse frozen {int(now - tick / 1000)}s (event loop wedged)")
                return
            if k == 1:
                hb = int(health.get("lastHeartbeatAt") or 0)
                if hb > 0 and (now * 1000 - hb) > WATCHDOG_OFFLINE_SEC * 1000:
                    _watchdog_respawn(k, state,
                        f"device heartbeat stale {int(now - hb / 1000)}s despite reachable "
                        f"health (in-process reconnect failing)")

        # Initial spawn of all workers.
        for k in range(1, n_workers + 1):
            workers[k] = _spawn_worker(k) or {"_dead": True}

        try:
            while True:
                _time.sleep(2)
                for k in range(1, n_workers + 1):
                    state = workers.get(k)
                    if state is None or state.get("_dead"):
                        # Spawn-failed-permanently slots can be retried on
                        # the next iteration in case the underlying issue
                        # (port held, disk full, etc.) cleared.
                        new_state = _spawn_worker(k)
                        if new_state is not None:
                            workers[k] = new_state
                        continue
                    rc = state["process"].poll()
                    if rc is None:
                        # Still running — liveness watchdog (#717).
                        _watchdog_check(k, state)
                        continue
                    # Worker exited — close logs, track crash, decide.
                    log(f"[daemon-loop] worker {k}: exited with code {rc}")
                    try:
                        state["out_fh"].close()
                        state["err_fh"].close()
                    except Exception:
                        pass
                    # A watchdog-initiated terminate must NOT feed the crash
                    # tracker — that path stops respawning / backs off a worker on
                    # a 3x loop. Respawn clean, carrying only the watchdog's own
                    # damping window. (#717)
                    if state.pop("watchdog_killing", False):
                        log(f"[daemon-loop] worker {k}: respawning after watchdog terminate")
                        _time.sleep(2)
                        new_state = _spawn_worker(k)
                        if new_state is not None:
                            new_state["watchdog_window"] = state.get("watchdog_window", [])
                            workers[k] = new_state
                        else:
                            workers[k] = {"_dead": True}
                        continue
                    if rc == 0:
                        state["crash_window"] = []
                        state["keystore_wiped"] = False
                        state["watchdog_window"] = []  # clean exit resets watchdog damping too
                    else:
                        _now = _time.time()
                        # Port-squatter auto-recovery (RC-3/RC-16): a leftover
                        # process on this worker's port makes uvicorn raise
                        # EADDRINUSE and exit non-zero. That is RECOVERABLE and it
                        # is NOT a crash — free the port and respawn WITHOUT
                        # counting it toward the crash tracker (else a persistent
                        # squatter would falsely look like a crash loop and, in the
                        # old code, trip a keystore wipe).
                        _w_port = state.get("port") or (port + (k - 1))
                        _, _err_path = _open_logs(k)
                        if _serve_exit_was_port_conflict(_err_path):
                            freed = _free_port(_w_port)
                            log(
                                f"[daemon-loop] worker {k}: port {_w_port} was occupied "
                                f"(EADDRINUSE) — freed {freed or 'nothing'}; respawning "
                                f"(not counted as a crash)",
                                "WARN",
                            )
                        else:
                            state["crash_window"].append(_now)
                            state["crash_window"] = [
                                t for t in state["crash_window"] if t > _now - CRASH_WINDOW_SEC
                            ]
                            if len(state["crash_window"]) >= CRASH_THRESHOLD:
                                # RC-3: a non-zero --serve exit is a CRASH (bad dep /
                                # corrupt profile / unexpected error) — NEVER a token
                                # revoke. A genuine revoke makes --serve exit 0 and
                                # enter the in-process relink loop; by the time we see
                                # 3 non-zero exits, init_firebase has already done a
                                # live refresh + rotated a valid token N times. So we
                                # do NOT wipe the keystore here: it is shared
                                # install-wide, and wiping forced a re-pair AND
                                # de-authed healthy sibling workers (the 02:44 bug).
                                #
                                # Belt-and-suspenders: if ANY sibling is reachable +
                                # healthy, the shared token is provably valid, which
                                # makes an auth problem impossible by construction.
                                _sib_ok = any(
                                    _probe_worker_health(w.get("port"))
                                    for j, w in workers.items()
                                    if j != k and w and not w.get("_dead")
                                )
                                if k == 1:
                                    _sup_audit(
                                        f"worker 1 crash loop ({len(state['crash_window'])} "
                                        f"non-zero exits in <{CRASH_WINDOW_SEC}s) — NOT wiping "
                                        f"keystore; siblings_healthy={_sib_ok}; see backend.err.log"
                                    )
                                    log(
                                        f"[daemon-loop] worker 1: crash loop "
                                        f"({len(state['crash_window'])} non-zero exits in "
                                        f"<{CRASH_WINDOW_SEC}s) — NOT wiping keystore (a "
                                        f"crash is not a revoke). Inspect backend.err.log "
                                        f"(port conflict / corrupt profile dir / dep "
                                        f"mismatch)."
                                        + (
                                            " Siblings are healthy → the auth token is "
                                            "valid; this is a worker-1-local problem."
                                            if _sib_ok else ""
                                        )
                                        + " Backing off, will keep retrying.",
                                        "ERROR",
                                    )
                                    # Diagnose once per loop, not every cycle, and
                                    # back off harder than the 5s below.
                                    state["crash_window"] = []
                                    _time.sleep(25)
                                else:
                                    # Worker 2+: stop respawning to prevent spam;
                                    # worker 1 keeps the device functional.
                                    _sup_audit(
                                        f"worker {k} crash loop ({len(state['crash_window'])} "
                                        f"non-zero exits in <{CRASH_WINDOW_SEC}s) — STOPPING "
                                        f"respawn; see backend-{k}.err.log"
                                    )
                                    log(
                                        f"[daemon-loop] worker {k}: crash loop "
                                        f"({len(state['crash_window'])} non-zero exits in "
                                        f"<{CRASH_WINDOW_SEC}s) — STOPPING respawn for this "
                                        f"worker. Check backend-{k}.err.log and fix the "
                                        f"underlying issue (port conflict / profile dir "
                                        f"missing / dep mismatch). Siblings keep running.",
                                        "ERROR",
                                    )
                                    # #64: durable on-disk marker so worker-1
                                    # (alive) can mark this permanently-dead
                                    # worker's abandoned "ongoing" runs
                                    # paused_backend_restart — the supervisor has
                                    # no Firestore client of its own.
                                    _write_worker_dead_marker(
                                        k,
                                        pid=(state.get("process").pid
                                             if state.get("process") else None),
                                        crash_count=len(state.get("crash_window") or []),
                                    )
                                    workers[k] = {"_dead": True}
                                    continue
                    state["restarts"] += 1
                    log(f"[daemon-loop] worker {k}: restarting (restart #{state['restarts']}) in 5s…")
                    _time.sleep(5)
                    new_state = _spawn_worker(k)
                    if new_state is not None:
                        # Carry over crash tracking across the respawn.
                        new_state["crash_window"] = state["crash_window"]
                        new_state["keystore_wiped"] = state["keystore_wiped"]
                        new_state["restarts"] = state["restarts"]
                        new_state["watchdog_window"] = state.get("watchdog_window", [])  # (#717)
                        workers[k] = new_state
                    else:
                        workers[k] = {"_dead": True}
        except KeyboardInterrupt:
            _terminate_worker_fleet(workers, "Interrupted (Ctrl+C)")
            return
        except Exception as _mw_err:
            # Any other exception in the multi-worker loop (rare:
            # resource exhaustion in _time.sleep, corrupted Popen state,
            # etc.) MUST NOT fall through to the single-worker code
            # below — that path would spawn an additional --serve on
            # port 8000 racing the existing worker-1. Terminate all
            # known children, log loudly, and exit the wrapper so the
            # supervisor's scheduled-task respawn can give us a fresh
            # event loop. Without this `return`, the multi-worker loop's
            # spawned children remain alive AND the single-worker loop
            # spins up its own --serve, leaving 2× the worker count.
            log(f"[daemon-loop] Multi-worker loop crashed: {_mw_err} — terminating workers + exiting wrapper for clean respawn", "ERROR")
            # ⚠ Same helper, and the WAIT matters more here than on Ctrl+C: this
            # branch exists so the scheduled task can respawn us with a fresh event
            # loop, and returning while the old workers still hold ports 8000+ is how
            # the respawn walks into EADDRINUSE on every slot.
            _terminate_worker_fleet(workers, f"Loop crashed ({_mw_err})")
            return

    # ──── Single-worker branch (legacy, workerCount==1) ────────────────
    # Crash-loop diagnostic (RC-3). If --serve exits non-zero CRASH_THRESHOLD
    # times within CRASH_WINDOW_SEC, surface the real cause loudly and keep
    # retrying with backoff. We deliberately do NOT wipe the keystore here:
    # a non-zero exit is a CRASH (port squatter — already auto-freed by the
    # mid-cycle sweep below — or a dep/profile fault), and a crash is NOT a
    # token revoke (a genuine revoke makes --serve exit 0 and enter the
    # in-process _revoked_recovery_loop). The old behaviour wiped the keystore
    # on any crash loop, which forced a needless re-pair on a recoverable local
    # problem (and, in multi-worker, de-authed healthy siblings). A genuinely
    # stuck / parser-unrecognised revoke is now visible in backend.err.log and
    # ~/.super-research/keystore-audit.log rather than silently nuking the
    # pairing; the fix for that is to harden the revoke parser, not to wipe.
    crash_window: list[float] = []
    restarts = 0
    while True:
        try:
            log(f"[daemon-loop] Starting --serve (restart #{restarts})")
            # ⭐ THE SITE THAT ACTUALLY MATTERS. `load_worker_count()` defaults
            # to 1, so this loop — not the multi-worker branch — is where the
            # default install lives. It also re-opens on every respawn, which
            # makes rotation per-respawn for free.
            _rotate_if_oversize(_serve_log, audit=_sup_audit)
            _rotate_if_oversize(_serve_err, audit=_sup_audit)
            with open(_serve_log, "ab") as _out, open(_serve_err, "ab") as _err:
                result = _subprocess.run(
                    [python_exe, script_path, "--serve", "--port", str(port)],
                    stdin=_subprocess.DEVNULL,
                    stdout=_out,
                    stderr=_err,
                    creationflags=_NO_WINDOW,
                )
            log(f"[daemon-loop] --serve exited with code {result.returncode}")
            # Track crash-loop pattern. Code 0 = clean exit (Ctrl+C from
            # outside, or `_revoked_recovery_loop` calling os._exit(0)
            # after picking up a fresh customToken). Clean exits reset
            # the window so a healthy restart doesn't get falsely
            # flagged later.
            if result.returncode == 0:
                crash_window = []
            else:
                _now = _time.time()
                crash_window.append(_now)
                crash_window = [t for t in crash_window if t > _now - CRASH_WINDOW_SEC]
                if len(crash_window) >= CRASH_THRESHOLD:
                    # RC-3: surface the cause; never wipe the keystore on a crash.
                    _sup_audit(
                        f"single-worker crash loop ({len(crash_window)} non-zero "
                        f"exits in <{CRASH_WINDOW_SEC}s) — NOT wiping keystore; see backend.err.log"
                    )
                    log(
                        f"[daemon-loop] Crash loop detected: {len(crash_window)} "
                        f"non-zero exits in <{CRASH_WINDOW_SEC}s. NOT wiping the "
                        f"keystore (a crash is not a revoke). Inspect "
                        f"backend.err.log for the real cause (port conflict / dep "
                        f"mismatch / corrupt profile). If the refresh token is "
                        f"genuinely revoked, run `{_PROG} --unpair && "
                        f"{_PROG} --pair`. Backing off, will keep retrying.",
                        "ERROR",
                    )
                    crash_window = []  # diagnose once per loop, not every cycle
                    try:
                        _time.sleep(25)  # extra backoff on top of the 5s below
                    except KeyboardInterrupt:
                        log("[daemon-loop] Interrupted during backoff — exiting wrapper")
                        return
        except KeyboardInterrupt:
            log("[daemon-loop] Interrupted — exiting wrapper")
            return
        except Exception as e:
            log(f"[daemon-loop] Subprocess launch failed: {e}", "WARN")
        restarts += 1
        log("[daemon-loop] Restarting in 5s…")
        try:
            _time.sleep(5)
        except KeyboardInterrupt:
            log("[daemon-loop] Interrupted during sleep — exiting wrapper")
            return

        # Per-iteration sweep + port-free probe. The wrapper-startup
        # sweep (above) only runs once; without this mid-cycle check
        # a serve that died mid-bind, or a hard-reset that didn't
        # quite release the socket, would leave port 8000 blocked
        # and the next subprocess.run would crash on EADDRINUSE in
        # uvicorn's startup — looping forever at 5s/cycle. Sweep
        # any orphan --serve PIDs first, then poll the port for up
        # to 10s. If still blocked, log and proceed anyway —
        # subprocess.run's failure logs will reveal the real cause.
        # Wrapped in the same KeyboardInterrupt handler shape as the
        # surrounding subprocess.run / sleep blocks so a Ctrl-C lands
        # in `_wait_for_port_free`'s inner sleep doesn't escape and
        # crash the wrapper.
        try:
            # Per-restart sweep reaps stale --serve children only. We do NOT kill
            # peer --daemon-loop wrappers here (see the ROOT-CAUSE FIX in the
            # pre-flight sweep above): the single-instance lock guarantees only one
            # supervisor runs, and taskkilling a peer/parent daemon-loop cascaded
            # and killed THIS supervisor too — the offline-after-pair bug. A losing
            # daemon-loop exits cleanly via the lock on its own.
            stale_serve: list[int] = []
            for pid, _cmd, role in _enumerate_research_py_procs():
                if pid == self_pid:
                    continue
                if role == "serve":
                    stale_serve.append(pid)
            if stale_serve:
                killed = _kill_pids(stale_serve)
                log(f"[daemon-loop] Pre-restart sweep: killed {killed}/{len(stale_serve)} stale --serve procs ({stale_serve})")
            if not _wait_for_port_free(port, max_wait_s=10.0):
                log(f"[daemon-loop] Port {port} still in use after 10s — spawning anyway; uvicorn will surface the cause", "WARN")
        except KeyboardInterrupt:
            log("[daemon-loop] Interrupted during pre-restart sweep — exiting wrapper")
            return
        except Exception as _se:
            log(f"[daemon-loop] Pre-restart sweep/probe failed: {_se}", "WARN")


def _write_supervised_flag(enabled: bool):
    """Push the Supervised flag to the top-level `devices/{deviceId}` doc
    so the FE Account-page On Startup toggle reflects the supervisor
    state. Uses Firestore REST PATCH via _pair_patch_device — no gRPC
    client init needed, so callers (--resurrect / --retire / --pair
    Stage 5) don't pay the ~10-30s init_firebase wall-clock on Windows.

    Best-effort: if no deviceId on disk or the PATCH fails, returns
    silently (the Scheduled Task / launchd / systemd unit is the actual
    source of truth for supervisor state, and the heartbeat will re-
    write supervised on next --serve boot)."""
    device_id = load_device_id()
    if not device_id:
        log("Device not paired — skipping Firestore flag update.", "WARN")
        return
    if _pair_patch_device(device_id, {"supervised": bool(enabled)}):
        log(f"Supervised flag = {enabled} written to device doc.")
    else:
        log("Could not update supervised flag (REST patch failed)", "WARN")


def _apply_supervisor_respawn_policy() -> "tuple[bool, str]":
    """Layer recurring trigger + restart-on-failure onto an existing
    SuperResearchBackend Scheduled Task. schtasks /SC ONLOGON does not
    expose Repetition or RestartCount via command-line, so we shell out
    to PowerShell once the task is created to set them.

    PT5M repetition + MultipleInstances=IgnoreNew → max ~5-min offline
    gap if daemon-loop dies for any reason (clean exit, Ctrl+C, crash).
    RestartCount=3 + RestartInterval=PT1M backstops non-zero failure
    exits with up to 3 retries spaced 1 minute apart.

    Returns (ok, msg). Best-effort: failure leaves the bare /SC ONLOGON
    behavior intact (one-shot at logon, no auto-respawn mid-session).
    """
    import subprocess as _subprocess
    ps = (
        "$ErrorActionPreference='Stop'; "
        f"$t = Get-ScheduledTask -TaskName '{_SUPERVISOR_TASK_NAME}'; "
        "$t.Triggers[0].Repetition.Interval = 'PT5M'; "
        "$t.Settings.RestartCount = 3; "
        "$t.Settings.RestartInterval = 'PT1M'; "
        # Make the comment true: if a supervisor is already running when the
        # PT5M repetition (or a re-logon) fires, the scheduler must NOT launch a
        # second one. The in-process single-instance lock (_acquire_supervisor_
        # lock) is the real backstop for manual launches, but setting this stops
        # the scheduler from even spawning a redundant supervisor. (RC-1)
        "$t.Settings.MultipleInstances = 'IgnoreNew'; "
        "$t.Settings.StartWhenAvailable = $true; "
        # Vista compat-mode defaults gate task start/run on AC power. On a
        # laptop, this means the supervisor goes "Queued" forever the moment
        # the cable is unplugged. Disable both so the supervisor stays alive
        # whether the user is on battery or on AC.
        "$t.Settings.DisallowStartIfOnBatteries = $false; "
        "$t.Settings.StopIfGoingOnBatteries = $false; "
        f"Set-ScheduledTask -TaskName '{_SUPERVISOR_TASK_NAME}' "
        "-Trigger $t.Triggers[0] -Settings $t.Settings | Out-Null"
    )
    try:
        result = _subprocess.run(
            ["powershell", "-NoProfile", "-NonInteractive", "-Command", ps],
            capture_output=True, text=True, timeout=30,
            creationflags=_PS_NO_WINDOW,
        )
        if result.returncode != 0:
            return False, (result.stderr or result.stdout or "PS exit non-zero").strip()
        return True, "applied"
    except Exception as e:
        return False, f"PS error: {e}"


def _supervisor_installed() -> bool:
    """Whether the always-on supervisor is pinned on this machine (launchd agent /
    systemd --user unit / Scheduled Task). Cheap + best-effort; False on any doubt."""
    import subprocess as _sp
    plat = _supervisor_platform()
    try:
        if plat == "Darwin":
            return _SUPERVISOR_PLIST_PATH.exists()
        if plat == "Linux":
            return _SUPERVISOR_UNIT_PATH.exists()
        if plat == "Windows":
            r = _sp.run(["schtasks", "/Query", "/TN", _SUPERVISOR_TASK_NAME],
                        capture_output=True, text=True, timeout=15,
                        creationflags=_PS_NO_WINDOW)
            return r.returncode == 0
    except Exception:
        return False
    return False


def _restart_supervisor() -> "tuple[bool, str]":
    """Restart an ALREADY-INSTALLED supervisor so it re-execs the code on disk.

    This is the post-update step: `pipx upgrade` / `--update` / the web installer
    all replace the package, but the RUNNING supervisor keeps the old code in
    memory until it is cycled. Each platform needs a real restart — the arm/install
    calls are NOT enough on their own:

      • macOS   — `launchctl kickstart -k` (the -k kills then restarts the job).
                  `bootstrap` alone errors when the job is already loaded.
      • Linux   — `systemctl --user restart`. `enable --now` is a no-op on an
                  already-running unit, so it would keep serving the OLD code.
      • Windows — `schtasks /End` then `/Run`. `/Create /F` rewrites the task
                  definition but never touches the running process.

    Returns (ok, message). Never raises."""
    import subprocess as _sp
    import os as _os
    plat = _supervisor_platform()
    if not _supervisor_installed():
        return False, "not installed"
    try:
        if plat == "Darwin":
            label = f"gui/{_os.getuid()}/{_SUPERVISOR_PLIST_LABEL}"
            r = _sp.run(["launchctl", "kickstart", "-k", label],
                        capture_output=True, text=True, timeout=30)
            if r.returncode != 0:
                return False, (r.stderr or r.stdout or "kickstart non-zero").strip()[:160]
            return True, "restarted"
        if plat == "Linux":
            r = _sp.run(["systemctl", "--user", "restart", _SUPERVISOR_UNIT_NAME],
                        capture_output=True, text=True, timeout=30)
            if r.returncode != 0:
                return False, (r.stderr or r.stdout or "restart non-zero").strip()[:160]
            return True, "restarted"
        if plat == "Windows":
            # /End is best-effort: the task may be idle, which returns non-zero.
            try:
                _sp.run(["schtasks", "/End", "/TN", _SUPERVISOR_TASK_NAME],
                        capture_output=True, text=True, timeout=20,
                        creationflags=_PS_NO_WINDOW)
            except Exception:
                pass
            r = _sp.run(["schtasks", "/Run", "/TN", _SUPERVISOR_TASK_NAME],
                        capture_output=True, text=True, timeout=20,
                        creationflags=_PS_NO_WINDOW)
            if r.returncode != 0:
                return False, (r.stderr or r.stdout or "schtasks /Run non-zero").strip()[:160]
            return True, "restarted"
    except Exception as e:
        return False, f"{type(e).__name__}: {e}"
    return False, f"unsupported platform ({plat})"


def _arm_supervisor_quiet() -> "tuple[bool, int | None, str, int]":
    """Dispatcher — routes to `_arm_supervisor_quiet_windows`,
    `_arm_supervisor_macos`, or `_arm_supervisor_linux`. Returns the same
    4-tuple shape regardless of platform: (installed_ok, daemon_pid_or_None,
    info, killed_serve_count)."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return _arm_supervisor_quiet_windows()
    if plat == "Darwin":
        return _arm_supervisor_macos()
    if plat == "Linux":
        return _arm_supervisor_linux()
    # Unsupported returns a consistent "not supported" tuple so callers
    # don't need platform branches.
    return False, None, "unsupported", 0


def _arm_supervisor_quiet_windows() -> "tuple[bool, int | None, str, int]":
    """Install the SuperResearchBackend scheduled task AND spawn a detached
    daemon-loop. No terminal narration — callers do their own.

    Returns (installed_ok, pid_or_None, info, killed_serve_count):
      • installed_ok         — schtasks install succeeded
      • pid_or_None          — daemon-loop pid if live-detected within 5s
      • info:
          - "non-Windows"    — platform not supported
          - "already running" — daemon-loop was already live; pid reflects that
          - ""               — fresh spawn detected within 5s
          - "<error string>" — failure (schtasks error, Popen failed, spawn
                               took > 5s to appear, etc.)
      • killed_serve_count   — number of plain --serve processes we had to
                               stop to free port 8000 for the supervised
                               child. Callers warn the user since the other
                               terminal's --serve died silently.

    installed_ok=True + pid=None means the scheduled task is installed but
    the live spawn did not appear — the next login will still fire it, so
    On Startup mode is enabled for the future even if this turn didn't
    catch the process handoff."""
    import subprocess as _subprocess
    import platform as _platform
    import time as _time

    if _platform.system() != "Windows":
        return False, None, "non-Windows", 0

    # Seed `.dg-supervisor.env` from scripts/dg-supervisor.env.example if
    # the user hasn't created one yet. Idempotent — no-op when target exists.
    _seed_env_file_if_missing()

    # pythonw.exe (no-console subsystem) keeps the supervisor invisible at
    # logon — under the `/IT` interactive token, console-mode python.exe
    # would otherwise pop a visible daemon-loop terminal. Scheduled Task
    # invokes pythonw DIRECTLY (NOT via a cmd.exe /c wrapper) — the cmd
    # intermediary would flash a console window on every PT5M trigger
    # fire. The same quoted-path pattern as before; --env-file is an extra
    # quoted arg that Python loads via _load_env_file() before subcommand
    # dispatch.
    python_exe = _supervisor_python_exe()
    script_path = _launcher_path()
    env_file = _SUPERVISOR_ENV_FILE_DEFAULT_PATH
    task_run = f'"{python_exe}" "{script_path}" --daemon-loop --env-file "{env_file}"'

    cmd = [
        "schtasks", "/Create",
        "/TN", _SUPERVISOR_TASK_NAME,
        "/TR", task_run,
        "/SC", "ONLOGON",
        "/RL", "LIMITED",
        "/IT",
        "/F",
    ]
    try:
        result = _subprocess.run(cmd, capture_output=True, text=True, timeout=30,
                                 creationflags=_PS_NO_WINDOW)
    except Exception as e:
        return False, None, f"schtasks error: {e}", 0
    if result.returncode != 0:
        return False, None, (result.stderr or result.stdout or "schtasks returned non-zero").strip(), 0

    # Layer respawn policy (PT5M repetition + restart-on-failure) onto the
    # freshly-created task — best-effort; failure leaves bare /SC ONLOGON.
    _apply_supervisor_respawn_policy()

    procs = _enumerate_research_py_procs()
    daemon_pid = next((pid for pid, _cmd, role in procs if role == "daemon-loop"), None)
    if daemon_pid is not None:
        return True, daemon_pid, "already running", 0

    plain_serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]
    killed_serve_count = 0
    if plain_serve_pids:
        killed_serve_count = _kill_pids(plain_serve_pids)

    # Belt-and-suspenders: gate creationflags on win32 to mirror
    # `run_daemon_loop`'s pattern (research.py:27223-27240) — function is
    # already Windows-only by name + caller chain, but a future refactor
    # that bypasses the dispatcher could otherwise re-introduce the same
    # POSIX ValueError class. 2026-05-18: caught after Linux Track C smoke
    # hit the same anti-pattern in `run_daemon_loop`.
    _DETACHED = (
        getattr(_subprocess, "DETACHED_PROCESS", 0x00000008)
        if sys.platform == "win32" else 0
    )
    _NEWGROUP = (
        getattr(_subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200)
        if sys.platform == "win32" else 0
    )
    # Capture the spawned daemon-loop's raw stdout/stderr to backend.err.log
    # instead of DEVNULL. The daemon-loop reassigns its own stdio to the
    # backend logs once running (research.py ~37695), but a crash in the window
    # BEFORE that — the _sr_core import, a native-extension load, an early
    # dispatch error — would otherwise vanish into DEVNULL, leaving the device
    # silently offline (the exact failure this fixes). Append so we never
    # clobber the daemon's own redirect target.
    # Capture early-boot errors to the SAME relocated log dir the daemon-loop
    # uses (~/.super-research/logs/), so a crash before the daemon's own redirect
    # survives a later `pipx uninstall`.
    _log_dir = _STATE_DIR / "logs"
    try:
        _log_dir.mkdir(parents=True, exist_ok=True)
    except Exception:
        _log_dir = Path(script_path).parent
    try:
        _boot_fh = open(_log_dir / "backend.err.log", "a", encoding="utf-8")
    except Exception:
        _boot_fh = None
    try:
        _subprocess.Popen(
            [python_exe, script_path, "--daemon-loop"],
            creationflags=_DETACHED | _NEWGROUP,
            stdout=(_boot_fh or _subprocess.DEVNULL),
            stderr=(_boot_fh or _subprocess.DEVNULL),
            stdin=_subprocess.DEVNULL,
            close_fds=True,
        )
    except Exception as e:
        if _boot_fh:
            _boot_fh.close()
        return True, None, f"spawn failed: {e}", killed_serve_count

    # Poll up to 30s, not 5s. A freshly pipx-installed COMPILED build has a slow
    # cold start: the daemon-loop imports the heavy native deps (playwright,
    # grpc/firestore, anthropic) before it's detectable, and a first-ever launch
    # also races Windows Defender scanning the just-extracted .pyd files. The old
    # 5s window expired mid-import and wrongly reported "did not appear," leaving
    # On-Startup armed but the device offline. 30s comfortably covers the cold
    # start (a warm --serve reaches Firestore-init in ~7s); we still return the
    # instant a daemon-loop is detected, so a warm start is no slower.
    deadline = _time.time() + 30.0
    while _time.time() < deadline:
        _time.sleep(0.5)
        for pid, _cmd, role in _enumerate_research_py_procs():
            if role == "daemon-loop":
                if _boot_fh:
                    _boot_fh.close()
                return True, pid, "", killed_serve_count
    if _boot_fh:
        _boot_fh.close()
    return True, None, (
        f"daemon-loop did not appear within 30s — check backend.err.log in {_log_dir}"
    ), killed_serve_count


def _disarm_supervisor_quiet() -> "tuple[str, int]":
    """Dispatcher — routes to `_disarm_supervisor_quiet_windows`,
    `_disarm_supervisor_macos`, or `_disarm_supervisor_linux`. Returns
    (status, killed_total) on all platforms."""
    plat = _supervisor_platform()
    if plat == "Windows":
        return _disarm_supervisor_quiet_windows()
    if plat == "Darwin":
        return _disarm_supervisor_macos()
    if plat == "Linux":
        return _disarm_supervisor_linux()
    return "unsupported", 0


def _disarm_supervisor_quiet_windows() -> "tuple[str, int]":
    """Inverse of _arm_supervisor_quiet_windows. Removes the Scheduled Task AND
    kills every daemon-loop + --serve process. No terminal narration —
    callers do their own.

    Shared by the --pair N-branch (enforce "user said unsupervised") and
    any future "reset supervisor" entry point. run_retire / run_unpair
    still inline their own narration-rich versions since their step
    reporting differs.

    Returns (task_info, killed_count):
      • task_info: "removed" | "missing" | "non-Windows" | error string
      • killed_count: number of daemon-loop + serve procs stopped
    """
    import subprocess as _subprocess
    import platform as _platform
    import time as _time

    task_info = "non-Windows"
    if _platform.system() == "Windows":
        cmd = ["schtasks", "/Delete", "/TN", _SUPERVISOR_TASK_NAME, "/F"]
        try:
            result = _subprocess.run(cmd, capture_output=True, text=True, timeout=30,
                                     creationflags=_PS_NO_WINDOW)
            if result.returncode == 0:
                task_info = "removed"
            elif "cannot find the file" in (result.stdout + result.stderr).lower():
                task_info = "missing"
            else:
                task_info = (result.stderr or result.stdout or "non-zero exit").strip()
        except Exception as e:
            task_info = f"schtasks error: {e}"

    self_pid = os.getpid()
    killed_total = 0
    deadline = _time.time() + 8.0
    while True:
        procs = [p for p in _enumerate_research_py_procs() if p[0] != self_pid]
        daemon_pids = [pid for pid, _cmd, role in procs if role == "daemon-loop"]
        serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]
        if not daemon_pids and not serve_pids:
            break
        killed_total += _kill_pids(daemon_pids) + _kill_pids(serve_pids)
        if _time.time() >= deadline:
            break
        _time.sleep(0.5)
    return task_info, killed_total


def run_resurrect():
    """Install a Windows Scheduled Task that launches `python research.py
    --serve` at user logon. Idempotent — re-running overwrites the existing
    task. Prints actionable output on success/failure."""
    import subprocess as _subprocess

    _branded_header("resurgam", _BOLD + _BRIGHT, "the backend rises")

    plat = _supervisor_platform()
    if plat not in ("Windows", "Darwin", "Linux"):
        # Truly unsupported platform (FreeBSD, headless WSL without GUI, etc.).
        print()
        print(f"  {_c(_WARN, '⚠')} Only Windows / macOS / Linux desktop is supported.")
        return

    if plat in ("Darwin", "Linux"):
        # POSIX path — refactored 2026-05-20 from a bare-bones flow into the
        # same 4-step scaffolding as Windows. Removes the "parity-of-mechanism,
        # not parity-of-UX" gap the user flagged during Linux testing. Helpers
        # (`_render_context_strip`, `_setup_step`, `_print_with_flourish`,
        # `_render_next_actions`) were already platform-agnostic; we just call
        # them. Platform-specific install lives in `_arm_supervisor_<plat>`
        # which spawns the daemon-loop inline (vs Windows which spawns it in
        # Step 4 — that asymmetry is intentional, see Step 4 below).
        # NOTE: init_firebase() + _fetch_paired_email() deliberately skipped
        # — see the matching comment in the Windows path below. supervised
        # flag goes through _pair_patch_device (REST), no gRPC dep.
        paired_uid = load_paired_uid()
        device_id = load_device_id()
        # Pull friendly name + owner email from the device doc via REST so
        # the banner shows "VivobookPro" / "Rocky (alice@example.com)"
        # instead of the raw deviceId UUID / uid[:8] prefix. Best-effort —
        # drops back to the raw values on any failure.
        with _sync_spinner_ctx("Reading device info"):
            _meta_b = _fetch_device_meta_rest()
        device_name = (
            (_meta_b.get("name") if isinstance(_meta_b.get("name"), str) else "")
            or (_meta_b.get("hostname") if isinstance(_meta_b.get("hostname"), str) else "")
            or device_id
            or "(not paired)"
        )
        owner_display = _meta_b.get("ownerDisplayName") if isinstance(_meta_b.get("ownerDisplayName"), str) else ""
        owner_email = _meta_b.get("ownerEmail") if isinstance(_meta_b.get("ownerEmail"), str) else ""
        if owner_display and owner_email:
            paired_email = f"{owner_display}  ({owner_email})"
        elif owner_email:
            paired_email = owner_email
        elif paired_uid:
            paired_email = paired_uid[:8] + "…"
        else:
            paired_email = "(not paired)"
        currently_supervised = _detect_supervised()
        _ctx_rows = [
            ("Device",    _c(_BOLD, device_name)),
            ("Paired to", _c(_BOLD, paired_email)),
            ("On Startup", _aegis_rune(currently_supervised, transition_to="on")),
        ]
        _bat = _battery_state()
        if _bat:
            _ctx_rows.append(("Power", _c(_DIM, _bat)))
        _render_context_strip(_ctx_rows)

        # ── [1/4] Pre-flight ──
        _setup_step(1, 4, "Pre-flight")
        if not paired_uid:
            print(f"  {_c(_WARN, '⚠')} Device not paired yet.")
            print(f"  {_c(_DIM, '     Run')} {_c(_BOLD, f'{_PROG} --pair')} {_c(_DIM, 'first, then retry --resurrect.')}")
            return
        print(f"  {_c(_OK, '✓')}  Pairing complete on this machine")
        _seed_env_file_if_missing()

        # ── [2/4] Installing supervisor + auto-spawn ──
        _setup_step(2, 4, f"Installing {_supervisor_artifact_label()}")
        if plat == "Linux" and _is_wsl():
            # F15 of the CLI audit — WSL2's systemd-user requires
            # `systemd=true` in /etc/wsl.conf [boot] (not the default).
            # If that's missing, the unit installs but won't survive
            # `wsl --shutdown`. Warn but don't bail — users with systemd
            # already enabled get exactly what they want.
            print(f"  {_c(_WARN, '⚠')}  WSL detected — systemd-user units need `systemd=true` in /etc/wsl.conf [boot].")
            print(f"  {_c(_DIM, '     If unset: add it, run `wsl --shutdown` from PowerShell, then re-run --resurrect.')}")
        if plat == "Linux" and _check_linger_status() == "no":
            _linger_user = os.environ.get("USER") or os.environ.get("LOGNAME") or "$USER"
            print(f"  {_c(_WARN, '⚠')}  loginctl Linger=no — daemon-loop will die at logout.")
            print(f"  {_c(_DIM, '     Run:')} {_c(_BOLD, f'sudo loginctl enable-linger {_linger_user}')}")
            print(f"  {_c(_DIM, '     (continuing — supervisor still works while logged in)')}")
        if plat == "Darwin":
            with _sync_spinner_ctx("Installing & starting supervisor"):
                ok, daemon_pid, info, killed_serve = _arm_supervisor_macos()
            if not ok:
                print(f"  {_c(_WARN, '⚠')}  launchd install failed: {info}")
                return
            print(f"  {_c(_OK, '✓')}  LaunchAgent installed ({_SUPERVISOR_PLIST_LABEL})")
        else:
            with _sync_spinner_ctx("Installing & starting supervisor"):
                ok, daemon_pid, info, killed_serve = _arm_supervisor_linux()
            if not ok:
                print(f"  {_c(_WARN, '⚠')}  systemctl install failed: {info}")
                return
            print(f"  {_c(_OK, '✓')}  systemd user unit installed ({_SUPERVISOR_UNIT_NAME})")
        if killed_serve:
            _plural_s = "es" if killed_serve != 1 else ""
            print(f"  {_c(_DIM, f'     Stopped {killed_serve} stale --serve process{_plural_s}.')}")

        # ── [3/4] Firestore sync ──
        _setup_step(3, 4, "Firestore sync")
        _write_supervised_flag(True)
        print(f"  {_c(_OK, '✓')}  Synced to the Super Research app")

        # ── [4/4] Handoff — verify daemon-loop is live + API responds ──
        # Asymmetric with Windows: `_arm_supervisor_<plat>` already spawned
        # daemon-loop in Step 2 (launchd/systemd handle the spawn at install
        # time). Here we just confirm the spawn succeeded and that uvicorn
        # bound port 8000. Matches the Windows handoff's "did the daemon
        # actually come up?" verification.
        _setup_step(4, 4, "Handoff")
        _kind = "launchd" if plat == "Darwin" else "systemd"
        _retry_hint = "KeepAlive=true" if plat == "Darwin" else "Restart=always"
        if daemon_pid is not None:
            print(f"  {_c(_OK, '✓')}  Backend started (PID {daemon_pid}, supervised by {_kind})")
        else:
            print(f"  {_c(_WARN, '⚠')}  {info or 'daemon-loop did not appear within 5s'} — {_kind} will retry ({_retry_hint}).")
        # API health probe (matches Windows handoff's _local_api_health call).
        import time as _time_pos
        _api_ok, _api_detail = False, ""
        with _sync_spinner_ctx("Waiting for API"):
            for _hb_attempt in range(24):  # 24 × 1.5s = 36s — covers a compiled multi-worker cold start
                _time_pos.sleep(1.5)
                _api_ok, _api_detail = _local_api_health()
                if _api_ok:
                    break
        if _api_ok:
            print(f"  {_c(_OK, '✓')}  API responding ({_api_detail})")
        else:
            print(f"  {_c(_WARN, '⚠')}  API still warming up: {_api_detail}")
            print(f"  {_c(_DIM, '     A compiled multi-worker start can take a bit — it should come online shortly. Check the app, or curl localhost:8000/api/health.')}")

        # ── Final flourish + next actions (matches Windows path) ──
        print()
        _print_with_flourish(
            f"  {_c(_BOLD + _BRIGHT, '  The supervisor holds watch.')}  "
            f"{_c(_DIM, '--serve respawns on any exit.')}",
            fade_to_color=_BOLD + _ACCENT,
            hold_s=0.3,
        )
        _render_next_actions([
            ("python research.py --retire", "disable On Startup"),
            ("python research.py agent connect", "drive Super Research from chat (Hermes / OpenClaw)"),
        ])
        return

    # Seed `.dg-supervisor.env` from scripts/dg-supervisor.env.example so the
    # user-facing happy path lays down a documented config file at install
    # time. Idempotent — no-op when target exists.
    _seed_env_file_if_missing()

    # pythonw.exe (no-console subsystem) keeps the supervisor invisible at
    # logon — under the `/IT` interactive token, console-mode python.exe
    # would otherwise pop a visible daemon-loop terminal. Falls back to
    # sys.executable if pythonw.exe isn't installed alongside.
    python_exe = _supervisor_python_exe()
    script_path = _launcher_path()
    env_file = _SUPERVISOR_ENV_FILE_DEFAULT_PATH
    # Use the full path to python.exe so the task runs even if PATH isn't set
    # up for the scheduler's session. Quote both to tolerate spaces.
    # Launch the daemon-loop wrapper (not --serve directly) so the backend
    # auto-restarts on any exit — including the os._exit(0) that the Stop
    # button calls for Chromium cleanup. Without this, the scheduled task
    # only fires once per logon and the backend stays dead after Stop.
    # --env-file directs research.py to load .dg-supervisor.env via
    # _load_env_file() before subcommand dispatch (parity with the
    # _arm_supervisor_quiet install path).
    task_run = f'"{python_exe}" "{script_path}" --daemon-loop --env-file "{env_file}"'

    # NOTE: deliberately skip `init_firebase()` + `_fetch_paired_email()` here.
    # The only Firestore-side action --resurrect needs is the supervised:true
    # flag write in step 3, which goes through _pair_patch_device (Firestore
    # REST + bootstrapped idToken — no gRPC client init). Skipping the cold
    # gRPC channel construction shaves ~30-60s off resurrect on Windows.
    paired_uid = load_paired_uid()
    device_id = load_device_id()
    # Pull friendly name + owner email from the device doc via REST so the
    # banner shows "VivobookPro" / "Rocky (alice@example.com)" instead of
    # the raw deviceId UUID / uid[:8] prefix. Best-effort — drops back to
    # the raw values on any failure.
    with _sync_spinner_ctx("Reading device info"):
        _meta_b = _fetch_device_meta_rest()
    device_name = (
        (_meta_b.get("name") if isinstance(_meta_b.get("name"), str) else "")
        or (_meta_b.get("hostname") if isinstance(_meta_b.get("hostname"), str) else "")
        or device_id
        or "(not paired)"
    )
    owner_display = _meta_b.get("ownerDisplayName") if isinstance(_meta_b.get("ownerDisplayName"), str) else ""
    owner_email = _meta_b.get("ownerEmail") if isinstance(_meta_b.get("ownerEmail"), str) else ""
    if owner_display and owner_email:
        paired_email = f"{owner_display}  ({owner_email})"
    elif owner_email:
        paired_email = owner_email
    elif paired_uid:
        paired_email = paired_uid[:8] + "…"
    else:
        paired_email = "(not paired)"
    currently_supervised = _detect_supervised()
    _ctx_rows = [
        ("Device",    _c(_BOLD, device_name)),
        ("Paired to", _c(_BOLD, paired_email)),
        ("On Startup", _aegis_rune(currently_supervised, transition_to="on")),
    ]
    _bat = _battery_state()
    if _bat:
        _ctx_rows.append(("Power", _c(_DIM, _bat)))
    _render_context_strip(_ctx_rows)

    # ── [1/4] Pre-flight ──
    _setup_step(1, 4, "Pre-flight")
    if not paired_uid:
        print(f"  {_c(_WARN, '⚠')} Device not paired yet.")
        print(f"  {_c(_DIM, '     Run')} {_c(_BOLD, 'python research.py --pair')} {_c(_DIM, 'first, then retry --resurrect.')}")
        return
    print(f"  {_c(_OK, '✓')}  Pairing complete on this machine")

    # ── [2/4] Scheduling auto-start ──
    _setup_step(2, 4, "Scheduling auto-start")
    cmd = [
        "schtasks", "/Create",
        "/TN", _SUPERVISOR_TASK_NAME,
        "/TR", task_run,
        "/SC", "ONLOGON",
        "/RL", "LIMITED",       # keep user privileges (Chrome profile access)
        "/IT",                  # interactive — required for Playwright headed mode
        "/F",                   # overwrite existing
    ]
    try:
        with _sync_spinner_ctx("Pinning Scheduled Task"):
            result = _subprocess.run(cmd, capture_output=True, text=True, timeout=30,
                                     creationflags=_PS_NO_WINDOW)
    except Exception as e:
        print(f"  {_c(_WARN, '⚠')}  Failed to run schtasks: {e}")
        return

    if result.returncode != 0:
        print(f"  {_c(_WARN, '⚠')}  schtasks returned non-zero status.")
        if result.stderr.strip():
            print(f"  {_c(_DIM, '     stderr:')}")
            for line in result.stderr.strip().splitlines():
                print(f"       {line}")
        return

    print(f"  {_c(_OK, '✓')}  Scheduled Task pinned to login ({_SUPERVISOR_TASK_NAME})")
    print(f"  {_c(_DIM, '     Executes:')} {task_run}")

    # Layer respawn policy onto the task — PT5M repetition + restart-on-failure.
    with _sync_spinner_ctx("Applying respawn policy"):
        _ok, _msg = _apply_supervisor_respawn_policy()
    if _ok:
        print(f"  {_c(_OK, '✓')}  Respawn policy applied (5-min repetition + restart-on-failure)")
    else:
        print(f"  {_c(_WARN, '⚠')}  Could not apply respawn policy: {_msg}")
        print(f"  {_c(_DIM, '     Backend still spawns at next login as a fallback.')}")

    # ── [3/4] Firestore sync ──
    _setup_step(3, 4, "Firestore sync")
    _write_supervised_flag(True)  # uses _pair_patch_device internally — fast
    print(f"  {_c(_OK, '✓')}  Synced to the Super Research app")

    # ── [4/4] Handoff — activate the supervisor NOW, not at next logon ──
    # Without this, --resurrect only schedules the task and leaves the
    # backend on whatever the user had before. Active supervised mode
    # needs --daemon-loop running so --serve is supervised. Steps:
    #   (a) detect an already-running daemon-loop (re-run = no-op),
    #   (b) taskkill any plain --serve so port 8000 is free for the
    #       supervised child,
    #   (c) spawn --daemon-loop DETACHED + CREATE_NEW_PROCESS_GROUP so
    #       it outlives this call and doesn't inherit our console,
    #   (d) verify the spawn actually worked by re-polling until the
    #       daemon-loop PID appears (so we don't print "started" for
    #       a child that crashed on import).
    _setup_step(4, 4, "Handoff")
    import time as _time
    procs = _enumerate_research_py_procs()
    daemon_pid = next((pid for pid, _cmd, role in procs if role == "daemon-loop"), None)
    plain_serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]

    # Pre-flight orphan visibility: count what's about to be reaped before
    # the daemon-loop starts, so the user sees the sweep working rather
    # than just a silent kill. Same enumeration the daemon-loop wrapper
    # would do; we mirror it here so it's surfaced at install time too.
    _self_pid_r = os.getpid()
    _stale_daemons = [pid for pid, _c, role in procs
                      if role == "daemon-loop" and pid != _self_pid_r]
    _other_procs = [(pid, cmd) for pid, cmd, role in procs if role == "other"]
    if _stale_daemons or plain_serve_pids or _other_procs:
        bits = []
        if _stale_daemons:
            bits.append(f"{len(_stale_daemons)} stale daemon-loop")
        if plain_serve_pids:
            bits.append(f"{len(plain_serve_pids)} stale --serve")
        if _other_procs:
            bits.append(f"{len(_other_procs)} manual one-off run(s) preserved")
        print(f"  {_c(_DIM, '     Pre-flight: ' + ', '.join(bits))}")

    if daemon_pid is not None:
        print(f"  {_c(_OK, '✓')}  Backend already running (PID {daemon_pid}) — nothing to spawn")
    else:
        if plain_serve_pids:
            killed = _kill_pids(plain_serve_pids)
            plural = "es" if killed != 1 else ""
            print(f"  {_c(_DIM, f'     Stopped {killed} running --serve process{plural} to free port 8000.')}")
        # Belt-and-suspenders: even after killing known research.py --serve
        # processes, port 8000 can still be held by:
        #   - a stale --serve that crashed without releasing (rare)
        #   - a different app the user happened to bind there
        #   - a TIME_WAIT socket from a recent --serve exit
        # Without this, daemon-loop will spawn --serve which hits "address
        # already in use" on the first uvicorn bind and crash-loops every
        # 5s. _free_port_8000 catches it once at install time.
        port_squatters = _free_port_8000()
        if port_squatters:
            print(f"  {_c(_DIM, f'     Cleared port 8000 (killed PID(s): {port_squatters})')}")
        # Belt-and-suspenders: gate on win32 (mirrors `run_daemon_loop`'s
        # _NO_WINDOW pattern at research.py:27223-27240). This branch is
        # already only reachable on Windows after the Darwin/Linux early-
        # returns above, but the constants now self-defend against future
        # refactors that bypass the dispatcher. 2026-05-18.
        _DETACHED = (
            getattr(_subprocess, "DETACHED_PROCESS", 0x00000008)
            if sys.platform == "win32" else 0
        )
        _NEWGROUP = (
            getattr(_subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200)
            if sys.platform == "win32" else 0
        )
        try:
            _subprocess.Popen(
                [python_exe, script_path, "--daemon-loop"],
                creationflags=_DETACHED | _NEWGROUP,
                stdout=_subprocess.DEVNULL,
                stderr=_subprocess.DEVNULL,
                stdin=_subprocess.DEVNULL,
                close_fds=True,
            )
        except Exception as e:
            print(f"  {_c(_WARN, '⚠')}  Could not start backend: {e}")
            print(f"  {_c(_DIM, '     The scheduled task still fires at next login.')}")
        else:
            # PID detection is COSMETIC (for the "Backend started PID X" line).
            # 15s window — a freshly pipx-installed COMPILED build cold-starts
            # slowly (heavy native imports + Defender scanning the new .pyd), and
            # under pythonw the daemon-loop can take a moment to surface in wmic.
            spawned_pid = None
            with _sync_spinner_ctx("Starting backend"):
                deadline = _time.time() + 15.0
                while _time.time() < deadline:
                    _time.sleep(0.5)
                    for pid, _cmd, role in _enumerate_research_py_procs():
                        if role == "daemon-loop":
                            spawned_pid = pid
                            break
                    if spawned_pid is not None:
                        break
            if spawned_pid is not None:
                print(f"  {_c(_OK, '✓')}  Backend started (PID {spawned_pid}, running in background)")
            else:
                print(f"  {_c(_DIM, '  Backend launching in the background — checking the API directly…')}")
            # Health probe — the AUTHORITATIVE readiness check, run REGARDLESS of
            # whether we saw the PID. PID detection can miss a slow/pythonw cold
            # start, but a bound API cannot be faked. (Previously this was nested
            # inside `if spawned_pid` with a 5s detect window, so a slow start
            # printed a false "did not appear" + never probed the API — the same
            # offline-symptom class this fix targets.) Daemon-loop must (1) start
            # --serve, (2) Firestore init (~3-5s cold), (3) uvicorn bind.
            _api_ok = False
            _api_detail = ""
            with _SyncSpinnerCtx("Waiting for API"):
                for _hb_attempt in range(24):  # 24 × 1.5s = 36s — covers a compiled multi-worker cold start
                    _time.sleep(1.5)
                    _api_ok, _api_detail = _local_api_health()
                    if _api_ok:
                        break
            if _api_ok:
                print(f"  {_c(_OK, '✓')}  API responding ({_api_detail})")
            else:
                print(f"  {_c(_WARN, '⚠')}  API still warming up: {_api_detail}")
                print(f"  {_c(_DIM, '     A compiled multi-worker start can take a bit — it should come online shortly. Check the app, or curl localhost:8000/api/health.')}")

    print()
    _print_with_flourish(
        f"  {_c(_BOLD + _BRIGHT, '  The supervisor holds watch.')}  "
        f"{_c(_DIM, '--serve respawns on any exit.')}",
        fade_to_color=_BOLD + _ACCENT,
        hold_s=0.3,
    )
    _render_next_actions([
        ("python research.py --retire", "disable On Startup"),
        ("python research.py agent connect", "drive Super Research from chat (Hermes / OpenClaw)"),
    ])


def run_restart():
    """`superresearch --restart` — cycle the running backend onto the code that is
    currently ON DISK. This is the missing step after ANY update route: `--update`,
    a bare `pipx upgrade`, or the superresearch.io installer all replace the
    package, but the live process keeps the old build in memory until restarted.

    Deliberately NOT `--retire` + `--resurrect`: retire REMOVES On Startup (a
    teardown, not a restart), so that pairing left users disabling always-on just to
    pick up an update. This keeps the pin and restarts in place.

    With always-on installed → restart the supervisor (launchctl kickstart -k /
    systemctl --user restart / schtasks /End+/Run). Without it there is nothing
    supervised to cycle, so point at the manual path instead of failing."""
    _branded_header("recursus", _BOLD + _ACCENT, "return · restart Super Research")
    installed = _sr_version()
    running = _running_version()

    if not _supervisor_installed():
        print("  On Startup isn't set up on this machine — nothing supervised to restart.")
        if running:
            print(f"  {_c(_DIM, 'Stop the running backend, then start it again:')}  {_c(_BOLD, _PROG + ' --serve')}")
        else:
            print(f"  {_c(_DIM, 'Start the backend with')}  {_c(_BOLD, _PROG + ' --serve')}"
                  f"  {_c(_DIM, '(or')} {_c(_BOLD, _PROG + ' --resurrect')} {_c(_DIM, 'for always-on).')}")
        print()
        return

    if running and running != installed:
        print(f"  Running  {_c(_DIM, 'v' + running)}  →  installed  {_c(_BOLD + _OK, 'v' + installed)}")
    else:
        print(f"  Restarting the backend  {_c(_DIM, '(v' + installed + ')')}")

    ok, msg = _restart_supervisor()
    if not ok:
        print(f"  {_c(_WARN, '⚠')}  Couldn't restart the supervisor: {msg}")
        print(f"  {_c(_DIM, 'Fallback:')}  {_c(_BOLD, _PROG + ' --retire')}  {_c(_DIM, 'then')}  {_c(_BOLD, _PROG + ' --resurrect')}")
        print()
        return

    print(f"  {_c(_OK, '✓')}  Backend restarted on v{installed}.")
    print(f"  {_c(_DIM, 'It reconnects in a few seconds — the device goes green in the app when it is live.')}")
    print()


def run_retire():
    """Disable On Startup — completely. Idempotent: succeeds whether or not
    the scheduled task and backend are currently running.

    Full-reset semantics: after --retire the machine is back to "nothing
    related to research.py is running in the background". If a pipeline was
    in-flight under the supervised --serve, it aborts — that's the deliberate
    cost of a clean undo. Re-run --serve yourself to bring the backend back,
    or --resurrect to re-enable On Startup.

    Three-step reset:
      1. Delete the Windows Scheduled Task so daemon-loop won't auto-start
         at next login.
      2. Kill every running daemon-loop AND every --serve process, looping
         for up to 8s so a mid-enumeration respawn (daemon-loop spawns
         --serve every ~5s between deaths) still gets caught.
      3. Flip the Firestore On Startup flag to off + verify stragglers."""
    import subprocess as _subprocess

    _branded_header("requiescat", _BOLD + _RED, "let the loop rest")

    plat = _supervisor_platform()
    if plat not in ("Windows", "Darwin", "Linux"):
        # Truly unsupported platform (FreeBSD, headless WSL without GUI, etc.).
        print()
        print(f"  {_c(_WARN, '⚠')} Only Windows / macOS / Linux desktop is supported.")
        return

    if plat in ("Darwin", "Linux"):
        # POSIX path — refactored 2026-05-20 to match the Windows 3-step
        # scaffolding (Context strip → [1/3] Unbinding → [2/3] Stopping →
        # [3/3] Firestore sync → flourish + next-actions). Closes the
        # "Polish deferred" gap so --retire reads the same on every OS.
        # NOTE: init_firebase + _fetch_paired_email skipped — supervised
        # flag goes via _write_supervised_flag → _pair_patch_device REST.
        paired_uid = load_paired_uid()
        device_id = load_device_id()
        # Pull friendly name + owner email from the device doc via REST so
        # the banner shows "VivobookPro" / "Rocky (alice@example.com)"
        # instead of the raw deviceId UUID / uid[:8] prefix. Best-effort —
        # drops back to the raw values on any failure.
        with _sync_spinner_ctx("Reading device info"):
            _meta_b = _fetch_device_meta_rest()
        device_name = (
            (_meta_b.get("name") if isinstance(_meta_b.get("name"), str) else "")
            or (_meta_b.get("hostname") if isinstance(_meta_b.get("hostname"), str) else "")
            or device_id
            or "(not paired)"
        )
        owner_display = _meta_b.get("ownerDisplayName") if isinstance(_meta_b.get("ownerDisplayName"), str) else ""
        owner_email = _meta_b.get("ownerEmail") if isinstance(_meta_b.get("ownerEmail"), str) else ""
        if owner_display and owner_email:
            paired_email = f"{owner_display}  ({owner_email})"
        elif owner_email:
            paired_email = owner_email
        elif paired_uid:
            paired_email = paired_uid[:8] + "…"
        else:
            paired_email = "(not paired)"
        currently_supervised = _detect_supervised()

        _ctx_rows = [
            ("Device",     _c(_BOLD, device_name)),
            ("Paired to",  _c(_BOLD, paired_email)),
            ("On Startup", _aegis_rune(currently_supervised, transition_to="nothing-to-undo")),
        ]
        _bat = _battery_state()
        if _bat:
            _ctx_rows.append(("Power", _c(_DIM, _bat)))
        _render_context_strip(_ctx_rows)

        # Short-circuit: nothing armed AND nothing running → no-op (mirrors
        # the Windows branch). Avoids three separate "nothing to do" lines.
        self_pid = os.getpid()
        running_now = any(
            role in ("daemon-loop", "serve")
            for pid, _cmd, role in _enumerate_research_py_procs()
            if pid != self_pid
        )
        if not currently_supervised and not running_now:
            print()
            print(f"  {_c(_DIM, 'Nothing to retire — On Startup is already off and no backend is running.')}")
            _render_next_actions([
                ("python research.py --resurrect", "enable On Startup"),
            ])
            return

        # ── [1/3] Unbinding schedule ──
        _setup_step(1, 3, "Unbinding schedule")
        if plat == "Darwin":
            with _sync_spinner_ctx("Unbinding supervisor & stopping backend"):
                status, killed_during_disarm = _disarm_supervisor_macos()
            if status == "removed":
                print(f"  {_c(_OK, '✓')}  LaunchAgent removed ({_SUPERVISOR_PLIST_LABEL})")
            elif status == "no-task":
                print(f"  {_c(_DIM, '     Nothing bound — LaunchAgent was not installed.')}")
            else:
                print(f"  {_c(_WARN, '⚠')}  bootout returned: {status}")
        else:
            with _sync_spinner_ctx("Unbinding supervisor & stopping backend"):
                status, killed_during_disarm = _disarm_supervisor_linux()
            if status == "removed":
                print(f"  {_c(_OK, '✓')}  systemd user unit removed ({_SUPERVISOR_UNIT_NAME})")
            elif status == "no-task":
                print(f"  {_c(_DIM, '     Nothing bound — systemd unit was not installed.')}")
            else:
                print(f"  {_c(_WARN, '⚠')}  systemctl disable returned: {status}")

        # ── [2/3] Stopping backend ──
        _setup_step(2, 3, "Stopping backend")
        if killed_during_disarm:
            _plural = "es" if killed_during_disarm != 1 else ""
            print(f"  {_c(_OK, '✓')}  Stopped {killed_during_disarm} process{_plural}")
        else:
            print(f"  {_c(_DIM, '     No daemon-loop / --serve processes were running.')}")

        # ── [3/3] Firestore sync ──
        _setup_step(3, 3, "Firestore sync")
        _write_supervised_flag(False)
        print(f"  {_c(_OK, '✓')}  Synced to the Super Research app")

        # ── Final flourish + next actions (matches Windows path) ──
        print()
        _print_with_flourish(
            f"  {_c(_BOLD + _RED, '  Silence.')}  "
            f"{_c(_DIM, 'No research.py process remains.')}",
            fade_to_color=_DIM + _RED,
            hold_s=0.5,
        )
        _render_next_actions([
            ("python research.py --resurrect", "re-enable On Startup"),
        ])
        return

    # Context strip — what's about to get torn down. Skip init_firebase
    # + email fetch; supervised flag goes via _write_supervised_flag →
    # _pair_patch_device REST.
    paired_uid = load_paired_uid()
    device_id = load_device_id()
    # Pull friendly name + owner email from the device doc via REST so the
    # banner shows "VivobookPro" / "Rocky (alice@example.com)" instead of
    # the raw deviceId UUID / uid[:8] prefix. Best-effort — drops back to
    # the raw values on any failure.
    with _sync_spinner_ctx("Reading device info"):
        _meta_b = _fetch_device_meta_rest()
    device_name = (
        (_meta_b.get("name") if isinstance(_meta_b.get("name"), str) else "")
        or (_meta_b.get("hostname") if isinstance(_meta_b.get("hostname"), str) else "")
        or device_id
        or "(not paired)"
    )
    owner_display = _meta_b.get("ownerDisplayName") if isinstance(_meta_b.get("ownerDisplayName"), str) else ""
    owner_email = _meta_b.get("ownerEmail") if isinstance(_meta_b.get("ownerEmail"), str) else ""
    if owner_display and owner_email:
        paired_email = f"{owner_display}  ({owner_email})"
    elif owner_email:
        paired_email = owner_email
    elif paired_uid:
        paired_email = paired_uid[:8] + "…"
    else:
        paired_email = "(not paired)"
    currently_supervised = _detect_supervised()
    _ctx_rows_r = [
        ("Device",     _c(_BOLD, device_name)),
        ("Paired to",  _c(_BOLD, paired_email)),
        ("On Startup", _aegis_rune(currently_supervised, transition_to="nothing-to-undo")),
    ]
    _bat_r = _battery_state()
    if _bat_r:
        _ctx_rows_r.append(("Power", _c(_DIM, _bat_r)))
    _render_context_strip(_ctx_rows_r)

    # Short-circuit: if nothing is armed and nothing is running, there's
    # nothing to retire. Walking through all 3 steps just to print "Nothing
    # bound / No processes running" 3 times is noise — tell the user directly.
    import time as _time
    self_pid = os.getpid()
    running_now = any(role in ("daemon-loop", "serve")
                      for pid, _cmd, role in _enumerate_research_py_procs()
                      if pid != self_pid)
    if not currently_supervised and not running_now:
        print()
        print(f"  {_c(_DIM, 'Nothing to retire — On Startup is already off and no backend is running.')}")
        _render_next_actions([
            ("python research.py --resurrect", "enable On Startup"),
        ])
        return

    # ── [1/3] Unbinding schedule ──
    _setup_step(1, 3, "Unbinding schedule")
    cmd = [
        "schtasks", "/Delete",
        "/TN", _SUPERVISOR_TASK_NAME,
        "/F",
    ]
    try:
        with _sync_spinner_ctx("Removing Scheduled Task"):
            result = _subprocess.run(cmd, capture_output=True, text=True, timeout=30,
                                     creationflags=_PS_NO_WINDOW)
    except Exception as e:
        print(f"  {_c(_WARN, '⚠')}  Failed to run schtasks: {e}")
        return

    # Exit code 1 with a "does not exist" message means the task wasn't
    # installed to begin with — that's fine, we still clear the flag.
    not_installed = (
        result.returncode != 0
        and "ERROR: The system cannot find the file specified." in (result.stdout + result.stderr)
    )
    if result.returncode == 0:
        print(f"  {_c(_OK, '✓')}  Scheduled Task removed ({_SUPERVISOR_TASK_NAME})")
    elif not_installed:
        print(f"  {_c(_DIM, '     Nothing bound — task was not installed.')}")
    else:
        print(f"  {_c(_WARN, '⚠')}  schtasks returned non-zero status.")
        if result.stderr.strip():
            print(f"  {_c(_DIM, '     stderr:')}")
            for line in result.stderr.strip().splitlines():
                print(f"       {line}")

    # ── [2/3] Stopping backend ──
    # The daemon-loop respawns --serve every ~5s between deaths, so a
    # single-shot enumerate+kill misses any --serve that happened to be
    # respawning at the wrong moment. Loop for up to 8s, re-enumerating
    # each tick. Always kill daemon-loop first so it can't respawn a
    # freshly-killed --serve. `self_pid` is excluded in case --retire
    # was itself launched through the supervisor.
    _setup_step(2, 3, "Stopping backend")
    killed_daemon_total = 0
    killed_serve_total = 0
    deadline = _time.time() + 8.0
    last_survivors: list[tuple[int, str, str]] = []
    with _sync_spinner_ctx("Stopping backend — waiting for processes to exit"):
        while True:
            procs = [p for p in _enumerate_research_py_procs() if p[0] != self_pid]
            daemon_pids = [pid for pid, _cmd, role in procs if role == "daemon-loop"]
            serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]
            if not daemon_pids and not serve_pids:
                last_survivors = procs  # only 'other' left, which we don't touch
                break
            killed_daemon_total += _kill_pids(daemon_pids)
            killed_serve_total += _kill_pids(serve_pids)
            if _time.time() >= deadline:
                last_survivors = [p for p in _enumerate_research_py_procs() if p[0] != self_pid]
                break
            _time.sleep(0.5)

    if killed_daemon_total:
        plural = "es" if killed_daemon_total != 1 else ""
        print(f"  {_c(_OK, '✓')}  Stopped {killed_daemon_total} daemon-loop process{plural}")
    else:
        print(f"  {_c(_DIM, '     No daemon-loop processes were running.')}")
    if killed_serve_total:
        plural = "s" if killed_serve_total != 1 else ""
        print(f"  {_c(_OK, '✓')}  Stopped {killed_serve_total} --serve process{plural}")
    else:
        print(f"  {_c(_DIM, '     No --serve processes were running.')}")

    # Manual one-off runs (role="other") are NOT killed by --retire — those
    # are user-launched `python research.py "<topic>"` invocations. Surface
    # them so the user knows what's still alive on their box.
    other_procs = [(pid, cmd) for pid, cmd, role in last_survivors if role == "other"]
    if other_procs:
        plural = "s" if len(other_procs) != 1 else ""
        print(f"  {_c(_DIM, f'     Preserved {len(other_procs)} manual run{plural} (not touched by --retire):')}")
        for pid, cmd in other_procs[:3]:
            age = _proc_age_seconds(pid)
            age_s = f"{int(age/3600)}h" if (age and age >= 3600) else (f"{int(age/60)}m" if age else "?")
            cmd_short = cmd.split('research.py', 1)[-1][:60] if 'research.py' in cmd else cmd[:60]
            print(f"       {_c(_DIM, f'PID {pid}  age {age_s}  research.py{cmd_short}')}")
        if len(other_procs) > 3:
            print(f"       {_c(_DIM, f'... and {len(other_procs) - 3} more')}")
        print(f"       {_c(_DIM, f'Stop manually with: {_kill_pid_hint()}')}")

    # ── [3/3] Firestore sync + verification ──
    _setup_step(3, 3, "Firestore sync")
    _write_supervised_flag(False)
    print(f"  {_c(_OK, '✓')}  Synced to the Super Research app")

    stragglers = [(pid, role) for pid, _cmd, role in last_survivors if role in ("daemon-loop", "serve")]
    print()
    if stragglers:
        print(f"  {_c(_WARN, '⚠')}  {len(stragglers)} related process(es) would not terminate:")
        for pid, role in stragglers:
            print(f"       {_c(_BOLD, f'PID {pid}')}  ({role})")
        print(f"  {_c(_DIM, f'       Kill them from {_process_manager_label()} or re-run --retire.')}")
    else:
        _print_with_flourish(
            f"  {_c(_BOLD + _RED, '  Silence.')}  "
            f"{_c(_DIM, 'No research.py process remains.')}",
            fade_to_color=_DIM + _RED,
            hold_s=0.5,
        )
    _render_next_actions([
        ("python research.py --resurrect", "re-enable On Startup"),
    ])


def run_unpair(deep: bool = False):
    """Fully disconnect this machine from Super Research — opposite of --pair.

    Semantics: after --unpair, this PC appears nowhere in the Super
    Research app. The device doc is deleted via the unpair-self Cloud
    Function call, local pairing config + OS-keystore refresh token
    are wiped, the scheduled-task supervisor (if any) is removed, and
    every daemon-loop / --serve process owned by this user is killed.
    A subsequent --pair starts fresh — there's no quiet "rejoin" path
    that resurrects the old identity.

    Preserved by default (delete manually for a truly clean machine):
      • Chrome profile(s) at ~/.super-research/browser-profile*/ (your logins)
      • Pipeline history in queues/

    With `deep=True` (CLI: `--unpair --deep`), ALSO wipes:
      • All ~/.super-research/browser-profile*/ dirs (fresh browsers
        on next --pair) + workerCount reset to 1.
      • Pair-time API keys (ANTHROPIC_API_KEY and GEMINI_API_KEY,
        plus the retired legacy aliases CUA_API_KEY and GOOGLE_API_KEY
        in case any survived the startup migration) from Windows
        User-scope env (HKCU) or `.dg-supervisor.env` on POSIX, plus the current
        process's os.environ + _RESOLVED_KEY_CACHE — so the next
        --pair Stage 3 actually re-prompts and re-verifies instead
        of short-circuiting on a leftover key.
      • Transient multi-worker state files at queues/ root
        (`.worker.*.lock` and `_pending_queue*.json`, including
        their `.tmp` siblings). Per-run history dirs (research
        outputs) under queues/ are still preserved. The wiped
        files are auto-recreated by the next worker's first job
        pickup, so a same-account re-pair sees a clean slate
        without losing research history.
    Use this when re-pairing to a different account or when the
    multi-account safety check refuses pair due to stale Google auth.

    Five-step reset (order matters):
      0. Pre-step: while keystore is still alive, mint an ID token and
         POST /api/devices/unpair-self so the FE drops the device tile
         instantly across every browser.
      1. Wipe local research_config.json + OS-keystore refresh token
         + zero in-memory caches. A respawned --serve now reads empty
         state and the heartbeat loop bails on its missing-deviceId
         guard.
      2. Remove the supervisor artifact; kill every daemon-loop +
         --serve process.
      3. Confirm the server-side retire (or fall back to FE Unlink for
         pre-cutover devices the BE can't reach).
      4. Local artifacts summary.
      5. Verify no related process survived."""
    import subprocess as _subprocess
    import time as _time

    _branded_header("absolvo", _BOLD + _ACCENT, "the bond dissolves")

    # Load context BEFORE we nuke local state — the load_* helpers read
    # research_config.json, which step 4 deletes. NOTE: we deliberately
    # skip `init_firebase()` here — the only Firestore operation unpair
    # needs is the retire POST below, which authenticates with an
    # idToken minted via `_fresh_user_mode_id_token()` (its own
    # creds.refresh, no Firestore client init required). Skipping the
    # cold gRPC channel construction shaves ~10-15s off the user-facing
    # unpair wall-clock on Windows.
    paired_uid = load_paired_uid()
    device_id = load_device_id()
    paired_email = ""  # cosmetic only — banner falls back to uid[:8]

    # Bug C extension (2026-05-22): sweep stale research docs before
    # the device doc gets deleted. Without this, runs that were
    # ongoing/queued/paused_backend_restart on this device persist
    # under the owner's tree with no device link (cloud function
    # deletes the device doc but doesn't cascade-update research
    # docs), leaving zombie chat tiles the owner can't Resume.
    # Mirror of the HARD_RESET sweep — same helper, different
    # stopped_by/summary labels for audit-trail differentiation.
    #
    # Cost: ~10-15s wall-clock for init_firebase() on Windows (the
    # bypass-init optimization is intentionally reverted here for
    # correctness — a clean-state guarantee outweighs the wall-clock
    # for a once-per-device-lifetime operation).
    if paired_uid and device_id:
        with _sync_spinner_ctx("Removing this device's runs from your account"):
            try:
                init_firebase()
                global _firebase_db
                if _firebase_db:
                    _swp_n, _swp_f = _sweep_stuck_research_docs_for_device(
                        _firebase_db, paired_uid, device_id,
                        stopped_by="unpair_sweep",
                        summary="Cancelled by Unpair",
                    )
                    if _swp_n or _swp_f:
                        log(f"[unpair] Firestore sweep marked {_swp_n} stale run(s) as stopped ({_swp_f} failed) — owner + sharer trees", "INFO")
                    else:
                        log("[unpair] Firestore sweep — no stale runs found (owner + sharers)", "DEBUG")
                else:
                    log("[unpair] skipping Firestore sweep — init_firebase did not produce a client", "WARN")
            except Exception as _sw_err:
                log(f"[unpair] Firestore sweep failed (continuing): {_sw_err}", "WARN")

    # Best-effort server-side retire BEFORE we wipe the keystore. The
    # endpoint deletes the top-level devices/{deviceId} doc + revokes
    # the synth-device-user's refresh tokens, so the FE listenToDevices
    # subscription drops the tile across every browser instantly. Once
    # we wipe the keystore in step 1 we lose the ability to mint an ID
    # token, so this MUST run first. Non-fatal if it fails — the local
    # wipe still happens and the FE Unlink button is the fallback.
    _retire_action = None
    if device_id:
        with _sync_spinner_ctx("Releasing this device from the server"):
            try:
                import requests as _requests
                from auth.v2_flow import FE_BASE_URL as _FE_BASE_URL
                _id_token = _fresh_user_mode_id_token()
                if _id_token:
                    _resp = _requests.post(
                        f"{_FE_BASE_URL}/api/devices/unpair-self",
                        headers={"Authorization": f"Bearer {_id_token}"},
                        json={"deviceId": device_id},
                        timeout=15,
                    )
                    if _resp.status_code == 200:
                        try:
                            _retire_action = (_resp.json() or {}).get("action")
                        except Exception:
                            _retire_action = "retired"
                    else:
                        log(
                            f"[unpair] retire endpoint HTTP {_resp.status_code}: {_resp.text[:200]}",
                            "WARN",
                        )
            except Exception as _re:
                log(f"[unpair] retire endpoint failed (continuing): {_re}", "WARN")

    # NOTE: no "nothing to do" short-circuit here even when local config is
    # missing. A prior --unpair (or manual config wipe) can leave orphan
    # daemon-loop + serve processes and a scheduled task behind — those are
    # the root cause of the "paired-but-serve-crash-looping" state. We want
    # --unpair to ALWAYS run step 1 (process kill + schtasks removal) so
    # re-running it is a guaranteed-clean cleanup. Steps 2-4 already no-op
    # gracefully when the relevant state is missing.

    # Context strip — what's about to vanish.
    _render_context_strip([
        ("Device",    _c(_BOLD, device_id or "(unknown)")),
        ("Paired to", _c(_BOLD, paired_email)),
    ])

    total = 5

    # ── [1/5] Wipe local config FIRST ──
    # Ordering: research_config.json + keystore disappear BEFORE we
    # kill processes. A daemon-loop respawns --serve on a 5s loop; if
    # processes were killed first, a freshly-spawned --serve could
    # read still-valid config and re-attach to Firestore. Wiping config
    # first means any respawned --serve reads empty state and the
    # heartbeat loop bails on its missing-deviceId guard before any
    # external writes happen.
    _setup_step(1, total, "Wiping local pairing config")
    wiped = []
    try:
        if RESEARCH_CONFIG_PATH.exists():
            RESEARCH_CONFIG_PATH.unlink()
            wiped.append(RESEARCH_CONFIG_PATH.name)
    except Exception as e:
        print(f"  {_c(_WARN, '⚠')}  Could not delete {RESEARCH_CONFIG_PATH.name}: {e}")
    try:
        if _LEGACY_PIPE_CONFIG_PATH.exists():
            _LEGACY_PIPE_CONFIG_PATH.unlink()
            wiped.append(_LEGACY_PIPE_CONFIG_PATH.name)
    except Exception:
        pass
    # Clear the OS keystore so the refresh token can't re-auth this BE.
    try:
        from auth import keystore as _ks
        _ks.clear_all(_ks.install_uuid(), reason="unpair")
        wiped.append("OS keystore")
    except Exception as _ke:
        print(f"  {_c(_WARN, '⚠')}  Keystore clear failed: {_ke}")
    # Zero in-memory state too, so anything still running in this process
    # can't re-read pre-wipe values from the global caches.
    global _device_id, _device_paired_uid
    _device_id = None
    _device_paired_uid = None
    if wiped:
        print(f"  {_c(_OK, '✓')}  Deleted: {', '.join(wiped)}")
    else:
        print(f"  {_c(_DIM, '     No local config files to wipe.')}")

    # ── [2/5] Stop supervisor + serve ──
    _setup_step(2, total, "Stopping running processes")
    plat = _supervisor_platform()
    if plat == "Windows":
        cmd = ["schtasks", "/Delete", "/TN", _SUPERVISOR_TASK_NAME, "/F"]
        try:
            result = _subprocess.run(cmd, capture_output=True, text=True, timeout=30,
                                     creationflags=_PS_NO_WINDOW)
            if result.returncode == 0:
                print(f"  {_c(_OK, '✓')}  Scheduled Task removed ({_SUPERVISOR_TASK_NAME})")
            elif "cannot find the file" in (result.stdout + result.stderr):
                print(f"  {_c(_DIM, '     No scheduled task was installed.')}")
            else:
                print(f"  {_c(_WARN, '⚠')}  schtasks returned non-zero — continuing.")
        except Exception as e:
            print(f"  {_c(_WARN, '⚠')}  schtasks error (continuing): {e}")
    elif plat == "Darwin":
        # launchctl bootout + plist removal. The subsequent kill loop
        # below handles process termination cross-platform via dispatchers.
        if os.geteuid() == 0:
            print(f"  {_c(_WARN, '⚠')}  Refusing under sudo — user agent must be in your own home.")
        else:
            uid = os.getuid()
            label = f"gui/{uid}/{_SUPERVISOR_PLIST_LABEL}"
            try:
                r = _subprocess.run(["launchctl", "bootout", label],
                                    capture_output=True, text=True, timeout=10)
                if r.returncode == 0:
                    print(f"  {_c(_OK, '✓')}  LaunchAgent removed ({_SUPERVISOR_PLIST_LABEL})")
                elif "could not find" in (r.stderr or "").lower() or "no such" in (r.stderr or "").lower():
                    print(f"  {_c(_DIM, '     No LaunchAgent was installed.')}")
                else:
                    print(f"  {_c(_WARN, '⚠')}  bootout: {(r.stderr or r.stdout).strip()[:80]}")
            except Exception as e:
                print(f"  {_c(_WARN, '⚠')}  bootout exception: {e}")
            try:
                if _SUPERVISOR_PLIST_PATH.exists():
                    _SUPERVISOR_PLIST_PATH.unlink()
            except Exception:
                pass
    elif plat == "Linux":
        # systemctl --user disable --now + unit unlink. Kill loop below
        # handles process termination cross-platform via dispatchers.
        if os.geteuid() == 0:
            print(f"  {_c(_WARN, '⚠')}  Refusing under sudo — user unit must be in your own home.")
        else:
            try:
                r = _subprocess.run(["systemctl", "--user", "disable", "--now", _SUPERVISOR_UNIT_NAME],
                                    capture_output=True, text=True, timeout=15)
                if r.returncode == 0:
                    print(f"  {_c(_OK, '✓')}  systemd unit removed ({_SUPERVISOR_UNIT_NAME})")
                else:
                    combined = ((r.stderr or "") + (r.stdout or "")).lower()
                    if "does not exist" in combined or "no such" in combined or "not loaded" in combined:
                        print(f"  {_c(_DIM, '     No systemd unit was installed.')}")
                    else:
                        print(f"  {_c(_WARN, '⚠')}  systemctl disable: {(r.stderr or r.stdout).strip()[:80]}")
            except Exception as e:
                print(f"  {_c(_WARN, '⚠')}  systemctl exception: {e}")
            try:
                if _SUPERVISOR_UNIT_PATH.exists():
                    _SUPERVISOR_UNIT_PATH.unlink()
            except Exception:
                pass
            try:
                _subprocess.run(["systemctl", "--user", "daemon-reload"],
                                capture_output=True, text=True, timeout=10)
            except Exception:
                pass

    # Loop-until-clean pattern so a daemon-loop mid-respawn of --serve
    # still gets fully caught.
    self_pid = os.getpid()
    killed_total = 0
    deadline = _time.time() + 8.0
    with _sync_spinner_ctx("Stopping backend — waiting for processes to exit"):
        while True:
            procs = [p for p in _enumerate_research_py_procs() if p[0] != self_pid]
            daemon_pids = [pid for pid, _cmd, role in procs if role == "daemon-loop"]
            serve_pids = [pid for pid, _cmd, role in procs if role == "serve"]
            if not daemon_pids and not serve_pids:
                break
            killed_total += _kill_pids(daemon_pids) + _kill_pids(serve_pids)
            if _time.time() >= deadline:
                break
            _time.sleep(0.5)
    if killed_total:
        plural = "es" if killed_total != 1 else ""
        print(f"  {_c(_OK, '✓')}  Stopped {killed_total} backend process{plural}")
    else:
        print(f"  {_c(_DIM, '     No backend processes were running.')}")

    # ── [3/5] Confirm the server-side retire that ran before step 1 ──
    _setup_step(3, total, "Removing device from your account")
    if _retire_action == "retired":
        print(f"  {_c(_OK, '✓')}  Deleted devices/{device_id} on the server.")
        print(f"  {_c(_DIM, '     The device tile will disappear from all browsers immediately.')}")
    elif _retire_action == "left-shared":
        print(f"  {_c(_OK, '✓')}  Removed your account from the device's shared list.")
    elif device_id:
        print(f"  {_c(_WARN, '⚠')}  Server-side retire didn't complete — the device tile may stick around.")
        print(f"  {_c(_DIM, '     If it does, tap Unlink on the tile in your Account page.')}")
    else:
        print(f"  {_c(_DIM, '     No paired modern device on this machine — nothing to remove server-side.')}")
    # Pre-cutover devices live at users/{uid}/devices/{deviceId} — the
    # synth-device-user BE can't delete them, and the unpair-self
    # endpoint only handles top-level devices. The FE Account page
    # surfaces an Unlink button on those legacy tiles for owner-side
    # cleanup; mention it so the user knows.
    print(f"  {_c(_DIM, '     Pre-cutover devices: tap Unlink on the tile in your Account page.')}")

    # ── [4/5] Local pairing artifacts ──
    _setup_step(4, total, "Local pairing artifacts")
    print(f"  {_c(_OK, '✓')}  Local config wiped (step 1) + keystore cleared.")

    # Deep cleanup: also wipe pair-time API keys. Lives in Step 4 because
    # API keys are conceptually "local pairing artifacts" — they're
    # persisted by --pair Stage 3 and live in the same axis as the
    # config + keystore. _save_api_key_local writes to Windows User-
    # scope env (HKCU) on Windows and to .dg-supervisor.env on POSIX.
    # Default --unpair leaves these in place so a re-pair on the same
    # machine skips re-pasting (Stage 3 short-circuits via
    # resolve_api_key/resolve_gemini_api_key "already configured").
    # --deep is the "I want a truly fresh slate" path — wipe the
    # persisted keys too so the next --pair Stage 3 fires the paste-
    # and-verify loop end-to-end.
    #
    # We also pop from os.environ in this process so an immediate
    # --pair launched in the SAME shell session (rare but happens
    # during development / E2E testing) doesn't inherit the stale keys
    # via the shell env fallback (resolver rank 5/6).
    api_keys_cleared = 0
    if deep:
        api_key_names = (
            "ANTHROPIC_API_KEY",
            "CUA_API_KEY",
            "GEMINI_API_KEY",
            "GOOGLE_API_KEY",
        )
        for _name in api_key_names:
            try:
                if _clear_api_key_local(_name):
                    api_keys_cleared += 1
            except Exception as _ke:
                log(f"API key clear failed for {_name}: {_ke}", "WARN")
            # Strip from current process too. shell-inherited env on
            # POSIX or pythonw inheritance on Windows can both stash a
            # stale value that would re-resolve in a same-shell --pair.
            os.environ.pop(_name, None)
        # Bust the hot-path key cache so any in-process resolver
        # (shouldn't be any, but defense in depth) sees the cleared
        # state immediately on next call.
        try:
            _RESOLVED_KEY_CACHE.update(key=None, ts=0.0)
        except Exception:
            pass
    api_keys_wiped = api_keys_cleared > 0
    if api_keys_wiped:
        print(f"  {_c(_OK, '✓')}  Pair-time API keys cleared (`--deep`) — Stage 3 will re-prompt and re-verify on next --pair.")

    # 2026-05-26: also wipe queues/ runtime-state files under --deep.
    # Per-run history dirs are intentionally preserved (the rest of
    # queues/ is "research history" per the docstring); only the
    # transient multi-worker state files at the root get cleaned —
    # they're rehydrated lazily on the next worker's first job
    # pickup (_write_worker_lock auto-creates the dir + lock,
    # _persist_pending_queue tmp+replaces the snapshot). Stale ones
    # surviving a cross-account re-pair cause the new BE to try
    # reprocessing the prior pair's jobs under a uid that doesn't
    # own them (Firestore 403 noise) and the worker-lock sibling-
    # claim scanner to see dead-PID locks (handled by the PID-
    # liveness guard but still ugly). Globs at queues/ root only
    # — never per-run subdirs, never README.md.
    queue_state_wiped = 0
    if deep:
        try:
            queues_root = Path(__file__).parent / "queues"
            if queues_root.exists():
                _patterns = (
                    ".worker.*.lock",
                    ".worker.*.lock.tmp",
                    "_pending_queue.json",
                    "_pending_queue_worker_*.json",
                    "_pending_queue.json.tmp",
                    "_pending_queue_worker_*.json.tmp",
                )
                for _pat in _patterns:
                    for _stale in queues_root.glob(_pat):
                        try:
                            _stale.unlink()
                            queue_state_wiped += 1
                        except Exception as _qse:
                            log(
                                f"[unpair] queue-state wipe failed for {_stale.name}: {_qse}",
                                "DEBUG",
                            )
        except Exception as _qe:
            log(f"[unpair] queue-state wipe pass failed (continuing): {_qe}", "WARN")
    if queue_state_wiped:
        _plural = "s" if queue_state_wiped != 1 else ""
        print(f"  {_c(_OK, '✓')}  Cleared {queue_state_wiped} stale worker-state file{_plural} from queues/ (`--deep`).")

    # ── [5/5] Verify ──
    _setup_step(5, total, "Confirming silence")
    stragglers = [p for p in _enumerate_research_py_procs()
                  if p[0] != self_pid and p[2] in ("daemon-loop", "serve")]
    if stragglers:
        print(f"  {_c(_WARN, '⚠')}  {len(stragglers)} related process(es) would not terminate:")
        for pid, _cmd, role in stragglers:
            print(f"       {_c(_BOLD, f'PID {pid}')}  ({role})")
        print(f"  {_c(_DIM, f'       Kill them from {_process_manager_label()} or re-run --unpair.')}")
    else:
        print(f"  {_c(_OK, '✓')}  No research.py process remains")

    # Deep cleanup: also wipe ALL Playwright browser profiles if --unpair
    # --deep was passed. Default --unpair preserves the profiles so a
    # re-pair on the same account doesn't force the user back through
    # ChatGPT/Gemini/Claude/NotebookLM logins. --deep is for the explicit
    # "I want a fresh browser, e.g. switching accounts" case + the F4
    # cookie-refusal recovery path.
    #
    # 2026-05-21: multi-profile aware. Globs ~/.super-research/browser-profile*
    # so profile-1 (legacy `browser-profile/`) AND any profile-N dirs
    # (`browser-profile-2/`, `browser-profile-3/`, …) all get wiped in one
    # pass. Without this, a re-pair after --unpair --deep would see stale
    # cookies in profile-2+ and the new pair's Stage 4 multi-profile loop
    # would inherit them. workerCount is also reset to 1 so the post-deep
    # state matches a fresh-install baseline.
    browser_wiped_count = 0
    if deep:
        try:
            import shutil as _shutil
            profile_root = PROFILE_DIR.parent  # ~/.super-research
            wiped_names: list[str] = []
            survived_names: list[str] = []
            if profile_root.exists():
                for sub in profile_root.iterdir():
                    # Match exactly `browser-profile` and `browser-profile-{N}`,
                    # not arbitrary `browser-profile_backup` or similar.
                    if not sub.is_dir():
                        continue
                    name = sub.name
                    if name != "browser-profile" and not (
                        name.startswith("browser-profile-")
                        and name[len("browser-profile-"):].isdigit()
                    ):
                        continue
                    try:
                        _shutil.rmtree(str(sub), ignore_errors=True)
                    except Exception as _sub_err:
                        log(f"Browser profile wipe failed for {name}: {_sub_err}", "WARN")
                        survived_names.append(name)
                        continue
                    if sub.exists():
                        survived_names.append(name)
                        log(f"Browser profile wipe partial — some files survived at {sub}", "WARN")
                    else:
                        wiped_names.append(name)
                        log(f"Browser profile wiped: {sub}", "INFO")
            browser_wiped_count = len(wiped_names)
            if browser_wiped_count:
                # Reset worker capacity to fresh-install baseline. Next pair's
                # Stage 4 multi-profile loop will re-establish whatever count
                # the user wants.
                try:
                    save_worker_count(1)
                    log("workerCount reset to 1 after --unpair --deep", "INFO")
                except Exception as _wc_err:
                    log(f"workerCount reset failed (non-fatal): {_wc_err}", "WARN")
        except Exception as _de:
            log(f"Browser profile wipe failed: {_de}", "WARN")
    browser_wiped = browser_wiped_count > 0

    print()
    print(f"  {_c(_BOLD + _ACCENT, '  The bond dissolves.')}  {_c(_DIM, 'This machine is no longer paired.')}")
    print()
    if browser_wiped:
        if browser_wiped_count == 1:
            print(f"  {_c(_OK, '✓')}  Chrome profile wiped (`--deep`) — fresh browser on next --pair.")
        else:
            print(f"  {_c(_OK, '✓')}  {browser_wiped_count} Chrome profiles wiped (`--deep`) — fresh browsers on next --pair.")
    if browser_wiped or api_keys_wiped:
        print(f"  {_c(_DIM, 'Preserved on disk (remove manually for a fully clean slate):')}")
        print(f"       {_c(_DIM, '• Research history in queues/')}")
        print(f"       {_c(_DIM, '• firebase-service-account.json  (needed to re-pair)')}")
    else:
        print(f"  {_c(_DIM, 'Preserved on disk (remove manually for a fully clean slate):')}")
        print(f"       {_c(_DIM, '• Chrome profile(s) at ~/.super-research/browser-profile*/  (your logins)')}")
        print(f"       {_c(_DIM, '• Research history in queues/')}")
        print(f"       {_c(_DIM, '• firebase-service-account.json  (needed to re-pair)')}")
        print(f"       {_c(_DIM, '  Add --deep to also wipe the Chrome profile(s) + pair-time API keys next time.')}")
    _render_next_actions([
        ("python research.py --pair", "reconnect this machine (mints a fresh token)"),
    ])


def run_commands_help():
    """The `superresearch --help` / `-h` screen — a branded command reference
    grouped by use-case (daily / lifecycle / agent / advanced / diagnostics)
    rather than the raw argparse flag dump, since users learn the workflow not
    the parser layout. This is the single discovery surface (the old separate
    `--commands` flag was folded into --help)."""
    _branded_header("manuale", _BOLD + _ACCENT, "command reference")
    print()

    def _section(title, rows):
        print(f"  {_c(_BOLD, title)}")
        print(f"  {_rule(max_width=64)}")
        # Swap the authored `python research.py` prefix for the real invocation
        # (`superresearch` when installed) before measuring/printing.
        rows = [(cmd.replace("python research.py", _PROG), desc) for cmd, desc in rows]
        # Align command column; longest command wins the padding budget.
        pad = max(len(cmd) for cmd, _desc in rows)
        for cmd, desc in rows:
            print(f"  {_c(_BOLD, cmd.ljust(pad))}   {_c(_DIM, desc)}")
        print()

    _section("Daily", [
        ("python research.py --pair",
         "Pair this PC to your Super Research account (5-stage guided setup)"),
        ("python research.py --serve",
         "Run the backend in the foreground (Ctrl+C to stop)"),
        ("python research.py \"<topic>\"",
         "One-shot CLI research run (no web app)"),
    ])

    _section("Lifecycle (supervised auto-restart)", [
        ("python research.py --resurrect",
         "Install OS-native supervisor — auto-start at login + restart on crash"),
        ("python research.py --restart",
         "Restart the backend onto a newly installed version (the step after --update / pipx upgrade); keeps On Startup on"),
        ("python research.py --retire",
         "Disable On Startup — removes the supervisor; foreground --serve unchanged"),
        ("python research.py --unpair",
         "Fully disconnect this PC (deletes token + device doc + local config)"),
        ("python research.py --unpair --deep",
         "Same as --unpair, but ALSO wipes browser-profile*/ dirs + pair-time API keys + stale worker-state files + resets workerCount"),
    ])

    _section("Agent — drive Super Research from chat (Hermes / OpenClaw)", [
        ("python research.py agent connect [hermes|openclaw]",
         "Connect a chat runtime — branded 4-step flow (detects Windows + WSL; auto if omitted)"),
        ("python research.py agent resurrect",
         "Run the bridge in the background + on every login (windowless)"),
        ("python research.py agent retire",
         "Stop the background bridge + remove the login pin (session + skill untouched)"),
        ("python research.py agent serve",
         "Run the bridge in the foreground (this terminal) — holds your account session"),
        ("python research.py agent login",
         "Sign the agent in (add --remote to approve from your phone)"),
        ("python research.py agent status",
         "Bridge + session + autostart + runtime at a glance"),
        ("python research.py agent doctor",
         "Health + connectivity check (incl. WSL mirrored-networking prerequisite)"),
        ("python research.py agent disconnect",
         "Full teardown — remove the skill from the runtime AND sign out (the app's Revoke twin)"),
        ("python research.py agent --help",
         "Full agent command list (device / research / watch / skip / cancel / stop …)"),
    ])

    _section("Advanced", [
        ("python research.py --brief-file <path>",
         "Skip Phase 1 — start from an existing brief.md"),
        ("python research.py --pdf <file> [--pdf <file>...]",
         "Attach PDF(s) to Phase 1 (repeatable)"),
        ("python research.py --resume <queue-name|path>",
         "Resume a previous run from its queue/ directory"),
        ("python research.py --port <N>",
         "Override the default port 8000 for --serve"),
        ("python research.py --env-file <path>",
         "Load env vars from a custom file (default: .dg-supervisor.env)"),
        ("python research.py --api-key <key>",
         "One-shot Anthropic key override (bypasses Firestore / env resolve)"),
    ])

    _section("Diagnostics", [
        ("python research.py --doctor",
         "Diagnose + auto-repair common issues (pair state / Chromium / supervisor / DISPLAY / port 8000)"),
    ])

    # The local HTTP surface `--serve` binds. This used to print on every serve
    # boot as six timestamped `[INFO]   GET /api/runs …` lines — a static
    # reference pushed through the logger, which no other command did. It is
    # reference material, so it lives on the reference surface.
    _section(f"Local API  (while {_PROG} --serve is running)",
             [(route, desc) for route, desc in _LOCAL_API_ROUTES])

    _section("Internal / Debug", [
        ("python research.py --daemon-loop",
         "Wrapper that keeps --serve alive; spawned by the supervisor"),
        ("python research.py --verbose",
         "Tee extra logs to stdout (combine with any other command)"),
        ("python research.py --version",
         "Print the installed version (+ any available update)"),
    ])

    # Platform-specific hint surfaced at the bottom so users don't miss it.
    _plat = _supervisor_platform()
    if _plat == "Darwin":
        print(f"  {_c(_DIM, '• macOS supervisor: ~/Library/LaunchAgents/com.dgresearch.supervisor.plist')}")
    elif _plat == "Linux":
        print(f"  {_c(_DIM, '• Linux supervisor: ~/.config/systemd/user/dgresearch-supervisor.service')}")
    else:
        print(f"  {_c(_DIM, '• Windows supervisor: Scheduled Task `SuperResearchBackend`')}")
    # Cross-platform descriptor — F13 of the CLI audit. Pre-fix it only printed
    # under the Linux branch; Windows + macOS users never saw the full set.
    print(f"  {_c(_DIM, '  (Cross-platform: Windows Scheduled Task / macOS LaunchAgent / Linux systemd-user)')}")
    print(f"  {_c(_DIM, '• Config file: .dg-supervisor.env  (template at scripts/dg-supervisor.env.example)')}")
    print(f"  {_c(_DIM, '• Pipeline broken? Run')}  {_c(_BOLD, f'{_PROG} --doctor')}  {_c(_DIM, 'to diagnose + auto-fix.')}")
    print(f"  {_c(_DIM, '• Full docs: README.md   ·   ARCHITECTURE.md')}")
    print()


def run_doctor():
    """Diagnostic + auto-repair for common Super Research issues.

    Runs platform-aware checks and applies safe auto-fixes where possible.
    Designed to be the first thing a user runs when something feels wrong —
    surfaces the actual root cause (DISPLAY not propagated through systemd,
    stale supervisor unit, port-bound by another process, missing Chromium
    binary, etc.) instead of leaving them to grep logs.

    No destructive operations — never deletes user data, never unpairs,
    never modifies firebase-service-account.json. Worst case: restarts the
    supervisor + imports the calling shell's graphical-session env into
    the user-systemd manager (Linux only)."""
    import subprocess as _sp

    _branded_header("medicus", _BOLD + _ACCENT, "diagnose + heal")
    print()

    plat = _supervisor_platform()
    issues_found = 0
    fixes_applied = 0
    manual_actions: list[str] = []

    def _ok(label: str, detail: str = ""):
        suffix = f"  {_c(_DIM, '· ' + detail)}" if detail else ""
        print(f"  {_c(_OK, '✓')}  {label}{suffix}")

    def _warn(label: str, detail: str = ""):
        nonlocal issues_found
        issues_found += 1
        suffix = f"  {_c(_DIM, '· ' + detail)}" if detail else ""
        print(f"  {_c(_WARN, '⚠')}  {label}{suffix}")

    def _fail(label: str, detail: str = ""):
        nonlocal issues_found
        issues_found += 1
        suffix = f"  {_c(_DIM, '· ' + detail)}" if detail else ""
        print(f"  {_c(_ERR, '✗')}  {label}{suffix}")

    def _fix(label: str):
        nonlocal fixes_applied
        fixes_applied += 1
        print(f"     {_c(_ACCENT, '→')} {label}")

    # ── [1] Platform + pair state ──
    print(f"  {_c(_BOLD, 'Platform + pair state')}")
    print(f"  {_rule(max_width=58)}")
    if plat == "Unsupported":
        _fail(f"Platform unsupported ({sys.platform})", "Only Windows / macOS / Linux desktop.")
        print()
        print(f"  {_c(_DIM, 'Cannot continue diagnostics on this platform.')}")
        # ⛔ THE HAND-OVER RUNS HERE TOO. This is the ONE early return in
        # run_doctor, and it skipped the closing line that tells a person what
        # to do next — so the reader who most needs it (nothing here can be
        # diagnosed at all) reached the end of the page with no next step. The
        # commit that added the hand-over said it "closes every doctor run";
        # this branch is what made that untrue.
        print()
        print(f"  {_c(_DIM, _doctor_share_logs_line())}")
        print()
        return
    _ok(f"Platform: {plat}")

    paired_uid = load_paired_uid()
    device_id = load_device_id()
    if paired_uid and device_id:
        _ok("Pair state", f"deviceId={device_id}")
    else:
        _fail("Not paired", "research_config.json missing or incomplete — run --pair")
        manual_actions.append("Run `python research.py --pair`")

    with _sync_spinner_ctx("Checking Firestore connectivity"):
        _fb_ok = init_firebase()
    if _fb_ok:
        _ok("Firestore client", "user-mode (refresh-token credentials)")
    elif _firebase_down_reason == "broken_install":
        # ⛔⛔ THIS BRANCH DID NOT EXIST, and its absence made the doctor lie the
        # same way the reconnect ladder did. A machine whose `auth/` package will
        # not import classified as "transient", so this command answered "Cannot
        # reach firestore.googleapis.com — the network, not your pairing", ran
        # the host probes, found every one of them healthy, and printed "The
        # network path is fine" with an EMPTY action list. A diagnosis, a
        # contradiction of the diagnosis, and nothing to do.
        _fail("This install is incomplete",
              "part of the backend is missing — the network and the pairing "
              "are both fine")
        manual_actions.append(_remedy_reinstall())
    elif _firebase_down_reason == "transient":
        # ⛔⛔ 2026-08-17 — THIS BRANCH DID NOT EXIST, and its absence is what
        # sent a real new owner in a circle. Their machine could not resolve
        # firestore.googleapis.com; --doctor told them their token was revoked
        # and to re-pair. Re-pairing cannot fix a network, and it spends the
        # pairing they still had. `init_firebase` has always known the
        # difference — it sets the reason authoritatively, from whether the
        # live token refresh raised (network) or returned None (revoked) —
        # and doctor simply never asked.
        _fail(f"Cannot reach {FIRESTORE_HOST}",
              "the network, not your pairing — nothing here needs re-pairing")

        # ⭐ Then LOCALIZE it, rather than handing over a list of suspects. The
        # probes only run on this branch, so a healthy machine pays nothing for
        # them. Resolution and connection are asked separately because they have
        # different causes and different fixes.
        print()
        print(f"  {_c(_BOLD, 'Network path')}")
        print(f"  {_rule(max_width=58)}")
        _probes = []
        with _sync_spinner_ctx("Testing the hosts this machine needs"):
            for _host, _why_host, _kind in _DOCTOR_NET_TARGETS:
                _probes.append(_probe_host(_host))
        for _p, (_h, _why_host, _kind) in zip(_probes, _DOCTOR_NET_TARGETS):
            if _p["connected"]:
                _ok(f"{_p['host']}", f"{_why_host} — resolves to {_p['addr']}, connects")
            elif _p["resolved"]:
                _fail(f"{_p['host']}",
                      f"{_why_host} — resolves to {_p['addr']}, but the connection "
                      f"was refused ({_p['connect_error']})")
            else:
                _fail(f"{_p['host']}",
                      f"{_why_host} — the name could not be looked up "
                      f"({_p['resolve_error']})")

        _verdict = _network_verdict(_probes)
        print()
        print(f"  {_c(_BOLD, _verdict['headline'])}")
        for _addr in _verdict["blocked_addrs"]:
            print(f"  {_c(_DIM, 'Refusing address: ' + _addr + ':443')}")
        for _act in _verdict["actions"]:
            print(f"     {_c(_ACCENT, '→')} {_act}")
        # ⛔ Say plainly that this is not ours to change. A diagnostic that
        # implies it will fix a VPN is the same species of lie as the message
        # that told them to re-pair.
        print()
        print(f"  {_c(_DIM, 'Super Research cannot change any of this for you — DNS, VPN,')}")
        print(f"  {_c(_DIM, 'proxy and firewall settings belong to this machine and this')}")
        print(f"  {_c(_DIM, 'network. Nothing is wrong with your install or your pairing.')}")
        # ⭐ The hand-over line used to be printed HERE and only here. It now
        # closes every doctor run — see the summary — so repeating it in this
        # branch would put it on the page twice for the one fault that already
        # had it.
        manual_actions.extend(_verdict["actions"] or [
            f"nslookup {FIRESTORE_HOST}   (then check VPN / proxy / firewall / DNS)"])
    else:
        _fail("Firestore init failed", "OS keystore empty or refresh token revoked")
        manual_actions.append("Run `python research.py --pair`")
    print()

    # ── [2] Browser dependencies (Playwright + Chromium) ──
    print(f"  {_c(_BOLD, 'Browser dependencies')}")
    print(f"  {_rule(max_width=58)}")
    try:
        import patchright  # noqa: F401
        _ok("patchright package", "installed in active venv")
    except ImportError:
        _fail("patchright not importable", _remedy_reinstall())
        manual_actions.append(_remedy_reinstall())
    try:
        # All-semicolons probe so `python -c` parses on every platform
        # (compound try/except blocks with embedded \n break -c). If
        # chromium can't launch, the launch() raises and the subprocess
        # exits non-zero — we read that return code + stderr instead of
        # relying on a try/except inside -c. 60s timeout because cold
        # Chromium boot on slow hardware (Crostini, low-power) can take
        # a while; this probe runs once per `--doctor`, not per request.
        # Probe REAL Google Chrome via channel="chrome" — the exact browser the
        # pipeline drives (research.py:~16137 launch_persistent_context(channel=
        # "chrome")). Probing bundled Chromium instead would pass even when real
        # Chrome / its patchright wrapper is missing, masking the actual failure.
        _probe = (
            "from patchright.sync_api import sync_playwright; "
            "pp=sync_playwright().start(); "
            "b=pp.chromium.launch(headless=True, channel='chrome'); "
            "b.close(); pp.stop(); "
            "print('OK')"
        )
        with _sync_spinner_ctx("Launching Chrome (headless) to verify it boots"):
            _chromium_check = _sp.run(
                [sys.executable, "-c", _probe],
                capture_output=True, text=True, timeout=60,
            )
        _stdout = (_chromium_check.stdout or "").strip()
        _stderr = (_chromium_check.stderr or "").strip()
        _combined = (_stdout + " " + _stderr).lower()
        if _chromium_check.returncode == 0 and "OK" in _stdout:
            _ok("Chrome binary", "patchright launches Chrome (channel=chrome) headless cleanly")
        elif "executable doesn't exist" in _combined or "browsertype.launch" in _combined or "playwright install" in _combined or "no such file" in _combined:
            # Two distinct causes: the patchright Chrome wrapper isn't fetched
            # yet (fixable with `patchright install chrome`), or real Google
            # Chrome isn't installed on the OS at all (an OS-level dep). Surface
            # both so a fresh pipx install knows what to do.
            _fail("Chrome not launchable", "run patchright install chrome (and install Google Chrome if absent)")
            manual_actions.append("patchright install chrome")
            manual_actions.append(_chrome_install_hint())
        elif "modulenotfounderror" in _combined or "no module named" in _combined:
            # "venv mismatch?" — a question mark was the whole detail, and the
            # remedy was POSIX-only shell on a product whose commonest new-owner
            # platform is Windows. Say what was actually observed instead: the
            # probe runs the SAME interpreter that just imported patchright
            # successfully a few lines above, so a failure here is a broken or
            # half-written install rather than the wrong environment.
            _fail("patchright imports here but not in a fresh subprocess",
                  f"same interpreter ({sys.executable}) — a partial or broken install")
            manual_actions.append(_remedy_reinstall())
        else:
            _warn("Chromium launch test inconclusive",
                  (_stderr[:80] or _stdout[:80] or f"exit={_chromium_check.returncode}"))
    except _sp.TimeoutExpired:
        _warn("Chromium launch probe timed out (>60s)", "machine under heavy load?")
    except Exception as e:
        _warn("Chromium launch probe errored", str(e)[:80])
    print()

    # ── [3] Supervisor unit / task ──
    print(f"  {_c(_BOLD, 'Supervisor')}")
    print(f"  {_rule(max_width=58)}")
    if plat == "Linux":
        if _SUPERVISOR_UNIT_PATH.exists():
            _ok("Unit file present", str(_SUPERVISOR_UNIT_PATH))
            _unit_content = _SUPERVISOR_UNIT_PATH.read_text(encoding="utf-8", errors="replace")
            if "Environment=" in _unit_content and "DISPLAY=" in _unit_content:
                _ok("Unit has DISPLAY embedded", "reboot-safe")
            else:
                _warn("Unit missing Environment=DISPLAY=...",
                      "browser may fail post-reboot — re-run --resurrect")
                manual_actions.append(_remedy_resurrect() + "  — run it from a graphical-session terminal")
        else:
            _warn("Unit file not installed", "supervisor disabled")
            manual_actions.append(_remedy_resurrect())
        try:
            r = _sp.run(["systemctl", "--user", "is-active", _SUPERVISOR_UNIT_NAME],
                        capture_output=True, text=True, timeout=5)
            state = (r.stdout or "").strip()
            if state == "active":
                _ok("systemctl is-active", state)
            else:
                _warn("systemctl is-active", state or "unknown")
                try:
                    _sp.run(["systemctl", "--user", "restart", _SUPERVISOR_UNIT_NAME],
                            capture_output=True, text=True, timeout=15)
                    _fix("Restarted dgresearch-supervisor")
                except Exception as _re:
                    manual_actions.append(f"systemctl --user restart dgresearch-supervisor  (was: {_re})")
        except Exception as e:
            _warn("systemctl probe failed", str(e)[:80])
        linger = _check_linger_status()
        if linger == "yes":
            _ok("loginctl Linger", "yes — survives logout")
        elif linger == "no":
            _warn("loginctl Linger=no", "daemon-loop dies at logout")
            manual_actions.append("sudo loginctl enable-linger $USER")
        else:
            _warn("loginctl Linger unknown")
    elif plat == "Darwin":
        if _SUPERVISOR_PLIST_PATH.exists():
            _ok("LaunchAgent plist present", str(_SUPERVISOR_PLIST_PATH))
            if _detect_supervised_macos():
                _ok("launchctl bootstrapped", _SUPERVISOR_PLIST_LABEL)
            else:
                _warn("launchctl not bootstrapped", "plist exists but agent not loaded")
                # Auto-fix attempt: re-bootstrap into the gui session.
                try:
                    uid = os.getuid()
                    _sp.run(["launchctl", "bootstrap", f"gui/{uid}", str(_SUPERVISOR_PLIST_PATH)],
                            capture_output=True, text=True, timeout=10)
                    _fix("Re-bootstrapped LaunchAgent into gui session")
                except Exception as _le:
                    manual_actions.append(f"launchctl bootstrap gui/$(id -u) {_SUPERVISOR_PLIST_PATH}  (was: {_le})")
        else:
            _warn("LaunchAgent plist not installed")
            manual_actions.append(_remedy_resurrect())
    else:  # Windows
        if _detect_supervised_windows():
            _ok("Scheduled Task installed", _SUPERVISOR_TASK_NAME)
            # Confirm the task is currently scheduled to run (not just registered).
            try:
                r = _sp.run(["schtasks", "/Query", "/TN", _SUPERVISOR_TASK_NAME, "/FO", "LIST"],
                            capture_output=True, text=True, timeout=5,
                            creationflags=_PS_NO_WINDOW)
                _qout = (r.stdout or "").lower()
                if "ready" in _qout or "running" in _qout:
                    _ok("Scheduled Task state", "ready/running")
                elif "disabled" in _qout:
                    _warn("Scheduled Task state", "disabled")
                    try:
                        _sp.run(["schtasks", "/Change", "/TN", _SUPERVISOR_TASK_NAME, "/ENABLE"],
                                capture_output=True, text=True, timeout=5,
                                creationflags=_PS_NO_WINDOW)
                        _fix("Re-enabled SuperResearchBackend Scheduled Task")
                    except Exception as _se:
                        manual_actions.append(f"schtasks /Change /TN {_SUPERVISOR_TASK_NAME} /ENABLE  (was: {_se})")
            except Exception:
                pass
        else:
            _warn("Scheduled Task not installed")
            manual_actions.append(_remedy_resurrect())
    print()

    # ── [3b] Search path ──
    #
    # ⛔⛔ THIS COMMAND ONLY EVER LOOKED AT DISPLAY. The supervisor bakes a search
    # path with the tool homes FIRST — a stated trade, and it stands — which
    # means anything dropped in a user-writable directory shadows the OS copy for
    # every supervised child. Nothing logged the baked value and nothing here
    # asked about it, so a shadowed audio binary presented as a phase-3 failure
    # that happened ONLY under the supervisor and was undiagnosable from a
    # support bundle.
    #
    # ⭐⭐ AND ASKING `shutil.which` FROM HERE IS THE WRONG QUESTION. This command
    # runs in a login shell, whose path is not the one a supervised child gets.
    # The two answers are compared below, because a tool that resolves
    # differently in each IS the "works in my terminal, fails as a service"
    # report, already localized.
    print(f"  {_c(_BOLD, 'Search path')}")
    print(f"  {_rule(max_width=58)}")
    # ⭐⭐ EVERY DECISION IS IN `_search_path_findings`, and this only renders
    # them. `run_doctor` cannot be executed in a test — it opens a Firestore
    # client, imports patchright and spawns a 60-second Chromium probe — so a
    # section written inline here can only ever be pinned by looking at its
    # source. Mutation showed exactly what that is worth: five separate mutants
    # gutted the branches and every source pin still passed, because the strings
    # they looked for survived the gutting.
    _spf = _search_path_findings(
        shell_path=os.environ.get("PATH", ""),
        supervisor_path=_installed_supervisor_path(),
        would_bake=_supervisor_path_value(),
        platform=plat)
    for _lvl, _label, _detail in _spf["rows"]:
        if _lvl == "ok":
            _ok(_label, _detail)
        elif _lvl == "warn":
            _warn(_label, _detail)
        else:
            _note = f"     {_label}" + (f"  {_detail}" if _detail else "")
            print(f"  {_c(_DIM, _note)}")
    manual_actions.extend(_spf["actions"])
    print()

    # ── [4] Process tree + port ──
    print(f"  {_c(_BOLD, 'Process tree')}")
    print(f"  {_rule(max_width=58)}")
    procs = _enumerate_research_py_procs()
    daemon_pids = [pid for pid, _c2, role in procs if role == "daemon-loop"]
    serve_pids  = [pid for pid, _c2, role in procs if role == "serve"]
    if daemon_pids:
        _ok("daemon-loop running", f"PID {daemon_pids[0]}")
    else:
        # ⛔⛔ "SEE THE SUPERVISOR SECTION ABOVE" WAS A DEAD END. On a machine
        # whose backend dies at spawn and is respawned every ten seconds, that
        # section reports the plist present and launchctl bootstrapped — both
        # true — so the reader was sent to a section that says nothing is wrong.
        # The evidence exists and nothing had ever read it: whatever launchd or
        # systemd captured on the way down, which for a spawn-time death is the
        # only record, because our own logging never got to start.
        _ev = _supervisor_evidence()
        if _ev["lines"]:
            _fail("daemon-loop not running",
                  "the supervisor started it and it exited — its own last words:")
            for _evl in _ev["lines"]:
                print(f"       {_c(_DIM, _evl[:160])}")
            if _ev["legacy"]:
                _legacy_note = ("     That log is in an older build's location, so "
                                "--send-logs cannot include it.")
                print(f"  {_c(_DIM, _legacy_note)}")
                manual_actions.append(_remedy_resurrect())
        else:
            _warn("daemon-loop not running",
                  f"nothing in {_supervisor_log_dir() / 'supervisor.err.log'} either")
    if serve_pids:
        _ok("--serve running", f"PID {serve_pids[0]}")
    else:
        _fail("--serve not running", "no API server → FE will show offline")
        # ⛔⛔ THIS FAILURE USED TO CARRY NO REMEDY AT ALL. The doctor told you the
        # API server was not running and then never said how to start one — the
        # only step listed came from the SUPERVISOR finding above, so `--resurrect`
        # read as the single answer to a different question. Both ways out are
        # named here, each with the one fact that decides between them, because
        # "which of these do I want" is the actual question a reader has.
        manual_actions.append(_remedy_serve())
        manual_actions.append(_remedy_resurrect())
    # Port 8000 ownership
    if plat in ("Linux", "Darwin"):
        try:
            r = _sp.run(["ss", "-ltnp"], capture_output=True, text=True, timeout=5)
            if ":8000" in (r.stdout or ""):
                if serve_pids and f"pid={serve_pids[0]}" in r.stdout:
                    _ok("Port 8000", f"bound by our --serve (PID {serve_pids[0]})")
                else:
                    _warn("Port 8000", "bound by a non-Super-Research process")
                    manual_actions.append("Identify with `ss -ltnp | grep :8000` and kill the stale binding")
            else:
                _warn("Port 8000 not bound", "API unreachable")
        except Exception:
            pass
    print()

    # ── [5] Linux-specific: DISPLAY propagation ──
    if plat == "Linux":
        print(f"  {_c(_BOLD, 'Graphical-session env (Linux)')}")
        print(f"  {_rule(max_width=58)}")
        shell_disp = os.environ.get("DISPLAY", "")
        if shell_disp:
            _ok("Shell DISPLAY", shell_disp)
        else:
            _warn("Shell DISPLAY empty", "you're in a non-graphical session (SSH? cron?)")
        # Manager env
        try:
            r = _sp.run(["systemctl", "--user", "show-environment"],
                        capture_output=True, text=True, timeout=5)
            mgr_env = r.stdout or ""
            if "DISPLAY=" in mgr_env:
                _ok("user-systemd manager DISPLAY", "present")
            else:
                _warn("user-systemd manager DISPLAY missing",
                      "supervisor children won't see it")
                if shell_disp:
                    try:
                        _sp.run(["systemctl", "--user", "import-environment",
                                 "DISPLAY", "WAYLAND_DISPLAY", "XAUTHORITY", "XDG_RUNTIME_DIR"],
                                capture_output=True, text=True, timeout=10)
                        _fix("Imported DISPLAY/WAYLAND_DISPLAY/XAUTHORITY into user-systemd manager")
                        # Restart so children pick it up
                        try:
                            _sp.run(["systemctl", "--user", "restart", _SUPERVISOR_UNIT_NAME],
                                    capture_output=True, text=True, timeout=15)
                            _fix("Restarted dgresearch-supervisor to inherit new env")
                        except Exception:
                            pass
                    except Exception as e:
                        manual_actions.append(f"systemctl --user import-environment DISPLAY WAYLAND_DISPLAY XAUTHORITY  (was: {e})")
        except Exception as e:
            _warn("systemctl show-environment failed", str(e)[:80])
        # --serve actual env
        if serve_pids:
            try:
                env_blob = Path(f"/proc/{serve_pids[0]}/environ").read_bytes().decode("utf-8", errors="replace")
                if "DISPLAY=" in env_blob:
                    _ok("--serve DISPLAY env", "present")
                else:
                    _warn("--serve DISPLAY missing",
                          "running browser will fail — restart supervisor after the import-environment above")
            except Exception:
                pass
        print()

    # ── Summary ──
    print(f"  {_rule(max_width=58)}")
    if issues_found == 0:
        print(f"  {_c(_OK + _BOLD, '✓  Healthy.')}  {_c(_DIM, 'All checks passed.')}")
    else:
        tm.tm_emit(tm.Ev.DOCTOR_RUN, count=int(issues_found),
                   supervised=_detect_supervised())
        print(f"  {_c(_BOLD, f'Found {issues_found} issue(s); applied {fixes_applied} auto-fix(es).')}")
        # Two findings can legitimately prescribe the same command — a missing
        # supervisor and a stopped server both end at `--resurrect`. Listing it
        # twice makes a two-step list look like a four-step one.
        manual_actions = _dedupe_actions(manual_actions)
        if manual_actions:
            print()
            print(f"  {_c(_BOLD, 'Manual steps still required:')}")
            for i, a in enumerate(manual_actions, 1):
                print(f"    {_c(_ACCENT, f'{i}.')} {a.replace('python research.py', _PROG)}")
    # ⛔⛔ THE HAND-OVER, ON EVERY RUN, and it used to live inside ONE branch:
    # the transient-Firestore one. So a machine whose Chromium would not launch,
    # whose supervisor was missing, or whose refresh token was revoked read a
    # diagnosis and reached the end of the page with nothing to do next. The
    # owner's ask was "every failure a person can be left holding should point at
    # the way to hand it over", and a network fault is one failure out of a dozen
    # this command reports.
    #
    # ⭐ INCLUDING `✓ Healthy`, which is the case a person is MOST stuck in: they
    # ran this because something is wrong, and the answer was that nothing here
    # is. That is exactly when the logs are the next move, and the line opens
    # "Still stuck?" — which is a question only that reader is being asked.
    #
    # Printed here rather than in each branch because two authors of one sentence
    # is how `--resurrect` came to be prescribed twice in a three-step list.
    print()
    print(f"  {_c(_DIM, _doctor_share_logs_line())}")
    print()


# ── CLI ──────────────────────────────────────────────────────────────────────

def _delegate_agent_via_pipx(agent_args: "list[str]") -> int:
    """Run the Super Research agent via pipx — the path used when the backend
    was installed as a package (no in-tree agent/ sibling). The agent is its own
    PyPI package (`superresearch-agent`); `pipx run` fetches + runs it in an
    isolated venv, exactly as the install docs / chat-install flow do. Falls
    back to `python -m pipx run …` when the pipx shim isn't on PATH yet, and
    prints a clear pointer if pipx is missing entirely."""
    pipx = shutil.which("pipx")
    if pipx:
        cmd = [pipx, "run", "superresearch-agent", *agent_args]
    else:
        # pipx not on PATH (e.g. just installed, shim not refreshed) — module
        # form via the current interpreter dodges the PATH-refresh gap.
        cmd = [sys.executable, "-m", "pipx", "run", "superresearch-agent", *agent_args]
    try:
        print("Fetching the Super Research agent (first run downloads it; this can take a moment)…")
        return subprocess.call(cmd)
    except KeyboardInterrupt:
        return 130
    except FileNotFoundError:
        shown = " ".join(agent_args) if agent_args else "connect"
        print("The Super Research agent runs via pipx, which isn't installed.")
        print("Install pipx (https://pipx.pypa.io), then run:")
        print(f"  pipx run superresearch-agent {shown}")
        return 2


def _sr_version() -> str:
    """Installed package version (from wheel metadata), or a source-checkout
    label when not pip-installed."""
    try:
        from importlib.metadata import version as _v
        return _v("superresearch")
    except Exception:
        return "(source checkout)"


# What THIS process is executing, frozen at import.
#
# `_sr_version()` cannot answer that question later: it is `importlib.metadata`,
# which re-reads the dist-info off disk, so it flips to the NEW number the instant
# pipx finishes — inside a process that is still running the old code. Read once,
# before any upgrade can land, and it is exact for the life of the process.
#
# This is the honest source for "does the backend still owe a restart", and the
# marker file below is not, for a reason that only shows up on multi-worker hosts:
# it is a single path with no worker id and every `--serve` writes it, so it names
# whichever worker started LAST, while the verdict is published by worker 1's
# heartbeat. A worker that crashed and was respawned onto the new venv would stamp
# it and worker 1 would report "Updated ✓" while still serving the old build.
try:
    _BOOT_VERSION: "str | None" = _sr_version()
except Exception:  # pragma: no cover - metadata unreadable; degrade to "can't tell"
    _BOOT_VERSION = None


def _serving_version() -> "str | None":
    """The version the process answering the app is executing."""
    return _BOOT_VERSION


# Version of the backend the CURRENTLY-RUNNING serve process is executing, as seen
# from ANOTHER process (a CLI invocation) — which is the one thing `_BOOT_VERSION`
# cannot tell you. Still used by `_restart_pending`, which runs from `--version` /
# `--update` and has to ask about a process that is not itself.
_RUNNING_VERSION_PATH = _STATE_DIR / "running-version.json"


def _write_running_version() -> None:
    """Record what this serve process is running. Best-effort — never blocks serve."""
    try:
        _STATE_DIR.mkdir(parents=True, exist_ok=True)
        _RUNNING_VERSION_PATH.write_text(
            json.dumps({"version": _sr_version(), "pid": os.getpid(),
                        "started_at": time.time()}),
            encoding="utf-8")
    except Exception:
        pass


def _running_version() -> "str | None":
    """Version of the live serve process, or None when nothing is running / unknown.
    A recorded PID that is no longer alive means the marker is stale → None."""
    try:
        data = json.loads(_RUNNING_VERSION_PATH.read_text(encoding="utf-8"))
        ver, pid = data.get("version"), data.get("pid")
        if not ver or not isinstance(pid, int):
            return None
        if not _pid_alive(pid):
            return None
        return str(ver)
    except Exception:
        return None


def _pid_alive(pid: int) -> bool:
    try:
        if sys.platform == "win32":
            import ctypes
            h = ctypes.windll.kernel32.OpenProcess(0x00100000, 0, pid)  # SYNCHRONIZE
            if not h:
                return False
            ctypes.windll.kernel32.CloseHandle(h)
            return True
        os.kill(pid, 0)
        return True
    except (ProcessLookupError, OSError, Exception):
        return False


def _restart_pending() -> "tuple[str, str] | None":
    """(running_version, installed_version) when a newer build is installed than the
    one actually serving — i.e. an update landed and the backend still needs a
    restart. None when nothing is running, versions match, or we can't tell."""
    running = _running_version()
    if not running:
        return None
    installed = _sr_version()
    if not installed or installed.startswith("("):     # source checkout
        return None
    if running == installed:
        return None
    return running, installed


def _restart_hint_lines() -> list:
    """The one place that words the post-update restart. Used by --update, --version
    and the generic nudge so the instruction never drifts between them."""
    if _supervisor_installed():
        cmd = f"{_PROG} --restart"
        why = "always-on is set up, so this cycles the supervisor onto the new build"
    else:
        cmd = f"{_PROG} --serve"
        why = "stop the running backend, then start it again"
    return [
        f"  {_c(_WARN, '⚠')}  Update installed, but the RUNNING backend is still the old build.",
        f"  {_c(_DIM, 'Restart it:')}  {_c(_BOLD, cmd)}   {_c(_DIM, '(' + why + ')')}",
    ]


def _warn_if_restart_pending() -> None:
    """Print the restart nudge when a newer build is installed than the one serving.
    Called from the CLI dispatch so it surfaces no matter HOW the update arrived —
    `--update`, a bare `pipx upgrade`, or the superresearch.io installer."""
    try:
        pend = _restart_pending()
        if not pend:
            return
        running, installed = pend
        print()
        print(f"  {_c(_WARN, '⚠')}  Running v{running}  →  installed v{installed}")
        for line in _restart_hint_lines()[1:]:
            print(line)
        print()
    except Exception:
        pass


def _is_source_checkout() -> bool:
    """True when running from a dev source tree (vs a pipx/pip-installed build).
    Mirrors the agent front-door heuristic: the in-tree agent package exists only
    in a checkout, never in an installed wheel."""
    try:
        return (Path(__file__).resolve().parent / "agent" / "facade" / "__main__.py").exists()
    except Exception:
        return False


# ─── Where exactly the network path is broken ──────────────────────────
# ⛔ 2026-08-17. A new owner's machine could not resolve firestore.googleapis.com.
# `--doctor` told them their refresh token was revoked and to re-pair, which
# cannot fix a network and spends the pairing they still had. Naming the real
# fault was the first fix; this is the second, and the owner asked for it
# directly: "so the doctor tells them the RIGHT solution".
#
# ⭐⭐ IT CANNOT FIX THIS, AND MUST NOT PRETEND TO. DNS resolvers, VPN clients,
# corporate proxies and firewall rules are the user's own machine and network,
# most of them need administrator rights, and none of them are ours to change.
# What a diagnostic CAN do is stop handing over a list of five suspects and
# instead say WHICH ONE — and where it cannot, hand over the log.
#
# The three hosts are the product's own dependencies, not arbitrary pings, so
# the control costs nothing extra and its answer is directly relevant: two
# Google API hostnames the pipeline cannot work without, and one non-Google host
# it also needs. That third one is what separates "this machine has no working
# DNS at all" from "something on this network answers for everything EXCEPT
# Google's APIs" — which is the corporate-resolver and blocklist case, and the
# single most likely cause of the outage that started all this.
_DOCTOR_NET_TARGETS = (
    (FIRESTORE_HOST, "the channel your machine and the web app talk over", "google"),
    ("securetoken.googleapis.com", "the sign-in refresh your machine needs", "google"),
    ("firebasestorage.googleapis.com",
     "where your logs and podcasts are uploaded", "google"),
    ("api.anthropic.com", "a non-Google host the pipeline also needs", "control"),
)


def _probe_host(host: str, port: int = 443, timeout: float = 4.0) -> dict:
    """Resolve a hostname, then try to open a socket to it.

    Two SEPARATE facts, reported separately, because they have different causes
    and different fixes: a name that will not resolve is DNS, and a name that
    resolves but will not connect is a firewall or a proxy. The old single
    "could not reach" verdict could not tell them apart, so its advice had to
    list both and commit to neither.
    """
    out = {"host": host, "resolved": False, "connected": False,
           "addr": "", "resolve_error": "", "connect_error": ""}
    try:
        infos = socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)
        out["resolved"] = True
        if infos:
            out["addr"] = str(infos[0][4][0])
    except Exception as exc:
        out["resolve_error"] = f"{type(exc).__name__}: {exc}"
        return out
    try:
        with socket.create_connection((host, port), timeout=timeout):
            out["connected"] = True
    except Exception as exc:
        out["connect_error"] = f"{type(exc).__name__}: {exc}"
    return out


def _network_verdict(probes: "list[dict]") -> dict:
    """Turn three probe results into ONE named fault, a headline, and actions.

    Pure so it can be tested without a network — the probes are the only part
    that touches one. Returns `kind`, `headline`, `actions` and `blocked_addrs`
    (the resolved addresses of whatever refused a connection, which is exactly
    what a corporate IT ticket has to name).
    """
    rows = [p for p in (probes or []) if isinstance(p, dict)]
    if not rows:
        return {"kind": "unknown", "headline": "No network probes ran.",
                "actions": [], "blocked_addrs": []}

    def group(kind):
        return [p for p in rows
                if next((t[2] for t in _DOCTOR_NET_TARGETS if t[0] == p.get("host")),
                        "control") == kind]

    google, control = group("google"), group("control")
    g_res = [p for p in google if p.get("resolved")]
    c_res = [p for p in control if p.get("resolved")]
    unresolved = [p for p in rows if not p.get("resolved")]
    unconnected = [p for p in rows if p.get("resolved") and not p.get("connected")]
    blocked = [p.get("addr", "") for p in unconnected if p.get("addr")]

    if not unresolved and not unconnected:
        return {"kind": "ok",
                "headline": "The network path is fine — every host this machine "
                            "needs resolves and accepts a connection.",
                "actions": [], "blocked_addrs": []}

    if not g_res and not c_res:
        return {
            "kind": "no_dns",
            "headline": "This machine has no working name resolution at all — "
                        "not one of the hosts it needs could be looked up.",
            "actions": [
                "Check you are actually on a network (Wi-Fi joined, cable in).",
                "If this is a hotel, cafe or campus network, open any web page "
                "first — those networks hold you until you accept their terms.",
                "If you are on a VPN, disconnect it and run this again.",
            ],
            "blocked_addrs": [],
        }

    if c_res and not g_res:
        return {
            "kind": "google_blocked",
            "headline": "Name resolution works, but NOT for Google's APIs — "
                        "something on this network answers for everything except "
                        "the hosts Super Research needs.",
            "actions": [
                "This is nearly always a corporate DNS server, a VPN's resolver, "
                "or a network-level blocker such as a Pi-hole.",
                "Disconnect any VPN and run this again — that alone settles it.",
                f"If you administer this network, allow {FIRESTORE_HOST} and "
                f"securetoken.googleapis.com.",
                "If someone else administers it, this is the sentence to send "
                "them: name resolution for *.googleapis.com is not being answered "
                "on this network.",
            ],
            "blocked_addrs": [],
        }

    if unconnected and not unresolved:
        return {
            "kind": "blocked_after_dns",
            "headline": "The names resolve, so DNS is fine — but this machine "
                        "cannot open a connection to them. Something is refusing "
                        "the traffic, not the lookup.",
            "actions": [
                "That is a firewall or an intercepting proxy rather than DNS.",
                "Disconnect any VPN and run this again.",
                "If someone else administers this network, they need to allow "
                "outbound TCP on port 443 to the addresses listed above.",
            ],
            "blocked_addrs": blocked,
        }

    return {
        "kind": "partial",
        "headline": "Some of the hosts this machine needs answer and some do not, "
                    "so the fault is inside this network rather than at either end.",
        "actions": [
            "Disconnect any VPN and run this again — a split-tunnel VPN produces "
            "exactly this pattern.",
            "If it persists, the per-host detail above is what to send us.",
        ],
        "blocked_addrs": blocked,
    }


# ─── --send-logs: the hand-over that does not need the network to work ──
# ⛔⛔ THE FOUNDING BLOCKER, and the reason this ladder exists. The machine that
# started this wave was PAIRED, with Google DNS dead: securetoken, firestore and
# firebasestorage were all unreachable, so the authenticated path was not slow,
# it was gone. An unpaired-only fallback would have excluded exactly that case.
#
# So the order is: write the file locally FIRST and print where it is, then try
# the authenticated upload, then fall back to our own host. The printed local
# file is the floor, and it is the only rung that cannot fail.
#
# ⭐ Honest residual, stated in the copy rather than hidden: if ALL DNS is dead —
# ours included — nothing live can send anything. The file on disk and the
# doctor's network verdict are what the person is left holding, and that is a
# real answer, unlike a spinner.

# ✅ FLIPPED 2026-08-26, WITH THE READ-BACK PASTED IN THE SAME COMMIT — which is
# the whole protocol this flag exists to enforce. The rule is live on
# `gs://super-research-492814.firebasestorage.app`: one rule, action Delete,
# `age` 30, `matchesPrefix` ["logs/"], read back by `gcloud storage buckets
# describe` and `gsutil lifecycle get` independently. See the ship-time runbook
# in the front end's ARCHITECTURE.md, §1 `verified:`.
#
# ⛔ WHAT THE SENTENCE MAY CLAIM. The rule deletes the OBJECT — the zip, which is
# the logs. It does not delete the Firestore index row, and that row's own TTL
# turns out never to have been deployed, so today the receipt outlives the file
# it names. That is why the line below says the material is deleted and stops
# there: `firestore.rules` bounds the row to a code, a device id, a status,
# timestamps, counts and sizes — no log content, no topics, no addresses — so a
# surviving row is a receipt for something that is gone, not a copy of it.
#
# ⛔ IF THE RULE IS EVER REMOVED, FLIP THIS BACK IN THE SAME BREATH. The flag is
# not a feature switch; it is a claim about a bucket, and the bucket is the only
# thing that makes the claim true.
BUNDLE_LIFECYCLE_VERIFIED = True


def _send_logs_consent_lines(runs: int = BUNDLE_MAX_RUNS,
                             chosen_exactly: bool = False) -> "list[str]":
    """Everything that leaves the machine, named. One line per fact.

    ⭐ The run bounds and the raw device logs are listed SEPARATELY on purpose:
    the runs obey 30-runs/30-days, and the raw logs are byte-tails with no age
    bound at all — a machine that predates per-run capture has its whole history
    only there. Folding them into one sentence would make the 30-day half a
    claim about bytes it does not cover.

    ⭐⭐ `chosen_exactly` is what `--select` sets, and the difference it makes is
    a promise this command otherwise cannot keep. Without a selection the first
    line has to say "at MOST n, and only those from the last 30 days" — a
    ceiling, because the collector sorts age-eligible runs newest-first and takes
    the top n, so a machine with fifty inside the window sends thirty. With a
    selection the person named the runs, every name came from a list of what the
    machine actually holds, and the count is exact. Saying "at most" there would
    understate a request the person made precisely.

    ⛔ AND THE AGE BOUND DROPS WITH IT, for the same reason: it can no longer
    remove anything that was picked. Repeating it would describe a filter with
    nothing left to filter.
    """
    if chosen_exactly:
        n = max(0, int(runs))
        first = ("no runs — this machine's own log files only" if n == 0 else
                 f"the {n} run{'' if n == 1 else 's'} you chose, and only those")
    else:
        n = max(BUNDLE_MIN_RUNS, min(int(runs), BUNDLE_MAX_RUNS))
        first = (f"at most {n} run{'' if n == 1 else 's'} from this machine — and only "
                 f"{'if it is' if n == 1 else 'those'} from the last "
                 f"{BUNDLE_MAX_AGE_DAYS} days")
    lines = [
        first,
        "your research topics, and the titles of what each run produced",
        "links that open your research results — anyone holding one can read them",
        "the email address on your account",
        "what the agent screens showed while a run was working",
        "this computer's hostname and the account name you sign into it with",
        "this device's own log files — the most recent few megabytes of each, "
        "whatever their age",
    ]
    # ⛔⛔ EVERYTHING BELOW THE FIRST LINE IS UNAFFECTED BY THE NUMBER. The
    # sessions are age-bound only and the raw tails have no bound at all, and
    # those tails carry the same topics, result links and account email for the
    # machine's whole history. Without this sentence, moving the number down
    # reads as "less of everything leaves", which is the one thing it does not
    # mean.
    lines.append(
        "⚠ only the first line above is what your choice changes — everything "
        "else leaves in full whichever runs you pick"
        if chosen_exactly else
        f"⚠ only the first line above is what the {n}-run choice changes — "
        f"everything else leaves in full whatever number you pick")
    # ⭐ "AFTER IT ARRIVES", NOT "AFTER 30 DAYS", because the two clocks are
    # different and only one of them is the bucket's. The lifecycle rule counts
    # from the moment the object is created — the upload — while the index row's
    # own `expireAt` is stamped when the row is OPENED, before a byte has moved,
    # and is never refreshed afterwards. Naming the arrival is the half a person
    # can check against the support code they were just handed.
    if BUNDLE_LIFECYCLE_VERIFIED:
        lines.append("and it is deleted automatically 30 days after it arrives")
    return lines


def _queued_bundle_rows_path() -> "Path":
    return _logs_root() / "pending-bundle-rows.jsonl"


def _queue_log_bundle_row(owner_uid: str, code: str, patch: dict,
                          device_id: str = "") -> None:
    """Park an index-row write that could not go out now.

    ⭐ The row appears LATE rather than never. During the incident this feature
    exists for, Firestore was unreachable — so the upload can succeed through
    our own host while the row that names it cannot be written at all."""
    try:
        path = _queued_bundle_rows_path()
        path.parent.mkdir(parents=True, exist_ok=True)
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"ownerUid": owner_uid, "code": code,
                                 "deviceId": device_id, "patch": patch,
                                 "at": _utc_iso()}) + "\n")
    except Exception:
        pass


def _drain_queued_log_bundle_rows() -> int:
    """Try the parked row writes again. Returns how many landed.

    Reads the whole file, rewrites what is still owed. Best-effort and silent
    when there is nothing parked, because this runs at the top of every
    command."""
    path = _queued_bundle_rows_path()
    try:
        lines = [ln for ln in path.read_text(encoding="utf-8").splitlines() if ln.strip()]
    except OSError:
        return 0
    if not lines or not _firebase_db:
        return 0
    still_owed, landed = [], 0
    for line in lines:
        try:
            row = json.loads(line)
        except Exception:
            continue  # unparseable — drop it rather than retry forever
        # ⛔ Replays the OPEN and then the patch, in that order. Replaying the
        # patch alone as a create is what the rule refuses — the defect this
        # helper existed to work around and was itself reproducing.
        owner = row.get("ownerUid") or ""
        code = row.get("code") or ""
        if (_open_log_bundle_row(owner, code, row.get("deviceId") or "")
                and _write_log_bundle_status(owner, code, row.get("patch") or {})):
            landed += 1
        else:
            still_owed.append(line)
    try:
        if still_owed:
            path.write_text("\n".join(still_owed) + "\n", encoding="utf-8")
        else:
            path.unlink()
    except OSError:
        pass
    if landed:
        log(f"[send-logs] {landed} parked bundle row(s) reached the account")
    return landed


def _post_bundle_to_ingest(local_path: "Path", code: str,
                           email: "str | None" = None) -> "str | None":
    """Last live rung: POST the bundle to our own host, unauthenticated.

    ⛔ Reached for PAIRED machines too, not only unpaired ones. The founding
    machine was paired and its Google DNS was dead, so gating this on "never
    paired" would have excluded the one case it was built for."""
    import requests as _requests
    try:
        from auth.v2_flow import FE_BASE_URL as _base
    except Exception:
        _base = "https://superresearch.io"
    url = f"{_base.rstrip('/')}/api/logs/ingest"
    try:
        size = Path(local_path).stat().st_size
    except OSError:
        return None
    if size > BUNDLE_INGEST_MAX_BYTES:
        log(f"[send-logs] bundle is {size} bytes — over the {BUNDLE_INGEST_MAX_BYTES} "
            f"ceiling the unauthenticated route accepts", "WARN")
        return None
    headers = {
        "Content-Type": BUNDLE_CONTENT_TYPE,
        "X-Support-Code": code,
        "X-Install-Id": str(_install_uuid_best_effort() or ""),
        "X-Build": _sr_version(),
    }
    if email:
        headers["X-Contact-Email"] = email
    try:
        with open(local_path, "rb") as fh:
            resp = _requests.post(url, headers=headers, data=fh, timeout=180)
    except Exception as exc:
        log(f"[send-logs] {url} unreachable: {type(exc).__name__}: {exc}", "WARN")
        return None
    if resp.status_code != 200:
        log(f"[send-logs] ingest refused: HTTP {resp.status_code} "
            f"{str(resp.text)[:200]}", "WARN")
        return None
    try:
        return str((resp.json() or {}).get("supportCode") or code)
    except Exception:
        return code


def _format_run_choice(index: int, row: dict) -> str:
    """One numbered line in the terminal's run list.

    ⛔⛔ NO TOPIC AND NO TITLE, and not because they are unavailable to a person
    standing at their own machine — they hold every one of these files on their
    own disk. It is because there is nowhere to READ one from. A run folder
    carries no topic and no title: `_run_log_folder_name` has no `run_id`
    parameter precisely so a topic cannot reach a folder name, and `meta.json`
    and `events.json` carry neither. The only topic text anywhere in a run
    folder is inside `run.log`, and a parser over user-controlled text feeding a
    disclosure decision is exactly what this wave's design rejected.

    ⭐ So the row is what the machine actually knows: when it started, how it
    ended, and how big it is. That is enough to find "the one from Tuesday that
    hung", which is the question somebody at a terminal is actually asking."""
    started = str(row.get("startedUtc") or "")[:19].replace("T", " ") or "unknown time"
    status = str(row.get("status") or "unknown")
    size_kb = int(row.get("sizeBytes") or 0) // 1024
    return f"{index:>3}. {started}  {status:<14} {size_kb:>6} KB"


def _parse_run_choice(answer: str, count: int) -> "list[int] | None":
    """Which of `count` numbered rows an answer names, or None meaning "unreadable".

    ⛔⛔ REFUSES RATHER THAN GUESSING, on this file's own standing rule: a
    malformed request must never resolve toward MORE collection than was agreed
    to. `1,3` and `1 3` and `1, 3` all mean the same thing; `1-3` does NOT mean
    a range here and is refused, because a person who meant "1 and 3" and typed
    a dash would otherwise silently send 2 as well.

    ⭐ `all` and an empty answer are both explicit and both mean something. Empty
    is the machine-level bundle — the pairing-failure case, which is exactly when
    there are no runs to choose from — and it is the DEFAULT because it is the
    smallest thing the command can do.

    Returns 0-based indices, de-duplicated, in the order the person typed them."""
    text = (answer or "").strip().lower()
    if not text:
        return []
    if text in ("all", "a", "*"):
        return list(range(count))
    out: "list[int]" = []
    for token in re.split(r"[,\s]+", text):
        if not token:
            continue
        if not token.isdigit():
            return None
        n = int(token)
        if n < 1 or n > count:
            return None
        if (n - 1) not in out:
            out.append(n - 1)
    return out


def _choose_runs_interactively(rows: "list[dict]") -> "list[str] | None":
    """Print the numbered list and read a choice. None means "the person quit".

    ⛔ THE OWNER AT THE MACHINE SEES EVERY RUN ON IT, including the ones no
    account can be attributed to — which today is all of them, since no shipped
    build recorded a submitter. They already hold these files on their own disk,
    so listing them grants nothing; withholding them would only hide the machine's
    whole history from the one person who can act on it."""
    if not rows:
        print(f"  {_c(_DIM, 'This machine is holding no run logs.')}")
        return []
    print()
    print(f"  {_c(_BOLD, 'Runs this machine still has logs for')}")
    for i, row in enumerate(rows, 1):
        print(f"    {_c(_DIM, _format_run_choice(i, row))}")
    print()
    # ⛔⛔ BUILT OUTSIDE THE f-STRING, and this is a portability fix rather than a
    # style one. A LINE BREAK inside an f-string replacement field is Python
    # 3.12+ syntax; `pyproject` declares `requires-python = ">=3.11"`, so on the
    # floor this repo supports the original form is a SyntaxError at IMPORT and
    # the whole backend fails to start. Caught by ruff, which reported it as
    # `invalid-syntax` rather than a lint — the delta that made the count 11.
    _hint = ("Type numbers like  1,3  ·  [all] every run  ·  "
             "[Enter] none, machine logs only")
    print(f"    {_c(_DIM, _hint)}")
    for _ in range(3):
        try:
            answer = input(f"  {_c(_ACCENT, '>')}  Choose ")
        except (EOFError, KeyboardInterrupt):
            print()
            return None
        picked = _parse_run_choice(answer, len(rows))
        if picked is not None:
            # ⭐ ECHO WHAT WAS UNDERSTOOD, like the yes/no reader does. A silent
            # interpretation is how "2" became a yes at a prompt that never
            # offered it, which is the defect that produced that reader.
            if picked:
                print(f"     {_c(_DIM, f'Sending {len(picked)} run(s).')}")
            else:
                print(f"     {_c(_DIM, 'Sending no runs — this machine' + chr(39) + 's own logs only.')}")
            return [str(rows[i].get("name")) for i in picked]
        print(f"     {_c(_WARN, 'Numbers from the list, or ' + chr(39) + 'all' + chr(39) + ', or Enter for none.')}")
    # ⛔ GIVES UP OUT LOUD rather than applying a default nobody chose — the same
    # rule `_ask_yes_no_sync` gives up under, for the same reason.
    print(f"  {_c(_WARN, '⚠')}  Could not read a choice. Nothing was sent.")
    return None


def cmd_send_logs(assume_yes: bool = False, email: "str | None" = None,
                  runs: "int | None" = None, select: bool = False) -> int:
    """`superresearch --send-logs` — hand the logs over from the terminal.

    Returns a process exit code. 0 means something landed OR the local file was
    written, because the local file IS a successful outcome: it is what a person
    attaches to an email when their network is the thing that is broken."""
    _branded_header("nuntius", _BOLD + _ACCENT, "hand it over")

    # ⭐ THE CHOICE COMES BEFORE THE DISCLOSURE, on purpose. The consent screen
    # names a number of runs, and until the person has chosen there is no number
    # to name — printing "at most 30" and then asking for two would describe a
    # bundle nobody is about to build.
    only_runs: "list[str] | None" = None
    if select:
        chosen = _choose_runs_interactively(_scan_run_folders())
        if chosen is None:
            return 130
        only_runs = chosen

    print()
    print(f"  {_c(_BOLD, 'What leaves this machine')}")
    n_runs = BUNDLE_MAX_RUNS if runs is None else max(
        BUNDLE_MIN_RUNS, min(int(runs), BUNDLE_MAX_RUNS))
    for line in _send_logs_consent_lines(
            len(only_runs) if only_runs is not None else n_runs,
            chosen_exactly=only_runs is not None):
        print(f"    {_c(_DIM, '•')}  {line}")
    print()
    print(f"  {_c(_BOLD, 'What does not')}")
    for line in ("passwords", "browser cookies or profiles", "your API keys"):
        print(f"    {_c(_DIM, '•')}  {line}")
    print()

    if not assume_yes:
        try:
            if not _ask_yes_no_sync("Send this to the team?", default=False):
                print(f"  {_c(_DIM, 'Nothing was sent.')}")
                return 0
        except (EOFError, KeyboardInterrupt):
            print()
            print(f"  {_c(_DIM, 'Nothing was sent.')}")
            return 130

    code = _mint_support_code()
    dest = _logs_root() / "outgoing" / f"support-{code}{BUNDLE_SUFFIX}"

    # ── Rung 0: the file. Always, first, and printed. ──
    try:
        summary = _build_log_bundle(dest, support_code=code, max_runs=n_runs,
                                    only_runs=only_runs)
    except Exception as exc:
        print(f"  {_c(_WARN, '⚠')}  Could not build the log bundle: {exc}")
        print(f"  {_c(_DIM, 'The raw logs are still here:')}  "
              f"{_c(_BOLD, str(_logs_root()))}")
        return 1
    _n_runs = summary["runCount"]
    _n_sessions = summary["sessionCount"]
    _n_bytes = summary["sizeBytes"]
    print(f"  {_c(_OK, '✓')}  Bundle written  {_c(_BOLD, str(dest))}")
    print(f"     {_c(_DIM, f'{_n_runs} run(s), {_n_sessions} session(s), {_n_bytes} bytes')}")
    _n_dropped = len(summary["droppedForSize"])
    if _n_dropped:
        # ⛔ Never a silent truncation: a bundle that quietly dropped the run
        # somebody is asking about reads as complete coverage.
        print(f"     {_c(_DIM, f'{_n_dropped} older item(s) left out for size')}")
    print()

    landed_via = None
    device_id = load_device_id()
    id_token = _fresh_user_mode_id_token()
    owner_uid = (_decode_jwt_claims(id_token) or {}).get("ownerUid") if id_token else None

    # ── Rung 1: the authenticated upload. ──
    if id_token and owner_uid and device_id:
        object_path = _upload_log_bundle_via_storage_rest(dest, owner_uid, device_id, code)
        if object_path:
            landed_via = "your account"
            patch = {"status": "done", "objectPath": object_path,
                     "runCount": int(summary["runCount"]),
                     "sessionCount": int(summary["sessionCount"]),
                     "sizeBytes": int(summary["sizeBytes"])}
            # ⛔⛔ THE ROW IS THE ONLY THING CLEAR SHARED LOGS CAN SEE. It walks
            # rows, not objects — so a send whose row never lands leaves a
            # readable bundle in the bucket that the privacy button cannot
            # reach, on a product where no lifecycle rule exists yet. A terminal
            # process has no Firestore client at all, so in practice both writes
            # park and a serve process replays them.
            if not (_open_log_bundle_row(owner_uid, code, device_id or "", "")
                    and _write_log_bundle_status(owner_uid, code, patch)):
                _queue_log_bundle_row(owner_uid, code, patch,
                                      device_id=device_id or "")
    elif not id_token:
        print(f"  {_c(_DIM, 'This machine could not sign in, so the account route is')} "
              f"{_c(_DIM, 'unavailable — trying our own host instead.')}")

    # ── Rung 2: our own host, unauthenticated. Paired machines included. ──
    if not landed_via:
        _server_code = _post_bundle_to_ingest(dest, code, email=email)
        if _server_code:
            landed_via = "superresearch.io"
            # ⛔ THE SERVER'S CODE WINS ON THIS PATH. There is no uid and no
            # deviceId to scope an object under here, so a caller-chosen folder
            # name would let anyone who learned a code overwrite the bundle it
            # names — the route therefore mints its own and ignores ours.
            # Printing the local one would send a person into a support
            # conversation quoting a code that indexes nothing.
            #
            # ⛔⛔ AND THE ARCHIVE ON DISK HAS TO FOLLOW. Until 2026-08-24 only
            # the printed code changed: the zip stayed named under the LOCAL
            # code we had just discarded, so `find_support_bundle.py <CODE>`
            # — the script whose whole job is to locate it, run with the code
            # support just quoted back — found nothing on the machine that sent
            # it. Found by cross-verification. Renaming is best effort: the
            # bundle already reached the server, so a failure here must not turn
            # a successful send into an error.
            if _server_code and _server_code != code:
                _renamed = dest.with_name(f"support-{_server_code}{BUNDLE_SUFFIX}")
                try:
                    dest.replace(_renamed)
                    dest = _renamed
                except Exception as _exc:
                    log(f"[send-logs] sent as {_server_code} but could not rename "
                        f"the local archive from {dest.name}: {_exc}", "WARN")
            code = _server_code

    print()
    tm.tm_emit(tm.Ev.SEND_LOGS_RESULT, ok=bool(landed_via),
               count=int(summary["runCount"]))
    if landed_via:
        print(f"  {_c(_OK, '✓')}  Sent via {_c(_BOLD, landed_via)}")
        print(f"  {_c(_BOLD, 'Your support code is')}  {_c(_BOLD + _ACCENT, code)}")
        print(f"  {_c(_DIM, 'Quote it to us and we can find your logs.')}")
        return 0

    print(f"  {_c(_WARN, '⚠')}  Nothing could be sent from this machine right now.")
    print(f"  {_c(_DIM, 'That is usually the network itself — run')}  "
          f"{_c(_BOLD, _PROG + ' --doctor')}  {_c(_DIM, 'to see which part.')}")
    print(f"  {_c(_DIM, 'The bundle is on disk and can be attached to an email:')}")
    print(f"     {_c(_BOLD, str(dest))}")
    return 0


def _doctor_share_logs_line() -> str:
    """What to say when the diagnosis does not get them moving.

    ⭐ Owner, 2026-08-17: every failure a person can be left holding should
    point at the way to hand it over — "so the user would know that he can share
    the logs on failure to the dev team and get it sorted".
    ⭐ 2026-08-18, WAVE 2: the command now exists, so this line names it. Until
    then it deliberately did NOT — naming a command that was not there is the
    exact defect that wave set out to remove.

    ⛔⛔ 2026-08-19, OWNER DECISION: THE MIDDLE ROUTE IS GONE. It read "or send the
    file yourself — ~/.super-research/logs/backend.log", and that file is the
    WORST answer available on three counts, measured on this machine:
      • 44 MB — not emailable, and the one file that carries no dates at all;
      • it is only the raw stdout capture. It contains NONE of the per-run folders
        and NONE of the session logs, which are the evidence worth having;
      • `--send-logs`, named one clause earlier, writes ~600 KB containing all
        three and prints where it put it.
    So the route existed to spare someone a terminal, and spent that on sending
    the least useful bytes on the disk while omitting the best. Report Bug already
    covers "no terminal", so dropping it loses no reach.

    ⭐ AND THE FILE IS STILL OFFERED — by the command itself. `cmd_send_logs`
    writes the bundle FIRST and prints its path whether or not the upload lands
    ("Rung 0: the file. Always, first, and printed"), so a person with no network
    is told what to attach without this line having to guess a path.
    """
    return (f"Still stuck? Run {_PROG} --send-logs — it packs your logs into one "
            f"file, sends it if it can, and prints where the file is if it cannot. "
            f"No terminal? Use Report Bug on the web app's Settings page.")


def _remedy_serve() -> str:
    """Start the backend in this terminal, now."""
    return ("python research.py --serve  — start it in this terminal now; "
            "it stops when you close the window")


def _remedy_resurrect() -> str:
    """Install the background supervisor instead.

    ⛔⛔ AUTHORED ONCE, ON PURPOSE. Two findings prescribe this command — a
    missing supervisor and a stopped server — and on 2026-08-18 they each spelled
    it out in their own words. The de-duplication compared whole strings, so two
    phrasings of ONE command both survived and the reader was told to run
    `--resurrect` twice in a three-step list. A remedy written in two places is a
    remedy that will disagree with itself; the fix is one author, not a cleverer
    comparison."""
    return ("python research.py --resurrect  — install the background "
            "supervisor, so the backend starts at login and restarts itself "
            "after a crash, a logout or a reboot")


def _dedupe_actions(actions: "list[str]") -> "list[str]":
    """Keep the first occurrence of each step, in order.

    Extracted so it can be CALLED by a test. The previous version was three lines
    inline in `run_doctor`, and the test that was supposed to cover it asserted
    the code existed rather than that a duplicate did not survive — so it passed
    while the duplicate shipped."""
    seen: "set[str]" = set()
    out = []
    for a in actions:
        if a in seen:
            continue
        seen.add(a)
        out.append(a)
    return out


def _remedy_reinstall() -> str:
    """The command that actually repairs a broken install — for THIS install.

    ⛔ 2026-08-17. Four separate messages prescribed `pip install -r
    requirements.txt`, and a pipx install has no requirements.txt and never has
    had one. The supervisor's abort was the worst of them: it built a path
    under the LOG directory (`~/.super-research/logs/requirements.txt`), which
    exists on no machine of either kind. So the one instruction printed at the
    moment the product stopped working was guaranteed to fail, and then the
    reader has no second idea.

    ⭐ `--force` rather than a plain install: pipx treats re-installing an
    already-present package as a no-op AND exits 0, so a plain install would
    report success while changing nothing.
    """
    if _is_source_checkout():
        return "pip install -r requirements.txt"
    return "pipx install --force superresearch"


def _version_gt(a: str, b: str) -> bool:
    """True if version string `a` is strictly newer than `b`. Tolerant numeric
    component compare (1.0.10 > 1.0.9); non-numeric suffixes are ignored. Returns
    False on any parse error so a weird version never spams an upgrade nudge."""
    def _parse(v: str) -> list:
        out = []
        for chunk in str(v).split("."):
            digits = ""
            for ch in chunk:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            out.append(int(digits) if digits else 0)
        return out
    try:
        pa, pb = _parse(a), _parse(b)
        n = max(len(pa), len(pb))  # zero-pad so 1.0 == 1.0.0 (no false 'newer')
        pa += [0] * (n - len(pa))
        pb += [0] * (n - len(pb))
        return pa > pb
    except Exception:
        return False


def _latest_on_pypi(*, force: bool = False) -> "str | None":
    """Latest superresearch version published on PyPI (RAW — regardless of the
    installed version), or None if it can't be determined (source checkout /
    offline / timeout / parse error).

    Cheap + safe by construction: skips entirely on a source checkout; caches the
    PyPI answer to ~/.super-research/.version_check.json for 24h (so it costs at
    most ONE short network call per day, shared across all commands/workers);
    fail-silent so it can NEVER block or break a command. The 2.5s timeout only
    ever applies once per day on a cache miss. `force=True` bypasses the cache
    READ for a FRESH answer (used by an explicit `--update` — an 'update now' must
    not be decided off a stale 24h cache); it still refreshes the cache."""
    if _is_source_checkout():
        return None
    import json as _j
    import time as _t
    cache = _STATE_DIR / ".version_check.json"
    if not force:
        try:
            if cache.exists():
                data = _j.loads(cache.read_text())
                if _t.time() - float(data.get("checked_at", 0)) < 86400:
                    return (data.get("latest") or None)
        except Exception:
            pass
    latest = ""
    try:
        import urllib.request as _u
        with _u.urlopen("https://pypi.org/pypi/superresearch/json", timeout=2.5) as r:
            latest = ((_j.loads(r.read().decode("utf-8")).get("info") or {}).get("version")) or ""
    except Exception:
        latest = ""
    # Only refresh the cache on a SUCCESSFUL fetch. A failed fetch (offline /
    # >2.5s timeout) must NOT overwrite a previously-cached good version with ""
    # — with force=True (the explicit `--update` path, which is exactly when the
    # network is likely down) that clobber would suppress the "update available"
    # nudge on BOTH the CLI and the FE (via the heartbeat's updateAvailable) for
    # up to 24h. On failure leave the cache untouched so the last known-good
    # value keeps surfacing the update; the next call simply retries.
    if latest:
        try:
            cache.parent.mkdir(parents=True, exist_ok=True)
            cache.write_text(_j.dumps({"checked_at": _t.time(), "latest": latest}))
        except Exception:
            pass
    return latest or None


def _check_newer_version(*, force: bool = False) -> "str | None":
    """Return the latest superresearch version published on PyPI IF it is newer
    than the installed one, else None — a pip-style "new version available" nudge.
    Thin wrapper over `_latest_on_pypi()` (24h-cached); returns None on a source
    checkout, offline, or when already current. `force=True` bypasses the 24h
    cache for a fresh check (the app's on-demand "Check for updates").

    A source checkout is never PyPI-updatable (it updates via `git pull`, and
    `--update` refuses it), so it must never advertise an update. Gate on the
    authoritative PATH check `_is_source_checkout()` — NOT the `_sr_version()`
    string below: an editable / `pip install -e .` checkout has discoverable
    package metadata, so `_sr_version()` returns a real "0.1.4" that slips past
    the `startswith("(")` test (the VivobookPro leak)."""
    if _is_source_checkout():
        return None
    cur = _sr_version()
    if not cur or cur.startswith("("):
        return None
    latest = _latest_on_pypi(force=force)
    return latest if (latest and _version_gt(latest, cur)) else None


# Per-process memo so the Next-block renderer doesn't re-check every call.
_VERSION_NOTICE_SENTINEL = object()
_VERSION_NOTICE_MEMO: object = _VERSION_NOTICE_SENTINEL


def _newer_version_notice() -> "str | None":
    """Memoized `_check_newer_version()` — computed at most once per process."""
    global _VERSION_NOTICE_MEMO
    if _VERSION_NOTICE_MEMO is _VERSION_NOTICE_SENTINEL:
        try:
            _VERSION_NOTICE_MEMO = _check_newer_version()
        except Exception:
            _VERSION_NOTICE_MEMO = None
    return _VERSION_NOTICE_MEMO  # type: ignore[return-value]


def _device_version_fields(*, force: bool = False) -> dict:
    """Version fields the heartbeat publishes to the device doc: `version` (the
    BE's running package version) and `updateAvailable` (the newer version on
    PyPI, or None when current). The FE reads these to show the backend version +
    an update prompt. Sync (file read + 24h-cached PyPI); call OFF the event loop.
    `force=True` does a FRESH PyPI check (the app's on-demand "Check for updates"
    device command).

    A SOURCE CHECKOUT yields version None + updateAvailable None: the app then
    shows "Backend version unknown" and offers no update, because a dev tree isn't
    a pipx-managed build and can't be updated from the app (it updates via
    `git pull`). Gate on the authoritative PATH check `_is_source_checkout()`, NOT
    on the `_sr_version()` string — an editable / `pip install -e .` checkout has
    discoverable metadata, so `_sr_version()` returns a real "0.1.4" and the old
    `startswith("(")` test leaked a version for a source-paired device (the
    VivobookPro bug). Offline / not-installed also yields None."""
    if _is_source_checkout():
        # `sourceCheckout` lets the app show "Source checkout · update with git
        # pull" and hide the Check/Update control — distinct from a pipx build
        # that just hasn't reported its version yet (offline/just-started), which
        # is also version None but SHOULD keep Check.
        return {"version": None, "updateAvailable": None, "sourceCheckout": True,
                "servingVersion": None}
    try:
        _v = _sr_version()
        version = _v if (_v and not _v.startswith("(")) else None
    except Exception:
        version = None
    try:
        update_available = _check_newer_version(force=force)  # newer-than-installed or None
    except Exception:
        update_available = None
    # ⭐⭐ THE TWO NUMBERS ARE NOT THE SAME NUMBER, and publishing only the first
    # is what made the app's Restart button unreachable.
    #
    #   `version`        — what is ON DISK. `_sr_version()` re-reads the
    #                      dist-info, so it flips to the new release THE INSTANT
    #                      pipx finishes, inside a process still executing the
    #                      old code.
    #   `servingVersion` — what THIS PROCESS is executing, frozen at import.
    #
    # Between an install and a restart those disagree, and that disagreement IS
    # the definition of "a restart is owed". With only the disk number published,
    # the app compared it against the update target, found them equal, and
    # concluded the update was finished — so it hid the Restart control at
    # exactly the moment it was needed, and treated a successful restart (which
    # moves nothing the app could see) as the backend failing to come back.
    #
    # ⭐ Published on the ordinary heartbeat rather than recorded once, which is
    # what makes it self-correcting: the restarted process publishes its own boot
    # version and the disagreement disappears with no one having to clear a flag.
    # ⛔ Deliberately NOT folded into `updateStatus` — that record belongs to an
    # update in flight, and a heartbeat writing into it would race the update it
    # is describing.
    _sv = _serving_version()
    serving = _sv if (_sv and not _sv.startswith("(")) else None
    return {"version": version, "updateAvailable": update_available,
            "sourceCheckout": False, "servingVersion": serving}


def _pipx_cmd() -> "list[str] | None":
    """How to invoke pipx from an INSTALLED build. pipx lives in the user's
    Python, NOT this app's isolated pipx venv — so NEVER use sys.executable (the
    venv's python has no pipx module; that's the bug that made `--update` /
    `--uninstall` wrongly report 'pipx not found'). Prefer the `pipx` shim on
    PATH; else the shim in the pip --user script dir that `pipx ensurepath` only
    wired for FUTURE shells; else a PATH python's `-m pipx`."""
    import shutil as _shutil
    # Absolute, not the bare name: this list gets baked into the DETACHED waiter's
    # argv, and the waiter runs with a PATH we deliberately widen (see
    # _lifecycle_env). A bare "pipx" would be re-resolved against that wider PATH
    # and could pick a DIFFERENT pipx than the one this process validated.
    if _which_pipx := _shutil.which("pipx"):
        return [_which_pipx]
    # The install one-liner puts pipx there with `pip install --user`, whose
    # script dir is OFF the default PATH until a NEW shell picks up
    # `pipx ensurepath` — so a machine that DID install via the one-liner can have
    # a perfectly good pipx that `which` can't see, and `--update` wrongly bailed
    # with "pipx not found" (reported on a macOS Research Computer, where
    # pip --user lands the shim in ~/Library/Python/X.Y/bin, never on PATH). Probe
    # the known user-script dirs directly (newest macOS pythonX.Y first).
    import glob as _glob
    _home = os.path.expanduser("~")
    _shims = sorted(
        _glob.glob(os.path.join(_home, "Library", "Python", "*", "bin", "pipx")),
        reverse=True,
    ) + [os.path.join(_home, ".local", "bin", "pipx")]
    for _shim in _shims:
        if os.path.isfile(_shim) and os.access(_shim, os.X_OK):
            return [_shim]
    # Else any python with pipx importable as a module — including the versioned
    # interpreters the installer prefers (the default `python3` may not be the one
    # pip --user'd pipx into).
    for _cand in ("python", "py", "python3", "python3.13", "python3.12", "python3.11"):
        _exe = _shutil.which(_cand)
        if not _exe:
            continue
        try:
            r = subprocess.run([_exe, "-m", "pipx", "--version"],
                               capture_output=True, text=True, timeout=20)
            if r.returncode == 0:
                return [_exe, "-m", "pipx"]
        except Exception:
            pass
    return None


def _cgroup_escape_prefix() -> "list[str]":
    """Prefix that runs a detached helper OUTSIDE the supervisor's cgroup.

    The APP-DRIVEN update runs from inside a serve worker, a child of the
    --daemon-loop that IS the systemd unit's main process. When the upgrade kills
    the daemon-loop (so pipx can rebuild the venv) and the helper then restarts the
    unit, systemd's default KillMode=control-group would reap the helper mid-flight
    — the same cgroup trap the agent bridge hits (the update "starts" but the
    version never bumps → the app's 'taking longer than expected'). `systemd-run
    --user --collect` runs it in its OWN transient scope so it survives. Empty list
    off-Linux, without systemd-run, or with no user manager reachable (the CLI
    `--update` already runs outside the cgroup, in the user's terminal) — never
    worse than before."""
    import shutil as _shutil
    if not sys.platform.startswith("linux"):
        return []
    exe = _shutil.which("systemd-run")
    if not exe:
        return []
    if not (os.environ.get("XDG_RUNTIME_DIR") or os.environ.get("DBUS_SESSION_BUS_ADDRESS")):
        return []
    return [exe, "--user", "--collect", "--quiet", "--"]


def _installed_sr_entry() -> "str | None":
    """Path to the persistently-installed `superresearch` console script (so the
    post-upgrade restart runs the NEW build). Prefer the pipx shim on PATH; else
    resolve it under the pipx venvs dir. None if it can't be located."""
    import shutil as _shutil
    shim = _shutil.which("superresearch")
    if shim:
        return shim
    pipx = _pipx_cmd()
    if pipx is None:
        return None
    try:
        r = subprocess.run([*pipx, "environment", "--value", "PIPX_LOCAL_VENVS"],
                           capture_output=True, text=True, timeout=30)
        venvs = (r.stdout or "").strip()
        if r.returncode != 0 or not venvs:
            return None
        rel = ("Scripts", "superresearch.exe") if sys.platform == "win32" else ("bin", "superresearch")
        cand = Path(venvs).joinpath("superresearch", *rel)
        return str(cand) if cand.exists() else None
    except Exception:
        return None


# Where the detached waiter leaves the upgrade's real outcome for the NEXT backend
# to publish. The handoff has to go through disk: the waiter has no credentials (it
# runs on a non-venv python so it can survive the venv rebuild) and the backend that
# would have reported is deliberately dead while the rebuild happens. See
# _LIFECYCLE_WAITER and _consume_pending_update_result.
_UPDATE_RESULT_PATH = _STATE_DIR / "update_result.json"

# Written when the waiter is LAUNCHED, so an update that dies before it can leave a
# result is still reportable. The result sentinel above only covers a waiter that
# lived long enough to write one — and the oldest recorded instances of this bug are
# precisely the ones where it did not: five `update` commands on 07-21..07-24 whose
# worker was killed mid-launch, leaving no pipx run, no log line and no status at
# all. See `_update_intent_verdict`.
_UPDATE_INTENT_PATH = _STATE_DIR / "update_intent.json"
# The waiter's step-by-step journal. Separate from the outcome sentinel ON PURPOSE:
# the sentinel is written only once the package manager has RETURNED, so the one
# failure that most needs evidence — an upgrade that never finishes — could never
# produce one. The journal is appended as each step begins, so it survives a hang,
# a SIGKILL, and a machine that slept through the whole thing.
_UPDATE_JOURNAL_PATH = _STATE_DIR / "update_journal.jsonl"

# Detached lifecycle waiter (run by a NON-venv Python): waits for THIS process
# to exit, then runs `pipx <action> superresearch`. Required because
# `--update`/`--uninstall` run from the very venv pipx must rebuild/delete — on
# Windows you cannot delete files a running process has open, which is what left
# a half-deleted venv husk + a WinError-5 traceback when uninstall ran inline.
_LIFECYCLE_WAITER = r'''
import os, sys, time, subprocess
pid = int(sys.argv[1]); rest = sys.argv[2:]
# ── Progress journal ────────────────────────────────────────────────────────
# ⭐⭐ 2026-08-06 — WHY THIS EXISTS. The reported failure is "the app-driven update
# hangs forever", and until now that produced NO evidence whatsoever: the only
# write this script made was the outcome sentinel AFTER the package manager
# returned, so a package manager that never returns left nothing at all — no
# outcome, no timings, no indication of how far it got. The one thing the operator
# needed to root-cause it was the one thing that could not survive it.
#
# So: an append-only journal, written at every step, BEFORE the step that can
# hang. Stdlib only and no credentials, same as the rest of this script — it is a
# plain file, and whichever backend comes up next carries it to the app.
#
# Append, never rewrite: a crash mid-journal must leave the earlier lines intact.
_jrnl = os.environ.get("DG_LIFECYCLE_JOURNAL") or ""
_t0 = time.time()
def _note(step, **kw):
    if not _jrnl:
        return
    try:
        import json as _j
        rec = {"t": round(time.time() - _t0, 2), "step": step}
        rec.update(kw)
        with open(_jrnl, "a", encoding="utf-8") as _f:
            _f.write(_j.dumps(rec) + "\n")
    except Exception:
        pass
_note("waiter_started", pid=os.getpid(), watching=pid,
      python=sys.executable, platform=sys.platform)
# CLAIM the launch record before anything else. The spawner cannot record a
# trustworthy pid: on Linux the upgrade is submitted through `systemd-run`, a
# FRONT-END that exits in milliseconds, so `Popen.pid` names a process that is
# already dead — and the liveness check that decides "the upgrade helper stopped
# without reporting back" would then declare every Linux update failed about
# thirty seconds in, while pipx is still installing. Only this process knows which
# pid is actually doing the work, so only this process writes it.
_intent = os.environ.get("DG_LIFECYCLE_INTENT") or ""
if _intent:
    try:
        import json as _json
        with open(_intent, "r", encoding="utf-8") as _f:
            _rec = _json.load(_f)
        _rec["waiter_pid"] = os.getpid()
        with open(_intent, "w", encoding="utf-8") as _f:
            _json.dump(_rec, _f)
    except Exception:
        pass
# rest = [<pipx cmd...>] optionally followed by "--then--" <restart cmd...>. The
# restart cmd (e.g. `superresearch --restart`) cycles the SUPERVISOR onto the
# freshly-rebuilt venv — Restart=always alone races the rebuild and would relaunch
# the OLD in-memory build, so the app-driven update needs an explicit restart.
if "--then--" in rest:
    _i = rest.index("--then--"); cmd = rest[:_i]; after = rest[_i + 1:]
else:
    cmd = rest; after = []
def _alive(p):
    if sys.platform == "win32":
        import ctypes
        h = ctypes.windll.kernel32.OpenProcess(0x00100000, 0, p)  # SYNCHRONIZE
        if not h:
            return False
        r = ctypes.windll.kernel32.WaitForSingleObject(h, 0)
        ctypes.windll.kernel32.CloseHandle(h)
        return r == 0x00000102  # WAIT_TIMEOUT -> still running
    try:
        os.kill(p, 0); return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
_note("waiting_for_launcher_exit", cmd=cmd, restart=after)
_waited = 0.0
for _ in range(120):  # wait up to ~60s for the launcher to exit
    if not _alive(pid):
        break
    time.sleep(0.5); _waited += 0.5
_note("launcher_gone" if not _alive(pid) else "launcher_still_alive",
      waited_s=_waited)
time.sleep(2)  # grace for the OS to release the venv's file handles
# ⭐ A CEILING, because the reported symptom is a hang. `subprocess.run(cmd)` with
# no timeout is an unbounded wait on a package manager that can block on a network
# read, a lock, or a credential prompt that nobody will ever answer — and while it
# blocks, this process holds the only knowledge of the outcome and publishes
# nothing, so the app spins until its own timeout with no reason to show. Twenty
# minutes is far above a real install and far below "forever".
# On timeout: kill the whole TREE, then report it as a FAILURE with a distinguishable
# reason, because an update that never finished is not an update that succeeded.
#
# ⭐⭐ 2026-08-06 — WHY THE TREE AND NOT THE CHILD. `subprocess.run(timeout=)` kills
# only the process it started, and the process it starts here is a FRONT-END: pipx
# shells out to pip or uv, so the thing actually holding the network read / the lock
# / the venv is a GRANDCHILD, and it keeps running after the timeout "handled" it.
# On Windows that is not untidy, it is the husk this whole waiter exists to prevent:
# `free_venv` is true there, so the daemon-loop has already been killed and the
# restart leg is skipped on a nonzero rc — leaving the box offline with a surviving
# grandchild holding the venv's DLLs open, which is exactly what makes the NEXT
# repair attempt fail too. So: own the group, then kill the group, then PROVE it is
# gone, and journal it either way — an orphan we could not reap is the single most
# useful thing the next operator can be told.
_TIMEOUT_S = 1200


def _kill_tree(proc, pgid):
    """SIGTERM then SIGKILL the package manager AND its descendants.

    Returns True only when nothing of the tree is left. POSIX: the child was spawned
    with `start_new_session`, so it leads its own group and killing that group cannot
    reach us — and once the group is empty `killpg` raises ProcessLookupError, which
    is the only real PROOF available. The direct child has to be reaped before that
    probe, because a zombie keeps its group alive and would read as a survivor.
    Windows has no such group: `taskkill /T` walking the parent-child chain is the
    best available, so 'clean' there means the child itself is gone."""
    if sys.platform == "win32":
        try:
            subprocess.run(["taskkill", "/T", "/F", "/PID", str(proc.pid)],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                           timeout=120)
        except Exception:
            try:
                proc.kill()  # taskkill absent/blocked — at least drop the front-end
            except Exception:
                pass
        try:
            proc.wait(timeout=30)
        except Exception:
            pass
        return proc.poll() is not None
    import signal as _signal
    if pgid == os.getpgid(0):
        # ⛔ REFUSE. The child did not get its own session after all, so this group is
        # OURS — killing it would take this waiter down before it could publish
        # anything, turning a reported timeout back into the silent hang the whole
        # sentinel exists to end. Settle for the front-end and say so honestly.
        try:
            proc.kill()
        except Exception:
            pass
        try:
            proc.wait(timeout=10)
        except Exception:
            pass
        return False
    for _sig in (_signal.SIGTERM, _signal.SIGKILL):
        try:
            os.killpg(pgid, _sig)
        except ProcessLookupError:
            break  # group already empty
        except Exception:
            pass
        try:
            proc.wait(timeout=10)  # reap, so the probe below sees a real absence
        except Exception:
            pass
    if proc.poll() is None:
        return False
    # POLL the emptiness probe; do not ask it once. SIGKILL delivery and reaping
    # are asynchronous — the signal returns as soon as it is queued, and the
    # kernel takes the descendants down and reaps them afterwards. Asking
    # immediately therefore sees a group that is dying but not yet empty, and on
    # a loaded machine that is the ORDINARY outcome, not a rare one.
    #
    # Reporting False there is not a harmless conservatism. It publishes
    # `package_manager_orphan` — "a process from the upgrade survived the kill
    # and may still hold the venv open" — and tells the operator their venv may
    # be inconsistent, about a kill that in fact worked and finished
    # milliseconds later. A path whose entire job is telling the operator the
    # truth about a failed upgrade must not invent a second failure. CI caught
    # this: the same commit passed on one runner and failed on a busier one,
    # while the test's own 8-second wait confirmed the descendant really did die.
    #
    # Bounded, so a group that genuinely will not die is still reported as
    # orphaned — which is the honest answer, and the one this exists to give.
    _deadline = time.time() + 10.0
    while True:
        try:
            os.killpg(pgid, 0)
        except ProcessLookupError:
            return True  # the group is empty — the only real proof available
        except Exception:
            return False  # cannot see it, cannot claim it is gone
        if time.time() >= _deadline:
            return False
        time.sleep(0.1)


_note("package_manager_start", cmd=cmd, timeout_s=_TIMEOUT_S)
_timed_out = False
_orphaned = False
_spawn_kw = {}
if sys.platform == "win32":
    _spawn_kw["creationflags"] = 0x00000200  # CREATE_NEW_PROCESS_GROUP
else:
    # Makes the child a session AND group leader: its pgid is its own pid, the group
    # contains only its descendants, and a Ctrl-C in the launching terminal cannot
    # reach it either.
    _spawn_kw["start_new_session"] = True
try:
    _proc = subprocess.Popen(cmd, **_spawn_kw)
except Exception as _pe:
    rc = 125
    _note("package_manager_error", error=str(_pe)[:200])
else:
    # Read the group id while the child is CERTAINLY alive — after it is reaped
    # `getpgid` raises, and we would have nothing left to aim at. It equals the pid
    # for a session leader; the fallback covers a platform that ignored the request.
    _pgid = _proc.pid
    try:
        _pgid = os.getpgid(_proc.pid)
    except Exception:
        pass
    try:
        rc = _proc.wait(timeout=_TIMEOUT_S)
        _note("package_manager_done", rc=rc)
    except subprocess.TimeoutExpired:
        _timed_out = True
        rc = 124  # conventional timeout code, and never a real pipx exit status
        _note("package_manager_timeout", after_s=_TIMEOUT_S, pid=_proc.pid,
              pgid=_pgid)
        _orphaned = not _kill_tree(_proc, _pgid)
        # ⛔ Say plainly that the install was interrupted MID-FLIGHT. pipx upgrades
        # in place, so a package manager stopped part-way can leave the venv neither
        # the old build nor the new one, and no exit code anywhere records that. The
        # operator repair is the same either way (`superresearch --update` on the
        # machine) but they can only choose it if someone tells them.
        _note("venv_may_be_inconsistent", killed_tree=not _orphaned,
              repair="run superresearch --update on this machine")
        if _orphaned:
            _note("package_manager_orphan", pid=_proc.pid, pgid=_pgid,
                  detail="a process from the upgrade survived the kill and may still "
                         "hold the venv open")
    except Exception as _we:
        rc = 125
        _note("package_manager_error", error=str(_we)[:200])
# Record the outcome BEFORE the restart. This process is the only thing that ever
# learns whether the upgrade actually worked, and it cannot tell the app directly:
# it runs on a NON-venv python by design, so it has no firebase-admin and no
# credentials. Without this sentinel a nonzero pipx exit is invisible — the app was
# already told "started" before pipx even ran, so it spins until its own timeout.
# Written BEFORE the restart on purpose: `--then--` cycles the supervisor, and a
# post-restart write would race the new backend's read of this same file.
_res = os.environ.get("DG_LIFECYCLE_RESULT") or ""
if _res:
    try:
        import json, tempfile
        # ⚠ 2026-08-06 — the tail used to be carried ONLY when rc != 0. The
        # confusing report is an update that claims success while the version does
        # not move, and for exactly that case there was no evidence at all. Always
        # carry it: it costs a bounded read and it is the difference between
        # diagnosing the next one and asking for another reproduction.
        _tail = ""
        try:
            with open(os.environ.get("DG_LIFECYCLE_LOG") or "", "rb") as _f:
                try:
                    _f.seek(-8192, 2)
                except Exception:
                    _f.seek(0)
                _tail = _f.read().decode("utf-8", "replace").strip()[-4000:]
        except Exception:
            pass
        # The journal travels with the outcome, so the app has the step timings
        # without needing a second channel. Bounded from the END — the last steps
        # are the interesting ones — and it is the tail that says where a hang was.
        _journal = ""
        try:
            if _jrnl:
                with open(_jrnl, "r", encoding="utf-8", errors="replace") as _f:
                    _journal = "".join(_f.readlines()[-60:])[-6000:]
        except Exception:
            pass
        _payload = {"action": os.environ.get("DG_LIFECYCLE_ACTION") or "upgrade",
                    "rc": rc, "at": int(time.time() * 1000),
                    "current": os.environ.get("DG_LIFECYCLE_FROM") or "",
                    "latest": os.environ.get("DG_LIFECYCLE_TO") or "",
                    "restarting": bool(after) and rc == 0,
                    "timed_out": _timed_out,
                    # A kill we could not confirm changes the operator's repair — a
                    # surviving process can hold the venv open and make the next
                    # attempt fail the same way — so it travels as its own field
                    # rather than only as a line inside the journal.
                    "orphaned": _orphaned,
                    "journal": _journal,
                    "log_tail": _tail}
        _fd, _tmp = tempfile.mkstemp(dir=os.path.dirname(_res) or ".",
                                     prefix=".update-result-", suffix=".tmp")
        with os.fdopen(_fd, "w") as _f:
            json.dump(_payload, _f)
        os.replace(_tmp, _res)  # atomic — the reader never sees a partial file
    except Exception:
        pass
# Only cycle the supervisor if the upgrade itself succeeded — never restart onto a
# half-built venv.
if after and rc == 0:
    _note("restart_issued", cmd=after)
    try:
        subprocess.run(after)
    except Exception as _re:
        _note("restart_failed", error=str(_re)[:200])
elif after:
    # Deliberately NOT attempted after a timeout either, even though the box may be
    # offline until it is: pipx upgrades in place, so the venv we would be starting
    # could be half-written, and off-Windows the daemon-loop is still alive and
    # SERVING — cycling it onto a half-built venv would break a working machine to
    # chase a broken update. The honest failure plus the repair line beats that.
    _note("restart_skipped", rc=rc, timed_out=_timed_out,
          reason="upgrade did not succeed")
_note("waiter_exit", rc=rc, timed_out=_timed_out, orphaned=_orphaned)
'''


def _path_python() -> "str | None":
    """A Python that will OUTLIVE the venv this process is running from.

    The detached lifecycle waiter keeps running while pipx deletes and rebuilds
    that venv, so the interpreter it is launched with has to live somewhere pipx
    is not about to remove.

    ⭐ Selection is by LOCATION, not by interpreter identity. The previous version
    compared `Path(exe).resolve()` against `Path(sys.executable).resolve()` — but
    on POSIX a venv's python is a SYMLINK to its base, so both sides resolve to
    the same real binary and EVERY candidate was rejected. The unguarded
    `return cands[0]` fallback then supplied the answer, which was right only by
    luck: with the venv's own bin on PATH — which is exactly what `activate`
    does — it returned the venv python itself, the one thing this function exists
    to avoid and the one thing its docstring already forbade. Reproduced
    2026-08-05; it also meant the accompanying guard failed on any POSIX box
    while passing on Windows, where venvs COPY python.exe instead of symlinking.

    Order: a PATH candidate outside the venv, then the interpreter the venv was
    BUILT from (outside it by definition, and the only safe answer when every
    PATH name points back inside), then None. None is honest — the caller treats
    it as "cannot spawn" and prints the manual command, which beats handing the
    waiter an interpreter that is about to be deleted underneath it.
    """
    import shutil as _shutil

    # The venv pipx is about to rebuild. Empty when this is not a venv at all, in
    # which case nothing is being deleted and any candidate will do.
    doomed: "list[Path]" = []
    if sys.prefix != sys.base_prefix:
        doomed.append(Path(sys.prefix))
        try:
            doomed.append(Path(sys.prefix).resolve())
        except OSError:
            pass

    def _is_doomed(exe: str) -> bool:
        # BOTH the literal path and the resolved one: the literal catches the
        # venv's own `bin/python` (whose resolve() points harmlessly outside),
        # and the resolved one catches a symlink from elsewhere INTO the venv.
        here = [Path(exe)]
        try:
            here.append(Path(exe).resolve())
        except OSError:
            pass
        return any(p == d or d in p.parents for p in here for d in doomed)

    for _c in ("py", "python", "python3"):
        exe = _shutil.which(_c)
        if exe and not _is_doomed(exe):
            return exe

    if doomed:
        base = Path(sys.base_prefix)
        for rel in (("bin", "python3"), ("bin", "python"),
                    ("python.exe",), ("Scripts", "python.exe")):
            cand = base.joinpath(*rel)
            try:
                if cand.exists() and not _is_doomed(str(cand)):
                    return str(cand)
            except OSError:
                continue
    return None


def _lifecycle_path_dirs() -> "list[str]":
    """Standard homes for `uv` and the pipx shim, in priority order — prepended to
    the detached waiter's PATH by `_lifecycle_env`. These are the two tools the
    upgrade shells out to; a supervisor's own PATH is far narrower."""
    home = os.path.expanduser("~")
    if sys.platform == "win32":
        local = os.environ.get("LOCALAPPDATA") or os.path.join(home, "AppData", "Local")
        return [
            os.path.join(home, ".local", "bin"),        # uv's own installer + pipx
            os.path.join(local, "Programs", "uv"),
            os.path.join(local, "uv", "bin"),
            os.path.join(home, ".cargo", "bin"),        # `cargo install uv`
        ]
    return [
        "/opt/homebrew/bin",                            # Apple-silicon Homebrew
        "/usr/local/bin",                               # Intel Homebrew + manual installs
        os.path.join(home, ".local", "bin"),            # uv's own installer + pipx
        os.path.join(home, ".cargo", "bin"),
    ]


def _supervisor_path_value() -> str:
    """PATH to bake into the OS supervisor (launchd plist / systemd unit).

    This is not just the supervisor's PATH — it is EVERY CHILD'S PATH: the
    daemon-loop, the serve workers, the browser tooling they shell out to, and the
    detached update waiter. It used to be the literal `/usr/local/bin:/usr/bin:/bin`
    on macOS and unset on Linux (leaving systemd's equally narrow default), neither
    of which contains `/opt/homebrew/bin` or `~/.local/bin`.

    That single omission is the root cause of the app-driven update never
    completing: pipx replays the backend recorded in the venv's metadata, and for a
    uv-built venv it can locate uv ONLY through PATH — so `pipx upgrade` died with
    "the 'uv' executable could not be found" while the identical command from a
    login shell succeeded minutes later. The same gap had already broken `ffprobe`
    once and been patched at that one call site. Deriving it from the same list the
    waiter uses fixes the class instead of the instance.

    The tool homes come FIRST and the system dirs last — the same order a login
    shell ends up with once `brew shellenv` has run, which is the order under which
    every one of these tools was installed and is expected to resolve. Be clear
    about what that trades away: a user-writable directory ahead of /usr/bin means
    anything dropped in `~/.local/bin` shadows the OS copy for every supervised
    child. That is accepted deliberately, because the alternative — system first —
    reintroduces the exact bug, resolving a system tool the user never installed in
    preference to the one they did. The supervisor's own interpreter is immune
    either way: the plist and the unit both exec an ABSOLUTE python path."""
    system = ["/usr/local/bin", "/usr/bin", "/bin", "/usr/sbin", "/sbin"]
    parts: list[str] = []
    seen: set[str] = set()
    for d in [*_lifecycle_path_dirs(), *system]:
        if not d or d in seen:
            continue
        seen.add(d)
        parts.append(d)
    return os.pathsep.join(parts)


# The binaries this product resolves BY NAME rather than by absolute path, so
# these are exactly the ones a search-path ordering can decide. Read off the
# `shutil.which("…")` call sites; a test holds the two lists together.
_PATH_SENSITIVE_TOOLS = ("ffmpeg", "ffprobe", "uv", "pipx")


def _which_all(tool: str, path: str) -> "list[str]":
    """Every directory on `path` that provides `tool`, in resolution order.

    ⭐ `shutil.which` answers only the FIRST, which is what runs — and the
    diagnosis a support bundle needs is the rest of the list, because a second
    copy further along is the difference between "not installed" and "the wrong
    one wins". Deliberately not `shutil.which(mode=…)` in a loop: that cannot
    report the losers at all.
    """
    found: list[str] = []
    seen: set[str] = set()
    for d in (path or "").split(os.pathsep):
        # ⛔ An empty entry means the CURRENT DIRECTORY to the shell, and this
        # report must not say a tool was found because the person happened to be
        # standing next to a file with that name.
        if not d:
            continue
        cand = os.path.join(d, tool)
        for c in ((cand, cand + ".exe", cand + ".cmd", cand + ".bat")
                  if sys.platform == "win32" else (cand,)):
            # ⛔ NO try/except HERE, and it is not an oversight. `os.path.isfile`
            # and `os.access` both absorb OSError and ValueError internally and
            # answer False — including for a path with an embedded null. A guard
            # around them could not fire, which mutation proved by surviving one
            # written to test it.
            if os.path.isfile(c) and os.access(c, os.X_OK) and c not in seen:
                seen.add(c)
                found.append(c)
                break
    return found


def _installed_supervisor_path() -> str:
    """The search path the INSTALLED supervisor entry really exports, or "".

    ⛔⛔ NOT `_supervisor_path_value()`, and the difference is the whole point.
    That function is what THIS build would write. The entry sitting on disk may
    have been written by an older one — the value was a literal
    `/usr/local/bin:/usr/bin:/bin` until 2026-08, with no `/opt/homebrew/bin` in
    it — and until someone re-runs `--resurrect`, every supervised child is
    still using the old one. Reading the file is the only way to know.

    "" when nothing is installed, when the file cannot be parsed, or on Windows,
    where the Scheduled Task bakes no path at all and the child inherits.
    """
    plat = _supervisor_platform()
    try:
        if plat == "Darwin":
            if not _SUPERVISOR_PLIST_PATH.exists():
                return ""
            import plistlib
            with open(_SUPERVISOR_PLIST_PATH, "rb") as fh:
                data = plistlib.load(fh)
            return str((data.get("EnvironmentVariables") or {}).get("PATH") or "")
        if plat == "Linux":
            if not _SUPERVISOR_UNIT_PATH.exists():
                return ""
            text = _SUPERVISOR_UNIT_PATH.read_text(encoding="utf-8", errors="replace")
            m = re.search(r'^Environment="PATH=([^"]*)"', text, re.MULTILINE)
            return m.group(1) if m else ""
    except Exception:
        return ""
    return ""


def _search_path_report(env_path=None, would_bake=None,
                        tools=_PATH_SENSITIVE_TOOLS) -> "list[str]":
    """What this process will actually find, as lines for the log.

    ⛔⛔ NOTHING LOGGED THIS. The supervisor bakes a search path with the tool
    homes FIRST — a deliberate trade, written down in `_supervisor_path_value`,
    which accepts that anything dropped in a user-writable directory shadows the
    OS copy for every supervised child. The trade stands. What did not exist was
    any way to SEE it after the fact: the baked value appeared in no log, and the
    doctor only ever looked at DISPLAY. So a shadowed audio binary presented as a
    phase-3 failure that happened only under the supervisor and could not be
    diagnosed from a support bundle at all.

    A LIST because `log()` is one print per call.
    """
    env_path = os.environ.get("PATH", "") if env_path is None else env_path
    would_bake = _supervisor_path_value() if would_bake is None else would_bake
    lines = [f"[path] this process searches: {env_path or '(nothing — PATH is empty)'}"]
    for tool in tools:
        hits = _which_all(tool, env_path)
        if not hits:
            lines.append(f"[path] {tool}: not on this path")
        elif len(hits) == 1:
            lines.append(f"[path] {tool}: {hits[0]}")
        else:
            # ⭐ THE LINE THAT DIAGNOSES THE FAILURE. Naming the loser is what
            # turns "the audio step behaves differently under the supervisor"
            # into one readable fact.
            lines.append(f"[path] {tool}: {hits[0]}  (shadows {', '.join(hits[1:])})")
    if env_path != would_bake:
        lines.append(f"[path] a supervisor installed by this build would use: {would_bake}")
    return lines


def _supervisor_evidence(*, log_dir=None, legacy_dirs=None, max_lines=6,
                         max_bytes=8000) -> dict:
    """The last thing the OS supervisor's own stderr said, if it said anything.

    Returns `{"path": str, "legacy": bool, "lines": [str]}` — `path` empty when
    there is nothing to show.

    ⛔⛔ WHY THIS IS THE ONLY EVIDENCE THERE IS. "Enable On Startup?" defaults to
    yes, so the common install has no terminal at all: everything this product
    writes about a failure goes to a file nobody has been told to open. And when
    the failure is the supervised process dying at spawn — a missing dependency,
    a TCC refusal, an unparseable plist — it dies BEFORE our own logging exists,
    so `backend.log` has nothing either. What launchd or systemd captured on the
    way down is the whole record.

    ⭐ The legacy directories are read but never collected. A machine that has
    not re-run `--resurrect` since this moved still writes to the old place, and
    a diagnostic that could not see it would be useless on exactly the installs
    that predate the fix. Reading is not collecting: the bundle's allowlist is
    unchanged, because that allowlist is what the consent screen's promise about
    passwords, cookies and profile data is gated on.
    """
    out = {"path": "", "legacy": False, "lines": []}
    dirs = [(Path(log_dir) if log_dir is not None else _supervisor_log_dir(), False)]
    for d in (legacy_dirs if legacy_dirs is not None else _legacy_supervisor_log_dirs()):
        dirs.append((Path(d), True))
    for d, is_legacy in dirs:
        try:
            p = d / "supervisor.err.log"
            if not p.is_file():
                continue
            with open(p, "rb") as fh:
                fh.seek(0, os.SEEK_END)
                size = fh.tell()
                fh.seek(max(0, size - int(max_bytes)))
                blob = fh.read()
        except OSError:
            continue
        text = blob.decode("utf-8", errors="replace")
        # ⛔ Drop the first line when the read started mid-file: a truncated
        # first record reads as a different error than the one that happened.
        rows = text.splitlines()[1 if size > int(max_bytes) else 0:]
        rows = [r.rstrip() for r in rows if r.strip()]
        if not rows:
            continue
        out["path"] = str(p)
        out["legacy"] = is_legacy
        out["lines"] = rows[-int(max_lines):]
        return out
    return out


def _search_path_findings(*, shell_path, supervisor_path, would_bake,
                          platform="", tools=_PATH_SENSITIVE_TOOLS) -> dict:
    """Everything the doctor's search-path section decides, as data.

    Returns `{"rows": [(level, label, detail), …], "actions": [str, …]}` with
    level in `ok` / `warn` / `note`. `run_doctor` only renders it.

    ⭐⭐ SEPARATE BECAUSE `run_doctor` CANNOT BE RUN. It opens a Firestore
    client, imports patchright and spawns a 60-second Chromium probe, so a
    section written inline can only be pinned by reading its source — and
    mutation showed what that is worth: five mutants gutted the branches one by
    one, and every source pin still passed, because the strings they searched for
    survived the gutting.

    ⭐⭐ AND THE COMPARISON IS THE POINT. `--doctor` runs in a login shell whose
    path is NOT the one a supervised child gets. Resolving a tool here and
    reporting it answers a different question from the one being asked; a tool
    that resolves differently in each is the "works in my terminal, fails as a
    service" report, already localized to one binary.
    """
    rows: list[tuple[str, str, str]] = []
    actions: list[str] = []
    if supervisor_path and supervisor_path != would_bake:
        # The entry on disk predates this build. Every supervised child keeps
        # using the old value until it is rewritten — which is one command.
        rows.append(("warn", "Supervisor search path is out of date",
                     "written by an older build — supervised runs use the old one"))
        actions.append(_remedy_resurrect())
    elif supervisor_path:
        rows.append(("ok", "Supervisor search path", "matches this build"))
    elif platform == "Windows":
        rows.append(("note", "The Scheduled Task bakes no search path — the "
                             "child inherits yours.", ""))
    else:
        rows.append(("note", "No supervisor installed, so nothing is baked. "
                             "Showing this shell.", ""))
    effective = supervisor_path or shell_path
    for tool in tools:
        hits = _which_all(tool, effective)
        shell_hits = _which_all(tool, shell_path)
        if not hits:
            # ⚠ A NOTE, NOT A FAULT. Every tool here is optional — tinytag is the
            # primary duration probe, the mp3 transcode falls back to the
            # original file, and uv/pipx matter only during an update. Counting
            # these would put an issue on the summary line of a healthy machine.
            rows.append(("note", f"{tool}: not on this path "
                                 f"(optional — only used when it is)", ""))
        elif len(hits) > 1:
            rows.append(("warn", f"{tool} is shadowed",
                         f"{hits[0]} wins over {', '.join(hits[1:])}"))
        elif supervisor_path and shell_hits and hits[0] != shell_hits[0]:
            rows.append(("warn", f"{tool} differs under the supervisor",
                         f"background runs use {hits[0]}, this terminal uses "
                         f"{shell_hits[0]}"))
        else:
            rows.append(("ok", tool, hits[0]))
    return {"rows": rows, "actions": actions}


def _lifecycle_env(**extra: "str | None") -> dict:
    """Environment for the detached upgrade/uninstall waiter.

    THE WAITER MUST NOT INHERIT THE SUPERVISOR'S PATH UNCHANGED. pipx records the
    backend a venv was BUILT with in `pipx_metadata.json` and replays it on every
    upgrade — and for an EXISTING venv that recorded value beats both `--backend`
    and `PIPX_DEFAULT_BACKEND`: pipx 1.16's `_resolve_backend_for_venv` forces
    `cli_backend = None` ("Ignoring --backend=… for existing venv … Run `pipx
    reinstall`") and `resolve_backend_name`'s precedence is then metadata > env.
    So a uv-built venv constructs `UvBackend()` unconditionally, and pipx locates
    uv ONLY through `shutil.which("uv")` (`backends/uv.py:find_uv_binary` — the
    bundled-extra branch aside, there is no env-var override). **PATH is the only
    lever there is**, which is why neither workaround pipx's own error message
    suggests would have helped here.

    That is exactly what broke the app-driven update on a supervised macOS host:
    the LaunchAgent exports `PATH=/usr/local/bin:/usr/bin:/bin`, Homebrew's uv
    lives in `/opt/homebrew/bin`, and the waiter inherited that PATH — so `pipx
    upgrade` died with "The uv backend was requested but the 'uv' executable could
    not be found" while the SAME command run by hand from a login shell succeeded
    four minutes later (Research Computer, 2026-07-27: pipx logs 11:09:13 and
    11:12:32 raised PipxError with "Backend resolved to pip (auto-pip)"; 11:16:58
    logged "auto-path" → "using path uv 0.11.29 from /opt/homebrew/bin/uv" → rc 0).
    Prepending the standard uv/pipx homes makes the detached upgrade resolve its
    backend the way the user's own shell does.

    `extra` carries the waiter's out-of-band parameters (result-file path, log
    path, version pair). Env rather than argv: argv is world-readable in the
    process list, and it keeps the waiter's positional contract (`pid [pipx…]
    [--then-- restart…]`) unchanged."""
    env = dict(os.environ)
    parts: list[str] = []
    seen: set[str] = set()
    for d in [*_lifecycle_path_dirs(), *(env.get("PATH") or os.defpath).split(os.pathsep)]:
        if not d or d in seen:
            continue
        seen.add(d)
        parts.append(d)
    env["PATH"] = os.pathsep.join(parts)
    for k, v in extra.items():
        if v is not None:
            env[k] = str(v)
    return env


def _pipx_recorded_backend() -> "str | None":
    """The build backend pipx recorded in OUR venv's metadata, lowercased.

    Read from `pipx_metadata.json` rather than asked of pipx, because this has to
    answer the question pipx will answer at upgrade time and pipx offers no way to
    query it. None when the file is missing or unreadable (a source checkout, a
    pip install, an older pipx) — every caller treats that as "can't tell" and
    proceeds, since guessing wrong here must never block a working update."""
    pipx = _pipx_cmd()
    if pipx is None:
        return None
    try:
        r = subprocess.run([*pipx, "environment", "--value", "PIPX_LOCAL_VENVS"],
                           capture_output=True, text=True, timeout=30)
        venvs = (r.stdout or "").strip()
        if r.returncode != 0 or not venvs:
            return None
        meta = json.loads((Path(venvs) / "superresearch" / "pipx_metadata.json")
                          .read_text(encoding="utf-8"))
        backend = meta.get("backend")
        return str(backend).strip().lower() if backend else None
    except Exception:
        return None


def _pipx_bundles_uv() -> bool:
    """Whether pipx can reach uv WITHOUT going through PATH.

    `pipx install pipx[uv]`, `uv tool install pipx` and similar put the `uv` PyPI
    distribution alongside pipx, and pipx's `find_uv_binary` asks that package for
    the binary before it ever consults PATH. On such a host the preflight below
    would refuse an upgrade pipx would complete perfectly well, and tell the user
    to install a uv they already have. So: ask pipx's OWN interpreter whether the
    module imports.

    Fails closed on "don't know" (returns False) only in the sense that it declines
    to vouch — the caller's own guard is the fail-open one."""
    pipx = _pipx_cmd()
    if not pipx:
        return False
    import shutil as _shutil
    py: "str | None" = None
    if len(pipx) >= 3 and pipx[1] == "-m":
        py = pipx[0]
    else:
        # A console-script shim names its interpreter in the shebang. `#!/usr/bin/
        # env python3` needs the second token resolved; anything else is absolute.
        try:
            with open(pipx[0], "rb") as _fh:
                first = _fh.readline(512).decode("utf-8", "replace").strip()
            if first.startswith("#!"):
                toks = first[2:].strip().split()
                if toks:
                    py = (_shutil.which(toks[1]) if (len(toks) > 1
                          and os.path.basename(toks[0]) == "env") else toks[0])
        except Exception:
            py = None
    if not py:
        # The shebang branch cannot work on Windows: `_pipx_cmd()` hands back
        # `pipx.EXE`, a PE binary whose first bytes are "MZ", so `startswith("#!")`
        # is never true and `py` stays None. That left this function structurally
        # unable to return True on Windows, which quietly turns the caller's
        # deliberately fail-OPEN guard into a fail-CLOSED one: a host where pipx
        # bundles uv gets `--update` and the app's Update button refused outright,
        # with a message telling the user to install a uv they already have.
        #
        # So ask pipx itself where it keeps its venvs and use pipx's own
        # interpreter. Anything unexpected leaves `py` None and we return False
        # exactly as before — this branch can only ADD a True, never remove one,
        # so the worst case is the behaviour that shipped before the preflight.
        try:
            env = subprocess.run([*pipx, "environment", "--value", "PIPX_LOCAL_VENVS"],
                                 capture_output=True, text=True, timeout=20)
            if env.returncode == 0 and env.stdout.strip():
                venv = Path(env.stdout.strip()) / "pipx"
                for rel in (("Scripts", "python.exe"), ("bin", "python3"), ("bin", "python")):
                    cand = venv.joinpath(*rel)
                    if cand.exists():
                        py = str(cand)
                        break
        except Exception:
            py = None
    if not py:
        return False
    try:
        return subprocess.run([py, "-c", "import uv"], capture_output=True,
                              timeout=20).returncode == 0
    except Exception:
        return False


def _upgrade_preflight() -> "str | None":
    """Why the upgrade would fail, checked BEFORE anything is torn down — or None
    when it looks runnable.

    Everything after `_perform_self_update` returns "started" is postmortem by
    construction: the worker has to exit so pipx can rebuild the venv it is running
    from, and the detached waiter holds no credentials, so the best the reporting
    path can ever do is explain a failure that already happened. This is the only
    check that PREVENTS the downtime instead of narrating it, and it costs one
    `which` against the environment the waiter will actually get.

    It answers exactly the failure that was observed: pipx replays the backend
    recorded in the venv's metadata, and for a uv-built venv it resolves uv ONLY
    through PATH — so a supervisor whose PATH lacks Homebrew produced "the 'uv'
    executable could not be found", a five-minute spinner in the app, and a
    backend that came back on the old version. Neither `--backend pip` nor
    `PIPX_DEFAULT_BACKEND` can help: pipx nulls the CLI flag for an existing venv
    and ranks metadata above the environment. PATH is the only lever, so PATH is
    what gets checked.

    Deliberately narrow, and ONE condition rather than the two it is tempting to
    write. `uv` is the only recorded backend with a binary that has to be findable
    on PATH — `pip` lives inside the venv, and anything we cannot name (an older
    pipx, a pip install, a source checkout, a backend that does not exist yet) is
    let through, because a preflight that guesses is a preflight that blocks
    working updates. A second "is it a backend I recognise?" guard in front of this
    one would be unreachable, and unreachable guards read as protection."""
    if _pipx_recorded_backend() != "uv":
        return None
    import shutil as _shutil
    # `path=` is the whole point: the question is not whether uv is on OUR PATH —
    # a login shell finds it fine, which is exactly why this was so confusing —
    # but whether it is on the PATH the detached waiter will run with.
    if _shutil.which("uv", path=_lifecycle_env().get("PATH")):
        return None
    if _pipx_bundles_uv():
        return None  # pipx ships its own uv and never consults PATH for it
    return ("this install was built with the 'uv' backend and 'uv' isn't on "
            "the background service's PATH, so the upgrade would fail before it "
            "started — install uv where the service can see it, or re-run "
            "`superresearch --resurrect` to refresh the service's PATH")


def _spawn_detached_lifecycle(action: str, *, restart_after: bool = False,
                              current: "str | None" = None,
                              latest: "str | None" = None) -> "int | None":
    """Stop any running supervisor/workers, then spawn a DETACHED waiter that
    runs `pipx <action> superresearch` once THIS process exits. `action` is
    'uninstall' or 'upgrade'. Returns the spawned waiter's PID (truthy) on success,
    or None if it couldn't launch. The PID lets the caller PROTECT the waiter from
    its own `_schedule_server_exit` child-reap (see restart_after below).

    ``restart_after`` (app-driven remote update only): after a successful upgrade,
    also cycle the supervisor onto the new venv via `superresearch --restart`, and
    run the waiter cgroup-escaped so systemd can't reap it mid-restart. The CLI
    `--update` leaves this False — it runs outside the cgroup and hands the restart
    to the user (the `--restart` advice it prints).

    IMPORTANT: the caller that then calls `_schedule_server_exit` MUST pass this
    PID as `protect_pids` — that helper reaps ALL child processes before exiting,
    and off-Linux (no systemd-run re-parenting) the waiter is a direct child that
    would otherwise be SIGKILLed before it ever runs the upgrade."""
    pipx = _pipx_cmd()
    py = _path_python()
    if pipx is None or py is None:
        return None
    log_path = _STATE_DIR / f"{action}.log"
    try:
        _STATE_DIR.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    # Drop any sentinel left by an EARLIER update before this one can write its own.
    # A stale file would otherwise be republished as this attempt's outcome (and, if
    # the waiter dies before writing, would report the wrong result entirely). The
    # launch record goes with it for the same reason.
    # The journal is truncated here too, and for the same reason: it is APPEND-only
    # while the waiter runs, so without this the next attempt's steps would be read
    # as a continuation of the last one's — and the whole point of it is to say
    # where THIS attempt stopped.
    # ⛔ AND THE LOG, which is the file every one of those reasons was written about:
    # it is opened append-only below and the waiter publishes its TAIL as this
    # attempt's evidence, so leaving it would hand the user the PREVIOUS attempt's
    # error as the explanation for this one — in the diagnostics and in the single
    # sentence `reason` they actually read. Cleared BEFORE the handle is opened,
    # because an unlink after the open writes into an inode nothing can read back
    # (POSIX) or fails outright (Windows).
    for _stale in (_UPDATE_RESULT_PATH, _UPDATE_INTENT_PATH, _UPDATE_JOURNAL_PATH,
                   log_path):
        try:
            _stale.unlink(missing_ok=True)
        except Exception:
            pass
    logf = subprocess.DEVNULL
    try:
        # "wb", not "ab": belt and braces with the unlink above, which a Windows box
        # will refuse while a previous waiter still holds the file open. Truncating
        # at open means a clear the OS declined cannot silently become an append.
        logf = open(log_path, "wb")
    except Exception:
        pass
    waiter_argv = [str(os.getpid()), *pipx, action, "superresearch"]
    escape: list[str] = []
    entry = None
    if restart_after and action == "upgrade":
        # Cycle the whole supervisor (incl. the daemon-loop) onto the rebuilt venv.
        entry = _installed_sr_entry()
        if entry:
            waiter_argv += ["--then--", entry, "--restart"]
            escape = _cgroup_escape_prefix()  # survive the daemon-loop's death
        else:
            # Can't locate the `superresearch` console script → we cannot cycle the
            # supervisor onto the new build. The upgrade still lands (applied on the
            # next natural restart/reboot), but we must NOT free the venv below —
            # killing the daemon-loop with no way to relaunch it would strand the
            # machine offline. Surface it so the operator isn't left guessing.
            log("[device-cmds] UPDATE: couldn't resolve the 'superresearch' console "
                "script — upgrading in place, but the running build won't cycle until "
                "the next restart.", "WARN")
    # PATH widened so pipx can resolve its recorded backend, plus the waiter's
    # out-of-band parameters (see _lifecycle_env). The result sentinel is what makes
    # a FAILED upgrade reportable at all — `_perform_self_update` has already
    # returned "started" by the time pipx runs.
    env = _lifecycle_env(
        DG_LIFECYCLE_RESULT=str(_UPDATE_RESULT_PATH) if action == "upgrade" else None,
        DG_LIFECYCLE_INTENT=str(_UPDATE_INTENT_PATH) if action == "upgrade" else None,
        # Journaled for EVERY action, not only an upgrade: a `--restart` that never
        # comes back is as opaque as an upgrade that never finishes, and the journal
        # is the only thing either of them can leave behind.
        DG_LIFECYCLE_JOURNAL=str(_UPDATE_JOURNAL_PATH),
        DG_LIFECYCLE_LOG=str(log_path),
        DG_LIFECYCLE_ACTION=action,
        DG_LIFECYCLE_FROM=current,
        DG_LIFECYCLE_TO=latest,
    )
    if escape:
        # systemd-run does NOT hand our environment to the transient unit — it gets
        # the user manager's, which is the very narrow PATH we just widened. Forward
        # the keys explicitly, spliced in before the trailing `--`.
        # ⛔ Every out-of-band parameter the waiter reads MUST be listed here or it
        # is silently absent on Linux only — systemd-run hands the transient unit
        # the user manager's environment, not ours. A journal variable missing from
        # this tuple would make the diagnostic dead on exactly the platform where
        # the extra indirection makes it hardest to reproduce.
        _fwd = ("PATH", "DG_LIFECYCLE_RESULT", "DG_LIFECYCLE_INTENT", "DG_LIFECYCLE_LOG",
                "DG_LIFECYCLE_JOURNAL",
                "DG_LIFECYCLE_ACTION", "DG_LIFECYCLE_FROM", "DG_LIFECYCLE_TO")
        escape = (escape[:-1]
                  + [f"--setenv={k}={env[k]}" for k in _fwd if env.get(k)]
                  + escape[-1:])
    cmd = escape + [py, "-c", _LIFECYCLE_WAITER, *waiter_argv]
    creationflags = 0
    kwargs: dict = {}
    if sys.platform == "win32":
        creationflags = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    else:
        kwargs["start_new_session"] = True
    # Record that an upgrade is IN FLIGHT — BEFORE the spawn, because the waiter's
    # first act is to stamp its own pid into this file and it must find it there.
    # Written without a pid on purpose: `Popen.pid` is not the worker on Linux (the
    # upgrade is submitted through `systemd-run`, a front-end that exits at once),
    # and a dead pid here would make every Linux update read as abandoned. No pid
    # therefore means "nothing has claimed this yet", which is exactly right —
    # including when the waiter never starts at all.
    #
    # If the waiter dies without leaving a result — killed by a supervisor sweep,
    # reaped, crashed — this file is the only thing left that knows an update was
    # ever attempted, and without it the app has nothing to show but a spinner. See
    # `_update_intent_verdict`.
    if action == "upgrade":
        try:
            _UPDATE_INTENT_PATH.write_text(json.dumps({
                "action": "upgrade", "waiter_pid": None,
                "at": int(time.time() * 1000),
                "current": current or "", "latest": latest or "",
            }), encoding="utf-8")
        except Exception as _ie:
            log(f"[update] couldn't record the upgrade attempt ({_ie}) — a failure "
                f"that never reaches the waiter's own report will stay silent", "WARN")
    # Spawn the waiter BEFORE freeing the venv. Two reasons: (a) if the launch
    # fails we must NOT have already torn the backend down (leave it serving so the
    # caller can report "failed" cleanly, not strand the machine offline); (b) on a
    # systemd host, killing the daemon-loop tears its cgroup down — the escaped
    # waiter must already be running in its own scope before that happens.
    waiter_pid: "int | None" = None
    try:
        _proc = subprocess.Popen(cmd, stdout=logf, stderr=subprocess.STDOUT,
                                 stdin=subprocess.DEVNULL, env=env,
                                 creationflags=creationflags, **kwargs)
        waiter_pid = _proc.pid
        # ⛔ Register it before ANY other work: from this instant a reap that does not
        # know about it would abort the update. The `atexit` reap installed by
        # `--serve` cannot be passed a pid list (it is registered at startup), so this
        # set is the only channel it has. See `_reap_child_processes`.
        _ALWAYS_PROTECTED_PIDS.add(waiter_pid)
    except Exception as e:
        print(f"  Could not launch the background {action} helper: {e}")
        # Nothing will ever claim the record we just wrote, and the caller is about
        # to report this failure synchronously — leaving it would republish the same
        # attempt as a mystery failure on the next startup.
        try:
            _UPDATE_INTENT_PATH.unlink(missing_ok=True)
        except Exception:
            pass
        return None
    finally:
        if logf is not subprocess.DEVNULL:
            try:
                logf.close()
            except Exception:
                pass
    # Free the venv: kill any leftover daemon-loop / --serve workers (NOT self) —
    # on WINDOWS they'd keep the venv's files open and pipx would fail. The detached
    # waiter handles the LAST holder (this process) by waiting for it.
    #
    # SKIP this on the restart_after (remote) path off-Windows: Unix lets pipx
    # rebuild a venv whose files are still open, so the kill isn't needed there —
    # and killing the daemon-loop (the systemd unit's MAIN process) would tear its
    # cgroup down, SIGTERM-ing the very worker still writing updateStatus. Leaving
    # it alive lets this handler finish; `superresearch --restart` cycles the whole
    # supervisor onto the new venv at the end.
    #
    # On Windows the kill IS needed (file lock) — but ONLY when we're going to
    # restart (entry resolved). With no restart to relaunch it, killing the
    # daemon-loop would leave the box offline until the next logon, so don't.
    free_venv = (not restart_after) or (sys.platform == "win32" and bool(entry))
    if free_venv:
        try:
            self_pid = os.getpid()
            victims = [pid for pid, _cmd, role in _enumerate_research_py_procs()
                       if pid != self_pid and role in ("daemon-loop", "serve")]
            if victims:
                _kill_pids(victims)
                print(f"  Stopped {len(victims)} running backend process(es) so the "
                      f"{action} can complete.")
        except Exception:
            pass
    return waiter_pid


def _perform_self_update(*, force_check: bool = True, restart_after: bool = False) -> dict:
    """Headless core of the self-update — shared by the `superresearch --update`
    CLI (_self_update) AND the app-driven remote "update" device command. Decides
    whether to upgrade and, if so, SPAWNS the detached pipx-upgrade waiter — but
    does NOT print and does NOT exit the process (the caller owns both: the CLI
    exits via main()'s SystemExit; the serve command handler must call
    `_schedule_server_exit` so the waiter's `pipx upgrade` can rebuild the venv).

    Returns a status dict the caller can render / write back:
      {state, current, latest, reason}
      state ∈ {"already", "started", "failed", "unsupported"}
        already     — installed build is current (or ahead of) the latest on PyPI
        started     — a detached upgrade was launched (caller must now exit)
        unsupported — source checkout (update via `git pull`)
        failed      — pipx missing, or the detached launch failed
    `force_check` bypasses the 24h cache for a fresh PyPI read (an explicit
    "update now" must not decide off a stale cache); `latest` is None only when
    PyPI is unreachable, in which case we PROCEED rather than strand the update.
    `restart_after` (remote/app path): after a successful upgrade, cycle the
    supervisor onto the new venv (cgroup-escaped) so the version actually bumps —
    the CLI leaves this False and prints the `--restart` step for the user."""
    cur = _sr_version()
    if _is_source_checkout():
        return {"state": "unsupported", "current": cur, "latest": None,
                "reason": "source checkout — update with `git pull`"}
    if _pipx_cmd() is None:
        return {"state": "failed", "current": cur, "latest": None,
                "reason": "pipx not found"}
    latest = _latest_on_pypi(force=force_check)
    if latest and not _version_gt(latest, cur):
        return {"state": "already", "current": cur, "latest": latest, "reason": ""}
    # LAST POINT OF NO RETURN. Past here the caller exits so pipx can rebuild the
    # venv, and no honest outcome can reach the app until a new backend comes up.
    # Refuse now, while we can still answer.
    if blocked := _upgrade_preflight():
        log(f"[update] refusing before shutdown: {blocked}", "WARN")
        return {"state": "failed", "current": cur, "latest": latest, "reason": blocked}
    waiter_pid = _spawn_detached_lifecycle("upgrade", restart_after=restart_after,
                                           current=cur, latest=latest)
    if waiter_pid:
        # Surface the waiter PID so the caller can protect it from
        # _schedule_server_exit's child-reap (off-Linux the waiter is a direct child;
        # the reap would SIGKILL it before the upgrade runs).
        return {"state": "started", "current": cur, "latest": latest, "reason": "",
                "waiter_pid": waiter_pid}
    return {"state": "failed", "current": cur, "latest": latest,
            "reason": "couldn't launch the background upgrade"}


def _self_update() -> int:
    """`superresearch --update` — upgrade the installed package via pipx (detached,
    so pipx can rebuild the venv this process runs from). Branded + crisp, matching
    the other subcommands. Thin printer over `_perform_self_update`."""
    _branded_header("renovatio", _BOLD + _ACCENT, "renew · update Super Research")
    res = _perform_self_update(force_check=True)
    state, cur, latest = res["state"], res["current"], res.get("latest")
    if state == "unsupported":
        print(f"  Source checkout — update with  {_c(_BOLD, 'git pull')}.")
        print()
        return 0
    if state == "failed" and res.get("reason") == "pipx not found":
        print(f"  {_c(_WARN, '⚠')}  pipx not found — update manually:  {_c(_BOLD, 'pipx upgrade superresearch')}")
        print()
        return 1
    if state == "already":
        print(f"  {_c(_OK, '✓')}  Already up to date  {_c(_DIM, '(v' + cur + ')')}")
        print()
        return 0
    if latest:
        print(f"  Updating  {_c(_DIM, 'v' + cur)}  →  {_c(_BOLD + _OK, 'v' + latest)}")
    else:
        print(f"  Updating Super Research  {_c(_DIM, '(current: v' + cur + ')')}")
    if state == "started":
        print(f"  {_c(_OK, '✓')}  Update running — completes a moment after this exits.")
        print()
        # The restart is REQUIRED, not optional: the live process keeps the old
        # build in memory until it is cycled. (The old copy said "confirm with
        # --version", which reports the INSTALLED build — so it reads as success
        # while the old code is still serving. Never use it as the confirmation.)
        print(f"  {_c(_BOLD, 'Then restart the backend')} {_c(_DIM, '— it keeps running the OLD build until you do:')}")
        if _supervisor_installed():
            print(f"      {_c(_BOLD, _PROG + ' --restart')}   {_c(_DIM, '(~20s after this exits; keeps On Startup on)')}")
        else:
            print(f"      {_c(_BOLD, _PROG + ' --serve')}   {_c(_DIM, '(stop the running backend first)')}")
        print(f"  {_c(_DIM, 'Confirmation is the device going green in the app — not')} {_c(_BOLD, '--version')}{_c(_DIM, ', which reports the installed build.')}")
        print()
        return 0
    # Print the REASON when there is one. The bare "run pipx upgrade" line below is
    # actively wrong advice for the pre-flight refusal — that is the very command
    # that would fail, for a reason the user can't see from its output.
    if _reason := res.get("reason"):
        print(f"  {_c(_WARN, '⚠')}  Couldn't start the update — {_reason}")
        print()
        return 1
    print(f"  {_c(_WARN, '⚠')}  Couldn't start the update. Run:  {_c(_BOLD, 'pipx upgrade superresearch')}")
    print()
    return 1


def _self_uninstall() -> int:
    """`superresearch --uninstall` — remove the installed package via pipx. Detached
    by necessity: pipx cannot delete the venv THIS process runs from on Windows, so
    a tiny helper finishes the removal the instant this command exits. Leaves
    ~/.super-research/ (logins + pairing) intact; --unpair is the full disconnect.
    Branded + crisp, matching the other subcommands."""
    _branded_header("vale", _BOLD + _RED, "farewell · remove Super Research")
    if _is_source_checkout():
        print("  Source checkout — nothing to uninstall.")
        print(f"  To disconnect this machine:  {_c(_BOLD, _PROG + ' --unpair')}")
        print()
        return 0
    if _pipx_cmd() is None:
        print(f"  {_c(_WARN, '⚠')}  pipx not found — uninstall manually:  {_c(_BOLD, 'pipx uninstall superresearch')}")
        print()
        return 1
    try:
        _remove = _ask_yes_no_sync("Remove the Super Research backend?", default=False)
    except (EOFError, KeyboardInterrupt):
        _remove = False
    if not _remove:
        print(f"  {_c(_DIM, 'Cancelled — nothing removed.')}")
        print()
        return 0
    if _spawn_detached_lifecycle("uninstall"):
        print()
        print(f"  {_c(_OK, '✓')}  Super Research removed.")
        print(f"  {_c(_DIM, 'Finalizing in the background (~3s) — verify with')}  {_c(_BOLD, 'pipx list')}{_c(_DIM, '.')}")
        print(f"  {_c(_DIM, 'Logins kept in ~/.super-research; run')}  {_c(_BOLD, _PROG + ' --unpair')}  {_c(_DIM, 'to fully disconnect.')}")
        print()
        return 0
    print(f"  {_c(_WARN, '⚠')}  Couldn't start the uninstall. Run:  {_c(_BOLD, 'pipx uninstall superresearch')}")
    print()
    return 1


def main():
    # Before anything else can log: auth/, vision, selfheal and narrate all use
    # the standard library, and without this their WARNINGs go to bare stderr
    # and their DEBUG/INFO go nowhere. Applies to EVERY command — the uvicorn
    # log config below only exists inside `--serve`.
    _install_stdlib_log_bridge()
    # And before anything can CRASH: this file had no excepthook at all, so an
    # uncaught traceback out of any command reached a closing terminal or
    # backend.err.log — never the file a user sends.
    _install_crash_log_hook()
    # ⛔⛔ THE FLUSH THAT CLOSES THE TWO CASES THAT OTHERWISE NEVER FIRE. A
    # machine whose pairing SUCCEEDED but whose telemetry POST failed never
    # pairs again, and a machine whose pairing FAILED runs `--doctor` next — so
    # "retry on the next attempt of the same thing" has no trigger at all. Every
    # command, on a daemon thread, bounded by its own deadline.
    tm.flush_in_background()

    # Super Agent (chat-runtime bridge) — `python research.py agent <…>`
    # (or the flag-style alias `--agent`, consistent with --pair/--serve). Bare
    # `agent` / `--agent` with no subcommand is fine — the package defaults to a
    # smart entry (status if set up, else connect).
    # The agent is an isolated sub-package under agent/ (its own deps + its own
    # process; it imports NOTHING from this file and this file never imports it).
    # We only FRONT it here so it's invoked consistently with the rest of the
    # CLI. Everything after the verb is forwarded verbatim to the package (run
    # from agent/ so `-m facade` resolves), intercepted before argparse so the
    # agent's own subcommands/flags pass straight through. (A research topic of
    # literally "agent" is shadowed — phrase it differently, e.g. "AI agents".)
    if len(sys.argv) > 1 and sys.argv[1] in ("agent", "--agent"):
        agent_args = sys.argv[2:]
        agent_dir = Path(__file__).resolve().parent / "agent"
        if (agent_dir / "facade" / "__main__.py").exists():
            # Source checkout: run the in-tree agent package directly (cwd=agent/
            # so `-m facade` resolves; the agent owns its own deps + process).
            try:
                rc = subprocess.call([sys.executable, "-m", "facade", *agent_args],
                                     cwd=str(agent_dir))
            except KeyboardInterrupt:
                rc = 130
            raise SystemExit(rc)
        # Installed build (`pipx install superresearch`): the agent is its own
        # separately-published package, `superresearch-agent`. Delegate to the
        # canonical `pipx run superresearch-agent …` path end-users use, so
        # `superresearch agent connect` keeps working without bundling (and
        # without duplicating) the agent inside this wheel.
        raise SystemExit(_delegate_agent_via_pipx(agent_args))

    # Relocate any pre-relocation pairing/runtime state into ~/.super-research/
    # before anything reads it, so a pipx upgrade/reinstall can't orphan a paired
    # device. Best-effort + idempotent; runs for every non-agent CLI invocation.
    _migrate_state_to_home()

    parser = argparse.ArgumentParser(
        prog=_PROG,
        description="Multi-Agent Deep Research Pipeline",
        add_help=False,  # -h/--help shows our branded, grouped command reference (run_commands_help)
        epilog=f"Chat-runtime (Hermes / OpenClaw) commands:  {_PROG} agent --help"
               "   (bare  agent  /  --agent  → smart entry: status or connect)",
    )
    parser.add_argument("-h", "--help", action="store_true", dest="show_help",
        help="Show the Super Research command reference (grouped by use-case).")
    parser.add_argument("topic", nargs="?", help="Research topic")
    parser.add_argument("--pdf", action="append", default=[], help="PDF to attach (Phase 1)")
    parser.add_argument("--brief-file", "-b", help="Existing brief file (skip Phase 1)")
    parser.add_argument("--email", "-e", help="Email for Phase 6 delivery")
    parser.add_argument("--api-key", "-k", help="CUA API key")
    parser.add_argument("--verbose", "-v", action="store_true")
    parser.add_argument("--pair", action="store_true", help="First-time login setup")
    parser.add_argument("--login", action="store_true",
        help="Open your REAL Chrome (not automated) per browser profile so you can sign in to "
             "ChatGPT/Gemini/Claude/NotebookLM by hand — the reliable way past Google's "
             "'browser may not be secure' + Cloudflare's human-check, which block the pipeline's "
             "automated browser at sign-in. Verifies each login (+ Pro tier) and refreshes the app "
             "login badges if paired. Re-run whenever a session expires. No pairing required.")
    parser.add_argument("--resume", "-r", help="Resume from a previous queue directory (name or full path)")
    parser.add_argument("--serve", action="store_true", help="Start web app API server")
    parser.add_argument("--port", type=int, default=None,
        help="Server port. Default: 8000 for worker 1, 8000+(worker_id-1) for worker N. "
             "Pass explicitly only for non-default port mappings (testing / port collision recovery).")
    parser.add_argument("--worker-id", type=int, default=None, dest="worker_id",
        help="Worker slot index (1-based). Worker N uses _profile_dir(N) for its browser "
             "and binds port 8000+N-1 (unless --port overrides). Workers ≥2 are spawned by "
             "daemon-loop when research_config.json's workerCount > 1; set up via pair Stage 4's "
             "multi-profile loop. Omitted = standalone serve, which runs one worker no matter "
             "how many profiles are configured (WORKER_ID still resolves to 1).")
    parser.add_argument("--resurrect", action="store_true",
        help="Enable On Startup: auto-start the backend at login and keep it running in the background")
    parser.add_argument("--retire", action="store_true",
        help="Disable On Startup: remove the auto-start scheduled task and stop the background backend")
    parser.add_argument("--restart", action="store_true",
        help="Restart the running backend so it picks up a newly installed version "
             "(the step after --update / pipx upgrade / the web installer). Keeps On "
             "Startup enabled — unlike --retire, which removes it.")
    parser.add_argument("--unpair", action="store_true",
        help="Fully disconnect this machine from Super Research (inverse of --pair): deletes token + device doc + local config")
    parser.add_argument("--deep", action="store_true",
        help="With --unpair: also wipe ALL Playwright browser profiles under ~/.super-research/browser-profile*/ "
             "(clears ChatGPT/Gemini/Claude/NotebookLM logins across profile-1 and any profile-N set up via pair "
             "Stage 4 multi-profile loop). Also resets workerCount to 1 and wipes pair-time API keys "
             "(ANTHROPIC_API_KEY/GEMINI_API_KEY, plus retired legacy aliases CUA_API_KEY/GOOGLE_API_KEY) from Windows User-scope env or "
             ".dg-supervisor.env so the next --pair Stage 3 re-prompts and re-verifies. Useful when re-pairing "
             "to a different account or when the F4 cookie check refuses pair due to stale Google auth. "
             "Default: preserve profiles + keys.")
    parser.add_argument("--daemon-loop", action="store_true",
        help="Internal: wrapper that keeps --serve alive by relaunching it on any exit. Used by the On Startup scheduled task.")
    parser.add_argument("--env-file", default=None,
        help="Path to KEY=value env file. Default: <script_dir>/.dg-supervisor.env (silently skipped if missing).")
    parser.add_argument("--doctor", action="store_true",
        help="Diagnose + auto-repair common Super Research issues (pair state / Firebase / "
             "Chromium binary / supervisor unit / port 8000 / Linux DISPLAY propagation). "
             "First thing to run when something feels wrong. Non-destructive — never unpairs or deletes user data.")
    parser.add_argument("--send-logs", action="store_true", dest="send_logs",
        help="Package this machine's recent logs and hand them to the team. Shows "
             "exactly what leaves before asking. Always writes a local copy first, "
             "so it still gives you something to send when the network is the "
             "problem.")
    parser.add_argument("--yes", "-y", action="store_true", dest="assume_yes",
        help="Skip the confirmation prompt on --send-logs (for scripted use).")
    parser.add_argument("--runs", type=int, default=None, dest="send_logs_runs",
        help=f"How many recent runs --send-logs should include (1-{BUNDLE_MAX_RUNS}). "
             f"Default: all {BUNDLE_MAX_RUNS}. Sessions and this machine's own log "
             f"files are included whatever you pick.")
    parser.add_argument("--select", action="store_true", dest="send_logs_select",
        help="Choose which runs --send-logs includes, from a numbered list of "
             "what this machine still has. Enter alone sends no runs — just this "
             "computer's own log files, which is the whole evidence when a "
             "pairing failure produced no run at all.")
    parser.add_argument("--contact-email", default=None, dest="contact_email",
        help="Optional address to reach you on if --send-logs cannot use your "
             "account. Never verified, never used as an identifier.")
    parser.add_argument("--update", "--upgrade", action="store_true", dest="update",
        help="Update Super Research to the latest published version (via pipx). Alias: --upgrade.")
    parser.add_argument("--uninstall", action="store_true",
        help="Uninstall the Super Research backend (via pipx). Keeps your logins + pairing; "
             "run --unpair first for a full disconnect.")
    parser.add_argument("--version", action="store_true", dest="show_version",
        help="Print the installed Super Research version (+ any available update) and exit.")
    args = parser.parse_args()

    # ── Give the interactive commands a file of their own ────────────
    # `--pair` / `--login` / `--doctor` print branded output through bare
    # `print()`, so until now their entire account of a failure was whatever
    # the user photographed before the window closed.
    _session_cmd = _session_command_name(args)
    if _session_cmd:
        _install_session_tee(_session_cmd)

    if args.show_version:
        print(f"  {_c(_BOLD + _ACCENT, 'Super')} {_c(_BOLD, 'Research')}  {_c(_BOLD, 'v' + _sr_version())}")
        # This line reports the INSTALLED build. If a different build is actually
        # serving, say so right here — otherwise --version reads as "update done"
        # while the old code is still live (the exact trap the old --update copy
        # walked users into).
        try:
            _pend = _restart_pending()
        except Exception:
            _pend = None
        if _pend:
            _run_v, _inst_v = _pend
            print(f"  {_c(_WARN, '⚠')}  {_c(_DIM, 'but the backend is still SERVING')} {_c(_BOLD, 'v' + _run_v)}"
                  f"  {_c(_DIM, '— restart to apply:')}  {_c(_BOLD, _PROG + ' --restart')}")
        try:
            _newer = _newer_version_notice()
        except Exception:
            _newer = None
        if _newer:
            print(f"  {_c(_OK, '⬆')}  {_c(_DIM, 'v' + _newer + ' available — run')}  {_c(_BOLD, _PROG + ' --update')}")
        return 0

    # Post-update restart nudge. Surfaces on ordinary commands so an update that
    # arrived by ANY route — `--update`, a bare `pipx upgrade`, or the
    # superresearch.io installer — can't sit silently applied-but-not-live.
    # Skipped where it would be noise or wrong: the serve/daemon processes are the
    # thing being restarted, --restart/--update/--retire/--unpair speak for
    # themselves, and --version prints its own (richer) variant above.
    if not (args.serve or args.daemon_loop or args.restart or args.update
            or args.retire or args.unpair or args.resurrect):
        _warn_if_restart_pending()

    # Load .dg-supervisor.env BEFORE subcommand dispatch so every subcommand
    # (--serve, --daemon-loop, --resurrect, etc.) inherits the same values.
    # `os.environ.setdefault` semantics — existing process env wins, which
    # preserves Windows user-scope env priority for `resolve_api_key` callers.
    if args.env_file:
        _load_env_file(args.env_file)
    elif _SUPERVISOR_ENV_FILE_DEFAULT_PATH.exists():
        # Silently auto-load if default file exists. No WARN on first-run
        # where the user hasn't created it yet (the path-exists check here
        # sidesteps `_load_env_file`'s missing-file WARN).
        _load_env_file(_SUPERVISOR_ENV_FILE_DEFAULT_PATH)

    # One-shot upgrade for pre-2026-05-23 machines that paired before the
    # CUA_API_KEY → ANTHROPIC_API_KEY + GOOGLE_API_KEY → GEMINI_API_KEY
    # rename. Runs after env-file load (so POSIX picks up env-file legacy
    # values) and before subcommand dispatch (so resolvers see canonical
    # names everywhere). Cached via `~/.super-research/env-migrated-v1`
    # sentinel — subsequent process starts skip the work.
    _migrate_legacy_api_keys()

    if args.show_help:
        run_commands_help()
        return

    if args.update:
        raise SystemExit(_self_update())

    if args.uninstall:
        raise SystemExit(_self_uninstall())

    if args.send_logs:
        raise SystemExit(cmd_send_logs(assume_yes=bool(args.assume_yes),
                                      select=bool(args.send_logs_select),
                                      email=args.contact_email,
                                      runs=args.send_logs_runs))

    if args.doctor:
        run_doctor()
        return

    if args.resurrect:
        run_resurrect()
        return

    if args.restart:
        run_restart()
        return

    if args.retire:
        run_retire()
        return

    if args.unpair:
        run_unpair(deep=bool(args.deep))
        return

    # Resolve worker_id + port. Port defaults to 8000+(worker_id-1) so the
    # daemon-loop's N children each bind a distinct port without each spawn
    # needing to know the global mapping. Stamp WORKER_ID module-global so
    # downstream code (pipeline launcher, pending-queue path, listener
    # claim, w1-only gates) can read it without plumbing.
    global WORKER_ID, _FLEET_MEMBER
    WORKER_ID = max(1, int(args.worker_id or 1))
    # Presence, not value — see `_FLEET_MEMBER`. argparse's default is None
    # precisely so "not passed" stays distinguishable from "--worker-id 1".
    _FLEET_MEMBER = args.worker_id is not None
    _resolved_port = args.port if args.port is not None else (8000 + WORKER_ID - 1)

    if args.daemon_loop:
        run_daemon_loop(_resolved_port)
        return

    if args.login:
        asyncio.run(run_login())
        return

    if args.pair:
        asyncio.run(cmd_pair_v2(str(PROFILE_DIR)))
        return

    if args.serve:
        # Stamp what this process is actually running, so any later CLI call can
        # tell "a newer build is installed but the OLD one is still serving"
        # (see _restart_pending) no matter how the update arrived.
        _write_running_version()
        tm.tm_emit(tm.Ev.SERVE_STARTED, worker=WORKER_ID,
                   supervised=_detect_supervised())
        # ⭐ 2026-08-05 — TAKE CHROMIUM WITH US ON A SUPERVISOR-INITIATED STOP.
        # `_schedule_server_exit` reaps this process's child tree before its
        # `os._exit`, but that only covers an in-process Stop. A SIGTERM from the
        # supervisor (now every Ctrl+C, and already every watchdog respawn) is
        # handled by uvicorn as a GRACEFUL shutdown: the server loop returns,
        # `run_server` returns, and the interpreter exits normally — taking no
        # notice of the patchright node driver and the Chromium hanging off it.
        # Those orphan, and an orphaned Chromium still holds the profile lock, so
        # the very next worker starts against a wedged profile. `atexit` is the
        # right hook precisely because it fires on that normal exit and NOT on
        # `os._exit` (already reaped) or SIGKILL (nothing can run there).
        import atexit as _atexit
        _atexit.register(_reap_child_processes, "serve-exit")
        asyncio.run(run_server(_resolved_port))
        return

    if args.resume:
        resume_path = Path(args.resume)
        if not resume_path.is_absolute():
            resume_path = Path(__file__).parent / "queues" / args.resume
        log(f"Resuming from: {resume_path}")
        global _cli_mode
        _cli_mode = True
        asyncio.run(run_pipeline_captured(
            topic=args.topic or "", resume_dir=str(resume_path),
            verbose=args.verbose, api_key=args.api_key, email=args.email,
        ))
        return

    if not args.topic:
        parser.error(f'Provide topic: {_PROG} "Your topic"')

    log(f"Topic: {args.topic}")
    if args.brief_file:
        log(f"Brief: {args.brief_file} (skipping Phase 1)")
    if args.pdf:
        log(f"PDFs: {[Path(p).name for p in args.pdf]}")

    _cli_mode = True
    asyncio.run(run_pipeline_captured(
        topic=args.topic, pdf_paths=args.pdf,
        brief_file=args.brief_file, verbose=args.verbose,
        api_key=args.api_key, email=args.email,
    ))


if __name__ == "__main__":
    # F11 of the CLI audit — wrap the dispatcher in a single clean
    # KeyboardInterrupt catch so Ctrl+C anywhere in any subcommand
    # (--pair, --unpair, --retire, --resurrect, --doctor, --serve) exits
    # with a calm message + Unix convention exit code 130 instead of a
    # noisy traceback. Subcommands that need to do their own cleanup
    # before bailing can still catch KeyboardInterrupt locally; if they
    # re-raise it lands here.
    try:
        main()
    except KeyboardInterrupt:
        print()
        print(f"  {_c(_DIM, 'Cancelled.')}  {_c(_DIM, 'Re-run when ready.')}")
        sys.exit(130)
